-- Daily push notifications (pregnancy_day_notifications, mommy_day_notifications) translated into
-- es, fr, hi, id, ja, ko, nl, pl, pt, sv, vi, zh (owner request 2026-11-12; human-quality translation, not machine/Gemini). Batch 20261112240000_push_notifications_i18n_wave3.
-- Only empty cells are filled; existing text is never overwritten. Tables already CDC enrolled and writer guarded.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '300s';
DO $$ BEGIN
  IF (SELECT count(*) FROM _anacan_gcp_migration.guarded_relations WHERE schema_name = 'public'
      AND table_name IN ('pregnancy_day_notifications', 'mommy_day_notifications')) <> 2 THEN
    RAISE EXCEPTION 'PUSH_I18N_GUARD_MISSING'; END IF;
END $$;
UPDATE public.mommy_day_notifications SET title_es = '500 días increíbles 🎉', body_es = '¿Te lo puedes creer? ¡Han pasado exactamente 500 días desde el parto!', title_fr = '500 jours formidables.🎉', body_fr = 'Vous y croyez ?! Cela fait 500 jours pile depuis la naissance !', title_hi = 'शानदार 500 दिन।🎉', body_hi = 'यकीन होता है?! जन्म से अब तक पूरे 500 दिन बीत गए!', title_id = '500 hari yang luar biasa.🎉', body_id = 'Percaya tidak?! Sudah tepat 500 hari sejak ia lahir!', title_ja = 'すばらしい500日🎉', body_ja = '信じられますか？！生まれてからちょうど500日がたちました！', title_ko = '멋진 500일.🎉', body_ko = '믿어지나요?! 태어난 지 꼬박 500일이 됐어요!', title_nl = 'Geweldige 500 dagen.🎉', body_nl = 'Kun je het geloven?! Sinds de geboorte zijn precies 500 dagen voorbij!', title_pl = 'Wspaniałe 500 dni.🎉', body_pl = 'Wierzysz w to?! Od porodu minęło równo 500 dni!', title_pt = 'Uns fantásticos 500 dias.🎉', body_pt = 'Consegue acreditar?! Passaram exatamente 500 dias desde o nascimento!', title_sv = 'Fantastiska 500 dagar.🎉', body_sv = 'Kan du tro det?! Exakt 500 dagar har gått sedan förlossningen!', title_vi = '500 ngày tuyệt vời.🎉', body_vi = 'Mẹ có tin được không?! Đã tròn 500 ngày kể từ ngày bé chào đời!', title_zh = '了不起的500天 🎉', body_zh = '你敢相信吗？！从出生到现在已经整整500天了！' WHERE id = '7cc24719-4bcf-403b-9178-3f6a80317c26' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis con el menú 🥣', title_fr = 'Les crises du menu 🥣', title_hi = 'मेन्यू के नखरे 🥣', title_id = 'Krisis menu 🥣', title_ja = '食事のかんしゃく 🥣', title_ko = '메뉴 위기 🥣', title_nl = 'Crisis aan tafel 🥣', title_pl = 'Kryzysy przy jedzeniu 🥣', title_pt = 'Crises à mesa 🥣', title_sv = 'Menykriser 🥣', title_vi = 'Khủng hoảng thực đơn 🥣', title_zh = '菜单危机 🥣' WHERE id = '0f2d9f90-69e8-4777-adab-24eab59b69a5' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un fondo mágico para la noche 🪄', title_fr = 'Une ambiance de nuit magique 🪄', title_hi = 'जादुई रात का बैकग्राउंड 🪄', title_id = 'Latar malam yang ajaib 🪄', title_ja = '魔法の夜のBGM 🪄', title_ko = '마법 같은 밤의 배경음 🪄', title_nl = 'Een magische achtergrond voor de nacht 🪄', title_pl = 'Magiczne tło na noc 🪄', title_pt = 'Um fundo mágico para a noite 🪄', title_sv = 'Magisk nattbakgrund 🪄', title_vi = 'Không gian đêm kỳ diệu 🪄', title_zh = '魔法夜晚背景 🪄' WHERE id = 'adf1cd9b-1322-48c3-a05b-72b8aa90f9cc' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recuerda con tu pareja aquellos primeros días y reíd juntos.', body_es = '¡No ha sido fácil llegar a este primer año! Es vuestra victoria como equipo.', title_fr = 'Remémorez-vous vos premiers jours avec votre conjoint et riez ensemble.', body_fr = 'Arriver à ce 1er anniversaire n''a pas été facile ! C''est votre victoire d''équipe.', title_hi = 'अपने साथी के साथ शुरुआती दिनों को याद करके हँसिए।', body_hi = 'आप आसानी से इस 1 साल तक नहीं पहुँचे हैं! यह एक टीम के रूप में आपकी जीत है।', title_id = 'Kenang hari-hari pertama bersama pasangan dan tertawalah bersama.', body_id = 'Usia 1 tahun ini tidak Anda capai dengan mudah! Ini kemenangan Anda sebagai satu tim.', title_ja = 'パートナーと出会ったころを思い出して、一緒に笑いましょう。', body_ja = 'この1歳まで、決して楽な道のりではありませんでしたね！これはおふたりのチームとしての勝利です。', title_ko = '배우자와 처음 며칠을 떠올리며 함께 웃어 보세요.', body_ko = '이 1년은 결코 쉽게 오지 않았어요! 한 팀으로 함께 이룬 승리예요.', title_nl = 'Haal herinneringen op aan de eerste dagen en lach samen met je partner.', body_nl = 'Die 1e verjaardag kwam niet vanzelf! Dit is jullie overwinning als team.', title_pl = 'Powspominaj z partnerem pierwsze dni i pośmiejcie się razem.', body_pl = 'Ten pierwszy rok nie przyszedł wam łatwo! To wasze wspólne zwycięstwo jako zespołu.', title_pt = 'Recorde com o seu companheiro os primeiros tempos e riam-se juntos.', body_pt = 'Não chegaram a este 1 ano com facilidade! Esta é a vitória de vocês, como equipa.', title_sv = 'Minns de första dagarna med din partner och skratta tillsammans.', body_sv = 'Ni har inte nått det här första året lätt! Det är er seger som ett team.', title_vi = 'Cùng bố ôn lại những ngày đầu và cười thật vui nhé.', body_vi = 'Chặng đường 1 năm này không hề dễ dàng! Đây là chiến thắng của cả đội nhà mình.', title_zh = '和另一半一起回忆刚在一起的日子，笑一笑吧。', body_zh = '走到这1岁可不容易！这是你们作为一个团队的胜利。' WHERE id = '5a7c1a91-4811-4c74-93f4-2ee19bdbb39a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En Cuentos inteligentes crea un fondo especial solo con música y sonidos de la naturaleza. Sin palabras, solo calma e ilusión.', body_fr = 'Dans les Contes intelligents, créez une ambiance faite uniquement de musique et de sons de la nature. Pas de mots, juste du calme et de l''impatience.', body_hi = 'स्मार्ट कहानियों में सिर्फ़ संगीत और प्रकृति की आवाज़ों वाला एक खास बैकग्राउंड बनाइए। कोई शब्द नहीं, बस सुकून और इंतज़ार।', body_id = 'Di Dongeng Pintar, buat latar khusus yang hanya berisi musik dan suara alam. Tanpa kata-kata, hanya ketenangan dan penantian.', body_ja = '「スマートおはなし」で、音楽と自然の音だけの特別なBGMをつくってみましょう。言葉はなく、ただ安らぎとわくわくする気持ちだけ。', body_ko = '스마트 동화에서 음악과 자연의 소리만으로 특별한 배경을 만들어 보세요. 말은 없고, 오직 평온함과 설렘만 있어요.', body_nl = 'Maak in Slimme sprookjes een speciale achtergrond van alleen muziek en natuurgeluiden. Geen woorden, alleen rust en verwachting.', body_pl = 'W Mądrych bajkach stwórz wyjątkowe tło z samej muzyki i odgłosów natury. Bez słów, tylko spokój i oczekiwanie.', body_pt = 'Nas Histórias Inteligentes, crie um fundo especial só com música e sons da natureza. Sem palavras, apenas tranquilidade e expectativa.', body_sv = 'Skapa en särskild bakgrund i Smarta sagor med bara musik och naturljud. Inga ord, bara lugn och förväntan.', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo một nền âm thanh đặc biệt chỉ có nhạc và tiếng thiên nhiên. Không lời, chỉ có bình yên và háo hức chờ đợi.', body_zh = '在智能故事里创作一段只有音乐和自然声音的特别背景。没有言语，只有安宁与期待。' WHERE id = '14e209af-2489-4eb6-a1f0-be21be617768' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Las encías vuelven a estar rojas y no para de babear? Puede que vengan en camino las primeras muelas.', body_fr = 'Ses gencives sont encore rouges et il bave sans arrêt ? Ses premières molaires arrivent peut-être.', body_hi = 'मसूड़े फिर से लाल हो गए हैं और लार रुक नहीं रही? शायद पहली दाढ़ें आने वाली हैं।', body_id = 'Gusinya memerah lagi dan air liurnya terus menetes? Mungkin geraham pertamanya sedang dalam perjalanan.', body_ja = '歯ぐきがまた赤くなって、よだれが止まらない？最初の奥歯が生えてくるところかもしれません。', body_ko = '잇몸이 또 빨개지고 침이 계속 흐르나요? 첫 어금니가 나오는 중일지도 몰라요.', body_nl = 'Is het tandvlees weer rood en blijft je kleintje kwijlen? Misschien zijn de eerste kiezen onderweg.', body_pl = 'Dziąsła znów są czerwone, a ślinka cieknie bez przerwy? Może w drodze są pierwsze trzonowce.', body_pt = 'As gengivas estão outra vez vermelhas e não para de babar? Talvez os primeiros molares estejam a caminho.', body_sv = 'Är tandköttet rött igen och slutar dreglet aldrig? De första kindtänderna kan vara på väg.', body_vi = 'Nướu của bé lại đỏ lên và chảy dãi không ngừng? Có lẽ những chiếc răng hàm đầu tiên đang trên đường mọc.', body_zh = '牙龈又红了，口水还流个不停？也许第一颗磨牙就要来了。' WHERE id = '0549edc6-63d2-4caa-a43c-f029f7f39465' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Levanta los brazos cuando le dices «¿Nos vamos?» o niega con la cabeza al oír «No»? ¡Su capacidad de comprensión ha crecido muchísimo!', body_fr = 'Il lève les bras quand vous dites « On y va ? » ou secoue la tête quand vous dites « Non ». Sa compréhension a fait un bond incroyable !', body_hi = '''चलें?'' कहने पर हाथ ऊपर उठाता है या ''नहीं'' कहते हुए सिर हिलाता है। उसकी समझने की क्षमता कमाल की बढ़ गई है!', body_id = 'Ia mengangkat tangan saat Anda bilang "Ayo pergi?" atau menggeleng saat bilang "Tidak"? Kemampuan memahaminya meningkat luar biasa!', body_ja = '「行こうか？」と言うと両手を上げたり、「ダメ」と言うと首を振ったり。言葉を理解する力がぐんと伸びています！', body_ko = '"갈까?" 하면 두 팔을 들고, "안 돼" 하면 고개를 저어요. 이해력이 놀랍도록 자랐어요!', body_nl = 'Steekt je kindje zijn armpjes omhoog als je vraagt: gaan we? Of schudt hij nee? Hij begrijpt ongelofelijk veel meer!', body_pl = 'Na „Idziemy?” podnosi rączki, a na „Nie” kręci główką. Jego rozumienie mowy niesamowicie wzrosło!', body_pt = 'Levanta os braços quando lhe diz "Vamos?" ou abana a cabeça quando ouve "Não". A capacidade de compreensão cresceu imenso!', body_sv = 'Barnet sträcker upp armarna när du säger ”Ska vi gå?” eller skakar på huvudet vid ”Nej”. Förståelsen har ökat otroligt!', body_vi = 'Mẹ hỏi "Đi nhé?" là bé giơ tay, nghe "Không" là bé lắc đầu. Khả năng hiểu của bé đã tăng vượt bậc!', body_zh = '你说“走吗？”宝宝就举起双手，说“不行”就摇头。理解能力真是突飞猛进！' WHERE id = '262cbb13-eb12-4831-9fe5-37ece168bdfa' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hoy todo te ha molestado? 📝', title_fr = 'Tout vous a agacée aujourd''hui ? 📝', title_hi = 'आज हर बात पर चिढ़ हो रही है? 📝', title_id = 'Hari ini semuanya bikin kesal? 📝', title_ja = '今日はなんだかイライラしますか？📝', title_ko = '오늘 모든 게 짜증 났나요? 📝', title_nl = 'Ergerde je je vandaag aan alles? 📝', title_pl = 'Wszystko cię dziś irytowało? 📝', title_pt = 'Hoje tudo a irritou? 📝', title_sv = 'Har allt irriterat dig i dag? 📝', title_vi = 'Hôm nay chuyện gì cũng khiến mẹ bực mình? 📝', title_zh = '今天什么都让你心烦？📝' WHERE id = 'c5294433-a84c-4be9-ad57-5744718366c9' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empieza la etapa de niño pequeño 🌟', body_es = '¡La etapa de bebé ha quedado atrás! Ya es oficialmente un niño que afirma su personalidad y quiere hacerlo todo «yo solo». ¡Empieza una nueva aventura llena de paciencia y amor!', title_fr = 'La période des tout-petits commence 🌟', body_fr = 'La petite enfance est derrière vous ! Il est désormais officiellement un enfant qui affirme sa personnalité et veut tout faire « tout seul ». Une nouvelle aventure pleine de patience et d''amour commence !', title_hi = 'टॉडलर (छोटे बच्चे) का दौर शुरू 🌟', body_hi = 'शिशु अवस्था पीछे छूट गई! अब वह आधिकारिक रूप से अपनी पहचान जताने वाला, हर काम ''मैं खुद'' कहने वाला बच्चा है। धैर्य और प्यार से भरा एक नया सफ़र शुरू हो रहा है!', title_id = 'Masa balita dimulai 🌟', body_id = 'Masa bayi sudah berlalu! Kini ia resmi menjadi anak yang menunjukkan jati dirinya dan berkata "aku sendiri" untuk segala hal. Petualangan baru penuh kesabaran dan cinta dimulai!', title_ja = '幼児期のはじまり 🌟', body_ja = '赤ちゃん時代は卒業！これからは自分らしさを主張して、なんでも「自分で！」と言う子どもです。忍耐と愛情でいっぱいの新しい冒険が始まります！', title_ko = '토들러(유아기)가 시작돼요 🌟', body_ko = '아기 시절은 지나갔어요! 이제 "내가 할래!"를 외치며 자기 개성을 드러내는 어엿한 아이예요. 인내와 사랑이 가득한 새로운 모험이 시작돼요!', title_nl = 'De dreumesfase begint 🌟', body_nl = 'De babytijd ligt achter jullie! Je kindje is nu officieel een dreumes die zijn eigen wil laat zien en alles zelf wil doen. Een nieuw avontuur vol geduld en liefde begint!', title_pl = 'Zaczyna się etap małego dziecka 🌟', body_pl = 'Niemowlęctwo za wami! Teraz to już małe dziecko, które pokazuje swoją osobowość i chce wszystko robić „samo”. Zaczyna się nowa przygoda pełna cierpliwości i miłości!', title_pt = 'Começa a fase de criança pequena 🌟', body_pt = 'A fase de bebé ficou para trás! Agora é oficialmente uma criança que afirma a sua personalidade e quer fazer tudo "sozinho". Começa uma nova aventura cheia de paciência e amor!', title_sv = 'Småbarnsåren börjar 🌟', body_sv = 'Bebisåret är över! Nu är det ett barn som officiellt visar sin egen personlighet och säger ”själv” om allt. Ett nytt äventyr fullt av tålamod och kärlek börjar!', title_vi = 'Bắt đầu giai đoạn chập chững 🌟', body_vi = 'Giai đoạn sơ sinh đã ở lại phía sau! Giờ bé đã là một đứa trẻ chính thức khẳng định cá tính, việc gì cũng muốn "tự làm". Một hành trình mới đầy kiên nhẫn và yêu thương bắt đầu!', title_zh = '幼儿期开始啦 🌟', body_zh = '婴儿期过去了！宝宝已经正式宣告自己的个性，什么都要“我自己来”。一段充满耐心和爱的新冒险开始了！' WHERE id = '0944c4dc-3e95-4efb-97dc-8b4809d96d45' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Sigue con la rutina creando en Cuentos inteligentes la historia de un gran héroe que ya tiene 1 año y está descubriendo el mundo.', body_fr = 'Poursuivez le rituel en créant dans les Contes intelligents l''histoire d''un grand héros qui a 1 an et découvre le monde.', body_hi = 'स्मार्ट कहानियों में 1 साल के हो चुके और दुनिया खोजने वाले बड़े हीरो की कहानी बनाकर रूटीन जारी रखिए।', body_id = 'Lanjutkan rutinitasnya dengan membuat kisah di Dongeng Pintar tentang pahlawan besar yang kini berusia 1 tahun dan sedang menjelajahi dunia.', body_ja = '「スマートおはなし」で、1歳になって世界を探検する大きなヒーローのお話をつくって、いつもの習慣を続けましょう。', body_ko = '스마트 동화에서 이제 1살이 되어 세상을 탐험하는 큰 주인공의 이야기를 만들며 루틴을 이어 가세요.', body_nl = 'Ga door met de routine en maak in Slimme sprookjes een verhaal over een grote held die nu 1 jaar is en de wereld ontdekt.', body_pl = 'Kontynuuj rytuał w Mądrych bajkach, tworząc historię o wielkim bohaterze, który ma już roczek i odkrywa świat.', body_pt = 'Mantenha a rotina nas Histórias Inteligentes, criando a história de um grande herói que já tem 1 ano e está a descobrir o mundo.', body_sv = 'Fortsätt rutinen i Smarta sagor genom att skapa en berättelse om en stor hjälte som nu är 1 år och upptäcker världen.', body_vi = 'Hãy tiếp tục thói quen bằng cách tạo trong Truyện cổ tích thông minh câu chuyện về người hùng lớn đã tròn 1 tuổi và đang khám phá thế giới.', body_zh = '在智能故事里创作一个1岁小英雄探索世界的故事，延续睡前习惯吧。' WHERE id = '569602c0-f0cf-4229-b498-984bfdabf097' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de la cuchara 🥄', body_es = 'Quiere coger la cuchara y comerse el puré solo. Se manchará y lo pondrá todo perdido, pero es muy importante para su motricidad. Déjale hacerlo.', title_fr = 'La bataille de la cuillère 🥄', body_fr = 'Il veut tenir la cuillère et manger sa purée tout seul. Ça va couler et salir, mais c''est très important pour sa motricité. Laissez-le faire.', title_hi = 'चम्मच की ज़िद 🥄', body_hi = 'वह खुद चम्मच पकड़कर खुद प्यूरी खाना चाहता है। गिरेगा, गंदगी होगी, लेकिन यह मोटर स्किल्स के लिए बहुत ज़रूरी है। उसे करने दीजिए।', title_id = 'Ngotot pegang sendok 🥄', body_id = 'Ia ingin memegang sendok dan makan puree sendiri. Pasti tumpah dan berantakan, tapi ini sangat penting untuk motoriknya. Biarkan saja.', title_ja = 'スプーンは自分で！🥄', body_ja = '自分でスプーンを持って、ピューレを食べたがっています。こぼれて汚れますが、手先の発達にとても大切です。やらせてあげましょう。', title_ko = '숟가락 고집 🥄', body_ko = '숟가락을 직접 잡고 퓌레를 혼자 먹고 싶어 해요. 흘리고 더러워지겠지만 운동 능력 발달에 정말 중요해요. 해 보게 해 주세요.', title_nl = 'Koppig met de lepel 🥄', body_nl = 'Je kindje wil zelf de lepel vasthouden en zelf zijn hapje eten. Het wordt een knoeiboel, maar het is heel belangrijk voor de motoriek. Laat hem maar.', title_pl = 'Upór przy łyżeczce 🥄', body_pl = 'Chce sam trzymać łyżeczkę i sam jeść przecier. Będzie rozlane i brudno, ale to bardzo ważne dla motoryki. Pozwól mu.', title_pt = 'A teimosia da colher 🥄', body_pt = 'Quer segurar a colher e comer o puré sozinho. Vai entornar e sujar, mas é muito importante para a motricidade. Deixe-o tentar.', title_sv = 'Skedens trots 🥄', body_sv = 'Barnet vill hålla skeden själv och äta purén själv. Det kommer att spillas och bli kladdigt, men det är mycket viktigt för motoriken. Låt barnet försöka.', title_vi = 'Bé đòi tự cầm thìa 🥄', body_vi = 'Bé muốn tự cầm thìa và tự ăn món nghiền. Sẽ rơi vãi, sẽ lem luốc, nhưng điều này rất quan trọng cho kỹ năng vận động. Hãy để bé tự làm.', title_zh = '勺子要自己拿 🥄', body_zh = '宝宝想自己拿勺子、自己吃泥糊。会撒、会弄脏，但这对动作发育非常重要。放手让宝宝试吧。' WHERE id = 'd5e35c42-03ad-4068-b27d-3efca55a35ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'El ritmo es cada vez más intenso. Elige en Recetas saludables una comida cargada de hierro y proteínas y recarga energía.', body_fr = 'Le rythme s''accélère encore. Choisissez dans les Recettes saines un déjeuner riche en fer et en protéines pour reprendre des forces.', body_hi = 'भागदौड़ और बढ़ गई है। सेहतमंद रेसिपी से आयरन और प्रोटीन से भरपूर ऐसा लंच चुनिए जो आपको ताकत दे।', body_id = 'Kesibukan makin padat. Pilih makan siang kaya zat besi dan protein dari Resep Sehat untuk mengisi tenaga Anda.', body_ja = '毎日がさらに慌ただしくなってきましたね。「ヘルシーレシピ」から鉄分とたんぱく質たっぷりのランチを選んで、エネルギーをチャージしましょう。', body_ko = '뛰어다니는 속도가 더 빨라졌어요. 건강한 레시피에서 힘이 나는 철분과 단백질 가득한 점심을 골라 기운을 충전하세요.', body_nl = 'Het wordt alleen maar drukker. Kies in Gezonde recepten een lunch vol ijzer en eiwit die je kracht geeft.', body_pl = 'Bieganiny jest jeszcze więcej. Wybierz ze zdrowych przepisów obiad pełen żelaza i białka, który doda ci sił.', body_pt = 'A correria está ainda mais intensa. Escolha nas Receitas Saudáveis um almoço cheio de ferro e proteína que lhe dê energia e recupere forças.', body_sv = 'Stressen har ökat ännu mer. Välj en lunch full av järn och protein från Hälsosamma recept och samla kraft.', body_vi = 'Cuộc sống càng thêm tất bật. Hãy chọn trong Công thức lành mạnh một bữa trưa giàu sắt và protein để nạp lại năng lượng nhé.', body_zh = '追着跑的节奏更快了。从健康食谱里选一份富含铁和蛋白质的午餐，给自己补充能量。' WHERE id = 'f93e7290-30ca-44fe-a1e4-55044619c9a6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Primeros pasos sin ayuda? 🧗‍♂️', body_es = 'Quizá hoy, quizá mañana... Ya intenta dar uno o dos pasos sin agarrarse a nada. ¡Prepárate para registrarlo en el Seguimiento del desarrollo!', title_fr = 'Premiers pas en solo ? 🧗‍♂️', body_fr = 'Peut-être aujourd''hui, peut-être demain... Il essaie déjà de faire un ou deux pas sans se tenir. Préparez-vous à le noter dans le Suivi de développement !', title_hi = 'खुद के पहले कदम? 🧗‍♂️', body_hi = 'शायद आज, शायद कल... वह बिना कुछ पकड़े एक-दो कदम चलने की कोशिश कर रहा है। ग्रोथ ट्रैकर में दर्ज करने के लिए तैयार रहिए!', title_id = 'Langkah pertama tanpa pegangan? 🧗‍♂️', body_id = 'Mungkin hari ini, mungkin besok... Ia sudah mencoba melangkah satu-dua kali tanpa berpegangan. Bersiaplah mencatatnya di Pelacak Perkembangan!', title_ja = 'ひとりで最初の一歩？🧗‍♂️', body_ja = '今日か、明日か…もうどこにもつかまらずに1、2歩踏み出そうとしています。「発達トラッカー」に記録する準備をしておきましょう！', title_ko = '혼자 내딛는 첫걸음? 🧗‍♂️', body_ko = '오늘일까, 내일일까... 이제 아무것도 잡지 않고 한두 걸음 떼려고 해요. 성장 기록에 남길 준비를 하세요!', title_nl = 'Eerste losse stapjes? 🧗‍♂️', body_nl = 'Misschien vandaag, misschien morgen... Je kindje probeert al een of twee stapjes te zetten zonder zich vast te houden. Houd de Groeitracker klaar om het te noteren!', title_pl = 'Pierwsze samodzielne kroki? 🧗‍♂️', body_pl = 'Może dziś, może jutro... Już próbuje zrobić krok czy dwa, niczego się nie trzymając. Bądź gotowa, by zapisać to w Śledzeniu rozwoju!', title_pt = 'Primeiros passos sozinho? 🧗‍♂️', body_pt = 'Talvez hoje, talvez amanhã... Já tenta dar um ou dois passos sem se agarrar a nada. Esteja pronta para o registar no Registo de Desenvolvimento!', title_sv = 'Första stegen på egen hand? 🧗‍♂️', body_sv = 'Kanske i dag, kanske i morgon... Barnet försöker redan ta ett par steg utan att hålla i något. Var redo att anteckna det i Utvecklingsspåraren!', title_vi = 'Những bước đi tự lập đầu tiên? 🧗‍♂️', body_vi = 'Có thể hôm nay, có thể ngày mai... Bé đã thử bước một hai bước mà không cần vịn vào đâu. Hãy sẵn sàng ghi lại trong Theo dõi phát triển nhé!', title_zh = '独立迈出第一步？🧗‍♂️', body_zh = '也许今天，也许明天……宝宝已经在尝试不扶任何东西走一两步了。准备好在发育追踪里记录吧！' WHERE id = '50b26349-9946-4708-aec2-e87f1b15952f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No decidas el paseo mirando por la ventana. Deja que Tiempo y ropa te diga al momento la velocidad del viento y la ropa adecuada.', body_fr = 'Avant de sortir vous promener, ne décidez pas en regardant par la fenêtre. Laissez l''outil Météo et tenue vous indiquer tout de suite la vitesse du vent et la bonne tenue.', body_hi = 'घूमने निकलने से पहले सिर्फ़ खिड़की से देखकर फ़ैसला मत कीजिए। मौसम और कपड़े टूल तुरंत हवा की रफ़्तार और सही कपड़े बता देगा।', body_id = 'Jangan putuskan jalan-jalan hanya dengan melihat dari jendela. Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin dan pakaian yang tepat.', body_ja = 'お散歩に出る前、窓の外を見るだけで決めないで。「天気と服装」で風の強さとぴったりのコーデをすぐにチェックしましょう。', body_ko = '산책 나갈 때 창밖만 보고 정하지 마세요. 날씨와 옷차림 도구가 바람 세기와 알맞은 옷차림을 바로 알려 줄 거예요.', body_nl = 'Beslis niet over een wandeling door uit het raam te kijken. Laat de tool Weer en kleding je meteen de windsnelheid en de juiste outfit vertellen.', body_pl = 'Nie decyduj o spacerze, patrząc tylko przez okno. Narzędzie Pogoda i ubiór od razu poda ci prędkość wiatru i odpowiedni zestaw.', body_pt = 'Antes de sair a passear, não decida só a olhar pela janela. Deixe que o Tempo e Roupa lhe diga na hora a velocidade do vento e a combinação certa.', body_sv = 'Bestäm inte om promenaden genom att titta ut genom fönstret. Låt verktyget Väder och kläder direkt berätta vindhastigheten och rätt klädsel.', body_vi = 'Đừng chỉ nhìn qua cửa sổ để quyết định có đi dạo hay không. Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió và bộ đồ phù hợp.', body_zh = '出门散步前别只看窗外就做决定。让天气穿衣工具马上告诉你风速和合适的搭配。' WHERE id = '9407d96f-ca5a-4378-a7c6-ee00256c457a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te asustan quienes dicen que después del año todo es más difícil? Escribe en la Comunidad Anacan y lee experiencias reales y positivas de otras mamás.', body_fr = 'Ceux qui disent que tout devient plus dur après 1 an vous font peur ? Écrivez dans la Communauté Anacan et lisez les expériences réelles et positives d''autres mamans.', body_hi = '''1 साल के बाद और मुश्किल हो जाता है'' कहने वाले आपको डराते हैं? Anacan कम्युनिटी में लिखिए और माँओं के असली, सकारात्मक अनुभव पढ़िए।', body_id = 'Takut mendengar orang bilang setelah 1 tahun makin sulit? Tulis di Komunitas Anacan dan baca pengalaman nyata yang positif dari para ibu.', body_ja = '「1歳を過ぎるともっと大変になる」という話が不安ですか？Anacanコミュニティに書き込んで、ママたちのリアルで前向きな体験を読んでみましょう。', body_ko = '1살 이후가 더 힘들다는 말이 겁나나요? Anacan 커뮤니티에 글을 남기고 엄마들의 실제 긍정적인 경험을 읽어 보세요.', body_nl = 'Schrik je van mensen die zeggen dat het na 1 jaar zwaarder wordt? Schrijf in de Anacan Community en lees echte, positieve ervaringen van andere moeders.', body_pl = 'Straszą cię, że po roczku jest trudniej? Napisz w Społeczności Anacan i przeczytaj prawdziwe, pozytywne doświadczenia innych mam.', body_pt = 'Assusta-a quem diz que depois de 1 ano fica mais difícil? Escreva na Comunidade Anacan e leia experiências reais e positivas de outras mães.', body_sv = 'Skräms du av dem som säger att det blir svårare efter 1 år? Skriv i Anacans Community och läs verkliga, positiva erfarenheter från andra mammor.', body_vi = 'Mẹ lo lắng khi nghe người ta nói "sau 1 tuổi còn vất vả hơn"? Hãy viết vào Cộng đồng Anacan và đọc những trải nghiệm thật, tích cực từ các mẹ khác.', body_zh = '有人说“1岁以后更难带”，让你害怕？在Anacan社区发个帖，看看妈妈们真实又积极的经验。' WHERE id = '3ed836ab-41d4-4203-a7c8-b9e7b1394cd2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue órdenes sencillas 🧸', body_es = '¿Cuando le dices «Dame la pelota» la busca y te la trae? ¡Su comprensión de las palabras está en su mejor momento! Hazle participar más en los juegos.', title_fr = 'Il suit des consignes simples 🧸', body_fr = 'Quand vous dites « Donne-moi le ballon », il le trouve vraiment et vous l''apporte ? Sa compréhension des mots est au top ! Impliquez-le davantage dans vos jeux.', title_hi = 'आसान बातें मानता है 🧸', body_hi = '''गेंद मुझे दो'' कहने पर वह सच में ढूँढकर ले आता है? शब्दों को समझने की उसकी क्षमता चरम पर है! उसे खेलों में और शामिल कीजिए।', title_id = 'Mengikuti perintah sederhana 🧸', body_id = 'Saat Anda bilang "Berikan bolanya ke Mama", ia benar-benar mencari dan membawanya? Kemampuannya memahami kata sedang di puncak! Ajak ia lebih sering bermain.', title_ja = '簡単なお願いがわかる 🧸', body_ja = '「ボールちょうだい」と言うと、本当に探して持ってきてくれますか？言葉を理解する力がぐんぐん伸びています！遊びにもっと誘ってあげましょう。', title_ko = '간단한 말을 알아듣고 해내요 🧸', body_ko = '"공 줘" 하면 정말 찾아서 가져오나요? 말을 이해하는 능력이 최고조예요! 놀이에 더 많이 참여시켜 주세요.', title_nl = 'Voert eenvoudige opdrachtjes uit 🧸', body_nl = 'Zoekt je kindje echt de bal als je zegt: geef mij de bal? Hij begrijpt woorden steeds beter! Betrek hem meer bij spelletjes.', title_pl = 'Wykonuje proste polecenia 🧸', body_pl = 'Na „Daj mi piłkę” naprawdę ją znajduje i przynosi? Rozumienie słów jest na szczycie! Częściej angażuj go w zabawy.', title_pt = 'Cumpre ordens simples 🧸', body_pt = 'Quando lhe diz "Dá-me a bola", ele encontra-a mesmo e traz-lha? A compreensão das palavras está no auge! Envolva-o mais nas brincadeiras.', title_sv = 'Följer enkla instruktioner 🧸', body_sv = 'Hittar barnet verkligen bollen och kommer med den när du säger ”Ge mig bollen”? Ordförståelsen är på topp! Låt barnet vara med mer i lekarna.', title_vi = 'Bé làm theo yêu cầu đơn giản 🧸', body_vi = 'Mẹ nói "Đưa quả bóng cho mẹ" là bé tìm và mang đến thật? Khả năng hiểu lời nói của bé đang ở đỉnh cao! Hãy cho bé tham gia các trò chơi nhiều hơn.', title_zh = '能听懂简单指令了 🧸', body_zh = '你说“把球给我”，宝宝真的找来给你？理解词语的能力正处于高峰！多让宝宝参与游戏吧。' WHERE id = '6ad316f8-edd9-4dff-aac4-f3492d4a602a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sus primeros zapatos 👟', body_es = 'Se prepara para caminar, pero ¿debe llevar zapatos en casa? Pregunta a Anacan AI por los zapatos de primeros pasos y los beneficios de ir descalzo.', title_fr = 'Choisir ses premières chaussures 👟', body_fr = 'Il se prépare à marcher, mais doit-il porter des chaussures à la maison ? Interrogez Anacan AI sur les chaussures premiers pas et les bienfaits de marcher pieds nus.', title_hi = 'पहले जूते का चुनाव 👟', body_hi = 'चलने की तैयारी कर रहा है, तो क्या घर में जूते पहनने चाहिए? Anacan AI से पहले कदम वाले जूतों और नंगे पैर चलने के फ़ायदों के बारे में पूछिए।', title_id = 'Memilih sepatu pertama 👟', body_id = 'Ia bersiap berjalan, tapi apakah perlu memakai sepatu di rumah? Tanyakan ke Anacan AI tentang sepatu langkah pertama dan manfaat berjalan tanpa alas kaki.', title_ja = 'はじめての靴選び 👟', body_ja = '歩く準備をしていますが、家の中でも靴は必要？はじめての靴と、はだしで歩くメリットについてAnacan AIに聞いてみましょう。', title_ko = '첫 신발 고르기 👟', body_ko = '걸을 준비를 하는데, 집에서도 신발을 신어야 할까요? Anacan AI에게 첫걸음 신발과 맨발로 걷기의 장점에 대해 물어보세요.', title_nl = 'De eerste schoentjes kiezen 👟', body_nl = 'Je kindje wil gaan lopen, maar moet hij binnen schoenen dragen? Vraag Anacan AI naar eerste loopschoentjes en de voordelen van blootsvoets lopen.', title_pl = 'Wybór pierwszych butów 👟', body_pl = 'Szykuje się do chodzenia, ale czy w domu powinien nosić buty? Zapytaj Anacan AI o buty na pierwsze kroki i zalety chodzenia boso.', title_pt = 'A escolha dos primeiros sapatos 👟', body_pt = 'Está a preparar-se para andar, mas deve usar sapatos em casa? Pergunte ao Anacan AI sobre os sapatos para os primeiros passos e os benefícios de andar descalço.', title_sv = 'Att välja de första skorna 👟', body_sv = 'Barnet förbereder sig för att gå, men behövs skor inomhus? Fråga Anacan AI om skor för de första stegen och fördelarna med att gå barfota.', title_vi = 'Chọn đôi giày đầu tiên 👟', body_vi = 'Bé chuẩn bị biết đi, vậy ở nhà có cần đi giày không? Hãy hỏi Anacan AI về giày tập đi và lợi ích của việc đi chân trần.', title_zh = '选第一双鞋 👟', body_zh = '宝宝准备走路了，那在家要穿鞋吗？问问Anacan AI关于学步鞋和光脚走路的好处吧。' WHERE id = '028a5b0d-04de-43dc-984d-eaf6e3427904' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después del año, el menú cambia. ¿Hace falta leche de vaca o alimentos nuevos en casa? Rellena ya la Lista de la compra y envíasela a tu pareja.', body_fr = 'Après 1 an, le menu change. Il faut du lait de vache ou de nouveaux aliments à la maison ? Remplissez tout de suite la Liste de courses et envoyez-la à votre conjoint.', body_hi = '1 साल के बाद मेन्यू बदलता है। घर में गाय का दूध या नए खाने चाहिए? तुरंत शॉपिंग लिस्ट भरिए और अपने साथी को भेजिए।', body_id = 'Setelah 1 tahun, menunya berubah. Butuh susu sapi atau makanan lain di rumah? Segera isi Daftar Belanja dan kirim ke pasangan Anda.', body_ja = '1歳を過ぎるとメニューが変わります。牛乳や新しい食材が必要ですか？すぐに「買い物リスト」に入れて、パートナーに送りましょう。', body_ko = '1살이 지나면 식단이 바뀌어요. 우유나 다른 식재료가 필요한가요? 바로 쇼핑 목록을 채워 배우자에게 보내세요.', body_nl = 'Na 1 jaar verandert het menu. Heb je koemelk of andere voeding nodig in huis? Vul meteen het Boodschappenlijstje in en stuur het naar je partner.', body_pl = 'Po roczku menu się zmienia. Potrzebujesz w domu mleka krowiego lub nowych produktów? Od razu uzupełnij Listę zakupów i wyślij ją partnerowi.', body_pt = 'Depois de 1 ano, a ementa muda. Precisa de leite de vaca ou de novos alimentos em casa? Preencha já a Lista de Compras e envie-a ao seu companheiro.', body_sv = 'Efter 1 år ändras menyn. Behövs komjölk eller nya livsmedel hemma? Fyll direkt i Inköpslistan och skicka den till din partner.', body_vi = 'Sau 1 tuổi, thực đơn thay đổi. Nhà cần sữa bò hay thực phẩm mới? Hãy điền ngay vào Danh sách mua sắm và gửi cho bố.', body_zh = '1岁以后菜单要变了。家里需要牛奶或其他新食物？马上填好购物清单发给另一半。' WHERE id = '5d68d6d5-05d2-43b4-bd93-e3f95983e445' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Correr todo el día detrás de un peque que no para no es fácil. Anota tu cansancio en el Diario de ánimo, desahógate y descansa.', body_fr = 'Courir toute la journée après un enfant qui marche n''est pas facile. Allégez votre fatigue en la notant dans le Journal d''humeur, puis reposez-vous.', body_hi = 'पूरे दिन चलते-फिरते बच्चे के पीछे भागना आसान नहीं है। अपनी थकान मूड डायरी में लिखकर मन हल्का कीजिए और आराम कीजिए।', body_id = 'Mengejar anak yang berjalan ke sana kemari seharian tidak mudah. Ringankan lelah Anda dengan menuliskannya di Buku Harian Suasana Hati, lalu beristirahatlah.', body_ja = '一日中動き回る子を追いかけるのは大変ですよね。「気分日記」に疲れを書き出して、気持ちを軽くして休みましょう。', body_ko = '하루 종일 돌아다니는 아이를 쫓아다니기는 쉽지 않아요. 기분 일기에 피로를 적으며 마음을 가볍게 하고 쉬어 가세요.', body_nl = 'De hele dag achter een rondlopend kindje aanrennen is niet makkelijk. Schrijf je vermoeidheid op in je Stemmingsdagboek, lucht je hart en rust uit.', body_pl = 'Bieganie cały dzień za maluchem, który wszędzie chodzi, to nie lada wyzwanie. Zapisz zmęczenie w Dzienniku nastroju, poczuj ulgę i odpocznij.', body_pt = 'Correr o dia todo atrás de uma criança que já anda não é fácil. Registe o seu cansaço no Diário de Humor, alivie o peso e descanse.', body_sv = 'Det är inte lätt att springa efter ett barn som är i farten hela dagen. Skriv av dig tröttheten i Humördagboken och vila.', body_vi = 'Chạy theo một em bé đi khắp nơi cả ngày thật không dễ. Hãy ghi lại sự mệt mỏi vào Nhật ký tâm trạng để nhẹ lòng hơn và nghỉ ngơi nhé.', body_zh = '追着整天走来走去的孩子跑可不轻松。把疲惫记进心情日记，给自己减减压，好好休息。' WHERE id = '9a073421-3e36-4699-bbbd-50a69e46f431' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Pasa él solo las páginas de los libros de cartón y reacciona a los dibujos? Léele muchos cuentos llenos de color.', body_fr = 'Il tourne tout seul les pages de ses livres cartonnés et réagit aux images ? Lisez-lui plein de livres d''histoires colorés.', body_hi = 'मोटे पन्नों वाली किताबों के पन्ने पूरी तरह खुद पलटता है और तस्वीरों पर प्रतिक्रिया देता है? उसे खूब रंगीन कहानी की किताबें पढ़कर सुनाइए।', body_id = 'Ia membalik sendiri halaman buku bertebal dan bereaksi pada gambarnya? Bacakan banyak buku cerita berwarna untuknya.', body_ja = '厚紙の絵本のページを自分でめくって、絵に反応していますか？カラフルな絵本をたくさん読んであげましょう。', body_ko = '두꺼운 책장을 혼자서 넘기며 그림에 반응하나요? 알록달록한 그림책을 많이 읽어 주세요.', body_nl = 'Slaat je kindje zelf de dikke bladzijden van kartonboekjes om en reageert hij op de plaatjes? Lees hem veel kleurrijke prentenboeken voor.', body_pl = 'Sam przewraca kartki grubych książeczek i reaguje na obrazki? Czytaj mu dużo kolorowych książeczek z bajkami.', body_pt = 'Já vira sozinho as páginas dos livros cartonados e reage às imagens? Leia-lhe muitos livros de histórias coloridos.', body_sv = 'Vänder barnet själv sidorna i kartongböcker och reagerar på bilderna? Läs massor av färgglada sagoböcker tillsammans.', body_vi = 'Bé tự lật những trang sách bìa cứng và phản ứng với hình ảnh? Hãy đọc cho bé thật nhiều sách truyện đầy màu sắc nhé.', body_zh = '宝宝能自己完整地翻厚纸板书，还会对图片做出反应？多给宝宝读读色彩丰富的故事书吧。' WHERE id = '2cdeb7df-f4f5-4a75-ae9b-552210a168fe' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Primeros pasos sin ayuda! 🧗‍♂', body_es = '️ Se suelta de los muebles, se queda de pie solo y quizá dé ese primer paso tan esperado. No te pierdas este momento inolvidable y súbelo en vídeo al Álbum del bebé enseguida.', title_fr = 'Premiers pas en solo ! 🧗‍♂', body_fr = '️ Il lâche les meubles, tient debout tout seul et fait peut-être ses premiers pas tant attendus ! Ne manquez pas ce moment inoubliable et ajoutez tout de suite une vidéo à l''Album de bébé.', title_hi = 'पहले आज़ाद कदम! 🧗‍♂', body_hi = '️ फ़र्नीचर छोड़कर अकेले खड़ा होता है और शायद वह इंतज़ार किया हुआ पहला कदम भी उठा ले! इस यादगार ऐतिहासिक पल को मत चूकिए और तुरंत वीडियो के रूप में बेबी एल्बम में अपलोड कीजिए।', title_id = 'Langkah pertama tanpa bantuan! 🧗‍♂', body_id = '️ Ia melepas pegangan pada perabot, berdiri sendiri, dan mungkin mengambil langkah pertama yang dinanti-nanti! Jangan lewatkan momen bersejarah ini dan segera unggah videonya ke Album Bayi.', title_ja = 'はじめてのひとり歩き！🧗‍♂', body_ja = '️家具から手を離してひとりで立ち、待ちに待った最初の一歩を踏み出すかもしれません！この忘れられない瞬間を逃さず、すぐに動画で「ベビーアルバム」に保存しましょう。', title_ko = '혼자 내딛는 첫걸음! 🧗‍♂', body_ko = '️가구를 놓고 혼자 서서 기다리던 첫걸음을 뗄지도 몰라요! 이 잊지 못할 역사적인 순간을 놓치지 말고 바로 영상으로 아기 앨범에 올리세요.', title_nl = 'De eerste losse stapjes! 🧗‍♂', body_nl = '️ Je kindje laat de meubels los, staat alleen en zet misschien die langverwachte eerste stap! Mis dit onvergetelijke moment niet en zet er meteen een video van in het Babyalbum.', title_pl = 'Pierwsze samodzielne kroki! 🧗‍♂', body_pl = '️ Puszcza się mebli, stoi sam i może właśnie robi ten długo wyczekiwany pierwszy krok! Nie przegap tej niezapomnianej chwili i od razu dodaj filmik do Albumu dziecka.', title_pt = 'Os primeiros passos sozinho! 🧗‍♂', body_pt = '️ Larga os móveis, fica de pé sozinho e talvez dê aquele primeiro passo tão esperado! Não perca este momento histórico inesquecível e carregue já um vídeo no Álbum do Bebé.', title_sv = 'De första stegen på egen hand! 🧗‍♂', body_sv = '️ Barnet släpper möblerna, står själv och tar kanske det efterlängtade första steget! Missa inte detta oförglömliga ögonblick och ladda direkt upp en video i Babyalbumet.', title_vi = 'Những bước đi tự lập đầu tiên! 🧗‍♂', body_vi = '️ Bé buông đồ vật, tự đứng và có thể sắp bước những bước đầu tiên được mong chờ! Đừng bỏ lỡ khoảnh khắc lịch sử khó quên này, hãy tải video lên Album của bé ngay.', title_zh = '独立迈出第一步！🧗‍♂', body_zh = '️ 宝宝松开家具独自站立，也许还会迈出那期待已久的第一步！别错过这个难忘的历史时刻，马上录成视频上传到宝宝相册。' WHERE id = '8b98f6cf-24e2-4a41-9bea-c77f1a82d1bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Ha aprendido a decir que no con la cabeza cuando le ofreces algo! No es terquedad, está expresando su opinión. Dale opciones para que se calme.', body_fr = 'Il a appris à dire non en secouant la tête quand on lui propose quelque chose ! Ce n''est pas de l''entêtement, il exprime son avis. Apaisez-le en lui proposant des choix.', body_hi = 'कुछ देने पर वह सिर हिलाकर ''नहीं'' कहना सीख गया है! यह ज़िद नहीं, अपनी राय जताना है। उसे विकल्प देकर शांत कीजिए।', body_id = 'Ia sudah belajar menggeleng untuk bilang tidak saat ditawari sesuatu! Ini bukan keras kepala, melainkan cara menyampaikan pendapatnya. Tenangkan ia dengan memberi pilihan.', body_ja = '何かをすすめると、首を振って「いや」と言えるようになりました！これはわがままではなく、自分の気持ちを伝えているのです。選択肢をあげて落ち着かせてあげましょう。', body_ko = '무언가를 권하면 고개를 저으며 싫다고 말하는 법을 배웠어요! 고집이 아니라 자기 생각을 표현하는 거예요. 선택지를 주며 달래 주세요.', body_nl = 'Je kindje heeft geleerd nee te schudden als je iets aanbiedt! Dat is geen koppigheid, maar zijn eigen mening laten horen. Geef hem keuzes, dan wordt hij rustiger.', body_pl = 'Nauczył się mówić „nie”, kręcąc główką, gdy coś mu proponujesz! To nie upór, tylko wyrażanie własnego zdania. Uspokój go, dając mu wybór.', body_pt = 'Aprendeu a dizer que não abanando a cabeça quando lhe oferecem algo! Não é teimosia, é expressar a sua opinião. Acalme-o dando-lhe opções.', body_sv = 'Barnet har lärt sig skaka på huvudet och säga nej när du erbjuder något! Det är inte trots, utan ett sätt att uttrycka sin åsikt. Ge valmöjligheter för att lugna barnet.', body_vi = 'Bé đã biết lắc đầu nói "không" khi được mời thứ gì đó! Đây không phải bướng bỉnh mà là bé đang bày tỏ ý kiến. Hãy đưa ra lựa chọn để bé bình tĩnh hơn.', body_zh = '你给宝宝东西时，宝宝学会摇头说“不”了！这不是任性，而是在表达自己的想法。给宝宝一些选择，让他平静下来。' WHERE id = '61d67656-ab73-4417-b42d-5e55ecf64b87' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mamá sana 🥑', body_es = 'Si ya está lleno, te toca a ti. Elige un tentempié energético en Recetas saludables y túmbate en el sofá al menos 10 minutos.', title_fr = 'Maman en forme 🥑', body_fr = 'Il a bien mangé ? À votre tour. Choisissez un en-cas énergisant dans les Recettes saines et allongez-vous au moins 10 minutes sur le canapé.', title_hi = 'सेहतमंद माँ 🥑', body_hi = 'उसका पेट भर गया, तो अब आपकी बारी है। सेहतमंद रेसिपी से कोई ऊर्जा भरा स्नैक चुनिए और कम से कम 10 मिनट सोफ़े पर लेटिए।', title_id = 'Ibu sehat 🥑', body_id = 'Kalau ia sudah kenyang, sekarang giliran Anda. Pilih camilan berenergi dari Resep Sehat dan berbaringlah di sofa setidaknya 10 menit.', title_ja = 'ママも健康に 🥑', body_ja = 'お子さんがお腹いっぱいになったら、次はあなたの番。「ヘルシーレシピ」から元気が出るおやつを選んで、せめて10分はソファで横になりましょう。', title_ko = '건강한 엄마 🥑', body_ko = '아기가 배불리 먹었다면 이제 엄마 차례예요. 건강한 레시피에서 든든한 간식을 고르고 단 10분이라도 소파에 누워 쉬세요.', title_nl = 'Gezonde mama 🥑', body_nl = 'Heeft je kindje genoeg gegeten? Dan ben jij aan de beurt. Kies een energierijk tussendoortje in Gezonde recepten en ga minstens 10 minuten op de bank liggen.', title_pl = 'Zdrowa mama 🥑', body_pl = 'Jeśli on już najedzony, teraz twoja kolej. Wybierz ze zdrowych przepisów energetyczną przekąskę i połóż się na kanapie choć na 10 minut.', title_pt = 'Mãe saudável 🥑', body_pt = 'Se ele já está satisfeito, agora é a sua vez. Escolha um lanche energético nas Receitas Saudáveis e deite-se no sofá pelo menos 10 minutos.', title_sv = 'Frisk mamma 🥑', body_sv = 'Är barnet mätt är det din tur. Välj ett energigivande mellanmål från Hälsosamma recept och ligg på soffan i minst 10 minuter.', title_vi = 'Mẹ khỏe mạnh 🥑', body_vi = 'Bé no rồi thì đến lượt mẹ. Hãy chọn một món ăn nhẹ giàu năng lượng trong Công thức lành mạnh và nằm nghỉ trên sofa ít nhất 10 phút nhé.', title_zh = '健康妈妈 🥑', body_zh = '宝宝吃饱了，轮到你了。从健康食谱里选一款能量小食，至少在沙发上躺10分钟吧。' WHERE id = '6b997061-a83d-4040-b848-d55a40a87a1a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya no le basta con andar por el suelo e intenta subirse a escaleras y muebles? ¡Su motricidad avanza con decisión! Vigílale siempre de cerca.', body_fr = 'Marcher au sol ne lui suffit plus, il essaie de grimper sur les escaliers et les meubles ? Une motricité bien déterminée ! Gardez-le toujours sous surveillance.', body_hi = 'नीचे चलना उसके लिए काफ़ी नहीं, सीढ़ियों और फ़र्नीचर पर चढ़ने की कोशिश करता है? ज़िद्दी मोटर विकास! उस पर हमेशा नज़र रखिए।', body_id = 'Berjalan di lantai saja tidak cukup, ia mencoba memanjat tangga dan perabot? Motoriknya berkembang dengan gigih! Pastikan selalu diawasi.', body_ja = '床を歩くだけでは物足りず、階段や家具によじ登ろうとしていますか？たくましい運動能力の発達です！必ず目を離さないでくださいね。', body_ko = '바닥에서 노는 것만으로는 부족해서 계단이나 가구 위로 올라가려 하나요? 끈질긴 운동 발달이에요! 반드시 곁에서 지켜봐 주세요.', body_nl = 'Is rondlopen niet meer genoeg en probeert je kindje op de trap en op meubels te klimmen? Een vastberaden motorische ontwikkeling! Houd hem goed in het oog.', body_pl = 'Chodzenie po podłodze mu nie wystarcza i próbuje wspinać się po schodach i meblach? To uparty rozwój motoryki! Koniecznie miej go na oku.', body_pt = 'Andar no chão já não lhe chega e tenta subir escadas e móveis? É a motricidade a desenvolver-se com determinação! Vigie-o sempre.', body_sv = 'Räcker det inte att gå på golvet, försöker barnet klättra upp på trappor och möbler? En envis motorisk utveckling! Håll alltid uppsikt.', body_vi = 'Đi dưới sàn không đủ với bé, bé cố trèo lên cầu thang và đồ đạc? Kỹ năng vận động phát triển mạnh mẽ! Mẹ nhớ luôn để mắt đến bé nhé.', body_zh = '在地上走已经不够了，还想爬楼梯、爬家具？这是执着的动作发育！一定要看好宝宝。' WHERE id = '8d89c421-922f-4b8a-bc83-525a380ead88' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Dale color a la rutina de la noche con el cuento «Los secretos para dormir del héroe más pequeño» en Cuentos inteligentes.', body_fr = 'Mettez de la couleur dans le rituel du soir avec l''histoire « Les secrets du sommeil du plus petit des héros » dans les Contes intelligents.', body_hi = 'स्मार्ट कहानियों में ''सबसे नन्हे हीरो के सोने के राज़'' नाम की कहानी से शाम के रूटीन में रंग भरिए।', body_id = 'Warnai rutinitas malam dengan kisah "Rahasia Tidur Pahlawan Paling Kecil" di Dongeng Pintar.', body_ja = '「スマートおはなし」の「いちばん小さなヒーローのねんねのひみつ」というお話で、夜の習慣を楽しく彩りましょう。', body_ko = '스마트 동화에서 ''가장 작은 주인공의 잠드는 비밀''이라는 이야기로 저녁 루틴에 색을 더해 보세요.', body_nl = 'Geef de avondroutine kleur met een verhaal in Slimme sprookjes: De slaapgeheimen van de allerkleinste held.', body_pl = 'Dodaj kolorów wieczornej rutynie dzięki historii „Sekrety zasypiania najmniejszego bohatera” w Mądrych bajkach.', body_pt = 'Dê cor à rotina da noite nas Histórias Inteligentes com a história "Os segredos do sono do herói mais pequenino".', body_sv = 'Ge kvällsrutinen färg med berättelsen ”Den minsta hjältens sömnhemligheter” i Smarta sagor.', body_vi = 'Hãy thêm màu sắc cho giờ đi ngủ bằng câu chuyện "Bí mật đi ngủ của người hùng nhỏ nhất" trong Truyện cổ tích thông minh.', body_zh = '用智能故事里《最小英雄的入睡秘密》这个故事，给晚间作息增添一点色彩吧。' WHERE id = 'dacf6637-c6dd-4427-9e89-1dc06f453ae5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Nada le contenta y llora por todo? Puede que le estén saliendo las muelas de atrás. Ten preparados mordedores fríos.', body_fr = 'Rien ne lui convient et il pleure pour tout ? Ce sont peut-être ses molaires du fond qui percent. Préparez des anneaux de dentition froids.', body_hi = 'किसी बात से खुश नहीं, हर चीज़ पर रोता है? शायद पीछे की दाढ़ें निकल रही हैं। ठंडे टीदर तैयार रखिए।', body_id = 'Tidak ada yang membuatnya puas dan ia menangis karena segala hal? Mungkin geraham belakangnya sedang tumbuh. Siapkan teether dingin.', body_ja = '何をしても気に入らず、泣いてばかり？奥歯が生えてきているのかもしれません。冷やした歯がためを用意しておきましょう。', body_ko = '무엇에도 만족하지 못하고 계속 우나요? 안쪽 어금니가 나오는 중일 수도 있어요. 차갑게 한 치발기를 준비해 두세요.', body_nl = 'Is je kindje nergens tevreden mee en huilt hij om alles? Misschien komen de achterste kiezen door. Leg koele bijtringen klaar.', body_pl = 'Nic mu nie pasuje i płacze o wszystko? Może wychodzą tylne trzonowce. Przygotuj schłodzone gryzaki.', body_pt = 'Nada o contenta e chora por tudo? Talvez estejam a nascer os molares de trás. Tenha mordedores frios à mão.', body_sv = 'Är barnet missnöjt med allt och gråter för allting? Kanske är det de bakre kindtänderna som kommer. Ha kalla bitringar redo.', body_vi = 'Bé không vừa ý điều gì, cứ khóc mãi? Có thể răng hàm phía sau đang mọc. Hãy chuẩn bị sẵn vòng gặm nướu mát lạnh nhé.', body_zh = '什么都不满意，动不动就哭？也许后面的磨牙正在长出来。准备好冰凉的牙胶吧。' WHERE id = '2d2e06b1-2d94-4883-a675-93637a17ca98' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En los despertares nocturnos, turnaos: una vez tú y otra tu pareja. A veces lo que mejor le calma son las caricias rítmicas de papá.', body_fr = 'Pour les réveils nocturnes, levez-vous une fois chacun avec votre conjoint. Parfois, seules les caresses rythmées de papa l''apaisent.', body_hi = 'रात में जागने पर एक बार आप उठिए, एक बार आपके साथी। कभी-कभी बच्चे को सिर्फ़ पापा का लयबद्ध सहलाना ही सुकून देता है।', body_id = 'Saat ia terbangun malam, bergantianlah: sekali Anda, sekali pasangan. Kadang usapan berirama dari ayahlah yang paling menenangkannya.', body_ja = '夜中に起きたら、あなたとパートナーで交代で対応しましょう。パパのリズミカルなトントンがいちばん効くこともあります。', body_ko = '밤에 깰 때는 한 번은 엄마, 한 번은 배우자가 일어나세요. 때로는 아빠의 리듬감 있는 토닥임만이 통할 때도 있어요.', body_nl = 'Sta ''s nachts om de beurt op: de ene keer jij, de andere keer je partner. Soms helpt alleen papa''s ritmische geaai.', body_pl = 'Przy nocnych pobudkach wstawajcie na zmianę, raz ty, raz partner. Czasem dziecku najlepiej pomaga właśnie rytmiczne głaskanie taty.', body_pt = 'Nos despertares noturnos, levante-se uma vez a mãe e outra vez o seu companheiro. Às vezes, só as carícias ritmadas do pai resultam.', body_sv = 'Turas om vid nattliga uppvaknanden, en gång du och en gång din partner. Ibland är det bara pappas rytmiska smekningar som hjälper.', body_vi = 'Khi bé thức giấc ban đêm, lần này mẹ dậy, lần sau để bố dậy. Đôi khi chỉ có cái vỗ về nhịp nhàng của bố mới giúp bé dịu lại.', body_zh = '夜醒时你起一次，另一半起一次。有时候宝宝就吃爸爸有节奏的轻抚这一套。' WHERE id = '2eeb1f61-7042-48aa-9ecc-41443c68b4a8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se acumulan las tareas? Que esperen. Pide a tu compañero de equipo que hoy se encargue de la casa. Tú descansa.', body_fr = 'Les tâches s''accumulent ? Tant pis. Demandez à votre coéquipier de prendre en charge la maison aujourd''hui. Vous, reposez-vous.', body_hi = 'काम बाकी हैं? रहने दीजिए। अपने टीम पार्टनर से कहिए कि आज घर के काम वे संभालें। आप आराम कीजिए।', body_id = 'Pekerjaan menumpuk? Biarkan saja. Minta pasangan Anda mengambil alih pekerjaan rumah hari ini. Anda beristirahatlah.', body_ja = '家事がたまっている？そのままで大丈夫。今日はパートナーに家事をお願いして、あなたは休みましょう。', body_ko = '할 일이 남았나요? 그냥 두세요. 오늘은 팀 동료인 배우자에게 집안일을 맡아 달라고 부탁하세요. 엄마는 쉬세요.', body_nl = 'Blijft er werk liggen? Laat het maar liggen. Vraag je partner om vandaag het huishouden op zich te nemen. Jij rust uit.', body_pl = 'Obowiązki czekają? Niech czekają. Poproś partnera, by dziś przejął prace domowe. Ty odpocznij.', body_pt = 'Há tarefas por fazer? Deixe ficar. Peça ao seu companheiro de equipa que trate hoje das lides da casa. Descanse.', body_sv = 'Blir sysslorna liggande? Låt dem ligga. Be din partner ta hand om hushållet i dag. Vila du.', body_vi = 'Việc nhà còn dồn đống? Cứ để đó. Hãy nhờ người đồng đội của mình lo việc nhà hôm nay. Mẹ cứ nghỉ ngơi nhé.', body_zh = '家务做不完？那就先放着。请你的队友今天把家务都接过去。你好好休息。' WHERE id = 'd1cf73d9-421b-4ad1-b114-e5025146d5b2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Dejar el chupete o el biberón? 🍼', body_es = '¿Piensas en quitarle el chupete después del año? Pregunta a las mamás de la Comunidad Anacan por los métodos más suaves.', title_fr = 'Arrêter la tétine ou le biberon ? 🍼', body_fr = 'Vous pensez à arrêter la tétine après 1 an ? Demandez aux mamans de la Communauté Anacan leurs méthodes les plus douces.', title_hi = 'चुसनी/बोतल छुड़ाना? 🍼', body_hi = '1 साल के बाद चुसनी छुड़ाने के बारे में सोच रही हैं? Anacan कम्युनिटी की माँओं से इसके सबसे नरम तरीके पूछिए।', title_id = 'Berhenti dot atau botol? 🍼', body_id = 'Berpikir untuk menyapih dot setelah usia 1 tahun? Tanyakan cara paling lembut kepada para ibu di Komunitas Anacan.', title_ja = 'おしゃぶりや哺乳びんの卒業？🍼', body_ja = '1歳を過ぎて、おしゃぶりの卒業を考えていますか？Anacanコミュニティのママたちに、いちばんやさしい方法を聞いてみましょう。', title_ko = '쪽쪽이/젖병 끊기? 🍼', body_ko = '1살 이후 쪽쪽이를 끊을 생각인가요? Anacan 커뮤니티의 엄마들에게 가장 부드러운 방법을 물어보세요.', title_nl = 'Afscheid van speen of fles? 🍼', body_nl = 'Denk je erover om na 1 jaar te stoppen met de speen? Vraag de moeders in de Anacan Community naar de zachtste manieren.', title_pl = 'Odstawienie smoczka/butelki? 🍼', body_pl = 'Myślisz o odstawieniu smoczka po roczku? Zapytaj mamy w Społeczności Anacan o najłagodniejsze sposoby.', title_pt = 'Deixar a chupeta/o biberão? 🍼', body_pt = 'Está a pensar tirar a chupeta depois de 1 ano? Pergunte às mães da Comunidade Anacan quais são os métodos mais suaves.', title_sv = 'Sluta med napp/flaska? 🍼', body_sv = 'Funderar du på att sluta med nappen efter 1 år? Fråga mammorna i Anacans Community om de mjukaste metoderna.', title_vi = 'Cai ti giả/bình sữa? 🍼', body_vi = 'Mẹ đang nghĩ đến việc cai ti giả sau 1 tuổi? Hãy hỏi các mẹ trong Cộng đồng Anacan về những cách nhẹ nhàng nhất.', title_zh = '戒安抚奶嘴/奶瓶？🍼', body_zh = '1岁后在考虑戒安抚奶嘴吗？问问Anacan社区里的妈妈们，有哪些最温和的方法。' WHERE id = '19c626ef-26a5-49ef-921f-4577f35ab653' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Formas geométricas y juegos de ingenio! 🧩', body_es = 'Intenta meter el círculo o el cuadrado por el agujero correcto. Guarda para siempre estos descubrimientos en el Álbum del bebé.', title_fr = 'Formes géométriques et jeux d''éveil ! 🧩', body_fr = 'Il essaie de faire passer le rond ou le carré dans le bon trou. Immortalisez ces découvertes éducatives dans l''Album de bébé.', title_hi = 'ज्यामितीय आकृतियाँ और दिमागी खेल! 🧩', body_hi = 'वह गोले या चौकोर को सही छेद में डालने की कोशिश करता है। सीखने की इन खोजों को बेबी एल्बम में हमेशा के लिए सहेजिए।', title_id = 'Bentuk geometri dan permainan asah otak! 🧩', body_id = 'Ia mencoba memasukkan lingkaran atau persegi ke lubang yang sesuai. Abadikan penemuan edukatif ini di Album Bayi.', title_ja = '形あそびと知育ゲーム！🧩', body_ja = '丸や四角を、ぴったりの穴に入れようとしています。この学びの瞬間を「ベビーアルバム」に残しましょう。', title_ko = '도형과 두뇌 놀이! 🧩', body_ko = '동그라미나 네모를 알맞은 구멍에 넣으려고 해요. 이 배움 가득한 발견을 아기 앨범에 영원히 남기세요.', title_nl = 'Vormen en denkspelletjes! 🧩', body_nl = 'Je kindje probeert een rondje of vierkantje door het juiste gat te steken. Leg deze leerzame ontdekkingen vast in het Babyalbum.', title_pl = 'Kształty geometryczne i łamigłówki! 🧩', body_pl = 'Próbuje wkładać kółko lub kwadrat do pasujących otworów. Uwiecznij te pouczające odkrycia w Albumie dziecka.', title_pt = 'Formas geométricas e jogos de inteligência! 🧩', body_pt = 'Tenta encaixar o círculo ou o quadrado no buraco certo. Eternize estas descobertas educativas no Álbum do Bebé.', title_sv = 'Geometriska former och tankelekar! 🧩', body_sv = 'Barnet försöker få cirkeln eller kvadraten genom rätt hål. Förevig dessa lärorika upptäckter i Babyalbumet.', title_vi = 'Hình khối và trò chơi trí tuệ! 🧩', body_vi = 'Bé cố nhét hình tròn hay hình vuông vào đúng lỗ. Hãy lưu giữ những khám phá bổ ích này trong Album của bé.', title_zh = '几何形状和益智游戏！🧩', body_zh = '宝宝在尝试把圆形或方形塞进对应的孔里。把这些有趣的学习发现留在宝宝相册里吧。' WHERE id = 'f20aef27-fde2-489c-9dd8-fe28386cf1db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se resiste por completo a una de sus dos siestas? Después del año empieza la transición a una sola siesta. Ajusta la rutina poco a poco.', body_fr = 'Il refuse complètement l''une de ses deux siestes ? Après 1 an, le passage à une seule sieste commence. Réajustez son rythme petit à petit.', body_hi = 'दिन की दो झपकियों में से एक का पूरा विरोध करता है? 1 साल के बाद एक झपकी पर आने का दौर शुरू होता है। रूटीन को धीरे-धीरे नए सिरे से ढालिए।', body_id = 'Ia benar-benar menolak salah satu dari dua tidur siangnya? Setelah usia 1 tahun, peralihan ke satu kali tidur siang dimulai. Atur ulang rutinitasnya perlahan-lahan.', body_ja = '2回のお昼寝のうち1回をすっかり嫌がるように？1歳を過ぎると1回寝への移行が始まります。少しずつ生活リズムを調整しましょう。', body_ko = '낮잠 두 번 중 한 번을 완강히 거부하나요? 1살이 지나면 낮잠이 한 번으로 바뀌기 시작해요. 루틴을 천천히 다시 맞춰 주세요.', body_nl = 'Verzet je kindje zich helemaal tegen een van zijn twee dutjes? Na 1 jaar begint de overgang naar één dutje. Pas de routine rustig opnieuw aan.', body_pl = 'Zdecydowanie broni się przed jedną z dwóch drzemek? Po roczku zaczyna się przejście na jedną drzemkę. Powoli dostosuj rutynę.', body_pt = 'Resiste por completo a uma das duas sestas? Depois de 1 ano começa a transição para uma só sesta. Reajuste a rotina aos poucos.', body_sv = 'Kämpar barnet helt emot en av de två dagsluren? Efter 1 år börjar övergången till en enda tupplur. Justera rutinen sakta.', body_vi = 'Bé hoàn toàn từ chối một trong hai giấc ngủ ngày? Sau 1 tuổi, bé bắt đầu chuyển sang ngủ một giấc ngày. Hãy điều chỉnh lại nếp sinh hoạt từ từ.', body_zh = '两次白天小睡里，有一次宝宝坚决不睡？1岁后开始过渡到一天一次小睡。慢慢重新调整作息吧。' WHERE id = '1d781ae8-7800-48ae-b0ee-fe44c7f13291' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Niebla mental 🛒', body_es = '¿Se te olvida todo? No pienses en las pequeñas compras de casa: apúntalas ya en la Lista de la compra y que se ocupe tu pareja.', title_fr = 'Le brouillard de mémoire 🛒', body_fr = 'Les oublis vous poursuivent ? Ne vous encombrez pas l''esprit avec les petites courses, ajoutez-les tout de suite à la Liste de courses et laissez votre conjoint s''en charger.', title_hi = 'याददाश्त का धुंधलापन 🛒', body_hi = 'भूलने की आदत पीछा नहीं छोड़ रही? घर की छोटी-मोटी खरीदारी के बारे में मत सोचिए, तुरंत शॉपिंग लिस्ट में डालिए, आपके साथी संभाल लेंगे।', title_id = 'Kabut ingatan 🛒', body_id = 'Masih sering lupa? Jangan pikirkan belanjaan kecil rumah tangga, langsung masukkan ke Daftar Belanja dan biar pasangan Anda yang mengurusnya.', title_ja = 'ママのもの忘れ 🛒', body_ja = 'もの忘れが続いていますか？家の細かい買い物を覚えておこうとせず、すぐに「買い物リスト」に入れて、パートナーに任せましょう。', title_ko = '깜빡깜빡 엄마 머리 🛒', body_ko = '건망증이 계속되나요? 자잘한 장보기는 고민하지 말고 바로 쇼핑 목록에 넣어 배우자가 해결하게 하세요.', title_nl = 'Mistig hoofd 🛒', body_nl = 'Vergeet je steeds dingen? Pieker niet over de kleine boodschappen, zet ze meteen op het Boodschappenlijstje en laat je partner het regelen.', title_pl = 'Mgła w głowie 🛒', body_pl = 'Zapominalstwo nie odpuszcza? Nie zaprzątaj sobie głowy drobnymi zakupami, od razu wpisz je na Listę zakupów, a partner się tym zajmie.', title_pt = 'Memória enevoada 🛒', body_pt = 'Os esquecimentos não a largam? Não pense nas pequenas compras da casa: ponha-as já na Lista de Compras e o seu companheiro trata disso.', title_sv = 'Minnesdimma 🛒', body_sv = 'Släpper glömskan inte taget? Fundera inte på hushållets småinköp, lägg dem direkt i Inköpslistan och låt din partner fixa det.', title_vi = 'Đầu óc mơ hồ 🛒', body_vi = 'Cứ hay quên mãi? Đừng bận tâm chuyện mua sắm lặt vặt trong nhà, hãy thêm ngay vào Danh sách mua sắm để bố lo.', title_zh = '记性像雾一样 🛒', body_zh = '总是忘事？家里的零碎采购别再记在脑子里，马上丢进购物清单，让另一半去搞定。' WHERE id = '8b586560-e2d2-46b0-ba82-419bb7b56682' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Intenta lanzar a propósito el juguete hacia un objetivo concreto. Su coordinación ojo-mano avanza a toda velocidad. Jugad juntos a lanzar y atrapar la pelota.', body_fr = 'Il essaie volontairement de lancer son jouet vers une cible précise. Sa coordination œil-main progresse vite. Jouez ensemble à lancer et attraper la balle.', body_hi = 'हाथ का खिलौना जान-बूझकर किसी खास निशाने पर फेंकने की कोशिश करता है। आँख और हाथ का तालमेल तेज़ी से विकसित हो रहा है। साथ में गेंद फेंकिए और पकड़िए।', body_id = 'Ia sengaja mencoba melempar mainan di tangannya ke sasaran tertentu. Koordinasi mata dan tangannya berkembang pesat. Ayo bermain lempar tangkap bola bersama.', body_ja = '手に持ったおもちゃを、わざと目標に向かって投げようとしています。目と手の協調がどんどん発達しています。一緒にボールを投げたり受けたりしましょう。', body_ko = '손에 든 장난감을 일부러 특정 목표를 향해 던지려 해요. 눈과 손의 협응력이 빠르게 발달하고 있어요. 함께 공을 던지고 받아 보세요.', body_nl = 'Je kindje probeert het speeltje in zijn hand bewust naar een doel te gooien. De oog-handcoördinatie ontwikkelt zich snel. Gooi en vang samen met een bal.', body_pl = 'Celowo próbuje rzucić zabawką w konkretny cel. Koordynacja wzrokowo-ruchowa szybko się rozwija. Porzucajcie i połapcie razem piłkę.', body_pt = 'Tenta atirar de propósito o brinquedo que tem na mão para um alvo. A coordenação olho-mão desenvolve-se depressa. Atirem e apanhem a bola juntos.', body_sv = 'Barnet försöker kasta leksaken medvetet mot ett visst mål. Öga-hand-koordinationen utvecklas snabbt. Kasta och fånga boll tillsammans.', body_vi = 'Bé cố tình ném đồ chơi trong tay vào một mục tiêu nhất định. Khả năng phối hợp tay mắt phát triển nhanh chóng. Hãy cùng bé ném và bắt bóng nhé.', body_zh = '宝宝会故意把手里的玩具扔向某个目标了。手眼协调发展得飞快。一起玩扔球接球吧。' WHERE id = 'b87394f8-5f2b-4eb7-a491-26b80560c8a3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Diversión a la hora de comer! 🥦', body_es = 'Si no tiene apetito, prepara raciones coloridas y llamativas de la sección Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Des repas amusants ! 🥦', body_fr = 'Il manque d''appétit ? Préparez des portions colorées et attrayantes grâce aux Recettes pour bébés qui commencent la diversification.', title_hi = 'खाने के समय की मस्ती! 🥦', body_hi = 'अगर भूख नहीं लग रही, तो ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी सेक्शन से रंग-बिरंगे और ध्यान खींचने वाले हिस्से तैयार कीजिए।', title_id = 'Makan jadi seru! 🥦', body_id = 'Si kecil susah makan? Siapkan porsi berwarna-warni dan menarik dari bagian Resep untuk bayi yang mulai MPASI.', title_ja = '食事の時間を楽しく！🥦', body_ja = '食欲がないときは、「離乳食を始める赤ちゃんのレシピ」から、カラフルで目を引く一皿をつくってみましょう。', title_ko = '즐거운 식사 시간! 🥦', body_ko = '아이가 입맛이 없나요? 레시피 섹션의 이유식을 시작하는 아기를 위한 레시피로 알록달록하고 눈길을 끄는 한 그릇을 만들어 보세요.', title_nl = 'Plezier aan tafel! 🥦', body_nl = 'Heeft je kindje weinig trek? Maak kleurrijke, aantrekkelijke porties uit het onderdeel Recepten voor baby''s die met bijvoeding beginnen.', title_pl = 'Zabawa przy jedzeniu! 🥦', body_pl = 'Brakuje mu apetytu? Przygotuj kolorowe, przyciągające uwagę porcje z sekcji Przepisy dla niemowląt rozpoczynających rozszerzanie diety.', title_pt = 'Diversão à hora da refeição! 🥦', body_pt = 'Se anda com pouco apetite, prepare porções coloridas e apelativas com as Receitas para bebés em diversificação alimentar.', title_sv = 'Rolig måltid! 🥦', body_sv = 'Om barnet saknar aptit, gör färgglada och lockande portioner från avsnittet Recept för bebisar som börjar med fast föda.', title_vi = 'Giờ ăn thật vui! 🥦', body_vi = 'Nếu bé biếng ăn, hãy chuẩn bị những phần ăn nhiều màu sắc, bắt mắt từ mục Công thức cho bé bắt đầu ăn dặm.', title_zh = '吃饭也能很好玩！🥦', body_zh = '如果宝宝胃口不好，可以从食谱板块的辅食宝宝食谱里，做些色彩缤纷、吸引眼球的小份餐。' WHERE id = '078c86a9-a3c8-4f20-a27a-3aa00d3961ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reconoce las partes de su cuerpo 👀', body_es = '¿Cuando le preguntas «¿Dónde está tu ojo?» lo señala con el dedo? ¡Su comprensión está en plena forma! Regístralo con orgullo en el Seguimiento del desarrollo.', title_fr = 'Il reconnaît les parties du visage 👀', body_fr = 'Quand vous demandez « Où est ton œil ? », il le touche du doigt ? Sa compréhension est au top ! Notez-le fièrement dans le Suivi de développement.', title_hi = 'शरीर के अंग पहचानता है 👀', body_hi = '''आँख कहाँ है?'' पूछने पर उँगली से छूकर दिखाता है? उसकी समझ चरम पर है! ग्रोथ ट्रैकर में इसे गर्व से दर्ज कीजिए।', title_id = 'Mengenal anggota tubuh 👀', body_id = 'Saat ditanya "Matanya mana?", ia menyentuh dan menunjuk dengan jarinya? Daya tangkapnya sedang di puncak! Catat dengan bangga di Pelacak Perkembangan.', title_ja = '体の部分がわかる 👀', body_ja = '「おめめはどこ？」と聞くと、指でさわって教えてくれますか？理解する力がぐんぐん伸びています！「発達トラッカー」に誇らしく記録しましょう。', title_ko = '신체 부위를 알아요 👀', body_ko = '"눈 어디 있어?" 하고 물으면 손가락으로 짚어 보여 주나요? 이해력이 최고조예요! 성장 기록에 뿌듯하게 남겨 두세요.', title_nl = 'Herkent lichaamsdelen 👀', body_nl = 'Wijst je kindje met zijn vingertje als je vraagt: waar is je oog? Hij begrijpt steeds meer! Noteer het trots in de Groeitracker.', title_pl = 'Rozpoznaje części ciała 👀', body_pl = 'Na pytanie „Gdzie masz oko?” pokazuje je paluszkiem? Rozumienie jest na szczycie! Zapisz to z dumą w Śledzeniu rozwoju.', title_pt = 'Reconhece as partes do corpo 👀', body_pt = 'Quando lhe pergunta "Onde está o olho?", toca-lhe com o dedo e mostra? A compreensão está no auge! Registe-o com orgulho no Registo de Desenvolvimento.', title_sv = 'Känner igen kroppsdelar 👀', body_sv = 'Pekar barnet med fingret när du frågar ”Var är ögat?”? Förståelsen är på topp! Anteckna det med stolthet i Utvecklingsspåraren.', title_vi = 'Bé nhận biết các bộ phận cơ thể 👀', body_vi = 'Mẹ hỏi "Mắt con đâu?" là bé lấy ngón tay chỉ vào? Khả năng nhận thức đang ở đỉnh cao! Hãy tự hào ghi lại trong Theo dõi phát triển nhé.', title_zh = '认识身体部位 👀', body_zh = '问“眼睛在哪里？”宝宝会用手指指给你看？认知能力正处于高峰！自豪地在发育追踪里记下来吧。' WHERE id = '3b7df91a-7022-4a50-9438-82f89b2240b8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo estás haciendo genial! 💖', body_es = 'Criar a un hijo es una maratón. Esta noche dedícate un rato: ve tu película favorita o simplemente descansa.', title_fr = 'Vous faites de votre mieux ! 💖', body_fr = 'Élever un enfant, c''est un marathon. Ce soir, prenez un peu de temps pour vous, regardez un film que vous aimez ou reposez-vous simplement.', title_hi = 'आप सबसे अच्छा कर रही हैं! 💖', body_hi = 'बच्चे को पालना मैराथन जैसा है। आज शाम अपने लिए थोड़ा समय निकालिए, अपनी पसंदीदा फ़िल्म देखिए या बस आराम कीजिए।', title_id = 'Anda sudah melakukan yang terbaik! 💖', body_id = 'Membesarkan anak itu seperti maraton. Malam ini, luangkan sedikit waktu untuk diri sendiri: tonton film favorit atau sekadar beristirahat.', title_ja = 'あなたは本当によくやっています！💖', body_ja = '子育てはマラソンのようなもの。今夜は少し自分のための時間をつくって、好きな映画を観たり、ただのんびりしたりしましょう。', title_ko = '정말 최선을 다하고 있어요! 💖', body_ko = '육아는 마라톤 같아요. 오늘 저녁은 나를 위한 시간을 조금 내어 좋아하는 영화를 보거나 그냥 쉬어 보세요.', title_nl = 'Je doet het geweldig! 💖', body_nl = 'Een kind opvoeden is een marathon. Neem vanavond wat tijd voor jezelf, kijk een film die je leuk vindt of rust gewoon uit.', title_pl = 'Robisz to najlepiej, jak się da! 💖', body_pl = 'Wychowywanie dziecka to maraton. Znajdź dziś wieczorem trochę czasu dla siebie, obejrzyj ulubiony film albo po prostu odpocznij.', title_pt = 'Está a fazer o melhor que pode! 💖', body_pt = 'Criar um filho é uma maratona. Esta noite, reserve um pouco de tempo para si, veja um filme de que goste ou simplesmente descanse.', title_sv = 'Du gör ditt allra bästa! 💖', body_sv = 'Att uppfostra ett barn är som ett maraton. Ta lite tid för dig själv i kväll, se en film du gillar eller bara vila.', title_vi = 'Mẹ đang làm tốt nhất có thể! 💖', body_vi = 'Nuôi con giống như chạy marathon. Tối nay hãy dành chút thời gian cho bản thân, xem một bộ phim yêu thích hoặc đơn giản là nghỉ ngơi.', title_zh = '你已经做得最好了！💖', body_zh = '养孩子就像跑马拉松。今晚给自己留点时间，看一部喜欢的电影，或者就好好休息。' WHERE id = 'f55bcf4b-2f37-47d2-8e08-b8c72b1b9a56' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Ya has introducido alimentos nuevos después del año? Si algo te preocupa, consulta enseguida los primeros pasos con Anacan AI.', body_fr = 'Vous êtes passée à de nouveaux aliments après 1 an ? Si quelque chose vous inquiète, découvrez tout de suite les premières étapes avec Anacan AI.', body_hi = '1 साल के बाद नए खानों पर आ गईं? अगर कोई चिंता है, तो तुरंत Anacan AI से पहले कदम जानिए।', body_id = 'Sudah beralih ke makanan baru setelah usia 1 tahun? Kalau ada yang Anda khawatirkan, segera pelajari langkah pertamanya dari Anacan AI.', body_ja = '1歳を過ぎて新しい食事に移りましたか？気になることがあれば、すぐにAnacan AIで最初の対処法を確認しましょう。', body_ko = '1살 이후 새로운 음식으로 바꿨나요? 걱정되는 점이 있다면 바로 Anacan AI에게 첫 단계를 알아보세요.', body_nl = 'Ben je na 1 jaar overgestapt op nieuwe voeding? Heb je ergens zorgen over, ontdek dan meteen de eerste stappen bij Anacan AI.', body_pl = 'Po roczku wprowadziłaś nowe produkty? Jeśli coś cię niepokoi, od razu poznaj pierwsze kroki w Anacan AI.', body_pt = 'Já fez a transição para novos alimentos depois de 1 ano? Se tiver alguma preocupação, saiba já os primeiros passos com o Anacan AI.', body_sv = 'Har ni gått över till nya livsmedel efter 1 år? Om något oroar dig, lär dig de första stegen direkt från Anacan AI.', body_vi = 'Bé đã chuyển sang thực phẩm mới sau 1 tuổi? Nếu có điều gì lo lắng, hãy tìm hiểu ngay những bước đầu tiên cùng Anacan AI.', body_zh = '1岁以后开始吃新食物了？如果有任何担心，马上向Anacan AI了解第一步该怎么做。' WHERE id = 'c9fb44a1-ad82-4f16-a316-50d99863130e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ha crecido y ya llega a estantes que antes no alcanzaba. Revisa cuanto antes la seguridad de casa.', body_fr = 'Il a encore grandi et atteint des étagères qui lui étaient inaccessibles. Revoyez sans tarder la sécurité de la maison.', body_hi = 'उसकी लंबाई और बढ़ गई है और अब वह उन शेल्फ़ तक पहुँचता है जहाँ पहले नहीं पहुँचता था। घर की सुरक्षा की तुरंत दोबारा जाँच कीजिए।', body_id = 'Tubuhnya makin tinggi dan kini bisa meraih rak yang dulu tak terjangkau. Segera periksa ulang keamanan rumah.', body_ja = '背が伸びて、前は届かなかった棚にも手が届くように。すぐに家の安全対策を見直しましょう。', body_ko = '키가 더 자라서 예전에는 닿지 않던 선반에 손이 닿아요. 집 안 안전을 서둘러 다시 점검하세요.', body_nl = 'Je kindje is gegroeid en kan nu bij planken waar hij eerst niet bij kon. Controleer meteen opnieuw de veiligheid in huis.', body_pl = 'Urósł i sięga już półek, do których wcześniej nie dosięgał. Pilnie sprawdź ponownie bezpieczeństwo w domu.', body_pt = 'Está mais alto e já chega a prateleiras onde antes não chegava. Reveja com urgência a segurança da casa.', body_sv = 'Barnet har blivit längre och når hyllor det inte nådde förut. Se över säkerheten i hemmet snarast.', body_vi = 'Bé đã cao hơn và với tới những kệ trước đây không với được. Hãy kiểm tra lại an toàn trong nhà ngay nhé.', body_zh = '宝宝又长高了，能够到以前够不着的架子了。赶紧重新检查一遍家里的安全隐患。' WHERE id = '159279c3-df89-49cf-a71c-bb577a8dd0c3' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si le molestan los coches o los ruidos de fuera, comprueba el ambiente con el Medidor de sonido y deja ruido blanco de fondo.', body_fr = 'Si les voitures ou les bruits extérieurs le dérangent, vérifiez l''ambiance avec le Sonomètre et laissez des Bruits blancs en fond.', body_hi = 'अगर गाड़ियों या बाहर की आवाज़ें उसे परेशान करती हैं, तो साउंड मीटर से माहौल ज़रूर जाँचिए और पीछे व्हाइट नॉइज़ चलाइए।', body_id = 'Kalau suara mobil atau suara dari luar mengganggunya, periksa lingkungan dengan Pengukur Suara dan putar white noise di latar belakang.', body_ja = '車や外の音が気になるようなら、「サウンドメーター」で周りの音をチェックして、BGMにホワイトノイズを流しましょう。', body_ko = '차 소리나 바깥 소음이 아이를 방해한다면 꼭 소음 측정기로 주변을 확인하고 배경에 백색소음을 틀어 두세요.', body_nl = 'Stoort verkeer of lawaai van buiten je kindje? Controleer de omgeving met de Geluidsmeter en laat witte ruis op de achtergrond spelen.', body_pl = 'Jeśli przeszkadzają mu samochody lub hałas z zewnątrz, koniecznie sprawdź otoczenie Miernikiem dźwięku i włącz w tle biały szum.', body_pt = 'Se os carros ou os ruídos da rua o incomodam, verifique o ambiente com o Medidor de Som e mantenha Ruído Branco de fundo.', body_sv = 'Om bilar eller ljud utifrån stör barnet, kolla miljön med Ljudmätaren och ha vitt brus i bakgrunden.', body_vi = 'Nếu tiếng xe cộ hay tiếng ồn bên ngoài làm bé khó chịu, hãy kiểm tra môi trường bằng Đo âm thanh và bật tiếng ồn trắng làm nền.', body_zh = '如果车声或外面的声音让宝宝不安，一定要用噪音测量检查一下环境，并在背景里放点白噪音。' WHERE id = '3b6ac273-a759-45de-9492-87af2df8cac9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo esparce todo por todas partes 🌪️', body_es = 'Lo importante no es la limpieza, sino que descanses. Los juguetes seguirán ahí mañana, pero ahora hace falta una mamá con energía.', title_fr = 'Il éparpille tout ce avec quoi il joue.  🌪️', body_fr = 'Ce n''est pas le ménage qui compte, c''est votre repos. Les jouets seront encore là demain, mais il a besoin d''une maman en forme maintenant.', title_hi = 'जिस चीज़ से खेलता है, सब इधर-उधर बिखेर देता है।  🌪️', body_hi = 'सफ़ाई नहीं, आपका आराम ज़रूरी है। खिलौने कल भी वहीं होंगे, लेकिन तरोताज़ा माँ की ज़रूरत अभी है।', title_id = 'Mainannya berserakan ke mana-mana.  🌪️', body_id = 'Yang penting bukan kebersihan, melainkan istirahat Anda. Mainan masih akan ada di sana besok, tapi saat ini yang dibutuhkan adalah ibu yang segar.', title_ja = '遊んだものを全部まき散らす 🌪️', body_ja = '大切なのは掃除より、あなたが休むこと。おもちゃは明日もそこにありますが、元気なママは今必要です。', title_ko = '가지고 노는 걸 다 사방에 흩어 놓아요.  🌪️', body_ko = '청소보다 엄마의 휴식이 더 중요해요. 장난감은 내일도 그 자리에 있겠지만, 기운 넘치는 엄마는 지금 필요해요.', title_nl = 'Overal ligt speelgoed. 🌪️', body_nl = 'Niet het opruimen, maar jouw rust is belangrijk. Het speelgoed ligt er morgen ook nog, maar een frisse mama is nu nodig.', title_pl = 'Wszystkim, czym się bawi, rozrzuca dookoła.  🌪️', body_pl = 'Ważniejszy od porządku jest twój odpoczynek. Zabawki jutro też tam będą, a wypoczęta mama jest potrzebna teraz.', title_pt = 'Espalha tudo aquilo com que brinca.  🌪️', body_pt = 'O importante não é a arrumação, é o seu descanso. Os brinquedos amanhã continuam lá, mas uma mãe com energia faz falta agora.', title_sv = 'Allt barnet leker med sprids överallt. 🌪️', body_sv = 'Det viktiga är inte städningen, utan att du vilar. Leksakerna finns kvar i morgon, men en pigg mamma behövs nu.', title_vi = 'Chơi đến đâu bừa đến đó.  🌪️', body_vi = 'Điều quan trọng không phải là dọn dẹp mà là mẹ được nghỉ ngơi. Đồ chơi ngày mai vẫn ở đó, nhưng bây giờ bé cần một người mẹ khỏe khoắn.', title_zh = '玩过的东西扔得到处都是 🌪️', body_zh = '重要的不是打扫，而是你能休息。玩具明天还在那里，但现在需要的是精神饱满的妈妈。' WHERE id = 'bc24cbab-3bcd-4b5b-92fb-249b861079c2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja a un lado todo el cansancio.', title_fr = 'Laissez toute la fatigue de côté.', title_hi = 'सारी थकान एक तरफ़ रख दीजिए।', title_id = 'Singkirkan semua rasa lelah.', title_ja = '疲れはいったん横に置きましょう。', title_ko = '모든 피로는 잠시 내려놓으세요.', title_nl = 'Zet alle vermoeidheid opzij.', title_pl = 'Odłóż całe zmęczenie na bok.', title_pt = 'Deixe todo o cansaço de lado.', title_sv = 'Lägg all trötthet åt sidan.', title_vi = 'Hãy gác lại mọi mệt mỏi.', title_zh = '把所有疲惫都放一边吧。' WHERE id = '0693172d-9675-431e-ae2b-b1d735f8da0f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Olvídate de frases como «el hijo de fulanita habló antes». Cada niño tiene su propio ritmo. Tú solo dale amor.', body_fr = 'Oubliez la phrase « Le petit d''untel a parlé plus tôt ». Chaque enfant se développe à son propre rythme. Vous, donnez-lui simplement de l''amour.', body_hi = '''फ़लाँ का बच्चा जल्दी बोलने लगा'' वाली बात भूल जाइए। हर बच्चे के विकास की रफ़्तार अलग होती है। आप बस उसे प्यार दीजिए।', body_id = 'Lupakan kalimat "Anak si anu sudah bisa bicara lebih cepat". Setiap anak punya tempo perkembangan yang unik. Cukup beri ia cinta.', body_ja = '「〇〇ちゃんはもっと早くしゃべった」という言葉は忘れましょう。成長のペースは一人ひとり違います。あなたはただ、たっぷりの愛情をあげてください。', body_ko = '''누구네 아이는 더 빨리 말했대''라는 말은 잊으세요. 아이마다 발달 속도는 모두 달라요. 엄마는 그저 사랑을 주면 돼요.', body_nl = 'Vergeet de zin: het kindje van die-en-die praatte eerder. Elk kind ontwikkelt zich in zijn eigen tempo. Geef hem gewoon je liefde.', body_pl = 'Zapomnij o zdaniu „Dziecko tej a tej mówiło wcześniej”. Każde dziecko rozwija się we własnym tempie. Ty po prostu dawaj mu miłość.', body_pt = 'Esqueça a frase "o filho de fulano falou mais cedo". Cada criança tem o seu próprio ritmo. Dê-lhe simplesmente amor.', body_sv = 'Glöm meningen ”Någons barn pratade tidigare”. Varje barn utvecklas i sin egen takt. Ge bara barnet kärlek.', body_vi = 'Hãy quên câu "Con nhà người ta nói sớm hơn" đi. Mỗi đứa trẻ có nhịp phát triển riêng. Mẹ chỉ cần trao cho bé tình yêu thương.', body_zh = '忘掉“别人家孩子说话更早”这句话。每个孩子的发育节奏都独一无二。你只要给宝宝爱就好。' WHERE id = '3e6bfa0e-5f58-4921-bf7a-6f47b0eb1125' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Camino del año y medio! 📸', body_es = '¡Ya tiene 12,5 meses! Abre la Sesión de fotos del bebé y guarda en imágenes los momentos más divertidos de esta etapa tan movida.', title_fr = 'En route vers 1 an et demi ! 📸', body_fr = 'Il a déjà 12,5 mois ! Ouvrez la Séance photo bébé et gardez en photo les moments les plus drôles de cette période agitée et mouvementée.', title_hi = 'डेढ़ साल की ओर! 📸', body_hi = 'वह अब 12.5 महीने का है! बेबी फ़ोटोशूट खोलिए और इस चुलबुले, तूफ़ानी बचपन के सबसे मज़ेदार पलों को तस्वीरों में सहेज लीजिए।', title_id = 'Menuju 1,5 tahun! 📸', body_id = 'Ia sudah berusia 12,5 bulan! Buka Sesi Foto Bayi dan abadikan momen paling lucu dari masa kanak-kanak yang aktif dan penuh gejolak ini.', title_ja = 'もうすぐ1歳半！📸', body_ja = 'もう12.5か月！「ベビーフォトセッション」を開いて、元気いっぱいでにぎやかなこの時期のいちばん面白い瞬間を写真に残しましょう。', title_ko = '1살 반을 향해! 📸', body_ko = '벌써 12.5개월이에요! 아기 사진 촬영을 열고 활발하고 정신없는 이 유아기의 가장 웃긴 순간들을 사진으로 남기세요.', title_nl = 'Op weg naar anderhalf jaar! 📸', body_nl = 'Je kindje is al 12,5 maanden! Open Babyfotoshoot en leg de grappigste momenten van deze drukke, stormachtige dreumestijd vast.', title_pl = 'Coraz bliżej półtora roku! 📸', body_pl = 'Ma już 12,5 miesiąca! Otwórz Sesję zdjęciową dziecka i uwiecznij na zdjęciach najzabawniejsze chwile tego ruchliwego, burzliwego okresu.', title_pt = 'A caminho do ano e meio! 📸', body_pt = 'Já tem 12,5 meses! Abra a Sessão Fotográfica do Bebé e guarde em fotos os momentos mais engraçados desta fase agitada e tempestuosa.', title_sv = 'Mot 1,5 år! 📸', body_sv = 'Barnet är redan 12,5 månader! Öppna Babyfotografering och spara de roligaste stunderna från denna livliga, stormiga småbarnstid i bilder.', title_vi = 'Hướng tới mốc 1 tuổi rưỡi! 📸', body_vi = 'Bé đã 12,5 tháng rồi! Hãy mở Chụp ảnh cho bé và lưu giữ những khoảnh khắc hài hước nhất của giai đoạn hiếu động, sôi nổi này.', title_zh = '向1岁半迈进！📸', body_zh = '宝宝已经12.5个月了！打开宝宝写真，用照片记录下这个活泼好动、风风火火的幼儿期里最好笑的瞬间。' WHERE id = 'b9520b22-b9b3-4ca3-a219-de05702404a8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se desarrolla la motricidad fina 🖍', body_es = '️ Puede que disfrute garabateando con un lápiz sobre el papel. Dale ceras gruesas adecuadas y observa su creatividad.', title_fr = 'La motricité fine se développe. 🖍', body_fr = '️ Il peut adorer gribouiller sur du papier avec un crayon. Donnez-lui de gros crayons adaptés et regardez sa créativité s''exprimer.', title_hi = 'बारीक मोटर स्किल्स विकसित हो रही हैं। 🖍', body_hi = '️ उसे पेंसिल से कागज़ पर लकीरें खींचने में मज़ा आ सकता है। उसे सही मोटे रंग दीजिए और उसकी रचनात्मकता देखिए।', title_id = 'Motorik halus berkembang. 🖍', body_id = '️ Ia mungkin senang mencoret-coret kertas dengan krayon. Berikan krayon tebal yang sesuai dan saksikan kreativitasnya.', title_ja = '手先が器用になってきた 🖍', body_ja = '️紙にクレヨンでぐるぐる描くのが楽しいようです。年齢に合った太いクレヨンを渡して、創造力を見守りましょう。', title_ko = '소근육이 발달하고 있어요. 🖍', body_ko = '️크레용으로 종이에 끄적이는 걸 즐길 수 있어요. 아이에게 맞는 굵은 크레용을 주고 창작하는 모습을 지켜보세요.', title_nl = 'De fijne motoriek ontwikkelt zich. 🖍', body_nl = '️ Je kindje vindt krassen met een kleurpotlood op papier misschien heerlijk. Geef hem geschikte dikke kleurpotloden en kijk hoe creatief hij is.', title_pl = 'Rozwija się motoryka mała. 🖍', body_pl = '️ Może mu sprawiać frajdę bazgranie kredką po papierze. Daj mu odpowiednie grube kredki i obserwuj jego kreatywność.', title_pt = 'A motricidade fina está a desenvolver-se. 🖍', body_pt = '️ Pode adorar rabiscar no papel com um lápis. Dê-lhe lápis de cor grossos adequados e acompanhe a criatividade dele.', title_sv = 'Finmotoriken utvecklas. 🖍', body_sv = '️ Barnet kan tycka om att klottra med krita på papper. Ge passande tjocka kritor och följ kreativiteten.', title_vi = 'Vận động tinh đang phát triển. 🖍', body_vi = '️ Bé có thể thích thú vẽ nguệch ngoạc bằng bút chì trên giấy. Hãy đưa cho bé bút màu to phù hợp và ngắm nhìn sự sáng tạo của bé.', title_zh = '精细动作在发展 🖍', body_zh = '️ 宝宝可能很喜欢用蜡笔在纸上涂涂画画。给宝宝合适的粗蜡笔，看看他的创作吧。' WHERE id = '0c105765-0e1a-42dd-bd14-0ca4153705c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina de sueño da seguridad 🌙', body_es = 'Repetir cada noche los mismos pasos (baño, cuento, bajar las luces) le ayudará a dormirse más tranquilo.', title_fr = 'Le rituel du coucher rassure. 🌙', body_fr = 'Les mêmes gestes, dans le même ordre chaque soir (bain, histoire, lumière tamisée), l''aideront à s''endormir plus sereinement.', title_hi = 'नींद का रूटीन भरोसा देता है। 🌙', body_hi = 'हर शाम एक ही क्रम में किए जाने वाले काम (स्नान, कहानी, रोशनी धीमी करना) उसे ज़्यादा आराम से सोने में मदद करेंगे।', title_id = 'Rutinitas tidur memberi rasa aman. 🌙', body_id = 'Kegiatan dengan urutan yang sama setiap malam (mandi, dongeng, meredupkan lampu) akan membantunya tertidur lebih nyaman.', title_ja = '寝る前の習慣は安心につながります 🌙', body_ja = '毎晩同じ順番で過ごすこと（お風呂、お話、照明を暗くする）で、よりスムーズに眠れるようになります。', title_ko = '수면 루틴은 안정감을 줘요. 🌙', body_ko = '매일 저녁 같은 순서로 하는 일들(목욕, 동화, 조명 낮추기)이 더 편하게 잠드는 데 도움이 될 거예요.', title_nl = 'Een slaapritueel geeft zekerheid. 🌙', body_nl = 'Elke avond dezelfde volgorde (badje, verhaaltje, lichten dimmen) helpt je kindje rustiger in slaap te vallen.', title_pl = 'Rytuał przed snem daje poczucie bezpieczeństwa. 🌙', body_pl = 'Czynności wykonywane co wieczór w tej samej kolejności (kąpiel, bajka, przygaszone światła) pomogą mu spokojniej zasnąć.', title_pt = 'A rotina de sono dá segurança. 🌙', body_pt = 'Repetir todas as noites os mesmos passos pela mesma ordem (banho, história, luzes mais baixas) vai ajudá-lo a adormecer com mais tranquilidade.', title_sv = 'Sömnrutinen ger trygghet. 🌙', body_sv = 'Samma ordning varje kväll (bad, saga, dämpat ljus) hjälper barnet att somna lugnare.', title_vi = 'Nếp ngủ mang lại cảm giác an toàn. 🌙', body_vi = 'Những việc làm theo cùng một trình tự mỗi tối (tắm, kể chuyện, giảm đèn) sẽ giúp bé dễ đi vào giấc ngủ hơn.', title_zh = '睡前习惯带来安全感 🌙', body_zh = '每晚按同样的顺序做同样的事（洗澡、讲故事、调暗灯光），能帮宝宝更轻松地入睡。' WHERE id = '1b77ed52-4cf2-48a6-98fc-53d0a94dc968' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Las encías vuelven a estar rojas y no para de babear? Registra el proceso en el Seguimiento de dentición y prepara mordedores fríos.', body_fr = 'Ses gencives sont encore rouges et il bave sans arrêt ? Notez l''évolution dans le Suivi des dents et préparez des anneaux de dentition froids.', body_hi = 'मसूड़े फिर लाल हो गए हैं और लार रुक नहीं रही? दाँत निकलने के ट्रैकर में इसे दर्ज कीजिए और ठंडे टीदर तैयार रखिए।', body_id = 'Gusinya memerah lagi dan air liurnya terus menetes? Catat prosesnya di Pelacak Tumbuh Gigi dan siapkan teether dingin.', body_ja = '歯ぐきがまた赤くなって、よだれが止まらない？「歯の生え始めトラッカー」に記録して、冷やした歯がためを用意しましょう。', body_ko = '잇몸이 또 빨개지고 침이 계속 흐르나요? 이앓이 기록에 과정을 남기고 차갑게 한 치발기를 준비해 두세요.', body_nl = 'Is het tandvlees weer rood en blijft je kindje kwijlen? Houd het bij in de Tandjestracker en leg koele bijtringen klaar.', body_pl = 'Dziąsła znów są czerwone, a ślinka cieknie bez przerwy? Zapisz przebieg w narzędziu do śledzenia ząbkowania i przygotuj schłodzone gryzaki.', body_pt = 'As gengivas estão outra vez vermelhas e não para de babar? Registe o processo no Registo de Dentição e prepare mordedores frios.', body_sv = 'Är tandköttet rött igen och slutar dreglet aldrig? Anteckna förloppet i Tandspåraren och ha kalla bitringar redo.', body_vi = 'Nướu của bé lại đỏ và chảy dãi không ngừng? Hãy ghi lại trong Theo dõi mọc răng và chuẩn bị vòng gặm nướu mát lạnh nhé.', body_zh = '牙龈又红了，口水还流个不停？在出牙追踪里记录下来，准备好冰凉的牙胶吧。' WHERE id = '795996e4-e3e1-4fa7-b442-27c8ffa35bff' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha acabado la fruta o la avena? Rellena ya la Lista de la compra y envía lo que falta al móvil de tu pareja.', body_fr = 'Plus de fruits ou de flocons d''avoine pour les repas ? Remplissez tout de suite la Liste de courses et envoyez-la sur le téléphone de votre conjoint.', body_hi = 'खाने के लिए फल या ओट्स खत्म हो गए? तुरंत शॉपिंग लिस्ट भरिए और ज़रूरतें अपने साथी के फ़ोन पर भेजिए।', body_id = 'Buah atau oat untuk makannya habis? Segera isi Daftar Belanja dan kirim ke ponsel pasangan Anda.', body_ja = '果物やオートミールが切れていませんか？すぐに「買い物リスト」に入れて、パートナーのスマホに送りましょう。', body_ko = '먹을 과일이나 오트밀이 떨어졌나요? 바로 쇼핑 목록을 채워 배우자 휴대폰으로 보내세요.', body_nl = 'Is het fruit of de havermout op? Vul meteen het Boodschappenlijstje in en stuur het naar de telefoon van je partner.', body_pl = 'Skończyły się owoce lub płatki owsiane? Od razu uzupełnij Listę zakupów i wyślij potrzeby na telefon partnera.', body_pt = 'Acabou a fruta ou a aveia para as refeições? Preencha já a Lista de Compras e envie os pedidos para o telemóvel do seu companheiro.', body_sv = 'Är frukten eller havregrynen slut? Fyll direkt i Inköpslistan och skicka det som behövs till din partners telefon.', body_vi = 'Hết trái cây hay yến mạch cho bữa ăn rồi? Hãy điền ngay Danh sách mua sắm và gửi yêu cầu đến điện thoại của bố.', body_zh = '吃的水果或燕麦没了？马上填好购物清单，把需求发到另一半手机上。' WHERE id = '452e9fa3-8dba-4774-8bfe-d6afa50d161c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Caminar de lado agarrado a los muebles es su ejercicio favorito. ¡Queda muy poco para los pasos sin ayuda! Echa un vistazo al Seguimiento del desarrollo.', body_fr = 'Avancer de côté le long des meubles est son exercice préféré. Les premiers pas seuls ne sont plus très loin ! Consultez le Suivi de développement.', body_hi = 'फ़र्नीचर के किनारे-किनारे बगल में कदम बढ़ाना उसकी पसंदीदा कसरत है। खुद के कदमों में बहुत कम समय बाकी है! ग्रोथ ट्रैकर देखिए।', body_id = 'Melangkah menyamping sambil berpegangan pada tepi perabot adalah latihan favoritnya. Langkah mandiri sudah sangat dekat! Lihat Pelacak Perkembangan.', body_ja = '家具のふちを伝い歩きするのがお気に入りの練習です。ひとり歩きまであと少し！「発達トラッカー」を見てみましょう。', body_ko = '가구 가장자리를 잡고 옆으로 걷는 게 가장 좋아하는 연습이에요. 혼자 걷기까지 얼마 안 남았어요! 성장 기록을 확인해 보세요.', body_nl = 'Zijwaarts langs de meubels stappen is zijn favoriete oefening. De eerste losse stapjes zijn heel dichtbij! Kijk in de Groeitracker.', body_pl = 'Chodzenie bokiem wzdłuż mebli to jego ulubione ćwiczenie. Do samodzielnych kroków zostało bardzo niewiele! Zajrzyj do Śledzenia rozwoju.', body_pt = 'Andar de lado agarrado à beira dos móveis é o exercício preferido dele. Faltam muito pouco para os passos sozinho! Veja o Registo de Desenvolvimento.', body_sv = 'Att gå i sidled längs möbelkanterna är barnets favoritövning. Snart kommer egna steg! Titta i Utvecklingsspåraren.', body_vi = 'Men theo mép đồ đạc bước ngang là bài tập yêu thích của bé. Chỉ còn chút nữa là bé tự đi được rồi! Hãy xem Theo dõi phát triển nhé.', body_zh = '扶着家具横着走是宝宝最爱的练习。离独立迈步只差一点点了！看看发育追踪吧。' WHERE id = '8c12c251-a9b5-45cb-92ff-f145e2484025' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla entre mamás 💬', body_es = '¿No puedes con las rabietas? Entra ya en la Comunidad Anacan, lee los comentarios de apoyo de otras mamás y respira.', title_fr = 'Entre mamans 💬', body_fr = 'Les crises vous dépassent ? Rejoignez tout de suite la Communauté Anacan, lisez les messages de soutien des autres mamans et soufflez un peu.', title_hi = 'माँओं की दिल की बातें 💬', body_hi = 'नखरे संभाल नहीं पा रहीं? तुरंत Anacan कम्युनिटी में आइए, दूसरी माँओं के हौसला बढ़ाने वाले कमेंट पढ़िए और सुकून पाइए।', title_id = 'Curhat sesama ibu 💬', body_id = 'Kewalahan menghadapi tantrum? Segera masuk ke Komunitas Anacan, baca komentar dukungan dari ibu-ibu lain, dan tenangkan diri.', title_ja = 'ママ同士のおしゃべり 💬', body_ja = 'かんしゃくに手を焼いていますか？すぐにAnacanコミュニティを開いて、ほかのママたちの温かいコメントを読んでほっとしましょう。', title_ko = '엄마들의 수다 💬', body_ko = '떼쓰기를 감당하기 어렵나요? 바로 Anacan 커뮤니티에 들어가 다른 엄마들의 응원 댓글을 읽으며 마음을 편히 하세요.', title_nl = 'Moeders onder elkaar 💬', body_nl = 'Kun je de driftbuien niet aan? Ga meteen naar de Anacan Community, lees de steunende reacties van andere moeders en kom tot rust.', title_pl = 'Mamy rozmawiają 💬', body_pl = 'Nie dajesz rady z napadami złości? Od razu wejdź do Społeczności Anacan, przeczytaj wspierające komentarze innych mam i odetchnij.', title_pt = 'Conversa entre mães 💬', body_pt = 'Não está a conseguir lidar com as birras? Entre já na Comunidade Anacan, leia os comentários de apoio de outras mães e descontraia.', title_sv = 'Mammasnack 💬', body_sv = 'Orkar du inte med utbrotten? Gå direkt in i Anacans Community, läs stöttande kommentarer från andra mammor och slappna av.', title_vi = 'Các mẹ tâm sự 💬', body_vi = 'Mẹ không xoay xở nổi với những cơn ăn vạ? Hãy vào ngay Cộng đồng Anacan, đọc những lời động viên của các mẹ khác để nhẹ lòng hơn.', title_zh = '妈妈们的知心话 💬', body_zh = '搞不定宝宝发脾气？马上进入Anacan社区，读读其他妈妈的暖心留言，放松一下。' WHERE id = '763e2885-6f82-4d6b-8ec4-680155ad7a5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se tira al suelo cuando no consigue lo que quiere? Ponte a su altura, háblale con calma y ponle nombre a lo que siente.', body_fr = 'Il se jette par terre quand il n''obtient pas ce qu''il veut ? Mettez-vous à sa hauteur et nommez ces crises en lui parlant calmement.', body_hi = 'मन का न होने पर खुद को ज़मीन पर पटकता है? उसके बराबर झुककर शांति से बात करते हुए इन पलों को पार कीजिए।', body_id = 'Ia menjatuhkan diri ke lantai saat keinginannya tidak dituruti? Berjongkoklah setinggi dirinya, bicara dengan tenang, dan beri nama pada perasaannya.', body_ja = '思いどおりにならないと床にひっくり返りますか？目線を合わせてしゃがみ、落ち着いて気持ちを言葉にしてあげましょう。', body_ko = '원하는 대로 안 되면 바닥에 드러눕나요? 눈높이를 맞춰 몸을 숙이고 차분히 말하며 감정에 이름을 붙여 주세요.', body_nl = 'Gooit je kindje zich op de grond als hij zijn zin niet krijgt? Zak door je knieën, praat rustig en benoem de driftbui.', body_pl = 'Rzuca się na podłogę, gdy nie dostaje tego, czego chce? Zniż się do jego poziomu, mów spokojnie i nazywaj te kryzysy.', body_pt = 'Atira-se para o chão quando não consegue o que quer? Baixe-se ao nível dele e, a falar com calma, dê nome a essas crises.', body_sv = 'Kastar sig barnet på golvet när det inte får som det vill? Sätt dig på barnets nivå, prata lugnt och sätt ord på utbrotten.', body_vi = 'Không được như ý là bé ném mình xuống sàn? Hãy cúi xuống ngang tầm bé, nói chuyện nhẹ nhàng và gọi tên những cơn khủng hoảng ấy.', body_zh = '要不到想要的就往地上一躺？蹲到和宝宝一样的高度，平静地说出他的感受。' WHERE id = 'f47e2fcf-5030-43a8-a77b-79834cb3f95a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Sin energía de tanto estar en casa? Elige en Lugares para mamás una cafetería donde estar a gusto y dedícate un rato.', body_fr = 'Rester à la maison vous a vidée de votre énergie. Choisissez parmi les Lieux adaptés aux mamans un café où vous installer confortablement et prenez du temps pour vous.', body_hi = 'घर में रहकर आपकी ऊर्जा खत्म हो गई है। माँ के लिए अनुकूल जगहों से कोई ऐसा कैफ़े चुनिए जहाँ आराम से बैठ सकें, और अपने लिए समय निकालिए।', body_id = 'Energi Anda habis karena terus di rumah? Pilih kafe yang nyaman dari Tempat Ramah Ibu dan luangkan waktu untuk diri sendiri.', body_ja = '家にこもってばかりでエネルギー切れ。「ママにやさしいスポット」からゆっくりできるカフェを選んで、自分の時間をつくりましょう。', body_ko = '집에만 있어 기운이 다 빠졌어요. 엄마 친화 장소에서 편히 앉을 수 있는 카페를 골라 나를 위한 시간을 가져 보세요.', body_nl = 'Is je energie op van het thuiszitten? Kies in Mamavriendelijke plekken een café waar je rustig kunt zitten en neem tijd voor jezelf.', body_pl = 'Siedzenie w domu odebrało ci energię. Wybierz z Miejsc przyjaznych mamom kawiarnię, w której wygodnie usiądziesz, i znajdź czas dla siebie.', body_pt = 'Ficar em casa esgotou-lhe a energia. Escolha nos Locais Amigos das Mães um café onde possa estar à vontade e reserve tempo para si.', body_sv = 'Energin har tagit slut av att vara hemma. Välj ett kafé i Mammavänliga platser där du kan sitta bekvämt och ta tid för dig själv.', body_vi = 'Ở nhà mãi khiến mẹ cạn năng lượng. Hãy chọn một quán cà phê có thể ngồi thoải mái trong Địa điểm thân thiện với mẹ và dành thời gian cho bản thân.', body_zh = '在家待得没电了？从妈妈友好场所里选一家能舒服坐坐的咖啡馆，给自己留点时间。' WHERE id = 'dfa800b1-6c2e-4bc9-b061-4b6d1df9eb95' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de la noche es mágico 📖', body_es = 'Una historia corta antes de dormir estimula su imaginación y refuerza el vínculo emocional entre vosotros.', title_fr = 'L''histoire du soir est magique. 📖', body_fr = 'Une petite histoire lue avant de dormir stimule son imagination et renforce le lien affectif entre vous.', title_hi = 'शाम की कहानी जादुई होती है। 📖', body_hi = 'सोने से पहले पढ़ी गई छोटी कहानी कल्पना शक्ति भी बढ़ाती है और आपके बीच का भावनात्मक रिश्ता भी मज़बूत करती है।', title_id = 'Dongeng malam itu ajaib. 📖', body_id = 'Cerita pendek sebelum tidur tidak hanya memperkuat daya khayalnya, tapi juga mempererat ikatan emosional di antara kalian.', title_ja = '寝る前のお話は魔法の時間 📖', body_ja = '寝る前の短いお話は、想像力をふくらませ、親子の心のつながりも深めてくれます。', title_ko = '잠자리 동화는 마법이에요. 📖', body_ko = '잠들기 전 읽어 주는 짧은 이야기는 상상력을 키우고 두 사람의 정서적 유대도 더 깊게 해 줘요.', title_nl = 'Een verhaaltje voor het slapen is magisch. 📖', body_nl = 'Een kort verhaaltje voor het slapengaan prikkelt de fantasie en versterkt de band tussen jullie.', title_pl = 'Wieczorna bajka jest magiczna. 📖', body_pl = 'Krótka historia przed snem rozwija wyobraźnię i wzmacnia więź emocjonalną między wami.', title_pt = 'A história da noite é mágica. 📖', body_pt = 'Uma história curta antes de dormir estimula a imaginação e reforça o laço emocional entre vocês.', title_sv = 'Kvällssagan är magisk. 📖', body_sv = 'En kort berättelse före sömnen stärker både fantasin och det känslomässiga bandet mellan er.', title_vi = 'Truyện kể buổi tối thật kỳ diệu. 📖', body_vi = 'Một câu chuyện ngắn trước khi ngủ vừa giúp bé phát triển trí tưởng tượng, vừa gắn kết tình cảm giữa mẹ và bé.', title_zh = '睡前故事有魔力 📖', body_zh = '睡前读一个小故事，既能激发想象力，又能加深你们之间的情感联结。' WHERE id = '8a51b6b4-96e5-40da-8e4b-a3f74c147eb5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aprende a jugar solo 🧩', body_es = 'Que pueda jugar solo, aunque sea un rato, demuestra que su atención se está desarrollando. Obsérvale con cariño desde lejos en esos momentos.', title_fr = 'Savoir jouer seul. 🧩', body_fr = 'Pouvoir jouer seul, même un court moment, montre que son attention se développe. Pendant ces moments, observez-le avec amour, de loin.', title_hi = 'अकेले खेलने का हुनर। 🧩', body_hi = 'थोड़ी देर के लिए ही सही, उसका अपने आप खेल पाना दिखाता है कि उसका ध्यान विकसित हो रहा है। ऐसे पलों में उसे दूर से प्यार से देखिए।', title_id = 'Kemampuan bermain sendiri. 🧩', body_id = 'Kemampuannya bermain sendiri, meski sebentar, menunjukkan perhatiannya sedang berkembang. Pada saat seperti ini, perhatikan ia dari jauh dengan penuh cinta.', title_ja = 'ひとり遊びの力 🧩', body_ja = '短い時間でもひとりで遊べるのは、集中力が育っている証拠です。そんなときは、少し離れたところから愛情をこめて見守りましょう。', title_ko = '혼자 노는 능력. 🧩', body_ko = '잠깐이라도 혼자 놀 수 있다는 건 집중력이 자라고 있다는 뜻이에요. 이럴 때는 멀리서 사랑스럽게 지켜봐 주세요.', title_nl = 'Zelfstandig spelen. 🧩', body_nl = 'Dat je kindje even alleen kan spelen, laat zien dat zijn concentratie groeit. Kijk op die momenten liefdevol van een afstandje toe.', title_pl = 'Umiejętność samodzielnej zabawy. 🧩', body_pl = 'To, że potrafi choć chwilę bawić się sam, pokazuje, że rozwija się jego uwaga. W takich chwilach obserwuj go z miłością z daleka.', title_pt = 'A capacidade de brincar sozinho. 🧩', body_pt = 'Conseguir brincar sozinho, mesmo por pouco tempo, mostra que a atenção dele se está a desenvolver. Nesses momentos, observe-o com carinho à distância.', title_sv = 'Förmågan att leka själv. 🧩', body_sv = 'Att barnet kan leka själv, även en kort stund, visar att uppmärksamheten utvecklas. Följ barnet kärleksfullt på avstånd i de stunderna.', title_vi = 'Kỹ năng tự chơi. 🧩', body_vi = 'Bé có thể tự chơi dù chỉ trong thời gian ngắn cho thấy khả năng tập trung đang phát triển. Những lúc ấy, hãy âu yếm dõi theo bé từ xa.', title_zh = '独自玩耍的能力 🧩', body_zh = '哪怕只能自己玩一小会儿，也说明宝宝的专注力在发展。这时远远地、满怀爱意地看着他吧。' WHERE id = 'b28c4699-a204-48ae-80c2-bef5008fdffd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos su crecimiento 📏', body_es = '¿Se le empieza a quedar pequeña la ropa? Añade sus nuevas medidas en el Registro de peso y sigue su crecimiento sano.', title_fr = 'On suit sa croissance. 📏', body_fr = 'Ses vêtements commencent à devenir trop petits ? Ajoutez ses nouvelles mesures dans le Suivi du poids et notez sa bonne croissance.', title_hi = 'बढ़त पर नज़र। 📏', body_hi = 'बच्चे के कपड़े छोटे होने लगे हैं? वेट ट्रैकर सेक्शन में नए आँकड़े जोड़िए और उसके सेहतमंद विकास को दर्ज कीजिए।', title_id = 'Memantau pertumbuhan. 📏', body_id = 'Bajunya mulai kekecilan? Tambahkan ukuran terbarunya di Pelacak Berat Badan dan catat pertumbuhannya yang sehat.', title_ja = '成長を見守ろう 📏', body_ja = 'お洋服が小さくなってきましたか？「体重トラッカー」に新しい数値を追加して、健やかな成長を記録しましょう。', title_ko = '성장을 지켜봐요. 📏', body_ko = '아이 옷이 작아지기 시작했나요? 체중 기록에 새 수치를 추가하고 건강한 성장을 기록하세요.', title_nl = 'We volgen de groei. 📏', body_nl = 'Worden de kleertjes van je kindje te klein? Voeg de nieuwe gegevens toe in de Gewichtstracker en houd zijn gezonde groei bij.', title_pl = 'Śledzimy wzrost. 📏', body_pl = 'Ubranka robią się za małe? Dodaj nowe pomiary w sekcji Licznik wagi i zapisuj jego zdrowy rozwój.', title_pt = 'A acompanhar o crescimento. 📏', body_pt = 'A roupa do seu filho começa a ficar pequena? Adicione as novas medidas no Registo de Peso e registe o seu crescimento saudável.', title_sv = 'Vi följer tillväxten. 📏', body_sv = 'Börjar kläderna bli för små? Lägg in de nya måtten i Viktspåraren och anteckna den friska utvecklingen.', title_vi = 'Theo dõi bé lớn lên. 📏', body_vi = 'Quần áo của bé bắt đầu chật? Hãy thêm số đo mới vào mục Theo dõi cân nặng và ghi lại sự phát triển khỏe mạnh của bé.', title_zh = '见证成长 📏', body_zh = '宝宝的衣服开始变小了？在体重记录里添加新数据，记录宝宝的健康成长吧。' WHERE id = 'e6b48652-88e0-49d8-b2cc-654a9f8eb626' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Quieres salir, pero hace viento. Deja que Tiempo y ropa te diga al momento qué ponerle.', body_fr = 'Vous voulez sortir, mais il y a du vent ? Laissez l''assistant Météo et tenue vous indiquer tout de suite la bonne tenue.', body_hi = 'बाहर जाना चाहती हैं, लेकिन हवा चल रही है? मौसम और कपड़े टूल तुरंत सही कपड़े बता देगा।', body_id = 'Ingin keluar rumah, tapi berangin? Biarkan asisten Cuaca dan Pakaian langsung memberi tahu pakaian yang tepat.', body_ja = 'お出かけしたいけれど、風が強い？「天気と服装」アシスタントで、ぴったりのコーデをすぐにチェックしましょう。', body_ko = '밖에 나가고 싶은데 바람이 부나요? 날씨와 옷차림 도우미가 알맞은 옷차림을 바로 알려 줄 거예요.', body_nl = 'Wil je naar buiten, maar waait het? Laat de assistent Weer en kleding je meteen de juiste outfit vertellen.', body_pl = 'Chcesz wyjść, ale wieje wiatr? Pomocnik Pogoda i ubiór od razu podpowie ci odpowiedni zestaw.', body_pt = 'Quer sair, mas está vento? Deixe que o assistente Tempo e Roupa lhe diga na hora a combinação certa.', body_sv = 'Vill du gå ut, men det blåser? Låt assistenten Väder och kläder direkt berätta rätt klädsel.', body_vi = 'Mẹ muốn ra ngoài nhưng trời có gió. Hãy để Trợ lý thời tiết và trang phục cho mẹ biết ngay bộ đồ phù hợp.', body_zh = '想出门，可是外面有风。让天气穿衣助手马上告诉你合适的搭配。' WHERE id = '13c2fa37-beb3-4b36-a1a9-4ba3fd32e6a0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intenta vestirse solo 👕', body_es = '¿Ya intenta quitarse o ponerse los calcetines él solo? Apoya con paciencia estas habilidades de motricidad fina.', title_fr = 'Il essaie de s''habiller seul. 👕', body_fr = 'Il essaie déjà d''enlever ou de mettre ses chaussettes tout seul ? Encouragez patiemment ces petites compétences motrices.', title_hi = 'खुद कपड़े पहनने की कोशिशें। 👕', body_hi = 'क्या वह अब खुद मोज़े उतारने या पहनने की कोशिश करता है? इन बारीक मोटर स्किल्स का धैर्य से साथ दीजिए।', title_id = 'Mencoba berpakaian sendiri. 👕', body_id = 'Ia sudah mencoba melepas atau memakai kaus kakinya sendiri? Dukung kemampuan motorik halus ini dengan sabar.', title_ja = '自分で着替えたい！👕', body_ja = 'もう自分で靴下を脱いだり履いたりしようとしていますか？この小さな手先の力を、根気よく応援しましょう。', title_ko = '혼자 옷 입기 도전. 👕', body_ko = '이제 양말을 혼자 벗거나 신으려고 하나요? 이 작은 운동 능력을 인내심을 갖고 응원해 주세요.', title_nl = 'Zelf aankleden proberen. 👕', body_nl = 'Probeert je kindje al zelf zijn sokken uit of aan te trekken? Steun deze kleine motorische vaardigheden met geduld.', title_pl = 'Próby samodzielnego ubierania. 👕', body_pl = 'Próbuje już sam zdejmować lub zakładać skarpetki? Cierpliwie wspieraj te małe umiejętności motoryczne.', title_pt = 'Tentativas de se vestir sozinho. 👕', body_pt = 'Já tenta tirar ou calçar as meias sozinho? Apoie com paciência estas pequenas competências motoras.', title_sv = 'Försök att klä sig själv. 👕', body_sv = 'Försöker barnet redan ta av eller sätta på sig strumporna själv? Stötta dessa motoriska färdigheter med tålamod.', title_vi = 'Bé tập tự mặc đồ. 👕', body_vi = 'Bé đã thử tự cởi hay tự mang tất? Hãy kiên nhẫn hỗ trợ những kỹ năng vận động tinh nhỏ bé này nhé.', title_zh = '尝试自己穿衣服 👕', body_zh = '宝宝已经在尝试自己脱袜子或穿袜子了？耐心支持这些小小的动作技能吧。' WHERE id = '9dd82a43-7f3a-4a5e-9d01-a99d7d738015' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Beber agua es muy importante 💧', body_es = 'Los niños activos tienen sed enseguida. No olvides ofrecerle agua a lo largo del día, sobre todo después de la cena.', title_fr = 'Boire de l''eau est essentiel. 💧', body_fr = 'Les enfants actifs ont vite soif. N''oubliez pas de lui proposer de l''eau tout au long de la journée, surtout après le dîner.', title_hi = 'पानी पीना बहुत ज़रूरी है। 💧', body_hi = 'सक्रिय बच्चों को जल्दी प्यास लगती है। दिनभर, खासकर रात के खाने के बाद, उसे पानी देना मत भूलिए।', title_id = 'Minum air itu sangat penting. 💧', body_id = 'Anak yang aktif cepat haus. Jangan lupa menawarinya air sepanjang hari, terutama setelah makan malam.', title_ja = '水分補給はとても大切です 💧', body_ja = '活発な子はすぐにのどが渇きます。一日を通して、特に夕食のあとは、お水をすすめるのを忘れずに。', title_ko = '물 마시기는 정말 중요해요. 💧', body_ko = '활발한 아이는 금방 목이 말라요. 하루 동안, 특히 저녁 식사 후에 물을 권하는 걸 잊지 마세요.', title_nl = 'Water drinken is heel belangrijk. 💧', body_nl = 'Actieve kinderen krijgen snel dorst. Vergeet niet om je kindje overdag water aan te bieden, vooral na het avondeten.', title_pl = 'Picie wody jest bardzo ważne. 💧', body_pl = 'Aktywnym dzieciom szybko chce się pić. Pamiętaj, by w ciągu dnia, zwłaszcza po kolacji, proponować mu wodę.', title_pt = 'Beber água é muito importante. 💧', body_pt = 'As crianças ativas ficam com sede depressa. Não se esqueça de lhe oferecer água ao longo do dia, sobretudo depois do jantar.', title_sv = 'Att dricka vatten är mycket viktigt. 💧', body_sv = 'Aktiva barn blir snabbt törstiga. Glöm inte att erbjuda vatten under dagen, särskilt efter middagen.', title_vi = 'Uống nước rất quan trọng. 💧', body_vi = 'Trẻ hiếu động rất nhanh khát. Mẹ nhớ cho bé uống nước trong ngày, nhất là sau bữa tối nhé.', title_zh = '喝水非常重要 💧', body_zh = '活泼的孩子很容易口渴。白天，尤其是晚饭后，别忘了给宝宝喝点水。' WHERE id = 'ccf44d60-2dc0-447f-b1ea-dd06a80f0324' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Intenta poner un cubo encima de otro, pero se cae. Lo vuelve a probar con atención. Observa en silencio sus intentos de pequeño ingeniero.', body_fr = 'Il essaie d''empiler deux cubes, mais ils tombent. Il recommence avec attention. Observez en silence ses essais d''ingénieur.', body_hi = 'दो खिलौना ब्लॉक एक के ऊपर एक रखने की कोशिश करता है, पर वे गिर जाते हैं। वह ध्यान से फिर कोशिश करता है। उसकी इंजीनियरिंग की कोशिशों को चुपचाप देखिए।', body_id = 'Ia mencoba menumpuk dua balok mainan, tapi jatuh. Ia mencobanya lagi dengan saksama. Saksikan diam-diam usaha kecilnya sebagai insinyur.', body_ja = '積み木を2つ重ねようとしても、くずれてしまいます。それでもまた慎重に挑戦。小さなエンジニアの挑戦をそっと見守りましょう。', body_ko = '블록 두 개를 쌓으려다 무너져요. 그래도 집중해서 다시 시도해요. 꼬마 엔지니어의 도전을 조용히 지켜봐 주세요.', body_nl = 'Je kindje probeert twee blokken op elkaar te zetten, maar ze vallen om. Hij probeert het zorgvuldig opnieuw. Bekijk zijn bouwpogingen in stilte.', body_pl = 'Próbuje postawić jedną kostkę na drugiej, ale się przewracają. Uważnie próbuje jeszcze raz. Po cichu obserwuj jego inżynierskie próby.', body_pt = 'Tenta pôr dois cubos um em cima do outro, mas caem. Volta a tentar com atenção. Observe em silêncio estas tentativas de engenharia.', body_sv = 'Barnet försöker stapla två klossar, men de ramlar. Det försöker noga igen. Följ ingenjörsförsöken i tysthet.', body_vi = 'Bé cố chồng hai khối đồ chơi lên nhau nhưng chúng đổ. Bé chăm chú thử lại. Hãy lặng lẽ quan sát những nỗ lực "kỹ sư" của bé.', body_zh = '宝宝想把两块积木摞起来，可总是倒。他会专注地一试再试。静静地欣赏这位小工程师的尝试吧。' WHERE id = '58866969-75c5-44cd-a308-210945d7a2af' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Fin del día, tu momento 🛁', body_es = '¿Hoy has acabado agotada? Date una ducha caliente, descansa y date las gracias por todo lo que has hecho.', title_fr = 'Fin de journée, votre moment. 🛁', body_fr = 'Très fatiguée aujourd''hui ? Prenez une douche chaude, reposez-vous et remerciez-vous pour tout ce que vous avez fait.', title_hi = 'दिन का अंत, आपका समय। 🛁', body_hi = 'आज बहुत थक गईं? गरम पानी से नहाइए, आराम कीजिए और जो कुछ आपने किया, उसके लिए खुद को धन्यवाद दीजिए।', title_id = 'Akhir hari, waktunya untuk Anda. 🛁', body_id = 'Hari ini sangat lelah? Mandilah air hangat, beristirahat, dan berterima kasihlah pada diri sendiri atas semua yang sudah Anda lakukan.', title_ja = '一日の終わりは、あなたの時間 🛁', body_ja = '今日はとても疲れましたか？温かいシャワーを浴びてゆっくり休み、がんばった自分に「ありがとう」と言ってあげましょう。', title_ko = '하루의 끝, 엄마의 시간. 🛁', body_ko = '오늘 많이 지쳤나요? 따뜻한 물로 샤워하고 쉬면서 오늘 해낸 모든 일에 대해 스스로에게 고마워하세요.', title_nl = 'Einde van de dag, tijd voor jou. 🛁', body_nl = 'Was je vandaag erg moe? Neem een warme douche, rust uit en bedank jezelf voor alles wat je hebt gedaan.', title_pl = 'Koniec dnia, czas dla ciebie. 🛁', body_pl = 'Bardzo się dziś zmęczyłaś? Weź ciepły prysznic, odpocznij i podziękuj sobie za wszystko, co zrobiłaś.', title_pt = 'O fim do dia é o seu momento. 🛁', body_pt = 'Hoje ficou muito cansada? Tome um duche quente, descanse e agradeça a si própria por tudo o que fez.', title_sv = 'Dagens slut, din tid. 🛁', body_sv = 'Har du varit väldigt trött i dag? Ta en varm dusch, vila och tacka dig själv för allt du har gjort.', title_vi = 'Cuối ngày là thời gian của mẹ. 🛁', body_vi = 'Hôm nay mẹ mệt lắm rồi? Hãy tắm nước ấm, nghỉ ngơi và cảm ơn chính mình vì tất cả những gì mẹ đã làm.', title_zh = '一天结束了，现在是你的时间 🛁', body_zh = '今天累坏了吧？冲个热水澡，好好休息，为自己做的一切谢谢自己。' WHERE id = '8a5f3751-2bcd-4454-bfef-74c90f1c3f85' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Aprendemos las partes del cuerpo! 👃', body_es = '¿Cuando le dices «¿Dónde está tu nariz?» la señala con su dedito? Convierte estos descubrimientos en un juego divertido delante del espejo.', title_fr = 'On apprend les parties du corps ! 👃', body_fr = 'Quand vous dites « Où est ton nez ? », il le montre de son petit doigt ? Transformez ces jolies découvertes en jeu devant le miroir et amusez-vous ensemble.', title_hi = 'शरीर के अंग सीख रहे हैं! 👃', body_hi = '''नाक कहाँ है?'' पूछने पर नन्ही उँगली से दिखाता है? इन प्यारी खोजों को आईने के सामने खेल बनाकर उसके साथ मज़ा कीजिए।', title_id = 'Belajar anggota tubuh! 👃', body_id = 'Saat Anda bertanya "Hidungnya mana?", ia menunjuk dengan jari kecilnya? Jadikan penemuan manis ini permainan seru di depan cermin.', title_ja = '体の部分を覚えよう！👃', body_ja = '「お鼻はどこ？」と聞くと、小さな指で指さしますか？鏡の前でこのかわいい発見を遊びにして、一緒に楽しみましょう。', title_ko = '신체 부위를 배워요! 👃', body_ko = '"코 어디 있어?" 하면 작은 손가락으로 가리키나요? 이 귀여운 발견을 거울 앞 놀이로 만들어 함께 즐겨 보세요.', title_nl = 'We leren lichaamsdelen! 👃', body_nl = 'Wijst je kindje met zijn vingertje als je vraagt: waar is je neus? Maak er voor de spiegel een leuk spelletje van.', title_pl = 'Uczymy się części ciała! 👃', body_pl = 'Na „Gdzie masz nos?” pokazuje go małym paluszkiem? Zamień te słodkie odkrycia w zabawę przed lustrem i bawcie się razem.', title_pt = 'A aprender as partes do corpo! 👃', body_pt = 'Quando lhe diz "Onde está o nariz?", aponta com o dedinho? Divirta-se com ele transformando estas descobertas num jogo em frente ao espelho.', title_sv = 'Vi lär oss kroppsdelar! 👃', body_sv = 'Pekar barnet med sitt lilla finger när du säger ”Var är näsan?”? Gör dessa söta upptäckter till en lek framför spegeln.', title_vi = 'Cùng học các bộ phận cơ thể! 👃', body_vi = 'Mẹ hỏi "Mũi con đâu?" là bé chỉ bằng ngón tay bé xíu? Hãy biến những khám phá đáng yêu này thành trò chơi trước gương và vui cùng bé.', title_zh = '一起认识身体部位！👃', body_zh = '你问“鼻子在哪里？”宝宝会用小手指指给你看吗？在镜子前把这些可爱的发现变成游戏，一起玩吧。' WHERE id = 'dcaa4b27-ca42-45e3-98f1-f11ad70e3dc8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de un tentempié sano 🍎', body_es = 'Para niños con energía inagotable, los trozos de fruta o los palitos de verdura son ideales. Deja que los coja y se los coma solo.', title_fr = 'L''heure d''un en-cas sain. 🍎', body_fr = 'Pour les enfants pleins d''énergie, des tranches de fruits ou des bâtonnets de légumes sont un excellent choix. Laissez-le les prendre et les manger tout seul.', title_hi = 'सेहतमंद स्नैक का समय। 🍎', body_hi = 'कभी न थकने वाले बच्चों के लिए फलों के टुकड़े या सब्ज़ियों की स्टिक बढ़िया विकल्प हैं। उसे खुद पकड़कर खाने का मौका दीजिए।', title_id = 'Waktunya camilan sehat. 🍎', body_id = 'Untuk anak yang energinya tak ada habisnya, potongan buah atau stik sayur adalah pilihan tepat. Biarkan ia memegang dan memakannya sendiri.', title_ja = 'ヘルシーなおやつタイム 🍎', body_ja = '元気いっぱいの子には、くし切りの果物や野菜スティックがぴったり。自分で持って食べられるようにしてあげましょう。', title_ko = '건강한 간식 시간. 🍎', body_ko = '에너지가 끝없는 아이에게는 과일 조각이나 채소 스틱이 훌륭한 선택이에요. 혼자 집어 먹을 수 있게 해 주세요.', title_nl = 'Tijd voor een gezond tussendoortje. 🍎', body_nl = 'Voor kinderen met eindeloze energie zijn stukjes fruit of groentesticks een prima keuze. Laat je kindje ze zelf pakken en opeten.', title_pl = 'Czas na zdrową przekąskę. 🍎', body_pl = 'Dla dzieci o niewyczerpanej energii plasterki owoców lub słupki warzyw to świetny wybór. Pozwól mu samemu brać je i jeść.', title_pt = 'Hora do lanche saudável. 🍎', body_pt = 'Para crianças com energia inesgotável, fatias de fruta ou palitos de legumes são uma ótima escolha. Deixe que pegue neles e coma sozinho.', title_sv = 'Dags för nyttigt mellanmål. 🍎', body_sv = 'Fruktbitar eller grönsaksstavar är ett utmärkt val för barn med oändlig energi. Låt barnet ta och äta själv.', title_vi = 'Giờ ăn nhẹ lành mạnh. 🍎', body_vi = 'Với những em bé tràn đầy năng lượng, lát trái cây hay que rau củ là lựa chọn tuyệt vời. Hãy tạo điều kiện để bé tự cầm ăn.', title_zh = '健康加餐时间 🍎', body_zh = '对精力无限的孩子来说，水果片或蔬菜条是很好的选择。让宝宝自己拿着吃吧。' WHERE id = 'e70adad3-3a0b-4d15-ab3c-9f286916a872' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pequeño artista en acción! 🖍', body_es = '️ Dale ceras gruesas y déjale garabatear libremente en el papel. Es muy bueno para la motricidad fina y la creatividad.', title_fr = 'Petit artiste au travail ! 🖍', body_fr = '️ Donnez-lui de gros crayons et laissez-le gribouiller librement sur la feuille. C''est excellent pour sa motricité fine et sa créativité.', title_hi = 'नन्हा कलाकार काम पर! 🖍', body_hi = '️ मोटे रंग दीजिए और उसे कागज़ पर खुलकर आड़ी-तिरछी लकीरें खींचने दीजिए। यह बारीक मोटर स्किल्स और रचनात्मकता के लिए बहुत फ़ायदेमंद है।', title_id = 'Seniman kecil sedang beraksi! 🖍', body_id = '️ Berikan krayon tebal dan biarkan ia mencoret-coret kertas dengan bebas. Ini sangat bermanfaat untuk motorik halus dan kreativitasnya.', title_ja = '小さな画家が作業中！🖍', body_ja = '️太いクレヨンを渡して、紙に自由にお絵かきさせてあげましょう。手先の発達と創造力にとても役立ちます。', title_ko = '꼬마 화가 작업 중! 🖍', body_ko = '️굵은 크레용을 주고 종이에 마음껏 끄적이게 해 주세요. 소근육과 창의력에 아주 좋아요.', title_nl = 'Een kleine kunstenaar aan het werk! 🖍', body_nl = '️ Geef je kindje dikke kleurpotloden of verf en laat hem vrij krassen op papier. Dat is heel goed voor de fijne motoriek en de creativiteit.', title_pl = 'Mały artysta przy pracy! 🖍', body_pl = '️ Daj mu grube kredki i pozwól swobodnie bazgrać po kartce. To bardzo korzystne dla motoryki małej i kreatywności.', title_pt = 'Pequeno artista em ação! 🖍', body_pt = '️ Dê-lhe lápis de cor grossos e deixe-o rabiscar livremente na folha. É muito bom para a motricidade fina e a criatividade.', title_sv = 'Liten konstnär i arbete! 🖍', body_sv = '️ Ge tjocka kritor och låt barnet klottra fritt på papperet. Det är mycket bra för finmotoriken och kreativiteten.', title_vi = 'Họa sĩ nhí đang làm việc! 🖍', body_vi = '️ Hãy đưa cho bé bút màu to và để bé tự do vẽ nguệch ngoạc trên giấy. Điều này rất có lợi cho vận động tinh và sự sáng tạo.', title_zh = '小画家上岗啦！🖍', body_zh = '️ 给宝宝粗蜡笔，让他在纸上随意涂鸦。这对精细动作和创造力都很有好处。' WHERE id = '6b0a9309-594c-4f0a-a15f-6c0611c0d5c3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Descubre en el mapa de Lugares para mamás un parque nuevo donde pasear cómodamente con el carrito y sal a dar una vuelta.', body_fr = 'Découvrez sur la carte des Lieux adaptés aux mamans un nouveau parc où vous promener facilement avec la poussette, et partez en balade.', body_hi = 'हमारे माँ के लिए अनुकूल जगहों के नक्शे से कोई नया पार्क खोजिए जहाँ स्ट्रॉलर के साथ आराम से घूम सकें, और सैर पर निकलिए।', body_id = 'Temukan taman baru yang nyaman untuk jalan-jalan dengan stroller di peta Tempat Ramah Ibu, lalu pergilah berjalan-jalan.', body_ja = '「ママにやさしいスポット」マップで、ベビーカーでゆったりお散歩できる新しい公園を見つけて出かけましょう。', body_ko = '엄마 친화 장소 지도에서 유모차로 편하게 걸을 수 있는 새로운 공원을 찾아 산책을 나가 보세요.', body_nl = 'Ontdek op onze kaart Mamavriendelijke plekken een nieuw park waar je makkelijk met de kinderwagen kunt wandelen, en ga op pad.', body_pl = 'Odkryj na naszej mapie Miejsc przyjaznych mamom nowy park, po którym wygodnie pospacerujesz z wózkiem, i wybierzcie się na spacer.', body_pt = 'Descubra no mapa dos Locais Amigos das Mães um parque novo onde possa passear à vontade com o carrinho e saia a passear.', body_sv = 'Upptäck en ny park där du kan promenera bekvämt med barnvagnen på vår karta Mammavänliga platser och gå ut på en promenad.', body_vi = 'Hãy khám phá một công viên mới có thể đẩy xe đẩy thoải mái trên bản đồ Địa điểm thân thiện với mẹ và cùng bé đi dạo.', body_zh = '在我们的妈妈友好场所地图上找一个适合推婴儿车散步的新公园，出去走走吧。' WHERE id = 'ccb3a3d0-8dc5-450a-b184-37cf81a39c01' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina de sueño da seguridad 🌙', body_es = 'Repetir cada noche los mismos pasos (baño, cuento, bajar las luces) le ayudará a dormirse antes.', title_fr = 'Le rituel du coucher rassure. 🌙', body_fr = 'Les mêmes gestes, dans le même ordre chaque soir (bain, histoire, lumière tamisée), l''aideront à s''endormir plus vite.', title_hi = 'नींद का रूटीन भरोसा देता है। 🌙', body_hi = 'हर शाम एक ही क्रम में किए जाने वाले काम (स्नान, कहानी, रोशनी धीमी करना) उसे जल्दी सोने में मदद करेंगे।', title_id = 'Rutinitas tidur memberi rasa aman. 🌙', body_id = 'Kegiatan dengan urutan yang sama setiap malam (mandi, dongeng, meredupkan lampu) akan membantunya tertidur lebih cepat.', title_ja = '寝る前の習慣は安心につながります 🌙', body_ja = '毎晩同じ順番で過ごすこと（お風呂、お話、照明を暗くする）で、より早く眠れるようになります。', title_ko = '수면 루틴은 안정감을 줘요. 🌙', body_ko = '매일 저녁 같은 순서로 하는 일들(목욕, 동화, 조명 낮추기)이 더 빨리 잠드는 데 도움이 될 거예요.', title_nl = 'Een slaapritueel geeft zekerheid. 🌙', body_nl = 'Elke avond dezelfde volgorde (badje, verhaaltje, lichten dimmen) helpt je kindje sneller in slaap te vallen.', title_pl = 'Rytuał przed snem daje poczucie bezpieczeństwa. 🌙', body_pl = 'Czynności wykonywane co wieczór w tej samej kolejności (kąpiel, bajka, przygaszone światła) pomogą mu szybciej zasnąć.', title_pt = 'A rotina de sono dá segurança. 🌙', body_pt = 'Repetir todas as noites os mesmos passos pela mesma ordem (banho, história, luzes mais baixas) vai ajudá-lo a adormecer mais depressa.', title_sv = 'Sömnrutinen ger trygghet. 🌙', body_sv = 'Samma ordning varje kväll (bad, saga, dämpat ljus) hjälper barnet att somna snabbare.', title_vi = 'Nếp ngủ mang lại cảm giác an toàn. 🌙', body_vi = 'Những việc làm theo cùng một trình tự mỗi tối (tắm, kể chuyện, giảm đèn) sẽ giúp bé ngủ nhanh hơn.', title_zh = '睡前习惯带来安全感 🌙', body_zh = '每晚按同样的顺序做同样的事（洗澡、讲故事、调暗灯光），能帮宝宝更快入睡。' WHERE id = 'dd0a1e57-cbbc-4cc0-9c63-a03032174ab5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cada día crece un poquito más. Abre ya la Sesión de fotos del bebé y guarda para siempre este momento tan auténtico.', body_fr = 'Il grandit un peu plus chaque jour. Ouvrez tout de suite la Séance photo bébé et gravez ce moment spontané dans vos souvenirs.', body_hi = 'वह हर दिन थोड़ा और बड़ा हो रहा है। तुरंत बेबी फ़ोटोशूट खोलिए और उसके इस सच्चे पल को यादों में बसा लीजिए।', body_id = 'Ia tumbuh sedikit demi sedikit setiap hari. Segera buka Sesi Foto Bayi dan abadikan momen tulusnya ini.', body_ja = '毎日少しずつ大きくなっています。すぐに「ベビーフォトセッション」を開いて、この自然な瞬間を記憶に刻みましょう。', body_ko = '아이는 날마다 조금씩 더 자라요. 바로 아기 사진 촬영을 열어 이 꾸밈없는 순간을 기억에 새기세요.', body_nl = 'Je kindje groeit elke dag een beetje meer. Open meteen Babyfotoshoot en leg dit oprechte moment voor altijd vast.', body_pl = 'Z każdym dniem jest coraz większy. Od razu otwórz Sesję zdjęciową dziecka i uwiecznij tę szczerą chwilę.', body_pt = 'Cresce um pouco mais a cada dia. Abra já a Sessão Fotográfica do Bebé e grave na memória este momento tão genuíno.', body_sv = 'Barnet växer lite mer för varje dag. Öppna direkt Babyfotografering och förevig detta äkta ögonblick.', body_vi = 'Mỗi ngày bé lại lớn thêm một chút. Hãy mở ngay Chụp ảnh cho bé và khắc ghi khoảnh khắc chân thật này.', body_zh = '宝宝每天都在长大一点。马上打开宝宝写真，把这个真情流露的瞬间留在记忆里吧。' WHERE id = '12139491-dd07-42f8-b056-98645d9880be' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se libera en un ambiente tranquilo.', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme.', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ रोशनियाँ और स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ शांत माहौल में बनता है।', body_id = '1 jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang.', body_ja = '寝る1時間前には、家の明るい照明と画面をすべて消しましょう。メラトニンは落ち着いた環境でこそ分泌されます。', body_ko = '잠들기 1시간 전에는 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 차분한 환경에서만 분비돼요.', body_nl = 'Doe een uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving aangemaakt.', body_pl = 'Godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym otoczeniu.', body_pt = '1 hora antes de dormir, apague todas as luzes fortes e ecrãs da casa. A melatonina só é libertada num ambiente calmo.', body_sv = 'Släck alla starka lampor och skärmar i hemmet 1 timme före läggdags. Melatonin bildas bara i en lugn miljö.', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh.', body_zh = '睡前1小时，关掉家里所有的昏暗灯光和屏幕。褪黑素只有在安静的环境中才会分泌。' WHERE id = '302d3885-ce15-4277-a0cf-d95f95d7ed63' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ya puede entretenerse solo con sus juguetes durante 10-15 minutos. Vigílale desde lejos y disfruta del silencio.', body_fr = 'Il sait déjà s''occuper seul avec ses jouets pendant 10-15 minutes. Surveillez-le de loin et savourez le calme.', body_hi = 'अब वह 10-15 मिनट अपने खिलौनों में अकेले मगन रह सकता है। दूर से उस पर नज़र रखिए और शांति का मज़ा लीजिए।', body_id = 'Kini ia sudah bisa asyik sendiri dengan mainannya selama 10-15 menit. Awasi dari jauh dan nikmati ketenangannya.', body_ja = 'もう10-15分はひとりでおもちゃで遊べるようになりました。少し離れて見守りながら、静かなひとときを味わいましょう。', body_ko = '이제 10-15분 동안 혼자 장난감을 가지고 놀 수 있어요. 옆에서 지켜보며 고요함을 즐겨 보세요.', body_nl = 'Je kindje kan zich nu 10-15 minuten alleen met zijn speelgoed vermaken. Houd een oogje in het zeil van een afstandje en geniet van de stilte.', body_pl = 'Potrafi już przez 10-15 minut sam zająć się zabawkami. Miej go na oku z boku i delektuj się ciszą.', body_pt = 'Já consegue entreter-se sozinho com os brinquedos 10-15 minutos. Vigie-o à distância e aproveite o silêncio.', body_sv = 'Nu kan barnet sysselsätta sig själv med leksakerna i 10-15 minuter. Håll uppsikt på avstånd och njut av tystnaden.', body_vi = 'Bé đã có thể tự chơi với đồ chơi 10-15 phút. Hãy trông chừng bé từ xa và tận hưởng chút yên tĩnh nhé.', body_zh = '宝宝已经能自己玩玩具10-15分钟了。在一旁看着他，享受这份安静吧。' WHERE id = '78f8f713-17f3-46f4-83f8-9cdbfd0c9894' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Encuentra el juguete que le has escondido detrás de algo? ¡Entiende que los objetos siguen existiendo aunque no los vea!', body_fr = 'Il retrouve le jouet que vous avez caché derrière quelque chose ? Il comprend que les objets continuent d''exister !', body_hi = 'आँखों से दूर करके छिपाया खिलौना वह जाकर छिपने की जगह से ढूँढ लेता है? वह समझ रहा है कि चीज़ें नज़र से हटकर भी मौजूद रहती हैं!', body_id = 'Ia menemukan mainan yang Anda sembunyikan dari pandangannya? Ia mulai memahami bahwa benda tetap ada!', body_ja = '見えないところに隠したおもちゃを、ちゃんと探し出せますか？物が見えなくてもそこにあることを理解しています！', body_ko = '눈앞에서 치운 장난감을 숨겨 둔 곳에서 찾아내나요? 물건이 사라지지 않는다는 걸 이해하고 있어요!', body_nl = 'Vindt je kindje een speeltje dat je uit zijn zicht hebt verstopt? Hij begrijpt dat dingen blijven bestaan!', body_pl = 'Znajduje zabawkę, którą schowałaś mu sprzed oczu? Rozumie, że przedmioty istnieją, nawet gdy ich nie widzi!', body_pt = 'Encontra o brinquedo que tirou da vista dele e escondeu atrás de algo? Está a perceber que os objetos continuam a existir!', body_sv = 'Hittar barnet leksaken som du gömt bakom något? Barnet förstår att föremål finns kvar!', body_vi = 'Món đồ chơi mẹ giấu đi, bé tìm ra được ở chỗ mẹ giấu? Bé đã hiểu rằng đồ vật vẫn tồn tại dù không nhìn thấy!', body_zh = '你把玩具从宝宝眼前拿开藏起来，他会去藏的地方找出来？宝宝明白物体是一直存在的了！' WHERE id = 'c1daed2c-e22f-4c5a-8534-4ff90b6b866e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando le dices «Trae la pelota», ¿de verdad va a buscarla? Su vocabulario crece rápido. Háblale con frases más elaboradas.', body_fr = 'Quand vous dites « Apporte le ballon », il part vraiment le chercher. Son vocabulaire s''enrichit vite. Parlez-lui avec des phrases plus élaborées.', body_hi = '''गेंद लाओ'' कहने पर सच में जाकर गेंद ढूँढता है। शब्द भंडार तेज़ी से बढ़ रहा है। उससे थोड़े लंबे वाक्यों में बात कीजिए।', body_id = 'Saat Anda bilang "Ambil bolanya", ia benar-benar pergi mencarinya. Kosakatanya bertambah pesat. Ajak ia bicara dengan kalimat yang lebih panjang.', body_ja = '「ボール持ってきて」と言うと、本当にボールを探しに行きますか？語彙がどんどん増えています。もう少し長い文で話しかけてみましょう。', body_ko = '"공 가져와" 하면 정말 가서 공을 찾아요. 어휘가 빠르게 늘고 있어요. 더 다양한 문장으로 이야기해 주세요.', body_nl = 'Gaat je kindje echt de bal zoeken als je zegt: haal de bal? Zijn woordenschat groeit snel. Praat met hem in langere zinnen.', body_pl = 'Na „Przynieś piłkę” naprawdę idzie jej szukać. Zasób słów szybko rośnie. Rozmawiaj z nim bardziej złożonymi zdaniami.', body_pt = 'Quando lhe diz "Traz a bola", vai mesmo procurá-la. O vocabulário cresce depressa. Fale com ele usando frases mais elaboradas.', body_sv = 'När du säger ”Hämta bollen” går barnet verkligen och letar efter den. Ordförrådet växer snabbt. Prata med mer avancerade meningar.', body_vi = 'Mẹ nói "Mang bóng lại đây" là bé đi tìm bóng thật. Vốn từ đang tăng nhanh. Hãy nói chuyện với bé bằng những câu phức tạp hơn.', body_zh = '你说“把球拿来”，宝宝真的会去找球。词汇量增长得很快。用更复杂的句子和宝宝说话吧。' WHERE id = '05fff0e7-029c-401c-bfab-497bbc099997' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grandes emociones, cuerpo pequeño 🌪', body_es = '️ Es normal que se frustre y llore cuando no puede expresarse. Ponte a su altura y dile con voz tranquila que entiendes lo que siente.', title_fr = 'De grandes émotions dans un petit corps. 🌪', body_fr = '️ C''est normal qu''il s''énerve et pleure quand il n''arrive pas à s''exprimer. Mettez-vous à sa hauteur et dites-lui d''une voix douce que vous comprenez ce qu''il ressent.', title_hi = 'बड़ी भावनाएँ, छोटा शरीर। 🌪', body_hi = '️ अपनी बात न कह पाने पर चिढ़कर रोना सामान्य है। उसके बराबर झुकिए और शांत आवाज़ में बताइए कि आप उसकी भावनाएँ समझती हैं।', title_id = 'Emosi besar, tubuh kecil. 🌪', body_id = '️ Wajar jika ia kesal dan menangis saat belum bisa mengungkapkan diri. Berjongkoklah setinggi dirinya dan katakan dengan suara tenang bahwa Anda memahami perasaannya.', title_ja = '大きな気持ち、小さな体 🌪', body_ja = '️うまく気持ちを伝えられないときに、イライラして泣くのは自然なことです。目線を合わせてしゃがみ、落ち着いた声で「気持ちわかるよ」と伝えましょう。', title_ko = '큰 감정, 작은 몸. 🌪', body_ko = '️자신을 표현하지 못할 때 화가 나서 우는 건 자연스러운 일이에요. 눈높이를 맞춰 몸을 숙이고 차분한 목소리로 마음을 이해한다고 말해 주세요.', title_nl = 'Grote gevoelens, klein lijfje. 🌪', body_nl = '️ Het is normaal dat je kindje boos wordt en huilt als hij zich niet kan uiten. Zak door je knieën en zeg met een rustige stem dat je zijn gevoelens begrijpt.', title_pl = 'Wielkie emocje, małe ciało. 🌪', body_pl = '️ To normalne, że denerwuje się i płacze, gdy nie umie się wyrazić. Zniż się do jego poziomu i spokojnym głosem powiedz, że rozumiesz jego uczucia.', title_pt = 'Grandes emoções, corpo pequenino. 🌪', body_pt = '️ É normal irritar-se e chorar quando não se consegue expressar. Baixe-se ao nível dele e diga-lhe, com voz calma, que compreende o que sente.', title_sv = 'Stora känslor, liten kropp. 🌪', body_sv = '️ Det är normalt att bli arg och gråta när barnet inte kan uttrycka sig. Sätt dig på barnets nivå och säg med lugn röst att du förstår känslorna.', title_vi = 'Cảm xúc lớn, cơ thể nhỏ. 🌪', body_vi = '️ Khi chưa diễn đạt được, bé bực bội và khóc là chuyện bình thường. Hãy cúi xuống ngang tầm bé và nói bằng giọng nhẹ nhàng rằng mẹ hiểu cảm xúc của bé.', title_zh = '大情绪，小身体 🌪', body_zh = '️ 表达不出来时又急又哭是正常的。蹲到宝宝的高度，用平静的声音告诉他你懂他的感受。' WHERE id = '663824a2-b8fe-471a-b981-3eb69f3a2c7f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Jugar con agua relaja 💧', body_es = 'Llena un barreño pequeño con agua y echa dentro unos recipientes de plástico. Jugar con agua ayuda a los niños a liberar energía y relajarse.', title_fr = 'Jouer avec l''eau apaise. 💧', body_fr = 'Remplissez une petite bassine d''eau et mettez-y des récipients en plastique. Jouer avec l''eau aide les enfants à se défouler et à se détendre.', title_hi = 'पानी से खेलना शांत करता है। 💧', body_hi = 'एक छोटे टब में पानी भरकर उसमें प्लास्टिक के बर्तन डाल दीजिए। पानी से खेलना बच्चों को ऊर्जा निकालने और शांत होने में मदद करता है।', title_id = 'Bermain air itu menenangkan. 💧', body_id = 'Isi baskom kecil dengan air dan masukkan beberapa wadah plastik. Bermain air membantu anak menyalurkan energi dan merasa rileks.', title_ja = '水遊びで心が落ち着きます 💧', body_ja = '小さなたらいに水を入れて、プラスチックの容器を浮かべてみましょう。水遊びはエネルギーを発散させ、リラックスさせてくれます。', title_ko = '물놀이는 마음을 진정시켜요. 💧', body_ko = '작은 대야에 물을 채우고 플라스틱 그릇을 넣어 주세요. 물놀이는 아이가 에너지를 발산하고 긴장을 푸는 데 도움이 돼요.', title_nl = 'Spelen met water werkt rustgevend. 💧', body_nl = 'Doe water in een kleine teil en gooi er plastic bakjes in. Spelen met water helpt kinderen hun energie kwijt te raken en te ontspannen.', title_pl = 'Zabawa wodą uspokaja. 💧', body_pl = 'Nalej wody do małej miski i wrzuć do niej plastikowe pojemniki. Zabawa wodą pomaga dzieciom wyładować energię i się zrelaksować.', title_pt = 'Brincar com água acalma. 💧', body_pt = 'Encha um alguidar pequeno com água e ponha lá dentro recipientes de plástico. Brincar com água ajuda as crianças a gastar energia e a relaxar.', title_sv = 'Vattenlek lugnar. 💧', body_sv = 'Fyll en liten balja med vatten och lägg i plastburkar. Vattenlek hjälper barn att få ut energi och slappna av.', title_vi = 'Chơi với nước giúp bé bình tĩnh. 💧', body_vi = 'Đổ nước vào một chậu nhỏ và thả vào vài chiếc hộp nhựa. Chơi với nước giúp trẻ giải tỏa năng lượng và thư giãn.', title_zh = '玩水能让人平静 💧', body_zh = '在小盆里装些水，放几个塑料碗进去。玩水能帮孩子释放精力、放松下来。' WHERE id = '8be96289-58a8-4a48-89ec-c4ba0488e973' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Haz tus preguntas importantes, como «¿Cómo gestionar la crisis del año?», a nuestro asistente Anacan AI incluso de madrugada y recibe consejo experto.', body_fr = 'Posez vos questions importantes, comme « Comment gérer la crise de 1 an ? », à notre assistant Anacan AI, même la nuit, et recevez des conseils d''expert.', body_hi = '''1 साल के संकट को कैसे संभालें?'' जैसे ज़रूरी सवाल रात में भी हमारे Anacan AI असिस्टेंट से पूछिए और विशेषज्ञ सलाह पाइए।', body_id = 'Punya pertanyaan penting seperti "Bagaimana menghadapi krisis usia 1 tahun?" Bahkan di malam hari, tanyakan ke asisten Anacan AI kami dan dapatkan saran ahli.', body_ja = '「1歳のかんしゃく、どう対応したらいい？」といった大切な質問は、夜中でもAnacan AIアシスタントに聞いて、専門的なアドバイスをもらいましょう。', body_ko = '''1살 떼쓰기는 어떻게 다뤄야 할까?'' 같은 중요한 질문은 늦은 밤에도 Anacan AI 도우미에게 물어 전문가 조언을 받아 보세요.', body_nl = 'Stel je belangrijke vragen, zoals: hoe ga ik om met de 1-jaarscrisis?, zelfs midden in de nacht aan onze assistent Anacan AI en krijg deskundig advies.', body_pl = 'Masz ważne pytania, np. „Jak poradzić sobie z kryzysem roczniaka?”? Nawet w nocy zapytaj naszego asystenta Anacan AI i otrzymaj radę eksperta.', body_pt = 'Faça as suas perguntas importantes, como "Como lidar com a crise de 1 ano?", mesmo de madrugada ao nosso assistente Anacan AI e receba conselhos de especialista.', body_sv = 'Ställ dina viktiga frågor, som ”Hur hanterar man 1-årskrisen?”, till vår assistent Anacan AI även sent på natten och få expertråd.', body_vi = 'Những câu hỏi quan trọng như "Làm sao vượt qua khủng hoảng 1 tuổi?", ngay cả lúc nửa đêm mẹ cũng có thể hỏi trợ lý Anacan AI và nhận lời khuyên chuyên gia.', body_zh = '像“1岁危机该怎么应对？”这样的重要问题，哪怕深夜也可以问我们的Anacan AI助手，获得专家建议。' WHERE id = 'a70fb0ff-98b0-4735-ac10-846168dd5d60' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Tu pequeño ayudante! 🧹', body_es = '¿Te imita y coge un trapo para quitar el polvo? No olvides añadir en vídeo estos momentos tan tiernos al Álbum del bebé para el futuro.', title_fr = 'Votre petit assistant ! 🧹', body_fr = 'Il vous imite en prenant un chiffon pour essayer d''épousseter ? Ajoutez absolument ces moments adorables et éducatifs en vidéo à l''Album de bébé pour plus tard.', title_hi = 'आपका नन्हा मददगार! 🧹', body_hi = 'आपकी नकल करते हुए हाथ में कपड़ा लेकर धूल पोंछने की कोशिश करता है? इन प्यारे और सिखाने वाले पलों को भविष्य के लिए वीडियो के रूप में बेबी एल्बम में ज़रूर जोड़िए।', title_id = 'Asisten kecil Anda! 🧹', body_id = 'Ia meniru Anda, mengambil lap, dan mencoba membersihkan debu? Pastikan menyimpan momen manis dan edukatif ini sebagai video di Album Bayi untuk kenangan nanti.', title_ja = '小さなお手伝いさん！🧹', body_ja = 'あなたのまねをして、ふきんを持ってほこりを拭こうとしていますか？このかわいくて学びのある瞬間を、ぜひ動画で「ベビーアルバム」に残しましょう。', title_ko = '작은 도우미! 🧹', body_ko = '엄마를 따라 수건을 들고 먼지를 닦으려 하나요? 이 귀엽고 배움 가득한 순간을 영상으로 아기 앨범에 꼭 남겨 두세요.', title_nl = 'Je kleine hulpje! 🧹', body_nl = 'Doet je kindje je na en probeert hij met een doekje af te stoffen? Zet deze lieve, leerzame momenten zeker als video in het Babyalbum voor later.', title_pl = 'Twój mały pomocnik! 🧹', body_pl = 'Naśladuje cię, bierze ściereczkę i próbuje ścierać kurze? Koniecznie dodaj te słodkie i pouczające chwile jako filmik do Albumu dziecka na pamiątkę.', title_pt = 'O seu pequeno ajudante! 🧹', body_pt = 'Imita-a e pega num pano para limpar o pó? Não deixe de adicionar estes momentos doces e educativos em vídeo ao Álbum do Bebé, para o futuro.', title_sv = 'Din lilla hjälpreda! 🧹', body_sv = 'Härmar barnet dig, tar en trasa och försöker damma? Lägg till dessa söta och lärorika stunder som video i Babyalbumet för framtiden.', title_vi = 'Người phụ giúp nhỏ của mẹ! 🧹', body_vi = 'Bé bắt chước mẹ cầm khăn lau bụi? Mẹ nhớ quay video những khoảnh khắc đáng yêu và bổ ích này và thêm vào Album của bé để làm kỷ niệm nhé.', title_zh = '你的小帮手！🧹', body_zh = '宝宝学你的样子拿起抹布擦灰？一定要把这些可爱又有教育意义的瞬间录成视频，存进宝宝相册留作纪念。' WHERE id = '2a991705-4255-4931-9ad5-cef8eb9bf0dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma con música 🎶', body_es = 'Por la noche, en lugar de juegos movidos, poned música relajante: a él le preparará para dormir y a ti te dará paz.', title_fr = 'Le calme en musique. 🎶', body_fr = 'Le soir, au lieu des jeux agités, écoutez des musiques apaisantes pour le préparer au sommeil et vous préparer à la sérénité.', title_hi = 'संगीत से सुकून। 🎶', body_hi = 'शाम को भाग-दौड़ वाले खेलों के बजाय शांत करने वाला संगीत सुनिए, ताकि वह नींद के लिए और आप सुकून के लिए तैयार हो सकें।', title_id = 'Tenang bersama musik. 🎶', body_id = 'Di malam hari, ganti permainan yang aktif dengan musik yang menenangkan untuk menyiapkannya tidur dan menyiapkan diri Anda untuk beristirahat.', title_ja = '音楽で心穏やかに 🎶', body_ja = '夕方は活発な遊びの代わりに、落ち着いた音楽を聴いて、お子さんは眠りへ、あなたは安らぎへと準備しましょう。', title_ko = '음악으로 찾는 평온. 🎶', body_ko = '저녁에는 활발한 놀이 대신 차분한 음악을 들으며 아이는 잠을, 엄마는 휴식을 준비해 보세요.', title_nl = 'Rust met muziek. 🎶', body_nl = 'Laat ''s avonds in plaats van drukke spelletjes rustgevende muziek horen, zo bereid je je kindje voor op de slaap en jezelf op rust.', title_pl = 'Spokój z muzyką. 🎶', body_pl = 'Wieczorem zamiast ruchliwych zabaw puśćcie kojącą muzykę, by przygotować go do snu, a siebie do odpoczynku.', title_pt = 'Tranquilidade com música. 🎶', body_pt = 'Ao fim do dia, em vez de brincadeiras agitadas, ouçam música calmante: prepare-o para dormir e a si própria para a tranquilidade.', title_sv = 'Lugn med musik. 🎶', body_sv = 'Lyssna på lugnande musik i stället för livliga lekar på kvällen och förbered barnet för sömn och dig själv för ro.', title_vi = 'Thư thái cùng âm nhạc. 🎶', body_vi = 'Buổi tối, thay vì trò chơi vận động, hãy nghe nhạc êm dịu để chuẩn bị cho bé đi ngủ và cho mẹ được thư thái.', title_zh = '用音乐静下来 🎶', body_zh = '傍晚别玩太激烈的游戏，听些舒缓的音乐，让宝宝准备入睡，也让自己平静下来。' WHERE id = '813ebcca-fa4c-42de-926c-6ca1c1526de6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Selectivo con la comida 🍲', body_es = 'Si rechaza ciertos alimentos, no te preocupes. Vuelve a ofrecérselos otro día y de otra forma (por ejemplo, como finger food en lugar de puré).', title_fr = 'Un mangeur difficile. 🍲', body_fr = 'S''il refuse certains aliments, ne vous inquiétez pas. Proposez-les à nouveau d''autres jours et sous d''autres formes (par exemple en morceaux à attraper plutôt qu''en purée).', title_hi = 'खाने में नखरे। 🍲', body_hi = 'अगर वह कुछ खाने मना करता है, तो चिंता मत कीजिए। अलग-अलग दिनों में अलग रूप में (जैसे प्यूरी नहीं, फ़िंगर फ़ूड की तरह) फिर से दीजिए।', title_id = 'Pilih-pilih makanan. 🍲', body_id = 'Kalau ia menolak makanan tertentu, jangan khawatir. Tawarkan lagi di hari lain dalam bentuk berbeda (misalnya finger food, bukan puree).', title_ja = '食べ物の好き嫌い 🍲', body_ja = '特定の食べ物を嫌がっても心配いりません。日を変えて、違う形で（たとえばピューレではなく手づかみ食べで）もう一度すすめてみましょう。', title_ko = '가리는 음식이 생겼어요. 🍲', body_ko = '어떤 음식을 거부해도 걱정하지 마세요. 다른 날, 다른 형태로(예: 퓌레 대신 핑거푸드로) 다시 권해 보세요.', title_nl = 'Kieskeurig eten. 🍲', body_nl = 'Weigert je kindje bepaalde voeding? Geen zorgen. Bied het op andere dagen in een andere vorm opnieuw aan (bijvoorbeeld als vingervoedsel in plaats van een hapje).', title_pl = 'Wybiórczość w jedzeniu. 🍲', body_pl = 'Jeśli odrzuca niektóre produkty, nie martw się. Proponuj je ponownie w różne dni i w różnej formie (np. nie jako przecier, tylko do jedzenia rączką).', title_pt = 'Esquisitice à mesa. 🍲', body_pt = 'Se recusa certos alimentos, não se preocupe. Volte a oferecê-los noutros dias e de outras formas (por exemplo, como finger food em vez de puré).', title_sv = 'Kräsen med maten. 🍲', body_sv = 'Oroa dig inte om barnet vägrar viss mat. Erbjud den igen andra dagar i andra former (till exempel som fingermat i stället för puré).', title_vi = 'Kén ăn. 🍲', body_vi = 'Nếu bé từ chối một số món, mẹ đừng lo. Hãy cho bé thử lại vào những ngày khác dưới dạng khác (ví dụ, món cầm tay thay vì món nghiền).', title_zh = '挑食 🍲', body_zh = '宝宝拒绝某些食物也别担心。换个日子、换种形式（比如不做成泥，而是做成手指食物）再试试。' WHERE id = 'ce071e13-068a-4c5a-8d4c-437e6f25658d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Las torres crecen! 🧱', body_es = 'Ya sabe apilar 3-4 cubos. Aplaude y apoya este juego que exige concentración y coordinación ojo-mano.', title_fr = 'Les tours s''élèvent ! 🧱', body_fr = 'Il sait déjà empiler 3-4 cubes. Encouragez par vos applaudissements ce jeu qui demande de la concentration et de la coordination œil-main.', title_hi = 'मीनारें ऊँची हो रही हैं! 🧱', body_hi = 'अब वह 3-4 ब्लॉक एक के ऊपर एक रख लेता है। ध्यान और आँख-हाथ के तालमेल वाले इस खेल में तालियाँ बजाकर उसका हौसला बढ़ाइए।', title_id = 'Menaranya makin tinggi! 🧱', body_id = 'Kini ia sudah bisa menumpuk 3-4 balok. Dukung permainan yang butuh fokus dan koordinasi mata-tangan ini dengan tepuk tangan.', title_ja = 'タワーが高くなる！🧱', body_ja = 'もう積み木を3-4個重ねられます。集中力と目と手の協調が必要なこの遊びを、拍手で応援してあげましょう。', title_ko = '탑이 높아져요! 🧱', body_ko = '이제 블록 3-4개를 쌓을 수 있어요. 집중력과 눈과 손의 협응력이 필요한 이 놀이를 박수로 응원해 주세요.', title_nl = 'Torens bouwen! 🧱', body_nl = 'Je kindje kan nu 3-4 blokken op elkaar zetten. Moedig dit spel, dat concentratie en oog-handcoördinatie vraagt, aan met applaus.', title_pl = 'Wieże rosną! 🧱', body_pl = 'Potrafi już ustawić 3-4 klocki jeden na drugim. Wspieraj oklaskami tę zabawę, która wymaga skupienia i koordynacji wzrokowo-ruchowej.', title_pt = 'As torres estão a crescer! 🧱', body_pt = 'Já consegue empilhar 3-4 cubos. Apoie com aplausos esta brincadeira que exige atenção e coordenação olho-mão.', title_sv = 'Tornen växer! 🧱', body_sv = 'Nu kan barnet stapla 3-4 klossar. Applådera och stötta den här leken som kräver fokus och öga-hand-koordination.', title_vi = 'Tòa tháp vươn cao! 🧱', body_vi = 'Bé đã biết chồng 3-4 khối lên nhau. Hãy vỗ tay khích lệ trò chơi đòi hỏi sự tập trung và phối hợp tay mắt này nhé.', title_zh = '高塔建起来啦！🧱', body_zh = '宝宝已经能把3-4块积木摞起来了。为这个需要专注力和手眼协调的游戏鼓鼓掌，支持他吧。' WHERE id = '502b8118-151f-47c7-9476-eb53fa55cfd0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de socializar 👶', body_es = '¿Observa con atención a otros niños en el parque? Aunque aún no jueguen juntos, el juego en paralelo es el primer gran paso de la socialización.', title_fr = 'L''heure de se sociabiliser. 👶', body_fr = 'Au parc, il observe attentivement les autres enfants ? Même s''ils ne jouent pas encore ensemble, le jeu côte à côte (jeu parallèle) est le premier grand pas vers la sociabilisation.', title_hi = 'मेलजोल का समय। 👶', body_hi = 'पार्क में दूसरे बच्चों को ध्यान से देखता है? भले अभी वे साथ न खेलें, साथ-साथ खेलने (पैरेलल प्ले) का दौर मेलजोल का पहला बड़ा कदम है।', title_id = 'Waktunya bersosialisasi. 👶', body_id = 'Ia memperhatikan anak-anak lain di taman dengan saksama? Meski belum bermain bersama, masa bermain berdampingan (parallel play) adalah langkah besar pertama dalam bersosialisasi.', title_ja = 'ほかの子とふれあう時間 👶', body_ja = '公園でほかの子をじっと見ていますか？まだ一緒には遊ばなくても、そばで並んで遊ぶ「平行遊び」は社会性の大きな第一歩です。', title_ko = '사회성을 키울 시간. 👶', body_ko = '공원에서 다른 아이들을 유심히 지켜보나요? 아직 함께 놀지는 않아도, 나란히 노는 시기(병행 놀이)는 사회성의 첫 큰 걸음이에요.', title_nl = 'Tijd om te socialiseren. 👶', body_nl = 'Kijkt je kindje in het park aandachtig naar andere kinderen? Ook al spelen ze nog niet samen, naast elkaar spelen (parallel spel) is de eerste grote stap in de sociale ontwikkeling.', title_pl = 'Czas na kontakty z innymi. 👶', body_pl = 'W parku uważnie obserwuje inne dzieci? Choć jeszcze nie bawią się razem, zabawa obok siebie (zabawa równoległa) to pierwszy duży krok w socjalizacji.', title_pt = 'Hora de socializar. 👶', body_pt = 'Observa com atenção as outras crianças no parque? Mesmo que ainda não brinquem juntas, a fase da brincadeira lado a lado (brincadeira paralela) é o primeiro grande passo na socialização.', title_sv = 'Dags att umgås. 👶', body_sv = 'Följer barnet de andra barnen noga i parken? Även om de inte leker tillsammans än är parallellek det första stora steget i den sociala utvecklingen.', title_vi = 'Giờ giao lưu. 👶', body_vi = 'Bé chăm chú quan sát các bạn ở công viên? Dù chưa chơi cùng nhau, giai đoạn chơi song song là bước tiến lớn đầu tiên của kỹ năng xã hội.', title_zh = '社交时间 👶', body_zh = '在公园里专心看着其他小朋友？虽然还不会一起玩，但并排玩耍（平行游戏）阶段是社交的第一大步。' WHERE id = 'af470a51-532a-4658-877a-26e61845210a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡400 días de emoción! 🌟', body_es = '¡Mañana es el gran día 400! ¡Más de 1 año y 1 mes! Crea un pequeño ambiente de fiesta en casa y libera memoria en el móvil.', title_fr = '400 jours d''émotions ! 🌟', body_fr = 'Demain, c''est le grand 400e jour ! Plus de 1 an et 1 mois ! Créez une petite ambiance de fête à la maison et libérez de la mémoire sur votre téléphone.', title_hi = '400 दिनों का रोमांच! 🌟', body_hi = 'कल बड़ा, चार सौवाँ दिन है! 1 साल 1 महीने से भी ज़्यादा! घर में छोटे से जश्न का माहौल बनाइए और फ़ोन की मेमोरी खाली कीजिए।', title_id = 'Serunya 400 hari! 🌟', body_id = 'Besok hari besar, hari ke-400! Lebih dari 1 tahun 1 bulan! Ciptakan suasana pesta kecil di rumah dan kosongkan memori ponsel Anda.', title_ja = 'わくわくの400日！🌟', body_ja = '明日は大切な400日目！1歳1か月を過ぎました！家の中を小さなお祝いムードにして、スマホの容量も空けておきましょう。', title_ko = '400일의 설렘! 🌟', body_ko = '내일은 큰 날, 400일째예요! 1살 1개월이 넘었어요! 집 안에 작은 축제 분위기를 만들고 휴대폰 저장 공간을 비워 두세요.', title_nl = '400 dagen spanning! 🌟', body_nl = 'Morgen is de grote 400e dag! Meer dan 1 jaar en 1 maand! Zorg thuis voor een feestelijke sfeer en maak ruimte vrij op je telefoon.', title_pl = '400 dni emocji! 🌟', body_pl = 'Jutro wielki, czterechsetny dzień! Ponad 1 rok i 1 miesiąc! Stwórz w domu odrobinę świątecznej atmosfery i zwolnij pamięć w telefonie.', title_pt = '400 dias de emoção! 🌟', body_pt = 'Amanhã é o grande dia 400! Mais de 1 ano e 1 mês! Crie em casa um pequeno ambiente de festa e liberte memória no telemóvel.', title_sv = '400 dagars spänning! 🌟', body_sv = 'I morgon är det den stora 400:e dagen! Mer än 1 år och 1 månad! Skapa lite feststämning hemma och rensa telefonens minne.', title_vi = '400 ngày háo hức! 🌟', body_vi = 'Ngày mai là ngày thứ 400 trọng đại! Hơn 1 tuổi 1 tháng rồi! Hãy tạo không khí lễ hội nho nhỏ trong nhà và dọn dẹp bộ nhớ điện thoại nhé.', title_zh = '400天的兴奋！🌟', body_zh = '明天就是第400天这个大日子！比1岁1个月还多！在家营造一点小小的节日气氛，清理一下手机内存吧。' WHERE id = '53cb1b60-78f0-41c1-a42e-b48a4324533b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una noche para perdonarte 📝', body_es = '¿Hoy todo te ha molestado? Cuando se duerma, escribe cómo te sientes en el Diario de ánimo. Mañana será un día nuevo y mejor.', title_fr = 'Un soir pour se pardonner 📝', body_fr = 'Tout vous a agacée aujourd''hui ? Quand il dort, écrivez vos ressentis dans le Journal d''humeur. Demain sera un nouveau jour, plus beau.', title_hi = 'खुद को माफ़ करने की रात 📝', body_hi = 'आज हर बात पर चिढ़ हुई? बच्चा सो जाए तो मूड डायरी में अपनी भावनाएँ लिखिए। कल एक नया और बेहतर दिन होगा।', title_id = 'Malam untuk memaafkan diri 📝', body_id = 'Hari ini semuanya bikin kesal? Saat si kecil tidur, tulis perasaan Anda di Buku Harian Suasana Hati. Besok akan jadi hari baru yang lebih indah.', title_ja = '自分を許す夜 📝', body_ja = '今日はなんだかイライラしましたか？お子さんが寝たら「気分日記」に気持ちを書き出しましょう。明日はまた新しい、すてきな一日になります。', title_ko = '나를 용서하는 밤 📝', body_ko = '오늘 모든 게 짜증 났나요? 아이가 잠들면 기분 일기에 감정을 적어 보세요. 내일은 새롭고 더 좋은 하루가 될 거예요.', title_nl = 'Een avond om jezelf te vergeven 📝', body_nl = 'Ergerde je je vandaag aan alles? Schrijf je gevoelens op in je Stemmingsdagboek als je kindje slaapt. Morgen wordt een nieuwe, mooiere dag.', title_pl = 'Wieczór wybaczania sobie 📝', body_pl = 'Wszystko cię dziś irytowało? Gdy maluszek zaśnie, zapisz swoje uczucia w Dzienniku nastroju. Jutro będzie nowy, piękniejszy dzień.', title_pt = 'Uma noite para se perdoar 📝', body_pt = 'Hoje tudo a irritou? Quando ele adormecer, escreva o que sente no Diário de Humor. Amanhã será um dia novo e mais bonito.', title_sv = 'En kväll för att förlåta dig själv 📝', body_sv = 'Har allt irriterat dig i dag? Skriv dina känslor i Humördagboken när barnet sover. I morgon blir en ny och finare dag.', title_vi = 'Đêm tha thứ cho bản thân 📝', body_vi = 'Hôm nay chuyện gì cũng khiến mẹ bực mình? Khi bé ngủ, hãy viết cảm xúc vào Nhật ký tâm trạng. Ngày mai sẽ là một ngày mới tươi đẹp hơn.', title_zh = '原谅自己的夜晚 📝', body_zh = '今天什么都让你心烦？宝宝睡着后，把感受写进心情日记。明天会是崭新又更美好的一天。' WHERE id = 'fab52013-4ea8-458f-b397-01341fb91dad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡400 días increíbles! 🎉', body_es = '¡Enhorabuena! ¡Lleváis exactamente 400 días recorriendo juntos este camino tan intenso! ¡Celebra ya este día tan especial!', title_fr = '400 jours formidables ! 🎉', body_fr = 'Félicitations ! Cela fait 400 jours pile que vous avancez ensemble sur ce chemin mouvementé ! Fêtez vite ce jour spécial !', title_hi = 'शानदार 400 दिन! 🎉', body_hi = 'बधाई हो! आप पूरे 400 दिनों से यह तूफ़ानी सफ़र साथ-साथ तय कर रहे हैं! इस खास दिन को तुरंत धूमधाम से मनाइए!', title_id = '400 hari yang luar biasa! 🎉', body_id = 'Selamat! Sudah tepat 400 hari kalian menapaki perjalanan penuh badai ini bersama! Segera rayakan hari istimewa ini!', title_ja = 'すばらしい400日！🎉', body_ja = 'おめでとうございます！ちょうど400日間、このにぎやかな道のりを一緒に歩んできました！さっそくこの特別な日をお祝いしましょう！', title_ko = '멋진 400일! 🎉', body_ko = '축하해요! 꼬박 400일 동안 이 폭풍 같은 길을 함께 걸어왔어요! 지금 바로 이 특별한 날을 축하하세요!', title_nl = 'Geweldige 400 dagen! 🎉', body_nl = 'Gefeliciteerd! Al precies 400 dagen lopen jullie samen deze stormachtige weg! Vier deze bijzondere dag meteen!', title_pl = 'Wspaniałe 400 dni! 🎉', body_pl = 'Gratulacje! Już równo 400 dni idziecie razem tą burzliwą drogą! Od razu uczcijcie ten wyjątkowy dzień!', title_pt = 'Uns fantásticos 400 dias! 🎉', body_pt = 'Parabéns! Há exatamente 400 dias que percorrem juntos este caminho agitado! Celebre já este dia especial!', title_sv = 'Fantastiska 400 dagar! 🎉', body_sv = 'Grattis! Ni har vandrat den här stormiga vägen tillsammans i exakt 400 dagar! Fira den här speciella dagen direkt!', title_vi = '400 ngày tuyệt vời! 🎉', body_vi = 'Chúc mừng! Cả nhà đã cùng nhau đi qua chặng đường đầy sóng gió này tròn 400 ngày! Hãy ăn mừng ngày đặc biệt này ngay nhé!', title_zh = '了不起的400天！🎉', body_zh = '恭喜！你们已经携手走过这段风风雨雨的路整整400天了！快来庆祝这个特别的日子吧！' WHERE id = '165064a6-acf5-4848-b342-4a3782635921' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue comiendo solo 🥄', body_es = 'Aunque se ponga perdido, deja que intente comer con su propia cuchara. Así desarrolla la confianza en sí mismo y la coordinación muscular.', title_fr = 'On continue à manger seul. 🥄', body_fr = 'Même s''il se salit, laissez-le essayer de manger avec sa propre cuillère. Cela développe sa confiance en lui et sa coordination musculaire.', title_hi = 'खुद खाना जारी रखें। 🥄', body_hi = 'भले कपड़े गंदे हो जाएँ, उसे अपने चम्मच से खाने की कोशिश करने दीजिए। इससे उसका आत्मविश्वास और मांसपेशियों का तालमेल विकसित होता है।', title_id = 'Terus makan sendiri. 🥄', body_id = 'Meski bajunya kotor, biarkan ia mencoba makan dengan sendoknya sendiri. Ini mengembangkan rasa percaya diri dan koordinasi ototnya.', title_ja = '自分で食べる練習を続けよう 🥄', body_ja = '服が汚れても、自分のスプーンで食べさせてあげましょう。自信と筋肉の協調が育ちます。', title_ko = '혼자 먹기는 계속돼요. 🥄', body_ko = '온몸이 엉망이 되더라도 자기 숟가락으로 먹어 보게 해 주세요. 자신감과 근육 협응력이 자라요.', title_nl = 'Blijf zelf laten eten. 🥄', body_nl = 'Ook al wordt hij er vies van, laat hem met zijn eigen lepel proberen te eten. Dat versterkt zijn zelfvertrouwen en zijn spiercoördinatie.', title_pl = 'Dalej je samodzielnie. 🥄', body_pl = 'Nawet jeśli cały się ubrudzi, pozwól mu jeść własną łyżeczką. To rozwija jego pewność siebie i koordynację mięśni.', title_pt = 'Continue a deixá-lo comer sozinho. 🥄', body_pt = 'Mesmo que fique todo sujo, deixe-o tentar comer com a própria colher. Isso desenvolve a autoconfiança e a coordenação muscular.', title_sv = 'Fortsätt äta själv. 🥄', body_sv = 'Även om barnet blir kladdigt, låt det försöka äta med sin egen sked. Det stärker självförtroendet och muskelkoordinationen.', title_vi = 'Tiếp tục tự ăn. 🥄', body_vi = 'Dù lem luốc khắp người, hãy để bé tự ăn bằng thìa của mình. Điều này giúp bé tự tin hơn và phát triển khả năng phối hợp cơ bắp.', title_zh = '继续自己吃饭 🥄', body_zh = '就算吃得满身都是，也让宝宝用自己的勺子吃吧。这能培养他的自信心和肌肉协调能力。' WHERE id = '894151c3-97b8-419f-9602-aa08da619716' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres la mejor! ✨', body_es = 'La entrega que has demostrado durante 400 días no tiene precio. Ahora respira hondo, recuéstate y descansa tranquila.', title_fr = 'Vous êtes la meilleure ! ✨', body_fr = 'Le dévouement dont vous avez fait preuve pendant ces 400 jours n''a pas de prix. Maintenant, respirez profondément, installez-vous confortablement et reposez-vous au calme.', title_hi = 'आप सबसे अच्छी हैं! ✨', body_hi = '400 दिनों में आपका दिखाया समर्पण अनमोल है। अब गहरी साँस लीजिए, पीछे टिककर बैठिए और शांति से आराम कीजिए।', title_id = 'Anda yang terbaik! ✨', body_id = 'Pengorbanan Anda selama 400 hari ini tak ternilai. Sekarang tarik napas dalam-dalam, bersandarlah, dan beristirahat dengan tenang.', title_ja = 'あなたは最高です！✨', body_ja = 'この400日間のあなたの献身は、何ものにも代えられません。さあ、深呼吸して、背もたれに寄りかかり、ゆっくり休みましょう。', title_ko = '엄마가 최고예요! ✨', body_ko = '400일 동안 보여 준 헌신은 그 무엇과도 바꿀 수 없어요. 이제 깊게 숨을 쉬고, 기대어 앉아 편히 쉬세요.', title_nl = 'Je bent de beste! ✨', body_nl = 'Je toewijding in deze 400 dagen is onbetaalbaar. Haal nu diep adem, leun achterover en rust rustig uit.', title_pl = 'Jesteś najlepsza! ✨', body_pl = 'Twoje poświęcenie przez te 400 dni jest bezcenne. Teraz weź głęboki oddech, odchyl się i spokojnie odpocznij.', title_pt = 'É a melhor! ✨', body_pt = 'A dedicação que mostrou ao longo de 400 dias não tem preço. Agora respire fundo, recoste-se e descanse com calma.', title_sv = 'Du är bäst! ✨', body_sv = 'Uppoffringarna du har gjort under 400 dagar är ovärderliga. Ta nu ett djupt andetag, luta dig tillbaka och vila i lugn och ro.', title_vi = 'Mẹ là tuyệt nhất! ✨', body_vi = 'Sự hy sinh của mẹ suốt 400 ngày qua là vô giá. Giờ hãy hít một hơi thật sâu, ngả lưng và thư giãn nhé.', title_zh = '你是最棒的！✨', body_zh = '这400天里你的付出无可替代。现在深吸一口气，往后靠一靠，安静地休息一下吧。' WHERE id = '8c8e0b49-c38c-485a-b336-5facb1258a02' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Más allá de cuatro paredes ⛅', body_es = '¿No puede gastar energía en casa y está quejica? La naturaleza es el mejor calmante. Consulta Tiempo y ropa, elige la ropa adecuada y vete directa al parque.', title_fr = 'Sortir de la maison ⛅', body_fr = 'Il n''arrive pas à se défouler à la maison et pleurniche ? La nature est le meilleur des calmants. Consultez Météo et tenue, choisissez la bonne tenue et filez au parc.', title_hi = 'चार दीवारों से बाहर ⛅', body_hi = 'बच्चा घर में ऊर्जा नहीं निकाल पा रहा और चिड़चिड़ा है? प्रकृति सबसे अच्छी शांति देती है। मौसम और कपड़े देखिए, सही कपड़े चुनिए और तुरंत पार्क चलिए।', title_id = 'Keluar dari empat dinding ⛅', body_id = 'Ia tidak bisa menyalurkan energinya di rumah dan jadi rewel? Alam adalah penenang terbaik. Cek Cuaca dan Pakaian, pilih pakaian yang tepat, dan segera pergi ke taman.', title_ja = 'お家の外へ ⛅', body_ja = '家の中でエネルギーを発散できず、ぐずっていますか？自然はいちばんの癒やしです。「天気と服装」を見てぴったりのコーデを選び、すぐに公園へ出かけましょう。', title_ko = '네 벽 밖으로 ⛅', body_ko = '집에서 에너지를 다 쓰지 못해 칭얼대나요? 자연이 최고의 진정제예요. 날씨와 옷차림을 확인하고 알맞은 옷을 골라 바로 공원으로 향하세요.', title_nl = 'Weg uit de vier muren ⛅', body_nl = 'Kan je kindje zijn energie binnen niet kwijt en is hij zeurderig? De natuur kalmeert het best. Kijk in Weer en kleding, kies de juiste outfit en ga meteen naar het park.', title_pl = 'Poza cztery ściany ⛅', body_pl = 'Maluch nie może w domu wyładować energii i marudzi? Natura najlepiej uspokaja. Sprawdź Pogodę i ubiór, wybierz odpowiedni zestaw i od razu ruszajcie do parku.', title_pt = 'Para lá das quatro paredes ⛅', body_pt = 'Em casa não consegue gastar energia e anda rabugento? A natureza é o melhor calmante. Veja o Tempo e Roupa, escolha a combinação certa e siga já para o parque.', title_sv = 'Ut ur de fyra väggarna ⛅', body_sv = 'Kan barnet inte få ut energin hemma och gnäller? Naturen är det bästa lugnande medlet. Kolla Väder och kläder, välj rätt klädsel och gå direkt till parken.', title_vi = 'Ra khỏi bốn bức tường ⛅', body_vi = 'Ở nhà bé không xả được năng lượng nên quấy khóc? Thiên nhiên là liều thuốc an thần tốt nhất. Hãy xem Thời tiết và trang phục, chọn bộ đồ phù hợp và ra công viên ngay.', title_zh = '走出四面墙 ⛅', body_zh = '宝宝在家释放不了精力，哼哼唧唧？大自然是最好的安抚。看看天气穿衣，选好合适的搭配，马上去公园吧。' WHERE id = '05dbf09b-2a49-4886-a4e4-6f85e7cbea42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de jugar con papá 👨‍👧', body_es = 'Tienes las piernas destrozadas de correr detrás de él todo el día. Ahora toca el Modo pareja. Que papá se encargue de las volteretas en el suelo y los caballitos. Tú descansa.', title_fr = 'L''heure de jeu avec papa 👨‍👧', body_fr = 'À force de lui courir après toute la journée, vous n''avez plus de jambes. C''est l''heure du mode Partenaire. Laissez papa s''occuper des roulades par terre et des jeux de cheval. Vous, reposez-vous.', title_hi = 'पापा का खेल का समय 👨‍👧', body_hi = 'पूरे दिन उसके पीछे भागते-भागते आपके पैर जवाब दे गए हैं। अब पार्टनर मोड का समय है। ज़मीन पर लोटने और घोड़ा बनने वाले खेल पापा संभालें। आप आराम कीजिए।', title_id = 'Waktu bermain ayah 👨‍👧', body_id = 'Kaki Anda pegal setelah mengejarnya seharian. Sekarang waktunya Mode Pasangan. Biar ayah yang mengurus permainan guling-guling dan kuda-kudaan. Anda beristirahatlah.', title_ja = 'パパの遊び時間 👨‍👧', body_ja = '一日中追いかけて、足がくたくたですね。今こそ「パートナーモード」の出番です。床でごろごろ、お馬さんごっこはパパに任せて、あなたは休みましょう。', title_ko = '아빠의 놀이 시간 👨‍👧', body_ko = '하루 종일 쫓아다니느라 다리가 후들거리죠. 이제 파트너 모드 시간이에요. 바닥에서 뒹굴기, 말 타기 놀이는 아빠에게 맡기세요. 엄마는 쉬세요.', title_nl = 'Speeltijd met papa 👨‍👧', body_nl = 'Je benen zijn op van de hele dag achter je kindje aanrennen. Nu is het tijd voor de Partnermodus. Laat papa over de vloer rollen en paardje rijden. Jij rust uit.', title_pl = 'Czas zabawy z tatą 👨‍👧', body_pl = 'Po całym dniu biegania za maluchem nogi odmawiają ci posłuszeństwa. Teraz czas na tryb Partnera. Niech turlanie się po podłodze i zabawę w konika przejmie tata. Ty odpocznij.', title_pt = 'A hora de brincar do pai 👨‍👧', body_pt = 'De correr o dia todo atrás dele, já não sente as pernas. Agora é a vez do Modo Parceiro. Deixe as cambalhotas no chão e os cavalinhos por conta do pai. Descanse.', title_sv = 'Pappas lektid 👨‍👧', body_sv = 'Benen värker av att springa efter barnet hela dagen. Nu är det dags för Partnerläget. Låt pappa sköta rullandet på golvet och rida-ranka-lekarna. Vila du.', title_vi = 'Giờ chơi của bố 👨‍👧', body_vi = 'Chạy theo bé cả ngày làm chân mẹ rã rời. Giờ là lúc dùng Chế độ đối tác. Hãy để bố lo những trò lăn lộn dưới sàn, cưỡi ngựa. Mẹ cứ nghỉ ngơi.', title_zh = '爸爸的游戏时间 👨‍👧', body_zh = '追着宝宝跑了一整天，腿都要断了。现在是伴侣模式时间。在地上打滚、骑大马这些游戏就交给爸爸吧。你好好休息。' WHERE id = '3cf4affc-53f5-4c77-84f1-006d5732e36a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maratón de habitación en habitación 🏃‍♂️', body_es = 'Ya no le basta con andar: ¡ahora corre de una habitación a otra! Su equilibrio de pie se está consolidando. Registra este gran logro motor en el Seguimiento del desarrollo.', title_fr = 'Marathon de pièce en pièce 🏃‍♂️', body_fr = 'Marcher ne lui suffit plus, il court déjà d''une pièce à l''autre ! Son équilibre debout se met en place. Notez cette grande victoire motrice dans le Suivi de développement.', title_hi = 'कमरों के बीच मैराथन 🏃‍♂️', body_hi = 'चलना उसके लिए काफ़ी नहीं, अब एक कमरे से दूसरे कमरे तक दौड़ शुरू हो गई है! पैरों पर संतुलन पूरी तरह बन रहा है। ग्रोथ ट्रैकर में मोटर स्किल्स की इस बड़ी जीत को दर्ज कीजिए।', title_id = 'Maraton antarkamar 🏃‍♂️', body_id = 'Berjalan saja tidak cukup, kini ia berlari dari kamar ke kamar! Keseimbangannya saat berdiri makin matang. Catat kemenangan motorik besar ini di Pelacak Perkembangan.', title_ja = '部屋から部屋へマラソン 🏃‍♂️', body_ja = '歩くだけでは物足りず、部屋から部屋へ走り回り始めました！立ったときのバランスもしっかりしてきています。「発達トラッカー」にこの大きな運動の成果を記録しましょう。', title_ko = '방에서 방으로 마라톤 🏃‍♂️', body_ko = '걷는 것만으로는 부족해서 이제 방에서 방으로 뛰어다녀요! 서 있는 균형이 완전히 잡혀 가고 있어요. 성장 기록에 이 큰 운동 발달의 승리를 남기세요.', title_nl = 'Marathon door de kamers 🏃‍♂️', body_nl = 'Lopen is niet meer genoeg, je kindje rent al van kamer naar kamer! Zijn evenwicht op twee benen is bijna helemaal ontwikkeld. Noteer deze grote motorische overwinning in de Groeitracker.', title_pl = 'Maraton między pokojami 🏃‍♂️', body_pl = 'Chodzenie mu nie wystarcza, zaczęło się bieganie z pokoju do pokoju! Równowaga na nóżkach w pełni się kształtuje. Zapisz ten wielki sukces motoryczny w Śledzeniu rozwoju.', title_pt = 'Maratona entre divisões 🏃‍♂️', body_pt = 'Andar já não lhe chega, agora corre de divisão em divisão! O equilíbrio de pé está a ficar completo. Registe esta grande vitória motora no Registo de Desenvolvimento.', title_sv = 'Maraton mellan rummen 🏃‍♂️', body_sv = 'Det räcker inte längre att gå, nu springer barnet från rum till rum! Balansen på fötterna formas helt. Anteckna denna stora motoriska seger i Utvecklingsspåraren.', title_vi = 'Chạy marathon giữa các phòng 🏃‍♂️', body_vi = 'Đi thôi chưa đủ, bé đã bắt đầu chạy từ phòng này sang phòng khác! Khả năng giữ thăng bằng khi đứng đang hoàn thiện. Hãy ghi lại chiến thắng vận động lớn này trong Theo dõi phát triển.', title_zh = '房间之间的马拉松 🏃‍♂️', body_zh = '走路已经满足不了宝宝了，开始在房间之间跑来跑去！站立平衡已经完全形成。在发育追踪里记下这个大动作的胜利吧。' WHERE id = 'f1269e86-21d6-4d2f-83e1-31926957408a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño dictador del menú 🥣', body_es = '¿Hoy aparta la comida que ayer le encantaba? Ser selectivo con la comida es normal después del año. Sin agobiarte, busca alternativas distintas en Recetas saludables.', title_fr = 'Le petit dictateur du menu 🥣', body_fr = 'Il repousse aujourd''hui le plat qu''il adorait hier ? Être difficile à table est normal après 1 an. Sans paniquer, cherchez d''autres idées dans les Recettes saines.', title_hi = 'मेन्यू का तानाशाह 🥣', body_hi = 'कल का पसंदीदा खाना आज दूर सरका देता है? 1 साल के बाद खाने में नखरे सामान्य हैं। घबराए बिना सेहतमंद रेसिपी में अलग विकल्प ढूँढिए।', title_id = 'Diktator menu 🥣', body_id = 'Makanan favoritnya kemarin, hari ini ia singkirkan? Pilih-pilih makanan setelah usia 1 tahun itu normal. Jangan panik, cari alternatif lain di Resep Sehat.', title_ja = '小さなメニュー決定権者 🥣', body_ja = '昨日大好きだった料理を、今日は押しのけていますか？1歳を過ぎての好き嫌いはよくあることです。慌てずに「ヘルシーレシピ」で別のメニューを探してみましょう。', title_ko = '메뉴 독재자 🥣', body_ko = '어제 좋아하던 음식을 오늘은 밀어내나요? 1살 이후 음식을 가리는 건 정상이에요. 당황하지 말고 건강한 레시피에서 다른 대안을 찾아보세요.', title_nl = 'Kleine menudictator 🥣', body_nl = 'Duwt je kindje vandaag weg wat hij gisteren nog lekker vond? Kieskeurig eten is normaal na 1 jaar. Raak niet in paniek en zoek andere opties in Gezonde recepten.', title_pl = 'Mały dyktator menu 🥣', body_pl = 'Odpycha dziś jedzenie, które wczoraj uwielbiał? Wybiórczość w jedzeniu po roczku to norma. Bez paniki poszukaj innych propozycji w zdrowych przepisach.', title_pt = 'O ditador da ementa 🥣', body_pt = 'Hoje afasta a comida de que ontem gostava? Ser esquisito com a comida depois de 1 ano é normal. Sem entrar em pânico, procure alternativas nas Receitas Saudáveis.', title_sv = 'Menydiktatorn 🥣', body_sv = 'Skjuter barnet bort gårdagens favoritmat i dag? Kräsenhet med maten är normalt efter 1 år. Få inte panik, leta efter andra alternativ i Hälsosamma recept.', title_vi = '"Nhà độc tài" thực đơn 🥣', body_vi = 'Món hôm qua bé thích, hôm nay lại đẩy ra? Kén ăn sau 1 tuổi là chuyện bình thường. Đừng hoảng, hãy tìm những lựa chọn khác trong Công thức lành mạnh nhé.', title_zh = '菜单小独裁者 🥣', body_zh = '昨天还爱吃的东西，今天就推到一边？1岁后挑食很正常。别慌，去健康食谱里找找其他替代选择吧。' WHERE id = '7df527b0-7bf7-42d6-b9f4-0f231186e70c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¿Qué es esto?» ☝️', body_es = 'Lo señala todo con el dedo y hace un sonido especial. Te está pidiendo que le pongas nombre al mundo. Dile con paciencia el nombre de cada cosa que señale.', title_fr = 'La période du « C''est quoi ? » ☝️', body_fr = 'Il montre tout du doigt en faisant un petit son bien à lui. Il vous demande de nommer le monde. Dites-lui patiemment le nom de chaque objet qu''il montre.', title_hi = '''यह क्या है?'' का दौर ☝️', body_hi = 'हर चीज़ की ओर उँगली दिखाकर खास आवाज़ निकालता है। वह चाहता है कि आप उसे दुनिया की चीज़ों के नाम बताएँ। जो भी चीज़ वह दिखाए, धैर्य से उसका नाम बताइए।', title_id = 'Masa "Ini apa?" ☝️', body_id = 'Ia menunjuk segala hal dengan jarinya sambil mengeluarkan suara khusus. Ia ingin Anda menyebutkan nama dunia di sekitarnya. Sebutkan dengan sabar nama setiap benda yang ia tunjuk.', title_ja = '「これなあに？」の時期 ☝️', body_ja = 'なんでも指さして、特別な声を出していますか？世界のものに名前をつけてほしいのです。指さしたものの名前を、根気よく教えてあげましょう。', title_ko = '"이게 뭐야?" 시기 ☝️', body_ko = '모든 걸 손가락으로 가리키며 특별한 소리를 내요. 세상의 이름을 알려 달라는 거예요. 가리키는 물건마다 인내심을 갖고 이름을 말해 주세요.', title_nl = 'De wat-is-dat-fase ☝️', body_nl = 'Je kindje wijst alles aan en maakt er een speciaal geluidje bij. Hij vraagt je de wereld te benoemen. Zeg geduldig de naam van alles wat hij aanwijst.', title_pl = 'Etap „Co to jest?” ☝️', body_pl = 'Pokazuje wszystko paluszkiem i wydaje przy tym szczególny dźwięk. Prosi cię, byś nazwała mu świat. Cierpliwie mów mu nazwę każdej rzeczy, którą pokazuje.', title_pt = 'A fase do "O que é isto?" ☝️', body_pt = 'Aponta para tudo com o dedo e faz um som especial. Está a pedir-lhe que dê nome ao mundo. Diga-lhe com paciência o nome de cada objeto que aponta.', title_sv = 'Fasen ”Vad är det?” ☝️', body_sv = 'Barnet pekar på allt och gör ett särskilt ljud. Det vill att du sätter namn på världen. Säg med tålamod namnet på varje sak barnet pekar på.', title_vi = 'Giai đoạn "Cái gì đây?" ☝️', body_vi = 'Bé chỉ tay vào mọi thứ và phát ra âm thanh đặc biệt. Bé đang muốn mẹ gọi tên thế giới xung quanh. Hãy kiên nhẫn nói cho bé tên của từng đồ vật bé chỉ.', title_zh = '“这是什么？”阶段 ☝️', body_zh = '宝宝用手指指着各种东西，还发出特别的声音。他是想让你告诉他世界万物的名字。耐心地告诉他指到的每样东西叫什么吧。' WHERE id = '85bb394b-b9a2-4a30-a34a-98479663ff2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta la culpa 📝', body_es = '«Hoy le he leído poco», «Ha visto demasiada pantalla»... ¡Silencia esas voces! Haces todo lo que puedes. Escríbete una nota cariñosa en el Diario de ánimo.', title_fr = 'Laissez la culpabilité de côté 📝', body_fr = '« Je lui ai peu lu aujourd''hui », « Il a trop regardé les écrans »... Faites taire ces voix ! Vous faites de votre mieux. Écrivez-vous un mot bienveillant dans le Journal d''humeur.', title_hi = 'अपराध-बोध छोड़िए 📝', body_hi = '''आज उसे कम किताबें पढ़ाईं'', ''स्क्रीन ज़्यादा देखी''... इन आवाज़ों को चुप कराइए! आप अपनी पूरी कोशिश कर रही हैं। मूड डायरी में खुद के लिए एक नरम सा नोट लिखिए।', title_id = 'Lepaskan rasa bersalah 📝', body_id = '"Hari ini aku kurang membacakan buku", "Ia terlalu lama menonton layar"... Diamkan suara-suara itu! Anda sudah berusaha sebaik mungkin. Tulis catatan penuh kasih untuk diri sendiri di Buku Harian Suasana Hati.', title_ja = '罪悪感は手放して 📝', body_ja = '「今日は絵本をあまり読んであげられなかった」「画面を見せすぎた」…そんな声は止めましょう！あなたはできる限りのことをしています。「気分日記」に自分へのやさしいメモを書きましょう。', title_ko = '죄책감은 내려놓으세요 📝', body_ko = '''오늘 책을 별로 못 읽어 줬어'', ''화면을 너무 많이 봤어''... 이런 목소리는 꺼 두세요! 엄마는 최선을 다하고 있어요. 기분 일기에 나를 다독이는 한 줄을 적어 보세요.', title_nl = 'Laat je schuldgevoel los 📝', body_nl = 'Vandaag heb ik te weinig voorgelezen, hij heeft te veel naar een scherm gekeken... Zet die stemmen uit! Je doet je best. Schrijf een liefdevol briefje aan jezelf in je Stemmingsdagboek.', title_pl = 'Porzuć poczucie winy 📝', body_pl = '„Dziś przeczytałam mu za mało książek”, „Za dużo patrzył w ekran”... Ucisz te głosy! Robisz, co możesz. Zapisz w Dzienniku nastroju życzliwą notkę dla siebie.', title_pt = 'Liberte-se da culpa 📝', body_pt = '"Hoje li-lhe poucos livros", "Viu demasiado ecrã"... Cale essas vozes! Está a fazer o melhor que pode. Escreva no Diário de Humor uma nota carinhosa para si própria.', title_sv = 'Släpp skuldkänslorna 📝', body_sv = '”I dag läste jag för lite”, ”Barnet tittade för mycket på skärm”... Tysta de rösterna! Du gör ditt bästa. Skriv en snäll anteckning till dig själv i Humördagboken.', title_vi = 'Buông bỏ cảm giác tội lỗi 📝', body_vi = '"Hôm nay mình đọc ít sách cho con quá", "Con xem màn hình nhiều quá"... Hãy tắt những tiếng nói ấy đi! Mẹ đang làm hết sức mình. Hãy viết một dòng thật bao dung với bản thân vào Nhật ký tâm trạng.', title_zh = '放下内疚感 📝', body_zh = '“今天给他读的书太少”“他看了太多屏幕”……让这些声音安静下来！你已经尽力了。在心情日记里给自己写一句温柔的话吧。' WHERE id = 'f78a5d11-ba9f-41e9-8557-2840d12964be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paso a una sola siesta 🥱', body_es = '¿No quiere dormir la siesta de la mañana y se ha descolocado todo el horario? ¡Está creciendo! Puede que esté pasando de dos siestas a una. Ajusta la rutina poco a poco.', title_fr = 'Le passage à une seule sieste 🥱', body_fr = 'Il refuse la sieste du matin et tout le planning est chamboulé ? Il grandit ! C''est peut-être le passage de deux siestes à une seule. Réajustez son rythme petit à petit.', title_hi = 'एक झपकी पर आना 🥱', body_hi = 'सुबह की झपकी नहीं लेना चाहता और पूरा शेड्यूल उलट-पुलट हो गया? वह बड़ा हो रहा है! दिन की दो झपकियों से एक पर आने का दौर हो सकता है। रूटीन को धीरे-धीरे नए सिरे से ढालिए।', title_id = 'Peralihan ke satu kali tidur siang 🥱', body_id = 'Ia tidak mau tidur pagi dan seluruh jadwal jadi kacau? Ia sedang tumbuh! Mungkin ini masa peralihan dari dua kali ke satu kali tidur siang. Atur ulang rutinitasnya perlahan-lahan.', title_ja = 'お昼寝1回への移行 🥱', body_ja = '朝寝を嫌がって、スケジュールがすっかり乱れていますか？成長している証拠です！お昼寝が2回から1回に移る時期かもしれません。少しずつ生活リズムを整え直しましょう。', title_ko = '낮잠 한 번으로 전환 🥱', body_ko = '오전 낮잠을 거부하고 일정이 엉망이 됐나요? 아이가 자라고 있는 거예요! 낮잠이 두 번에서 한 번으로 바뀌는 시기일 수 있어요. 루틴을 천천히 다시 맞춰 주세요.', title_nl = 'Overgang naar één dutje 🥱', body_nl = 'Wil je kindje ''s ochtends niet slapen en ligt het hele schema overhoop? Hij wordt groter! Misschien gaat hij van twee dutjes naar één. Pas de routine rustig opnieuw aan.', title_pl = 'Przejście na jedną drzemkę 🥱', body_pl = 'Nie chce iść na poranną drzemkę i cały plan dnia się sypie? On rośnie! To może być okres przejścia z dwóch drzemek na jedną. Powoli dostosuj rutynę.', title_pt = 'A passagem para uma só sesta 🥱', body_pt = 'Não quer fazer a sesta da manhã e o horário ficou todo trocado? Está a crescer! Pode ser a fase de passar de duas sestas para uma. Reajuste a rotina aos poucos.', title_sv = 'Övergång till en tupplur 🥱', body_sv = 'Vill barnet inte sova på förmiddagen och har hela schemat ställts på ända? Barnet växer! Det kan vara dags att gå från två tupplurar till en. Justera rutinen sakta.', title_vi = 'Chuyển sang một giấc ngủ ngày 🥱', body_vi = 'Bé không chịu ngủ buổi sáng và mọi lịch trình đảo lộn? Bé đang lớn! Có thể đây là giai đoạn chuyển từ hai giấc ngủ ngày sang một giấc. Hãy điều chỉnh lại nếp sinh hoạt từ từ.', title_zh = '过渡到一次小睡 🥱', body_zh = '宝宝不想睡上午觉，整个作息都乱了？他在长大！可能正处在白天从两次小睡过渡到一次的阶段。慢慢重新调整作息吧。' WHERE id = '1167974e-3206-4f0f-b4e8-4d14f35444b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La habitación mágica 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial sobre un héroe valiente que descubre el mundo. Haz más fácil la hora de dormir con este cuento tan dulce.', title_fr = 'La chambre magique 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire unique sur un héros courageux qui découvre le monde. Facilitez le passage à la nuit avec ce joli conte.', title_hi = 'जादुई कमरा 🪄', body_hi = 'स्मार्ट कहानियों में दुनिया खोजने वाले एक बहादुर हीरो की खास कहानी बनाइए। इस प्यारी कहानी से रात की ओर बढ़ना आसान बनाइए।', title_id = 'Kamar ajaib 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa tentang pahlawan pemberani yang menjelajahi dunia. Permudah peralihan ke malam dengan dongeng manis ini.', title_ja = '魔法のお部屋 🪄', body_ja = '「スマートおはなし」で、勇敢なヒーローが世界を探検する特別なお話をつくりましょう。このかわいいお話で、夜への切りかえをスムーズに。', title_ko = '마법 같은 방 🪄', body_ko = '스마트 동화에서 용감한 주인공이 세상을 탐험하는 특별한 이야기를 만들어 보세요. 이 달콤한 동화로 밤으로 가는 길을 편하게 해 주세요.', title_nl = 'De toverkamer 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal over een dappere held die de wereld ontdekt. Maak de overgang naar de nacht makkelijker met dit lieve sprookje.', title_pl = 'Magiczny pokój 🪄', body_pl = 'W Mądrych bajkach stwórz wyjątkową historię o odważnym bohaterze, który odkrywa świat. Ułatw przejście do nocy tą słodką bajką.', title_pt = 'O quarto mágico 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial sobre um herói corajoso a descobrir o mundo. Facilite a passagem para a noite com este conto doce.', title_sv = 'Det magiska rummet 🪄', body_sv = 'Skapa en egen berättelse i Smarta sagor om en modig hjälte som upptäcker världen. Gör övergången till natten lättare med den här söta sagan.', title_vi = 'Căn phòng kỳ diệu 🪄', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo một câu chuyện riêng về người hùng dũng cảm khám phá thế giới. Hãy để câu chuyện ngọt ngào này giúp bé vào giấc dễ dàng hơn.', title_zh = '魔法房间 🪄', body_zh = '在智能故事里创作一个勇敢小英雄探索世界的专属故事。用这个温馨的故事，让入夜过渡更轻松。' WHERE id = '8017b10d-4bdb-4fe5-8a0b-20ae132c6ec2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cansada de ver siempre las mismas paredes? Descubre en Lugares para mamás una cafetería con zona de juegos infantil. Que juegue mientras tú disfrutas del café.', body_fr = 'Regarder toujours les mêmes murs vous a épuisée. Trouvez dans les Lieux adaptés aux mamans un café avec un coin jeux. Il joue, vous savourez votre café.', body_hi = 'घर की वही दीवारें देखकर आप थक गई हैं। माँ के लिए अनुकूल जगहों में बच्चों के खेलने के कोने वाला कोई कैफ़े खोजिए। वह खेले, और आप कॉफ़ी का मज़ा लीजिए।', body_id = 'Bosan menatap dinding rumah yang sama? Temukan kafe dengan area bermain anak di Tempat Ramah Ibu. Biar ia bermain, dan Anda menikmati kopi.', body_ja = '家の同じ壁ばかり見て疲れていませんか？「ママにやさしいスポット」でキッズスペースのあるカフェを見つけましょう。お子さんは遊び、あなたはコーヒーを楽しんで。', body_ko = '집 안의 똑같은 벽만 보느라 지쳤나요? 엄마 친화 장소에서 키즈 놀이 공간이 있는 카페를 찾아보세요. 아이는 놀고, 엄마는 커피를 즐기세요.', body_nl = 'Ben je het zat om naar dezelfde muren te kijken? Ontdek in Mamavriendelijke plekken een café met speelhoek. Laat je kindje spelen en geniet jij van je koffie.', body_pl = 'Masz dość patrzenia na te same ściany w domu? Odkryj w Miejscach przyjaznych mamom kawiarnię z kącikiem zabaw dla dzieci. Niech on się bawi, a ty delektuj się kawą.', body_pt = 'Olhar para as mesmas paredes de casa esgotou-a. Descubra nos Locais Amigos das Mães um café com espaço de brincar para crianças. Ele brinca, e a mãe saboreia o café.', body_sv = 'Har du tröttnat på att titta på samma väggar hemma? Hitta ett kafé med lekhörna i Mammavänliga platser. Låt barnet leka medan du njuter av kaffet.', body_vi = 'Nhìn mãi những bức tường quen thuộc khiến mẹ kiệt sức. Hãy khám phá một quán cà phê có góc vui chơi cho trẻ trong Địa điểm thân thiện với mẹ. Bé chơi, còn mẹ thưởng thức cà phê.', body_zh = '天天对着家里同样的墙壁，你已经累坏了。从妈妈友好场所里找一家有儿童游乐区的咖啡馆。宝宝玩，你好好享受咖啡。' WHERE id = 'c7ad498c-1a79-4b6f-a5e5-0ac0b264682c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pone a prueba los límites 🛑', body_es = '¿Aunque le dices que no, te mira a los ojos y vuelve a alargar la mano hacia ese objeto? No es terquedad, solo está probando los límites. Sé paciente y coherente.', title_fr = 'Il teste les limites. 🛑', body_fr = 'Malgré votre « non », il vous regarde droit dans les yeux et tend encore la main vers l''objet ? Ce n''est pas de l''entêtement, il teste simplement les limites. Restez patiente et cohérente.', title_hi = 'सीमाएँ परख रहा है। 🛑', body_hi = 'आपके ''नहीं'' कहने के बावजूद आपकी आँखों में देखकर फिर उसी चीज़ की ओर हाथ बढ़ाता है? यह ज़िद नहीं, बस सीमाएँ समझने का टेस्ट है। धैर्य रखिए और एक जैसा व्यवहार रखिए।', title_id = 'Menguji batas. 🛑', body_id = 'Meski Anda sudah bilang tidak, ia menatap mata Anda lalu tetap meraih benda itu? Ini bukan keras kepala, ia hanya sedang menguji batas. Tetaplah sabar dan konsisten.', title_ja = '境界線を試しています 🛑', body_ja = '「ダメ」と言ったのに、あなたの目をじっと見ながら、またそれに手を伸ばしますか？これは反抗ではなく、ルールを学ぶためのテストです。根気よく、一貫した対応を。', title_ko = '한계를 시험하고 있어요. 🛑', body_ko = '"안 돼"라고 해도 엄마 눈을 바라보며 또 그 물건에 손을 뻗나요? 고집이 아니라 한계를 배우는 시험이에요. 인내심을 갖고 일관되게 대해 주세요.', title_nl = 'Grenzen aftasten. 🛑', body_nl = 'Je zegt nee, maar je kindje kijkt je recht aan en grijpt toch naar dat ding? Dat is geen koppigheid, maar een test om grenzen te leren kennen. Blijf geduldig en consequent.', title_pl = 'Sprawdza granice. 🛑', body_pl = 'Mimo twojego „nie” patrzy ci w oczy i znów sięga po tę rzecz? To nie upór, tylko test, w którym poznaje granice. Bądź cierpliwa i konsekwentna.', title_pt = 'Está a testar os limites. 🛑', body_pt = 'Mesmo depois de dizer que não, olha-a nos olhos e volta a esticar a mão para aquele objeto? Não é teimosia, é só um teste para aprender os limites. Seja paciente e coerente.', title_sv = 'Testar gränserna. 🛑', body_sv = 'Trots att du sagt nej tittar barnet dig i ögonen och sträcker sig ändå efter saken? Det är inte trots, bara ett test för att lära sig gränserna. Var tålmodig och konsekvent.', title_vi = 'Bé thử giới hạn. 🛑', body_vi = 'Dù mẹ đã nói "không", bé vẫn nhìn thẳng vào mắt mẹ và với lấy món đồ đó? Đây không phải bướng bỉnh mà chỉ là bé đang thử tìm hiểu giới hạn. Hãy kiên nhẫn và nhất quán.', title_zh = '在试探边界 🛑', body_zh = '你说了“不行”，宝宝却看着你的眼睛，还是伸手去拿那样东西？这不是倔强，只是在测试边界。保持耐心，前后一致。' WHERE id = 'd29d33a4-aed4-4635-9f37-3a7a39a378b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares nocturnos 😴', body_es = 'Los dientes o un estirón pueden alterar el sueño. Si hace falta, sigue el Temporizador de sueño y anota los cambios en su rutina.', title_fr = 'Les réveils nocturnes. 😴', body_fr = 'Les dents ou un pic de croissance peuvent perturber le sommeil. Si besoin, notez les changements de rythme en suivant le minuteur de sommeil.', title_hi = 'रात में जागना। 😴', body_hi = 'दाँत निकलना या विकास की छलांग नींद बिगाड़ सकती है। ज़रूरत हो तो स्लीप टाइमर देखकर रूटीन में आए बदलाव दर्ज कीजिए।', title_id = 'Terbangun di malam hari. 😴', body_id = 'Tumbuh gigi atau lonjakan pertumbuhan bisa mengganggu tidurnya. Bila perlu, catat perubahan rutinitasnya dengan memantau Timer Tidur.', title_ja = '夜中に起きる 😴', body_ja = '歯の生え始めや成長期は、睡眠を乱すことがあります。必要に応じて睡眠タイマーで、生活リズムの変化を記録しましょう。', title_ko = '밤에 깨요. 😴', body_ko = '이가 나거나 성장 급등기가 오면 잠이 흐트러질 수 있어요. 필요하면 수면 타이머로 일과의 변화를 기록하세요.', title_nl = '''s Nachts wakker worden. 😴', body_nl = 'Doorkomende tandjes of een groeisprong kunnen de slaap verstoren. Houd zo nodig met de Slaaptimer de veranderingen in het ritme bij.', title_pl = 'Nocne pobudki. 😴', body_pl = 'Ząbkowanie lub skok rozwojowy mogą zaburzyć sen. W razie potrzeby śledź timer snu i zapisuj zmiany w rytmie dnia.', title_pt = 'Despertares noturnos. 😴', body_pt = 'Os dentes ou um pico de crescimento podem perturbar o sono. Se for preciso, acompanhe o temporizador de sono e registe as mudanças na rotina.', title_sv = 'Nattliga uppvaknanden. 😴', body_sv = 'Tandsprickning eller ett tillväxtsprång kan störa sömnen. Följ vid behov sömntimern och anteckna förändringar i rutinen.', title_vi = 'Thức giấc ban đêm. 😴', body_vi = 'Mọc răng hay giai đoạn tăng trưởng vọt có thể làm xáo trộn giấc ngủ. Khi cần, hãy theo dõi Bộ hẹn giờ ngủ và ghi lại những thay đổi trong nếp sinh hoạt.', title_zh = '夜醒 😴', body_zh = '出牙或生长飞跃期可能会打乱睡眠。需要时用睡眠计时器记录作息的变化吧。' WHERE id = 'f3355fe9-0c3b-41e2-9043-0a5cb8a61740' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Turnaos sin falta en los despertares nocturnos. A veces, en la oscuridad, solo las caricias rítmicas y el olor de papá le calman al instante.', body_fr = 'Pour les réveils nocturnes, relayez-vous absolument. Parfois, dans le noir, seules les caresses rythmées et l''odeur de papa l''apaisent aussitôt.', body_hi = 'रात में जागने पर बारी-बारी से ज़रूर उठिए। कभी-कभी अँधेरे में सिर्फ़ पापा का लयबद्ध सहलाना और उनकी खुशबू ही बच्चे को तुरंत शांत कर देती है।', body_id = 'Saat ia terbangun malam, pastikan bergantian. Kadang di tengah gelap, hanya usapan berirama dan aroma ayah yang langsung menenangkannya.', body_ja = '夜中に起きたら、必ず交代で対応しましょう。暗い中では、パパのリズミカルなトントンと匂いで、すぐに落ち着くこともあります。', body_ko = '밤에 깰 때는 꼭 번갈아 일어나세요. 어둠 속에서는 아빠의 리듬감 있는 토닥임과 냄새만으로 아이가 금세 진정되기도 해요.', body_nl = 'Wissel ''s nachts zeker af met opstaan. Soms kalmeert alleen papa''s ritmische geaai en geur je kindje meteen in het donker.', body_pl = 'Przy nocnych pobudkach koniecznie się zmieniajcie. Czasem w ciemności tylko rytmiczne głaskanie i zapach taty od razu uspokajają dziecko.', body_pt = 'Revezem-se sem falta nos despertares noturnos. Às vezes, no escuro, só as carícias ritmadas e o cheiro do pai acalmam a criança num instante.', body_sv = 'Turas alltid om vid nattliga uppvaknanden. Ibland är det bara pappas rytmiska smekningar och doft i mörkret som lugnar barnet direkt.', body_vi = 'Hãy thay phiên nhau khi bé thức giấc ban đêm. Đôi khi trong bóng tối, chỉ cái vỗ về nhịp nhàng và mùi hương của bố mới khiến bé dịu ngay.', body_zh = '夜醒时一定要轮流起来。有时候在黑暗中，只有爸爸有节奏的轻抚和他的气味能让宝宝立刻安静下来。' WHERE id = '2e0b0129-5a3d-466c-a35f-ef4707dea065' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un espejo que imita a los mayores 🧹', body_es = 'Mientras limpias, coge un trapo e intenta hacer lo mismo. ¡Es tu pequeña copia! Dale algo inofensivo y hazle participar en las tareas de casa.', title_fr = 'Le petit miroir des grands 🧹', body_fr = 'Quand vous nettoyez, il prend un chiffon et essaie de faire pareil. C''est votre mini-vous ! Donnez-lui un objet sans danger et faites-le participer aux tâches de la maison.', title_hi = 'बड़ों की नकल करने वाला आईना 🧹', body_hi = 'आप घर साफ़ करती हैं तो वह भी हाथ में कपड़ा लेकर वैसा ही करने की कोशिश करता है। वह आपकी छोटी सी परछाईं है! उसके हाथ में कोई सुरक्षित चीज़ देकर उसे घर के कामों में शामिल कीजिए।', title_id = 'Cermin yang meniru orang dewasa 🧹', body_id = 'Saat Anda bersih-bersih, ia juga mengambil kain dan mencoba melakukan hal yang sama. Ia adalah versi kecil Anda! Berikan benda yang aman dan ajak ia ikut bekerja di rumah.', title_ja = '大人のまねっこ 🧹', body_ja = 'あなたが掃除をしていると、布を持って同じことをしようとしますか？あなたのミニチュア版ですね！安全なものを渡して、家事に参加させてあげましょう。', title_ko = '어른을 따라 하는 거울 🧹', body_ko = '엄마가 집을 닦으면 아이도 걸레를 들고 똑같이 하려 해요. 엄마의 작은 복사판이에요! 안전한 물건을 쥐여 주고 집안일에 함께하게 해 주세요.', title_nl = 'Een spiegel die volwassenen nadoet 🧹', body_nl = 'Jij maakt schoon en je kindje pakt ook een doekje om hetzelfde te doen. Hij is jouw kleine kopie! Geef hem iets onschuldigs en laat hem meehelpen in huis.', title_pl = 'Lusterko, które naśladuje dorosłych 🧹', body_pl = 'Gdy sprzątasz, on też bierze ściereczkę i próbuje robić to samo. To twoja mała kopia! Daj mu bezpieczny przedmiot i włącz go w prace domowe.', title_pt = 'Um espelho que imita os adultos 🧹', body_pt = 'Enquanto limpa a casa, ele pega num pano e tenta fazer o mesmo. É a sua pequena cópia! Dê-lhe um objeto inofensivo e inclua-o nas tarefas da casa.', title_sv = 'En spegel som härmar de vuxna 🧹', body_sv = 'När du torkar av hemma tar barnet också en trasa och försöker göra likadant. Barnet är din lilla kopia! Ge något ofarligt och låt barnet vara med i hushållssysslorna.', title_vi = 'Tấm gương nhỏ bắt chước người lớn 🧹', body_vi = 'Khi mẹ lau nhà, bé cũng cầm khăn làm theo. Bé là phiên bản nhỏ của mẹ đấy! Hãy đưa cho bé một món đồ an toàn và để bé cùng làm việc nhà.', title_zh = '模仿大人的小镜子 🧹', body_zh = '你擦地时，宝宝也拿块布学着做。他就是你的小翻版！给他一件安全的东西，让他也参与家务吧。' WHERE id = '812159bf-a0a9-4bf9-8e7b-97d82abbaa80' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Contra los olvidos 🛒', body_es = '¿Te ha vuelto a fallar la memoria? Apunta al momento en la Lista de la compra cada cosita que se acabe en casa y que tu pareja la compre al volver del trabajo.', title_fr = 'Contre les oublis 🛒', body_fr = 'Votre mémoire vous a encore joué un tour ? Ajoutez tout de suite à la Liste de courses chaque petite chose qui manque à la maison, votre conjoint l''achètera en rentrant du travail.', title_hi = 'भूलने की आदत से जंग 🛒', body_hi = 'याददाश्त ने फिर धोखा दिया? घर में खत्म होने वाली हर छोटी चीज़ तुरंत शॉपिंग लिस्ट में डालिए, ताकि आपके साथी काम से लौटते समय ले आएँ।', title_id = 'Melawan lupa 🛒', body_id = 'Ingatan Anda menipu lagi? Langsung masukkan setiap barang kecil yang habis ke Daftar Belanja, biar pasangan Anda membelinya saat pulang kerja.', title_ja = 'もの忘れ対策 🛒', body_ja = 'また忘れてしまいましたか？家で切れた細かいものは、すぐに「買い物リスト」に入れて、パートナーに仕事帰りに買ってきてもらいましょう。', title_ko = '건망증과의 싸움 🛒', body_ko = '기억력이 또 깜빡했나요? 집에 떨어진 자잘한 것은 바로 쇼핑 목록에 넣어 두세요. 배우자가 퇴근길에 사 올 거예요.', title_nl = 'Strijd tegen vergeetachtigheid 🛒', body_nl = 'Liet je geheugen je weer in de steek? Zet alles wat thuis op raakt meteen op het Boodschappenlijstje, dan neemt je partner het mee op weg naar huis.', title_pl = 'Walka z zapominalstwem 🛒', body_pl = 'Pamięć znów cię zawiodła? Każdą drobnostkę, która skończyła się w domu, od razu dodaj do Listy zakupów, a partner kupi ją w drodze z pracy.', title_pt = 'Combater os esquecimentos 🛒', body_pt = 'A memória voltou a pregar-lhe uma partida? Ponha logo na Lista de Compras cada coisinha que acaba em casa, e o seu companheiro compra-a no regresso do trabalho.', title_sv = 'Kampen mot glömskan 🛒', body_sv = 'Har minnet svikit dig igen? Lägg direkt varje liten sak som tagit slut hemma i Inköpslistan, så kan din partner handla på vägen hem från jobbet.', title_vi = 'Chiến đấu với chứng hay quên 🛒', body_vi = 'Trí nhớ lại đánh lừa mẹ? Hễ thứ gì trong nhà sắp hết, hãy thêm ngay vào Danh sách mua sắm để bố mua trên đường đi làm về.', title_zh = '对抗健忘 🛒', body_zh = '记性又跟你开玩笑了？家里用完的任何小东西，马上丢进购物清单，让另一半下班路上买回来。' WHERE id = '9510e83b-c10c-4166-b921-d1cd3c8f203c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Mete los juguetes en una caja y luego la vacía entera? Está entendiendo la lógica de «dentro» y «fuera». Observa en silencio estos intentos repetidos.', body_fr = 'Il met ses jouets dans une boîte, puis la vide entièrement ? Il comprend la logique du dedans et du dehors. Observez en silence ses essais répétés.', body_hi = 'डिब्बे में खिलौने डालकर फिर सब बाहर निकाल देता है? वह ''अंदर'' और ''बाहर'' का तर्क समझ रहा है। उसकी इन बार-बार की कोशिशों को चुपचाप देखिए।', body_id = 'Ia memasukkan mainan ke dalam kotak, lalu mengeluarkan semuanya lagi? Ia sedang memahami konsep "di dalam" dan "di luar". Perhatikan diam-diam usahanya yang berulang ini.', body_ja = '箱におもちゃを入れては、全部出していますか？「中」と「外」の仕組みを理解しようとしています。この繰り返しの挑戦をそっと見守りましょう。', body_ko = '상자에 장난감을 넣었다가 다시 다 쏟아 내나요? 안과 밖의 개념을 이해하고 있어요. 반복하는 시도를 조용히 지켜봐 주세요.', body_nl = 'Gooit je kindje speelgoed in een doos en haalt hij alles er weer uit? Hij begrijpt de logica van erin en eruit. Kijk stil toe bij zijn herhaalde pogingen.', body_pl = 'Wrzuca zabawki do pudełka, a potem wszystko wysypuje? Poznaje logikę „w środku” i „na zewnątrz”. Po cichu obserwuj te powtarzane próby.', body_pt = 'Põe os brinquedos dentro da caixa e depois esvazia-a toda? Está a compreender a lógica de "dentro" e "fora". Observe em silêncio estas tentativas repetidas.', body_sv = 'Lägger barnet leksakerna i lådan och tömmer sedan ut allt igen? Barnet förstår logiken med i och ut. Följ dessa upprepade försök i tysthet.', body_vi = 'Bé bỏ đồ chơi vào hộp rồi lại đổ hết ra? Bé đang hiểu logic "trong" và "ngoài". Hãy lặng lẽ quan sát những lần thử lặp đi lặp lại này.', body_zh = '把玩具扔进盒子，再全部倒出来？宝宝在理解“里面”和“外面”的逻辑。静静地看着他一遍遍尝试吧。' WHERE id = '0a5f0553-0fcd-480d-a18f-a3ecfcfe950c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la rutina de la noche 🛀', body_es = 'Un baño templado siempre funciona. No te saltes nunca la rutina de la noche: le indica a su cerebro con total precisión que ya es hora de dormir.', title_fr = 'La force du rituel du soir 🛀', body_fr = 'Un bain tiède marche toujours. Ne sautez jamais le rituel du soir : il envoie à son cerveau un signal très précis, « c''est l''heure de dormir ».', title_hi = 'शाम के रूटीन की ताकत 🛀', body_hi = 'गुनगुना स्नान हमेशा काम करता है। शाम का रूटीन कभी मत तोड़िए, क्योंकि यह उसके दिमाग को ठीक-ठीक संकेत देता है कि ''अब सोने का समय है''।', title_id = 'Kekuatan rutinitas malam 🛀', body_id = 'Mandi air hangat selalu berhasil. Jangan pernah melewatkan rutinitas malam, karena ini memberi sinyal yang sangat jelas ke otaknya bahwa sekarang waktunya tidur.', title_ja = '夜の習慣の力 🛀', body_ja = 'ぬるめのお風呂はいつも効果的。夜の習慣は崩さないようにしましょう。脳に「もう寝る時間だよ」という合図をしっかり送ってくれます。', title_ko = '저녁 루틴의 힘 🛀', body_ko = '따뜻한 목욕은 언제나 효과가 있어요. 저녁 루틴은 절대 깨지 마세요. ''이제 잘 시간이야''라는 신호를 뇌에 정확히 보내 주니까요.', title_nl = 'De kracht van de avondroutine 🛀', body_nl = 'Een lauw badje werkt altijd. Sla de avondroutine nooit over, want die geeft zijn hersentjes precies het signaal: nu is het slaaptijd.', title_pl = 'Siła wieczornej rutyny 🛀', body_pl = 'Ciepła kąpiel zawsze działa. Nigdy nie przerywaj wieczornej rutyny, bo bardzo precyzyjnie daje jego mózgowi sygnał: „teraz pora spać”.', title_pt = 'A força da rotina da noite 🛀', body_pt = 'Um banho morno resulta sempre. Nunca quebre a rotina da noite, porque é ela que dá ao cérebro dele, com toda a precisão, o sinal de "agora é hora de dormir".', title_sv = 'Kvällsrutinens kraft 🛀', body_sv = 'Ett ljummet bad fungerar alltid. Bryt aldrig kvällsrutinen, för den ger hjärnan en exakt signal om att det nu är dags att sova.', title_vi = 'Sức mạnh của nếp sinh hoạt buổi tối 🛀', body_vi = 'Tắm nước ấm luôn hiệu quả. Đừng bao giờ phá vỡ nếp sinh hoạt buổi tối, vì nó gửi đến não bé tín hiệu chính xác rằng "giờ là giờ ngủ".', title_zh = '晚间作息的力量 🛀', body_zh = '温水澡总是管用。千万别打乱晚间作息，因为它会准确地向宝宝的大脑发出“现在该睡觉了”的信号。' WHERE id = '302bafdb-c5ca-4389-a56e-16a2ddd6812b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recarga energía 🥑', body_es = 'Si ya está lleno, te toca a ti. No comas de pie con las prisas del día. Elige un tentempié energético en Recetas saludables y túmbate en el sofá.', title_fr = 'Rechargez vos batteries 🥑', body_fr = 'Il a bien mangé ? À votre tour. Dans le tourbillon du quotidien, ne déjeunez pas debout. Choisissez un en-cas énergisant dans les Recettes saines et allongez-vous sur le canapé.', title_hi = 'अपनी ऊर्जा लौटाइए 🥑', body_hi = 'उसका पेट भर गया, तो अब आपकी बारी है। रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए। सेहतमंद रेसिपी से कोई ऊर्जा भरा स्नैक चुनिए और सोफ़े पर लेटिए।', title_id = 'Pulihkan energi Anda 🥑', body_id = 'Kalau ia sudah kenyang, sekarang giliran Anda. Jangan makan siang sambil berdiri di tengah kesibukan. Pilih camilan berenergi dari Resep Sehat dan berbaringlah di sofa.', title_ja = 'エネルギーをチャージ 🥑', body_ja = 'お子さんがお腹いっぱいになったら、次はあなたの番。慌ただしい毎日でも、立ったままランチをすませないで。「ヘルシーレシピ」から元気が出るおやつを選んで、ソファで横になりましょう。', title_ko = '에너지를 회복하세요 🥑', body_ko = '아기가 배불리 먹었다면 이제 엄마 차례예요. 바쁜 하루 속에서도 점심을 서서 먹지 마세요. 건강한 레시피에서 든든한 간식을 골라 소파에 누워 쉬세요.', title_nl = 'Laad je energie op 🥑', body_nl = 'Heeft je kindje genoeg gegeten? Dan ben jij aan de beurt. Eet je lunch niet staand tussen alle drukte door. Kies een energierijk tussendoortje in Gezonde recepten en ga op de bank liggen.', title_pl = 'Odzyskaj energię 🥑', body_pl = 'Jeśli on już najedzony, teraz twoja kolej. W codziennej bieganinie nie jedz obiadu na stojąco. Wybierz ze zdrowych przepisów energetyczną przekąskę i połóż się na kanapie.', title_pt = 'Recupere energia 🥑', body_pt = 'Se ele já está satisfeito, agora é a sua vez. Não almoce de pé no meio da correria. Escolha um lanche energético nas Receitas Saudáveis e deite-se no sofá.', title_sv = 'Fyll på energin 🥑', body_sv = 'Är barnet mätt är det din tur. Ät inte lunchen stående i vardagsstressen. Välj ett energigivande mellanmål från Hälsosamma recept och lägg dig på soffan.', title_vi = 'Nạp lại năng lượng 🥑', body_vi = 'Bé no rồi thì đến lượt mẹ. Đừng ăn trưa vội vàng giữa bộn bề mỗi ngày. Hãy chọn một món ăn nhẹ giàu năng lượng trong Công thức lành mạnh và nằm nghỉ trên sofa nhé.', title_zh = '恢复能量 🥑', body_zh = '宝宝吃饱了，轮到你了。别在日常忙乱中站着吃午饭。从健康食谱里选一款能量小食，到沙发上躺一躺。' WHERE id = '309b39de-d5f5-4702-93e1-596dca9c9021' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No dejas de darle vueltas a «¿Por qué mi hijo hace esto?»? Entra en la Comunidad Anacan, lee historias parecidas de otras mamás y respira.', body_fr = 'La question « Pourquoi mon enfant fait-il ça ? » vous obsède ? Rejoignez la Communauté Anacan, lisez les histoires similaires d''autres mamans et soufflez un peu.', body_hi = '''मेरा बच्चा ऐसा क्यों करता है?'' यह सोच आपको खाए जा रही है? Anacan कम्युनिटी में आइए, दूसरी माँओं की मिलती-जुलती कहानियाँ पढ़िए और सुकून पाइए।', body_id = 'Pikiran "Kenapa anakku begini?" terus menghantui Anda? Masuklah ke Komunitas Anacan, baca kisah serupa dari ibu-ibu lain, dan tenangkan diri.', body_ja = '「どうしてうちの子はこうなの？」と頭がいっぱいですか？Anacanコミュニティを開いて、ほかのママたちの似た体験を読んでほっとしましょう。', body_ko = '''우리 아이는 왜 이럴까?'' 하는 생각이 머리를 떠나지 않나요? Anacan 커뮤니티에 들어가 다른 엄마들의 비슷한 이야기를 읽으며 마음을 편히 하세요.', body_nl = 'Blijf je piekeren: waarom doet mijn kind dit? Ga naar de Anacan Community, lees vergelijkbare verhalen van andere moeders en kom tot rust.', body_pl = 'Myśl „Dlaczego moje dziecko tak robi?” nie daje ci spokoju? Wejdź do Społeczności Anacan, przeczytaj podobne historie innych mam i odetchnij.', body_pt = 'O pensamento "Porque é que o meu filho faz isto?" não lhe sai da cabeça? Entre na Comunidade Anacan, leia histórias parecidas de outras mães e descontraia.', body_sv = 'Äter tanken ”Varför gör mitt barn så här?” upp dig? Gå in i Anacans Community, läs liknande berättelser från andra mammor och slappna av.', body_vi = 'Câu hỏi "Sao con mình lại thế này?" cứ ám ảnh mẹ? Hãy vào Cộng đồng Anacan, đọc những câu chuyện tương tự của các mẹ khác để nhẹ lòng hơn.', body_zh = '“为什么我的孩子会这样？”这个念头让你停不下来？进入Anacan社区，读读其他妈妈的相似经历，放松一下。' WHERE id = '66b4bd9b-8226-4190-94c7-9d50f8db6c34' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Pasa las páginas de los libros de cartón y reacciona a los dibujos? Su memoria visual se está desarrollando. Léele muchos cuentos llenos de color.', body_fr = 'Il tourne les pages de ses livres cartonnés et réagit aux images ? Sa mémoire visuelle se développe. Lisez-lui plein de livres d''histoires colorés.', body_hi = 'मोटे पन्नों वाली किताबों के पन्ने पलटता है और तस्वीरों पर प्रतिक्रिया देता है? उसकी देखी हुई चीज़ें याद रखने की क्षमता बढ़ रही है। उसे खूब रंगीन कहानी की किताबें पढ़कर सुनाइए।', body_id = 'Ia membalik halaman buku bertebal dan bereaksi pada gambarnya? Ingatan visualnya sedang berkembang. Bacakan banyak buku cerita berwarna untuknya.', body_ja = '厚紙の絵本のページをめくって、絵に反応していますか？見たものを覚える力が育っています。カラフルな絵本をたくさん読んであげましょう。', body_ko = '두꺼운 책장을 넘기며 그림에 반응하나요? 시각 기억력이 발달하고 있어요. 알록달록한 그림책을 많이 읽어 주세요.', body_nl = 'Slaat je kindje de bladzijden van kartonboekjes om en reageert hij op de plaatjes? Zijn visuele geheugen ontwikkelt zich. Lees hem veel kleurrijke prentenboeken voor.', body_pl = 'Przewraca kartki grubych książeczek i reaguje na obrazki? Rozwija się pamięć wzrokowa. Czytaj mu dużo kolorowych książeczek z bajkami.', body_pt = 'Vira as páginas dos livros cartonados e reage às imagens? A memória visual está a desenvolver-se. Leia-lhe muitos livros de histórias coloridos.', body_sv = 'Vänder barnet sidorna i kartongböcker och reagerar på bilderna? Det visuella minnet utvecklas. Läs massor av färgglada sagoböcker tillsammans.', body_vi = 'Bé lật trang sách bìa cứng và phản ứng với hình ảnh? Trí nhớ hình ảnh đang phát triển. Hãy đọc cho bé thật nhiều sách truyện đầy màu sắc nhé.', body_zh = '宝宝会翻厚纸板书，还会对图片做出反应？视觉记忆在发展。多给宝宝读读色彩丰富的故事书吧。' WHERE id = '80e6be85-6917-46a0-b283-acc653cca6c1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tiempo contigo es precioso ✨', body_es = 'Cada día es una aventura distinta. Mientras duerme, mira sus manitas y sonríe por los pequeños logros de hoy.', title_fr = 'Le temps est beau avec vous. ✨', body_fr = 'Chaque jour est une nouvelle aventure. Pendant qu''il dort, regardez ses petites mains et souriez à ses petites victoires du jour.', title_hi = 'आपके साथ समय खूबसूरत है। ✨', body_hi = 'हर दिन एक अलग सफ़र है। उसके सोते समय उसके नन्हे हाथों को देखिए और आज की छोटी-छोटी कामयाबियों पर मुस्कुराइए।', title_id = 'Waktu bersama Anda itu indah. ✨', body_id = 'Setiap hari adalah petualangan yang berbeda. Saat ia tidur, pandangi tangan mungilnya dan tersenyumlah atas keberhasilan kecilnya hari ini.', title_ja = 'あなたと過ごす時間はすてき ✨', body_ja = '毎日がちがう冒険です。お子さんが眠っている間に小さな手を眺めて、今日の小さな成長にほほえみましょう。', title_ko = '엄마와 함께라서 시간이 아름다워요. ✨', body_ko = '하루하루가 새로운 모험이에요. 아이가 잘 때 작은 손을 바라보며 오늘의 작은 성공에 미소 지어 보세요.', title_nl = 'De tijd is mooi met jou. ✨', body_nl = 'Elke dag is een ander avontuur. Kijk naar zijn kleine handjes terwijl hij slaapt en glimlach om zijn kleine successen van vandaag.', title_pl = 'Czas z tobą jest piękny. ✨', body_pl = 'Każdy dzień to inna przygoda. Gdy śpi, spójrz na jego małe rączki i uśmiechnij się do jego dzisiejszych drobnych sukcesów.', title_pt = 'O tempo é bonito ao seu lado. ✨', body_pt = 'Cada dia é uma aventura diferente. Enquanto ele dorme, olhe para as suas mãozinhas e sorria pelas pequenas conquistas de hoje.', title_sv = 'Tiden är fin med dig. ✨', body_sv = 'Varje dag är ett nytt äventyr. Titta på barnets små händer när det sover och le åt dagens små framsteg.', title_vi = 'Thời gian bên mẹ thật đẹp. ✨', body_vi = 'Mỗi ngày là một cuộc phiêu lưu mới. Khi bé ngủ, hãy ngắm đôi bàn tay nhỏ xíu và mỉm cười vì những thành công nho nhỏ hôm nay.', title_zh = '有你在，时光真美 ✨', body_zh = '每一天都是一场不同的冒险。宝宝睡着时，看看他的小手，为今天的小小成就微笑一下吧。' WHERE id = 'df1f7c26-41ff-4081-9b25-dae8d38c75e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere comer solo 🥄', body_es = 'Te quita la cuchara de la mano porque quiere comer solo. Se le caerá y se manchará, pero es importante para su motricidad. Deja que sea independiente.', title_fr = 'Il veut manger seul 🥄', body_fr = 'Il vous prend la cuillère des mains pour manger tout seul. Ça va couler et salir, mais c''est important pour sa motricité. Laissez-lui son autonomie.', title_hi = 'खुद खाने की ज़िद 🥄', body_hi = 'आपके हाथ से चम्मच लेकर खुद खाना चाहता है। गिरेगा, गंदा होगा, लेकिन यह उसकी मोटर स्किल्स के लिए ज़रूरी है। उसे आत्मनिर्भर बनने दीजिए।', title_id = 'Ngotot makan sendiri 🥄', body_id = 'Ia mengambil sendok dari tangan Anda dan ingin makan sendiri. Pasti tumpah dan berantakan, tapi ini penting untuk motoriknya. Biarkan ia mandiri.', title_ja = '自分で食べたい！🥄', body_ja = 'あなたの手からスプーンを取って、自分で食べたがっています。こぼれて汚れますが、手先の発達にとても大切です。自立を見守ってあげましょう。', title_ko = '혼자 먹겠다는 고집 🥄', body_ko = '엄마 손에서 숟가락을 빼앗아 혼자 먹고 싶어 해요. 흘리고 묻겠지만 운동 능력 발달에 중요해요. 스스로 해 보게 해 주세요.', title_nl = 'Koppig zelf willen eten 🥄', body_nl = 'Je kindje pakt de lepel uit je hand en wil zelf eten. Het wordt een knoeiboel, maar dat is belangrijk voor zijn motoriek. Gun hem zijn zelfstandigheid.', title_pl = 'Upór przy samodzielnym jedzeniu 🥄', body_pl = 'Wyrywa ci łyżeczkę z ręki i chce jeść sam. Będzie rozlane i umazane, ale to ważne dla jego motoryki. Pozwól mu na samodzielność.', title_pt = 'A teimosia de comer sozinho 🥄', body_pt = 'Tira-lhe a colher da mão e quer comer sozinho. Vai entornar e sujar, mas é importante para a motricidade. Dê espaço à independência dele.', title_sv = 'Envis med att äta själv 🥄', body_sv = 'Barnet tar skeden ur din hand och vill äta själv. Det kommer att spillas och kladdas, men det är viktigt för motoriken. Låt barnet vara självständigt.', title_vi = 'Bé nhất định đòi tự ăn 🥄', body_vi = 'Bé giành lấy thìa từ tay mẹ để tự ăn. Sẽ rơi vãi, sẽ lem luốc, nhưng điều này quan trọng cho kỹ năng vận động. Hãy để bé được tự lập.', title_zh = '执意自己吃饭 🥄', body_zh = '宝宝从你手里拿走勺子，想自己吃。会撒、会弄脏，但这对他的动作发育很重要。让他独立一下吧。' WHERE id = '52e92eba-b885-4c30-891d-aa6e5379acf9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si tienes dudas sobre el comportamiento o el desarrollo de un niño de 13-14 meses, nuestro asistente Anacan AI te aconseja al momento.', body_fr = 'Des questions sur le comportement ou le développement d''un enfant de 13-14 mois vous trottent dans la tête ? Notre assistant Anacan AI vous conseille instantanément.', body_hi = 'अगर 13-14 महीने के बच्चे के व्यवहार या विकास को लेकर कोई सवाल आपको परेशान कर रहा है, तो हमारे Anacan AI असिस्टेंट से तुरंत सलाह ले सकती हैं।', body_id = 'Kalau ada pertanyaan tentang perilaku atau perkembangan anak usia 13-14 bulan yang mengganggu pikiran Anda, dapatkan saran instan dari asisten Anacan AI kami.', body_ja = '1歳1-2か月の子の行動や発達で気になることがあれば、Anacan AIアシスタントからすぐにアドバイスをもらえます。', body_ko = '13-14개월 아이의 행동이나 발달에 대해 궁금한 점이 있다면 Anacan AI 도우미에게 바로 조언을 받을 수 있어요.', body_nl = 'Heb je vragen over het gedrag of de ontwikkeling van je kindje van 13-14 maanden? Bij onze assistent Anacan AI krijg je meteen advies.', body_pl = 'Jeśli nurtują cię pytania o zachowanie lub rozwój 13-14-miesięcznego dziecka, od razu otrzymasz radę od naszego asystenta Anacan AI.', body_pt = 'Se tem dúvidas sobre o comportamento ou o desenvolvimento de uma criança de 13-14 meses, pode receber conselhos na hora do nosso assistente Anacan AI.', body_sv = 'Har du frågor om beteendet eller utvecklingen hos ett barn på 13-14 månader? Få råd direkt från vår assistent Anacan AI.', body_vi = 'Nếu mẹ có thắc mắc về hành vi hay sự phát triển của bé 13-14 tháng, hãy nhận lời khuyên ngay từ trợ lý Anacan AI.', body_zh = '如果你对13-14个月宝宝的行为或发育有疑问，可以随时向我们的Anacan AI助手获得建议。' WHERE id = 'a26c1e0d-7872-4f7e-9268-2fba22c9203a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡A quemar energía! 🏃‍♂', body_es = '️ Antes de la siesta, jugad a algo movido que le canse un poco (pillar, lanzar la pelota) para que duerma a gusto.', title_fr = 'Se défouler ! 🏃‍♂', body_fr = '️ Avant la sieste de l''après-midi, jouez à des jeux qui bougent (chat, lancer de balle) pour le fatiguer un peu et l''aider à bien dormir.', title_hi = 'ऊर्जा निकालिए! 🏃‍♂', body_hi = '️ दोपहर की झपकी से पहले उसे थोड़ा थकाने वाले खेल (पकड़म-पकड़ाई, गेंद फेंकना) खेलिए, ताकि वह आराम से सो सके।', title_id = 'Salurkan energinya! 🏃‍♂', body_id = '️ Sebelum tidur siang, bantu ia tidur nyenyak dengan permainan aktif yang sedikit melelahkan (kejar-kejaran, lempar bola).', title_ja = 'エネルギーを発散！🏃‍♂', body_ja = '️お昼寝の前に、ほどよく疲れる活発な遊び（追いかけっこ、ボール投げ）をして、ぐっすり眠れるようにしてあげましょう。', title_ko = '에너지 발산! 🏃‍♂', body_ko = '️낮잠 전에 조금 지치게 해 줄 활발한 놀이(술래잡기, 공 던지기)를 하며 편하게 잠들도록 도와주세요.', title_nl = 'Energie kwijtraken! 🏃‍♂', body_nl = '️ Speel voor het middagdutje wat drukke spelletjes (tikkertje, met een bal gooien) die hem een beetje moe maken, zodat hij rustig slaapt.', title_pl = 'Wyładuj energię! 🏃‍♂', body_pl = '️ Przed popołudniową drzemką pobawcie się w ruchliwe zabawy, które go trochę zmęczą (berek, rzucanie piłką), by spokojnie zasnął.', title_pt = 'Gastar energia! 🏃‍♂', body_pt = '️ Antes da sesta da tarde, brinquem a jogos agitados que o cansem um pouco (apanhada, atirar a bola) para o ajudar a dormir tranquilo.', title_sv = 'Få ut energin! 🏃‍♂', body_sv = '️ Hjälp barnet att sova gott genom att före eftermiddagsluren leka livliga lekar (kull, kasta boll) som gör det lite trött.', title_vi = 'Xả năng lượng! 🏃‍♂', body_vi = '️ Trước giấc ngủ trưa, hãy chơi những trò vận động (đuổi bắt, ném bóng) để bé hơi mệt một chút và ngủ ngon hơn.', title_zh = '释放精力！🏃‍♂', body_zh = '️ 午睡前和宝宝玩些能让他累一点的活跃游戏（追逐、扔球），帮他睡得更安稳。' WHERE id = 'eb8ab523-6225-489f-8a09-0f37ba40956a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vienen las muelas? 🦷', body_es = '¿Tiene las encías hinchadas y lo muerde todo? Puede que le estén saliendo los dientes de atrás. Mete los mordedores en el congelador.', title_fr = 'Les molaires arrivent ? 🦷', body_fr = 'Ses gencives sont gonflées et il mâchouille tout ? Ce sont peut-être les dents du fond. Mettez des anneaux de dentition au frais.', title_hi = 'दाढ़ें आ रही हैं? 🦷', body_hi = 'मसूड़े सूज गए हैं और वह हर चीज़ चबाता है? पीछे के दाँत निकल रहे हो सकते हैं। ठंडे टीदर फ़्रीज़र में रख दीजिए।', title_id = 'Geraham sedang tumbuh? 🦷', body_id = 'Gusinya bengkak dan ia menggigiti semua benda? Mungkin gigi belakangnya sedang tumbuh. Masukkan teether ke freezer.', title_ja = '奥歯が生えてくる？🦷', body_ja = '歯ぐきが腫れて、なんでもかじっていますか？奥歯が生えてきているのかもしれません。歯がためを冷凍庫で冷やしておきましょう。', title_ko = '어금니가 나오는 중일까요? 🦷', body_ko = '잇몸이 붓고 무엇이든 갉아 대나요? 안쪽 어금니가 나오는 중일 수 있어요. 치발기를 냉동실에 넣어 차갑게 해 두세요.', title_nl = 'Kiezen onderweg? 🦷', body_nl = 'Is het tandvlees gezwollen en knaagt je kindje op alles? Misschien komen de achterste tanden door. Leg koele bijtringen in de vriezer.', title_pl = 'Trzonowce w drodze? 🦷', body_pl = 'Dziąsła są opuchnięte i gryzie wszystko? Mogą wychodzić tylne zęby. Włóż gryzaki do zamrażarki.', title_pt = 'Os molares vêm a caminho? 🦷', body_pt = 'As gengivas estão inchadas e rói tudo? Podem estar a nascer os dentes de trás. Ponha os mordedores frios no congelador.', title_sv = 'Är kindtänderna på väg? 🦷', body_sv = 'Är tandköttet svullet och gnager barnet på allt? Det kan vara de bakre tänderna som kommer. Lägg kalla bitringar i frysen.', title_vi = 'Răng hàm đang mọc? 🦷', body_vi = 'Nướu bé sưng lên và bé gặm mọi thứ? Có thể răng phía sau đang mọc. Hãy cho vòng gặm nướu vào ngăn đá nhé.', title_zh = '磨牙要来了？🦷', body_zh = '牙龈肿起来，什么都要啃？可能是后面的牙在长。把牙胶放进冰箱冷冻吧。' WHERE id = '5d99a4ad-d33f-448d-9f7c-32943cbfa648' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ha crecido y llega a estantes que antes no alcanzaba. El mueble de la tele, las esquinas... Revisa cuanto antes la seguridad de casa.', body_fr = 'Il a grandi et atteint des étagères qui lui étaient inaccessibles. Meuble TV, coins de table... Revoyez sans tarder la sécurité de la maison.', body_hi = 'उसकी लंबाई बढ़ गई है और अब वह उन शेल्फ़ तक पहुँचता है जहाँ पहले नहीं पहुँचता था। टीवी स्टैंड, कोने... घर की सुरक्षा की तुरंत दोबारा जाँच कीजिए।', body_id = 'Tubuhnya makin tinggi dan bisa meraih rak yang dulu tak terjangkau. Meja TV, sudut-sudut tajam... Segera periksa ulang keamanan rumah.', body_ja = '背が伸びて、前は届かなかった棚に手が届くように。テレビ台、家具の角…すぐに家の安全対策を見直しましょう。', body_ko = '키가 자라서 예전에는 닿지 않던 선반에 손이 닿아요. TV 받침대, 모서리... 집 안 안전을 서둘러 다시 점검하세요.', body_nl = 'Je kindje is gegroeid en kan bij planken waar hij eerst niet bij kon. Tv-meubel, hoeken... Controleer meteen opnieuw de veiligheid in huis.', body_pl = 'Urósł i sięga już półek, do których wcześniej nie dosięgał. Szafka pod telewizor, narożniki... Pilnie sprawdź ponownie bezpieczeństwo w domu.', body_pt = 'Está mais alto e já chega a prateleiras onde antes não chegava. Móvel da televisão, esquinas... Reveja com urgência a segurança da casa.', body_sv = 'Barnet har blivit längre och når hyllor det inte nådde förut. TV-bänken, hörnen... Se över säkerheten i hemmet snarast.', body_vi = 'Bé đã cao lên và với tới những kệ trước đây không với được. Kệ TV, các góc cạnh... Hãy kiểm tra lại an toàn trong nhà ngay nhé.', body_zh = '宝宝长高了，能够到以前够不着的架子了。电视柜、桌角……赶紧重新检查一遍家里的安全。' WHERE id = 'aa9c9479-f8d5-4149-b7c4-99976958a17c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares de golpe 😭', body_es = '¿Se despierta gritando en mitad de la noche y no se calma? Escucha su llanto con el Análisis del llanto y descubre la causa.', title_fr = 'Réveils soudains 😭', body_fr = 'Il se réveille en pleine nuit en hurlant et ne se calme pas ? Faites écouter ses pleurs à l''Analyse des pleurs pour en trouver la cause.', title_hi = 'अचानक जागना 😭', body_hi = 'आधी रात को चीखकर जागता है और चुप नहीं होता? क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और परेशानी की वजह जानिए।', title_id = 'Terbangun tiba-tiba 😭', body_id = 'Ia terbangun tengah malam sambil berteriak dan tidak mau diam? Perdengarkan suaranya ke Analisis Tangisan dan temukan penyebabnya.', title_ja = '突然の夜泣き 😭', body_ja = '夜中に叫ぶように起きて、泣き止まない？「泣き声分析」で泣き声を聞かせて、原因を探りましょう。', title_ko = '갑자기 깨요 😭', body_ko = '한밤중에 소리 지르며 깨서 울음을 그치지 않나요? 울음 분석으로 소리를 들려주어 원인을 찾아보세요.', title_nl = 'Plots wakker 😭', body_nl = 'Wordt je kindje midden in de nacht krijsend wakker en stopt het niet? Laat Huilanalyse naar het huilen luisteren en vind de oorzaak.', title_pl = 'Nagłe pobudki 😭', body_pl = 'W środku nocy budzi się z krzykiem i nie przestaje? Daj Analizie płaczu posłuchać jego głosu i poznaj przyczynę.', title_pt = 'Despertares repentinos 😭', body_pt = 'Acorda a meio da noite aos gritos e não se acalma? Deixe a Análise do Choro ouvir o choro e descubra a causa do problema.', title_sv = 'Plötsliga uppvaknanden 😭', body_sv = 'Vaknar barnet mitt i natten, skriker och slutar inte? Låt Gråtanalys lyssna på ljudet och hitta orsaken.', title_vi = 'Thức giấc đột ngột 😭', body_vi = 'Nửa đêm bé thức dậy la hét và không chịu nín? Hãy cho Phân tích tiếng khóc nghe và tìm ra nguyên nhân.', title_zh = '突然惊醒 😭', body_zh = '半夜尖叫着醒来，怎么也停不下来？用哭声分析听一听，找出问题的原因。' WHERE id = '0872925d-e2d7-471e-ba13-22ee468f0a1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ritmo de crecimiento 📏', body_es = 'Hasta en la ropa notas lo rápido que crece. Anota su peso y su altura en el Registro de peso y asegúrate de que crece sano.', title_fr = 'Le rythme de croissance. 📏', body_fr = 'Ses vêtements vous le montrent : il grandit vite. Notez son poids et sa taille dans le Suivi pour vous assurer qu''il grandit bien.', title_hi = 'बढ़ने की रफ़्तार। 📏', body_hi = 'उसके कपड़ों से भी आप महसूस करती हैं कि वह कितनी तेज़ी से बढ़ रहा है। ट्रैकर में वज़न और लंबाई दर्ज करके उसके सेहतमंद विकास के बारे में निश्चिंत रहिए।', title_id = 'Laju pertumbuhan. 📏', body_id = 'Dari bajunya pun terasa betapa cepat ia tumbuh. Catat berat dan tinggi badannya di Pelacak agar Anda yakin pertumbuhannya sehat.', title_ja = '成長のペース 📏', body_ja = 'お洋服を見ても、ぐんぐん大きくなっているのがわかりますね。トラッカーに体重と身長を記録して、健やかな成長を確認しましょう。', title_ko = '성장 속도. 📏', body_ko = '옷만 봐도 아이가 빠르게 자라는 게 느껴져요. 기록 도구에 몸무게와 키를 남기며 건강하게 자라고 있는지 확인하세요.', title_nl = 'Groeitempo. 📏', body_nl = 'Aan zijn kleertjes merk je ook hoe snel je kindje groeit. Noteer gewicht en lengte in de tracker om zeker te zijn van een gezonde groei.', title_pl = 'Tempo wzrostu. 📏', body_pl = 'Po ubrankach też widzisz, jak szybko rośnie. Zapisuj w narzędziu do śledzenia wagę i wzrost, by mieć pewność, że rozwija się zdrowo.', title_pt = 'O ritmo de crescimento. 📏', body_pt = 'Até pela roupa sente que ele está a crescer depressa. Registe o peso e a altura no Registo de Crescimento e confirme que cresce de forma saudável.', title_sv = 'Tillväxttakt. 📏', body_sv = 'Du märker på kläderna hur snabbt barnet växer. Anteckna vikt och längd i spåraren och försäkra dig om en frisk tillväxt.', title_vi = 'Nhịp tăng trưởng. 📏', body_vi = 'Nhìn quần áo là mẹ cũng thấy bé lớn nhanh thế nào. Hãy ghi lại cân nặng và chiều cao trong mục Theo dõi để yên tâm bé phát triển khỏe mạnh.', title_zh = '成长速度 📏', body_zh = '从衣服就能感觉到宝宝长得飞快。在追踪工具里记录体重和身高数据，确认宝宝健康成长。' WHERE id = '1fe0720b-91d5-4dc9-ad61-71e5ff522246' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se tira al suelo cuando no consigue lo que quiere? Son las famosas rabietas de esta etapa. Mantén la calma, mírale a los ojos y hazle saber que estás a su lado.', body_fr = 'Il se jette par terre quand il n''obtient pas ce qu''il veut ? Ce sont les fameuses crises des tout-petits. Gardez votre calme, regardez-le dans les yeux et faites-lui comprendre que vous êtes là.', body_hi = 'मन का न होने पर खुद को ज़मीन पर पटकता है? टॉडलर दौर के मशहूर नखरे। शांत रहिए, उससे आँख मिलाइए और ''मैं तुम्हारे पास हूँ'' का संदेश दीजिए।', body_id = 'Ia menjatuhkan diri ke lantai saat keinginannya tidak dituruti? Inilah tantrum khas masa balita. Tetap tenang, tatap matanya, dan sampaikan pesan "Mama di sini".', body_ja = '思いどおりにならないと床にひっくり返りますか？幼児期によくあるかんしゃくです。落ち着いて目を合わせ、「そばにいるよ」と伝えましょう。', body_ko = '원하는 대로 안 되면 바닥에 드러눕나요? 토들러 시기의 유명한 떼쓰기예요. 침착함을 지키고 눈을 맞추며 ''엄마가 옆에 있어''라고 알려 주세요.', body_nl = 'Gooit je kindje zich op de grond als hij zijn zin niet krijgt? De bekende driftbuien van de dreumestijd. Blijf kalm, maak oogcontact en laat hem weten: ik ben bij je.', body_pl = 'Rzuca się na podłogę, gdy nie dostaje tego, czego chce? To słynne napady złości małego dziecka. Zachowaj spokój, nawiąż kontakt wzrokowy i daj mu znać: „Jestem przy tobie”.', body_pt = 'Atira-se para o chão quando não consegue o que quer? São as famosas birras da fase de criança pequena. Mantenha a calma, olhe-o nos olhos e mostre-lhe que está ao lado dele.', body_sv = 'Kastar sig barnet på golvet när det inte får som det vill? Småbarnsårens kända utbrott. Behåll lugnet, sök ögonkontakt och visa att du finns där.', body_vi = 'Không được như ý là bé ném mình xuống sàn? Đây là những cơn ăn vạ nổi tiếng của giai đoạn chập chững. Hãy giữ bình tĩnh, nhìn vào mắt bé và cho bé biết "mẹ ở đây".', body_zh = '要不到想要的就往地上一躺？这是幼儿期出名的发脾气。保持冷静，和宝宝对视，传达“我在你身边”。' WHERE id = 'ca5a420a-5b8f-49ce-b884-6a219b8b71aa' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Necesitas información sobre los saltos de desarrollo de los 13,5 meses? No te agotes buscando: pide a Anacan AI una lista precisa y avalada por pediatras.', body_fr = 'Besoin d''informations sur les pics de développement à 13,5 mois ? Ne vous épuisez pas, demandez à Anacan AI une liste précise et validée par des pédiatres.', body_hi = '13.5 महीने की विकास की छलांगों के बारे में जानकारी चाहिए? खुद को मत थकाइए, Anacan AI से सटीक और बाल रोग विशेषज्ञ द्वारा पुष्ट सूची माँगिए।', body_id = 'Butuh informasi tentang lompatan perkembangan usia 13,5 bulan? Jangan melelahkan diri, minta daftar akurat yang disetujui dokter anak dari Anacan AI.', body_ja = '1歳1か月半ごろの発達の節目について知りたいですか？ひとりで悩まず、Anacan AIに正確で小児科医も認めるリストを聞いてみましょう。', body_ko = '13.5개월 발달 도약에 대한 정보가 필요한가요? 혼자 애쓰지 말고 Anacan AI에게 정확하고 소아과 의사가 확인한 목록을 요청하세요.', body_nl = 'Wil je meer weten over de ontwikkelingssprongen rond 13,5 maanden? Maak jezelf niet moe en vraag Anacan AI om een nauwkeurige lijst die door kinderartsen is goedgekeurd.', body_pl = 'Potrzebujesz informacji o skokach rozwojowych w 13,5 miesiącu? Nie męcz się, poproś Anacan AI o rzetelną listę zatwierdzoną przez pediatrę.', body_pt = 'Precisa de informação sobre os saltos de desenvolvimento aos 13,5 meses? Não se canse, peça ao Anacan AI uma lista precisa e validada por pediatras.', body_sv = 'Behöver du information om utvecklingssprången vid 13,5 månader? Trötta inte ut dig, be Anacan AI om en exakt och barnläkargodkänd lista.', body_vi = 'Mẹ cần thông tin về các bước nhảy phát triển ở tháng 13,5? Đừng tự làm mình mệt, hãy nhờ Anacan AI đưa ra một danh sách chính xác, đã được bác sĩ nhi khoa xác nhận.', body_zh = '想了解13.5个月的发育飞跃？别累着自己，请Anacan AI给你一份准确、经儿科医生认可的清单吧。' WHERE id = '005096a2-1549-4208-a331-7e39e1da9587' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue instrucciones sencillas 🧸', body_es = '¿Cuando le dices «Trae los zapatos» de verdad va a buscarlos? ¡Su vocabulario y su comprensión están en plena forma! Hazle participar más en los juegos.', title_fr = 'Il suit des consignes simples 🧸', body_fr = 'Quand vous dites « Apporte tes chaussures », il va vraiment les chercher ? Son vocabulaire et sa compréhension sont au top ! Impliquez-le davantage dans vos jeux.', title_hi = 'आसान निर्देश मानता है 🧸', body_hi = '''जूते लाओ'' कहने पर सच में जाकर ले आता है? शब्द भंडार और समझने की क्षमता चरम पर है! उसे खेलों में और शामिल कीजिए।', title_id = 'Mengikuti instruksi sederhana 🧸', body_id = 'Saat Anda bilang "Ambil sepatunya", ia benar-benar pergi mengambilnya? Kosakata dan kemampuan memahaminya sedang di puncak! Ajak ia lebih sering bermain.', title_ja = '簡単な指示がわかる 🧸', body_ja = '「靴を持ってきて」と言うと、本当に取ってきてくれますか？語彙も理解力もぐんぐん伸びています！遊びにもっと誘ってあげましょう。', title_ko = '간단한 말을 알아듣고 해내요 🧸', body_ko = '"신발 가져와" 하면 정말 가서 가져오나요? 어휘력과 이해력이 최고조예요! 놀이에 더 많이 참여시켜 주세요.', title_nl = 'Voert eenvoudige opdrachtjes uit 🧸', body_nl = 'Haalt je kindje echt zijn schoenen als je zegt: breng je schoenen? Zijn woordenschat en begrip groeien enorm! Betrek hem meer bij spelletjes.', title_pl = 'Wykonuje proste polecenia 🧸', body_pl = 'Na „Przynieś buty” naprawdę idzie i je przynosi? Zasób słów i rozumienie są na szczycie! Częściej angażuj go w zabawy.', title_pt = 'Cumpre instruções simples 🧸', body_pt = 'Quando lhe diz "Traz os sapatos", vai mesmo buscá-los? O vocabulário e a compreensão estão no auge! Envolva-o mais nas brincadeiras.', title_sv = 'Följer enkla instruktioner 🧸', body_sv = 'Går barnet verkligen och hämtar skorna när du säger ”Hämta skorna”? Ordförrådet och förståelsen är på topp! Låt barnet vara med mer i lekarna.', title_vi = 'Bé làm theo hướng dẫn đơn giản 🧸', body_vi = 'Mẹ nói "Mang giày lại đây" là bé đi lấy thật? Vốn từ và khả năng hiểu đang ở đỉnh cao! Hãy cho bé tham gia các trò chơi nhiều hơn.', title_zh = '能听懂简单指令 🧸', body_zh = '你说“把鞋拿来”，宝宝真的会去拿？词汇量和理解能力正处于高峰！多让宝宝参与游戏吧。' WHERE id = '7de487db-11d1-4c22-8b8d-e58adb31344a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina de la noche prepara para dormir 🌙', body_es = 'Pequeños hábitos a la misma hora cada día (lavarse los dientes, leer un cuento) le ayudan mucho a pasar al sueño.', title_fr = 'Le rituel du soir prépare au sommeil. 🌙', body_fr = 'De petites habitudes à la même heure chaque jour (se brosser les dents, lire une histoire) facilitent beaucoup son endormissement.', title_hi = 'शाम का रूटीन नींद के लिए तैयार करता है। 🌙', body_hi = 'हर दिन एक ही समय पर की जाने वाली छोटी आदतें (दाँत साफ़ करना, कहानी पढ़ना) उसके लिए नींद में जाना काफ़ी आसान बना देती हैं।', title_id = 'Rutinitas malam menyiapkannya untuk tidur. 🌙', body_id = 'Kebiasaan kecil yang dilakukan di jam yang sama setiap hari (menggosok gigi, membaca dongeng) sangat memudahkannya beralih ke tidur.', title_ja = '夜の習慣が眠りへの準備に 🌙', body_ja = '毎日同じ時間の小さな習慣（歯みがき、絵本の読み聞かせ）で、眠りへの切りかえがずっと楽になります。', title_ko = '저녁 루틴이 잠을 준비해요. 🌙', body_ko = '매일 같은 시간에 하는 작은 습관(양치하기, 동화 읽기)이 잠드는 과정을 훨씬 쉽게 만들어 줘요.', title_nl = 'De avondroutine bereidt voor op de slaap. 🌙', body_nl = 'Kleine gewoontes elke dag op hetzelfde tijdstip (tandenpoetsen, voorlezen) maken de overgang naar de slaap een stuk makkelijker.', title_pl = 'Wieczorna rutyna przygotowuje do snu. 🌙', body_pl = 'Drobne nawyki powtarzane codziennie o tej samej porze (mycie zębów, czytanie bajki) bardzo ułatwiają mu zasypianie.', title_pt = 'A rotina da noite prepara para o sono. 🌙', body_pt = 'Pequenos hábitos feitos todos os dias à mesma hora (lavar os dentes, ler uma história) facilitam muito a passagem para o sono.', title_sv = 'Kvällsrutinen förbereder för sömn. 🌙', body_sv = 'Små vanor vid samma tid varje dag (tandborstning, saga) gör övergången till sömn mycket lättare.', title_vi = 'Nếp sinh hoạt buổi tối giúp bé sẵn sàng đi ngủ. 🌙', body_vi = 'Những thói quen nhỏ làm vào cùng một giờ mỗi ngày (đánh răng, đọc truyện) giúp bé vào giấc dễ dàng hơn nhiều.', title_zh = '晚间作息帮助入睡 🌙', body_zh = '每天在同一时间做的小习惯（刷牙、讲故事），能让宝宝入睡容易得多。' WHERE id = '3170ad10-66c6-4ca0-bf72-80b0daf91373' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pequeño explorador atento! 🔍', body_es = 'Cada rincón y cada armario de casa es un mundo nuevo para él. Crea un entorno seguro y déjale explorar la casa con libertad.', title_fr = 'Petit explorateur attentif ! 🔍', body_fr = 'Chaque coin, chaque placard de la maison est un nouveau monde pour lui. Sécurisez les lieux et laissez-le explorer librement.', title_hi = 'ध्यान से खोज करने वाला! 🔍', body_hi = 'घर का हर कोना, हर अलमारी उसके लिए एक नई दुनिया है। सुरक्षित माहौल बनाइए और उसे घर में खुलकर खोजबीन करने दीजिए।', title_id = 'Penjelajah yang teliti! 🔍', body_id = 'Setiap sudut dan setiap lemari di rumah adalah dunia baru baginya. Ciptakan lingkungan yang aman dan biarkan ia menjelajahi rumah dengan bebas.', title_ja = '好奇心いっぱいの探検家！🔍', body_ja = '家の中のすみずみ、戸棚のひとつひとつが、新しい世界です。安全な環境を整えて、家の中を自由に探検させてあげましょう。', title_ko = '꼼꼼한 탐험가! 🔍', body_ko = '집 안의 모든 구석, 모든 수납장이 아이에게는 새로운 세상이에요. 안전한 환경을 만들어 집 안을 마음껏 탐험하게 해 주세요.', title_nl = 'Een oplettende ontdekkingsreiziger! 🔍', body_nl = 'Elke hoek en elke kast in huis is voor je kindje een nieuwe wereld. Maak je huis veilig en laat hem vrij op ontdekking gaan.', title_pl = 'Uważny odkrywca! 🔍', body_pl = 'Każdy kąt i każda szafka w domu to dla niego nowy świat. Zadbaj o bezpieczne otoczenie i pozwól mu swobodnie odkrywać dom.', title_pt = 'Explorador atento! 🔍', body_pt = 'Cada canto e cada armário da casa é um mundo novo para ele. Crie um ambiente seguro e deixe-o explorar a casa à vontade.', title_sv = 'Uppmärksam upptäcktsresande! 🔍', body_sv = 'Varje hörn och varje skåp hemma är en ny värld för barnet. Skapa en säker miljö och låt barnet upptäcka hemmet fritt.', title_vi = 'Nhà thám hiểm chăm chú! 🔍', body_vi = 'Mỗi góc nhà, mỗi chiếc tủ đều là một thế giới mới với bé. Hãy tạo môi trường an toàn và để bé tự do khám phá trong nhà.', title_zh = '专注的小探险家！🔍', body_zh = '家里的每个角落、每个柜子，对宝宝来说都是一个新世界。营造安全的环境，让他在家里自由探索吧。' WHERE id = '64832db8-28ac-41fb-8d33-21a72b48fa8c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Aire libre y mucha energía! 🌳', body_es = 'Gastar energía al aire libre ayuda a los niños a dormir mejor la siesta. Id juntos al parque.', title_fr = 'Air frais et plein d''énergie ! 🌳', body_fr = 'Se défouler dehors aide les enfants à s''endormir plus facilement pour la sieste. Partez ensemble au parc.', title_hi = 'ताज़ी हवा और भरपूर ऊर्जा! 🌳', body_hi = 'बाहर ऊर्जा निकालने से बच्चे दिन की झपकी आसानी से ले पाते हैं। साथ में पार्क चलिए।', title_id = 'Udara segar dan energi melimpah! 🌳', body_id = 'Menyalurkan energi di luar rumah membantu anak lebih mudah tidur siang. Ayo pergi ke taman bersama.', title_ja = '新鮮な空気と元気いっぱい！🌳', body_ja = '外でエネルギーを発散すると、お昼寝もスムーズになります。一緒に公園へ出かけましょう。', title_ko = '신선한 공기와 넘치는 에너지! 🌳', body_ko = '밖에서 에너지를 발산하면 낮잠에 더 쉽게 들어요. 함께 공원으로 나가 보세요.', title_nl = 'Frisse lucht en veel energie! 🌳', body_nl = 'Als kinderen buiten hun energie kwijt kunnen, gaan ze makkelijker hun middagdutje doen. Ga samen naar het park.', title_pl = 'Świeże powietrze i mnóstwo energii! 🌳', body_pl = 'Gdy dzieci wyszaleją się na dworze, łatwiej zasypiają na drzemkę. Wybierzcie się razem do parku.', title_pt = 'Ar puro e muita energia! 🌳', body_pt = 'Gastar energia ao ar livre ajuda as crianças a fazer a sesta com mais facilidade. Vão juntos até ao parque.', title_sv = 'Frisk luft och massor av energi! 🌳', body_sv = 'När barn får ut energin utomhus somnar de lättare till dagsluren. Gå till parken tillsammans.', title_vi = 'Không khí trong lành và tràn đầy năng lượng! 🌳', body_vi = 'Được xả năng lượng ngoài trời giúp trẻ dễ ngủ trưa hơn. Hãy cùng bé ra công viên nhé.', title_zh = '新鲜空气，满满能量！🌳', body_zh = '孩子在户外释放精力，白天小睡会更容易。一起去公园吧。' WHERE id = 'f283f219-7efa-4926-a360-3fb653057b9b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le encanta decir «no»? 🛑', body_es = 'Puede que imite tus negativas y diga que no a todo. En esta etapa es importante tener paciencia y ofrecerle pequeñas alternativas.', title_fr = 'Il adore dire « Non » ? 🛑', body_fr = 'En imitant vos refus, il peut lui aussi dire non à tout. À cette période, il est important d''être patiente et de lui proposer de petites alternatives.', title_hi = '''नहीं'' कहना पसंद है? 🛑', body_hi = 'आपकी मनाही की नकल करते हुए वह भी हर बात पर ''नहीं'' कह सकता है। इस दौर में धैर्य रखना और उसे छोटे-छोटे विकल्प देना ज़रूरी है।', title_id = 'Senang bilang "Tidak"? 🛑', body_id = 'Ia mungkin meniru penolakan Anda dan bilang tidak untuk segala hal. Di masa ini, penting untuk bersabar dan menawarkan alternatif kecil.', title_ja = '「いや」が大好き？🛑', body_ja = 'あなたの「ダメ」をまねして、なんでも「いや」と言うことも。この時期は根気よく、小さな選択肢を用意してあげることが大切です。', title_ko = '"싫어", "안 해"라고 말하는 걸 좋아하나요? 🛑', body_ko = '엄마의 거절을 따라 하며 아이도 모든 것에 싫다고 할 수 있어요. 이 시기에는 인내심을 갖고 작은 선택지를 주는 게 중요해요.', title_nl = 'Zegt hij graag nee? 🛑', body_nl = 'Je kindje doet jouw protest na en zegt misschien overal nee tegen. Wees in deze fase geduldig en bied kleine alternatieven aan.', title_pl = 'Uwielbia mówić „nie”? 🛑', body_pl = 'Naśladując twoje sprzeciwy, sam może mówić „nie” na wszystko. Na tym etapie ważne są cierpliwość i proponowanie mu małych alternatyw.', title_pt = 'Adora dizer "não"? 🛑', body_pt = 'Ao imitar as suas recusas, também ele pode começar a dizer não a tudo. Nesta fase, é importante ter paciência e oferecer-lhe pequenas alternativas.', title_sv = 'Älskar att säga ”Nej”? 🛑', body_sv = 'Barnet kan härma dina protester och säga nej till allt. I den här perioden är det viktigt att ha tålamod och erbjuda små alternativ.', title_vi = 'Bé thích nói "Không"? 🛑', body_vi = 'Bắt chước những lời phản đối của mẹ, bé có thể nói "không" với mọi thứ. Trong giai đoạn này, hãy kiên nhẫn và đưa ra cho bé những lựa chọn nhỏ.', title_zh = '爱说“不”？🛑', body_zh = '宝宝可能会模仿你的拒绝，对什么都说“不”。这个阶段要有耐心，给他一些小小的选择。' WHERE id = 'aa01a859-3ad0-4c64-9ef3-4423ccf76d24' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Haz que beber agua sea divertido 💧', body_es = 'Ofrécele agua a menudo en un vaso de aprendizaje de colores para que no se deshidrate después de tanto movimiento.', title_fr = 'Rendez l''eau amusante. 💧', body_fr = 'Proposez-lui régulièrement de l''eau dans une gourde colorée pour qu''il ne manque pas d''eau après ses activités.', title_hi = 'पानी पीना मज़ेदार बनाइए। 💧', body_hi = 'रंगीन सिपी कप से उसे नियमित रूप से पानी दीजिए, ताकि भाग-दौड़ के बाद उसके शरीर में पानी की कमी न हो।', title_id = 'Jadikan minum air menyenangkan. 💧', body_id = 'Tawarkan air secara rutin dengan botol minum berwarna agar tubuhnya tidak kekurangan cairan setelah aktif bergerak.', title_ja = 'お水を楽しく飲もう 💧', body_ja = 'カラフルなマグで、こまめにお水をすすめましょう。活発に動いたあとも、体が水分不足にならないように。', title_ko = '물 마시기를 재미있게. 💧', body_ko = '활발하게 움직인 뒤 몸에 수분이 부족하지 않도록 알록달록한 물병으로 물을 자주 권해 주세요.', title_nl = 'Maak water drinken leuk. 💧', body_nl = 'Bied je kindje regelmatig water aan in een kleurrijke drinkbeker, zodat hij na het actieve spelen niet uitdroogt.', title_pl = 'Niech picie wody będzie zabawą. 💧', body_pl = 'Regularnie proponuj mu wodę w kolorowym kubku niekapku, by po aktywnej zabawie jego organizm się nie odwodnił.', title_pt = 'Torne divertido beber água. 💧', body_pt = 'Ofereça-lhe água com regularidade num copo com bico colorido, para que o corpo não fique desidratado depois das brincadeiras ativas.', title_sv = 'Gör vattendrickandet roligt. 💧', body_sv = 'Erbjud regelbundet vatten i en färgglad pipmugg så att kroppen inte blir uttorkad efter aktiv lek.', title_vi = 'Biến việc uống nước thành niềm vui. 💧', body_vi = 'Hãy thường xuyên cho bé uống nước bằng một chiếc bình tập uống nhiều màu sắc để cơ thể bé không bị thiếu nước sau khi vận động.', title_zh = '让喝水变有趣 💧', body_zh = '用一个彩色水杯经常给宝宝喝水，别让他活动后缺水。' WHERE id = 'b8b7257f-64c5-46a3-b958-ded901da8e8d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento con papá 👨‍🍼', body_es = 'Hoy deja a papá el turno del cuento y de acostarle, y regálate un pequeño descanso.', title_fr = 'L''heure du conte avec papa. 👨‍🍼', body_fr = 'Ce soir, confiez à papa l''histoire du soir et le coucher, et offrez-vous une petite pause.', title_hi = 'पापा की कहानी का समय। 👨‍🍼', body_hi = 'आज शाम कहानी सुनाने और सुलाने की बारी पापा को सौंपिए और खुद को छोटा सा ब्रेक दीजिए।', title_id = 'Waktu dongeng bersama ayah. 👨‍🍼', body_id = 'Hari ini, serahkan giliran membacakan dongeng dan menidurkan si kecil kepada ayah, dan beri diri Anda jeda sejenak.', title_ja = 'パパのお話タイム 👨‍🍼', body_ja = '今夜は寝る前の読み聞かせと寝かしつけをパパにお願いして、自分に小さな休憩をあげましょう。', title_ko = '아빠의 이야기 시간. 👨‍🍼', body_ko = '오늘은 저녁 동화 읽기와 재우기를 아빠에게 맡기고 엄마는 잠깐 쉬어 가세요.', title_nl = 'Verhaaltjestijd met papa. 👨‍🍼', body_nl = 'Laat het voorlezen en naar bed brengen vandaag aan papa over en gun jezelf een kleine pauze.', title_pl = 'Czas bajek z tatą. 👨‍🍼', body_pl = 'Dziś wieczorem przekaż tacie czytanie bajki i usypianie, a sobie daj małą przerwę.', title_pt = 'A hora das histórias do pai. 👨‍🍼', body_pt = 'Hoje, entregue ao pai a vez de ler a história da noite e de o adormecer, e dê a si própria uma pequena pausa.', title_sv = 'Pappas sagostund. 👨‍🍼', body_sv = 'Lämna kvällssagan och nattningen till pappa i dag och ge dig själv en liten paus.', title_vi = 'Giờ kể chuyện của bố. 👨‍🍼', body_vi = 'Tối nay hãy giao việc kể chuyện và ru bé ngủ cho bố, còn mẹ thì cho mình nghỉ ngơi một chút.', title_zh = '爸爸的故事时间 👨‍🍼', body_zh = '今天把讲睡前故事和哄睡的任务交给爸爸，给自己一个小小的休息。' WHERE id = 'd2e6d5c6-90cf-4a42-ae18-383c2c592a7c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del ruido blanco 🎶', body_es = 'Si después de un día tan activo no consigue dormirse, pon el sonido del mar o de la lluvia en Ruido blanco y crea calma en la habitación.', title_fr = 'La force des bruits blancs. 🎶', body_fr = 'Il n''arrive pas à dormir après une journée active ? Lancez le bruit de l''océan ou de la pluie dans les Bruits blancs pour apaiser la chambre.', title_hi = 'व्हाइट नॉइज़ की ताकत। 🎶', body_hi = 'अगर भाग-दौड़ भरे दिन के असर से वह सो नहीं पा रहा, तो व्हाइट नॉइज़ से समुद्र या बारिश की आवाज़ चलाकर कमरे में शांति बनाइए।', title_id = 'Kekuatan suara putih. 🎶', body_id = 'Kalau ia sulit tidur setelah hari yang aktif, ciptakan ketenangan di kamar dengan memutar suara ombak atau hujan dari Suara Putih.', title_ja = 'ホワイトノイズの力 🎶', body_ja = '活発に過ごした日で寝つけないときは、「ホワイトノイズ」から海や雨の音を流して、部屋を穏やかな雰囲気にしましょう。', title_ko = '백색소음의 힘. 🎶', body_ko = '활발한 하루 때문에 잠들지 못한다면 백색소음에서 파도나 빗소리를 틀어 방을 차분하게 만들어 주세요.', title_nl = 'De kracht van witte ruis. 🎶', body_nl = 'Kan je kindje na een drukke dag niet slapen? Zet in Witte ruis het geluid van de oceaan of regen aan en breng rust in de kamer.', title_pl = 'Moc białego szumu. 🎶', body_pl = 'Jeśli po aktywnym dniu nie może zasnąć, włącz w Białym szumie odgłos oceanu lub deszczu i stwórz w pokoju spokojną atmosferę.', title_pt = 'A força do Ruído Branco. 🎶', body_pt = 'Se não consegue adormecer por causa de um dia agitado, ligue o som do mar ou da chuva no Ruído Branco e crie tranquilidade no quarto.', title_sv = 'Kraften i vitt brus. 🎶', body_sv = 'Om barnet inte kan somna efter en aktiv dag, skapa lugn i rummet genom att sätta på havs- eller regnljud i Vitt brus.', title_vi = 'Sức mạnh của tiếng ồn trắng. 🎶', body_vi = 'Nếu bé không ngủ được sau một ngày hiếu động, hãy bật tiếng sóng biển hoặc tiếng mưa trong Tiếng ồn trắng để căn phòng thêm yên bình.', title_zh = '白噪音的力量 🎶', body_zh = '如果玩了一整天兴奋得睡不着，就在白噪音里放海浪声或雨声，让房间安静下来。' WHERE id = '4484d3ee-8677-4454-8e65-371ba851a267' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Abrazos dulces! 🤗', body_es = 'Que te abrace de repente e intente darte besos es su forma de expresar su amor. ¡Disfruta de estos momentos de amor únicos!', title_fr = 'Câlins tout doux ! 🤗', body_fr = 'Quand il vous serre soudain dans ses bras et essaie de vous embrasser, c''est sa façon de dire je t''aime. Savourez ces moments d''amour uniques !', title_hi = 'प्यारी झप्पियाँ! 🤗', body_hi = 'अचानक आपसे लिपट जाना और चूमने की कोशिश करना उसका प्यार जताने का तरीका है। प्यार के इन बेमिसाल पलों का आनंद लीजिए!', title_id = 'Pelukan manis! 🤗', body_id = 'Tiba-tiba memeluk dan mencoba mencium Anda adalah caranya mengungkapkan cinta. Nikmati momen penuh cinta yang tak ternilai ini!', title_ja = 'あまいハグ！🤗', body_ja = '突然ぎゅっと抱きついたり、キスしようとしたりするのは、愛情の表し方です。このかけがえのない愛の瞬間を味わってください！', title_ko = '달콤한 포옹! 🤗', body_ko = '갑자기 엄마를 꼭 안고 뽀뽀하려는 건 사랑을 표현하는 방법이에요. 이 무엇과도 바꿀 수 없는 사랑의 순간을 마음껏 누리세요!', title_nl = 'Lieve knuffels! 🤗', body_nl = 'Als je kindje je ineens omhelst en je probeert te kussen, laat hij zo zijn liefde zien. Geniet van deze onbetaalbare liefdevolle momenten!', title_pl = 'Słodkie przytulasy! 🤗', body_pl = 'Nagłe przytulanie i próby całowania to jego sposób na okazanie miłości. Delektuj się tymi bezcennymi chwilami!', title_pt = 'Abraços doces! 🤗', body_pt = 'Abraçá-la de repente e tentar dar-lhe beijinhos é a forma dele de mostrar amor. Aproveite estes momentos de amor sem igual!', title_sv = 'Söta kramar! 🤗', body_sv = 'När barnet plötsligt kramar dig och försöker pussa dig är det ett sätt att visa kärlek. Njut av dessa makalösa kärleksstunder!', title_vi = 'Những cái ôm ngọt ngào! 🤗', body_vi = 'Bé bất ngờ ôm và cố hôn mẹ là cách bé thể hiện tình yêu. Hãy tận hưởng những khoảnh khắc yêu thương vô giá này!', title_zh = '甜蜜的拥抱！🤗', body_zh = '宝宝突然抱住你、想亲你，这是他表达爱的方式。好好享受这些无与伦比的爱的瞬间吧！' WHERE id = 'b03cef74-ad4c-4ee6-86e3-5d55fe15d1fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invítale a hablar 🗣', body_es = '️ Di el nombre de las cosas de la habitación y espera a que lo repita. Su vocabulario se enriquece justo con estos pequeños juegos.', title_fr = 'Faites-le parler. 🗣', body_fr = '️ Nommez les objets de la pièce et attendez qu''il les répète. C''est grâce à ces petits jeux que son vocabulaire s''enrichit.', title_hi = 'बातचीत में शामिल कीजिए। 🗣', body_hi = '️ कमरे की चीज़ों के नाम बोलिए और उसके दोहराने का इंतज़ार कीजिए। शब्द भंडार ऐसे ही छोटे खेलों से बढ़ता है।', title_id = 'Ajak ia mengobrol. 🗣', body_id = '️ Sebutkan nama benda-benda di kamar dan tunggu ia mengulanginya. Kosakatanya bertambah justru lewat permainan kecil seperti ini.', title_ja = 'おしゃべりに誘おう 🗣', body_ja = '️部屋にあるものの名前を言って、まねして言うのを待ってみましょう。語彙はこんな小さな遊びで豊かになります。', title_ko = '대화에 참여시켜요. 🗣', body_ko = '️방 안 물건의 이름을 말하고 아이가 따라 하기를 기다려 보세요. 어휘는 바로 이런 작은 놀이로 풍부해져요.', title_nl = 'Betrek hem bij het gesprek. 🗣', body_nl = '️ Noem de namen van dingen in de kamer en wacht tot je kindje ze herhaalt. Juist met zulke kleine spelletjes groeit de woordenschat.', title_pl = 'Zachęcaj do rozmowy. 🗣', body_pl = '️ Nazywaj przedmioty w pokoju i czekaj, aż je powtórzy. Właśnie takie małe zabawy wzbogacają zasób słów.', title_pt = 'Puxe-o para a conversa. 🗣', body_pt = '️ Diga o nome dos objetos do quarto e espere que ele os repita. É com pequenos jogos assim que o vocabulário se enriquece.', title_sv = 'Få igång samtalet. 🗣', body_sv = '️ Säg namnen på sakerna i rummet och vänta på att barnet upprepar. Ordförrådet växer just genom sådana små lekar.', title_vi = 'Cùng bé trò chuyện. 🗣', body_vi = '️ Hãy gọi tên các đồ vật trong phòng và chờ bé nhắc lại. Vốn từ của bé phong phú lên chính nhờ những trò chơi nhỏ như vậy.', title_zh = '多和宝宝聊天 🗣', body_zh = '️ 说出房间里物品的名字，等宝宝跟着重复。词汇量正是在这样的小游戏中丰富起来的。' WHERE id = 'fb1bbc34-c7a1-41dc-b4eb-e7444cbade21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere comer solo 🥦', body_es = 'Aunque se manche, deja que sujete la cuchara él solo. Así desarrollará su independencia y su coordinación ojo-mano.', title_fr = 'Il veut manger seul. 🥦', body_fr = 'Même s''il se salit, laissez-le tenir la cuillère lui-même. Cela développera son sentiment d''autonomie et sa coordination œil-main.', title_hi = 'खुद खाना चाहता है। 🥦', body_hi = 'भले कपड़े गंदे हो जाएँ, उसे चम्मच खुद पकड़ने दीजिए। इससे उसकी आत्मनिर्भरता की भावना और आँख-हाथ का तालमेल विकसित होगा।', title_id = 'Ingin makan sendiri. 🥦', body_id = 'Meski bajunya kotor, biarkan ia memegang sendok sendiri. Ini akan mengembangkan rasa mandiri dan koordinasi mata-tangannya.', title_ja = '自分で食べたい 🥦', body_ja = '服が汚れても、スプーンは自分で持たせてあげましょう。自立心と目と手の協調が育ちます。', title_ko = '혼자 먹고 싶어 해요. 🥦', body_ko = '옷이 엉망이 되더라도 숟가락은 직접 잡게 해 주세요. 독립심과 눈과 손의 협응력이 자랄 거예요.', title_nl = 'Wil zelf eten. 🥦', body_nl = 'Ook al wordt hij vies, laat hem zelf de lepel vasthouden. Dat versterkt zijn gevoel van zelfstandigheid en zijn oog-handcoördinatie.', title_pl = 'Chce jeść sam. 🥦', body_pl = 'Nawet jeśli się ubrudzi, pozwól mu samemu trzymać łyżeczkę. To rozwinie jego poczucie samodzielności i koordynację wzrokowo-ruchową.', title_pt = 'Quer comer sozinho. 🥦', body_pt = 'Mesmo que se suje todo, deixe-o segurar a colher sozinho. Isso vai desenvolver o sentido de independência e a coordenação olho-mão.', title_sv = 'Vill äta själv. 🥦', body_sv = 'Även om barnet blir kladdigt, låt det hålla skeden själv. Det utvecklar känslan av frihet och öga-hand-koordinationen.', title_vi = 'Bé muốn tự ăn. 🥦', body_vi = 'Dù lem luốc, hãy để bé tự cầm thìa. Điều này giúp bé phát triển cảm giác tự lập và khả năng phối hợp tay mắt.', title_zh = '想自己吃饭 🥦', body_zh = '就算弄得一身脏，也让宝宝自己拿勺子吧。这能培养他的独立感和手眼协调能力。' WHERE id = '35a5e175-d9f9-4d9a-9445-a523d64bc595' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descansar es tu derecho 🛁', body_es = 'Has estado de pie todo el día. Cuando se duerma, sírvete un té calentito y disfruta sin más del silencio.', title_fr = 'Vous avez le droit de vous reposer. 🛁', body_fr = 'Vous avez été debout toute la journée. Une fois qu''il dort, servez-vous un thé chaud et savourez simplement le calme.', title_hi = 'आराम करना आपका हक है। 🛁', body_hi = 'आप पूरे दिन खड़ी रहीं। बच्चे के सोने के बाद अपने लिए गरम चाय डालिए और बस शांति का मज़ा लीजिए।', title_id = 'Anda berhak beristirahat. 🛁', body_id = 'Seharian Anda terus berdiri. Setelah si kecil tidur, tuang teh hangat dan nikmati saja ketenangannya.', title_ja = '休むのはあなたの権利です 🛁', body_ja = '一日中立ちっぱなしでしたね。お子さんが寝たら温かいお茶をいれて、静けさをゆっくり味わいましょう。', title_ko = '쉬는 건 엄마의 권리예요. 🛁', body_ko = '하루 종일 서 있었죠. 아이가 잠들면 따뜻한 차 한 잔을 따르고 그저 고요함을 즐기세요.', title_nl = 'Je verdient rust. 🛁', body_nl = 'Je stond de hele dag op je benen. Schenk een warme kop thee in als je kindje slaapt en geniet gewoon van de stilte.', title_pl = 'Masz prawo odpocząć. 🛁', body_pl = 'Cały dzień byłaś na nogach. Gdy maluszek zaśnie, nalej sobie gorącej herbaty i po prostu delektuj się ciszą.', title_pt = 'Descansar é um direito seu. 🛁', body_pt = 'Esteve de pé o dia todo. Quando ele adormecer, sirva-se de um chá quente e aproveite simplesmente o silêncio.', title_sv = 'Du har rätt att vila. 🛁', body_sv = 'Du har varit på benen hela dagen. Häll upp ditt varma te när barnet somnat och njut bara av lugnet.', title_vi = 'Mẹ xứng đáng được nghỉ ngơi. 🛁', body_vi = 'Cả ngày mẹ đã đứng không ngơi chân. Khi bé ngủ, hãy rót một tách trà nóng và tận hưởng sự yên tĩnh.', title_zh = '休息是你的权利 🛁', body_zh = '你站了一整天。宝宝睡着后，给自己倒杯热茶，好好享受这份安静吧。' WHERE id = '66beeaaa-0b78-4114-b41f-8d7e6f407c55' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pasos rápidos! 🏃‍♂', body_es = '️ Ya va libremente de una habitación a otra e incluso intenta correr. ¡Seguirle el ritmo es todo un deporte para mamá!', title_fr = 'Des pas rapides ! 🏃‍♂', body_fr = '️ Il circule déjà librement d''une pièce à l''autre et essaie même de courir. Le suivre, c''est un vrai sport pour les mamans !', title_hi = 'तेज़ कदम! 🏃‍♂', body_hi = '️ अब वह कमरों के बीच खुलकर चलता है, दौड़ने की कोशिश भी करता है। उसके पीछे भागना माँओं के लिए असली कसरत है!', title_id = 'Langkah-langkah cepat! 🏃‍♂', body_id = '️ Kini ia bebas berjalan dari kamar ke kamar, bahkan mencoba berlari. Mengejarnya benar-benar jadi olahraga bagi para ibu!', title_ja = '速い足取り！🏃‍♂', body_ja = '️もう部屋から部屋へ自由に歩き、走ろうとすることも！追いかけるのは、ママにとって本格的な運動ですね！', title_ko = '빨라진 걸음! 🏃‍♂', body_ko = '️이제 방과 방 사이를 자유롭게 걸어 다니고, 뛰려고까지 해요. 아이를 따라잡는 건 엄마에게 진짜 운동이에요!', title_nl = 'Snelle stapjes! 🏃‍♂', body_nl = '️ Je kindje loopt nu vrij van kamer naar kamer en probeert zelfs te rennen. Hem bijhouden is voor mama''s echte sport!', title_pl = 'Szybkie kroki! 🏃‍♂', body_pl = '️ Swobodnie chodzi już między pokojami, a nawet próbuje biegać. Nadążanie za nim to dla mamy prawdziwy trening!', title_pt = 'Passos rápidos! 🏃‍♂', body_pt = '️ Já anda à vontade de uma divisão para outra e até tenta correr. Acompanhá-lo é um verdadeiro desporto para as mães!', title_sv = 'Snabba steg! 🏃‍♂', body_sv = '️ Barnet går redan fritt mellan rummen och försöker till och med springa. Att hinna ikapp är rena träningen för mammor!', title_vi = 'Những bước chân nhanh nhẹn! 🏃‍♂', body_vi = '️ Bé đã tự do đi lại giữa các phòng, thậm chí còn thử chạy. Đuổi theo bé đúng là một bài thể dục thực sự cho mẹ!', title_zh = '步子越来越快！🏃‍♂', body_zh = '️ 宝宝已经能在房间之间自由走动，甚至想跑了。对妈妈来说，追着他跑可是真正的运动！' WHERE id = '979d3d6f-0938-49ad-b47d-0cedcf8c1cf6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Dónde están tus ojos? 👀', body_es = 'El juego de reconocer las partes del cuerpo sigue siendo uno de sus favoritos. Jugad delante del espejo para hacerlo aún más divertido.', title_fr = 'Où sont tes yeux ? 👀', body_fr = 'Le jeu des parties du corps reste l''un de ses préférés. Faites-le devant le miroir pour le rendre encore plus amusant.', title_hi = 'आँख कहाँ है? 👀', body_hi = 'शरीर के अंग पहचानने का खेल अब भी उसके सबसे पसंदीदा खेलों में से एक है। इसे आईने के सामने खेलकर और मज़ेदार बनाइए।', title_id = 'Matanya mana? 👀', body_id = 'Permainan mengenal anggota tubuh masih jadi salah satu favoritnya. Mainkan di depan cermin agar makin seru.', title_ja = 'おめめはどこ？👀', body_ja = '体の部分を当てる遊びは、今もお気に入りのひとつ。鏡の前でやると、もっと楽しくなりますよ。', title_ko = '눈 어디 있어? 👀', body_ko = '신체 부위 맞히기는 여전히 가장 좋아하는 놀이 중 하나예요. 거울 앞에서 하면 훨씬 더 재미있어요.', title_nl = 'Waar zijn je ogen? 👀', body_nl = 'Het spelletje lichaamsdelen aanwijzen is nog steeds een van zijn favorieten. Speel het voor de spiegel, dan wordt het nog leuker.', title_pl = 'Gdzie masz oko? 👀', body_pl = 'Zabawa w rozpoznawanie części ciała to wciąż jedna z jego ulubionych. Bawcie się przed lustrem, a będzie jeszcze weselej.', title_pt = 'Onde estão os olhos? 👀', body_pt = 'O jogo de reconhecer as partes do corpo continua a ser um dos preferidos. Façam-no em frente ao espelho para o tornar ainda mais divertido.', title_sv = 'Var är ögat? 👀', body_sv = 'Leken med kroppsdelar är fortfarande en av favoriterna. Gör den ännu roligare genom att leka framför spegeln.', title_vi = 'Mắt con đâu nào? 👀', body_vi = 'Trò chơi nhận biết các bộ phận cơ thể vẫn là một trong những trò bé thích nhất. Hãy chơi trước gương để thêm phần vui nhộn.', title_zh = '眼睛在哪里？👀', body_zh = '认身体部位的游戏仍然是宝宝的最爱之一。在镜子前玩，会更有意思哦。' WHERE id = '1008f62b-ef11-490d-886c-a80a06e64454' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Organizarse da tranquilidad 📝', body_es = 'Repasa con unas notas rápidas lo que harás mañana o el menú, y vete a la cama más tranquila.', title_fr = 'S''organiser, ça détend. 📝', body_fr = 'Préparez dans votre tête, avec quelques petites notes, vos tâches ou le menu de demain, puis allez vous coucher l''esprit reposé.', title_hi = 'योजना से सुकून मिलता है। 📝', body_hi = 'कल के कामों या खाने की योजना छोटे-छोटे नोट्स के साथ मन में तैयार कीजिए और सुकून से सोने जाइए।', title_id = 'Punya rencana bikin tenang. 📝', body_id = 'Siapkan dalam pikiran rencana kegiatan atau menu besok dengan beberapa catatan kecil, lalu pergilah tidur dengan perasaan tenang.', title_ja = '計画があると安心 📝', body_ja = '明日やることや献立を、小さなメモで頭の中に準備してから、すっきりした気持ちでベッドに入りましょう。', title_ko = '계획이 있으면 마음이 편해요. 📝', body_ko = '내일 할 일이나 식단 계획을 간단히 머릿속에 정리해 두고 편안한 마음으로 잠자리에 드세요.', title_nl = 'Een planning geeft rust. 📝', body_nl = 'Zet de taken of het eetplan voor morgen met een paar korte notities op een rijtje in je hoofd en ga uitgerust naar bed.', title_pl = 'Planowanie daje spokój. 📝', body_pl = 'Przygotuj w głowie z kilkoma krótkimi notatkami plan na jutro lub jadłospis i idź spać odprężona.', title_pt = 'Planear traz tranquilidade. 📝', body_pt = 'Prepare de cabeça, com pequenas notas, as tarefas ou o plano de refeições de amanhã e vá para a cama já descansada.', title_sv = 'Att planera ger ro. 📝', body_sv = 'Förbered morgondagens sysslor eller matplan med små anteckningar i huvudet och gå utvilad till sängs.', title_vi = 'Có kế hoạch giúp mẹ nhẹ nhõm. 📝', body_vi = 'Hãy chuẩn bị trong đầu những việc cần làm hay thực đơn ngày mai bằng vài ghi chú nhỏ, rồi lên giường thật thư thái.', title_zh = '有计划更安心 📝', body_zh = '在脑子里简单列好明天要做的事或饮食安排，然后安心上床休息吧。' WHERE id = '2ca5e024-95be-449a-af7e-ee34228f8bca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de calma ☕', body_es = 'A veces apetece salir de casa y cambiar de aires. Encuentra en Lugares para mamás una cafetería cercana a la que ir cómodamente con tu peque y disfruta del café.', title_fr = 'En quête de détente. ☕', body_fr = 'Parfois, vous avez envie de sortir et de changer d''air. Trouvez dans les Lieux adaptés aux mamans un café proche où aller facilement avec votre enfant, et savourez votre café.', title_hi = 'सुकून की तलाश में। ☕', body_hi = 'कभी-कभी घर से निकलकर अलग माहौल में रहने का मन करता है। माँ के लिए अनुकूल जगहों में आसपास का ऐसा कैफ़े ढूँढिए जहाँ बच्चे के साथ आराम से जा सकें, और कॉफ़ी का मज़ा लीजिए।', title_id = 'Mencari kenyamanan. ☕', body_id = 'Kadang Anda ingin keluar rumah dan berada di suasana berbeda. Temukan kafe terdekat yang nyaman dikunjungi bersama anak di Tempat Ramah Ibu dan nikmati kopinya.', title_ja = 'ほっとできる場所を探して ☕', body_ja = 'たまには家を出て、ちがう雰囲気の中で過ごしたいですよね。「ママにやさしいスポット」で、子連れで気軽に行ける近くのカフェを見つけて、コーヒーを楽しみましょう。', title_ko = '편안함을 찾아서. ☕', body_ko = '가끔은 집을 나와 다른 분위기 속에 있고 싶죠. 엄마 친화 장소에서 아이와 편하게 갈 수 있는 가까운 카페를 찾아 커피를 즐겨 보세요.', title_nl = 'Op zoek naar rust. ☕', body_nl = 'Soms wil je gewoon even de deur uit en ergens anders zijn. Zoek in Mamavriendelijke plekken een kindvriendelijk café in de buurt en geniet van je koffie.', title_pl = 'W poszukiwaniu wygody. ☕', body_pl = 'Czasem chcesz wyjść z domu i zmienić otoczenie. Znajdź w Miejscach przyjaznych mamom pobliską kawiarnię, do której wygodnie pójdziesz z dzieckiem, i delektuj się kawą.', title_pt = 'Em busca de conforto. ☕', body_pt = 'Às vezes apetece sair de casa e estar noutro ambiente. Encontre nos Locais Amigos das Mães um café perto onde possa ir à vontade com a criança e saboreie o seu café.', title_sv = 'På jakt efter ro. ☕', body_sv = 'Ibland vill du ut och vara i en annan miljö. Hitta ett barnvänligt kafé i närheten i Mammavänliga platser och njut av kaffet.', title_vi = 'Đi tìm sự thoải mái. ☕', body_vi = 'Đôi khi mẹ muốn ra khỏi nhà và đổi gió. Hãy tìm một quán cà phê gần đó, tiện đưa bé đi cùng trong Địa điểm thân thiện với mẹ và thưởng thức cà phê.', title_zh = '寻找片刻舒适 ☕', body_zh = '有时候你就是想出门，换个环境。在妈妈友好场所里找一家附近适合带娃的咖啡馆，享受一杯咖啡吧。' WHERE id = 'efb1280f-e8f0-4ecf-bb77-385f667aff5d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En cuanto oye un sonido rítmico en la tele, mueve el culete. ¡Su percepción musical se despierta, baila con él!', body_fr = 'Dès qu''il entend un son rythmé à la télé, il se dandine. Son sens de la musique s''éveille, dansez avec lui !', body_hi = 'टीवी पर कोई लयबद्ध आवाज़ सुनते ही वह कमर मटकाने लगता है। संगीत की समझ जाग रही है, उसके साथ नाचिए!', body_id = 'Begitu mendengar suara berirama di TV, ia langsung menggoyangkan pantatnya. Kepekaan musiknya mulai bekerja, ayo ikut berjoget bersamanya!', body_ja = 'テレビからリズミカルな音が聞こえると、すぐにおしりをふりふり。音楽を感じる力が育っています。一緒に踊りましょう！', body_ko = 'TV에서 리듬감 있는 소리가 들리자마자 엉덩이를 흔들어요. 음악 감각이 깨어나고 있어요, 함께 춤춰 주세요!', body_nl = 'Zodra je kindje een ritmisch geluid op tv hoort, wiebelt hij met zijn billetjes. Hij gaat muziek begrijpen, dans lekker mee!', body_pl = 'Gdy tylko usłyszy w telewizji rytmiczny dźwięk, kręci pupą. Budzi się wyczucie muzyki, tańcz razem z nim!', body_pt = 'Mal ouve um som com ritmo na televisão, começa a abanar o rabinho. A perceção musical está a despertar, junte-se e dance com ele!', body_sv = 'Så fort barnet hör ett rytmiskt ljud på TV:n vickar det på rumpan. Musikkänslan vaknar, dansa med!', body_vi = 'Vừa nghe thấy âm thanh có nhịp điệu trên TV là bé lắc mông. Khả năng cảm thụ âm nhạc đang khởi động, hãy cùng nhảy với bé nhé!', body_zh = '电视里一响起有节奏的声音，宝宝就扭起小屁股。音乐感知开始启动了，跟他一起跳吧！' WHERE id = '8edf71cc-a90b-4465-947f-070adc35b5f7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahogo emocional 📝', body_es = 'A veces todo se hace cuesta arriba. Escribe en el Diario de ánimo lo que sientes y lo cansada que estás, y suelta el estrés del día.', title_fr = 'Lâcher prise. 📝', body_fr = 'Parfois, c''est trop. Évacuez le stress de la journée en écrivant dans le Journal d''humeur ce que vous ressentez et votre fatigue.', title_hi = 'मन का बोझ हल्का करना। 📝', body_hi = 'कभी-कभी सब कुछ बहुत भारी लग सकता है। मन की बातें और थकान मूड डायरी में लिखकर दिन का तनाव निकाल दीजिए।', title_id = 'Melepaskan emosi. 📝', body_id = 'Kadang semuanya terasa terlalu berat. Lepaskan stres hari ini dengan menuliskan isi hati dan rasa lelah Anda di Buku Harian Suasana Hati.', title_ja = '気持ちを吐き出そう 📝', body_ja = '何もかもが重く感じることもあります。「気分日記」に思っていることや疲れを書き出して、一日のストレスを手放しましょう。', title_ko = '감정을 털어놓기. 📝', body_ko = '가끔은 모든 게 버겁게 느껴질 수 있어요. 기분 일기에 마음속 이야기와 피로를 적으며 하루의 스트레스를 덜어 내세요.', title_nl = 'Je gevoelens loslaten. 📝', body_nl = 'Soms wordt alles even te veel. Schrijf in je Stemmingsdagboek wat je bezighoudt en hoe moe je bent, en laat de stress van de dag los.', title_pl = 'Emocjonalne odreagowanie. 📝', body_pl = 'Czasem wszystkiego jest za dużo. Wypisz w Dzienniku nastroju, co czujesz i jak bardzo jesteś zmęczona, i zrzuć z siebie stres dnia.', title_pt = 'Desabafo emocional. 📝', body_pt = 'Às vezes tudo pode ser demasiado. Liberte o stress do dia escrevendo no Diário de Humor o que lhe vai na alma e o seu cansaço.', title_sv = 'Känslomässig urladdning. 📝', body_sv = 'Ibland kan allt bli för mycket. Skriv av dig tankarna och tröttheten i Humördagboken och släpp dagens stress.', title_vi = 'Giải tỏa cảm xúc. 📝', body_vi = 'Đôi khi mọi thứ trở nên quá sức. Hãy viết những điều trong lòng và sự mệt mỏi vào Nhật ký tâm trạng để trút bỏ căng thẳng trong ngày.', title_zh = '释放情绪 📝', body_zh = '有时候一切都会让人喘不过气。把心里的想法和疲惫写进心情日记，卸下一天的压力。' WHERE id = 'c0c8236b-5e7c-45b1-a5c1-d45f005b603c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Besos al aire! 👋', body_es = '¿Ya dice adiós con la mano conscientemente y manda besos a quien se va? Disfruta de estos gestos tan tiernos y sociables.', title_fr = 'Des bisous volants ! 👋', body_fr = 'Il fait déjà consciemment au revoir de la main et envoie des bisous à ceux qui partent ? Savourez ce geste adorable et sociable.', title_hi = 'हवा में चुम्मियाँ! 👋', body_hi = 'क्या अब वह जाने वालों को समझते हुए हाथ हिलाकर बाय करता है और फ़्लाइंग किस भेजता है? उसकी इस प्यारी और सामाजिक हरकत का आनंद लीजिए।', title_id = 'Ciuman jauh! 👋', body_id = 'Ia sudah sadar melambaikan tangan dan mengirim ciuman kepada orang yang pergi? Nikmati gerakan sosial yang menggemaskan ini.', title_ja = '投げキッス！👋', body_ja = '帰っていく人に、わかっていて手を振ったり投げキッスをしたりしますか？このかわいくて社交的なしぐさを楽しみましょう。', title_ko = '날아가는 뽀뽀! 👋', body_ko = '이제 떠나는 사람에게 스스로 손을 흔들고 뽀뽀를 날리나요? 이 사랑스럽고 사교적인 행동을 마음껏 즐기세요.', title_nl = 'Kushandjes! 👋', body_nl = 'Zwaait je kindje nu bewust naar mensen die weggaan en geeft hij kushandjes? Geniet van dit lieve, sociale gebaar.', title_pl = 'Całuski w powietrzu! 👋', body_pl = 'Świadomie macha już na pożegnanie i posyła całuski? Ciesz się tymi uroczymi gestami społecznymi.', title_pt = 'Beijinhos no ar! 👋', body_pt = 'Já diz adeus com a mão e manda beijinhos, de forma consciente, a quem se vai embora? Aproveite este gesto social tão querido.', title_sv = 'Slängkyssar! 👋', body_sv = 'Vinkar barnet redan medvetet efter dem som går och skickar pussar? Njut av denna söta och sociala gest.', title_vi = 'Những nụ hôn gió! 👋', body_vi = 'Bé đã có ý thức vẫy tay và gửi nụ hôn gió theo người ra về? Hãy tận hưởng hành động đáng yêu và đầy tính xã hội này của bé.', title_zh = '飞吻！👋', body_zh = '宝宝已经会有意识地向离开的人挥手、送飞吻了？好好享受这个可爱的社交小动作吧。' WHERE id = '4c8a3a5d-e5df-48ed-823d-41dd50a6bc1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de los Cuentos inteligentes 🪄', title_fr = 'La magie des Contes intelligents 🪄', title_hi = 'स्मार्ट कहानी का जादू 🪄', title_id = 'Keajaiban Dongeng Pintar 🪄', title_ja = '「スマートおはなし」の魔法 🪄', title_ko = '스마트 동화의 마법 🪄', title_nl = 'De magie van een slim sprookje 🪄', title_pl = 'Magia Mądrej bajki 🪄', title_pt = 'A magia das Histórias Inteligentes 🪄', title_sv = 'Den smarta sagans magi 🪄', title_vi = 'Phép màu của Truyện cổ tích thông minh 🪄', title_zh = '智能故事的魔力 🪄' WHERE id = 'c46434f8-d6b6-4038-89e7-8bc38a5332c2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un baño relajante 🛁', body_es = 'Un baño templado es divertido para soltar la energía del día y además relaja los músculos y le prepara perfectamente para dormir.', title_fr = 'Un bain apaisant. 🛁', body_fr = 'Un bain tiède est amusant pour évacuer l''énergie de la journée, et il détend ses muscles pour bien le préparer au sommeil.', title_hi = 'सुकून देने वाला स्नान। 🛁', body_hi = 'गुनगुना स्नान दिनभर की ऊर्जा निकालने के लिए मज़ेदार भी है और मांसपेशियों को आराम देकर नींद के लिए पूरी तरह तैयार भी करता है।', title_id = 'Mandi yang menenangkan. 🛁', body_id = 'Mandi air hangat tidak hanya seru untuk menyalurkan energi seharian, tapi juga melemaskan otot dan membuatnya siap tidur.', title_ja = '心落ち着くお風呂 🛁', body_ja = 'ぬるめのお風呂は、一日のエネルギーを発散する楽しい時間であり、筋肉をほぐして眠りへの準備もばっちり整えてくれます。', title_ko = '마음을 달래 주는 목욕. 🛁', body_ko = '따뜻한 목욕은 하루의 에너지를 발산하는 즐거운 시간이자, 근육을 풀어 잠들 준비를 완벽하게 해 줘요.', title_nl = 'Een rustgevend badje. 🛁', body_nl = 'Een lauw badje is leuk om de energie van de dag kwijt te raken, ontspant de spieren en maakt je kindje perfect klaar om te slapen.', title_pl = 'Kojąca kąpiel. 🛁', body_pl = 'Ciepła kąpiel to zabawny sposób na wyładowanie energii całego dnia, a przy tym rozluźnia mięśnie i idealnie przygotowuje do snu.', title_pt = 'Um banho calmante. 🛁', body_pt = 'Um banho morno é divertido para gastar a energia do dia e, ao mesmo tempo, relaxa os músculos e prepara-o na perfeição para dormir.', title_sv = 'Lugnande bad. 🛁', body_sv = 'Ett ljummet bad är både roligt för att få ut dagens energi och avslappnande för musklerna, så att barnet blir perfekt förberett för sömnen.', title_vi = 'Tắm thư giãn. 🛁', body_vi = 'Tắm nước ấm vừa là trò vui để xả năng lượng cả ngày, vừa giúp cơ bắp thư giãn và chuẩn bị hoàn hảo cho giấc ngủ.', title_zh = '舒缓的洗澡时间 🛁', body_zh = '温水澡既能好玩地释放一天的精力，又能放松肌肉，为入睡做好准备。' WHERE id = '9e41eb2a-f9ac-4f4c-8455-0ad7cfd405e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Imitamos palabras! 🗣', body_es = '️ ¿Intenta imitar las palabras que dices o los sonidos de los animales? Recibe estos intentos con entusiasmo para que crezcan sus ganas de expresarse.', title_fr = 'On imite les mots ! 🗣', body_fr = '️ Il essaie de répéter vos mots ou d''imiter les cris des animaux ? Accueillez ces essais avec enthousiasme pour renforcer son envie de s''exprimer.', title_hi = 'शब्दों की नकल! 🗣', body_hi = '️ आपके बोले शब्दों या जानवरों की आवाज़ों की नकल करने की कोशिश करता है? इन कोशिशों का उत्साह से स्वागत कीजिए, ताकि खुद को व्यक्त करने की उसकी चाह बढ़े।', title_id = 'Meniru kata-kata! 🗣', body_id = '️ Ia mencoba meniru kata-kata Anda atau suara hewan? Sambut usahanya dengan antusias agar keinginannya mengungkapkan diri makin besar.', title_ja = '言葉をまねっこ！🗣', body_ja = '️あなたが言った言葉や動物の鳴き声をまねしようとしていますか？自分を表現したい気持ちが育つよう、その挑戦をうれしそうに受け止めてあげましょう。', title_ko = '말을 따라 해요! 🗣', body_ko = '️엄마가 하는 말이나 동물 소리를 흉내 내려 하나요? 이런 시도를 반갑게 받아 주면 자신을 표현하고 싶은 마음이 커져요.', title_nl = 'We doen woorden na! 🗣', body_nl = '️ Probeert je kindje woorden of dierengeluiden die jij zegt na te doen? Reageer er enthousiast op, dan groeit zijn zin om zich te uiten.', title_pl = 'Naśladujemy słowa! 🗣', body_pl = '️ Próbuje powtarzać twoje słowa lub odgłosy zwierząt? Przyjmuj te próby z entuzjazmem, by rosła jego chęć wyrażania siebie.', title_pt = 'A imitar palavras! 🗣', body_pt = '️ Tenta imitar as palavras que diz ou os sons dos animais? Receba estas tentativas com entusiasmo, para que a vontade de se expressar aumente.', title_sv = 'Vi härmar ord! 🗣', body_sv = '️ Försöker barnet härma orden du säger eller djurläten? Möt försöken med entusiasm så att lusten att uttrycka sig växer.', title_vi = 'Bé bắt chước từ ngữ! 🗣', body_vi = '️ Bé cố bắt chước những từ mẹ nói hay tiếng kêu của con vật? Hãy hào hứng đón nhận những lần thử này để bé thêm muốn thể hiện bản thân.', title_zh = '学说话啦！🗣', body_zh = '️ 宝宝在模仿你说的词或动物的叫声？热情地回应这些尝试，让他更想表达自己。' WHERE id = 'd452b163-e134-4c64-90b8-7e561b20c6f9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del ruido blanco 🎶', body_es = 'Si después de un día tan activo no consigue dormirse, pon el sonido del mar o de la lluvia en Ruido blanco y crea calma en la habitación.', title_fr = 'La force des bruits blancs. 🎶', body_fr = 'Il n''arrive pas à dormir après une journée active ? Lancez le bruit de l''océan ou de la pluie dans les Bruits blancs pour apaiser la chambre.', title_hi = 'व्हाइट नॉइज़ की ताकत। 🎶', body_hi = 'अगर भाग-दौड़ भरे दिन के असर से वह सो नहीं पा रहा, तो कमरे में व्हाइट नॉइज़ से समुद्र या बारिश की आवाज़ चलाकर शांति बनाइए।', title_id = 'Kekuatan suara putih. 🎶', body_id = 'Kalau ia sulit tidur setelah hari yang aktif, ciptakan ketenangan di kamar dengan memutar suara ombak atau hujan dari Suara Putih.', title_ja = 'ホワイトノイズの力 🎶', body_ja = '活発に過ごした日で寝つけないときは、「ホワイトノイズ」から海や雨の音を流して、部屋を穏やかな雰囲気にしましょう。', title_ko = '백색소음의 힘. 🎶', body_ko = '활발한 하루 때문에 잠들지 못한다면 백색소음에서 파도나 빗소리를 틀어 방을 차분하게 만들어 주세요.', title_nl = 'De kracht van witte ruis. 🎶', body_nl = 'Kan je kindje na een drukke dag niet slapen? Zet in Witte ruis het geluid van de oceaan of regen aan en breng rust in de kamer.', title_pl = 'Moc białego szumu. 🎶', body_pl = 'Jeśli po aktywnym dniu nie może zasnąć, włącz w pokoju odgłos oceanu lub deszczu z Białego szumu i stwórz spokojną atmosferę.', title_pt = 'A força do Ruído Branco. 🎶', body_pt = 'Se não consegue adormecer por causa de um dia agitado, ligue no quarto o som do mar ou da chuva no Ruído Branco e crie tranquilidade.', title_sv = 'Kraften i vitt brus. 🎶', body_sv = 'Om barnet inte kan sova efter en aktiv dag, skapa lugn i rummet genom att sätta på havs- eller regnljud i Vitt brus.', title_vi = 'Sức mạnh của tiếng ồn trắng. 🎶', body_vi = 'Nếu bé không ngủ được sau một ngày hiếu động, hãy bật tiếng sóng biển hoặc tiếng mưa trong Tiếng ồn trắng để căn phòng thêm yên bình.', title_zh = '白噪音的力量 🎶', body_zh = '如果玩了一整天兴奋得睡不着，就在房间里用白噪音放海浪声或雨声，营造安静的氛围。' WHERE id = '72ba71ca-1652-48f5-bc29-c321459f659a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla entre mamás 💬', title_fr = 'Entre mamans 💬', title_hi = 'माँओं की दिल की बातें 💬', title_id = 'Curhat sesama ibu 💬', title_ja = 'ママ同士のおしゃべり 💬', title_ko = '엄마들의 수다 💬', title_nl = 'Moeders onder elkaar 💬', title_pl = 'Mamy rozmawiają 💬', title_pt = 'Conversa entre mães 💬', title_sv = 'Mammasnack 💬', title_vi = 'Các mẹ tâm sự 💬', title_zh = '妈妈们的知心话 💬' WHERE id = '0db41c26-c87d-4bd7-8650-e9fd07449904' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recarga para mamá 🔋', body_es = '¿El ajetreo del día te ha dejado sin energía? Criar olvidándote de ti misma no es heroico. Déjale en un lugar seguro y tómate 10 minutos de pausa para un café.', title_fr = 'Recharge pour maman 🔋', body_fr = 'Le tourbillon de la journée a aspiré votre énergie ? S''oublier en élevant son enfant n''a rien d''héroïque. Installez-le dans un endroit sûr et faites une pause café de 10 minutes.', title_hi = 'माँ के लिए चार्जिंग 🔋', body_hi = 'दिन की भागदौड़ ने आपकी ऊर्जा सोख ली? खुद को भूलकर बच्चा पालना बहादुरी नहीं है। उसे किसी सुरक्षित जगह रखिए और 10 मिनट का कॉफ़ी ब्रेक लीजिए।', title_id = 'Isi ulang energi untuk Bunda 🔋', body_id = 'Kesibukan siang hari menguras energi Anda? Membesarkan anak sambil melupakan diri sendiri bukanlah kepahlawanan. Letakkan ia di tempat yang aman dan ambil rehat kopi 10 menit.', title_ja = 'ママのエネルギー充電 🔋', body_ja = '日中の慌ただしさでエネルギーを吸い取られましたか？自分を忘れて子育てするのは、ヒーローではありません。お子さんを安全な場所に置いて、10分間のコーヒーブレイクをとりましょう。', title_ko = '엄마를 위한 충전 🔋', body_ko = '낮 동안 바쁘게 뛰어다니느라 기운이 다 빠졌나요? 나를 잊고 육아하는 건 영웅적인 일이 아니에요. 아이를 안전한 곳에 두고 10분 동안 커피 한 잔의 여유를 가지세요.', title_nl = 'Opladen voor mama 🔋', body_nl = 'Heeft de drukte van de dag al je energie opgeslokt? Jezelf vergeten tijdens het opvoeden is geen heldendom. Zet je kindje op een veilige plek en neem 10 minuten koffiepauze.', title_pl = 'Ładowanie baterii dla mamy 🔋', body_pl = 'Dzienna bieganina wyssała z ciebie energię? Wychowywanie dziecka kosztem zapominania o sobie to nie bohaterstwo. Zostaw go w bezpiecznym miejscu i zrób sobie 10 minut przerwy na kawę.', title_pt = 'Recarregar a mãe 🔋', body_pt = 'A correria do dia sugou-lhe a energia? Criar um filho esquecendo-se de si não é heroísmo. Deixe-o num sítio seguro e faça uma pausa de 10 minutos para um café.', title_sv = 'Laddning för mamma 🔋', body_sv = 'Har dagens stress sugit ut din energi? Att uppfostra ett barn och glömma bort sig själv är inte hjältemod. Sätt barnet på en säker plats och ta en 10 minuters kaffepaus.', title_vi = 'Sạc pin cho mẹ 🔋', body_vi = 'Bộn bề ban ngày đã rút cạn năng lượng của mẹ? Quên bản thân để nuôi con không phải là anh hùng đâu. Hãy để bé ở nơi an toàn và nghỉ uống cà phê 10 phút nhé.', title_zh = '给妈妈充电 🔋', body_zh = '白天的忙乱吸干了你的能量？忘记自己去养孩子并不是英雄行为。把他放在安全的地方，喝杯咖啡休息10分钟吧。' WHERE id = 'ad8a8472-f316-41bd-82ab-7d5720d810ee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de recargar energía 🍎', body_es = 'Mientras duerme, cierra tú también los ojos 20 minutos. Las tareas de casa no se acaban nunca, pero tu energía sí. Cuídate.', title_fr = 'L''heure de recharger les batteries. 🍎', body_fr = 'Pendant qu''il dort, fermez vous aussi les yeux 20 minutes. Les tâches ménagères ne finissent jamais, mais votre énergie, elle, peut s''épuiser. Protégez-vous.', title_hi = 'ऊर्जा लौटाने का समय। 🍎', body_hi = 'बच्चा सोए तो आप भी 20 मिनट आँखें बंद कीजिए। घर के काम कभी खत्म नहीं होते, लेकिन आपकी ऊर्जा खत्म हो सकती है। अपना ख्याल रखिए।', title_id = 'Waktunya memulihkan energi. 🍎', body_id = 'Saat si kecil tidur, pejamkan juga mata Anda selama 20 menit. Pekerjaan rumah tidak ada habisnya, tapi energi Anda bisa habis. Jaga diri Anda.', title_ja = 'エネルギー回復の時間 🍎', body_ja = 'お子さんが寝ている間、あなたも20分目を閉じましょう。家事は終わりませんが、あなたのエネルギーは尽きてしまいます。自分を大切に。', title_ko = '에너지 충전 시간. 🍎', body_ko = '아이가 잘 때 엄마도 20분만 눈을 감으세요. 집안일은 끝이 없지만, 엄마의 에너지는 바닥날 수 있어요. 나를 지켜 주세요.', title_nl = 'Tijd om energie bij te tanken. 🍎', body_nl = 'Doe als je kindje slaapt ook 20 minuten je ogen dicht. Het huishouden is nooit af, maar jouw energie kan wel op raken. Zorg goed voor jezelf.', title_pl = 'Czas na odzyskanie energii. 🍎', body_pl = 'Gdy maluszek śpi, ty też zamknij oczy na 20 minut. Prace domowe się nie kończą, ale twoja energia może się skończyć. Zadbaj o siebie.', title_pt = 'Hora de recuperar energia. 🍎', body_pt = 'Enquanto ele dorme, feche também os olhos durante 20 minutos. As tarefas da casa nunca acabam, mas a sua energia pode acabar. Proteja-se.', title_sv = 'Dags att fylla på energin. 🍎', body_sv = 'Blunda du också i 20 minuter när barnet sover. Hushållssysslorna tar aldrig slut, men din energi kan göra det. Ta hand om dig själv.', title_vi = 'Giờ nạp lại năng lượng. 🍎', body_vi = 'Khi bé ngủ, mẹ cũng nhắm mắt 20 phút nhé. Việc nhà không bao giờ hết, nhưng năng lượng của mẹ thì có thể cạn. Hãy bảo vệ bản thân.', title_zh = '恢复能量的时间 🍎', body_zh = '宝宝睡觉时，你也闭上眼睛休息20分钟。家务永远做不完，但你的能量会耗尽。保护好自己。' WHERE id = '449d1eaf-e90d-45bb-8ac5-83cc8e44397d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu asistente inteligente 🤖', body_es = '¿Por qué ha perdido el apetito de repente? Escribe a Anacan AI esta y otras preguntas que te preocupen y recibe al momento una respuesta con base científica.', title_fr = 'Votre assistant intelligent 🤖', body_fr = 'Pourquoi a-t-il soudain perdu l''appétit ? Posez cette question, ou toute autre qui vous inquiète, à Anacan AI et obtenez tout de suite une réponse fondée sur la science.', title_hi = 'आपका स्मार्ट असिस्टेंट 🤖', body_hi = 'बच्चे की भूख अचानक क्यों कम हो गई? यह या कोई और परेशान करने वाला सवाल Anacan AI को लिखिए और तुरंत वैज्ञानिक जवाब पाइए।', title_id = 'Asisten pintar Anda 🤖', body_id = 'Kenapa nafsu makannya tiba-tiba turun? Tulis pertanyaan ini atau pertanyaan lain yang membuat Anda cemas ke Anacan AI dan langsung dapatkan jawaban berbasis ilmiah.', title_ja = 'あなたのスマートアシスタント 🤖', body_ja = 'どうして急に食欲が落ちたの？こうした気になる質問はAnacan AIに書き込んで、科学的な根拠のある答えをすぐに受け取りましょう。', title_ko = '똑똑한 도우미 🤖', body_ko = '''아이가 왜 갑자기 입맛을 잃었을까?'' 이런 걱정되는 질문을 Anacan AI에게 물어 바로 과학적 근거가 있는 답을 받아 보세요.', title_nl = 'Je slimme assistent 🤖', body_nl = 'Waarom heeft je kindje ineens geen trek meer? Schrijf deze en andere vragen die je zorgen baren aan Anacan AI en krijg meteen een wetenschappelijk onderbouwd antwoord.', title_pl = 'Twój mądry asystent 🤖', body_pl = 'Dlaczego dziecko nagle straciło apetyt? Napisz do Anacan AI z tym lub innym niepokojącym pytaniem i od razu otrzymaj odpowiedź opartą na nauce.', title_pt = 'O seu assistente inteligente 🤖', body_pt = 'Porque é que a criança perdeu de repente o apetite? Escreva esta ou outras perguntas que a preocupem ao Anacan AI e receba já uma resposta com base científica.', title_sv = 'Din smarta assistent 🤖', body_sv = 'Varför har barnet plötsligt tappat aptiten? Skriv den här och andra oroande frågor till Anacan AI och få direkt ett vetenskapligt grundat svar.', title_vi = 'Trợ lý thông minh của mẹ 🤖', body_vi = 'Sao bé bỗng dưng biếng ăn? Hãy hỏi Anacan AI câu hỏi này hay bất kỳ điều gì khiến mẹ lo lắng và nhận ngay câu trả lời có cơ sở khoa học.', title_zh = '你的智能助手 🤖', body_zh = '孩子为什么突然没胃口了？把这个或其他让你担心的问题发给Anacan AI，马上获得有科学依据的回答。' WHERE id = '9c6e1121-6b3a-4988-b52a-daff7cb47017' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un fondo mágico para la noche 🪄', title_fr = 'Une ambiance de nuit magique 🪄', title_hi = 'जादुई रात का बैकग्राउंड 🪄', title_id = 'Latar malam yang ajaib 🪄', title_ja = '魔法の夜のBGM 🪄', title_ko = '마법 같은 밤의 배경음 🪄', title_nl = 'Een magische achtergrond voor de nacht 🪄', title_pl = 'Magiczne tło na noc 🪄', title_pt = 'Um fundo mágico para a noite 🪄', title_sv = 'Magisk nattbakgrund 🪄', title_vi = 'Không gian đêm kỳ diệu 🪄', title_zh = '魔法夜晚背景 🪄' WHERE id = '4cba464d-475d-46de-93c9-1a54b6d0a768' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue órdenes sencillas 🧸', body_es = '¿Cuando le dices «Trae los zapatos» de verdad va a buscarlos? ¡Su vocabulario y su comprensión están en plena forma! Hazle participar más en los juegos.', title_fr = 'Il suit des consignes simples 🧸', body_fr = 'Quand vous dites « Apporte tes chaussures », il va vraiment les chercher ? Son vocabulaire et sa compréhension sont au top ! Impliquez-le davantage dans vos jeux.', title_hi = 'आसान बातें मानता है 🧸', body_hi = '''जूते लाओ'' कहने पर सच में जाकर ले आता है? शब्द भंडार और समझने की क्षमता चरम पर है! उसे खेलों में और शामिल कीजिए।', title_id = 'Mengikuti perintah sederhana 🧸', body_id = 'Saat Anda bilang "Ambil sepatunya", ia benar-benar pergi mengambilnya? Kosakata dan kemampuan memahaminya sedang di puncak! Ajak ia lebih sering bermain.', title_ja = '簡単なお願いがわかる 🧸', body_ja = '「靴を持ってきて」と言うと、本当に取ってきてくれますか？語彙も理解力もぐんぐん伸びています！遊びにもっと誘ってあげましょう。', title_ko = '간단한 말을 알아듣고 해내요 🧸', body_ko = '"신발 가져와" 하면 정말 가서 가져오나요? 어휘력과 이해력이 최고조예요! 놀이에 더 많이 참여시켜 주세요.', title_nl = 'Voert eenvoudige opdrachtjes uit 🧸', body_nl = 'Haalt je kindje echt zijn schoenen als je zegt: breng je schoenen? Zijn woordenschat en begrip groeien enorm! Betrek hem meer bij spelletjes.', title_pl = 'Wykonuje proste polecenia 🧸', body_pl = 'Na „Przynieś buty” naprawdę idzie i je przynosi? Zasób słów i rozumienie są na szczycie! Częściej angażuj go w zabawy.', title_pt = 'Cumpre ordens simples 🧸', body_pt = 'Quando lhe diz "Traz os sapatos", vai mesmo buscá-los? O vocabulário e a compreensão estão no auge! Envolva-o mais nas brincadeiras.', title_sv = 'Följer enkla instruktioner 🧸', body_sv = 'Går barnet verkligen och hämtar skorna när du säger ”Hämta skorna”? Ordförrådet och förståelsen är på topp! Låt barnet vara med mer i lekarna.', title_vi = 'Bé làm theo yêu cầu đơn giản 🧸', body_vi = 'Mẹ nói "Mang giày lại đây" là bé đi lấy thật? Vốn từ và khả năng hiểu đang ở đỉnh cao! Hãy cho bé tham gia các trò chơi nhiều hơn.', title_zh = '能听懂简单指令了 🧸', body_zh = '你说“把鞋拿来”，宝宝真的会去拿？词汇量和理解能力正处于高峰！多让宝宝参与游戏吧。' WHERE id = 'dd84435f-c5e3-4339-9062-61f9c8648898' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se te ha acabado la paciencia? Cierra la puerta de la habitación y deja a tu peque a solas con papá. Que esta noche sea él quien mande en el parque de juegos de casa.', body_fr = 'Vous êtes à bout de patience ? Fermez la porte de la pièce et laissez l''enfant seul avec son papa. Ce soir, c''est lui le chef de l''aire de jeux de la maison.', body_hi = 'धैर्य खत्म हो गया? कमरे का दरवाज़ा बंद कीजिए और बच्चे को उसके पापा के साथ अकेला छोड़ दीजिए। आज शाम घर के प्ले पार्क के बॉस वही हों।', body_id = 'Kesabaran habis? Tutup pintu kamar dan biarkan si kecil berdua saja dengan ayahnya. Malam ini, biar ia yang jadi pemimpin taman bermain di rumah.', body_ja = 'がまんの限界？部屋のドアを閉めて、お子さんをパパに任せましょう。今夜は家の遊び場のリーダーはパパです。', body_ko = '인내심이 바닥났나요? 방문을 닫고 아이를 아빠와 단둘이 두세요. 오늘 저녁 집 안 놀이터의 대장은 아빠예요.', body_nl = 'Is je geduld op? Doe de deur dicht en laat je kindje alleen met papa. Laat hem vanavond de baas zijn van de speeltuin thuis.', body_pl = 'Skończyła ci się cierpliwość? Zamknij drzwi pokoju i zostaw malucha samego z tatą. Niech dziś wieczorem to on rządzi domowym placem zabaw.', body_pt = 'A paciência acabou? Feche a porta do quarto e deixe a criança sozinha com o pai. Esta noite, ele que seja o chefe do parque infantil lá de casa.', body_sv = 'Har tålamodet tagit slut? Stäng dörren och lämna barnet ensamt med pappa. Låt honom vara chef över hemmets lekpark i kväll.', body_vi = 'Mẹ hết kiên nhẫn rồi? Hãy đóng cửa phòng và để bé chơi riêng với bố. Tối nay hãy để bố làm "trưởng khu vui chơi" trong nhà.', body_zh = '耐心用完了？关上房门，让宝宝和爸爸单独待一会儿。今晚就让爸爸当家里游乐园的负责人吧。' WHERE id = 'd14775e1-8a41-4689-87c3-351bcaa01c87' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Olas que calman 🌊', body_es = '¿No consigue dormirse después de un día lleno de descubrimientos? Elige el sonido de las olas del mar en Ruido blanco y crea una calma mágica en la habitación.', title_fr = 'Des vagues apaisantes 🌊', body_fr = 'Il n''arrive pas à dormir après une journée pleine de découvertes ? Choisissez les vagues de l''océan dans les Bruits blancs et créez un calme magique dans la chambre.', title_hi = 'शांत करने वाली लहरें 🌊', body_hi = 'खोजबीन भरे दिन के बाद सो नहीं पा रहा? व्हाइट नॉइज़ में समुद्र की लहरें चुनिए और कमरे में जादुई शांति बनाइए।', title_id = 'Ombak yang menenangkan 🌊', body_id = 'Ia tidak bisa tidur setelah hari penuh penjelajahan? Pilih suara ombak laut dari Suara Putih dan ciptakan keheningan ajaib di kamar.', title_ja = '心落ち着く波の音 🌊', body_ja = '活発な発見でいっぱいの一日のあと、なかなか眠れない？「ホワイトノイズ」から波の音を選んで、部屋に魔法のような静けさをつくりましょう。', title_ko = '마음을 달래 주는 파도 🌊', body_ko = '활발한 탐험으로 가득한 하루 뒤에 잠들지 못하나요? 백색소음에서 파도 소리를 골라 방에 마법 같은 고요함을 만들어 주세요.', title_nl = 'Rustgevende golven 🌊', body_nl = 'Kan je kindje niet slapen na een dag vol ontdekkingen? Kies in Witte ruis de golven van de oceaan en zorg voor een magische stilte in de kamer.', title_pl = 'Kojące fale 🌊', body_pl = 'Nie może zasnąć po dniu pełnym aktywnych odkryć? Wybierz w Białym szumie fale oceanu i stwórz w pokoju magiczną ciszę.', title_pt = 'Ondas calmantes 🌊', body_pt = 'Não consegue dormir depois de um dia cheio de descobertas? Escolha o som das ondas do mar no Ruído Branco e crie no quarto uma calma mágica.', title_sv = 'Lugnande vågor 🌊', body_sv = 'Kan barnet inte sova efter en dag full av aktiva upptäckter? Välj havsvågor i Vitt brus och skapa en magisk stillhet i rummet.', title_vi = 'Những con sóng êm dịu 🌊', body_vi = 'Bé không ngủ được sau một ngày đầy khám phá sôi nổi? Hãy chọn tiếng sóng biển trong Tiếng ồn trắng để tạo một không gian tĩnh lặng kỳ diệu trong phòng.', title_zh = '舒缓的海浪 🌊', body_zh = '探索了一整天，兴奋得睡不着？在白噪音里选海浪声，在房间里营造一种魔法般的宁静。' WHERE id = 'f9ac9f1e-0a4a-473c-909e-2a7e500a27b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comida nueva, reacción nueva 💩', body_es = '¿Ayer comió algo diferente o que puede dar alergia? Al cambiar el pañal de la mañana, observa la caca, anota en la app los cambios de color o consistencia y controla la situación.', title_fr = 'Nouvel aliment, nouvelle réaction 💩', body_fr = 'Il a mangé hier quelque chose de nouveau ou d''allergisant ? Lors du change du matin, observez les selles et notez les changements de couleur ou de consistance dans l''application pour surveiller la situation.', title_hi = 'नया खाना, नई प्रतिक्रिया 💩', body_hi = 'कल उसने कुछ अलग या एलर्जी वाला खाया? सुबह का डायपर बदलते समय पॉटी पर नज़र रखिए और रंग/गाढ़ेपन के बदलाव ऐप में दर्ज करके स्थिति पर नियंत्रण रखिए।', title_id = 'Makanan baru, reaksi baru 💩', body_id = 'Kemarin ia makan sesuatu yang berbeda atau berpotensi alergi? Saat mengganti popok pagi, perhatikan BAB-nya dan catat perubahan warna/kepadatannya di aplikasi untuk memantau kondisinya.', title_ja = '新しい食べ物、新しい反応 💩', body_ja = '昨日、いつもとちがうものやアレルギーが心配なものを食べましたか？朝のおむつ替えでうんちを観察し、色やかたさの変化をアプリに記録して様子を見守りましょう。', title_ko = '새 음식, 새 반응 💩', body_ko = '어제 색다르거나 알레르기를 일으킬 수 있는 음식을 먹었나요? 아침 기저귀를 갈 때 변을 살피고 색과 굳기 변화를 앱에 기록해 상태를 확인하세요.', title_nl = 'Nieuw eten, nieuwe reactie 💩', body_nl = 'Heeft je kindje gisteren iets nieuws of iets allergeens gegeten? Bekijk bij het verschonen van de ochtendluier de ontlasting, noteer veranderingen in kleur of dikte in de app en houd de situatie in de gaten.', title_pl = 'Nowe jedzenie, nowa reakcja 💩', body_pl = 'Wczoraj zjadł coś nowego lub potencjalnie alergizującego? Przy porannym przewijaniu obserwuj kupkę i zapisuj w aplikacji zmiany koloru/konsystencji, by kontrolować sytuację.', title_pt = 'Novo alimento, nova reação 💩', body_pt = 'Ontem comeu algo diferente ou potencialmente alergénico? Ao mudar a fralda da manhã, observe as fezes e registe na app as mudanças de cor/consistência para controlar a situação.', title_sv = 'Ny mat, ny reaktion 💩', body_sv = 'Åt barnet något annorlunda eller allergiframkallande i går? Följ bajset när du byter morgonblöjan och håll koll på läget genom att anteckna förändringar i färg och konsistens i appen.', title_vi = 'Món mới, phản ứng mới 💩', body_vi = 'Hôm qua bé ăn món mới hay món dễ gây dị ứng? Khi thay tã buổi sáng, hãy quan sát phân và ghi lại thay đổi về màu sắc, độ đặc vào ứng dụng để theo dõi tình hình.', title_zh = '新食物，新反应 💩', body_zh = '昨天吃了不一样或者可能过敏的东西？换早上的尿布时观察便便，把颜色和稠度的变化记到应用里，掌握情况。' WHERE id = 'cb4b4d68-2b36-4d3f-aa77-92d10314464f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Turnaos sin falta en los despertares nocturnos. A veces, en la oscuridad, solo las caricias rítmicas y el olor de papá le calman al instante.', body_fr = 'Pour les réveils nocturnes, relayez-vous absolument. Parfois, dans le noir, seules les caresses rythmées et l''odeur de papa l''apaisent aussitôt.', body_hi = 'रात में जागने पर बारी-बारी से ज़रूर उठिए। कभी-कभी अँधेरे में सिर्फ़ पापा का लयबद्ध सहलाना और उनकी खुशबू ही बच्चे को तुरंत शांत कर देती है।', body_id = 'Saat ia terbangun malam, pastikan bergantian. Kadang di tengah gelap, hanya usapan berirama dan aroma ayah yang langsung menenangkannya.', body_ja = '夜中に起きたら、必ず交代で対応しましょう。暗い中では、パパのリズミカルなトントンと匂いで、すぐに落ち着くこともあります。', body_ko = '밤에 깰 때는 꼭 번갈아 일어나세요. 어둠 속에서는 아빠의 리듬감 있는 토닥임과 냄새만으로 아이가 금세 진정되기도 해요.', body_nl = 'Wissel ''s nachts zeker af met opstaan. Soms kalmeert alleen papa''s ritmische geaai en geur je kindje meteen in het donker.', body_pl = 'Przy nocnych pobudkach koniecznie się zmieniajcie. Czasem w ciemności tylko rytmiczne głaskanie i zapach taty od razu uspokajają dziecko.', body_pt = 'Revezem-se sem falta nos despertares noturnos. Às vezes, no escuro, só as carícias ritmadas e o cheiro do pai acalmam a criança num instante.', body_sv = 'Turas alltid om vid nattliga uppvaknanden. Ibland är det bara pappas rytmiska smekningar och doft i mörkret som lugnar barnet direkt.', body_vi = 'Hãy thay phiên nhau khi bé thức giấc ban đêm. Đôi khi trong bóng tối, chỉ cái vỗ về nhịp nhàng và mùi hương của bố mới khiến bé dịu ngay.', body_zh = '夜醒时一定要轮流起来。有时候在黑暗中，只有爸爸有节奏的轻抚和他的气味能让宝宝立刻安静下来。' WHERE id = 'a0d7169c-229c-430c-a926-4c31eef15e2c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te has quedado sin ideas para el menú de alimentación complementaria? No te pierdas en internet: encuentra sabores nuevos en Recetas saludables.', body_fr = 'Plus d''idées pour les menus de diversification ? Ne vous perdez pas sur Internet, trouvez de nouvelles saveurs dans la rubrique Recettes saines.', body_hi = 'ऊपरी आहार के मेन्यू के आइडिया खत्म हो गए? इंटरनेट में मत खोइए, सेहतमंद रेसिपी सेक्शन में नए स्वाद खोजिए।', body_id = 'Kehabisan ide untuk menu MPASI? Jangan tersesat di internet, temukan rasa baru di bagian Resep Sehat.', body_ja = '離乳食のメニューのアイデアが尽きましたか？ネットで迷わず、「ヘルシーレシピ」で新しい味を見つけましょう。', body_ko = '이유식 메뉴 아이디어가 바닥났나요? 인터넷에서 헤매지 말고 건강한 레시피 섹션에서 새로운 맛을 찾아보세요.', body_nl = 'Geen ideeën meer voor bijvoeding? Verdwaal niet op internet, vind nieuwe smaken in het onderdeel Gezonde recepten.', body_pl = 'Kończą ci się pomysły na menu przy rozszerzaniu diety? Nie gub się w internecie, znajdź nowe smaki w sekcji Zdrowe przepisy.', body_pt = 'Ficou sem ideias para a ementa da diversificação alimentar? Não se perca na internet, encontre novos sabores nas Receitas Saudáveis.', body_sv = 'Har idéerna till menyn med fast föda tagit slut? Gå inte vilse på nätet, hitta nya smaker i avsnittet Hälsosamma recept.', body_vi = 'Hết ý tưởng cho thực đơn ăn dặm? Đừng lạc lối trên mạng, hãy tìm những món ngon mới trong mục Công thức lành mạnh.', body_zh = '辅食菜单的点子用完了？别在网上迷路了，去健康食谱板块发现新的美味吧。' WHERE id = '4e5540da-110f-46b1-a6fe-0833314d27a6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cambian las rabietas 🛑', body_es = '¿Empiezan nuevas rabietas, como tirarse al suelo? Aún no sabe gestionar sus emociones. Ponte a su altura, háblale con calma y ponle nombre a lo que siente.', title_fr = 'Les caprices évoluent 🛑', body_fr = 'De nouvelles crises commencent, comme se jeter par terre ? Il ne sait pas encore gérer ses émotions. Mettez-vous à sa hauteur et nommez ces crises en lui parlant calmement.', title_hi = 'नखरे बदल रहे हैं 🛑', body_hi = 'खुद को ज़मीन पर पटकने जैसे नए नखरे (टैंट्रम) शुरू हो गए हैं? वह अपनी भावनाएँ संभाल नहीं पाता। उसके बराबर झुककर शांति से बात करते हुए इन पलों को पार कीजिए।', title_id = 'Suasana hatinya berubah 🛑', body_id = 'Mulai muncul tantrum baru, seperti menjatuhkan diri ke lantai? Ia belum bisa mengendalikan perasaannya. Berjongkoklah setinggi dirinya, bicara dengan tenang, dan beri nama pada perasaannya.', title_ja = 'ぐずり方が変わってきた 🛑', body_ja = '床にひっくり返るような新しいかんしゃくが始まりましたか？まだ気持ちをうまくコントロールできません。目線を合わせてしゃがみ、落ち着いて気持ちを言葉にしてあげましょう。', title_ko = '떼쓰기가 달라져요 🛑', body_ko = '바닥에 드러눕는 새로운 떼쓰기(탠트럼)가 시작됐나요? 아직 감정을 다룰 줄 몰라서 그래요. 눈높이를 맞춰 몸을 숙이고 차분히 말하며 감정에 이름을 붙여 주세요.', title_nl = 'Andere buien 🛑', body_nl = 'Beginnen er nieuwe driftbuien, zoals zich op de grond gooien? Je kindje kan zijn gevoelens nog niet sturen. Zak door je knieën, praat rustig en benoem wat er gebeurt.', title_pl = 'Kaprysy się zmieniają 🛑', body_pl = 'Zaczynają się nowe napady złości, jak rzucanie się na podłogę? Maluszek nie umie jeszcze panować nad emocjami. Zniż się do jego poziomu, mów spokojnie i nazywaj te kryzysy.', title_pt = 'As birras estão a mudar 🛑', body_pt = 'Começam novas birras, como atirar-se para o chão? Ainda não consegue gerir as emoções. Baixe-se ao nível dele e, a falar com calma, dê nome a essas crises.', title_sv = 'Humöret förändras 🛑', body_sv = 'Börjar nya utbrott, som att kasta sig på golvet? Barnet kan inte hantera sina känslor. Sätt dig på barnets nivå, prata lugnt och sätt ord på utbrotten.', title_vi = 'Tính khí đang thay đổi 🛑', body_vi = 'Bé bắt đầu có những cơn ăn vạ mới như ném mình xuống sàn? Bé chưa biết kiểm soát cảm xúc. Hãy cúi xuống ngang tầm bé, nói chuyện nhẹ nhàng và gọi tên những cơn khủng hoảng ấy.', title_zh = '闹脾气升级了 🛑', body_zh = '开始出现往地上一躺这样的新崩溃（发脾气）了？宝宝还不会管理情绪。蹲到和宝宝一样的高度，平静地说出他的感受。' WHERE id = 'ae6d1371-ca56-433f-b6db-9c70c59094fb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Necesitas información sobre la motricidad de un niño de 12 meses? Pide a Anacan AI una lista breve, precisa y avalada por pediatras.', body_fr = 'Besoin d''informations sur la motricité d''un enfant de 12 mois ? Demandez à Anacan AI une liste courte, précise et validée par des pédiatres.', body_hi = '12 महीने के बच्चे की मोटर स्किल्स के बारे में जानकारी चाहिए? Anacan AI से छोटी, सटीक और बाल रोग विशेषज्ञ द्वारा पुष्ट सूची माँगिए।', body_id = 'Butuh informasi tentang kemampuan motorik anak usia 12 bulan? Minta daftar singkat, akurat, dan disetujui dokter anak dari Anacan AI.', body_ja = '1歳の子の運動能力について知りたいですか？Anacan AIに、短く正確で小児科医も認める内容のリストを聞いてみましょう。', body_ko = '12개월 아이의 운동 능력에 대한 정보가 필요한가요? Anacan AI에게 짧고 정확한, 소아과 의사가 확인한 목록을 요청하세요.', body_nl = 'Wil je meer weten over de motoriek van een kindje van 12 maanden? Vraag Anacan AI om een korte, duidelijke lijst die door kinderartsen is goedgekeurd.', body_pl = 'Potrzebujesz informacji o motoryce 12-miesięcznego dziecka? Poproś Anacan AI o krótką, rzetelną listę zatwierdzoną przez pediatrę.', body_pt = 'Precisa de informação sobre a motricidade de uma criança de 12 meses? Peça ao Anacan AI uma lista curta, precisa e validada por pediatras.', body_sv = 'Behöver du information om motoriken hos en 12 månader gammal? Be Anacan AI om en kort, exakt och barnläkargodkänd lista.', body_vi = 'Mẹ cần thông tin về kỹ năng vận động của bé 12 tháng? Hãy nhờ Anacan AI đưa ra một danh sách ngắn gọn, chính xác, đã được bác sĩ nhi khoa xác nhận.', body_zh = '想了解12个月宝宝的动作技能？请Anacan AI给你一份简短、准确、经儿科医生认可的清单。' WHERE id = '92cb503c-c013-47cb-ab12-416c047b2693' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de la fruta! 🍎', body_es = 'Para recuperar energía, prepara un plato colorido y llamativo con fruta de temporada.', title_fr = 'L''heure des fruits ! 🍎', body_fr = 'Pour lui redonner de l''énergie, préparez une assiette colorée et appétissante de fruits de saison.', title_hi = 'फलों का समय! 🍎', body_hi = 'उसकी ऊर्जा लौटाने के लिए मौसमी फलों की रंग-बिरंगी और ध्यान खींचने वाली प्लेट तैयार कीजिए।', title_id = 'Waktunya buah! 🍎', body_id = 'Untuk memulihkan energinya, siapkan piring buah musiman yang berwarna-warni dan menarik.', title_ja = 'フルーツタイム！🍎', body_ja = '元気を取り戻せるよう、旬の果物でカラフルで目を引くお皿をつくりましょう。', title_ko = '과일 시간! 🍎', body_ko = '에너지를 채울 수 있도록 제철 과일로 알록달록하고 눈길을 끄는 한 접시를 만들어 주세요.', title_nl = 'Fruittijd! 🍎', body_nl = 'Maak een kleurrijk, aantrekkelijk bord met seizoensfruit om de energie weer aan te vullen.', title_pl = 'Czas na owoce! 🍎', body_pl = 'Aby odzyskać energię, przygotuj kolorowy, przyciągający wzrok talerz sezonowych owoców.', title_pt = 'Hora da fruta! 🍎', body_pt = 'Para recuperar a energia dele, prepare um prato colorido e apelativo com fruta da época.', title_sv = 'Fruktstund! 🍎', body_sv = 'Gör en färgglad och lockande tallrik med säsongens frukter för att fylla på energin.', title_vi = 'Giờ ăn trái cây! 🍎', body_vi = 'Để nạp lại năng lượng, hãy chuẩn bị một đĩa trái cây theo mùa nhiều màu sắc và bắt mắt.', title_zh = '水果时间！🍎', body_zh = '用应季水果摆一盘色彩缤纷、吸引眼球的果盘，帮宝宝恢复能量吧。' WHERE id = '63bf2d84-bd96-49e0-9c51-b1f59bd85995' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Necesita un juguete nuevo? 🛒', body_es = 'Si buscas juguetes educativos adecuados a su edad que estimulen su mente, echa un vistazo a nuestra lista de Productos recomendados.', title_fr = 'Besoin d''un nouveau jouet ? 🛒', body_fr = 'Vous cherchez des jouets éducatifs adaptés à son âge qui stimulent son intelligence ? Jetez un œil à notre liste de Produits recommandés.', title_hi = 'नए खिलौने की ज़रूरत? 🛒', body_hi = 'अगर आप उसके विकास के हिसाब से दिमाग चलाने वाले शैक्षिक खिलौने ढूँढ रही हैं, तो हमारी सुझाए गए प्रोडक्ट की लिस्ट देखिए।', title_id = 'Butuh mainan baru? 🛒', body_id = 'Mencari mainan edukatif yang sesuai perkembangannya dan mengasah kecerdasannya? Lihat daftar Produk Rekomendasi kami.', title_ja = '新しいおもちゃが必要？🛒', body_ja = '発達に合った、頭を使う知育おもちゃを探しているなら、「おすすめ商品」リストをのぞいてみましょう。', title_ko = '새 장난감이 필요한가요? 🛒', body_ko = '발달에 맞고 두뇌를 쓰게 하는 교육용 장난감을 찾고 있다면 추천 제품 목록을 살펴보세요.', title_nl = 'Nieuw speelgoed nodig? 🛒', body_nl = 'Zoek je leerzaam speelgoed dat past bij zijn ontwikkeling en zijn hersentjes laat werken? Bekijk onze lijst Aanbevolen producten.', title_pl = 'Potrzebna nowa zabawka? 🛒', body_pl = 'Szukasz edukacyjnych zabawek dopasowanych do jego rozwoju, które pobudzą umysł? Zajrzyj do naszej listy Polecanych produktów.', title_pt = 'Precisa de um brinquedo novo? 🛒', body_pt = 'Se procura brinquedos educativos adequados ao desenvolvimento dele e que estimulem a inteligência, espreite a nossa lista de Produtos Recomendados.', title_sv = 'Behövs en ny leksak? 🛒', body_sv = 'Söker du lärorika leksaker som passar utvecklingen och får tankarna att arbeta? Titta i vår lista Rekommenderade produkter.', title_vi = 'Cần đồ chơi mới? 🛒', body_vi = 'Nếu mẹ đang tìm đồ chơi giáo dục phù hợp với sự phát triển và kích thích trí tuệ của bé, hãy xem danh sách Sản phẩm gợi ý của chúng tôi.', title_zh = '需要新玩具了？🛒', body_zh = '如果你在找适合宝宝发育阶段、能开动脑筋的益智玩具，看看我们的推荐商品清单吧。' WHERE id = 'd4a01ba0-4f2b-45a3-8cb0-3f2fa493585d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Leed un libro juntos 📖', body_es = 'Ya quiere pasar las páginas él solo. Los libros de cartón y los cuentos con sonidos son ideales para esta etapa.', title_fr = 'Lisez un livre ensemble. 📖', body_fr = 'Il veut déjà tourner les pages lui-même. Les livres cartonnés et les histoires sonores sont parfaits à cet âge.', title_hi = 'साथ में किताब पढ़िए। 📖', body_hi = 'अब वह पन्ने खुद पलटना चाहता है। मोटे पन्नों वाली किताबें और ऑडियो कहानियाँ इस दौर के लिए एकदम सही हैं।', title_id = 'Membaca buku bersama. 📖', body_id = 'Kini ia ingin membalik halaman sendiri. Buku bertebal dan dongeng bersuara sangat cocok untuk masa ini.', title_ja = '一緒に絵本を読もう 📖', body_ja = 'もう自分でページをめくりたがっています。厚紙の絵本や音の出る絵本がこの時期にぴったりです。', title_ko = '함께 책을 읽어요. 📖', body_ko = '이제 책장을 직접 넘기고 싶어 해요. 두꺼운 보드북과 소리 나는 동화책이 이 시기에 딱이에요.', title_nl = 'Lees samen een boek. 📖', body_nl = 'Je kindje wil nu zelf de bladzijden omslaan. Kartonboekjes en luisterverhalen zijn ideaal in deze fase.', title_pl = 'Czytajcie razem książki. 📖', body_pl = 'Chce już sam przewracać kartki. Książeczki z grubymi stronami i bajki dźwiękowe są idealne na ten etap.', title_pt = 'Leiam um livro juntos. 📖', body_pt = 'Já quer virar as páginas sozinho. Livros cartonados e histórias com som são ideais para esta fase.', title_sv = 'Läs en bok tillsammans. 📖', body_sv = 'Barnet vill redan vända sidorna själv. Kartongböcker och ljudsagor är perfekta i den här åldern.', title_vi = 'Cùng nhau đọc sách. 📖', body_vi = 'Bé đã muốn tự lật trang. Sách bìa cứng và truyện audio là lựa chọn lý tưởng cho giai đoạn này.', title_zh = '一起读书吧 📖', body_zh = '宝宝已经想自己翻书页了。厚纸板书和有声故事最适合这个阶段。' WHERE id = '5b41e7e4-7a14-41e6-a7a1-c4a7838db66b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un fondo mágico para la noche 🪄', body_es = '¿Le cuesta dormirse? Pon en Ruido blanco un fondo relajante solo con el sonido de un río.', title_fr = 'Une ambiance de nuit magique 🪄', body_fr = 'Il a du mal à s''endormir ? Lancez dans les Bruits blancs un fond apaisant composé uniquement du bruit de la rivière.', title_hi = 'जादुई रात का बैकग्राउंड 🪄', body_hi = 'सोने में दिक्कत हो रही है? व्हाइट नॉइज़ में सिर्फ़ नदी की आवाज़ों वाला शांत बैकग्राउंड चलाइए।', title_id = 'Latar malam yang ajaib 🪄', body_id = 'Ia sulit tertidur? Putar latar yang menenangkan dari Suara Putih yang hanya berisi suara sungai.', title_ja = '魔法の夜のBGM 🪄', body_ja = 'なかなか寝つけない？「ホワイトノイズ」で、川の音だけの心落ち着くBGMを流してみましょう。', title_ko = '마법 같은 밤의 배경음 🪄', body_ko = '잠들기 힘들어하나요? 백색소음에서 시냇물 소리로만 된 차분한 배경음을 틀어 주세요.', title_nl = 'Een magische achtergrond voor de nacht 🪄', body_nl = 'Valt je kindje moeilijk in slaap? Zet in Witte ruis een rustgevende achtergrond aan met alleen het geluid van een rivier.', title_pl = 'Magiczne tło na noc 🪄', body_pl = 'Trudno mu zasnąć? Włącz w Białym szumie kojące tło z samym szumem rzeki.', title_pt = 'Um fundo mágico para a noite 🪄', body_pt = 'Tem dificuldade em adormecer? Ligue no Ruído Branco um fundo calmante só com o som de um rio.', title_sv = 'Magisk nattbakgrund 🪄', body_sv = 'Har barnet svårt att somna? Sätt på en lugnande bakgrund med bara bäckljud i Vitt brus.', title_vi = 'Không gian đêm kỳ diệu 🪄', body_vi = 'Bé khó vào giấc? Hãy bật một nền âm thanh êm dịu chỉ có tiếng suối chảy trong Tiếng ồn trắng.', title_zh = '魔法夜晚背景 🪄', body_zh = '入睡困难？在白噪音里放一段只有河流声的舒缓背景音吧。' WHERE id = 'd3ed901e-4f05-435d-a1d6-02b2847be818' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Tráeme la pelota! 🧠', body_es = 'Ya entiende muy bien las instrucciones sencillas. Que te traiga con alegría lo que le pides demuestra que su inteligencia avanza a toda velocidad.', title_fr = 'Apporte-moi le ballon ! 🧠', body_fr = 'Il comprend déjà très bien les consignes simples. Quand vous lui demandez quelque chose, il vous l''apporte avec joie : son intelligence se développe à toute vitesse.', title_hi = 'गेंद मुझे लाकर दो! 🧠', body_hi = 'अब वह आसान निर्देश बहुत अच्छे से समझता है। आपके कुछ माँगने पर खुशी से लाकर देना दिखाता है कि उसका दिमाग तेज़ी से विकसित हो रहा है।', title_id = 'Ambilkan bolanya! 🧠', body_id = 'Kini ia sudah sangat memahami instruksi sederhana. Saat Anda meminta sesuatu, ia dengan senang hati mengambilkannya, tanda kecerdasannya berkembang pesat.', title_ja = 'ボール持ってきて！🧠', body_ja = 'もう簡単な指示をよく理解しています。お願いしたものを喜んで持ってきてくれるのは、知性がぐんぐん育っている証拠です。', title_ko = '공 가져다줘! 🧠', body_ko = '이제 간단한 말을 아주 잘 알아들어요. 무언가를 부탁하면 신나서 가져다주는 건 두뇌가 빠르게 발달하고 있다는 뜻이에요.', title_nl = 'Breng me de bal! 🧠', body_nl = 'Je kindje begrijpt eenvoudige opdrachtjes nu heel goed. Dat hij blij iets komt brengen als je erom vraagt, laat zien hoe snel zijn verstand zich ontwikkelt.', title_pl = 'Przynieś mi piłkę! 🧠', body_pl = 'Bardzo dobrze rozumie już proste polecenia. To, że z radością przynosi ci to, o co prosisz, pokazuje, jak szybko rozwija się jego umysł.', title_pt = 'Traz-me a bola! 🧠', body_pt = 'Já percebe muito bem instruções simples. Quando lhe pede algo e ele o traz todo contente, é sinal de que a inteligência dele se desenvolve depressa.', title_sv = 'Hämta bollen till mig! 🧠', body_sv = 'Barnet förstår nu enkla instruktioner mycket bra. Att det glatt hämtar det du ber om visar att intelligensen utvecklas snabbt.', title_vi = 'Mang bóng lại cho mẹ nào! 🧠', body_vi = 'Giờ bé đã hiểu rất rõ những hướng dẫn đơn giản. Bé vui vẻ mang đến khi mẹ nhờ cho thấy trí tuệ đang phát triển nhanh chóng.', title_zh = '把球拿给我！🧠', body_zh = '宝宝已经能很好地理解简单指令了。你让他拿东西时，他开心地拿给你，说明他的智力在快速发展。' WHERE id = '917ef6a5-ae0d-4133-b145-53d60f762945' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apoyo experto 🤖', body_es = 'Si te surgen nuevas dudas de comportamiento, como «Mi hijo me muerde, ¿cómo reacciono?», pregunta a nuestro asistente Anacan AI.', title_fr = 'L''aide d''un expert. 🤖', body_fr = 'Posez à notre assistant Anacan AI vos nouvelles questions sur son comportement, comme « Mon enfant me mord, comment réagir ? ».', title_hi = 'विशेषज्ञ का सहारा। 🤖', body_hi = '''मेरा बच्चा मुझे काटता है, मैं कैसे प्रतिक्रिया दूँ?'' जैसे व्यवहार से जुड़े नए सवाल हमारे Anacan AI असिस्टेंट से पूछिए।', title_id = 'Dukungan ahli. 🤖', body_id = 'Punya pertanyaan baru tentang perilaku yang membuat Anda cemas, seperti "Anakku menggigitku, bagaimana harus bereaksi?" Tanyakan ke asisten Anacan AI kami.', title_ja = '専門家のサポート 🤖', body_ja = '「子どもが噛んでくるけど、どう対応したらいい？」といった行動の気になる質問は、Anacan AIアシスタントに聞いてみましょう。', title_ko = '전문가의 도움. 🤖', body_ko = '''아이가 나를 깨무는데 어떻게 반응해야 할까?''처럼 행동에 관한 새로운 고민은 Anacan AI 도우미에게 물어보세요.', title_nl = 'Hulp van een deskundige. 🤖', body_nl = 'Heb je nieuwe vragen over gedrag die je zorgen baren, zoals: mijn kind bijt me, hoe moet ik reageren? Stel ze aan onze assistent Anacan AI.', title_pl = 'Wsparcie eksperta. 🤖', body_pl = 'Nowe pytania o zachowanie, które cię niepokoją, np. „Dziecko mnie gryzie, jak reagować?”, zadaj naszemu asystentowi Anacan AI.', title_pt = 'Apoio de especialistas. 🤖', body_pt = 'Faça ao nosso assistente Anacan AI as novas perguntas sobre comportamento que a preocupam, como "O meu filho morde-me, como devo reagir?".', title_sv = 'Stöd från experter. 🤖', body_sv = 'Ställ nya frågor om beteenden som oroar dig, som ”Mitt barn bits, hur ska jag reagera?”, till vår assistent Anacan AI.', title_vi = 'Hỗ trợ từ chuyên gia. 🤖', body_vi = 'Những câu hỏi mới về hành vi khiến mẹ lo lắng, như "Con cắn mẹ, mẹ nên phản ứng thế nào?", hãy hỏi trợ lý Anacan AI.', title_zh = '专家支持 🤖', body_zh = '像“孩子咬我，我该怎么反应？”这类让你担心的新行为问题，可以问我们的Anacan AI助手。' WHERE id = '35d30a24-8966-43d1-afce-6f79d49ebcec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sonidos que calman 🎶', body_es = 'Si después de un día lleno de descubrimientos tu peque no consigue calmarse, pon el sonido de la lluvia en Ruido blanco y llena la habitación de paz.', title_fr = 'Des sons qui apaisent. 🎶', body_fr = 'Après une journée pleine d''explorations, votre enfant n''arrive pas à se calmer ? Lancez le bruit de la pluie dans les Bruits blancs pour apaiser la chambre.', title_hi = 'शांति देने वाली आवाज़ें। 🎶', body_hi = 'खोजबीन भरे दिन के बाद अगर आपका बच्चा शांत नहीं हो पा रहा, तो कमरे में व्हाइट नॉइज़ से बारिश की आवाज़ चलाकर सुकून बनाइए।', title_id = 'Suara yang menenangkan. 🎶', body_id = 'Kalau si kecil sulit tenang setelah hari penuh penjelajahan, ciptakan ketenangan di kamar dengan memutar suara hujan dari Suara Putih.', title_ja = '心を落ち着かせる音 🎶', body_ja = '活発な探検でいっぱいの一日のあと、なかなか落ち着けないときは、「ホワイトノイズ」から雨の音を流して、部屋を穏やかな雰囲気にしましょう。', title_ko = '마음을 차분하게 하는 소리. 🎶', body_ko = '활발한 탐험으로 가득한 하루 뒤에 아이가 진정하지 못한다면 백색소음에서 빗소리를 틀어 방에 평온함을 더해 주세요.', title_nl = 'Rustgevende geluiden. 🎶', body_nl = 'Kan je kindje na een dag vol ontdekkingen niet tot rust komen? Zet in Witte ruis het geluid van regen aan en breng rust in de kamer.', title_pl = 'Dźwięki, które uspokajają. 🎶', body_pl = 'Jeśli po dniu pełnym aktywnych odkryć maluszek nie może się uspokoić, włącz w pokoju odgłos deszczu z Białego szumu i stwórz spokojną atmosferę.', title_pt = 'Sons que trazem calma. 🎶', body_pt = 'Se o seu filho não se consegue acalmar depois de um dia cheio de descobertas, ligue no quarto o som da chuva no Ruído Branco e crie tranquilidade.', title_sv = 'Ljud som skapar lugn. 🎶', body_sv = 'Om barnet inte kan lugna sig efter en dag full av aktiva upptäckter, skapa ro i rummet genom att sätta på regnljud i Vitt brus.', title_vi = 'Âm thanh mang lại bình yên. 🎶', body_vi = 'Nếu sau một ngày đầy khám phá sôi nổi mà bé không dịu lại được, hãy bật tiếng mưa trong Tiếng ồn trắng để căn phòng thêm yên bình.', title_zh = '让人平静的声音 🎶', body_zh = '如果忙着探索了一整天，宝宝静不下来，就在房间里用白噪音放雨声，营造宁静的氛围。' WHERE id = 'a9e6c327-e70b-4cd7-9bed-cb9d250622ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse sin esfuerzo 🌙', body_es = 'Después de un día activo, baja las luces de la habitación y cántale una nana con voz suave para que caiga en un sueño profundo.', title_fr = 'Un endormissement en douceur. 🌙', body_fr = 'Après une journée active, tamisez la lumière et chantez-lui une berceuse d''une voix douce pour l''aider à plonger dans un sommeil profond.', title_hi = 'नींद में आसानी से जाना। 🌙', body_hi = 'भाग-दौड़ भरे दिन के बाद कमरे की रोशनी धीमी कीजिए और धीमे लहजे में लोरी गाकर उसे गहरी नींद में जाने में मदद कीजिए।', title_id = 'Peralihan yang mudah ke tidur. 🌙', body_id = 'Setelah hari yang aktif, redupkan lampu kamar dan nyanyikan nina bobo dengan suara lembut agar ia bisa tidur nyenyak.', title_ja = '眠りへの切りかえをスムーズに 🌙', body_ja = '活発に過ごした日のあとは、部屋の照明を暗くして、やさしい声で子守唄を歌い、ぐっすり眠れるようにしてあげましょう。', title_ko = '편안하게 잠으로. 🌙', body_ko = '활발한 하루가 끝나면 방의 조명을 낮추고 느린 목소리로 자장가를 불러 깊이 잠들 수 있게 해 주세요.', title_nl = 'Makkelijk in slaap vallen. 🌙', body_nl = 'Dim na een drukke dag de lichten en zing met een zachte stem een slaapliedje, zodat je kindje diep in slaap valt.', title_pl = 'Łatwe zasypianie. 🌙', body_pl = 'Po aktywnym dniu przygaś światła w pokoju i zaśpiewaj mu cicho kołysankę, by mógł zapaść w głęboki sen.', title_pt = 'Uma passagem fácil para o sono. 🌙', body_pt = 'Depois de um dia agitado, baixe as luzes do quarto e cante-lhe uma canção de embalar em voz suave para o ajudar a cair num sono profundo.', title_sv = 'Lätt övergång till sömn. 🌙', body_sv = 'Dämpa ljuset i rummet efter en aktiv dag och sjung en vaggvisa med lugn röst så att barnet somnar djupt.', title_vi = 'Vào giấc nhẹ nhàng. 🌙', body_vi = 'Sau một ngày hiếu động, hãy giảm đèn trong phòng và hát ru bằng giọng nhẹ nhàng để bé chìm vào giấc ngủ sâu.', title_zh = '轻松入睡 🌙', body_zh = '活跃了一天之后，调暗房间的灯光，用轻柔的声音给他唱摇篮曲，帮他进入深睡吧。' WHERE id = '714f8ced-9ccc-40ff-a807-9428279f86d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apoyo experto 🤖', body_es = 'Pregunta a nuestro asistente Anacan AI las dudas que te inquietan, como «Entiende las palabras, pero ¿por qué habla tan poco?», y quédate tranquila.', title_fr = 'L''aide d''un expert. 🤖', body_fr = 'Posez à notre assistant Anacan AI les questions qui vous préoccupent, comme « Il comprend les mots, mais pourquoi parle-t-il si peu ? », et soyez rassurée.', title_hi = 'विशेषज्ञ का सहारा। 🤖', body_hi = '''शब्द समझता है, पर कम क्यों बोलता है?'' जैसे सवाल जो आपको सोच में डालते हैं, हमारे Anacan AI असिस्टेंट से पूछिए और निश्चिंत हो जाइए।', title_id = 'Dukungan ahli. 🤖', body_id = 'Tanyakan pertanyaan yang mengganggu pikiran Anda, seperti "Ia mengerti kata-kata, tapi kenapa jarang bicara?", ke asisten Anacan AI kami dan tenangkan diri.', title_ja = '専門家のサポート 🤖', body_ja = '「言葉はわかっているのに、どうしてあまり話さないの？」といった気になる質問は、Anacan AIアシスタントに聞いて安心しましょう。', title_ko = '전문가의 도움. 🤖', body_ko = '''말은 알아듣는데 왜 말을 적게 할까?'' 같은 고민은 Anacan AI 도우미에게 물어 마음의 안정을 찾아보세요.', title_nl = 'Hulp van een deskundige. 🤖', body_nl = 'Heb je vragen die je bezighouden, zoals: hij begrijpt woorden, maar waarom praat hij zo weinig? Stel ze aan onze assistent Anacan AI en stel jezelf gerust.', title_pl = 'Wsparcie eksperta. 🤖', body_pl = 'Pytania, które cię nurtują, np. „Rozumie słowa, ale dlaczego mówi tak mało?”, zadaj naszemu asystentowi Anacan AI i odetchnij.', title_pt = 'Apoio de especialistas. 🤖', body_pt = 'Faça ao nosso assistente Anacan AI as perguntas que a preocupam, como "Percebe as palavras, mas porque fala tão pouco?", e fique mais descansada.', title_sv = 'Stöd från experter. 🤖', body_sv = 'Ställ frågor som oroar dig, som ”Barnet förstår ord, men varför pratar det så lite?”, till vår assistent Anacan AI och få ro.', title_vi = 'Hỗ trợ từ chuyên gia. 🤖', body_vi = 'Những câu hỏi khiến mẹ băn khoăn như "Con hiểu lời nhưng sao nói ít thế?", hãy hỏi trợ lý Anacan AI để yên tâm hơn.', title_zh = '专家支持 🤖', body_zh = '像“他听得懂话，为什么说得这么少？”这样让你挂心的问题，可以问我们的Anacan AI助手，让自己安心。' WHERE id = 'bf80d71f-c8bb-4983-b046-1ee91c367f20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entenderse sin palabras 🫂', body_es = 'Hoy estás muy cansada. Cuando se duerma, siéntate en el sofá junto a tu pareja sin necesidad de hablar y disfrutad del silencio.', title_fr = 'Se comprendre sans mots 🫂', body_fr = 'Vous êtes très fatiguée aujourd''hui. Quand bébé dort, asseyez-vous simplement sur le canapé à côté de votre conjoint, sans parler, et savourez le silence.', title_hi = 'बिना शब्दों की समझ 🫂', body_hi = 'आज आप बहुत थक गईं। बच्चे के सोने के बाद अपने साथी के साथ बिना कुछ बोले बस सोफ़े पर पास-पास बैठिए और खामोशी का आनंद लीजिए।', title_id = 'Saling memahami tanpa kata 🫂', body_id = 'Hari ini Anda sangat lelah. Setelah si kecil tidur, duduk saja berdampingan di sofa bersama pasangan tanpa berbicara, dan nikmati keheningannya.', title_ja = '言葉のいらない通じ合い 🫂', body_ja = '今日はとても疲れましたね。お子さんが寝たら、パートナーと何も話さず、ソファに並んで座って静けさを味わいましょう。', title_ko = '말없이 통하는 마음 🫂', body_ko = '오늘 많이 지쳤죠. 아기가 잠들면 배우자와 아무 말 없이 소파에 나란히 앉아 고요함을 즐겨 보세요.', title_nl = 'Begrip zonder woorden 🫂', body_nl = 'Je bent vandaag erg moe. Ga als je kindje slaapt gewoon naast je partner op de bank zitten, zonder te praten, en geniet van de stilte.', title_pl = 'Porozumienie bez słów 🫂', body_pl = 'Jesteś dziś bardzo zmęczona. Gdy maluszek zaśnie, po prostu usiądźcie z partnerem obok siebie na kanapie i bez słów delektujcie się ciszą.', title_pt = 'Entendimento sem palavras 🫂', body_pt = 'Hoje ficou muito cansada. Depois de o bebé adormecer, sente-se no sofá ao lado do seu companheiro, sem dizer nada, e aproveitem o silêncio.', title_sv = 'Förståelse utan ord 🫂', body_sv = 'Du är väldigt trött i dag. När barnet har somnat, sitt bara bredvid din partner i soffan utan att säga något och njut av tystnaden.', title_vi = 'Thấu hiểu không cần lời 🫂', body_vi = 'Hôm nay mẹ mệt lắm rồi. Khi bé ngủ, hãy cùng bố ngồi cạnh nhau trên sofa, chẳng cần nói gì, chỉ tận hưởng sự yên lặng.', title_zh = '无声的默契 🫂', body_zh = '今天你太累了。宝宝睡着后，和另一半什么都不说，就在沙发上并肩坐着，享受这份安静吧。' WHERE id = 'fb70ef32-f9e7-42c7-9f54-302457a506bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El milagro del día 🖼️', body_es = '¡Un toque especial para el día 520! Sube al Álbum del bebé las fotos más valiosas y divertidas y recuérdalas con una sonrisa dentro de muchos años.', title_fr = 'Le petit miracle du jour 🖼️', body_fr = 'Une touche spéciale pour le 520e jour ! Ajoutez les photos les plus précieuses et les plus drôles à l''Album de bébé et souvenez-vous-en avec le sourire dans quelques années.', title_hi = 'आज का चमत्कार 🖼️', body_hi = '520वें दिन को खास टच दीजिए! सबसे अनमोल और मज़ेदार तस्वीरें बेबी एल्बम में अपलोड कीजिए और सालों बाद मुस्कुराते हुए याद कीजिए।', title_id = 'Keajaiban hari ini 🖼️', body_id = 'Sentuhan istimewa untuk hari ke-520! Unggah foto paling berharga dan paling lucu ke Album Bayi dan kenang sambil tersenyum bertahun-tahun kemudian.', title_ja = '今日の小さな奇跡 🖼️', body_ja = '520日目に特別なひと工夫を！いちばん大切でおもしろい写真を「ベビーアルバム」にアップして、何年たっても笑顔で思い出しましょう。', title_ko = '오늘의 기적 🖼️', body_ko = '520일째를 위한 특별한 한 장! 가장 소중하고 웃긴 사진을 아기 앨범에 올리고 몇 년 뒤 미소 지으며 추억해 보세요.', title_nl = 'Het wonder van de dag 🖼️', body_nl = 'Een speciaal tintje voor dag 520! Zet de dierbaarste en grappigste foto''s in het Babyalbum en denk er over jaren met een glimlach aan terug.', title_pl = 'Cud dnia 🖼️', body_pl = 'Wyjątkowy akcent na 520. dzień! Dodaj najcenniejsze i najzabawniejsze zdjęcia do Albumu dziecka i wspominaj je z uśmiechem za wiele lat.', title_pt = 'O milagre do dia 🖼️', body_pt = 'Um toque especial para o dia 520! Carregue as fotos mais preciosas e mais cómicas no Álbum do Bebé e recorde-as com um sorriso daqui a muitos anos.', title_sv = 'Dagens mirakel 🖼️', body_sv = 'En speciell touch för dag 520! Ladda upp de mest värdefulla och roliga bilderna i Babyalbumet och minns dem med ett leende om många år.', title_vi = 'Điều kỳ diệu của ngày hôm nay 🖼️', body_vi = 'Một dấu ấn đặc biệt cho ngày thứ 520! Hãy tải những bức ảnh quý giá và hài hước nhất lên Album của bé để nhiều năm sau mỉm cười nhớ lại.', title_zh = '今天的小奇迹 🖼️', body_zh = '给第520天加点特别的纪念！把最珍贵、最搞笑的照片上传到宝宝相册，多年后再带着笑容回味。' WHERE id = '15793f9f-2b07-4de4-817b-a555822e7e8e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El apetito del mediodía 🥣', body_es = '¿Habrá tomado hoy suficientes proteínas? Introduce sus comidas en el Seguimiento de tomas y asegúrate de que cubre lo que necesita al día.', title_fr = 'L''appétit de l''après-midi 🥣', body_fr = 'A-t-il mangé assez de protéines aujourd''hui ? Saisissez ses repas dans le Suivi des repas et vérifiez qu''il a bien couvert ses besoins du jour.', title_hi = 'दोपहर की भूख 🥣', body_hi = 'क्या आज पर्याप्त प्रोटीन खाया गया? फ़ीडिंग ट्रैकर में खाना दर्ज कीजिए और पक्का कीजिए कि रोज़ का मानक पूरा हुआ।', title_id = 'Nafsu makan siang 🥣', body_id = 'Apakah hari ini ia cukup makan protein? Masukkan makanannya ke alat Pemantau Makan dan pastikan kebutuhan hariannya terpenuhi.', title_ja = '午後の食欲 🥣', body_ja = '今日はたんぱく質を十分にとれましたか？「栄養管理ツール」に食事を入力して、1日の目安を満たせているか確認しましょう。', title_ko = '점심 입맛 🥣', body_ko = '오늘 단백질은 충분히 먹었나요? 수유 기록 도구에 먹은 음식을 입력하고 하루 섭취량을 채웠는지 확인하세요.', title_nl = 'Eetlust in de middag 🥣', body_nl = 'Heeft je kindje vandaag genoeg eiwit gegeten? Voer de maaltijden in de Voedingstracker in en controleer of hij de dagelijkse norm haalt.', title_pl = 'Popołudniowy apetyt 🥣', body_pl = 'Czy zjadł dziś wystarczająco białka? Wpisz posiłki do narzędzia do śledzenia karmienia i upewnij się, że dzienna norma jest osiągnięta.', title_pt = 'O apetite do almoço 🥣', body_pt = 'Hoje comeu proteína suficiente? Introduza os alimentos no Registo de Alimentação e confirme que atingiu a quantidade diária recomendada.', title_sv = 'Aptiten på eftermiddagen 🥣', body_sv = 'Fick barnet i sig tillräckligt med protein i dag? Lägg in maten i Matningskoll och se till att den dagliga normen nås.', title_vi = 'Bữa ăn buổi chiều 🥣', body_vi = 'Hôm nay bé đã ăn đủ protein chưa? Hãy nhập các món vào công cụ Theo dõi cữ bú để chắc chắn bé ăn đủ định mức hằng ngày.', title_zh = '午餐胃口 🥣', body_zh = '今天蛋白质吃够了吗？把吃的东西录入喂养记录工具，确认达到了每日参考量。' WHERE id = '5d7b0b3c-0707-4aa1-9c33-a30f5f43c63b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Todo un aventurero 📸', body_es = 'Añade al Álbum del bebé la foto más alegre que le hayas hecho trepando o jugando a pillar y conviértela en un recuerdo.', title_fr = 'Un vrai aventurier 📸', body_fr = 'Ajoutez à l''Album de bébé la photo la plus joyeuse prise pendant qu''il grimpait ou courait partout, et faites-en un souvenir.', title_hi = 'असली साहसी 📸', body_hi = 'चढ़ते हुए या दौड़-भाग वाले खेल में खींची अपनी सबसे खुशनुमा फ़ोटो बेबी एल्बम में जोड़कर याद बना लीजिए।', title_id = 'Petualang sejati 📸', body_id = 'Jadikan foto paling ceria saat ia memanjat atau bermain kejar-kejaran sebagai kenangan dengan menambahkannya ke Album Bayi.', title_ja = '本物の冒険家 📸', body_ja = 'よじ登ったり走り回ったりしているときに撮った、いちばん楽しい写真を「ベビーアルバム」に追加して、思い出にしましょう。', title_ko = '진정한 모험가 📸', body_ko = '기어오르거나 뛰어놀 때 찍은 가장 즐거운 사진을 아기 앨범에 추가해 추억으로 남기세요.', title_nl = 'Een echte avonturier 📸', body_nl = 'Zet de vrolijkste foto die je maakte terwijl hij klom of rondrende in het Babyalbum en maak er een herinnering van.', title_pl = 'Prawdziwy podróżnik 📸', body_pl = 'Dodaj do Albumu dziecka najweselsze zdjęcie zrobione, gdy się wspinał lub biegał, i zamień je we wspomnienie.', title_pt = 'Um verdadeiro aventureiro 📸', body_pt = 'Adicione ao Álbum do Bebé a foto mais alegre que tirou enquanto ele trepava ou corria a brincar e transforme-a numa recordação.', title_sv = 'En riktig äventyrare 📸', body_sv = 'Lägg till den gladaste bilden du tog när barnet klättrade eller lekte jagalek i Babyalbumet och gör den till ett minne.', title_vi = 'Nhà thám hiểm thực thụ 📸', body_vi = 'Hãy thêm bức ảnh vui nhất mẹ chụp khi bé leo trèo hay chạy nhảy vào Album của bé để biến nó thành kỷ niệm.', title_zh = '真正的冒险家 📸', body_zh = '把他爬上爬下、跑来跑去时拍下的最开心的照片加进宝宝相册，变成美好回忆吧。' WHERE id = 'a242b14e-b434-493a-ab87-b2064aedfc9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal su digestión? 💩', body_es = 'Al cambiar el pañal, anota en la app cómo es la caca. Sigue fácilmente cómo afectan los alimentos ricos en fibra a su digestión a lo largo del día.', title_fr = 'Comment va la digestion ? 💩', body_fr = 'Lors du change, notez les selles dans l''application. Suivez facilement l''effet des aliments riches en fibres sur sa digestion au fil de la journée.', title_hi = 'पाचन कैसा है? 💩', body_hi = 'डायपर बदलते समय पॉटी की जानकारी ऐप में जोड़िए। दिनभर में फ़ाइबर वाले खाने का पाचन पर असर आसानी से देखिए।', title_id = 'Bagaimana pencernaannya? 💩', body_id = 'Saat mengganti popok, tambahkan catatan BAB ke aplikasi. Pantau dengan mudah pengaruh makanan berserat pada pencernaannya sepanjang hari.', title_ja = '消化の調子はどう？💩', body_ja = 'おむつ替えのときに、うんちの記録をアプリに追加しましょう。食物繊維の多い食べ物が消化にどう影響しているか、一日を通してかんたんに見守れます。', title_ko = '소화는 잘 되고 있나요? 💩', body_ko = '기저귀를 갈 때 배변 기록을 앱에 추가하세요. 식이섬유가 많은 음식이 하루 동안 소화에 어떤 영향을 주는지 쉽게 살펴볼 수 있어요.', title_nl = 'Hoe gaat het met de spijsvertering? 💩', body_nl = 'Voeg bij het verschonen notities over de ontlasting toe in de app. Volg zo makkelijk hoe vezelrijke voeding gedurende de dag de spijsvertering beïnvloedt.', title_pl = 'Jak tam trawienie? 💩', body_pl = 'Przy przewijaniu zapisuj w aplikacji informacje o kupce. Łatwo śledź, jak pokarmy bogate w błonnik wpływają na trawienie w ciągu dnia.', title_pt = 'Como está a digestão? 💩', body_pt = 'Ao mudar a fralda, adicione à app as notas sobre as fezes. Acompanhe com facilidade o efeito dos alimentos ricos em fibra na digestão ao longo do dia.', title_sv = 'Hur fungerar matsmältningen? 💩', body_sv = 'Lägg in anteckningar om bajset i appen när du byter blöja. Följ enkelt hur fiberrik mat påverkar matsmältningen under dagen.', title_vi = 'Hệ tiêu hóa thế nào? 💩', body_vi = 'Khi thay tã, hãy ghi chú về phân vào ứng dụng. Dễ dàng theo dõi ảnh hưởng của thực phẩm giàu chất xơ đến tiêu hóa trong ngày.', title_zh = '消化系统怎么样？💩', body_zh = '换尿布时把便便记录添加到应用里。轻松关注一天中高纤维食物对消化的影响。' WHERE id = '0671a41f-8a24-4dff-87f0-008aa3abfc3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No quiere compartir? 🤖', body_es = '¿En el parque no comparte su juguete y se pone a gritar? Aprende con Anacan AI cómo actuar en esta situación y ponlo en práctica.', title_fr = 'Il ne veut pas partager ? 🤖', body_fr = 'Au parc, il refuse de prêter son jouet et se met à crier ? Découvrez avec Anacan AI comment réagir dans cette situation et appliquez-le.', title_hi = 'बाँटना नहीं चाहता? 🤖', body_hi = 'पार्क में अपना खिलौना नहीं बाँटता और चिल्लाता है? Anacan AI से जानिए कि ऐसी स्थिति में कैसे पेश आएँ, और उसे अपनाइए।', title_id = 'Tidak mau berbagi? 🤖', body_id = 'Di taman ia tidak mau berbagi mainan dan berteriak? Pelajari dari Anacan AI bagaimana bersikap dalam situasi ini, lalu terapkan.', title_ja = '貸したくない？🤖', body_ja = '公園でおもちゃを貸さずに叫んでしまう？こんなとき、どう対応すればいいかAnacan AIで学んで、実践してみましょう。', title_ko = '나누기 싫어하나요? 🤖', body_ko = '공원에서 장난감을 나누지 않고 소리를 지르나요? Anacan AI에게 이런 상황에서 어떻게 대처해야 할지 알아보고 실천해 보세요.', title_nl = 'Wil hij niet delen? 🤖', body_nl = 'Wil je kindje in het park zijn speelgoed niet delen en begint hij te gillen? Ontdek met Anacan AI hoe je in zo''n situatie reageert en pas het toe.', title_pl = 'Nie chce się dzielić? 🤖', body_pl = 'W parku nie chce dzielić się zabawką i krzyczy? Dowiedz się w Anacan AI, jak zachować się w takiej sytuacji, i zastosuj to w praktyce.', title_pt = 'Não quer partilhar? 🤖', body_pt = 'No parque, não partilha o brinquedo e grita? Saiba com o Anacan AI como agir nesta situação e ponha-o em prática.', title_sv = 'Vill inte dela? 🤖', body_sv = 'Delar barnet inte sin leksak i parken och skriker? Lär dig av Anacan AI hur du ska agera i den här situationen och använd det.', title_vi = 'Bé không muốn chia sẻ? 🤖', body_vi = 'Ở công viên bé không chịu chia đồ chơi và la hét? Hãy tìm hiểu cùng Anacan AI cách ứng xử trong tình huống này và áp dụng nhé.', title_zh = '不想分享？🤖', body_zh = '在公园里不肯分享玩具，还大喊大叫？向Anacan AI学习这种情况该怎么做，然后试着用起来吧。' WHERE id = 'fbbb1355-d1ac-4efe-b9c7-1746b97b1656' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Platos de colores 🥦', body_es = '¿No come verdura? Con presentaciones divertidas de Recetas para bebés que empiezan con la alimentación complementaria, completa jugando las cantidades del Seguimiento de tomas.', title_fr = 'Des assiettes colorées 🥦', body_fr = 'Il ne mange pas de légumes ? Avec les présentations amusantes des Recettes pour bébés qui commencent la diversification, remplissez ses objectifs du Suivi des repas en s''amusant.', title_hi = 'रंगीन प्लेटें 🥦', body_hi = 'सब्ज़ियाँ नहीं खाता? ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी के दिलचस्प तरीकों से फ़ीडिंग ट्रैकर का मानक मज़ेदार ढंग से पूरा कीजिए।', title_id = 'Piring berwarna-warni 🥦', body_id = 'Ia tidak mau makan sayur? Penuhi target porsi di alat Pemantau Makan dengan cara seru lewat penyajian menarik dari Resep untuk bayi yang mulai MPASI.', title_ja = 'カラフルなお皿 🥦', body_ja = '野菜を食べない？「離乳食を始める赤ちゃんのレシピ」の楽しい盛り付けで、「栄養管理ツール」の目安を楽しく満たしましょう。', title_ko = '알록달록한 접시 🥦', body_ko = '채소를 안 먹나요? 이유식을 시작하는 아기를 위한 레시피의 재미있는 담음새로 수유 기록 도구의 하루 섭취량을 즐겁게 채워 보세요.', title_nl = 'Kleurrijke borden 🥦', body_nl = 'Eet je kindje geen groenten? Haal met leuke presentaties uit Recepten voor baby''s die met bijvoeding beginnen op een speelse manier de norm in de Voedingstracker.', title_pl = 'Kolorowe talerze 🥦', body_pl = 'Nie je warzyw? Dzięki ciekawym sposobom podania z Przepisów dla niemowląt rozpoczynających rozszerzanie diety w zabawny sposób osiągnij normę w narzędziu do śledzenia karmienia.', title_pt = 'Pratos coloridos 🥦', body_pt = 'Não come legumes? Com as apresentações divertidas das Receitas para bebés em diversificação alimentar, atinja de forma divertida a quantidade recomendada no Registo de Alimentação.', title_sv = 'Färgglada tallrikar 🥦', body_sv = 'Äter barnet inte grönsaker? Fyll normen i Matningskoll på ett roligt sätt med spännande serveringar från Recept för bebisar som börjar med fast föda.', title_vi = 'Những chiếc đĩa đầy màu sắc 🥦', body_vi = 'Bé không ăn rau? Hãy dùng những cách bày biện thú vị từ mục Công thức cho bé bắt đầu ăn dặm để vui vẻ đạt định mức trong công cụ Theo dõi cữ bú.', title_zh = '彩色餐盘 🥦', body_zh = '不吃蔬菜？用食谱板块里辅食宝宝食谱的有趣摆盘，轻松愉快地达到喂养记录工具里的参考量。' WHERE id = 'f0fc96ac-776c-4e66-bacf-461eff128cbc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Diseñador de moda en acción! 👗', body_es = '¿Quiere elegir su ropa y se pone colores que no pegan? Decora este conjunto tan gracioso con las pegatinas divertidas de la Sesión de fotos del bebé y conviértelo en la foto más divertida del álbum.', title_fr = 'Styliste au travail ! 👗', body_fr = 'Il veut choisir ses vêtements et porte des couleurs qui ne vont pas ensemble ? Décorez cette tenue comique avec les stickers joyeux de la Séance photo bébé et faites-en la photo la plus drôle de l''album.', title_hi = 'फ़ैशन डिज़ाइनर काम पर! 👗', body_hi = 'अपने कपड़े खुद चुनना चाहता है और बेमेल रंग पहनता है? इस मज़ेदार जोड़ी को बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम की सबसे मज़ेदार तस्वीर बना दीजिए।', title_id = 'Perancang busana sedang beraksi! 👗', body_id = 'Ia ingin memilih bajunya sendiri dan memakai warna yang tidak serasi? Hiasi padu padan lucu ini dengan stiker ceria di Sesi Foto Bayi dan jadikan foto paling kocak di album.', title_ja = '小さなファッションデザイナー！👗', body_ja = '自分で服を選びたがって、ちぐはぐな色の組み合わせに？このおもしろいコーデを「ベビーフォトセッション」の楽しいステッカーで飾って、アルバムでいちばん笑える一枚にしましょう。', title_ko = '꼬마 디자이너 작업 중! 👗', body_ko = '옷을 직접 고르겠다며 어울리지 않는 색을 입나요? 이 웃긴 옷차림을 아기 사진 촬영의 즐거운 스티커로 꾸며 앨범에서 가장 재미있는 한 컷으로 만드세요.', title_nl = 'Een modeontwerper aan het werk! 👗', body_nl = 'Wil je kindje zelf zijn kleren kiezen en trekt hij kleuren aan die niet bij elkaar passen? Versier deze grappige outfit met vrolijke stickers in Babyfotoshoot en maak er de grappigste foto van het album van.', title_pl = 'Mały projektant mody przy pracy! 👗', body_pl = 'Chce sam wybierać ubrania i zakłada niepasujące kolory? Ozdób ten zabawny zestaw wesołymi naklejkami w Sesji zdjęciowej dziecka i zamień go w najzabawniejsze ujęcie w albumie.', title_pt = 'Estilista em ação! 👗', body_pt = 'Quer escolher a própria roupa e veste cores que não combinam? Decore este conjunto cómico com os autocolantes divertidos da Sessão Fotográfica do Bebé e transforme-o na foto mais engraçada do álbum.', title_sv = 'Modeskaparen i arbete! 👗', body_sv = 'Vill barnet välja sina egna kläder och klär sig i färger som inte passar ihop? Pynta den roliga kombinationen med glada klistermärken i Babyfotografering och gör den till albumets roligaste bild.', title_vi = 'Nhà thiết kế thời trang đang làm việc! 👗', body_vi = 'Bé muốn tự chọn quần áo và mặc những màu chẳng ăn nhập gì? Hãy trang trí bộ đồ hài hước này bằng những sticker vui nhộn trong Chụp ảnh cho bé để có khung hình ngộ nghĩnh nhất album.', title_zh = '小小造型师上岗！👗', body_zh = '想自己挑衣服，结果穿得五颜六色不搭调？用宝宝写真里欢乐的贴纸装点这身搞笑搭配，让它成为相册里最有趣的一张。' WHERE id = '6bb4b5b9-3f8e-4a1c-a637-e0752d1d87ee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Zurdo o diestro? 🤚', body_es = '¿Con qué mano coge la cuchara? No te pierdas nuestro nuevo artículo científico del Blog sobre cómo y cuándo se define la mano dominante.', title_fr = 'Gaucher ou droitier ? 🤚', body_fr = 'De quelle main tient-il sa cuillère ? Jetez absolument un œil à notre nouvel article scientifique dans les Blogs sur comment et quand se met en place la main dominante.', title_hi = 'बाएँ हाथ वाला या दाएँ? 🤚', body_hi = 'चम्मच किस हाथ से पकड़ता है? मुख्य हाथ कैसे और कब तय होता है, इस पर ब्लॉग सेक्शन में हमारा नया वैज्ञानिक लेख ज़रूर देखिए।', title_id = 'Kidal atau kanan? 🤚', body_id = 'Dengan tangan mana ia memegang sendok? Pastikan membaca artikel ilmiah terbaru kami di bagian Blog tentang bagaimana dan kapan tangan dominan terbentuk.', title_ja = '左利き？右利き？🤚', body_ja = 'スプーンをどちらの手で持っていますか？利き手がいつ、どのように決まるのかについて、ブログの新しい科学的な記事をぜひ読んでみましょう。', title_ko = '왼손잡이일까, 오른손잡이일까? 🤚', body_ko = '숟가락을 어느 손으로 잡나요? 주로 쓰는 손이 언제, 어떻게 정해지는지에 관한 블로그 섹션의 새로운 과학 글을 꼭 살펴보세요.', title_nl = 'Linkshandig of rechtshandig? 🤚', body_nl = 'Met welke hand houdt je kindje de lepel vast? Lees zeker ons nieuwe wetenschappelijke artikel in het onderdeel Blogs over hoe en wanneer de voorkeurshand zich ontwikkelt.', title_pl = 'Leworęczny czy praworęczny? 🤚', body_pl = 'Którą ręką trzyma łyżeczkę? Koniecznie przeczytaj w sekcji Blogi nasz nowy, naukowy artykuł o tym, jak i kiedy kształtuje się ręka dominująca.', title_pt = 'Canhoto ou destro? 🤚', body_pt = 'Com que mão segura a colher? Não deixe de ler o nosso novo artigo científico na secção Blogues sobre como e quando se define a mão dominante.', title_sv = 'Vänsterhänt eller högerhänt? 🤚', body_sv = 'Med vilken hand håller barnet skeden? Läs vår nya, vetenskapliga artikel i avsnittet Bloggar om hur och när den dominanta handen utvecklas.', title_vi = 'Thuận tay trái hay tay phải? 🤚', body_vi = 'Bé cầm thìa bằng tay nào? Mẹ nhớ xem bài viết khoa học mới trong mục Blog về việc tay thuận hình thành như thế nào và khi nào nhé.', title_zh = '左撇子还是右撇子？🤚', body_zh = '他用哪只手拿勺子？一定要看看博客板块里关于惯用手如何、何时形成的最新科学文章。' WHERE id = 'f8565841-4602-47d5-af45-99f7dea5b129' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primeros sonidos de animales 🐮', body_es = '¿Intenta imitar al perro o al gato cuando los ve? Añade este gran avance cognitivo en un vídeo corto al Álbum del bebé y guárdalo para siempre.', title_fr = 'Premiers cris d''animaux 🐮', body_fr = 'Il essaie d''imiter le chien ou le chat quand il les voit ? Gardez ce magnifique progrès cognitif en petite vidéo dans l''Album de bébé.', title_hi = 'जानवरों की पहली आवाज़ें 🐮', body_hi = 'कुत्ता या बिल्ली देखकर उनकी आवाज़ निकालने की कोशिश करता है? समझ के इस शानदार विकास को छोटे वीडियो के रूप में बेबी एल्बम में जोड़कर यादों में सहेज लीजिए।', title_id = 'Suara hewan pertama 🐮', body_id = 'Saat melihat anjing atau kucing, ia mencoba menirukan suaranya? Simpan perkembangan kognitif yang luar biasa ini sebagai video pendek di Album Bayi.', title_ja = 'はじめての動物の鳴き声 🐮', body_ja = '犬やねこを見ると、鳴き声をまねしようとしますか？このすばらしい知能の発達を短い動画で「ベビーアルバム」に追加して、思い出に残しましょう。', title_ko = '첫 동물 소리 🐮', body_ko = '강아지나 고양이를 보면 그 소리를 흉내 내려 하나요? 이 멋진 인지 발달을 짧은 영상으로 아기 앨범에 추가해 기억에 남기세요.', title_nl = 'Eerste dierengeluiden 🐮', body_nl = 'Probeert je kindje een hond of poes na te doen als hij ze ziet? Leg deze geweldige verstandelijke ontwikkeling vast als korte video in het Babyalbum.', title_pl = 'Pierwsze odgłosy zwierząt 🐮', body_pl = 'Na widok psa lub kota próbuje naśladować ich odgłosy? Dodaj ten wspaniały postęp poznawczy jako krótki filmik do Albumu dziecka i zachowaj go we wspomnieniach.', title_pt = 'Os primeiros sons de animais 🐮', body_pt = 'Quando vê um cão ou um gato, tenta imitar o som deles? Adicione este fantástico desenvolvimento cognitivo ao Álbum do Bebé num vídeo curto e guarde-o na memória.', title_sv = 'De första djurläten 🐮', body_sv = 'Försöker barnet låta som hunden eller katten när det ser dem? Lägg till denna fantastiska kognitiva utveckling som en kort video i Babyalbumet och spara minnet.', title_vi = 'Những tiếng kêu con vật đầu tiên 🐮', body_vi = 'Thấy chó hay mèo là bé cố bắt chước tiếng kêu? Hãy lưu giữ bước phát triển nhận thức tuyệt vời này bằng một video ngắn trong Album của bé.', title_zh = '第一次学动物叫 🐮', body_zh = '看到狗或猫时，他会学它们叫？把这个了不起的认知进步录成短视频加进宝宝相册，留在记忆里吧。' WHERE id = 'daa6a0d6-25d4-401e-ba81-8a8ca5108695' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla del «¡Como yo solo!» 🥣', body_es = 'Si le dejas, la comida acaba por todas partes; si no, grita. Aprende ya con los consejos psicológicos de Anacan AI a gestionar esta crisis sin estrés.', title_fr = 'La bataille du « Je mange tout seul ! » 🥣', body_fr = 'Si vous le laissez faire, il y en a partout ; sinon, il crie. Découvrez tout de suite avec les conseils psychologiques d''Anacan AI comment gérer cette crise sans stress.', title_hi = '''मैं खुद खाऊँगा!'' की जंग 🥣', body_hi = 'इजाज़त दें तो खाना हर जगह बिखरता है, न दें तो चीखता है। इस संकट को बिना तनाव कैसे संभालें, यह तुरंत Anacan AI की मनोवैज्ञानिक सलाह से जानिए।', title_id = 'Perang "Aku makan sendiri!" 🥣', body_id = 'Kalau dibiarkan, makanan berserakan ke mana-mana; kalau tidak, ia berteriak. Pelajari sekarang juga cara menghadapi krisis ini tanpa stres dengan saran psikologis dari Anacan AI.', title_ja = '「自分で食べる！」の攻防 🥣', body_ja = 'やらせると食べ物が飛び散り、やらせないと叫ぶ。この悩みをストレスなく乗りこえる方法を、Anacan AIの心理的アドバイスですぐに学びましょう。', title_ko = '"내가 먹을래!" 전쟁 🥣', body_ko = '허락하면 음식이 사방에 흩어지고, 안 하면 소리를 지르죠. 이 위기를 스트레스 없이 다루는 법을 Anacan AI의 심리 조언으로 바로 알아보세요.', title_nl = 'De strijd: ik eet zelf! 🥣', body_nl = 'Laat je hem zelf eten, dan ligt alles overal; laat je het niet toe, dan krijst hij. Ontdek meteen met de psychologische tips van Anacan AI hoe je deze crisis zonder stress aanpakt.', title_pl = 'Bitwa „Sam zjem!” 🥣', body_pl = 'Gdy mu pozwolisz, jedzenie ląduje wszędzie, a gdy nie, krzyczy. Od razu dowiedz się z psychologicznych porad Anacan AI, jak bez stresu opanować ten kryzys.', title_pt = 'A guerra do "Eu como sozinho!" 🥣', body_pt = 'Se deixar, a comida espalha-se por todo o lado; se não deixar, grita. Aprenda já com os conselhos psicológicos do Anacan AI a gerir esta crise sem stress.', title_sv = 'Kampen ”Jag äter själv!” 🥣', body_sv = 'Om du låter barnet hamnar maten överallt, om du inte gör det skriker barnet. Lär dig direkt hur du hanterar krisen utan stress med psykologiska råd från Anacan AI.', title_vi = 'Cuộc chiến "Con tự ăn!" 🥣', body_vi = 'Cho bé tự ăn thì đồ ăn vương vãi khắp nơi, không cho thì bé la hét. Hãy tìm hiểu ngay cách xử lý tình huống này không căng thẳng với lời khuyên tâm lý từ Anacan AI.', title_zh = '“我要自己吃！”之战 🥣', body_zh = '让他自己吃，饭菜撒得到处都是；不让他吃，他就尖叫。马上用Anacan AI的心理建议，学习如何不带压力地应对这个难关吧。' WHERE id = 'cc01349a-6eef-4c61-aa08-b3f505c2eb5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por el agua y el barro 💦', body_es = '¡No te importe que se manche! Encuentra un sitio al aire libre en Lugares para mamás y deja que entre en contacto con la naturaleza y viva el punto álgido de su desarrollo sensorial.', title_fr = 'L''amour de l''eau et de la boue 💦', body_fr = 'N''ayez pas peur qu''il se salisse ! Trouvez un lieu en plein air dans les Lieux adaptés aux mamans et laissez-le profiter du contact avec la nature, au sommet de son développement sensoriel.', title_hi = 'पानी और कीचड़ से प्यार 💦', body_hi = 'कपड़े गंदे होने से मत झिझकिए! माँ के लिए अनुकूल जगहों में कोई खुली जगह ढूँढिए और उसे प्रकृति से जुड़कर सेंसरी विकास का भरपूर अनुभव करने दीजिए।', title_id = 'Cinta air dan lumpur 💦', body_id = 'Jangan takut bajunya kotor! Temukan tempat terbuka di Tempat Ramah Ibu, biarkan ia bersentuhan dengan alam dan merasakan puncak perkembangan sensoriknya.', title_ja = '水と泥が大好き 💦', body_ja = '服が汚れるのを気にしないで！「ママにやさしいスポット」で屋外の場所を見つけて、自然とふれあいながら感覚の発達を思いきり楽しませてあげましょう。', title_ko = '물과 진흙 사랑 💦', body_ko = '옷이 더러워지는 걸 걱정하지 마세요! 엄마 친화 장소에서 야외 공간을 찾아 자연을 만지며 감각 발달의 절정을 경험하게 해 주세요.', title_nl = 'Dol op water en modder 💦', body_nl = 'Wees niet bang dat hij vies wordt! Zoek in Mamavriendelijke plekken een plek in de buitenlucht en laat hem in contact komen met de natuur, voor een topmoment in zijn zintuiglijke ontwikkeling.', title_pl = 'Miłość do wody i błota 💦', body_pl = 'Nie bój się, że się ubrudzi! Znajdź w Miejscach przyjaznych mamom miejsce na świeżym powietrzu i pozwól mu obcować z naturą, by rozwój zmysłów osiągnął szczyt.', title_pt = 'O amor pela água e pela lama 💦', body_pt = 'Não tenha medo que ele se suje! Encontre nos Locais Amigos das Mães um sítio ao ar livre e deixe-o estar em contacto com a natureza para viver o auge do desenvolvimento sensorial.', title_sv = 'Kärlek till vatten och lera 💦', body_sv = 'Var inte rädd för att barnet blir smutsigt! Hitta en plats utomhus i Mammavänliga platser och låt barnet få kontakt med naturen och nå toppen av sin sensoriska utveckling.', title_vi = 'Yêu nước và bùn đất 💦', body_vi = 'Đừng ngại bé lấm lem! Hãy tìm một nơi ngoài trời trong Địa điểm thân thiện với mẹ để bé được tiếp xúc với thiên nhiên và phát triển giác quan ở mức tốt nhất.', title_zh = '爱玩水和泥巴 💦', body_zh = '别怕弄脏衣服！在妈妈友好场所里找一个户外的地方，让他亲近大自然，让感官发育达到巅峰。' WHERE id = 'deb6cbd4-3a89-4915-9bdf-626d87829918' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Un capricho de 5 minutos! 🥗', title_fr = 'Un délice en 5 minutes ! 🥗', title_hi = '5 मिनट का स्वाद! 🥗', title_id = 'Nikmat dalam 5 menit! 🥗', title_ja = '5分でできるごちそう！🥗', title_ko = '5분이면 완성! 🥗', title_nl = 'Genieten in 5 minuten! 🥗', title_pl = 'Przysmak w 5 minut! 🥗', title_pt = 'Uma delícia em 5 minutos! 🥗', title_sv = 'Njutning på 5 minuter! 🥗', title_vi = 'Món ngon 5 phút! 🥗', title_zh = '5分钟的美味！🥗' WHERE id = '8ae66558-ee37-4cd1-9102-46bab1a97b21' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere comer solo 🥣', title_fr = 'Il veut manger seul 🥣', title_hi = 'खुद खाना चाहता है 🥣', title_id = 'Ingin makan sendiri 🥣', title_ja = '自分で食べたい 🥣', title_ko = '혼자 먹고 싶어 해요 🥣', title_nl = 'Wil zelf eten 🥣', title_pl = 'Chce jeść sam 🥣', title_pt = 'Quer comer sozinho 🥣', title_sv = 'Vill äta själv 🥣', title_vi = 'Bé muốn tự ăn 🥣', title_zh = '想自己吃饭 🥣' WHERE id = '622216cc-100d-4e85-95dc-7d70e41c5761' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla entre mamás 💬', body_es = '¿Sientes que no llegas a todo? Entra ya en la Comunidad Anacan, lee los comentarios de apoyo de otras mamás y respira.', title_fr = 'Entre mamans 💬', body_fr = 'Vous avez l''impression de ne pas être à la hauteur ? Rejoignez tout de suite la Communauté Anacan, lisez les messages de soutien des autres mamans et soufflez un peu.', title_hi = 'माँओं की दिल की बातें 💬', body_hi = 'खुद को कम महसूस कर रही हैं? तुरंत Anacan कम्युनिटी में आइए, दूसरी माँओं के हौसला बढ़ाने वाले कमेंट पढ़िए और सुकून पाइए।', title_id = 'Curhat sesama ibu 💬', body_id = 'Merasa tidak cukup baik? Segera masuk ke Komunitas Anacan, baca komentar dukungan dari ibu-ibu lain, dan tenangkan diri.', title_ja = 'ママ同士のおしゃべり 💬', body_ja = '自分は足りていないと感じますか？すぐにAnacanコミュニティを開いて、ほかのママたちの温かいコメントを読んでほっとしましょう。', title_ko = '엄마들의 수다 💬', body_ko = '내가 부족한 엄마 같나요? 바로 Anacan 커뮤니티에 들어가 다른 엄마들의 응원 댓글을 읽으며 마음을 편히 하세요.', title_nl = 'Moeders onder elkaar 💬', body_nl = 'Voel je je tekortschieten? Ga meteen naar de Anacan Community, lees de steunende reacties van andere moeders en kom tot rust.', title_pl = 'Mamy rozmawiają 💬', body_pl = 'Czujesz, że nie dajesz rady? Od razu wejdź do Społeczności Anacan, przeczytaj wspierające komentarze innych mam i odetchnij.', title_pt = 'Conversa entre mães 💬', body_pt = 'Sente que não é suficiente? Entre já na Comunidade Anacan, leia os comentários de apoio de outras mães e descontraia.', title_sv = 'Mammasnack 💬', body_sv = 'Känner du dig otillräcklig? Gå direkt in i Anacans Community, läs stöttande kommentarer från andra mammor och slappna av.', title_vi = 'Các mẹ tâm sự 💬', body_vi = 'Mẹ cảm thấy mình chưa đủ tốt? Hãy vào ngay Cộng đồng Anacan, đọc những lời động viên của các mẹ khác để nhẹ lòng hơn.', title_zh = '妈妈们的知心话 💬', body_zh = '觉得自己做得不够好？马上进入Anacan社区，读读其他妈妈的暖心留言，放松一下。' WHERE id = '8f7c6b2d-87b3-4688-9ad1-78064dda6eb8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubre sitios nuevos ☕', body_es = '¿Agobiada de la rutina diaria? Encuentra en nuestra app una cafetería a la que entrar cómodamente con el carrito y tómate un descanso con un café.', title_fr = 'Découvrez de nouveaux lieux. ☕', body_fr = 'La routine vous pèse ? Trouvez dans l''application un café où entrer facilement avec la poussette, et faites une pause café.', title_hi = 'नई जगहें खोजिए। ☕', body_hi = 'रोज़ के रूटीन से ऊब गई हैं? हमारे ऐप में ऐसा कैफ़े ढूँढिए जहाँ स्ट्रॉलर के साथ आराम से जा सकें, और एक कॉफ़ी ब्रेक लीजिए।', title_id = 'Temukan tempat baru. ☕', body_id = 'Bosan dengan rutinitas sehari-hari? Temukan kafe yang mudah dimasuki dengan stroller lewat aplikasi kami dan nikmati rehat kopi.', title_ja = '新しい場所を見つけよう ☕', body_ja = '毎日の繰り返しに疲れていませんか？アプリでベビーカーでも入りやすいカフェを見つけて、コーヒーブレイクを楽しみましょう。', title_ko = '새로운 장소를 발견해요. ☕', body_ko = '똑같은 일상이 답답한가요? 앱에서 유모차로 편하게 들어갈 수 있는 카페를 찾아 커피 한 잔의 여유를 가져 보세요.', title_nl = 'Ontdek nieuwe plekken. ☕', body_nl = 'Zit je vast in de dagelijkse routine? Zoek in onze app een café waar je makkelijk met de kinderwagen binnenkomt en neem een koffiepauze.', title_pl = 'Odkrywaj nowe miejsca. ☕', body_pl = 'Codzienna rutyna cię przytłacza? Znajdź w naszej aplikacji kawiarnię, do której łatwo wjedziesz wózkiem, i zrób sobie przerwę na kawę.', title_pt = 'Descubra novos lugares. ☕', body_pt = 'Está cansada da rotina diária? Encontre na nossa app um café onde entre à vontade com o carrinho e faça uma pausa para um café.', title_sv = 'Upptäck nya platser. ☕', body_sv = 'Trött på vardagsrutinen? Hitta ett kafé i appen dit du lätt kommer in med barnvagnen och ta en kaffepaus.', title_vi = 'Khám phá địa điểm mới. ☕', body_vi = 'Mẹ thấy ngột ngạt với nếp sinh hoạt hằng ngày? Hãy tìm trong ứng dụng một quán cà phê có thể vào thoải mái với xe đẩy và nghỉ uống cà phê nhé.', title_zh = '发现新地方 ☕', body_zh = '厌倦了日常重复？在我们的应用里找一家推婴儿车也能轻松进出的咖啡馆，来个咖啡时间吧。' WHERE id = '4a0eb59e-113c-42ab-af5f-e0f64f837b44' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ayudante en casa! 🧹', body_es = '¿Está deseando coger un trapo para quitar el polvo o jugar con la escoba? Que te imite es una señal preciosa de su desarrollo.', title_fr = 'Un petit assistant ménager ! 🧹', body_fr = 'Il veut prendre un chiffon pour épousseter ou jouer avec le balai ? Qu''il vous imite est un beau signe de son développement.', title_hi = 'घर के कामों में मददगार! 🧹', body_hi = 'हाथ में कपड़ा लेकर धूल पोंछने या झाड़ू से खेलने को उत्सुक है? आपकी नकल करना उसके विकास का खूबसूरत संकेत है।', title_id = 'Asisten pekerjaan rumah! 🧹', body_id = 'Ia ingin mengambil lap untuk membersihkan debu atau bermain dengan sapu? Meniru Anda adalah tanda perkembangan yang indah.', title_ja = '家事のお手伝い！🧹', body_ja = 'ふきんでほこりを拭いたり、ほうきで遊んだりしたがりますか？あなたのまねをするのは、発達のすてきなサインです。', title_ko = '집안일 도우미! 🧹', body_ko = '수건을 들고 먼지를 닦거나 빗자루로 놀고 싶어 하나요? 엄마를 따라 하는 건 발달이 잘 되고 있다는 멋진 신호예요.', title_nl = 'Hulpje in het huishouden! 🧹', body_nl = 'Wil je kindje met een doekje afstoffen of met de bezem spelen? Dat hij jou nadoet, is een mooi teken van zijn ontwikkeling.', title_pl = 'Pomocnik w pracach domowych! 🧹', body_pl = 'Rwie się, by wziąć ściereczkę i ścierać kurze albo bawić się miotłą? To, że cię naśladuje, to piękny znak jego rozwoju.', title_pt = 'Um ajudante nas tarefas da casa! 🧹', body_pt = 'Quer pegar num pano para limpar o pó ou brincar com a vassoura? Imitá-la é um belo sinal do desenvolvimento dele.', title_sv = 'Hjälpreda i hushållet! 🧹', body_sv = 'Vill barnet ta en trasa och damma eller leka med sopborsten? Att barnet härmar dig är ett fint tecken på utveckling.', title_vi = 'Trợ thủ việc nhà! 🧹', body_vi = 'Bé muốn cầm khăn lau bụi hay chơi với cây chổi? Việc bé bắt chước mẹ là dấu hiệu phát triển tuyệt vời.', title_zh = '家务小帮手！🧹', body_zh = '宝宝抢着拿抹布擦灰，或者玩扫帚？他模仿你，是发育良好的美好表现。' WHERE id = '4c4da832-707f-472e-a209-374acff11d94' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tienes preguntas sobre su desarrollo? 🤖', body_es = 'Si algo de la etapa de los 13-14 meses te preocupa, escribe a nuestro asistente Anacan AI incluso de madrugada.', title_fr = 'Des questions sur son développement ? 🤖', body_fr = 'Quelque chose vous préoccupe sur la période des 13-14 mois ? Écrivez à notre assistant Anacan AI, même en pleine nuit.', title_hi = 'बच्चे के विकास को लेकर सवाल हैं? 🤖', body_hi = 'अगर 13-14 महीने के दौर को लेकर कुछ भी आपको परेशान कर रहा है, तो रात में भी हमारे Anacan AI असिस्टेंट को लिखिए।', title_id = 'Ada pertanyaan tentang perkembangan anak? 🤖', body_id = 'Kalau ada yang Anda pikirkan tentang usia 13-14 bulan, tulis ke asisten Anacan AI kami, bahkan di malam hari.', title_ja = 'お子さんの発達で気になることは？🤖', body_ja = '1歳1-2か月の時期について気になることがあれば、夜中でもAnacan AIアシスタントに書き込んでみましょう。', title_ko = '아이 발달에 대해 궁금한 게 있나요? 🤖', body_ko = '13-14개월 시기에 대해 고민되는 게 있다면 늦은 밤에도 Anacan AI 도우미에게 물어보세요.', title_nl = 'Vragen over de ontwikkeling van je kind? 🤖', body_nl = 'Zit je iets dwars over de periode van 13-14 maanden? Schrijf onze assistent Anacan AI, zelfs midden in de nacht.', title_pl = 'Masz pytania o rozwój dziecka? 🤖', body_pl = 'Jeśli coś cię niepokoi w okresie 13-14 miesięcy, napisz do naszego asystenta Anacan AI, nawet w nocy.', title_pt = 'Tem dúvidas sobre o desenvolvimento infantil? 🤖', body_pt = 'Se alguma coisa sobre a fase dos 13-14 meses a preocupa, escreva ao nosso assistente Anacan AI, mesmo de madrugada.', title_sv = 'Har du frågor om barnets utveckling? 🤖', body_sv = 'Om något oroar dig kring perioden 13-14 månader, skriv till vår assistent Anacan AI, även sent på natten.', title_vi = 'Mẹ có câu hỏi về sự phát triển của bé? 🤖', body_vi = 'Nếu có điều gì khiến mẹ băn khoăn về giai đoạn 13-14 tháng, hãy nhắn cho trợ lý Anacan AI, ngay cả lúc nửa đêm.', title_zh = '对宝宝发育有疑问？🤖', body_zh = '如果13-14个月这个阶段有什么让你挂心的事，哪怕深夜也可以给我们的Anacan AI助手留言。' WHERE id = 'ca45e311-dc2b-43fe-aa24-08a197d26f0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primeros experimentos con lápices 🖍', body_es = '️ Dale ceras gruesas adecuadas y observa con cariño cómo garabatea en el papel. ¡Quizá estés criando a un futuro artista!', title_fr = 'Premiers essais de crayon. 🖍', body_fr = '️ Donnez-lui de gros crayons adaptés et regardez-le gribouiller avec amour. Un futur artiste grandit peut-être sous vos yeux !', title_hi = 'पेंसिल के पहले प्रयोग। 🖍', body_hi = '️ उसे सही मोटे रंग दीजिए और कागज़ पर उसकी आड़ी-तिरछी लकीरें प्यार से देखिए। शायद भविष्य का कोई कलाकार बड़ा हो रहा है!', title_id = 'Percobaan pertama dengan krayon. 🖍', body_id = '️ Berikan krayon tebal yang sesuai dan perhatikan dengan penuh cinta saat ia mencoret-coret kertas. Mungkin seorang pelukis masa depan sedang tumbuh!', title_ja = 'はじめてのクレヨン体験 🖍', body_ja = '️年齢に合った太いクレヨンを渡して、紙にお絵かきする姿を愛情をこめて見守りましょう。未来の画家が育っているかもしれません！', title_ko = '첫 크레용 체험. 🖍', body_ko = '️아이에게 맞는 굵은 크레용을 주고 종이에 끄적이는 모습을 사랑스럽게 지켜보세요. 미래의 화가가 자라고 있을지도 몰라요!', title_nl = 'Eerste krabbels met kleurpotlood. 🖍', body_nl = '️ Geef je kindje geschikte dikke kleurpotloden en kijk liefdevol toe hoe hij op papier krast. Misschien groeit hier een toekomstige kunstenaar op!', title_pl = 'Pierwsze próby z kredkami. 🖍', body_pl = '️ Daj mu odpowiednie grube kredki i z miłością obserwuj, jak bazgrze po kartce. Może rośnie przyszły artysta!', title_pt = 'As primeiras experiências com lápis. 🖍', body_pt = '️ Dê-lhe lápis de cor grossos adequados e veja com carinho os rabiscos dele na folha. Talvez esteja a crescer aí um artista do futuro!', title_sv = 'De första kritförsöken. 🖍', body_sv = '️ Ge tjocka kritor som passar barnet och följ kärleksfullt klottret på papperet. Kanske växer en framtida konstnär upp!', title_vi = 'Những nét bút màu đầu tiên. 🖍', body_vi = '️ Hãy đưa cho bé bút màu to phù hợp và âu yếm ngắm bé vẽ nguệch ngoạc trên giấy. Biết đâu một họa sĩ tương lai đang lớn lên!', title_zh = '第一次用蜡笔 🖍', body_zh = '️ 给宝宝合适的粗蜡笔，满怀爱意地看他在纸上涂鸦。说不定一位未来的画家正在成长！' WHERE id = '2064ec2b-0483-4d3b-9453-106b6b9f32f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Jugar solo con sus juguetes 🧩', body_es = 'Que pueda jugar solo, aunque sea un rato, es un gran paso hacia la independencia. Obsérvale desde lejos.', title_fr = 'Jouer seul avec ses jouets. 🧩', body_fr = 'Pouvoir jouer seul, même un court moment, est un grand pas vers l''autonomie. Observez-le de loin.', title_hi = 'अपने खिलौनों से अकेले खेलना। 🧩', body_hi = 'थोड़ी देर के लिए ही सही, उसका अपने आप खेल पाना आत्मनिर्भरता की ओर बड़ा कदम है। उसे दूर से देखिए।', title_id = 'Bermain sendiri dengan mainannya. 🧩', body_id = 'Kemampuannya bermain sendiri, meski sebentar, adalah langkah besar menuju kemandirian. Perhatikan ia dari jauh.', title_ja = '自分のおもちゃでひとり遊び 🧩', body_ja = '短い時間でもひとりで遊べるのは、自立への大きな一歩です。少し離れたところから見守りましょう。', title_ko = '자기 장난감으로 혼자 놀기. 🧩', body_ko = '잠깐이라도 혼자 놀 수 있다는 건 독립을 향한 큰 걸음이에요. 멀리서 지켜봐 주세요.', title_nl = 'Alleen spelen met zijn speelgoed. 🧩', body_nl = 'Dat je kindje, al is het maar even, alleen kan spelen, is een grote stap naar zelfstandigheid. Kijk van een afstandje toe.', title_pl = 'Samodzielna zabawa własnymi zabawkami. 🧩', body_pl = 'To, że potrafi choć chwilę bawić się sam, to wielki krok ku samodzielności. Obserwuj go z daleka.', title_pt = 'Brincar sozinho com os seus brinquedos. 🧩', body_pt = 'Conseguir brincar sozinho, mesmo por pouco tempo, é um grande passo de independência. Observe-o à distância.', title_sv = 'Leker själv med sina leksaker. 🧩', body_sv = 'Att barnet kan leka själv, även en kort stund, är ett stort steg mot självständighet. Följ barnet på avstånd.', title_vi = 'Tự chơi với đồ chơi của mình. 🧩', body_vi = 'Bé có thể tự chơi dù chỉ trong thời gian ngắn là một bước tiến lớn về sự tự lập. Hãy dõi theo bé từ xa.', title_zh = '自己玩玩具 🧩', body_zh = '哪怕只能自己玩一小会儿，也是迈向独立的一大步。远远地看着他吧。' WHERE id = '7f86b541-f24f-46cc-bf72-a538c8e62fa0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue creciendo 📏', body_es = '¡Se le queda pequeña la ropa! Añade su nueva altura y su nuevo peso en el Seguimiento del desarrollo y sigue su evolución.', title_fr = 'Il continue de grandir. 📏', body_fr = 'Ses vêtements deviennent trop petits ! Ajoutez sa nouvelle taille et son nouveau poids dans le Suivi de croissance et suivez son évolution.', title_hi = 'बढ़ना जारी है। 📏', body_hi = 'बच्चे के कपड़े छोटे हो रहे हैं! ग्रोथ ट्रैकर सेक्शन में नई लंबाई और वज़न जोड़िए और विकास पर नज़र रखिए।', title_id = 'Terus tumbuh. 📏', body_id = 'Baju si kecil mulai kekecilan! Tambahkan tinggi dan berat terbarunya di Pelacak Pertumbuhan dan pantau perkembangannya.', title_ja = 'ぐんぐん成長中 📏', body_ja = 'お洋服が小さくなってきました！「発達トラッカー」に新しい身長と体重を追加して、成長を見守りましょう。', title_ko = '계속 자라요. 📏', body_ko = '아이 옷이 작아지고 있어요! 성장 기록에 새 키와 몸무게를 추가하고 발달을 지켜보세요.', title_nl = 'Hij blijft groeien. 📏', body_nl = 'De kleertjes van je kindje worden te klein! Voeg de nieuwe lengte en het nieuwe gewicht toe in de Groeitracker en volg zijn ontwikkeling.', title_pl = 'Rośniemy dalej. 📏', body_pl = 'Ubranka robią się za małe! Dodaj nowy wzrost i wagę w sekcji Śledzenie rozwoju i obserwuj jego rozwój.', title_pt = 'Continua a crescer. 📏', body_pt = 'A roupa do seu filho está a ficar pequena! Adicione a nova altura e o novo peso no Registo de Desenvolvimento e acompanhe o crescimento.', title_sv = 'Tillväxten fortsätter. 📏', body_sv = 'Barnets kläder blir för små! Lägg in ny längd och vikt i Tillväxtspåraren och följ utvecklingen.', title_vi = 'Tiếp tục lớn khôn. 📏', body_vi = 'Quần áo của bé đang chật dần! Hãy thêm chiều cao và cân nặng mới vào mục Theo dõi phát triển để theo dõi sự phát triển của bé.', title_zh = '继续长大 📏', body_zh = '宝宝的衣服变小了！在发育追踪里添加新的身高和体重数据，关注宝宝的成长吧。' WHERE id = 'f945146d-2bbb-40d9-95f6-29bdc7f3be6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cómo lidiar con la selectividad 🍲', body_es = 'Algunos días puede rechazar su comida favorita. No le obligues, simplemente ofrécele alternativas distintas.', title_fr = 'Face aux refus à table. 🍲', body_fr = 'Certains jours, il peut refuser son plat préféré. Ne le forcez pas, proposez-lui simplement d''autres options.', title_hi = 'खाने के नखरों से निपटना। 🍲', body_hi = 'किसी दिन वह अपना सबसे पसंदीदा खाना भी मना कर सकता है। ज़बरदस्ती मत कीजिए, बस अलग विकल्प दीजिए।', title_id = 'Menghadapi anak pilih-pilih makanan. 🍲', body_id = 'Ada hari-hari ia menolak makanan favoritnya. Jangan dipaksa, cukup tawarkan alternatif lain.', title_ja = '好き嫌いとの付き合い方 🍲', body_ja = '大好きな料理を嫌がる日もあります。無理強いせず、別のメニューをすすめてみましょう。', title_ko = '편식과 씨름하기. 🍲', body_ko = '어떤 날은 가장 좋아하던 음식도 거부할 수 있어요. 억지로 먹이지 말고 다른 대안을 권해 주세요.', title_nl = 'Omgaan met kieskeurig eten. 🍲', body_nl = 'Op sommige dagen weigert je kindje misschien zijn lievelingseten. Dwing hem niet, bied gewoon andere opties aan.', title_pl = 'Jak radzić sobie z wybiórczością w jedzeniu. 🍲', body_pl = 'Niektórego dnia może odmówić nawet ulubionego dania. Nie zmuszaj go, po prostu proponuj inne opcje.', title_pt = 'Lidar com a esquisitice à mesa. 🍲', body_pt = 'Há dias em que pode recusar a comida de que mais gosta. Não o obrigue, ofereça simplesmente outras alternativas.', title_sv = 'Kampen mot kräsenheten. 🍲', body_sv = 'Vissa dagar kan barnet vägra sin favoritmat. Tvinga inte, erbjud bara andra alternativ.', title_vi = 'Đối phó với chứng kén ăn. 🍲', body_vi = 'Có những ngày bé từ chối cả món yêu thích nhất. Đừng ép, chỉ cần đưa ra những lựa chọn khác.', title_zh = '应对挑食 🍲', body_zh = '有些日子宝宝可能连最爱吃的都不吃。别强迫，换些其他选择试试就好。' WHERE id = '241a81f3-8158-4d3c-a8b2-640a1b060696' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baño de la noche 🛁', body_es = 'Un baño templado es divertido para quitarse la suciedad del día y además le relaja y le prepara perfectamente para dormir.', title_fr = 'Le bain du soir. 🛁', body_fr = 'Un bain tiède est amusant pour se débarrasser de la poussière de la journée, et il le détend pour bien le préparer au sommeil.', title_hi = 'शाम का स्नान। 🛁', body_hi = 'गुनगुना स्नान दिनभर की धूल-मिट्टी धोने के लिए मज़ेदार भी है और उसे आराम देकर नींद के लिए पूरी तरह तैयार भी करता है।', title_id = 'Mandi sore. 🛁', body_id = 'Mandi air hangat tidak hanya seru untuk membersihkan debu seharian, tapi juga membuatnya rileks dan siap tidur.', title_ja = '夜のお風呂 🛁', body_ja = 'ぬるめのお風呂は、一日の汚れを落とす楽しい時間であり、リラックスして眠りへの準備もばっちり整えてくれます。', title_ko = '저녁 목욕. 🛁', body_ko = '따뜻한 목욕은 하루의 먼지를 씻어 내는 즐거운 시간이자, 몸을 편안하게 해 잠들 준비를 완벽하게 해 줘요.', title_nl = 'Avondbadje. 🛁', body_nl = 'Een lauw badje is leuk om het stof van de dag af te spoelen en maakt je kindje ook rustig, zodat hij perfect klaar is om te slapen.', title_pl = 'Wieczorna kąpiel. 🛁', body_pl = 'Ciepła kąpiel to zabawny sposób na zmycie kurzu całego dnia, a przy tym rozluźnia go i idealnie przygotowuje do snu.', title_pt = 'O banho da noite. 🛁', body_pt = 'Um banho morno é divertido para tirar o pó do dia e, ao mesmo tempo, relaxa-o e prepara-o na perfeição para dormir.', title_sv = 'Kvällsbad. 🛁', body_sv = 'Ett ljummet bad är både roligt för att tvätta bort dagens smuts och avslappnande, så att barnet blir perfekt förberett för sömnen.', title_vi = 'Tắm buổi tối. 🛁', body_vi = 'Tắm nước ấm vừa là trò vui để rửa sạch bụi bặm cả ngày, vừa giúp bé thư giãn và sẵn sàng cho giấc ngủ.', title_zh = '晚间洗澡 🛁', body_zh = '温水澡既能好玩地洗去一天的尘土，又能让宝宝放松，为入睡做好准备。' WHERE id = '4716a93b-966d-4c69-b174-c2a48e9a09fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reconoce las partes del cuerpo 👃', body_es = 'Jugad a «¿Dónde está tu nariz?» o «¿Dónde está tu oreja?». Cuando acierte, anímale con aplausos.', title_fr = 'Il reconnaît les parties du corps. 👃', body_fr = 'Jouez à « Où est ton nez ? » ou « Où est ton oreille ? ». Quand il trouve, applaudissez-le pour l''encourager.', title_hi = 'शरीर के अंग पहचानता है। 👃', body_hi = '''नाक कहाँ है?'' या ''कान कहाँ है?'' वाला खेल खेलिए। सही जगह दिखाने पर तालियाँ बजाकर उसका हौसला बढ़ाइए।', title_id = 'Mengenal anggota tubuh. 👃', body_id = 'Mainkan permainan "Hidungnya mana?" atau "Telinganya mana?". Saat ia menunjuk dengan benar, semangati ia dengan tepuk tangan.', title_ja = '体の部分がわかる 👃', body_ja = '「お鼻はどこ？」「お耳はどこ？」遊びをしましょう。正しく指させたら、拍手で褒めてあげて。', title_ko = '신체 부위를 알아요. 👃', body_ko = '"코 어디 있어?", "귀 어디 있어?" 놀이를 해 보세요. 맞히면 박수 치며 칭찬해 주세요.', title_nl = 'Herkent lichaamsdelen. 👃', body_nl = 'Speel het spelletje: waar is je neus? of: waar is je oor? Klap voor hem als hij het goed aanwijst.', title_pl = 'Rozpoznaje części ciała. 👃', body_pl = 'Pobawcie się w „Gdzie masz nos?” albo „Gdzie masz ucho?”. Gdy dobrze wskaże, zachęć go brawami.', title_pt = 'Reconhece as partes do corpo. 👃', body_pt = 'Brinquem ao "Onde está o nariz?" ou "Onde está a orelha?". Quando acertar, encoraje-o com aplausos.', title_sv = 'Känner igen kroppsdelar. 👃', body_sv = 'Lek ”Var är näsan?” eller ”Var är örat?”. Applådera och uppmuntra när barnet hittar rätt.', title_vi = 'Bé nhận biết các bộ phận cơ thể. 👃', body_vi = 'Hãy chơi trò "Mũi con đâu?" hay "Tai con đâu?". Khi bé chỉ đúng, hãy vỗ tay khích lệ bé nhé.', title_zh = '认识身体部位 👃', body_zh = '玩“鼻子在哪里？”或“耳朵在哪里？”的游戏。找对了就鼓掌鼓励他。' WHERE id = 'dbbcb16c-cf48-47f7-92ab-992ed2fab247' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Cuando alguien se va, dice adiós con la mano por iniciativa propia! Un reflejo social precioso. Anímale mucho.', body_fr = 'Quand quelqu''un s''en va, il fait au revoir de la main de lui-même ! Un beau réflexe social. Encouragez-le beaucoup.', body_hi = 'कोई दरवाज़े से निकलता है तो वह खुद हाथ हिलाकर बाय करता है! एक खूबसूरत सामाजिक आदत। उसका खूब हौसला बढ़ाइए।', body_id = 'Saat seseorang keluar pintu, ia melambaikan tangan atas inisiatifnya sendiri! Refleks sosial yang indah. Beri ia banyak semangat.', body_ja = '誰かが帰るとき、自分から手を振ってバイバイしますか！すてきな社会性の表れです。たくさん褒めてあげましょう。', body_ko = '누가 문을 나서면 스스로 손을 흔들며 인사해요! 멋진 사회적 반응이에요. 많이 칭찬해 주세요.', body_nl = 'Zwaait je kindje uit zichzelf gedag als iemand de deur uitgaat? Een mooie sociale reflex. Moedig hem veel aan.', body_pl = 'Gdy ktoś wychodzi, sam z siebie macha na pożegnanie! To piękny odruch społeczny. Często go chwal i zachęcaj.', body_pt = 'Quando alguém sai pela porta, diz adeus com a mão por iniciativa própria! Um belo reflexo social. Encoraje-o muito.', body_sv = 'När någon går vinkar barnet hej då på eget initiativ! En fin social reflex. Uppmuntra barnet massor.', body_vi = 'Có người ra về là bé tự vẫy tay chào tạm biệt! Một phản xạ xã hội thật đáng yêu. Hãy khích lệ bé thật nhiều.', body_zh = '有人出门时，宝宝会主动挥手说再见！这是很棒的社交反应。多多鼓励他吧。' WHERE id = 'f39f5c34-c612-4758-a438-ed52b2d49ba8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Crees que algo falla en su rutina de sueño? Pregunta al momento a Anacan AI todo lo que te genere dudas y quédate tranquila.', body_fr = 'Vous pensez vous tromper dans son rituel du coucher ? Posez tout de suite vos questions à Anacan AI et soyez rassurée.', body_hi = 'लगता है नींद के रूटीन में कुछ गलत कर रही हैं? जिस भी बात पर दुविधा है, तुरंत Anacan AI से पूछिए और निश्चिंत हो जाइए।', body_id = 'Merasa ada yang salah dengan rutinitas tidurnya? Tanyakan semua keraguan Anda ke Anacan AI saat itu juga dan tenangkan diri.', body_ja = '寝かしつけの習慣で、何か間違えているかもと不安ですか？迷っていることは、すぐにAnacan AIに聞いて安心しましょう。', body_ko = '수면 루틴에서 뭔가 잘못하고 있는 것 같나요? 망설여지는 건 무엇이든 바로 Anacan AI에게 물어보고 마음을 놓으세요.', body_nl = 'Denk je dat je iets fout doet met de slaaproutine? Vraag Anacan AI meteen alles waar je over twijfelt en stel jezelf gerust.', body_pl = 'Myślisz, że robisz coś źle w rutynie snu? Od razu zapytaj Anacan AI o wszystko, co budzi twoje wątpliwości, i odetchnij.', body_pt = 'Acha que está a fazer algo errado na rotina de sono? Pergunte já ao Anacan AI tudo aquilo de que duvida e fique descansada.', body_sv = 'Tror du att du gör något fel i sömnrutinen? Fråga Anacan AI direkt om allt du är osäker på och slappna av.', body_vi = 'Mẹ nghĩ mình đang làm sai điều gì đó với nếp ngủ của bé? Hãy hỏi ngay Anacan AI mọi điều còn băn khoăn để yên tâm hơn.', body_zh = '觉得自己在睡前作息上做错了什么？任何拿不准的事都可以马上问Anacan AI，让自己安心。' WHERE id = '0dcb1657-4eeb-47c5-a193-84ed106d43bc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Siguen los despertares nocturnos? 😴', body_es = 'Si en los últimos días su sueño se ha vuelto a alterar, analiza el horario con el Temporizador de sueño de Anacan y busca los huecos de la rutina.', title_fr = 'Les réveils nocturnes continuent ? 😴', body_fr = 'Son sommeil est de nouveau perturbé ces derniers jours ? Analysez son planning avec le minuteur de sommeil Anacan pour repérer les failles dans son rythme.', title_hi = 'रात में जागना जारी है? 😴', body_hi = 'अगर पिछले दिनों उसकी नींद फिर बिगड़ गई है, तो Anacan स्लीप टाइमर से शेड्यूल का विश्लेषण करके रूटीन की कमियाँ ढूँढिए।', title_id = 'Masih sering terbangun malam? 😴', body_id = 'Kalau beberapa hari terakhir tidurnya terganggu lagi, analisis jadwalnya dengan Timer Tidur Anacan dan cari celah dalam rutinitasnya.', title_ja = '夜中に起きるのが続いている？😴', body_ja = '最近また睡眠が乱れているなら、Anacanの睡眠タイマーでスケジュールを分析し、生活リズムのすき間を探してみましょう。', title_ko = '밤에 계속 깨나요? 😴', body_ko = '최근 며칠 잠이 다시 흐트러졌다면 Anacan 수면 타이머로 일정을 분석해 일과의 빈틈을 찾아보세요.', title_nl = 'Nog steeds ''s nachts wakker? 😴', body_nl = 'Is de slaap de laatste dagen weer verstoord? Analyseer het schema met de Slaaptimer van Anacan en zoek de gaten in het ritme.', title_pl = 'Nocne pobudki trwają? 😴', body_pl = 'Jeśli w ostatnich dniach sen znów się rozregulował, przeanalizuj plan timerem snu Anacan i poszukaj luk w rytmie dnia.', title_pt = 'Os despertares noturnos continuam? 😴', body_pt = 'Se nos últimos dias o sono voltou a desregular-se, analise o horário com o temporizador de sono do Anacan e procure as falhas na rotina.', title_sv = 'Fortsätter de nattliga uppvaknandena? 😴', body_sv = 'Om sömnen har störts igen de senaste dagarna, analysera schemat med Anacans sömntimer och leta efter luckor i rutinen.', title_vi = 'Bé vẫn thức giấc ban đêm? 😴', body_vi = 'Nếu mấy ngày gần đây giấc ngủ của bé lại bị xáo trộn, hãy phân tích biểu đồ bằng Bộ hẹn giờ ngủ của Anacan để tìm ra những chỗ chưa ổn trong lịch sinh hoạt.', title_zh = '夜醒还在继续？😴', body_zh = '如果最近几天睡眠又乱了，用Anacan睡眠计时器分析一下图表，找找作息里的空档。' WHERE id = '10d800e4-c6bd-4325-b22e-385edaca8f7f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres la mejor! 💖', body_es = 'Criar a un hijo es una maratón. Esta noche dedícate un rato: ve tu película favorita o simplemente descansa tranquila.', title_fr = 'Vous êtes la meilleure ! 💖', body_fr = 'Élever un enfant, c''est un marathon. Ce soir, prenez un peu de temps pour vous, regardez un film que vous aimez ou reposez-vous simplement au calme.', title_hi = 'आप सबसे अच्छी हैं! 💖', body_hi = 'बच्चे को पालना मैराथन जैसा है। आज शाम अपने लिए थोड़ा समय निकालिए, अपनी पसंदीदा फ़िल्म देखिए या बस शांति से आराम कीजिए।', title_id = 'Anda yang terbaik! 💖', body_id = 'Membesarkan anak itu seperti maraton. Malam ini, luangkan sedikit waktu untuk diri sendiri: tonton film favorit atau sekadar beristirahat dengan tenang.', title_ja = 'あなたは最高です！💖', body_ja = '子育てはマラソンのようなもの。今夜は少し自分のための時間をつくって、好きな映画を観たり、ただ静かに休んだりしましょう。', title_ko = '엄마가 최고예요! 💖', body_ko = '육아는 마라톤 같아요. 오늘 저녁은 나를 위한 시간을 조금 내어 좋아하는 영화를 보거나 그냥 조용히 쉬어 보세요.', title_nl = 'Je bent de beste! 💖', body_nl = 'Een kind opvoeden is een marathon. Neem vanavond wat tijd voor jezelf, kijk een film die je leuk vindt of rust gewoon rustig uit.', title_pl = 'Jesteś najlepsza! 💖', body_pl = 'Wychowywanie dziecka to maraton. Znajdź dziś wieczorem trochę czasu dla siebie, obejrzyj ulubiony film albo po prostu spokojnie odpocznij.', title_pt = 'É a melhor! 💖', body_pt = 'Criar um filho é uma maratona. Esta noite, reserve um pouco de tempo para si, veja um filme de que goste ou simplesmente descanse com calma.', title_sv = 'Du är bäst! 💖', body_sv = 'Att uppfostra ett barn är som ett maraton. Ta lite tid för dig själv i kväll, se en film du gillar eller bara vila i lugn och ro.', title_vi = 'Mẹ là tuyệt nhất! 💖', body_vi = 'Nuôi con giống như chạy marathon. Tối nay hãy dành chút thời gian cho bản thân, xem một bộ phim yêu thích hoặc đơn giản là nghỉ ngơi yên tĩnh.', title_zh = '你是最棒的！💖', body_zh = '养孩子就像跑马拉松。今晚给自己留点时间，看一部喜欢的电影，或者就安安静静地休息。' WHERE id = '0cc0cda4-4fef-4e92-9af2-cd065cfee008' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Arrastra sus juguetes! 🧸', body_es = 'Los juguetes de arrastre con cuerda o los carritos para empujar son ahora su diversión favorita. ¡Es un ejercicio estupendo para el equilibrio!', title_fr = 'Il traîne ses jouets ! 🧸', body_fr = 'Les jouets à tirer avec une ficelle ou les petits chariots à pousser sont désormais ses jeux préférés. C''est un excellent exercice d''équilibre !', title_hi = 'खिलौने खींचता फिरता है! 🧸', body_hi = 'डोरी से खींचे जाने वाले खिलौने या धकेलने वाली छोटी गाड़ियाँ अब उसका सबसे पसंदीदा मनोरंजन हैं। यह संतुलन बनाने के लिए बढ़िया अभ्यास है!', title_id = 'Menarik mainannya ke mana-mana! 🧸', body_id = 'Mainan tarik bertali atau gerobak kecil yang bisa didorong kini jadi hiburan favoritnya. Ini latihan yang bagus untuk menjaga keseimbangan!', title_ja = 'おもちゃを引っぱって歩く！🧸', body_ja = 'ひもで引くおもちゃや、押して歩ける小さなカートが今いちばんのお気に入り。バランス感覚を育てるすばらしい練習です！', title_ko = '장난감을 끌고 다녀요! 🧸', body_ko = '줄로 끄는 장난감이나 밀고 다닐 수 있는 작은 수레가 요즘 가장 좋아하는 놀이예요. 균형 잡기에 아주 좋은 연습이에요!', title_nl = 'Trekt zijn speelgoed mee! 🧸', body_nl = 'Trekspeelgoed aan een touwtje of kleine duwkarretjes zijn nu zijn favoriete vermaak. Dat is een prima oefening voor zijn evenwicht!', title_pl = 'Ciągnie swoje zabawki! 🧸', body_pl = 'Zabawki na sznurku lub małe wózki do pchania to teraz jego ulubiona rozrywka. To świetne ćwiczenie równowagi!', title_pt = 'Arrasta os brinquedos atrás de si! 🧸', body_pt = 'Brinquedos de puxar com um fio ou carrinhos pequenos que possa empurrar são agora a sua diversão preferida. É um ótimo treino de equilíbrio!', title_sv = 'Drar runt leksakerna! 🧸', body_sv = 'Dragleksaker eller små vagnar att skjuta på är nu barnets favoritnöje. Det är en utmärkt övning för balansen!', title_vi = 'Bé kéo đồ chơi đi khắp nơi! 🧸', body_vi = 'Đồ chơi kéo dây hay những chiếc xe đẩy nhỏ giờ là trò bé yêu thích nhất. Đây là bài tập tuyệt vời để giữ thăng bằng!', title_zh = '拖着玩具走！🧸', body_zh = '拉绳玩具或能推着走的小车，是宝宝现在最喜欢的游戏。这是练习平衡的好方法！' WHERE id = '781ac9f7-7fd3-4466-9d70-0b41dd1e954a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuídate tú también 🥗', body_es = 'Seguir el ritmo de un niño tan enérgico no es fácil. Prepara en Recetas saludables para mujeres un plato rico y lleno de vitaminas que te devuelva la energía.', title_fr = 'Nourrissez-vous aussi. 🥗', body_fr = 'Suivre un enfant plein d''énergie n''est pas facile. Préparez une portion savoureuse et vitaminée grâce aux Recettes saines pour femmes pour refaire le plein d''énergie.', title_hi = 'खुद को भी पोषण दीजिए। 🥗', body_hi = 'ऊर्जा से भरे बच्चे के साथ कदम मिलाना मुश्किल है। महिलाओं के लिए सेहतमंद रेसिपी से अपनी ऊर्जा लौटाने वाला कोई स्वादिष्ट और विटामिन से भरपूर खाना बनाइए।', title_id = 'Beri nutrisi untuk diri Anda juga. 🥗', body_id = 'Mengimbangi anak yang energik itu tidak mudah. Siapkan hidangan lezat kaya vitamin dari Resep Sehat untuk wanita yang akan memulihkan energi Anda.', title_ja = '自分にも栄養を 🥗', body_ja = '元気いっぱいの子についていくのは大変です。「女性のためのヘルシーレシピ」から、エネルギーを取り戻せるおいしくてビタミンたっぷりの一品をつくりましょう。', title_ko = '엄마도 잘 챙겨 드세요. 🥗', body_ko = '에너지 넘치는 아이를 따라가기란 쉽지 않아요. 건강한 레시피에서 기운을 되찾아 줄 맛있고 비타민 가득한 한 끼를 만들어 보세요.', title_nl = 'Zorg ook voor jezelf. 🥗', body_nl = 'Een energiek kindje bijhouden is zwaar. Maak uit Gezonde recepten voor vrouwen een lekkere, vitaminerijke portie die je energie teruggeeft.', title_pl = 'Zadbaj też o siebie. 🥗', body_pl = 'Trudno nadążyć za energicznym dzieckiem. Przygotuj ze Zdrowych przepisów dla kobiet smaczne, bogate w witaminy danie, które przywróci ci energię.', title_pt = 'Alimente-se também a si. 🥗', body_pt = 'Acompanhar uma criança cheia de energia é difícil. Prepare nas Receitas Saudáveis para Mulheres uma refeição saborosa e rica em vitaminas que lhe devolva a energia.', title_sv = 'Ta hand om dig själv också. 🥗', body_sv = 'Det är svårt att hänga med ett energiskt barn. Gör en god och vitaminrik portion från Hälsosamma recept för kvinnor som fyller på energin.', title_vi = 'Mẹ cũng cần được nuôi dưỡng. 🥗', body_vi = 'Theo kịp một em bé hiếu động thật không dễ. Hãy chuẩn bị một phần ăn ngon, giàu vitamin từ Công thức lành mạnh cho phụ nữ để lấy lại năng lượng.', title_zh = '也要照顾好自己 🥗', body_zh = '跟上精力充沛的宝宝可不容易。从女性健康食谱里做一份美味又富含维生素的餐点，帮自己恢复能量。' WHERE id = '7dec83e1-5089-42b4-a2b5-f3d997eb1138' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¡Yo solo!» 🧦', body_es = 'Si intenta ponerse los calcetines o comer él solo, no se lo impidas. Su independencia crece justo con estos pequeños intentos.', title_fr = 'La période du « Tout seul ! ». 🧦', body_fr = 'S''il essaie de mettre ses chaussettes ou de manger seul, ne l''en empêchez pas. C''est grâce à ces petits essais que se développe son sens de l''autonomie.', title_hi = '''मैं खुद!'' की ज़िद। 🧦', body_hi = 'अगर वह खुद मोज़े पहनने या खुद खाना खाने की कोशिश करता है, तो उसे मत रोकिए। आत्मनिर्भरता की भावना इन्हीं छोटी कोशिशों से बढ़ती है।', title_id = 'Fase "Aku sendiri!". 🧦', body_id = 'Kalau ia mencoba memakai kaus kaki sendiri atau makan sendiri, jangan dihalangi. Rasa mandirinya tumbuh justru lewat usaha-usaha kecil ini.', title_ja = '「自分で！」の時期 🧦', body_ja = '靴下を自分で履こうとしたり、自分で食べようとしたりしたら、止めないであげて。自立心はこんな小さな挑戦から育ちます。', title_ko = '"내가 할래!" 고집. 🧦', body_ko = '양말을 혼자 신거나 혼자 밥을 먹으려 한다면 막지 마세요. 독립심은 바로 이런 작은 시도로 자라요.', title_nl = 'Zelf doen! 🧦', body_nl = 'Probeert je kindje zelf zijn sokken aan te trekken of zelf te eten? Houd hem niet tegen. Juist met zulke kleine pogingen groeit zijn zelfstandigheid.', title_pl = 'Upór „Sam!”. 🧦', body_pl = 'Jeśli próbuje sam założyć skarpetki lub samodzielnie jeść, nie przeszkadzaj mu. Poczucie samodzielności rozwija się właśnie dzięki takim małym próbom.', title_pt = 'A teimosia do "Sozinho!". 🧦', body_pt = 'Se tenta calçar as meias ou comer sozinho, não o impeça. O sentido de independência desenvolve-se precisamente com estas pequenas tentativas.', title_sv = 'Envisheten med ”Själv!”. 🧦', body_sv = 'Försöker barnet sätta på sig strumporna själv eller äta själv, hindra det inte. Självständigheten utvecklas just genom dessa små försök.', title_vi = 'Giai đoạn "Con tự làm!" 🧦', body_vi = 'Nếu bé cố tự mang tất hay tự ăn, đừng ngăn bé. Cảm giác tự lập phát triển chính nhờ những lần thử nhỏ này.', title_zh = '“我自己来！”的倔强 🧦', body_zh = '如果宝宝想自己穿袜子或自己吃饭，就别拦着他。独立感正是在这些小小的尝试中培养起来的。' WHERE id = '6942d3e7-d39d-4aee-b8a0-ef2313920693' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubrimientos al aire libre 🌳', body_es = 'Tocar hojas y recoger piedras en el parque desarrolla sus sentidos. Elige un parque nuevo para pasear.', title_fr = 'Découvertes en plein air. 🌳', body_fr = 'Toucher les feuilles et ramasser des cailloux au parc éveille ses sens. Choisissez un nouveau parc pour votre balade.', title_hi = 'ताज़ी हवा में खोजें। 🌳', body_hi = 'पार्क में पत्तियों को छूना, पत्थर इकट्ठे करना उसकी इंद्रियों को विकसित करता है। सैर के लिए कोई नया पार्क चुनिए।', title_id = 'Penjelajahan di udara segar. 🌳', body_id = 'Menyentuh daun dan mengumpulkan batu di taman mengembangkan indranya. Pilih taman baru untuk jalan-jalan.', title_ja = '外の空気で発見がいっぱい 🌳', body_ja = '公園で葉っぱにさわったり、石を集めたりすることで、感覚が育ちます。お散歩に新しい公園を選んでみましょう。', title_ko = '바깥 공기 속 발견. 🌳', body_ko = '공원에서 나뭇잎을 만지고 돌멩이를 모으는 일이 감각을 발달시켜요. 산책할 새로운 공원을 골라 보세요.', title_nl = 'Ontdekkingen in de frisse lucht. 🌳', body_nl = 'Blaadjes aanraken en steentjes verzamelen in het park prikkelt zijn zintuigen. Kies een nieuw park voor jullie wandeling.', title_pl = 'Odkrycia na świeżym powietrzu. 🌳', body_pl = 'Dotykanie liści i zbieranie kamyków w parku rozwija jego zmysły. Wybierz na spacer nowy park.', title_pt = 'Descobertas ao ar livre. 🌳', body_pt = 'Tocar nas folhas e apanhar pedrinhas no parque desenvolve os sentidos. Escolha um parque novo para o passeio.', title_sv = 'Upptäckter i friska luften. 🌳', body_sv = 'Att röra vid löv och samla stenar i parken utvecklar sinnena. Välj en ny park för promenaden.', title_vi = 'Khám phá không khí trong lành. 🌳', body_vi = 'Chạm vào lá cây, nhặt sỏi ở công viên giúp phát triển các giác quan của bé. Hãy chọn một công viên mới để đi dạo nhé.', title_zh = '户外新发现 🌳', body_zh = '在公园里摸摸树叶、捡捡石子，能促进宝宝的感官发育。选一个新公园去散步吧。' WHERE id = 'e1f2089f-f46e-44ca-b5b5-5564bd6ee8fb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No olvides beber agua 💧', body_es = '¡Él y tú! Después de los juegos movidos y entre comidas, bebed agua para manteneros bien hidratados.', title_fr = 'N''oubliez pas de boire. 💧', body_fr = 'Lui comme vous ! Après les jeux énergiques et entre les repas, buvez de l''eau pour rester bien hydratés.', title_hi = 'पानी पीना मत भूलिए। 💧', body_hi = 'वह भी और आप भी! भाग-दौड़ वाले खेलों के बाद और खाने के बीच ज़रूर पानी पीकर शरीर में पानी की कमी मत होने दीजिए।', title_id = 'Jangan lupa minum air. 💧', body_id = 'Ia dan juga Anda! Setelah bermain aktif dan di sela waktu makan, pastikan minum air agar tubuh tetap terhidrasi.', title_ja = '水分補給を忘れずに 💧', body_ja = 'お子さんもあなたも！元気に遊んだあとや食事の合間に、しっかりお水を飲んで水分を保ちましょう。', title_ko = '물 마시는 걸 잊지 마세요. 💧', body_ko = '아이도, 엄마도요! 활발한 놀이 후와 식사 사이에 꼭 물을 마셔 몸에 수분을 채워 주세요.', title_nl = 'Vergeet niet te drinken. 💧', body_nl = 'Dat geldt voor jullie allebei! Drink na drukke spelletjes en tussen de maaltijden door zeker water, zodat je lichaam niet uitdroogt.', title_pl = 'Nie zapominaj o piciu wody. 💧', body_pl = 'I on, i ty! Po energicznych zabawach i między posiłkami koniecznie pijcie wodę, by dobrze nawodnić organizm.', title_pt = 'Não se esqueça de beber água. 💧', body_pt = 'Ele e a mãe! Depois de brincadeiras cheias de energia e entre as refeições, bebam água sem falta para manter o corpo hidratado.', title_sv = 'Glöm inte att dricka vatten. 💧', body_sv = 'Både barnet och du! Drick vatten efter energiska lekar och mellan måltiderna så att kroppen hålls återfuktad.', title_vi = 'Đừng quên uống nước. 💧', body_vi = 'Cả bé và mẹ! Sau những trò chơi vận động và giữa các bữa ăn, hãy nhớ uống nước để cơ thể luôn đủ nước.', title_zh = '别忘了喝水 💧', body_zh = '宝宝和你都要！玩得满头大汗后、两餐之间，一定要喝水补充水分。' WHERE id = '96b02483-42a2-4868-a751-d817b0144951' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pequeño ayudante en acción! 🧹', body_es = '¿Te imita y coge un trapo para quitar el polvo o juega con la escoba? Los niños aprenden sobre todo viendo.', title_fr = 'Petit assistant au travail ! 🧹', body_fr = 'Il vous imite en prenant un chiffon pour épousseter ou en jouant avec le balai ? Les enfants apprennent surtout en regardant.', title_hi = 'नन्हा मददगार काम पर! 🧹', body_hi = 'आपकी नकल करते हुए हाथ में कपड़ा लेकर धूल पोंछता है या झाड़ू से खेलता है? बच्चे सबसे ज़्यादा देखकर ही सीखते हैं।', title_id = 'Asisten kecil sedang bekerja! 🧹', body_id = 'Ia meniru Anda dengan mengambil lap untuk membersihkan debu atau bermain dengan sapu? Anak paling banyak belajar dengan melihat.', title_ja = '小さなお手伝いさんが活躍中！🧹', body_ja = 'あなたのまねをして、ふきんでほこりを拭いたり、ほうきで遊んだりしていますか？子どもは見て学ぶのがいちばんです。', title_ko = '꼬마 도우미 작업 중! 🧹', body_ko = '엄마를 따라 수건을 들고 먼지를 닦거나 빗자루로 노나요? 아이들은 보면서 가장 많이 배워요.', title_nl = 'Klein hulpje aan het werk! 🧹', body_nl = 'Doet je kindje je na en pakt hij een doekje om af te stoffen of speelt hij met de bezem? Kinderen leren vooral door te kijken.', title_pl = 'Mały pomocnik przy pracy! 🧹', body_pl = 'Naśladuje cię, bierze ściereczkę i ściera kurze albo bawi się miotłą? Dzieci najwięcej uczą się, patrząc.', title_pt = 'Um pequeno ajudante em ação! 🧹', body_pt = 'Imita-a e pega num pano para limpar o pó ou brinca com a vassoura? As crianças aprendem sobretudo a ver.', title_sv = 'Liten hjälpreda i arbete! 🧹', body_sv = 'Härmar barnet dig, tar en trasa och dammar eller leker med sopborsten? Barn lär sig mest genom att se.', title_vi = 'Người phụ giúp nhỏ đang làm việc! 🧹', body_vi = 'Bé bắt chước mẹ cầm khăn lau bụi hay chơi với cây chổi? Trẻ học nhiều nhất qua việc quan sát.', title_zh = '小帮手上岗啦！🧹', body_zh = '宝宝学你的样子拿起抹布擦灰，或者玩扫帚？孩子最主要是通过观察来学习的。' WHERE id = 'd89100dc-a7f8-49dd-8358-e3c63248fa5d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cambios en el sueño? 😴', body_es = 'Si empieza a hacer una sola siesta, durante la transición puede dormir más por la noche. Sigue el horario de los últimos días con el Temporizador de sueño.', title_fr = 'Son rythme de sommeil change ? 😴', body_fr = 'Si les siestes passent à une seule, le sommeil de nuit peut s''allonger pendant la transition. Suivez le planning des derniers jours avec le minuteur de sommeil.', title_hi = 'नींद के रूटीन में बदलाव? 😴', body_hi = 'अगर दिन की झपकियाँ एक पर आने लगी हैं, तो इस बदलाव के दौर में रात की नींद बढ़ सकती है। स्लीप टाइमर से पिछले दिनों का शेड्यूल देखिए।', title_id = 'Pola tidurnya berubah? 😴', body_id = 'Kalau tidur siangnya mulai jadi satu kali, tidur malamnya bisa bertambah di masa peralihan ini. Pantau jadwal beberapa hari terakhir dengan Timer Tidur.', title_ja = '睡眠リズムに変化？😴', body_ja = 'お昼寝が1回になり始めたら、移行期には夜の睡眠が長くなることがあります。睡眠タイマーでここ数日の記録をチェックしましょう。', title_ko = '수면 패턴이 바뀌었나요? 😴', body_ko = '낮잠이 한 번으로 줄기 시작했다면 전환기에는 밤잠이 길어질 수 있어요. 수면 타이머로 최근 며칠의 일정을 살펴보세요.', title_nl = 'Verandering in het slaapritme? 😴', body_nl = 'Gaan de dutjes overdag naar één, dan kan de nachtslaap in deze overgangsperiode langer worden. Volg het schema van de laatste dagen met de Slaaptimer.', title_pl = 'Zmiana w rytmie snu? 😴', body_pl = 'Jeśli drzemki w ciągu dnia zaczynają się zmniejszać do jednej, w okresie przejściowym nocny sen może się wydłużyć. Śledź timerem snu plan z ostatnich dni.', title_pt = 'Mudanças no sono? 😴', body_pt = 'Se as sestas começaram a passar para uma só, o sono noturno pode aumentar durante a transição. Acompanhe o horário dos últimos dias com o temporizador de sono.', title_sv = 'Förändring i sömnen? 😴', body_sv = 'Om dagsluren börjar bli bara en kan nattsömnen öka under övergången. Följ de senaste dagarnas schema med sömntimern.', title_vi = 'Nếp ngủ thay đổi? 😴', body_vi = 'Nếu bé bắt đầu chỉ ngủ một giấc ngày, giấc ngủ đêm có thể dài hơn trong giai đoạn chuyển tiếp. Hãy theo dõi biểu đồ những ngày gần đây bằng Bộ hẹn giờ ngủ.', title_zh = '睡眠作息变了？😴', body_zh = '如果白天小睡开始减到一次，过渡期夜里的睡眠可能会变长。用睡眠计时器看看最近几天的图表吧。' WHERE id = 'eea0806e-a72b-42f1-b1c3-b7a791619a96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ya puede entretenerse solo con sus juguetes durante 10-15 minutos. Su capacidad de atención se alarga. Disfruta del silencio.', body_fr = 'Il sait déjà s''occuper seul avec ses jouets pendant 10-15 minutes. Son attention s''allonge. Savourez le calme.', body_hi = 'अब वह 10-15 मिनट अपने खिलौनों में अकेले मगन रह सकता है। यह उसके ध्यान का दायरा बढ़ने का संकेत है। शांति का मज़ा लीजिए।', body_id = 'Kini ia bisa asyik sendiri dengan mainannya selama 10-15 menit. Ini tanda rentang perhatiannya makin panjang. Nikmati ketenangannya.', body_ja = 'もう10-15分はひとりでおもちゃで遊べるようになりました。集中できる時間が長くなっている証拠です。静かなひとときを味わいましょう。', body_ko = '이제 10-15분 동안 혼자 장난감을 가지고 놀 수 있어요. 집중하는 시간이 길어지고 있다는 뜻이에요. 고요함을 즐겨 보세요.', body_nl = 'Je kindje kan zich nu 10-15 minuten alleen met zijn speelgoed vermaken. Zijn concentratie wordt langer. Geniet van de stilte.', body_pl = 'Potrafi już przez 10-15 minut sam zająć się zabawkami. To znak, że wydłuża się jego skupienie uwagi. Delektuj się ciszą.', body_pt = 'Já consegue entreter-se sozinho com os brinquedos 10-15 minutos. É a capacidade de atenção a aumentar. Aproveite o silêncio.', body_sv = 'Nu kan barnet sysselsätta sig själv med leksakerna i 10-15 minuter. Uppmärksamheten håller längre. Njut av tystnaden.', body_vi = 'Bé đã có thể tự chơi với đồ chơi 10-15 phút. Đó là dấu hiệu khả năng tập trung đang dài ra. Hãy tận hưởng chút yên tĩnh nhé.', body_zh = '宝宝已经能自己玩玩具10-15分钟了。这说明他的专注时间在变长。享受这份安静吧。' WHERE id = '15bfc39a-e833-4e38-b7fc-bc13ef473b00' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entiende tu tono de voz 🗣️', title_fr = 'Il comprend votre ton de voix 🗣️', title_hi = 'आपकी आवाज़ का लहजा समझता है 🗣️', title_id = 'Ia memahami nada suara Anda 🗣️', title_ja = 'あなたの声のトーンがわかる 🗣️', title_ko = '엄마의 목소리 톤을 알아들어요 🗣️', title_nl = 'Hij begrijpt je toon 🗣️', title_pl = 'Rozumie ton twojego głosu 🗣️', title_pt = 'Percebe o seu tom de voz 🗣️', title_sv = 'Förstår ditt tonfall 🗣️', title_vi = 'Bé hiểu giọng điệu của mẹ 🗣️', title_zh = '宝宝能听懂你的语气 🗣️' WHERE id = '99045f34-6450-4abd-856c-64fd61405e7b' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la música 🎶', title_fr = 'La force de la musique 🎶', title_hi = 'संगीत की ताकत 🎶', title_id = 'Kekuatan musik 🎶', title_ja = '音楽の力 🎶', title_ko = '음악의 힘 🎶', title_nl = 'De kracht van muziek 🎶', title_pl = 'Moc muzyki 🎶', title_pt = 'A força da música 🎶', title_sv = 'Musikens kraft 🎶', title_vi = 'Sức mạnh của âm nhạc 🎶', title_zh = '音乐的力量 🎶' WHERE id = 'dc953aca-0624-4e7e-a96b-11f2b35b9a14' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Garabatos de colores! 🖍', body_es = '️ Prepárale en un rincón de la habitación ceras gruesas adecuadas y un papel grande. ¡No olvides guardar sus primeras obras de arte en el Álbum del bebé!', title_fr = 'Des gribouillis colorés ! 🖍', body_fr = '️ Installez dans un coin de la pièce de gros crayons adaptés et une grande feuille. N''oubliez pas d''immortaliser ses premières œuvres dans l''Album de bébé !', title_hi = 'रंग-बिरंगी लकीरें! 🖍', body_hi = '️ कमरे के एक कोने में उसे सही मोटे रंग और बड़ा कागज़ दीजिए। उसकी पहली कलाकृतियों को बेबी एल्बम में हमेशा के लिए सहेजना मत भूलिए!', title_id = 'Coretan warna-warni! 🖍', body_id = '️ Sediakan krayon tebal yang sesuai dan kertas besar di salah satu sudut kamar. Jangan lupa abadikan karya seni pertamanya di Album Bayi!', title_ja = 'カラフルなお絵かき！🖍', body_ja = '️部屋のすみに、年齢に合った太いクレヨンと大きな紙を用意してあげましょう。はじめての作品を「ベビーアルバム」に残すのを忘れずに！', title_ko = '알록달록 끄적끄적! 🖍', body_ko = '️방 한쪽에 아이에게 맞는 굵은 크레용과 큰 종이를 놓아 주세요. 첫 작품을 아기 앨범에 영원히 남기는 것도 잊지 마세요!', title_nl = 'Kleurrijke krabbels! 🖍', body_nl = '️ Geef je kindje in een hoekje van de kamer geschikte dikke kleurpotloden en een groot vel papier. Vergeet niet zijn eerste kunstwerken vast te leggen in het Babyalbum!', title_pl = 'Kolorowe bazgroły! 🖍', body_pl = '️ W kąciku pokoju daj mu odpowiednie grube kredki i dużą kartkę. Nie zapomnij uwiecznić jego pierwszych dzieł w Albumie dziecka!', title_pt = 'Rabiscos coloridos! 🖍', body_pt = '️ Num canto do quarto, dê-lhe lápis de cor grossos adequados e uma folha grande. Não se esqueça de eternizar as primeiras obras de arte no Álbum do Bebé!', title_sv = 'Färgglatt klotter! 🖍', body_sv = '️ Ge barnet tjocka kritor och ett stort papper i ett hörn av rummet. Glöm inte att förevig de första konstverken i Babyalbumet!', title_vi = 'Những nét vẽ nguệch ngoạc đầy màu sắc! 🖍', body_vi = '️ Hãy dành một góc phòng với bút màu to phù hợp và tờ giấy lớn cho bé. Đừng quên lưu giữ những tác phẩm nghệ thuật đầu tiên trong Album của bé nhé!', title_zh = '五彩缤纷的涂鸦！🖍', body_zh = '️ 在房间一角给宝宝准备合适的粗蜡笔和大张纸。别忘了把他的第一批艺术作品留在宝宝相册里！' WHERE id = '1eee6b26-c3fa-460c-8e48-030eb1e5a77c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Necesitas apoyo experto? 🤖', body_es = 'Haz preguntas como «¿Cómo estimulo el habla de un niño de 14 meses?» a nuestro asistente Anacan AI incluso de madrugada.', title_fr = 'Besoin de l''avis d''un expert ? 🤖', body_fr = 'Posez vos questions, comme « Comment développer le langage de mon enfant de 14 mois ? », à notre assistant Anacan AI, même en pleine nuit.', title_hi = 'विशेषज्ञ की मदद चाहिए? 🤖', body_hi = '''14 महीने के बच्चे की बोली कैसे विकसित करूँ?'' जैसे सवाल रात में भी हमारे Anacan AI असिस्टेंट से पूछिए।', title_id = 'Butuh dukungan ahli? 🤖', body_id = 'Tanyakan pertanyaan seperti "Bagaimana mengembangkan kemampuan bicara anak 14 bulan?" ke asisten Anacan AI kami, bahkan di malam hari.', title_ja = '専門家のサポートが必要？🤖', body_ja = '「1歳2か月の子の言葉の発達をどう促せばいい？」といった質問も、夜中でもAnacan AIアシスタントに聞いてみましょう。', title_ko = '전문가의 도움이 필요한가요? 🤖', body_ko = '''14개월 아이의 말을 어떻게 키워 줄까?'' 같은 질문은 늦은 밤에도 Anacan AI 도우미에게 물어보세요.', title_nl = 'Deskundige hulp nodig? 🤖', body_nl = 'Stel je vragen, zoals: hoe stimuleer ik de spraak van mijn kindje van 14 maanden?, zelfs midden in de nacht aan onze assistent Anacan AI.', title_pl = 'Potrzebujesz wsparcia eksperta? 🤖', body_pl = 'Pytania typu „Jak rozwijać mowę 14-miesięcznego dziecka?” zadawaj naszemu asystentowi Anacan AI, nawet w nocy.', title_pt = 'Precisa do apoio de um especialista? 🤖', body_pt = 'Faça as suas perguntas, como "Como desenvolvo a fala de uma criança de 14 meses?", ao nosso assistente Anacan AI, mesmo de madrugada.', title_sv = 'Behöver du stöd från en expert? 🤖', body_sv = 'Ställ frågor som ”Hur utvecklar jag talet hos mitt barn på 14 månader?” till vår assistent Anacan AI, även sent på natten.', title_vi = 'Mẹ cần sự hỗ trợ của chuyên gia? 🤖', body_vi = 'Những câu hỏi như "Làm sao để phát triển khả năng nói cho bé 14 tháng?", ngay cả lúc nửa đêm mẹ cũng có thể hỏi trợ lý Anacan AI.', title_zh = '需要专家支持吗？🤖', body_zh = '像“怎样促进14个月宝宝的语言发展？”这样的问题，哪怕深夜也可以问我们的Anacan AI助手。' WHERE id = '3ed02c3f-6c13-412d-9e4b-93ad1bd1da69' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hay que actualizar la seguridad 🛡', body_es = '️ A medida que anda solo y abre armarios, aumentan los peligros. Echa un vistazo a nuestra lista de Productos recomendados para encontrar cierres de seguridad infantil.', title_fr = 'La sécurité doit être revue. 🛡', body_fr = '️ Plus il marche librement et ouvre les placards, plus les dangers augmentent. Consultez notre liste de Produits recommandés pour trouver des verrous de sécurité enfant.', title_hi = 'सुरक्षा को अपडेट करना ज़रूरी है। 🛡', body_hi = '️ जैसे-जैसे वह खुलकर चलने और अलमारियाँ खोलने लगता है, खतरे बढ़ते हैं। चाइल्ड लॉक के लिए हमारी सुझाए गए प्रोडक्ट की लिस्ट देखिए।', title_id = 'Keamanan perlu diperbarui. 🛡', body_id = '️ Saat ia mulai bebas berjalan dan membuka lemari, bahayanya bertambah. Lihat daftar Produk Rekomendasi kami untuk kunci pengaman anak.', title_ja = '安全対策を見直そう 🛡', body_ja = '️自由に歩いて戸棚を開け始めると、危険も増えます。チャイルドロックは「おすすめ商品」リストをのぞいてみましょう。', title_ko = '안전 점검을 새로 할 때예요. 🛡', body_ko = '️자유롭게 걷고 수납장을 열기 시작하면 위험도 늘어나요. 안전 잠금장치는 추천 제품 목록에서 살펴보세요.', title_nl = 'Tijd om de veiligheid bij te werken. 🛡', body_nl = '️ Nu je kindje vrij rondloopt en kastjes opent, nemen de gevaren toe. Bekijk onze lijst Aanbevolen producten voor kinderslotjes.', title_pl = 'Czas odświeżyć zabezpieczenia. 🛡', body_pl = '️ Gdy zaczyna swobodnie chodzić i otwierać szafki, zagrożeń przybywa. Zajrzyj do naszej listy Polecanych produktów po blokady dla dzieci.', title_pt = 'É altura de reforçar a segurança. 🛡', body_pt = '️ À medida que começa a andar à vontade e a abrir armários, os perigos aumentam. Espreite a nossa lista de Produtos Recomendados para encontrar trancas de segurança.', title_sv = 'Säkerheten behöver uppdateras. 🛡', body_sv = '️ När barnet börjar gå fritt och öppna skåp ökar riskerna. Titta i vår lista Rekommenderade produkter efter barnlås.', title_vi = 'Cần cập nhật an toàn. 🛡', body_vi = '️ Khi bé bắt đầu tự đi lại và mở tủ, nguy hiểm cũng tăng lên. Hãy xem danh sách Sản phẩm gợi ý của chúng tôi để tìm khóa an toàn cho trẻ.', title_zh = '安全措施需要升级 🛡', body_zh = '️ 宝宝开始自由走动、打开柜子，危险也随之增加。看看我们推荐商品清单里的儿童安全锁吧。' WHERE id = 'f1854aec-f168-4789-a191-8a1fa96c3cd8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de un tentempié sano 🍎', body_es = 'Para niños con energía inagotable, los trozos de fruta o los palitos de verdura son ideales. Deja que los coja y se los coma solo.', title_fr = 'L''heure d''un en-cas sain. 🍎', body_fr = 'Pour les enfants pleins d''énergie, des tranches de fruits ou des bâtonnets de légumes sont un excellent choix. Laissez-le les prendre et les manger tout seul.', title_hi = 'सेहतमंद स्नैक का समय। 🍎', body_hi = 'कभी न थकने वाले बच्चों के लिए फलों के टुकड़े या सब्ज़ियों की स्टिक बढ़िया विकल्प हैं। उसे खुद पकड़कर खाने दीजिए।', title_id = 'Waktunya camilan sehat. 🍎', body_id = 'Untuk anak yang energinya tak ada habisnya, potongan buah atau stik sayur adalah pilihan tepat. Biarkan ia memegang dan memakannya sendiri.', title_ja = 'ヘルシーなおやつタイム 🍎', body_ja = '元気いっぱいの子には、くし切りの果物や野菜スティックがぴったり。自分で持って食べさせてあげましょう。', title_ko = '건강한 간식 시간. 🍎', body_ko = '에너지가 끝없는 아이에게는 과일 조각이나 채소 스틱이 훌륭한 선택이에요. 혼자 집어 먹게 해 주세요.', title_nl = 'Tijd voor een gezond tussendoortje. 🍎', body_nl = 'Voor kinderen met eindeloze energie zijn stukjes fruit of groentesticks een prima keuze. Laat hem ze zelf pakken en opeten.', title_pl = 'Czas na zdrową przekąskę. 🍎', body_pl = 'Dla dzieci o niewyczerpanej energii plasterki owoców lub słupki warzyw to świetny wybór. Niech sam bierze je i je.', title_pt = 'Hora do lanche saudável. 🍎', body_pt = 'Para crianças com energia inesgotável, fatias de fruta ou palitos de legumes são uma ótima escolha. Deixe que pegue neles e coma sozinho.', title_sv = 'Dags för nyttigt mellanmål. 🍎', body_sv = 'Fruktbitar eller grönsaksstavar är ett utmärkt val för barn med oändlig energi. Låt barnet ta och äta själv.', title_vi = 'Giờ ăn nhẹ lành mạnh. 🍎', body_vi = 'Với những em bé tràn đầy năng lượng, lát trái cây hay que rau củ là lựa chọn tuyệt vời. Hãy để bé tự cầm ăn.', title_zh = '健康加餐时间 🍎', body_zh = '对精力无限的孩子来说，水果片或蔬菜条是很好的选择。让宝宝自己拿着吃吧。' WHERE id = '02d67440-3e37-4d1c-99f8-cbfa7aadda52' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¿Qué es esto?» ☝', body_es = '️ Lo señala todo con el dedo y pregunta cómo se llama. Dile con paciencia el nombre de cada cosa: su vocabulario crecerá muy rápido.', title_fr = 'La période du « C''est quoi ? ». ☝', body_fr = '️ Il montre tout du doigt et demande le nom. Dites-lui patiemment le nom de chaque chose : son vocabulaire va s''enrichir très vite.', title_hi = '''यह क्या है?'' का दौर। ☝', body_hi = '️ हर चीज़ की ओर उँगली दिखाकर उसका नाम पूछता है। धैर्य से हर चीज़ का नाम बताइए; इससे उसका शब्द भंडार तेज़ी से बढ़ेगा।', title_id = 'Masa "Ini apa?". ☝', body_id = '️ Ia menunjuk segala hal dan menanyakan namanya. Sebutkan nama semuanya dengan sabar; ini akan menambah kosakatanya dengan cepat.', title_ja = '「これなあに？」の時期 ☝', body_ja = '️なんでも指さして名前を聞いてきます。根気よくひとつひとつ名前を教えてあげましょう。語彙がぐんぐん増えます。', title_ko = '"이게 뭐야?" 시기. ☝', body_ko = '️모든 걸 손가락으로 가리키며 이름을 물어요. 인내심을 갖고 하나하나 이름을 말해 주세요. 어휘가 빠르게 늘어날 거예요.', title_nl = 'De wat-is-dat-fase. ☝', body_nl = '️ Je kindje wijst alles aan en vraagt hoe het heet. Zeg geduldig de naam van alles, zo groeit zijn woordenschat snel.', title_pl = 'Etap „Co to jest?”. ☝', body_pl = '️ Pokazuje wszystko paluszkiem i pyta o nazwę. Cierpliwie nazywaj mu wszystko, to szybko wzbogaci jego zasób słów.', title_pt = 'A fase do "O que é isto?". ☝', body_pt = '️ Aponta para tudo com o dedo e pergunta o nome. Diga com paciência o nome de cada coisa: isso vai aumentar depressa o vocabulário dele.', title_sv = 'Fasen ”Vad är det?”. ☝', body_sv = '️ Barnet pekar på allt och frågar vad det heter. Säg med tålamod namnet på allt, det får ordförrådet att växa snabbt.', title_vi = 'Giai đoạn "Cái gì đây?". ☝', body_vi = '️ Bé chỉ tay vào mọi thứ và hỏi tên. Hãy kiên nhẫn gọi tên từng thứ; điều này sẽ giúp vốn từ của bé tăng nhanh.', title_zh = '“这是什么？”阶段 ☝', body_zh = '️ 宝宝用手指着各种东西问名字。耐心地告诉他每样东西叫什么，这会让他的词汇量快速增长。' WHERE id = '4a197291-3001-4afb-9a70-d4320bd260b2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento con papá 👨‍🍼', body_es = 'Hoy deja a papá el turno del cuento y de acostarle, y regálate un pequeño descanso.', title_fr = 'L''heure du conte avec papa. 👨‍🍼', body_fr = 'Ce soir, confiez à papa l''histoire du soir et le coucher, et offrez-vous une petite pause.', title_hi = 'पापा की कहानी का समय। 👨‍🍼', body_hi = 'आज शाम कहानी सुनाने और सुलाने की बारी पापा को सौंपिए और खुद को छोटा सा ब्रेक दीजिए।', title_id = 'Waktu dongeng bersama ayah. 👨‍🍼', body_id = 'Hari ini, serahkan giliran membacakan dongeng dan menidurkan si kecil kepada ayah, dan beri diri Anda jeda sejenak.', title_ja = 'パパのお話タイム 👨‍🍼', body_ja = '今夜は寝る前の読み聞かせと寝かしつけをパパにお願いして、自分に小さな休憩をあげましょう。', title_ko = '아빠의 이야기 시간. 👨‍🍼', body_ko = '오늘은 저녁 동화 읽기와 재우기를 아빠에게 맡기고 엄마는 잠깐 쉬어 가세요.', title_nl = 'Verhaaltjestijd met papa. 👨‍🍼', body_nl = 'Laat het voorlezen en naar bed brengen vandaag aan papa over en gun jezelf een kleine pauze.', title_pl = 'Czas bajek z tatą. 👨‍🍼', body_pl = 'Dziś wieczorem przekaż tacie czytanie bajki i usypianie, a sobie daj małą przerwę.', title_pt = 'A hora das histórias do pai. 👨‍🍼', body_pt = 'Hoje, entregue ao pai a vez de ler a história da noite e de o adormecer, e dê a si própria uma pequena pausa.', title_sv = 'Pappas sagostund. 👨‍🍼', body_sv = 'Lämna kvällssagan och nattningen till pappa i dag och ge dig själv en liten paus.', title_vi = 'Giờ kể chuyện của bố. 👨‍🍼', body_vi = 'Tối nay hãy giao việc kể chuyện và ru bé ngủ cho bố, còn mẹ thì cho mình nghỉ ngơi một chút.', title_zh = '爸爸的故事时间 👨‍🍼', body_zh = '今天把讲睡前故事和哄睡的任务交给爸爸，给自己一个小小的休息。' WHERE id = '8938f1b0-220a-48ac-b5f5-33db3613995c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Trepa como un monito! 🧗‍♂', body_es = '️ Intenta subirse solo al sofá o a los muebles bajos. Haz que la zona sea segura y deja que pruebe estos valientes avances motores bajo tu vigilancia.', title_fr = 'Il grimpe comme un petit singe ! 🧗‍♂', body_fr = '️ Il essaie de grimper seul sur le canapé ou les meubles bas. Sécurisez les lieux et laissez-le tester ces audacieux progrès moteurs sous votre surveillance.', title_hi = 'बंदर की तरह चढ़ता है! 🧗‍♂', body_hi = '️ सोफ़े या नीचे फ़र्नीचर पर अकेले चढ़ने की कोशिश करता है? आसपास को सुरक्षित बनाइए और अपनी निगरानी में उसे ये हिम्मत भरे मोटर कदम आज़माने दीजिए।', title_id = 'Memanjat seperti monyet! 🧗‍♂', body_id = '️ Ia mencoba memanjat sofa atau perabot rendah sendirian. Amankan sekelilingnya dan biarkan ia mencoba langkah motorik yang berani ini di bawah pengawasan.', title_ja = 'おさるさんのようによじ登る！🧗‍♂', body_ja = '️ソファや低い家具にひとりで登ろうとしています。周りを安全にして、見守りながらこの勇敢な運動の挑戦をさせてあげましょう。', title_ko = '원숭이처럼 기어올라요! 🧗‍♂', body_ko = '️소파나 낮은 가구에 혼자 기어오르려 해요. 주변을 안전하게 만들고, 지켜보는 가운데 이 용감한 운동 도전을 해 보게 해 주세요.', title_nl = 'Klimt als een aapje! 🧗‍♂', body_nl = '️ Je kindje probeert zelf op de bank of op lage meubels te klimmen. Maak de omgeving veilig en laat hem deze dappere motorische stappen onder toezicht uitproberen.', title_pl = 'Wspina się jak małpka! 🧗‍♂', body_pl = '️ Próbuje sam wspiąć się na kanapę lub niskie meble. Zabezpiecz otoczenie i pozwól mu pod twoim okiem sprawdzać te odważne kroki motoryczne.', title_pt = 'Trepa como um macaquinho! 🧗‍♂', body_pt = '️ Tenta subir sozinho para o sofá ou para móveis baixos. Torne o espaço seguro e deixe-o pôr à prova, sob vigilância, estes passos motores tão corajosos.', title_sv = 'Klättrar som en apa! 🧗‍♂', body_sv = '️ Barnet försöker klättra upp på soffan eller låga möbler själv. Gör omgivningen säker och låt barnet prova dessa modiga motoriska steg under uppsikt.', title_vi = 'Leo trèo như chú khỉ con! 🧗‍♂', body_vi = '️ Bé cố tự leo lên sofa hay đồ đạc thấp. Hãy đảm bảo xung quanh an toàn và để bé thử những bước vận động táo bạo này dưới sự bảo vệ của mẹ.', title_zh = '像小猴子一样爬上爬下！🧗‍♂', body_zh = '️ 宝宝在尝试自己爬上沙发或矮家具。把周围布置安全，在你的保护下让他尝试这些勇敢的大动作吧。' WHERE id = '47ea2f2a-adf0-473a-a6a2-47218a354bbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse es cada vez más fácil 🌙', body_es = 'Repetir cada noche los mismos pasos (baño, cuento, bajar las luces) le ayudará a dormirse más tranquilo.', title_fr = 'L''endormissement devient plus facile. 🌙', body_fr = 'Les mêmes gestes, dans le même ordre chaque soir (bain, histoire, lumière tamisée), l''aideront à s''endormir plus sereinement.', title_hi = 'नींद में जाना आसान हो रहा है। 🌙', body_hi = 'हर शाम एक ही क्रम में किए जाने वाले काम (स्नान, कहानी, रोशनी धीमी करना) उसे ज़्यादा आराम से सोने में मदद करेंगे।', title_id = 'Peralihan ke tidur makin mudah. 🌙', body_id = 'Kegiatan dengan urutan yang sama setiap malam (mandi, dongeng, meredupkan lampu) akan membantunya tertidur lebih nyaman.', title_ja = '眠りへの切りかえが楽に 🌙', body_ja = '毎晩同じ順番で過ごすこと（お風呂、お話、照明を暗くする）で、よりスムーズに眠れるようになります。', title_ko = '잠드는 게 쉬워져요. 🌙', body_ko = '매일 저녁 같은 순서로 하는 일들(목욕, 동화, 조명 낮추기)이 더 편하게 잠드는 데 도움이 될 거예요.', title_nl = 'Makkelijker in slaap vallen. 🌙', body_nl = 'Elke avond dezelfde volgorde (badje, verhaaltje, lichten dimmen) helpt je kindje rustiger in slaap te vallen.', title_pl = 'Zasypianie staje się łatwiejsze. 🌙', body_pl = 'Czynności wykonywane co wieczór w tej samej kolejności (kąpiel, bajka, przygaszone światła) pomogą mu spokojniej zasnąć.', title_pt = 'Adormecer fica mais fácil. 🌙', body_pt = 'Repetir todas as noites os mesmos passos pela mesma ordem (banho, história, luzes mais baixas) vai ajudá-lo a adormecer com mais tranquilidade.', title_sv = 'Insomnandet blir lättare. 🌙', body_sv = 'Samma ordning varje kväll (bad, saga, dämpat ljus) hjälper barnet att somna lugnare.', title_vi = 'Vào giấc dễ dàng hơn. 🌙', body_vi = 'Những việc làm theo cùng một trình tự mỗi tối (tắm, kể chuyện, giảm đèn) sẽ giúp bé dễ đi vào giấc ngủ hơn.', title_zh = '入睡变得更容易了 🌙', body_zh = '每晚按同样的顺序做同样的事（洗澡、讲故事、调暗灯光），能帮宝宝更轻松地入睡。' WHERE id = 'ea4bc86f-6869-478f-98a6-52bb8dc4c40f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cansancio y orgullo 💖', body_es = 'Celebra esta noche con tu pareja el cansancio y el orgullo de estos 14 meses. ¡Sois un equipo perfecto!', title_fr = 'Fatigue et fierté💖', body_fr = 'Ce soir, fêtez avec votre conjoint 14 mois de fatigue et de fierté. Vous formez une équipe parfaite !', title_hi = 'थकान और गर्व💖', body_hi = '14 महीनों की थकान और गर्व को आज शाम अपने साथी के साथ मनाइए। आप एक परफ़ेक्ट टीम हैं!', title_id = 'Lelah dan bangga💖', body_id = 'Malam ini, rayakan lelah dan bangganya 14 bulan ini bersama pasangan. Kalian tim yang sempurna!', title_ja = '疲れと誇り💖', body_ja = '14か月分の疲れと誇りを、今夜はパートナーと一緒にお祝いしましょう。おふたりは最高のチームです！', title_ko = '피로와 뿌듯함💖', body_ko = '14개월의 피로와 뿌듯함을 오늘 저녁 배우자와 함께 축하하세요. 두 사람은 완벽한 팀이에요!', title_nl = 'Vermoeidheid en trots💖', body_nl = 'Vier vanavond samen met je partner de vermoeidheid en de trots van deze 14 maanden. Jullie zijn een perfect team!', title_pl = 'Zmęczenie i duma💖', body_pl = 'Uczcij dziś wieczorem z partnerem zmęczenie i dumę tych 14 miesięcy. Jesteście idealnym zespołem!', title_pt = 'Cansaço e orgulho💖', body_pt = 'Celebre esta noite com o seu companheiro o cansaço e o orgulho destes 14 meses. Vocês são uma equipa perfeita!', title_sv = 'Trötthet och stolthet💖', body_sv = 'Fira 14 månaders trötthet och stolthet tillsammans med din partner i kväll. Ni är ett perfekt team!', title_vi = 'Mệt mỏi và tự hào💖', body_vi = 'Tối nay hãy cùng bố ăn mừng 14 tháng mệt nhọc nhưng đầy tự hào. Hai người là một đội hoàn hảo!', title_zh = '疲惫与骄傲💖', body_zh = '今晚和另一半一起庆祝这14个月的疲惫与骄傲。你们是完美的团队！' WHERE id = '9052004a-46e9-4652-8de2-61f2a8f774d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Cuánto camino ha recorrido tu peque! 📈', body_es = 'Los miedos de los primeros días han dejado paso a una fuerte confianza de madre. ¡Siéntete orgullosa!', title_fr = 'Quel chemin parcouru ! 📈', body_fr = 'Les peurs des premiers jours ont laissé place à une solide confiance de maman. Soyez fière de vous !', title_hi = 'आपके बच्चे ने कितना लंबा सफ़र तय किया है! 📈', body_hi = 'पहले दिनों का डर अब एक माँ के मज़बूत आत्मविश्वास में बदल गया है। खुद पर गर्व कीजिए!', title_id = 'Lihat sejauh apa si kecil melangkah! 📈', body_id = 'Ketakutan di hari-hari pertama kini berganti menjadi rasa percaya diri seorang ibu yang kuat. Banggalah pada diri sendiri!', title_ja = 'こんなに大きくなりました！📈', body_ja = 'はじめのころの不安は、ママとしての強い自信に変わりました。自分を誇りに思ってください！', title_ko = '아이가 얼마나 먼 길을 왔는지! 📈', body_ko = '첫 며칠의 두려움이 이제 엄마로서의 단단한 확신으로 바뀌었어요. 스스로를 자랑스러워하세요!', title_nl = 'Wat heeft je kindje al een weg afgelegd! 📈', body_nl = 'De angst van de eerste dagen heeft plaatsgemaakt voor een sterk moedergevoel. Wees trots op jezelf!', title_pl = 'Jak wielką drogę przeszło twoje dziecko! 📈', body_pl = 'Lęki pierwszych dni ustąpiły miejsca silnej matczynej pewności siebie. Bądź z siebie dumna!', title_pt = 'Quanto caminho o seu filho já percorreu! 📈', body_pt = 'O medo dos primeiros dias deu lugar a uma forte confiança de mãe. Orgulhe-se de si!', title_sv = 'Så långt barnet har kommit! 📈', body_sv = 'De första dagarnas rädsla har ersatts av en stark tro på dig som mamma. Var stolt över dig själv!', title_vi = 'Bé đã đi được một chặng đường thật dài! 📈', body_vi = 'Nỗi sợ những ngày đầu đã nhường chỗ cho niềm tin vững vàng của người mẹ. Hãy tự hào về bản thân!', title_zh = '宝宝已经走了多远啊！📈', body_zh = '最初那些日子的恐惧，已经变成了一位妈妈坚定的自信。为自己骄傲吧！' WHERE id = 'dde3a118-6b4b-4b86-b077-744218b7fcd7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Has estado de pie todo el día. Anota tu cansancio en el Diario de ánimo, desahógate y descansa con un té calentito.', body_fr = 'Vous avez été debout toute la journée. Allégez votre fatigue en la notant dans le Journal d''humeur et reposez-vous avec un thé chaud.', body_hi = 'आप पूरे दिन खड़ी रहीं। अपनी थकान मूड डायरी में लिखकर मन हल्का कीजिए और गरम चाय के साथ आराम कीजिए।', body_id = 'Seharian Anda terus berdiri. Ringankan lelah Anda dengan menuliskannya di Buku Harian Suasana Hati dan beristirahatlah dengan secangkir teh hangat.', body_ja = '一日中立ちっぱなしでしたね。「気分日記」に疲れを書き出して気持ちを軽くし、温かいお茶でひと休みしましょう。', body_ko = '하루 종일 서 있었죠. 기분 일기에 피로를 적어 마음을 가볍게 하고 따뜻한 차 한 잔과 함께 쉬세요.', body_nl = 'Je stond de hele dag op je benen. Schrijf je vermoeidheid op in je Stemmingsdagboek, lucht je hart en rust uit met een warme kop thee.', body_pl = 'Cały dzień byłaś na nogach. Zapisz zmęczenie w Dzienniku nastroju, poczuj ulgę i odpocznij przy ciepłej herbacie.', body_pt = 'Esteve de pé o dia todo. Registe o seu cansaço no Diário de Humor, alivie o peso e descanse com um chá quente.', body_sv = 'Du har varit på benen hela dagen. Skriv av dig tröttheten i Humördagboken och vila med en kopp varmt te.', body_vi = 'Cả ngày mẹ đã đứng không ngơi chân. Hãy ghi lại sự mệt mỏi vào Nhật ký tâm trạng để nhẹ lòng hơn và nghỉ ngơi cùng một tách trà nóng.', body_zh = '你站了一整天。把疲惫记进心情日记，给自己减减压，再喝杯热茶休息一下。' WHERE id = '33a2089a-67cc-4441-bb79-483ad77a1a42' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de tirar cosas 🎾', body_es = 'Tirar juguetes o comida al suelo y mirar cómo caen no es una travesura: está descubriendo la gravedad. Ten paciencia y déjale jugar con cosas irrompibles.', title_fr = 'L''art de tout lancer. 🎾', body_fr = 'Jeter ses jouets ou sa nourriture par terre et les regarder tomber, ce n''est pas de la bêtise, c''est découvrir la gravité. Soyez patiente et laissez-le jouer avec des objets incassables.', title_hi = 'चीज़ें फेंकने की कला। 🎾', body_hi = 'खिलौने या खाना नीचे फेंककर उसे देखते रहना शरारत नहीं, गुरुत्वाकर्षण की खोज है। धैर्य रखिए और उसे न टूटने वाली चीज़ों से खेलने दीजिए।', title_id = 'Seni melempar barang. 🎾', body_id = 'Melempar mainan atau makanan ke lantai lalu memperhatikannya bukan kenakalan, melainkan cara menjelajahi gravitasi. Bersabarlah dan biarkan ia bermain dengan benda yang tidak mudah pecah.', title_ja = '投げるのが得意！🎾', body_ja = 'おもちゃや食べ物を床に落として見つめるのは、いたずらではなく重力の発見です。根気よく見守り、割れないもので遊ばせてあげましょう。', title_ko = '물건 던지기의 기술. 🎾', body_ko = '장난감이나 음식을 바닥에 던지고 바라보는 건 장난이 아니라 중력을 발견하는 거예요. 인내심을 갖고 깨지지 않는 물건으로 놀게 해 주세요.', title_nl = 'De kunst van het gooien. 🎾', body_nl = 'Gooit je kindje speelgoed of eten op de grond en kijkt hij het na? Dat is geen stoutheid, hij ontdekt de zwaartekracht. Wees geduldig en laat hem spelen met dingen die niet breken.', title_pl = 'Sztuka rzucania. 🎾', body_pl = 'Rzucanie zabawek lub jedzenia na podłogę i patrzenie, jak spadają, to nie psoty, tylko odkrywanie grawitacji. Bądź cierpliwa i pozwól mu bawić się rzeczami, które się nie stłuką.', title_pt = 'A arte de atirar coisas. 🎾', body_pt = 'Atirar brinquedos ou comida para o chão e ficar a ver não é traquinice, é descobrir a gravidade. Tenha paciência e deixe-o brincar com objetos que não se partem.', title_sv = 'Konsten att kasta saker. 🎾', body_sv = 'Att kasta leksaker eller mat på golvet och titta efter dem är inte bus, det är att upptäcka tyngdkraften. Ha tålamod och låt barnet leka med saker som inte går sönder.', title_vi = 'Nghệ thuật ném đồ. 🎾', body_vi = 'Bé ném đồ chơi hay thức ăn xuống sàn rồi nhìn theo, đó không phải nghịch ngợm mà là đang khám phá trọng lực. Hãy kiên nhẫn và để bé chơi với những đồ không vỡ.', title_zh = '扔东西的艺术 🎾', body_zh = '把玩具或食物扔到地上再盯着看，这不是调皮，而是在探索重力。保持耐心，让他玩摔不坏的东西吧。' WHERE id = '625bdfef-2359-4843-aaac-6c8411b1963b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pasos hacia atrás y de lado! 🦀', body_es = 'Ya no solo camina hacia delante: también prueba a dar pasos hacia atrás y hacia los lados. ¡Es un ejercicio estupendo para el equilibrio y la motricidad!', title_fr = 'Pas en arrière et de côté ! 🦀', body_fr = 'Il ne marche plus seulement en avant, il teste aussi les pas en arrière et sur le côté. Un superbe exercice d''équilibre et de motricité !', title_hi = 'पीछे और बगल में कदम! 🦀', body_hi = 'अब वह सिर्फ़ आगे नहीं, पीछे और बगल में भी कदम रखकर देख रहा है। यह संतुलन और मोटर स्किल्स के लिए शानदार अभ्यास है!', title_id = 'Melangkah mundur dan menyamping! 🦀', body_id = 'Kini ia tidak hanya melangkah maju, tapi juga mencoba melangkah mundur dan ke samping. Ini latihan hebat untuk keseimbangan dan motoriknya!', title_ja = 'うしろ歩き、横歩き！🦀', body_ja = '前だけでなく、うしろや横にも歩いてみようとしています。バランスと運動能力のすばらしい練習です！', title_ko = '뒤로, 옆으로 걸음! 🦀', body_ko = '이제 앞으로만이 아니라 뒤로, 옆으로도 걸어 보려 해요. 균형과 운동 능력에 정말 멋진 연습이에요!', title_nl = 'Stapjes achteruit en opzij! 🦀', body_nl = 'Je kindje probeert nu niet alleen vooruit te stappen, maar ook achteruit en opzij. Een geweldige oefening voor evenwicht en motoriek!', title_pl = 'Kroki do tyłu i w bok! 🦀', body_pl = 'Próbuje już chodzić nie tylko do przodu, ale też do tyłu i w bok. To wspaniałe ćwiczenie równowagi i motoryki!', title_pt = 'Passos para trás e para o lado! 🦀', body_pt = 'Já não experimenta só andar para a frente, mas também para trás e para os lados. É um treino fantástico para o equilíbrio e a motricidade!', title_sv = 'Steg bakåt och åt sidan! 🦀', body_sv = 'Barnet provar nu att ta steg inte bara framåt, utan också bakåt och åt sidan. Det är en fantastisk övning för balansen och motoriken!', title_vi = 'Bước lùi và bước ngang! 🦀', body_vi = 'Bé không chỉ bước tới mà còn thử bước lùi và bước sang hai bên. Đây là bài tập tuyệt vời cho sự thăng bằng và vận động!', title_zh = '往后走、横着走！🦀', body_zh = '宝宝不只往前走，还在尝试往后、往两边迈步。这对平衡和动作发育是很棒的练习！' WHERE id = 'ee0ba9ab-4b88-462e-aae9-f9a207218204' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Los niños movidos piden el doble de fuerzas a mamá! Prémiate eligiendo y preparando un plato apetecible de Recetas saludables.', body_fr = 'Les enfants qui bougent beaucoup demandent deux fois plus d''énergie aux mamans ! Récompensez-vous en choisissant et en préparant un bon plat dans les Recettes saines.', body_hi = 'चुलबुले बच्चे माँओं से दोगुनी ताकत माँगते हैं! सेहतमंद रेसिपी से कोई दिलचस्प खाना चुनकर बनाइए और खुद को इनाम दीजिए।', body_id = 'Anak yang aktif menuntut tenaga dua kali lipat dari ibunya! Hadiahi diri Anda dengan memilih dan memasak hidangan menarik dari Resep Sehat.', body_ja = '活発な子どもには、ママの力が2倍必要！「ヘルシーレシピ」から気になる料理を選んでつくり、自分にごほうびをあげましょう。', body_ko = '활발한 아이는 엄마에게 두 배의 힘을 요구해요! 건강한 레시피에서 끌리는 요리를 골라 만들어 먹으며 스스로에게 상을 주세요.', body_nl = 'Actieve kinderen vragen dubbel zoveel kracht van mama''s! Beloon jezelf met een lekker gerecht uit Gezonde recepten.', body_pl = 'Ruchliwe dzieci wymagają od mam podwójnych sił! Wybierz ze zdrowych przepisów ciekawe danie, przygotuj je i nagródź się.', body_pt = 'Crianças ativas exigem o dobro da força às mães! Recompense-se escolhendo e preparando uma receita interessante das Receitas Saudáveis.', body_sv = 'Aktiva barn kräver dubbel kraft av mammor! Belöna dig själv genom att välja och laga en spännande rätt från Hälsosamma recept.', body_vi = 'Những em bé hiếu động đòi hỏi mẹ gấp đôi sức lực! Hãy tự thưởng cho mình bằng cách chọn và nấu một món ngon trong Công thức lành mạnh.', body_zh = '好动的孩子需要妈妈付出双倍的力气！从健康食谱里挑一道有意思的菜做给自己，犒劳一下自己吧。' WHERE id = '21478892-353c-43fd-ba31-59c9aeb8255d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Diga? ¿Quién es? 📱', body_es = '¿Se pone el mando o el móvil en la oreja e intenta hablar como tú? No te pierdas estos tiernos momentos de imitación.', title_fr = 'Allô, qui est-ce ? 📱', body_fr = 'Il colle la télécommande ou le téléphone à son oreille et essaie de parler comme vous ? Ne manquez pas ces adorables moments d''imitation.', title_hi = 'हैलो, कौन? 📱', body_hi = 'रिमोट या फ़ोन कान से लगाकर आपकी तरह बात करने की कोशिश करता है? नकल के इन प्यारे पलों को मत चूकिए।', title_id = 'Halo, siapa ini? 📱', body_id = 'Ia menempelkan remote atau ponsel ke telinga dan mencoba bicara seperti Anda? Jangan lewatkan momen meniru yang manis ini.', title_ja = 'もしもし、だあれ？📱', body_ja = 'リモコンやスマホを耳に当てて、あなたのように話そうとしていますか？このかわいいまねっこの瞬間を見逃さないで。', title_ko = '여보세요, 누구세요? 📱', body_ko = '리모컨이나 휴대폰을 귀에 대고 엄마처럼 말하려 하나요? 이 귀여운 흉내 내기 순간을 놓치지 마세요.', title_nl = 'Hallo, wie is daar? 📱', body_nl = 'Houdt je kindje de afstandsbediening of telefoon aan zijn oor en probeert hij te praten zoals jij? Mis deze lieve momenten van nadoen niet.', title_pl = 'Halo, kto mówi? 📱', body_pl = 'Przykłada pilota lub telefon do ucha i próbuje mówić tak jak ty? Nie przegap tych słodkich chwil naśladowania.', title_pt = 'Está lá, quem fala? 📱', body_pt = 'Encosta o comando ou o telemóvel à orelha e tenta falar como a mãe? Não perca estes momentos de imitação tão queridos.', title_sv = 'Hallå, vem är det? 📱', body_sv = 'Håller barnet fjärrkontrollen eller telefonen mot örat och försöker prata som du? Missa inte dessa söta härmstunder.', title_vi = 'A lô, ai đấy? 📱', body_vi = 'Bé áp điều khiển hay điện thoại lên tai và cố nói chuyện giống mẹ? Đừng bỏ lỡ những khoảnh khắc bắt chước đáng yêu này nhé.', title_zh = '喂，是谁呀？📱', body_zh = '宝宝把遥控器或手机放在耳边，学你的样子说话？别错过这些可爱的模仿瞬间。' WHERE id = '530feb7f-e42b-4ca3-88fe-a9c205c1ef1e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Las siestas se han quedado en una sola? Mientras duerme, activa el Temporizador de sueño y comprueba en el gráfico cómo se adapta a la nueva rutina.', body_fr = 'Il ne fait plus qu''une seule sieste ? Pendant qu''il dort, lancez le minuteur de sommeil et vérifiez sur le graphique comment il s''adapte à ce nouveau rythme.', body_hi = 'दिन की झपकियाँ पूरी तरह एक पर आ गई हैं? बच्चे के सोते समय स्लीप टाइमर चालू कीजिए और चार्ट में देखिए कि वह नए रूटीन में कैसे ढल रहा है।', body_id = 'Tidur siangnya kini benar-benar tinggal satu kali? Saat si kecil tidur, nyalakan Timer Tidur dan periksa penyesuaiannya dengan rutinitas baru di grafik.', body_ja = 'お昼寝がすっかり1回になりましたか？寝ている間に睡眠タイマーをオンにして、新しいリズムへの慣れ具合をグラフで確認しましょう。', body_ko = '낮잠이 완전히 한 번으로 줄었나요? 아기가 잘 때 수면 타이머를 켜고 새 일과에 적응하는 모습을 그래프로 확인하세요.', body_nl = 'Is je kindje overgestapt op één dutje per dag? Zet de Slaaptimer aan als hij slaapt en controleer in het schema hoe hij aan het nieuwe ritme went.', body_pl = 'Drzemki w ciągu dnia zmniejszyły się do jednej? Gdy maluszek śpi, włącz timer snu i sprawdź na wykresie, jak przyzwyczaja się do nowego rytmu.', body_pt = 'As sestas passaram de vez para uma só? Enquanto o bebé dorme, ligue o temporizador de sono e veja no gráfico como se está a adaptar ao novo horário.', body_sv = 'Har dagsluren helt gått ner till en? Starta sömntimern när barnet sover och se i diagrammet hur anpassningen till den nya rutinen går.', body_vi = 'Bé đã hoàn toàn chuyển sang một giấc ngủ ngày? Khi bé ngủ, hãy bật Bộ hẹn giờ ngủ và xem biểu đồ để kiểm tra bé thích nghi với nếp mới thế nào.', body_zh = '白天小睡已经完全变成一次了？宝宝睡觉时打开睡眠计时器，从图表里看看他对新作息的适应情况。' WHERE id = 'ab819835-a2e1-481b-91b5-5391eb6051e8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Los juegos de la tarde son muy movidos. Esta noche deja a papá las carreras, los juegos de pillar y el turno de acostarle, y descansa tú.', body_fr = 'Les jeux du soir sont très énergiques. Ce soir, laissez papa s''occuper des courses-poursuites et du coucher, et reposez-vous.', body_hi = 'शाम के खेल बहुत भाग-दौड़ वाले होते हैं। आज शाम बच्चे के साथ पकड़म-पकड़ाई और सुलाने की बारी पापा को दीजिए और खुद आराम कीजिए।', body_id = 'Permainan sore hari biasanya sangat energik. Malam ini, serahkan permainan kejar-kejaran dan giliran menidurkan kepada ayah, dan Anda beristirahatlah.', body_ja = '夜の遊びはとても元気いっぱい。今夜は追いかけっこと寝かしつけをパパに任せて、あなたは休みましょう。', body_ko = '저녁 놀이는 에너지가 넘쳐요. 오늘 저녁 술래잡기와 재우기는 아빠에게 넘기고 엄마는 쉬세요.', body_nl = 'Spelletjes ''s avonds zijn vaak heel druk. Laat vanavond het rennen en het naar bed brengen aan papa over en rust zelf uit.', body_pl = 'Wieczorne zabawy bywają bardzo energiczne. Dziś oddaj tacie gonitwy z maluchem i usypianie, a sama odpocznij.', body_pt = 'As brincadeiras da noite são cheias de energia. Hoje, deixe a correria com a criança e a hora de deitar por conta do pai e descanse.', body_sv = 'Kvällslekarna blir väldigt energiska. Låt pappa sköta jagalekarna och nattningen i kväll och vila du.', body_vi = 'Những trò chơi buổi tối thường rất sôi động. Tối nay hãy giao trò đuổi bắt và việc ru bé ngủ cho bố, còn mẹ thì nghỉ ngơi.', body_zh = '晚上的游戏总是特别兴奋。今晚陪宝宝追追跑跑之后，把哄睡任务交给爸爸，你去休息吧。' WHERE id = '44b33bc4-3602-4265-9fe5-30b5609015de' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Despierta la empatía! 💖', body_es = '¿Cuando alguien llora o está triste, se acerca e intenta acariciarle? Su inteligencia emocional se está desarrollando de maravilla.', title_fr = 'L''empathie s''éveille ! 💖', body_fr = 'Quand quelqu''un pleure ou est triste, il vient le caresser ? L''intelligence émotionnelle de votre enfant se développe magnifiquement.', title_hi = 'सहानुभूति की भावना जाग रही है! 💖', body_hi = 'कोई रोता या दुखी होता है तो वह आकर उसे सहलाने की कोशिश करता है? आपके बच्चे की भावनात्मक समझ बहुत सुंदर ढंग से विकसित हो रही है।', title_id = 'Rasa empati mulai tumbuh! 💖', body_id = 'Saat seseorang menangis atau sedih, ia datang dan mencoba mengelusnya? Kecerdasan emosional si kecil berkembang dengan sangat indah.', title_ja = '思いやりの気持ちが芽生える！💖', body_ja = '誰かが泣いたり悲しんだりしていると、そばに来てなでようとしますか？心の知性がすてきに育っています。', title_ko = '공감 능력이 깨어나요! 💖', body_ko = '누가 울거나 슬퍼하면 다가가 쓰다듬어 주려 하나요? 아이의 정서 지능이 아주 멋지게 자라고 있어요.', title_nl = 'Empathie ontwaakt! 💖', body_nl = 'Komt je kindje iemand aaien als die huilt of verdrietig is? De emotionele intelligentie van je kindje ontwikkelt zich prachtig.', title_pl = 'Budzi się empatia! 💖', body_pl = 'Gdy ktoś płacze lub jest smutny, podchodzi i próbuje go pogłaskać? Inteligencja emocjonalna twojego dziecka pięknie się rozwija.', title_pt = 'A empatia está a despertar! 💖', body_pt = 'Quando alguém chora ou está triste, aproxima-se e tenta fazer-lhe uma festinha? A inteligência emocional do seu filho está a desenvolver-se muito bem.', title_sv = 'Empatin vaknar! 💖', body_sv = 'Kommer barnet fram och försöker stryka den som gråter eller är ledsen? Barnets emotionella intelligens utvecklas fint.', title_vi = 'Sự đồng cảm đang nảy nở! 💖', body_vi = 'Khi có ai khóc hay buồn, bé đến và cố vuốt ve người đó? Trí tuệ cảm xúc của bé đang phát triển thật tuyệt vời.', title_zh = '同理心萌芽了！💖', body_zh = '有人哭或难过时，宝宝会过去摸摸他？宝宝的情商发展得非常好。' WHERE id = 'b2803eb7-9fa9-49b3-a014-d7a2eabb5c95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Energía sin fin al aire libre! 🌳', body_es = 'Para que tu peque, que ya anda solo, gaste energía, encuentra en Lugares para mamás parques nuevos y seguros a los que ir cómodamente.', title_fr = 'Une énergie sans fin en plein air ! 🌳', body_fr = 'Pour que votre petit marcheur se défoule, trouvez dans les Lieux adaptés aux mamans de nouveaux parcs sûrs et faciles d''accès.', title_hi = 'खुली हवा में कभी न खत्म होने वाली ऊर्जा! 🌳', body_hi = 'खुलकर चलने वाले बच्चे की ऊर्जा निकालने के लिए माँ के लिए अनुकूल जगहों में आराम से जाने लायक सुरक्षित और नए पार्क ढूँढिए।', title_id = 'Energi tanpa batas di luar ruangan! 🌳', body_id = 'Agar si kecil yang sudah bebas berjalan bisa menyalurkan energinya, temukan taman baru yang aman dan nyaman di Tempat Ramah Ibu.', title_ja = '外では元気が止まらない！🌳', body_ja = '自由に歩けるようになったお子さんが思いきり遊べるよう、「ママにやさしいスポット」で安全で新しい公園を見つけましょう。', title_ko = '바깥에서 끝없는 에너지! 🌳', body_ko = '자유롭게 걷는 아이가 에너지를 발산할 수 있도록, 편하게 갈 수 있는 안전한 새 공원을 엄마 친화 장소에서 찾아보세요.', title_nl = 'Eindeloze energie in de buitenlucht! 🌳', body_nl = 'Vind in Mamavriendelijke plekken nieuwe, veilige parken waar je makkelijk naartoe kunt, zodat je rondlopende kindje zijn energie kwijt kan.', title_pl = 'Niewyczerpana energia na świeżym powietrzu! 🌳', body_pl = 'Znajdź w Miejscach przyjaznych mamom nowe, bezpieczne parki, do których wygodnie dotrzesz, by twój samodzielnie chodzący maluch mógł się wyszaleć.', title_pt = 'Energia sem fim ao ar livre! 🌳', body_pt = 'Para que o seu filho, que já anda sozinho, gaste energia, encontre nos Locais Amigos das Mães parques novos e seguros onde possa ir à vontade.', title_sv = 'Oändlig energi utomhus! 🌳', body_sv = 'Hitta säkra och nya parker som är lätta att ta sig till i Mammavänliga platser, så att ditt gående barn får ut sin energi.', title_vi = 'Năng lượng ngoài trời không bao giờ cạn! 🌳', body_vi = 'Để bé đã tự đi được xả hết năng lượng, hãy tìm những công viên mới, an toàn và dễ đi trong Địa điểm thân thiện với mẹ.', title_zh = '户外用不完的精力！🌳', body_zh = '为了让会自己走的宝宝释放精力，去妈妈友好场所里找些安全、方便去的新公园吧。' WHERE id = 'e569bdf3-a845-44dc-852b-5318a0cf6a72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se resiste a la siesta 😴', body_es = '¡Jugar es mucho más interesante que dormir! Media hora antes de acostarle, deja los juegos movidos y pasa a actividades más tranquilas.', title_fr = 'Il résiste à la sieste. 😴', body_fr = 'Jouer est bien plus intéressant que dormir ! Une demi-heure avant le coucher, arrêtez les jeux agités et passez à des activités plus calmes.', title_hi = 'दिन की झपकी का विरोध। 😴', body_hi = 'खेलना सोने से ज़्यादा मज़ेदार है! बिस्तर पर जाने से आधा घंटा पहले भाग-दौड़ वाले खेल रोककर शांत गतिविधियाँ शुरू कीजिए।', title_id = 'Menolak tidur siang. 😴', body_id = 'Bermain lebih menarik daripada tidur! Setengah jam sebelum tidur, hentikan permainan aktif dan beralihlah ke kegiatan yang lebih tenang.', title_ja = 'お昼寝を嫌がる 😴', body_ja = '寝るより遊ぶほうが楽しい！寝る30分前には活発な遊びをやめて、静かな遊びに切りかえましょう。', title_ko = '낮잠 거부. 😴', body_ko = '노는 게 자는 것보다 더 재밌으니까요! 잠자리에 들기 30분 전에는 활발한 놀이를 멈추고 차분한 활동으로 바꿔 주세요.', title_nl = 'Verzet tegen het middagdutje. 😴', body_nl = 'Spelen is leuker dan slapen! Stop een half uur voor bedtijd met drukke spelletjes en kies rustigere bezigheden.', title_pl = 'Opór przed drzemką. 😴', body_pl = 'Zabawa jest ciekawsza od spania! Pół godziny przed pójściem do łóżka przerwij ruchliwe zabawy i przejdźcie do spokojniejszych zajęć.', title_pt = 'Resistência à sesta. 😴', body_pt = 'Brincar é mais interessante do que dormir! Meia hora antes de ir para a cama, pare as brincadeiras agitadas e passe a atividades mais calmas.', title_sv = 'Motstånd mot dagsluren. 😴', body_sv = 'Att leka är roligare än att sova! Avbryt livliga lekar en halvtimme före läggdags och gå över till lugnare aktiviteter.', title_vi = 'Bé chống lại giấc ngủ ngày. 😴', body_vi = 'Chơi thú vị hơn ngủ nhiều! Nửa tiếng trước giờ ngủ, hãy dừng các trò vận động và chuyển sang những hoạt động nhẹ nhàng hơn.', title_zh = '抗拒白天小睡 😴', body_zh = '玩比睡有意思多了！上床前半小时停止激烈的游戏，换成安静一点的活动。' WHERE id = '381afc75-3dbd-4716-b5ea-3af987c642dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Haz tus preguntas importantes, como «¿Por qué hay días en que mi hijo no come nada?», a nuestro asistente Anacan AI incluso de madrugada y recibe apoyo.', body_fr = 'Posez vos questions importantes, comme « Pourquoi mon enfant ne mange-t-il rien certains jours ? », à notre assistant Anacan AI, même la nuit, et trouvez du soutien.', body_hi = '''मेरा बच्चा कुछ दिनों में कुछ भी क्यों नहीं खाता?'' जैसे ज़रूरी सवाल रात में भी हमारे Anacan AI असिस्टेंट से पूछिए और सहारा पाइए।', body_id = 'Tanyakan pertanyaan penting seperti "Kenapa anakku kadang tidak mau makan sama sekali?" ke asisten Anacan AI kami dan dapatkan dukungan, bahkan di malam hari.', body_ja = '「どうしてうちの子は食べない日があるの？」といった大切な質問も、夜中でもAnacan AIアシスタントに聞いてサポートを受けましょう。', body_ko = '''우리 아이는 왜 어떤 날은 아무것도 안 먹을까?'' 같은 중요한 질문은 늦은 밤에도 Anacan AI 도우미에게 물어 도움을 받으세요.', body_nl = 'Stel je belangrijke vragen, zoals: waarom eet mijn kind sommige dagen helemaal niets?, zelfs midden in de nacht aan onze assistent Anacan AI en krijg steun.', body_pl = 'Ważne pytania, np. „Dlaczego moje dziecko niektórego dnia nic nie je?”, zadawaj naszemu asystentowi Anacan AI i otrzymaj wsparcie, nawet w nocy.', body_pt = 'Faça as suas perguntas importantes, como "Porque é que o meu filho há dias em que não come nada?", ao nosso assistente Anacan AI, mesmo de madrugada, e receba apoio.', body_sv = 'Ställ dina viktiga frågor, som ”Varför äter mitt barn ingenting vissa dagar?”, till vår assistent Anacan AI även sent på natten och få stöd.', body_vi = 'Những câu hỏi quan trọng như "Sao có ngày con chẳng ăn gì?", ngay cả lúc nửa đêm mẹ cũng có thể hỏi trợ lý Anacan AI để được hỗ trợ.', body_zh = '像“为什么我的孩子有时一点东西都不吃？”这样的重要问题，哪怕深夜也可以问我们的Anacan AI助手，获得支持。' WHERE id = '3ed2bd45-e711-4e56-bdc9-29b31e605069' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cómo lidiar con la selectividad 🍲', body_es = 'Algunos días puede rechazar su comida favorita. No le obligues, simplemente prueba otras recetas alternativas de nuestra app.', title_fr = 'Face aux refus à table. 🍲', body_fr = 'Certains jours, il peut refuser son plat préféré. Ne le forcez pas, essayez simplement d''autres recettes dans l''application.', title_hi = 'खाने के नखरों से निपटना। 🍲', body_hi = 'किसी दिन वह अपना सबसे पसंदीदा खाना भी मना कर सकता है। ज़बरदस्ती मत कीजिए, बस हमारे ऐप की अलग-अलग रेसिपी आज़माइए।', title_id = 'Menghadapi anak pilih-pilih makanan. 🍲', body_id = 'Ada hari-hari ia menolak makanan favoritnya. Jangan dipaksa, coba saja resep alternatif lain di aplikasi kami.', title_ja = '好き嫌いとの付き合い方 🍲', body_ja = '大好きな料理を嫌がる日もあります。無理強いせず、アプリにある別のレシピを試してみましょう。', title_ko = '편식과 씨름하기. 🍲', body_ko = '어떤 날은 가장 좋아하던 음식도 거부할 수 있어요. 억지로 먹이지 말고 앱에 있는 다른 대체 레시피를 시도해 보세요.', title_nl = 'Omgaan met kieskeurig eten. 🍲', body_nl = 'Op sommige dagen weigert je kindje misschien zijn lievelingseten. Dwing hem niet, probeer gewoon andere recepten uit onze app.', title_pl = 'Jak radzić sobie z wybiórczością w jedzeniu. 🍲', body_pl = 'Niektórego dnia może odmówić nawet ulubionego dania. Nie zmuszaj go, po prostu wypróbuj inne przepisy z naszej aplikacji.', title_pt = 'Lidar com a esquisitice à mesa. 🍲', body_pt = 'Há dias em que pode recusar a comida de que mais gosta. Não o obrigue, experimente simplesmente outras receitas alternativas da nossa app.', title_sv = 'Kampen mot kräsenheten. 🍲', body_sv = 'Vissa dagar kan barnet vägra sin favoritmat. Tvinga inte, prova bara andra alternativa recept i appen.', title_vi = 'Đối phó với chứng kén ăn. 🍲', body_vi = 'Có những ngày bé từ chối cả món yêu thích nhất. Đừng ép, chỉ cần thử những công thức khác trong ứng dụng.', title_zh = '应对挑食 🍲', body_zh = '有些日子宝宝可能连最爱吃的都不吃。别强迫，试试我们应用里的其他替代食谱就好。' WHERE id = '718ac202-3ddd-463e-90fd-d1367161e2b5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo limpio yo! 🧽', body_es = '¿Mientras limpias la mesa, él también quiere un trapo? Dale a tu pequeño ayudante una tarea inofensiva. Esto aumenta muchísimo su confianza en sí mismo.', title_fr = 'C''est moi qui essuie ! 🧽', body_fr = 'Quand vous essuyez la table, il veut lui aussi un chiffon ? Confiez à votre petit assistant une tâche sans danger. Sa confiance en lui va grimper en flèche.', title_hi = 'मैं खुद पोंछूँगा! 🧽', body_hi = 'आप मेज़ पोंछती हैं तो वह भी कपड़ा माँगता है? अपने नन्हे मददगार को कोई सुरक्षित काम दीजिए। इससे उसका आत्मविश्वास बहुत बढ़ता है।', title_id = 'Aku yang lap sendiri! 🧽', body_id = 'Saat Anda mengelap meja, ia juga ingin lap? Beri asisten kecil Anda tugas yang aman. Ini akan sangat meningkatkan rasa percaya dirinya.', title_ja = '自分で拭く！🧽', body_ja = 'あなたがテーブルを拭いていると、ふきんをほしがりますか？小さなお手伝いさんに安全な役割をあげましょう。自信がぐんと高まります。', title_ko = '내가 닦을래! 🧽', body_ko = '엄마가 식탁을 닦으면 아이도 행주를 달라고 하나요? 작은 도우미에게 안전한 일을 맡겨 보세요. 자신감이 놀랍도록 자라요.', title_nl = 'Ik veeg het zelf! 🧽', body_nl = 'Wil je kindje ook een doekje als jij de tafel afveegt? Geef je kleine hulpje een onschuldig taakje. Dat geeft zijn zelfvertrouwen een enorme boost.', title_pl = 'Sam wytrę! 🧽', body_pl = 'Gdy wycierasz stół, on też chce ściereczkę? Daj małemu pomocnikowi bezpieczne zadanie. To niesamowicie wzmacnia jego pewność siebie.', title_pt = 'Eu limpo sozinho! 🧽', body_pt = 'Enquanto limpa a mesa, também ele quer um pano? Dê ao seu pequeno ajudante uma tarefa inofensiva. Isso aumenta imenso a autoconfiança dele.', title_sv = 'Jag torkar själv! 🧽', body_sv = 'Vill barnet också ha en trasa när du torkar bordet? Ge din lilla hjälpreda en ofarlig uppgift. Det stärker självförtroendet otroligt mycket.', title_vi = 'Con tự lau! 🧽', body_vi = 'Mẹ lau bàn là bé cũng đòi khăn? Hãy giao cho người phụ giúp nhỏ một việc an toàn. Điều này giúp bé tự tin hơn rất nhiều.', title_zh = '我来擦！🧽', body_zh = '你擦桌子时宝宝也要抹布？给小帮手一个安全的任务吧。这会让他的自信心大大提升。' WHERE id = '9693a098-adc4-4d19-ab73-4c5cc195a25e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del ruido blanco 🎶', body_es = 'Si no consigue dormirse por un día muy activo o por los dientes, pon el sonido de la lluvia en Ruido blanco y crea calma en la habitación.', title_fr = 'La force des bruits blancs. 🎶', body_fr = 'Il n''arrive pas à dormir à cause d''une journée active ou des dents ? Lancez le bruit de la pluie dans les Bruits blancs pour apaiser la chambre.', title_hi = 'व्हाइट नॉइज़ की ताकत। 🎶', body_hi = 'अगर भाग-दौड़ भरे दिन या दाँत निकलने की वजह से वह सो नहीं पा रहा, तो व्हाइट नॉइज़ से बारिश की आवाज़ चलाकर कमरे में शांति बनाइए।', title_id = 'Kekuatan suara putih. 🎶', body_id = 'Kalau ia sulit tidur karena hari yang aktif atau tumbuh gigi, ciptakan ketenangan di kamar dengan memutar suara hujan dari Suara Putih.', title_ja = 'ホワイトノイズの力 🎶', body_ja = '活発に過ごした日や歯の生え始めで寝つけないときは、「ホワイトノイズ」から雨の音を流して、部屋を穏やかな雰囲気にしましょう。', title_ko = '백색소음의 힘. 🎶', body_ko = '활발한 하루나 이앓이 때문에 잠들지 못한다면 백색소음에서 빗소리를 틀어 방을 차분하게 만들어 주세요.', title_nl = 'De kracht van witte ruis. 🎶', body_nl = 'Kan je kindje niet slapen na een drukke dag of door doorkomende tandjes? Zet in Witte ruis het geluid van regen aan en breng rust in de kamer.', title_pl = 'Moc białego szumu. 🎶', body_pl = 'Jeśli po aktywnym dniu lub przez ząbkowanie nie może zasnąć, włącz w Białym szumie odgłos deszczu i stwórz w pokoju spokojną atmosferę.', title_pt = 'A força do Ruído Branco. 🎶', body_pt = 'Se não consegue adormecer por causa de um dia agitado ou dos dentes, ligue o som da chuva no Ruído Branco e crie tranquilidade no quarto.', title_sv = 'Kraften i vitt brus. 🎶', body_sv = 'Om barnet inte kan sova efter en aktiv dag eller på grund av tänderna, skapa lugn i rummet genom att sätta på regnljud i Vitt brus.', title_vi = 'Sức mạnh của tiếng ồn trắng. 🎶', body_vi = 'Nếu bé không ngủ được sau một ngày hiếu động hoặc vì mọc răng, hãy bật tiếng mưa trong Tiếng ồn trắng để căn phòng thêm yên bình.', title_zh = '白噪音的力量 🎶', body_zh = '如果玩了一整天或者出牙让他睡不着，就在白噪音里放雨声，让房间安静下来。' WHERE id = '98ba1e51-63c6-4c73-891d-99f1b14f3495' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tentempiés sanos 🍎', body_es = 'Los trozos de fruta o el yogur son tentempiés ideales a esta edad. Descubre ideas distintas y deliciosas en las recetas infantiles de nuestra app.', title_fr = 'Des en-cas sains. 🍎', body_fr = 'Des tranches de fruits ou un yaourt sont d''excellents en-cas à cet âge. Découvrez des idées variées et savoureuses dans les recettes pour enfants de l''application.', title_hi = 'सेहतमंद स्नैक्स। 🍎', body_hi = 'फलों के टुकड़े या दही इस उम्र के लिए बढ़िया स्नैक हैं। हमारे ऐप की बच्चों की रेसिपी में अलग और स्वादिष्ट आइडिया खोजिए।', title_id = 'Camilan sehat. 🍎', body_id = 'Potongan buah atau yogurt adalah camilan yang pas untuk usia ini. Temukan ide berbeda dan lezat dari resep anak di aplikasi kami.', title_ja = 'ヘルシーなおやつ 🍎', body_ja = '果物やヨーグルトは、この年齢にぴったりのおやつです。アプリの子ども向けレシピで、いろいろなおいしいアイデアを見つけましょう。', title_ko = '건강한 간식. 🍎', body_ko = '과일 조각이나 요거트는 이 나이에 훌륭한 간식이에요. 앱의 아이 레시피에서 색다르고 맛있는 아이디어를 찾아보세요.', title_nl = 'Gezonde tussendoortjes. 🍎', body_nl = 'Stukjes fruit of yoghurt zijn op deze leeftijd prima tussendoortjes. Ontdek andere lekkere ideeën in de kinderrecepten van onze app.', title_pl = 'Zdrowe przekąski. 🍎', body_pl = 'Plasterki owoców lub jogurt to świetna przekąska w tym wieku. Odkryj inne, smaczne pomysły w przepisach dla dzieci w naszej aplikacji.', title_pt = 'Lanches saudáveis. 🍎', body_pt = 'Fatias de fruta ou iogurte são um ótimo lanche para esta idade. Descubra ideias diferentes e deliciosas nas receitas para crianças da nossa app.', title_sv = 'Nyttiga mellanmål. 🍎', body_sv = 'Fruktbitar eller yoghurt är utmärkta mellanmål i den här åldern. Upptäck nya och goda idéer bland barnrecepten i appen.', title_vi = 'Bữa ăn nhẹ lành mạnh. 🍎', body_vi = 'Lát trái cây hay sữa chua là món ăn nhẹ tuyệt vời cho tuổi này. Hãy khám phá những ý tưởng mới lạ, ngon miệng trong các công thức cho bé trên ứng dụng.', title_zh = '健康小零食 🍎', body_zh = '水果片或酸奶是这个年龄的好零食。在我们应用的儿童食谱里发现更多新鲜美味的点子吧。' WHERE id = 'f5a87b81-5f64-4d75-abaf-6fd718e53fc5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Sus primeras obras de arte! 🖍', body_es = '️ Le encanta garabatear en el papel con ceras gruesas. Guarda sus primeras obras de arte para el futuro en la Sesión de fotos del bebé.', title_fr = 'Ses premières œuvres d''art ! 🖍', body_fr = '️ Il adore gribouiller sur du papier avec de gros crayons. Gardez ses premières œuvres pour plus tard dans la Séance photo bébé.', title_hi = 'पहली पेंटिंग! 🖍', body_hi = '️ उसे मोटे रंगों से कागज़ पर लकीरें खींचना बहुत पसंद है। उसकी पहली कलाकृतियों को बेबी फ़ोटोशूट सेक्शन में भविष्य के लिए सहेजिए।', title_id = 'Karya seni pertama! 🖍', body_id = '️ Ia sangat senang mencoret-coret kertas dengan krayon tebal. Simpan karya seni pertamanya untuk masa depan di bagian Sesi Foto Bayi.', title_ja = 'はじめての作品！🖍', body_ja = '️太いクレヨンで紙にお絵かきするのが大好き。はじめての作品を「ベビーフォトセッション」に保存して、将来の思い出にしましょう。', title_ko = '첫 그림 작품! 🖍', body_ko = '️굵은 크레용으로 종이에 끄적이는 걸 정말 좋아해요. 첫 작품들을 아기 사진 촬영 섹션에 남겨 두고 훗날 꺼내 보세요.', title_nl = 'De eerste kunstwerken! 🖍', body_nl = '️ Je kindje krast heel graag met dikke verf op papier. Bewaar zijn eerste kunstwerken voor later in het onderdeel Babyfotoshoot.', title_pl = 'Pierwsze dzieła sztuki! 🖍', body_pl = '️ Uwielbia bazgrać grubymi kredkami po papierze. Zachowaj jego pierwsze dzieła na przyszłość w sekcji Sesja zdjęciowa dziecka.', title_pt = 'As primeiras obras de arte! 🖍', body_pt = '️ Adora rabiscar no papel com lápis de cor grossos. Guarde as primeiras obras de arte dele para o futuro na Sessão Fotográfica do Bebé.', title_sv = 'De första konstverken! 🖍', body_sv = '️ Barnet älskar att klottra med tjocka kritor på papper. Spara de första konstverken för framtiden i avsnittet Babyfotografering.', title_vi = 'Những tác phẩm hội họa đầu tiên! 🖍', body_vi = '️ Bé rất thích vẽ nguệch ngoạc bằng bút màu to trên giấy. Hãy lưu giữ những tác phẩm nghệ thuật đầu tiên của bé trong mục Chụp ảnh cho bé để làm kỷ niệm.', title_zh = '第一批画作！🖍', body_zh = '️ 宝宝特别喜欢用粗蜡笔在纸上涂鸦。把他的第一批艺术作品保存在宝宝写真板块里，留给将来吧。' WHERE id = '0b365564-8d23-4572-9881-7a4b9e2159bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Incluso cuando vas al baño, te espera detrás de la puerta llorando. La ansiedad por separación está en su punto máximo. Dale seguridad cada vez.', body_fr = 'Même quand vous allez aux toilettes, il vous attend en pleurant derrière la porte. L''angoisse de séparation est à son comble. Rassurez-le à chaque fois.', body_hi = 'आप टॉयलेट भी जाती हैं तो वह दरवाज़े के पीछे इंतज़ार करते हुए रोता है। अलगाव की बेचैनी चरम पर है। उसे हर बार भरोसा दिलाइए।', body_id = 'Bahkan saat Anda ke toilet, ia menunggu di balik pintu sambil menangis. Kecemasan berpisahnya sedang di puncak. Beri ia rasa aman setiap kali.', body_ja = 'トイレに行くときでさえ、ドアの向こうで泣きながら待っています。分離不安がピークです。そのたびに安心させてあげましょう。', body_ko = '화장실에만 가도 문 앞에서 엄마를 기다리며 우나요? 분리불안이 최고조예요. 그때마다 안심시켜 주세요.', body_nl = 'Zelfs als je naar de wc gaat, wacht je kindje huilend achter de deur. De scheidingsangst is op zijn hoogtepunt. Stel hem elke keer gerust.', body_pl = 'Nawet gdy idziesz do łazienki, czeka pod drzwiami i płacze. Lęk separacyjny jest na szczycie. Za każdym razem dawaj mu poczucie bezpieczeństwa.', body_pt = 'Até quando vai à casa de banho, fica atrás da porta à sua espera, a chorar. A ansiedade de separação está no auge. Transmita-lhe segurança todas as vezes.', body_sv = 'Även när du går på toaletten väntar barnet bakom dörren och gråter. Separationsångesten är på topp. Ge barnet trygghet varje gång.', body_vi = 'Ngay cả khi mẹ vào nhà vệ sinh, bé cũng đứng sau cửa chờ và khóc. Nỗi lo xa mẹ đang ở đỉnh điểm. Hãy trấn an bé mỗi lần như vậy.', body_zh = '连你去上厕所，他都在门外等着哭。分离焦虑正处于高峰。每次都给他安全感吧。' WHERE id = 'c0638659-03fe-4ca5-b078-76057498811f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El hábito de beber agua es importante 💧', body_es = 'Cuanto más se mueve, más sed tiene. No olvides ofrecerle agua mientras juega y después de las comidas.', title_fr = 'L''habitude de boire de l''eau compte. 💧', body_fr = 'Plus il bouge, plus il a soif. N''oubliez pas de lui proposer de l''eau pendant les jeux et après les repas.', title_hi = 'पानी पीने की आदत ज़रूरी है। 💧', body_hi = 'जितनी भाग-दौड़, उतनी प्यास। खेल के दौरान और खाने के बाद उसे पानी देना मत भूलिए।', title_id = 'Kebiasaan minum air itu penting. 💧', body_id = 'Makin aktif bergerak, makin cepat haus. Jangan lupa menawarinya air saat bermain dan setelah makan.', title_ja = 'お水を飲む習慣は大切です 💧', body_ja = '活発に動くほど、のどもよく渇きます。遊んでいるときや食事のあとに、お水をすすめるのを忘れずに。', title_ko = '물 마시는 습관이 중요해요. 💧', body_ko = '활발하게 움직일수록 목도 더 말라요. 놀이 중과 식사 후에 물을 권하는 걸 잊지 마세요.', title_nl = 'Water drinken is een belangrijke gewoonte. 💧', body_nl = 'Hoe actiever je kindje is, hoe meer dorst hij krijgt. Vergeet niet hem tijdens het spelen en na het eten water aan te bieden.', title_pl = 'Nawyk picia wody jest ważny. 💧', body_pl = 'Im więcej się rusza, tym bardziej chce mu się pić. Pamiętaj, by proponować mu wodę podczas zabawy i po posiłkach.', title_pt = 'O hábito de beber água é importante. 💧', body_pt = 'Quanto mais se mexe, mais sede tem. Não se esqueça de lhe oferecer água durante as brincadeiras e depois das refeições.', title_sv = 'Vanan att dricka vatten är viktig. 💧', body_sv = 'Ju mer aktivt barnet är, desto törstigare blir det. Glöm inte att erbjuda vatten under leken och efter måltiderna.', title_vi = 'Thói quen uống nước rất quan trọng. 💧', body_vi = 'Càng vận động nhiều, bé càng khát. Mẹ nhớ cho bé uống nước trong lúc chơi và sau bữa ăn nhé.', title_zh = '喝水习惯很重要 💧', body_zh = '活动越多越容易口渴。玩耍时和饭后，别忘了给宝宝喝点水。' WHERE id = 'f2ba1614-ef41-4060-97ee-0fe66e58b884' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Intenta poner dos o tres cubos uno encima de otro. Observa en silencio sus intentos de pequeño ingeniero.', body_fr = 'Il essaie d''empiler deux ou trois cubes. Observez en silence ses petits essais d''ingénieur.', body_hi = 'दो या तीन खिलौना ब्लॉक एक के ऊपर एक रखने की कोशिश करता है। उसकी इन छोटी इंजीनियरिंग कोशिशों को चुपचाप देखिए।', body_id = 'Ia mencoba menumpuk dua atau tiga balok mainan. Saksikan diam-diam usaha kecilnya sebagai insinyur.', body_ja = 'おもちゃの積み木を2つか3つ重ねようとしています。この小さなエンジニアの挑戦を、そっと見守りましょう。', body_ko = '블록 두세 개를 쌓아 보려 해요. 이 작은 엔지니어링 도전을 조용히 지켜봐 주세요.', body_nl = 'Je kindje probeert twee of drie blokken op elkaar te zetten. Kijk stil toe bij deze kleine bouwpogingen.', body_pl = 'Próbuje ustawić dwie lub trzy kostki jedna na drugiej. Po cichu obserwuj jego małe inżynierskie próby.', body_pt = 'Tenta empilhar dois ou três cubos. Observe em silêncio estas pequenas tentativas de engenharia.', body_sv = 'Barnet försöker stapla två eller tre klossar. Följ dessa små ingenjörsförsök i tysthet.', body_vi = 'Bé cố chồng hai, ba khối đồ chơi lên nhau. Hãy lặng lẽ quan sát những nỗ lực "kỹ sư" nhỏ bé này.', body_zh = '宝宝在尝试把两三块积木摞起来。静静地欣赏这位小工程师的尝试吧。' WHERE id = '356f85b5-b941-4e2e-8218-18498e652ff8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del ruido blanco 🎶', body_es = 'Si no consigue dormirse por un día muy activo o por los dientes, pon el sonido de la lluvia en Ruido blanco y crea calma en la habitación.', title_fr = 'La force des bruits blancs. 🎶', body_fr = 'Il n''arrive pas à dormir à cause d''une journée active ou des dents ? Lancez le bruit de la pluie dans les Bruits blancs pour apaiser la chambre.', title_hi = 'व्हाइट नॉइज़ की ताकत। 🎶', body_hi = 'अगर भाग-दौड़ भरे दिन या दाँत निकलने की वजह से वह सो नहीं पा रहा, तो व्हाइट नॉइज़ से बारिश की आवाज़ चलाकर कमरे में शांति बनाइए।', title_id = 'Kekuatan suara putih. 🎶', body_id = 'Kalau ia sulit tidur karena hari yang aktif atau tumbuh gigi, ciptakan ketenangan di kamar dengan memutar suara hujan dari Suara Putih.', title_ja = 'ホワイトノイズの力 🎶', body_ja = '活発に過ごした日や歯の生え始めで寝つけないときは、「ホワイトノイズ」から雨の音を流して、部屋を穏やかな雰囲気にしましょう。', title_ko = '백색소음의 힘. 🎶', body_ko = '활발한 하루나 이앓이 때문에 잠들지 못한다면 백색소음에서 빗소리를 틀어 방을 차분하게 만들어 주세요.', title_nl = 'De kracht van witte ruis. 🎶', body_nl = 'Kan je kindje niet slapen na een drukke dag of door doorkomende tandjes? Zet in Witte ruis het geluid van regen aan en breng rust in de kamer.', title_pl = 'Moc białego szumu. 🎶', body_pl = 'Jeśli po aktywnym dniu lub przez ząbkowanie nie może zasnąć, włącz w Białym szumie odgłos deszczu i stwórz w pokoju spokojną atmosferę.', title_pt = 'A força do Ruído Branco. 🎶', body_pt = 'Se não consegue adormecer por causa de um dia agitado ou dos dentes, ligue o som da chuva no Ruído Branco e crie tranquilidade no quarto.', title_sv = 'Kraften i vitt brus. 🎶', body_sv = 'Om barnet inte kan sova efter en aktiv dag eller på grund av tänderna, skapa lugn i rummet genom att sätta på regnljud i Vitt brus.', title_vi = 'Sức mạnh của tiếng ồn trắng. 🎶', body_vi = 'Nếu bé không ngủ được sau một ngày hiếu động hoặc vì mọc răng, hãy bật tiếng mưa trong Tiếng ồn trắng để căn phòng thêm yên bình.', title_zh = '白噪音的力量 🎶', body_zh = '如果玩了一整天或者出牙让他睡不着，就在白噪音里放雨声，让房间安静下来。' WHERE id = 'b22af5a1-54b4-4af4-afbf-f4de46dc6ba3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lavarse los dientes es divertido 🪥', body_es = '¿Quiere coger el cepillo él solo? Con un cepillo suave adecuado para él, lavaos los dientes juntos delante del espejo y crea este hábito.', title_fr = 'Le brossage des dents en s''amusant. 🪥', body_fr = 'Il veut tenir sa brosse à dents tout seul ? Brossez-vous les dents ensemble devant le miroir avec une brosse souple adaptée pour lui donner cette habitude.', title_hi = 'दाँत ब्रश करने की मस्ती। 🪥', body_hi = 'टूथब्रश खुद पकड़ना चाहता है? उसके लिए सही, नरम ब्रश लेकर आईने के सामने साथ-साथ दाँत साफ़ कीजिए और यह आदत डालिए।', title_id = 'Serunya menyikat gigi. 🪥', body_id = 'Ia ingin memegang sikat giginya sendiri? Tanamkan kebiasaan ini dengan menyikat gigi bersama di depan cermin memakai sikat lembut yang sesuai untuknya.', title_ja = '歯みがきを楽しく 🪥', body_ja = '自分で歯ブラシを持ちたがりますか？やわらかい子ども用の歯ブラシで、鏡の前で一緒に歯みがきをして、習慣にしていきましょう。', title_ko = '즐거운 양치 시간. 🪥', body_ko = '칫솔을 직접 잡고 싶어 하나요? 아이에게 맞는 부드러운 칫솔로 거울 앞에서 함께 양치하며 습관을 길러 주세요.', title_nl = 'Tandenpoetsen is leuk. 🪥', body_nl = 'Wil je kindje zelf de tandenborstel vasthouden? Poets samen voor de spiegel met een geschikte zachte borstel en leer hem zo deze gewoonte aan.', title_pl = 'Zabawa w mycie zębów. 🪥', body_pl = 'Chce sam trzymać szczoteczkę? Myjcie razem zęby przed lustrem miękkimi szczoteczkami odpowiednimi dla niego i wyrabiajcie ten nawyk.', title_pt = 'Diversão a escovar os dentes. 🪥', body_pt = 'Quer segurar a escova de dentes sozinho? Crie este hábito escovando os dentes juntos em frente ao espelho, com escovas macias adequadas para ele.', title_sv = 'Rolig tandborstning. 🪥', body_sv = 'Vill barnet hålla tandborsten själv? Skapa vanan genom att borsta tänderna tillsammans framför spegeln med mjuka borstar som passar barnet.', title_vi = 'Đánh răng thật vui. 🪥', body_vi = 'Bé muốn tự cầm bàn chải? Hãy cùng bé đánh răng trước gương với bàn chải mềm phù hợp để hình thành thói quen này.', title_zh = '刷牙真好玩 🪥', body_zh = '宝宝想自己拿牙刷？准备一把合适的软毛牙刷，在镜子前和他一起刷牙，培养这个习惯吧。' WHERE id = 'f73e2678-7057-466b-a01a-218bff7ab963' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse sin esfuerzo 🌙', body_es = 'Después de un día activo, baja las luces de la habitación, habla más bajito y léele un cuento con voz suave para prepararle para dormir.', title_fr = 'Un endormissement en douceur. 🌙', body_fr = 'Après une journée active, tamisez la lumière, baissez la voix et préparez-le au sommeil en lui lisant une histoire d''un ton doux.', title_hi = 'नींद में आसानी से जाना। 🌙', body_hi = 'भाग-दौड़ भरे दिन के बाद कमरे की रोशनी धीमी कीजिए, आवाज़ धीमी रखिए और धीमे लहजे में कहानी पढ़कर उसे नींद के लिए तैयार कीजिए।', title_id = 'Peralihan yang mudah ke tidur. 🌙', body_id = 'Setelah hari yang aktif, redupkan lampu kamar, pelankan suara Anda, dan siapkan ia tidur dengan membacakan dongeng dengan nada lembut.', title_ja = '眠りへの切りかえをスムーズに 🌙', body_ja = '活発に過ごした日のあとは、照明を暗くして声のトーンを落とし、やさしい声でお話を読んで眠りへと導きましょう。', title_ko = '편안하게 잠으로. 🌙', body_ko = '활발한 하루가 끝나면 방의 조명을 낮추고 목소리도 낮춰, 느린 목소리로 동화를 읽어 주며 잠을 준비하세요.', title_nl = 'Makkelijk in slaap vallen. 🌙', body_nl = 'Dim na een drukke dag de lichten, praat zachter en lees met een rustige stem een verhaaltje voor om hem klaar te maken voor de slaap.', title_pl = 'Łatwe zasypianie. 🌙', body_pl = 'Po aktywnym dniu przygaś światła w pokoju, mów ciszej i przygotuj go do snu, czytając bajkę łagodnym głosem.', title_pt = 'Uma passagem fácil para o sono. 🌙', body_pt = 'Depois de um dia agitado, baixe as luzes do quarto, fale mais baixinho e prepare-o para dormir lendo-lhe uma história em tom suave.', title_sv = 'Lätt övergång till sömn. 🌙', body_sv = 'Dämpa ljuset efter en aktiv dag, sänk rösten och förbered barnet för sömn genom att läsa en saga med lugn röst.', title_vi = 'Vào giấc nhẹ nhàng. 🌙', body_vi = 'Sau một ngày hiếu động, hãy giảm đèn, hạ giọng và đọc truyện cho bé bằng giọng chậm rãi để chuẩn bị cho giấc ngủ.', title_zh = '轻松入睡 🌙', body_zh = '忙碌了一天后，调暗房间灯光，放低声音，用轻柔的语调给他讲个故事，为入睡做准备。' WHERE id = '58b586ed-1396-42c6-81f5-29f087488332' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu energía también se agota 🥗', body_es = '¿Muy cansada? Prepara en Recetas saludables para mujeres un batido lleno de vitaminas que te devuelva la energía al momento y date un premio.', title_fr = 'Votre énergie aussi peut s''épuiser. 🥗', body_fr = 'Très fatiguée ? Préparez un smoothie vitaminé des Recettes saines pour femmes qui vous redonnera vite de l''énergie, et faites-vous plaisir.', title_hi = 'आपकी ऊर्जा भी खत्म हो सकती है। 🥗', body_hi = 'बहुत थक गईं? महिलाओं के लिए सेहतमंद रेसिपी से ऐसी विटामिन भरी स्मूदी बनाइए जो तुरंत ऊर्जा लौटाए, और खुद को इनाम दीजिए।', title_id = 'Energi Anda juga bisa habis. 🥗', body_id = 'Sangat lelah? Buat smoothie kaya vitamin dari Resep Sehat untuk wanita yang langsung memulihkan energi Anda, dan manjakan diri.', title_ja = 'あなたのエネルギーも切れることがあります 🥗', body_ja = 'とても疲れましたか？「女性のためのヘルシーレシピ」から、すぐに元気を取り戻せるビタミンたっぷりのスムージーをつくって、自分にごほうびをあげましょう。', title_ko = '엄마의 에너지도 바닥날 수 있어요. 🥗', body_ko = '많이 지쳤나요? 건강한 레시피에서 기운을 바로 되찾아 줄 비타민 스무디를 만들어 스스로에게 상을 주세요.', title_nl = 'Ook jouw energie kan opraken. 🥗', body_nl = 'Ben je erg moe? Maak uit Gezonde recepten voor vrouwen een vitaminerijke smoothie die je meteen nieuwe energie geeft, en beloon jezelf.', title_pl = 'Twoja energia też może się wyczerpać. 🥗', body_pl = 'Jesteś bardzo zmęczona? Przygotuj ze Zdrowych przepisów dla kobiet witaminowe smoothie, które od razu przywróci ci energię, i nagródź się.', title_pt = 'A sua energia também se pode esgotar. 🥗', body_pt = 'Está muito cansada? Prepare nas Receitas Saudáveis para Mulheres um batido cheio de vitaminas que lhe devolva logo a energia, e recompense-se.', title_sv = 'Din energi kan också ta slut. 🥗', body_sv = 'Är du väldigt trött? Gör en vitaminrik smoothie från Hälsosamma recept för kvinnor som snabbt fyller på energin och belöna dig själv.', title_vi = 'Năng lượng của mẹ cũng có thể cạn. 🥗', body_vi = 'Mẹ mệt lắm rồi? Hãy làm một ly sinh tố giàu vitamin từ Công thức lành mạnh cho phụ nữ để lấy lại năng lượng ngay và tự thưởng cho mình nhé.', title_zh = '你的能量也会耗尽 🥗', body_zh = '太累了？从女性健康食谱里做一杯富含维生素、能马上恢复精力的果昔，犒劳一下自己吧。' WHERE id = '82b39d0a-8bac-4430-a17f-2937f0af35e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡A explorar la cocina! 🍳', body_es = 'Las ollas, las cucharas y los recipientes de plástico se han convertido en sus juguetes favoritos. Deja a su alcance los armarios seguros para que los explore.', title_fr = 'Explorations en cuisine ! 🍳', body_fr = 'Casseroles, cuillères et boîtes en plastique sont devenues ses jouets préférés. Laissez-lui les placards sans danger à explorer.', title_hi = 'रसोई की खोज! 🍳', body_hi = 'पतीले, चम्मच और प्लास्टिक के बर्तन उसके सबसे पसंदीदा खिलौने बन गए हैं। सुरक्षित अलमारियाँ उसकी खोज के लिए खुली छोड़ दीजिए।', title_id = 'Menjelajah dapur! 🍳', body_id = 'Panci, sendok, dan wadah plastik kini jadi mainan favoritnya. Biarkan lemari yang aman terbuka untuk ia jelajahi.', title_ja = 'キッチン探検！🍳', body_ja = 'お鍋やスプーン、プラスチック容器がいちばんのおもちゃに。安全な戸棚は、自由に探検できるようにしておきましょう。', title_ko = '부엌 탐험! 🍳', body_ko = '냄비, 숟가락, 플라스틱 그릇이 가장 좋아하는 장난감이 됐어요. 안전한 수납장은 마음껏 탐험하게 열어 두세요.', title_nl = 'Ontdekkingstocht in de keuken! 🍳', body_nl = 'Pannen, lepels en plastic bakjes zijn zijn favoriete speelgoed geworden. Laat de veilige kastjes open om te ontdekken.', title_pl = 'Kuchenne odkrycia! 🍳', body_pl = 'Garnki, łyżki i plastikowe pojemniki stały się jego ulubionymi zabawkami. Zostaw bezpieczne szafki otwarte do jego odkrywania.', title_pt = 'Exploração na cozinha! 🍳', body_pt = 'Tachos, colheres e recipientes de plástico tornaram-se os brinquedos preferidos dele. Deixe os armários seguros abertos para ele explorar.', title_sv = 'Upptäcktsfärd i köket! 🍳', body_sv = 'Kastruller, skedar och plastburkar har blivit favoritleksakerna. Låt de säkra skåpen vara öppna för barnets upptäckter.', title_vi = 'Khám phá nhà bếp! 🍳', body_vi = 'Nồi, thìa và hộp nhựa đã trở thành đồ chơi yêu thích nhất của bé. Hãy để những chiếc tủ an toàn cho bé tự do khám phá.', title_zh = '厨房大探索！🍳', body_zh = '锅、勺子和塑料碗成了宝宝最爱的玩具。把安全的柜子留给他去探索吧。' WHERE id = '1bf6a974-24ed-47b3-8587-a38235ea120e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hay que actualizar la seguridad! 🛡', body_es = '️ A medida que anda solo y abre armarios, aumentan los peligros. Echa un vistazo a nuestra lista de Productos recomendados para encontrar cierres de seguridad y protectores de esquinas.', title_fr = 'La sécurité doit être revue ! 🛡', body_fr = '️ Plus il se promène librement et ouvre les placards, plus les dangers augmentent. Consultez notre liste de Produits recommandés pour les verrous de sécurité et les protège-coins.', title_hi = 'सुरक्षा को अपडेट करना ज़रूरी है! 🛡', body_hi = '️ जैसे-जैसे वह खुलकर चलता है और अलमारियाँ खोलता है, खतरे बढ़ते हैं। चाइल्ड लॉक और कॉर्नर गार्ड के लिए हमारी सुझाए गए प्रोडक्ट की लिस्ट ज़रूर देखिए।', title_id = 'Keamanan perlu diperbarui! 🛡', body_id = '️ Saat ia bebas berjalan dan membuka lemari, bahayanya bertambah. Pastikan melihat daftar Produk Rekomendasi kami untuk kunci pengaman anak dan pelindung sudut.', title_ja = '安全対策を見直そう！🛡', body_ja = '️自由に歩いて戸棚を開けるほど、危険も増えます。チャイルドロックやコーナーガードは、ぜひ「おすすめ商品」リストでチェックしましょう。', title_ko = '안전 점검을 새로 할 때예요! 🛡', body_ko = '️자유롭게 걷고 수납장을 열수록 위험도 늘어나요. 안전 잠금장치와 모서리 보호대는 추천 제품 목록에서 꼭 확인하세요.', title_nl = 'Tijd om de veiligheid bij te werken! 🛡', body_nl = '️ Nu je kindje vrij rondloopt en kastjes opent, nemen de gevaren toe. Bekijk zeker onze lijst Aanbevolen producten voor kinderslotjes en hoekbeschermers.', title_pl = 'Czas odświeżyć zabezpieczenia! 🛡', body_pl = '️ Gdy swobodnie chodzi i otwiera szafki, zagrożeń przybywa. Koniecznie zajrzyj do naszej listy Polecanych produktów po blokady i osłonki na narożniki.', title_pt = 'É altura de reforçar a segurança! 🛡', body_pt = '️ À medida que anda à vontade e abre armários, os perigos aumentam. Não deixe de ver a nossa lista de Produtos Recomendados para trancas de segurança e protetores de esquinas.', title_sv = 'Säkerheten behöver uppdateras! 🛡', body_sv = '️ När barnet går fritt och öppnar skåp ökar riskerna. Titta i vår lista Rekommenderade produkter efter barnlås och hörnskydd.', title_vi = 'Cần cập nhật an toàn! 🛡', body_vi = '️ Bé càng tự đi lại và mở tủ, nguy hiểm càng tăng. Mẹ nhớ xem danh sách Sản phẩm gợi ý của chúng tôi để tìm khóa an toàn và miếng bọc góc nhé.', title_zh = '安全措施需要升级！🛡', body_zh = '️ 宝宝自由走动、打开柜子，危险也随之增加。一定要看看我们推荐商品清单里的儿童安全锁和防撞护角。' WHERE id = '88b4c840-5c20-4f9f-8b89-4530da60297b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de la noche es mágico 📖', body_es = 'Una historia corta antes de dormir estimula su imaginación y refuerza el vínculo emocional entre vosotros.', title_fr = 'L''histoire du soir est magique. 📖', body_fr = 'Une petite histoire lue avant de dormir stimule son imagination et renforce le lien affectif entre vous.', title_hi = 'शाम की कहानी जादुई होती है। 📖', body_hi = 'सोने से पहले पढ़ी गई छोटी कहानी कल्पना शक्ति भी बढ़ाती है और आपके बीच का भावनात्मक रिश्ता भी मज़बूत करती है।', title_id = 'Dongeng malam itu ajaib. 📖', body_id = 'Cerita pendek sebelum tidur tidak hanya memperkuat daya khayalnya, tapi juga mempererat ikatan emosional di antara kalian.', title_ja = '寝る前のお話は魔法の時間 📖', body_ja = '寝る前の短いお話は、想像力をふくらませ、親子の心のつながりも深めてくれます。', title_ko = '잠자리 동화는 마법이에요. 📖', body_ko = '잠들기 전 읽어 주는 짧은 이야기는 상상력을 키우고 두 사람의 정서적 유대도 더 깊게 해 줘요.', title_nl = 'Een verhaaltje voor het slapen is magisch. 📖', body_nl = 'Een kort verhaaltje voor het slapengaan prikkelt de fantasie en versterkt de band tussen jullie.', title_pl = 'Wieczorna bajka jest magiczna. 📖', body_pl = 'Krótka historia przed snem rozwija wyobraźnię i wzmacnia więź emocjonalną między wami.', title_pt = 'A história da noite é mágica. 📖', body_pt = 'Uma história curta antes de dormir estimula a imaginação e reforça o laço emocional entre vocês.', title_sv = 'Kvällssagan är magisk. 📖', body_sv = 'En kort berättelse före sömnen stärker både fantasin och det känslomässiga bandet mellan er.', title_vi = 'Truyện kể buổi tối thật kỳ diệu. 📖', body_vi = 'Một câu chuyện ngắn trước khi ngủ vừa giúp bé phát triển trí tưởng tượng, vừa gắn kết tình cảm giữa mẹ và bé.', title_zh = '睡前故事有魔力 📖', body_zh = '睡前读一个小故事，既能激发想象力，又能加深你们之间的情感联结。' WHERE id = '409e6b49-8ccb-4975-92b1-c12021092540' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crece muy deprisa 📏', body_es = '¡Se le vuelve a quedar pequeña la ropa! Añade su nueva altura y su nuevo peso en el Seguimiento del desarrollo y celebra su crecimiento sano.', title_fr = 'Il grandit vite. 📏', body_fr = 'Ses vêtements recommencent à devenir trop petits ! Ajoutez sa nouvelle taille et son nouveau poids dans le Suivi de croissance et notez sa bonne évolution.', title_hi = 'बढ़ने की रफ़्तार तेज़ है। 📏', body_hi = 'बच्चे के कपड़े फिर छोटे होने लगे हैं! ग्रोथ ट्रैकर सेक्शन में नई लंबाई और वज़न जोड़िए और उसके सेहतमंद विकास को दर्ज कीजिए।', title_id = 'Pertumbuhannya cepat. 📏', body_id = 'Baju si kecil mulai kekecilan lagi! Tambahkan tinggi dan berat terbarunya di Pelacak Pertumbuhan dan catat pertumbuhannya yang sehat.', title_ja = '成長のスピードは速い 📏', body_ja = 'お洋服がまた小さくなってきました！「発達トラッカー」に新しい身長と体重を追加して、健やかな成長を記録しましょう。', title_ko = '쑥쑥 자라고 있어요. 📏', body_ko = '아이 옷이 또 작아지기 시작했나요? 성장 기록에 새 키와 몸무게를 추가하고 건강한 성장을 기록하세요.', title_nl = 'Het groeitempo is hoog. 📏', body_nl = 'De kleertjes van je kindje worden alweer te klein! Voeg de nieuwe lengte en het nieuwe gewicht toe in de Groeitracker en houd zijn gezonde groei bij.', title_pl = 'Szybko rośnie. 📏', body_pl = 'Ubranka znów robią się za małe! Dodaj nowy wzrost i wagę w sekcji Śledzenie rozwoju i zapisuj jego zdrowy rozwój.', title_pt = 'O ritmo de crescimento é rápido. 📏', body_pt = 'A roupa do seu filho começa outra vez a ficar pequena! Adicione a nova altura e o novo peso no Registo de Desenvolvimento e registe o seu crescimento saudável.', title_sv = 'Tillväxten går snabbt. 📏', body_sv = 'Barnets kläder börjar bli för små igen! Lägg in ny längd och vikt i Tillväxtspåraren och anteckna den friska utvecklingen.', title_vi = 'Bé lớn rất nhanh. 📏', body_vi = 'Quần áo của bé lại bắt đầu chật! Hãy thêm chiều cao và cân nặng mới vào mục Theo dõi phát triển và ghi lại sự phát triển khỏe mạnh của bé.', title_zh = '长得飞快 📏', body_zh = '宝宝的衣服又开始变小了！在发育追踪里添加新的身高和体重数据，记录宝宝的健康成长吧。' WHERE id = '6b7d6637-7328-44aa-b6c8-47c73df3a6f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Levanta los brazos cuando le dices «¿Nos vamos?» o niega con la cabeza al oír «No»? ¡Su capacidad de comprensión ha crecido muchísimo!', body_fr = 'Il lève les bras quand vous dites « On y va ? » ou secoue la tête quand vous dites « Non ». Sa compréhension a fait un bond incroyable !', body_hi = '''चलें?'' कहने पर हाथ ऊपर उठाता है या ''नहीं'' कहते हुए सिर हिलाता है। उसकी समझने की क्षमता कमाल की बढ़ गई है!', body_id = 'Ia mengangkat tangan saat Anda bilang "Ayo pergi?" atau menggeleng saat bilang "Tidak"? Kemampuan memahaminya meningkat luar biasa!', body_ja = '「行こうか？」と言うと両手を上げたり、「ダメ」と言うと首を振ったり。言葉を理解する力がぐんと伸びています！', body_ko = '"갈까?" 하면 두 팔을 들고, "안 돼" 하면 고개를 저어요. 이해력이 놀랍도록 자랐어요!', body_nl = 'Steekt je kindje zijn armpjes omhoog als je vraagt: gaan we? Of schudt hij nee? Hij begrijpt ongelofelijk veel meer!', body_pl = 'Na „Idziemy?” podnosi rączki, a na „Nie” kręci główką. Jego rozumienie mowy niesamowicie wzrosło!', body_pt = 'Levanta os braços quando lhe diz "Vamos?" ou abana a cabeça quando ouve "Não". A capacidade de compreensão cresceu imenso!', body_sv = 'Barnet sträcker upp armarna när du säger ”Ska vi gå?” eller skakar på huvudet vid ”Nej”. Förståelsen har ökat otroligt!', body_vi = 'Mẹ hỏi "Đi nhé?" là bé giơ tay, nghe "Không" là bé lắc đầu. Khả năng hiểu của bé đã tăng vượt bậc!', body_zh = '你说“走吗？”宝宝就举起双手，说“不行”就摇头。理解能力真是突飞猛进！' WHERE id = '807127b9-417f-43a0-9bca-9ef33fbdadb8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Aventura al aire libre! 🌳', body_es = '¿No consigue gastar energía en casa? Elige un parque seguro por el que pasear cómodamente con el carrito y disfrutad juntos del aire fresco.', title_fr = 'Aventure en plein air ! 🌳', body_fr = 'Il n''arrive pas à se défouler à la maison ? Choisissez un parc sûr où vous promener facilement avec la poussette et profitez ensemble de l''air frais.', title_hi = 'खुली हवा का रोमांच! 🌳', body_hi = 'घर में ऊर्जा नहीं निकाल पा रहा? ऐसा सुरक्षित पार्क चुनिए जहाँ स्ट्रॉलर के साथ आराम से घूम सकें, और साथ में ताज़ी हवा का मज़ा लीजिए।', title_id = 'Petualangan di luar ruangan! 🌳', body_id = 'Ia tidak bisa menyalurkan energinya di dalam rumah? Pilih taman aman yang nyaman untuk stroller dan nikmati udara segar bersama.', title_ja = 'お外で冒険！🌳', body_ja = '家の中ではエネルギーを発散しきれない？ベビーカーで気軽に行ける安全な公園を選んで、一緒に新鮮な空気を楽しみましょう。', title_ko = '바깥 모험! 🌳', body_ko = '집 안에서 에너지를 다 쓰지 못하나요? 유모차로 편하게 걸을 수 있는 안전한 공원을 골라 함께 신선한 공기를 즐겨 보세요.', title_nl = 'Avontuur in de buitenlucht! 🌳', body_nl = 'Kan je kindje zijn energie binnen niet kwijt? Kies een veilig park waar je makkelijk met de kinderwagen kunt wandelen en geniet samen van de frisse lucht.', title_pl = 'Przygoda na świeżym powietrzu! 🌳', body_pl = 'Nie może wyładować energii w domu? Wybierz bezpieczny park, po którym wygodnie pospacerujecie z wózkiem, i razem cieszcie się świeżym powietrzem.', title_pt = 'Aventura ao ar livre! 🌳', body_pt = 'Em casa não consegue gastar energia? Escolha um parque seguro onde possa passear à vontade com o carrinho e aproveitem juntos o ar puro.', title_sv = 'Äventyr i friska luften! 🌳', body_sv = 'Kan barnet inte få ut energin inomhus? Välj en säker park där du lätt kan gå med barnvagnen och njut av den friska luften tillsammans.', title_vi = 'Phiêu lưu ngoài trời! 🌳', body_vi = 'Ở trong nhà bé không xả được năng lượng? Hãy chọn một công viên an toàn, dễ đẩy xe đẩy và cùng bé tận hưởng không khí trong lành.', title_zh = '户外探险！🌳', body_zh = '在家里释放不了精力？选一个适合推婴儿车散步的安全公园，一起享受新鲜空气吧。' WHERE id = '2cca6125-c540-4b9b-9a06-6121b60507e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja salir tus emociones 📝', body_es = 'No todos los días son fáciles y a veces todo se hace cuesta arriba. Escribe lo que sientes en el Diario de ánimo y suelta el estrés del día.', title_fr = 'Libérez vos émotions. 📝', body_fr = 'Tous les jours ne sont pas faciles, parfois c''est trop. Évacuez le stress de la journée en écrivant vos ressentis dans le Journal d''humeur.', title_hi = 'अपनी भावनाओं को बाहर आने दीजिए। 📝', body_hi = 'हर दिन आसान नहीं होता, कभी-कभी सब कुछ बहुत भारी लग सकता है। अपने मन की भावनाएँ मूड डायरी में लिखकर दिन का तनाव निकाल दीजिए।', title_id = 'Lepaskan emosi Anda. 📝', body_id = 'Tidak setiap hari terasa mudah, kadang semuanya terasa terlalu berat. Lepaskan stres hari ini dengan menuliskan perasaan Anda di Buku Harian Suasana Hati.', title_ja = '気持ちを解放しよう 📝', body_ja = '毎日が楽なわけではなく、何もかもが重く感じることもあります。「気分日記」に気持ちを書いて、一日のストレスを手放しましょう。', title_ko = '감정을 자유롭게 풀어 주세요. 📝', body_ko = '매일이 쉽지는 않아요. 가끔은 모든 게 버거울 수 있어요. 마음속 감정을 기분 일기에 적으며 하루의 스트레스를 덜어 내세요.', title_nl = 'Laat je gevoelens de vrije loop. 📝', body_nl = 'Niet elke dag is makkelijk, soms wordt alles even te veel. Schrijf je gevoelens op in je Stemmingsdagboek en laat de stress van de dag los.', title_pl = 'Daj upust emocjom. 📝', body_pl = 'Nie każdy dzień jest łatwy, czasem wszystkiego jest za dużo. Zapisz swoje uczucia w Dzienniku nastroju i zrzuć z siebie stres dnia.', title_pt = 'Dê liberdade às suas emoções. 📝', body_pt = 'Nem todos os dias são fáceis e às vezes tudo pode ser demasiado. Liberte o stress do dia escrevendo no Diário de Humor o que sente.', title_sv = 'Släpp ut dina känslor. 📝', body_sv = 'Alla dagar är inte lätta, ibland kan allt bli för mycket. Skriv dina känslor i Humördagboken och släpp dagens stress.', title_vi = 'Hãy để cảm xúc được tự do. 📝', body_vi = 'Không phải ngày nào cũng dễ dàng, đôi khi mọi thứ trở nên quá sức. Hãy viết những cảm xúc trong lòng vào Nhật ký tâm trạng để trút bỏ căng thẳng trong ngày.', title_zh = '释放你的情绪 📝', body_zh = '不是每天都轻松，有时候一切都会让人喘不过气。把心里的感受写进心情日记，卸下一天的压力。' WHERE id = '73b001a8-93ab-4798-bca3-094a519e468a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El final de un día perfecto ✨', body_es = 'Hoy también has hecho lo mejor que puede hacer una madre. Cierra los ojos y duérmete tranquila, orgullosa de ti misma.', title_fr = 'La fin d''une journée parfaite. ✨', body_fr = 'Aujourd''hui encore, vous avez fait tout ce qu''une maman peut faire de mieux. Fermez les yeux et endormez-vous sereinement, fière de vous.', title_hi = 'एक परफ़ेक्ट दिन का अंत। ✨', body_hi = 'आज भी आपने वह सब किया जो एक माँ सबसे अच्छा कर सकती है। आँखें बंद कीजिए और खुद पर गर्व करते हुए चैन की नींद सोइए।', title_id = 'Akhir hari yang sempurna. ✨', body_id = 'Hari ini pun Anda sudah melakukan yang terbaik yang bisa dilakukan seorang ibu. Pejamkan mata dan tidurlah dengan tenang, bangga pada diri sendiri.', title_ja = 'すてきな一日の終わり ✨', body_ja = '今日もママとしてできる最高のことをしました。目を閉じて、自分を誇りに思いながら、ゆっくり眠りにつきましょう。', title_ko = '완벽한 하루의 끝. ✨', body_ko = '오늘도 엄마로서 할 수 있는 최선을 다했어요. 눈을 감고, 스스로를 자랑스러워하며 편히 잠드세요.', title_nl = 'Het einde van een perfecte dag. ✨', body_nl = 'Ook vandaag deed je het beste wat een moeder kan doen. Sluit je ogen, wees trots op jezelf en val rustig in slaap.', title_pl = 'Idealny koniec dnia. ✨', body_pl = 'Dziś znów zrobiłaś wszystko, co najlepsze, co może zrobić mama. Zamknij oczy i zaśnij spokojnie, dumna z siebie.', title_pt = 'O fim de um dia perfeito. ✨', body_pt = 'Hoje voltou a fazer o melhor que uma mãe pode fazer. Feche os olhos e adormeça tranquila, orgulhosa de si.', title_sv = 'Slutet på en perfekt dag. ✨', body_sv = 'I dag gjorde du också det bästa en mamma kan göra. Blunda och somna gott, stolt över dig själv.', title_vi = 'Kết thúc một ngày trọn vẹn. ✨', body_vi = 'Hôm nay mẹ lại làm tốt nhất những gì một người mẹ có thể làm. Hãy nhắm mắt lại và chìm vào giấc ngủ bình yên trong niềm tự hào về bản thân.', title_zh = '完美一天的尾声 ✨', body_zh = '今天你也做到了一位妈妈能做的最好。闭上眼睛，带着对自己的骄傲安心入睡吧。' WHERE id = '80913e3b-4640-4efe-ae49-ce789db16fd1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pasos cada vez más seguros! 🏃‍♂', body_es = '️ Ya recorre la casa con libertad y a veces hasta intenta correr. ¡Sus valientes movimientos te llenan de orgullo y te mantienen siempre alerta!', title_fr = 'Des pas plus assurés ! 🏃‍♂', body_fr = '️ Il fait déjà librement le tour de la maison et essaie même parfois de courir. Ses mouvements audacieux vous rendent fière et vous gardent toujours sur le qui-vive !', title_hi = 'कदम ज़्यादा भरोसेमंद हैं! 🏃‍♂', body_hi = '️ अब वह खुलकर पूरे घर का चक्कर लगाता है और कभी-कभी दौड़ने की कोशिश भी करता है। उसकी ये हिम्मत भरी हरकतें आपको गर्व भी कराती हैं और हमेशा चौकन्ना भी रखती हैं!', title_id = 'Langkahnya makin mantap! 🏃‍♂', body_id = '️ Kini ia bebas berkeliling rumah, bahkan kadang mencoba berlari. Gerakan beraninya membuat Anda bangga, sekaligus selalu siaga!', title_ja = '足取りに自信がついてきた！🏃‍♂', body_ja = '️もう家の中を自由に歩き回り、ときには走ろうとすることも！その勇敢な動きは誇らしくもあり、いつも目が離せませんね！', title_ko = '걸음에 자신감이 붙었어요! 🏃‍♂', body_ko = '️이제 자유롭게 집 안을 누비고 가끔은 뛰려고까지 해요. 이 용감한 움직임이 뿌듯하면서도 늘 긴장하게 만들죠!', title_nl = 'Steeds zekerdere stapjes! 🏃‍♂', body_nl = '️ Je kindje maakt nu vrij zijn rondjes door het huis en probeert soms zelfs te rennen. Zijn dappere bewegingen maken je trots, maar houden je ook voortdurend alert!', title_pl = 'Coraz pewniejsze kroki! 🏃‍♂', body_pl = '️ Swobodnie zwiedza już cały dom, a czasem nawet próbuje biegać. Te odważne ruchy napawają cię dumą, ale też trzymają w ciągłej gotowości!', title_pt = 'Passos mais confiantes! 🏃‍♂', body_pt = '️ Já percorre a casa à vontade e às vezes até tenta correr. Estes movimentos corajosos enchem-na de orgulho e, ao mesmo tempo, mantêm-na sempre alerta!', title_sv = 'Stegen är säkrare! 🏃‍♂', body_sv = '️ Barnet tar sig redan fritt runt i hemmet och försöker ibland till och med springa. De modiga rörelserna gör dig både stolt och ständigt på helspänn!', title_vi = 'Những bước chân tự tin hơn! 🏃‍♂', body_vi = '️ Bé đã tự do đi khắp nhà và đôi khi còn thử chạy. Những bước đi táo bạo này vừa khiến mẹ tự hào, vừa khiến mẹ luôn phải cảnh giác!', title_zh = '步子更稳了！🏃‍♂', body_zh = '️ 宝宝已经能在家里自由转悠，有时甚至想跑。他这些大胆的动作，既让你骄傲，又让你时刻提心吊胆！' WHERE id = '8e332da4-937a-4f7f-af67-edbe9e325d0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Molestias de la dentición 🦷', title_fr = 'Les douleurs des dents 🦷', title_hi = 'दाँत निकलने का दर्द 🦷', title_id = 'Nyeri tumbuh gigi 🦷', title_ja = '歯が生えるときの痛み 🦷', title_ko = '이앓이 통증 🦷', title_nl = 'Pijn bij doorkomende tandjes 🦷', title_pl = 'Bóle ząbkowania 🦷', title_pt = 'As dores dos dentes 🦷', title_sv = 'Värk vid tandsprickning 🦷', title_vi = 'Đau khi mọc răng 🦷', title_zh = '出牙的疼痛 🦷' WHERE id = '0deab7a8-9a3b-4827-969f-f24303c70419' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El hábito de beber agua es importante 💧', body_es = 'Cuanto más se mueve, más sed tiene. No olvides ofrecerle agua mientras juega y después de las comidas.', title_fr = 'L''habitude de boire de l''eau compte. 💧', body_fr = 'Plus il bouge, plus il a soif. N''oubliez pas de lui proposer de l''eau pendant les jeux et après les repas.', title_hi = 'पानी पीने की आदत ज़रूरी है। 💧', body_hi = 'जितनी भाग-दौड़, उतनी प्यास। खेल के दौरान और खाने के बाद उसे पानी देना मत भूलिए।', title_id = 'Kebiasaan minum air itu penting. 💧', body_id = 'Makin aktif bergerak, makin cepat haus. Jangan lupa menawarinya air saat bermain dan setelah makan.', title_ja = 'お水を飲む習慣は大切です 💧', body_ja = '活発に動くほど、のどもよく渇きます。遊んでいるときや食事のあとに、お水をすすめるのを忘れずに。', title_ko = '물 마시는 습관이 중요해요. 💧', body_ko = '활발하게 움직일수록 목도 더 말라요. 놀이 중과 식사 후에 물을 권하는 걸 잊지 마세요.', title_nl = 'Water drinken is een belangrijke gewoonte. 💧', body_nl = 'Hoe actiever je kindje is, hoe meer dorst hij krijgt. Vergeet niet hem tijdens het spelen en na het eten water aan te bieden.', title_pl = 'Nawyk picia wody jest ważny. 💧', body_pl = 'Im więcej się rusza, tym bardziej chce mu się pić. Pamiętaj, by proponować mu wodę podczas zabawy i po posiłkach.', title_pt = 'O hábito de beber água é importante. 💧', body_pt = 'Quanto mais se mexe, mais sede tem. Não se esqueça de lhe oferecer água durante as brincadeiras e depois das refeições.', title_sv = 'Vanan att dricka vatten är viktig. 💧', body_sv = 'Ju mer aktivt barnet är, desto törstigare blir det. Glöm inte att erbjuda vatten under leken och efter måltiderna.', title_vi = 'Thói quen uống nước rất quan trọng. 💧', body_vi = 'Càng vận động nhiều, bé càng khát. Mẹ nhớ cho bé uống nước trong lúc chơi và sau bữa ăn nhé.', title_zh = '喝水习惯很重要 💧', body_zh = '活动越多越容易口渴。玩耍时和饭后，别忘了给宝宝喝点水。' WHERE id = '46166e0f-606a-46ff-86d4-07304bc93180' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Sus primeras obras de arte! 🖍', body_es = '️ Le encanta garabatear en el papel con ceras gruesas. Guarda sus primeras obras de arte para el futuro en la Sesión de fotos del bebé.', title_fr = 'Ses premières œuvres d''art ! 🖍', body_fr = '️ Il adore gribouiller sur du papier avec de gros crayons. Gardez ses premières œuvres pour plus tard dans la Séance photo bébé.', title_hi = 'पहली पेंटिंग! 🖍', body_hi = '️ उसे मोटे रंगों से कागज़ पर लकीरें खींचना बहुत पसंद है। उसकी पहली कलाकृतियों को बेबी फ़ोटोशूट सेक्शन में भविष्य के लिए सहेजिए।', title_id = 'Karya seni pertama! 🖍', body_id = '️ Ia sangat senang mencoret-coret kertas dengan krayon tebal. Simpan karya seni pertamanya untuk masa depan di bagian Sesi Foto Bayi.', title_ja = 'はじめての作品！🖍', body_ja = '️太いクレヨンで紙にお絵かきするのが大好き。はじめての作品を「ベビーフォトセッション」に保存して、将来の思い出にしましょう。', title_ko = '첫 그림 작품! 🖍', body_ko = '️굵은 크레용으로 종이에 끄적이는 걸 정말 좋아해요. 첫 작품들을 아기 사진 촬영 섹션에 남겨 두고 훗날 꺼내 보세요.', title_nl = 'De eerste kunstwerken! 🖍', body_nl = '️ Je kindje krast heel graag met dikke verf op papier. Bewaar zijn eerste kunstwerken voor later in het onderdeel Babyfotoshoot.', title_pl = 'Pierwsze dzieła sztuki! 🖍', body_pl = '️ Uwielbia bazgrać grubymi kredkami po papierze. Zachowaj jego pierwsze dzieła na przyszłość w sekcji Sesja zdjęciowa dziecka.', title_pt = 'As primeiras obras de arte! 🖍', body_pt = '️ Adora rabiscar no papel com lápis de cor grossos. Guarde as primeiras obras de arte dele para o futuro na Sessão Fotográfica do Bebé.', title_sv = 'De första konstverken! 🖍', body_sv = '️ Barnet älskar att klottra med tjocka kritor på papper. Spara de första konstverken för framtiden i avsnittet Babyfotografering.', title_vi = 'Những tác phẩm hội họa đầu tiên! 🖍', body_vi = '️ Bé rất thích vẽ nguệch ngoạc bằng bút màu to trên giấy. Hãy lưu giữ những tác phẩm nghệ thuật đầu tiên của bé trong mục Chụp ảnh cho bé để làm kỷ niệm.', title_zh = '第一批画作！🖍', body_zh = '️ 宝宝特别喜欢用粗蜡笔在纸上涂鸦。把他的第一批艺术作品保存在宝宝写真板块里，留给将来吧。' WHERE id = '9e232723-1401-4819-8b29-1e4636b3edc3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los juegos de imitación 🧸', body_es = '¿Intenta dar de comer o de beber a su osito? ¡Es la prueba más tierna de lo atentamente que te observa y te imita!', title_fr = 'Les jeux d''imitation commencent. 🧸', body_fr = 'Il essaie de nourrir son ours en peluche ou de lui donner à boire ? C''est la preuve la plus mignonne qu''il vous observe et vous imite attentivement !', title_hi = 'रोल-प्ले वाले खेल शुरू हो रहे हैं। 🧸', body_hi = 'अपने टेडी बेयर को खाना खिलाने या पानी पिलाने की कोशिश करता है? यह सबसे प्यारा सबूत है कि वह आपको कितने ध्यान से देखता और आपकी नकल करता है!', title_id = 'Permainan peran dimulai. 🧸', body_id = 'Ia mencoba menyuapi boneka beruangnya atau memberinya minum? Inilah bukti paling manis betapa saksama ia memperhatikan dan meniru Anda!', title_ja = 'ごっこ遊びが始まる 🧸', body_ja = 'くまのぬいぐるみにごはんを食べさせたり、お水をあげたりしていますか？あなたをよく見て、まねしている何よりかわいい証拠です！', title_ko = '역할 놀이가 시작돼요. 🧸', body_ko = '곰 인형에게 밥을 먹이거나 물을 주려 하나요? 엄마를 얼마나 유심히 보고 따라 하는지 보여 주는 가장 사랑스러운 증거예요!', title_nl = 'Rollenspel begint. 🧸', body_nl = 'Probeert je kindje zijn knuffelbeer te voeren of water te geven? Het liefste bewijs dat hij je aandachtig bekijkt en nadoet!', title_pl = 'Zaczynają się zabawy w udawanie. 🧸', body_pl = 'Próbuje nakarmić misia albo dać mu wody? To najsłodszy dowód na to, jak uważnie cię obserwuje i naśladuje!', title_pt = 'Começam os jogos de faz de conta. 🧸', body_pt = 'Tenta dar de comer ou de beber ao ursinho de peluche? É a prova mais doce de como a observa com atenção e a imita!', title_sv = 'Rollekarna börjar. 🧸', body_sv = 'Försöker barnet mata nallen eller ge den vatten? Det är det sötaste beviset på hur noga barnet följer och härmar dig!', title_vi = 'Bắt đầu trò chơi đóng vai. 🧸', body_vi = 'Bé cố cho gấu bông ăn hay cho gấu uống nước? Đây là bằng chứng đáng yêu nhất cho thấy bé quan sát và bắt chước mẹ kỹ đến thế nào!', title_zh = '角色扮演开始啦 🧸', body_zh = '宝宝想喂泰迪熊吃饭，或者给它喝水？这是他认真观察、模仿你的最可爱证明！' WHERE id = '2423bd81-d7d2-4b3e-b97a-32a10186bc3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cualquier pregunta que te preocupe, como «¿Es normal que mi hijo sea tan selectivo con la comida?», házsela a nuestro asistente Anacan AI incluso de madrugada.', body_fr = 'Posez toutes vos questions, comme « Est-ce normal que mon enfant trie ce qu''il mange ? », à notre assistant Anacan AI, même en pleine nuit.', body_hi = '''क्या मेरे बच्चे का खाने में नखरे करना सामान्य है?'' जैसा कोई भी सवाल जो आपको परेशान करे, रात में भी हमारे Anacan AI असिस्टेंट से पूछिए।', body_id = 'Tanyakan pertanyaan apa pun yang membuat Anda cemas, seperti "Normalkah anakku pilih-pilih makanan?", ke asisten Anacan AI kami, bahkan di malam hari.', body_ja = '「うちの子の好き嫌いは普通？」といった気になる質問は、夜中でもAnacan AIアシスタントに聞いてみましょう。', body_ko = '''아이가 음식을 가리는 게 정상일까?''처럼 걱정되는 질문은 늦은 밤에도 Anacan AI 도우미에게 물어보세요.', body_nl = 'Stel elke vraag die je bezighoudt, zoals: is het normaal dat mijn kind kieskeurig eet?, zelfs midden in de nacht aan onze assistent Anacan AI.', body_pl = 'Każde pytanie, które cię niepokoi, np. „Czy to normalne, że moje dziecko wybrzydza przy jedzeniu?”, zadaj naszemu asystentowi Anacan AI, nawet w nocy.', body_pt = 'Faça qualquer pergunta que a preocupe, como "É normal o meu filho escolher o que come?", ao nosso assistente Anacan AI, mesmo de madrugada.', body_sv = 'Ställ alla frågor som oroar dig, som ”Är det normalt att mitt barn är kräset?”, till vår assistent Anacan AI, även sent på natten.', body_vi = 'Mọi câu hỏi khiến mẹ lo lắng như "Con mình kén ăn có bình thường không?", ngay cả lúc nửa đêm mẹ cũng có thể hỏi trợ lý Anacan AI.', body_zh = '像“孩子挑食正常吗？”这样让你担心的任何问题，哪怕深夜也可以问我们的Anacan AI助手。' WHERE id = 'a589cdee-fd82-4fde-b44b-6b88fbe8e1cc' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se resiste a la siesta 😴', body_es = 'Jugar siempre es más atractivo que dormir. Si le cuesta dormirse, sigue el horario de los últimos días con el Temporizador de sueño de Anacan y ajusta su rutina.', title_fr = 'Il résiste à la sieste. 😴', body_fr = 'Jouer est toujours plus tentant que dormir. S''il a du mal à s''endormir, suivez le planning des derniers jours avec le minuteur de sommeil Anacan et ajustez son rythme.', title_hi = 'दिन की झपकी का विरोध। 😴', body_hi = 'खेलना हमेशा सोने से ज़्यादा लुभाता है। अगर उसे सोने में दिक्कत हो रही है, तो Anacan स्लीप टाइमर से पिछले दिनों का शेड्यूल देखकर रूटीन ढालिए।', title_id = 'Menolak tidur siang. 😴', body_id = 'Bermain selalu lebih menarik daripada tidur. Kalau ia sulit tertidur, pantau jadwal beberapa hari terakhir dengan Timer Tidur Anacan dan sesuaikan rutinitasnya.', title_ja = 'お昼寝を嫌がる 😴', body_ja = '寝るより遊ぶほうがいつだって魅力的。寝つきが悪いときは、Anacanの睡眠タイマーでここ数日のスケジュールを確認して、リズムを調整しましょう。', title_ko = '낮잠 거부. 😴', body_ko = '노는 건 언제나 자는 것보다 더 끌리죠. 잠들기 힘들어한다면 Anacan 수면 타이머로 최근 며칠의 일정을 살펴보고 일과를 맞춰 주세요.', title_nl = 'Verzet tegen het middagdutje. 😴', body_nl = 'Spelen is altijd aantrekkelijker dan slapen. Valt je kindje moeilijk in slaap? Volg het schema van de laatste dagen met de Slaaptimer van Anacan en pas zijn ritme aan.', title_pl = 'Opór przed drzemką. 😴', body_pl = 'Zabawa zawsze kusi bardziej niż sen. Jeśli trudno mu zasnąć, śledź timerem snu Anacan plan z ostatnich dni i dopasuj rytm dnia.', title_pt = 'Resistência à sesta. 😴', body_pt = 'Brincar é sempre mais apelativo do que dormir. Se tem dificuldade em adormecer, acompanhe o horário dos últimos dias com o temporizador de sono do Anacan e ajuste a rotina.', title_sv = 'Motstånd mot dagsluren. 😴', body_sv = 'Att leka är alltid mer lockande än att sova. Om barnet har svårt att somna, följ de senaste dagarnas schema med Anacans sömntimer och anpassa rutinen.', title_vi = 'Bé chống lại giấc ngủ ngày. 😴', body_vi = 'Chơi lúc nào cũng hấp dẫn hơn ngủ. Nếu bé khó vào giấc, hãy theo dõi biểu đồ những ngày gần đây bằng Bộ hẹn giờ ngủ của Anacan và điều chỉnh nếp sinh hoạt.', title_zh = '抗拒白天小睡 😴', body_zh = '玩总是比睡更有吸引力。如果入睡困难，用Anacan睡眠计时器看看最近几天的图表，调整一下作息吧。' WHERE id = 'd4f6586e-25f9-4dd3-9a6b-1408627d49eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Fuera el tiempo no está muy claro? ⛅', body_es = 'Deja que Tiempo y ropa te diga al momento la velocidad del viento que no se ve desde la ventana.', title_fr = 'Le temps est incertain dehors ? ⛅', body_fr = 'Laissez l''outil Météo et tenue vous indiquer tout de suite la vitesse du vent, invisible depuis la fenêtre.', title_hi = 'बाहर का मौसम साफ़ नहीं है? ⛅', body_hi = 'मौसम और कपड़े टूल तुरंत वह हवा की रफ़्तार बता देगा जो खिड़की से नहीं दिखती।', title_id = 'Cuaca di luar kurang jelas? ⛅', body_id = 'Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela.', title_ja = '外の天気がはっきりしない？⛅', body_ja = '窓からは見えない風の強さも、「天気と服装」がすぐに教えてくれます。', title_ko = '바깥 날씨가 애매한가요? ⛅', body_ko = '창밖으로는 보이지 않는 바람 세기를 날씨와 옷차림 도구가 바로 알려 줄 거예요.', title_nl = 'Is het weer buiten niet helemaal duidelijk? ⛅', body_nl = 'Laat de tool Weer en kleding je meteen de windsnelheid vertellen die je vanuit het raam niet ziet.', title_pl = 'Pogoda na dworze niepewna? ⛅', body_pl = 'Niech narzędzie Pogoda i ubiór od razu poda ci prędkość wiatru, której nie widać przez okno.', title_pt = 'O tempo lá fora não está bem limpo? ⛅', body_pt = 'Deixe que o Tempo e Roupa lhe diga na hora a velocidade do vento que não se vê da janela.', title_sv = 'Är vädret ute inte helt klart? ⛅', body_sv = 'Låt verktyget Väder och kläder direkt berätta vindhastigheten som du inte ser genom fönstret.', title_vi = 'Thời tiết bên ngoài không rõ ràng? ⛅', body_vi = 'Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được.', title_zh = '外面天气说不准？⛅', body_zh = '让天气穿衣工具马上告诉你窗外看不出来的风速。' WHERE id = '13b16a71-31e8-44cf-bbf4-b97f55c8f45e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crea en Cuentos inteligentes una historia especial protagonizada por tu peque: «El niño valiente que trepó hasta las estrellas».', body_fr = 'Dans les Contes intelligents, créez une histoire unique dont votre enfant est le héros : « L''enfant courageux qui grimpa jusqu''aux étoiles ».', body_hi = 'स्मार्ट कहानियों में ऐसी खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: ''तारों तक चढ़ने वाला बहादुर बच्चा''।', body_id = 'Di Dongeng Pintar, buat kisah istimewa dengan si kecil sebagai pahlawannya: Anak Pemberani yang Memanjat ke Bintang.', body_ja = '「スマートおはなし」で、お子さんが主人公の特別なお話「星までのぼった勇敢な子」をつくりましょう。', body_ko = '스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: 별을 향해 기어오르는 용감한 아이.', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: Het dappere kind dat naar de sterren klom.', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Odważne dziecko, które wspięło się do gwiazd”.', body_pt = 'Crie nas Histórias Inteligentes uma história especial em que o herói é o seu filho: "A criança corajosa que subiu até às estrelas".', body_sv = 'Skapa en speciell berättelse i Smarta sagor där ditt barn är hjälten: Det modiga barnet som klättrade upp till stjärnorna.', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo một câu chuyện đặc biệt với nhân vật chính là chính con mình: "Em bé dũng cảm leo lên những vì sao".', body_zh = '在智能故事里创作一个以你的孩子为主角的专属故事：《爬上星星的勇敢孩子》。' WHERE id = '807a2e9f-2fb3-4378-94cf-0ad756854f25' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juntos en la cocina 🥦', body_es = 'Mientras cocinas, dale un recipiente de plástico irrompible y una cuchara de madera para que él también prepare su comida.', title_fr = 'Ensemble en cuisine. 🥦', body_fr = 'Pendant que vous cuisinez, donnez-lui un bol en plastique incassable et une cuillère en bois, et laissez-le préparer son propre repas.', title_hi = 'साथ में रसोई में। 🥦', body_hi = 'खाना बनाते समय उसे न टूटने वाला प्लास्टिक का बर्तन और लकड़ी का चम्मच दीजिए, ताकि वह भी अपना खाना बनाए।', title_id = 'Bersama di dapur. 🥦', body_id = 'Saat memasak, berikan wadah plastik yang tidak mudah pecah dan sendok kayu, biarkan ia juga "memasak" makanannya sendiri.', title_ja = 'キッチンで一緒に 🥦', body_ja = '料理をするときは、割れないプラスチックのボウルと木のスプーンを渡して、お子さんにも自分のごはんを「つくって」もらいましょう。', title_ko = '함께 부엌에서. 🥦', body_ko = '요리할 때 깨지지 않는 플라스틱 그릇과 나무 숟가락을 건네 아이도 자기 요리를 하게 해 주세요.', title_nl = 'Samen in de keuken. 🥦', body_nl = 'Geef je kindje tijdens het koken een onbreekbare plastic kom en een houten lepel, dan kan hij ook zijn eigen eten maken.', title_pl = 'Razem w kuchni. 🥦', body_pl = 'Gdy gotujesz, daj mu plastikową miskę, która się nie stłucze, i drewnianą łyżkę. Niech on też przygotuje swoje danie.', title_pt = 'Juntos na cozinha. 🥦', body_pt = 'Enquanto prepara a comida, dê-lhe uma taça de plástico que não se parta e uma colher de pau, e deixe-o preparar também a sua refeição.', title_sv = 'Tillsammans i köket. 🥦', body_sv = 'Ge barnet en plastskål som inte går sönder och en träslev när du lagar mat, så får det också laga sin egen mat.', title_vi = 'Cùng nhau vào bếp. 🥦', body_vi = 'Khi nấu ăn, hãy đưa cho bé một chiếc bát nhựa không vỡ và một chiếc thìa gỗ để bé cũng "nấu" món của mình.', title_zh = '一起进厨房 🥦', body_zh = '做饭时给他一个摔不坏的塑料碗和一把木勺，让他也“做”自己的饭吧。' WHERE id = '25f37869-be99-4918-83ae-dd5fecd2f5ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Organizarse da tranquilidad 📝', body_es = 'Repasa con unas notas rápidas lo que harás mañana o el menú, y vete a la cama más tranquila.', title_fr = 'S''organiser, ça détend. 📝', body_fr = 'Préparez dans votre tête, avec quelques petites notes, vos tâches ou le menu de demain, puis allez vous coucher l''esprit reposé.', title_hi = 'योजना से सुकून मिलता है। 📝', body_hi = 'कल के कामों या खाने की योजना छोटे-छोटे नोट्स के साथ मन में तैयार कीजिए और सुकून से सोने जाइए।', title_id = 'Punya rencana bikin tenang. 📝', body_id = 'Siapkan dalam pikiran rencana kegiatan atau menu besok dengan beberapa catatan kecil, lalu pergilah tidur dengan perasaan tenang.', title_ja = '計画があると安心 📝', body_ja = '明日やることや献立を、小さなメモで頭の中に準備してから、すっきりした気持ちでベッドに入りましょう。', title_ko = '계획이 있으면 마음이 편해요. 📝', body_ko = '내일 할 일이나 식단 계획을 간단히 머릿속에 정리해 두고 편안한 마음으로 잠자리에 드세요.', title_nl = 'Een planning geeft rust. 📝', body_nl = 'Zet de taken of het eetplan voor morgen met een paar korte notities op een rijtje in je hoofd en ga uitgerust naar bed.', title_pl = 'Planowanie daje spokój. 📝', body_pl = 'Przygotuj w głowie z kilkoma krótkimi notatkami plan na jutro lub jadłospis i idź spać odprężona.', title_pt = 'Planear traz tranquilidade. 📝', body_pt = 'Prepare de cabeça, com pequenas notas, as tarefas ou o plano de refeições de amanhã e vá para a cama já descansada.', title_sv = 'Att planera ger ro. 📝', body_sv = 'Förbered morgondagens sysslor eller matplan med små anteckningar i huvudet och gå utvilad till sängs.', title_vi = 'Có kế hoạch giúp mẹ nhẹ nhõm. 📝', body_vi = 'Hãy chuẩn bị trong đầu những việc cần làm hay thực đơn ngày mai bằng vài ghi chú nhỏ, rồi lên giường thật thư thái.', title_zh = '有计划更安心 📝', body_zh = '在脑子里简单列好明天要做的事或饮食安排，然后安心上床休息吧。' WHERE id = 'c0b75b28-86cb-44ea-8bc4-de62c31fae30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo señala todo con el dedo ☝', body_es = '️ Es la versión silenciosa de «¿Qué es esto?». Para mantener viva su curiosidad, repite con paciencia el nombre de todo lo que señale.', title_fr = 'Il montre tout du doigt. ☝', body_fr = '️ C''est la version silencieuse de « C''est quoi ? ». Pour garder sa curiosité en éveil, répétez patiemment le nom de tout ce qu''il montre.', title_hi = 'हर चीज़ की ओर उँगली दिखाता है। ☝', body_hi = '️ यह ''यह क्या है?'' सवाल का बिना बोले वाला रूप है। उसकी जिज्ञासा बनाए रखने के लिए जो भी वह दिखाए, उसका नाम धैर्य से दोहराइए।', title_id = 'Ia menunjuk segala hal dengan jarinya. ☝', body_id = '️ Ini adalah versi tanpa suara dari pertanyaan "Ini apa?". Agar rasa ingin tahunya tetap hidup, ulangi dengan sabar nama setiap benda yang ia tunjuk.', title_ja = 'なんでも指さします ☝', body_ja = '️「これなあに？」の声のないバージョンです。好奇心が続くよう、指さしたものの名前を根気よく繰り返してあげましょう。', title_ko = '모든 걸 손가락으로 가리켜요. ☝', body_ko = '️"이게 뭐야?"의 말 없는 버전이에요. 호기심이 계속 살아 있도록 가리키는 모든 것의 이름을 인내심을 갖고 반복해 주세요.', title_nl = 'Wijst alles aan met zijn vingertje. ☝', body_nl = '️ Dat is de stille versie van de vraag: wat is dat? Herhaal geduldig de naam van alles wat hij aanwijst, zo blijft zijn nieuwsgierigheid levend.', title_pl = 'Pokazuje wszystko paluszkiem. ☝', body_pl = '️ To cicha wersja pytania „Co to jest?”. By podtrzymać jego ciekawość, cierpliwie powtarzaj nazwę wszystkiego, co pokazuje.', title_pt = 'Aponta tudo com o dedo. ☝', body_pt = '️ É a versão silenciosa da pergunta "O que é isto?". Para manter viva a curiosidade dele, repita com paciência o nome de tudo o que aponta.', title_sv = 'Pekar på allt med fingret. ☝', body_sv = '️ Det är den tysta versionen av frågan ”Vad är det?”. Upprepa med tålamod namnet på allt barnet pekar på för att hålla nyfikenheten vid liv.', title_vi = 'Bé chỉ tay vào mọi thứ. ☝', body_vi = '️ Đây là phiên bản không lời của câu hỏi "Cái gì đây?". Để giữ sự tò mò của bé, hãy kiên nhẫn nhắc lại tên của mọi thứ bé chỉ.', title_zh = '什么都用手指指 ☝', body_zh = '️ 这是无声版的“这是什么？”。为了保持他的好奇心，耐心地重复说出他指的每样东西的名字吧。' WHERE id = 'e47ea433-71bf-4c11-8e6e-6edbaec03292' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Necesitas información sobre los saltos de desarrollo de los 15 meses? Echa un vistazo al Calendario de crisis.', body_fr = 'Besoin d''informations sur les pics de développement à 15 mois ? Jetez un œil au Calendrier des pics de développement.', body_hi = '15 महीने की विकास की छलांगों के बारे में जानकारी चाहिए? क्राइसिस कैलेंडर देखिए।', body_id = 'Butuh informasi tentang lompatan perkembangan usia 15 bulan? Lihat Kalender Krisis.', body_ja = '1歳3か月ごろの発達の節目について知りたいですか？「ぐずり期カレンダー」をのぞいてみましょう。', body_ko = '15개월 발달 도약에 대한 정보가 필요한가요? 발달 위기 달력을 살펴보세요.', body_nl = 'Wil je meer weten over de ontwikkelingssprongen rond 15 maanden? Kijk in de Sprongenkalender.', body_pl = 'Potrzebujesz informacji o skokach rozwojowych w 15. miesiącu? Zajrzyj do Kalendarza skoków rozwojowych.', body_pt = 'Precisa de informação sobre os saltos de desenvolvimento aos 15 meses? Espreite o Calendário de Crises.', body_sv = 'Behöver du information om utvecklingssprången vid 15 månader? Titta i Kriskalendern.', body_vi = 'Mẹ cần thông tin về các bước nhảy phát triển ở tháng 15? Hãy xem Lịch tuần khủng hoảng.', body_zh = '想了解15个月的发育飞跃？看看飞跃期日历吧。' WHERE id = '30d6fd90-986c-491d-9a4a-39c6c9f48f69' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de leer 📖', body_es = 'Pasar las páginas de libros ilustrados y escucharte leer es ideal para su vocabulario. Leed juntos cada día, aunque sean 10 minutos.', title_fr = 'Le goût des livres. 📖', body_fr = 'Tourner les pages des livres d''images et vous écouter lire, c''est parfait pour son vocabulaire. Lisez ensemble chaque jour, ne serait-ce que 10 minutes.', title_hi = 'किताबें पढ़ने का शौक। 📖', body_hi = 'तस्वीरों वाली किताबों के पन्ने पलटना और आपको पढ़ते सुनना शब्द भंडार के लिए बढ़िया तरीका है। हर दिन 10 मिनट ही सही, साथ में किताब पढ़िए।', title_id = 'Semangat membaca buku. 📖', body_id = 'Membalik halaman buku bergambar dan mendengarkan Anda membaca adalah cara sempurna untuk menambah kosakata. Bacalah buku bersama setiap hari, meski hanya 10 menit.', title_ja = '本が好きになる 📖', body_ja = '絵本のページをめくり、あなたの読む声を聞くことは、語彙を育てる最高の方法です。1日10分でも、一緒に絵本を読みましょう。', title_ko = '책 읽기의 즐거움. 📖', body_ko = '그림책 책장을 넘기며 엄마가 읽어 주는 소리를 듣는 건 어휘를 늘리는 완벽한 방법이에요. 하루 10분이라도 함께 책을 읽어 보세요.', title_nl = 'Zin in boeken. 📖', body_nl = 'Bladzijden van prentenboeken omslaan en naar jou luisteren als je voorleest, is perfect voor zijn woordenschat. Lees elke dag samen, al is het maar 10 minuten.', title_pl = 'Zamiłowanie do książek. 📖', body_pl = 'Przewracanie kartek książeczek z obrazkami i słuchanie, jak czytasz, to świetny sposób na wzbogacanie zasobu słów. Czytajcie razem codziennie, choćby 10 minut.', title_pt = 'O gosto pelos livros. 📖', body_pt = 'Virar as páginas de livros com imagens e ouvi-la ler é uma forma perfeita de enriquecer o vocabulário. Leiam juntos todos os dias, nem que sejam 10 minutos.', title_sv = 'Lust att läsa böcker. 📖', body_sv = 'Att vända sidorna i bilderböcker och lyssna när du läser är perfekt för ordförrådet. Läs tillsammans varje dag, även om det bara blir 10 minuter.', title_vi = 'Niềm yêu thích đọc sách. 📖', body_vi = 'Lật trang sách tranh và nghe mẹ đọc là cách tuyệt vời để tăng vốn từ. Hãy cùng bé đọc sách mỗi ngày, dù chỉ 10 phút.', title_zh = '爱上读书 📖', body_zh = '翻图画书、听你朗读，是积累词汇的绝佳方式。每天哪怕只读10分钟，也要一起读书哦。' WHERE id = '661b0ef0-cce8-4702-8d5a-2f90901198ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rutina de la noche 😴', body_es = 'Un baño templado y un pijama limpio le relajarán y le prepararán perfectamente para dormir.', title_fr = 'Le rituel du soir. 😴', body_fr = 'Un bain tiède et un pyjama propre le détendront et le prépareront parfaitement au sommeil.', title_hi = 'रात का रूटीन। 😴', body_hi = 'गुनगुना स्नान और साफ़ पजामा उसे आराम देकर नींद के लिए पूरी तरह तैयार करेंगे।', title_id = 'Rutinitas malam. 😴', body_id = 'Mandi air hangat dan piyama bersih akan membuatnya rileks dan siap tidur.', title_ja = '夜の習慣 😴', body_ja = 'ぬるめのお風呂と清潔なパジャマで、リラックスして眠りへの準備がばっちり整います。', title_ko = '밤 루틴. 😴', body_ko = '따뜻한 목욕과 깨끗한 잠옷이 몸을 편안하게 해 잠들 준비를 완벽하게 해 줄 거예요.', title_nl = 'Avondroutine. 😴', body_nl = 'Een lauw badje en een schone pyjama maken je kindje rustig en perfect klaar om te slapen.', title_pl = 'Wieczorna rutyna. 😴', body_pl = 'Ciepła kąpiel i czysta piżamka rozluźnią go i idealnie przygotują do snu.', title_pt = 'A rotina da noite. 😴', body_pt = 'Um banho morno e um pijama lavado vão relaxá-lo e prepará-lo na perfeição para dormir.', title_sv = 'Kvällsrutin. 😴', body_sv = 'Ett ljummet bad och rena pyjamas får barnet att slappna av och förbereder det perfekt för sömnen.', title_vi = 'Nếp ngủ buổi tối. 😴', body_vi = 'Tắm nước ấm và bộ đồ ngủ sạch sẽ sẽ giúp bé thư giãn và sẵn sàng cho giấc ngủ.', title_zh = '睡前程序 😴', body_zh = '温水澡和干净的睡衣会让宝宝放松下来，为入睡做好充分准备。' WHERE id = '553f302d-8ba0-44d9-9d9d-e356d494f003' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de independencia 🥣', body_es = 'Cuando quiera sujetar su plato o su cuchara, dale la oportunidad. El desorden es la parte más bonita del aprendizaje.', title_fr = 'En quête d''autonomie. 🥣', body_fr = 'Quand il veut tenir son bol ou sa cuillère tout seul, laissez-le faire. Le désordre est la plus belle partie de l''apprentissage.', title_hi = 'आत्मनिर्भरता की तलाश में। 🥣', body_hi = 'जब वह अपनी कटोरी या चम्मच खुद पकड़ना चाहे, तो उसे मौका दीजिए। बिखराव सीखने का सबसे खूबसूरत हिस्सा है।', title_id = 'Mencari kemandirian. 🥣', body_id = 'Saat ia ingin memegang mangkuk atau sendoknya sendiri, beri ia kesempatan. Berantakan adalah bagian terindah dari belajar.', title_ja = '自分でやりたい 🥣', body_ja = 'お皿やスプーンを自分で持ちたがったら、やらせてあげましょう。散らかるのは、学びのいちばんすてきな部分です。', title_ko = '독립을 찾아서. 🥣', body_ko = '그릇이나 숟가락을 직접 잡고 싶어 하면 기회를 주세요. 어질러지는 것도 배움의 가장 멋진 부분이에요.', title_nl = 'Op zoek naar zelfstandigheid. 🥣', body_nl = 'Wil je kindje zelf zijn bord of lepel vasthouden? Geef hem de kans. Rommel is het mooiste deel van het leren.', title_pl = 'W poszukiwaniu samodzielności. 🥣', body_pl = 'Gdy chce sam trzymać miseczkę lub łyżeczkę, daj mu szansę. Bałagan to najpiękniejsza część nauki.', title_pt = 'Em busca de independência. 🥣', body_pt = 'Quando quiser segurar sozinho a taça ou a colher, dê-lhe essa oportunidade. A desarrumação é a parte mais bonita da aprendizagem.', title_sv = 'På jakt efter självständighet. 🥣', body_sv = 'Ge barnet chansen när det vill hålla skålen eller skeden själv. Stöket är den finaste delen av lärandet.', title_vi = 'Đi tìm sự tự lập. 🥣', body_vi = 'Khi bé muốn tự cầm bát hay thìa, hãy cho bé cơ hội. Bừa bộn là phần đẹp nhất của việc học.', title_zh = '追求独立 🥣', body_zh = '宝宝想自己拿碗或勺子时，就给他机会。弄得乱七八糟，正是学习中最美好的部分。' WHERE id = 'ed9814d4-d919-40b0-833b-d118d90c1727' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas energía 🥗', body_es = 'Te pasas el día de pie. Prepara en Recetas saludables para mujeres un tentempié delicioso que te devuelva la energía.', title_fr = 'Vous aussi avez besoin d''énergie. 🥗', body_fr = 'Vous êtes debout toute la journée. Préparez un en-cas savoureux des Recettes saines pour femmes pour refaire le plein d''énergie.', title_hi = 'आपको भी ऊर्जा चाहिए। 🥗', body_hi = 'आप पूरे दिन खड़ी रहती हैं। महिलाओं के लिए सेहतमंद रेसिपी से ऊर्जा लौटाने वाला कोई स्वादिष्ट स्नैक बनाइए।', title_id = 'Anda juga butuh energi. 🥗', body_id = 'Seharian Anda terus berdiri. Siapkan camilan lezat dari Resep Sehat untuk wanita yang akan memulihkan energi Anda.', title_ja = 'あなたにもエネルギーが必要です 🥗', body_ja = '一日中立ちっぱなしですね。「女性のためのヘルシーレシピ」から、元気を取り戻せるおいしいおやつをつくりましょう。', title_ko = '엄마에게도 에너지가 필요해요. 🥗', body_ko = '하루 종일 서 있었죠. 건강한 레시피에서 기운을 되찾아 줄 맛있는 간식을 만들어 보세요.', title_nl = 'Ook jij hebt energie nodig. 🥗', body_nl = 'Je staat de hele dag op je benen. Maak uit Gezonde recepten voor vrouwen een lekker tussendoortje dat je energie teruggeeft.', title_pl = 'Ty też potrzebujesz energii. 🥗', body_pl = 'Cały dzień jesteś na nogach. Przygotuj ze Zdrowych przepisów dla kobiet smaczną przekąskę, która przywróci ci energię.', title_pt = 'Também precisa de energia. 🥗', body_pt = 'Passa o dia todo de pé. Prepare nas Receitas Saudáveis para Mulheres um lanche delicioso que lhe devolva a energia.', title_sv = 'Du behöver också energi. 🥗', body_sv = 'Du är på benen hela dagen. Gör ett gott mellanmål från Hälsosamma recept för kvinnor som fyller på energin.', title_vi = 'Mẹ cũng cần năng lượng. 🥗', body_vi = 'Cả ngày mẹ đứng không ngơi chân. Hãy làm một món ăn nhẹ ngon miệng từ Công thức lành mạnh cho phụ nữ để lấy lại năng lượng.', title_zh = '你也需要能量 🥗', body_zh = '你站了一整天。从女性健康食谱里做一份美味的小点心，帮自己恢复能量吧。' WHERE id = '4e2f3772-b7ad-4946-a8a3-70f3ebef0c4e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Descubrimientos a toda velocidad! 🏃‍♂', body_es = '️ Ya va con seguridad de una habitación a otra y lo quiere tocar todo. Asegúrate de que la casa es segura y disfruta de esta etapa tan activa.', title_fr = 'Des découvertes à toute vitesse ! 🏃‍♂', body_fr = '️ Il circule déjà avec assurance d''une pièce à l''autre et veut tout toucher. Assurez-vous que la maison est sécurisée et profitez de cette belle énergie.', title_hi = 'तेज़ खोजें! 🏃‍♂', body_hi = '️ अब वह कमरों के बीच भरोसे से चलता है और हर चीज़ छूना चाहता है। पक्का कीजिए कि घर सुरक्षित है, और इस चुलबुलेपन का आनंद लीजिए।', title_id = 'Penjelajahan cepat! 🏃‍♂', body_id = '️ Kini ia berjalan dengan percaya diri dari kamar ke kamar dan ingin menyentuh segalanya. Pastikan rumah aman dan nikmati masa aktif ini.', title_ja = 'どんどん発見！🏃‍♂', body_ja = '️もう自信をもって部屋から部屋へ歩き、なんでもさわりたがります。家の安全を確認して、この活発な時期を楽しみましょう。', title_ko = '빠른 탐험! 🏃‍♂', body_ko = '️이제 방과 방 사이를 자신 있게 걸어 다니며 모든 걸 만지고 싶어 해요. 집 안이 안전한지 확인하고 이 활발함을 즐겨 보세요.', title_nl = 'Snelle ontdekkingen! 🏃‍♂', body_nl = '️ Je kindje loopt nu vol zelfvertrouwen van kamer naar kamer en wil alles aanraken. Zorg dat je huis veilig is en geniet van deze actieve fase.', title_pl = 'Szybkie odkrycia! 🏃‍♂', body_pl = '️ Pewnie chodzi już między pokojami i chce wszystkiego dotknąć. Upewnij się, że dom jest bezpieczny, i ciesz się tą aktywnością.', title_pt = 'Descobertas a alta velocidade! 🏃‍♂', body_pt = '️ Já anda com confiança de uma divisão para outra e quer tocar em tudo. Confirme que a casa é segura e aproveite esta fase tão ativa.', title_sv = 'Snabba upptäckter! 🏃‍♂', body_sv = '️ Barnet går nu säkert mellan rummen och vill röra vid allt. Se till att hemmet är säkert och njut av den här aktiva tiden.', title_vi = 'Những khám phá thần tốc! 🏃‍♂', body_vi = '️ Bé đã tự tin đi lại giữa các phòng và muốn chạm vào mọi thứ. Hãy đảm bảo nhà cửa an toàn và tận hưởng giai đoạn hiếu động này.', title_zh = '飞快的探索！🏃‍♂', body_zh = '️ 宝宝已经能自信地在房间之间走来走去，什么都想摸一摸。确保家里安全，享受这份活力吧。' WHERE id = '6df61827-7605-47d2-aeef-a4e811b4d8c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahogo emocional 📝', body_es = 'Después de un día agotador, escribe cómo te sientes en el Diario de ánimo y suelta el estrés. ¡Eres una madre estupenda!', title_fr = 'Lâcher prise. 📝', body_fr = 'Après une journée épuisante, évacuez le stress en écrivant vos ressentis dans le Journal d''humeur. Vous êtes une maman formidable !', title_hi = 'मन का बोझ हल्का करना। 📝', body_hi = 'थकाने वाले दिन के बाद अपनी भावनाएँ मूड डायरी में लिखकर दिन का तनाव निकाल दीजिए। आप एक शानदार माँ हैं!', title_id = 'Melepaskan emosi. 📝', body_id = 'Setelah hari yang melelahkan, lepaskan stres dengan menuliskan perasaan Anda di Buku Harian Suasana Hati. Anda ibu yang hebat!', title_ja = '気持ちを吐き出そう 📝', body_ja = '疲れた一日のあとは、「気分日記」に気持ちを書いて、ストレスを手放しましょう。あなたはすばらしいママです！', title_ko = '감정을 털어놓기. 📝', body_ko = '고된 하루를 보낸 뒤 기분 일기에 감정을 적으며 하루의 스트레스를 덜어 내세요. 당신은 훌륭한 엄마예요!', title_nl = 'Je gevoelens loslaten. 📝', body_nl = 'Schrijf na een vermoeiende dag je gevoelens op in je Stemmingsdagboek en laat de stress van de dag los. Je bent een geweldige mama!', title_pl = 'Emocjonalne odreagowanie. 📝', body_pl = 'Po męczącym dniu zapisz swoje uczucia w Dzienniku nastroju i zrzuć z siebie stres dnia. Jesteś wspaniałą mamą!', title_pt = 'Desabafo emocional. 📝', body_pt = 'Depois de um dia cansativo, liberte o stress escrevendo o que sente no Diário de Humor. É uma mãe fantástica!', title_sv = 'Känslomässig urladdning. 📝', body_sv = 'Släpp dagens stress efter en tröttsam dag genom att skriva dina känslor i Humördagboken. Du är en fantastisk mamma!', title_vi = 'Giải tỏa cảm xúc. 📝', body_vi = 'Sau một ngày mệt mỏi, hãy viết cảm xúc vào Nhật ký tâm trạng để trút bỏ căng thẳng. Mẹ là một người mẹ tuyệt vời!', title_zh = '释放情绪 📝', body_zh = '累了一天之后，把感受写进心情日记，卸下一天的压力。你是很棒的妈妈！' WHERE id = 'c9b2a6a2-258b-4f8c-96f9-86282d8d8145' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres una heroína! ✨', body_es = 'El amor y los cuidados que has dado durante 450 días no tienen precio. Ahora recuéstate y, tras este día tan bonito, duérmete tranquila.', title_fr = 'Vous êtes une héroïne ! ✨', body_fr = 'L''amour et les soins que vous avez donnés pendant ces 450 jours n''ont pas de prix. Maintenant, installez-vous confortablement et endormez-vous sereinement après cette belle journée.', title_hi = 'आप हीरो हैं! ✨', body_hi = '450 दिनों में आपका दिखाया प्यार और देखभाल अनमोल है। अब पीछे टिककर बैठिए और इस खूबसूरत दिन के बाद चैन की नींद सोइए।', title_id = 'Anda pahlawan! ✨', body_id = 'Cinta dan perhatian yang Anda berikan selama 450 hari ini tak ternilai. Sekarang bersandarlah dan tidurlah dengan tenang setelah hari yang indah ini.', title_ja = 'あなたはヒーローです！✨', body_ja = 'この450日間にあなたが注いできた愛情とケアは、何ものにも代えられません。さあ、背もたれに寄りかかって、このすてきな一日のあとはゆっくり眠りましょう。', title_ko = '엄마는 영웅이에요! ✨', body_ko = '450일 동안 보여 준 사랑과 보살핌은 그 무엇과도 바꿀 수 없어요. 이제 편히 기대어 이 멋진 하루를 마무리하며 조용히 잠드세요.', title_nl = 'Je bent een held! ✨', body_nl = 'De liefde en zorg die je in 450 dagen hebt gegeven, zijn onbetaalbaar. Leun nu achterover en val na deze mooie dag rustig in slaap.', title_pl = 'Jesteś bohaterką! ✨', body_pl = 'Miłość i troska, które okazujesz od 450 dni, są bezcenne. Teraz odchyl się i po tym pięknym dniu spokojnie zaśnij.', title_pt = 'É uma heroína! ✨', body_pt = 'O amor e o cuidado que mostrou ao longo de 450 dias não têm preço. Agora recoste-se e, depois deste dia tão bonito, adormeça tranquila.', title_sv = 'Du är en hjälte! ✨', body_sv = 'Kärleken och omsorgen du har visat under 450 dagar är ovärderlig. Luta dig nu tillbaka och somna lugnt efter denna fina dag.', title_vi = 'Mẹ là người hùng! ✨', body_vi = 'Tình yêu và sự chăm sóc mẹ dành cho bé suốt 450 ngày qua là vô giá. Giờ hãy ngả lưng và chìm vào giấc ngủ bình yên sau một ngày tươi đẹp.', title_zh = '你是英雄！✨', body_zh = '这450天里你付出的爱与关怀无可替代。现在往后靠一靠，在这美好的一天之后安静入睡吧。' WHERE id = '14e2b559-f6b1-4ffb-ba5f-0e5d6eeca267' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maratón de habitación en habitación 🏃‍♂️', body_es = '¡Ya no solo camina, casi corre! Su equilibrio mejora día a día. Registra con orgullo esta etapa tan movida en el Seguimiento del desarrollo.', title_fr = 'Marathon de pièce en pièce 🏃‍♂️', body_fr = 'Il ne se contente plus de marcher, il court presque ! Son équilibre se renforce de jour en jour. Notez fièrement cette période pleine de mouvement dans le Suivi de développement.', title_hi = 'कमरों के बीच मैराथन 🏃‍♂️', body_hi = 'अब वह बस चलता नहीं, लगभग दौड़ता है! उसका संतुलन दिन-ब-दिन मज़बूत हो रहा है। ग्रोथ ट्रैकर में इस चुलबुले दौर को गर्व से दर्ज कीजिए।', title_id = 'Maraton antarkamar 🏃‍♂️', body_id = 'Kini ia tidak hanya berjalan, tapi hampir berlari! Keseimbangannya makin kuat dari hari ke hari. Catat masa aktif ini dengan bangga di Pelacak Perkembangan.', title_ja = '部屋から部屋へマラソン 🏃‍♂️', body_ja = 'もう歩くだけでなく、ほとんど走っています！バランスも日に日に安定してきました。「発達トラッカー」にこの活発な時期を誇らしく記録しましょう。', title_ko = '방에서 방으로 마라톤 🏃‍♂️', body_ko = '이제 그냥 걷는 게 아니라 거의 뛰어요! 균형 감각이 날마다 튼튼해지고 있어요. 성장 기록에 이 활발한 시기를 뿌듯하게 남기세요.', title_nl = 'Marathon door de kamers 🏃‍♂️', body_nl = 'Je kindje loopt niet meer alleen, hij rent bijna! Zijn evenwicht wordt elke dag beter. Noteer deze actieve fase trots in de Groeitracker.', title_pl = 'Maraton między pokojami 🏃‍♂️', body_pl = 'Już nie tylko chodzi, prawie biega! Jego równowaga z dnia na dzień jest coraz lepsza. Zapisz z dumą ten ruchliwy etap w Śledzeniu rozwoju.', title_pt = 'Maratona entre divisões 🏃‍♂️', body_pt = 'Já não se limita a andar, quase corre! O equilíbrio fica mais forte de dia para dia. Registe com orgulho esta fase agitada no Registo de Desenvolvimento.', title_sv = 'Maraton mellan rummen 🏃‍♂️', body_sv = 'Barnet går inte bara längre, det springer nästan! Balansen blir starkare för varje dag. Anteckna denna livliga period med stolthet i Utvecklingsspåraren.', title_vi = 'Chạy marathon giữa các phòng 🏃‍♂️', body_vi = 'Bé không chỉ đi nữa mà gần như đang chạy! Khả năng giữ thăng bằng mạnh lên từng ngày. Hãy tự hào ghi lại giai đoạn hiếu động này trong Theo dõi phát triển.', title_zh = '房间之间的马拉松 🏃‍♂️', body_zh = '宝宝已经不只是走，简直是在跑了！平衡能力一天比一天强。在发育追踪里自豪地记下这个活力满满的阶段吧。' WHERE id = '157a98b7-1825-4699-b38d-85781cd21cf3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El parque de juegos de papá 👨‍👧', body_es = 'Correr detrás de él todo el día te ha dejado agotada. ¡El turno de la tarde es de papá! Que se encargue él de las volteretas en el suelo y los juegos de pillar.', title_fr = 'Le terrain de jeu de papa 👨‍👧', body_fr = 'Lui courir après toute la journée vous a épuisée. Ce soir, c''est au tour de papa ! Laissez-le s''occuper des roulades par terre et des courses-poursuites.', title_hi = 'पापा का खेल का मैदान 👨‍👧', body_hi = 'पूरे दिन उसके पीछे भागकर आप थक गई हैं। शाम की बारी पापा की है! ज़मीन पर लोटने और पकड़म-पकड़ाई वाले खेल वही संभालें।', title_id = 'Taman bermain ayah 👨‍👧', body_id = 'Mengejarnya seharian membuat Anda kelelahan. Giliran malam ini milik ayah! Biar ia yang mengurus permainan guling-guling dan kejar-kejaran.', title_ja = 'パパの遊び場 👨‍👧', body_ja = '一日中追いかけて、くたくたですね。夜はパパの番！床でごろごろや追いかけっこは、パパに任せましょう。', title_ko = '아빠의 놀이터 👨‍👧', body_ko = '하루 종일 쫓아다니느라 지쳤죠. 저녁 당번은 아빠예요! 바닥에서 뒹굴기와 술래잡기는 아빠에게 맡기세요.', title_nl = 'Papa''s speeltuin 👨‍👧', body_nl = 'De hele dag achter je kindje aanrennen heeft je uitgeput. Vanavond is papa aan de beurt! Laat hem over de vloer rollen en tikkertje spelen.', title_pl = 'Plac zabaw taty 👨‍👧', body_pl = 'Całodzienne bieganie za maluchem cię wykończyło. Wieczorna zmiana należy do taty! Niech turlanie się po podłodze i gonitwy przejmie on.', title_pt = 'O parque de diversões do pai 👨‍👧', body_pt = 'Correr atrás dele o dia todo deixou-a exausta. O turno da noite é do pai! Deixe as cambalhotas no chão e as brincadeiras de apanhada por conta dele.', title_sv = 'Pappas lekplats 👨‍👧', body_sv = 'Att springa efter barnet hela dagen har tagit all din kraft. Kvällspasset är pappas! Låt honom sköta rullandet på golvet och jagalekarna.', title_vi = 'Sân chơi của bố 👨‍👧', body_vi = 'Chạy theo bé cả ngày khiến mẹ kiệt sức. Ca tối là của bố! Hãy để bố lo những trò lăn lộn dưới sàn và đuổi bắt.', title_zh = '爸爸的游乐场 👨‍👧', body_zh = '追着宝宝跑了一整天，你已经筋疲力尽。晚上轮到爸爸了！在地上打滚、追追跑跑的游戏就交给他吧。' WHERE id = '47ea1c98-c71a-45d9-b06c-d95aa3da437b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te estreses porque hoy la casa esté desordenada.', body_es = 'Los niños no recuerdan casas ordenadas, sino mamás felices. Sírvete un café y descansa.', title_fr = 'Ne stressez pas parce que la maison est en désordre aujourd''hui.', body_fr = 'Les enfants ne se souviennent pas d''une maison bien rangée, mais d''une maman heureuse. Servez-vous un café et reposez-vous.', title_hi = 'आज घर बहुत बिखरा है, इसलिए तनाव मत लीजिए।', body_hi = 'बच्चे साफ़-सुथरे घर नहीं, खुश माँ को याद रखते हैं। अपनी कॉफ़ी डालिए और आराम कीजिए।', title_id = 'Jangan stres hanya karena rumah sedang berantakan.', body_id = 'Anak-anak tidak mengingat rumah yang rapi, melainkan ibu yang bahagia. Tuang kopi Anda dan beristirahatlah.', title_ja = '今日は家が散らかっていてもストレスを感じないで。', body_ja = '子どもが覚えているのは、片付いた家ではなく、幸せそうなママです。コーヒーをいれて、ひと休みしましょう。', title_ko = '오늘 집이 너무 어질러졌다고 스트레스받지 마세요.', body_ko = '아이들은 깔끔한 집이 아니라 행복한 엄마를 기억해요. 커피 한 잔을 따르고 쉬세요.', title_nl = 'Raak niet gestrest omdat het huis vandaag een rommel is.', body_nl = 'Kinderen onthouden geen opgeruimde huizen, maar gelukkige moeders. Schenk een kop koffie in en rust uit.', title_pl = 'Nie stresuj się, że w domu jest dziś bałagan.', body_pl = 'Dzieci nie pamiętają posprzątanych domów, tylko szczęśliwe mamy. Nalej sobie kawy i odpocznij.', title_pt = 'Não fique stressada por a casa estar desarrumada hoje.', body_pt = 'As crianças não se lembram de casas arrumadas, lembram-se de mães felizes. Sirva-se de um café e descanse.', title_sv = 'Stressa inte över att det är stökigt hemma i dag.', body_sv = 'Barn minns inte städade hem, utan glada mammor. Häll upp ditt kaffe och vila.', title_vi = 'Đừng căng thẳng vì hôm nay nhà cửa quá bừa bộn.', body_vi = 'Trẻ con không nhớ ngôi nhà gọn gàng, mà nhớ người mẹ hạnh phúc. Hãy pha một tách cà phê và nghỉ ngơi nhé.', title_zh = '别因为今天家里很乱而焦虑。', body_zh = '孩子记住的不是整洁的家，而是快乐的妈妈。倒杯咖啡，休息一下吧。' WHERE id = '9b3b08e6-de82-413f-9e4b-6da904b304a3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No puede gastar energía en casa y está quejica? ⛅', body_es = 'La naturaleza es el mejor calmante. Consulta Tiempo y ropa, elige la ropa adecuada y vete directa al parque.', title_fr = 'Il n''arrive pas à se défouler à la maison et pleurniche ?  ⛅', body_fr = 'La nature est le meilleur des calmants. Consultez Météo et tenue, choisissez la tenue et filez au parc.', title_hi = 'बच्चा घर में ऊर्जा नहीं निकाल पा रहा और चिड़चिड़ा है?  ⛅', body_hi = 'प्रकृति सबसे अच्छी शांति देती है। मौसम और कपड़े देखिए, कपड़े चुनिए और तुरंत पार्क चलिए।', title_id = 'Ia tidak bisa menyalurkan energinya di rumah dan jadi rewel?  ⛅', body_id = 'Alam adalah penenang terbaik. Cek Cuaca dan Pakaian, pilih pakaian yang tepat, dan segera pergi ke taman.', title_ja = '家の中でエネルギーを発散できず、ぐずっている？⛅', body_ja = '自然はいちばんの癒やしです。「天気と服装」を見てコーデを選び、すぐに公園へ出かけましょう。', title_ko = '집에서 에너지를 다 쓰지 못해 칭얼대나요?  ⛅', body_ko = '자연이 최고의 진정제예요. 날씨와 옷차림을 확인하고 옷을 골라 바로 공원으로 향하세요.', title_nl = 'Kan je kindje zijn energie binnen niet kwijt en is hij zeurderig? ⛅', body_nl = 'De natuur kalmeert het best. Kijk in Weer en kleding, kies de outfit en ga meteen naar het park.', title_pl = 'Maluch nie może w domu wyładować energii i marudzi?  ⛅', body_pl = 'Natura najlepiej uspokaja. Sprawdź Pogodę i ubiór, wybierz zestaw i od razu ruszajcie do parku.', title_pt = 'Em casa não consegue gastar energia e anda rabugento?  ⛅', body_pt = 'A natureza é o melhor calmante. Veja o Tempo e Roupa, escolha a combinação e siga já para o parque.', title_sv = 'Kan barnet inte få ut energin hemma och gnäller?  ⛅', body_sv = 'Naturen är det bästa lugnande medlet. Kolla Väder och kläder, välj klädsel och gå direkt till parken.', title_vi = 'Ở nhà bé không xả được năng lượng nên quấy khóc?  ⛅', body_vi = 'Thiên nhiên là liều thuốc an thần tốt nhất. Hãy xem Thời tiết và trang phục, chọn bộ đồ phù hợp và ra công viên ngay.', title_zh = '宝宝在家释放不了精力，哼哼唧唧？⛅', body_zh = '大自然是最好的安抚。看看天气穿衣，选好搭配，马上去公园吧。' WHERE id = '67b35eea-eab9-41c5-88b7-f31e283eddd9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¿Qué es esto?» ☝️', body_es = 'Lo señala todo con el dedo y hace un sonido especial. Te está pidiendo que le pongas nombre al mundo. Dile con paciencia el nombre de cada cosa que señale.', title_fr = 'La période du « C''est quoi ? » ☝️', body_fr = 'Il montre tout du doigt en faisant un petit son bien à lui. Il vous demande de nommer le monde. Dites-lui patiemment le nom de chaque objet qu''il montre.', title_hi = '''यह क्या है?'' का दौर ☝️', body_hi = 'हर चीज़ की ओर उँगली दिखाकर खास आवाज़ निकालता है। वह चाहता है कि आप उसे दुनिया की चीज़ों के नाम बताएँ। जो भी चीज़ वह दिखाए, धैर्य से उसका नाम बताइए।', title_id = 'Masa "Ini apa?" ☝️', body_id = 'Ia menunjuk segala hal dengan jarinya sambil mengeluarkan suara khusus. Ia ingin Anda menyebutkan nama dunia di sekitarnya. Sebutkan dengan sabar nama setiap benda yang ia tunjuk.', title_ja = '「これなあに？」の時期 ☝️', body_ja = 'なんでも指さして、特別な声を出していますか？世界のものに名前をつけてほしいのです。指さしたものの名前を、根気よく教えてあげましょう。', title_ko = '"이게 뭐야?" 시기 ☝️', body_ko = '모든 걸 손가락으로 가리키며 특별한 소리를 내요. 세상의 이름을 알려 달라는 거예요. 가리키는 물건마다 인내심을 갖고 이름을 말해 주세요.', title_nl = 'De wat-is-dat-fase ☝️', body_nl = 'Je kindje wijst alles aan en maakt er een speciaal geluidje bij. Hij vraagt je de wereld te benoemen. Zeg geduldig de naam van alles wat hij aanwijst.', title_pl = 'Etap „Co to jest?” ☝️', body_pl = 'Pokazuje wszystko paluszkiem i wydaje przy tym szczególny dźwięk. Prosi cię, byś nazwała mu świat. Cierpliwie mów mu nazwę każdej rzeczy, którą pokazuje.', title_pt = 'A fase do "O que é isto?" ☝️', body_pt = 'Aponta para tudo com o dedo e faz um som especial. Está a pedir-lhe que dê nome ao mundo. Diga-lhe com paciência o nome de cada objeto que aponta.', title_sv = 'Fasen ”Vad är det?” ☝️', body_sv = 'Barnet pekar på allt och gör ett särskilt ljud. Det vill att du sätter namn på världen. Säg med tålamod namnet på varje sak barnet pekar på.', title_vi = 'Giai đoạn "Cái gì đây?" ☝️', body_vi = 'Bé chỉ tay vào mọi thứ và phát ra âm thanh đặc biệt. Bé đang muốn mẹ gọi tên thế giới xung quanh. Hãy kiên nhẫn nói cho bé tên của từng đồ vật bé chỉ.', title_zh = '“这是什么？”阶段 ☝️', body_zh = '宝宝用手指指着各种东西，还发出特别的声音。他是想让你告诉他世界万物的名字。耐心地告诉他指到的每样东西叫什么吧。' WHERE id = 'b9cf7b0e-6913-455f-8740-fcf7cc3d09d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hace falta silencio 🤫', body_es = 'La primera media hora después de dormirse es el momento más delicado. Comprueba los decibelios con el Medidor de sonido y evita los ruidos repentinos.', title_fr = 'Besoin de silence 🤫', body_fr = 'La première demi-heure après l''endormissement est la plus fragile. Vérifiez le niveau de décibels avec le Sonomètre et méfiez-vous des bruits soudains.', title_hi = 'शांति की ज़रूरत है 🤫', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक होता है। साउंड मीटर से माहौल का डेसिबल जाँचिए और अचानक के शोर से बचिए।', title_id = 'Butuh ketenangan 🤫', body_id = 'Setengah jam pertama setelah ia tertidur adalah waktu yang paling rawan. Periksa desibel ruangan dengan Pengukur Suara dan hindari suara bising yang tiba-tiba.', title_ja = '静けさが必要 🤫', body_ja = '眠りについてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で部屋のデシベルを確認し、急な物音に気をつけましょう。', title_ko = '고요함이 필요해요 🤫', body_ko = '잠든 뒤 처음 30분이 가장 예민한 시간이에요. 소음 측정기로 주변 데시벨을 확인하고 갑작스러운 소음에 주의하세요.', title_nl = 'Tijd voor stilte 🤫', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer het aantal decibel met de Geluidsmeter en pas op voor plotseling lawaai.', title_pl = 'Potrzebna cisza 🤫', body_pl = 'Pierwsze pół godziny po zaśnięciu to najwrażliwszy czas. Sprawdź Miernikiem dźwięku poziom decybeli w otoczeniu i uważaj na nagłe hałasy.', title_pt = 'É preciso silêncio 🤫', body_pt = 'A primeira meia hora depois de adormecer é o momento mais sensível. Verifique os decibéis do ambiente com o Medidor de Som e evite barulhos repentinos.', title_sv = 'Det behövs tystnad 🤫', body_sv = 'Den första halvtimmen efter att barnet somnat är den känsligaste. Kolla decibelnivån med Ljudmätaren och akta dig för plötsligt oväsen.', title_vi = 'Cần chút yên tĩnh 🤫', body_vi = 'Nửa tiếng đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra độ ồn bằng Đo âm thanh và cẩn thận với những tiếng động đột ngột.', title_zh = '需要安静 🤫', body_zh = '入睡后的头半小时是最敏感的时候。用噪音测量检查一下环境分贝，小心突然的噪音。' WHERE id = 'd4a833e4-9676-4c95-baa2-923b9117c325' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hay detalles del desarrollo de tu peque de 15 meses que te preocupan? No te pierdas en internet: escribe directamente a Anacan AI y recibe una respuesta con base científica.', body_fr = 'Certains détails du développement de votre enfant de 15 mois vous préoccupent ? Ne vous perdez pas sur Internet, écrivez directement à Anacan AI et obtenez une réponse fondée sur la science.', body_hi = '15 महीने के बच्चे के विकास में कुछ बातें आपको सोच में डाल रही हैं? इंटरनेट में मत खोइए, सीधे Anacan AI को लिखिए और वैज्ञानिक जवाब पाइए।', body_id = 'Ada detail perkembangan anak 15 bulan yang mengganggu pikiran Anda? Jangan tersesat di internet, langsung tulis ke Anacan AI dan dapatkan jawaban berbasis ilmiah.', body_ja = '1歳3か月の子の発達で気になることがありますか？ネットで迷わず、Anacan AIに直接書き込んで、科学的な根拠のある答えをもらいましょう。', body_ko = '15개월 아이의 발달에 대해 고민되는 점이 있나요? 인터넷에서 헤매지 말고 바로 Anacan AI에게 물어 과학적 근거가 있는 답을 받아 보세요.', body_nl = 'Maak je je zorgen over iets in de ontwikkeling van je kindje van 15 maanden? Verdwaal niet op internet, schrijf meteen Anacan AI en krijg een wetenschappelijk onderbouwd antwoord.', body_pl = 'Nurtują cię jakieś szczegóły rozwoju 15-miesięcznego dziecka? Nie gub się w internecie, napisz bezpośrednio do Anacan AI i otrzymaj odpowiedź opartą na nauce.', body_pt = 'Há detalhes no desenvolvimento de uma criança de 15 meses que a preocupam? Não se perca na internet: escreva diretamente ao Anacan AI e receba uma resposta com base científica.', body_sv = 'Finns det detaljer i utvecklingen hos ditt barn på 15 månader som oroar dig? Gå inte vilse på nätet, skriv direkt till Anacan AI och få ett vetenskapligt grundat svar.', body_vi = 'Có chi tiết nào về sự phát triển của bé 15 tháng khiến mẹ băn khoăn? Đừng lạc lối trên mạng, hãy hỏi thẳng Anacan AI và nhận câu trả lời có cơ sở khoa học.', body_zh = '15个月宝宝的发育有让你挂心的细节？别在网上迷路了，直接问Anacan AI，获得有科学依据的回答。' WHERE id = '088ce5b1-9a8e-4d7d-8f55-017e0cc63605' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento mágico 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial sobre un héroe valiente que descubre el mundo. Haz más dulce la hora de dormir.', title_fr = 'Un conte magique 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire unique sur un héros courageux qui découvre le monde. Adoucissez le passage au sommeil.', title_hi = 'जादुई कहानी 🪄', body_hi = 'स्मार्ट कहानियों में दुनिया खोजने वाले एक बहादुर हीरो की खास कहानी बनाइए। नींद की ओर बढ़ना मीठा बनाइए।', title_id = 'Dongeng ajaib 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa tentang pahlawan pemberani yang menjelajahi dunia. Jadikan peralihan ke tidur lebih manis.', title_ja = '魔法のお話 🪄', body_ja = '「スマートおはなし」で、勇敢なヒーローが世界を探検する特別なお話をつくりましょう。眠りへの切りかえをやさしく。', title_ko = '마법 같은 동화 🪄', body_ko = '스마트 동화에서 용감한 주인공이 세상을 탐험하는 특별한 이야기를 만들어 보세요. 잠드는 시간을 달콤하게 만들어 줄 거예요.', title_nl = 'Een magisch sprookje 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal over een dappere held die de wereld ontdekt. Maak het slapengaan wat zoeter.', title_pl = 'Magiczna bajka 🪄', body_pl = 'W Mądrych bajkach stwórz wyjątkową historię o odważnym bohaterze, który odkrywa świat. Osłódź mu zasypianie.', title_pt = 'Um conto mágico 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial sobre um herói corajoso a descobrir o mundo. Torne mais doce a passagem para o sono.', title_sv = 'Magisk saga 🪄', body_sv = 'Skapa en egen berättelse i Smarta sagor om en modig hjälte som upptäcker världen. Gör övergången till sömnen ännu sötare.', title_vi = 'Câu chuyện kỳ diệu 🪄', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo một câu chuyện riêng về người hùng dũng cảm khám phá thế giới. Hãy để giờ đi ngủ thêm ngọt ngào.', title_zh = '魔法故事 🪄', body_zh = '在智能故事里创作一个勇敢小英雄探索世界的专属故事，让入睡变得更甜蜜。' WHERE id = 'b6c6ae0a-2aaa-45b3-b8de-d4785923503c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paso a una sola siesta 🥱', body_es = '¿No quiere dormir la siesta de la mañana y se ha descolocado el horario? ¡Está creciendo! Empieza el paso de dos siestas a una. Ajusta la rutina poco a poco.', title_fr = 'Le passage à une seule sieste 🥱', body_fr = 'Il refuse la sieste du matin et le planning est chamboulé ? Il grandit ! Le passage de deux siestes à une seule commence. Réajustez son rythme petit à petit.', title_hi = 'एक झपकी पर आना 🥱', body_hi = 'सुबह की झपकी नहीं लेना चाहता और शेड्यूल उलट-पुलट हो गया? वह बड़ा हो रहा है! दिन की दो झपकियों से एक पर आने का दौर शुरू हो रहा है। रूटीन को धीरे-धीरे ढालिए।', title_id = 'Peralihan ke satu kali tidur siang 🥱', body_id = 'Ia tidak mau tidur pagi dan jadwal jadi kacau? Ia sedang tumbuh! Peralihan dari dua kali ke satu kali tidur siang sedang dimulai. Atur rutinitasnya perlahan-lahan.', title_ja = 'お昼寝1回への移行 🥱', body_ja = '朝寝を嫌がって、スケジュールが乱れていますか？成長している証拠です！お昼寝が2回から1回に移る時期です。少しずつ生活リズムを整えましょう。', title_ko = '낮잠 한 번으로 전환 🥱', body_ko = '오전 낮잠을 거부하고 일정이 엉망이 됐나요? 아이가 자라고 있는 거예요! 낮잠이 두 번에서 한 번으로 바뀌기 시작해요. 루틴을 천천히 맞춰 주세요.', title_nl = 'Overgang naar één dutje 🥱', body_nl = 'Wil je kindje ''s ochtends niet slapen en ligt het schema overhoop? Hij wordt groter! De overgang van twee dutjes naar één begint. Pas de routine rustig aan.', title_pl = 'Przejście na jedną drzemkę 🥱', body_pl = 'Nie chce iść na poranną drzemkę i plan dnia się sypie? On rośnie! Zaczyna się przejście z dwóch drzemek na jedną. Powoli dostosuj rutynę.', title_pt = 'A passagem para uma só sesta 🥱', body_pt = 'Não quer fazer a sesta da manhã e o horário ficou todo trocado? Está a crescer! Começa a passagem de duas sestas para uma. Ajuste a rotina aos poucos.', title_sv = 'Övergång till en tupplur 🥱', body_sv = 'Vill barnet inte sova på förmiddagen och har schemat ställts på ända? Barnet växer! Övergången från två tupplurar till en börjar. Justera rutinen sakta.', title_vi = 'Chuyển sang một giấc ngủ ngày 🥱', body_vi = 'Bé không chịu ngủ buổi sáng và lịch trình đảo lộn? Bé đang lớn! Giai đoạn chuyển từ hai giấc ngủ ngày sang một giấc đã bắt đầu. Hãy điều chỉnh nếp sinh hoạt từ từ.', title_zh = '过渡到一次小睡 🥱', body_zh = '宝宝不想睡上午觉，作息全乱了？他在长大！白天开始从两次小睡过渡到一次。慢慢调整作息吧。' WHERE id = 'c4cd946e-4029-4937-a10b-6f87983c2067' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un baño templado relaja 🛁', body_es = 'Jugar con el agua para quitarse el polvo y el cansancio del día le divertirá y le preparará perfectamente para dormir.', title_fr = 'Un bain tiède qui détend. 🛁', body_fr = 'Jouer avec l''eau pour se débarrasser de la poussière et de la fatigue de la journée va l''amuser et le préparer parfaitement au sommeil.', title_hi = 'गुनगुना स्नान सुकून देता है। 🛁', body_hi = 'दिन की धूल और थकान धोने के लिए पानी से खेलना उसे मज़ा भी देगा और नींद के लिए पूरी तरह तैयार भी करेगा।', title_id = 'Mandi air hangat itu menenangkan. 🛁', body_id = 'Bermain air untuk menghapus debu dan lelah seharian akan menghiburnya sekaligus membuatnya siap tidur.', title_ja = 'ぬるめのお風呂でリラックス 🛁', body_ja = '水遊びで一日のほこりと疲れを落とせば、楽しいうえに、眠りへの準備もばっちり整います。', title_ko = '따뜻한 목욕은 마음을 편하게 해요. 🛁', body_ko = '하루의 먼지와 피로를 씻어 내는 물놀이는 아이를 즐겁게 하고 잠들 준비도 완벽하게 해 줄 거예요.', title_nl = 'Een lauw badje ontspant. 🛁', body_nl = 'Spelen met water spoelt het stof en de vermoeidheid van de dag weg, is leuk en maakt je kindje perfect klaar om te slapen.', title_pl = 'Ciepła kąpiel odpręża. 🛁', body_pl = 'Zabawa w wodzie zmyje kurz i zmęczenie całego dnia, rozbawi go i idealnie przygotuje do snu.', title_pt = 'Um banho morno relaxa. 🛁', body_pt = 'Brincar com a água para tirar o pó e o cansaço do dia vai diverti-lo e, ao mesmo tempo, prepará-lo na perfeição para dormir.', title_sv = 'Ett ljummet bad avslappnar. 🛁', body_sv = 'Att leka med vatten för att skölja bort dagens damm och trötthet både roar barnet och förbereder det perfekt för sömnen.', title_vi = 'Tắm nước ấm giúp thư giãn. 🛁', body_vi = 'Chơi với nước để rửa trôi bụi bặm và mệt mỏi cả ngày vừa giúp bé vui, vừa chuẩn bị hoàn hảo cho giấc ngủ.', title_zh = '温水澡让人放松 🛁', body_zh = '玩玩水，洗去一天的尘土和疲惫，既能逗他开心，又能为入睡做好充分准备。' WHERE id = '2517046a-f369-483a-b1e2-38f6320720ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Rabietas? 🌪', body_es = '️ Cuando no puede expresarse, puede enfadarse y llorar. Si necesitas apoyo con esto, consulta a Anacan AI y aprende a afrontarlo bien.', title_fr = 'Des crises de colère ? 🌪', body_fr = '️ Quand il n''arrive pas à s''exprimer, il peut s''énerver et pleurer. Si vous avez besoin de soutien, demandez conseil à Anacan AI pour trouver la bonne approche.', title_hi = 'गुस्से के दौरे? 🌪', body_hi = '️ अपनी बात न कह पाने पर वह चिढ़कर रो सकता है। अगर इसमें आपको मदद चाहिए, तो Anacan AI से सलाह लेकर सही तरीका जानिए।', title_id = 'Ledakan amarah? 🌪', body_id = '️ Saat belum bisa mengungkapkan diri, ia bisa kesal dan menangis. Kalau Anda butuh dukungan soal ini, konsultasikan dengan Anacan AI dan pelajari cara menghadapinya dengan tepat.', title_ja = 'かんしゃく？🌪', body_ja = '️うまく気持ちを伝えられないと、イライラして泣くことがあります。サポートが必要なら、Anacan AIに相談して、適切な接し方を学びましょう。', title_ko = '분노 발작? 🌪', body_ko = '️자신을 표현하지 못하면 화가 나서 울 수 있어요. 도움이 필요하다면 Anacan AI와 상담해 올바른 대처법을 알아보세요.', title_nl = 'Driftbuien? 🌪', body_nl = '️ Je kindje kan boos worden en huilen als hij zich niet kan uiten. Heb je hierbij steun nodig? Overleg met Anacan AI en ontdek de juiste aanpak.', title_pl = 'Napady złości? 🌪', body_pl = '️ Gdy nie umie się wyrazić, może się złościć i płakać. Jeśli potrzebujesz w tym wsparcia, poradź się Anacan AI i poznaj właściwe podejście.', title_pt = 'Crises de birra? 🌪', body_pt = '️ Quando não se consegue expressar, pode irritar-se e chorar. Se precisar de apoio nisso, fale com o Anacan AI e aprenda a abordagem certa.', title_sv = 'Ilskeutbrott? 🌪', body_sv = '️ Barnet kan bli argt och gråta när det inte kan uttrycka sig. Om du behöver stöd, rådfråga Anacan AI och lär dig rätt förhållningssätt.', title_vi = 'Những cơn giận dữ? 🌪', body_vi = '️ Khi chưa diễn đạt được, bé có thể bực bội và khóc. Nếu mẹ cần hỗ trợ, hãy hỏi ý kiến Anacan AI để biết cách ứng xử đúng.', title_zh = '发脾气崩溃？🌪', body_zh = '️ 表达不出来时，宝宝可能会着急哭闹。如果你需要这方面的支持，可以咨询Anacan AI，学习正确的应对方法。' WHERE id = '258818a7-034e-4b93-86ea-97e8e01d3126' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entiende las palabras 🧠', body_es = '¿Cuando le dices «Trae los zapatos» los encuentra y te los trae? Su inteligencia avanza a toda velocidad. ¡Elógiale mucho!', title_fr = 'Il comprend les mots. 🧠', body_fr = 'Quand vous dites « Apporte tes chaussures », il les trouve et vous les apporte ? Son intelligence se développe à toute vitesse. Félicitez-le beaucoup !', title_hi = 'शब्द समझने का हुनर। 🧠', body_hi = '''जूते लाओ'' कहने पर वह ढूँढकर ले आता है? यह दिखाता है कि उसका दिमाग तेज़ी से विकसित हो रहा है। खूब तारीफ़ कीजिए!', title_id = 'Kemampuan memahami kata. 🧠', body_id = 'Saat Anda bilang "Ambil sepatunya", ia menemukan dan membawanya? Ini tanda kecerdasannya berkembang pesat. Puji ia sebanyak-banyaknya!', title_ja = '言葉がわかる力 🧠', body_ja = '「靴を持ってきて」と言うと、探して持ってきてくれますか？知性がぐんぐん育っている証拠です。たっぷり褒めてあげましょう！', title_ko = '말을 이해하는 능력. 🧠', body_ko = '"신발 가져와" 하면 찾아서 가져오나요? 두뇌가 빠르게 발달하고 있다는 뜻이에요. 듬뿍 칭찬해 주세요!', title_nl = 'Woorden begrijpen. 🧠', body_nl = 'Zoekt en brengt je kindje zijn schoenen als je zegt: haal je schoenen? Dat laat zien hoe snel zijn verstand zich ontwikkelt. Prijs hem volop!', title_pl = 'Rozumienie słów. 🧠', body_pl = 'Na „Przynieś buty” znajduje je i przynosi? To pokazuje, jak szybko rozwija się jego umysł. Chwal go jak najczęściej!', title_pt = 'A capacidade de compreender palavras. 🧠', body_pt = 'Quando lhe diz "Traz os sapatos", ele encontra-os e traz-lhos? Isso mostra que a inteligência dele se desenvolve depressa. Elogie-o muito!', title_sv = 'Förmågan att förstå ord. 🧠', body_sv = 'Hittar barnet skorna och kommer med dem när du säger ”Hämta skorna”? Det visar att intelligensen utvecklas snabbt. Beröm massor!', title_vi = 'Khả năng hiểu từ ngữ. 🧠', body_vi = 'Mẹ nói "Mang giày lại đây" là bé tìm và mang đến? Điều này cho thấy trí tuệ của bé đang phát triển nhanh chóng. Hãy khen bé thật nhiều!', title_zh = '理解词语的能力 🧠', body_zh = '你说“把鞋拿来”，他会找到拿给你？这说明他的智力在快速发展。多多夸奖他吧！' WHERE id = 'ca5a1958-0c22-4c62-874b-c3b801f70118' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño dictador del menú 🥣', body_es = '¿Hoy aparta la comida que ayer le encantaba? Ser selectivo con la comida es normal a esta edad. Sin agobiarte, busca alternativas distintas en Recetas saludables.', title_fr = 'Le petit dictateur du menu 🥣', body_fr = 'Il repousse aujourd''hui le plat qu''il adorait hier ? Être difficile à table est normal à cet âge. Sans paniquer, cherchez d''autres idées dans les Recettes saines.', title_hi = 'मेन्यू का तानाशाह 🥣', body_hi = 'कल का पसंदीदा खाना आज दूर सरका देता है? इस उम्र में खाने में नखरे सामान्य हैं। घबराए बिना सेहतमंद रेसिपी में अलग विकल्प ढूँढिए।', title_id = 'Diktator menu 🥣', body_id = 'Makanan favoritnya kemarin, hari ini ia singkirkan? Pilih-pilih makanan di usia ini normal. Jangan panik, cari alternatif lain di Resep Sehat.', title_ja = '小さなメニュー決定権者 🥣', body_ja = '昨日大好きだった料理を、今日は押しのけていますか？この年齢の好き嫌いはよくあることです。慌てずに「ヘルシーレシピ」で別のメニューを探してみましょう。', title_ko = '메뉴 독재자 🥣', body_ko = '어제 좋아하던 음식을 오늘은 밀어내나요? 이 나이에 음식을 가리는 건 정상이에요. 당황하지 말고 건강한 레시피에서 다른 대안을 찾아보세요.', title_nl = 'Kleine menudictator 🥣', body_nl = 'Duwt je kindje vandaag weg wat hij gisteren nog lekker vond? Kieskeurig eten is normaal op deze leeftijd. Raak niet in paniek en zoek andere opties in Gezonde recepten.', title_pl = 'Mały dyktator menu 🥣', body_pl = 'Odpycha dziś jedzenie, które wczoraj uwielbiał? Wybiórczość w jedzeniu w tym wieku to norma. Bez paniki poszukaj innych propozycji w zdrowych przepisach.', title_pt = 'O ditador da ementa 🥣', body_pt = 'Hoje afasta a comida de que ontem gostava? Ser esquisito com a comida nesta idade é normal. Sem entrar em pânico, procure alternativas nas Receitas Saudáveis.', title_sv = 'Menydiktatorn 🥣', body_sv = 'Skjuter barnet bort gårdagens favoritmat i dag? Kräsenhet med maten är normalt i den här åldern. Få inte panik, leta efter andra alternativ i Hälsosamma recept.', title_vi = '"Nhà độc tài" thực đơn 🥣', body_vi = 'Món hôm qua bé thích, hôm nay lại đẩy ra? Kén ăn ở tuổi này là chuyện bình thường. Đừng hoảng, hãy tìm những lựa chọn khác trong Công thức lành mạnh nhé.', title_zh = '菜单小独裁者 🥣', body_zh = '昨天还爱吃的东西，今天就推到一边？这个年龄挑食很正常。别慌，去健康食谱里找找其他替代选择吧。' WHERE id = '9cae6c34-b21b-425c-bdc8-0f1f07e9d0ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Imita los sonidos de los animales! 🐱', body_es = 'Jugad a «¿Cómo hace el gato?». Estas imitaciones sencillas y divertidas son una base estupenda para que empiece a hablar.', title_fr = 'Il imite les cris des animaux ! 🐱', body_fr = 'Jouez à « Que fait le chat ? ». Ces imitations simples et amusantes sont une excellente base pour l''aider à parler.', title_hi = 'जानवरों की आवाज़ की नकल! 🐱', body_hi = '''बिल्ली कैसे बोलती है?'' वाला खेल खेलिए। ये आसान और मज़ेदार नकलें उसके बोलना शुरू करने की बढ़िया नींव हैं।', title_id = 'Meniru suara hewan! 🐱', body_id = 'Mainkan permainan "Kucing bunyinya bagaimana?". Peniruan sederhana dan seru ini adalah fondasi yang bagus untuk mulai bicara.', title_ja = '動物の鳴き声をまねっこ！🐱', body_ja = '「ねこはなんて鳴く？」遊びをしてみましょう。簡単で楽しいまねっこは、おしゃべりを始めるためのすばらしい土台になります。', title_ko = '동물 소리 흉내! 🐱', body_ko = '"고양이는 어떻게 울지?" 놀이를 해 보세요. 이런 간단하고 재미있는 흉내 내기가 말문이 트이는 훌륭한 바탕이 돼요.', title_nl = 'Dierengeluiden nadoen! 🐱', body_nl = 'Speel het spelletje: wat zegt de poes? Zulke eenvoudige, leuke imitaties zijn een prima basis om te leren praten.', title_pl = 'Naśladujemy zwierzęta! 🐱', body_pl = 'Pobawcie się w „Jak robi kotek?”. Takie proste i zabawne naśladowanie to świetny fundament, by zaczął mówić.', title_pt = 'A imitar os sons dos animais! 🐱', body_pt = 'Brinquem ao "Como faz o gato?". Estas imitações simples e divertidas são uma ótima base para ele começar a falar.', title_sv = 'Härmar djurläten! 🐱', body_sv = 'Lek leken ”Vad säger katten?”. Dessa enkla och roliga härmningar är en utmärkt grund för att börja prata.', title_vi = 'Bắt chước tiếng kêu của con vật! 🐱', body_vi = 'Hãy chơi trò "Con mèo kêu thế nào?". Những trò bắt chước đơn giản và vui nhộn này là nền tảng tuyệt vời để bé bắt đầu nói.', title_zh = '模仿动物叫声！🐱', body_zh = '玩“小猫怎么叫？”的游戏吧。这些简单有趣的模仿，是他开口说话的好基础。' WHERE id = '54788c72-cfe2-4f75-82f0-ba29d942e404' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recarga energía 🥑', body_es = 'Si ya está lleno, te toca a ti. No comas de pie con las prisas del día. Elige un tentempié energético en Recetas saludables y túmbate en el sofá.', title_fr = 'Rechargez vos batteries 🥑', body_fr = 'Il a bien mangé ? À votre tour. Dans le tourbillon du quotidien, ne déjeunez pas debout. Choisissez un en-cas énergisant dans les Recettes saines et allongez-vous sur le canapé.', title_hi = 'अपनी ऊर्जा लौटाइए 🥑', body_hi = 'उसका पेट भर गया, तो अब आपकी बारी है। रोज़ की भागदौड़ में खड़े-खड़े लंच मत कीजिए। सेहतमंद रेसिपी से कोई ऊर्जा भरा स्नैक चुनिए और सोफ़े पर लेटिए।', title_id = 'Pulihkan energi Anda 🥑', body_id = 'Kalau ia sudah kenyang, sekarang giliran Anda. Jangan makan siang sambil berdiri di tengah kesibukan. Pilih camilan berenergi dari Resep Sehat dan berbaringlah di sofa.', title_ja = 'エネルギーをチャージ 🥑', body_ja = 'お子さんがお腹いっぱいになったら、次はあなたの番。慌ただしい毎日でも、立ったままランチをすませないで。「ヘルシーレシピ」から元気が出るおやつを選んで、ソファで横になりましょう。', title_ko = '에너지를 회복하세요 🥑', body_ko = '아기가 배불리 먹었다면 이제 엄마 차례예요. 바쁜 하루 속에서도 점심을 서서 먹지 마세요. 건강한 레시피에서 든든한 간식을 골라 소파에 누워 쉬세요.', title_nl = 'Laad je energie op 🥑', body_nl = 'Heeft je kindje genoeg gegeten? Dan ben jij aan de beurt. Eet je lunch niet staand tussen alle drukte door. Kies een energierijk tussendoortje in Gezonde recepten en ga op de bank liggen.', title_pl = 'Odzyskaj energię 🥑', body_pl = 'Jeśli on już najedzony, teraz twoja kolej. W codziennej bieganinie nie jedz obiadu na stojąco. Wybierz ze zdrowych przepisów energetyczną przekąskę i połóż się na kanapie.', title_pt = 'Recupere energia 🥑', body_pt = 'Se ele já está satisfeito, agora é a sua vez. Não almoce de pé no meio da correria. Escolha um lanche energético nas Receitas Saudáveis e deite-se no sofá.', title_sv = 'Fyll på energin 🥑', body_sv = 'Är barnet mätt är det din tur. Ät inte lunchen stående i vardagsstressen. Välj ett energigivande mellanmål från Hälsosamma recept och lägg dig på soffan.', title_vi = 'Nạp lại năng lượng 🥑', body_vi = 'Bé no rồi thì đến lượt mẹ. Đừng ăn trưa vội vàng giữa bộn bề mỗi ngày. Hãy chọn một món ăn nhẹ giàu năng lượng trong Công thức lành mạnh và nằm nghỉ trên sofa nhé.', title_zh = '恢复能量 🥑', body_zh = '宝宝吃饱了，轮到你了。别在日常忙乱中站着吃午饭。从健康食谱里选一款能量小食，到沙发上躺一躺。' WHERE id = 'b6e52bfa-dc31-4ddf-8f05-2d6b4e9ec2fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la rutina de la noche 🛀', title_fr = 'La force du rituel du soir 🛀', title_hi = 'शाम के रूटीन की ताकत 🛀', title_id = 'Kekuatan rutinitas malam 🛀', title_ja = '夜の習慣の力 🛀', title_ko = '저녁 루틴의 힘 🛀', title_nl = 'De kracht van de avondroutine 🛀', title_pl = 'Siła wieczornej rutyny 🛀', title_pt = 'A força da rotina da noite 🛀', title_sv = 'Kvällsrutinens kraft 🛀', title_vi = 'Sức mạnh của nếp sinh hoạt buổi tối 🛀', title_zh = '晚间作息的力量 🛀' WHERE id = 'f3a87482-9f2e-4700-94d8-d413093ea00a' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los momentos más tiernos del día 📸', body_es = 'Inmortaliza con la Sesión de fotos del bebé cualquier gesto gracioso que haya hecho hoy o una habilidad que acabe de aprender.', title_fr = 'Les doux moments du jour. 📸', body_fr = 'Immortalisez avec la Séance photo bébé ses pitreries du jour ou la nouvelle chose qu''il vient d''apprendre.', title_hi = 'दिन के प्यारे पल। 📸', body_hi = 'आज उसकी कोई मज़ेदार हरकत या नया सीखा हुनर बेबी फ़ोटोशूट से हमेशा के लिए सहेज लीजिए।', title_id = 'Momen manis hari ini. 📸', body_id = 'Abadikan tingkah lucunya hari ini atau keterampilan baru yang ia pelajari dengan Sesi Foto Bayi.', title_ja = '今日のかわいい瞬間 📸', body_ja = '今日のおもしろいしぐさや新しくできるようになったことを、「ベビーフォトセッション」で残しましょう。', title_ko = '오늘의 달콤한 순간. 📸', body_ko = '오늘 보여 준 재미있는 행동이나 새로 배운 기술을 아기 사진 촬영으로 영원히 남기세요.', title_nl = 'Lieve momenten van de dag. 📸', body_nl = 'Leg een grappige actie of een nieuwe vaardigheid van vandaag voor altijd vast met Babyfotoshoot.', title_pl = 'Słodkie chwile dnia. 📸', body_pl = 'Uwiecznij w Sesji zdjęciowej dziecka każdą zabawną minę lub nową umiejętność, którą dziś pokazał.', title_pt = 'Os momentos doces do dia. 📸', body_pt = 'Eternize com a Sessão Fotográfica do Bebé qualquer gesto engraçado que ele tenha feito hoje ou uma competência que acabou de aprender.', title_sv = 'Dagens söta stunder. 📸', body_sv = 'Förevig något roligt barnet gjort i dag eller en nyinlärd färdighet med Babyfotografering.', title_vi = 'Những khoảnh khắc ngọt ngào trong ngày. 📸', body_vi = 'Hãy lưu giữ mọi hành động ngộ nghĩnh hay kỹ năng mới học được hôm nay của bé bằng Chụp ảnh cho bé.', title_zh = '今天的甜蜜瞬间 📸', body_zh = '把宝宝今天做的好笑动作或新学会的本领，用宝宝写真永远留下来吧。' WHERE id = '1b9c01dc-4c8d-4f96-bbe5-d06d1d460981' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pone a prueba los límites 🛑', body_es = '¿Aunque le dices que no, vuelve a alargar la mano hacia ese objeto? No es terquedad, solo está poniendo a prueba las normas. Ten paciencia.', title_fr = 'Il teste les limites. 🛑', body_fr = 'Malgré votre « non », il tend encore la main vers l''objet ? Ce n''est pas de l''entêtement, c''est simplement sa façon d''apprendre les règles. Soyez patiente.', title_hi = 'सीमाएँ परख रहा है। 🛑', body_hi = 'आपके ''नहीं'' कहने के बावजूद फिर उसी चीज़ की ओर हाथ बढ़ाता है? यह ज़िद नहीं, बस नियम सीखने का टेस्ट है। धैर्य रखिए।', title_id = 'Menguji batas. 🛑', body_id = 'Meski Anda sudah bilang tidak, ia tetap meraih benda itu? Ini bukan keras kepala, ia hanya sedang menguji aturan. Bersabarlah.', title_ja = '境界線を試しています 🛑', body_ja = '「ダメ」と言ったのに、またそれに手を伸ばしますか？これは反抗ではなく、ルールを学ぶためのテストです。根気よく見守りましょう。', title_ko = '한계를 시험하고 있어요. 🛑', body_ko = '"안 돼"라고 해도 또 그 물건에 손을 뻗나요? 고집이 아니라 규칙을 배우는 시험이에요. 인내심을 가져 주세요.', title_nl = 'Grenzen aftasten. 🛑', body_nl = 'Je zegt nee, maar je kindje grijpt toch naar dat ding? Dat is geen koppigheid, maar een test om de regels te leren. Wees geduldig.', title_pl = 'Sprawdza granice. 🛑', body_pl = 'Mimo twojego „nie” znów sięga po tę rzecz? To nie upór, tylko test, w którym poznaje zasady. Bądź cierpliwa.', title_pt = 'Está a testar os limites. 🛑', body_pt = 'Mesmo depois de dizer que não, volta a esticar a mão para aquele objeto? Não é teimosia, é só um teste para aprender as regras. Seja paciente.', title_sv = 'Testar gränserna. 🛑', body_sv = 'Trots att du sagt nej sträcker sig barnet ändå efter saken? Det är inte trots, bara ett test för att lära sig reglerna. Ha tålamod.', title_vi = 'Bé thử giới hạn. 🛑', body_vi = 'Dù mẹ đã nói "không", bé vẫn với lấy món đồ đó? Đây không phải bướng bỉnh mà chỉ là bé đang thử tìm hiểu quy tắc. Hãy kiên nhẫn nhé.', title_zh = '在试探边界 🛑', body_zh = '你说了“不行”，他还是伸手去拿那样东西？这不是倔强，只是在测试规则。保持耐心吧。' WHERE id = '21100889-9857-4170-a0a6-59c3dec113f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Pasa las páginas de los libros de cartón y reacciona a los dibujos? Su memoria visual se está desarrollando. Léele muchos cuentos llenos de color.', body_fr = 'Il tourne les pages de ses livres cartonnés et réagit aux images ? Sa mémoire visuelle se développe. Lisez-lui plein de livres d''histoires colorés.', body_hi = 'मोटे पन्नों वाली किताबों के पन्ने पलटता है और तस्वीरों पर प्रतिक्रिया देता है? उसकी देखी हुई चीज़ें याद रखने की क्षमता बढ़ रही है। उसे खूब रंगीन कहानी की किताबें पढ़कर सुनाइए।', body_id = 'Ia membalik halaman buku bertebal dan bereaksi pada gambarnya? Ingatan visualnya sedang berkembang. Bacakan banyak buku cerita berwarna untuknya.', body_ja = '厚紙の絵本のページをめくって、絵に反応していますか？見たものを覚える力が育っています。カラフルな絵本をたくさん読んであげましょう。', body_ko = '두꺼운 책장을 넘기며 그림에 반응하나요? 시각 기억력이 발달하고 있어요. 알록달록한 그림책을 많이 읽어 주세요.', body_nl = 'Slaat je kindje de bladzijden van kartonboekjes om en reageert hij op de plaatjes? Zijn visuele geheugen ontwikkelt zich. Lees hem veel kleurrijke prentenboeken voor.', body_pl = 'Przewraca kartki grubych książeczek i reaguje na obrazki? Rozwija się pamięć wzrokowa. Czytaj mu dużo kolorowych książeczek z bajkami.', body_pt = 'Vira as páginas dos livros cartonados e reage às imagens? A memória visual está a desenvolver-se. Leia-lhe muitos livros de histórias coloridos.', body_sv = 'Vänder barnet sidorna i kartongböcker och reagerar på bilderna? Det visuella minnet utvecklas. Läs massor av färgglada sagoböcker tillsammans.', body_vi = 'Bé lật trang sách bìa cứng và phản ứng với hình ảnh? Trí nhớ hình ảnh đang phát triển. Hãy đọc cho bé thật nhiều sách truyện đầy màu sắc nhé.', body_zh = '宝宝会翻厚纸板书，还会对图片做出反应？视觉记忆在发展。多给宝宝读读色彩丰富的故事书吧。' WHERE id = '66da2b8a-fe86-40dc-b027-d36d46f5091a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cada día crece un poquito más 📸', body_es = 'Abre ya la Sesión de fotos del bebé y guarda para siempre este momento tan auténtico.', title_fr = 'Il grandit un peu plus chaque jour.📸', body_fr = 'Ouvrez tout de suite la Séance photo bébé et gravez ce moment spontané dans vos souvenirs.', title_hi = 'वह हर दिन थोड़ा और बड़ा हो रहा है।📸', body_hi = 'तुरंत बेबी फ़ोटोशूट खोलिए और उसके इस सच्चे पल को यादों में बसा लीजिए।', title_id = 'Ia tumbuh sedikit demi sedikit setiap hari.📸', body_id = 'Segera buka Sesi Foto Bayi dan abadikan momen tulusnya ini.', title_ja = '毎日少しずつ大きくなっています📸', body_ja = 'すぐに「ベビーフォトセッション」を開いて、この自然な瞬間を記憶に刻みましょう。', title_ko = '아이는 날마다 조금씩 더 자라요.📸', body_ko = '바로 아기 사진 촬영을 열어 이 꾸밈없는 순간을 기억에 새기세요.', title_nl = 'Je kindje groeit elke dag een beetje meer.📸', body_nl = 'Open meteen Babyfotoshoot en leg dit oprechte moment voor altijd vast.', title_pl = 'Z każdym dniem jest coraz większy.📸', body_pl = 'Od razu otwórz Sesję zdjęciową dziecka i uwiecznij tę szczerą chwilę.', title_pt = 'Cresce um pouco mais a cada dia.📸', body_pt = 'Abra já a Sessão Fotográfica do Bebé e grave na memória este momento tão genuíno.', title_sv = 'Barnet växer lite mer för varje dag.📸', body_sv = 'Öppna direkt Babyfotografering och förevig detta äkta ögonblick.', title_vi = 'Mỗi ngày bé lại lớn thêm một chút.📸', body_vi = 'Hãy mở ngay Chụp ảnh cho bé và khắc ghi khoảnh khắc chân thật này.', title_zh = '宝宝每天都在长大一点。📸', body_zh = '马上打开宝宝写真，把这个真情流露的瞬间留在记忆里吧。' WHERE id = '67273a71-3d6d-40e2-b209-34b098335818' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere comer solo 🥄', body_es = 'Te quita la cuchara de la mano porque quiere comer solo. Se le caerá y se manchará, pero es importante para su motricidad. Deja que sea independiente.', title_fr = 'Il veut manger seul 🥄', body_fr = 'Il vous prend la cuillère des mains pour manger tout seul. Ça va couler et salir, mais c''est important pour sa motricité. Laissez-lui son autonomie.', title_hi = 'खुद खाने की ज़िद 🥄', body_hi = 'आपके हाथ से चम्मच लेकर खुद खाना चाहता है। गिरेगा, गंदा होगा, लेकिन यह उसकी मोटर स्किल्स के लिए ज़रूरी है। उसे आत्मनिर्भर बनने दीजिए।', title_id = 'Ngotot makan sendiri 🥄', body_id = 'Ia mengambil sendok dari tangan Anda dan ingin makan sendiri. Pasti tumpah dan berantakan, tapi ini penting untuk motoriknya. Biarkan ia mandiri.', title_ja = '自分で食べたい！🥄', body_ja = 'あなたの手からスプーンを取って、自分で食べたがっています。こぼれて汚れますが、手先の発達にとても大切です。自立を見守ってあげましょう。', title_ko = '혼자 먹겠다는 고집 🥄', body_ko = '엄마 손에서 숟가락을 빼앗아 혼자 먹고 싶어 해요. 흘리고 묻겠지만 운동 능력 발달에 중요해요. 스스로 해 보게 해 주세요.', title_nl = 'Koppig zelf willen eten 🥄', body_nl = 'Je kindje pakt de lepel uit je hand en wil zelf eten. Het wordt een knoeiboel, maar dat is belangrijk voor zijn motoriek. Gun hem zijn zelfstandigheid.', title_pl = 'Upór przy samodzielnym jedzeniu 🥄', body_pl = 'Wyrywa ci łyżeczkę z ręki i chce jeść sam. Będzie rozlane i umazane, ale to ważne dla jego motoryki. Pozwól mu na samodzielność.', title_pt = 'A teimosia de comer sozinho 🥄', body_pt = 'Tira-lhe a colher da mão e quer comer sozinho. Vai entornar e sujar, mas é importante para a motricidade. Dê espaço à independência dele.', title_sv = 'Envis med att äta själv 🥄', body_sv = 'Barnet tar skeden ur din hand och vill äta själv. Det kommer att spillas och kladdas, men det är viktigt för motoriken. Låt barnet vara självständigt.', title_vi = 'Bé nhất định đòi tự ăn 🥄', body_vi = 'Bé giành lấy thìa từ tay mẹ để tự ăn. Sẽ rơi vãi, sẽ lem luốc, nhưng điều này quan trọng cho kỹ năng vận động. Hãy để bé được tự lập.', title_zh = '执意自己吃饭 🥄', body_zh = '宝宝从你手里拿走勺子，想自己吃。会撒、会弄脏，但这对他的动作发育很重要。让他独立一下吧。' WHERE id = 'd17f36fc-9cb8-4df2-a29e-60891f565b13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ha crecido y llega a estantes que antes no alcanzaba. El mueble de la tele, las esquinas... Revisa cuanto antes la seguridad de casa.', body_fr = 'Il a grandi et atteint des étagères qui lui étaient inaccessibles. Meuble TV, coins de table... Revoyez sans tarder la sécurité de la maison.', body_hi = 'उसकी लंबाई बढ़ गई है और अब वह उन शेल्फ़ तक पहुँचता है जहाँ पहले नहीं पहुँचता था। टीवी स्टैंड, कोने... घर की सुरक्षा की तुरंत दोबारा जाँच कीजिए।', body_id = 'Tubuhnya makin tinggi dan bisa meraih rak yang dulu tak terjangkau. Meja TV, sudut-sudut tajam... Segera periksa ulang keamanan rumah.', body_ja = '背が伸びて、前は届かなかった棚に手が届くように。テレビ台、家具の角…すぐに家の安全対策を見直しましょう。', body_ko = '키가 자라서 예전에는 닿지 않던 선반에 손이 닿아요. TV 받침대, 모서리... 집 안 안전을 서둘러 다시 점검하세요.', body_nl = 'Je kindje is gegroeid en kan bij planken waar hij eerst niet bij kon. Tv-meubel, hoeken... Controleer meteen opnieuw de veiligheid in huis.', body_pl = 'Urósł i sięga już półek, do których wcześniej nie dosięgał. Szafka pod telewizor, narożniki... Pilnie sprawdź ponownie bezpieczeństwo w domu.', body_pt = 'Está mais alto e já chega a prateleiras onde antes não chegava. Móvel da televisão, esquinas... Reveja com urgência a segurança da casa.', body_sv = 'Barnet har blivit längre och når hyllor det inte nådde förut. TV-bänken, hörnen... Se över säkerheten i hemmet snarast.', body_vi = 'Bé đã cao lên và với tới những kệ trước đây không với được. Kệ TV, các góc cạnh... Hãy kiểm tra lại an toàn trong nhà ngay nhé.', body_zh = '宝宝长高了，能够到以前够不着的架子了。电视柜、桌角……赶紧重新检查一遍家里的安全。' WHERE id = '145c55e0-770c-4adc-a15b-4bd94389378f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vienen las muelas? 🦷', body_es = '¿Tiene las encías hinchadas y se mete la mano en la boca? Puede que le estén saliendo los dientes de atrás. Revisa el Seguimiento de dentición y dale mordedores fríos.', title_fr = 'Les molaires arrivent ? 🦷', body_fr = 'Ses gencives sont gonflées et il met ses mains à la bouche ? Ce sont peut-être les dents du fond. Consultez le Suivi des dents et donnez-lui des anneaux de dentition froids.', title_hi = 'दाढ़ें आ रही हैं? 🦷', body_hi = 'मसूड़े सूज गए हैं और हाथ मुँह में डालता है? पीछे के दाँत निकल रहे हो सकते हैं। दाँत निकलने का ट्रैकर देखिए और ठंडे टीदर दीजिए।', title_id = 'Geraham sedang tumbuh? 🦷', body_id = 'Gusinya bengkak dan ia memasukkan tangan ke mulut? Mungkin gigi belakangnya sedang tumbuh. Cek Pelacak Tumbuh Gigi dan berikan teether dingin.', title_ja = '奥歯が生えてくる？🦷', body_ja = '歯ぐきが腫れて、手を口に入れていますか？奥歯が生えてきているのかもしれません。「歯の生え始めトラッカー」を確認して、冷やした歯がためをあげましょう。', title_ko = '어금니가 나오는 중일까요? 🦷', body_ko = '잇몸이 붓고 손을 입에 넣나요? 안쪽 어금니가 나오는 중일 수 있어요. 이앓이 기록을 확인하고 차갑게 한 치발기를 주세요.', title_nl = 'Kiezen onderweg? 🦷', body_nl = 'Is het tandvlees gezwollen en stopt je kindje zijn handje in zijn mond? Misschien komen de achterste tanden door. Kijk in de Tandjestracker en geef hem koele bijtringen.', title_pl = 'Trzonowce w drodze? 🦷', body_pl = 'Dziąsła są opuchnięte i wkłada rączkę do buzi? Mogą wychodzić tylne zęby. Zajrzyj do narzędzia do śledzenia ząbkowania i podaj schłodzone gryzaki.', title_pt = 'Os molares vêm a caminho? 🦷', body_pt = 'As gengivas estão inchadas e mete a mão na boca? Podem estar a nascer os dentes de trás. Veja o Registo de Dentição e dê-lhe mordedores frios.', title_sv = 'Är kindtänderna på väg? 🦷', body_sv = 'Är tandköttet svullet och stoppar barnet handen i munnen? Det kan vara de bakre tänderna som kommer. Kolla Tandspåraren och ge kalla bitringar.', title_vi = 'Răng hàm đang mọc? 🦷', body_vi = 'Nướu bé sưng lên và bé cho tay vào miệng? Có thể răng phía sau đang mọc. Hãy xem Theo dõi mọc răng và đưa bé vòng gặm nướu mát lạnh.', title_zh = '磨牙要来了？🦷', body_zh = '牙龈肿起来，总把手伸进嘴里？可能是后面的牙在长。看看出牙追踪，给他冰凉的牙胶吧。' WHERE id = 'b6ac32de-f983-4a93-89fc-cb209586570b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares de golpe 😭', body_es = '¿Se despierta gritando en mitad de la noche y no se calma? Escucha su llanto con el Análisis del llanto y averigua si es un terror nocturno o dolor.', title_fr = 'Réveils soudains 😭', body_fr = 'Il se réveille en pleine nuit en hurlant et ne se calme pas ? Faites écouter ses pleurs à l''Analyse des pleurs pour savoir s''il s''agit d''une terreur nocturne ou d''une douleur.', title_hi = 'अचानक जागना 😭', body_hi = 'आधी रात को चीखकर जागता है और चुप नहीं होता? क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और जानिए कि यह नाइट टेरर है या दर्द।', title_id = 'Terbangun tiba-tiba 😭', body_id = 'Ia terbangun tengah malam sambil berteriak dan tidak mau diam? Perdengarkan suaranya ke Analisis Tangisan dan cari tahu apakah itu teror tidur atau rasa sakit.', title_ja = '突然の夜泣き 😭', body_ja = '夜中に叫ぶように起きて、泣き止まない？「泣き声分析」で泣き声を聞かせて、夜驚症なのか痛みなのかを探りましょう。', title_ko = '갑자기 깨요 😭', body_ko = '한밤중에 소리 지르며 깨서 울음을 그치지 않나요? 울음 분석으로 소리를 들려주어 야경증인지 통증인지 알아보세요.', title_nl = 'Plots wakker 😭', body_nl = 'Wordt je kindje midden in de nacht krijsend wakker en stopt het niet? Laat Huilanalyse naar het huilen luisteren en ontdek of het een nachtmerrie of pijn is.', title_pl = 'Nagłe pobudki 😭', body_pl = 'W środku nocy budzi się z krzykiem i nie przestaje? Pozwól Analizie płaczu posłuchać jego głosu i ustal, czy to lęk nocny, czy ból.', title_pt = 'Despertares repentinos 😭', body_pt = 'Acorda a meio da noite aos gritos e não se acalma? Deixe a Análise do Choro ouvir o choro e descubra se é um terror noturno ou dor.', title_sv = 'Plötsliga uppvaknanden 😭', body_sv = 'Vaknar barnet mitt i natten, skriker och slutar inte? Låt Gråtanalys lyssna på ljudet och ta reda på om det är nattskräck eller smärta.', title_vi = 'Thức giấc đột ngột 😭', body_vi = 'Nửa đêm bé thức dậy la hét và không chịu nín? Hãy cho Phân tích tiếng khóc nghe để biết đó là cơn hoảng sợ khi ngủ hay do đau.', title_zh = '突然惊醒 😭', body_zh = '半夜尖叫着醒来，怎么也停不下来？用哭声分析听一听，弄清楚是夜惊还是疼痛。' WHERE id = '4139adbd-6ed1-4e3e-a4dc-01c65b9d8182' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se tira al suelo cuando no consigue lo que quiere? Son las famosas rabietas de esta etapa. Mantén la calma, mírale a los ojos y dile «estoy aquí contigo».', body_fr = 'Il se jette par terre quand il n''obtient pas ce qu''il veut ? Ce sont les fameuses crises des tout-petits. Gardez votre calme, regardez-le dans les yeux et dites-lui « je suis là ».', body_hi = 'मन का न होने पर खुद को ज़मीन पर पटकता है? टॉडलर दौर के मशहूर नखरे। शांत रहिए, उससे आँख मिलाइए और कहिए ''मैं तुम्हारे पास हूँ''।', body_id = 'Ia menjatuhkan diri ke lantai saat keinginannya tidak dituruti? Inilah tantrum khas masa balita. Tetap tenang, tatap matanya, dan katakan "Mama di sini".', body_ja = '思いどおりにならないと床にひっくり返りますか？幼児期によくあるかんしゃくです。落ち着いて目を合わせ、「そばにいるよ」と伝えましょう。', body_ko = '원하는 대로 안 되면 바닥에 드러눕나요? 토들러 시기의 유명한 떼쓰기예요. 침착함을 지키고 눈을 맞추며 ''엄마가 옆에 있어''라고 말해 주세요.', body_nl = 'Gooit je kindje zich op de grond als hij zijn zin niet krijgt? De bekende driftbuien van de dreumestijd. Blijf kalm, maak oogcontact en zeg: ik ben bij je.', body_pl = 'Rzuca się na podłogę, gdy nie dostaje tego, czego chce? To słynne napady złości małego dziecka. Zachowaj spokój, nawiąż kontakt wzrokowy i powiedz: „Jestem przy tobie”.', body_pt = 'Atira-se para o chão quando não consegue o que quer? São as famosas birras da fase de criança pequena. Mantenha a calma, olhe-o nos olhos e diga-lhe "estou aqui".', body_sv = 'Kastar sig barnet på golvet när det inte får som det vill? Småbarnsårens kända utbrott. Behåll lugnet, sök ögonkontakt och säg ”jag är här”.', body_vi = 'Không được như ý là bé ném mình xuống sàn? Đây là những cơn ăn vạ nổi tiếng của giai đoạn chập chững. Hãy giữ bình tĩnh, nhìn vào mắt bé và nói "mẹ ở đây".', body_zh = '要不到想要的就往地上一躺？这是幼儿期出名的发脾气。保持冷静，和宝宝对视，告诉他“我在你身边”。' WHERE id = 'cfd3d5f1-834e-412c-9e3a-a69a0413fbc1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Recuerda con tu pareja aquellos primeros días y las noches sin dormir, y reíd juntos. ¡No ha sido fácil llegar hasta aquí! Es una victoria de equipo.', body_fr = 'Remémorez-vous avec votre conjoint les premiers jours et les nuits blanches, et riez ensemble. Arriver jusqu''ici n''a pas été facile ! C''est une victoire d''équipe.', body_hi = 'अपने साथी के साथ शुरुआती दिनों और उन बिना नींद की रातों को याद करके हँसिए। आप आसानी से इन दिनों तक नहीं पहुँचे हैं! यह टीम की जीत है।', body_id = 'Kenang hari-hari pertama dan malam-malam tanpa tidur itu bersama pasangan, lalu tertawalah bersama. Kalian tidak sampai di titik ini dengan mudah! Ini kemenangan tim.', body_ja = 'パートナーと、はじめのころの眠れない夜を思い出して笑い合いましょう。ここまで来るのは楽ではありませんでしたね！これはチームの勝利です。', body_ko = '배우자와 처음 며칠, 그 잠 못 든 밤들을 떠올리며 함께 웃어 보세요. 여기까지 결코 쉽게 오지 않았어요! 한 팀으로 이룬 승리예요.', body_nl = 'Haal met je partner herinneringen op aan de eerste dagen en die slapeloze nachten, en lach samen. Jullie zijn hier niet zomaar gekomen! Dit is een overwinning als team.', body_pl = 'Powspominaj z partnerem pierwsze dni i te nieprzespane noce, i pośmiejcie się razem. Nie doszliście tu łatwo! To zwycięstwo zespołu.', body_pt = 'Recorde com o seu companheiro os primeiros tempos e aquelas noites sem dormir, e riam-se juntos. Não chegaram aqui com facilidade! É uma vitória de equipa.', body_sv = 'Minns de första dagarna och de sömnlösa nätterna med din partner och skratta tillsammans. Ni har inte nått hit lätt! Det här är en lagseger.', body_vi = 'Hãy cùng bố ôn lại những ngày đầu, những đêm mất ngủ và cười thật vui. Chặng đường đến hôm nay không hề dễ dàng! Đây là chiến thắng của cả đội.', body_zh = '和另一半一起回忆最初的日子、那些不眠之夜，笑一笑吧。走到今天可不容易！这是团队的胜利。' WHERE id = 'd33491b0-9722-4db2-ae48-c019740b7411' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sigue selectivo con la comida? 🥦', body_es = 'Si rechaza algunos alimentos, no te preocupes. Prueba presentaciones distintas y divertidas de Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Il est toujours difficile à table ? 🥦', body_fr = 'S''il refuse certains aliments, ne vous inquiétez pas. Essayez des présentations différentes et amusantes grâce aux Recettes pour bébés qui commencent la diversification.', title_hi = 'खाने में नखरे जारी हैं? 🥦', body_hi = 'अगर वह कुछ खाने मना करता है, तो चिंता मत कीजिए। ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी से अलग और मज़ेदार तरीके से परोसकर देखिए।', title_id = 'Masih pilih-pilih makanan? 🥦', body_id = 'Kalau ia menolak beberapa makanan, jangan khawatir. Coba penyajian yang berbeda dan seru dari Resep untuk bayi yang mulai MPASI.', title_ja = '好き嫌いが続いている？🥦', body_ja = '食べない料理があっても心配いりません。「離乳食を始める赤ちゃんのレシピ」から、ちがう楽しい盛り付けを試してみましょう。', title_ko = '여전히 음식을 가리나요? 🥦', body_ko = '어떤 음식을 거부해도 걱정하지 마세요. 이유식을 시작하는 아기를 위한 레시피에서 색다르고 재미있는 담음새를 시도해 보세요.', title_nl = 'Nog steeds kieskeurig? 🥦', body_nl = 'Weigert je kindje sommige gerechten? Geen zorgen. Probeer andere, leuke manieren van opdienen uit Recepten voor baby''s die met bijvoeding beginnen.', title_pl = 'Wybiórczość w jedzeniu trwa? 🥦', body_pl = 'Jeśli odmawia niektórych dań, nie martw się. Wypróbuj inne, zabawne sposoby podania z Przepisów dla niemowląt rozpoczynających rozszerzanie diety.', title_pt = 'A esquisitice à mesa continua? 🥦', body_pt = 'Se recusa alguns alimentos, não se preocupe. Experimente apresentações diferentes e divertidas das Receitas para bebés em diversificação alimentar.', title_sv = 'Fortsätter kräsenheten? 🥦', body_sv = 'Oroa dig inte om barnet vägrar viss mat. Prova nya och roliga sätt att servera från Recept för bebisar som börjar med fast föda.', title_vi = 'Bé vẫn kén ăn? 🥦', body_vi = 'Nếu bé từ chối một số món, mẹ đừng lo. Hãy thử những cách bày biện mới lạ, vui mắt từ mục Công thức cho bé bắt đầu ăn dặm.', title_zh = '还在挑食？🥦', body_zh = '如果他不肯吃某些食物，别担心。试试食谱板块里辅食宝宝食谱的不同有趣做法吧。' WHERE id = '138aeaf3-e845-4d03-b6db-2a04410076a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahogo emocional 📝', body_es = '¿Ha sido un día agotador? Cuando se duerma, escribe cómo te sientes en el Diario de ánimo y quítate de encima el estrés del día.', title_fr = 'Lâcher prise. 📝', body_fr = 'La journée a été épuisante ? Une fois qu''il dort, évacuez le stress en écrivant vos ressentis dans le Journal d''humeur.', title_hi = 'मन का बोझ हल्का करना। 📝', body_hi = 'बहुत थकाने वाला दिन था? बच्चे के सोने के बाद अपनी भावनाएँ मूड डायरी में लिखकर दिन का तनाव उतार दीजिए।', title_id = 'Melepaskan emosi. 📝', body_id = 'Harinya sangat melelahkan? Setelah si kecil tidur, lepaskan stres hari ini dengan menuliskan perasaan Anda di Buku Harian Suasana Hati.', title_ja = '気持ちを吐き出そう 📝', body_ja = 'とても疲れる一日でしたか？お子さんが寝たら「気分日記」に気持ちを書いて、一日のストレスを手放しましょう。', title_ko = '감정을 털어놓기. 📝', body_ko = '정말 지치는 하루였나요? 아이가 잠들면 기분 일기에 감정을 적으며 하루의 스트레스를 털어 내세요.', title_nl = 'Je gevoelens loslaten. 📝', body_nl = 'Was het een erg vermoeiende dag? Schrijf je gevoelens op in je Stemmingsdagboek als je kindje slaapt en laat de stress van de dag van je afglijden.', title_pl = 'Emocjonalne odreagowanie. 📝', body_pl = 'To był bardzo męczący dzień? Gdy maluszek zaśnie, zapisz swoje uczucia w Dzienniku nastroju i zrzuć z siebie stres dnia.', title_pt = 'Desabafo emocional. 📝', body_pt = 'Foi um dia muito cansativo? Quando ele adormecer, escreva o que sente no Diário de Humor e liberte-se do stress do dia.', title_sv = 'Känslomässig urladdning. 📝', body_sv = 'Har det varit en väldigt tröttsam dag? Skriv dina känslor i Humördagboken när barnet somnat och släpp dagens stress.', title_vi = 'Giải tỏa cảm xúc. 📝', body_vi = 'Hôm nay thật mệt mỏi? Khi bé ngủ, hãy viết cảm xúc vào Nhật ký tâm trạng để trút bỏ căng thẳng trong ngày.', title_zh = '释放情绪 📝', body_zh = '今天特别累？宝宝睡着后，把感受写进心情日记，卸下一天的压力。' WHERE id = '2f302f24-3142-4182-84a0-2782c5ce8394' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Maratón dentro de casa! 🏃‍♂', body_es = 'Ya no le basta con andar, ¡parece que quiere correr! Disfruta del sonido de sus piececitos, pero no le quites el ojo de encima.', title_fr = 'Marathon à la maison ! 🏃‍♂', body_fr = 'Marcher ne lui suffit plus, on dirait qu''il essaie de courir. Profitez du bruit de ses petits pas, mais ne le quittez pas des yeux !', title_hi = 'घर के अंदर मैराथन! 🏃‍♂', body_hi = 'अब उसे सिर्फ़ चलना काफ़ी नहीं, जैसे दौड़ने की कोशिश कर रहा हो। नन्हे पैरों की टप-टप का आनंद लीजिए, लेकिन उससे नज़र मत हटाइए!', title_id = 'Maraton di dalam rumah! 🏃‍♂', body_id = 'Berjalan saja tidak cukup, ia seperti mencoba berlari. Nikmati suara tapak kaki mungilnya, tapi jangan lepaskan pandangan darinya!', title_ja = '家の中でマラソン！🏃‍♂', body_ja = 'もう歩くだけでは物足りず、走ろうとしているみたい。小さな足のパタパタという音を楽しみつつ、目を離さないでくださいね！', title_ko = '집 안 마라톤! 🏃‍♂', body_ko = '이제 걷는 걸로는 부족해서 뛰려는 것 같아요. 작은 발이 콩콩대는 소리를 즐기되, 눈은 떼지 마세요!', title_nl = 'Een marathon door het huis! 🏃‍♂', body_nl = 'Lopen is niet meer genoeg, je kindje probeert bijna te rennen. Geniet van het getrippel van die kleine voetjes, maar houd hem goed in het oog!', title_pl = 'Maraton po domu! 🏃‍♂', body_pl = 'Samo chodzenie mu już nie wystarcza, jakby próbował biegać. Ciesz się tupotem małych stópek, ale nie spuszczaj go z oka!', title_pt = 'Maratona dentro de casa! 🏃‍♂', body_pt = 'Já não se contenta em andar, parece que tenta correr. Aproveite o som dos pezinhos a correr, mas não tire os olhos dele!', title_sv = 'Maraton inomhus! 🏃‍♂', body_sv = 'Barnet nöjer sig inte längre med att gå, det verkar försöka springa. Njut av de små fötternas tripp-trapp, men släpp inte barnet med blicken!', title_vi = 'Marathon trong nhà! 🏃‍♂', body_vi = 'Bé không chỉ đi mà còn như đang cố chạy. Hãy tận hưởng tiếng bước chân nhỏ lạch bạch, nhưng đừng rời mắt khỏi bé nhé!', title_zh = '家里的马拉松！🏃‍♂', body_zh = '光走路已经满足不了他，好像要跑起来了。享受小脚丫啪嗒啪嗒的声音吧，但眼睛也别离开他！' WHERE id = '8b269aa5-a26e-4c52-b247-14a7194a3d35' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Carreras al aire libre 🌳', body_es = '¿No consigue gastar energía en casa? Salid juntos a tomar el aire y deja que corretee libremente por el parque hasta cansarse.', title_fr = 'Courses-poursuites en plein air. 🌳', body_fr = 'Il n''arrive pas à se défouler à la maison ? Sortez ensemble prendre l''air et laissez-le se promener librement au parc jusqu''à bien se fatiguer.', title_hi = 'खुली हवा में पकड़म-पकड़ाई। 🌳', body_hi = 'घर में ऊर्जा नहीं निकाल पा रहा? साथ में ताज़ी हवा में निकलिए, उसे पार्क में खुलकर घूमने और जी भरकर थकने दीजिए।', title_id = 'Kejar-kejaran di luar ruangan. 🌳', body_id = 'Ia tidak bisa menyalurkan energinya di dalam rumah? Ayo keluar menghirup udara segar bersama, biarkan ia bebas berjalan di taman sampai puas dan lelah.', title_ja = 'お外で追いかけっこ 🌳', body_ja = '家の中ではエネルギーを発散しきれない？一緒に外の空気を吸いに出かけて、公園で思いきり歩き回らせてあげましょう。', title_ko = '바깥에서 술래잡기. 🌳', body_ko = '집 안에서 에너지를 다 쓰지 못하나요? 함께 신선한 공기를 마시러 나가 공원에서 마음껏 걷고 실컷 지치게 해 주세요.', title_nl = 'Rennen en spelen in de buitenlucht. 🌳', body_nl = 'Kan je kindje zijn energie binnen niet kwijt? Ga samen naar buiten en laat hem vrij rondlopen in het park tot hij lekker moe is.', title_pl = 'Gonitwy na świeżym powietrzu. 🌳', body_pl = 'Nie może wyładować energii w domu? Wyjdźcie razem na świeże powietrze, niech swobodnie pobiega po parku i porządnie się zmęczy.', title_pt = 'Correrias ao ar livre. 🌳', body_pt = 'Em casa não consegue gastar energia? Saiam juntos para o ar livre e deixe-o andar à vontade no parque até se cansar.', title_sv = 'Jagalekar utomhus. 🌳', body_sv = 'Kan barnet inte få ut energin inomhus? Gå ut i friska luften tillsammans och låt barnet gå fritt i parken tills det blir ordentligt trött.', title_vi = 'Đuổi bắt ngoài trời. 🌳', body_vi = 'Ở trong nhà bé không xả được năng lượng? Hãy cùng bé ra ngoài hít thở không khí trong lành, để bé tự do chạy nhảy ở công viên đến khi thấm mệt.', title_zh = '户外追逐游戏 🌳', body_zh = '在家里释放不了精力？一起出去呼吸新鲜空气，让他在公园里自由奔跑，玩个够吧。' WHERE id = '8ee97257-b3d6-4144-ad9a-91e2e54c967a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Ayudante en acción! 🧹', body_es = '¿Está deseando coger un trapo para quitar el polvo o jugar con la escoba? Que te imite es la parte más tierna de su aprendizaje.', title_fr = 'Petit assistant au travail ! 🧹', body_fr = 'Il veut prendre un chiffon pour épousseter ou jouer avec le balai ? Qu''il vous imite est la plus jolie partie de son apprentissage.', title_hi = 'मददगार काम पर! 🧹', body_hi = 'हाथ में कपड़ा लेकर धूल पोंछने या झाड़ू से खेलने को उत्सुक है? आपकी नकल करना उसके सीखने का सबसे प्यारा हिस्सा है।', title_id = 'Asisten sedang bekerja! 🧹', body_id = 'Ia ingin mengambil kain untuk membersihkan debu atau bermain dengan sapu? Meniru Anda adalah bagian paling manis dari proses belajarnya.', title_ja = 'お手伝いさんが活躍中！🧹', body_ja = '布を持ってほこりを拭いたり、ほうきで遊んだりしたがりますか？あなたのまねをするのは、学びのいちばんかわいい部分です。', title_ko = '도우미 작업 중! 🧹', body_ko = '걸레를 들고 먼지를 닦거나 빗자루로 놀고 싶어 하나요? 엄마를 따라 하는 건 배움의 과정에서 가장 사랑스러운 부분이에요.', title_nl = 'Hulpje aan het werk! 🧹', body_nl = 'Wil je kindje met een doekje afstoffen of met de bezem spelen? Dat hij jou nadoet, is het liefste deel van zijn leerproces.', title_pl = 'Pomocnik przy pracy! 🧹', body_pl = 'Rwie się, by wziąć ściereczkę i ścierać kurze albo bawić się miotłą? Naśladowanie cię to najsłodsza część jego nauki.', title_pt = 'Ajudante em ação! 🧹', body_pt = 'Quer pegar num pano para limpar o pó ou brincar com a vassoura? Imitá-la é a parte mais doce do processo de aprendizagem.', title_sv = 'Hjälpredan i arbete! 🧹', body_sv = 'Vill barnet ta en trasa och damma eller leka med sopborsten? Att barnet härmar dig är den sötaste delen av inlärningen.', title_vi = 'Người phụ giúp đang làm việc! 🧹', body_vi = 'Bé háo hức cầm khăn lau bụi hay chơi với cây chổi? Bắt chước mẹ là phần đáng yêu nhất trong quá trình học hỏi của bé.', title_zh = '小帮手上岗啦！🧹', body_zh = '宝宝抢着拿抹布擦灰，或者玩扫帚？模仿你是他学习过程中最可爱的部分。' WHERE id = 'e84402f2-45d4-40ce-ae96-610f12a3e06b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rutina de sueño da seguridad 🌙', body_es = 'Repetir cada noche los mismos pasos (baño, cuento, bajar las luces) le ayudará a dormirse más tranquilo.', title_fr = 'Le rituel du coucher rassure. 🌙', body_fr = 'Les mêmes gestes, dans le même ordre chaque soir (bain, histoire, lumière tamisée), l''aideront à s''endormir plus sereinement.', title_hi = 'नींद का रूटीन भरोसा देता है। 🌙', body_hi = 'हर शाम एक ही क्रम में किए जाने वाले काम (स्नान, कहानी, रोशनी धीमी करना) उसे ज़्यादा आराम से सोने में मदद करेंगे।', title_id = 'Rutinitas tidur memberi rasa aman. 🌙', body_id = 'Kegiatan dengan urutan yang sama setiap malam (mandi, dongeng, meredupkan lampu) akan membantunya tertidur lebih nyaman.', title_ja = '寝る前の習慣は安心につながります 🌙', body_ja = '毎晩同じ順番で過ごすこと（お風呂、お話、照明を暗くする）で、よりスムーズに眠れるようになります。', title_ko = '수면 루틴은 안정감을 줘요. 🌙', body_ko = '매일 저녁 같은 순서로 하는 일들(목욕, 동화, 조명 낮추기)이 더 편하게 잠드는 데 도움이 될 거예요.', title_nl = 'Een slaapritueel geeft zekerheid. 🌙', body_nl = 'Elke avond dezelfde volgorde (badje, verhaaltje, lichten dimmen) helpt je kindje rustiger in slaap te vallen.', title_pl = 'Rytuał przed snem daje poczucie bezpieczeństwa. 🌙', body_pl = 'Czynności wykonywane co wieczór w tej samej kolejności (kąpiel, bajka, przygaszone światła) pomogą mu spokojniej zasnąć.', title_pt = 'A rotina de sono dá segurança. 🌙', body_pt = 'Repetir todas as noites os mesmos passos pela mesma ordem (banho, história, luzes mais baixas) vai ajudá-lo a adormecer com mais tranquilidade.', title_sv = 'Sömnrutinen ger trygghet. 🌙', body_sv = 'Samma ordning varje kväll (bad, saga, dämpat ljus) hjälper barnet att somna lugnare.', title_vi = 'Nếp ngủ mang lại cảm giác an toàn. 🌙', body_vi = 'Những việc làm theo cùng một trình tự mỗi tối (tắm, kể chuyện, giảm đèn) sẽ giúp bé dễ đi vào giấc ngủ hơn.', title_zh = '睡前习惯带来安全感 🌙', body_zh = '每晚按同样的顺序做同样的事（洗澡、讲故事、调暗灯光），能帮宝宝更轻松地入睡。' WHERE id = 'ed63e2e3-10b5-4bd6-9b06-a81622e913eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Entiende las palabras 🧠', body_es = '¿Cuando le dices «Trae los zapatos» los encuentra y te los trae? Su inteligencia avanza a toda velocidad. ¡Elógiale y anímale mucho!', title_fr = 'Il comprend les mots. 🧠', body_fr = 'Quand vous dites « Apporte tes chaussures », il les trouve et vous les apporte ? Son intelligence se développe à toute vitesse. Félicitez-le et encouragez-le beaucoup !', title_hi = 'शब्द समझने का हुनर। 🧠', body_hi = '''जूते लाओ'' कहने पर वह ढूँढकर ले आता है? यह दिखाता है कि उसका दिमाग तेज़ी से विकसित हो रहा है। खूब तारीफ़ करके हौसला बढ़ाइए!', title_id = 'Kemampuan memahami kata. 🧠', body_id = 'Saat Anda bilang "Ambil sepatunya", ia menemukan dan membawanya? Ini tanda kecerdasannya berkembang pesat. Puji dan semangati ia sebanyak-banyaknya!', title_ja = '言葉がわかる力 🧠', body_ja = '「靴を持ってきて」と言うと、探して持ってきてくれますか？知性がぐんぐん育っている証拠です。たっぷり褒めて励ましましょう！', title_ko = '말을 이해하는 능력. 🧠', body_ko = '"신발 가져와" 하면 찾아서 가져오나요? 두뇌가 빠르게 발달하고 있다는 뜻이에요. 듬뿍 칭찬하고 격려해 주세요!', title_nl = 'Woorden begrijpen. 🧠', body_nl = 'Zoekt en brengt je kindje zijn schoenen als je zegt: haal je schoenen? Dat laat zien hoe snel zijn verstand zich ontwikkelt. Prijs hem en moedig hem volop aan!', title_pl = 'Rozumienie słów. 🧠', body_pl = 'Na „Przynieś buty” znajduje je i przynosi? To pokazuje, jak szybko rozwija się jego umysł. Chwal go i zachęcaj jak najczęściej!', title_pt = 'A capacidade de compreender palavras. 🧠', body_pt = 'Quando lhe diz "Traz os sapatos", ele encontra-os e traz-lhos? Isso mostra que a inteligência dele se desenvolve depressa. Elogie-o e encoraje-o muito!', title_sv = 'Förmågan att förstå ord. 🧠', body_sv = 'Hittar barnet skorna och kommer med dem när du säger ”Hämta skorna”? Det visar att intelligensen utvecklas snabbt. Beröm och uppmuntra massor!', title_vi = 'Khả năng hiểu từ ngữ. 🧠', body_vi = 'Mẹ nói "Mang giày lại đây" là bé tìm và mang đến? Điều này cho thấy trí tuệ của bé đang phát triển nhanh chóng. Hãy khen ngợi và khích lệ bé thật nhiều!', title_zh = '理解词语的能力 🧠', body_zh = '你说“把鞋拿来”，他会找到拿给你？这说明他的智力在快速发展。多夸夸他、鼓励他吧！' WHERE id = 'ae5acd1f-b8cf-43ad-b265-37b9e76b0c35' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas energía 🥗', body_es = 'Te pasas el día de pie. No olvides prepararte un tentempié rico y lleno de vitaminas.', title_fr = 'Vous aussi avez besoin d''énergie. 🥗', body_fr = 'Vous êtes debout toute la journée. N''oubliez pas de vous préparer un en-cas vitaminé et savoureux.', title_hi = 'आपको भी ऊर्जा चाहिए। 🥗', body_hi = 'आप पूरे दिन खड़ी रहती हैं। अपने लिए विटामिन भरा और स्वादिष्ट स्नैक बनाना मत भूलिए।', title_id = 'Anda juga butuh energi. 🥗', body_id = 'Seharian Anda terus berdiri. Jangan lupa menyiapkan camilan lezat kaya vitamin untuk diri sendiri.', title_ja = 'あなたにもエネルギーが必要です 🥗', body_ja = '一日中立ちっぱなしですね。自分のためにも、ビタミンたっぷりでおいしいおやつを用意するのを忘れずに。', title_ko = '엄마에게도 에너지가 필요해요. 🥗', body_ko = '하루 종일 서 있었죠. 나를 위한 비타민 가득하고 맛있는 간식을 챙기는 것도 잊지 마세요.', title_nl = 'Ook jij hebt energie nodig. 🥗', body_nl = 'Je staat de hele dag op je benen. Vergeet niet een vitaminerijk, lekker tussendoortje voor jezelf te maken.', title_pl = 'Ty też potrzebujesz energii. 🥗', body_pl = 'Cały dzień jesteś na nogach. Nie zapomnij przygotować sobie smacznej przekąski pełnej witamin.', title_pt = 'Também precisa de energia. 🥗', body_pt = 'Passa o dia todo de pé. Não se esqueça de preparar para si um lanche saboroso e cheio de vitaminas.', title_sv = 'Du behöver också energi. 🥗', body_sv = 'Du är på benen hela dagen. Glöm inte att göra ett vitaminrikt och gott mellanmål åt dig själv.', title_vi = 'Mẹ cũng cần năng lượng. 🥗', body_vi = 'Cả ngày mẹ đứng không ngơi chân. Đừng quên làm cho mình một món ăn nhẹ ngon miệng và giàu vitamin nhé.', title_zh = '你也需要能量 🥗', body_zh = '你站了一整天。别忘了给自己做一份富含维生素的美味小点心。' WHERE id = 'ce1fc21a-8f96-4c92-b928-5126f2240b1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Rabietas? 🌪', body_es = '️ Cuando no puede expresarse, puede enfadarse y llorar. Si necesitas apoyo con esto, consulta a Anacan AI y aprende a afrontarlo bien.', title_fr = 'Des crises de colère ? 🌪', body_fr = '️ Quand il n''arrive pas à s''exprimer, il peut s''énerver et pleurer. Si vous avez besoin de soutien, demandez conseil à Anacan AI pour trouver la bonne approche.', title_hi = 'गुस्से के दौरे? 🌪', body_hi = '️ अपनी बात न कह पाने पर वह चिढ़कर रो सकता है। अगर इसमें आपको मदद चाहिए, तो Anacan AI से सलाह लेकर सही तरीका जानिए।', title_id = 'Ledakan amarah? 🌪', body_id = '️ Saat belum bisa mengungkapkan diri, ia bisa kesal dan menangis. Kalau Anda butuh dukungan soal ini, konsultasikan dengan Anacan AI dan pelajari cara menghadapinya dengan tepat.', title_ja = 'かんしゃく？🌪', body_ja = '️うまく気持ちを伝えられないと、イライラして泣くことがあります。サポートが必要なら、Anacan AIに相談して、適切な接し方を学びましょう。', title_ko = '분노 발작? 🌪', body_ko = '️자신을 표현하지 못하면 화가 나서 울 수 있어요. 도움이 필요하다면 Anacan AI와 상담해 올바른 대처법을 알아보세요.', title_nl = 'Driftbuien? 🌪', body_nl = '️ Je kindje kan boos worden en huilen als hij zich niet kan uiten. Heb je hierbij steun nodig? Overleg met Anacan AI en ontdek de juiste aanpak.', title_pl = 'Napady złości? 🌪', body_pl = '️ Gdy nie umie się wyrazić, może się złościć i płakać. Jeśli potrzebujesz w tym wsparcia, poradź się Anacan AI i poznaj właściwe podejście.', title_pt = 'Crises de birra? 🌪', body_pt = '️ Quando não se consegue expressar, pode irritar-se e chorar. Se precisar de apoio nisso, fale com o Anacan AI e aprenda a abordagem certa.', title_sv = 'Ilskeutbrott? 🌪', body_sv = '️ Barnet kan bli argt och gråta när det inte kan uttrycka sig. Om du behöver stöd, rådfråga Anacan AI och lär dig rätt förhållningssätt.', title_vi = 'Những cơn giận dữ? 🌪', body_vi = '️ Khi chưa diễn đạt được, bé có thể bực bội và khóc. Nếu mẹ cần hỗ trợ, hãy hỏi ý kiến Anacan AI để biết cách ứng xử đúng.', title_zh = '发脾气崩溃？🌪', body_zh = '️ 表达不出来时，宝宝可能会着急哭闹。如果你需要这方面的支持，可以咨询Anacan AI，学习正确的应对方法。' WHERE id = 'd8cf1dda-3655-48e8-9316-6481b7ea82ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El turno de papá 👨‍🍼', body_es = 'Hoy deja a papá el turno del cuento y de acostarle, y regálate un pequeño descanso.', title_fr = 'Au tour de papa. 👨‍🍼', body_fr = 'Ce soir, confiez à papa l''histoire du soir et le coucher, et offrez-vous une petite pause.', title_hi = 'पापा की बारी। 👨‍🍼', body_hi = 'आज शाम कहानी सुनाने और सुलाने की बारी पापा को सौंपिए और खुद को छोटा सा ब्रेक दीजिए।', title_id = 'Giliran ayah. 👨‍🍼', body_id = 'Hari ini, serahkan giliran membacakan dongeng dan menidurkan si kecil kepada ayah, dan beri diri Anda jeda sejenak.', title_ja = 'パパの番 👨‍🍼', body_ja = '今夜は寝る前の読み聞かせと寝かしつけをパパにお願いして、自分に小さな休憩をあげましょう。', title_ko = '아빠 차례예요. 👨‍🍼', body_ko = '오늘은 저녁 동화 읽기와 재우기를 아빠에게 맡기고 엄마는 잠깐 쉬어 가세요.', title_nl = 'Papa is aan de beurt. 👨‍🍼', body_nl = 'Laat het voorlezen en naar bed brengen vandaag aan papa over en gun jezelf een kleine pauze.', title_pl = 'Zmiana taty. 👨‍🍼', body_pl = 'Dziś wieczorem przekaż tacie czytanie bajki i usypianie, a sobie daj małą przerwę.', title_pt = 'A vez do pai. 👨‍🍼', body_pt = 'Hoje, entregue ao pai a vez de ler a história da noite e de o adormecer, e dê a si própria uma pequena pausa.', title_sv = 'Pappas tur. 👨‍🍼', body_sv = 'Lämna kvällssagan och nattningen till pappa i dag och ge dig själv en liten paus.', title_vi = 'Đến lượt bố. 👨‍🍼', body_vi = 'Tối nay hãy giao việc kể chuyện và ru bé ngủ cho bố, còn mẹ thì cho mình nghỉ ngơi một chút.', title_zh = '轮到爸爸了 👨‍🍼', body_zh = '今天把讲睡前故事和哄睡的任务交给爸爸，给自己一个小小的休息。' WHERE id = '2b9c6af1-1706-4704-b2ce-29e57d4866f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de construir torres 🧱', body_es = 'Apilar 3-4 cubos y tirarlos es uno de sus pasatiempos favoritos. Este juego desarrolla muy rápido la coordinación ojo-mano.', title_fr = 'L''art de construire des tours. 🧱', body_fr = 'Empiler 3-4 cubes puis tout faire tomber est l''une de ses activités préférées. Ce jeu développe très vite sa coordination œil-main.', title_hi = 'मीनार बनाने की कला। 🧱', body_hi = '3-4 ब्लॉक एक के ऊपर एक रखकर गिराना उसके सबसे पसंदीदा कामों में से एक है। यह खेल आँख-हाथ के तालमेल को तेज़ी से विकसित करता है।', title_id = 'Seni membangun menara. 🧱', body_id = 'Menumpuk 3-4 balok lalu merobohkannya adalah salah satu kegiatan favoritnya. Permainan ini mengembangkan koordinasi mata-tangannya dengan pesat.', title_ja = 'タワーづくりの名人 🧱', body_ja = '積み木を3-4個重ねてはくずすのが、お気に入りの遊びのひとつ。この遊びで目と手の協調がぐんぐん育ちます。', title_ko = '탑 쌓기의 기술. 🧱', body_ko = '블록 3-4개를 쌓았다가 무너뜨리는 게 가장 좋아하는 놀이 중 하나예요. 이 놀이는 눈과 손의 협응력을 빠르게 키워 줘요.', title_nl = 'De kunst van torens bouwen. 🧱', body_nl = '3-4 blokken op elkaar zetten en ze weer omgooien is een van zijn favoriete bezigheden. Dit spel ontwikkelt snel de oog-handcoördinatie.', title_pl = 'Sztuka budowania wież. 🧱', body_pl = 'Ustawianie 3-4 klocków jeden na drugim i burzenie wieży to jedno z jego ulubionych zajęć. Ta zabawa szybko rozwija koordynację wzrokowo-ruchową.', title_pt = 'A arte de construir torres. 🧱', body_pt = 'Empilhar 3-4 cubos e depois deitá-los abaixo é uma das brincadeiras preferidas. Este jogo desenvolve depressa a coordenação olho-mão.', title_sv = 'Konsten att bygga torn. 🧱', body_sv = 'Att stapla 3-4 klossar och sedan välta dem är en av favoritsysselsättningarna. Leken utvecklar öga-hand-koordinationen snabbt.', title_vi = 'Nghệ thuật xây tháp. 🧱', body_vi = 'Chồng 3-4 khối lên nhau rồi xô đổ là một trong những trò bé thích nhất. Trò chơi này giúp phát triển nhanh khả năng phối hợp tay mắt.', title_zh = '搭高塔的艺术 🧱', body_zh = '把3-4块积木摞起来再推倒，是他最爱的游戏之一。这个游戏能快速提升手眼协调能力。' WHERE id = '8db205c2-0561-48d8-8b6c-61fc68065e2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comodidad fuera de casa ☕', body_es = '¿Agobiada de la rutina diaria? Encuentra en Lugares para mamás una cafetería a la que entrar cómodamente con el carrito y tómate un descanso con un café.', title_fr = 'Se détendre hors de la maison. ☕', body_fr = 'La routine vous pèse ? Trouvez dans les Lieux adaptés aux mamans un café où entrer facilement avec la poussette, et faites une pause café.', title_hi = 'घर से बाहर सुकून। ☕', body_hi = 'रोज़ के रूटीन से ऊब गई हैं? माँ के लिए अनुकूल जगहों में ऐसा कैफ़े ढूँढिए जहाँ स्ट्रॉलर के साथ आराम से जा सकें, और कॉफ़ी ब्रेक लीजिए।', title_id = 'Nyaman di luar rumah. ☕', body_id = 'Bosan dengan rutinitas sehari-hari? Temukan kafe yang mudah dimasuki dengan stroller di Tempat Ramah Ibu dan nikmati rehat kopi.', title_ja = 'お出かけ先でほっとひと息 ☕', body_ja = '毎日の繰り返しに疲れていませんか？「ママにやさしいスポット」でベビーカーでも入りやすいカフェを見つけて、コーヒーブレイクを楽しみましょう。', title_ko = '집 밖에서 찾는 여유. ☕', body_ko = '똑같은 일상이 답답한가요? 엄마 친화 장소에서 유모차로 편하게 들어갈 수 있는 카페를 찾아 커피 한 잔의 여유를 가져 보세요.', title_nl = 'Ontspannen buiten de deur. ☕', body_nl = 'Zit je vast in de dagelijkse routine? Zoek in Mamavriendelijke plekken een café waar je makkelijk met de kinderwagen binnenkomt en neem een koffiepauze.', title_pl = 'Wygoda poza domem. ☕', body_pl = 'Codzienna rutyna cię przytłacza? Znajdź w Miejscach przyjaznych mamom kawiarnię, do której łatwo wjedziesz wózkiem, i zrób sobie przerwę na kawę.', title_pt = 'Conforto fora de casa. ☕', body_pt = 'Está cansada da rotina diária? Encontre nos Locais Amigos das Mães um café onde entre à vontade com o carrinho e faça uma pausa para um café.', title_sv = 'Avkoppling utanför hemmet. ☕', body_sv = 'Trött på vardagsrutinen? Hitta ett kafé i Mammavänliga platser dit du lätt kommer in med barnvagnen och ta en kaffepaus.', title_vi = 'Thoải mái bên ngoài ngôi nhà. ☕', body_vi = 'Mẹ thấy ngột ngạt với nếp sinh hoạt hằng ngày? Hãy tìm một quán cà phê có thể vào thoải mái với xe đẩy trong Địa điểm thân thiện với mẹ và nghỉ uống cà phê nhé.', title_zh = '在外面放松一下 ☕', body_zh = '厌倦了日常重复？在妈妈友好场所里找一家推婴儿车也能轻松进出的咖啡馆，来个咖啡时间吧。' WHERE id = 'e513a042-7558-4dae-8bc5-5e2b5e5d74fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del ruido blanco 🎶', body_es = 'Si después de un día tan activo no consigue dormirse, pon el sonido del mar o de la lluvia en Ruido blanco y crea calma en la habitación.', title_fr = 'La force des bruits blancs. 🎶', body_fr = 'Il n''arrive pas à dormir après une journée active ? Lancez le bruit de l''océan ou de la pluie dans les Bruits blancs pour apaiser la chambre.', title_hi = 'व्हाइट नॉइज़ की ताकत। 🎶', body_hi = 'अगर भाग-दौड़ भरे दिन के असर से वह सो नहीं पा रहा, तो कमरे में व्हाइट नॉइज़ से समुद्र या बारिश की आवाज़ चलाकर शांति बनाइए।', title_id = 'Kekuatan suara putih. 🎶', body_id = 'Kalau ia sulit tidur setelah hari yang aktif, ciptakan ketenangan di kamar dengan memutar suara ombak atau hujan dari Suara Putih.', title_ja = 'ホワイトノイズの力 🎶', body_ja = '活発に過ごした日で寝つけないときは、「ホワイトノイズ」から海や雨の音を流して、部屋を穏やかな雰囲気にしましょう。', title_ko = '백색소음의 힘. 🎶', body_ko = '활발한 하루 때문에 잠들지 못한다면 백색소음에서 파도나 빗소리를 틀어 방을 차분하게 만들어 주세요.', title_nl = 'De kracht van witte ruis. 🎶', body_nl = 'Kan je kindje na een drukke dag niet slapen? Zet in Witte ruis het geluid van de oceaan of regen aan en breng rust in de kamer.', title_pl = 'Moc białego szumu. 🎶', body_pl = 'Jeśli po aktywnym dniu nie może zasnąć, włącz w pokoju odgłos oceanu lub deszczu z Białego szumu i stwórz spokojną atmosferę.', title_pt = 'A força do Ruído Branco. 🎶', body_pt = 'Se não consegue adormecer por causa de um dia agitado, ligue no quarto o som do mar ou da chuva no Ruído Branco e crie tranquilidade.', title_sv = 'Kraften i vitt brus. 🎶', body_sv = 'Om barnet inte kan sova efter en aktiv dag, skapa lugn i rummet genom att sätta på havs- eller regnljud i Vitt brus.', title_vi = 'Sức mạnh của tiếng ồn trắng. 🎶', body_vi = 'Nếu bé không ngủ được sau một ngày hiếu động, hãy bật tiếng sóng biển hoặc tiếng mưa trong Tiếng ồn trắng để căn phòng thêm yên bình.', title_zh = '白噪音的力量 🎶', body_zh = '如果玩了一整天兴奋得睡不着，就在房间里用白噪音放海浪声或雨声，营造安静的氛围。' WHERE id = '6537418f-2c88-443b-b40f-e07f0ccd5801' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ritmo de crecimiento 📏', body_es = '¡Se le vuelve a quedar pequeña la ropa! Añade su nueva altura y su nuevo peso en el Seguimiento del desarrollo y actualiza su gráfica de crecimiento.', title_fr = 'Le rythme de croissance. 📏', body_fr = 'Ses vêtements redeviennent trop petits ! Ajoutez sa nouvelle taille et son nouveau poids dans le Suivi de croissance et mettez à jour sa courbe.', title_hi = 'बढ़ने की रफ़्तार। 📏', body_hi = 'कपड़े फिर छोटे हो रहे हैं! ग्रोथ ट्रैकर सेक्शन में नई लंबाई और वज़न जोड़िए और सेहतमंद विकास का चार्ट अपडेट कीजिए।', title_id = 'Laju pertumbuhan. 📏', body_id = 'Bajunya kekecilan lagi! Tambahkan tinggi dan berat terbarunya di Pelacak Pertumbuhan dan perbarui grafik pertumbuhannya yang sehat.', title_ja = '成長のペース 📏', body_ja = 'お洋服がまた小さくなってきました！「発達トラッカー」に新しい身長と体重を追加して、成長グラフを更新しましょう。', title_ko = '성장 속도. 📏', body_ko = '옷이 또 작아졌어요! 성장 기록에 새 키와 몸무게를 추가하고 건강한 성장 그래프를 업데이트하세요.', title_nl = 'Groeitempo. 📏', body_nl = 'De kleertjes worden alweer te klein! Voeg de nieuwe lengte en het nieuwe gewicht toe in de Groeitracker en werk de gezonde groeicurve bij.', title_pl = 'Tempo wzrostu. 📏', body_pl = 'Ubranka znów robią się za małe! Dodaj nowy wzrost i wagę w sekcji Śledzenie rozwoju i zaktualizuj wykres jego zdrowego rozwoju.', title_pt = 'O ritmo de crescimento. 📏', body_pt = 'A roupa voltou a ficar pequena! Adicione a nova altura e o novo peso no Registo de Desenvolvimento e atualize o gráfico de crescimento saudável.', title_sv = 'Tillväxttakt. 📏', body_sv = 'Kläderna blir för små igen! Lägg in ny längd och vikt i Tillväxtspåraren och uppdatera den friska tillväxtkurvan.', title_vi = 'Nhịp tăng trưởng. 📏', body_vi = 'Quần áo lại chật rồi! Hãy thêm chiều cao và cân nặng mới vào mục Theo dõi phát triển và cập nhật biểu đồ phát triển khỏe mạnh của bé.', title_zh = '成长速度 📏', body_zh = '衣服又变小了！在发育追踪里添加新的身高和体重数据，更新宝宝的健康成长曲线吧。' WHERE id = 'c45968e1-c58f-48dd-a705-2dc4c22325e0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Sus primeras obras de arte! 🖍', body_es = '️ Le encanta garabatear en el papel con ceras gruesas. Observa con mucho amor sus primeras obras de arte.', title_fr = 'Ses premières œuvres d''art ! 🖍', body_fr = '️ Il adore gribouiller sur du papier avec de gros crayons. Regardez ses premières œuvres avec beaucoup d''amour.', title_hi = 'पहली पेंटिंग! 🖍', body_hi = '️ उसे मोटे रंगों से कागज़ पर लकीरें खींचना पसंद है। उसकी पहली कलाकृतियों को ढेर सारे प्यार से देखिए।', title_id = 'Karya seni pertama! 🖍', body_id = '️ Ia senang mencoret-coret kertas dengan krayon tebal. Saksikan karya seni pertamanya dengan penuh cinta.', title_ja = 'はじめての作品！🖍', body_ja = '️太いクレヨンで紙にお絵かきするのが大好き。はじめての作品を、愛情たっぷりに見守りましょう。', title_ko = '첫 그림 작품! 🖍', body_ko = '️굵은 크레용으로 종이에 끄적이는 걸 좋아해요. 첫 작품들을 큰 사랑으로 지켜봐 주세요.', title_nl = 'De eerste kunstwerken! 🖍', body_nl = '️ Je kindje krast graag met dikke verf op papier. Kijk vol liefde naar zijn eerste kunstwerken.', title_pl = 'Pierwsze dzieła sztuki! 🖍', body_pl = '️ Uwielbia bazgrać grubymi kredkami po papierze. Obserwuj jego pierwsze dzieła z ogromną miłością.', title_pt = 'As primeiras obras de arte! 🖍', body_pt = '️ Adora rabiscar no papel com lápis de cor grossos. Acompanhe com muito amor as primeiras obras de arte dele.', title_sv = 'De första konstverken! 🖍', body_sv = '️ Barnet älskar att klottra med tjocka kritor på papper. Följ de första konstverken med stor kärlek.', title_vi = 'Những tác phẩm hội họa đầu tiên! 🖍', body_vi = '️ Bé thích vẽ nguệch ngoạc bằng bút màu to trên giấy. Hãy ngắm nhìn những tác phẩm nghệ thuật đầu tiên của bé bằng tất cả tình yêu thương.', title_zh = '第一批画作！🖍', body_zh = '️ 宝宝喜欢用粗蜡笔在纸上涂鸦。满怀爱意地欣赏他的第一批艺术作品吧。' WHERE id = 'f13027ff-0446-4962-9c51-398d40234b5a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Quiere comer solo! 🥄', body_es = 'Aunque se manche él y todo lo que hay alrededor, deja que sujete la cuchara. Es muy importante para su coordinación muscular y su independencia.', title_fr = 'Il veut manger seul ! 🥄', body_fr = 'Même s''il se salit, lui et tout autour, laissez-le tenir la cuillère lui-même. C''est très important pour sa coordination musculaire et son autonomie.', title_hi = 'खुद खाना चाहता है! 🥄', body_hi = 'भले कपड़े और आसपास सब गंदा हो जाए, उसे चम्मच खुद पकड़ने दीजिए। यह उसकी मांसपेशियों के तालमेल और आत्मनिर्भरता के लिए बहुत ज़रूरी है।', title_id = 'Ingin makan sendiri! 🥄', body_id = 'Meski baju dan sekitarnya jadi kotor, biarkan ia memegang sendok sendiri. Ini sangat penting untuk koordinasi otot dan kemandiriannya.', title_ja = '自分で食べたい！🥄', body_ja = '服やまわりが汚れても、スプーンは自分で持たせてあげましょう。筋肉の協調と自立心にとても大切です。', title_ko = '혼자 먹고 싶어 해요! 🥄', body_ko = '옷과 주변이 엉망이 되더라도 숟가락은 직접 잡게 해 주세요. 근육 협응력과 독립심에 정말 중요해요.', title_nl = 'Wil zelf eten! 🥄', body_nl = 'Ook al wordt alles om hem heen vies, laat hem zelf de lepel vasthouden. Dat is heel belangrijk voor zijn spiercoördinatie en zelfstandigheid.', title_pl = 'Chce jeść sam! 🥄', body_pl = 'Nawet jeśli on i wszystko dookoła się ubrudzi, pozwól mu samemu trzymać łyżeczkę. To bardzo ważne dla koordynacji mięśni i samodzielności.', title_pt = 'Quer comer sozinho! 🥄', body_pt = 'Mesmo que ele e tudo à volta fiquem sujos, deixe-o segurar a colher sozinho. É muito importante para a coordenação muscular e a independência.', title_sv = 'Vill äta själv! 🥄', body_sv = 'Även om barnet och omgivningen blir kladdiga, låt barnet hålla skeden själv. Det är mycket viktigt för muskelkoordinationen och självständigheten.', title_vi = 'Bé muốn tự ăn! 🥄', body_vi = 'Dù lem luốc khắp người và xung quanh, hãy để bé tự cầm thìa. Điều này rất quan trọng cho khả năng phối hợp cơ bắp và sự tự lập của bé.', title_zh = '想自己吃饭！🥄', body_zh = '就算身上和周围都弄脏了，也让他自己拿勺子吧。这对他的肌肉协调和独立性非常重要。' WHERE id = '3b86e3a2-b53e-4603-a4b1-a57fc531000c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Abrazos dulces! 🤗', body_es = 'Que te abrace de repente e intente darte besos es su forma de decirte que te quiere. Disfruta de estos momentos únicos e inmortalízalos en la Sesión de fotos del bebé.', title_fr = 'Câlins tout doux ! 🤗', body_fr = 'Quand il vous serre soudain dans ses bras et essaie de vous embrasser, c''est son langage de l''amour. Savourez ces moments uniques et immortalisez-les dans la Séance photo bébé.', title_hi = 'प्यारी झप्पियाँ! 🤗', body_hi = 'अचानक आपसे लिपट जाना और चूमने की कोशिश करना उसकी प्यार की भाषा है। इन बेमिसाल पलों का आनंद लीजिए और बेबी फ़ोटोशूट में हमेशा के लिए सहेज लीजिए।', title_id = 'Pelukan manis! 🤗', body_id = 'Tiba-tiba memeluk dan mencoba mencium Anda adalah bahasa cintanya. Nikmati momen tak ternilai ini dan abadikan di Sesi Foto Bayi.', title_ja = 'あまいハグ！🤗', body_ja = '突然ぎゅっと抱きついたり、キスしようとしたりするのは、愛情の言葉です。このかけがえのない瞬間を味わって、「ベビーフォトセッション」で残しましょう。', title_ko = '달콤한 포옹! 🤗', body_ko = '갑자기 엄마를 꼭 안고 뽀뽀하려는 건 사랑의 언어예요. 이 무엇과도 바꿀 수 없는 순간을 즐기고 아기 사진 촬영으로 영원히 남기세요.', title_nl = 'Lieve knuffels! 🤗', body_nl = 'Als je kindje je ineens omhelst en probeert te kussen, is dat zijn liefdestaal. Geniet van deze onbetaalbare momenten en leg ze vast in Babyfotoshoot.', title_pl = 'Słodkie przytulasy! 🤗', body_pl = 'Nagłe przytulanie i próby całowania to jego język miłości. Delektuj się tymi bezcennymi chwilami i uwiecznij je w Sesji zdjęciowej dziecka.', title_pt = 'Abraços doces! 🤗', body_pt = 'Abraçá-la de repente e tentar dar-lhe beijinhos é a linguagem do amor. Aproveite estes momentos sem igual e eternize-os na Sessão Fotográfica do Bebé.', title_sv = 'Söta kramar! 🤗', body_sv = 'När barnet plötsligt kramar dig och försöker pussa dig är det kärlekens språk. Njut av dessa makalösa stunder och förevig dem i Babyfotografering.', title_vi = 'Những cái ôm ngọt ngào! 🤗', body_vi = 'Bé bất ngờ ôm và cố hôn mẹ chính là ngôn ngữ của tình yêu. Hãy tận hưởng những khoảnh khắc vô giá này và lưu giữ chúng bằng Chụp ảnh cho bé.', title_zh = '甜蜜的拥抱！🤗', body_zh = '突然抱住你、想亲你，这就是宝宝的爱的语言。好好享受这些无与伦比的瞬间，用宝宝写真永远留住吧。' WHERE id = 'ce4d24a9-fdbd-44df-93c0-058cf5d834aa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de leer 📖', body_es = 'Deja que pase él solo las páginas de los libros ilustrados. Escuchar cuentos con tu voz amplía su vocabulario.', title_fr = 'Le goût des livres. 📖', body_fr = 'Laissez-le tourner lui-même les pages des livres d''images. Écouter des histoires avec votre voix enrichit son vocabulaire.', title_hi = 'किताबें पढ़ने का शौक। 📖', body_hi = 'तस्वीरों वाली किताबों के पन्ने उसे खुद पलटने दीजिए। आपकी आवाज़ में कहानी सुनना उसका शब्द भंडार बढ़ाता है।', title_id = 'Semangat membaca buku. 📖', body_id = 'Biarkan ia membalik sendiri halaman buku bergambar. Mendengarkan dongeng dengan suara Anda menambah kosakatanya.', title_ja = '本が好きになる 📖', body_ja = '絵本のページは自分でめくらせてあげましょう。あなたの声でお話を聞くことで、語彙が増えていきます。', title_ko = '책 읽기의 즐거움. 📖', body_ko = '그림책 책장은 아이가 직접 넘기게 해 주세요. 엄마 목소리로 동화를 들으면 어휘가 늘어나요.', title_nl = 'Zin in boeken. 📖', body_nl = 'Laat je kindje zelf de bladzijden van prentenboeken omslaan. Naar een verhaal luisteren met jouw stem vergroot zijn woordenschat.', title_pl = 'Zamiłowanie do książek. 📖', body_pl = 'Pozwól mu samemu przewracać kartki książeczek z obrazkami. Słuchanie bajek twoim głosem wzbogaca jego zasób słów.', title_pt = 'O gosto pelos livros. 📖', body_pt = 'Deixe-o virar sozinho as páginas dos livros com imagens. Ouvir histórias na sua voz aumenta o vocabulário dele.', title_sv = 'Lust att läsa böcker. 📖', body_sv = 'Låt barnet vända sidorna i bilderböckerna själv. Att lyssna på sagor med din röst ökar ordförrådet.', title_vi = 'Niềm yêu thích đọc sách. 📖', body_vi = 'Hãy để bé tự lật trang sách tranh. Nghe truyện qua giọng của mẹ giúp bé tăng vốn từ.', title_zh = '爱上读书 📖', body_zh = '让宝宝自己翻图画书吧。听着你的声音讲故事，能让他的词汇量增长。' WHERE id = 'fd4e2dc2-dbda-49c0-bcfc-b6880fe0e4a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos su sueño ⏱️', body_es = 'Si ya solo hace una siesta, por la tarde se cansará antes. Puedes adelantar un poco la hora de acostarle.', title_fr = 'On suit son sommeil. ⏱️', body_fr = 'S''il ne fait plus qu''une sieste, il sera fatigué plus tôt le soir. Vous pouvez avancer un peu l''heure du coucher.', title_hi = 'नींद के रूटीन पर नज़र। ⏱️', body_hi = 'अगर दिन की झपकी एक रह गई है, तो वह शाम को जल्दी थकेगा। रात की नींद का समय थोड़ा पहले कर सकती हैं।', title_id = 'Memantau pola tidur. ⏱️', body_id = 'Kalau tidur siangnya sudah jadi satu kali, ia akan lebih cepat lelah di sore hari. Anda bisa sedikit memajukan jam tidur malamnya.', title_ja = '睡眠リズムを見守ろう ⏱️', body_ja = 'お昼寝が1回になったら、夕方は早めに疲れます。夜の就寝時間を少し早めてもいいでしょう。', title_ko = '수면 일과를 살펴봐요. ⏱️', body_ko = '낮잠이 한 번으로 줄었다면 저녁에 더 빨리 지칠 거예요. 밤잠에 드는 시간을 조금 앞당겨도 좋아요.', title_nl = 'We volgen het slaapritme. ⏱️', body_nl = 'Is je kindje overgestapt op één dutje overdag? Dan wordt hij ''s avonds eerder moe. Je kunt het tijdstip van naar bed gaan iets vervroegen.', title_pl = 'Śledzimy rytm snu. ⏱️', body_pl = 'Jeśli w ciągu dnia została już jedna drzemka, wieczorem szybciej się zmęczy. Możesz trochę przyspieszyć porę nocnego snu.', title_pt = 'A acompanhar o sono. ⏱️', body_pt = 'Se passou a fazer só uma sesta, ao fim do dia vai cansar-se mais cedo. Pode antecipar um pouco a hora de deitar.', title_sv = 'Vi följer sömnen. ⏱️', body_sv = 'Om dagsluren har blivit en enda blir barnet trött tidigare på kvällen. Du kan flytta fram läggdags lite.', title_vi = 'Theo dõi nếp ngủ. ⏱️', body_vi = 'Nếu bé chỉ còn một giấc ngủ ngày, buổi tối bé sẽ mệt sớm hơn. Mẹ có thể cho bé đi ngủ đêm sớm hơn một chút.', title_zh = '关注睡眠作息 ⏱️', body_zh = '如果白天只睡一次了，晚上就会更早犯困。可以把晚上上床的时间稍微提前一点。' WHERE id = '1cb9115d-9cf4-466e-adbe-8fa808d6b45c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No olvides beber agua 💧', body_es = 'Cuanto más se mueve, más sed tiene. Ofrécele agua a menudo mientras juega y después de las comidas.', title_fr = 'N''oubliez pas de boire. 💧', body_fr = 'Plus il bouge, plus il a soif. Proposez-lui régulièrement de l''eau pendant les jeux et après les repas.', title_hi = 'पानी पीना मत भूलिए। 💧', body_hi = 'जितनी भाग-दौड़, उतनी प्यास। खेल के दौरान और खाने के बाद उसे नियमित रूप से पानी दीजिए।', title_id = 'Jangan lupa minum air. 💧', body_id = 'Makin aktif bergerak, makin cepat haus. Tawarkan air secara rutin saat bermain dan setelah makan.', title_ja = '水分補給を忘れずに 💧', body_ja = '活発に動くほど、のどもよく渇きます。遊んでいるときや食事のあとに、こまめにお水をすすめましょう。', title_ko = '물 마시는 걸 잊지 마세요. 💧', body_ko = '활발하게 움직일수록 목도 더 말라요. 놀이 중과 식사 후에 물을 자주 권해 주세요.', title_nl = 'Vergeet niet te drinken. 💧', body_nl = 'Hoe actiever je kindje is, hoe meer dorst hij krijgt. Bied hem tijdens het spelen en na het eten regelmatig water aan.', title_pl = 'Nie zapominaj o piciu wody. 💧', body_pl = 'Im więcej się rusza, tym bardziej chce mu się pić. Regularnie proponuj mu wodę podczas zabawy i po posiłkach.', title_pt = 'Não se esqueça de beber água. 💧', body_pt = 'Quanto mais se mexe, mais sede tem. Ofereça-lhe água com regularidade durante as brincadeiras e depois das refeições.', title_sv = 'Glöm inte att dricka vatten. 💧', body_sv = 'Ju mer aktivt barnet är, desto törstigare blir det. Erbjud vatten regelbundet under leken och efter måltiderna.', title_vi = 'Đừng quên uống nước. 💧', body_vi = 'Càng vận động nhiều, bé càng khát. Hãy thường xuyên cho bé uống nước trong lúc chơi và sau bữa ăn.', title_zh = '别忘了喝水 💧', body_zh = '活动越多越容易口渴。玩耍时和饭后，记得经常给宝宝喝水。' WHERE id = '42c60ff7-6aed-4b88-96d2-512be311f08c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¿Qué es eso?» ☝', body_es = '️ Lo señala todo con el dedo y te pregunta cómo se llama. Dile con paciencia el nombre de cada cosa: es su manera de descubrir el mundo.', title_fr = 'La période du « C''est quoi ? ». ☝', body_fr = '️ Il montre tout du doigt et vous demande le nom. Dites-lui patiemment le nom de chaque chose : c''est sa façon de découvrir le monde.', title_hi = '''वह क्या है?'' का दौर। ☝', body_hi = '️ हर चीज़ की ओर उँगली दिखाकर आपसे उसका नाम पूछता है। धैर्य से हर चीज़ का नाम बताइए; यह आसपास की दुनिया को खोजने का उसका तरीका है।', title_id = 'Masa "Itu apa?". ☝', body_id = '️ Ia menunjuk segala hal dengan jarinya dan menanyakan namanya. Sebutkan nama semuanya dengan sabar; ini caranya menjelajahi dunia di sekitarnya.', title_ja = '「あれなに？」の時期 ☝', body_ja = '️なんでも指さして、名前を聞いてきます。根気よくひとつひとつ名前を教えてあげましょう。これがまわりの世界を発見する方法なのです。', title_ko = '"저게 뭐야?" 시기. ☝', body_ko = '️모든 걸 손가락으로 가리키며 이름을 물어요. 인내심을 갖고 하나하나 이름을 말해 주세요. 이것이 아이가 주변 세상을 알아 가는 방법이에요.', title_nl = 'De wat-is-dat-fase. ☝', body_nl = '️ Je kindje wijst alles aan en vraagt je hoe het heet. Zeg geduldig de naam van alles: zo ontdekt hij de wereld om zich heen.', title_pl = 'Etap „A to co?”. ☝', body_pl = '️ Pokazuje wszystko paluszkiem i pyta cię o nazwę. Cierpliwie nazywaj mu wszystko, to jego sposób na odkrywanie świata wokół.', title_pt = 'A fase do "O que é aquilo?". ☝', body_pt = '️ Aponta para tudo com o dedo e pergunta-lhe o nome. Diga com paciência o nome de cada coisa: é a forma dele de descobrir o mundo à sua volta.', title_sv = 'Fasen ”Vad är det där?”. ☝', body_sv = '️ Barnet pekar på allt och frågar dig vad det heter. Säg med tålamod namnet på allt, det är barnets sätt att upptäcka världen.', title_vi = 'Giai đoạn "Cái gì kia?". ☝', body_vi = '️ Bé chỉ tay vào mọi thứ và hỏi mẹ tên của chúng. Hãy kiên nhẫn gọi tên từng thứ; đây là cách bé khám phá thế giới xung quanh.', title_zh = '“那是什么？”阶段 ☝', body_zh = '️ 宝宝用手指着各种东西问你名字。耐心地告诉他每样东西叫什么，这是他探索周围世界的方式。' WHERE id = '9a860f2e-97a8-4151-9a68-ed86235ecd75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Baila con la música! 🎶', body_es = '¿En cuanto oye un ritmo se balancea de un lado a otro y baila? Sube estos momentos llenos de energía en vídeo al Álbum del bebé.', title_fr = 'Il danse en musique ! 🎶', body_fr = 'Dès qu''il entend un son rythmé, il se balance et se met à danser ? Ajoutez ces moments pleins d''énergie en vidéo à l''Album de bébé.', title_hi = 'संगीत पर नाचता है! 🎶', body_hi = 'कोई लयबद्ध आवाज़ सुनते ही इधर-उधर झूमने और नाचने लगता है? इन ऊर्जा भरे पलों को वीडियो के रूप में बेबी एल्बम में अपलोड कीजिए।', title_id = 'Berjoget mengikuti musik! 🎶', body_id = 'Begitu mendengar suara berirama, ia bergoyang ke sana kemari dan berjoget? Unggah momen penuh energi ini sebagai video ke Album Bayi.', title_ja = '音楽に合わせてダンス！🎶', body_ja = 'リズミカルな音が聞こえると、体を左右にゆらして踊りますか？この元気いっぱいの瞬間を、動画で「ベビーアルバム」に保存しましょう。', title_ko = '음악에 맞춰 춤춰요! 🎶', body_ko = '리듬감 있는 소리가 들리자마자 이리저리 몸을 흔들며 춤추나요? 이 신나는 순간을 영상으로 아기 앨범에 올리세요.', title_nl = 'Dansen op muziek! 🎶', body_nl = 'Wiegt je kindje heen en weer en danst hij zodra hij een ritme hoort? Zet deze energieke momenten als video in het Babyalbum.', title_pl = 'Tańczy do muzyki! 🎶', body_pl = 'Gdy tylko usłyszy rytmiczny dźwięk, kołysze się na boki i tańczy? Dodaj te pełne energii chwile jako filmik do Albumu dziecka.', title_pt = 'Dança ao som da música! 🎶', body_pt = 'Mal ouve um som com ritmo, balança para um lado e para o outro e dança? Carregue estes momentos cheios de energia em vídeo no Álbum do Bebé.', title_sv = 'Dansar till musiken! 🎶', body_sv = 'Gungar barnet hit och dit och dansar så fort det hör ett rytmiskt ljud? Ladda upp dessa energiska stunder som video i Babyalbumet.', title_vi = 'Bé nhảy theo nhạc! 🎶', body_vi = 'Vừa nghe thấy âm thanh có nhịp điệu là bé lắc lư và nhún nhảy? Hãy tải những khoảnh khắc sôi động này lên Album của bé dưới dạng video nhé.', title_zh = '跟着音乐跳舞！🎶', body_zh = '一听到有节奏的声音，就左摇右摆地跳起来？把这些活力满满的瞬间录成视频上传到宝宝相册吧。' WHERE id = '09bd2033-24ed-4376-ba68-6795f9e6d0fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aprende a jugar solo 🧩', body_es = 'Que pueda jugar solo, aunque sea un rato, demuestra que su atención se está desarrollando. Obsérvale con cariño desde lejos en esos momentos.', title_fr = 'Savoir jouer seul. 🧩', body_fr = 'Pouvoir jouer seul, même un court moment, montre que son attention se développe. Pendant ces moments, observez-le avec amour, de loin.', title_hi = 'अकेले खेलने का हुनर। 🧩', body_hi = 'थोड़ी देर के लिए ही सही, उसका अपने आप खेल पाना दिखाता है कि उसका ध्यान विकसित हो रहा है। ऐसे पलों में उसे दूर से प्यार से देखिए।', title_id = 'Kemampuan bermain sendiri. 🧩', body_id = 'Kemampuannya bermain sendiri, meski sebentar, menunjukkan perhatiannya sedang berkembang. Pada saat seperti ini, perhatikan ia dari jauh dengan penuh cinta.', title_ja = 'ひとり遊びの力 🧩', body_ja = '短い時間でもひとりで遊べるのは、集中力が育っている証拠です。そんなときは、少し離れたところから愛情をこめて見守りましょう。', title_ko = '혼자 노는 능력. 🧩', body_ko = '잠깐이라도 혼자 놀 수 있다는 건 집중력이 자라고 있다는 뜻이에요. 이럴 때는 멀리서 사랑스럽게 지켜봐 주세요.', title_nl = 'Zelfstandig spelen. 🧩', body_nl = 'Dat je kindje even alleen kan spelen, laat zien dat zijn concentratie groeit. Kijk op die momenten liefdevol van een afstandje toe.', title_pl = 'Umiejętność samodzielnej zabawy. 🧩', body_pl = 'To, że potrafi choć chwilę bawić się sam, pokazuje, że rozwija się jego uwaga. W takich chwilach obserwuj go z miłością z daleka.', title_pt = 'A capacidade de brincar sozinho. 🧩', body_pt = 'Conseguir brincar sozinho, mesmo por pouco tempo, mostra que a atenção dele se está a desenvolver. Nesses momentos, observe-o com carinho à distância.', title_sv = 'Förmågan att leka själv. 🧩', body_sv = 'Att barnet kan leka själv, även en kort stund, visar att uppmärksamheten utvecklas. Följ barnet kärleksfullt på avstånd i de stunderna.', title_vi = 'Kỹ năng tự chơi. 🧩', body_vi = 'Bé có thể tự chơi dù chỉ trong thời gian ngắn cho thấy khả năng tập trung đang phát triển. Những lúc ấy, hãy âu yếm dõi theo bé từ xa.', title_zh = '独自玩耍的能力 🧩', body_zh = '哪怕只能自己玩一小会儿，也说明宝宝的专注力在发展。这时远远地、满怀爱意地看着他吧。' WHERE id = '899ab05b-717c-4e03-b941-aadf4ad85007' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un baño templado relaja 🛁', body_es = 'Jugar con el agua para quitarse el polvo y el cansancio del día le divertirá y le preparará perfectamente para dormir.', title_fr = 'Un bain tiède qui détend. 🛁', body_fr = 'Jouer avec l''eau pour se débarrasser de la poussière et de la fatigue de la journée va l''amuser et le préparer parfaitement au sommeil.', title_hi = 'गुनगुना स्नान सुकून देता है। 🛁', body_hi = 'दिन की धूल और थकान धोने के लिए पानी से खेलना उसे मज़ा भी देगा और नींद के लिए पूरी तरह तैयार भी करेगा।', title_id = 'Mandi air hangat itu menenangkan. 🛁', body_id = 'Bermain air untuk menghapus debu dan lelah seharian akan menghiburnya sekaligus membuatnya siap tidur.', title_ja = 'ぬるめのお風呂でリラックス 🛁', body_ja = '水遊びで一日のほこりと疲れを落とせば、楽しいうえに、眠りへの準備もばっちり整います。', title_ko = '따뜻한 목욕은 마음을 편하게 해요. 🛁', body_ko = '하루의 먼지와 피로를 씻어 내는 물놀이는 아이를 즐겁게 하고 잠들 준비도 완벽하게 해 줄 거예요.', title_nl = 'Een lauw badje ontspant. 🛁', body_nl = 'Spelen met water spoelt het stof en de vermoeidheid van de dag weg, is leuk en maakt je kindje perfect klaar om te slapen.', title_pl = 'Ciepła kąpiel odpręża. 🛁', body_pl = 'Zabawa w wodzie zmyje kurz i zmęczenie całego dnia, rozbawi go i idealnie przygotuje do snu.', title_pt = 'Um banho morno relaxa. 🛁', body_pt = 'Brincar com a água para tirar o pó e o cansaço do dia vai diverti-lo e, ao mesmo tempo, prepará-lo na perfeição para dormir.', title_sv = 'Ett ljummet bad avslappnar. 🛁', body_sv = 'Att leka med vatten för att skölja bort dagens damm och trötthet både roar barnet och förbereder det perfekt för sömnen.', title_vi = 'Tắm nước ấm giúp thư giãn. 🛁', body_vi = 'Chơi với nước để rửa trôi bụi bặm và mệt mỏi cả ngày vừa giúp bé vui, vừa chuẩn bị hoàn hảo cho giấc ngủ.', title_zh = '温水澡让人放松 🛁', body_zh = '玩玩水，洗去一天的尘土和疲惫，既能逗他开心，又能为入睡做好充分准备。' WHERE id = '98938324-49d8-43fc-bdde-202849487b20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pone a prueba los límites 🛑', body_es = '¿Aunque le dices que no, vuelve a alargar la mano hacia ese objeto? No es terquedad, está poniendo a prueba las normas. Sé coherente y paciente.', title_fr = 'Il teste les limites. 🛑', body_fr = 'Malgré votre « non », il tend encore la main vers l''objet ? Ce n''est pas de l''entêtement, c''est sa façon d''apprendre les règles. Soyez cohérente et patiente.', title_hi = 'सीमाएँ परख रहा है। 🛑', body_hi = 'आपके ''नहीं'' कहने के बावजूद फिर उसी चीज़ की ओर हाथ बढ़ाता है? यह ज़िद नहीं, नियम सीखने का टेस्ट है। एक जैसा व्यवहार रखिए और धैर्य रखिए।', title_id = 'Menguji batas. 🛑', body_id = 'Meski Anda sudah bilang tidak, ia tetap meraih benda itu? Ini bukan keras kepala, melainkan cara menguji aturan. Tetaplah konsisten dan sabar.', title_ja = '境界線を試しています 🛑', body_ja = '「ダメ」と言ったのに、またそれに手を伸ばしますか？これは反抗ではなく、ルールを学ぶためのテストです。一貫した態度で根気よく。', title_ko = '한계를 시험하고 있어요. 🛑', body_ko = '"안 돼"라고 해도 또 그 물건에 손을 뻗나요? 고집이 아니라 규칙을 배우는 시험이에요. 일관되게, 인내심을 갖고 대해 주세요.', title_nl = 'Grenzen aftasten. 🛑', body_nl = 'Je zegt nee, maar je kindje grijpt toch naar dat ding? Dat is geen koppigheid, maar een test om de regels te leren. Wees consequent en geduldig.', title_pl = 'Sprawdza granice. 🛑', body_pl = 'Mimo twojego „nie” znów sięga po tę rzecz? To nie upór, tylko test, w którym poznaje zasady. Bądź konsekwentna i cierpliwa.', title_pt = 'Está a testar os limites. 🛑', body_pt = 'Mesmo depois de dizer que não, volta a esticar a mão para aquele objeto? Não é teimosia, é um teste para aprender as regras. Seja coerente e paciente.', title_sv = 'Testar gränserna. 🛑', body_sv = 'Trots att du sagt nej sträcker sig barnet ändå efter saken? Det är inte trots, utan ett test för att lära sig reglerna. Var konsekvent och tålmodig.', title_vi = 'Bé thử giới hạn. 🛑', body_vi = 'Dù mẹ đã nói "không", bé vẫn với lấy món đồ đó? Đây không phải bướng bỉnh mà là bé đang thử tìm hiểu quy tắc. Hãy nhất quán và kiên nhẫn.', title_zh = '在试探边界 🛑', body_zh = '你说了“不行”，他还是伸手去拿那样东西？这不是倔强，而是在测试规则。保持一致和耐心吧。' WHERE id = '67d07afb-a906-4267-ae07-195da32a67d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de la fruta! 🍎', body_es = 'Para recuperar energía, prepara un plato colorido y llamativo con fruta de temporada.', title_fr = 'L''heure des fruits ! 🍎', body_fr = 'Pour lui redonner de l''énergie, préparez une assiette colorée et appétissante de fruits de saison.', title_hi = 'फलों का समय! 🍎', body_hi = 'उसकी ऊर्जा लौटाने के लिए मौसमी फलों की रंग-बिरंगी और ध्यान खींचने वाली प्लेट तैयार कीजिए।', title_id = 'Waktunya buah! 🍎', body_id = 'Untuk memulihkan energinya, siapkan piring buah musiman yang berwarna-warni dan menarik.', title_ja = 'フルーツタイム！🍎', body_ja = '元気を取り戻せるよう、旬の果物でカラフルで目を引くお皿をつくりましょう。', title_ko = '과일 시간! 🍎', body_ko = '에너지를 채울 수 있도록 제철 과일로 알록달록하고 눈길을 끄는 한 접시를 만들어 주세요.', title_nl = 'Fruittijd! 🍎', body_nl = 'Maak een kleurrijk, aantrekkelijk bord met seizoensfruit om de energie weer aan te vullen.', title_pl = 'Czas na owoce! 🍎', body_pl = 'Aby odzyskać energię, przygotuj kolorowy, przyciągający wzrok talerz sezonowych owoców.', title_pt = 'Hora da fruta! 🍎', body_pt = 'Para recuperar a energia dele, prepare um prato colorido e apelativo com fruta da época.', title_sv = 'Fruktstund! 🍎', body_sv = 'Gör en färgglad och lockande tallrik med säsongens frukter för att fylla på energin.', title_vi = 'Giờ ăn trái cây! 🍎', body_vi = 'Để nạp lại năng lượng, hãy chuẩn bị một đĩa trái cây theo mùa nhiều màu sắc và bắt mắt.', title_zh = '水果时间！🍎', body_zh = '用应季水果摆一盘色彩缤纷、吸引眼球的果盘，帮宝宝恢复能量吧。' WHERE id = '71f533be-645b-4990-ac46-86ad77f1a038' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No te olvides de ti! 💖', body_es = 'La primera hora después de que se duerma debería ser solo tuya. No hagas ninguna tarea: dedícate a algo que te guste y descansa.', title_fr = 'Ne vous oubliez pas ! 💖', body_fr = 'La première heure après son coucher doit être rien qu''à vous. Ne faites aucune tâche, occupez-vous simplement de quelque chose que vous aimez et reposez-vous.', title_hi = 'खुद को मत भूलिए! 💖', body_hi = 'बच्चे के सोने के बाद का पहला घंटा सिर्फ़ आपका होना चाहिए। कोई काम मत कीजिए, बस अपनी पसंद का कुछ कीजिए और आराम कीजिए।', title_id = 'Jangan lupakan diri Anda! 💖', body_id = 'Satu jam pertama setelah si kecil tidur harus jadi milik Anda. Jangan kerjakan apa pun, lakukan saja hal yang Anda sukai dan beristirahatlah.', title_ja = '自分のことも忘れないで！💖', body_ja = 'お子さんが寝たあとの最初の1時間は、あなただけの時間に。家事はせず、好きなことをしてゆっくり休みましょう。', title_ko = '나 자신을 잊지 마세요! 💖', body_ko = '아이가 잠든 뒤 첫 한 시간은 오롯이 엄마의 시간이어야 해요. 아무 일도 하지 말고 좋아하는 것을 하며 쉬세요.', title_nl = 'Vergeet jezelf niet! 💖', body_nl = 'Het eerste uur nadat je kindje slaapt, is helemaal van jou. Doe geen klusjes, doe gewoon iets wat je leuk vindt en rust uit.', title_pl = 'Nie zapominaj o sobie! 💖', body_pl = 'Pierwsza godzina po tym, jak maluszek zaśnie, powinna należeć tylko do ciebie. Nie zabieraj się za obowiązki, po prostu zajmij się czymś, co lubisz, i odpocznij.', title_pt = 'Não se esqueça de si! 💖', body_pt = 'A primeira hora depois de ele adormecer deve ser só sua. Não faça tarefas, dedique-se simplesmente a algo de que goste e descanse.', title_sv = 'Glöm inte dig själv! 💖', body_sv = 'Den första timmen efter att barnet somnat ska vara bara din. Gör inga sysslor, ägna dig bara åt något du gillar och vila.', title_vi = 'Đừng quên bản thân mẹ! 💖', body_vi = 'Một giờ đầu tiên sau khi bé ngủ phải là của riêng mẹ. Đừng làm việc gì cả, chỉ cần làm điều mình thích và nghỉ ngơi.', title_zh = '别忘了自己！💖', body_zh = '宝宝睡着后的第一个小时只属于你。什么家务都别做，做点自己喜欢的事，好好休息吧。' WHERE id = 'cbf7129c-f3df-44ab-928f-9f74910675e9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Crees que algo falla en su rutina de sueño? Pregunta al momento a Anacan AI todo lo que te genere dudas y quédate tranquila.', body_fr = 'Vous pensez vous tromper dans son rituel du coucher ? Posez tout de suite vos questions à Anacan AI et soyez rassurée.', body_hi = 'लगता है नींद के रूटीन में कुछ गलत कर रही हैं? जिस भी बात पर दुविधा है, तुरंत Anacan AI से पूछिए और निश्चिंत हो जाइए।', body_id = 'Merasa ada yang salah dengan rutinitas tidurnya? Tanyakan semua keraguan Anda ke Anacan AI saat itu juga dan tenangkan diri.', body_ja = '寝かしつけの習慣で、何か間違えているかもと不安ですか？迷っていることは、すぐにAnacan AIに聞いて安心しましょう。', body_ko = '수면 루틴에서 뭔가 잘못하고 있는 것 같나요? 망설여지는 건 무엇이든 바로 Anacan AI에게 물어보고 마음을 놓으세요.', body_nl = 'Denk je dat je iets fout doet met de slaaproutine? Vraag Anacan AI meteen alles waar je over twijfelt en stel jezelf gerust.', body_pl = 'Myślisz, że robisz coś źle w rutynie snu? Od razu zapytaj Anacan AI o wszystko, co budzi twoje wątpliwości, i odetchnij.', body_pt = 'Acha que está a fazer algo errado na rotina de sono? Pergunte já ao Anacan AI tudo aquilo de que duvida e fique descansada.', body_sv = 'Tror du att du gör något fel i sömnrutinen? Fråga Anacan AI direkt om allt du är osäker på och slappna av.', body_vi = 'Mẹ nghĩ mình đang làm sai điều gì đó với nếp ngủ của bé? Hãy hỏi ngay Anacan AI mọi điều còn băn khoăn để yên tâm hơn.', body_zh = '觉得自己在睡前作息上做错了什么？任何拿不准的事都可以马上问Anacan AI，让自己安心。' WHERE id = '6f0da037-da86-424d-bd6d-1e6d3aefe4db' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja a un lado todo el cansancio 🥂', title_fr = 'Laissez toute la fatigue de côté. 🥂', title_hi = 'सारी थकान एक तरफ़ रख दीजिए। 🥂', title_id = 'Singkirkan semua rasa lelah. 🥂', title_ja = '疲れはいったん横に置きましょう 🥂', title_ko = '모든 피로는 잠시 내려놓으세요. 🥂', title_nl = 'Zet alle vermoeidheid opzij. 🥂', title_pl = 'Odłóż całe zmęczenie na bok. 🥂', title_pt = 'Deixe todo o cansaço de lado. 🥂', title_sv = 'Lägg all trötthet åt sidan. 🥂', title_vi = 'Hãy gác lại mọi mệt mỏi. 🥂', title_zh = '把所有疲惫都放一边吧 🥂' WHERE id = 'b0d45a27-101a-4c13-b494-715c8c48dda4' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡A lanzar la pelota! ⚽', body_es = '¡Ya no solo rueda la pelota, levanta los brazos e intenta lanzártela! Añade enseguida en vídeo sus intentos de deportista al Álbum del bebé.', title_fr = 'On joue au ballon ! ⚽', body_fr = 'Il ne se contente plus de faire rouler le ballon, il lève les bras pour vous le lancer ! Ajoutez tout de suite ces essais sportifs en vidéo à l''Album de bébé.', title_hi = 'गेंद फेंकने का खेल! ⚽', body_hi = 'गेंद सिर्फ़ लुढ़काता नहीं, बाँहें उठाकर आपकी ओर फेंकने की कोशिश करता है! उसकी इन खिलाड़ी जैसी कोशिशों को तुरंत वीडियो के रूप में बेबी एल्बम में जोड़िए।', title_id = 'Main lempar bola! ⚽', body_id = 'Ia tidak hanya menggelindingkan bola, tapi mencoba melemparnya ke arah Anda sambil mengangkat tangan! Segera tambahkan usaha atletisnya ini sebagai video ke Album Bayi.', title_ja = 'ボール投げ遊び！⚽', body_ja = 'ボールを転がすだけでなく、腕を上げてあなたのほうへ投げようとしています！このスポーツ選手のような挑戦を、すぐに動画で「ベビーアルバム」に追加しましょう。', title_ko = '공 던지기 놀이! ⚽', body_ko = '공을 굴리기만 하는 게 아니라 팔을 들어 엄마 쪽으로 던지려 해요! 이 꼬마 운동선수의 도전을 바로 영상으로 아기 앨범에 추가하세요.', title_nl = 'Met een bal gooien! ⚽', body_nl = 'Je kindje rolt de bal niet meer alleen, hij steekt zijn armpjes omhoog en probeert hem naar je toe te gooien! Zet deze sportieve pogingen meteen als video in het Babyalbum.', title_pl = 'Zabawa w rzucanie piłką! ⚽', body_pl = 'Już nie tylko turla piłkę, ale podnosi rączki i próbuje rzucić ją do ciebie! Od razu dodaj te sportowe próby jako filmik do Albumu dziecka.', title_pt = 'O jogo de atirar a bola! ⚽', body_pt = 'Já não se limita a rolar a bola, levanta os braços e tenta atirá-la na sua direção! Adicione já em vídeo estas tentativas de desportista ao Álbum do Bebé.', title_sv = 'Bollkastning! ⚽', body_sv = 'Barnet rullar inte bara bollen, utan lyfter armarna och försöker kasta den till dig! Lägg direkt till dessa sportiga försök som video i Babyalbumet.', title_vi = 'Trò chơi ném bóng! ⚽', body_vi = 'Bé không chỉ lăn bóng mà còn giơ tay cố ném về phía mẹ! Hãy thêm ngay video những nỗ lực "vận động viên" này vào Album của bé.', title_zh = '扔球游戏！⚽', body_zh = '宝宝不只是滚球，还会举起手臂把球朝你扔过来！马上把这位小运动员的尝试录成视频放进宝宝相册吧。' WHERE id = '8878ea41-701a-4729-9437-858b0e0448ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Quién sale en el álbum familiar? 🖼', body_es = '️ Mirando fotos, cuando preguntas «¿Dónde está la abuela?», ¿la señala bien con el dedo? Su memoria y su capacidad de reconocer caras avanzan muy rápido.', title_fr = 'Qui est dans l''album de famille ? 🖼', body_fr = '️ En regardant les photos, quand vous demandez « Où est Mamie ? », il la montre du doigt ? Sa mémoire et sa reconnaissance des visages se développent vite.', title_hi = 'फ़ैमिली एल्बम में कौन-कौन है? 🖼', body_hi = '️ तस्वीरें देखते समय ''नानी/दादी कहाँ हैं?'' पूछने पर उँगली से सही दिखाता है? याददाश्त और चेहरे पहचानने का हुनर तेज़ी से विकसित हो रहा है।', title_id = 'Siapa saja di album keluarga? 🖼', body_id = '️ Saat melihat foto dan Anda bertanya "Nenek mana?", ia menunjuk dengan benar? Ingatan dan kemampuannya mengenali wajah berkembang pesat.', title_ja = '家族のアルバムには誰がいる？🖼', body_ja = '️写真を見ながら「おばあちゃんはどこ？」と聞くと、ちゃんと指さしますか？記憶力と顔を見分ける力がぐんぐん育っています。', title_ko = '가족 앨범에 누가 있을까요? 🖼', body_ko = '️사진을 보며 "할머니 어디 있어?" 하면 손가락으로 정확히 가리키나요? 기억력과 얼굴 인식 능력이 빠르게 발달하고 있어요.', title_nl = 'Wie staat er in het familiealbum? 🖼', body_nl = '️ Wijst je kindje bij het bekijken van foto''s de juiste persoon aan als je vraagt: waar is oma? Zijn geheugen en gezichtsherkenning ontwikkelen zich snel.', title_pl = 'Kto jest w rodzinnym albumie? 🖼', body_pl = '️ Gdy oglądacie zdjęcia i pytasz „Gdzie jest babcia?”, dobrze pokazuje ją paluszkiem? Pamięć i rozpoznawanie twarzy szybko się rozwijają.', title_pt = 'Quem está no álbum de família? 🖼', body_pt = '️ Ao ver fotografias, quando lhe pergunta "Onde está a avó?", aponta para o sítio certo? A memória e o reconhecimento de rostos desenvolvem-se depressa.', title_sv = 'Vilka finns i familjealbumet? 🖼', body_sv = '️ Pekar barnet rätt när du frågar ”Var är mormor?” medan ni tittar på bilder? Minnet och förmågan att känna igen ansikten utvecklas snabbt.', title_vi = 'Trong album gia đình có những ai? 🖼', body_vi = '️ Khi xem ảnh, mẹ hỏi "Bà đâu?" là bé chỉ đúng? Trí nhớ và khả năng nhận diện khuôn mặt đang phát triển nhanh chóng.', title_zh = '家庭相册里都有谁？🖼', body_zh = '️ 看照片时你问“奶奶在哪里？”，他能用手指准确指出来吗？记忆力和认脸能力正在快速发展。' WHERE id = 'd2eace3f-d381-45ba-bfbb-2db61f670769' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos de ingeniero 🧱', body_es = 'Intenta poner un cubo encima de otro, pero se cae. Lo vuelve a probar con atención. Observa en silencio sus intentos.', title_fr = 'Essais d''ingénieur 🧱', body_fr = 'Il essaie d''empiler deux cubes, mais ils tombent. Il recommence avec attention. Observez ses essais en silence.', title_hi = 'इंजीनियरिंग की कोशिशें 🧱', body_hi = 'दो खिलौना ब्लॉक एक के ऊपर एक रखने की कोशिश करता है, पर वे गिर जाते हैं। वह ध्यान से फिर कोशिश करता है। उसकी कोशिशों को चुपचाप देखिए।', title_id = 'Usaha sang insinyur 🧱', body_id = 'Ia mencoba menumpuk dua balok mainan, tapi jatuh. Ia mencobanya lagi dengan saksama. Saksikan usahanya dalam diam.', title_ja = 'エンジニアの挑戦 🧱', body_ja = '積み木を2つ重ねようとしても、くずれてしまいます。それでもまた慎重に挑戦。その挑戦をそっと見守りましょう。', title_ko = '꼬마 엔지니어의 도전 🧱', body_ko = '블록 두 개를 쌓으려다 무너져요. 그래도 집중해서 다시 시도해요. 그 도전을 조용히 지켜봐 주세요.', title_nl = 'Bouwpogingen 🧱', body_nl = 'Je kindje probeert twee blokken op elkaar te zetten, maar ze vallen om. Hij probeert het zorgvuldig opnieuw. Kijk stil toe bij zijn pogingen.', title_pl = 'Inżynierskie próby 🧱', body_pl = 'Próbuje postawić jedną kostkę na drugiej, ale się przewracają. Uważnie próbuje jeszcze raz. Po cichu obserwuj jego próby.', title_pt = 'Tentativas de engenharia 🧱', body_pt = 'Tenta pôr dois cubos um em cima do outro, mas caem. Volta a tentar com atenção. Observe em silêncio estas tentativas.', title_sv = 'Ingenjörsförsök 🧱', body_sv = 'Barnet försöker stapla två klossar, men de ramlar. Det försöker noga igen. Följ försöken i tysthet.', title_vi = 'Những nỗ lực "kỹ sư" 🧱', body_vi = 'Bé cố chồng hai khối đồ chơi lên nhau nhưng chúng đổ. Bé chăm chú thử lại. Hãy lặng lẽ quan sát những lần thử của bé.', title_zh = '小工程师的尝试 🧱', body_zh = '宝宝想把两块积木摞起来，可总是倒。他会专注地一试再试。静静地欣赏他的尝试吧。' WHERE id = 'f2055f25-61d4-4680-83b3-954a3f1a9671' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Sin energía de tanto estar en casa? Elige en Lugares para mamás una cafetería donde estar a gusto y dedícate un rato.', body_fr = 'Rester à la maison vous a vidée de votre énergie. Choisissez parmi les Lieux adaptés aux mamans un café où vous installer confortablement et prenez du temps pour vous.', body_hi = 'घर में रहकर आपकी ऊर्जा खत्म हो गई है। माँ के लिए अनुकूल जगहों से कोई ऐसा कैफ़े चुनिए जहाँ आराम से बैठ सकें, और अपने लिए समय निकालिए।', body_id = 'Energi Anda habis karena terus di rumah? Pilih kafe yang nyaman dari Tempat Ramah Ibu dan luangkan waktu untuk diri sendiri.', body_ja = '家にこもってばかりでエネルギー切れ。「ママにやさしいスポット」からゆっくりできるカフェを選んで、自分の時間をつくりましょう。', body_ko = '집에만 있어 기운이 다 빠졌어요. 엄마 친화 장소에서 편히 앉을 수 있는 카페를 골라 나를 위한 시간을 가져 보세요.', body_nl = 'Is je energie op van het thuiszitten? Kies in Mamavriendelijke plekken een café waar je rustig kunt zitten en neem tijd voor jezelf.', body_pl = 'Siedzenie w domu odebrało ci energię. Wybierz z Miejsc przyjaznych mamom kawiarnię, w której wygodnie usiądziesz, i znajdź czas dla siebie.', body_pt = 'Ficar em casa esgotou-lhe a energia. Escolha nos Locais Amigos das Mães um café onde possa estar à vontade e reserve tempo para si.', body_sv = 'Energin har tagit slut av att vara hemma. Välj ett kafé i Mammavänliga platser där du kan sitta bekvämt och ta tid för dig själv.', body_vi = 'Ở nhà mãi khiến mẹ cạn năng lượng. Hãy chọn một quán cà phê có thể ngồi thoải mái trong Địa điểm thân thiện với mẹ và dành thời gian cho bản thân.', body_zh = '在家待得没电了？从妈妈友好场所里选一家能舒服坐坐的咖啡馆，给自己留点时间。' WHERE id = '458a103b-d07a-4e59-ac24-1d9dafc323f0' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Nada le contenta y llora por todo? Puede que le estén saliendo las muelas de atrás. Registra el proceso en el Seguimiento de dentición.', body_fr = 'Rien ne lui convient et il pleure pour tout ? Ce sont peut-être ses molaires du fond qui percent. Notez l''évolution dans le Suivi des dents.', body_hi = 'किसी बात से खुश नहीं, हर चीज़ पर रोता है? शायद पीछे की दाढ़ें निकल रही हैं। दाँत निकलने के ट्रैकर में इसे दर्ज कीजिए।', body_id = 'Tidak ada yang membuatnya puas dan ia menangis karena segala hal? Mungkin geraham belakangnya sedang tumbuh. Catat prosesnya di Pelacak Tumbuh Gigi.', body_ja = '何をしても気に入らず、泣いてばかり？奥歯が生えてきているのかもしれません。「歯の生え始めトラッカー」に記録しましょう。', body_ko = '무엇에도 만족하지 못하고 계속 우나요? 안쪽 어금니가 나오는 중일 수도 있어요. 이앓이 기록에 과정을 남겨 두세요.', body_nl = 'Is je kindje nergens tevreden mee en huilt hij om alles? Misschien komen de achterste kiezen door. Houd het bij in de Tandjestracker.', body_pl = 'Nic mu nie pasuje i płacze o wszystko? Może wychodzą tylne trzonowce. Zapisz przebieg w narzędziu do śledzenia ząbkowania.', body_pt = 'Nada o contenta e chora por tudo? Talvez estejam a nascer os molares de trás. Registe o processo no Registo de Dentição.', body_sv = 'Är barnet missnöjt med allt och gråter för allting? Kanske är det de bakre kindtänderna som kommer. Anteckna förloppet i Tandspåraren.', body_vi = 'Bé không vừa ý điều gì, cứ khóc mãi? Có thể răng hàm phía sau đang mọc. Hãy ghi lại quá trình trong Theo dõi mọc răng.', body_zh = '什么都不满意，动不动就哭？也许后面的磨牙正在长出来。在出牙追踪里记录一下吧。' WHERE id = 'd9ba76c2-3830-4eb2-b0e8-55a4c6a2f75e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Necesitas información sobre los saltos de desarrollo de los 16 meses? Pide a Anacan AI una lista breve, precisa y avalada por pediatras.', body_fr = 'Besoin d''informations sur les pics de développement à 16 mois ? Demandez à Anacan AI une liste courte, précise et validée par des pédiatres.', body_hi = '16 महीने की विकास की छलांगों के बारे में जानकारी चाहिए? Anacan AI से छोटी, सटीक और बाल रोग विशेषज्ञ द्वारा पुष्ट सूची माँगिए।', body_id = 'Butuh informasi tentang lompatan perkembangan usia 16 bulan? Minta daftar singkat, akurat, dan disetujui dokter anak dari Anacan AI.', body_ja = '1歳4か月ごろの発達の節目について知りたいですか？Anacan AIに、短く正確で小児科医も認めるリストを聞いてみましょう。', body_ko = '16개월 발달 도약에 대한 정보가 필요한가요? Anacan AI에게 짧고 정확한, 소아과 의사가 확인한 목록을 요청하세요.', body_nl = 'Wil je meer weten over de ontwikkelingssprongen rond 16 maanden? Vraag Anacan AI om een korte, nauwkeurige lijst die door kinderartsen is goedgekeurd.', body_pl = 'Potrzebujesz informacji o skokach rozwojowych w 16. miesiącu? Poproś Anacan AI o krótką, rzetelną listę zatwierdzoną przez pediatrę.', body_pt = 'Precisa de informação sobre os saltos de desenvolvimento aos 16 meses? Peça ao Anacan AI uma lista curta, precisa e validada por pediatras.', body_sv = 'Behöver du information om utvecklingssprången vid 16 månader? Be Anacan AI om en kort, exakt och barnläkargodkänd lista.', body_vi = 'Mẹ cần thông tin về các bước nhảy phát triển ở tháng 16? Hãy nhờ Anacan AI đưa ra một danh sách ngắn gọn, chính xác, đã được bác sĩ nhi khoa xác nhận.', body_zh = '想了解16个月的发育飞跃？请Anacan AI给你一份简短、准确、经儿科医生认可的清单吧。' WHERE id = '07f52bf7-1174-455b-9c35-8391687a69fe' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sonidos que calman 🎶', body_es = 'Si después de un día lleno de descubrimientos tu peque no consigue calmarse, pon el sonido de la lluvia en Ruido blanco y llena la habitación de paz.', title_fr = 'Des sons qui apaisent. 🎶', body_fr = 'Après une journée pleine d''explorations, votre enfant n''arrive pas à se calmer ? Lancez le bruit de la pluie dans les Bruits blancs pour apaiser la chambre.', title_hi = 'शांति देने वाली आवाज़ें। 🎶', body_hi = 'खोजबीन भरे दिन के बाद अगर आपका बच्चा शांत नहीं हो पा रहा, तो कमरे में व्हाइट नॉइज़ से बारिश की आवाज़ चलाकर सुकून बनाइए।', title_id = 'Suara yang menenangkan. 🎶', body_id = 'Kalau si kecil sulit tenang setelah hari penuh penjelajahan, ciptakan ketenangan di kamar dengan memutar suara hujan dari Suara Putih.', title_ja = '心を落ち着かせる音 🎶', body_ja = '活発な探検でいっぱいの一日のあと、なかなか落ち着けないときは、「ホワイトノイズ」から雨の音を流して、部屋を穏やかな雰囲気にしましょう。', title_ko = '마음을 차분하게 하는 소리. 🎶', body_ko = '활발한 탐험으로 가득한 하루 뒤에 아이가 진정하지 못한다면 백색소음에서 빗소리를 틀어 방에 평온함을 더해 주세요.', title_nl = 'Rustgevende geluiden. 🎶', body_nl = 'Kan je kindje na een dag vol ontdekkingen niet tot rust komen? Zet in Witte ruis het geluid van regen aan en breng rust in de kamer.', title_pl = 'Dźwięki, które uspokajają. 🎶', body_pl = 'Jeśli po dniu pełnym aktywnych odkryć maluszek nie może się uspokoić, włącz w pokoju odgłos deszczu z Białego szumu i stwórz spokojną atmosferę.', title_pt = 'Sons que trazem calma. 🎶', body_pt = 'Se o seu filho não se consegue acalmar depois de um dia cheio de descobertas, ligue no quarto o som da chuva no Ruído Branco e crie tranquilidade.', title_sv = 'Ljud som skapar lugn. 🎶', body_sv = 'Om barnet inte kan lugna sig efter en dag full av aktiva upptäckter, skapa ro i rummet genom att sätta på regnljud i Vitt brus.', title_vi = 'Âm thanh mang lại bình yên. 🎶', body_vi = 'Nếu sau một ngày đầy khám phá sôi nổi mà bé không dịu lại được, hãy bật tiếng mưa trong Tiếng ồn trắng để căn phòng thêm yên bình.', title_zh = '让人平静的声音 🎶', body_zh = '如果忙着探索了一整天，宝宝静不下来，就在房间里用白噪音放雨声，营造宁静的氛围。' WHERE id = 'd94026ce-ef2a-4e93-b559-9f926c9f245d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos sensoriales 🌾', body_es = 'Echa un poco de arroz o pasta en un recipiente grande y esconde juguetes dentro. Deja que los busque con las manos y desarrolle el sentido del tacto.', title_fr = 'Jeux sensoriels. 🌾', body_fr = 'Versez un peu de riz ou de pâtes dans un grand récipient et cachez-y des jouets. Laissez-le les chercher avec ses mains pour développer son sens du toucher.', title_hi = 'छूकर महसूस करने वाले खेल। 🌾', body_hi = 'एक बड़े बर्तन में थोड़े चावल या पास्ता डालिए और उसमें खिलौने छिपा दीजिए। उसे हाथों से ढूँढने दीजिए, ताकि उसकी छूने की समझ विकसित हो।', title_id = 'Permainan sensorik. 🌾', body_id = 'Tuang sedikit beras atau makaroni ke wadah besar dan sembunyikan mainan di dalamnya. Biarkan ia menemukannya dengan tangan untuk melatih indra perabanya.', title_ja = '感覚遊び 🌾', body_ja = '大きな容器にお米やパスタを入れて、中におもちゃを隠しましょう。手で探して見つけることで、触覚が育ちます。', title_ko = '감각 놀이. 🌾', body_ko = '큰 그릇에 쌀이나 마카로니를 조금 붓고 장난감을 숨겨 보세요. 손으로 찾으며 촉감을 발달시킬 수 있어요.', title_nl = 'Voelspelletjes. 🌾', body_nl = 'Doe wat rijst of pasta in een grote bak en verstop er speeltjes in. Laat je kindje ze met zijn handjes zoeken, zo ontwikkelt hij zijn tastzin.', title_pl = 'Zabawy sensoryczne. 🌾', body_pl = 'Wsyp do dużej miski trochę ryżu lub makaronu i schowaj w nim zabawki. Niech szuka ich rączkami i rozwija zmysł dotyku.', title_pt = 'Jogos sensoriais. 🌾', body_pt = 'Deite um pouco de arroz ou massa num recipiente grande e esconda lá dentro brinquedos. Deixe-o encontrá-los com as mãos e desenvolver o tato.', title_sv = 'Sinneslekar. 🌾', body_sv = 'Häll lite ris eller pasta i en stor skål och göm leksaker i den. Låt barnet hitta dem med händerna och utveckla känseln.', title_vi = 'Trò chơi giác quan. 🌾', body_vi = 'Đổ một ít gạo hoặc nui vào một chiếc thau lớn và giấu đồ chơi vào trong. Hãy để bé dùng tay tìm chúng để phát triển xúc giác.', title_zh = '感官游戏 🌾', body_zh = '在一个大盆里倒些大米或意面，把玩具藏进去。让他用手去找、去摸，锻炼触觉。' WHERE id = '523911e7-6ac9-424d-9f11-0729711fb179' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ya puede entretenerse solo con sus juguetes durante 10-15 minutos. Su capacidad de atención se alarga. Disfruta del silencio.', body_fr = 'Il sait déjà s''occuper seul avec ses jouets pendant 10-15 minutes. Son attention s''allonge. Savourez le calme.', body_hi = 'अब वह 10-15 मिनट अपने खिलौनों में अकेले मगन रह सकता है। यह उसके ध्यान का दायरा बढ़ने का संकेत है। शांति का मज़ा लीजिए।', body_id = 'Kini ia bisa asyik sendiri dengan mainannya selama 10-15 menit. Ini tanda rentang perhatiannya makin panjang. Nikmati ketenangannya.', body_ja = 'もう10-15分はひとりでおもちゃで遊べるようになりました。集中できる時間が長くなっている証拠です。静かなひとときを味わいましょう。', body_ko = '이제 10-15분 동안 혼자 장난감을 가지고 놀 수 있어요. 집중하는 시간이 길어지고 있다는 뜻이에요. 고요함을 즐겨 보세요.', body_nl = 'Je kindje kan zich nu 10-15 minuten alleen met zijn speelgoed vermaken. Zijn concentratie wordt langer. Geniet van de stilte.', body_pl = 'Potrafi już przez 10-15 minut sam zająć się zabawkami. To znak, że wydłuża się jego skupienie uwagi. Delektuj się ciszą.', body_pt = 'Já consegue entreter-se sozinho com os brinquedos 10-15 minutos. É a capacidade de atenção a aumentar. Aproveite o silêncio.', body_sv = 'Nu kan barnet sysselsätta sig själv med leksakerna i 10-15 minuter. Uppmärksamheten håller längre. Njut av tystnaden.', body_vi = 'Bé đã có thể tự chơi với đồ chơi 10-15 phút. Đó là dấu hiệu khả năng tập trung đang dài ra. Hãy tận hưởng chút yên tĩnh nhé.', body_zh = '宝宝已经能自己玩玩具10-15分钟了。这说明他的专注时间在变长。享受这份安静吧。' WHERE id = '9d72a4f6-eac7-46c3-b9e9-ae6e482ce533' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando se acaba la paciencia 📝', body_es = 'A veces la energía de tu peque puede dejarte sin fuerzas. Abre el Diario de ánimo y escribe libremente qué es lo que más te ha cansado hoy.', title_fr = 'Quand la patience est à bout. 📝', body_fr = 'Parfois, l''énergie de votre enfant peut vous épuiser complètement. Ouvrez votre Journal d''humeur et écrivez librement ce qui vous a le plus fatiguée aujourd''hui.', title_hi = 'जब धैर्य का प्याला भर जाए। 📝', body_hi = 'कभी-कभी बच्चे की ऊर्जा आपको पूरी तरह थका सकती है। मूड डायरी खोलिए और खुलकर लिखिए कि आज आपको सबसे ज़्यादा किस बात ने थकाया।', title_id = 'Saat kesabaran menipis. 📝', body_id = 'Kadang energi si kecil bisa benar-benar menguras Anda. Buka Buku Harian Suasana Hati dan tulis dengan bebas apa yang paling membuat Anda lelah hari ini.', title_ja = 'がまんの限界がきたら 📝', body_ja = '子どものエネルギーに、すっかり疲れ果ててしまうこともあります。「気分日記」を開いて、今日いちばん疲れたことを自由に書きましょう。', title_ko = '인내심이 바닥날 때. 📝', body_ko = '가끔은 아이의 에너지에 완전히 지칠 수 있어요. 기분 일기를 열고 오늘 무엇이 가장 힘들었는지 자유롭게 적어 보세요.', title_nl = 'Als je geduld op is. 📝', body_nl = 'Soms kan de energie van je kindje je helemaal uitputten. Open je Stemmingsdagboek en schrijf vrij op wat je vandaag het meest vermoeide.', title_pl = 'Gdy cierpliwość się kończy. 📝', body_pl = 'Czasem energia dziecka potrafi cię całkiem wyczerpać. Otwórz Dziennik nastroju i swobodnie zapisz, co dziś zmęczyło cię najbardziej.', title_pt = 'Quando a paciência se esgota. 📝', body_pt = 'Às vezes, a energia da criança pode deixá-la completamente esgotada. Abra o Diário de Humor e escreva à vontade o que mais a cansou hoje.', title_sv = 'När tålamodet tar slut. 📝', body_sv = 'Ibland kan barnets energi trötta ut dig helt. Öppna Humördagboken och skriv fritt om vad som tröttat ut dig mest i dag.', title_vi = 'Khi sự kiên nhẫn cạn dần. 📝', body_vi = 'Đôi khi năng lượng của bé có thể khiến mẹ kiệt sức hoàn toàn. Hãy mở Nhật ký tâm trạng và thoải mái viết ra điều gì khiến mẹ mệt nhất hôm nay.', title_zh = '耐心快用完的时候 📝', body_zh = '有时候孩子的精力会把你彻底耗尽。打开心情日记，把今天最让你累的事情尽情写下来吧。' WHERE id = '8bf81bea-dee2-4f82-9f28-f1e6a128a812' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aprende a usar el tenedor 🍴', body_es = 'Ya intenta pinchar la comida con el tenedor. Prepara alimentos fáciles de pinchar de Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Le passage à la fourchette. 🍴', body_fr = 'Il essaie déjà de piquer ses morceaux avec une fourchette. Préparez des aliments faciles à piquer grâce aux Recettes pour bébés qui commencent la diversification.', title_hi = 'काँटे की ओर कदम। 🍴', body_hi = 'अब वह अपने खाने में काँटा चुभोकर खाने की कोशिश करता है। ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी से ऐसा खाना बनाइए जो काँटे से आसानी से उठे।', title_id = 'Mulai memakai garpu. 🍴', body_id = 'Ia sudah mencoba menusuk makanannya dengan garpu. Siapkan makanan yang mudah diambil dengan garpu dari Resep untuk bayi yang mulai MPASI.', title_ja = 'フォークデビュー 🍴', body_ja = 'もうフォークで食べ物を刺して食べようとしています。「離乳食を始める赤ちゃんのレシピ」から、フォークで刺しやすい料理をつくってあげましょう。', title_ko = '포크 사용으로 넘어가요. 🍴', body_ko = '이제 음식을 포크로 찍어 먹으려 해요. 이유식을 시작하는 아기를 위한 레시피에서 포크로 집기 쉬운 음식을 만들어 주세요.', title_nl = 'Leren eten met een vork. 🍴', body_nl = 'Je kindje probeert al zijn eten aan een vork te prikken. Maak uit Recepten voor baby''s die met bijvoeding beginnen gerechten die makkelijk met een vork te pakken zijn.', title_pl = 'Nauka jedzenia widelcem. 🍴', body_pl = 'Próbuje już nabijać jedzenie na widelec. Przygotuj z Przepisów dla niemowląt rozpoczynających rozszerzanie diety dania, które łatwo nabić na widelec.', title_pt = 'A passagem para o garfo. 🍴', body_pt = 'Já tenta espetar a comida com o garfo. Prepare nas Receitas para bebés em diversificação alimentar alimentos fáceis de apanhar com o garfo.', title_sv = 'Övergång till gaffel. 🍴', body_sv = 'Barnet försöker redan spetsa maten med gaffeln och äta. Gör mat som är lätt att ta med gaffel från Recept för bebisar som börjar med fast föda.', title_vi = 'Tập dùng nĩa. 🍴', body_vi = 'Bé đã thử dùng nĩa xiên thức ăn. Hãy chuẩn bị những món dễ xiên bằng nĩa từ mục Công thức cho bé bắt đầu ăn dặm.', title_zh = '开始用叉子 🍴', body_zh = '宝宝已经在尝试用叉子叉起食物吃了。从食谱板块的辅食宝宝食谱里，做些容易用叉子叉起来的食物吧。' WHERE id = '977f5267-192c-40d2-9215-420a5a54d255' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Es mío! 🧸', body_es = '¿Protesta y llora cuando le quitas algo de las manos? Su sentido de la propiedad se refuerza. Es una parte importante de la formación de su carácter.', title_fr = 'C''est à moi ! 🧸', body_fr = 'Il proteste et pleure quand on lui prend quelque chose des mains ? Son sens de la propriété se renforce. C''est une étape importante de la formation de son caractère.', title_hi = 'यह मेरा है! 🧸', body_hi = 'उसके हाथ से कुछ लेने पर विरोध करता और रोता है? ''मेरा'' होने की भावना मज़बूत हो रही है। यह उसके स्वभाव बनने का ज़रूरी हिस्सा है।', title_id = 'Itu punyaku! 🧸', body_id = 'Ia protes dan menangis saat sesuatu diambil dari tangannya? Rasa kepemilikannya makin kuat. Ini bagian penting dari pembentukan karakternya.', title_ja = 'ぼくの！わたしの！🧸', body_ja = '手から何かを取ると、怒って泣きますか？「自分のもの」という気持ちが強くなっています。これは人格が育つ大切な一部です。', title_ko = '내 거야! 🧸', body_ko = '손에 든 걸 가져가면 반발하며 우나요? 소유욕이 강해지고 있어요. 성격이 형성되는 중요한 과정이에요.', title_nl = 'Dat is van mij! 🧸', body_nl = 'Protesteert en huilt je kindje als je iets van hem afpakt? Zijn gevoel van bezit wordt sterker. Dat is een belangrijk deel van zijn karakterontwikkeling.', title_pl = 'To moje! 🧸', body_pl = 'Protestuje i płacze, gdy coś mu zabierasz? Wzmacnia się poczucie własności. To ważna część kształtowania charakteru.', title_pt = 'É meu! 🧸', body_pt = 'Protesta e chora quando lhe tira algo das mãos? O sentido de posse está a ficar mais forte. É uma parte importante da formação do caráter.', title_sv = 'Den är min! 🧸', body_sv = 'Protesterar och gråter barnet när du tar något ur handen? Känslan av ägande blir starkare. Det är en viktig del av personlighetens utveckling.', title_vi = 'Của con! 🧸', body_vi = 'Mẹ lấy thứ gì khỏi tay là bé phản đối và khóc? Ý thức sở hữu đang mạnh lên. Đây là một phần quan trọng trong việc hình thành tính cách.', title_zh = '那是我的！🧸', body_zh = '从他手里拿走东西时，他会抗议、会哭？物权意识在增强。这是性格形成的重要部分。' WHERE id = '3f154cd8-81d2-425b-aa71-ec2864247772' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hoy baña papá 👨‍🍼', body_es = 'Esta noche deja a papá el baño con mucha espuma y juegos de agua y el turno de acostarle, y descansa tú.', title_fr = 'Papa s''occupe du bain. 👨‍🍼', body_fr = 'Ce soir, confiez à papa le bain moussant avec jeux d''eau et le coucher, et reposez-vous.', title_hi = 'पापा के नहलाने की बारी। 👨‍🍼', body_hi = 'आज शाम पानी के खेलों के साथ झागदार स्नान कराने और सुलाने का काम पापा को सौंपिए और आराम कीजिए।', title_id = 'Giliran ayah memandikan. 👨‍🍼', body_id = 'Hari ini, serahkan tugas memandikan dengan banyak busa sambil bermain air dan menidurkannya kepada ayah, lalu beristirahatlah.', title_ja = 'パパのお風呂当番 👨‍🍼', body_ja = '今夜は、泡たっぷりのお風呂での水遊びと寝かしつけをパパにお願いして、ゆっくり休みましょう。', title_ko = '아빠의 목욕 당번. 👨‍🍼', body_ko = '오늘은 저녁 물놀이와 거품 가득한 목욕, 재우기까지 아빠에게 맡기고 엄마는 쉬세요.', title_nl = 'Papa is aan de beurt voor het badje. 👨‍🍼', body_nl = 'Laat vandaag het badje met veel schuim en waterspelletjes en het naar bed brengen aan papa over, en rust zelf uit.', title_pl = 'Kąpiel to zmiana taty. 👨‍🍼', body_pl = 'Dziś wieczorem przekaż tacie kąpiel z mnóstwem piany i zabawami w wodzie oraz usypianie, a sama odpocznij.', title_pt = 'A vez do pai dar o banho. 👨‍🍼', body_pt = 'Hoje, entregue ao pai o banho da noite com muita espuma e brincadeiras com água, e também a tarefa de o adormecer, e descanse.', title_sv = 'Pappas tur att bada barnet. 👨‍🍼', body_sv = 'Låt pappa i dag sköta det skummiga badet med vattenlekar och nattningen, och vila du.', title_vi = 'Đến lượt bố tắm cho bé. 👨‍🍼', body_vi = 'Tối nay hãy giao cho bố việc tắm bồn đầy bọt kèm trò chơi với nước và ru bé ngủ, còn mẹ thì nghỉ ngơi.', title_zh = '爸爸负责洗澡 👨‍🍼', body_zh = '今天把晚上玩水、洗个满是泡泡的澡、再哄他睡觉的任务交给爸爸，你好好休息吧。' WHERE id = '7a8e2bea-1a47-4839-9ded-36d3fa6fbd27' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te has quedado sin ideas para el menú de alimentación complementaria? No te pierdas en internet: encuentra sabores nuevos en Recetas saludables.', body_fr = 'Plus d''idées pour les menus de diversification ? Ne vous perdez pas sur Internet, trouvez de nouvelles saveurs dans la rubrique Recettes saines.', body_hi = 'ऊपरी आहार के मेन्यू के आइडिया खत्म हो गए? इंटरनेट में मत खोइए, सेहतमंद रेसिपी सेक्शन में नए स्वाद खोजिए।', body_id = 'Kehabisan ide untuk menu MPASI? Jangan tersesat di internet, temukan rasa baru di bagian Resep Sehat.', body_ja = '離乳食のメニューのアイデアが尽きましたか？ネットで迷わず、「ヘルシーレシピ」で新しい味を見つけましょう。', body_ko = '이유식 메뉴 아이디어가 바닥났나요? 인터넷에서 헤매지 말고 건강한 레시피 섹션에서 새로운 맛을 찾아보세요.', body_nl = 'Geen ideeën meer voor bijvoeding? Verdwaal niet op internet, vind nieuwe smaken in het onderdeel Gezonde recepten.', body_pl = 'Kończą ci się pomysły na menu przy rozszerzaniu diety? Nie gub się w internecie, znajdź nowe smaki w sekcji Zdrowe przepisy.', body_pt = 'Ficou sem ideias para a ementa da diversificação alimentar? Não se perca na internet, encontre novos sabores nas Receitas Saudáveis.', body_sv = 'Har idéerna till menyn med fast föda tagit slut? Gå inte vilse på nätet, hitta nya smaker i avsnittet Hälsosamma recept.', body_vi = 'Hết ý tưởng cho thực đơn ăn dặm? Đừng lạc lối trên mạng, hãy tìm những món ngon mới trong mục Công thức lành mạnh.', body_zh = '辅食菜单的点子用完了？别在网上迷路了，去健康食谱板块发现新的美味吧。' WHERE id = 'b60defb6-6a44-41ab-8087-7dec23cd3f5c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de desvestirse 🧦', body_es = '¡Vestirse es difícil, pero desvestirse es muy divertido! Deja que intente quitarse él solo el gorro, los calcetines o los zapatos.', title_fr = 'L''art de se déshabiller. 🧦', body_fr = 'S''habiller, c''est difficile, mais se déshabiller, c''est très amusant ! Laissez-le essayer d''enlever lui-même son bonnet, ses chaussettes ou ses chaussures.', title_hi = 'कपड़े उतारने की कला। 🧦', body_hi = 'कपड़े पहनना मुश्किल है, पर उतारना बहुत मज़ेदार! उसे अपनी टोपी, मोज़े या जूते खुद उतारने की कोशिश करने दीजिए।', title_id = 'Seni melepas pakaian. 🧦', body_id = 'Memakai baju itu sulit, tapi melepasnya sangat seru! Biarkan ia mencoba melepas sendiri topi, kaus kaki, atau sepatunya.', title_ja = 'お着替えより脱ぐのが得意 🧦', body_ja = '着るのは難しくても、脱ぐのはとっても楽しい！帽子や靴下、靴を自分で脱ごうとするのを見守ってあげましょう。', title_ko = '옷 벗기의 기술. 🧦', body_ko = '옷 입기는 어렵지만 벗기는 정말 재밌어요! 모자, 양말, 신발을 혼자 벗어 보게 해 주세요.', title_nl = 'De kunst van het uitkleden. 🧦', body_nl = 'Aankleden is lastig, maar uitkleden is heel leuk! Laat je kindje zelf proberen zijn mutsje, sokken of schoenen uit te trekken.', title_pl = 'Sztuka rozbierania się. 🧦', body_pl = 'Ubieranie jest trudne, ale rozbieranie to świetna zabawa! Pozwól mu samemu próbować zdjąć czapkę, skarpetki lub buty.', title_pt = 'A arte de se despir. 🧦', body_pt = 'Vestir-se é difícil, mas despir-se é muito divertido! Deixe-o tentar tirar sozinho o gorro, as meias ou os sapatos.', title_sv = 'Konsten att klä av sig. 🧦', body_sv = 'Att klä på sig är svårt, men att klä av sig är jätteroligt! Låt barnet försöka ta av sig mössan, strumporna eller skorna själv.', title_vi = 'Nghệ thuật cởi đồ. 🧦', body_vi = 'Mặc đồ thì khó, nhưng cởi đồ lại rất vui! Hãy để bé thử tự cởi mũ, tất hay giày.', title_zh = '脱衣服的艺术 🧦', body_zh = '穿衣服很难，但脱衣服超好玩！让他试着自己摘帽子、脱袜子或鞋子吧。' WHERE id = '5c715c5a-b613-43a0-9f22-5f59af3ae1fc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las cosas de los mayores son interesantes 👜', body_es = 'Rebuscar en tu bolso o intentar ponerse los zapatos de papá es su pasatiempo favorito. Déjale explorar tus cosas que no sean peligrosas.', title_fr = 'Les affaires des grands sont fascinantes. 👜', body_fr = 'Fouiller dans votre sac ou essayer les chaussures de papa est son activité préférée. Laissez-le explorer vos affaires sans danger.', title_hi = 'बड़ों की चीज़ें दिलचस्प होती हैं। 👜', body_hi = 'आपका बैग टटोलना या पापा के जूते पहनने की कोशिश करना उसका सबसे पसंदीदा काम है। अपनी सुरक्षित चीज़ों की खोज पर आँखें मूँद लीजिए।', title_id = 'Barang orang dewasa itu menarik. 👜', body_id = 'Mengobrak-abrik tas Anda atau mencoba memakai sepatu ayah adalah kegiatan favoritnya. Biarkan ia menjelajahi barang-barang Anda yang aman.', title_ja = '大人のものに興味津々 👜', body_ja = 'あなたのバッグをあさったり、パパの靴を履こうとしたりするのが大好き。安全なものなら、探検させてあげましょう。', title_ko = '어른들 물건은 흥미진진해요. 👜', body_ko = '엄마 가방을 뒤지거나 아빠 신발을 신어 보는 게 가장 좋아하는 놀이예요. 안전한 물건이라면 마음껏 탐험하게 눈감아 주세요.', title_nl = 'Spullen van grote mensen zijn interessant. 👜', body_nl = 'In je tas rommelen of papa''s schoenen aantrekken is zijn favoriete bezigheid. Laat hem gerust je veilige spullen ontdekken.', title_pl = 'Rzeczy dorosłych są ciekawe. 👜', body_pl = 'Grzebanie w twojej torebce albo przymierzanie butów taty to jego ulubione zajęcie. Przymknij oko, gdy odkrywa twoje bezpieczne rzeczy.', title_pt = 'As coisas dos adultos são interessantes. 👜', body_pt = 'Remexer na sua mala ou tentar calçar os sapatos do pai é a atividade preferida dele. Deixe-o explorar as suas coisas que sejam seguras.', title_sv = 'De vuxnas saker är spännande. 👜', body_sv = 'Att rota i din väska eller försöka ta på sig pappas skor är favoritsysselsättningen. Låt barnet utforska dina ofarliga saker.', title_vi = 'Đồ của người lớn thật thú vị. 👜', body_vi = 'Lục túi xách của mẹ hay thử đi giày của bố là trò bé thích nhất. Hãy để bé khám phá những món đồ an toàn của mẹ nhé.', title_zh = '大人的东西真有趣 👜', body_zh = '翻你的包，或者穿爸爸的鞋，是他最爱做的事。安全的东西就让他去探索吧。' WHERE id = 'd3844bde-9596-474d-adfe-9c81a7e0ff26' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte del garabato 🖍️', body_es = '¿Cuando le das un lápiz intenta garabatear en el papel? Es un ejercicio estupendo para la motricidad fina. Asegúrate de que los lápices sean seguros.', title_fr = 'L''art du gribouillage 🖍️', body_fr = 'Quand vous lui donnez un crayon, il essaie de gribouiller sur le papier ? C''est un superbe exercice pour sa motricité fine. Vérifiez simplement que les crayons sont sans danger.', title_hi = 'लकीरें खींचने की कला 🖍️', body_hi = 'हाथ में पेन देने पर कागज़ पर लकीरें खींचने की कोशिश करता है? बारीक मोटर स्किल्स के लिए यह शानदार अभ्यास है। पक्का कीजिए कि पेन सुरक्षित हों।', title_id = 'Seni mencoret-coret 🖍️', body_id = 'Saat diberi pensil, ia mencoba mencoret-coret kertas? Ini latihan hebat untuk motorik halusnya. Pastikan pensilnya aman.', title_ja = 'なぐり描きアート 🖍️', body_ja = 'クレヨンを渡すと、紙になぐり描きしようとしますか？手先の発達にすばらしい練習です。安全な画材かどうか確認しておきましょう。', title_ko = '끄적이기의 기술 🖍️', body_ko = '펜을 쥐여 주면 종이에 끄적이려 하나요? 소근육에 아주 좋은 연습이에요. 펜이 안전한지 꼭 확인하세요.', title_nl = 'De kunst van het krassen 🖍️', body_nl = 'Probeert je kindje op papier te krassen als je hem een potlood geeft? Een geweldige oefening voor de fijne motoriek. Zorg dat de potloden veilig zijn.', title_pl = 'Sztuka bazgrania 🖍️', body_pl = 'Gdy dasz mu kredkę, próbuje bazgrać po kartce? To wspaniałe ćwiczenie motoryki małej. Upewnij się, że kredki są bezpieczne.', title_pt = 'A arte dos rabiscos 🖍️', body_pt = 'Quando lhe dá um lápis, tenta rabiscar no papel? É um treino fantástico para a motricidade fina. Confirme que os lápis são seguros.', title_sv = 'Klotterkonst 🖍️', body_sv = 'Försöker barnet klottra på papper när du ger det en penna? Det är en fantastisk övning för finmotoriken. Se till att pennorna är säkra.', title_vi = 'Nghệ thuật vẽ nguệch ngoạc 🖍️', body_vi = 'Mẹ đưa bút là bé cố vẽ nguệch ngoạc trên giấy? Đây là bài tập tuyệt vời cho vận động tinh. Hãy đảm bảo bút an toàn cho bé nhé.', title_zh = '涂鸦的艺术 🖍️', body_zh = '你给他一支笔，他就想在纸上涂涂画画？这是很棒的精细动作练习。确保笔是安全的。' WHERE id = '68c3e726-41d6-481a-91d7-a89fa5795172' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se libera en un ambiente tranquilo.', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme.', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ रोशनियाँ और स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ शांत माहौल में बनता है।', body_id = '1 jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang.', body_ja = '寝る1時間前には、家の明るい照明と画面をすべて消しましょう。メラトニンは落ち着いた環境でこそ分泌されます。', body_ko = '잠들기 1시간 전에는 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 차분한 환경에서만 분비돼요.', body_nl = 'Doe een uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving aangemaakt.', body_pl = 'Godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym otoczeniu.', body_pt = '1 hora antes de dormir, apague todas as luzes fortes e ecrãs da casa. A melatonina só é libertada num ambiente calmo.', body_sv = 'Släck alla starka lampor och skärmar i hemmet 1 timme före läggdags. Melatonin bildas bara i en lugn miljö.', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh.', body_zh = '睡前1小时，关掉家里所有的昏暗灯光和屏幕。褪黑素只有在安静的环境中才会分泌。' WHERE id = '24b47242-9a10-48f7-a928-0a19449b984a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Búsqueda del tesoro en la naturaleza 🍂', body_es = 'Al pasear por el parque, recoged hojas distintas o piñas. Descubre en Lugares para mamás parques nuevos con paisajes naturales diferentes.', title_fr = 'Chasse au trésor dans la nature. 🍂', body_fr = 'En vous promenant au parc, ramassez différentes feuilles ou des pommes de pin. Découvrez dans les Lieux adaptés aux mamans de nouveaux parcs aux paysages variés.', title_hi = 'प्रकृति में खज़ाने की खोज। 🍂', body_hi = 'पार्क में घूमते समय अलग-अलग पत्तियाँ या चीड़ के फल इकट्ठे कीजिए। माँ के लिए अनुकूल जगहों में अलग प्राकृतिक नज़ारों वाले नए पार्क खोजिए।', title_id = 'Berburu harta karun di alam. 🍂', body_id = 'Saat jalan-jalan di taman, kumpulkan berbagai daun atau buah pinus. Temukan taman baru dengan pemandangan alam yang berbeda di Tempat Ramah Ibu.', title_ja = '自然の中で宝さがし 🍂', body_ja = '公園を歩きながら、いろいろな葉っぱや松ぼっくりを集めましょう。「ママにやさしいスポット」で、ちがう自然の景色が楽しめる新しい公園を見つけましょう。', title_ko = '자연 속 보물찾기. 🍂', body_ko = '공원을 걸으며 여러 가지 나뭇잎이나 솔방울을 모아 보세요. 엄마 친화 장소에서 색다른 자연 풍경이 있는 새 공원을 찾아보세요.', title_nl = 'Schattenjacht in de natuur. 🍂', body_nl = 'Verzamel tijdens een wandeling in het park verschillende blaadjes of dennenappels. Ontdek in Mamavriendelijke plekken nieuwe parken met andere natuur.', title_pl = 'Poszukiwanie skarbów w naturze. 🍂', body_pl = 'Na spacerze w parku zbierajcie różne liście lub szyszki. Odkryj w Miejscach przyjaznych mamom nowe parki z innymi krajobrazami.', title_pt = 'Caça ao tesouro na natureza. 🍂', body_pt = 'Durante o passeio no parque, apanhem folhas diferentes ou pinhas. Descubra nos Locais Amigos das Mães parques novos com paisagens naturais diferentes.', title_sv = 'Skattjakt i naturen. 🍂', body_sv = 'Samla olika löv eller kottar när ni promenerar i parken. Upptäck nya parker med annorlunda naturmiljöer i Mammavänliga platser.', title_vi = 'Săn kho báu giữa thiên nhiên. 🍂', body_vi = 'Khi đi dạo ở công viên, hãy cùng bé nhặt những chiếc lá hay quả thông khác nhau. Hãy khám phá những công viên mới với cảnh sắc thiên nhiên đa dạng trong Địa điểm thân thiện với mẹ.', title_zh = '大自然寻宝 🍂', body_zh = '在公园散步时收集不同的树叶或松果。在妈妈友好场所里发现更多有不同自然风光的新公园吧。' WHERE id = '2d66c314-cb67-48c8-93d1-be3249bad125' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sonidos de animales 🐶', body_es = '¿Intenta decir «miau» al ver un gato y «guau, guau» al ver un perro? El vocabulario empieza por los sonidos de los animales. Jugad juntos a esto.', title_fr = 'Les cris des animaux 🐶', body_fr = 'Il essaie de faire « miaou » en voyant un chat et « ouaf-ouaf » en voyant un chien ? Son vocabulaire commence par les cris des animaux. Jouez à ce jeu avec lui.', title_hi = 'जानवरों की आवाज़ें 🐶', body_hi = 'बिल्ली देखकर ''म्याऊँ'' और कुत्ता देखकर ''भौं-भौं'' कहने की कोशिश करता है? शब्द भंडार जानवरों की आवाज़ों से शुरू होता है। उसके साथ यह खेल खेलिए।', title_id = 'Suara hewan 🐶', body_id = 'Saat melihat kucing ia mencoba bilang "meong", dan saat melihat anjing "guk-guk"? Kosakata dimulai dari suara hewan. Mainkan permainan ini bersamanya.', title_ja = '動物の鳴き声 🐶', body_ja = 'ねこを見ると「にゃあ」、犬を見ると「わんわん」と言おうとしますか？語彙は動物の鳴き声から始まります。一緒にこの遊びをしましょう。', title_ko = '동물 소리 🐶', body_ko = '고양이를 보면 야옹, 강아지를 보면 멍멍 하려고 하나요? 어휘는 동물 소리에서 시작돼요. 함께 이 놀이를 해 보세요.', title_nl = 'Dierengeluiden 🐶', body_nl = 'Probeert je kindje miauw te zeggen bij een poes en waf-waf bij een hond? De woordenschat begint met dierengeluiden. Speel dit spelletje samen.', title_pl = 'Odgłosy zwierząt 🐶', body_pl = 'Na widok kota próbuje mówić „miau”, a na widok psa „hau-hau”? Zasób słów zaczyna się od odgłosów zwierząt. Pobawcie się w to razem.', title_pt = 'Sons de animais 🐶', body_pt = 'Quando vê um gato tenta dizer "miau" e, quando vê um cão, "ão-ão"? O vocabulário começa pelos sons dos animais. Brinque com ele a este jogo.', title_sv = 'Djurläten 🐶', body_sv = 'Försöker barnet säga mjau när det ser en katt och vov-vov när det ser en hund? Ordförrådet börjar med djurläten. Lek den här leken tillsammans.', title_vi = 'Tiếng kêu của con vật 🐶', body_vi = 'Thấy mèo là bé kêu "meo meo", thấy chó là "gâu gâu"? Vốn từ bắt đầu từ tiếng kêu của con vật. Hãy chơi trò này cùng bé nhé.', title_zh = '动物叫声 🐶', body_zh = '看到猫就“喵喵”，看到狗就“汪汪”？词汇量从动物叫声开始。和他一起玩这个游戏吧。' WHERE id = '98db8b9f-36cd-4968-86c5-ed66999457de' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Búsqueda del tesoro en la naturaleza 🍂', body_es = 'Al pasear por el parque, recoged hojas distintas o piñas. Descubre en Lugares para mamás parques nuevos con paisajes naturales diferentes.', title_fr = 'Chasse au trésor dans la nature. 🍂', body_fr = 'En vous promenant au parc, ramassez différentes feuilles ou des pommes de pin. Découvrez dans les Lieux adaptés aux mamans de nouveaux parcs aux paysages variés.', title_hi = 'प्रकृति में खज़ाने की खोज। 🍂', body_hi = 'पार्क में घूमते समय अलग-अलग पत्तियाँ या चीड़ के फल इकट्ठे कीजिए। माँ के लिए अनुकूल जगहों में अलग प्राकृतिक नज़ारों वाले नए पार्क खोजिए।', title_id = 'Berburu harta karun di alam. 🍂', body_id = 'Saat jalan-jalan di taman, kumpulkan berbagai daun atau buah pinus. Temukan taman baru dengan pemandangan alam yang berbeda di Tempat Ramah Ibu.', title_ja = '自然の中で宝さがし 🍂', body_ja = '公園を歩きながら、いろいろな葉っぱや松ぼっくりを集めましょう。「ママにやさしいスポット」で、ちがう自然の景色が楽しめる新しい公園を見つけましょう。', title_ko = '자연 속 보물찾기. 🍂', body_ko = '공원을 걸으며 여러 가지 나뭇잎이나 솔방울을 모아 보세요. 엄마 친화 장소에서 색다른 자연 풍경이 있는 새 공원을 찾아보세요.', title_nl = 'Schattenjacht in de natuur. 🍂', body_nl = 'Verzamel tijdens een wandeling in het park verschillende blaadjes of dennenappels. Ontdek in Mamavriendelijke plekken nieuwe parken met andere natuur.', title_pl = 'Poszukiwanie skarbów w naturze. 🍂', body_pl = 'Na spacerze w parku zbierajcie różne liście lub szyszki. Odkryj w Miejscach przyjaznych mamom nowe parki z innymi krajobrazami.', title_pt = 'Caça ao tesouro na natureza. 🍂', body_pt = 'Durante o passeio no parque, apanhem folhas diferentes ou pinhas. Descubra nos Locais Amigos das Mães parques novos com paisagens naturais diferentes.', title_sv = 'Skattjakt i naturen. 🍂', body_sv = 'Samla olika löv eller kottar när ni promenerar i parken. Upptäck nya parker med annorlunda naturmiljöer i Mammavänliga platser.', title_vi = 'Săn kho báu giữa thiên nhiên. 🍂', body_vi = 'Khi đi dạo ở công viên, hãy cùng bé nhặt những chiếc lá hay quả thông khác nhau. Hãy khám phá những công viên mới với cảnh sắc thiên nhiên đa dạng trong Địa điểm thân thiện với mẹ.', title_zh = '大自然寻宝 🍂', body_zh = '在公园散步时收集不同的树叶或松果。在妈妈友好场所里发现更多有不同自然风光的新公园吧。' WHERE id = '8e91be33-56a9-43aa-bf49-8aa525510abf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La etapa de llenar y vaciar! 📦', body_es = '¡Meter los juguetes en una caja grande y luego volcarlos todos de golpe en el suelo! Este juego de causa y efecto desarrolla su lógica.', title_fr = 'La période du remplir-vider ! 📦', body_fr = 'Ranger ses jouets dans une grande boîte, puis tout renverser d''un coup par terre ! Ce jeu de cause à effet développe sa logique.', title_hi = 'भरने-खाली करने का दौर! 📦', body_hi = 'खिलौने एक बड़े डिब्बे में भरना, फिर सब एक साथ ज़मीन पर उलट देना! कारण और परिणाम का यह खेल उसकी तर्क शक्ति विकसित करता है।', title_id = 'Masa isi dan tumpahkan! 📦', body_id = 'Mengumpulkan mainan ke kotak besar, lalu menumpahkan semuanya sekaligus ke lantai! Permainan sebab-akibat ini mengembangkan logikanya.', title_ja = '入れたり出したりの時期！📦', body_ja = 'おもちゃを大きな箱に集めて、一気に床にひっくり返す！この原因と結果の遊びが、論理的に考える力を育てます。', title_ko = '채우고 쏟는 시기! 📦', body_ko = '장난감을 큰 상자에 모았다가 한꺼번에 바닥에 쏟아요! 이 원인과 결과 놀이가 논리력을 키워 줘요.', title_nl = 'De fase van vullen en legen! 📦', body_nl = 'Speelgoed in een grote doos stoppen en dan alles in één keer op de grond gooien! Dit oorzaak-en-gevolgspel ontwikkelt zijn logisch denken.', title_pl = 'Etap napełniania i wysypywania! 📦', body_pl = 'Zbiera zabawki do dużego pudełka, a potem wysypuje wszystkie naraz na podłogę! Ta zabawa w przyczynę i skutek rozwija jego logiczne myślenie.', title_pt = 'A fase de encher e esvaziar! 📦', body_pt = 'Juntar os brinquedos numa caixa grande e depois despejá-los todos de uma vez no chão! Este jogo de causa e efeito desenvolve o raciocínio lógico.', title_sv = 'Fylla och tömma-perioden! 📦', body_sv = 'Samla alla leksaker i en stor låda och sedan tömma ut allt på golvet på en gång! Den här orsak-och-verkan-leken utvecklar logiken.', title_vi = 'Giai đoạn bỏ vào, đổ ra! 📦', body_vi = 'Gom đồ chơi vào một chiếc hộp lớn rồi đổ hết ra sàn cùng lúc! Trò chơi nhân quả này giúp phát triển tư duy logic của bé.', title_zh = '装满再倒空的阶段！📦', body_zh = '把玩具装进大盒子，再一下子全倒在地上！这个因果游戏能锻炼他的逻辑思维。' WHERE id = 'e0bce3ef-dd35-48ce-9b1d-dc4a7ba30ba8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te ahoga la idea de «nunca volveré a ser la de antes»? Comparte este sentimiento pasajero con las mamás de la Comunidad Anacan.', body_fr = 'La pensée « Je ne redeviendrai jamais comme avant » vous étouffe ? Partagez ce sentiment passager avec les mamans de la Communauté Anacan.', body_hi = '''मैं कभी पहले जैसी नहीं हो पाऊँगी'' यह सोच आपको घुटन दे रही है? इस गुज़र जाने वाली भावना को Anacan कम्युनिटी की माँओं के साथ बाँटिए।', body_id = 'Pikiran "Aku tidak akan pernah bisa jadi diriku yang dulu" membuat Anda sesak? Bagikan perasaan yang hanya sementara ini dengan para ibu di Komunitas Anacan.', body_ja = '「もう昔の自分には戻れない」という思いに押しつぶされそうですか？Anacanコミュニティのママたちと、この一時的な気持ちを分かち合いましょう。', body_ko = '''예전의 나로는 다시 돌아갈 수 없을 거야''라는 생각에 숨이 막히나요? 지나가는 이 감정을 Anacan 커뮤니티의 엄마들과 나눠 보세요.', body_nl = 'Word je overspoeld door de gedachte: ik word nooit meer de oude? Deel dit tijdelijke gevoel met de moeders in de Anacan Community.', body_pl = 'Dusi cię myśl „Już nigdy nie będę dawną sobą”? Podziel się tym przemijającym uczuciem z mamami w Społeczności Anacan.', body_pt = 'O pensamento "Nunca mais vou voltar a ser quem era" sufoca-a? Partilhe este sentimento passageiro com as mães da Comunidade Anacan.', body_sv = 'Kvävs du av tanken ”Jag kommer aldrig att bli mitt gamla jag igen”? Dela den här övergående känslan med mammorna i Anacans Community.', body_vi = 'Ý nghĩ "Mình sẽ không bao giờ được là mình như trước nữa" khiến mẹ ngột ngạt? Hãy chia sẻ cảm xúc thoáng qua này với các mẹ trong Cộng đồng Anacan.', body_zh = '“我再也回不到从前的自己了”这个念头压得你喘不过气？和Anacan社区的妈妈们聊聊这种暂时的感受吧。' WHERE id = '1ba81e06-af3c-43ed-b2c1-9d0d1b231a26' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de la noche es mágico 📖', body_es = 'Ahora es él quien te señala los dibujos del libro. Un cuento corto leído juntos antes de dormir refuerza muchísimo vuestro vínculo.', title_fr = 'L''histoire du soir est magique. 📖', body_fr = 'Il vous montre lui aussi les images du livre. Une petite histoire lue ensemble avant de dormir renforce incroyablement votre lien.', title_hi = 'शाम की कहानी जादुई होती है। 📖', body_hi = 'अब वह भी आपको किताब की तस्वीरें दिखाता है। सोने से पहले साथ पढ़ी गई छोटी कहानी आपके रिश्ते को बहुत मज़बूत बनाती है।', title_id = 'Dongeng malam itu ajaib. 📖', body_id = 'Kini ia juga menunjukkan gambar-gambar di buku kepada Anda. Cerita pendek yang dibaca bersama sebelum tidur sangat mempererat ikatan kalian.', title_ja = '寝る前のお話は魔法の時間 📖', body_ja = '絵本の絵を、今度はお子さんがあなたに指さして教えてくれます。寝る前に一緒に読む短いお話は、親子のきずなをぐっと深めてくれます。', title_ko = '잠자리 동화는 마법이에요. 📖', body_ko = '이제 아이도 책 속 그림을 엄마에게 가리켜 보여 줘요. 잠들기 전 함께 읽는 짧은 이야기가 두 사람의 유대를 놀랍도록 깊게 해 줘요.', title_nl = 'Een verhaaltje voor het slapen is magisch. 📖', body_nl = 'Je kindje wijst je nu ook de plaatjes in het boek aan. Een kort verhaaltje dat jullie samen lezen voor het slapengaan versterkt jullie band enorm.', title_pl = 'Wieczorna bajka jest magiczna. 📖', body_pl = 'Teraz to on pokazuje ci obrazki w książce. Krótka historia czytana razem przed snem niesamowicie wzmacnia więź między wami.', title_pt = 'A história da noite é mágica. 📖', body_pt = 'Agora é ele que lhe mostra as imagens do livro. Uma pequena história lida em conjunto antes de dormir fortalece imenso o laço entre vocês.', title_sv = 'Kvällssagan är magisk. 📖', body_sv = 'Nu pekar barnet också ut bilderna i boken för dig. En liten berättelse som ni läser tillsammans före sömnen stärker bandet mellan er otroligt mycket.', title_vi = 'Truyện kể buổi tối thật kỳ diệu. 📖', body_vi = 'Giờ bé cũng chỉ cho mẹ xem tranh trong sách. Một câu chuyện ngắn cùng đọc trước giờ ngủ giúp gắn kết mẹ con mạnh mẽ vô cùng.', title_zh = '睡前故事有魔力 📖', body_zh = '宝宝已经会指着书里的图画给你看了。睡前一起读一个小故事，能让你们之间的联结变得无比紧密。' WHERE id = '679e2936-6a93-4a92-9069-b372c4d3f661' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La etapa de llenar y vaciar! 📦', body_es = '¡Meter los juguetes en una caja grande y luego volcarlos todos de golpe en el suelo! Este juego de causa y efecto desarrolla su lógica.', title_fr = 'La période du remplir-vider ! 📦', body_fr = 'Ranger ses jouets dans une grande boîte, puis tout renverser d''un coup par terre ! Ce jeu de cause à effet développe sa logique.', title_hi = 'भरने-खाली करने का दौर! 📦', body_hi = 'खिलौने एक बड़े डिब्बे में भरना, फिर सब एक साथ ज़मीन पर उलट देना! कारण और परिणाम का यह खेल उसकी तर्क शक्ति विकसित करता है।', title_id = 'Masa isi dan tumpahkan! 📦', body_id = 'Mengumpulkan mainan ke kotak besar, lalu menumpahkan semuanya sekaligus ke lantai! Permainan sebab-akibat ini mengembangkan logikanya.', title_ja = '入れたり出したりの時期！📦', body_ja = 'おもちゃを大きな箱に集めて、一気に床にひっくり返す！この原因と結果の遊びが、論理的に考える力を育てます。', title_ko = '채우고 쏟는 시기! 📦', body_ko = '장난감을 큰 상자에 모았다가 한꺼번에 바닥에 쏟아요! 이 원인과 결과 놀이가 논리력을 키워 줘요.', title_nl = 'De fase van vullen en legen! 📦', body_nl = 'Speelgoed in een grote doos stoppen en dan alles in één keer op de grond gooien! Dit oorzaak-en-gevolgspel ontwikkelt zijn logisch denken.', title_pl = 'Etap napełniania i wysypywania! 📦', body_pl = 'Zbiera zabawki do dużego pudełka, a potem wysypuje wszystkie naraz na podłogę! Ta zabawa w przyczynę i skutek rozwija jego logiczne myślenie.', title_pt = 'A fase de encher e esvaziar! 📦', body_pt = 'Juntar os brinquedos numa caixa grande e depois despejá-los todos de uma vez no chão! Este jogo de causa e efeito desenvolve o raciocínio lógico.', title_sv = 'Fylla och tömma-perioden! 📦', body_sv = 'Samla alla leksaker i en stor låda och sedan tömma ut allt på golvet på en gång! Den här orsak-och-verkan-leken utvecklar logiken.', title_vi = 'Giai đoạn bỏ vào, đổ ra! 📦', body_vi = 'Gom đồ chơi vào một chiếc hộp lớn rồi đổ hết ra sàn cùng lúc! Trò chơi nhân quả này giúp phát triển tư duy logic của bé.', title_zh = '装满再倒空的阶段！📦', body_zh = '把玩具装进大盒子，再一下子全倒在地上！这个因果游戏能锻炼他的逻辑思维。' WHERE id = 'fbb768fe-d41f-4451-8978-b683840f7855' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dale la oportunidad de elegir 👕', body_es = '«¿Te pones la camiseta roja o la azul?»: darle pequeñas opciones reduce la terquedad y refuerza su sentido de sí mismo.', title_fr = 'Laissez-lui le choix. 👕', body_fr = '« Tu mets le t-shirt rouge ou le bleu ? » - Lui proposer de petits choix réduit l''entêtement et renforce son sentiment d''identité.', title_hi = 'चुनने का हक दीजिए। 👕', body_hi = '''लाल कमीज़ पहनोगे या नीली?'' उसे छोटे-छोटे विकल्प देने से ज़िद कम होती है और उसकी अपनी पहचान की भावना मज़बूत होती है।', title_id = 'Beri ia hak memilih. 👕', body_id = '"Mau pakai kaus merah atau biru?" Memberi pilihan kecil mengurangi sikap keras kepala dan memperkuat rasa dirinya.', title_ja = '選ぶ権利をあげよう 👕', body_ja = '「赤いシャツにする？青いのにする？」小さな選択肢をあげることで、いやいやが減り、自分らしさが育ちます。', title_ko = '선택권을 주세요. 👕', body_ko = '"빨간 티 입을래, 파란 티 입을래?" 작은 선택권을 주면 고집이 줄고 자아감이 단단해져요.', title_nl = 'Laat hem kiezen. 👕', body_nl = 'Trek je het rode shirt aan of het blauwe? Kleine keuzes geven vermindert koppigheid en versterkt zijn gevoel van eigenwaarde.', title_pl = 'Daj mu prawo wyboru. 👕', body_pl = '„Zakładasz czerwoną koszulkę czy niebieską?” Dawanie mu małych wyborów zmniejsza upór i wzmacnia poczucie własnego „ja”.', title_pt = 'Dê-lhe o direito de escolher. 👕', body_pt = '"Vestes a camisola vermelha ou a azul?": dar-lhe pequenas escolhas reduz a teimosia e reforça o sentido de si próprio.', title_sv = 'Ge barnet rätt att välja. 👕', body_sv = '”Vill du ha den röda tröjan eller den blå?” Att ge små valmöjligheter minskar trotset och stärker självkänslan.', title_vi = 'Cho bé quyền lựa chọn. 👕', body_vi = '"Con mặc áo đỏ hay áo xanh?": cho bé những lựa chọn nhỏ giúp giảm bướng bỉnh và tăng ý thức về bản thân.', title_zh = '给他选择的权利 👕', body_zh = '“你想穿红衣服还是蓝衣服？”给他一些小选择，能减少倔强，增强自我意识。' WHERE id = 'cd9fb3be-79a5-4ecd-980a-171e6fa00ed4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Escondite avanzado! 🙈', body_es = '¿Encuentra su juguete fácilmente aunque lo escondas bajo dos mantas distintas? Ya entiende del todo que los objetos siguen existiendo aunque no los vea.', title_fr = 'Cache-cache niveau expert ! 🙈', body_fr = 'Il retrouve facilement son jouet même caché sous deux tissus différents ? Il a parfaitement compris que les objets continuent d''exister.', title_hi = 'मुश्किल लुका-छिपी! 🙈', body_hi = 'खिलौने को दो अलग कपड़ों के नीचे छिपाने पर भी वह उसे आसानी से ढूँढ लेता है? चीज़ों के स्थायी होने की समझ पूरी तरह बन गई है।', title_id = 'Petak umpet tingkat lanjut! 🙈', body_id = 'Ia tetap mudah menemukan mainannya meski Anda sembunyikan di bawah dua penutup berbeda? Pemahamannya bahwa benda tetap ada sudah terbentuk sepenuhnya.', title_ja = 'レベルアップしたかくれんぼ！🙈', body_ja = '2つのちがう布の下におもちゃを隠しても、すぐに見つけられますか？物が見えなくてもそこにあることを、しっかり理解しています。', title_ko = '어려운 숨바꼭질! 🙈', body_ko = '장난감을 두 개의 덮개 중 하나에 숨겨도 쉽게 찾아내나요? 대상 영속성 개념이 완전히 자리 잡았어요.', title_nl = 'Moeilijker verstoppertje! 🙈', body_nl = 'Vindt je kindje zijn speeltje makkelijk terug, zelfs als je het onder twee verschillende doeken verstopt? Hij begrijpt nu helemaal dat dingen blijven bestaan.', title_pl = 'Zaawansowana zabawa w chowanego! 🙈', body_pl = 'Łatwo znajduje zabawkę, nawet gdy schowasz ją pod jednym z dwóch przykryć? W pełni rozumie już, że przedmioty istnieją, nawet gdy ich nie widać.', title_pt = 'Escondidas mais difíceis! 🙈', body_pt = 'Encontra facilmente o brinquedo mesmo quando o esconde debaixo de duas coberturas diferentes? A noção de permanência dos objetos está totalmente formada.', title_sv = 'Avancerad kurragömma! 🙈', body_sv = 'Hittar barnet leksaken lätt även när du gömmer den under två olika filtar? Förståelsen för att föremål finns kvar är helt på plats.', title_vi = 'Trốn tìm nâng cao! 🙈', body_vi = 'Mẹ giấu đồ chơi dưới một trong hai tấm phủ mà bé vẫn tìm ra dễ dàng? Khái niệm về sự tồn tại của đồ vật đã hình thành hoàn chỉnh.', title_zh = '升级版捉迷藏！🙈', body_zh = '即使把玩具藏在两块不同的布下面，他也能轻松找到？“物体恒存”的概念已经完全形成了。' WHERE id = 'd25d87b5-6fc8-47d3-a3b2-ce74b55cbbfe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Empiezan las carreras! 🏃‍♂', body_es = '️ Sus pasos rápidos ya se están convirtiendo en pequeñas carreras. Aunque proteger sus rodillas cueste más, ¡ver su alegría y su libertad merece la pena!', title_fr = 'Les premières courses commencent ! 🏃‍♂', body_fr = '️ Ses pas rapides se transforment déjà en petites courses. Protéger ses genoux devient plus difficile, mais voir sa joie de liberté vaut tout l''or du monde !', title_hi = 'दौड़ने का अभ्यास शुरू! 🏃‍♂', body_hi = '️ तेज़ कदम अब छोटी-छोटी दौड़ में बदल रहे हैं। भले घुटनों को बचाना मुश्किल हो रहा हो, उसकी आज़ादी की इस खुशी को देखना सब कुछ सार्थक कर देता है!', title_id = 'Latihan berlari dimulai! 🏃‍♂', body_id = '️ Langkah-langkah cepatnya kini berubah menjadi lari-lari kecil. Meski makin sulit melindungi lututnya, melihat kegembiraannya menikmati kebebasan sungguh sepadan!', title_ja = '走る練習が始まる！🏃‍♂', body_ja = '️速い足取りが、小さなかけっこに変わってきました。ひざを守るのは大変になっても、自由を楽しむ姿を見るのは何よりの価値があります！', title_ko = '달리기 연습이 시작돼요! 🏃‍♂', body_ko = '️빠른 걸음이 이제 짧은 달리기로 바뀌고 있어요. 무릎을 지켜 주기는 더 어려워지지만, 자유를 누리는 아이의 기쁨을 보는 건 그 무엇보다 값져요!', title_nl = 'Het rennen begint! 🏃‍♂', body_nl = '️ Snelle stapjes worden kleine sprintjes. Zijn knietjes beschermen wordt lastiger, maar zijn blijdschap over deze vrijheid is alles waard!', title_pl = 'Zaczynają się treningi biegania! 🏃‍♂', body_pl = '️ Szybkie kroki zamieniają się w małe biegi. Choć coraz trudniej chronić jego kolana, patrzenie na tę radość wolności jest warte wszystkiego!', title_pt = 'Começam os treinos de corrida! 🏃‍♂', body_pt = '️ Os passos rápidos já se transformam em pequenas corridas. Proteger os joelhos fica mais difícil, mas ver esta alegria de liberdade vale tudo!', title_sv = 'Löpträningen börjar! 🏃‍♂', body_sv = '️ De snabba stegen blir nu till små springturer. Även om det blir svårare att skydda knäna är det värt allt att se barnets glädje över friheten!', title_vi = 'Bắt đầu tập chạy! 🏃‍♂', body_vi = '️ Những bước đi nhanh giờ đã thành những bước chạy nhỏ. Dù khó bảo vệ đầu gối hơn, nhưng được ngắm bé hân hoan tự do thì thật đáng giá!', title_zh = '开始练习跑步！🏃‍♂', body_zh = '️ 快步走已经变成了小跑。护住膝盖越来越难，但看着他享受这份自由的快乐，一切都值得！' WHERE id = '373a30b7-4c10-4d16-b029-a2c123ab28b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Abierto a nuevas texturas 🥦', body_es = 'Cambia los colores y las formas de sus comidas para abrirle el apetito. Inspírate en la sección Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Il s''ouvre à de nouvelles textures. 🥦', body_fr = 'Variez les couleurs et les formes de ses repas pour stimuler son appétit. Pour des idées, inspirez-vous des Recettes pour bébés qui commencent la diversification.', title_hi = 'अलग-अलग बनावट के लिए तैयार है। 🥦', body_hi = 'खाने के रंग और आकार बदलकर उसकी भूख बढ़ाइए। आइडिया के लिए ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी सेक्शन से प्रेरणा लीजिए।', title_id = 'Terbuka pada tekstur baru. 🥦', body_id = 'Tingkatkan nafsu makannya dengan mengubah warna dan bentuk makanannya. Cari inspirasi di bagian Resep untuk bayi yang mulai MPASI.', title_ja = 'いろいろな食感に挑戦 🥦', body_ja = '料理の色や形を変えて、食欲を引き出しましょう。アイデアは「離乳食を始める赤ちゃんのレシピ」からヒントをもらって。', title_ko = '다양한 식감에 열려 있어요. 🥦', body_ko = '음식의 색과 모양을 바꿔 입맛을 돋워 주세요. 아이디어는 레시피 섹션의 이유식을 시작하는 아기를 위한 레시피에서 얻어 보세요.', title_nl = 'Open voor nieuwe structuren. 🥦', body_nl = 'Wissel de kleuren en vormen van zijn eten af om zijn eetlust te stimuleren. Laat je inspireren door het onderdeel Recepten voor baby''s die met bijvoeding beginnen.', title_pl = 'Otwarty na nowe konsystencje. 🥦', body_pl = 'Pobudź jego apetyt, zmieniając kolory i kształty dań. Inspiracji szukaj w sekcji Przepisy dla niemowląt rozpoczynających rozszerzanie diety.', title_pt = 'Aberto a novas texturas. 🥦', body_pt = 'Aumente-lhe o apetite variando as cores e as formas das refeições. Para ideias, inspire-se nas Receitas para bebés em diversificação alimentar.', title_sv = 'Öppen för nya konsistenser. 🥦', body_sv = 'Väck aptiten genom att variera färger och former på maten. Hämta inspiration i avsnittet Recept för bebisar som börjar med fast föda.', title_vi = 'Bé sẵn sàng với nhiều kết cấu mới. 🥦', body_vi = 'Hãy kích thích vị giác của bé bằng cách thay đổi màu sắc và hình dạng món ăn. Tìm cảm hứng trong mục Công thức cho bé bắt đầu ăn dặm nhé.', title_zh = '乐于尝试不同口感 🥦', body_zh = '变换食物的颜色和形状，增加他的食欲。去食谱板块的辅食宝宝食谱里找找灵感吧。' WHERE id = '5a23341a-91f5-4bdf-a760-e7b99f610283' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Eres una auténtica heroína 🛁', body_es = 'Has seguido todo el día a un peque que no para. Ahora sírvete un té calentito y descansa sin pensar en nada.', title_fr = 'Vous êtes une vraie héroïne. 🛁', body_fr = 'Vous avez géré toute la journée un enfant qui court partout. Maintenant, servez-vous un thé chaud et reposez-vous sans penser à rien.', title_hi = 'आप असली हीरो हैं। 🛁', body_hi = 'आपने पूरे दिन एक दौड़ते-भागते बच्चे को संभाला। अब अपनी गरम चाय डालिए और बिना कुछ सोचे बस आराम कीजिए।', title_id = 'Anda pahlawan sejati. 🛁', body_id = 'Seharian Anda mengurus anak yang terus berlari ke sana kemari. Sekarang tuang teh hangat dan beristirahatlah tanpa memikirkan apa pun.', title_ja = 'あなたは本当のヒーローです 🛁', body_ja = '一日中動き回る子をみてきましたね。さあ、温かいお茶をいれて、何も考えずにゆっくり休みましょう。', title_ko = '엄마는 진짜 영웅이에요. 🛁', body_ko = '하루 종일 뛰어다니는 아이를 돌봤어요. 이제 따뜻한 차 한 잔을 따르고 아무 생각 없이 그냥 쉬세요.', title_nl = 'Je bent een echte held. 🛁', body_nl = 'Je hebt de hele dag een rondrennend kindje bijgehouden. Schenk nu een warme kop thee in en rust gewoon uit zonder ergens aan te denken.', title_pl = 'Jesteś prawdziwą bohaterką. 🛁', body_pl = 'Cały dzień ogarniałaś dziecko, które ciągle biega. Teraz nalej sobie gorącej herbaty i po prostu odpocznij, o niczym nie myśląc.', title_pt = 'É uma verdadeira heroína. 🛁', body_pt = 'Passou o dia a gerir uma criança que não para quieta. Agora sirva-se de um chá quente e descanse simplesmente, sem pensar em nada.', title_sv = 'Du är en riktig hjälte. 🛁', body_sv = 'Du har haft hand om ett barn som springer runt hela dagen. Häll nu upp ditt varma te och vila utan att tänka på något.', title_vi = 'Mẹ là người hùng thực sự. 🛁', body_vi = 'Cả ngày mẹ đã xoay xở với một em bé chạy nhảy không ngừng. Giờ hãy rót một tách trà nóng và nghỉ ngơi, chẳng cần nghĩ ngợi gì cả.', title_zh = '你是真正的英雄 🛁', body_zh = '你应付了一个跑了一整天的孩子。现在倒杯热茶，什么都别想，好好休息吧。' WHERE id = '6581c209-98c5-4f79-adf1-c7b985567899' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un tiempo solo para ti 🛁', body_es = 'Se ha dormido y la casa está en calma. Deja el móvil a un lado, pon tu película favorita y disfruta de no hacer nada.', title_fr = 'Un moment rien que pour vous. 🛁', body_fr = 'Il dort, la maison est calme. Posez votre téléphone, lancez un film que vous aimez et savourez simplement le plaisir de ne rien faire.', title_hi = 'यह समय सिर्फ़ आपका है। 🛁', body_hi = 'वह सो गया, घर शांत हो गया। अब फ़ोन एक तरफ़ रखिए, अपनी पसंदीदा फ़िल्म लगाइए और बस कुछ न करने का मज़ा लीजिए।', title_id = 'Waktu khusus untuk Anda. 🛁', body_id = 'Ia sudah tidur, rumah jadi tenang. Sekarang letakkan ponsel, putar film favorit Anda, dan nikmati saja waktu tanpa melakukan apa-apa.', title_ja = 'あなただけの時間 🛁', body_ja = 'お子さんが眠り、家が静かになりました。スマホは置いて、好きな映画をつけて、何もしない時間をただ味わいましょう。', title_ko = '오롯이 엄마만의 시간. 🛁', body_ko = '아이가 잠들고 집이 조용해졌어요. 이제 휴대폰은 내려놓고, 좋아하는 영화를 틀고, 아무것도 하지 않는 시간을 즐기세요.', title_nl = 'Tijd alleen voor jou. 🛁', body_nl = 'Je kindje slaapt en het huis is stil. Leg je telefoon weg, zet een film op die je leuk vindt en geniet gewoon van het nietsdoen.', title_pl = 'Czas tylko dla ciebie. 🛁', body_pl = 'Zasnął, w domu zrobiło się cicho. Teraz odłóż telefon, włącz ulubiony film i po prostu delektuj się nicnierobieniem.', title_pt = 'Um tempo só para si. 🛁', body_pt = 'Ele adormeceu e a casa ficou em silêncio. Agora ponha o telemóvel de lado, ponha a dar um filme de que goste e aproveite simplesmente o prazer de não fazer nada.', title_sv = 'Tid bara för dig. 🛁', body_sv = 'Barnet sover och det har blivit lugnt hemma. Lägg nu telefonen åt sidan, sätt på en film du gillar och njut bara av att inte göra något alls.', title_vi = 'Thời gian chỉ dành cho mẹ. 🛁', body_vi = 'Bé đã ngủ, căn nhà yên tĩnh. Giờ hãy đặt điện thoại sang một bên, mở một bộ phim yêu thích và tận hưởng việc chẳng phải làm gì cả.', title_zh = '只属于你的时间 🛁', body_zh = '宝宝睡了，家里安静了。现在把手机放一边，打开一部喜欢的电影，享受什么都不做的时光吧。' WHERE id = '1705b7a5-fb30-4cc3-974a-91a4210ec2a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hacia atrás y de lado! 🦀', body_es = 'Ya no solo camina hacia delante: pone a prueba su equilibrio dando pasos hacia atrás o de lado. Hazle fotos en estos momentos tan divertidos.', title_fr = 'En arrière et sur le côté ! 🦀', body_fr = 'Il ne marche plus seulement en avant, il teste son équilibre en faisant des pas en arrière ou sur le côté. Prenez absolument ces moments amusants en photo.', title_hi = 'पीछे-पीछे और बगल में चलना! 🦀', body_hi = 'अब वह सिर्फ़ आगे नहीं, पीछे और बगल में कदम रखकर अपना संतुलन परख रहा है। इन मज़ेदार पलों की फ़ोटो ज़रूर लीजिए।', title_id = 'Berjalan mundur dan menyamping! 🦀', body_id = 'Kini ia tidak hanya melangkah maju, tapi juga menguji keseimbangannya dengan melangkah mundur atau menyamping. Jangan lupa memotret momen seru ini.', title_ja = 'うしろ歩き、横歩き！🦀', body_ja = '前だけでなく、うしろや横にも歩いて、バランスを試しています。この楽しい瞬間をぜひ写真に残しましょう。', title_ko = '뒤로, 옆으로 걷기! 🦀', body_ko = '이제 앞으로만이 아니라 뒤로, 옆으로 걸으며 균형을 시험해요. 이 즐거운 순간을 꼭 사진으로 남기세요.', title_nl = 'Achteruit en opzij! 🦀', body_nl = 'Je kindje test zijn evenwicht nu niet alleen door vooruit te stappen, maar ook achteruit en opzij. Leg deze leuke momenten zeker vast op de foto.', title_pl = 'Do tyłu i w bok! 🦀', body_pl = 'Sprawdza już równowagę, robiąc kroki nie tylko do przodu, ale też do tyłu i w bok. Koniecznie uwiecznij te zabawne chwile na zdjęciu.', title_pt = 'Para trás e para os lados! 🦀', body_pt = 'Já não anda só para a frente, também dá passos para trás e para o lado, a pôr o equilíbrio à prova. Não deixe de fotografar estes momentos divertidos.', title_sv = 'Bakåt och åt sidan! 🦀', body_sv = 'Barnet testar nu balansen genom att ta steg inte bara framåt, utan också bakåt och åt sidan. Fånga dessa roliga stunder på bild.', title_vi = 'Đi lùi và đi ngang! 🦀', body_vi = 'Bé không chỉ bước tới mà còn thử thăng bằng bằng những bước lùi hay bước ngang. Mẹ nhớ chụp lại những khoảnh khắc vui nhộn này nhé.', title_zh = '往后走、横着走！🦀', body_zh = '宝宝不只往前走，还会往后退、横着走，测试自己的平衡。一定要把这些有趣的瞬间拍下来。' WHERE id = '60fa7d8e-7d2e-4789-b844-5bdd9d35a5eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estirón! 📏', body_es = '¿Notas que ha crecido? Introduce sus nuevas medidas en el Registro de peso y mira cómo sube su gráfica de crecimiento.', title_fr = 'Poussée de croissance ! 📏', body_fr = 'Vous sentez qu''il a grandi ? Saisissez ses nouvelles mesures dans le Suivi du poids et regardez sa courbe de croissance monter.', title_hi = 'बढ़त की छलांग! 📏', body_hi = 'महसूस हो रहा है कि बच्चे की लंबाई बढ़ गई है? वेट ट्रैकर सेक्शन में नए आँकड़े डालिए और देखिए कि विकास का चार्ट कैसे ऊपर जा रहा है।', title_id = 'Lonjakan pertumbuhan! 📏', body_id = 'Merasa si kecil bertambah tinggi? Masukkan ukuran terbarunya di Pelacak Berat Badan dan lihat bagaimana grafik pertumbuhannya naik.', title_ja = 'ぐんと成長！📏', body_ja = '背が伸びたと感じますか？「体重トラッカー」に新しい数値を入れて、成長グラフがどう伸びているか見てみましょう。', title_ko = '성장 급등기! 📏', body_ko = '아이 키가 쑥 자란 게 느껴지나요? 체중 기록에 새 수치를 입력하고 성장 그래프가 어떻게 올라가는지 확인해 보세요.', title_nl = 'Groeisprong! 📏', body_nl = 'Merk je dat je kindje gegroeid is? Voer de nieuwe gegevens in de Gewichtstracker in en zie hoe zijn groeicurve stijgt.', title_pl = 'Skok wzrostu! 📏', body_pl = 'Czujesz, że twoje dziecko urosło? Wpisz nowe pomiary w sekcji Licznik wagi i zobacz, jak pnie się wykres rozwoju.', title_pt = 'Pico de crescimento! 📏', body_pt = 'Sente que o seu filho cresceu? Introduza as novas medidas no Registo de Peso e veja como sobe o gráfico de crescimento.', title_sv = 'Tillväxtsprång! 📏', body_sv = 'Känner du att barnet har vuxit? Skriv in de nya måtten i Viktspåraren och se hur tillväxtkurvan stiger.', title_vi = 'Bước nhảy tăng trưởng! 📏', body_vi = 'Mẹ cảm thấy bé đang cao lên? Hãy nhập số đo mới vào mục Theo dõi cân nặng và xem biểu đồ phát triển đi lên thế nào.', title_zh = '生长飞跃！📏', body_zh = '感觉宝宝在长个子？在体重记录里输入新的数据，看看成长曲线是怎么上升的吧。' WHERE id = 'f05a8717-d544-48fb-a529-17361118fee2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Peinarse y lavarse los dientes 🪥', body_es = 'Te observa y se pasa el peine por el pelo o se lleva el cepillo a la boca. Es la mejor etapa para enseñarle hábitos de autocuidado jugando.', title_fr = 'Se coiffer et se brosser les dents. 🪥', body_fr = 'En vous observant, il se passe le peigne dans les cheveux ou porte la brosse à sa bouche. C''est la période idéale pour lui transmettre les gestes d''hygiène en jouant.', title_hi = 'बाल सँवारना और दाँत साफ़ करना। 🪥', body_hi = 'आपको देखकर कंघी बालों में फेरता है या ब्रश मुँह तक ले जाता है। खेल-खेल में अपनी देखभाल की आदतें डालने का यह सबसे अच्छा दौर है।', title_id = 'Menyisir rambut dan menyikat gigi. 🪥', body_id = 'Meniru Anda, ia menyisir rambutnya atau memasukkan sikat gigi ke mulut. Inilah masa terbaik untuk menanamkan kebiasaan merawat diri lewat bermain.', title_ja = '髪をとかして、歯をみがいて 🪥', body_ja = 'あなたを見て、くしで髪をとかしたり、歯ブラシを口に持っていったりしています。遊びを通して身の回りの習慣を身につける絶好の時期です。', title_ko = '머리 빗기와 양치하기. 🪥', body_ko = '엄마를 보고 빗으로 머리를 빗거나 칫솔을 입에 가져가요. 놀이로 스스로 돌보는 습관을 들이기에 가장 좋은 시기예요.', title_nl = 'Haren kammen en tanden poetsen. 🪥', body_nl = 'Je kindje kijkt naar jou, haalt de kam door zijn haar of stopt de borstel in zijn mond. Het mooiste moment om met spelletjes zelfzorg aan te leren.', title_pl = 'Czesanie włosów i mycie zębów. 🪥', body_pl = 'Obserwując cię, przeczesuje włosy grzebieniem lub wkłada szczoteczkę do buzi. To najlepszy czas, by przez zabawę uczyć go dbania o siebie.', title_pt = 'Pentear o cabelo e lavar os dentes. 🪥', body_pt = 'Ao observá-la, passa o pente pelo cabelo ou leva a escova à boca. É a melhor fase para criar hábitos de cuidado pessoal a brincar.', title_sv = 'Kamma håret och borsta tänderna. 🪥', body_sv = 'Barnet härmar dig, drar kammen genom håret eller stoppar tandborsten i munnen. Det är den bästa tiden att lära ut egenvård genom lek.', title_vi = 'Chải tóc và đánh răng. 🪥', body_vi = 'Quan sát mẹ, bé đưa lược lên tóc hay đưa bàn chải vào miệng. Đây là giai đoạn tuyệt vời nhất để hình thành thói quen tự chăm sóc qua trò chơi.', title_zh = '梳头和刷牙 🪥', body_zh = '他看着你，也拿梳子梳头，或者把牙刷放进嘴里。这是通过游戏培养自理习惯的最好时期。' WHERE id = '75798a4e-e59c-4911-827e-b1622b37ae33' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cena en familia 🍲', body_es = '¿Esta noche no te apetece cocinar? Encuentra en el mapa de nuestra app restaurantes con menú infantil y tronas para tu peque.', title_fr = 'Dîner en famille. 🍲', body_fr = 'Pas envie de cuisiner ce soir ? Trouvez sur la carte de l''application des restaurants avec un menu enfant et une chaise haute.', title_hi = 'परिवार के साथ रात का खाना। 🍲', body_hi = 'आज शाम घर पर खाना बनाने का मन नहीं? हमारे ऐप के नक्शे में बच्चों के अलग मेन्यू और बच्चों की कुर्सी वाले रेस्टोरेंट ढूँढिए।', title_id = 'Makan malam keluarga. 🍲', body_id = 'Malam ini tidak ingin memasak? Temukan restoran dengan menu khusus anak dan kursi makan bayi lewat peta di aplikasi kami.', title_ja = '家族でディナー 🍲', body_ja = '今夜は家で料理したくない？アプリのマップで、キッズメニューとベビーチェアのあるレストランを見つけましょう。', title_ko = '가족 저녁 식사. 🍲', body_ko = '오늘 저녁은 요리하기 싫은가요? 앱 지도에서 아이 메뉴와 유아용 의자가 있는 식당을 찾아보세요.', title_nl = 'Samen uit eten. 🍲', body_nl = 'Heb je vanavond geen zin om te koken? Zoek op de kaart in onze app restaurants met een kindermenu en een kinderstoel.', title_pl = 'Rodzinna kolacja. 🍲', body_pl = 'Nie masz dziś ochoty gotować? Znajdź na mapie w naszej aplikacji restauracje z menu dla dzieci i krzesełkiem do karmienia.', title_pt = 'Jantar em família. 🍲', body_pt = 'Não lhe apetece cozinhar em casa esta noite? Encontre no mapa da nossa app restaurantes com menu infantil e cadeira de criança para o seu filho.', title_sv = 'Familjemiddag. 🍲', body_sv = 'Vill du inte laga mat hemma i kväll? Hitta restauranger med egen barnmeny och barnstol på kartan i appen.', title_vi = 'Bữa tối gia đình. 🍲', body_vi = 'Tối nay mẹ không muốn nấu ăn? Hãy tìm trên bản đồ trong ứng dụng những nhà hàng có thực đơn riêng và ghế ăn cho trẻ em.', title_zh = '家庭晚餐 🍲', body_zh = '今晚不想在家做饭？在我们应用的地图上找找有儿童菜单和儿童座椅的餐厅吧。' WHERE id = '784b1d1b-2c53-42bf-a43b-d6b6e3121aba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Respira hondo ✨', body_es = 'No todos los días salen como los planeas y a veces la casa estará desordenada. No tienes que ser perfecta: para él eres la mejor.', title_fr = 'Respirez profondément. ✨', body_fr = 'Les journées ne se passent pas toujours comme prévu et la maison reste parfois en désordre. Vous n''avez pas besoin d''être parfaite, pour lui, vous êtes la meilleure.', title_hi = 'गहरी साँस लीजिए। ✨', body_hi = 'हर दिन आपकी योजना के मुताबिक नहीं चल सकता और घर कभी-कभी बिखरा रह सकता है। आपको परफ़ेक्ट होने की ज़रूरत नहीं, उसके लिए आप सबसे अच्छी हैं।', title_id = 'Tarik napas dalam-dalam. ✨', body_id = 'Tidak setiap hari berjalan sesuai rencana, dan rumah kadang tetap berantakan. Anda tidak harus sempurna, bagi si kecil Anda yang terbaik.', title_ja = '深呼吸しましょう ✨', body_ja = '毎日が計画どおりにいくわけではなく、家が散らかることもあります。完璧でなくていいのです。お子さんにとって、あなたが最高なのですから。', title_ko = '깊게 숨을 쉬어 보세요. ✨', body_ko = '매일 계획대로 되지 않을 수도 있고, 집이 가끔 어질러져 있을 수도 있어요. 완벽할 필요는 없어요. 아이에게는 당신이 최고예요.', title_nl = 'Haal diep adem. ✨', body_nl = 'Niet elke dag loopt zoals gepland en het huis kan soms rommelig zijn. Je hoeft niet perfect te zijn, voor je kindje ben jij de beste.', title_pl = 'Weź głęboki oddech. ✨', body_pl = 'Nie każdy dzień pójdzie zgodnie z planem, a w domu czasem będzie bałagan. Nie musisz być idealna, dla niego jesteś najlepsza.', title_pt = 'Respire fundo. ✨', body_pt = 'Nem todos os dias correm como planeou e às vezes a casa fica desarrumada. Não tem de ser perfeita: para ele, é a melhor.', title_sv = 'Ta ett djupt andetag. ✨', body_sv = 'Alla dagar går inte som planerat, och ibland blir det stökigt hemma. Du behöver inte vara perfekt, du är den bästa för ditt barn.', title_vi = 'Hãy hít thở thật sâu. ✨', body_vi = 'Không phải ngày nào cũng diễn ra như kế hoạch và đôi khi nhà cửa có thể bừa bộn. Mẹ không cần phải hoàn hảo, với bé, mẹ là tuyệt nhất.', title_zh = '深呼吸 ✨', body_zh = '每天不一定都按计划进行，家里有时也会乱。你不必完美，对宝宝来说，你就是最好的。' WHERE id = 'b328273f-0602-46a6-a82b-54d47ec1b77d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una rutina que calma 🌙', body_es = 'Antes de dormir, bajar las luces de la habitación y hablar en susurros le ayudará a bajar el ritmo y prepararse para dormir.', title_fr = 'Un rituel apaisant. 🌙', body_fr = 'Avant la nuit, tamiser la lumière et parler à voix basse l''aidera à ralentir et à se préparer au sommeil.', title_hi = 'शांति लाने वाला रूटीन। 🌙', body_hi = 'रात की नींद से पहले कमरे की रोशनी धीमी करना और फुसफुसाकर बात करना उसकी रफ़्तार भी धीमी करेगा और उसे नींद के लिए तैयार करेगा।', title_id = 'Rutinitas yang menenangkan. 🌙', body_id = 'Sebelum tidur malam, meredupkan lampu kamar dan berbicara sambil berbisik akan memperlambat ritmenya dan menyiapkannya tidur.', title_ja = '心落ち着く習慣 🌙', body_ja = '寝る前に部屋の照明を暗くして、ささやき声で話すと、お子さんのペースもゆっくりになり、眠りへの準備が整います。', title_ko = '차분하게 해 주는 루틴. 🌙', body_ko = '밤잠에 들기 전 방의 조명을 낮추고 속삭이듯 말하면 아이의 속도도 느려지며 잠들 준비를 하게 돼요.', title_nl = 'Een rustgevende routine. 🌙', body_nl = 'Dim voor het slapengaan de lichten en praat fluisterend, dan komt je kindje ook tot rust en is hij klaar om te slapen.', title_pl = 'Uspokajająca rutyna. 🌙', body_pl = 'Przygaszenie świateł i mówienie szeptem przed nocnym snem spowolnią także jego tempo i przygotują go do snu.', title_pt = 'Uma rotina que traz calma. 🌙', body_pt = 'Antes de ir dormir, baixar as luzes do quarto e falar em sussurros vai abrandar também o ritmo dele e prepará-lo para dormir.', title_sv = 'En rutin som skapar lugn. 🌙', body_sv = 'Att dämpa ljuset i rummet och prata viskande före nattsömnen saktar ner barnets tempo och förbereder det för sömn.', title_vi = 'Nếp sinh hoạt mang lại bình yên. 🌙', body_vi = 'Trước giờ ngủ đêm, giảm đèn trong phòng và nói thì thầm sẽ giúp bé chậm lại và sẵn sàng cho giấc ngủ.', title_zh = '让人平静的睡前程序 🌙', body_zh = '睡前调暗灯光、轻声细语，能让他慢下来，为入睡做好准备。' WHERE id = '755229fb-26a0-4a27-af2c-49bb6a367386' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡De los garabatos a las líneas con intención! 🖍', body_es = '️ Cuando coge un lápiz, ya no solo hace puntos: intenta trazar líneas largas. Hazle una foto a esta pequeña obra de arte y añádela enseguida al Álbum del bebé.', title_fr = 'Des gribouillis aux vrais traits ! 🖍', body_fr = '️ Quand il prend un crayon, il ne fait plus seulement des points, il essaie de tracer de longs traits. Prenez en photo ce petit chef-d''œuvre et ajoutez-le tout de suite à l''Album de bébé.', title_hi = 'आड़ी-तिरछी लकीरों से सोची-समझी रेखाओं तक! 🖍', body_hi = '️ हाथ में पेन लेकर अब सिर्फ़ बिंदु नहीं, लंबी रेखाएँ खींचने की कोशिश करता है। इस छोटी कलाकृति की फ़ोटो लेकर तुरंत बेबी एल्बम में जोड़िए।', title_id = 'Dari coretan ke garis yang terarah! 🖍', body_id = '️ Saat memegang pensil, ia tidak hanya membuat titik, tapi mencoba menarik garis panjang. Foto karya seni kecil ini dan segera tambahkan ke Album Bayi.', title_ja = 'なぐり描きから、意味のある線へ！🖍', body_ja = '️クレヨンを持つと、点だけでなく長い線を描こうとしています。この小さな作品を写真に撮って、すぐに「ベビーアルバム」に追加しましょう。', title_ko = '끄적이기에서 의도한 선으로! 🖍', body_ko = '️펜을 쥐면 점만 찍는 게 아니라 긴 선을 그으려 해요. 이 작은 작품을 사진으로 찍어 바로 아기 앨범에 추가하세요.', title_nl = 'Van krabbels naar bewuste lijnen! 🖍', body_nl = '️ Met een potlood in zijn hand zet je kindje niet alleen stipjes, maar probeert hij lange lijnen te trekken. Maak een foto van dit kleine kunstwerk en zet het meteen in het Babyalbum.', title_pl = 'Od bazgrołów do celowych linii! 🖍', body_pl = '️ Gdy bierze kredkę do ręki, próbuje rysować nie tylko kropki, ale i długie linie. Zrób zdjęcie temu małemu dziełu i od razu dodaj je do Albumu dziecka.', title_pt = 'Dos rabiscos às linhas com intenção! 🖍', body_pt = '️ Quando pega num lápis, já não faz só pontos, tenta traçar linhas compridas. Fotografe esta pequena obra de arte e adicione-a já ao Álbum do Bebé.', title_sv = 'Från klotter till avsiktliga linjer! 🖍', body_sv = '️ När barnet tar en penna försöker det rita långa linjer, inte bara prickar. Fota det lilla konstverket och lägg direkt till det i Babyalbumet.', title_vi = 'Từ nét nguệch ngoạc đến những đường kẻ có chủ đích! 🖍', body_vi = '️ Khi cầm bút, bé không chỉ chấm chấm mà còn cố vẽ những đường dài. Hãy chụp lại tác phẩm nhỏ này và thêm ngay vào Album của bé.', title_zh = '从涂鸦到有意识的线条！🖍', body_zh = '️ 拿起笔时，宝宝不只是点点，还尝试画长长的线条。把这件小小的艺术作品拍下来，马上放进宝宝相册吧。' WHERE id = 'ae949749-3a87-49dc-a4ae-057b9e3594b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Búsqueda del tesoro en la naturaleza 🍂', body_es = 'Recoger y observar hojas y piedrecitas en el jardín o en el parque es una actividad perfecta para su desarrollo sensorial.', title_fr = 'Chasse au trésor dans la nature. 🍂', body_fr = 'Ramasser et examiner des feuilles ou des petits cailloux dans la cour ou au parc est une activité parfaite pour son développement sensoriel.', title_hi = 'प्रकृति में खज़ाने की खोज। 🍂', body_hi = 'आँगन या पार्क में पत्तियाँ और छोटे पत्थर इकट्ठे करके उन्हें परखना उसके सेंसरी (इंद्रिय) विकास के लिए बेहतरीन गतिविधि है।', title_id = 'Berburu harta karun di alam. 🍂', body_id = 'Mengumpulkan dan mengamati daun atau batu kecil di halaman atau taman adalah kegiatan sempurna untuk perkembangan sensoriknya.', title_ja = '自然の中で宝さがし 🍂', body_ja = '庭や公園で葉っぱや小石を集めて調べることは、感覚の発達にぴったりの遊びです。', title_ko = '자연 속 보물찾기. 🍂', body_ko = '마당이나 공원에서 나뭇잎과 작은 돌멩이를 모아 살펴보는 건 감각 발달에 완벽한 활동이에요.', title_nl = 'Schattenjacht in de natuur. 🍂', body_nl = 'Blaadjes en steentjes verzamelen en bekijken in de tuin of het park is een perfecte activiteit voor zijn zintuiglijke ontwikkeling.', title_pl = 'Poszukiwanie skarbów w naturze. 🍂', body_pl = 'Zbieranie i oglądanie liści oraz kamyków na podwórku lub w parku to idealne zajęcie dla rozwoju jego zmysłów.', title_pt = 'Caça ao tesouro na natureza. 🍂', body_pt = 'Apanhar e observar folhas e pedrinhas no quintal ou no parque é uma atividade perfeita para o desenvolvimento sensorial.', title_sv = 'Skattjakt i naturen. 🍂', body_sv = 'Att samla och undersöka löv och små stenar på gården eller i parken är en perfekt aktivitet för den sensoriska utvecklingen.', title_vi = 'Săn kho báu giữa thiên nhiên. 🍂', body_vi = 'Nhặt lá cây, sỏi nhỏ ở sân hay công viên và khám phá chúng là hoạt động tuyệt vời cho sự phát triển giác quan của bé.', title_zh = '大自然寻宝 🍂', body_zh = '在院子或公园里收集树叶、小石子来研究，是促进他感官发育的绝佳活动。' WHERE id = 'f1cd31cb-c9bf-40c8-b2e0-ab0c8e5c21b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Relajarse jugando con agua 🛁', body_es = 'Jugar en un baño templado con los juguetes que lanza al agua le quita el estrés del día y además es muy divertido.', title_fr = 'Se détendre en jouant dans l''eau. 🛁', body_fr = 'Jouer dans un bain tiède avec les jouets qu''il lance dans l''eau évacue le stress de la journée et c''est très amusant.', title_hi = 'पानी के खेलों से सुकून। 🛁', body_hi = 'गुनगुने स्नान के दौरान पानी में डाले खिलौनों से खेलना दिन का तनाव भी दूर करता है और बहुत मज़ेदार भी है।', title_id = 'Rileks lewat bermain air. 🛁', body_id = 'Bermain dengan mainan yang ia lempar ke air saat mandi air hangat tidak hanya menghilangkan stres seharian, tapi juga sangat seru.', title_ja = '水遊びでリラックス 🛁', body_ja = 'ぬるめのお風呂で、お湯に入れたおもちゃで遊ぶのは、一日のストレスを流してくれるうえに、とっても楽しい時間です。', title_ko = '물놀이로 긴장 풀기. 🛁', body_ko = '따뜻한 목욕을 하며 물에 던진 장난감으로 노는 건 하루의 스트레스를 풀어 주고 정말 즐겁기도 해요.', title_nl = 'Ontspannen met waterspelletjes. 🛁', body_nl = 'Spelen met speeltjes die hij in het lauwe badwater gooit, haalt de stress van de dag weg en is ook nog eens heel leuk.', title_pl = 'Relaks przy zabawach w wodzie. 🛁', body_pl = 'Zabawa zabawkami wrzuconymi do wody podczas ciepłej kąpieli zdejmuje stres dnia i jest przy tym świetną zabawą.', title_pt = 'Relaxar com brincadeiras na água. 🛁', body_pt = 'No banho morno, brincar com os brinquedos que atira para a água tira o stress do dia e é muito divertido.', title_sv = 'Avslappning med vattenlek. 🛁', body_sv = 'Att leka med leksakerna barnet kastar i vattnet under ett ljummet bad tar bort dagens stress och är dessutom jätteroligt.', title_vi = 'Thư giãn với trò chơi nước. 🛁', body_vi = 'Chơi với đồ chơi thả trong bồn tắm nước ấm vừa giúp xua tan căng thẳng trong ngày, vừa rất vui.', title_zh = '玩水放松 🛁', body_zh = '洗温水澡时，玩玩扔进水里的玩具，既能缓解一天的压力，又特别有趣。' WHERE id = '1b65f6b1-f423-43f5-bc48-5ffb574c7c74' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Entiende órdenes de dos pasos! 🧠', body_es = '¿Cuando le dices «Coge el zapato y dámelo» hace las dos cosas seguidas? ¡Es señal de un gran salto en su inteligencia!', title_fr = 'Il comprend les consignes en deux étapes ! 🧠', body_fr = 'Quand vous dites « Prends ta chaussure et donne-la-moi », il fait les deux actions à la suite ? C''est le signe d''un formidable bond de son intelligence !', title_hi = 'दो चरणों वाले निर्देश समझता है! 🧠', body_hi = '''जूता उठाओ और मुझे दो'' कहने पर दोनों काम एक के बाद एक करता है? यह उसकी समझ में शानदार छलांग का संकेत है!', title_id = 'Memahami perintah dua langkah! 🧠', body_id = 'Saat Anda bilang "Ambil sepatumu dan berikan ke Mama", ia melakukan keduanya berurutan? Ini tanda lompatan besar dalam kecerdasannya!', title_ja = '2つのステップのお願いがわかる！🧠', body_ja = '「靴を取って、ママにちょうだい」と言うと、2つの動作を順番にできますか？知性がぐんと飛躍している証拠です！', title_ko = '두 단계 지시를 이해해요! 🧠', body_ko = '"신발 들고 엄마한테 줘" 하면 두 가지 행동을 차례로 해내나요? 두뇌가 멋지게 도약했다는 신호예요!', title_nl = 'Begrijpt opdrachten met twee stappen! 🧠', body_nl = 'Doet je kindje beide dingen na elkaar als je zegt: pak je schoen en geef hem aan mij? Dat is een teken van een geweldige sprong in zijn verstand!', title_pl = 'Rozumie polecenia dwuetapowe! 🧠', body_pl = 'Na „Weź but i daj mi go” wykonuje obie czynności po kolei? To znak wspaniałego skoku w rozwoju jego umysłu!', title_pt = 'Percebe ordens com dois passos! 🧠', body_pt = 'Quando lhe diz "Pega no sapato e dá-mo", faz as duas ações seguidas? É sinal de um salto fantástico na inteligência dele!', title_sv = 'Förstår instruktioner i två steg! 🧠', body_sv = 'Gör barnet båda sakerna i rätt ordning när du säger ”Ta skon och ge den till mig”? Det är ett tecken på ett fantastiskt språng i intelligensen!', title_vi = 'Bé hiểu yêu cầu hai bước! 🧠', body_vi = 'Mẹ nói "Nhặt giày lên và đưa cho mẹ" là bé làm lần lượt cả hai việc? Đây là dấu hiệu của một bước nhảy vọt tuyệt vời về trí tuệ!', title_zh = '能听懂两步指令了！🧠', body_zh = '你说“拿起鞋子给我”，他会按顺序完成两个动作吗？这说明他的智力有了巨大的飞跃！' WHERE id = 'bc0b7dcc-fdc0-4664-bff5-56183ea22258' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La energía de mamá es muy importante 🥗', body_es = 'Estás cansada de correr de un lado a otro. Prepárate en Recetas saludables para mujeres un plato rico y lleno de vitaminas.', title_fr = 'L''énergie de maman compte beaucoup. 🥗', body_fr = 'Courir sans arrêt vous a fatiguée. Préparez-vous une portion savoureuse et vitaminée grâce aux Recettes saines pour femmes.', title_hi = 'माँ की ऊर्जा बहुत ज़रूरी है। 🥗', body_hi = 'लगातार भागते-भागते आप थक गई हैं। महिलाओं के लिए सेहतमंद रेसिपी से अपने लिए स्वादिष्ट और विटामिन भरा खाना बनाइए।', title_id = 'Energi ibu itu sangat penting. 🥗', body_id = 'Lelah terus berlari ke sana kemari? Siapkan hidangan lezat kaya vitamin untuk diri sendiri dari Resep Sehat untuk wanita.', title_ja = 'ママの元気はとても大切 🥗', body_ja = '追いかけ続けて疲れましたね。「女性のためのヘルシーレシピ」から、おいしくてビタミンたっぷりの一品を自分のためにつくりましょう。', title_ko = '엄마의 에너지는 정말 중요해요. 🥗', body_ko = '쉴 새 없이 쫓아다니느라 지쳤죠. 건강한 레시피에서 나를 위한 맛있고 비타민 가득한 한 끼를 만들어 보세요.', title_nl = 'Mama''s energie is heel belangrijk. 🥗', body_nl = 'Je bent moe van al dat rennen. Maak uit Gezonde recepten voor vrouwen een lekkere, vitaminerijke portie voor jezelf.', title_pl = 'Energia mamy jest bardzo ważna. 🥗', body_pl = 'Jesteś zmęczona ciągłym bieganiem. Przygotuj sobie ze Zdrowych przepisów dla kobiet smaczne i pełne witamin danie.', title_pt = 'A energia da mãe é muito importante. 🥗', body_pt = 'Está cansada de correr de um lado para o outro. Prepare nas Receitas Saudáveis para Mulheres uma refeição para si, saborosa e cheia de vitaminas.', title_sv = 'Mammas energi är mycket viktig. 🥗', body_sv = 'Du är trött av att springa omkring utan paus. Gör en portion som är både god och vitaminrik åt dig själv från Hälsosamma recept för kvinnor.', title_vi = 'Năng lượng của mẹ rất quan trọng. 🥗', body_vi = 'Mẹ mệt vì chạy theo bé liên tục. Hãy chuẩn bị cho mình một phần ăn vừa ngon vừa giàu vitamin từ Công thức lành mạnh cho phụ nữ.', title_zh = '妈妈的能量非常重要 🥗', body_zh = '追着跑了一整天，你累坏了。从女性健康食谱里给自己做一份美味又富含维生素的餐点吧。' WHERE id = 'c18b2eee-ba78-43cc-89fd-423a464819d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Usa la cuchara solo 🥄', body_es = 'Ya derrama menos al llevarse la cuchara a la boca. Aplaude esta habilidad de motricidad fina y déjale ser independiente.', title_fr = 'Il utilise la cuillère tout seul. 🥄', body_fr = 'Il renverse moins en portant la cuillère à sa bouche. Applaudissez cette compétence de motricité fine et laissez-lui son autonomie.', title_hi = 'खुद चम्मच चलाना। 🥄', body_hi = 'चम्मच मुँह तक ले जाते समय अब कम गिराता है। उसके इस बारीक मोटर हुनर पर ताली बजाइए और उसे खुद करने दीजिए।', title_id = 'Memakai sendok sendiri. 🥄', body_id = 'Kini makin sedikit yang tumpah saat ia menyuap dengan sendok. Beri tepuk tangan untuk keterampilan motorik halus ini dan biarkan ia mandiri.', title_ja = 'スプーンを自分で使う 🥄', body_ja = 'スプーンを口に運ぶとき、こぼすことが減ってきました。この手先の成長に拍手を送り、自分でやらせてあげましょう。', title_ko = '혼자 숟가락 쓰기. 🥄', body_ko = '숟가락을 입으로 가져갈 때 흘리는 양이 줄었어요. 이 소근육 기술에 박수를 보내고 스스로 하게 해 주세요.', title_nl = 'Zelf met de lepel eten. 🥄', body_nl = 'Je kindje morst minder als hij de lepel naar zijn mond brengt. Applaudisseer voor deze fijne motoriek en gun hem zijn zelfstandigheid.', title_pl = 'Samodzielne jedzenie łyżeczką. 🥄', body_pl = 'Niosąc łyżeczkę do buzi, rozlewa coraz mniej. Nagradzaj brawami tę umiejętność motoryki małej i pozwól mu na samodzielność.', title_pt = 'Usar a colher sozinho. 🥄', body_pt = 'Já entorna menos quando leva a colher à boca. Aplauda esta competência de motricidade fina e dê espaço à independência dele.', title_sv = 'Använder skeden själv. 🥄', body_sv = 'Barnet spiller mindre när skeden förs till munnen. Applådera den här finmotoriska färdigheten och låt barnet vara självständigt.', title_vi = 'Tự dùng thìa. 🥄', body_vi = 'Bé ít làm rơi vãi hơn khi đưa thìa lên miệng. Hãy vỗ tay khen kỹ năng vận động tinh này và để bé tự lập.', title_zh = '自己用勺子 🥄', body_zh = '把勺子送进嘴里时撒得更少了。为他的精细动作进步鼓掌，让他自己来吧。' WHERE id = 'cd0e822c-b843-41fa-9a3e-f4b682a848ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empatía con los juguetes 🧸', body_es = '¿Acaricia a su osito, le da de comer o lo tapa? Estos tiernos juegos de imitación muestran lo bien que se está desarrollando su inteligencia emocional.', title_fr = 'L''empathie avec les jouets. 🧸', body_fr = 'Il caresse son ours en peluche, le nourrit ou le couvre ? Ces adorables jeux de rôle montrent à quel point son intelligence émotionnelle se développe bien.', title_hi = 'खिलौनों के साथ सहानुभूति। 🧸', body_hi = 'टेडी बेयर को सहलाता है, खाना खिलाता है या उसे ओढ़ाता है? ये प्यारे रोल-प्ले खेल दिखाते हैं कि उसकी भावनात्मक समझ कितनी सुंदर ढंग से विकसित हो रही है।', title_id = 'Empati lewat mainan. 🧸', body_id = 'Ia mengelus boneka beruangnya, menyuapinya, atau menyelimutinya? Permainan peran yang manis ini menunjukkan betapa indahnya kecerdasan emosionalnya berkembang.', title_ja = 'おもちゃへの思いやり 🧸', body_ja = 'くまのぬいぐるみをなでたり、食べさせたり、布団をかけてあげたりしていますか？このかわいいごっこ遊びは、心の知性がすてきに育っている証拠です。', title_ko = '장난감으로 배우는 공감. 🧸', body_ko = '곰 인형을 쓰다듬고 밥을 먹이거나 이불을 덮어 주나요? 이 사랑스러운 역할 놀이는 정서 지능이 멋지게 자라고 있다는 증거예요.', title_nl = 'Empathie met knuffels. 🧸', body_nl = 'Aait je kindje zijn knuffelbeer, voert hij hem of stopt hij hem in? Deze lieve rollenspelletjes laten zien hoe mooi zijn emotionele intelligentie groeit.', title_pl = 'Empatia wobec zabawek. 🧸', body_pl = 'Głaszcze misia, karmi go albo go przykrywa? Te słodkie zabawy w udawanie pokazują, jak pięknie rozwija się jego inteligencja emocjonalna.', title_pt = 'Empatia com os brinquedos. 🧸', body_pt = 'Faz festinhas ao ursinho, dá-lhe de comer ou tapa-o? Estes jogos de faz de conta tão doces mostram como a inteligência emocional dele se desenvolve bem.', title_sv = 'Empati med leksaker. 🧸', body_sv = 'Stryker barnet nallen, matar den eller bäddar ner den? Dessa söta rollekar visar hur fint den emotionella intelligensen utvecklas.', title_vi = 'Đồng cảm qua đồ chơi. 🧸', body_vi = 'Bé vuốt ve gấu bông, cho gấu ăn hay đắp chăn cho gấu? Những trò đóng vai đáng yêu này cho thấy trí tuệ cảm xúc của bé đang phát triển thật tuyệt vời.', title_zh = '用玩具表达同理心 🧸', body_zh = '他会摸摸泰迪熊、喂它吃饭，或者给它盖被子？这些可爱的角色扮演游戏，说明他的情商发展得多好。' WHERE id = 'd6374c1a-94a0-4de3-855d-6a8d4e9a29af' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento con papá 👨‍🍼', body_es = 'Hoy deja a papá el turno del cuento y de acostarle, y regálate un pequeño descanso.', title_fr = 'L''heure du conte avec papa. 👨‍🍼', body_fr = 'Ce soir, confiez à papa l''histoire du soir et le coucher, et offrez-vous une petite pause.', title_hi = 'पापा की कहानी का समय। 👨‍🍼', body_hi = 'आज शाम कहानी सुनाने और सुलाने की बारी पापा को सौंपिए और खुद को छोटा सा ब्रेक दीजिए।', title_id = 'Waktu dongeng bersama ayah. 👨‍🍼', body_id = 'Hari ini, serahkan giliran membacakan dongeng dan menidurkan si kecil kepada ayah, dan beri diri Anda jeda sejenak.', title_ja = 'パパのお話タイム 👨‍🍼', body_ja = '今夜は寝る前の読み聞かせと寝かしつけをパパにお願いして、自分に小さな休憩をあげましょう。', title_ko = '아빠의 이야기 시간. 👨‍🍼', body_ko = '오늘은 저녁 동화 읽기와 재우기를 아빠에게 맡기고 엄마는 잠깐 쉬어 가세요.', title_nl = 'Verhaaltjestijd met papa. 👨‍🍼', body_nl = 'Laat het voorlezen en naar bed brengen vandaag aan papa over en gun jezelf een kleine pauze.', title_pl = 'Czas bajek z tatą. 👨‍🍼', body_pl = 'Dziś wieczorem przekaż tacie czytanie bajki i usypianie, a sobie daj małą przerwę.', title_pt = 'A hora das histórias do pai. 👨‍🍼', body_pt = 'Hoje, entregue ao pai a vez de ler a história da noite e de o adormecer, e dê a si própria uma pequena pausa.', title_sv = 'Pappas sagostund. 👨‍🍼', body_sv = 'Lämna kvällssagan och nattningen till pappa i dag och ge dig själv en liten paus.', title_vi = 'Giờ kể chuyện của bố. 👨‍🍼', body_vi = 'Tối nay hãy giao việc kể chuyện và ru bé ngủ cho bố, còn mẹ thì cho mình nghỉ ngơi một chút.', title_zh = '爸爸的故事时间 👨‍🍼', body_zh = '今天把讲睡前故事和哄睡的任务交给爸爸，给自己一个小小的休息。' WHERE id = '299405ea-50dc-48c1-ba2a-233941bf627c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hay que actualizar la seguridad 🛡️', body_es = 'Abrir armarios y cajones es su pasatiempo favorito. Echa un vistazo a nuestra lista de Productos recomendados para encontrar cierres de seguridad infantil.', title_fr = 'La sécurité doit être revue. 🛡️', body_fr = 'Ouvrir les placards et les tiroirs est son passe-temps préféré. Consultez absolument notre liste de Produits recommandés pour les verrous de sécurité enfant.', title_hi = 'सुरक्षा को अपडेट करना ज़रूरी है। 🛡️', body_hi = 'अलमारियाँ और दराज़ें खोलना उसका सबसे पसंदीदा शौक है। चाइल्ड लॉक के लिए हमारी सुझाए गए प्रोडक्ट की लिस्ट ज़रूर देखिए।', title_id = 'Keamanan perlu diperbarui. 🛡️', body_id = 'Membuka lemari dan laci adalah hobi favoritnya. Pastikan melihat daftar Produk Rekomendasi kami untuk kunci pengaman anak.', title_ja = '安全対策を見直そう 🛡️', body_ja = '戸棚や引き出しを開けるのが、いちばんの楽しみに。チャイルドロックは、ぜひ「おすすめ商品」リストでチェックしましょう。', title_ko = '안전 점검을 새로 할 때예요. 🛡️', body_ko = '수납장과 서랍 열기가 가장 좋아하는 취미예요. 안전 잠금장치는 추천 제품 목록에서 꼭 확인하세요.', title_nl = 'Tijd om de veiligheid bij te werken. 🛡️', body_nl = 'Kastjes en laden openen is zijn favoriete hobby. Bekijk zeker onze lijst Aanbevolen producten voor kinderslotjes.', title_pl = 'Czas odświeżyć zabezpieczenia. 🛡️', body_pl = 'Otwieranie szafek i szuflad to jego ulubione hobby. Koniecznie zajrzyj do naszej listy Polecanych produktów po blokady dla dzieci.', title_pt = 'É altura de reforçar a segurança. 🛡️', body_pt = 'Abrir armários e gavetas é o passatempo preferido dele. Não deixe de ver a nossa lista de Produtos Recomendados para trancas de segurança.', title_sv = 'Säkerheten behöver uppdateras. 🛡️', body_sv = 'Att öppna skåp och lådor är favorithobbyn. Titta i vår lista Rekommenderade produkter efter barnlås.', title_vi = 'Cần cập nhật an toàn. 🛡️', body_vi = 'Mở tủ và ngăn kéo là sở thích lớn nhất của bé. Mẹ nhớ xem danh sách Sản phẩm gợi ý của chúng tôi để tìm khóa an toàn cho trẻ nhé.', title_zh = '安全措施需要升级 🛡️', body_zh = '打开柜子和抽屉是他最爱的爱好。一定要看看我们推荐商品清单里的儿童安全锁。' WHERE id = '7ad6ef35-e677-498c-8bc2-cc3e84535415' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Conquista nuevas alturas! 🧗‍♂', body_es = '️ Ya llega más alto y trepa a los muebles con más facilidad. Es hora de revisar otra vez las medidas de seguridad de casa.', title_fr = 'À la conquête des hauteurs ! 🧗‍♂', body_fr = '️ Il atteint désormais des endroits plus hauts et grimpe plus facilement sur les meubles. C''est le moment de revoir une nouvelle fois la sécurité de la maison.', title_hi = 'नई ऊँचाइयाँ फ़तह हो रही हैं! 🧗‍♂', body_hi = '️ अब वह और ऊँचा पहुँच सकता है और फ़र्नीचर पर आसानी से चढ़ सकता है। घर की सुरक्षा के इंतज़ामों को एक बार फिर देखने का समय है।', title_id = 'Menaklukkan ketinggian baru! 🧗‍♂', body_id = '️ Kini ia bisa meraih tempat lebih tinggi dan memanjat perabot dengan lebih mudah. Saatnya meninjau ulang langkah keamanan di rumah.', title_ja = '新しい高さに挑戦！🧗‍♂', body_ja = '️もっと高いところに手が届き、家具にも楽によじ登れるようになりました。家の安全対策をもう一度見直すタイミングです。', title_ko = '새로운 높이를 정복해요! 🧗‍♂', body_ko = '️이제 더 높은 곳에 손이 닿고 가구에도 더 쉽게 기어올라요. 집 안 안전 조치를 다시 한번 점검할 때예요.', title_nl = 'Nieuwe hoogtes veroverd! 🧗‍♂', body_nl = '️ Je kindje kan nu hoger reiken en makkelijker op meubels klimmen. Tijd om de veiligheid in huis nog eens na te lopen.', title_pl = 'Zdobywanie nowych wysokości! 🧗‍♂', body_pl = '️ Sięga już wyżej i łatwiej wspina się na meble. Czas jeszcze raz przejrzeć zabezpieczenia w domu.', title_pt = 'A conquistar novas alturas! 🧗‍♂', body_pt = '️ Já chega mais alto e sobe aos móveis com mais facilidade. É altura de rever mais uma vez as medidas de segurança da casa.', title_sv = 'Nya höjder erövras! 🧗‍♂', body_sv = '️ Barnet når nu högre och klättrar lättare upp på möblerna. Det är dags att se över säkerheten i hemmet ännu en gång.', title_vi = 'Chinh phục những độ cao mới! 🧗‍♂', body_vi = '️ Bé đã với cao hơn và leo lên đồ đạc dễ dàng hơn. Đã đến lúc kiểm tra lại các biện pháp an toàn trong nhà một lần nữa.', title_zh = '征服新高度！🧗‍♂', body_zh = '️ 宝宝已经能够到更高的地方，爬家具也更轻松了。是时候再检查一遍家里的安全措施了。' WHERE id = 'ec2361c8-31f7-458e-ad6e-506355b447a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Haz que beber agua sea divertido 💧', body_es = 'Correr y jugar tanto da sed. Ofrécele agua a menudo en su vaso de aprendizaje de colores para que esté bien hidratado.', title_fr = 'Rendez l''eau amusante. 💧', body_fr = 'Courir et jouer donne soif. Proposez-lui souvent de l''eau dans sa gourde colorée pour qu''il reste bien hydraté.', title_hi = 'पानी पीना मज़ेदार बनाइए। 💧', body_hi = 'भाग-दौड़ और खेल से प्यास लगती है। उसके रंगीन सिपी कप से उसे बार-बार पानी देकर शरीर में पानी की कमी मत होने दीजिए।', title_id = 'Jadikan minum air menyenangkan. 💧', body_id = 'Berlari dan bermain aktif membuatnya haus. Tawarkan air sesering mungkin dengan botol minum berwarnanya agar tubuhnya tetap terhidrasi.', title_ja = 'お水を楽しく飲もう 💧', body_ja = '走ったり遊んだりすると、のどが渇きます。カラフルなマグでこまめにお水をすすめて、水分を保ちましょう。', title_ko = '물 마시기를 재미있게. 💧', body_ko = '활발한 달리기와 놀이는 목마름을 불러요. 알록달록한 물병으로 물을 자주 권해 몸에 수분을 채워 주세요.', title_nl = 'Maak water drinken leuk. 💧', body_nl = 'Rennen en spelen geeft dorst. Bied je kindje vaak water aan in zijn kleurrijke drinkbeker, zodat hij niet uitdroogt.', title_pl = 'Niech picie wody będzie zabawą. 💧', body_pl = 'Aktywne bieganie i zabawy wywołują pragnienie. Często proponuj mu wodę w kolorowym kubku niekapku, by był dobrze nawodniony.', title_pt = 'Torne divertido beber água. 💧', body_pt = 'Correr e brincar com energia dá sede. Mantenha-o hidratado oferecendo-lhe água muitas vezes no copo com bico colorido.', title_sv = 'Gör vattendrickandet roligt. 💧', body_sv = 'Aktivt springande och lekar gör barnet törstigt. Erbjud ofta vatten i den färgglada pipmuggen så att kroppen hålls återfuktad.', title_vi = 'Biến việc uống nước thành niềm vui. 💧', body_vi = 'Chạy nhảy và vui chơi khiến bé khát. Hãy thường xuyên cho bé uống nước bằng chiếc bình tập uống nhiều màu sắc để cơ thể luôn đủ nước.', title_zh = '让喝水变有趣 💧', body_zh = '活跃的奔跑和游戏会让人口渴。用他的彩色水杯经常给他喝水，保持身体水分充足。' WHERE id = '21888245-7cf1-48e4-a08b-53389aa39131' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El balance del día ✨', body_es = 'No tienes que ser perfecta todos los días. Si hoy no has llegado a algo, no pasa nada. Para él eres la mejor.', title_fr = 'Le bilan du jour. ✨', body_fr = 'Vous n''avez pas à être parfaite chaque jour. Si vous n''avez pas pu tout faire aujourd''hui, ce n''est pas grave. Pour lui, vous êtes la meilleure.', title_hi = 'दिन का हिसाब। ✨', body_hi = 'आपको हर दिन परफ़ेक्ट होने की ज़रूरत नहीं। आज कुछ काम पूरा नहीं कर पाईं, तो कोई बात नहीं। उसके लिए आप सबसे अच्छी हैं।', title_id = 'Laporan hari ini. ✨', body_id = 'Anda tidak harus sempurna setiap hari. Kalau hari ini ada yang tidak sempat Anda kerjakan, tidak apa-apa. Bagi si kecil, Anda yang terbaik.', title_ja = '今日のふり返り ✨', body_ja = '毎日完璧でなくていいのです。今日できなかったことがあっても大丈夫。お子さんにとって、あなたが最高です。', title_ko = '오늘의 결산. ✨', body_ko = '매일 완벽할 필요는 없어요. 오늘 무언가를 다 하지 못했어도 괜찮아요. 아이에게는 당신이 최고예요.', title_nl = 'Het verslag van de dag. ✨', body_nl = 'Je hoeft niet elke dag perfect te zijn. Is het vandaag niet allemaal gelukt? Geeft niets. Voor je kindje ben jij de beste.', title_pl = 'Podsumowanie dnia. ✨', body_pl = 'Nie musisz być idealna każdego dnia. Jeśli dziś z czymś nie zdążyłaś, nic się nie stało. Dla niego jesteś najlepsza.', title_pt = 'O balanço do dia. ✨', body_pt = 'Não tem de ser perfeita todos os dias. Se hoje não conseguiu fazer tudo, não faz mal. Para ele, é a melhor.', title_sv = 'Dagens rapport. ✨', body_sv = 'Du behöver inte vara perfekt varje dag. Om du inte hann med allt i dag gör det ingenting. Du är den bästa för ditt barn.', title_vi = 'Tổng kết ngày. ✨', body_vi = 'Mẹ không cần phải hoàn hảo mỗi ngày. Nếu hôm nay chưa làm kịp việc gì, cũng không sao cả. Với bé, mẹ là tuyệt nhất.', title_zh = '今天的总结 ✨', body_zh = '你不必每天都完美。今天有什么没顾上也没关系。对宝宝来说，你就是最好的。' WHERE id = '4595ac68-2033-4a66-a4d9-1146030382ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Su sentido del ritmo se refuerza! 🎶', body_es = '¿En cuanto oye los primeros segundos de su canción favorita se pone a moverse y sonríe? Capta estos momentos con la Sesión de fotos del bebé y envíalos al grupo de la familia.', title_fr = 'Son sens du rythme se renforce ! 🎶', body_fr = 'Dès les premières secondes de sa chanson préférée, il se met à bouger et sourit ? Capturez ces moments pleins d''énergie avec la Séance photo bébé et envoyez-les au groupe de la famille.', title_hi = 'लय की समझ मज़बूत हो रही है! 🎶', body_hi = 'पसंदीदा गाने के पहले कुछ सेकंड सुनते ही थिरकने और मुस्कुराने लगता है? इन ऊर्जा भरे पलों को बेबी फ़ोटोशूट से कैद करके फ़ैमिली ग्रुप में भेजिए।', title_id = 'Rasa iramanya makin kuat! 🎶', body_id = 'Begitu mendengar detik pertama lagu favoritnya, ia langsung bergerak dan tersenyum? Abadikan momen penuh energi ini dengan Sesi Foto Bayi dan kirim ke grup keluarga.', title_ja = 'リズム感が育つ！🎶', body_ja = '好きな歌の最初の数秒が聞こえただけで、体を動かしてにっこりしますか？この元気な瞬間を「ベビーフォトセッション」で撮って、家族のグループに送りましょう。', title_ko = '리듬감이 자라요! 🎶', body_ko = '좋아하는 노래의 첫 몇 초만 들려도 몸을 움직이며 웃나요? 이 신나는 순간을 아기 사진 촬영으로 찍어 가족 단톡방에 보내 주세요.', title_nl = 'Het ritmegevoel wordt sterker! 🎶', body_nl = 'Begint je kindje te bewegen en te lachen zodra hij de eerste seconden van zijn favoriete liedje hoort? Leg deze energieke momenten vast met Babyfotoshoot en stuur ze naar de familiegroep.', title_pl = 'Poczucie rytmu się wzmacnia! 🎶', body_pl = 'Gdy tylko usłyszy pierwsze sekundy ulubionej piosenki, zaczyna się ruszać i uśmiechać? Uwiecznij te pełne energii chwile w Sesji zdjęciowej dziecka i wyślij je na rodzinną grupę.', title_pt = 'O sentido de ritmo está mais forte! 🎶', body_pt = 'Mal ouve os primeiros segundos da canção preferida, começa a mexer-se e a sorrir? Capte estes momentos cheios de energia com a Sessão Fotográfica do Bebé e envie-os ao grupo da família.', title_sv = 'Rytmkänslan blir starkare! 🎶', body_sv = 'Börjar barnet röra sig och le så fort det hör de första sekunderna av sin favoritlåt? Fånga dessa energiska stunder med Babyfotografering och skicka dem till familjegruppen.', title_vi = 'Cảm nhận nhịp điệu mạnh mẽ hơn! 🎶', body_vi = 'Vừa nghe vài giây đầu bài hát yêu thích là bé nhún nhảy và mỉm cười? Hãy ghi lại những khoảnh khắc sôi động này bằng Chụp ảnh cho bé và gửi vào nhóm gia đình.', title_zh = '节奏感越来越强！🎶', body_zh = '一听到喜欢的歌开头几秒，就动起来、笑起来？用宝宝写真拍下这些活力满满的瞬间，发到家庭群里吧。' WHERE id = '9a00f6ae-31b9-432b-a4a4-3a97caf3bc85' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reconoce las partes del cuerpo con más detalle 👂', body_es = 'Que responda bien a preguntas nuevas como «¿Dónde está tu barriga?» o «¿Dónde está tu oreja?» demuestra lo rápido que aprende.', title_fr = 'Il connaît son corps plus en détail. 👂', body_fr = 'Qu''il réponde correctement à de nouvelles questions comme « Où est ton ventre ? » ou « Où est ton oreille ? » montre à quelle vitesse il apprend.', title_hi = 'शरीर के अंगों को और बारीकी से पहचानता है। 👂', body_hi = '''पेट कहाँ है?'', ''कान कहाँ है?'' जैसे नए सवालों का सही जवाब देना दिखाता है कि वह कितनी तेज़ी से सीख रहा है।', title_id = 'Mengenal anggota tubuh lebih detail. 👂', body_id = 'Kemampuannya menjawab pertanyaan baru dengan benar seperti "Perutnya mana?" atau "Telinganya mana?" menunjukkan betapa cepat ia belajar.', title_ja = '体の部分をもっと細かく覚える 👂', body_ja = '「おなかはどこ？」「お耳はどこ？」といった新しい質問に正しく答えられるのは、学ぶスピードが速い証拠です。', title_ko = '신체 부위를 더 자세히 알아요. 👂', body_ko = '"배 어디 있어?", "귀 어디 있어?" 같은 새로운 질문에 정확히 답하는 건 배우는 속도가 빠르다는 뜻이에요.', title_nl = 'Herkent lichaamsdelen steeds beter. 👂', body_nl = 'Dat hij nieuwe vragen goed beantwoordt, zoals: waar is je buik? of: waar is je oor?, laat zien hoe snel hij leert.', title_pl = 'Coraz dokładniej rozpoznaje części ciała. 👂', body_pl = 'To, że dobrze odpowiada na nowe pytania, np. „Gdzie masz brzuszek?” czy „Gdzie masz ucho?”, pokazuje, jak szybko się uczy.', title_pt = 'Reconhece as partes do corpo com mais detalhe. 👂', body_pt = 'Responder bem a perguntas novas como "Onde está a barriga?" ou "Onde está a orelha?" mostra a rapidez com que aprende.', title_sv = 'Känner igen kroppsdelarna mer detaljerat. 👂', body_sv = 'Att barnet svarar rätt på nya frågor som ”Var är magen?” och ”Var är örat?” visar hur snabbt det lär sig.', title_vi = 'Bé nhận biết bộ phận cơ thể chi tiết hơn. 👂', body_vi = 'Bé trả lời đúng những câu hỏi mới như "Bụng con đâu?", "Tai con đâu?" cho thấy khả năng học hỏi đang tăng nhanh.', title_zh = '更细致地认识身体部位 👂', body_zh = '能正确回答“肚子在哪里？”“耳朵在哪里？”这样的新问题，说明他的学习速度很快。' WHERE id = '33b8d80d-5434-483c-b198-c7b20c73321d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Leed un libro juntos 📖', body_es = 'Ya no solo pasa las páginas: señala con el dedo los animales o los objetos del libro y espera a que le digas cómo se llaman.', title_fr = 'Lisez un livre ensemble. 📖', body_fr = 'En plus de tourner les pages, il montre déjà du doigt les animaux ou les objets du livre et attend que vous lui disiez leur nom.', title_hi = 'साथ में किताब पढ़िए। 📖', body_hi = 'अब वह पन्ने पलटने के साथ-साथ किताब के जानवरों या चीज़ों की ओर उँगली दिखाकर आपसे उनका नाम सुनने का इंतज़ार करता है।', title_id = 'Membaca buku bersama. 📖', body_id = 'Kini ia tidak hanya membalik halaman, tapi juga menunjuk hewan atau benda di buku dengan jarinya dan menunggu Anda menyebutkan namanya.', title_ja = '一緒に絵本を読もう 📖', body_ja = 'ページをめくるだけでなく、絵本の動物やものを指さして、あなたが名前を言ってくれるのを待っています。', title_ko = '함께 책을 읽어요. 📖', body_ko = '이제 책장을 넘기는 것뿐 아니라 책 속 동물이나 물건을 손가락으로 가리키며 엄마가 이름을 말해 주길 기다려요.', title_nl = 'Lees samen een boek. 📖', body_nl = 'Je kindje slaat niet alleen de bladzijden om, hij wijst ook dieren of dingen in het boek aan en wacht tot jij zegt hoe ze heten.', title_pl = 'Czytajcie razem książki. 📖', body_pl = 'Oprócz przewracania kartek pokazuje już paluszkiem zwierzęta lub przedmioty w książce i czeka, aż powiesz mu ich nazwę.', title_pt = 'Leiam um livro juntos. 📖', body_pt = 'Além de virar as páginas, já aponta com o dedo para os animais ou objetos do livro e espera que lhe diga o nome.', title_sv = 'Läs en bok tillsammans. 📖', body_sv = 'Förutom att vända sidorna pekar barnet nu på djur eller saker i boken och väntar på att du ska säga vad de heter.', title_vi = 'Cùng nhau đọc sách. 📖', body_vi = 'Ngoài việc lật trang, bé còn chỉ tay vào con vật hay đồ vật trong sách và chờ mẹ nói tên.', title_zh = '一起读书吧 📖', body_zh = '宝宝不仅会翻书，还会指着书里的动物或东西，等你说出名字。' WHERE id = '87029bf7-0808-4eac-a180-0abfa62f0b48' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo va su crecimiento? 📏', body_es = '¡Las mangas y los bajos de la ropa vuelven a quedarle cortos! Introduce sus nuevas medidas en el Registro de peso y mira cómo sube su gráfica de crecimiento.', title_fr = 'Comment se passe sa croissance ? 📏', body_fr = 'Les manches et les jambes de pantalon raccourcissent encore ! Saisissez ses nouvelles mesures dans le Suivi du poids et regardez sa courbe de croissance monter.', title_hi = 'बढ़त की रफ़्तार कैसी है? 📏', body_hi = 'कपड़ों की बाँहें और पैंट फिर छोटी हो रही हैं! वेट ट्रैकर सेक्शन में नए आँकड़े डालिए और विकास के चार्ट की बढ़त पर नज़र रखिए।', title_id = 'Bagaimana laju pertumbuhannya? 📏', body_id = 'Lengan dan kaki celananya makin pendek lagi! Masukkan ukuran terbarunya di Pelacak Berat Badan dan pantau grafik pertumbuhannya yang terus naik.', title_ja = '成長の様子はどう？📏', body_ja = 'お洋服の袖やすそがまた短くなってきました！「体重トラッカー」に新しい数値を入れて、成長グラフの伸びを見守りましょう。', title_ko = '성장 속도는 어떤가요? 📏', body_ko = '옷소매와 바짓단이 또 짧아졌어요! 체중 기록에 새 수치를 입력하고 성장 그래프가 올라가는 걸 지켜보세요.', title_nl = 'Hoe gaat het met het groeitempo? 📏', body_nl = 'De mouwen en pijpen van de kleertjes worden alweer te kort! Voer de nieuwe gegevens in de Gewichtstracker in en volg hoe de groeicurve stijgt.', title_pl = 'Jak idzie wzrost? 📏', body_pl = 'Rękawy i nogawki znów są za krótkie! Wpisz nowe pomiary w sekcji Licznik wagi i obserwuj, jak pnie się wykres rozwoju.', title_pt = 'Como vai o ritmo de crescimento? 📏', body_pt = 'As mangas e as pernas das calças voltaram a ficar curtas! Introduza as novas medidas no Registo de Peso e acompanhe a subida do gráfico de crescimento.', title_sv = 'Hur går tillväxten? 📏', body_sv = 'Ärmarna och byxbenen blir korta igen! Skriv in de nya måtten i Viktspåraren och följ hur tillväxtkurvan stiger.', title_vi = 'Bé lớn lên thế nào rồi? 📏', body_vi = 'Tay áo và ống quần lại ngắn rồi! Hãy nhập số đo mới vào mục Theo dõi cân nặng và theo dõi biểu đồ phát triển đi lên.', title_zh = '成长速度怎么样？📏', body_zh = '衣服的袖子和裤腿又变短了！在体重记录里输入新的数据，关注成长曲线的上升吧。' WHERE id = 'cc468aff-f9d2-4961-b955-bf2eaa13f7ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La rabia de no poder expresarse 🌪', body_es = '️ Es normal que se enfade y llore cuando no consigue lo que quiere o no logra hacerse entender. Ponte a su altura y dile que entiendes lo que siente.', title_fr = 'La colère quand il n''arrive pas à s''exprimer. 🌪', body_fr = '️ C''est normal qu''il s''énerve et pleure quand il n''obtient pas ce qu''il veut ou n''arrive pas à se faire comprendre. Mettez-vous à sa hauteur et dites-lui que vous comprenez ce qu''il ressent.', title_hi = 'अपनी बात न कह पाने का गुस्सा। 🌪', body_hi = '️ मन का न होने पर या अपनी बात न समझा पाने पर उसका चिढ़कर रोना सामान्य है। उसके बराबर झुकिए और बताइए कि आप उसकी भावनाएँ समझती हैं।', title_id = 'Amarah karena belum bisa mengungkapkan diri. 🌪', body_id = '️ Wajar jika ia kesal dan menangis saat keinginannya tidak terpenuhi atau saat belum bisa membuat dirinya dipahami. Berjongkoklah setinggi dirinya dan katakan bahwa Anda memahami perasaannya.', title_ja = '気持ちを伝えられないときの怒り 🌪', body_ja = '️思いどおりにならなかったり、うまく伝えられなかったりすると、イライラして泣くのは自然なことです。目線を合わせてしゃがみ、「気持ちわかるよ」と伝えましょう。', title_ko = '표현하지 못해서 생기는 화. 🌪', body_ko = '️원하는 게 안 되거나 자신을 이해시키지 못할 때 화가 나서 우는 건 정상이에요. 눈높이를 맞춰 몸을 숙이고 마음을 이해한다고 말해 주세요.', title_nl = 'Boosheid als hij zich niet kan uiten. 🌪', body_nl = '️ Het is normaal dat je kindje boos wordt en huilt als hij iets niet krijgt of zich niet verstaanbaar kan maken. Zak door je knieën en zeg dat je zijn gevoelens begrijpt.', title_pl = 'Złość, gdy nie umie się wyrazić. 🌪', body_pl = '️ To normalne, że denerwuje się i płacze, gdy nie dostaje tego, czego chce, lub nie umie się wyrazić. Zniż się do jego poziomu i powiedz, że rozumiesz jego uczucia.', title_pt = 'A raiva de não se conseguir expressar. 🌪', body_pt = '️ É normal irritar-se e chorar quando não consegue o que quer ou não se consegue fazer entender. Baixe-se ao nível dele e diga-lhe que compreende o que sente.', title_sv = 'Ilska när barnet inte kan uttrycka sig. 🌪', body_sv = '️ Det är normalt att barnet blir argt och gråter när det inte får som det vill eller inte kan göra sig förstått. Sätt dig på barnets nivå och säg att du förstår känslorna.', title_vi = 'Cơn giận khi chưa diễn đạt được. 🌪', body_vi = '️ Khi không được như ý hay không diễn đạt được, bé bực bội và khóc là chuyện bình thường. Hãy cúi xuống ngang tầm bé và nói rằng mẹ hiểu cảm xúc của bé.', title_zh = '表达不出来时的怒气 🌪', body_zh = '️ 得不到想要的东西，或者没法让你明白时，又急又哭是正常的。蹲到他的高度，告诉他你懂他的感受。' WHERE id = '308b629a-7190-416d-8240-7f61a2fe4d68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja salir lo que sientes 📝', body_es = '¿Ha sido un día agotador? Cuando se duerma, escribe cómo te sientes en el Diario de ánimo y suelta el estrés del día.', title_fr = 'Libérez vos émotions. 📝', body_fr = 'La journée a été épuisante ? Une fois qu''il dort, évacuez le stress de la journée en écrivant vos ressentis dans le Journal d''humeur.', title_hi = 'अपनी भावनाओं को बाहर आने दीजिए। 📝', body_hi = 'बहुत थकाने वाला दिन था? बच्चे के सोने के बाद अपनी भावनाएँ मूड डायरी में लिखकर दिन का तनाव निकाल दीजिए।', title_id = 'Lepaskan perasaan Anda. 📝', body_id = 'Harinya sangat melelahkan? Setelah si kecil tidur, lepaskan stres hari ini dengan menuliskan perasaan Anda di Buku Harian Suasana Hati.', title_ja = '気持ちを解放しよう 📝', body_ja = 'とても疲れる一日でしたか？お子さんが寝たら「気分日記」に気持ちを書いて、一日のストレスを手放しましょう。', title_ko = '감정을 자유롭게 풀어 주세요. 📝', body_ko = '정말 지치는 하루였나요? 아이가 잠들면 기분 일기에 감정을 적으며 하루의 스트레스를 털어 내세요.', title_nl = 'Laat je gevoelens de vrije loop. 📝', body_nl = 'Was het een erg vermoeiende dag? Schrijf je gevoelens op in je Stemmingsdagboek als je kindje slaapt en laat de stress van de dag los.', title_pl = 'Daj upust uczuciom. 📝', body_pl = 'To był bardzo męczący dzień? Gdy maluszek zaśnie, zapisz swoje uczucia w Dzienniku nastroju i zrzuć z siebie stres dnia.', title_pt = 'Dê liberdade ao que sente. 📝', body_pt = 'Foi um dia muito cansativo? Quando ele adormecer, escreva o que sente no Diário de Humor e liberte o stress do dia.', title_sv = 'Släpp ut dina känslor. 📝', body_sv = 'Har det varit en väldigt tröttsam dag? Skriv dina känslor i Humördagboken när barnet somnat och släpp dagens stress.', title_vi = 'Hãy để cảm xúc được tự do. 📝', body_vi = 'Hôm nay thật mệt mỏi? Khi bé ngủ, hãy viết cảm xúc vào Nhật ký tâm trạng để trút bỏ căng thẳng trong ngày.', title_zh = '释放你的情绪 📝', body_zh = '今天特别累？宝宝睡着后，把感受写进心情日记，卸下一天的压力。' WHERE id = '78541e65-2128-40ff-8cb4-1e0d54454519' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubre sitios nuevos ☕', body_es = '¿Agobiada de la rutina diaria? Encuentra en Lugares para mamás cafeterías con menú infantil a las que ir cómodamente con tu peque.', title_fr = 'Découvrez de nouveaux lieux. ☕', body_fr = 'La routine vous pèse ? Trouvez dans les Lieux adaptés aux mamans des cafés avec menu enfant où aller facilement avec votre petit.', title_hi = 'नई जगहें खोजिए। ☕', body_hi = 'रोज़ के रूटीन से ऊब गई हैं? माँ के लिए अनुकूल जगहों में ऐसे कैफ़े ढूँढिए जहाँ बच्चे के साथ आराम से जा सकें और बच्चों का मेन्यू भी हो।', title_id = 'Temukan tempat baru. ☕', body_id = 'Bosan dengan rutinitas sehari-hari? Temukan kafe yang nyaman dikunjungi bersama anak dan punya menu anak di Tempat Ramah Ibu.', title_ja = '新しい場所を見つけよう ☕', body_ja = '毎日の繰り返しに疲れていませんか？「ママにやさしいスポット」で、子連れで気軽に行けるキッズメニューのあるカフェを見つけましょう。', title_ko = '새로운 장소를 발견해요. ☕', body_ko = '똑같은 일상이 답답한가요? 아이와 편하게 갈 수 있고 아이 메뉴가 있는 카페를 엄마 친화 장소에서 찾아보세요.', title_nl = 'Ontdek nieuwe plekken. ☕', body_nl = 'Zit je vast in de dagelijkse routine? Zoek in Mamavriendelijke plekken cafés met een kindermenu waar je makkelijk met je kindje naartoe kunt.', title_pl = 'Odkrywaj nowe miejsca. ☕', body_pl = 'Codzienna rutyna cię przytłacza? Znajdź w Miejscach przyjaznych mamom kawiarnie z menu dla dzieci, do których wygodnie pójdziesz z maluchem.', title_pt = 'Descubra novos lugares. ☕', body_pt = 'Está cansada da rotina diária? Encontre nos Locais Amigos das Mães cafés com menu infantil onde possa ir à vontade com a criança.', title_sv = 'Upptäck nya platser. ☕', body_sv = 'Trött på vardagsrutinen? Hitta kaféer med barnmeny som är lätta att besöka med barn i Mammavänliga platser.', title_vi = 'Khám phá địa điểm mới. ☕', body_vi = 'Mẹ thấy ngột ngạt với nếp sinh hoạt hằng ngày? Hãy tìm trong Địa điểm thân thiện với mẹ những quán cà phê có thực đơn trẻ em, tiện đưa bé đi cùng.', title_zh = '发现新地方 ☕', body_zh = '厌倦了日常重复？在妈妈友好场所里找一家适合带娃、有儿童菜单的咖啡馆吧。' WHERE id = '7ea95622-1f8d-4996-8638-aeeafe28a802' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de recoger y ordenar 🧺', body_es = 'A tu peque le encanta vaciar la caja de juguetes, y ahora también aprende a volver a guardar algunos. Cantad juntos una canción de recoger y convertidlo en un juego.', title_fr = 'Le jeu du rangement. 🧺', body_fr = 'Votre petit, qui adore vider les jouets de la boîte, apprend maintenant à en remettre quelques-uns. Chantez ensemble une chanson de rangement pour transformer la tâche en jeu.', title_hi = 'समेटने और सजाने का खेल। 🧺', body_hi = 'डिब्बे से खिलौने उलटना पसंद करने वाला आपका नन्हा अब उनमें से कुछ वापस रखना भी सीख रहा है। साथ में ''समेटो-समेटो'' गाना गाकर काम को खेल बना दीजिए।', title_id = 'Permainan mengumpulkan dan merapikan. 🧺', body_id = 'Si kecil yang senang menumpahkan mainan dari kotak kini juga belajar memasukkan beberapa di antaranya kembali. Jadikan kegiatan ini seru dengan menyanyikan lagu beres-beres bersama.', title_ja = 'お片付けごっこ 🧺', body_ja = 'おもちゃを箱からひっくり返すのが大好きなお子さんが、今度はいくつか戻すことも覚えています。一緒にお片付けの歌をうたって、楽しい遊びにしましょう。', title_ko = '모으고 정리하기 놀이. 🧺', body_ko = '상자에서 장난감을 쏟아 내길 좋아하던 아이가 이제 몇 개는 다시 넣는 법도 배워요. 함께 ''정리 정리'' 노래를 부르며 정리를 놀이로 만들어 보세요.', title_nl = 'Spelletje opruimen. 🧺', body_nl = 'Je kindje gooit graag speelgoed uit de doos, maar leert nu ook een paar dingen terug te leggen. Zing samen een opruimliedje en maak er een spelletje van.', title_pl = 'Zabawa w sprzątanie. 🧺', body_pl = 'Twój maluch, który uwielbia wysypywać zabawki z pudełka, uczy się teraz odkładać niektóre z powrotem. Śpiewajcie razem piosenkę o sprzątaniu i zamieńcie to w zabawę.', title_pt = 'O jogo de arrumar. 🧺', body_pt = 'O seu pequenino, que adora despejar os brinquedos da caixa, agora também aprende a voltar a pôr lá alguns. Cantem juntos uma canção de arrumar e transformem a tarefa numa brincadeira.', title_sv = 'Plocka undan-lek. 🧺', body_sv = 'Din lilla som älskar att tömma ut leksakerna ur lådan lär sig nu också att lägga tillbaka några. Sjung en städsång tillsammans och gör sysslan till lek.', title_vi = 'Trò chơi thu dọn. 🧺', body_vi = 'Bé thích đổ đồ chơi ra khỏi hộp, giờ còn đang học cất lại vài món. Hãy cùng hát bài "Thu dọn nào" để biến việc dọn dẹp thành trò chơi.', title_zh = '收拾整理游戏 🧺', body_zh = '喜欢把玩具从盒子里倒出来的小家伙，现在也在学着放回去几个了。一起唱“收玩具”的歌，把收拾变成游戏吧。' WHERE id = '58ff14f8-978e-4eec-8b86-a777de1b33ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cambia su horario de sueño? ⏱️', body_es = 'Si ya hace una sola siesta, el paso al sueño nocturno puede cambiar un poco. Sigue el horario de hoy con el Temporizador de sueño de Anacan y ajusta la nueva rutina.', title_fr = 'Son rythme de sommeil change ? ⏱️', body_fr = 'S''il ne fait plus qu''une seule sieste, l''heure du coucher peut un peu changer. Suivez le planning du jour avec le minuteur de sommeil Anacan et ajustez son nouveau rythme.', title_hi = 'नींद का दौर बदल रहा है? ⏱️', body_hi = 'अगर दिन की झपकी पूरी तरह एक रह गई है, तो रात की नींद का समय थोड़ा बदल सकता है। Anacan स्लीप टाइमर से आज का शेड्यूल देखिए और नया रूटीन तय कीजिए।', title_id = 'Pola tidurnya berubah? ⏱️', body_id = 'Kalau tidur siangnya sudah benar-benar satu kali, peralihan ke tidur malam bisa sedikit berubah. Pantau jadwal hari ini dengan Timer Tidur Anacan dan atur rutinitas barunya.', title_ja = '睡眠リズムが変わってきた？⏱️', body_ja = 'お昼寝がすっかり1回になると、夜の眠りへの切りかえも少し変わることがあります。Anacanの睡眠タイマーで今日の記録を見て、新しいリズムに整えましょう。', title_ko = '수면 주기가 바뀌나요? ⏱️', body_ko = '낮잠이 완전히 한 번으로 줄었다면 밤잠 시간이 조금 달라질 수 있어요. Anacan 수면 타이머로 오늘의 일정을 살펴보고 새 일과를 맞춰 주세요.', title_nl = 'Verandert het slaapritme? ⏱️', body_nl = 'Is je kindje helemaal overgestapt op één dutje? Dan kan het tijdstip van de nachtslaap wat verschuiven. Volg het schema van vandaag met de Slaaptimer van Anacan en stem het nieuwe ritme af.', title_pl = 'Zmienia się rytm snu? ⏱️', body_pl = 'Jeśli w ciągu dnia została już tylko jedna drzemka, pora nocnego snu może się nieco zmienić. Śledź dzisiejszy plan timerem snu Anacan i dopasuj nowy rytm.', title_pt = 'O padrão de sono está a mudar? ⏱️', body_pt = 'Se já faz só uma sesta, a passagem para o sono noturno pode mudar um pouco. Acompanhe o horário de hoje com o temporizador de sono do Anacan e ajuste a nova rotina.', title_sv = 'Förändras sömnen? ⏱️', body_sv = 'Om dagsluren helt har blivit en enda kan övergången till nattsömnen förändras lite. Följ dagens schema med Anacans sömntimer och justera den nya rutinen.', title_vi = 'Nếp ngủ đang thay đổi? ⏱️', body_vi = 'Nếu bé đã hoàn toàn chỉ ngủ một giấc ngày, giờ đi ngủ đêm có thể thay đổi đôi chút. Hãy theo dõi biểu đồ hôm nay bằng Bộ hẹn giờ ngủ của Anacan và điều chỉnh nếp mới.', title_zh = '睡眠周期在变化？⏱️', body_zh = '如果白天已经完全只睡一次，晚上入睡的时间可能会有些变化。用Anacan睡眠计时器看看今天的图表，调整新的作息吧。' WHERE id = 'b54bf6d9-a27d-4cd5-bc2b-21d160aa5b81' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Encajar formas (puzles) 🧩', body_es = 'Intenta meter el círculo por el agujero redondo y el cuadrado por el cuadrado. Estos juegos de lógica aumentan su paciencia y su atención.', title_fr = 'Les jeux d''encastrement (puzzles). 🧩', body_fr = 'Il essaie de faire passer le rond dans le trou rond et le carré dans le trou carré. Ces jeux de logique développent sa patience et son attention.', title_hi = 'आकार बिठाना (पज़ल)। 🧩', body_hi = 'गोले को गोल छेद में और चौकोर को चौकोर छेद में डालने की कोशिश करता है। तर्क वाले ये खेल उसका धैर्य और ध्यान बढ़ाते हैं।', title_id = 'Memasukkan bentuk (puzzle). 🧩', body_id = 'Ia mencoba memasukkan lingkaran ke lubang lingkaran dan persegi ke lubang persegi. Permainan logika ini meningkatkan kesabaran dan fokusnya.', title_ja = '型はめパズル 🧩', body_ja = '丸は丸い穴に、四角は四角い穴に入れようとしています。こうした考える遊びは、忍耐力と集中力を育てます。', title_ko = '모양 맞추기(퍼즐). 🧩', body_ko = '동그라미는 동그란 구멍에, 네모는 네모난 구멍에 넣으려 해요. 이런 논리 놀이가 인내심과 집중력을 키워 줘요.', title_nl = 'Vormen insteken (puzzels). 🧩', body_nl = 'Je kindje probeert het rondje in het ronde gat en het vierkantje in het vierkante gat te steken. Deze denkspelletjes vergroten zijn geduld en concentratie.', title_pl = 'Dopasowywanie kształtów (układanki). 🧩', body_pl = 'Próbuje włożyć kółko do okrągłego otworu, a kwadrat do kwadratowego. Takie zabawy logiczne wzmacniają jego cierpliwość i uwagę.', title_pt = 'Encaixar formas (puzzles). 🧩', body_pt = 'Tenta pôr o círculo no buraco redondo e o quadrado no buraco quadrado. Estes jogos de lógica aumentam a paciência e a atenção.', title_sv = 'Formpussel (Puzzles). 🧩', body_sv = 'Barnet försöker få cirkeln i det runda hålet och kvadraten i det fyrkantiga. Dessa logiklekar stärker tålamodet och uppmärksamheten.', title_vi = 'Trò chơi thả hình khối. 🧩', body_vi = 'Bé cố bỏ hình tròn vào lỗ tròn, hình vuông vào lỗ vuông. Những trò chơi tư duy này giúp bé kiên nhẫn và tập trung hơn.', title_zh = '形状配对（拼图）🧩', body_zh = '他在尝试把圆形放进圆孔，把方形放进方孔。这些逻辑游戏能提升他的耐心和专注力。' WHERE id = 'e71126af-730c-4cca-8daa-1682609e21a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le cuesta más dormirse? 😴', body_es = 'Tanto descubrimiento a veces le deja muy activado. Activa el Temporizador de sueño y, antes de dormir, baja al mínimo la luz de la habitación y léele un cuento.', title_fr = 'L''endormissement devient difficile ? 😴', body_fr = 'Les explorations actives le gardent parfois très excité. Lancez le minuteur de sommeil, baissez la lumière au minimum et lisez-lui une histoire avant de dormir.', title_hi = 'सोना मुश्किल हो रहा है? 😴', body_hi = 'खोजबीन भरी भाग-दौड़ कभी-कभी बच्चे को उत्साहित रखती है। स्लीप टाइमर चालू कीजिए और सोने से पहले कमरे की रोशनी कम से कम करके कहानी पढ़िए।', title_id = 'Makin sulit tertidur? 😴', body_id = 'Penjelajahan yang aktif kadang membuat anak tetap bersemangat. Nyalakan Timer Tidur, redupkan lampu kamar seminimal mungkin sebelum tidur, lalu bacakan dongeng.', title_ja = '寝つきが悪くなってきた？😴', body_ja = '活発な探検のあとは、興奮が続くこともあります。睡眠タイマーをオンにして、寝る前は部屋の照明をできるだけ暗くし、お話を読んであげましょう。', title_ko = '잠들기가 어려워졌나요? 😴', body_ko = '활발한 탐험 때문에 아이가 흥분 상태로 있을 때가 있어요. 수면 타이머를 켜고 잠들기 전 방의 조명을 최소로 낮춘 뒤 동화를 읽어 주세요.', title_nl = 'Moeilijker in slaap vallen? 😴', body_nl = 'Actief ontdekken houdt een kindje soms opgewonden. Zet de Slaaptimer aan, dim voor het slapengaan de lichten zo ver mogelijk en lees een verhaaltje voor.', title_pl = 'Coraz trudniej zasnąć? 😴', body_pl = 'Aktywne odkrywanie czasem trzyma dziecko w podekscytowaniu. Włącz timer snu, przed snem przygaś światło w pokoju do minimum i przeczytaj bajkę.', title_pt = 'Adormecer está a ficar mais difícil? 😴', body_pt = 'As descobertas ativas às vezes deixam a criança agitada. Ligue o temporizador de sono e, antes de dormir, baixe ao mínimo a luz do quarto e leia uma história.', title_sv = 'Blir det svårare att somna? 😴', body_sv = 'Aktiva upptäckter kan ibland hålla barnet uppspelt. Starta sömntimern, dämpa ljuset i rummet till ett minimum och läs en saga före sömnen.', title_vi = 'Bé khó vào giấc hơn? 😴', body_vi = 'Những khám phá sôi nổi đôi khi khiến bé còn phấn khích. Hãy bật Bộ hẹn giờ ngủ, giảm đèn trong phòng xuống thấp nhất và đọc truyện trước khi ngủ.', title_zh = '入睡变难了？😴', body_zh = '活跃的探索有时会让孩子一直很兴奋。打开睡眠计时器，睡前把房间灯光调到最暗，讲个故事吧。' WHERE id = '069cc383-0002-41b5-ba19-4172c6d6b10f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '«Gracias» y «Por favor» 🙏', body_es = 'Ya hace un gesto con la cabeza o da las gracias a su manera cuando da o recibe algo. ¡Es el momento perfecto para aprender las normas sociales!', title_fr = 'Merci et s''il te plaît. 🙏', body_fr = 'Quand il donne ou reçoit quelque chose, il fait un signe de tête ou dit merci à sa façon. C''est le moment idéal pour apprendre les règles de politesse !', title_hi = '''धन्यवाद'' और ''कृपया''। 🙏', body_hi = 'अब वह कुछ देते या लेते समय सिर से इशारा करता है या अपनी भाषा में धन्यवाद कहता है। सामाजिक तौर-तरीके सीखने का यही सही समय है!', title_id = '"Terima kasih" dan "Tolong". 🙏', body_id = 'Kini saat memberi atau menerima sesuatu, ia mengangguk atau berterima kasih dengan bahasanya sendiri. Inilah saat yang tepat untuk belajar aturan sosial!', title_ja = '「ありがとう」と「どうぞ」🙏', body_ja = '何かを渡したり受け取ったりするとき、うなずいたり、自分なりの言葉でお礼を伝えたりしています。社会のルールを学ぶのにぴったりの時期です！', title_ko = '"고마워"와 "주세요". 🙏', body_ko = '이제 무언가를 주고받을 때 고개를 끄덕이거나 자기만의 말로 고마움을 표현해요. 사회적 규칙을 배우기에 딱 좋은 때예요!', title_nl = 'Dank je en alsjeblieft. 🙏', body_nl = 'Knikt je kindje als hij iets geeft of krijgt, of bedankt hij in zijn eigen taaltje? Het perfecte moment om sociale regels te leren!', title_pl = '„Dziękuję” i „Proszę”. 🙏', body_pl = 'Gdy coś daje lub bierze, kiwa już głową lub po swojemu dziękuje. To najlepszy czas na naukę zasad grzeczności!', title_pt = '"Obrigado" e "Por favor". 🙏', body_pt = 'Quando dá ou recebe alguma coisa, já faz sinal com a cabeça ou agradece à sua maneira. É a altura certa para aprender as regras sociais!', title_sv = 'Tack och Snälla. 🙏', body_sv = 'När barnet ger eller får något nickar det nu eller visar tacksamhet på sitt eget språk. Det är precis rätt tid att lära sig sociala regler!', title_vi = '"Cảm ơn" và "Làm ơn". 🙏', body_vi = 'Giờ khi đưa hay nhận thứ gì, bé gật đầu hoặc cảm ơn bằng ngôn ngữ riêng của mình. Đây là lúc tuyệt vời để học các quy tắc ứng xử!', title_zh = '“谢谢”和“请” 🙏', body_zh = '给东西或拿东西时，他会点点头，或用自己的语言表示感谢。正是学习社交规则的好时候！' WHERE id = '1beeca23-44cf-48f8-9b07-fc08412e7809' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Seguimos su altura y su peso 📏', body_es = '¿Se le vuelve a quedar pequeña la ropa? Actualiza sus nuevas medidas en el Registro de peso y prepara su gráfica de crecimiento para el día 500.', title_fr = 'On suit sa taille et son poids. 📏', body_fr = 'Ses vêtements redeviennent trop petits ? Mettez à jour ses mesures dans le Suivi du poids et préparez sa courbe de croissance pour le 500e jour.', title_hi = 'लंबाई और वज़न की बढ़त पर नज़र। 📏', body_hi = 'कपड़े फिर छोटे हो रहे हैं? वेट ट्रैकर सेक्शन में नए आँकड़े अपडेट कीजिए और 500वें दिन के लिए विकास का चार्ट तैयार कीजिए।', title_id = 'Memantau pertambahan tinggi dan berat. 📏', body_id = 'Bajunya kekecilan lagi? Perbarui ukuran terbarunya di Pelacak Berat Badan dan siapkan grafik pertumbuhannya menuju hari ke-500.', title_ja = '身長と体重の伸びを見守ろう 📏', body_ja = 'お洋服がまた小さくなってきた？「体重トラッカー」で新しい数値を更新して、500日目に向けて成長グラフを準備しましょう。', title_ko = '키와 몸무게 성장을 지켜봐요. 📏', body_ko = '옷이 또 작아졌나요? 체중 기록에서 새 수치를 업데이트하고 500일을 위한 성장 그래프를 준비하세요.', title_nl = 'We volgen lengte en gewicht. 📏', body_nl = 'Worden de kleertjes alweer te klein? Werk de nieuwe gegevens bij in de Gewichtstracker en maak de groeicurve klaar voor dag 500.', title_pl = 'Śledzimy wzrost i wagę. 📏', body_pl = 'Ubranka znów są za małe? Zaktualizuj pomiary w sekcji Licznik wagi i przygotuj wykres rozwoju na 500. dzień.', title_pt = 'A acompanhar a altura e o peso. 📏', body_pt = 'A roupa voltou a ficar pequena? Atualize as novas medidas no Registo de Peso e prepare o gráfico de crescimento para o dia 500.', title_sv = 'Vi följer längd och vikt. 📏', body_sv = 'Blir kläderna för små igen? Uppdatera de nya måtten i Viktspåraren och gör tillväxtkurvan redo för dag 500.', title_vi = 'Theo dõi chiều cao và cân nặng. 📏', body_vi = 'Quần áo lại chật rồi? Hãy cập nhật số đo mới trong mục Theo dõi cân nặng và chuẩn bị biểu đồ phát triển cho ngày thứ 500.', title_zh = '关注身高体重增长 📏', body_zh = '衣服又变小了？在体重记录里更新新数据，为第500天准备好成长曲线吧。' WHERE id = 'eb807359-495c-4338-a628-e4dd3e405226' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reconoce los animales del libro 🐶', body_es = '¿Cuando le preguntas «¿Dónde está el perro?» lo señala con el dedo? Para ampliar su vocabulario, empieza a decirle también los colores de las cosas del libro.', title_fr = 'Il reconnaît les animaux du livre. 🐶', body_fr = 'Quand vous dites « Où est le chien ? », il le montre du doigt ? Pour enrichir son vocabulaire, commencez aussi à nommer les couleurs des objets du livre.', title_hi = 'किताब के जानवरों को पहचानता है। 🐶', body_hi = '''कुत्ता कहाँ है?'' पूछने पर उँगली से दिखाता है? शब्द भंडार बढ़ाने के लिए किताब की चीज़ों के रंग भी बताना शुरू कीजिए।', title_id = 'Mengenali hewan di buku. 🐶', body_id = 'Saat Anda bertanya "Anjingnya mana?", ia menunjuk dengan jarinya? Untuk menambah kosakatanya, mulailah juga menyebutkan warna benda-benda di buku.', title_ja = '絵本の動物がわかる 🐶', body_ja = '「わんわんはどこ？」と聞くと、指さしますか？語彙を増やすために、絵本のものの色も言ってみましょう。', title_ko = '책 속 동물을 알아봐요. 🐶', body_ko = '"강아지 어디 있어?" 하면 손가락으로 가리키나요? 어휘를 늘리기 위해 책 속 물건의 색깔도 말해 주기 시작하세요.', title_nl = 'Herkent dieren in boeken. 🐶', body_nl = 'Wijst je kindje het aan als je vraagt: waar is de hond? Noem ook de kleuren van de dingen in het boek om zijn woordenschat te vergroten.', title_pl = 'Rozpoznaje zwierzęta w książce. 🐶', body_pl = 'Na pytanie „Gdzie jest piesek?” pokazuje go paluszkiem? Aby wzbogacić zasób słów, zacznij też nazywać kolory przedmiotów w książce.', title_pt = 'Reconhece os animais do livro. 🐶', body_pt = 'Quando lhe pergunta "Onde está o cão?", aponta com o dedo? Para aumentar o vocabulário, comece também a dizer as cores dos objetos do livro.', title_sv = 'Känner igen djuren i boken. 🐶', body_sv = 'Pekar barnet när du frågar ”Var är hunden?”? Börja också säga färgerna på sakerna i boken för att öka ordförrådet.', title_vi = 'Bé nhận ra con vật trong sách. 🐶', body_vi = 'Mẹ hỏi "Con chó đâu?" là bé chỉ tay? Để tăng vốn từ, hãy bắt đầu nói cả màu sắc của đồ vật trong sách nhé.', title_zh = '认识书里的动物 🐶', body_zh = '你问“小狗在哪里？”他会用手指指出来？为了扩大词汇量，开始告诉他书里东西的颜色吧。' WHERE id = '158d01ac-e4e7-4be6-959c-37e93007ee0b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hay que actualizar la seguridad 🛡️', body_es = 'Ya llega más alto. Revisa otra vez los manteles y las esquinas afiladas. Si hace falta, echa un vistazo a los Productos recomendados.', title_fr = 'La sécurité doit être revue. 🛡️', body_fr = 'Il atteint désormais des endroits plus hauts. Vérifiez à nouveau les nappes et les coins pointus. Si besoin, jetez un œil aux Produits recommandés.', title_hi = 'सुरक्षा को अपडेट करना ज़रूरी है। 🛡️', body_hi = 'अब वह और ऊँचा पहुँच सकता है। मेज़पोश और नुकीले कोने एक बार फिर जाँचिए। ज़रूरत हो तो सुझाए गए प्रोडक्ट देखिए।', title_id = 'Keamanan perlu diperbarui. 🛡️', body_id = 'Kini ia bisa meraih tempat yang lebih tinggi. Periksa lagi taplak meja dan sudut-sudut tajam. Bila perlu, lihat Produk Rekomendasi.', title_ja = '安全対策を見直そう 🛡️', body_ja = 'もっと高いところに手が届くようになりました。テーブルクロスやとがった角をもう一度チェックしましょう。必要なら「おすすめ商品」をのぞいてみて。', title_ko = '안전 점검을 새로 할 때예요. 🛡️', body_ko = '이제 더 높은 곳까지 손이 닿아요. 식탁보와 날카로운 모서리를 다시 확인하세요. 필요하면 추천 제품을 살펴보세요.', title_nl = 'Tijd om de veiligheid bij te werken. 🛡️', body_nl = 'Je kindje kan nu hoger reiken. Controleer tafelkleden en scherpe hoeken nog eens. Kijk zo nodig bij Aanbevolen producten.', title_pl = 'Czas odświeżyć zabezpieczenia. 🛡️', body_pl = 'Sięga już wyżej. Jeszcze raz sprawdź obrusy i ostre narożniki. W razie potrzeby zajrzyj do Polecanych produktów.', title_pt = 'É altura de reforçar a segurança. 🛡️', body_pt = 'Já chega mais alto. Verifique outra vez as toalhas de mesa e as esquinas afiadas. Se for preciso, espreite os Produtos Recomendados.', title_sv = 'Säkerheten behöver uppdateras. 🛡️', body_sv = 'Barnet når nu högre. Kontrollera bordsdukar och vassa hörn en gång till. Titta vid behov i Rekommenderade produkter.', title_vi = 'Cần cập nhật an toàn. 🛡️', body_vi = 'Bé đã với cao hơn rồi. Hãy kiểm tra lại khăn trải bàn và các góc nhọn. Nếu cần, hãy xem Sản phẩm gợi ý.', title_zh = '安全措施需要升级 🛡️', body_zh = '宝宝已经能够到更高的地方了。再检查一遍桌布和尖锐的桌角。需要的话，看看推荐商品吧。' WHERE id = '9e266e10-1251-4668-af5f-a58fe3b3f537' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de las travesuras con papá 👨‍🍼', body_es = 'Deja a papá la parte más movida de la tarde. Sus juegos llenos de risas refuerzan su vínculo y a ti te dan un respiro.', title_fr = 'L''heure des bêtises avec papa. 👨‍🍼', body_fr = 'Confiez à papa la partie la plus énergique de la soirée. Leurs jeux pleins de rires renforcent leur lien et vous permettent de vous reposer.', title_hi = 'पापा की शरारत का समय। 👨‍🍼', body_hi = 'शाम का भाग-दौड़ वाला हिस्सा पापा को सौंपिए। उनकी हँसी भरी साथ की मस्ती उनका रिश्ता भी मज़बूत करती है और आपको आराम भी देती है।', title_id = 'Jam bermain seru bersama ayah. 👨‍🍼', body_id = 'Serahkan bagian sore yang penuh energi kepada ayah. Permainan mereka yang penuh tawa mempererat ikatan mereka sekaligus memberi Anda waktu istirahat.', title_ja = 'パパのやんちゃタイム 👨‍🍼', body_ja = '夜の元気いっぱいの時間はパパにお任せ。笑い声あふれる遊びが親子のきずなを深め、あなたもひと休みできます。', title_ko = '아빠의 장난 시간. 👨‍🍼', body_ko = '저녁의 활기찬 시간은 아빠에게 맡기세요. 웃음 가득한 둘만의 놀이가 유대를 깊게 하고, 엄마는 쉴 수 있어요.', title_nl = 'Ravotten met papa. 👨‍🍼', body_nl = 'Laat het energieke deel van de avond aan papa over. Hun spelletjes vol gelach versterken hun band en geven jou rust.', title_pl = 'Godzina psot z tatą. 👨‍🍼', body_pl = 'Najbardziej energiczną część wieczoru przekaż tacie. Ich wspólne zabawy pełne śmiechu wzmacniają więź, a ty możesz odpocząć.', title_pt = 'A hora das traquinices com o pai. 👨‍🍼', body_pt = 'Entregue ao pai a parte mais agitada da noite. As brincadeiras cheias de gargalhadas fortalecem o laço entre eles e deixam-na descansar.', title_sv = 'Pappas busstund. 👨‍🍼', body_sv = 'Låt pappa sköta kvällens energiska del. Deras skrattfyllda lekar stärker bandet mellan dem och ger dig vila.', title_vi = 'Giờ nghịch ngợm cùng bố. 👨‍🍼', body_vi = 'Hãy giao phần sôi động của buổi tối cho bố. Những trò chơi đầy tiếng cười của hai bố con vừa gắn kết tình cảm, vừa giúp mẹ được nghỉ ngơi.', title_zh = '爸爸的捣蛋时间 👨‍🍼', body_zh = '把晚上最闹腾的那段时间交给爸爸。他们一起欢笑玩耍，既能加深感情，也能让你休息一下。' WHERE id = 'ca40c713-93a7-4e51-9b1b-8465a3151e1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos sensoriales 🌾', body_es = 'Echa arroz o arena en un recipiente grande y esconde juguetes dentro. Buscarlos con las manos es buenísimo para la motricidad de sus dedos.', title_fr = 'Jeux sensoriels. 🌾', body_fr = 'Versez du riz ou du sable dans un grand récipient et cachez-y des jouets. Les chercher avec ses mains est idéal pour la motricité de ses doigts.', title_hi = 'छूकर महसूस करने वाले खेल। 🌾', body_hi = 'एक बड़े बर्तन में चावल या रेत डालकर उसमें खिलौने छिपाइए। हाथों से उन्हें ढूँढना उँगलियों की मोटर स्किल्स के लिए अनमोल है।', title_id = 'Permainan sensorik. 🌾', body_id = 'Tuang beras atau pasir ke wadah besar dan sembunyikan mainan di dalamnya. Mencarinya dengan tangan sangat bermanfaat untuk motorik jarinya.', title_ja = '感覚遊び 🌾', body_ja = '大きな容器にお米や砂を入れて、中におもちゃを隠しましょう。手で探すことは、指先の発達にとても役立ちます。', title_ko = '감각 놀이. 🌾', body_ko = '큰 그릇에 쌀이나 모래를 붓고 장난감을 숨겨 보세요. 손으로 찾아보는 놀이는 손가락 근육 발달에 정말 좋아요.', title_nl = 'Voelspelletjes. 🌾', body_nl = 'Doe rijst of zand in een grote bak en verstop er speeltjes in. Ze met zijn handjes zoeken is onbetaalbaar voor de motoriek van zijn vingers.', title_pl = 'Zabawy sensoryczne. 🌾', body_pl = 'Wsyp do dużej miski ryż lub piasek i schowaj w nim zabawki. Szukanie ich rączkami jest bezcenne dla motoryki palców.', title_pt = 'Jogos sensoriais. 🌾', body_pt = 'Deite arroz ou areia num recipiente grande e esconda lá dentro brinquedos. Procurá-los com as mãos é precioso para a motricidade dos dedos.', title_sv = 'Sinneslekar. 🌾', body_sv = 'Häll ris eller sand i en stor skål och göm leksaker i den. Att leta efter dem med händerna är ovärderligt för fingermotoriken.', title_vi = 'Trò chơi giác quan. 🌾', body_vi = 'Đổ gạo hoặc cát vào một chiếc thau lớn và giấu đồ chơi vào trong. Dùng tay tìm đồ chơi rất có lợi cho vận động tinh của các ngón tay.', title_zh = '感官游戏 🌾', body_zh = '在大盆里倒些大米或沙子，把玩具藏进去。让他用手去找，对手指精细动作特别有益。' WHERE id = '17791a06-d7d3-466d-acee-c2689fa82589' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que elija su ropa 👕', body_es = '«¿Quieres ponerte la camiseta azul o la verde?» Darle dos opciones refuerza su sentido de sí mismo y reduce un poco la terquedad.', title_fr = 'Le choix des vêtements. 👕', body_fr = '« Tu veux mettre le t-shirt bleu ou le vert ? » Proposer deux choix renforce son sentiment d''identité et réduit un peu l''entêtement.', title_hi = 'कपड़ों में चुनने का हक। 👕', body_hi = '''नीली कमीज़ पहनोगे या हरी?'' दो विकल्प देने से उसकी अपनी पहचान की भावना बढ़ती है और ज़िद थोड़ी कम होती है।', title_id = 'Hak memilih pakaian. 👕', body_id = '"Mau pakai kaus biru atau hijau?" Memberi dua pilihan memperkuat rasa dirinya dan sedikit mengurangi sikap keras kepala.', title_ja = 'お洋服を選ぶ権利 👕', body_ja = '「青いシャツにする？緑にする？」2つの選択肢をあげると、自分らしさが育ち、いやいやも少し減ります。', title_ko = '옷을 고를 권리. 👕', body_ko = '"파란 티 입을래, 초록 티 입을래?" 두 가지 선택지를 주면 자아감이 커지고 고집이 조금 줄어들어요.', title_nl = 'Zelf kleren kiezen. 👕', body_nl = 'Wil je het blauwe shirt aan of het groene? Twee keuzes geven versterkt zijn gevoel van eigenwaarde en vermindert de koppigheid een beetje.', title_pl = 'Prawo wyboru ubrania. 👕', body_pl = '„Chcesz założyć niebieską koszulkę czy zieloną?” Dwie opcje do wyboru wzmacniają jego poczucie własnego „ja” i trochę zmniejszają upór.', title_pt = 'O direito de escolher a roupa. 👕', body_pt = '"Queres vestir a camisola azul ou a verde?" Dar-lhe duas opções reforça o sentido de si próprio e reduz um pouco a teimosia.', title_sv = 'Rätt att välja kläder. 👕', body_sv = '”Vill du ha den blå tröjan eller den gröna?” Att ge två valmöjligheter stärker självkänslan och minskar trotset lite.', title_vi = 'Quyền chọn quần áo. 👕', body_vi = '"Con muốn mặc áo xanh dương hay áo xanh lá?" Cho bé hai lựa chọn giúp tăng ý thức về bản thân và giảm bướng bỉnh đôi chút.', title_zh = '穿衣服的选择权 👕', body_zh = '“你想穿蓝衣服还是绿衣服？”给他两个选择，能增强他的自我意识，也能让倔强少一点。' WHERE id = '85ff80d1-72d4-4dd2-9fa5-45e283e54bc3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Relajarse jugando con agua 🛁', body_es = 'Un baño templado y el chapoteo del agua se llevarán todo el cansancio del día. Pon recipientes de distintos tamaños en el agua y enséñale el concepto de volumen.', title_fr = 'Se détendre en jouant dans l''eau. 🛁', body_fr = 'Un bain tiède et le clapotis de l''eau emporteront toute la fatigue de la journée. Mettez dans l''eau des récipients de tailles différentes pour lui apprendre la notion de volume.', title_hi = 'पानी के खेलों से सुकून। 🛁', body_hi = 'गुनगुना स्नान और पानी की कलकल दिनभर की सारी थकान दूर कर देगी। पानी में अलग-अलग आकार के बर्तन डालकर उसे मात्रा का अंदाज़ा सिखाइए।', title_id = 'Rileks lewat bermain air. 🛁', body_id = 'Mandi air hangat dan gemericik air akan menghapus semua lelah seharian. Masukkan wadah berbagai ukuran ke dalam air untuk mengajarkan konsep volume.', title_ja = '水遊びでリラックス 🛁', body_ja = 'ぬるめのお風呂と水の音が、一日の疲れをすっかり流してくれます。大きさのちがう容器をお湯に入れて、量の感覚を教えてあげましょう。', title_ko = '물놀이로 긴장 풀기. 🛁', body_ko = '따뜻한 목욕과 졸졸 흐르는 물소리가 하루의 피로를 모두 씻어 줄 거예요. 물속에 크기가 다른 그릇을 넣어 양의 개념을 알려 주세요.', title_nl = 'Ontspannen met waterspelletjes. 🛁', body_nl = 'Een lauw badje en het geklater van water spoelen alle vermoeidheid van de dag weg. Zet bakjes van verschillende maten in het water en leer hem wat inhoud is.', title_pl = 'Relaks przy zabawach w wodzie. 🛁', body_pl = 'Ciepła kąpiel i szum wody zabiorą całe zmęczenie dnia. Włóż do wody pojemniki różnej wielkości i ucz go pojęcia objętości.', title_pt = 'Relaxar com brincadeiras na água. 🛁', body_pt = 'Um banho morno e o barulhinho da água vão levar todo o cansaço do dia. Ponha na água recipientes de tamanhos diferentes e ensine-lhe a noção de volume.', title_sv = 'Avslappning med vattenlek. 🛁', body_sv = 'Ett ljummet bad och vattnets porlande tar bort all dagens trötthet. Lägg burkar i olika storlekar i vattnet och lär barnet begreppet volym.', title_vi = 'Thư giãn với trò chơi nước. 🛁', body_vi = 'Tắm nước ấm và tiếng nước róc rách sẽ cuốn đi mọi mệt mỏi trong ngày. Hãy thả vào nước những chiếc cốc to nhỏ khác nhau để dạy bé khái niệm về thể tích.', title_zh = '玩水放松 🛁', body_zh = '温水澡和哗哗的水声会带走一天的疲惫。在水里放几个大小不同的容器，教他认识“容量”吧。' WHERE id = 'e6632c98-233d-431d-adc3-c5f78c1c7a37' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comparte lo que sientes ✨', body_es = 'A veces todo se junta. Al final del día, dedícate a un hobby que te guste para encontrar tu paz interior.', title_fr = 'Partagez vos émotions. ✨', body_fr = 'Parfois, tout s''accumule. En fin de journée, consacrez-vous à un loisir que vous aimez pour retrouver votre sérénité.', title_hi = 'अपनी भावनाएँ बाँटिए। ✨', body_hi = 'कभी-कभी सब कुछ एक साथ आ पड़ता है। दिन खत्म होने पर अंदर का सुकून पाने के लिए अपने पसंदीदा शौक में समय बिताइए।', title_id = 'Bagikan perasaan Anda. ✨', body_id = 'Kadang semuanya datang bersamaan. Saat hari berakhir, lakukan hobi favorit Anda untuk menemukan ketenangan batin.', title_ja = '気持ちを分かち合おう ✨', body_ja = '何もかもが重なってしまうこともあります。一日の終わりには、好きな趣味の時間をとって、心の平穏を取り戻しましょう。', title_ko = '감정을 나눠 보세요. ✨', body_ko = '가끔은 모든 게 한꺼번에 몰려올 수 있어요. 하루가 끝나면 좋아하는 취미를 즐기며 마음의 평화를 찾아보세요.', title_nl = 'Deel je gevoelens. ✨', body_nl = 'Soms komt alles tegelijk. Doe aan het eind van de dag iets wat je graag doet om je innerlijke rust terug te vinden.', title_pl = 'Podziel się uczuciami. ✨', body_pl = 'Czasem wszystko się nawarstwia. Gdy dzień się skończy, zajmij się ulubionym hobby, by odnaleźć wewnętrzny spokój.', title_pt = 'Partilhe o que sente. ✨', body_pt = 'Às vezes tudo se acumula. Ao fim do dia, dedique-se a um passatempo de que goste para encontrar a sua paz interior.', title_sv = 'Dela dina känslor. ✨', body_sv = 'Ibland kan allt hopa sig. Ägna dig åt en hobby du gillar när dagen är slut för att hitta din inre ro.', title_vi = 'Hãy chia sẻ cảm xúc. ✨', body_vi = 'Đôi khi mọi thứ dồn dập cùng lúc. Cuối ngày, hãy làm một sở thích yêu thích để tìm lại sự bình yên trong lòng.', title_zh = '分享你的感受 ✨', body_zh = '有时候所有事情会一起涌来。一天结束时，做点自己喜欢的事，找回内心的平静吧。' WHERE id = '148de716-5fb6-4776-96cc-81e2d00b53b8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lanza la pelota al objetivo! ⚽', body_es = 'Ya no solo rueda la pelota: intenta lanzarla en una dirección concreta. Es una señal clara de que su coordinación ojo-mano se está desarrollando.', title_fr = 'Il vise avec le ballon ! ⚽', body_fr = 'Il ne se contente plus de faire rouler le ballon, il essaie de le lancer dans une direction précise. C''est un signe évident que sa coordination œil-main se développe.', title_hi = 'गेंद निशाने पर फेंकता है! ⚽', body_hi = 'गेंद सिर्फ़ लुढ़काता नहीं, किसी खास दिशा में फेंकने की कोशिश करता है। यह आँख-हाथ के तालमेल के विकास का साफ़ संकेत है।', title_id = 'Melempar bola ke sasaran! ⚽', body_id = 'Ia tidak hanya menggelindingkan bola, tapi mencoba melemparnya ke arah tertentu. Ini tanda jelas perkembangan koordinasi mata-tangannya.', title_ja = 'ボールを狙って投げる！⚽', body_ja = 'ボールを転がすだけでなく、決まった方向へ投げようとしています。目と手の協調が育っているはっきりしたサインです。', title_ko = '공을 목표를 향해 던져요! ⚽', body_ko = '공을 굴리기만 하는 게 아니라 정해진 방향으로 던지려 해요. 눈과 손의 협응력이 발달하고 있다는 뚜렷한 신호예요.', title_nl = 'Gooit de bal naar een doel! ⚽', body_nl = 'Je kindje rolt de bal niet meer alleen, hij probeert hem een bepaalde kant op te gooien. Een duidelijk teken dat zijn oog-handcoördinatie zich ontwikkelt.', title_pl = 'Rzuca piłką do celu! ⚽', body_pl = 'Już nie tylko turla piłkę, ale próbuje rzucić ją w określonym kierunku. To wyraźny znak rozwoju koordynacji wzrokowo-ruchowej.', title_pt = 'Atira a bola ao alvo! ⚽', body_pt = 'Já não se limita a rolar a bola, tenta atirá-la numa direção certa. É um sinal claro do desenvolvimento da coordenação olho-mão.', title_sv = 'Kastar bollen mot ett mål! ⚽', body_sv = 'Barnet rullar inte bara bollen, utan försöker kasta den i en viss riktning. Det är ett tydligt tecken på att öga-hand-koordinationen utvecklas.', title_vi = 'Ném bóng trúng đích! ⚽', body_vi = 'Bé không chỉ lăn bóng mà còn cố ném theo một hướng nhất định. Đây là dấu hiệu rõ ràng của khả năng phối hợp tay mắt đang phát triển.', title_zh = '朝目标扔球！⚽', body_zh = '宝宝不只是滚球，还会朝某个方向扔。这明显说明他的手眼协调在发展。' WHERE id = 'b3ddea65-cbd9-4fdd-900d-8914e021db1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Haz que beber agua sea divertido 💧', body_es = 'Los niños activos tienen sed enseguida. Ofrécele agua a menudo en un vaso de aprendizaje de colores y llamativo para que no se deshidrate.', title_fr = 'Rendez l''eau amusante. 💧 A', body_fr = 'Les enfants actifs ont vite soif. Proposez-lui régulièrement de l''eau dans une gourde colorée et amusante pour qu''il reste bien hydraté.', title_hi = 'पानी पीना मज़ेदार बनाइए। 💧 A', body_hi = 'सक्रिय बच्चों को जल्दी प्यास लगती है। रंगीन और दिलचस्प सिपी कप से उसे नियमित रूप से पानी दीजिए, ताकि शरीर में पानी की कमी न हो।', title_id = 'Jadikan minum air menyenangkan. 💧 A', body_id = 'Anak yang aktif cepat haus. Tawarkan air secara rutin dengan botol minum yang berwarna dan menarik agar tubuhnya tidak kekurangan cairan.', title_ja = 'お水を楽しく飲もう 💧', body_ja = '活発な子はすぐにのどが渇きます。カラフルで楽しいマグで、こまめにお水をすすめて、水分不足を防ぎましょう。', title_ko = '물 마시기를 재미있게. 💧', body_ko = '활발한 아이는 금방 목이 말라요. 알록달록하고 재미있는 물병으로 물을 자주 권해 몸에 수분이 부족하지 않게 해 주세요.', title_nl = 'Maak water drinken leuk. 💧 A', body_nl = 'Actieve kinderen krijgen snel dorst. Bied je kindje regelmatig water aan in een kleurrijke, leuke drinkbeker, zodat hij niet uitdroogt.', title_pl = 'Niech picie wody będzie zabawą. 💧', body_pl = 'Aktywnym dzieciom szybko chce się pić. Regularnie proponuj mu wodę w kolorowym, ciekawym kubku niekapku, by jego organizm się nie odwodnił.', title_pt = 'Torne divertido beber água. 💧', body_pt = 'As crianças ativas ficam com sede depressa. Ofereça-lhe água com regularidade num copo com bico colorido e apelativo, para que o corpo não fique desidratado.', title_sv = 'Gör vattendrickandet roligt. 💧', body_sv = 'Aktiva barn blir snabbt törstiga. Erbjud vatten regelbundet i en färgglad och rolig pipmugg så att kroppen inte blir uttorkad.', title_vi = 'Biến việc uống nước thành niềm vui. 💧', body_vi = 'Trẻ hiếu động rất nhanh khát. Hãy thường xuyên cho bé uống nước bằng một chiếc bình tập uống nhiều màu sắc, thú vị để cơ thể không bị thiếu nước.', title_zh = '让喝水变有趣 💧', body_zh = '活泼的孩子很容易口渴。用一个彩色又有趣的水杯经常给他喝水，别让身体缺水。' WHERE id = 'cbf9b73e-6e0b-4cbc-8731-ad9674e6dca3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Órdenes de dos pasos 🧠', body_es = '«Coge el juguete y mételo en la caja.» Que cumpla estas tareas más complejas demuestra que su comprensión está muy avanzada.', title_fr = 'Les consignes en deux étapes. 🧠', body_fr = '« Prends le jouet et mets-le dans la boîte. » Qu''il réussisse ces consignes complexes montre une excellente compréhension.', title_hi = 'दो चरणों वाले निर्देश। 🧠', body_hi = '''खिलौना उठाओ और डिब्बे में रखो।'' ऐसे मुश्किल काम कर पाना दिखाता है कि उसकी समझने की क्षमता बहुत अच्छी है।', title_id = 'Perintah dua langkah. 🧠', body_id = '"Ambil mainannya dan masukkan ke kotak." Kemampuannya menjalankan tugas yang rumit ini menunjukkan daya tangkapnya yang tinggi.', title_ja = '2つのステップのお願い 🧠', body_ja = '「おもちゃを取って、箱に入れて」。こうした少し複雑なお願いができるのは、理解する力が高い証拠です。', title_ko = '두 단계 지시. 🧠', body_ko = '"장난감 들어서 상자에 넣어." 이런 복잡한 지시를 해낸다는 건 이해력이 뛰어나다는 뜻이에요.', title_nl = 'Opdrachten met twee stappen. 🧠', body_nl = 'Pak het speeltje en leg het in de doos. Dat hij zulke lastige opdrachten uitvoert, laat zien dat hij veel begrijpt.', title_pl = 'Polecenia dwuetapowe. 🧠', body_pl = '„Weź zabawkę i włóż ją do pudełka.” To, że wykonuje takie złożone zadania, pokazuje, jak dobrze rozumie.', title_pt = 'Ordens com dois passos. 🧠', body_pt = '"Pega no brinquedo e põe-no na caixa." Cumprir estas tarefas mais complexas mostra que tem uma grande capacidade de compreensão.', title_sv = 'Instruktioner i två steg. 🧠', body_sv = '”Ta leksaken och lägg den i lådan.” Att barnet klarar sådana sammansatta uppgifter visar att förståelsen är hög.', title_vi = 'Yêu cầu hai bước. 🧠', body_vi = '"Nhặt đồ chơi lên và cất vào hộp." Bé làm được những yêu cầu phức tạp này cho thấy khả năng tiếp thu rất tốt.', title_zh = '两步指令 🧠', body_zh = '“拿起玩具放进盒子里。”能完成这样复杂的任务，说明他的理解能力很强。' WHERE id = '2f67b26a-192a-4bd5-87f9-5f376ff164e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Baila a su propio ritmo 🎶', body_es = 'Ya no solo se balancea: da palmas o da vueltas siguiendo el ritmo de la música.', title_fr = 'Il danse à son propre rythme. 🎶', body_fr = 'Il ne se contente plus de se balancer, il tape des mains ou tourne sur lui-même au rythme de la musique.', title_hi = 'संगीत पर अपनी लय में नाचता है। 🎶', body_hi = 'अब वह सिर्फ़ झूमता नहीं, संगीत की ताल पर ताली बजाता है या घूमता है।', title_id = 'Berjoget mengikuti iramanya sendiri. 🎶', body_id = 'Kini ia tidak hanya bergoyang, tapi bertepuk tangan atau berputar mengikuti tempo musik.', title_ja = '音楽に合わせて自分のリズムで踊る 🎶', body_ja = 'もう体をゆらすだけでなく、音楽のテンポに合わせて手をたたいたり、くるくる回ったりしています。', title_ko = '자기만의 리듬으로 춤춰요. 🎶', body_ko = '이제 몸을 흔드는 것만이 아니라 음악 박자에 맞춰 손뼉을 치거나 빙글빙글 돌아요.', title_nl = 'Danst op zijn eigen ritme. 🎶', body_nl = 'Je kindje wiegt niet meer alleen heen en weer, hij klapt in zijn handjes of draait rondjes op het tempo van de muziek.', title_pl = 'Tańczy do muzyki w swoim rytmie. 🎶', body_pl = 'Już nie tylko się kołysze, ale klaszcze lub kręci się w rytm muzyki.', title_pt = 'Dança à música ao seu próprio ritmo. 🎶', body_pt = 'Já não se limita a balançar: bate palmas ou dá voltas ao ritmo da música.', title_sv = 'Dansar i sin egen rytm. 🎶', body_sv = 'Barnet gungar inte bara längre, utan klappar händerna eller snurrar i takt med musiken.', title_vi = 'Bé nhảy theo nhạc với nhịp điệu riêng. 🎶', body_vi = 'Bé không chỉ lắc lư mà còn vỗ tay hoặc xoay vòng theo nhịp nhạc.', title_zh = '跟着自己的节奏跳舞 🎶', body_zh = '他已经不只是摇来摇去，还会跟着音乐的节拍拍手或转圈了。' WHERE id = 'bf0e882a-2f6d-4439-b170-c9adaeed59cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de la noche es mágico 📖', body_es = 'Deja que cuente el cuento a su manera mirando los dibujos. Es la base del futuro hábito de lectura.', title_fr = 'L''histoire du soir est magique. 📖', body_fr = 'Laissez-le raconter l''histoire à sa façon en regardant les images. C''est la base de son futur goût pour la lecture.', title_hi = 'शाम की कहानी जादुई होती है। 📖', body_hi = 'तस्वीरें देखकर उसे अपनी भाषा में कहानी सुनाने दीजिए। यह आगे किताबें पढ़ने की आदत की नींव है।', title_id = 'Dongeng malam itu ajaib. 📖', body_id = 'Biarkan ia menceritakan dongeng dengan bahasanya sendiri sambil melihat gambar. Ini fondasi kebiasaan membaca di masa depan.', title_ja = '寝る前のお話は魔法の時間 📖', body_ja = '絵を見ながら、自分の言葉でお話をさせてあげましょう。これが将来の読書習慣の土台になります。', title_ko = '잠자리 동화는 마법이에요. 📖', body_ko = '그림을 보며 자기만의 말로 이야기를 들려주게 해 주세요. 앞으로 책 읽는 습관의 바탕이 돼요.', title_nl = 'Een verhaaltje voor het slapen is magisch. 📖', body_nl = 'Laat je kindje het verhaal in zijn eigen taaltje vertellen terwijl hij naar de plaatjes kijkt. Dat is de basis voor later graag lezen.', title_pl = 'Wieczorna bajka jest magiczna. 📖', body_pl = 'Pozwól mu opowiadać bajkę po swojemu, patrząc na obrazki. To fundament przyszłego nawyku czytania.', title_pt = 'A história da noite é mágica. 📖', body_pt = 'Deixe-o contar a história à sua maneira, a olhar para as imagens. É a base do hábito de leitura no futuro.', title_sv = 'Kvällssagan är magisk. 📖', body_sv = 'Låt barnet berätta sagan på sitt eget språk genom att titta på bilderna. Det lägger grunden för en framtida läsvana.', title_vi = 'Truyện kể buổi tối thật kỳ diệu. 📖', body_vi = 'Hãy để bé nhìn tranh và kể chuyện bằng ngôn ngữ của mình. Đây là nền tảng cho thói quen đọc sách sau này.', title_zh = '睡前故事有魔力 📖', body_zh = '让他看着图片，用自己的语言讲故事吧。这是将来养成读书习惯的基础。' WHERE id = 'c522fcf6-60fc-463a-b943-7933f5ac5c70' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Fiesta de aniversario! 🎈', body_es = 'Celebra este día con una pequeña tarta o con su fruta favorita. Ver lo rápido que crece es tu mayor recompensa.', title_fr = 'Petite fête d''anniversaire ! 🎈', body_fr = 'Fêtez ce jour avec un petit gâteau ou son fruit préféré. Le voir grandir si vite est votre plus belle récompense.', title_hi = 'सालगिरह का जश्न! 🎈', body_hi = 'छोटे से केक या उसके पसंदीदा फल से इस दिन को मनाइए। उसे इतनी तेज़ी से बढ़ते देखना ही आपका सबसे बड़ा इनाम है।', title_id = 'Pesta perayaan! 🎈', body_id = 'Rayakan hari ini dengan kue kecil atau buah favoritnya. Melihat betapa cepat ia tumbuh adalah hadiah terbesar Anda.', title_ja = '記念日のお祝い！🎈', body_ja = '小さなケーキや大好きな果物で、この日をお祝いしましょう。ぐんぐん成長する姿を見られることが、あなたへの最高のごほうびです。', title_ko = '기념일 파티! 🎈', body_ko = '작은 케이크나 좋아하는 과일로 오늘을 축하해 보세요. 아이가 이렇게 빨리 자라는 걸 보는 게 엄마에게 가장 큰 상이에요.', title_nl = 'Jubileumfeest! 🎈', body_nl = 'Vier deze dag met een taartje of met zijn lievelingsfruit. Zien hoe snel hij groeit, is je grootste beloning.', title_pl = 'Świętujemy jubileusz! 🎈', body_pl = 'Uczcijcie ten dzień małym tortem lub jego ulubionym owocem. Widok tego, jak szybko rośnie, to twoja największa nagroda.', title_pt = 'Festa de aniversário! 🎈', body_pt = 'Celebre este dia com um pequeno bolo ou com a fruta de que ele mais gosta. Ver como cresce tão depressa é a sua maior recompensa.', title_sv = 'Jubileumsfest! 🎈', body_sv = 'Fira dagen med en liten tårta eller barnets favoritfrukt. Att se hur snabbt barnet växer är din största belöning.', title_vi = 'Tiệc mừng cột mốc! 🎈', body_vi = 'Hãy ăn mừng ngày này bằng một chiếc bánh nhỏ hay loại trái cây bé thích. Được thấy bé lớn nhanh thế nào là phần thưởng lớn nhất của mẹ.', title_zh = '纪念日派对！🎈', body_zh = '用一个小蛋糕或他最爱的水果庆祝这一天吧。看着他长得这么快，就是你最大的奖励。' WHERE id = '19e05272-ac3b-430f-bbad-b5c770118fd3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Date las gracias ✨', body_es = 'Date las gracias por la entrega, el amor y la paciencia de estos 500 días. Ahora duerme tranquila: ¡mañana empieza una nueva etapa!', title_fr = 'Remerciez-vous. ✨', body_fr = 'Remerciez-vous pour le dévouement, l''amour et la patience dont vous avez fait preuve pendant 500 jours. Maintenant, dormez bien, une nouvelle période commence demain !', title_hi = 'खुद को धन्यवाद दीजिए। ✨', body_hi = '500 दिनों में दिखाए समर्पण, प्यार और धैर्य के लिए खुद को धन्यवाद दीजिए। अब चैन से सोइए, कल एक नया दौर शुरू होगा!', title_id = 'Berterima kasihlah pada diri sendiri. ✨', body_id = 'Berterima kasihlah pada diri sendiri atas pengorbanan, cinta, dan kesabaran selama 500 hari ini. Sekarang tidurlah dengan nyenyak, besok babak baru dimulai!', title_ja = '自分にありがとうを ✨', body_ja = '500日間の献身、愛情、忍耐に、自分で「ありがとう」を伝えましょう。今夜はゆっくり眠ってください。明日から新しい時期が始まります！', title_ko = '스스로에게 고마워하세요. ✨', body_ko = '500일 동안 보여 준 헌신과 사랑, 인내에 스스로 고마워하세요. 이제 편히 주무세요. 내일부터 새로운 시기가 시작돼요!', title_nl = 'Bedank jezelf. ✨', body_nl = 'Bedank jezelf voor de toewijding, liefde en het geduld van de afgelopen 500 dagen. Slaap nu lekker, morgen begint een nieuwe periode!', title_pl = 'Podziękuj sobie. ✨', body_pl = 'Podziękuj sobie za poświęcenie, miłość i cierpliwość przez te 500 dni. Teraz śpij spokojnie, jutro zaczyna się nowy etap!', title_pt = 'Agradeça a si própria. ✨', body_pt = 'Agradeça a si própria pela dedicação, pelo amor e pela paciência destes 500 dias. Agora durma descansada, amanhã começa uma nova fase!', title_sv = 'Tacka dig själv. ✨', body_sv = 'Tacka dig själv för uppoffringarna, kärleken och tålamodet du visat under 500 dagar. Sov gott nu, i morgon börjar en ny period!', title_vi = 'Hãy cảm ơn chính mình. ✨', body_vi = 'Hãy cảm ơn bản thân vì sự hy sinh, tình yêu và lòng kiên nhẫn suốt 500 ngày qua. Giờ hãy ngủ thật ngon, ngày mai một giai đoạn mới bắt đầu!', title_zh = '谢谢你自己 ✨', body_zh = '为这500天里你付出的奉献、爱与耐心，谢谢你自己。现在好好睡一觉，明天一个新的阶段就要开始了！' WHERE id = '52e84dda-8f2e-4dce-9b8e-b095190c1816' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Supera el límite de velocidad 🏃‍♂️', body_es = '¡Ya no camina, casi corre! Cada vez cuesta más alcanzarle. Registra este nuevo récord de velocidad en el Seguimiento del desarrollo y quita los obstáculos de casa.', title_fr = 'Excès de vitesse 🏃‍♂️', body_fr = 'Il ne marche plus, il court presque ! Le rattraper devient difficile. Notez ce nouveau record de vitesse dans le Suivi de développement et dégagez les obstacles de la maison.', title_hi = 'रफ़्तार की सीमा पार 🏃‍♂️', body_hi = 'अब वह चलता नहीं, लगभग दौड़ता है! उसके पीछे पहुँचना मुश्किल हो रहा है। ग्रोथ ट्रैकर में इस नए रफ़्तार रिकॉर्ड को दर्ज कीजिए और घर से रुकावटें हटा दीजिए।', title_id = 'Batas kecepatan terlampaui 🏃‍♂️', body_id = 'Kini ia tidak hanya berjalan, tapi hampir berlari! Makin sulit mengejarnya. Catat rekor kecepatan baru ini di Pelacak Perkembangan dan singkirkan rintangan di rumah.', title_ja = 'スピード違反！🏃‍♂️', body_ja = 'もう歩くというより、ほとんど走っています！追いかけるのも大変に。「発達トラッカー」にこの新しいスピード記録を残し、家の中の障害物を片付けましょう。', title_ko = '속도 제한 초과 🏃‍♂️', body_ko = '이제 걷는 게 아니라 거의 뛰어요! 따라잡기가 점점 힘들어지죠. 성장 기록에 이 새로운 속도 기록을 남기고 집 안의 장애물을 치워 주세요.', title_nl = 'Te hard gereden 🏃‍♂️', body_nl = 'Je kindje loopt niet meer, hij rent bijna! Hem bijhouden wordt lastig. Noteer dit nieuwe snelheidsrecord in de Groeitracker en ruim obstakels in huis op.', title_pl = 'Przekroczenie prędkości 🏃‍♂️', body_pl = 'Już nie chodzi, prawie biega! Coraz trudniej za nim nadążyć. Zapisz ten nowy rekord prędkości w Śledzeniu rozwoju i usuń przeszkody w domu.', title_pt = 'O limite de velocidade foi ultrapassado 🏃‍♂️', body_pt = 'Já não anda, quase corre! Acompanhá-lo é cada vez mais difícil. Registe este novo recorde de velocidade no Registo de Desenvolvimento e tire os obstáculos do caminho em casa.', title_sv = 'Hastighetsgränsen överskrids 🏃‍♂️', body_sv = 'Barnet går inte längre, det springer nästan! Det blir svårare att hinna ikapp. Anteckna det nya hastighetsrekordet i Utvecklingsspåraren och plocka bort hinder i hemmet.', title_vi = 'Vượt giới hạn tốc độ 🏃‍♂️', body_vi = 'Bé không chỉ đi mà gần như đang chạy! Đuổi theo bé ngày càng khó. Hãy ghi lại kỷ lục tốc độ mới này trong Theo dõi phát triển và dọn hết chướng ngại vật trong nhà.', title_zh = '超速啦 🏃‍♂️', body_zh = '他已经不是在走，简直是在跑了！追都追不上。在发育追踪里记下这个新的速度纪录，把家里的障碍物收拾好吧。' WHERE id = 'dcf8f474-5360-4c6f-ac54-ecde70444961' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo que tu cuerpo necesita 🥑', body_es = '¿Te duelen los brazos y la espalda? Ya pesa más. Elige en Recetas saludables una comida ligera rica en calcio y proteínas para cuidar tus músculos.', title_fr = 'Les besoins de votre corps 🥑', body_fr = 'Vous avez mal aux bras et au dos ? Il est devenu plus lourd. Soutenez vos muscles en choisissant dans les Recettes saines un déjeuner léger riche en calcium et en protéines.', title_hi = 'आपके शरीर की ज़रूरत 🥑', body_hi = 'बाँहों और कमर में दर्द है? वह अब भारी हो गया है। सेहतमंद रेसिपी से कैल्शियम और प्रोटीन से भरपूर हल्का लंच चुनकर अपनी मांसपेशियों को सहारा दीजिए।', title_id = 'Kebutuhan tubuh Anda 🥑', body_id = 'Lengan dan punggung Anda pegal? Ia sudah makin berat. Dukung otot Anda dengan memilih makan siang ringan kaya kalsium dan protein dari Resep Sehat.', title_ja = '体が必要としているもの 🥑', body_ja = '腕や腰が痛みますか？お子さんも重くなりましたね。「ヘルシーレシピ」からカルシウムとたんぱく質たっぷりの軽いランチを選んで、筋肉をいたわりましょう。', title_ko = '몸이 필요로 하는 것 🥑', body_ko = '팔과 허리가 아픈가요? 아이가 이제 꽤 무거워졌어요. 건강한 레시피에서 칼슘과 단백질이 풍부한 가벼운 점심을 골라 근육을 챙겨 주세요.', title_nl = 'Wat je lichaam nodig heeft 🥑', body_nl = 'Doen je armen en rug pijn? Je kindje is zwaarder geworden. Kies in Gezonde recepten een lichte lunch vol calcium en eiwit om je spieren te ondersteunen.', title_pl = 'Czego potrzebuje twoje ciało 🥑', body_pl = 'Bolą cię ręce i plecy? Maluch jest już cięższy. Wybierz ze zdrowych przepisów lekki obiad bogaty w wapń i białko i wspieraj swoje mięśnie.', title_pt = 'O que o seu corpo precisa 🥑', body_pt = 'Doem-lhe os braços e as costas? Ele já está mais pesado. Escolha nas Receitas Saudáveis um almoço leve, rico em cálcio e proteína, para apoiar os seus músculos.', title_sv = 'Kroppens behov 🥑', body_sv = 'Värker armarna och ryggen? Barnet har blivit tyngre. Stöd musklerna genom att välja en lätt lunch rik på kalcium och protein från Hälsosamma recept.', title_vi = 'Nhu cầu của cơ thể mẹ 🥑', body_vi = 'Tay và lưng mẹ đau nhức? Bé đã nặng hơn rồi. Hãy chọn một bữa trưa nhẹ giàu canxi và protein trong Công thức lành mạnh để hỗ trợ cơ bắp nhé.', title_zh = '身体的需要 🥑', body_zh = '手臂和腰在疼？宝宝已经变重了。从健康食谱里选一份富含钙和蛋白质的清淡午餐，给肌肉一些支持吧。' WHERE id = '19f5918f-33f2-423f-ba32-d0be2a6bca2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los juegos de imaginación 🧸', body_es = '¿Intenta dar de comer a su osito o dormirlo? ¡Su imaginación despierta! Observa con orgullo desde lejos estos maravillosos gestos de empatía.', title_fr = 'Les jeux d''imagination commencent 🧸', body_fr = 'Il essaie de donner à manger à son ours en peluche ou de l''endormir ? Son imagination s''éveille ! Observez fièrement, de loin, ces magnifiques gestes d''empathie.', title_hi = 'कल्पना वाले खेल शुरू 🧸', body_hi = 'अपने टेडी बेयर को खाना खिलाने या सुलाने की कोशिश करता है? उसकी कल्पना जाग रही है! सहानुभूति की इन शानदार कोशिशों को दूर से गर्व से देखिए।', title_id = 'Permainan imajinasi dimulai 🧸', body_id = 'Ia mencoba menyuapi boneka beruangnya atau menidurkannya? Imajinasinya mulai tumbuh! Saksikan dengan bangga usaha empati yang luar biasa ini.', title_ja = 'ごっこ遊びが始まる 🧸', body_ja = 'くまのぬいぐるみに食べさせたり、寝かしつけたりしようとしていますか？想像力が目覚めています！このすてきな思いやりの挑戦を、誇らしく見守りましょう。', title_ko = '상상 놀이가 시작돼요 🧸', body_ko = '곰 인형에게 밥을 먹이거나 재우려고 하나요? 상상력이 깨어나고 있어요! 이 멋진 공감의 시도를 옆에서 뿌듯하게 지켜봐 주세요.', title_nl = 'Het fantasiespel begint 🧸', body_nl = 'Probeert je kindje zijn knuffelbeer eten te geven of in slaap te brengen? Zijn fantasie ontwaakt! Kijk trots toe bij deze mooie pogingen tot empathie.', title_pl = 'Zaczynają się zabawy w udawanie 🧸', body_pl = 'Próbuje nakarmić misia albo go uśpić? Budzi się wyobraźnia! Z dumą obserwuj z boku te wspaniałe próby empatii.', title_pt = 'Começam os jogos de faz de conta 🧸', body_pt = 'Tenta dar de comer ao ursinho de peluche ou pô-lo a dormir? A imaginação está a despertar! Observe com orgulho, à distância, estas fantásticas tentativas de empatia.', title_sv = 'Låtsaslekarna börjar 🧸', body_sv = 'Försöker barnet mata nallen eller lägga den att sova? Fantasin vaknar! Följ dessa fantastiska försök till empati med stolthet på avstånd.', title_vi = 'Bắt đầu trò chơi tưởng tượng 🧸', body_vi = 'Bé cố cho gấu bông ăn hay ru gấu ngủ? Trí tưởng tượng đang thức giấc! Hãy tự hào dõi theo những nỗ lực đồng cảm tuyệt vời này từ xa.', title_zh = '想象游戏开始了 🧸', body_zh = '他在试着喂泰迪熊吃饭，或者哄它睡觉？想象力正在苏醒！远远地、骄傲地看着这些了不起的同理心尝试吧。' WHERE id = '3ddcf967-26bf-4c82-a9be-ef2d0c28d637' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora de jugar con papá 👨‍👧', body_es = '¿Estás al límite de tu paciencia? Esta noche, que papá se encargue de las volteretas en el suelo y las cosquillas.', title_fr = 'L''heure de jeu avec papa 👨‍👧', body_fr = 'Vous êtes à bout de patience ? Ce soir, laissez papa s''occuper des roulades par terre et des chatouilles.', title_hi = 'पापा का खेल का समय 👨‍👧', body_hi = 'धैर्य की आखिरी बूँद पर हैं? आज शाम ज़मीन पर लोटने और गुदगुदी वाले खेल पापा को संभालने दीजिए।', title_id = 'Waktu bermain ayah 👨‍👧', body_id = 'Kesabaran Anda tinggal setetes? Malam ini, biar ayah yang mengurus permainan guling-guling dan gelitik.', title_ja = 'パパの遊び時間 👨‍👧', body_ja = 'がまんの限界ですか？今夜は床でごろごろやくすぐりっこは、パパに任せましょう。', title_ko = '아빠의 놀이 시간 👨‍👧', body_ko = '인내심이 바닥나기 직전인가요? 오늘 저녁 바닥에서 뒹굴기와 간지럼 놀이는 아빠에게 맡기세요.', title_nl = 'Speeltijd met papa 👨‍👧', body_nl = 'Is je geduld bijna op? Laat papa vanavond over de vloer rollen en kietelspelletjes doen.', title_pl = 'Czas zabawy z tatą 👨‍👧', body_pl = 'Twoja cierpliwość jest na wyczerpaniu? Niech dziś wieczorem turlanie się po podłodze i łaskotki przejmie tata.', title_pt = 'A hora de brincar do pai 👨‍👧', body_pt = 'Está no limite da paciência? Esta noite, deixe as cambalhotas no chão e as cócegas por conta do pai.', title_sv = 'Pappas lektid 👨‍👧', body_sv = 'Är du på din sista droppe tålamod? Låt pappa sköta rullandet på golvet och kittellekarna i kväll.', title_vi = 'Giờ chơi của bố 👨‍👧', body_vi = 'Mẹ đã cạn giọt kiên nhẫn cuối cùng? Tối nay hãy để bố lo những trò lăn lộn dưới sàn và cù lét.', title_zh = '爸爸的游戏时间 👨‍👧', body_zh = '耐心快到极限了？今晚就把在地上打滚、挠痒痒的游戏交给爸爸吧。' WHERE id = 'c178ee13-258d-408c-8a70-3133436f4f3b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exploración en la cocina 🍎', body_es = 'Deja que te ayude a lavar la fruta. El sonido del agua y los colores de la fruta mantendrán viva su curiosidad.', title_fr = 'Explorations en cuisine. 🍎', body_fr = 'Laissez-le vous aider à laver les fruits. Le bruit de l''eau et les couleurs des fruits garderont sa curiosité en éveil.', title_hi = 'रसोई में खोज। 🍎', body_hi = 'फल धोते समय उसे भी मदद करने दीजिए। पानी की आवाज़ और फलों के रंग उसकी दिलचस्पी बनाए रखेंगे।', title_id = 'Menjelajah dapur. 🍎', body_id = 'Biarkan ia ikut membantu saat Anda mencuci buah. Suara air dan warna buah akan membuatnya tetap tertarik.', title_ja = 'キッチンで探検 🍎', body_ja = '果物を洗うときは、お子さんにも手伝ってもらいましょう。水の音と果物の色が、好奇心をかきたてます。', title_ko = '부엌 탐험. 🍎', body_ko = '과일을 씻을 때 아이도 돕게 해 주세요. 물소리와 과일의 색깔이 호기심을 계속 살아 있게 할 거예요.', title_nl = 'Ontdekken in de keuken. 🍎', body_nl = 'Laat je kindje helpen als je fruit wast. Het geluid van het water en de kleuren van het fruit houden zijn nieuwsgierigheid levend.', title_pl = 'Odkrycia w kuchni. 🍎', body_pl = 'Pozwól mu pomagać przy myciu owoców. Szum wody i kolory owoców podtrzymają jego ciekawość.', title_pt = 'Exploração na cozinha. 🍎', body_pt = 'Quando lavar a fruta, deixe que ele também ajude. O som da água e as cores da fruta vão manter viva a curiosidade dele.', title_sv = 'Upptäcktsfärd i köket. 🍎', body_sv = 'Låt barnet hjälpa till när du sköljer frukten. Vattnets ljud och fruktens färger håller nyfikenheten vid liv.', title_vi = 'Khám phá trong bếp. 🍎', body_vi = 'Khi rửa trái cây, hãy để bé phụ một tay. Tiếng nước và màu sắc của trái cây sẽ giữ cho bé luôn hứng thú.', title_zh = '厨房探索 🍎', body_zh = '洗水果时让他也来帮忙吧。水声和水果的颜色会让他一直保持好奇。' WHERE id = '05b16636-3744-4ea1-b6f2-f3824e51cd2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos de frase 🗣', body_es = '️ ¿Intenta unir dos palabras, como «mamá, dame» o «papá, mira»? ¡Es un salto enorme en el desarrollo del habla!', title_fr = 'Premiers essais de phrases. 🗣', body_fr = '️ Il essaie d''associer deux mots, comme « Maman, donne » ou « Papa, regarde » ? C''est un formidable bond dans le développement de son langage !', title_hi = 'शब्दों से वाक्य बनाने की कोशिश। 🗣', body_hi = '️ ''मा-मा, दो'' या ''पा-पा, देखो'' जैसे दो शब्द जोड़ने की कोशिश करता है? यह बोली के विकास में शानदार छलांग है!', title_id = 'Mencoba merangkai kalimat. 🗣', body_id = '️ Ia mencoba menggabungkan dua kata seperti "Mama, kasih" atau "Papa, lihat"? Ini lompatan luar biasa dalam perkembangan bicaranya!', title_ja = '2語文に挑戦 🗣', body_ja = '️「ママ、ちょうだい」「パパ、見て」のように、2つの言葉をつなげようとしていますか？言葉の発達のすばらしい飛躍です！', title_ko = '단어로 문장 만들기 도전. 🗣', body_ko = '️"엄마, 줘"나 "아빠, 봐"처럼 두 단어를 이어 말하려 하나요? 말하기 발달에서 정말 멋진 도약이에요!', title_nl = 'Eerste zinnetjes proberen. 🗣', body_nl = '️ Probeert je kindje twee woorden te combineren, zoals mama, geef of papa, kijk? Een geweldige sprong in zijn spraakontwikkeling!', title_pl = 'Próby budowania zdań. 🗣', body_pl = '️ Próbuje łączyć dwa słowa, np. „mama, daj” czy „tata, patrz”? To wspaniały skok w rozwoju mowy!', title_pt = 'Tentativas de frases. 🗣', body_pt = '️ Tenta juntar duas palavras, como "Mamã, dá" ou "Papá, olha"? É um salto fantástico no desenvolvimento da fala!', title_sv = 'Försök till meningar. 🗣', body_sv = '️ Försöker barnet sätta ihop två ord, som ”Mamma, ge” eller ”Pappa, titta”? Det är ett fantastiskt språng i talutvecklingen!', title_vi = 'Bé thử ghép từ thành câu. 🗣', body_vi = '️ Bé cố ghép hai từ như "Mẹ, đưa" hay "Bố, nhìn"? Đây là một bước nhảy vọt tuyệt vời trong phát triển ngôn ngữ!', title_zh = '尝试说句子 🗣', body_zh = '️ 他在尝试把两个词连起来，比如“妈妈，给”或“爸爸，看”？这是语言发展的一次了不起的飞跃！' WHERE id = '3fd7287e-bc6f-49d6-a94b-292122e10559' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño artista en acción 🖍️', body_es = '¿Cuando le das un lápiz garabatea el papel (o la pared)? Su motricidad fina avanza muy rápido. Es hora de comprar pinturas lavables.', title_fr = 'Petit artiste au travail 🖍️', body_fr = 'Quand vous lui donnez un crayon, il gribouille le papier (ou le mur) ? Sa motricité fine se développe vite. C''est le moment d''acheter des crayons lavables.', title_hi = 'नन्हा कलाकार काम पर 🖍️', body_hi = 'हाथ में पेन देने पर कागज़ (या दीवार) पर लकीरें खींचता है? उसकी बारीक मोटर स्किल्स तेज़ी से विकसित हो रही हैं। धुलने वाले रंग खरीदने का समय है।', title_id = 'Seniman kecil sedang beraksi 🖍️', body_id = 'Saat diberi pensil, ia mencoret-coret kertas (atau dinding)? Motorik halusnya berkembang pesat. Saatnya membeli krayon yang bisa dicuci.', title_ja = '小さな画家が作業中 🖍️', body_ja = 'クレヨンを渡すと、紙に（または壁に）なぐり描きしますか？手先がぐんぐん器用になっています。洗って落とせるクレヨンを用意するタイミングです。', title_ko = '꼬마 화가 작업 중 🖍️', body_ko = '펜을 쥐여 주면 종이(또는 벽)에 끄적이나요? 소근육이 빠르게 발달하고 있어요. 물로 지워지는 크레용을 살 때예요.', title_nl = 'Een kleine kunstenaar aan het werk 🖍️', body_nl = 'Krast je kindje op papier (of op de muur) als je hem een potlood geeft? Zijn fijne motoriek ontwikkelt zich snel. Tijd voor afwasbare verf.', title_pl = 'Mały artysta przy pracy 🖍️', body_pl = 'Gdy dasz mu kredkę, bazgrze po kartce (albo po ścianie)? Jego motoryka mała szybko się rozwija. Czas kupić zmywalne kredki.', title_pt = 'Pequeno artista em ação 🖍️', body_pt = 'Quando lhe dá um lápis, rabisca o papel (ou a parede)? A motricidade fina está a desenvolver-se depressa. É altura de comprar lápis laváveis.', title_sv = 'Liten konstnär i arbete 🖍️', body_sv = 'Klottrar barnet på papperet (eller väggen) när du ger det en penna? Finmotoriken utvecklas snabbt. Det är dags att köpa tvättbara färger.', title_vi = 'Họa sĩ nhí đang làm việc 🖍️', body_vi = 'Mẹ đưa bút là bé vẽ nguệch ngoạc lên giấy (hoặc lên tường)? Vận động tinh đang phát triển nhanh chóng. Đã đến lúc mua bút màu có thể giặt sạch rồi.', title_zh = '小画家上岗啦 🖍️', body_zh = '给他一支笔，他就在纸上（或墙上）涂涂画画？精细动作发展得很快。是时候买些可水洗的颜料了。' WHERE id = '9884e1c4-18cf-4fce-b89d-ae4f4603110b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del cuento con papá 👨‍🍼', body_es = 'Deja a papá los últimos juegos movidos de la tarde. Sus risas juntos serán el mejor fondo para tu descanso.', title_fr = 'L''heure du conte avec papa. 👨‍🍼', body_fr = 'Confiez à papa les derniers jeux énergiques de la soirée. Leurs rires partagés seront la plus belle musique de fond pour votre repos.', title_hi = 'पापा की कहानी का समय। 👨‍🍼', body_hi = 'शाम के आखिरी भाग-दौड़ वाले खेल पापा को सौंपिए। उनकी साथ की हँसी आपके आराम के लिए सबसे सुंदर बैकग्राउंड होगी।', title_id = 'Waktu dongeng bersama ayah. 👨‍🍼', body_id = 'Serahkan permainan aktif terakhir di malam hari kepada ayah. Tawa mereka bersama akan jadi latar istirahat terindah bagi Anda.', title_ja = 'パパのお話タイム 👨‍🍼', body_ja = '夜の最後の元気な遊びは、パパにお任せしましょう。ふたりの笑い声が、あなたにとって最高のくつろぎのBGMになります。', title_ko = '아빠의 이야기 시간. 👨‍🍼', body_ko = '저녁의 마지막 신나는 놀이는 아빠에게 맡기세요. 두 사람의 웃음소리가 엄마에게 가장 좋은 휴식의 배경음이 될 거예요.', title_nl = 'Verhaaltjestijd met papa. 👨‍🍼', body_nl = 'Laat de laatste drukke spelletjes van de avond aan papa over. Hun gelach samen is de mooiste achtergrond voor jouw rust.', title_pl = 'Czas bajek z tatą. 👨‍🍼', body_pl = 'Ostatnie energiczne zabawy wieczoru przekaż tacie. Ich wspólny śmiech będzie najpiękniejszym tłem do twojego odpoczynku.', title_pt = 'A hora das histórias do pai. 👨‍🍼', body_pt = 'Entregue ao pai as últimas brincadeiras agitadas da noite. As gargalhadas deles vão ser o fundo mais bonito para o seu descanso.', title_sv = 'Pappas sagostund. 👨‍🍼', body_sv = 'Låt pappa sköta kvällens sista energiska lekar. Deras gemensamma skratt blir den finaste bakgrunden till din vila.', title_vi = 'Giờ kể chuyện của bố. 👨‍🍼', body_vi = 'Hãy giao những trò chơi sôi động cuối ngày cho bố. Tiếng cười của hai bố con sẽ là bản nhạc nền thư giãn tuyệt vời nhất cho mẹ.', title_zh = '爸爸的故事时间 👨‍🍼', body_zh = '把晚上最后一轮闹腾的游戏交给爸爸吧。听着他们一起欢笑，就是你最好的休息背景音。' WHERE id = 'cbbf4112-6812-4999-b3bd-fe378d632205' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hace viento fuera o solo fresco? No te fíes de lo que ves por la ventana. Deja que Tiempo y ropa te diga en segundos la ropa exacta.', body_fr = 'Il y a du vent dehors, ou juste un peu de fraîcheur ? Ne vous fiez pas à un coup d''œil par la fenêtre. Laissez l''outil Météo et tenue vous indiquer la bonne tenue en quelques secondes.', body_hi = 'बाहर हवा चल रही है या बस ठंडक है? खिड़की से देखकर धोखा मत खाइए। मौसम और कपड़े टूल सेकंडों में सही कपड़े बता देगा।', body_id = 'Di luar berangin, atau hanya sejuk? Jangan tertipu dengan melihat dari jendela. Biarkan fitur Cuaca dan Pakaian memberi tahu pakaian yang tepat dalam hitungan detik.', body_ja = '外は風が強い？それとも少し涼しいだけ？窓から見ただけで判断しないで。「天気と服装」が、ぴったりのコーデを数秒で教えてくれます。', body_ko = '밖에 바람이 부는 걸까요, 그냥 선선한 걸까요? 창밖만 보고 착각하지 마세요. 날씨와 옷차림 도구가 정확한 옷차림을 몇 초 만에 알려 줄 거예요.', body_nl = 'Waait het buiten of is het gewoon fris? Laat je niet misleiden door uit het raam te kijken. De tool Weer en kleding vertelt je in een paar seconden de juiste outfit.', body_pl = 'Na dworze wieje czy jest tylko chłodno? Nie daj się zwieść widokowi z okna. Niech narzędzie Pogoda i ubiór w kilka sekund poda ci odpowiedni zestaw.', body_pt = 'Lá fora está vento ou só fresquinho? Não se engane a olhar pela janela. Deixe que o Tempo e Roupa lhe diga a combinação exata em segundos.', body_sv = 'Blåser det ute, eller är det bara svalt? Låt dig inte luras av en blick genom fönstret. Låt verktyget Väder och kläder berätta exakt rätt klädsel på några sekunder.', body_vi = 'Bên ngoài có gió hay chỉ hơi mát? Đừng nhìn qua cửa sổ mà đoán sai. Hãy để công cụ Thời tiết và trang phục cho mẹ biết bộ đồ phù hợp chỉ trong vài giây.', body_zh = '外面有风，还是只是有点凉？别只看窗外判断失误。让天气穿衣工具几秒钟内告诉你准确的搭配。' WHERE id = 'fcd25c40-af67-4335-a70a-9d6c3e016480' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comparte experiencias 💬', body_es = '¿No dejas de darle vueltas a «¿Mi hijo también es así?»? Entra en la Comunidad Anacan, lee historias de otras mamás de niños de 16 meses y respira hondo.', title_fr = 'Partagez vos expériences 💬', body_fr = 'La question « Mon enfant aussi fait ça ? » vous obsède ? Rejoignez la Communauté Anacan, lisez les histoires d''autres mamans d''enfants de 16 mois et respirez profondément.', title_hi = 'अनुभव बाँटिए 💬', body_hi = '''क्या मेरा बच्चा भी ऐसा है?'' यह सोच आपको खाए जा रही है? Anacan कम्युनिटी में आइए, 16 महीने के बच्चों की दूसरी माँओं की कहानियाँ पढ़िए और गहरी साँस लीजिए।', title_id = 'Bagikan pengalaman Anda 💬', body_id = 'Pikiran "Apa anakku juga begini?" terus menghantui Anda? Masuklah ke Komunitas Anacan, baca kisah ibu-ibu lain dengan anak 16 bulan, dan tarik napas dalam-dalam.', title_ja = '体験をシェアしよう 💬', body_ja = '「うちの子もこうなの？」と頭がいっぱいですか？Anacanコミュニティを開いて、1歳4か月の子をもつほかのママたちの体験を読み、深呼吸しましょう。', title_ko = '경험을 나눠요 💬', body_ko = '''우리 아이만 이런 걸까?'' 하는 생각이 머리를 떠나지 않나요? Anacan 커뮤니티에 들어가 다른 16개월 아이 엄마들의 이야기를 읽고 깊게 숨을 쉬어 보세요.', title_nl = 'Deel ervaringen 💬', body_nl = 'Blijf je piekeren: is mijn kind ook zo? Ga naar de Anacan Community, lees de verhalen van andere moeders van kindjes van 16 maanden en haal diep adem.', title_pl = 'Dziel się doświadczeniami 💬', body_pl = 'Myśl „Czy moje dziecko też tak ma?” nie daje ci spokoju? Wejdź do Społeczności Anacan, przeczytaj historie innych mam 16-miesięcznych dzieci i weź głęboki oddech.', title_pt = 'Partilhe experiências 💬', body_pt = 'O pensamento "O meu filho também é assim?" não lhe sai da cabeça? Entre na Comunidade Anacan, leia as histórias de outras mães de crianças de 16 meses e respire fundo.', title_sv = 'Dela erfarenheter 💬', body_sv = 'Äter tanken ”Är mitt barn också så här?” upp dig? Gå in i Anacans Community, läs berättelser från andra mammor med barn på 16 månader och andas djupt.', title_vi = 'Chia sẻ trải nghiệm 💬', body_vi = 'Câu hỏi "Con mình cũng thế này sao?" cứ ám ảnh mẹ? Hãy vào Cộng đồng Anacan, đọc câu chuyện của các mẹ có con 16 tháng khác và hít thở thật sâu.', title_zh = '分享经验 💬', body_zh = '“我的孩子也是这样吗？”这个念头让你停不下来？进入Anacan社区，读读其他16个月宝宝妈妈的故事，深呼吸一下吧。' WHERE id = '1cec3e77-df8d-4fe0-9a15-4d7f7ee66785' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un baño relajante 🛁', body_es = 'Jugar con agua templada antes de dormir se llevará toda la tensión del día. Añade un poco de aceite esencial al agua y crea un ambiente de calma.', title_fr = 'Un bain apaisant. 🛁', body_fr = 'Jouer dans l''eau tiède avant de dormir emportera toutes les tensions de la journée. Ajoutez un peu d''huile essentielle dans l''eau pour créer une ambiance sereine.', title_hi = 'सुकून देने वाला स्नान। 🛁', body_hi = 'सोने से पहले गुनगुने पानी से खेलना दिनभर का सारा तनाव दूर कर देगा। पानी में थोड़ा सा एसेंशियल ऑयल डालकर सुकून का माहौल बनाइए।', title_id = 'Mandi yang menenangkan. 🛁', body_id = 'Bermain air hangat sebelum tidur akan menghapus semua ketegangan hari ini. Tambahkan sedikit minyak esensial ke air untuk menciptakan ketenangan.', title_ja = '心落ち着くお風呂 🛁', body_ja = '寝る前のぬるめのお湯遊びが、一日の緊張をすっかり流してくれます。お湯にアロマオイルを少し加えて、穏やかな雰囲気をつくりましょう。', title_ko = '마음을 달래 주는 목욕. 🛁', body_ko = '잠들기 전 따뜻한 물놀이가 하루의 긴장을 모두 풀어 줄 거예요. 물에 에센셜 오일을 조금 더해 편안한 분위기를 만들어 보세요.', title_nl = 'Een rustgevend badje. 🛁', body_nl = 'Spelen met lauw water voor het slapengaan spoelt alle spanning van de dag weg. Doe een beetje etherische olie in het water en zorg voor rust.', title_pl = 'Kojąca kąpiel. 🛁', body_pl = 'Zabawa w ciepłej wodzie przed snem zabierze całe napięcie dnia. Dodaj do wody trochę olejku eterycznego i stwórz spokojną atmosferę.', title_pt = 'Um banho calmante. 🛁', body_pt = 'Brincar com água morna antes de dormir vai levar toda a tensão do dia. Junte à água um pouco de óleo essencial e crie um ambiente tranquilo.', title_sv = 'Lugnande bad. 🛁', body_sv = 'Att leka i ljummet vatten före sömnen tar bort all dagens spänning. Tillsätt lite eterisk olja i vattnet och skapa ro.', title_vi = 'Tắm thư giãn. 🛁', body_vi = 'Chơi với nước ấm trước khi ngủ sẽ cuốn đi mọi căng thẳng trong ngày. Hãy thêm vài giọt tinh dầu vào nước để tạo cảm giác bình yên.', title_zh = '舒缓的洗澡时间 🛁', body_zh = '睡前玩玩温水，能带走一天所有的紧张。在水里滴一点精油，营造宁静的氛围吧。' WHERE id = '61b42915-8f61-46a7-b887-07cc8998e71f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intenta subir solo las escaleras 🪜', body_es = 'Ya sube con más seguridad cogido de tu mano. No se lo impidas, así fortalece los músculos de las piernas; solo vela por su seguridad.', title_fr = 'Il essaie de monter l''escalier seul. 🪜', body_fr = 'En vous tenant la main, il monte déjà avec plus d''assurance. Ne l''en empêchez pas, cela renforce les muscles de ses jambes, veillez simplement à sa sécurité.', title_hi = 'अकेले सीढ़ियाँ चढ़ने की कोशिश। 🪜', body_hi = 'अब वह आपका हाथ पकड़कर ज़्यादा भरोसे से चढ़ता है। पैरों की मांसपेशियाँ मज़बूत करने के लिए उसे मत रोकिए, बस सुरक्षा का ध्यान रखिए।', title_id = 'Mencoba naik tangga sendiri. 🪜', body_id = 'Kini ia naik dengan lebih percaya diri sambil memegang tangan Anda. Jangan halangi ia menguatkan otot kakinya, cukup jaga keamanannya.', title_ja = 'ひとりで階段に挑戦 🪜', body_ja = 'あなたの手を握って、前より自信をもって上れるようになりました。脚の筋肉が強くなるよう止めずに、安全だけ見守りましょう。', title_ko = '혼자 계단 오르기 도전. 🪜', body_ko = '이제 엄마 손을 잡고 더 자신 있게 올라가요. 다리 근육이 튼튼해지도록 막지 말고, 안전만 지켜 주세요.', title_nl = 'Probeert alleen de trap op te gaan. 🪜', body_nl = 'Aan je hand klimt je kindje nu met meer zelfvertrouwen omhoog. Houd hem niet tegen, zo worden zijn beenspieren sterker, maar let goed op zijn veiligheid.', title_pl = 'Próby samodzielnego wchodzenia po schodach. 🪜', body_pl = 'Trzymając cię za rękę, wchodzi już pewniej. Nie przeszkadzaj mu wzmacniać mięśni nóg, tylko dbaj o bezpieczeństwo.', title_pt = 'Tentativas de subir as escadas sozinho. 🪜', body_pt = 'Agarrado à sua mão, já sobe com mais confiança. Não o impeça, para fortalecer os músculos das pernas, apenas garanta a segurança.', title_sv = 'Försöker gå i trappan själv. 🪜', body_sv = 'Barnet går nu säkrare uppför när det håller din hand. Hindra inte barnet från att stärka benmusklerna, se bara till att det är säkert.', title_vi = 'Bé thử tự leo cầu thang. 🪜', body_vi = 'Bé đã nắm tay mẹ leo lên tự tin hơn. Đừng ngăn bé, để cơ chân được rèn luyện, mẹ chỉ cần đảm bảo an toàn cho bé.', title_zh = '尝试自己爬楼梯 🪜', body_zh = '他牵着你的手，已经爬得更自信了。为了锻炼腿部肌肉，别拦着他，只要注意安全就好。' WHERE id = 'f5e358ba-f868-4a50-851c-6980fa2b0075' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'En el caos del día, ¿se ha acabado el champú o las toallitas? No lo guardes en la cabeza: apúntalo en la Lista de la compra y sincronízala con tu pareja.', body_fr = 'Dans le chaos du quotidien, plus de shampoing ou de lingettes ? Ne gardez pas tout en tête, notez-le dans la Liste de courses et synchronisez-la avec votre conjoint.', body_hi = 'रोज़ की अफ़रा-तफ़री में शैम्पू खत्म हुआ या वेट वाइप्स? दिमाग में मत रखिए, शॉपिंग लिस्ट में लिखिए और अपने साथी के साथ सिंक कीजिए।', body_id = 'Di tengah kekacauan sehari-hari, sampo atau tisu basah habis? Jangan disimpan di kepala, tulis di Daftar Belanja dan sinkronkan dengan pasangan Anda.', body_ja = '毎日のバタバタで、シャンプーやおしりふきが切れた？頭で覚えておかず、「買い物リスト」に書いてパートナーと共有しましょう。', body_ko = '정신없는 일상 속에 샴푸가 떨어졌나요, 물티슈가 떨어졌나요? 머릿속에 담아 두지 말고 쇼핑 목록에 적어 배우자와 공유하세요.', body_nl = 'Is de shampoo of zijn de vochtige doekjes op in de dagelijkse chaos? Onthoud het niet, zet het op het Boodschappenlijstje en synchroniseer met je partner.', body_pl = 'W codziennym chaosie skończył się szampon albo chusteczki nawilżane? Nie trzymaj tego w głowie, wpisz na Listę zakupów i zsynchronizuj z partnerem.', body_pt = 'No caos do dia a dia, acabou o champô ou os toalhetes húmidos? Não guarde isso na cabeça: escreva na Lista de Compras e sincronize com o seu companheiro.', body_sv = 'Har schampot eller våtservetterna tagit slut i vardagskaoset? Håll det inte i huvudet, skriv det i Inköpslistan och synka med din partner.', body_vi = 'Giữa bộn bề mỗi ngày, hết dầu gội hay khăn ướt rồi? Đừng cố nhớ trong đầu, hãy ghi vào Danh sách mua sắm và đồng bộ với bố.', body_zh = '日常一团乱，洗发水还是湿巾用完了？别记在脑子里，写进购物清单，和另一半同步吧。' WHERE id = 'bd0e8e10-27b9-43f5-b4c1-6f893a8d95e6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Haz preguntas como «¿Por qué se despierta más por la noche?» a nuestro asistente Anacan AI incluso de madrugada y recibe respuesta al momento.', body_fr = 'Posez vos questions, comme « Pourquoi les réveils nocturnes ont-ils augmenté ? », à notre assistant Anacan AI, même en pleine nuit, et obtenez une réponse immédiate.', body_hi = '''रात में जागना क्यों बढ़ गया?'' जैसे सवाल रात में भी हमारे Anacan AI असिस्टेंट से पूछिए और तुरंत जवाब पाइए।', body_id = 'Tanyakan pertanyaan seperti "Kenapa ia makin sering terbangun malam?" ke asisten Anacan AI kami dan dapatkan jawaban instan, bahkan di malam hari.', body_ja = '「どうして夜中に起きる回数が増えたの？」といった質問も、夜中でもAnacan AIアシスタントに聞けば、すぐに答えが返ってきます。', body_ko = '''왜 밤에 깨는 일이 늘었을까?'' 같은 질문은 늦은 밤에도 Anacan AI 도우미에게 물어 바로 답을 받아 보세요.', body_nl = 'Stel vragen als: waarom wordt mijn kind ''s nachts vaker wakker?, zelfs midden in de nacht aan onze assistent Anacan AI en krijg meteen antwoord.', body_pl = 'Pytania typu „Dlaczego nocnych pobudek jest więcej?” zadaj naszemu asystentowi Anacan AI, nawet w nocy, i od razu otrzymaj odpowiedź.', body_pt = 'Faça perguntas como "Porque aumentaram os despertares noturnos?" ao nosso assistente Anacan AI, mesmo de madrugada, e receba a resposta na hora.', body_sv = 'Ställ frågor som ”Varför har de nattliga uppvaknandena ökat?” till vår assistent Anacan AI även sent på natten och få svar direkt.', body_vi = 'Những câu hỏi như "Sao bé thức giấc ban đêm nhiều hơn?", ngay cả lúc nửa đêm mẹ cũng có thể hỏi trợ lý Anacan AI và nhận câu trả lời ngay.', body_zh = '像“为什么夜醒变多了？”这样的问题，哪怕深夜也可以问我们的Anacan AI助手，马上得到回答。' WHERE id = 'c131d78d-b239-4de3-9bc9-c0c8fe25a6f7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se tapa los ojos con las manos y juega al cucú? Ya entiende perfectamente que los objetos siguen existiendo aunque no los vea.', body_fr = 'Il se cache les yeux avec les mains pour jouer à coucou ? Il comprend de mieux en mieux que les objets continuent d''exister.', body_hi = 'हाथों से आँखें ढककर झाँकी-झाँकी खेलता है? चीज़ों के स्थायी होने की उसकी समझ एकदम पक्की हो रही है।', body_id = 'Ia menutup mata dengan tangan dan bermain cilukba? Pemahamannya bahwa benda tetap ada makin sempurna.', body_ja = '両手で目を隠して、いないいないばあをしていますか？物が見えなくてもそこにあることを、しっかり理解しています。', body_ko = '손으로 눈을 가리고 까꿍 놀이를 하나요? 물건이 사라지지 않는다는 이해가 완벽해지고 있어요.', body_nl = 'Bedekt je kindje zijn ogen met zijn handjes en speelt hij kiekeboe? Hij begrijpt steeds beter dat dingen blijven bestaan.', body_pl = 'Zasłania oczy rączkami i bawi się w „a kuku”? Coraz lepiej rozumie, że przedmioty istnieją, nawet gdy ich nie widać.', body_pt = 'Tapa os olhos com as mãos e brinca ao cucu? A compreensão de que os objetos continuam a existir está a ficar perfeita.', body_sv = 'Täcker barnet ögonen med händerna och leker tittut? Förståelsen för att föremål finns kvar blir fulländad.', body_vi = 'Bé lấy tay che mắt chơi ú òa? Khả năng hiểu rằng đồ vật vẫn tồn tại dù không nhìn thấy đang dần hoàn thiện.', body_zh = '用手捂住眼睛玩躲猫猫？他对“物体恒存”的理解越来越完善了。' WHERE id = 'c67019a7-8ef8-4eef-bcc7-41d6f859382f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después de un día difícil, sentaos frente a frente con tu pareja y desahogaos. Apoyaros mutuamente reparte a la mitad la carga física y emocional.', body_fr = 'Après une journée difficile, asseyez-vous face à votre conjoint et parlez de ce qui vous pèse. Se soutenir partage vraiment la charge physique et morale en deux.', body_hi = 'मुश्किल दिन के बाद अपने साथी के साथ आमने-सामने बैठकर दिल की बात कीजिए। एक-दूसरे का सहारा बनना शारीरिक और मानसिक बोझ को आधा कर देता है।', body_id = 'Setelah hari yang berat, duduklah berhadapan dengan pasangan dan saling bercerita. Saling mendukung membuat beban fisik dan emosional benar-benar terbagi dua.', body_ja = '大変な一日のあとは、パートナーと向かい合って座り、話をしましょう。支え合うことで、体と心の負担は半分になります。', body_ko = '힘든 하루를 보낸 뒤 배우자와 마주 앉아 이야기를 나눠 보세요. 서로를 응원하면 몸과 마음의 짐이 절반으로 줄어요.', body_nl = 'Ga na een zware dag tegenover je partner zitten en praat je hart uit. Elkaar steunen halveert de lichamelijke en emotionele last.', body_pl = 'Po trudnym dniu usiądźcie z partnerem naprzeciw siebie i porozmawiajcie. Wzajemne wsparcie dzieli fizyczny i emocjonalny ciężar na pół.', body_pt = 'Depois de um dia difícil, sente-se frente a frente com o seu companheiro e desabafem. Apoiarem-se um ao outro divide ao meio o peso físico e emocional.', body_sv = 'Sätt dig mittemot din partner efter en tuff dag och prata ut. Att stötta varandra delar den fysiska och känslomässiga bördan på hälften.', body_vi = 'Sau một ngày vất vả, hãy ngồi đối diện bố và tâm sự. Hỗ trợ lẫn nhau sẽ chia đôi gánh nặng cả về thể chất lẫn tinh thần.', body_zh = '辛苦的一天之后，和另一半面对面坐下聊聊心事。互相支持，能把身体和心理的重担减轻一半。' WHERE id = '45bc547e-6211-4178-aad6-4266015ca9cf' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Qué esperar del desarrollo entre los 16 y los 18 meses? En lugar de leer noticias alarmantes en internet, pide a Anacan AI un resumen experto y preciso.', body_fr = 'À quoi vous attendre dans le développement entre 16 et 18 mois ? Plutôt que de lire des histoires effrayantes sur Internet, demandez à Anacan AI un résumé précis d''expert.', body_hi = '16-18 महीने के विकास में क्या उम्मीद करें? इंटरनेट पर डरावनी खबरें पढ़ने के बजाय Anacan AI से विशेषज्ञ का सटीक सार माँगिए।', body_id = 'Apa yang perlu Anda harapkan dalam perkembangan usia 16-18 bulan? Daripada membaca berita menakutkan di internet, minta ringkasan ahli yang akurat dari Anacan AI.', body_ja = '1歳4-6か月の発達で何が起こるか気になりますか？ネットで怖い話を読むより、Anacan AIに正確な専門家のまとめを聞いてみましょう。', body_ko = '16-18개월 발달에서는 무엇을 기대해야 할까요? 인터넷에서 무서운 이야기를 읽는 대신 Anacan AI에게 정확한 전문가 요약을 요청하세요.', body_nl = 'Wat kun je verwachten in de ontwikkeling van 16-18 maanden? Lees geen enge berichten op internet, maar vraag Anacan AI om een nauwkeurige samenvatting van een deskundige.', body_pl = 'Czego się spodziewać w rozwoju między 16. a 18. miesiącem? Zamiast czytać straszne wiadomości w internecie, poproś Anacan AI o rzetelne podsumowanie eksperta.', body_pt = 'O que esperar no desenvolvimento entre os 16 e os 18 meses? Em vez de ler notícias assustadoras na internet, peça ao Anacan AI um resumo preciso de especialista.', body_sv = 'Vad kan du vänta dig av utvecklingen vid 16-18 månader? I stället för att läsa skrämmande nyheter på nätet, be Anacan AI om en exakt sammanfattning från experter.', body_vi = 'Giai đoạn 16-18 tháng cần chờ đợi điều gì? Thay vì đọc những tin đáng sợ trên mạng, hãy nhờ Anacan AI tóm tắt chính xác theo ý kiến chuyên gia.', body_zh = '16-18个月的发育会有哪些变化？与其在网上看吓人的消息，不如请Anacan AI给你一份准确的专家总结。' WHERE id = '89373578-8a41-4cd9-bcef-3a5786b1f576' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por los libros 📖', body_es = '¿Pasa solo las páginas del libro y toca los dibujos con el dedo? El hábito de lectura empieza ahora. Poned nombre juntos a lo que sale en los dibujos.', title_fr = 'L''amour des livres 📖', body_fr = 'Il tourne librement les pages d''un livre et touche les images du doigt ? Le goût de la lecture naît dès maintenant. Nommez ensemble ce qu''il y a sur les images.', title_hi = 'किताबों से प्यार 📖', body_hi = 'किताब के पन्ने खुद पलटता है और तस्वीरों को उँगली से छूता है? पढ़ने की आदत अभी से बन रही है। उसके साथ तस्वीरों में दिख रही चीज़ों के नाम बोलिए।', title_id = 'Cinta buku 📖', body_id = 'Ia bebas membalik halaman buku dan menyentuh gambar dengan jarinya? Kebiasaan membaca terbentuk sejak sekarang. Sebutkan bersama nama benda-benda di gambar.', title_ja = '絵本が大好き 📖', body_ja = '本のページを自由にめくって、指で絵をさわっていますか？読書の習慣は今から始まります。一緒に絵の中のものに名前をつけましょう。', title_ko = '책 사랑 📖', body_ko = '책장을 자유롭게 넘기며 그림을 손가락으로 만지나요? 책 읽는 습관이 벌써 자라고 있어요. 함께 그림 속 사물의 이름을 말해 보세요.', title_nl = 'Liefde voor boeken 📖', body_nl = 'Slaat je kindje zelf de bladzijden om en raakt hij de plaatjes aan met zijn vingertje? De leesgewoonte ontstaat nu al. Benoem samen wat er op de plaatjes staat.', title_pl = 'Miłość do książek 📖', body_pl = 'Swobodnie przewraca kartki i dotyka obrazków paluszkiem? Nawyk czytania rodzi się już teraz. Nazywajcie razem to, co jest na obrazkach.', title_pt = 'O amor pelos livros 📖', body_pt = 'Vira as páginas do livro sozinho e toca nas imagens com o dedo? O hábito de leitura começa já agora. Digam juntos o nome do que aparece nas imagens.', title_sv = 'Kärlek till böcker 📖', body_sv = 'Vänder barnet bokens sidor fritt och rör vid bilderna med fingret? Läsvanan skapas redan nu. Sätt namn på det som finns på bilderna tillsammans.', title_vi = 'Tình yêu sách 📖', body_vi = 'Bé tự lật trang sách và lấy ngón tay chạm vào tranh? Thói quen đọc sách đang hình thành từ bây giờ. Hãy cùng bé gọi tên những gì có trong tranh.', title_zh = '爱上书本 📖', body_zh = '他能自如地翻书页，还用手指摸图片？读书习惯从现在就开始养成。和他一起说出图里东西的名字吧。' WHERE id = 'daea63ca-66de-40da-bafb-c740af314d06' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se ha despertado gritando de golpe?', body_es = 'Puede ser un terror nocturno. Escucha su llanto con el Análisis del llanto y averigua si el problema es físico o psicológico.', title_fr = 'Il s''est réveillé soudain en hurlant ?', body_fr = 'C''est peut-être une terreur nocturne. Faites écouter ses pleurs à l''Analyse des pleurs pour savoir si le problème est physique ou psychologique.', title_hi = 'अचानक चीखकर जागा?', body_hi = 'यह नाइट टेरर हो सकता है। क्राइंग एनालिसिस से उसकी आवाज़ सुनवाइए और जानिए कि परेशानी शारीरिक है या मनोवैज्ञानिक।', title_id = 'Tiba-tiba terbangun sambil berteriak?', body_id = 'Mungkin itu teror tidur. Perdengarkan suaranya ke Analisis Tangisan dan cari tahu apakah masalahnya fisik atau psikologis.', title_ja = '突然叫ぶように起きた？', body_ja = '夜驚症かもしれません。「泣き声分析」で泣き声を聞かせて、原因が体のものか心のものかを探りましょう。', title_ko = '갑자기 소리 지르며 깼나요?', body_ko = '야경증일 수 있어요. 울음 분석으로 소리를 들려주어 신체적인 문제인지 심리적인 문제인지 알아보세요.', title_nl = 'Plots krijsend wakker geworden?', body_nl = 'Het kan een nachtmerrie zijn. Laat Huilanalyse naar het huilen luisteren en ontdek of het probleem lichamelijk of psychisch is.', title_pl = 'Nagle obudził się z krzykiem?', body_pl = 'To może być lęk nocny. Pozwól Analizie płaczu posłuchać dźwięku i ustal, czy problem jest fizyczny, czy psychiczny.', title_pt = 'Acordou de repente aos gritos?', body_pt = 'Pode ser um terror noturno. Deixe a Análise do Choro ouvir o choro e descubra se o problema é físico ou psicológico.', title_sv = 'Har barnet plötsligt vaknat och skrikit?', body_sv = 'Det kan vara nattskräck. Låt Gråtanalys lyssna på ljudet och ta reda på om problemet är fysiskt eller psykiskt.', title_vi = 'Bé bất ngờ thức dậy la hét?', body_vi = 'Có thể đó là cơn hoảng sợ khi ngủ. Hãy cho Phân tích tiếng khóc nghe để biết vấn đề là thể chất hay tâm lý.', title_zh = '突然尖叫着醒来？', body_zh = '可能是夜惊。用哭声分析听一听，弄清楚问题是身体上的还是心理上的。' WHERE id = '1ba2f4ba-35bf-41b8-9b1d-a9de5072ed4d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Sin fregar el suelo? Que se quede así. Una casa sucia se arregla, pero una mamá agotada tarda mucho en recuperarse. Túmbate en el sofá y escucha la calma.', body_fr = 'Le sol n''a pas été lavé ? Tant pis. Une maison sale se range, mais une maman épuisée met longtemps à récupérer. Allongez-vous sur le canapé et écoutez simplement le calme.', body_hi = 'फ़र्श पर पोंछा नहीं लगा? रहने दीजिए। गंदा घर ठीक हो जाता है, लेकिन थकी हुई माँ को सँभलने में लंबा समय लगता है। सोफ़े पर लेटिए और बस शांति को सुनिए।', body_id = 'Lantai belum dipel? Biarkan saja. Rumah yang kotor bisa dibereskan, tapi ibu yang kehabisan tenaga butuh waktu lama untuk pulih. Berbaringlah di sofa dan dengarkan saja ketenangannya.', body_ja = '床が拭けていない？そのままで大丈夫。散らかった家は片付きますが、疲れきったママの回復には時間がかかります。ソファに横になって、静けさに耳を傾けましょう。', body_ko = '바닥을 못 닦았나요? 그냥 두세요. 지저분한 집은 금방 정리되지만, 지친 엄마가 회복하는 데는 오래 걸려요. 소파에 누워 고요함에 귀 기울여 보세요.', body_nl = 'Is de vloer niet gedweild? Laat maar zo. Een vies huis is zo opgeruimd, maar een uitgeputte moeder heeft lang nodig om te herstellen. Ga op de bank liggen en luister gewoon naar de rust.', body_pl = 'Podłoga nieumyta? Niech tak zostanie. Brudny dom da się ogarnąć, ale wyczerpana mama długo wraca do sił. Połóż się na kanapie i po prostu wsłuchaj się w ciszę.', body_pt = 'O chão não foi limpo? Deixe ficar. Uma casa suja arruma-se, mas uma mãe esgotada demora muito a recuperar. Deite-se no sofá e escute simplesmente a tranquilidade.', body_sv = 'Är golvet inte torkat? Låt det vara. Ett smutsigt hem går att fixa, men det tar lång tid för en utmattad mamma att återhämta sig. Lägg dig på soffan och lyssna bara på lugnet.', body_vi = 'Sàn nhà chưa lau? Cứ để đó. Nhà bẩn thì dọn được, nhưng một người mẹ kiệt sức cần rất lâu để hồi phục. Hãy nằm xuống sofa và lắng nghe sự yên bình.', body_zh = '地还没拖？那就先放着。乱糟糟的家很快能收拾好，但累垮的妈妈要恢复却需要很久。在沙发上躺一躺，静静聆听这份安宁吧。' WHERE id = 'e0bbc5a2-5e4d-47c8-bbdb-cfdb203faf5c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de lógica 🧱', body_es = '¿Construye una torre apilando 3-4 cubos? ¡Registra este logro motor en el Seguimiento del desarrollo! Aplaude sus intentos de pequeño ingeniero.', title_fr = 'Jeux de logique 🧱', body_fr = 'Il empile 3-4 cubes pour construire une tour ? Notez cette victoire motrice dans le Suivi de développement ! Applaudissez ses petits essais d''ingénieur.', title_hi = 'तर्क वाले खेल 🧱', body_hi = '3-4 ब्लॉक एक के ऊपर एक रखकर मीनार बनाता है? ग्रोथ ट्रैकर में इस मोटर जीत को दर्ज कीजिए! उसकी छोटी इंजीनियरिंग कोशिशों पर ताली बजाइए।', title_id = 'Permainan logika 🧱', body_id = 'Ia menumpuk 3-4 balok untuk membangun menara? Catat kemenangan motorik ini di Pelacak Perkembangan! Beri tepuk tangan untuk usaha kecilnya sebagai insinyur.', title_ja = '考える力を育てる遊び 🧱', body_ja = '積み木を3-4個重ねてタワーをつくっていますか？「発達トラッカー」にこの運動の成果を記録しましょう！小さなエンジニアの挑戦に拍手を。', title_ko = '논리 놀이 🧱', body_ko = '블록 3-4개를 쌓아 탑을 만드나요? 성장 기록에 이 운동 발달의 승리를 남기세요! 꼬마 엔지니어의 도전에 박수를 보내 주세요.', title_nl = 'Denkspelletjes 🧱', body_nl = 'Zet je kindje 3-4 blokken op elkaar en bouwt hij een toren? Noteer deze motorische overwinning in de Groeitracker! Applaudisseer voor zijn kleine bouwpogingen.', title_pl = 'Zabawy logiczne 🧱', body_pl = 'Ustawia 3-4 kostki jedna na drugiej i buduje wieżę? Zapisz ten sukces motoryczny w Śledzeniu rozwoju! Nagradzaj brawami jego małe inżynierskie próby.', title_pt = 'Jogos de lógica 🧱', body_pt = 'Empilha 3-4 cubos e constrói uma torre? Registe esta vitória motora no Registo de Desenvolvimento! Aplauda estas pequenas tentativas de engenharia.', title_sv = 'Logiklekar 🧱', body_sv = 'Staplar barnet 3-4 klossar och bygger ett torn? Anteckna denna motoriska seger i Utvecklingsspåraren! Applådera de små ingenjörsförsöken.', title_vi = 'Trò chơi tư duy 🧱', body_vi = 'Bé chồng 3-4 khối lên nhau thành tòa tháp? Hãy ghi lại chiến thắng vận động này trong Theo dõi phát triển! Vỗ tay khen những nỗ lực "kỹ sư" nhỏ của bé nhé.', title_zh = '逻辑游戏 🧱', body_zh = '他能把3-4块积木摞成一座塔了？在发育追踪里记下这个动作上的胜利！为这位小工程师的尝试鼓鼓掌吧。' WHERE id = 'fba2093e-fbf1-4663-b05f-7071650fd43f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que dormirse sea más fácil 🌙', body_es = 'Baja al mínimo la luz de la habitación y háblale en susurros. Esto le indicará a su sistema nervioso que es hora de descansar.', title_fr = 'Pour un endormissement plus facile. 🌙', body_fr = 'Baissez la lumière au minimum et parlez doucement, en chuchotant. Cela indiquera à son système nerveux que c''est l''heure de se reposer.', title_hi = 'नींद में जाना आसान हो। 🌙', body_hi = 'कमरे की रोशनी कम से कम कीजिए और धीमे से फुसफुसाकर बात कीजिए। इससे उसके नर्वस सिस्टम को ''आराम का समय'' का संकेत मिलेगा।', title_id = 'Agar peralihan ke tidur lebih mudah. 🌙', body_id = 'Redupkan lampu kamar seminimal mungkin dan bicaralah pelan sambil berbisik. Ini memberi sinyal ke sistem sarafnya bahwa sekarang waktunya beristirahat.', title_ja = '眠りへの切りかえをスムーズに 🌙', body_ja = '部屋の照明をできるだけ暗くして、静かにささやき声で話しましょう。神経に「休む時間だよ」という合図を送ってくれます。', title_ko = '편안하게 잠으로. 🌙', body_ko = '방의 조명을 최소로 낮추고 조용히 속삭이듯 말해 주세요. 신경계에 ''이제 쉴 시간''이라는 신호를 보내 줄 거예요.', title_nl = 'Makkelijker in slaap vallen. 🌙', body_nl = 'Dim de lichten zo ver mogelijk en praat zachtjes fluisterend. Dat geeft zijn zenuwstelsel het signaal: nu is het tijd om te rusten.', title_pl = 'Niech zasypianie będzie łatwiejsze. 🌙', body_pl = 'Przygaś światło w pokoju do minimum i mów cicho, szeptem. To da jego układowi nerwowemu sygnał: „czas odpocząć”.', title_pt = 'Que adormecer seja mais fácil. 🌙', body_pt = 'Baixe ao mínimo a luz do quarto e fale baixinho, em sussurros. Isso vai dar ao sistema nervoso dele o sinal de que é hora de descansar.', title_sv = 'Låt insomnandet bli lättare. 🌙', body_sv = 'Dämpa ljuset i rummet till ett minimum och prata tyst och viskande. Det signalerar till nervsystemet att det är dags att vila.', title_vi = 'Để bé vào giấc dễ dàng hơn. 🌙', body_vi = 'Hãy giảm đèn trong phòng xuống thấp nhất và nói thì thầm. Điều này sẽ gửi đến hệ thần kinh của bé tín hiệu "đã đến giờ nghỉ ngơi".', title_zh = '让入睡更轻松 🌙', body_zh = '把房间灯光调到最暗，轻声细语地说话。这会向他的神经系统发出“该休息了”的信号。' WHERE id = '0fea9ae7-0132-47ff-9282-adcf39bd128b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño ayudante 🧺', body_es = '¿Cuando recoges los juguetes en la caja, él también trae uno y lo mete? Aplaude estas pequeñas ayudas y dale las gracias.', title_fr = 'Un petit serviable. 🧺', body_fr = 'Quand vous rangez les jouets dans la boîte, il en apporte un lui aussi ? Applaudissez absolument ces petits coups de main et remerciez-le.', title_hi = 'मदद करने वाला नन्हा। 🧺', body_hi = 'आप खिलौने डिब्बे में समेटती हैं तो वह भी एक लाकर रख देता है? इन छोटी मददों पर ज़रूर ताली बजाइए और उसे धन्यवाद कहिए।', title_id = 'Si kecil yang suka membantu. 🧺', body_id = 'Saat Anda ingin mengumpulkan mainan ke kotak, ia juga membawa satu dan memasukkannya? Pastikan memuji bantuan kecil ini dan berterima kasih padanya.', title_ja = 'お手伝い上手 🧺', body_ja = 'おもちゃを箱に片付けていると、お子さんもひとつ持ってきて入れてくれますか？この小さなお手伝いを必ず褒めて、「ありがとう」を伝えましょう。', title_ko = '도와주길 좋아하는 꼬마. 🧺', body_ko = '장난감을 상자에 정리하려 하면 아이도 하나를 가져와 넣나요? 이런 작은 도움에 꼭 박수 치며 고맙다고 말해 주세요.', title_nl = 'Behulpzaam kleintje. 🧺', body_nl = 'Brengt je kindje ook een speeltje als jij ze in de doos opruimt? Applaudisseer zeker voor deze kleine hulp en bedank hem.', title_pl = 'Pomocny maluch. 🧺', body_pl = 'Gdy zbierasz zabawki do pudełka, on też jakąś przynosi i wkłada? Koniecznie nagradzaj brawami te małe gesty pomocy i mu dziękuj.', title_pt = 'O pequeno prestável. 🧺', body_pt = 'Quando quer arrumar os brinquedos na caixa, ele também traz um e põe-no lá? Aplauda sem falta estas pequenas ajudas e agradeça-lhe.', title_sv = 'Hjälpsam liten. 🧺', body_sv = 'När du vill samla leksakerna i lådan, kommer barnet då också med en och lägger dit den? Applådera dessa små hjälpinsatser och tacka barnet.', title_vi = 'Em bé hay giúp đỡ. 🧺', body_vi = 'Khi mẹ gom đồ chơi vào hộp, bé cũng mang một món đến bỏ vào? Hãy vỗ tay khen và cảm ơn bé vì những sự giúp đỡ nhỏ này nhé.', title_zh = '热心的小家伙 🧺', body_zh = '你收拾玩具时，他也拿一个过来放进盒子？一定要为这些小小的帮忙鼓掌，并谢谢他。' WHERE id = 'eb955e5b-023a-4e67-ac53-d6ab712c507e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de los Cuentos inteligentes 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial protagonizada por tu peque: «El pequeño valiente que paseaba por el bosque mágico».', title_fr = 'La magie des Contes intelligents 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire unique dont votre enfant est le héros : « Le petit courageux qui se promenait dans la forêt magique ».', title_hi = 'स्मार्ट कहानी का जादू 🪄', body_hi = 'स्मार्ट कहानियों में ऐसी खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: ''जादुई जंगल में घूमने वाला बहादुर नन्हा''।', title_id = 'Keajaiban Dongeng Pintar 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa dengan si kecil sebagai pahlawannya: Si Kecil Pemberani yang Berkelana di Hutan Ajaib.', title_ja = '「スマートおはなし」の魔法 🪄', body_ja = '「スマートおはなし」で、お子さんが主人公の特別なお話「魔法の森を歩く勇敢なおちびさん」をつくりましょう。', title_ko = '스마트 동화의 마법 🪄', body_ko = '스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: 마법의 숲을 거니는 용감한 꼬마.', title_nl = 'De magie van een slim sprookje 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: Het dappere kleintje in het betoverde bos.', title_pl = 'Magia Mądrej bajki 🪄', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Odważny maluch w zaczarowanym lesie”.', title_pt = 'A magia das Histórias Inteligentes 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial em que o herói é o seu filho: "O pequeno corajoso que passeia na floresta mágica".', title_sv = 'Den smarta sagans magi 🪄', body_sv = 'Skapa en speciell berättelse i Smarta sagor där ditt barn är hjälten: Den modiga lilla som vandrar i den magiska skogen.', title_vi = 'Phép màu của Truyện cổ tích thông minh 🪄', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo một câu chuyện đặc biệt với nhân vật chính là chính con mình: "Em bé dũng cảm dạo chơi trong khu rừng kỳ diệu".', title_zh = '智能故事的魔力 🪄', body_zh = '在智能故事里创作一个以你的孩子为主角的专属故事：《走进魔法森林的勇敢小家伙》。' WHERE id = '49fd2511-4696-40ce-a9eb-8140a6570163' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tiempo de mamá 🎧', body_es = 'No corras a la cocina en cuanto se duerma. Ponte los auriculares, pon tu canción favorita y durante 15 minutos sé solo tú.', title_fr = 'Le moment à soi de maman 🎧', body_fr = 'Ne courez pas à la cuisine dès qu''il s''endort. Mettez vos écouteurs, lancez votre chanson préférée et soyez juste vous-même pendant 15 minutes.', title_hi = 'माँ का अपना समय 🎧', body_hi = 'बच्चे के सोते ही रसोई की ओर मत भागिए। हेडफ़ोन लगाइए, अपना पसंदीदा गाना चलाइए और 15 मिनट सिर्फ़ अपने लिए जीजिए।', title_id = 'Waktu pribadi Bunda 🎧', body_id = 'Jangan langsung lari ke dapur begitu ia tidur. Pasang headphone, putar lagu favorit Anda, dan jadilah diri Anda sendiri selama 15 menit.', title_ja = 'ママのひとり時間 🎧', body_ja = 'お子さんが寝たらすぐキッチンへ、はやめましょう。イヤホンをつけて好きな曲を流し、15分間は「自分」だけの時間に。', title_ko = '엄마만의 시간 🎧', body_ko = '아이가 잠들자마자 부엌으로 달려가지 마세요. 이어폰을 끼고 좋아하는 노래를 틀어 15분 동안은 오롯이 나로 있어 보세요.', title_nl = 'Mama''s eigen tijd 🎧', body_nl = 'Ren niet naar de keuken zodra je kindje slaapt. Zet je koptelefoon op, zet je favoriete liedje aan en wees 15 minuten alleen jij.', title_pl = 'Czas tylko dla mamy 🎧', body_pl = 'Gdy maluszek zaśnie, nie biegnij od razu do kuchni. Załóż słuchawki, włącz ulubioną piosenkę i przez 15 minut bądź po prostu sobą.', title_pt = 'O tempo só da mãe 🎧', body_pt = 'Não corra para a cozinha assim que ele adormecer. Ponha os auscultadores, ligue uma canção de que goste e, durante 15 minutos, seja só "você".', title_sv = 'Mammas egen tid 🎧', body_sv = 'Spring inte till köket så fort barnet somnat. Sätt på hörlurarna, spela en låt du gillar och var bara du i 15 minuter.', title_vi = 'Thời gian riêng của mẹ 🎧', body_vi = 'Đừng vội chạy vào bếp ngay khi bé ngủ. Hãy đeo tai nghe, bật bài hát yêu thích và là chính mình trong 15 phút.', title_zh = '妈妈的私人时间 🎧', body_zh = '宝宝一睡着，别急着冲进厨房。戴上耳机，放一首喜欢的歌，做15分钟只属于自己的你。' WHERE id = 'f03e45ee-5599-42df-9ad9-5c86e351f328' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Insiste en comer solo 🥄', body_es = 'Si te quita la cuchara de la mano, no se lo impidas. Aunque se manche, comer solo es la mayor prueba de su independencia.', title_fr = 'Il tient à manger seul. 🥄', body_fr = 'S''il vous prend la cuillère des mains, ne l''en empêchez pas. Même s''il se salit, manger seul est la plus belle preuve de son autonomie.', title_hi = 'खुद खाने की ज़िद करता है। 🥄', body_hi = 'अगर वह आपके हाथ से चम्मच लेता है, तो उसे मत रोकिए। भले कपड़े गंदे हों, खुद खाना उसकी आत्मनिर्भरता का सबसे बड़ा सबूत है।', title_id = 'Ngotot makan sendiri. 🥄', body_id = 'Kalau ia mengambil sendok dari tangan Anda, jangan dihalangi. Meski bajunya kotor, makan sendiri adalah bukti terbesar kemandiriannya.', title_ja = '自分で食べたい！🥄', body_ja = 'あなたの手からスプーンを取ろうとしたら、止めないで。服が汚れても、自分で食べることは自立の何よりの証です。', title_ko = '혼자 먹겠다고 고집해요. 🥄', body_ko = '엄마 손에서 숟가락을 가져가도 막지 마세요. 옷이 엉망이 되어도, 혼자 먹는 건 독립심의 가장 큰 증거예요.', title_nl = 'Wil per se zelf eten. 🥄', body_nl = 'Pakt je kindje de lepel uit je hand? Houd hem niet tegen. Ook al wordt hij vies, zelf eten is het grootste bewijs van zijn zelfstandigheid.', title_pl = 'Upiera się, by jeść sam. 🥄', body_pl = 'Jeśli zabiera ci łyżeczkę, nie przeszkadzaj mu. Nawet jeśli się ubrudzi, samodzielne jedzenie to największy dowód jego niezależności.', title_pt = 'Insiste em comer sozinho. 🥄', body_pt = 'Se lhe tira a colher da mão, não o impeça. Mesmo que se suje todo, comer sozinho é a maior prova da independência dele.', title_sv = 'Envis med att äta själv. 🥄', body_sv = 'Om barnet tar skeden ur din hand, hindra det inte. Även om det blir kladdigt är att äta själv det största beviset på självständighet.', title_vi = 'Bé nhất định đòi tự ăn. 🥄', body_vi = 'Nếu bé giành thìa từ tay mẹ, đừng ngăn bé. Dù lem luốc khắp người, việc tự ăn là bằng chứng lớn nhất cho sự tự lập của bé.', title_zh = '坚持自己吃饭 🥄', body_zh = '他从你手里拿走勺子，就别拦着。即使弄得一身脏，自己吃饭也是他独立的最好证明。' WHERE id = 'ff37a7ef-9322-44bc-9dbd-322f32bc0ec9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dulces sueños 🌙', body_es = 'Hoy has acabado muy cansada. Mientras duerme, pon el sonido de las olas del mar en Ruido blanco: él dormirá a gusto y tú descansarás.', title_fr = 'Doux rêves 🌙', body_fr = 'Vous êtes très fatiguée aujourd''hui. Pendant qu''il dort, lancez les vagues de l''océan dans les Bruits blancs : il dormira paisiblement et vous pourrez vous reposer.', title_hi = 'मीठे सपने 🌙', body_hi = 'आज आप बहुत थक गईं। उसके सोते समय व्हाइट नॉइज़ से समुद्र की लहरें चलाइए, ताकि वह भी चैन से सोए और आप भी आराम करें।', title_id = 'Mimpi indah 🌙', body_id = 'Hari ini Anda sangat lelah. Saat ia tidur, putar suara ombak laut dari Suara Putih, agar ia tidur nyenyak dan Anda pun bisa beristirahat.', title_ja = 'いい夢を 🌙', body_ja = '今日はとても疲れましたね。お子さんが眠ったら「ホワイトノイズ」から波の音を流して、お子さんはぐっすり、あなたもゆっくり休みましょう。', title_ko = '달콤한 꿈 🌙', body_ko = '오늘 많이 지쳤죠. 아이가 잘 때 백색소음에서 파도 소리를 틀어 아이는 편히 자고, 엄마도 쉬세요.', title_nl = 'Slaap lekker 🌙', body_nl = 'Je bent vandaag erg moe. Zet in Witte ruis de golven van de oceaan aan terwijl je kindje slaapt, zo slaapt hij rustig en kun jij uitrusten.', title_pl = 'Słodkich snów 🌙', body_pl = 'Bardzo się dziś zmęczyłaś. Gdy on śpi, włącz w Białym szumie fale oceanu, niech on śpi spokojnie, a ty odpocznij.', title_pt = 'Bons sonhos 🌙', body_pt = 'Hoje ficou muito cansada. Enquanto ele dorme, ligue o som das ondas do mar no Ruído Branco: ele dorme tranquilo e a mãe descansa.', title_sv = 'Sov sött 🌙', body_sv = 'Du har varit väldigt trött i dag. Sätt på havsvågor i Vitt brus medan barnet sover, så att barnet sover gott och du kan vila.', title_vi = 'Ngủ ngon nhé 🌙', body_vi = 'Hôm nay mẹ mệt lắm rồi. Khi bé ngủ, hãy bật tiếng sóng biển trong Tiếng ồn trắng để bé ngủ ngon và mẹ cũng được nghỉ ngơi.', title_zh = '甜甜的梦 🌙', body_zh = '今天你太累了。他睡觉时，在白噪音里放海浪声，让他睡得安稳，你也能好好休息。' WHERE id = '59f57b09-3fb4-490e-8cae-41edccebdd18' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Temporizador de comidas ⏱️', body_es = '¡Seguir las horas de comida ahora es más fácil! Activa el temporizador de tomas y controla con atención lo que come cada día.', title_fr = 'Le minuteur du déjeuner ⏱️', body_fr = 'Suivre l''heure des repas est désormais plus simple ! Lancez le minuteur des repas et surveillez attentivement ce qu''il mange chaque jour.', title_hi = 'खाने का टाइमर ⏱️', body_hi = 'खाने के समय पर नज़र रखना अब और आसान है! फ़ीडिंग टाइमर चालू कीजिए और बच्चे के रोज़ के मानक पर ध्यान से नज़र रखिए।', title_id = 'Timer makan siang ⏱️', body_id = 'Memantau jam makan kini lebih mudah! Nyalakan Timer Makan dan awasi dengan saksama porsi harian si kecil.', title_ja = 'ランチタイマー ⏱️', body_ja = '食事の時間の記録がもっと簡単に！食事タイマーをオンにして、毎日の食事量をしっかりチェックしましょう。', title_ko = '점심 타이머 ⏱️', body_ko = '식사 시간 기록이 더 쉬워졌어요! 수유 타이머를 켜고 아기의 하루 섭취량을 꼼꼼히 확인하세요.', title_nl = 'Lunchtimer ⏱️', body_nl = 'De etenstijden bijhouden is nu nog makkelijker! Zet de voedingstimer aan en houd de dagelijkse hoeveelheid van je kindje goed in de gaten.', title_pl = 'Timer obiadu ⏱️', body_pl = 'Śledzenie pór posiłków jest teraz łatwiejsze! Włącz timer karmienia i uważnie pilnuj dziennej normy dziecka.', title_pt = 'O temporizador do almoço ⏱️', body_pt = 'Acompanhar a hora das refeições agora é mais fácil! Ligue o temporizador de alimentação e acompanhe com atenção a quantidade diária do seu bebé.', title_sv = 'Måltidstimer ⏱️', body_sv = 'Nu är det enklare att följa måltiderna! Starta matningstimern och håll noga koll på barnets dagliga behov.', title_vi = 'Hẹn giờ bữa trưa ⏱️', body_vi = 'Theo dõi giờ ăn giờ đã dễ dàng hơn! Hãy bật bộ hẹn giờ trong Theo dõi cữ bú và theo dõi kỹ định mức hằng ngày của bé.', title_zh = '吃饭计时器 ⏱️', body_zh = '记录吃饭时间更简单了！打开喂养计时器，仔细关注宝宝每天的进食量。' WHERE id = '69941885-7481-4f3d-83b9-75392ac8bf14' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Empiezan las carreras! 🏃‍♀️', body_es = '¿Tu explorador de 17 meses está revolucionando la casa? Para que gaste energía, descubre en Lugares para mamás un parque nuevo cerca de ti.', title_fr = 'C''est parti pour courir ! 🏃‍♀️', body_fr = 'Votre explorateur de 17 mois met la maison sens dessus dessous ? Pour qu''il se défoule, découvrez un nouveau parc près de chez vous dans les Lieux adaptés aux mamans.', title_hi = 'भागदौड़ शुरू! 🏃‍♀️', body_hi = '17 महीने का खोजी घर में तूफ़ान मचा रहा है? उसकी ऊर्जा निकालने के लिए माँ के लिए अनुकूल जगहों में आसपास का कोई नया पार्क खोजिए।', title_id = 'Kejar-kejaran dimulai! 🏃‍♀️', body_id = 'Penjelajah 17 bulan Anda membuat heboh di rumah? Untuk menyalurkan energinya, temukan taman baru di dekat Anda lewat Tempat Ramah Ibu.', title_ja = '走り回る時期がスタート！🏃‍♀️', body_ja = '1歳5か月の探検家が家の中で大暴れ？エネルギーを発散できるよう、「ママにやさしいスポット」で近くの新しい公園を見つけましょう。', title_ko = '뛰어다니기 시작했어요! 🏃‍♀️', body_ko = '17개월 탐험가가 집 안을 휩쓸고 있나요? 에너지를 발산할 수 있도록 엄마 친화 장소에서 가까운 새 공원을 찾아보세요.', title_nl = 'Het rennen is begonnen! 🏃‍♀️', body_nl = 'Laat je ontdekker van 17 maanden thuis een storm opsteken? Ontdek in Mamavriendelijke plekken een nieuw park in de buurt waar hij zijn energie kwijt kan.', title_pl = 'Zaczęła się bieganina! 🏃‍♀️', body_pl = '17-miesięczny odkrywca robi w domu burzę? Odkryj w Miejscach przyjaznych mamom nowy park w pobliżu, by mógł wyładować energię.', title_pt = 'Começou a correria! 🏃‍♀️', body_pt = 'O explorador de 17 meses anda a fazer uma tempestade em casa? Para ele gastar energia, descubra um parque novo perto de si nos Locais Amigos das Mães.', title_sv = 'Nu börjar springet! 🏃‍♀️', body_sv = 'Ställer din upptäcktsresande på 17 månader till med storm hemma? Hitta en ny park i närheten i Mammavänliga platser så att barnet får ut sin energi.', title_vi = 'Cuộc rượt đuổi bắt đầu! 🏃‍♀️', body_vi = 'Nhà thám hiểm 17 tháng đang "khuấy động" cả nhà? Để bé xả năng lượng, hãy khám phá một công viên mới gần nhà trong Địa điểm thân thiện với mẹ.', title_zh = '开始满地跑啦！🏃‍♀️', body_zh = '17个月的小探险家在家里掀起风暴？为了让他释放精力，在妈妈友好场所里找一个附近的新公园吧。' WHERE id = '76342fb8-c3b7-4c1b-a6cb-70ae7ab72954' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Rico y diferente! 🥦', body_es = '¿Piensas qué cocinarle hoy de diferente? En la sección Recetas para bebés que empiezan con la alimentación complementaria hay ideas deliciosas.', title_fr = 'Savoureux et varié ! 🥦', body_fr = 'Vous vous demandez quoi lui cuisiner de nouveau aujourd''hui ? De délicieuses idées vous attendent dans les Recettes pour bébés qui commencent la diversification.', title_hi = 'स्वादिष्ट और कुछ अलग! 🥦', body_hi = 'सोच रही हैं कि आज उसके लिए क्या अलग बनाएँ? ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी सेक्शन में स्वादिष्ट आइडिया हैं।', title_id = 'Lezat dan berbeda! 🥦', body_id = 'Bingung mau masak apa yang berbeda untuknya hari ini? Ada ide-ide lezat di bagian Resep untuk bayi yang mulai MPASI.', title_ja = 'おいしくて、いつもとちがう！🥦', body_ja = '今日はどんな新しいメニューにしようか迷っていますか？「離乳食を始める赤ちゃんのレシピ」に、おいしいアイデアがあります。', title_ko = '맛있고 색다르게! 🥦', body_ko = '오늘은 뭘 색다르게 만들어 줄지 고민인가요? 레시피 섹션의 이유식을 시작하는 아기를 위한 레시피에 맛있는 아이디어가 있어요.', title_nl = 'Lekker en eens wat anders! 🥦', body_nl = 'Weet je niet wat je vandaag eens anders voor hem kunt koken? In het onderdeel Recepten voor baby''s die met bijvoeding beginnen vind je lekkere ideeën.', title_pl = 'Smacznie i inaczej! 🥦', body_pl = 'Zastanawiasz się, co nowego mu dziś ugotować? W sekcji Przepisy dla niemowląt rozpoczynających rozszerzanie diety znajdziesz smaczne pomysły.', title_pt = 'Saboroso e diferente! 🥦', body_pt = 'Está a pensar no que cozinhar hoje de diferente para ele? Nas Receitas para bebés em diversificação alimentar há ideias deliciosas.', title_sv = 'Gott och annorlunda! 🥦', body_sv = 'Funderar du på vad du ska laga för nytt till barnet i dag? I avsnittet Recept för bebisar som börjar med fast föda finns goda idéer.', title_vi = 'Ngon và lạ miệng! 🥦', body_vi = 'Mẹ đang nghĩ hôm nay nấu món gì mới cho bé? Mục Công thức cho bé bắt đầu ăn dặm có rất nhiều ý tưởng ngon miệng.', title_zh = '美味又新鲜！🥦', body_zh = '在想今天给他做点什么不一样的？食谱板块的辅食宝宝食谱里有很多美味的点子。' WHERE id = '310b35fd-56c2-4e43-bf45-49c975449bf2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escribe lo que sientes 📝', body_es = 'Ser madre a veces agota, y es totalmente normal. Escribe en el Diario de ánimo lo que más te ha cansado hoy y relájate.', title_fr = 'Écrivez vos ressentis 📝', body_fr = 'Être maman est parfois épuisant, et c''est tout à fait normal. Notez dans le Journal d''humeur ce qui vous a le plus fatiguée aujourd''hui, et détendez-vous.', title_hi = 'अपनी भावनाएँ लिखिए 📝', body_hi = 'माँ बनना कभी-कभी थकाने वाला होता है, और यह बिल्कुल सामान्य है। मूड डायरी में लिखिए कि आज आपको सबसे ज़्यादा किस बात ने थकाया, और हल्का महसूस कीजिए।', title_id = 'Tuliskan perasaan Anda 📝', body_id = 'Menjadi ibu kadang melelahkan, dan itu sangat normal. Tulis di Buku Harian Suasana Hati apa yang paling membuat Anda lelah hari ini, lalu tenangkan diri.', title_ja = '気持ちを書きとめよう 📝', body_ja = '子育てはときに疲れるもの。それはごく自然なことです。今日いちばん疲れたことを「気分日記」に書いて、リラックスしましょう。', title_ko = '감정을 적어 보세요 📝', body_ko = '엄마 노릇이 가끔 지치는 건 아주 자연스러운 일이에요. 기분 일기에 오늘 무엇이 가장 힘들었는지 적고 마음을 편히 하세요.', title_nl = 'Schrijf je gevoelens op 📝', body_nl = 'Moederschap is soms vermoeiend en dat is heel normaal. Schrijf in je Stemmingsdagboek op wat je vandaag het meest vermoeide en kom tot rust.', title_pl = 'Zapisz swoje uczucia 📝', body_pl = 'Macierzyństwo bywa męczące i to zupełnie normalne. Zapisz w Dzienniku nastroju, co dziś zmęczyło cię najbardziej, i odetchnij.', title_pt = 'Escreva o que sente 📝', body_pt = 'A maternidade às vezes cansa, e isso é muito normal. Escreva no Diário de Humor o que mais a cansou hoje e descontraia.', title_sv = 'Skriv ner dina känslor 📝', body_sv = 'Moderskapet är ibland tröttsamt, och det är helt normalt. Skriv i Humördagboken vad som tröttade ut dig mest i dag och slappna av.', title_vi = 'Hãy viết ra cảm xúc 📝', body_vi = 'Làm mẹ đôi khi thật mệt mỏi và điều đó hoàn toàn bình thường. Hãy viết vào Nhật ký tâm trạng điều khiến mẹ mệt nhất hôm nay và thả lỏng nhé.', title_zh = '写下你的感受 📝', body_zh = '当妈妈有时很累，这很正常。在心情日记里写下今天最让你累的事，放松一下吧。' WHERE id = '9477e55c-8f99-4ea9-8c87-38780aa67baa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa matutina 💩', body_es = '¿Has cambiado el primer pañal del día? No olvides anotarlo en el Seguimiento de pañales de la app para controlar fácilmente su rutina de higiene.', title_fr = 'La surprise du matin 💩', body_fr = 'Vous avez changé la première couche de la journée ? N''oubliez pas de la noter dans le Suivi des couches de l''application pour garder facilement un œil sur son hygiène !', title_hi = 'सुबह का सरप्राइज़ 💩', body_hi = 'दिन का पहला डायपर बदल दिया? ऐप के डायपर ट्रैकर में दर्ज करना मत भूलिए, ताकि साफ़-सफ़ाई का रूटीन आसानी से नियंत्रण में रहे!', title_id = 'Kejutan pagi 💩', body_id = 'Sudah mengganti popok pertama hari ini? Jangan lupa mencatatnya di Pelacak Popok di aplikasi, agar rutinitas kebersihannya mudah terpantau!', title_ja = '朝のサプライズ 💩', body_ja = '今日最初のおむつ替えはすみましたか？アプリの「おむつトラッカー」に記録するのを忘れずに。衛生の習慣をかんたんに管理しましょう！', title_ko = '아침의 깜짝 선물 💩', body_ko = '오늘 첫 기저귀를 갈았나요? 앱의 기저귀 기록에 남기는 걸 잊지 마세요. 위생 루틴을 쉽게 관리할 수 있어요!', title_nl = 'Een verrassing in de ochtend 💩', body_nl = 'Heb je de eerste luier van de dag verschoond? Vergeet niet het te noteren in de Luiertracker in de app, zo houden we de hygiëneroutine makkelijk bij!', title_pl = 'Poranna niespodzianka 💩', body_pl = 'Przewinęłaś pierwszą pieluszkę dnia? Nie zapomnij zapisać jej w narzędziu do śledzenia pieluszek w aplikacji, by łatwo kontrolować rutynę higieny!', title_pt = 'A surpresa da manhã 💩', body_pt = 'Já mudou a primeira fralda do dia? Não se esqueça de a registar no Registo de Fraldas da app, para manter a rotina de higiene sob controlo com facilidade!', title_sv = 'Morgonens överraskning 💩', body_sv = 'Har du bytt dagens första blöja? Glöm inte att anteckna det i appens Blöjkollen, så har vi enkelt koll på hygienrutinen!', title_vi = 'Bất ngờ buổi sáng 💩', body_vi = 'Mẹ vừa thay chiếc tã đầu tiên trong ngày? Đừng quên ghi lại vào Theo dõi tã trong ứng dụng để dễ dàng nắm được nếp vệ sinh của bé!', title_zh = '早晨的惊喜 💩', body_zh = '换了今天的第一片尿布？别忘了在应用的尿布记录里记下来，轻松掌握清洁护理的节奏！' WHERE id = 'bd556eab-5192-450f-94ce-a80cdc85557b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mírame! ☝️', body_es = 'Hace ruiditos para llamar tu atención y señala con el dedo lo que le interesa. Comparte sus descubrimientos y confírmaselo: «Sí, es una pelota».', title_fr = 'Regarde-moi ! ☝️', body_fr = 'Il fait des sons pour attirer votre attention et montre du doigt ce qui l''intéresse. Partagez ses découvertes et confirmez : « Oui, c''est un ballon ».', title_hi = 'मुझे देखो! ☝️', body_hi = 'ध्यान खींचने के लिए आवाज़ निकालता है और जिस चीज़ में दिलचस्पी है, उसकी ओर उँगली दिखाता है। उसकी खोजों में शामिल होइए, ''हाँ, यह गेंद है'' कहकर हामी भरिए।', title_id = 'Lihat aku! ☝️', body_id = 'Ia mengeluarkan suara untuk menarik perhatian dan menunjuk benda yang menarik minatnya? Ikutlah dalam penemuannya dan tegaskan: "Iya, ini bola".', title_ja = '見て！☝️', body_ja = '声を出してあなたの注意を引き、気になるものを指さしますか？その発見に寄り添って、「そうだね、ボールだね」と応えてあげましょう。', title_ko = '나 좀 봐! ☝️', body_ko = '관심을 끌려고 소리를 내며 궁금한 물건을 손가락으로 가리켜요. 아이의 발견에 함께하며 "맞아, 이건 공이야" 하고 맞장구쳐 주세요.', title_nl = 'Kijk naar mij! ☝️', body_nl = 'Je kindje maakt geluidjes om je aandacht te trekken en wijst aan wat hem interesseert. Doe mee met zijn ontdekkingen en bevestig: ja, dat is een bal.', title_pl = 'Popatrz na mnie! ☝️', body_pl = 'Wydaje dźwięki, by zwrócić twoją uwagę, i pokazuje paluszkiem to, co go ciekawi. Uczestnicz w jego odkryciach i potwierdzaj: „Tak, to piłka”.', title_pt = 'Olha para mim! ☝️', body_pt = 'Faz sons para chamar a atenção e aponta com o dedo para o objeto que lhe interessa. Partilhe as descobertas dele e confirme: "Sim, é uma bola".', title_sv = 'Titta på mig! ☝️', body_sv = 'Barnet låter för att få uppmärksamhet och pekar på det som intresserar det. Var med i upptäckterna och bekräfta: ”Ja, det är en boll.”', title_vi = 'Nhìn con này! ☝️', body_vi = 'Bé phát ra âm thanh để thu hút sự chú ý và chỉ tay vào thứ bé quan tâm. Hãy cùng bé khám phá và xác nhận: "Đúng rồi, đó là quả bóng".', title_zh = '看我！☝️', body_zh = '他会发出声音吸引你的注意，用手指指着感兴趣的东西。参与他的发现，回应他“对，这是球”吧。' WHERE id = '09e40e6a-1b4a-402d-88ca-e9d2b030ae96' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de la cuchara 🥄', body_es = '¿Quiere comer solo y se echa la mitad encima? No te centres en la limpieza. Estos días son la base de su hábito de comer solo.', title_fr = 'La bataille de la cuillère 🥄', body_fr = 'Il veut manger seul et en renverse la moitié sur lui ? Ne vous focalisez pas sur la propreté. Ces journées posent les bases de son autonomie à table.', title_hi = 'चम्मच की ज़िद 🥄', body_hi = 'खुद खाना चाहता है और आधा खुद पर गिरा लेता है? सफ़ाई पर ध्यान मत दीजिए। ये दिन उसकी खुद खाने की आदत की नींव हैं।', title_id = 'Ngotot pegang sendok 🥄', body_id = 'Ia ingin makan sendiri dan setengahnya tumpah ke bajunya? Jangan fokus pada kebersihan. Hari-hari ini adalah fondasi kebiasaannya makan sendiri.', title_ja = 'スプーンは自分で！🥄', body_ja = '自分で食べたがって、半分こぼしてしまう？きれいさは気にしないで。この時期が、自分で食べる習慣の土台になります。', title_ko = '숟가락 고집 🥄', body_ko = '혼자 먹겠다며 절반은 옷에 흘리나요? 청소에 신경 쓰지 마세요. 지금이 스스로 먹는 습관의 바탕이 되는 시기예요.', title_nl = 'Koppig met de lepel 🥄', body_nl = 'Wil je kindje zelf eten en morst hij de helft? Let niet op de rommel. Deze dagen zijn de basis voor zelfstandig leren eten.', title_pl = 'Upór przy łyżeczce 🥄', body_pl = 'Chce jeść sam i połowę wylewa na siebie? Nie skupiaj się na czystości. Te dni to fundament jego nawyku samodzielnego jedzenia.', title_pt = 'A teimosia da colher 🥄', body_pt = 'Quer comer sozinho e entorna metade em cima de si? Não se foque na limpeza. Estes dias são a base do hábito de comer sozinho.', title_sv = 'Skedens trots 🥄', body_sv = 'Vill barnet äta själv och spiller hälften på sig? Fokusera inte på städningen. De här dagarna lägger grunden för vanan att äta själv.', title_vi = 'Bé đòi tự cầm thìa 🥄', body_vi = 'Bé muốn tự ăn và làm đổ một nửa lên người? Đừng bận tâm chuyện sạch sẽ. Những ngày này là nền tảng cho thói quen tự ăn của bé.', title_zh = '勺子要自己拿 🥄', body_zh = '想自己吃饭，却把一半撒在身上？别盯着清洁。这些日子正是他自主进食习惯的基础。' WHERE id = 'c5a0bf61-8c64-48fe-98e1-446f7f35fcb3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El balance del día 📝', body_es = 'Cuando sientas que no llegas, escribe en el Diario de ánimo tus pequeños logros de hoy (por ejemplo: «Le he hecho reír», «Ha comido bien»). Eres genial.', title_fr = 'Le bilan du jour 📝', body_fr = 'Quand vous ne vous sentez pas à la hauteur, notez dans le Journal d''humeur vos petites réussites du jour. (Par exemple : je l''ai fait rire, il a bien mangé.) Vous êtes formidable.', title_hi = 'दिन का हिसाब 📝', body_hi = 'जब खुद को कम महसूस करें, तो मूड डायरी में आज की अपनी छोटी कामयाबियाँ लिखिए। (जैसे: ''उसे हँसाया'', ''उसका पेट भरा रखा'')। आप कमाल की हैं।', title_id = 'Laporan hari ini 📝', body_id = 'Saat merasa tidak cukup baik, tulis keberhasilan kecil Anda hari ini di Buku Harian Suasana Hati. (Misalnya: "Aku membuatnya tertawa", "Aku membuatnya kenyang"). Anda luar biasa.', title_ja = '今日のふり返り 📝', body_ja = '自分は足りていないと感じたら、「気分日記」に今日の小さな成功を書きましょう（たとえば「笑わせた」「お腹いっぱい食べさせた」）。あなたはすばらしいママです。', title_ko = '오늘의 결산 📝', body_ko = '내가 부족하게 느껴질 때는 기분 일기에 오늘의 작은 성공을 적어 보세요. (예: 아이를 웃게 했어, 배불리 먹였어). 당신은 정말 잘하고 있어요.', title_nl = 'Het verslag van de dag 📝', body_nl = 'Voel je je tekortschieten? Schrijf je kleine successen van vandaag op in je Stemmingsdagboek (bijvoorbeeld: ik heb hem laten lachen, ik heb hem goed te eten gegeven). Je bent geweldig.', title_pl = 'Podsumowanie dnia 📝', body_pl = 'Gdy czujesz, że nie dajesz rady, zapisz w Dzienniku nastroju swoje dzisiejsze małe sukcesy (np. „Rozśmieszyłam go”, „Był najedzony”). Jesteś wspaniała.', title_pt = 'O balanço do dia 📝', body_pt = 'Quando se sentir insuficiente, escreva no Diário de Humor as pequenas vitórias de hoje (por exemplo: "Fi-lo rir", "Dei-lhe de comer"). É fantástica.', title_sv = 'Dagens rapport 📝', body_sv = 'När du känner dig otillräcklig, skriv dagens små framgångar i Humördagboken. (Till exempel: Jag fick barnet att skratta, jag höll barnet mätt). Du är fantastisk.', title_vi = 'Tổng kết ngày 📝', body_vi = 'Khi cảm thấy mình chưa đủ tốt, hãy viết những thành công nhỏ hôm nay vào Nhật ký tâm trạng. (Ví dụ: "Mình đã làm con cười", "Mình đã cho con ăn no"). Mẹ thật tuyệt vời.', title_zh = '今天的总结 📝', body_zh = '觉得自己做得不够好时，把今天的小成就写进心情日记吧。（比如：“我逗他笑了，让他吃饱了。”）你很棒。' WHERE id = 'c62d64af-c28e-4bfc-82ce-a73c5d55fd91' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La conversación se pone seria 🗣️', body_es = '¿Te cuenta algo con palabras que no se entienden e incluso hace gestos con las manos? Respóndele con la misma seriedad: es clave para que se le suelte el habla.', title_fr = 'La conversation devient sérieuse 🗣️', body_fr = 'Il vous raconte quelque chose avec des mots incompréhensibles, et fait même des gestes ? Répondez-lui avec le même sérieux, c''est essentiel pour que son langage se libère.', title_hi = 'बातचीत और गंभीर हो रही है 🗣️', body_hi = 'न समझ आने वाले शब्दों में आपसे कुछ कहता है, हाथ भी हिलाता है? उसी गंभीरता से उससे बातचीत कीजिए, बोली खुलने के लिए यह ज़रूरी है।', title_id = 'Obrolan makin serius 🗣️', body_id = 'Ia bercerita dengan kata-kata yang sulit dipahami, bahkan sambil menggerakkan tangan? Tanggapi dengan sama seriusnya, ini syarat agar kemampuan bicaranya berkembang.', title_ja = 'おしゃべりが本格的に 🗣️', body_ja = 'よくわからない言葉で、身ぶりまでつけて話しかけてきますか？同じくらい真剣に会話をしてあげましょう。言葉が育つために欠かせません。', title_ko = '대화가 점점 진지해져요 🗣️', body_ko = '알아들을 수 없는 말로 무언가를 이야기하며 손짓까지 하나요? 똑같이 진지하게 대화해 주세요. 말문이 트이는 데 꼭 필요해요.', title_nl = 'De gesprekken worden serieuzer 🗣️', body_nl = 'Vertelt je kindje je iets in onverstaanbare woordjes en maakt hij er zelfs gebaren bij? Ga even serieus met hem in gesprek, dat is nodig om zijn spraak op gang te brengen.', title_pl = 'Rozmowy stają się poważniejsze 🗣️', body_pl = 'Opowiada ci coś niezrozumiałymi słowami, a nawet gestykuluje? Rozmawiaj z nim równie poważnie, to warunek rozwoju mowy.', title_pt = 'A conversa fica mais séria 🗣️', body_pt = 'Conta-lhe coisas com palavras impercetíveis e até faz gestos com as mãos? Dialogue com ele com a mesma seriedade: é essencial para a fala se desenvolver.', title_sv = 'Samtalen blir allt mer seriösa 🗣️', body_sv = 'Berättar barnet något för dig med obegripliga ord och gör till och med gester? För en dialog med samma allvar, det är en förutsättning för att talet ska komma igång.', title_vi = 'Cuộc trò chuyện ngày càng nghiêm túc 🗣️', body_vi = 'Bé nói với mẹ điều gì đó bằng những từ khó hiểu, thậm chí còn khoa tay múa chân? Hãy trò chuyện với bé nghiêm túc như vậy, đó là điều kiện để bé bật ra lời nói.', title_zh = '聊天越来越认真了 🗣️', body_zh = '他用听不懂的话跟你说着什么，还配上手势？用同样认真的态度和他对话，这是语言开口的关键。' WHERE id = '14fb698f-87dd-4c4e-b7ba-3a1f2a79dd22' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del aire fresco 🌙', body_es = '¿Se niega a dormir? Abre la ventana y ventila bien la habitación. El aire fresco y limpio siempre facilita el paso al sueño.', title_fr = 'La force de l''air frais 🌙', body_fr = 'Il refuse de dormir ? Ouvrez la fenêtre et aérez complètement la chambre. Un air frais et pur facilite toujours l''endormissement.', title_hi = 'ताज़ी हवा की ताकत 🌙', body_hi = 'सोने से मना करता है? खिड़की खोलिए और कमरे की हवा पूरी तरह बदल दीजिए। ठंडी और ताज़ी हवा नींद में जाना हमेशा आसान बनाती है।', title_id = 'Kekuatan udara segar 🌙', body_id = 'Ia menolak tidur? Buka jendela dan ganti udara kamar sepenuhnya. Udara sejuk dan segar selalu memudahkan peralihan ke tidur.', title_ja = '新鮮な空気の力 🌙', body_ja = '寝るのを嫌がる？窓を開けて、部屋の空気をすっかり入れかえましょう。ひんやりした新鮮な空気は、いつも眠りへの切りかえを楽にしてくれます。', title_ko = '신선한 공기의 힘 🌙', body_ko = '자지 않으려 하나요? 창문을 열어 방 공기를 완전히 바꿔 주세요. 선선하고 깨끗한 공기는 언제나 잠들기 쉽게 해 줘요.', title_nl = 'De kracht van frisse lucht 🌙', body_nl = 'Wil je kindje niet slapen? Zet het raam open en lucht de kamer goed. Koele, frisse lucht maakt het inslapen altijd makkelijker.', title_pl = 'Moc świeżego powietrza 🌙', body_pl = 'Nie chce spać? Otwórz okno i dobrze wywietrz pokój. Chłodne, świeże powietrze zawsze ułatwia zasypianie.', title_pt = 'A força do ar puro 🌙', body_pt = 'Recusa-se a dormir? Abra a janela e renove por completo o ar do quarto. O ar fresco e puro facilita sempre a passagem para o sono.', title_sv = 'Den friska luftens kraft 🌙', body_sv = 'Vägrar barnet sova? Öppna fönstret och vädra ut helt. Sval och frisk luft gör alltid insomnandet lättare.', title_vi = 'Sức mạnh của không khí trong lành 🌙', body_vi = 'Bé không chịu ngủ? Hãy mở cửa sổ và thay đổi hoàn toàn không khí trong phòng. Không khí mát mẻ, trong lành luôn giúp bé vào giấc dễ dàng hơn.', title_zh = '新鲜空气的力量 🌙', body_zh = '不肯睡觉？打开窗户，给房间彻底换换气。凉爽清新的空气总能让入睡更容易。' WHERE id = '1d9a7143-69c8-42b7-9dd5-0d7f48adbb9c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sospechas de una alergia? 🤖', body_es = '¿Le has dado una fruta nueva y le han salido rojeces? Antes de alarmarte, consulta con Anacan AI los primeros pasos ante una alergia alimentaria en niños.', title_fr = 'Un doute d''allergie ? 🤖', body_fr = 'Vous lui avez donné un nouveau fruit et des rougeurs sont apparues ? Avant de vous inquiéter, découvrez avec Anacan AI les premières étapes face à une allergie alimentaire chez l''enfant.', title_hi = 'एलर्जी का शक? 🤖', body_hi = 'नया फल दिया और लाल चकत्ते हो गए? घबराने से पहले Anacan AI से बच्चों में फ़ूड एलर्जी के पहले कदम जानिए।', title_id = 'Curiga alergi? 🤖', body_id = 'Memberi buah baru lalu muncul ruam kemerahan? Sebelum panik, pelajari langkah pertama menghadapi alergi makanan pada anak dari Anacan AI.', title_ja = 'アレルギーかも？🤖', body_ja = '新しい果物をあげたら、赤みが出ましたか？慌てる前に、Anacan AIで子どもの食物アレルギーの最初の対処法を確認しましょう。', title_ko = '알레르기가 의심되나요? 🤖', body_ko = '새 과일을 줬는데 붉은 발진이 생겼나요? 당황하기 전에 Anacan AI에게 아이 음식 알레르기의 첫 대처법을 알아보세요.', title_nl = 'Vermoeden van allergie? 🤖', body_nl = 'Heb je een nieuw soort fruit gegeven en zie je roodheid? Ontdek voordat je in paniek raakt bij Anacan AI wat de eerste stappen zijn bij voedselallergie bij kinderen.', title_pl = 'Podejrzewasz alergię? 🤖', body_pl = 'Podałaś nowy owoc i pojawiło się zaczerwienienie? Zanim zaczniesz panikować, poznaj w Anacan AI pierwsze kroki przy alergii pokarmowej u dzieci.', title_pt = 'Suspeita de alergia? 🤖', body_pt = 'Deu-lhe uma fruta nova e apareceu uma vermelhidão? Antes de entrar em pânico, saiba com o Anacan AI os primeiros passos perante uma alergia alimentar em crianças.', title_sv = 'Misstänkt allergi? 🤖', body_sv = 'Gav du en ny frukt och det blev rodnad? Innan du får panik, lär dig de första stegen vid matallergi hos barn från Anacan AI.', title_vi = 'Nghi ngờ dị ứng? 🤖', body_vi = 'Mẹ cho bé ăn một loại trái cây mới và bé bị nổi mẩn đỏ? Trước khi hoảng hốt, hãy tìm hiểu cùng Anacan AI những bước đầu tiên khi trẻ bị dị ứng thực phẩm.', title_zh = '怀疑过敏？🤖', body_zh = '给了一种新水果，皮肤发红了？先别慌，向Anacan AI了解孩子食物过敏时第一步该怎么做。' WHERE id = '66766839-1404-43e5-8e4f-02d3ea6ce97c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La siesta 😴', body_es = '¡Activa el Temporizador de sueño! Analiza cuánto duerme la siesta tu peque de 17 meses y planifica con más precisión la hora de acostarle.', title_fr = 'La sieste 😴', body_fr = 'Lancez le minuteur de sommeil ! Analysez la durée des siestes de votre enfant de 17 mois pour mieux organiser le coucher du soir.', title_hi = 'दिन की झपकी 😴', body_hi = 'स्लीप टाइमर चालू कीजिए! 17 महीने के बच्चे की दिन की झपकी की अवधि का विश्लेषण करके शाम को सुलाने की योजना और सटीक बनाइए।', title_id = 'Tidur siang 😴', body_id = 'Nyalakan Timer Tidur! Analisis durasi tidur siang anak 17 bulan Anda dan susun rencana tidur malam dengan lebih tepat.', title_ja = 'お昼寝 😴', body_ja = '睡眠タイマーをオンに！1歳5か月の子のお昼寝の長さを分析して、夜の寝かしつけ計画をより正確に立てましょう。', title_ko = '낮잠 😴', body_ko = '수면 타이머를 켜세요! 17개월 아이의 낮잠 시간을 분석해 저녁 재우기 계획을 더 정확하게 세워 보세요.', title_nl = 'Middagdutje 😴', body_nl = 'Zet de Slaaptimer aan! Analyseer hoe lang je kindje van 17 maanden overdag slaapt en plan het naar bed brengen ''s avonds nauwkeuriger.', title_pl = 'Drzemka 😴', body_pl = 'Włącz timer snu! Przeanalizuj długość drzemek 17-miesięcznego dziecka i dokładniej zaplanuj wieczorne usypianie.', title_pt = 'A sesta 😴', body_pt = 'Ligue o temporizador de sono! Analise a duração da sesta de uma criança de 17 meses e planeie com mais precisão a hora de deitar à noite.', title_sv = 'Dagslur 😴', body_sv = 'Starta sömntimern! Analysera hur länge ditt barn på 17 månader sover på dagen och lägg upp kvällens nattningsplan mer exakt.', title_vi = 'Giấc ngủ ngày 😴', body_vi = 'Hãy bật Bộ hẹn giờ ngủ! Phân tích thời lượng giấc ngủ ngày của bé 17 tháng để lên kế hoạch ru ngủ buổi tối chính xác hơn.', title_zh = '白天小睡 😴', body_zh = '打开睡眠计时器！分析17个月宝宝白天小睡的时长，更准确地安排晚上的哄睡计划。' WHERE id = '86fd1056-7ec6-4295-9ae9-cce90735b8fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de comodidad 🍼', body_es = '¿Buscas el mejor vaso antiderrame para su independencia? Mira en Productos recomendados las opciones favoritas de otras mamás.', title_fr = 'En quête de confort 🍼', body_fr = 'Vous cherchez la meilleure gourde anti-fuite pour son autonomie ? Découvrez les modèles préférés des mamans dans les Produits recommandés.', title_hi = 'आराम की तलाश में 🍼', body_hi = 'उसकी आत्मनिर्भरता के लिए सबसे अच्छा न छलकने वाला सिपी कप ढूँढ रही हैं? सुझाए गए प्रोडक्ट सेक्शन में माँओं के सबसे पसंदीदा विकल्प देखिए।', title_id = 'Mencari kenyamanan 🍼', body_id = 'Mencari botol minum anti tumpah terbaik untuk kemandiriannya? Lihat pilihan favorit para ibu di bagian Produk Rekomendasi.', title_ja = '快適さを求めて 🍼', body_ja = '自分で飲めるよう、こぼれにくいマグを探していますか？「おすすめ商品」で、ママたちにいちばん人気の商品を見てみましょう。', title_ko = '편안함을 찾아서 🍼', body_ko = '아이가 혼자 쓸 수 있는 가장 좋은 새지 않는 물병을 찾고 있나요? 추천 제품 섹션에서 엄마들이 가장 좋아하는 제품을 확인하세요.', title_nl = 'Op zoek naar gemak 🍼', body_nl = 'Op zoek naar de beste lekvrije drinkbeker voor zijn zelfstandigheid? Bekijk in het onderdeel Aanbevolen producten de keuzes die moeders het leukst vinden.', title_pl = 'W poszukiwaniu wygody 🍼', body_pl = 'Szukasz najlepszego niewylewającego kubka, który wesprze jego samodzielność? Zobacz w sekcji Polecane produkty opcje, które mamy lubią najbardziej.', title_pt = 'Em busca de conforto 🍼', body_pt = 'Procura o melhor copo antiderrame para a independência dele? Veja na secção Produtos Recomendados as opções preferidas das mães.', title_sv = 'På jakt efter bekvämlighet 🍼', body_sv = 'Letar du efter den bästa spillfria pipmuggen för barnets självständighet? Titta på mammornas favoriter i avsnittet Rekommenderade produkter.', title_vi = 'Tìm kiếm sự tiện lợi 🍼', body_vi = 'Mẹ đang tìm chiếc bình tập uống chống tràn tốt nhất để bé tự lập? Hãy xem những lựa chọn được các mẹ yêu thích nhất trong mục Sản phẩm gợi ý.', title_zh = '寻找更方便的选择 🍼', body_zh = '在找一款最好的防漏水杯，让他更独立？看看推荐商品里妈妈们最喜欢的选择吧。' WHERE id = '88975ce2-bde2-4036-a81f-ecfc994e6ec7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No te olvides de ti! ☕', body_es = 'Tu energía es lo más importante para tu peque. Prepárate en Recetas saludables un batido delicioso que te dé fuerzas.', title_fr = 'Ne vous oubliez pas ! ☕', body_fr = 'Votre énergie est essentielle pour votre bébé. Préparez-vous un smoothie savoureux et revigorant grâce aux Recettes saines.', title_hi = 'खुद को मत भूलिए! ☕', body_hi = 'आपकी ऊर्जा आपके बच्चे के लिए सबसे ज़रूरी है। सेहतमंद रेसिपी से अपने लिए स्वादिष्ट और ताकत देने वाली स्मूदी बनाइए।', title_id = 'Jangan lupakan diri Anda! ☕', body_id = 'Energi Anda adalah syarat terpenting untuk si kecil. Buat smoothie lezat penambah tenaga dari Resep Sehat untuk diri sendiri.', title_ja = '自分のことも忘れないで！☕', body_ja = 'あなたのエネルギーは、お子さんにとって何より大切です。「ヘルシーレシピ」から、おいしくて元気が出るスムージーをつくりましょう。', title_ko = '나 자신을 잊지 마세요! ☕', body_ko = '엄마의 에너지가 아기에게 가장 중요해요. 건강한 레시피에서 맛있고 힘이 나는 스무디를 만들어 보세요.', title_nl = 'Vergeet jezelf niet! ☕', body_nl = 'Jouw energie is het allerbelangrijkste voor je kindje. Maak uit Gezonde recepten een lekkere smoothie die je kracht geeft.', title_pl = 'Nie zapominaj o sobie! ☕', body_pl = 'Twoja energia to dla dziecka najważniejsza sprawa. Przygotuj sobie ze zdrowych przepisów smaczne smoothie, które doda ci sił.', title_pt = 'Não se esqueça de si! ☕', body_pt = 'A sua energia é essencial para o seu bebé. Prepare nas Receitas Saudáveis um batido delicioso que lhe dê força.', title_sv = 'Glöm inte dig själv! ☕', body_sv = 'Din energi är det viktigaste för ditt barn. Gör en god och kraftgivande smoothie åt dig själv från Hälsosamma recept.', title_vi = 'Đừng quên bản thân mẹ! ☕', body_vi = 'Năng lượng của mẹ là điều quan trọng nhất cho bé. Hãy làm cho mình một ly sinh tố ngon miệng, giàu năng lượng từ Công thức lành mạnh.', title_zh = '别忘了自己！☕', body_zh = '你的能量是宝宝最重要的保障。从健康食谱里给自己做一杯美味又提神的果昔吧。' WHERE id = 'b24e422c-33a1-4394-8c5a-e6048392180c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Blog y café 📖', body_es = '¡Se ha dormido, ahora el tiempo es tuyo! Lee nuestra nueva entrada del Blog y descubre datos muy interesantes sobre la psicología de los niños activos.', title_fr = 'Blog et café 📖', body_fr = 'Il dort, c''est votre moment ! Lisez notre nouvel article de blog et découvrez des faits passionnants sur la psychologie des enfants actifs.', title_hi = 'ब्लॉग और कॉफ़ी 📖', body_hi = 'बच्चा सो गया, अब समय आपका है! हमारी नई ब्लॉग पोस्ट पढ़िए और सक्रिय बच्चों के मनोविज्ञान के बारे में बहुत दिलचस्प बातें जानिए।', title_id = 'Blog dan kopi 📖', body_id = 'Si kecil sudah tidur, sekarang waktunya untuk Anda! Baca artikel blog terbaru kami dan pelajari fakta menarik tentang psikologi anak yang aktif.', title_ja = 'ブログとコーヒー 📖', body_ja = 'お子さんが寝たら、ここからはあなたの時間！新しいブログ記事を読んで、活発な子どもの心理についての興味深い話を知りましょう。', title_ko = '블로그와 커피 📖', body_ko = '아이가 잠들었으니 이제 엄마 시간이에요! 새 블로그 글에서 활발한 아이들의 심리에 관한 흥미로운 사실을 알아보세요.', title_nl = 'Blog en koffie 📖', body_nl = 'Je kindje slaapt, nu is de tijd voor jou! Lees onze nieuwe blog en ontdek heel interessante feiten over de psychologie van actieve kinderen.', title_pl = 'Blog i kawa 📖', body_pl = 'Maluszek zasnął, teraz czas dla ciebie! Przeczytaj nasz nowy wpis na blogu i poznaj ciekawe fakty o psychologii aktywnych dzieci.', title_pt = 'Blogue e café 📖', body_pt = 'Ele adormeceu, agora o tempo é seu! Leia o nosso novo artigo do Blogue e descubra factos muito interessantes sobre a psicologia das crianças ativas.', title_sv = 'Blogg och kaffe 📖', body_sv = 'Barnet sover, nu är tiden din! Läs vårt nya blogginlägg och lär dig mycket intressanta fakta om aktiva barns psykologi.', title_vi = 'Blog và cà phê 📖', body_vi = 'Bé ngủ rồi, giờ là thời gian của mẹ! Hãy đọc bài blog mới của chúng tôi để biết những điều rất thú vị về tâm lý của trẻ hiếu động.', title_zh = '博客和咖啡 📖', body_zh = '宝宝睡了，现在是你的时间！读读我们的新博客文章，了解关于活泼孩子心理的有趣知识吧。' WHERE id = '6a0dbe71-a2e3-4dfc-90e2-77ab87992f1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paseo cómodo 👟', body_es = '¿Necesitáis los dos un calzado cómodo para que puedas correr detrás de él en el parque? Echa un vistazo a las mejores opciones en Productos recomendados.', title_fr = 'Une balade confortable 👟', body_fr = 'Vous avez besoin, lui comme vous, de chaussures confortables pour courir au parc ? Jetez un œil aux meilleurs choix dans les Produits recommandés.', title_hi = 'आरामदायक सैर 👟', body_hi = 'पार्क में उसके पीछे भागने के लिए आपको और उसे आरामदायक जूते चाहिए? सुझाए गए प्रोडक्ट सेक्शन में सबसे अच्छे विकल्प देखिए।', title_id = 'Jalan-jalan dengan nyaman 👟', body_id = 'Butuh sepatu yang nyaman untuk Anda dan dia saat berkejaran di taman? Lihat pilihan terbaik di bagian Produk Rekomendasi.', title_ja = '快適なお散歩 👟', body_ja = '公園でお子さんを追いかけるのに、あなたにもお子さんにも履きやすい靴が必要ですか？「おすすめ商品」でベストな選択肢をのぞいてみましょう。', title_ko = '편안한 산책 👟', body_ko = '공원에서 아이를 쫓아다니려면 엄마와 아이 모두 편한 신발이 필요하죠? 추천 제품 섹션에서 가장 좋은 선택지를 둘러보세요.', title_nl = 'Een fijne wandeling 👟', body_nl = 'Hebben jij en je kindje goede schoenen nodig om in het park achter hem aan te rennen? Bekijk de beste keuzes in het onderdeel Aanbevolen producten.', title_pl = 'Wygodny spacer 👟', body_pl = 'Potrzebujecie z maluchem wygodnych butów do biegania po parku? Przejrzyj najlepsze propozycje w sekcji Polecane produkty.', title_pt = 'Um passeio confortável 👟', body_pt = 'Precisam os dois de sapatos confortáveis para correr atrás dele no parque? Espreite as melhores opções na secção Produtos Recomendados.', title_sv = 'Bekväm promenad 👟', body_sv = 'Behöver du och barnet bekväma skor för jakten i parken? Titta på de bästa alternativen i avsnittet Rekommenderade produkter.', title_vi = 'Dạo chơi thoải mái 👟', body_vi = 'Mẹ và bé cần giày thoải mái để chạy nhảy ở công viên? Hãy xem những lựa chọn tốt nhất trong mục Sản phẩm gợi ý.', title_zh = '舒服地散步 👟', body_zh = '在公园追着他跑，你们俩都需要一双舒适的鞋？看看推荐商品里的最佳选择吧。' WHERE id = '92227c75-1f64-4b68-adfc-1f2f5187c456' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tienes alguna pregunta? 🤔', body_es = '¿Te preguntas cómo llevar su creciente terquedad? ¡Anacan AI está listo para responderte al momento con consejos de expertos!', title_fr = 'Une question ? 🤔', body_fr = 'Vous vous demandez comment gérer son entêtement grandissant ? Anacan AI est prêt à vous répondre tout de suite avec des conseils d''expert !', title_hi = 'कोई सवाल है? 🤔', body_hi = 'सोच रही हैं कि बच्चे की बढ़ती ज़िद से कैसे निपटें? Anacan AI विशेषज्ञ सलाह के साथ तुरंत जवाब देने को तैयार है!', title_id = 'Ada pertanyaan? 🤔', body_id = 'Bingung bagaimana menghadapi sikap keras kepalanya yang makin menjadi? Anacan AI siap langsung menjawab dengan saran ahli!', title_ja = '質問がありますか？🤔', body_ja = 'だんだん強くなるいやいやに、どう向き合えばいいか悩んでいますか？Anacan AIが専門的なアドバイスですぐに答えます！', title_ko = '궁금한 게 있나요? 🤔', body_ko = '점점 늘어나는 아이의 고집을 어떻게 다뤄야 할지 고민인가요? Anacan AI가 전문가 조언으로 바로 답해 드릴게요!', title_nl = 'Heb je een vraag? 🤔', body_nl = 'Vraag je je af hoe je omgaat met de groeiende koppigheid van je kindje? Anacan AI staat klaar om je meteen deskundig advies te geven!', title_pl = 'Masz pytanie? 🤔', body_pl = 'Zastanawiasz się, jak poradzić sobie z rosnącym uporem dziecka? Anacan AI jest gotowe od razu odpowiedzieć radami eksperta!', title_pt = 'Tem uma pergunta? 🤔', body_pt = 'Está a pensar em como lidar com a teimosia crescente da criança? O Anacan AI está pronto para responder já com conselhos de especialistas!', title_sv = 'Har du en fråga? 🤔', body_sv = 'Undrar du hur du ska hantera barnets ökande trots? Anacan AI är redo att svara direkt med expertråd!', title_vi = 'Mẹ có câu hỏi? 🤔', body_vi = 'Mẹ đang nghĩ cách đối phó với sự bướng bỉnh ngày càng tăng của bé? Anacan AI sẵn sàng giải đáp ngay bằng lời khuyên của chuyên gia!', title_zh = '有问题吗？🤔', body_zh = '在想怎么应对孩子越来越强的倔脾气？Anacan AI随时准备用专家建议为你解答！' WHERE id = 'ee92e380-b93d-467f-ae59-b65756c20e29' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión digestiva ⏱️', body_es = 'Seguir los pañales de cada día muestra la calidad de su alimentación. ¿Has anotado hoy los cambios en nuestra app?', title_fr = 'Contrôle de la digestion ⏱️', body_fr = 'Suivre le nombre de couches chaque jour renseigne sur la qualité de son alimentation. Avez-vous noté les changes d''aujourd''hui dans l''application ?', title_hi = 'पेट की जाँच ⏱️', body_hi = 'रोज़ कितने डायपर लगते हैं, इस पर नज़र रखना पोषण की गुणवत्ता दिखाता है। क्या आपने आज के डायपर बदलना हमारे ऐप में दर्ज किया?', title_id = 'Cek pencernaan ⏱️', body_id = 'Memantau pemakaian popok harian menunjukkan kualitas asupannya. Sudahkah Anda mencatat penggantian popok hari ini di aplikasi?', title_ja = 'おなかの調子チェック ⏱️', body_ja = '毎日のおむつの回数を見ると、食事がしっかりとれているかがわかります。今日のおむつ替えはアプリに記録しましたか？', title_ko = '장 건강 체크 ⏱️', body_ko = '하루 기저귀 사용량을 살피면 잘 먹고 있는지 알 수 있어요. 오늘 기저귀 교체를 앱에 기록했나요?', title_nl = 'Controle van de spijsvertering ⏱️', body_nl = 'Het aantal luiers per dag laat zien hoe goed de voeding is. Heb je de verschoningen van vandaag al in onze app genoteerd?', title_pl = 'Kontrola trawienia ⏱️', body_pl = 'Śledzenie dziennego zużycia pieluszek pokazuje, jak dobrze się odżywia. Zapisałaś dzisiejsze przewijania w naszej aplikacji?', title_pt = 'Verificação do intestino ⏱️', body_pt = 'Acompanhar as fraldas gastas por dia mostra a qualidade da alimentação. Já registou na nossa app as mudas de hoje?', title_sv = 'Kontroll av mage och tarm ⏱️', body_sv = 'Att följa den dagliga blöjförbrukningen visar kvaliteten på matningen. Har du antecknat dagens blöjbyten i appen?', title_vi = 'Kiểm tra tiêu hóa ⏱️', body_vi = 'Theo dõi số tã dùng mỗi ngày cho biết chất lượng bữa ăn của bé. Mẹ đã ghi lại những lần thay tã hôm nay vào ứng dụng chưa?', title_zh = '肠胃检查 ⏱️', body_zh = '记录每天的尿布用量能反映喂养的质量。今天换尿布的情况记到应用里了吗？' WHERE id = '5124c8a0-ed5f-4aa8-8203-12fc951409c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mesa en familia 🍲', body_es = '¿Qué le darás de cenar? En las recetas de alimentación complementaria hay ideas de platos sanos para compartir que le encantarán a toda la familia.', title_fr = 'Le repas en famille 🍲', body_fr = 'Qu''allez-vous lui donner au dîner ? Les recettes de diversification proposent des idées de plats sains à partager que toute la famille aimera.', title_hi = 'परिवार की खाने की मेज़ 🍲', body_hi = 'रात के खाने में उसे क्या देंगी? ऊपरी आहार की रेसिपी में ऐसे सेहतमंद आइडिया हैं जिन्हें पूरा परिवार मिलकर चाव से खाएगा।', title_id = 'Meja makan keluarga 🍲', body_id = 'Mau memberinya apa untuk makan malam? Di resep MPASI ada ide hidangan sehat untuk bersama yang akan disukai seluruh keluarga.', title_ja = '家族の食卓 🍲', body_ja = '夕食は何にしますか？離乳食レシピには、家族みんなでおいしく食べられる、ヘルシーな共通メニューのアイデアがあります。', title_ko = '가족 식탁 🍲', body_ko = '저녁에 아이에게 무엇을 줄 건가요? 이유식 레시피에 온 가족이 즐겁게 먹을 수 있는 건강한 공동 메뉴 아이디어가 있어요.', title_nl = 'Aan de gezinstafel 🍲', body_nl = 'Wat geef je hem vanavond te eten? In de recepten voor bijvoeding staan gezonde ideeën die het hele gezin graag samen eet.', title_pl = 'Rodzinny stół 🍲', body_pl = 'Co mu dasz na kolację? W przepisach na rozszerzanie diety znajdziesz wspólne, zdrowe pomysły na dania, które z chęcią zje cała rodzina.', title_pt = 'A mesa da família 🍲', body_pt = 'O que lhe vai dar ao jantar? Nas receitas de diversificação alimentar há ideias de refeições saudáveis para partilhar, que toda a família vai adorar.', title_sv = 'Familjebordet 🍲', body_sv = 'Vad ska barnet få till middag? I recepten för fast föda finns gemensamma och nyttiga matidéer som hela familjen gillar.', title_vi = 'Mâm cơm gia đình 🍲', body_vi = 'Bữa tối mẹ sẽ cho bé ăn gì? Trong các công thức ăn dặm có những ý tưởng món ăn lành mạnh mà cả nhà đều thích.', title_zh = '家庭餐桌 🍲', body_zh = '晚饭给他吃什么？辅食食谱里有全家都爱吃的、健康的共享菜点子。' WHERE id = '9c188bf4-4509-4c22-a2b7-a1a25cc28562' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu historia como madre 📝', body_es = 'La historia de cada madre es única. Lee en nuestro Blog experiencias e historias reales de otras mamás e inspírate.', title_fr = 'Votre histoire de maman 📝', body_fr = 'L''histoire de chaque maman est unique. Lisez dans nos Blogs les expériences et histoires réelles d''autres mamans et trouvez l''inspiration.', title_hi = 'आपकी माँ बनने की कहानी 📝', body_hi = 'हर माँ की कहानी अनोखी होती है। हमारे ब्लॉग में दूसरी माँओं के असली अनुभव और कहानियाँ पढ़िए और प्रेरणा लीजिए।', title_id = 'Kisah keibuan Anda 📝', body_id = 'Kisah setiap ibu itu unik. Baca pengalaman dan kisah nyata ibu-ibu lain di Blog kami dan dapatkan inspirasi.', title_ja = 'あなたの子育てストーリー 📝', body_ja = 'ママの物語は一人ひとりちがいます。ブログでほかのママたちのリアルな体験やストーリーを読んで、元気をもらいましょう。', title_ko = '엄마의 이야기 📝', body_ko = '모든 엄마의 이야기는 저마다 특별해요. 블로그에서 다른 엄마들의 진짜 경험과 이야기를 읽으며 영감을 얻어 보세요.', title_nl = 'Jouw moederschapsverhaal 📝', body_nl = 'Het verhaal van elke moeder is uniek. Lees in onze Blogs de echte ervaringen en verhalen van andere moeders en laat je inspireren.', title_pl = 'Twoja historia macierzyństwa 📝', body_pl = 'Historia każdej mamy jest wyjątkowa. Przeczytaj na naszych Blogach prawdziwe doświadczenia i historie innych mam i zainspiruj się.', title_pt = 'A sua história de mãe 📝', body_pt = 'A história de cada mãe é única. Leia nos nossos Blogues as experiências e histórias reais de outras mães e inspire-se.', title_sv = 'Din mammaberättelse 📝', body_sv = 'Varje mammas berättelse är unik. Läs andra mammors verkliga erfarenheter och berättelser i Bloggar och bli inspirerad.', title_vi = 'Câu chuyện làm mẹ của bạn 📝', body_vi = 'Câu chuyện của mỗi người mẹ đều độc nhất. Hãy đọc những trải nghiệm và câu chuyện thật của các mẹ khác trong mục Blog để có thêm cảm hứng.', title_zh = '你的妈妈故事 📝', body_zh = '每位妈妈的故事都独一无二。读读我们博客里其他妈妈的真实经历和故事，获得灵感吧。' WHERE id = 'dab8f6cb-2ef5-454d-85b6-120c0f7644eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Carreras en el parque 👟', body_es = 'Después de los primeros pasos, empiezan las carreras. Para elegir sus primeros zapatos, mira los modelos saludables de Productos recomendados.', title_fr = 'Courir au parc 👟', body_fr = 'Après les premiers pas viennent les courses. Pour choisir ses premières chaussures, regardez les modèles adaptés dans les Produits recommandés.', title_hi = 'पार्क में दौड़ 👟', body_hi = 'पहले कदमों के बाद दौड़ शुरू होती है। पहले जूते चुनने के लिए सुझाए गए प्रोडक्ट सेक्शन में सेहतमंद मॉडल देखिए।', title_id = 'Berlari di taman 👟', body_id = 'Setelah langkah pertama, dimulailah lari-lari kecil. Untuk memilih sepatu pertama, lihat model-model yang sehat di bagian Produk Rekomendasi.', title_ja = '公園でかけっこ 👟', body_ja = 'はじめの一歩のあとは、走る時期がやってきます。はじめての靴選びには、「おすすめ商品」で足にやさしいモデルを見てみましょう。', title_ko = '공원에서 달리기 👟', body_ko = '첫걸음을 떼고 나면 달리기가 시작돼요. 첫 신발은 추천 제품 섹션의 발 건강에 좋은 모델에서 골라 보세요.', title_nl = 'Rennen in het park 👟', body_nl = 'Na de eerste stapjes begint het rennen. Bekijk voor de eerste schoentjes de gezonde modellen in het onderdeel Aanbevolen producten.', title_pl = 'Bieganie po parku 👟', body_pl = 'Po pierwszych krokach zaczyna się bieganie. Wybierając pierwsze buty, zajrzyj do zdrowych modeli w sekcji Polecane produkty.', title_pt = 'Corridas no parque 👟', body_pt = 'Depois dos primeiros passos, começam as corridas. Para escolher os primeiros sapatos, veja os modelos saudáveis na secção Produtos Recomendados.', title_sv = 'Springa i parken 👟', body_sv = 'Efter de första stegen börjar springet. Titta på hälsosamma modeller av första skor i avsnittet Rekommenderade produkter.', title_vi = 'Chạy nhảy ở công viên 👟', body_vi = 'Sau những bước đi đầu tiên là những bước chạy. Hãy xem những mẫu giày tốt cho đôi giày đầu tiên của bé trong mục Sản phẩm gợi ý.', title_zh = '在公园里奔跑 👟', body_zh = '迈出第一步之后，就开始跑了。选第一双鞋时，看看推荐商品里的健康款式吧。' WHERE id = '2522685d-511e-40e4-ab2a-4b34a238936c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma en la habitación 🌊', body_es = '¿Hoy le cuesta dormirse? Pon el sonido de las olas del mar en Ruido blanco para calmar su sistema nervioso y facilitar el paso al sueño.', title_fr = 'Le calme dans la chambre 🌊', body_fr = 'Difficile de s''endormir aujourd''hui ? Lancez les vagues de l''océan dans les Bruits blancs pour apaiser son système nerveux et faciliter l''endormissement.', title_hi = 'कमरे में सुकून 🌊', body_hi = 'आज सोना मुश्किल हो रहा है? व्हाइट नॉइज़ से समुद्र की लहरों की आवाज़ चलाइए, नर्वस सिस्टम को शांत करके नींद में जाना आसान बनाइए।', title_id = 'Ketenangan di kamar 🌊', body_id = 'Hari ini sulit tertidur? Putar suara ombak laut dari Suara Putih untuk menenangkan sistem saraf dan mempermudah peralihan ke tidur.', title_ja = '部屋に安らぎを 🌊', body_ja = '今日は寝つきが悪い？「ホワイトノイズ」から波の音を流して、神経を落ち着かせ、眠りへの切りかえを楽にしましょう。', title_ko = '방 안의 평온 🌊', body_ko = '오늘은 잠들기 힘든가요? 백색소음에서 파도 소리를 틀어 신경계를 진정시키고 잠드는 걸 도와주세요.', title_nl = 'Rust in de kamer 🌊', body_nl = 'Is in slaap vallen vandaag moeilijk? Zet in Witte ruis het geluid van de oceaangolven aan, zo kalmeert zijn zenuwstelsel en valt hij makkelijker in slaap.', title_pl = 'Spokój w pokoju 🌊', body_pl = 'Dziś trudno zasnąć? Włącz w Białym szumie dźwięk fal oceanu, który wyciszy układ nerwowy i ułatwi zasypianie.', title_pt = 'Tranquilidade no quarto 🌊', body_pt = 'Hoje está difícil adormecer? Ligue o som das ondas do mar no Ruído Branco: acalma o sistema nervoso e facilita a passagem para o sono.', title_sv = 'Lugn i rummet 🌊', body_sv = 'Är det svårt att somna i dag? Sätt på havsvågor i Vitt brus, som lugnar nervsystemet och gör insomnandet lättare.', title_vi = 'Bình yên trong phòng 🌊', body_vi = 'Hôm nay bé khó vào giấc? Hãy bật tiếng sóng biển trong Tiếng ồn trắng để làm dịu hệ thần kinh và giúp bé vào giấc dễ dàng hơn.', title_zh = '房间里的宁静 🌊', body_zh = '今天很难入睡？在白噪音里放海浪声，安抚神经系统，让入睡更轻松。' WHERE id = '4b619580-dcf5-4c3a-a584-37bd74dfbaba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal las proteínas? 🍗', body_es = '¡Las proteínas son imprescindibles para su crecimiento! Mide el equilibrio de su alimentación diaria con el Seguimiento de tomas y completa lo que falte.', title_fr = 'Et les protéines ? 🍗', body_fr = 'Les protéines sont indispensables à sa croissance ! Mesurez l''équilibre de son alimentation du jour avec le Suivi des repas et comblez les manques.', title_hi = 'प्रोटीन कितना मिल रहा है? 🍗', body_hi = 'बच्चे की बढ़त के लिए प्रोटीन ज़रूरी है! फ़ीडिंग ट्रैकर से उसके रोज़ के खाने का संतुलन देखिए और कमियाँ पूरी कीजिए।', title_id = 'Bagaimana asupan proteinnya? 🍗', body_id = 'Protein itu wajib untuk pertumbuhan anak! Ukur keseimbangan makanan hariannya dengan alat Pemantau Makan dan lengkapi kekurangannya.', title_ja = 'たんぱく質は足りている？🍗', body_ja = '子どもの成長にたんぱく質は欠かせません！「栄養管理ツール」で毎日の栄養バランスを確認して、足りないものを補いましょう。', title_ko = '단백질은 충분한가요? 🍗', body_ko = '아이의 성장에는 단백질이 꼭 필요해요! 수유 기록 도구로 하루 영양 균형을 확인하고 부족한 부분을 채워 주세요.', title_nl = 'Hoe zit het met de eiwitten? 🍗', body_nl = 'Eiwit is onmisbaar voor de groei van je kindje! Meet zijn dagelijkse voedingsbalans met de Voedingstracker en vul aan wat ontbreekt.', title_pl = 'Jak tam zapas białka? 🍗', body_pl = 'Białko jest niezbędne do wzrostu dziecka! Sprawdź w narzędziu do śledzenia karmienia jego dzienny bilans żywieniowy i uzupełnij braki.', title_pt = 'Como está a reserva de proteína? 🍗', body_pt = 'A proteína é essencial para o crescimento da criança! Meça o equilíbrio alimentar diário dele com o Registo de Alimentação e complete o que faltar.', title_sv = 'Hur går det med proteinet? 🍗', body_sv = 'Protein är en förutsättning för barnets tillväxt! Mät det dagliga näringsintaget med Matningskoll och fyll i det som saknas.', title_vi = 'Lượng protein thế nào rồi? 🍗', body_vi = 'Protein là điều kiện cần cho sự phát triển của bé! Hãy đo sự cân bằng dinh dưỡng hằng ngày bằng công cụ Theo dõi cữ bú và bổ sung những gì còn thiếu.', title_zh = '蛋白质够吗？🍗', body_zh = '蛋白质是孩子成长的必需！用喂养记录工具衡量他每天的饮食均衡，补上不足的部分吧。' WHERE id = '7ae22b42-7e16-455e-8d98-b410c2cd5c7a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Temporizador de sueño activado? ⏳', body_es = '¿Empiezas a dormirle? Activa el temporizador, analiza cuánto tarda en dormirse y descubre cómo mejorar esta rutina.', title_fr = 'Le minuteur de sommeil est lancé ? ⏳', body_fr = 'Vous commencez le coucher ? Lancez le minuteur et analysez le temps d''endormissement pour savoir comment améliorer ce rituel.', title_hi = 'स्लीप टाइमर चालू है? ⏳', body_hi = 'सुलाना शुरू कर रही हैं? टाइमर चालू कीजिए और नींद में जाने के समय का विश्लेषण करके जानिए कि इस रूटीन को कैसे बेहतर बनाएँ।', title_id = 'Timer Tidur sudah aktif? ⏳', body_id = 'Mulai menidurkannya? Nyalakan timer, analisis berapa lama ia beralih ke tidur, dan pelajari cara menyempurnakan rutinitasnya.', title_ja = '睡眠タイマーはオンになっている？⏳', body_ja = '寝かしつけを始めますか？タイマーをオンにして、寝つくまでの時間を分析し、習慣をどう改善できるか知りましょう。', title_ko = '수면 타이머 켰나요? ⏳', body_ko = '재우기를 시작하나요? 타이머를 켜고 잠드는 데 걸리는 시간을 분석해 루틴을 어떻게 개선할지 알아보세요.', title_nl = 'Staat de Slaaptimer aan? ⏳', body_nl = 'Ga je je kindje in slaap brengen? Zet de timer aan, analyseer hoe lang het inslapen duurt en ontdek hoe je deze routine kunt verbeteren.', title_pl = 'Timer snu włączony? ⏳', body_pl = 'Zaczynasz usypianie? Włącz timer, przeanalizuj, ile trwa zasypianie, i dowiedz się, jak udoskonalić tę rutynę.', title_pt = 'O temporizador de sono está ativo? ⏳', body_pt = 'Vai começar a adormecê-lo? Ligue o temporizador, analise quanto tempo demora a adormecer e descubra como melhorar esta rotina.', title_sv = 'Är sömntimern aktiv? ⏳', body_sv = 'Ska du börja nattningen? Starta timern, analysera hur lång tid insomnandet tar och lär dig hur du kan förbättra rutinen.', title_vi = 'Bộ hẹn giờ ngủ đã bật chưa? ⏳', body_vi = 'Mẹ bắt đầu ru bé ngủ? Hãy bật bộ hẹn giờ, phân tích thời gian bé vào giấc và tìm cách hoàn thiện nếp sinh hoạt này.', title_zh = '睡眠计时器开了吗？⏳', body_zh = '要开始哄睡了？打开计时器，分析入睡用了多久，学学怎样改进这个睡前程序。' WHERE id = '2c591870-5eb2-4029-b209-ea812c8276ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recarga energía 🔋', body_es = '¿Lista para el ajetreo del día? Elige en Recetas saludables para mujeres un desayuno rico y lleno de vitaminas.', title_fr = 'Faites le plein d''énergie 🔋', body_fr = 'Prête pour le tourbillon de la journée ? Choisissez-vous un petit-déjeuner savoureux et plein de vitamines dans les Recettes saines pour femmes.', title_hi = 'ऊर्जा जमा कीजिए 🔋', body_hi = 'दिन की भागदौड़ के लिए तैयार हैं? महिलाओं के लिए सेहतमंद रेसिपी से अपने लिए स्वादिष्ट और विटामिन भरा नाश्ता चुनिए।', title_id = 'Kumpulkan energi 🔋', body_id = 'Siap menghadapi kesibukan hari ini? Pilih sarapan lezat kaya vitamin untuk diri sendiri dari Resep Sehat untuk wanita.', title_ja = 'エネルギーをためよう 🔋', body_ja = '今日の慌ただしさへの準備はできましたか？「女性のためのヘルシーレシピ」から、おいしくてビタミンたっぷりの朝食を選びましょう。', title_ko = '에너지를 모아요 🔋', body_ko = '바쁜 하루를 맞을 준비가 됐나요? 건강한 레시피에서 맛있고 비타민 가득한 아침 식사를 골라 보세요.', title_nl = 'Laad je energie op 🔋', body_nl = 'Klaar voor de drukte van de dag? Kies uit Gezonde recepten voor vrouwen een lekker ontbijt vol vitaminen voor jezelf.', title_pl = 'Naładuj baterie 🔋', body_pl = 'Gotowa na dzienną bieganinę? Wybierz sobie ze Zdrowych przepisów dla kobiet smaczne śniadanie pełne witamin.', title_pt = 'Ganhe energia 🔋', body_pt = 'Está pronta para a correria do dia? Escolha nas Receitas Saudáveis para Mulheres um pequeno-almoço delicioso e cheio de vitaminas para si.', title_sv = 'Samla energi 🔋', body_sv = 'Är du redo för dagens stress? Välj en god och vitaminrik frukost åt dig själv från Hälsosamma recept för kvinnor.', title_vi = 'Nạp năng lượng 🔋', body_vi = 'Mẹ sẵn sàng cho một ngày bận rộn chưa? Hãy chọn cho mình một bữa sáng ngon miệng, giàu vitamin từ Công thức lành mạnh cho phụ nữ.', title_zh = '积攒能量 🔋', body_zh = '准备好迎接一天的忙碌了吗？从女性健康食谱里给自己选一份美味又富含维生素的早餐吧。' WHERE id = 'fb78ab52-3c7a-4706-adfa-55485f38dc6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de comodidad 🍼', body_es = '¿Buscas el mejor vaso antiderrame para su independencia? Mira en Productos recomendados las opciones favoritas de otras mamás.', title_fr = 'En quête de confort 🍼', body_fr = 'Vous cherchez la meilleure gourde anti-fuite pour son autonomie ? Découvrez les modèles préférés des mamans dans les Produits recommandés.', title_hi = 'आराम की तलाश में 🍼', body_hi = 'उसकी आत्मनिर्भरता के लिए सबसे अच्छा न छलकने वाला सिपी कप ढूँढ रही हैं? सुझाए गए प्रोडक्ट सेक्शन में माँओं के सबसे पसंदीदा विकल्प देखिए।', title_id = 'Mencari kenyamanan 🍼', body_id = 'Mencari botol minum anti tumpah terbaik untuk kemandiriannya? Lihat pilihan favorit para ibu di bagian Produk Rekomendasi.', title_ja = '快適さを求めて 🍼', body_ja = '自分で飲めるよう、こぼれにくいマグを探していますか？「おすすめ商品」で、ママたちにいちばん人気の商品を見てみましょう。', title_ko = '편안함을 찾아서 🍼', body_ko = '아이가 혼자 쓸 수 있는 가장 좋은 새지 않는 물병을 찾고 있나요? 추천 제품 섹션에서 엄마들이 가장 좋아하는 제품을 확인하세요.', title_nl = 'Op zoek naar gemak 🍼', body_nl = 'Op zoek naar de beste lekvrije drinkbeker voor zijn zelfstandigheid? Bekijk in het onderdeel Aanbevolen producten de keuzes die moeders het leukst vinden.', title_pl = 'W poszukiwaniu wygody 🍼', body_pl = 'Szukasz najlepszego niewylewającego kubka, który wesprze jego samodzielność? Zobacz w sekcji Polecane produkty opcje, które mamy lubią najbardziej.', title_pt = 'Em busca de conforto 🍼', body_pt = 'Procura o melhor copo antiderrame para a independência dele? Veja na secção Produtos Recomendados as opções preferidas das mães.', title_sv = 'På jakt efter bekvämlighet 🍼', body_sv = 'Letar du efter den bästa spillfria pipmuggen för barnets självständighet? Titta på mammornas favoriter i avsnittet Rekommenderade produkter.', title_vi = 'Tìm kiếm sự tiện lợi 🍼', body_vi = 'Mẹ đang tìm chiếc bình tập uống chống tràn tốt nhất để bé tự lập? Hãy xem những lựa chọn được các mẹ yêu thích nhất trong mục Sản phẩm gợi ý.', title_zh = '寻找更方便的选择 🍼', body_zh = '在找一款最好的防漏水杯，让他更独立？看看推荐商品里妈妈们最喜欢的选择吧。' WHERE id = '543206e3-a734-4c0f-89e0-a5bb0b8f6100' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Tú puedes! 💪', body_es = '¿Ha sido un día difícil? Escucha tu voz interior en el Diario de ánimo. Recuerda: es solo un día difícil, no una vida mala.', title_fr = 'Vous y arriverez ! 💪', body_fr = 'Journée difficile ? Écoutez votre voix intérieure dans le Journal d''humeur. N''oubliez pas, c''est juste une journée difficile, pas une vie difficile.', title_hi = 'आप कर सकती हैं! 💪', body_hi = 'आज का दिन मुश्किल रहा? मूड डायरी में अपने मन की आवाज़ सुनिए। याद रखिए, यह बस एक मुश्किल दिन है, बुरी ज़िंदगी नहीं।', title_id = 'Anda pasti bisa! 💪', body_id = 'Hari Anda berat? Dengarkan suara hati Anda di Buku Harian Suasana Hati. Ingat, ini hanya hari yang sulit, bukan hidup yang buruk.', title_ja = 'あなたならできる！💪', body_ja = '大変な一日でしたか？「気分日記」で自分の心の声に耳を傾けましょう。忘れないで。これはただ大変な一日であって、悪い人生ではありません。', title_ko = '당신은 할 수 있어요! 💪', body_ko = '힘든 하루였나요? 기분 일기에서 내 마음의 소리에 귀 기울여 보세요. 잊지 마세요, 그저 힘든 하루일 뿐 나쁜 인생이 아니에요.', title_nl = 'Je kunt het! 💪', body_nl = 'Was het een zware dag? Luister in je Stemmingsdagboek naar je innerlijke stem. Onthoud: dit is gewoon een zware dag, geen slecht leven.', title_pl = 'Dasz radę! 💪', body_pl = 'Miałaś trudny dzień? Wsłuchaj się w swój wewnętrzny głos w Dzienniku nastroju. Pamiętaj, to tylko trudny dzień, a nie złe życie.', title_pt = 'Consegue! 💪', body_pt = 'O seu dia foi difícil? Escute a sua voz interior no Diário de Humor. Lembre-se: foi só um dia difícil, não uma vida má.', title_sv = 'Du klarar det! 💪', body_sv = 'Har du haft en tuff dag? Lyssna på din inre röst i Humördagboken. Kom ihåg att det bara är en tuff dag, inte ett dåligt liv.', title_vi = 'Mẹ làm được mà! 💪', body_vi = 'Hôm nay thật khó khăn? Hãy lắng nghe tiếng nói bên trong mình qua Nhật ký tâm trạng. Hãy nhớ rằng đây chỉ là một ngày khó khăn, không phải một cuộc đời tồi tệ.', title_zh = '你一定可以！💪', body_zh = '今天过得很辛苦？在心情日记里听听内心的声音。记住，这只是辛苦的一天，而不是糟糕的人生。' WHERE id = '70ce55d5-f110-4637-a672-3efae4b7e852' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Informe de alimentación 📊', body_es = 'Introduce lo que ha comido hoy tu peque en el Seguimiento de tomas. ¿Habrá tomado hoy todas las vitaminas que necesita?', title_fr = 'Le bilan des repas 📊', body_fr = 'Saisissez ce que votre enfant a mangé aujourd''hui dans le Suivi des repas. Voyons s''il a bien eu toutes les vitamines nécessaires !', title_hi = 'पोषण की रिपोर्ट 📊', body_hi = 'बच्चे का आज का खाना फ़ीडिंग ट्रैकर में दर्ज कीजिए। देखें, क्या आज उसे ज़रूरी विटामिन पूरे मिले?', title_id = 'Laporan makan 📊', body_id = 'Masukkan asupan makan si kecil hari ini ke alat Pemantau Makan. Mari lihat apakah ia sudah mendapat semua vitamin yang dibutuhkan hari ini.', title_ja = '食事のレポート 📊', body_ja = '今日の食事を「栄養管理ツール」に入力しましょう。必要なビタミンをしっかりとれたか、確かめてみましょう！', title_ko = '식사 리포트 📊', body_ko = '오늘 아이가 먹은 것을 수유 기록 도구에 입력해 보세요. 오늘 필요한 비타민을 충분히 섭취했는지 확인해 봐요.', title_nl = 'Voedingsverslag 📊', body_nl = 'Voer de voeding van je kindje van vandaag in de Voedingstracker in. Eens kijken of hij vandaag alle nodige vitaminen heeft gekregen!', title_pl = 'Raport karmienia 📊', body_pl = 'Wpisz dzisiejsze posiłki dziecka do narzędzia do śledzenia karmienia. Sprawdźmy, czy dostało dziś wszystkie potrzebne witaminy!', title_pt = 'O balanço da alimentação 📊', body_pt = 'Introduza no Registo de Alimentação o que o seu filho comeu hoje. Vamos ver se recebeu todas as vitaminas de que precisa?', title_sv = 'Matrapport 📊', body_sv = 'Lägg in barnets mat för dagen i Matningskoll. Ska vi se om barnet fick i sig alla vitaminer det behöver i dag?', title_vi = 'Báo cáo ăn uống 📊', body_vi = 'Hãy nhập bữa ăn hôm nay của bé vào công cụ Theo dõi cữ bú. Cùng xem hôm nay bé đã nhận đủ vitamin cần thiết chưa nhé?', title_zh = '喂养报告 📊', body_zh = '把宝宝今天吃的东西录入喂养记录工具。看看今天需要的维生素是不是都吃够了？' WHERE id = '787e9318-ea30-497d-9a1a-d3de64060a9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Respira hondo ✨', body_es = 'No hace falta que todo sea perfecto. ¡Ya eres la mejor madre! Suelta el estrés del día en el Diario de ánimo y descansa.', title_fr = 'Respirez profondément ✨', body_fr = 'Tout n''a pas besoin d''être parfait. Vous êtes déjà la meilleure des mamans ! Évacuez le stress de la journée dans le Journal d''humeur et reposez-vous.', title_hi = 'गहरी साँस लीजिए ✨', body_hi = 'हर चीज़ का परफ़ेक्ट होना ज़रूरी नहीं। आप पहले से ही सबसे अच्छी माँ हैं! मूड डायरी में दिन का तनाव निकालिए और आराम कीजिए।', title_id = 'Tarik napas dalam-dalam ✨', body_id = 'Tidak semuanya harus sempurna. Anda sudah menjadi ibu terbaik! Lepaskan stres hari ini di Buku Harian Suasana Hati dan beristirahatlah.', title_ja = '深呼吸しましょう ✨', body_ja = 'すべてが完璧でなくていいのです。あなたはもう最高のママです！「気分日記」で一日のストレスを手放して、休みましょう。', title_ko = '깊게 숨을 쉬어 보세요 ✨', body_ko = '모든 게 완벽할 필요는 없어요. 당신은 이미 최고의 엄마예요! 기분 일기에 하루의 스트레스를 털어 내고 쉬세요.', title_nl = 'Haal diep adem ✨', body_nl = 'Niet alles hoeft perfect te zijn. Je bent nu al de beste mama! Laat de stress van de dag los in je Stemmingsdagboek en rust uit.', title_pl = 'Weź głęboki oddech ✨', body_pl = 'Nie wszystko musi być idealne. I tak jesteś najlepszą mamą! Zrzuć stres dnia w Dzienniku nastroju i odpocznij.', title_pt = 'Respire fundo ✨', body_pt = 'Não é preciso que tudo seja perfeito. Já é a melhor mãe! Liberte no Diário de Humor o stress do dia e descanse.', title_sv = 'Ta ett djupt andetag ✨', body_sv = 'Allt behöver inte vara perfekt. Du är redan den bästa mamman! Släpp dagens stress i Humördagboken och vila.', title_vi = 'Hãy hít thở thật sâu ✨', body_vi = 'Không cần mọi thứ phải hoàn hảo. Mẹ đã là người mẹ tuyệt vời nhất rồi! Hãy trút bỏ căng thẳng trong ngày vào Nhật ký tâm trạng và nghỉ ngơi nhé.', title_zh = '深呼吸 ✨', body_zh = '不需要一切都完美。你本来就是最好的妈妈！在心情日记里卸下一天的压力，休息一下吧。' WHERE id = '0d93db4a-8b6f-404c-af2e-d97c0d79adf5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Ha pegado un estirón? 🦒', body_es = '¿Notas que la ropa le queda justa? Introduce sus nuevas medidas en el Seguimiento del desarrollo y mira cómo sube su gráfica de crecimiento.', title_fr = 'Il a grandi ? 🦒', body_fr = 'Ses vêtements commencent à le serrer ? Saisissez les nouveaux chiffres dans le Suivi de croissance et voyez comment sa courbe monte.', title_hi = 'लंबाई बढ़ गई? 🦒', body_hi = 'महसूस हो रहा है कि कपड़े तंग हो गए हैं? ग्रोथ ट्रैकर में नए आँकड़े डालिए और देखिए कि बढ़त का चार्ट कैसे ऊपर जा रहा है।', title_id = 'Makin tinggi? 🦒', body_id = 'Bajunya terasa makin sempit? Masukkan angka terbarunya di Pelacak Pertumbuhan dan lihat bagaimana grafik pertumbuhannya naik.', title_ja = '背が伸びた？🦒', body_ja = 'お洋服がきつくなってきましたか？「発達トラッカー」に新しい数値を入れて、成長グラフの伸びを確認しましょう。', title_ko = '키가 자랐나요? 🦒', body_ko = '옷이 꽉 끼는 것 같나요? 성장 기록에 새 수치를 입력하고 성장 그래프가 얼마나 올라갔는지 확인하세요.', title_nl = 'Is hij gegroeid? 🦒', body_nl = 'Merk je dat zijn kleertjes krap worden? Voer de nieuwe cijfers in de Groeitracker in en kijk hoe zijn groeicurve stijgt.', title_pl = 'Urósł? 🦒', body_pl = 'Ubranka zrobiły się ciasne? Wpisz nowe liczby w Śledzeniu rozwoju i sprawdź, jak pnie się wykres wzrostu.', title_pt = 'Está mais alto? 🦒', body_pt = 'Sente que a roupa está a ficar apertada? Introduza os novos números no Registo de Desenvolvimento e veja como sobe o gráfico de crescimento.', title_sv = 'Har barnet blivit längre? 🦒', body_sv = 'Känns kläderna trånga? Skriv in de nya siffrorna i Tillväxtspåraren och se hur tillväxtkurvan stiger.', title_vi = 'Bé cao lên rồi? 🦒', body_vi = 'Mẹ thấy quần áo của bé chật dần? Hãy nhập số đo mới vào Theo dõi phát triển và xem biểu đồ tăng trưởng đi lên thế nào.', title_zh = '长高了？🦒', body_zh = '感觉他的衣服变紧了？在发育追踪里输入新的数字，看看成长曲线是怎么上升的吧。' WHERE id = 'c34d441d-5c3c-48a4-9477-974b42412b6e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cantidades de alimentación 🥣', body_es = '¿Hoy ha tomado suficientes proteínas? Analiza su menú del día con el Seguimiento de tomas y completa lo que falte.', title_fr = 'Les besoins alimentaires 🥣', body_fr = 'A-t-il eu assez de protéines aujourd''hui ? Analysez son menu du jour avec le Suivi des repas et comblez les manques.', title_hi = 'पोषण का मानक 🥣', body_hi = 'आज उसे पर्याप्त प्रोटीन मिला? फ़ीडिंग ट्रैकर से बच्चे के रोज़ के मेन्यू का विश्लेषण कीजिए और कमियाँ पूरी कीजिए।', title_id = 'Porsi makan 🥣', body_id = 'Apakah hari ini ia cukup mendapat protein? Analisis menu harian si kecil dengan alat Pemantau Makan dan lengkapi kekurangannya.', title_ja = '食事の目安 🥣', body_ja = '今日はたんぱく質を十分にとれましたか？「栄養管理ツール」で毎日のメニューを分析して、足りないものを補いましょう。', title_ko = '하루 섭취량 🥣', body_ko = '오늘 단백질은 충분히 먹었나요? 수유 기록 도구로 아이의 하루 식단을 분석해 부족한 부분을 채워 주세요.', title_nl = 'Voedingsnorm 🥣', body_nl = 'Heeft je kindje vandaag genoeg eiwit gekregen? Analyseer zijn dagmenu met de Voedingstracker en vul aan wat ontbreekt.', title_pl = 'Norma żywienia 🥣', body_pl = 'Czy dostał dziś wystarczająco białka? Przeanalizuj dzienne menu dziecka w narzędziu do śledzenia karmienia i uzupełnij braki.', title_pt = 'A quantidade diária de alimentação 🥣', body_pt = 'Hoje comeu proteína suficiente? Analise a ementa diária do seu bebé com o Registo de Alimentação e complete o que faltar.', title_sv = 'Matnorm 🥣', body_sv = 'Fick barnet tillräckligt med protein i dag? Analysera barnets dagliga meny med Matningskoll och fyll i det som saknas.', title_vi = 'Định mức ăn uống 🥣', body_vi = 'Hôm nay bé đã nạp đủ protein chưa? Hãy phân tích thực đơn hằng ngày của bé bằng công cụ Theo dõi cữ bú và bổ sung những gì còn thiếu.', title_zh = '每日饮食参考量 🥣', body_zh = '今天蛋白质吃够了吗？用喂养记录工具分析宝宝每天的饮食，补上不足的部分吧。' WHERE id = 'd37162b5-bdeb-4abc-8206-52d2382cc6de' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un sonido que calma 🌧️', body_es = '¿La emoción del día no le deja dormir? Elige el sonido de la lluvia en Ruido blanco y ayuda a su sistema nervioso a calmarse de forma natural.', title_fr = 'Un son apaisant 🌧️', body_fr = 'Trop excité par la journée pour dormir ? Choisissez le bruit de la pluie dans les Bruits blancs pour aider son système nerveux à se calmer naturellement.', title_hi = 'शांत करने वाली आवाज़ 🌧️', body_hi = 'दिन के उत्साह से सो नहीं पा रहा? व्हाइट नॉइज़ में बारिश की आवाज़ चुनिए और उसके नर्वस सिस्टम को स्वाभाविक रूप से शांत होने में मदद कीजिए।', title_id = 'Suara yang menenangkan 🌧️', body_id = 'Ia tidak bisa tidur karena terlalu bersemangat hari ini? Pilih suara hujan di Suara Putih dan bantu sistem sarafnya tenang secara alami.', title_ja = '心落ち着く音 🌧️', body_ja = '一日の興奮で寝つけない？「ホワイトノイズ」から雨の音を選んで、自然に神経が落ち着くのを助けてあげましょう。', title_ko = '마음을 달래 주는 소리 🌧️', body_ko = '하루의 설렘 때문에 잠들지 못하나요? 백색소음에서 빗소리를 골라 신경계가 자연스럽게 진정되도록 도와주세요.', title_nl = 'Rustgevend geluid 🌧️', body_nl = 'Kan je kindje niet slapen van de opwinding van de dag? Kies het geluid van regen in Witte ruis en help zijn zenuwstelsel op een natuurlijke manier tot rust te komen.', title_pl = 'Kojący dźwięk 🌧️', body_pl = 'Z emocji całego dnia nie może zasnąć? Wybierz w Białym szumie odgłos deszczu i pomóż jego układowi nerwowemu naturalnie się wyciszyć.', title_pt = 'Um som calmante 🌧️', body_pt = 'Não consegue dormir com a agitação do dia? Escolha o som da chuva no Ruído Branco e ajude o sistema nervoso dele a acalmar de forma natural.', title_sv = 'Lugnande ljud 🌧️', body_sv = 'Kan barnet inte sova efter dagens spänning? Välj regnljud i Vitt brus och hjälp nervsystemet att lugna sig på ett naturligt sätt.', title_vi = 'Âm thanh êm dịu 🌧️', body_vi = 'Bé không ngủ được vì còn phấn khích sau một ngày? Hãy chọn tiếng mưa trong Tiếng ồn trắng để giúp hệ thần kinh của bé dịu lại một cách tự nhiên.', title_zh = '舒缓的声音 🌧️', body_zh = '白天太兴奋睡不着？在白噪音里选雨声，帮助他的神经系统自然地平静下来。' WHERE id = '06c24f98-8519-42a4-86d5-14e6b430bf94' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que hoy sea diferente 🌟', body_es = '¿Agobiada de la rutina de casa? Abre el mapa de Lugares para mamás y encuentra una cafetería nueva donde estar a gusto con tu peque.', title_fr = 'Une journée différente aujourd''hui 🌟', body_fr = 'La routine de la maison vous pèse ? Ouvrez notre carte des Lieux adaptés aux mamans et trouvez un nouveau café où vous installer confortablement avec bébé.', title_hi = 'आज कुछ अलग हो 🌟', body_hi = 'घर के रूटीन से ऊब गई हैं? हमारा माँ के लिए अनुकूल जगहों का नक्शा खोलिए और कोई नया कैफ़े ढूँढिए जहाँ बच्चे के साथ आराम से बैठ सकें।', title_id = 'Jadikan hari ini berbeda 🌟', body_id = 'Bosan dengan rutinitas di rumah? Buka peta Tempat Ramah Ibu dan temukan kafe baru tempat Anda bisa duduk nyaman bersama si kecil.', title_ja = '今日はいつもとちがう日に 🌟', body_ja = '家での毎日にうんざり？「ママにやさしいスポット」マップを開いて、お子さんと一緒にゆったり過ごせる新しいカフェを見つけましょう。', title_ko = '오늘은 색다르게 🌟', body_ko = '집 안 일상이 답답한가요? 엄마 친화 장소 지도를 열고 아기와 함께 편히 앉을 수 있는 새로운 카페를 찾아보세요.', title_nl = 'Maak vandaag eens anders 🌟', body_nl = 'Word je benauwd van de dagelijkse routine thuis? Open onze kaart Mamavriendelijke plekken en vind een nieuw café waar je fijn met je kindje kunt zitten.', title_pl = 'Niech dziś będzie inaczej 🌟', body_pl = 'Domowa rutyna cię przytłacza? Otwórz naszą mapę Miejsc przyjaznych mamom i znajdź nową kawiarnię, w której wygodnie usiądziesz z maluszkiem.', title_pt = 'Que hoje seja diferente 🌟', body_pt = 'A rotina de casa está a sufocá-la? Abra o mapa dos Locais Amigos das Mães e encontre um café novo onde possa estar à vontade com o seu bebé.', title_sv = 'Låt i dag bli annorlunda 🌟', body_sv = 'Har vardagsrutinen hemma blivit tung? Öppna vår karta Mammavänliga platser och hitta ett nytt kafé där du kan sitta bekvämt tillsammans med barnet.', title_vi = 'Hãy để hôm nay thật khác biệt 🌟', body_vi = 'Nếp sinh hoạt ở nhà khiến mẹ ngột ngạt? Hãy mở bản đồ Địa điểm thân thiện với mẹ và tìm một quán cà phê mới, nơi mẹ có thể ngồi thoải mái cùng bé.', title_zh = '让今天与众不同 🌟', body_zh = '家里的日常让你闷得慌？打开我们的妈妈友好场所地图，找一家能和宝宝一起舒服坐坐的新咖啡馆吧。' WHERE id = '8fe0e4be-15b3-4472-a10c-0dbbc28c48cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pequeña estrella! 📸', body_es = '¡Su dulce sonrisa vale un mundo! Inmortaliza este día con distintos marcos en la Sesión de fotos del bebé.', title_fr = 'Petite star ! 📸', body_fr = 'Son joli sourire n''a pas de prix ! Immortalisez ce jour avec différents cadres grâce à la Séance photo bébé.', title_hi = 'बेबी स्टार! 📸', body_hi = 'उसकी प्यारी मुस्कान दुनिया से बढ़कर है! बेबी फ़ोटोशूट फ़ीचर के अलग-अलग फ़्रेम से इस दिन को हमेशा के लिए सहेज लीजिए।', title_id = 'Bintang kecil! 📸', body_id = 'Senyum manisnya tak ternilai! Abadikan hari ini dengan berbagai bingkai di fitur Sesi Foto Bayi.', title_ja = '小さなスター！📸', body_ja = 'かわいい笑顔は何ものにも代えられません！「ベビーフォトセッション」でいろいろなフレームを使って、今日という日を残しましょう。', title_ko = '아기 스타! 📸', body_ko = '그 달콤한 미소는 세상 무엇과도 바꿀 수 없죠! 아기 사진 촬영 기능의 다양한 프레임으로 오늘을 영원히 남기세요.', title_nl = 'Kleine ster! 📸', body_nl = 'Zijn lieve glimlach is goud waard! Leg deze dag voor altijd vast met verschillende kaders in Babyfotoshoot.', title_pl = 'Mała gwiazda! 📸', body_pl = 'Jego słodki uśmiech jest wart więcej niż cały świat! Uwiecznij ten dzień w funkcji Sesja zdjęciowa dziecka, korzystając z różnych ramek.', title_pt = 'Uma pequena estrela! 📸', body_pt = 'O sorriso doce dele vale o mundo! Eternize este dia com a Sessão Fotográfica do Bebé, usando molduras diferentes.', title_sv = 'Lilla stjärnan! 📸', body_sv = 'Barnets söta leende är värt allt! Förevig dagen med olika ramar i funktionen Babyfotografering.', title_vi = 'Ngôi sao nhí! 📸', body_vi = 'Nụ cười ngọt ngào của bé đáng giá cả thế giới! Hãy lưu giữ ngày hôm nay với những khung ảnh khác nhau trong tính năng Chụp ảnh cho bé.', title_zh = '宝宝小明星！📸', body_zh = '他甜甜的笑容比什么都珍贵！用宝宝写真功能里不同的相框，把今天永远留下来吧。' WHERE id = 'ea228eca-a9dc-4d32-bfab-5af38c95cc81' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Salto de desarrollo? 📈', body_es = '¿Llora mucho o duerme peor? Consulta con Anacan AI si puede ser la semana del salto de los 17 meses.', title_fr = 'Un pic de développement ? 📈', body_fr = 'Il pleure beaucoup ou dort mal ? Demandez conseil à Anacan AI pour savoir s''il s''agit de la semaine de pic du 17e mois.', title_hi = 'विकास की छलांग? 📈', body_hi = 'बहुत रोता है या नींद बिगड़ गई है? Anacan AI से सलाह लेकर पक्का कीजिए कि यह 17वें महीने की छलांग वाला हफ़्ता है या नहीं।', title_id = 'Lompatan perkembangan? 📈', body_id = 'Ia sering menangis atau tidurnya terganggu? Konsultasikan dengan Anacan AI untuk memastikan apakah ini minggu lompatan perkembangan bulan ke-17.', title_ja = '発達の節目？📈', body_ja = 'よく泣いたり、睡眠が乱れたりしていますか？Anacan AIに相談して、1歳5か月ごろのぐずり期の週なのかどうか確かめましょう。', title_ko = '발달 도약기일까요? 📈', body_ko = '많이 울거나 잠이 흐트러졌나요? Anacan AI와 상담해 17개월 도약 주간인지 확인해 보세요.', title_nl = 'Een ontwikkelingssprong? 📈', body_nl = 'Huilt je kindje veel of slaapt hij slecht? Overleg met Anacan AI en ontdek of dit de sprongweek van de 17e maand is.', title_pl = 'Skok rozwojowy? 📈', body_pl = 'Dużo płacze albo śpi niespokojnie? Poradź się Anacan AI i sprawdź, czy to tydzień skoku rozwojowego w 17. miesiącu.', title_pt = 'Salto de desenvolvimento? 📈', body_pt = 'Chora muito ou o sono anda desregulado? Fale com o Anacan AI e confirme se é a semana do salto dos 17 meses.', title_sv = 'Utvecklingssprång? 📈', body_sv = 'Gråter barnet mycket eller sover oroligt? Rådfråga Anacan AI och ta reda på om det är språngveckan i den 17:e månaden.', title_vi = 'Bước nhảy phát triển? 📈', body_vi = 'Bé khóc nhiều hay giấc ngủ bị xáo trộn? Hãy hỏi ý kiến Anacan AI để biết đây có phải tuần nhảy vọt của tháng thứ 17 không.', title_zh = '发育飞跃期？📈', body_zh = '哭得很多，或者睡眠乱了？咨询一下Anacan AI，弄清楚是不是第17个月的飞跃周。' WHERE id = '58bde9b3-f42d-49ca-ae5b-48563d307555' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una rutina relajante 🌙', body_es = 'El final de un día precioso. Activa el Temporizador de sueño, elige una nana en Ruido blanco y disfruta con calma del final del día.', title_fr = 'Un rituel relaxant 🌙', body_fr = 'La fin d''une belle journée. Lancez le minuteur de sommeil, choisissez une berceuse dans les Bruits blancs et savourez tranquillement la fin de la journée.', title_hi = 'सुकून देने वाला रूटीन 🌙', body_hi = 'एक खूबसूरत दिन का अंत। स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में लोरी चुनिए और दिन के खत्म होने का शांति से आनंद लीजिए।', title_id = 'Rutinitas yang menenangkan 🌙', body_id = 'Akhir hari yang indah. Nyalakan Timer Tidur, pilih nina bobo dari Suara Putih, dan nikmati dengan tenang berakhirnya hari ini.', title_ja = 'リラックスできる習慣 🌙', body_ja = 'すてきな一日の終わり。睡眠タイマーをオンにして、「ホワイトノイズ」から子守唄を選び、一日の終わりを静かに味わいましょう。', title_ko = '편안해지는 루틴 🌙', body_ko = '멋진 하루의 끝이에요. 수면 타이머를 켜고 백색소음에서 자장가를 고른 뒤 조용히 하루를 마무리하세요.', title_nl = 'Een ontspannende routine 🌙', body_nl = 'Het einde van een mooie dag. Zet de Slaaptimer aan, kies een slaapliedje in Witte ruis en geniet rustig van het einde van de dag.', title_pl = 'Relaksująca rutyna 🌙', body_pl = 'Koniec pięknego dnia. Włącz timer snu, wybierz w Białym szumie kołysankę i spokojnie delektuj się końcem dnia.', title_pt = 'Uma rotina relaxante 🌙', body_pt = 'O fim de um dia bonito. Ligue o temporizador de sono, escolha uma canção de embalar no Ruído Branco e aproveite com calma o final do dia.', title_sv = 'Avslappnande rutin 🌙', body_sv = 'Slutet på en fin dag. Starta sömntimern, välj vaggvisan i Vitt brus och njut i lugn och ro av att dagen tar slut.', title_vi = 'Nếp sinh hoạt thư giãn 🌙', body_vi = 'Kết thúc một ngày tươi đẹp. Hãy bật Bộ hẹn giờ ngủ, chọn bài hát ru trong Tiếng ồn trắng và nhẹ nhàng tận hưởng phút cuối ngày.', title_zh = '放松的睡前程序 🌙', body_zh = '美好一天的尾声。打开睡眠计时器，在白噪音里选一首摇篮曲，静静享受一天的结束吧。' WHERE id = '7771d800-de2f-41eb-8bd6-431add8986fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de aire fresco 🌳', body_es = '¿Agobiada en casa? Abre el mapa de Lugares para mamás y descubre un parque nuevo por el que pasear cómodamente con tu peque.', title_fr = 'En quête d''air frais 🌳', body_fr = 'Vous vous ennuyez à la maison ? Ouvrez notre carte des Lieux adaptés aux mamans et découvrez un nouveau parc où vous promener facilement avec bébé.', title_hi = 'ताज़ी हवा की तलाश में 🌳', body_hi = 'घर में घुटन हो रही है? हमारा माँ के लिए अनुकूल जगहों का नक्शा खोलिए और कोई नया पार्क खोजिए जहाँ बच्चे के साथ आराम से घूम सकें।', title_id = 'Mencari udara segar 🌳', body_id = 'Bosan di rumah? Buka peta Tempat Ramah Ibu dan temukan taman baru yang nyaman untuk jalan-jalan bersama si kecil.', title_ja = '新鮮な空気を求めて 🌳', body_ja = '家の中で退屈していませんか？「ママにやさしいスポット」マップを開いて、お子さんとゆったりお散歩できる新しい公園を見つけましょう。', title_ko = '신선한 공기를 찾아서 🌳', body_ko = '집이 답답한가요? 엄마 친화 장소 지도를 열고 아기와 함께 편하게 걸을 수 있는 새 공원을 찾아보세요.', title_nl = 'Op zoek naar frisse lucht 🌳', body_nl = 'Word je benauwd thuis? Open onze kaart Mamavriendelijke plekken en ontdek een nieuw park waar je fijn met je kindje kunt wandelen.', title_pl = 'W poszukiwaniu świeżego powietrza 🌳', body_pl = 'Nudzisz się w domu? Otwórz naszą mapę Miejsc przyjaznych mamom i odkryj nowy park, po którym wygodnie pospacerujesz z maluszkiem.', title_pt = 'Em busca de ar puro 🌳', body_pt = 'Está farta de estar em casa? Abra o mapa dos Locais Amigos das Mães e descubra um parque novo onde possa passear à vontade com o seu bebé.', title_sv = 'På jakt efter frisk luft 🌳', body_sv = 'Har du tröttnat på att vara hemma? Öppna vår karta Mammavänliga platser och upptäck en ny park där du kan promenera bekvämt med barnet.', title_vi = 'Đi tìm không khí trong lành 🌳', body_vi = 'Ở nhà thấy ngột ngạt? Hãy mở bản đồ Địa điểm thân thiện với mẹ và khám phá một công viên mới để cùng bé thong thả dạo chơi.', title_zh = '寻找新鲜空气 🌳', body_zh = '在家闷得慌？打开我们的妈妈友好场所地图，找一个能和宝宝一起舒服散步的新公园吧。' WHERE id = 'b9d3a084-eae2-4a4a-af8c-e99d02752f66' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de dormir ⏱️', body_es = '¿Empiezas a dormirle? Activa el Temporizador de sueño, anota cómo seguís la rutina y analiza cuánto duerme.', title_fr = 'C''est l''heure de dormir ⏱️', body_fr = 'Vous commencez à le coucher ? Lancez le minuteur de sommeil et notez si vous respectez le rythme pour analyser ses besoins en sommeil.', title_hi = 'सोने का समय आ गया ⏱️', body_hi = 'उसे सुलाना शुरू कर रही हैं? स्लीप टाइमर चालू कीजिए और रूटीन का पालन दर्ज करके नींद के मानक का विश्लेषण कीजिए।', title_id = 'Waktunya tidur ⏱️', body_id = 'Mulai menidurkannya? Nyalakan Timer Tidur, catat seberapa baik Anda menjalankan rutinitas, dan analisis kebutuhan tidurnya.', title_ja = 'ねんねの時間 ⏱️', body_ja = '寝かしつけを始めますか？睡眠タイマーをオンにして、リズムをどれだけ守れているか記録し、睡眠量を分析しましょう。', title_ko = '잘 시간이에요 ⏱️', body_ko = '재우기를 시작하나요? 수면 타이머를 켜고 일과를 얼마나 잘 지키는지 기록하며 수면량을 분석해 보세요.', title_nl = 'Tijd om te slapen ⏱️', body_nl = 'Ga je je kindje in slaap brengen? Zet de Slaaptimer aan, noteer hoe goed jullie het ritme volgen en analyseer zijn slaapbehoefte.', title_pl = 'Pora spać ⏱️', body_pl = 'Zaczynasz go usypiać? Włącz timer snu, zapisuj, jak trzymacie się rytmu, i przeanalizuj normę snu.', title_pt = 'Chegou a hora de dormir ⏱️', body_pt = 'Vai começar a adormecê-lo? Ligue o temporizador de sono, registe como está a cumprir a rotina e analise as horas de sono.', title_sv = 'Dags att sova ⏱️', body_sv = 'Ska du börja natta barnet? Starta sömntimern, anteckna hur väl ni följer rutinen och analysera sömnnormen.', title_vi = 'Đến giờ ngủ rồi ⏱️', body_vi = 'Mẹ bắt đầu ru bé ngủ? Hãy bật Bộ hẹn giờ ngủ, ghi lại việc tuân thủ lịch sinh hoạt và phân tích định mức giấc ngủ.', title_zh = '睡觉时间到 ⏱️', body_zh = '要开始哄睡了？打开睡眠计时器，记录作息执行情况，分析一下睡眠参考量吧。' WHERE id = 'c7d9bc7f-54a9-4f50-9876-80c78adff647' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal el apetito por la mañana? 🥣', body_es = '¡Empezar el día de forma sana es importante! Calcula con el Seguimiento de tomas las vitaminas que necesita hoy y planifica el menú.', title_fr = 'Et l''appétit du matin ? 🥣', body_fr = 'Bien commencer la journée est important ! Calculez ses besoins en vitamines du jour avec le Suivi des repas et planifiez le menu.', title_hi = 'सुबह की भूख कैसी है? 🥣', body_hi = 'दिन की सेहतमंद शुरुआत ज़रूरी है! फ़ीडिंग ट्रैकर से आज की विटामिन की ज़रूरत का हिसाब लगाकर मेन्यू की योजना बनाइए।', title_id = 'Bagaimana nafsu makannya pagi ini? 🥣', body_id = 'Memulai hari dengan sehat itu penting! Hitung kebutuhan vitamin hari ini dengan alat Pemantau Makan dan rencanakan menunya.', title_ja = '朝の食欲はどう？🥣', body_ja = '健康的な一日のスタートが大切！「栄養管理ツール」で今日必要なビタミンを計算して、メニューを計画しましょう。', title_ko = '아침 입맛은 어떤가요? 🥣', body_ko = '건강하게 하루를 시작하는 게 중요해요! 수유 기록 도구로 오늘 필요한 비타민을 계산하고 식단을 계획하세요.', title_nl = 'Hoe is de eetlust ''s ochtends? 🥣', body_nl = 'Gezond aan de dag beginnen is belangrijk! Bereken met de Voedingstracker de vitaminebehoefte van vandaag en plan het menu.', title_pl = 'Jak tam poranny apetyt? 🥣', body_pl = 'Ważne, by zacząć dzień zdrowo! Oblicz w narzędziu do śledzenia karmienia dzisiejsze zapotrzebowanie na witaminy i zaplanuj menu.', title_pt = 'Como está o apetite da manhã? 🥣', body_pt = 'Começar o dia de forma saudável é importante! Calcule com o Registo de Alimentação as necessidades de vitaminas de hoje e planeie a ementa.', title_sv = 'Hur är aptiten på morgonen? 🥣', body_sv = 'Det är viktigt att börja dagen hälsosamt! Räkna ut dagens vitaminbehov med Matningskoll och planera menyn.', title_vi = 'Bữa sáng của bé thế nào? 🥣', body_vi = 'Bắt đầu ngày mới lành mạnh rất quan trọng! Hãy tính nhu cầu vitamin hôm nay bằng công cụ Theo dõi cữ bú và lên kế hoạch thực đơn.', title_zh = '早上胃口怎么样？🥣', body_zh = '健康地开始一天很重要！用喂养记录工具算一算今天的维生素需求，规划一下菜单吧。' WHERE id = 'e064d0bf-455a-4252-9305-e3585f5b88ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿La ropa le queda justa? 📏', body_es = '¿Notas que ha pegado un estirón de repente? Introduce las nuevas cifras en el Registro de peso y mira su gráfica de crecimiento sano.', title_fr = 'Ses vêtements le serrent ? 📏', body_fr = 'Vous sentez que votre enfant a grandi d''un coup ? Saisissez les nouveaux chiffres dans le Suivi du poids et regardez sa courbe de croissance.', title_hi = 'कपड़े तंग हो रहे हैं? 📏', body_hi = 'महसूस हो रहा है कि बच्चे की लंबाई अचानक बढ़ गई? वेट ट्रैकर में नए आँकड़े डालिए और सेहतमंद बढ़त का चार्ट देखिए।', title_id = 'Bajunya makin sempit? 📏', body_id = 'Merasa si kecil tiba-tiba bertambah tinggi? Masukkan angka terbarunya di Pelacak Berat Badan dan lihat grafik pertumbuhannya yang sehat.', title_ja = 'お洋服がきつくなった？📏', body_ja = '急に背が伸びたと感じますか？「体重トラッカー」に新しい数値を入れて、健やかな成長グラフを確認しましょう。', title_ko = '옷이 꽉 끼나요? 📏', body_ko = '아이 키가 갑자기 쑥 자란 것 같나요? 체중 기록에 새 수치를 입력하고 건강한 성장 그래프를 확인하세요.', title_nl = 'Worden de kleertjes krap? 📏', body_nl = 'Merk je dat je kindje ineens gegroeid is? Voer de nieuwe cijfers in de Gewichtstracker in en bekijk de gezonde groeicurve.', title_pl = 'Ubranka robią się ciasne? 📏', body_pl = 'Czujesz, że dziecko nagle urosło? Wpisz nowe liczby w Liczniku wagi i zobacz wykres zdrowego wzrostu.', title_pt = 'A roupa está a ficar apertada? 📏', body_pt = 'Sente que o seu filho cresceu de repente? Introduza os novos números no Registo de Peso e veja o gráfico de crescimento saudável.', title_sv = 'Blir kläderna trånga? 📏', body_sv = 'Känner du att barnet plötsligt har vuxit? Skriv in de nya siffrorna i Viktspåraren och titta på den friska tillväxtkurvan.', title_vi = 'Quần áo chật dần? 📏', body_vi = 'Mẹ thấy bé bỗng dưng cao vọt? Hãy nhập số đo mới vào Theo dõi cân nặng và xem biểu đồ tăng trưởng khỏe mạnh.', title_zh = '衣服变紧了？📏', body_zh = '感觉孩子突然长高了？在体重记录里输入新的数字，看看健康的成长曲线吧。' WHERE id = '256bddeb-107b-434f-9688-0c6670394bc8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Temporizador de comidas ⏱️', body_es = '¿Cuánto tiempo tarda en comer? Activa el temporizador de tomas y controla la rutina para que haga bien la digestión.', title_fr = 'Le minuteur des repas ⏱️', body_fr = 'Combien de temps lui faut-il pour manger ? Lancez le minuteur des repas et surveillez son rythme pour une bonne digestion.', title_hi = 'फ़ीडिंग टाइमर ⏱️', body_hi = 'खाना खाने में उसे कितना समय लगता है? फ़ीडिंग टाइमर चालू कीजिए और खाना पूरी तरह पचने के लिए रूटीन पर नज़र रखिए।', title_id = 'Timer Makan ⏱️', body_id = 'Berapa lama waktu makannya? Nyalakan Timer Makan dan awasi rutinitasnya agar makanan tercerna dengan baik.', title_ja = '食事タイマー ⏱️', body_ja = '食事にどれくらい時間がかかっていますか？食事タイマーをオンにして、しっかり消化できるようリズムを見守りましょう。', title_ko = '식사 타이머 ⏱️', body_ko = '밥 먹는 데 얼마나 걸리나요? 수유 타이머를 켜고 음식이 잘 소화되도록 식사 일과를 관리하세요.', title_nl = 'Voedingstimer ⏱️', body_nl = 'Hoe lang doet je kindje over het eten? Zet de voedingstimer aan en houd het ritme in de gaten, zodat het eten goed verteerd wordt.', title_pl = 'Timer karmienia ⏱️', body_pl = 'Ile czasu zajmuje mu jedzenie? Włącz timer karmienia i pilnuj rytmu posiłków, by jedzenie dobrze się trawiło.', title_pt = 'Temporizador de alimentação ⏱️', body_pt = 'Quanto tempo demora a comer? Ligue o temporizador de alimentação e acompanhe a rotina para que a comida seja bem digerida.', title_sv = 'Matningstimer ⏱️', body_sv = 'Hur lång tid tar måltiden? Starta matningstimern och håll koll på rutinen så att maten hinner smälta ordentligt.', title_vi = 'Hẹn giờ bữa ăn ⏱️', body_vi = 'Bé ăn mất bao lâu? Hãy bật bộ hẹn giờ trong Theo dõi cữ bú và theo dõi lịch ăn để thức ăn được tiêu hóa hoàn toàn.', title_zh = '喂养计时器 ⏱️', body_zh = '吃一顿饭要花多长时间？打开喂养计时器，关注进餐节奏，帮助食物充分消化。' WHERE id = 'ac852fa3-348f-43fe-9321-7b4e3e9f3af1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lecturas útiles 📖', body_es = 'Ya se ha dormido, ¿y tú qué haces? Lee los artículos más recientes de nuestro Blog para enriquecer tu experiencia como madre.', title_fr = 'Lecture utile 📖', body_fr = 'Il dort, et vous, que faites-vous ? Lisez les derniers articles de nos Blogs pour enrichir votre expérience de maman.', title_hi = 'काम का पढ़ना 📖', body_hi = 'बच्चा सो गया, और आप क्या कर रही हैं? माँ बनने का अपना अनुभव बढ़ाने के लिए हमारे ब्लॉग सेक्शन के सबसे नए लेख पढ़िए।', title_id = 'Bacaan bermanfaat 📖', body_id = 'Si kecil sudah tidur, lalu Anda sedang apa? Baca artikel terbaru di bagian Blog kami untuk menambah pengalaman Anda sebagai ibu.', title_ja = '役に立つ読みもの 📖', body_ja = 'お子さんが寝ましたが、あなたは何をしていますか？子育ての知識を深めるために、ブログの最新記事を読んでみましょう。', title_ko = '유익한 읽을거리 📖', body_ko = '아이가 잠들었는데, 엄마는 뭘 하고 있나요? 육아 지식을 넓힐 수 있도록 블로그 섹션의 최신 글을 읽어 보세요.', title_nl = 'Nuttig leesvoer 📖', body_nl = 'Je kindje slaapt, en wat doe jij? Lees de nieuwste artikelen in ons onderdeel Blogs en doe meer kennis op over het moederschap.', title_pl = 'Pożyteczna lektura 📖', body_pl = 'Maluszek śpi, a co robisz ty? Przeczytaj najnowsze artykuły w sekcji Blogi i poszerz swoje doświadczenie mamy.', title_pt = 'Leituras úteis 📖', body_pt = 'Ele adormeceu, e a mãe, o que faz? Leia os artigos mais recentes da nossa secção Blogues para enriquecer a sua experiência de mãe.', title_sv = 'Nyttig läsning 📖', body_sv = 'Barnet sover, men vad gör du? Läs de senaste artiklarna i avsnittet Bloggar och öka din erfarenhet som mamma.', title_vi = 'Đọc sách bổ ích 📖', body_vi = 'Bé ngủ rồi, còn mẹ đang làm gì? Hãy đọc những bài viết mới nhất trong mục Blog để thêm kinh nghiệm làm mẹ.', title_zh = '有益的阅读 📖', body_zh = '宝宝睡了，你在做什么呢？读读我们博客板块里的最新文章，丰富你的育儿经验吧。' WHERE id = 'f78fdccc-68a3-4827-b309-2accfb39bff1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca del vaso perfecto 🥤', body_es = '¿Buscas un vaso antiderrame y cómodo? Echa un vistazo en Productos recomendados a los que más han probado otras mamás.', title_fr = 'À la recherche de la gourde idéale 🥤', body_fr = 'Vous cherchez une gourde anti-fuite et pratique ? Jetez un œil aux produits les plus testés par les mamans dans les Produits recommandés.', title_hi = 'परफ़ेक्ट सिपी कप की तलाश 🥤', body_hi = 'न छलकने वाला आरामदायक सिपी कप ढूँढ रही हैं? सुझाए गए प्रोडक्ट सेक्शन में माँओं के सबसे ज़्यादा आज़माए प्रोडक्ट देखिए।', title_id = 'Mencari botol minum ideal 🥤', body_id = 'Mencari botol minum anti tumpah yang nyaman? Lihat produk yang paling banyak dicoba para ibu di bagian Produk Rekomendasi.', title_ja = '理想のマグ探し 🥤', body_ja = 'こぼれにくくて使いやすいマグを探していますか？「おすすめ商品」で、ママたちがいちばん試している商品をのぞいてみましょう。', title_ko = '딱 맞는 물병 찾기 🥤', body_ko = '새지 않고 편한 물병을 찾고 있나요? 추천 제품 섹션에서 엄마들이 가장 많이 써 본 제품을 살펴보세요.', title_nl = 'Op zoek naar de ideale drinkbeker 🥤', body_nl = 'Op zoek naar een fijne, lekvrije drinkbeker? Bekijk in het onderdeel Aanbevolen producten wat moeders het vaakst hebben getest.', title_pl = 'W poszukiwaniu idealnego kubka 🥤', body_pl = 'Szukasz wygodnego kubka, który się nie wylewa? Zajrzyj do sekcji Polecane produkty i zobacz produkty najczęściej sprawdzone przez mamy.', title_pt = 'Em busca do copo ideal 🥤', body_pt = 'Procura um copo com bico prático e que não verta? Espreite na secção Produtos Recomendados os produtos mais testados pelas mães.', title_sv = 'Jakten på den perfekta pipmuggen 🥤', body_sv = 'Letar du efter en spillfri och bekväm pipmugg? Titta på produkterna som mammor har testat mest i avsnittet Rekommenderade produkter.', title_vi = 'Đi tìm bình tập uống lý tưởng 🥤', body_vi = 'Mẹ đang tìm một chiếc bình tập uống chống tràn và tiện lợi? Hãy xem những sản phẩm được các mẹ dùng thử nhiều nhất trong mục Sản phẩm gợi ý.', title_zh = '寻找理想水杯 🥤', body_zh = '在找不漏水又好用的水杯？看看推荐商品里妈妈们试用最多的产品吧。' WHERE id = '0a2bf8ce-6e82-41df-9345-19718f7bde4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa para el café ☕', body_es = '¿Hoy te apetece salir de casa? Encuentra en Lugares para mamás una cafetería con rincón infantil y dedícate un rato.', title_fr = 'Pause café ☕', body_fr = 'Envie de sortir de la maison aujourd''hui ? Trouvez dans les Lieux adaptés aux mamans un café avec un coin enfants et prenez du temps pour vous.', title_hi = 'कॉफ़ी ब्रेक ☕', body_hi = 'आज घर से निकलने का मन है? माँ के लिए अनुकूल जगहों में बच्चों के कोने वाला कोई कैफ़े ढूँढिए और अपने लिए समय निकालिए।', title_id = 'Rehat kopi ☕', body_id = 'Ingin keluar rumah hari ini? Temukan kafe dengan area bermain anak di Tempat Ramah Ibu dan luangkan waktu untuk diri sendiri.', title_ja = 'コーヒーブレイク ☕', body_ja = '今日は家から出たい気分？「ママにやさしいスポット」でキッズスペースのあるカフェを見つけて、自分の時間をつくりましょう。', title_ko = '커피 타임 ☕', body_ko = '오늘 집 밖으로 나가고 싶나요? 엄마 친화 장소에서 키즈 공간이 있는 카페를 찾아 나를 위한 시간을 가져 보세요.', title_nl = 'Koffiepauze ☕', body_nl = 'Wil je vandaag de deur uit? Zoek in Mamavriendelijke plekken een café met een kinderhoek en neem tijd voor jezelf.', title_pl = 'Przerwa na kawę ☕', body_pl = 'Chcesz dziś wyjść z domu? Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem dla dzieci i znajdź czas dla siebie.', title_pt = 'Pausa para o café ☕', body_pt = 'Hoje apetece-lhe sair de casa? Encontre nos Locais Amigos das Mães um café com espaço infantil e reserve tempo para si.', title_sv = 'Kaffepaus ☕', body_sv = 'Vill du komma ut i dag? Hitta ett kafé med lekhörna i Mammavänliga platser och ta tid för dig själv.', title_vi = 'Giờ nghỉ cà phê ☕', body_vi = 'Hôm nay mẹ muốn ra khỏi nhà? Hãy tìm một quán cà phê có góc vui chơi cho trẻ trong Địa điểm thân thiện với mẹ và dành thời gian cho bản thân.', title_zh = '咖啡时间 ☕', body_zh = '今天想出门吗？在妈妈友好场所里找一家有儿童角的咖啡馆，给自己留点时间。' WHERE id = '12fa87ff-96f2-48c2-a70c-da7757524f9b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahogo emocional 📝', body_es = '¿Hoy no ha salido todo como lo planeabas? No te culpes. Escribe tus agobios en el Diario de ánimo y vacía la mente.', title_fr = 'Lâcher prise 📝', body_fr = 'Tout ne s''est pas passé comme prévu aujourd''hui ? Ne vous blâmez pas. Videz votre esprit en écrivant ce qui vous pèse dans le Journal d''humeur.', title_hi = 'मन का बोझ हल्का करना 📝', body_hi = 'आज सब कुछ योजना के मुताबिक नहीं हुआ? खुद को दोष मत दीजिए। मूड डायरी में अपनी अंदर की परेशानियाँ लिखकर दिमाग खाली कीजिए।', title_id = 'Melepaskan emosi 📝', body_id = 'Hari ini tidak semuanya berjalan sesuai rencana? Jangan menyalahkan diri sendiri. Kosongkan pikiran dengan menuliskan beban hati Anda di Buku Harian Suasana Hati.', title_ja = '気持ちを吐き出そう 📝', body_ja = '今日は計画どおりにいかなかった？自分を責めないで。「気分日記」に心のもやもやを書き出して、頭をすっきりさせましょう。', title_ko = '감정을 털어놓기 📝', body_ko = '오늘 모든 게 계획대로 되지 않았나요? 자책하지 마세요. 기분 일기에 마음속 답답함을 적어 머리를 비워 보세요.', title_nl = 'Je gevoelens loslaten 📝', body_nl = 'Ging vandaag niet alles volgens plan? Wees niet streng voor jezelf. Schrijf wat je dwarszit op in je Stemmingsdagboek en maak je hoofd leeg.', title_pl = 'Emocjonalne odreagowanie 📝', body_pl = 'Dziś nie wszystko poszło zgodnie z planem? Nie obwiniaj się. Zapisz w Dzienniku nastroju, co cię gnębi, i oczyść głowę.', title_pt = 'Desabafo emocional 📝', body_pt = 'Hoje nada correu como planeado? Não se culpe. Esvazie a cabeça escrevendo no Diário de Humor as suas preocupações.', title_sv = 'Känslomässig urladdning 📝', body_sv = 'Gick inte allt enligt planen i dag? Skuldbelägg inte dig själv. Töm huvudet genom att skriva ner det som tynger dig i Humördagboken.', title_vi = 'Giải tỏa cảm xúc 📝', body_vi = 'Hôm nay mọi thứ không theo kế hoạch? Đừng tự trách mình. Hãy viết những nỗi niềm trong lòng vào Nhật ký tâm trạng để đầu óc nhẹ nhõm hơn.', title_zh = '释放情绪 📝', body_zh = '今天一切都没按计划进行？别责怪自己。把内心的烦闷写进心情日记，让大脑放空一下。' WHERE id = '5bd8188b-93fc-435a-8a33-b488c4ecc902' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rutina de la mañana 💩', body_es = '¿Has cambiado el primer pañal del día? El color y la consistencia de la caca dicen mucho de su salud intestinal. ¡Anótalo ya en el Seguimiento de pañales!', title_fr = 'Le rituel du matin 💩', body_fr = 'Vous avez changé la première couche de la journée ? La couleur et la consistance des selles renseignent sur la santé de ses intestins. Notez-le tout de suite dans le Suivi des couches !', title_hi = 'सुबह का रूटीन 💩', body_hi = 'दिन का पहला डायपर बदल दिया? पॉटी का रंग और गाढ़ापन आँतों की सेहत के बारे में बताते हैं। तुरंत डायपर ट्रैकर में दर्ज कीजिए!', title_id = 'Rutinitas pagi 💩', body_id = 'Sudah mengganti popok pertama hari ini? Warna dan kepadatan feses menunjukkan kesehatan ususnya. Segera catat di Pelacak Popok!', title_ja = '朝の習慣 💩', body_ja = '今日最初のおむつ替えはすみましたか？うんちの色やかたさは腸の健康を教えてくれます。すぐに「おむつトラッカー」に記録しましょう！', title_ko = '아침 루틴 💩', body_ko = '오늘 첫 기저귀를 갈았나요? 변의 색과 굳기는 장 건강을 알려 줘요. 바로 기저귀 기록에 남기세요!', title_nl = 'Ochtendroutine 💩', body_nl = 'Heb je de eerste luier van de dag verschoond? De kleur en dikte van de ontlasting zeggen iets over de darmgezondheid. Noteer het meteen in de Luiertracker!', title_pl = 'Poranna rutyna 💩', body_pl = 'Przewinęłaś pierwszą pieluszkę dnia? Kolor i konsystencja kupki mówią o zdrowiu jelit. Od razu zapisz to w narzędziu do śledzenia pieluszek!', title_pt = 'A rotina da manhã 💩', body_pt = 'Já mudou a primeira fralda do dia? A cor e a consistência das fezes dizem muito sobre a saúde intestinal. Registe já no Registo de Fraldas!', title_sv = 'Morgonrutin 💩', body_sv = 'Har du bytt dagens första blöja? Bajsets färg och konsistens berättar om tarmhälsan. Anteckna det direkt i Blöjkollen!', title_vi = 'Nếp sinh hoạt buổi sáng 💩', body_vi = 'Mẹ vừa thay chiếc tã đầu tiên trong ngày? Màu sắc và độ đặc của phân cho biết sức khỏe đường ruột. Hãy ghi ngay vào Theo dõi tã!', title_zh = '早晨的日常 💩', body_zh = '换了今天的第一片尿布？便便的颜色和稠度能反映肠道健康。马上在尿布记录里记下来吧！' WHERE id = '0d268555-6803-4b45-adab-7558434a3d7b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía para mamá 🥗', body_es = 'Correr detrás de él agota. ¡No te olvides de ti! Prepara en Recetas saludables para mujeres una ensalada deliciosa que te dé fuerzas al momento.', title_fr = 'De l''énergie pour les mamans 🥗', body_fr = 'Lui courir après, c''est fatigant. Ne vous oubliez pas ! Préparez une bonne salade revigorante grâce aux Recettes saines pour femmes.', title_hi = 'महिलाओं के लिए ऊर्जा 🥗', body_hi = 'भागदौड़ थका देती है। खुद को मत भूलिए! महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ताकत देने वाला स्वादिष्ट सलाद बनाइए।', title_id = 'Energi untuk wanita 🥗', body_id = 'Kejar-kejaran itu melelahkan. Jangan lupakan diri Anda! Siapkan salad lezat yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = '女性のためのエネルギー 🥗', body_ja = '追いかけっこは疲れます。自分のことも忘れないで！「女性のためのヘルシーレシピ」から、すぐに元気が出るおいしいサラダをつくりましょう。', title_ko = '엄마를 위한 에너지 🥗', body_ko = '쫓아다니기는 정말 지쳐요. 나 자신을 잊지 마세요! 건강한 레시피에서 바로 힘이 나는 맛있는 샐러드를 만들어 보세요.', title_nl = 'Energie voor vrouwen 🥗', body_nl = 'Achter je kindje aanrennen is vermoeiend. Vergeet jezelf niet! Maak uit Gezonde recepten voor vrouwen een lekkere salade die je meteen kracht geeft.', title_pl = 'Energia dla mamy 🥗', body_pl = 'Gonitwy są męczące. Nie zapominaj o sobie! Przygotuj ze Zdrowych przepisów dla kobiet smaczną sałatkę, która od razu doda ci sił.', title_pt = 'Energia para mulheres 🥗', body_pt = 'As correrias cansam. Não se esqueça de si! Prepare nas Receitas Saudáveis para Mulheres uma salada deliciosa que lhe dê força na hora.', title_sv = 'Energi för kvinnor 🥗', body_sv = 'Jagalekar är tröttsamma. Glöm inte dig själv! Gör en god sallad som ger kraft direkt från Hälsosamma recept för kvinnor.', title_vi = 'Năng lượng cho phụ nữ 🥗', body_vi = 'Chạy theo bé thật mệt. Đừng quên bản thân mẹ! Hãy làm một đĩa salad ngon miệng, nạp năng lượng tức thì từ Công thức lành mạnh cho phụ nữ.', title_zh = '女性能量补给 🥗', body_zh = '追追跑跑太累人了。别忘了自己！从女性健康食谱里做一份马上补充体力的美味沙拉吧。' WHERE id = '7d0a17bf-475f-48d2-9838-14918053b021' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia del ruido blanco 🌧️', body_es = '¿Ha sido un día muy activo? Pon el sonido de la lluvia en Ruido blanco: tu peque se dormirá fácilmente y tú podrás respirar tranquila.', title_fr = 'La magie des Bruits blancs 🌧️', body_fr = 'La journée a été très active ? Lancez le bruit de la pluie dans les Bruits blancs : bébé s''endormira facilement et vous pourrez souffler.', title_hi = 'व्हाइट नॉइज़ का जादू 🌧️', body_hi = 'बहुत भाग-दौड़ वाला दिन था? कमरे में व्हाइट नॉइज़ से बारिश की आवाज़ चलाइए, ताकि बच्चा आसानी से सो जाए और आप भी चैन की साँस लें।', title_id = 'Keajaiban Suara Putih 🌧️', body_id = 'Harinya sangat aktif? Putar suara hujan dari Suara Putih di kamar, agar si kecil mudah tertidur dan Anda bisa bernapas lega.', title_ja = 'ホワイトノイズの魔法 🌧️', body_ja = 'とても活発な一日でしたか？部屋で「ホワイトノイズ」から雨の音を流しましょう。お子さんはすんなり眠り、あなたもほっとひと息つけます。', title_ko = '백색소음의 마법 🌧️', body_ko = '정말 활발한 하루였나요? 방에 백색소음의 빗소리를 틀어 아기는 쉽게 잠들고, 엄마는 한숨 돌리세요.', title_nl = 'De magie van witte ruis 🌧️', body_nl = 'Was het een erg actieve dag? Zet in Witte ruis het geluid van regen aan in de kamer, zodat je kindje makkelijk in slaap valt en jij weer rustig kunt ademhalen.', title_pl = 'Magia Białego szumu 🌧️', body_pl = 'To był bardzo aktywny dzień? Włącz w pokoju odgłos deszczu z Białego szumu, niech maluszek łatwo zaśnie, a ty spokojnie odetchnij.', title_pt = 'A magia do Ruído Branco 🌧️', body_pt = 'Foi um dia muito ativo? Ligue no quarto o som da chuva no Ruído Branco: o bebé adormece com facilidade e a mãe respira tranquila.', title_sv = 'Magin i vitt brus 🌧️', body_sv = 'Har det varit en väldigt aktiv dag? Sätt på regnljud i Vitt brus i rummet så att barnet somnar lätt och du kan andas ut.', title_vi = 'Phép màu của Tiếng ồn trắng 🌧️', body_vi = 'Hôm nay bé quá hiếu động? Hãy bật tiếng mưa trong Tiếng ồn trắng để bé dễ dàng chìm vào giấc ngủ, còn mẹ cũng được thở phào thư thái.', title_zh = '白噪音的魔力 🌧️', body_zh = '今天特别活跃？在房间里用白噪音放雨声，让宝宝轻松入睡，你也能松口气。' WHERE id = 'b2894838-9e87-4d9f-80b1-63a311667ac3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El momento más tierno del día 📸', body_es = '¿Hoy ha hecho algo diferente y gracioso? Captura ese momento con los marcos divertidos de la Sesión de fotos del bebé y conviértelo en un recuerdo para siempre.', title_fr = 'Le plus doux moment du jour 📸', body_fr = 'Il a fait quelque chose de nouveau et de drôle aujourd''hui ? Capturez ce moment avec les cadres amusants de la Séance photo bébé et faites-en un souvenir pour la vie.', title_hi = 'दिन का सबसे प्यारा पल 📸', body_hi = 'आज उसने कोई अलग और मज़ेदार हरकत की? बेबी फ़ोटोशूट के मज़ेदार फ़्रेम से उस पल को कैद करके उम्रभर की याद बना लीजिए।', title_id = 'Momen termanis hari ini 📸', body_id = 'Hari ini ia melakukan sesuatu yang berbeda dan lucu? Abadikan momen itu dengan bingkai seru di Sesi Foto Bayi dan jadikan kenangan seumur hidup.', title_ja = '今日いちばんかわいい瞬間 📸', body_ja = '今日はいつもとちがう、おもしろいしぐさをしましたか？「ベビーフォトセッション」の楽しいフレームでその瞬間を撮って、一生の思い出にしましょう。', title_ko = '오늘의 가장 귀여운 순간 📸', body_ko = '오늘 색다르고 웃긴 행동을 했나요? 아기 사진 촬영의 재미있는 프레임으로 그 순간을 담아 평생의 추억으로 만드세요.', title_nl = 'Het liefste moment van de dag 📸', body_nl = 'Deed je kindje vandaag iets bijzonders en grappigs? Leg dat moment vast met de leuke kaders in Babyfotoshoot en maak er een herinnering voor altijd van.', title_pl = 'Najsłodsza chwila dnia 📸', body_pl = 'Zrobił dziś coś nietypowego i zabawnego? Uchwyć tę chwilę z zabawnymi ramkami w Sesji zdjęciowej dziecka i zamień ją we wspomnienie na całe życie.', title_pt = 'O momento mais doce do dia 📸', body_pt = 'Hoje fez algo diferente e engraçado? Capte esse momento com as molduras divertidas da Sessão Fotográfica do Bebé e transforme-o numa recordação para a vida.', title_sv = 'Dagens sötaste stund 📸', body_sv = 'Gjorde barnet något annorlunda och roligt i dag? Fånga stunden med de roliga ramarna i Babyfotografering och gör den till ett minne för livet.', title_vi = 'Khoảnh khắc đáng yêu nhất trong ngày 📸', body_vi = 'Hôm nay bé làm điều gì đó khác lạ và hài hước? Hãy chụp lại khoảnh khắc ấy với những khung ảnh vui nhộn trong Chụp ảnh cho bé để biến nó thành kỷ niệm trọn đời.', title_zh = '今天最甜的瞬间 📸', body_zh = '今天他做了什么特别又好笑的动作？用宝宝写真里有趣的相框抓住那一刻，变成一辈子的回忆吧。' WHERE id = '0b41a1b3-ce5c-4804-b352-c95cc9725120' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Quiere comer solo! 🥦', body_es = '¿Está deseando ser independiente? Elige en Recetas para bebés que empiezan con la alimentación complementaria raciones deliciosas, fáciles de coger y que no se derramen.', title_fr = 'Il veut manger seul ! 🥦', body_fr = 'Il a soif d''autonomie ? Choisissez dans les Recettes pour bébés qui commencent la diversification des portions savoureuses, faciles à tenir et qui ne coulent pas.', title_hi = 'खुद खाना चाहता है! 🥦', body_hi = 'आत्मनिर्भर बनने को उत्सुक है? ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी से आसानी से पकड़े जाने वाले और न गिरने वाले स्वादिष्ट हिस्से चुनिए।', title_id = 'Ingin makan sendiri! 🥦', body_id = 'Ingin mandiri? Pilih porsi lezat yang mudah dipegang dan tidak mudah tumpah dari Resep untuk bayi yang mulai MPASI.', title_ja = '自分で食べたい！🥦', body_ja = '自分でやりたい気持ちがいっぱい？「離乳食を始める赤ちゃんのレシピ」から、持ちやすくてこぼれにくいおいしい一品を選びましょう。', title_ko = '혼자 먹고 싶어 해요! 🥦', body_ko = '스스로 하고 싶어 하나요? 이유식을 시작하는 아기를 위한 레시피에서 집기 쉽고 잘 흘리지 않는 맛있는 메뉴를 골라 보세요.', title_nl = 'Wil zelf eten! 🥦', body_nl = 'Wil je kindje graag zelfstandig zijn? Kies in Recepten voor baby''s die met bijvoeding beginnen lekkere porties die makkelijk vast te pakken zijn en niet morsen.', title_pl = 'Chce jeść sam! 🥦', body_pl = 'Rwie się do samodzielności? Wybierz z Przepisów dla niemowląt rozpoczynających rozszerzanie diety smaczne porcje, które łatwo chwycić i które się nie rozsypują.', title_pt = 'Quer comer sozinho! 🥦', body_pt = 'Anseia por independência? Escolha nas Receitas para bebés em diversificação alimentar porções deliciosas, fáceis de agarrar e que não se entornam.', title_sv = 'Vill äta själv! 🥦', body_sv = 'Längtar barnet efter självständighet? Välj goda portioner som är lätta att hålla och inte spills från Recept för bebisar som börjar med fast föda.', title_vi = 'Bé muốn tự ăn! 🥦', body_vi = 'Bé khao khát tự lập? Hãy chọn những phần ăn ngon miệng, dễ cầm và không rơi vãi từ mục Công thức cho bé bắt đầu ăn dặm.', title_zh = '想自己吃饭！🥦', body_zh = '渴望独立？从食谱板块的辅食宝宝食谱里选些容易拿、不容易撒的美味小份餐吧。' WHERE id = '136efb64-ddf1-465d-be06-c1f4f0ca13f2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cómo llevar la terquedad 🤖', body_es = '¿Dice que no a todo? Si no sabes cómo gestionar las rabietas de esta etapa, consulta ya con Anacan AI.', title_fr = 'Face à l''entêtement 🤖', body_fr = 'Il dit non à tout ? Si vous ne savez pas comment gérer les crises de cette période, demandez tout de suite conseil à Anacan AI.', title_hi = 'ज़िद से निपटना 🤖', body_hi = 'हर बात पर ''नहीं'' कहता है? अगर आप नहीं जानतीं कि इस दौर के नखरों को कैसे संभालें, तो तुरंत Anacan AI से सलाह लीजिए।', title_id = 'Menghadapi sikap keras kepala 🤖', body_id = 'Ia bilang tidak untuk segala hal? Kalau Anda tidak tahu cara menghadapi krisis di masa ini, segera konsultasikan dengan Anacan AI.', title_ja = 'いやいやとの付き合い方 🤖', body_ja = 'なんでも「いや」と言いますか？この時期のかんしゃくにどう対応すればいいかわからなければ、すぐにAnacan AIに相談しましょう。', title_ko = '고집과의 씨름 🤖', body_ko = '모든 것에 싫다고 하나요? 이 시기의 떼쓰기를 어떻게 다뤄야 할지 모르겠다면 바로 Anacan AI와 상담하세요.', title_nl = 'Omgaan met koppigheid 🤖', body_nl = 'Zegt je kindje overal nee tegen? Weet je niet hoe je de driftbuien in deze fase aanpakt? Overleg meteen met Anacan AI.', title_pl = 'Jak radzić sobie z uporem 🤖', body_pl = 'Na wszystko mówi „nie”? Jeśli nie wiesz, jak radzić sobie z kryzysami na tym etapie, od razu poradź się Anacan AI.', title_pt = 'Lidar com a teimosia 🤖', body_pt = 'Diz não a tudo? Se não sabe como gerir as crises desta fase, fale já com o Anacan AI.', title_sv = 'Att hantera trotset 🤖', body_sv = 'Säger barnet nej till allt? Om du inte vet hur du ska hantera utbrotten i den här perioden, rådfråga Anacan AI direkt.', title_vi = 'Đối phó với sự bướng bỉnh 🤖', body_vi = 'Bé nói "không" với mọi thứ? Nếu mẹ không biết cách xử lý những cơn khủng hoảng giai đoạn này, hãy hỏi ý kiến Anacan AI ngay.', title_zh = '应对倔脾气 🤖', body_zh = '什么都说“不”？如果不知道怎么应对这个阶段的情绪崩溃，马上咨询Anacan AI吧。' WHERE id = '37e233ca-794d-4595-8c1d-115d93279302' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Veamos cuánto duerme 😴', body_es = '¿Qué tal ha dormido esta noche? Revisa los registros del Temporizador de sueño y analiza si tu peque duerme lo que necesita cada día.', title_fr = 'Regardons ses besoins en sommeil 😴', body_fr = 'Comment a-t-il dormi cette nuit ? Consultez les données du minuteur de sommeil pour voir si votre enfant a eu son quota de sommeil quotidien.', title_hi = 'नींद का मानक देखें 😴', body_hi = 'रात को कैसे सोया? स्लीप टाइमर के रिकॉर्ड देखकर विश्लेषण कीजिए कि बच्चे ने रोज़ की नींद का मानक पूरा किया या नहीं।', title_id = 'Yuk, cek kebutuhan tidurnya 😴', body_id = 'Bagaimana tidurnya semalam? Lihat catatan Timer Tidur dan analisis apakah kebutuhan tidur harian si kecil sudah terpenuhi.', title_ja = '睡眠量をチェック 😴', body_ja = '昨夜はどう眠りましたか？睡眠タイマーの記録を見て、1日の睡眠量が足りているか分析しましょう。', title_ko = '수면량을 확인해요 😴', body_ko = '밤에 잘 잤나요? 수면 타이머 기록을 보며 아기가 하루 수면량을 채웠는지 분석해 보세요.', title_nl = 'Laten we naar de slaapbehoefte kijken 😴', body_nl = 'Hoe sliep je kindje vannacht? Bekijk de gegevens van de Slaaptimer en analyseer of hij zijn dagelijkse slaapbehoefte heeft gehaald.', title_pl = 'Sprawdźmy normę snu 😴', body_pl = 'Jak spał w nocy? Przejrzyj zapisy timera snu i sprawdź, czy maluszek osiąga dzienną normę snu.', title_pt = 'Vamos ver as horas de sono 😴', body_pt = 'Como dormiu esta noite? Consulte os registos do temporizador de sono e analise se o seu bebé cumpre as horas de sono diárias recomendadas.', title_sv = 'Vi kollar sömnnormen 😴', body_sv = 'Hur sov barnet i natt? Titta på sömntimerns anteckningar och analysera om barnet når sin dagliga sömnnorm.', title_vi = 'Cùng xem định mức giấc ngủ 😴', body_vi = 'Đêm qua bé ngủ thế nào? Hãy xem các ghi chép trong Bộ hẹn giờ ngủ để phân tích bé đã ngủ đủ định mức hằng ngày chưa.', title_zh = '看看睡眠参考量 😴', body_zh = '昨晚睡得怎么样？看看睡眠计时器的记录，分析宝宝是否达到了每日睡眠参考量。' WHERE id = '30a82706-c2b4-4804-8bf8-50b827b59af2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Tienes dudas sobre su desarrollo? Escribe a nuestro asistente experto Anacan AI, recibe respuestas con base científica y quédate tranquila.', body_fr = 'Des doutes sur le développement de votre enfant ? Écrivez à notre assistant expert Anacan AI pour obtenir des réponses fondées sur la science et être rassurée.', body_hi = 'बच्चे के विकास को लेकर कोई शंका है? हमारे Anacan AI विशेषज्ञ असिस्टेंट को लिखिए, वैज्ञानिक जवाब पाइए और निश्चिंत हो जाइए।', body_id = 'Ada keraguan tentang perkembangan si kecil? Tulis ke asisten ahli Anacan AI kami, dapatkan jawaban berbasis ilmiah, dan tenangkan diri.', body_ja = 'お子さんの発達で気になることはありますか？Anacan AIの専門アシスタントに書き込んで、科学的な根拠のある答えをもらい、安心しましょう。', body_ko = '아이 발달에 대해 의문이 있나요? Anacan AI 전문가 도우미에게 물어 과학적 근거가 있는 답을 받고 마음을 놓으세요.', body_nl = 'Twijfel je over de ontwikkeling van je kindje? Schrijf onze deskundige assistent Anacan AI, krijg wetenschappelijk onderbouwde antwoorden en stel jezelf gerust.', body_pl = 'Masz wątpliwości co do rozwoju dziecka? Napisz do naszego eksperckiego asystenta Anacan AI, otrzymaj odpowiedzi oparte na nauce i odetchnij.', body_pt = 'Tem dúvidas sobre o desenvolvimento do seu filho? Escreva ao nosso assistente especialista Anacan AI, receba respostas com base científica e fique descansada.', body_sv = 'Har du funderingar kring barnets utveckling? Skriv till vår expertassistent Anacan AI, få vetenskapligt grundade svar och slappna av.', body_vi = 'Mẹ có băn khoăn về sự phát triển của bé? Hãy nhắn cho trợ lý chuyên gia Anacan AI để nhận câu trả lời có cơ sở khoa học và yên tâm hơn.', body_zh = '对孩子的发育有疑问？给我们的Anacan AI专家助手留言，获得有科学依据的回答，让自己安心。' WHERE id = '63599f1b-cfac-43fe-af30-fa096e5c9039' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cada comida, un sabor distinto 🍲', body_es = 'Se acabó el dilema de «¿Qué cocino hoy?». En Recetas para bebés que empiezan con la alimentación complementaria tienes menús sanos y llenos de color.', title_fr = 'Une nouvelle saveur à chaque repas 🍲', body_fr = 'Fini le casse-tête « Qu''est-ce que je cuisine aujourd''hui ? ». Des menus colorés et sains vous attendent dans les Recettes pour bébés qui commencent la diversification.', title_hi = 'हर खाने में अलग स्वाद 🍲', body_hi = '''आज क्या बनाऊँ?'' की चिंता खत्म। ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी में आपके लिए रंग-बिरंगे और सेहतमंद मेन्यू हैं।', title_id = 'Setiap makan, rasa yang berbeda 🍲', body_id = 'Tak perlu pusing lagi soal "Hari ini masak apa?". Di Resep untuk bayi yang mulai MPASI ada menu berwarna-warni dan sehat untuk Anda.', title_ja = '毎回ちがう味を 🍲', body_ja = '「今日は何をつくろう？」の悩みはもうおしまい。「離乳食を始める赤ちゃんのレシピ」に、カラフルでヘルシーなメニューがそろっています。', title_ko = '끼니마다 다른 맛 🍲', body_ko = '''오늘은 뭘 만들지?'' 하는 고민은 끝이에요. 이유식을 시작하는 아기를 위한 레시피에 알록달록하고 건강한 메뉴가 준비되어 있어요.', title_nl = 'Elke maaltijd een andere smaak 🍲', body_nl = 'Geen gepieker meer over wat je vandaag moet koken. In Recepten voor baby''s die met bijvoeding beginnen vind je kleurrijke, gezonde menu''s.', title_pl = 'Każdy posiłek to nowy smak 🍲', body_pl = 'Koniec z dylematem „Co dziś ugotować?”. W Przepisach dla niemowląt rozpoczynających rozszerzanie diety czekają na ciebie kolorowe i zdrowe menu.', title_pt = 'Cada refeição, um sabor diferente 🍲', body_pt = 'Acabou a dúvida "O que cozinho hoje?". Nas Receitas para bebés em diversificação alimentar há ementas coloridas e saudáveis para si.', title_sv = 'Varje måltid en ny smak 🍲', body_sv = 'Bekymret ”Vad ska jag laga i dag?” är över. I Recept för bebisar som börjar med fast föda finns färgglada och nyttiga menyer åt dig.', title_vi = 'Mỗi bữa một hương vị mới 🍲', body_vi = 'Nỗi lo "Hôm nay nấu gì?" đã hết. Mục Công thức cho bé bắt đầu ăn dặm có những thực đơn đầy màu sắc và lành mạnh dành cho mẹ.', title_zh = '每一餐都有不同滋味 🍲', body_zh = '“今天做什么好？”的烦恼结束了。食谱板块的辅食宝宝食谱里有为你准备的丰富健康菜单。' WHERE id = 'c29b8ee7-5a3e-484e-b3fb-fba482038bb2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Informe diario de cacas 💩', body_es = '¡No olvides anotarlo al cambiar el pañal de la mañana! Seguir los cambios de pañal a lo largo del día muestra si toma suficiente líquido.', title_fr = 'Le bilan couches du jour 💩', body_fr = 'N''oubliez pas de noter le change du matin ! Suivre les changes de couche dans la journée montre si votre enfant boit suffisamment.', title_hi = 'रोज़ की पॉटी रिपोर्ट 💩', body_hi = 'सुबह का डायपर बदलते समय दर्ज करना मत भूलिए! दिनभर डायपर बदलने पर नज़र रखना दिखाता है कि बच्चे को पर्याप्त तरल मिल रहा है।', title_id = 'Laporan BAB harian 💩', body_id = 'Jangan lupa mencatat saat mengganti popok pagi! Memantau penggantian popok sepanjang hari menunjukkan apakah anak cukup mendapat cairan.', title_ja = '今日のうんちレポート 💩', body_ja = '朝のおむつ替えを記録するのを忘れずに！一日を通しておむつ替えを記録すると、水分が十分にとれているかがわかります。', title_ko = '하루 배변 리포트 💩', body_ko = '아침 기저귀를 갈 때 기록하는 걸 잊지 마세요! 하루 동안 기저귀 교체를 살피면 아이가 수분을 충분히 섭취하는지 알 수 있어요.', title_nl = 'Dagelijks poepverslag 💩', body_nl = 'Vergeet niet de ochtendluier te noteren! Als je de verschoningen overdag bijhoudt, zie je of je kindje genoeg vocht binnenkrijgt.', title_pl = 'Dzienny raport z pieluszki 💩', body_pl = 'Nie zapomnij zapisać porannej zmiany pieluszki! Śledzenie przewijań w ciągu dnia pokazuje, czy dziecko dostaje wystarczająco płynów.', title_pt = 'O relatório diário das fezes 💩', body_pt = 'Não se esqueça de registar a fralda da manhã quando a mudar! Acompanhar as mudas de fralda ao longo do dia mostra se a criança bebe líquidos suficientes.', title_sv = 'Daglig bajsrapport 💩', body_sv = 'Glöm inte att anteckna morgonens blöjbyte! Att följa blöjbytena under dagen visar att barnet får i sig tillräckligt med vätska.', title_vi = 'Báo cáo "đi nặng" hằng ngày 💩', body_vi = 'Đừng quên ghi lại khi thay tã buổi sáng! Theo dõi việc thay tã trong ngày cho biết bé có nạp đủ nước hay không.', title_zh = '每日便便报告 💩', body_zh = '换早上的尿布时别忘了记录！关注一天中的尿布更换，能看出孩子是否摄入了足够的水分。' WHERE id = '0c8639eb-e97c-4e44-a8d2-900ea16527d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también lo necesitas 🥗', body_es = '¿Te estás quedando sin energía? Prepara en Recetas saludables para mujeres un batido rico en vitaminas. ¡Tienes que estar fuerte!', title_fr = 'Vous aussi en avez besoin 🥗', body_fr = 'Votre énergie est presque à plat ? Préparez un smoothie riche en vitamines grâce aux Recettes saines pour femmes. Vous devez rester forte !', title_hi = 'आपको भी ज़रूरत है 🥗', body_hi = 'ऊर्जा खत्म होने वाली है? महिलाओं के लिए सेहतमंद रेसिपी से विटामिन से भरपूर स्मूदी बनाइए। आपको मज़बूत रहना है!', title_id = 'Anda juga butuh nutrisi 🥗', body_id = 'Energi Anda hampir habis? Buat smoothie kaya vitamin dari Resep Sehat untuk wanita. Anda harus tetap kuat!', title_ja = 'あなたにも必要です 🥗', body_ja = 'エネルギー切れ寸前？「女性のためのヘルシーレシピ」から、ビタミンたっぷりのスムージーをつくりましょう。あなたが元気でいることが大切です！', title_ko = '엄마에게도 필요해요 🥗', body_ko = '에너지가 바닥나기 직전인가요? 건강한 레시피에서 비타민 가득한 스무디를 만들어 보세요. 엄마는 튼튼해야 하니까요!', title_nl = 'Ook jij hebt het nodig 🥗', body_nl = 'Is je energie bijna op? Maak uit Gezonde recepten voor vrouwen een vitaminerijke smoothie. Je moet sterk blijven!', title_pl = 'Ty też tego potrzebujesz 🥗', body_pl = 'Energia na wyczerpaniu? Przygotuj ze Zdrowych przepisów dla kobiet smoothie bogate w witaminy. Musisz być silna!', title_pt = 'Também precisa de cuidados 🥗', body_pt = 'A energia está quase a acabar? Prepare nas Receitas Saudáveis para Mulheres um batido rico em vitaminas. Precisa de estar forte!', title_sv = 'Du behöver också 🥗', body_sv = 'Håller energin på att ta slut? Gör en vitaminrik smoothie från Hälsosamma recept för kvinnor. Du behöver vara stark!', title_vi = 'Mẹ cũng cần được chăm sóc 🥗', body_vi = 'Năng lượng của mẹ sắp cạn? Hãy làm một ly sinh tố giàu vitamin từ Công thức lành mạnh cho phụ nữ. Mẹ cần thật khỏe mạnh!', title_zh = '你也有需要 🥗', body_zh = '能量快耗尽了？从女性健康食谱里做一杯富含维生素的果昔吧。你需要保持强大！' WHERE id = 'c9a5ad78-ffcc-4191-a0f2-0e290d6c0364' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recuerdos inolvidables 🖼️', body_es = 'Para reírte en el futuro mirando sus monerías de hoy, sube sus fotos más bonitas al Álbum del bebé y guárdalas en un lugar seguro.', title_fr = 'Des souvenirs inoubliables 🖼️', body_fr = 'Pour sourire plus tard en revoyant ses mimiques d''aujourd''hui, ajoutez ses plus belles photos à l''Album de bébé et gardez-les en sécurité.', title_hi = 'न भूलने वाली यादें 🖼️', body_hi = 'आगे चलकर आज की प्यारी बातों पर मुस्कुराने के लिए उसकी सबसे सुंदर तस्वीरें बेबी एल्बम में अपलोड करके सुरक्षित रखिए।', title_id = 'Kenangan tak terlupakan 🖼️', body_id = 'Agar kelak bisa tertawa melihat kelucuannya hari ini, unggah foto-foto terbaiknya ke Album Bayi dan simpan di tempat yang aman.', title_ja = '忘れられない思い出 🖼️', body_ja = 'いつか今日のかわいい姿を見て笑えるように、いちばんすてきな写真を「ベビーアルバム」にアップして、大切に保存しましょう。', title_ko = '잊지 못할 추억 🖼️', body_ko = '훗날 오늘의 귀여운 모습을 보며 웃을 수 있도록 가장 멋진 사진을 아기 앨범에 올려 안전하게 보관하세요.', title_nl = 'Onvergetelijke herinneringen 🖼️', body_nl = 'Zet zijn mooiste foto''s in het Babyalbum en bewaar ze veilig, zodat je later om de lieve momenten van vandaag kunt lachen.', title_pl = 'Niezapomniane wspomnienia 🖼️', body_pl = 'Dodaj najpiękniejsze zdjęcia do Albumu dziecka i przechowuj je bezpiecznie, by kiedyś śmiać się, oglądając dzisiejsze słodkie chwile.', title_pt = 'Recordações inesquecíveis 🖼️', body_pt = 'Para se rir no futuro das gracinhas de hoje, carregue as fotos mais bonitas no Álbum do Bebé e guarde-as num lugar seguro.', title_sv = 'Oförglömliga minnen 🖼️', body_sv = 'Ladda upp de finaste bilderna i Babyalbumet och spara dem säkert, så att du kan titta på dagens söta stunder och skratta i framtiden.', title_vi = 'Những kỷ niệm khó quên 🖼️', body_vi = 'Hãy tải những bức ảnh đẹp nhất lên Album của bé để lưu giữ an toàn, để sau này mẹ có thể nhìn lại những nét đáng yêu hôm nay và mỉm cười.', title_zh = '难忘的回忆 🖼️', body_zh = '把最美的照片上传到宝宝相册安全保存，将来回看今天的可爱模样时还能笑出来。' WHERE id = 'd0842140-92ca-41c9-be61-ea76700b043c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo te has sentido hoy? 💖', body_es = 'Aunque estés muy cansada, en cuanto hueles a tu peque se te pasa todo, ¿verdad? Anota en el Diario de ánimo cómo te has sentido hoy y descansa.', title_fr = 'Comment vous êtes-vous sentie aujourd''hui ? 💖', body_fr = 'Même très fatiguée, il suffit de respirer son odeur pour que tout passe, n''est-ce pas ? Notez vos ressentis du jour dans le Journal d''humeur et reposez-vous.', title_hi = 'आज आपने क्या महसूस किया? 💖', body_hi = 'भले बहुत थक जाएँ, उसकी खुशबू लेते ही सब ठीक हो जाता है, है ना? मूड डायरी में आज की अपनी भावनाएँ दर्ज कीजिए और आराम कीजिए।', title_id = 'Apa yang Anda rasakan hari ini? 💖', body_id = 'Selelah apa pun Anda, semuanya hilang saat menghirup aroma tubuhnya, bukan? Catat perasaan Anda hari ini di Buku Harian Suasana Hati dan beristirahatlah.', title_ja = '今日はどんな気持ちでしたか？💖', body_ja = 'どんなに疲れても、お子さんの匂いをかぐと全部吹き飛びますよね？「気分日記」に今日の気持ちを記録して、ひと休みしましょう。', title_ko = '오늘 어떤 기분이었나요? 💖', body_ko = '아무리 지쳐도 아이 냄새를 맡으면 다 풀리죠? 기분 일기에 오늘의 감정을 기록하고 쉬세요.', title_nl = 'Hoe voelde je je vandaag? 💖', body_nl = 'Ook al ben je heel moe, als je aan je kindje ruikt, is alles over, toch? Schrijf je gevoelens van vandaag op in je Stemmingsdagboek en rust uit.', title_pl = 'Co dziś czułaś? 💖', body_pl = 'Nawet gdy jesteś bardzo zmęczona, wystarczy go powąchać i wszystko mija, prawda? Zapisz dzisiejsze uczucia w Dzienniku nastroju i odpocznij.', title_pt = 'O que sentiu hoje? 💖', body_pt = 'Por mais cansada que esteja, quando sente o cheirinho dele tudo passa, não é? Registe no Diário de Humor o que sentiu hoje e descanse.', title_sv = 'Hur kändes det i dag? 💖', body_sv = 'Även om du är väldigt trött försvinner allt när du luktar på barnet, eller hur? Anteckna dagens känslor i Humördagboken och vila.', title_vi = 'Hôm nay mẹ cảm thấy thế nào? 💖', body_vi = 'Dù mệt đến đâu, chỉ cần hít hà mùi hương của bé là mọi thứ tan biến, phải không? Hãy ghi lại cảm xúc hôm nay vào Nhật ký tâm trạng và nghỉ ngơi nhé.', title_zh = '今天你感觉怎么样？💖', body_zh = '再怎么累，闻一闻他的小脑袋，一切就都过去了，对吧？在心情日记里记下今天的感受，休息一下吧。' WHERE id = '4a60c9b7-f5e6-41f9-ba8e-fc0fbecf8b3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Comer con temporizador ⏱️', body_es = '¿Se pasa mucho rato en la mesa? Activa el temporizador de tomas, respeta las cantidades adecuadas y evita la falta de apetito.', title_fr = 'Des repas chronométrés ⏱️', body_fr = 'Il reste longtemps à table ? Lancez le minuteur des repas pour respecter le bon rythme et éviter le manque d''appétit.', title_hi = 'टाइमर के साथ खाना ⏱️', body_hi = 'खाने की मेज़ पर बहुत देर बैठता है? फ़ीडिंग टाइमर चालू कीजिए, मानक का पालन कीजिए और भूख न लगने से बचाइए।', title_id = 'Makan dengan timer ⏱️', body_id = 'Ia terlalu lama duduk di meja makan? Nyalakan Timer Makan, jaga porsinya, dan cegah hilangnya nafsu makan.', title_ja = 'タイマーで食事 ⏱️', body_ja = '食卓にいる時間が長すぎる？食事タイマーをオンにして、目安を守り、食欲不振を防ぎましょう。', title_ko = '타이머와 함께하는 식사 ⏱️', body_ko = '식탁에 너무 오래 앉아 있나요? 수유 타이머를 켜고 적정 시간을 지키며 입맛 없는 식사를 예방하세요.', title_nl = 'Eten met de timer ⏱️', body_nl = 'Zit je kindje lang aan tafel? Zet de voedingstimer aan, houd je aan de norm en voorkom gebrek aan eetlust.', title_pl = 'Posiłek z timerem ⏱️', body_pl = 'Długo siedzi przy stole? Włącz timer karmienia, trzymaj się normy i zapobiegaj brakowi apetytu.', title_pt = 'Refeições com temporizador ⏱️', body_pt = 'Fica muito tempo à mesa? Ligue o temporizador de alimentação, cumpra a quantidade recomendada e previna a falta de apetite.', title_sv = 'Måltid med timer ⏱️', body_sv = 'Sitter barnet länge vid matbordet? Starta matningstimern, håll normen och förebygg dålig aptit.', title_vi = 'Ăn uống có hẹn giờ ⏱️', body_vi = 'Bé ngồi bàn ăn quá lâu? Hãy bật bộ hẹn giờ trong Theo dõi cữ bú để giữ đúng định mức và phòng tránh biếng ăn.', title_zh = '用计时器吃饭 ⏱️', body_zh = '在餐桌前坐太久？打开喂养计时器，遵循参考量，防止食欲不振。' WHERE id = '965bee4a-5d90-4c53-aa89-40a47df609d3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de la mañana 🧩', body_es = '¡Aprendemos juntos! No te pierdas nuestro artículo del Blog sobre juegos que estimulan el desarrollo intelectual de los niños de 17,5 meses.', title_fr = 'Les jeux du matin 🧩', body_fr = 'On apprend ensemble ! Lisez absolument notre article dans les Blogs sur les jeux qui stimulent le développement intellectuel des enfants de 17,5 mois.', title_hi = 'सुबह के खेल 🧩', body_hi = 'साथ-साथ सीखते हैं! 17.5 महीने के बच्चों के दिमागी विकास में मदद करने वाले खेलों के बारे में ब्लॉग सेक्शन में हमारा लेख ज़रूर पढ़िए।', title_id = 'Permainan pagi 🧩', body_id = 'Ayo belajar bersama! Pastikan membaca artikel kami di bagian Blog tentang permainan yang mendukung perkembangan kecerdasan anak usia 17,5 bulan.', title_ja = '朝の遊び時間 🧩', body_ja = '一緒に学びましょう！1歳5か月半の子の知能の発達を応援する遊びについて、ブログの記事をぜひ読んでみてください。', title_ko = '아침 놀이 🧩', body_ko = '함께 배워요! 17.5개월 아이의 두뇌 발달을 돕는 놀이에 관한 블로그 글을 꼭 읽어 보세요.', title_nl = 'Spelletjes in de ochtend 🧩', body_nl = 'We leren samen! Lees zeker onze blog in het onderdeel Blogs over spelletjes die de verstandelijke ontwikkeling van kinderen van 17,5 maanden stimuleren.', title_pl = 'Poranne zabawy 🧩', body_pl = 'Uczymy się razem! Koniecznie przeczytaj nasz wpis w sekcji Blogi o zabawach wspierających rozwój umysłowy dzieci w wieku 17,5 miesiąca.', title_pt = 'Brincadeiras da manhã 🧩', body_pt = 'Aprendemos juntos! Não deixe de ler o nosso artigo na secção Blogues sobre jogos que apoiam o desenvolvimento cognitivo das crianças de 17,5 meses.', title_sv = 'Morgonlekar 🧩', body_sv = 'Vi lär oss tillsammans! Läs vårt inlägg i avsnittet Bloggar om lekar som stöttar den kognitiva utvecklingen hos barn på 17,5 månader.', title_vi = 'Trò chơi buổi sáng 🧩', body_vi = 'Cùng nhau học hỏi! Mẹ nhớ đọc bài viết trong mục Blog về những trò chơi hỗ trợ phát triển trí tuệ cho bé 17,5 tháng nhé.', title_zh = '上午的游戏 🧩', body_zh = '一起学习！一定要读读博客板块里关于促进17.5个月宝宝智力发展的游戏文章。' WHERE id = 'ff2d08b5-7a14-4db2-985e-1998a959811b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Agobiada en casa? ☕', body_es = 'Encuentra en Lugares para mamás la cafetería más cercana donde tú puedas tomar aire y tu peque pueda divertirse.', title_fr = 'La maison vous pèse ?☕', body_fr = 'Trouvez dans les Lieux adaptés aux mamans le café le plus proche où vous pourrez prendre l''air et où bébé pourra s''amuser.', title_hi = 'घर में घुटन हो रही है?☕', body_hi = 'माँ के लिए अनुकूल जगहों में सबसे पास का ऐसा कैफ़े ढूँढिए जहाँ आप भी ताज़ी हवा लें और बच्चा भी मज़े करे।', title_id = 'Bosan di rumah?☕', body_id = 'Temukan kafe terdekat di Tempat Ramah Ibu, tempat Anda bisa menghirup udara segar dan si kecil bisa bersenang-senang.', title_ja = '家にいて息がつまる？☕', body_ja = '「ママにやさしいスポット」で、あなたはひと息つけて、お子さんも楽しめるいちばん近くのカフェを見つけましょう。', title_ko = '집이 답답한가요?☕', body_ko = '엄마 친화 장소에서 엄마는 바람을 쐬고 아기는 즐겁게 놀 수 있는 가장 가까운 카페를 찾아보세요.', title_nl = 'Word je benauwd thuis?☕', body_nl = 'Zoek in Mamavriendelijke plekken het dichtstbijzijnde café waar jij even op adem komt en je kindje zich vermaakt.', title_pl = 'Dom cię przytłacza?☕', body_pl = 'Znajdź w Miejscach przyjaznych mamom najbliższą kawiarnię, w której ty złapiesz oddech, a maluszek się pobawi.', title_pt = 'A casa está a sufocá-la?☕', body_pt = 'Encontre nos Locais Amigos das Mães o café mais próximo, onde a mãe apanha ar e o bebé se diverte.', title_sv = 'Känns hemmet trångt?☕', body_sv = 'Hitta det närmaste kaféet i Mammavänliga platser där du kan få luft och barnet kan ha roligt.', title_vi = 'Ở nhà thấy ngột ngạt?☕', body_vi = 'Hãy tìm trong Địa điểm thân thiện với mẹ quán cà phê gần nhất để mẹ được hít thở không khí mới, còn bé được vui chơi.', title_zh = '在家闷得慌？☕', body_zh = '在妈妈友好场所里找一家最近的咖啡馆，你能透透气，宝宝也能玩得开心。' WHERE id = '85d64887-6099-4720-8a44-11c6766f10bb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cuando le dices «no» con tono serio se queda quieto y te mira? Ya entiende perfectamente las emociones y las prohibiciones. Mantén los límites.', body_fr = 'Quand vous dites non d''un ton sérieux, il s''arrête et vous regarde ? Il comprend désormais bien les émotions et les interdits. Tenez bon sur les limites.', body_hi = 'सख्त आवाज़ में ''नहीं'' कहने पर रुककर आपको देखता है? अब वह भावनाएँ और मनाही पूरी तरह समझता है। सीमाएँ बनाए रखिए।', body_id = 'Ia terdiam dan menatap Anda saat Anda bilang tidak dengan nada serius? Kini ia sepenuhnya memahami emosi dan larangan. Jaga batasannya.', body_ja = '真剣な声で「ダメ」と言うと、動きを止めてあなたを見ますか？もう気持ちや禁止をしっかり理解しています。ルールを守り続けましょう。', body_ko = '단호한 목소리로 "안 돼"라고 하면 멈칫하고 엄마를 바라보나요? 이제 감정과 금지를 확실히 이해해요. 한계를 지켜 주세요.', body_nl = 'Stopt je kindje en kijkt hij je aan als je met een serieuze stem nee zegt? Hij begrijpt nu goed wat emoties en verboden zijn. Bewaak de grenzen.', body_pl = 'Gdy mówisz „nie” poważnym tonem, zatrzymuje się i patrzy na ciebie? Już w pełni rozumie emocje i zakazy. Pilnuj granic.', body_pt = 'Quando lhe diz "não" com voz séria, fica parado a olhar para si? Já percebe bem as emoções e as proibições. Mantenha os limites.', body_sv = 'Stannar barnet upp och tittar på dig när du säger nej med allvarlig röst? Barnet förstår nu helt känslor och förbud. Håll gränserna.', body_vi = 'Mẹ nói "không" bằng giọng nghiêm túc là bé khựng lại và nhìn mẹ? Bé đã hiểu rõ cảm xúc và những điều cấm. Hãy giữ vững giới hạn.', body_zh = '你严肃地说“不”时，他会愣一下看着你？他已经完全能理解情绪和禁令了。守住边界吧。' WHERE id = 'aa709e76-dc89-4447-b36a-69ce62fbdfe6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Una hora antes de dormir, apaga todas las luces fuertes y las pantallas de casa. La melatonina solo se libera en un ambiente tranquilo.', body_fr = '1 heure avant le coucher, éteignez toutes les lumières vives et les écrans de la maison. La mélatonine n''est sécrétée que dans un environnement calme.', body_hi = 'सोने से 1 घंटा पहले घर की सारी तेज़ रोशनियाँ और स्क्रीन बंद कर दीजिए। मेलाटोनिन सिर्फ़ शांत माहौल में बनता है।', body_id = '1 jam sebelum tidur, matikan semua lampu terang dan layar di rumah. Melatonin hanya diproduksi di lingkungan yang tenang.', body_ja = '寝る1時間前には、家の明るい照明と画面をすべて消しましょう。メラトニンは落ち着いた環境でこそ分泌されます。', body_ko = '잠들기 1시간 전에는 집 안의 밝은 조명과 화면을 모두 끄세요. 멜라토닌은 차분한 환경에서만 분비돼요.', body_nl = 'Doe een uur voor het slapengaan alle felle lampen en schermen in huis uit. Melatonine wordt alleen in een rustige omgeving aangemaakt.', body_pl = 'Godzinę przed snem wyłącz w domu wszystkie mocne światła i ekrany. Melatonina wydziela się tylko w spokojnym otoczeniu.', body_pt = '1 hora antes de dormir, apague todas as luzes fortes e ecrãs da casa. A melatonina só é libertada num ambiente calmo.', body_sv = 'Släck alla starka lampor och skärmar i hemmet 1 timme före läggdags. Melatonin bildas bara i en lugn miljö.', body_vi = '1 tiếng trước giờ ngủ, hãy tắt hết đèn sáng và màn hình trong nhà. Melatonin chỉ được tiết ra trong môi trường yên tĩnh.', body_zh = '睡前1小时，关掉家里所有的昏暗灯光和屏幕。褪黑素只有在安静的环境中才会分泌。' WHERE id = 'd09c606d-f7bf-4df1-900d-b7cc38d34313' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Horas de sueño ⏱️', body_es = '¡A la cama! Activa el Temporizador de sueño. Analiza el horario para asegurarte de que duerme lo que necesita cada día.', title_fr = 'Les besoins en sommeil ⏱️', body_fr = 'Au lit ! Activez le minuteur de sommeil. Analysez le graphique pour vous assurer qu''il dort suffisamment chaque jour.', title_hi = 'नींद का मानक ⏱️', body_hi = 'सोने चलें! स्लीप टाइमर चालू कीजिए। यह पक्का करने के लिए कि वह रोज़ की नींद का मानक पूरा कर रहा है, चार्ट का विश्लेषण कीजिए।', title_id = 'Kebutuhan tidur ⏱️', body_id = 'Waktunya tidur! Aktifkan Timer Tidur. Analisis grafiknya untuk memastikan ia memenuhi kebutuhan tidur hariannya.', title_ja = '睡眠の目安 ⏱️', body_ja = 'さあ、ねんねの時間！睡眠タイマーをオンにしましょう。1日の睡眠量の目安を守れているか、記録を分析して確かめましょう。', title_ko = '수면량 ⏱️', body_ko = '잘 시간이에요! 수면 타이머를 켜세요. 하루 수면량을 잘 지키고 있는지 그래프를 분석해 확인하세요.', title_nl = 'Slaapbehoefte ⏱️', body_nl = 'Tijd voor bed! Zet de Slaaptimer aan. Analyseer het schema om zeker te zijn dat hij zijn dagelijkse slaap haalt.', title_pl = 'Norma snu ⏱️', body_pl = 'Idziemy spać! Włącz timer snu. Przeanalizuj wykres, by mieć pewność, że trzyma się dziennej normy snu.', title_pt = 'As horas de sono ⏱️', body_pt = 'Vamos para a cama! Ative o temporizador de sono. Analise o gráfico para confirmar que cumpre as horas de sono diárias recomendadas.', title_sv = 'Sömnnorm ⏱️', body_sv = 'Vi går och lägger oss! Aktivera sömntimern. Analysera schemat för att försäkra dig om att barnet når sin dagliga sömnnorm.', title_vi = 'Định mức giấc ngủ ⏱️', body_vi = 'Đi ngủ thôi! Hãy bật Bộ hẹn giờ ngủ. Phân tích biểu đồ để chắc chắn bé ngủ đủ định mức hằng ngày.', title_zh = '睡眠参考量 ⏱️', body_zh = '准备上床啦！打开睡眠计时器。分析图表，确认他达到了每日睡眠参考量。' WHERE id = '7c968d48-84d9-4e6e-9f71-708f424d13fc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuídate 🥗', body_es = '¿Cansada de correr detrás de tu peque? Descubre en Recetas saludables para mujeres una ensalada deliciosa que te dé energía al momento.', title_fr = 'Prenez soin de vous 🥗', body_fr = 'Fatiguée de lui courir après ? Découvrez une délicieuse salade revigorante dans les Recettes saines pour femmes.', title_hi = 'अपना ख्याल रखिए 🥗', body_hi = 'बच्चे के पीछे भागते-भागते थक गई हैं? महिलाओं के लिए सेहतमंद रेसिपी में तुरंत ऊर्जा देने वाला स्वादिष्ट सलाद खोजिए।', title_id = 'Rawat diri Anda 🥗', body_id = 'Lelah mengejar si kecil? Temukan salad lezat yang langsung memberi tenaga di Resep Sehat untuk wanita.', title_ja = '自分をいたわって 🥗', body_ja = 'お子さんを追いかけて疲れましたか？「女性のためのヘルシーレシピ」で、すぐに元気が出るおいしいサラダを見つけましょう。', title_ko = '나를 돌봐요 🥗', body_ko = '아이를 쫓아다니느라 지쳤나요? 건강한 레시피에서 바로 힘이 나는 맛있는 샐러드를 찾아보세요.', title_nl = 'Zorg voor jezelf 🥗', body_nl = 'Ben je moe van het achter je kindje aanrennen? Ontdek in Gezonde recepten voor vrouwen een lekkere salade die je meteen energie geeft.', title_pl = 'Zadbaj o siebie 🥗', body_pl = 'Zmęczyło cię bieganie za maluchem? Odkryj w Zdrowych przepisach dla kobiet smaczną sałatkę, która od razu doda ci energii.', title_pt = 'Cuide de si 🥗', body_pt = 'Está cansada de correr atrás da criança? Descubra nas Receitas Saudáveis para Mulheres uma salada deliciosa que dá energia na hora.', title_sv = 'Ta hand om dig själv 🥗', body_sv = 'Är du trött av att springa efter barnet? Upptäck en god sallad som ger energi direkt i Hälsosamma recept för kvinnor.', title_vi = 'Hãy chăm sóc bản thân 🥗', body_vi = 'Mẹ mệt vì chạy theo bé? Hãy khám phá một món salad ngon miệng, nạp năng lượng tức thì trong Công thức lành mạnh cho phụ nữ.', title_zh = '照顾好自己 🥗', body_zh = '追着孩子跑累坏了？在女性健康食谱里发现一款马上补充能量的美味沙拉吧。' WHERE id = '83a23b90-6573-48f0-bd8e-9924821c611c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Limpieza de la mañana 🧻', body_es = '¿Qué tal el primer cambio de pañal del día? Anota los datos de la caca en la app y sigue fácilmente cómo funciona su sistema digestivo.', title_fr = 'Le change du matin 🧻', body_fr = 'Comment s''est passé le premier change de la journée ? Notez les selles dans l''application et suivez facilement le fonctionnement de son système digestif.', title_hi = 'सुबह की सफ़ाई 🧻', body_hi = 'दिन का पहला डायपर बदलना कैसा रहा? पॉटी की जानकारी ऐप में दर्ज कीजिए और उसके पाचन तंत्र के काम पर आसानी से नज़र रखिए।', title_id = 'Bersih-bersih pagi 🧻', body_id = 'Bagaimana penggantian popok pertama hari ini? Catat data BAB-nya di aplikasi dan pantau kerja sistem pencernaannya dengan mudah.', title_ja = '朝のおむつチェック 🧻', body_ja = '今日最初のおむつ替えはどうでしたか？うんちの情報をアプリに記録して、おなかの調子をかんたんに見守りましょう。', title_ko = '아침 정리 🧻', body_ko = '오늘 첫 기저귀 교체는 어땠나요? 배변 정보를 앱에 기록하면 소화기 상태를 쉽게 살펴볼 수 있어요.', title_nl = 'Ochtendverschoning 🧻', body_nl = 'Hoe ging de eerste verschoning van de dag? Noteer de gegevens over de ontlasting in de app en volg makkelijk hoe zijn spijsvertering werkt.', title_pl = 'Poranne porządki 🧻', body_pl = 'Jak poszła pierwsza zmiana pieluszki? Zapisz informacje o kupce w aplikacji i łatwo śledź pracę jego układu pokarmowego.', title_pt = 'A limpeza da manhã 🧻', body_pt = 'Como correu a primeira muda de fralda do dia? Registe na app as informações das fezes e acompanhe com facilidade o funcionamento do sistema digestivo dele.', title_sv = 'Morgonstädning 🧻', body_sv = 'Hur gick dagens första blöjbyte? Anteckna informationen om bajset i appen och följ enkelt hur mage och tarm fungerar.', title_vi = 'Vệ sinh buổi sáng 🧻', body_vi = 'Lần thay tã đầu tiên trong ngày thế nào? Hãy ghi thông tin về phân vào ứng dụng để dễ dàng theo dõi hoạt động tiêu hóa của bé.', title_zh = '早晨的清洁 🧻', body_zh = '今天第一次换尿布怎么样？把便便情况记到应用里，轻松关注他的肠胃状况。' WHERE id = 'e949f663-9f46-4fb4-8e24-07f0556f19ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recuerdos tiernos 📸', body_es = 'Añade al Álbum del bebé lo más gracioso que ha hecho hoy. Dentro de unos años, al repasar estas fotos, os reiréis muchísimo.', title_fr = 'De doux souvenirs 📸', body_fr = 'Ajoutez à l''Album de bébé la chose la plus drôle qu''il a faite aujourd''hui. Dans quelques années, vous rirez beaucoup en revoyant ces images.', title_hi = 'प्यारी यादें 📸', body_hi = 'आज की उसकी सबसे मज़ेदार हरकत बेबी एल्बम में जोड़िए। सालों बाद ये तस्वीरें पलटते हुए आप खूब हँसेंगी।', title_id = 'Kenangan manis 📸', body_id = 'Tambahkan tingkah paling lucunya hari ini ke Album Bayi. Bertahun-tahun kemudian, Anda akan tertawa lepas saat melihat foto-foto ini.', title_ja = 'かわいい思い出 📸', body_ja = '今日いちばんおもしろかったしぐさを「ベビーアルバム」に追加しましょう。何年かたってこの写真を見返したら、きっと大笑いしますよ。', title_ko = '달콤한 추억 📸', body_ko = '오늘 가장 웃겼던 행동을 아기 앨범에 추가하세요. 몇 년 뒤 이 사진들을 넘겨 보며 많이 웃게 될 거예요.', title_nl = 'Lieve herinneringen 📸', body_nl = 'Zet het grappigste wat je kindje vandaag deed in het Babyalbum. Als je over jaren door deze foto''s bladert, moet je vast heel erg lachen.', title_pl = 'Słodkie wspomnienia 📸', body_pl = 'Dodaj do Albumu dziecka najzabawniejszą rzecz, którą dziś zrobił. Za kilka lat, przeglądając te ujęcia, będziecie się świetnie bawić.', title_pt = 'Doces recordações 📸', body_pt = 'Adicione ao Álbum do Bebé o gesto mais engraçado que ele fez hoje. Daqui a muitos anos, vai rir-se imenso ao folhear estas imagens.', title_sv = 'Söta minnen 📸', body_sv = 'Lägg till det roligaste barnet gjorde i dag i Babyalbumet. Om många år kommer du att bläddra bland bilderna och skratta mycket.', title_vi = 'Những kỷ niệm ngọt ngào 📸', body_vi = 'Hãy thêm hành động ngộ nghĩnh nhất hôm nay của bé vào Album của bé. Nhiều năm sau, lật lại những khung hình này mẹ sẽ cười rất nhiều.', title_zh = '甜蜜的回忆 📸', body_zh = '把他今天最好笑的动作加进宝宝相册。多年后翻看这些照片，你们一定会笑个不停。' WHERE id = '317a6a9f-9ea0-4356-ac6b-713b806d7195' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Vaso antiderrame 🥤', body_es = '¿Le encanta beber agua mientras corretea, pero se empapa? Echa un vistazo en Productos recomendados a los vasos más cómodos que eligen otras mamás.', title_fr = 'La gourde anti-fuite 🥤', body_fr = 'Il adore boire en courant, mais se mouille tout ? Jetez un œil aux gourdes les plus pratiques choisies par les mamans dans les Produits recommandés.', title_hi = 'न छलकने वाला सिपी कप 🥤', body_hi = 'दौड़ते हुए पानी पीना पसंद है, पर कपड़े भिगो लेता है? सुझाए गए प्रोडक्ट सेक्शन में माँओं के चुने सबसे आरामदायक सिपी कप देखिए।', title_id = 'Botol minum anti tumpah 🥤', body_id = 'Ia suka minum sambil berlari, tapi bajunya jadi basah? Lihat botol minum paling praktis pilihan para ibu di bagian Produk Rekomendasi.', title_ja = 'こぼれにくいマグ 🥤', body_ja = '走りながらお水を飲むのが好きだけど、いつも服がびしょびしょ？「おすすめ商品」で、ママたちが選んだいちばん使いやすいマグをチェックしましょう。', title_ko = '새지 않는 물병 🥤', body_ko = '뛰어다니며 물 마시길 좋아하지만 옷을 다 적시나요? 추천 제품 섹션에서 엄마들이 고른 가장 편한 물병을 둘러보세요.', title_nl = 'Lekvrije drinkbeker 🥤', body_nl = 'Drinkt je kindje graag water terwijl hij rondrent, maar wordt hij er nat van? Bekijk in Aanbevolen producten de handigste drinkbekers die moeders kozen.', title_pl = 'Kubek, który się nie wylewa 🥤', body_pl = 'Lubi pić w biegu, ale cały się oblewa? Zajrzyj do sekcji Polecane produkty po najwygodniejsze kubki wybrane przez mamy.', title_pt = 'Copo antiderrame 🥤', body_pt = 'Adora beber água enquanto corre, mas molha-se todo? Espreite na secção Produtos Recomendados os copos mais práticos escolhidos pelas mães.', title_sv = 'Spillfri pipmugg 🥤', body_sv = 'Älskar barnet att dricka vatten i farten, men blir blött? Titta på de bekvämaste pipmuggarna som mammor valt i avsnittet Rekommenderade produkter.', title_vi = 'Bình tập uống chống tràn 🥤', body_vi = 'Bé thích vừa chạy vừa uống nước nhưng lại làm ướt hết người? Hãy xem những chiếc bình tập uống tiện lợi nhất được các mẹ chọn trong mục Sản phẩm gợi ý.', title_zh = '防漏水杯 🥤', body_zh = '他喜欢边跑边喝水，却把身上弄湿？看看推荐商品里妈妈们挑选的最好用的水杯吧。' WHERE id = 'c56a5aef-ad55-4a58-b85d-04ee040e2457' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Se le queda pequeña la ropa! 📏', body_es = '¿Las mangas le vuelven a quedar cortas? Introduce sus nuevas medidas en el Registro de peso y comprueba con orgullo en la gráfica cuánto ha crecido y engordado.', title_fr = 'Les vêtements rapetissent ! 📏', body_fr = 'Ses manches sont encore trop courtes ? Saisissez ses nouvelles mesures dans le Suivi du poids et regardez fièrement sa taille et son poids progresser sur la courbe.', title_hi = 'कपड़े छोटे हो रहे हैं! 📏', body_hi = 'नन्हे की बाँहें फिर छोटी पड़ गईं? वेट ट्रैकर में नए आँकड़े डालिए और विकास के चार्ट में लंबाई और वज़न की बढ़त गर्व से देखिए।', title_id = 'Bajunya kekecilan! 📏', body_id = 'Lengan baju si kecil makin pendek lagi? Masukkan ukuran terbarunya di Pelacak Berat Badan dan lihat dengan bangga pertambahan tinggi dan beratnya di grafik pertumbuhan.', title_ja = 'お洋服が小さくなってきた！📏', body_ja = 'また袖が短くなりましたか？「体重トラッカー」に新しい数値を入れて、身長と体重の伸びを成長グラフで誇らしく確認しましょう。', title_ko = '옷이 작아져요! 📏', body_ko = '아이 소매가 또 짧아졌나요? 체중 기록에 새 수치를 입력하고 키와 몸무게가 자란 모습을 성장 그래프에서 뿌듯하게 확인하세요.', title_nl = 'De kleertjes worden te klein! 📏', body_nl = 'Zijn de mouwen van je kleintje alweer te kort? Voer de nieuwe gegevens in de Gewichtstracker in en bekijk trots de groei in lengte en gewicht op de groeicurve.', title_pl = 'Ubranka robią się za małe! 📏', body_pl = 'Rękawki znów są za krótkie? Wpisz nowe pomiary w Liczniku wagi i z dumą sprawdź na wykresie rozwoju przyrost wzrostu i wagi.', title_pt = 'A roupa está a ficar pequena! 📏', body_pt = 'As mangas voltaram a ficar curtas? Introduza as novas medidas no Registo de Peso e veja com orgulho no gráfico de crescimento o aumento da altura e do peso.', title_sv = 'Kläderna blir för små! 📏', body_sv = 'Har ärmarna blivit korta igen? Skriv in de nya måtten i Viktspåraren och kolla med stolthet längd- och viktökningen i tillväxtkurvan.', title_vi = 'Quần áo chật rồi! 📏', body_vi = 'Tay áo của bé lại ngắn rồi? Hãy nhập số đo mới vào Theo dõi cân nặng và tự hào xem chiều cao, cân nặng tăng lên trên biểu đồ phát triển.', title_zh = '衣服变小了！📏', body_zh = '小家伙的袖子又短了？在体重记录里输入新数据，自豪地从成长曲线上看看身高和体重的增长吧。' WHERE id = 'e0699b25-a664-453e-b3a5-a31644bae458' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Ya puede entretenerse solo con sus juguetes durante 10-15 minutos. Su capacidad de atención se alarga. Disfruta del silencio.', body_fr = 'Il sait déjà s''occuper seul avec ses jouets pendant 10-15 minutes. Son attention s''allonge. Savourez le calme.', body_hi = 'अब वह 10-15 मिनट अपने खिलौनों में अकेले मगन रह सकता है। यह उसके ध्यान का दायरा बढ़ने का संकेत है। शांति का मज़ा लीजिए।', body_id = 'Kini ia bisa asyik sendiri dengan mainannya selama 10-15 menit. Ini tanda rentang perhatiannya makin panjang. Nikmati ketenangannya.', body_ja = 'もう10-15分はひとりでおもちゃで遊べるようになりました。集中できる時間が長くなっている証拠です。静かなひとときを味わいましょう。', body_ko = '이제 10-15분 동안 혼자 장난감을 가지고 놀 수 있어요. 집중하는 시간이 길어지고 있다는 뜻이에요. 고요함을 즐겨 보세요.', body_nl = 'Je kindje kan zich nu 10-15 minuten alleen met zijn speelgoed vermaken. Zijn concentratie wordt langer. Geniet van de stilte.', body_pl = 'Potrafi już przez 10-15 minut sam zająć się zabawkami. To znak, że wydłuża się jego skupienie uwagi. Delektuj się ciszą.', body_pt = 'Já consegue entreter-se sozinho com os brinquedos 10-15 minutos. É a capacidade de atenção a aumentar. Aproveite o silêncio.', body_sv = 'Nu kan barnet sysselsätta sig själv med leksakerna i 10-15 minuter. Uppmärksamheten håller längre. Njut av tystnaden.', body_vi = 'Bé đã có thể tự chơi với đồ chơi 10-15 phút. Đó là dấu hiệu khả năng tập trung đang dài ra. Hãy tận hưởng chút yên tĩnh nhé.', body_zh = '宝宝已经能自己玩玩具10-15分钟了。这说明他的专注时间在变长。享受这份安静吧。' WHERE id = '281783cf-f4b1-478b-9c23-4859307143e4' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Fuera el tiempo no está muy claro? ⛅', body_es = 'Deja que Tiempo y ropa te diga al momento la velocidad del viento que no se ve desde la ventana y la ropa adecuada.', title_fr = 'Le temps est incertain dehors ? ⛅', body_fr = 'Laissez l''outil Météo et tenue vous indiquer tout de suite la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue.', title_hi = 'बाहर का मौसम साफ़ नहीं है? ⛅', body_hi = 'मौसम और कपड़े टूल तुरंत वह हवा की रफ़्तार और सही कपड़े बता देगा जो खिड़की से नहीं दिखते।', title_id = 'Cuaca di luar kurang jelas? ⛅', body_id = 'Biarkan fitur Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan pakaian yang tepat.', title_ja = '外の天気がはっきりしない？⛅', body_ja = '窓からは見えない風の強さとぴったりのコーデを、「天気と服装」がすぐに教えてくれます。', title_ko = '바깥 날씨가 애매한가요? ⛅', body_ko = '창밖으로는 보이지 않는 바람 세기와 알맞은 옷차림을 날씨와 옷차림 도구가 바로 알려 줄 거예요.', title_nl = 'Is het weer buiten niet helemaal duidelijk? ⛅', body_nl = 'Laat de tool Weer en kleding je meteen de windsnelheid die je vanuit het raam niet ziet en de juiste outfit vertellen.', title_pl = 'Pogoda na dworze niepewna? ⛅', body_pl = 'Niech narzędzie Pogoda i ubiór od razu poda ci prędkość wiatru, której nie widać przez okno, i odpowiedni zestaw.', title_pt = 'O tempo lá fora não está bem limpo? ⛅', body_pt = 'Deixe que o Tempo e Roupa lhe diga na hora a velocidade do vento que não se vê da janela e a combinação certa.', title_sv = 'Är vädret ute inte helt klart? ⛅', body_sv = 'Låt verktyget Väder och kläder direkt berätta vindhastigheten som du inte ser genom fönstret och rätt klädsel.', title_vi = 'Thời tiết bên ngoài không rõ ràng? ⛅', body_vi = 'Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được và bộ đồ phù hợp.', title_zh = '外面天气说不准？⛅', body_zh = '让天气穿衣工具马上告诉你窗外看不出的风速和合适的搭配。' WHERE id = '64f775c3-f09d-4993-a954-437681ccf730' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando se duerma, daos un masaje de hombros el uno al otro con tu pareja para soltar el estrés del día. ¡Sois un equipo!', body_fr = 'Une fois qu''il dort, massez-vous les épaules à tour de rôle avec votre conjoint pour évacuer le stress de la journée. Vous êtes une équipe !', body_hi = 'बच्चे के सोने के बाद दिन का तनाव निकालने के लिए अपने पार्टनर के साथ एक-दूसरे के कंधों की मालिश कीजिए। आप एक टीम हैं!', body_id = 'Setelah si kecil tidur, lepaskan stres hari ini dengan saling memijat bahu bersama pasangan. Kalian satu tim!', body_ja = 'お子さんが寝たら、一日のストレスを解消するために、パートナーと肩をもみ合いましょう。おふたりはチームです！', body_ko = '아이가 잠들면 하루의 스트레스를 풀 수 있게 배우자와 서로 어깨를 주물러 주세요. 두 사람은 한 팀이에요!', body_nl = 'Geef elkaar als je kindje slaapt een schoudermassage om de stress van de dag kwijt te raken. Jullie zijn een team!', body_pl = 'Gdy maluszek zaśnie, zróbcie sobie z partnerem nawzajem masaż ramion, by zrzucić stres dnia. Jesteście zespołem!', body_pt = 'Depois de a criança adormecer, façam uma massagem aos ombros um ao outro para libertar o stress do dia. Vocês são uma equipa!', body_sv = 'När barnet har somnat, ge varandra en axelmassage med din partner för att släppa dagens stress. Ni är ett team!', body_vi = 'Khi bé ngủ, hãy cùng bố xoa bóp vai cho nhau để xua tan căng thẳng trong ngày. Hai người là một đội!', body_zh = '宝宝睡着后，和伴侣互相按按肩膀，卸下一天的压力吧。你们是一个团队！' WHERE id = '6ca7a3a7-3202-4bdf-87de-b43d04388374' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Depósito de vitaminas 🥦', body_es = 'Revisa el menú de hoy con el Seguimiento de tomas. ¡Para las vitaminas que falten, te esperan raciones llenas de color en Recetas para bebé!', title_fr = 'Le plein de vitamines 🥦', body_fr = 'Vérifiez son menu du jour avec le Suivi des repas. Pour les vitamines qui manquent, des portions colorées vous attendent dans les Recettes pour bébés !', title_hi = 'विटामिन का खज़ाना 🥦', body_hi = 'फ़ीडिंग ट्रैकर से आज का मेन्यू जाँचिए। कम विटामिन के लिए बच्चों की रेसिपी में रंग-बिरंगे हिस्से आपका इंतज़ार कर रहे हैं!', title_id = 'Gudang vitamin 🥦', body_id = 'Periksa menu hari ini dengan alat Pemantau Makan. Untuk vitamin yang kurang, porsi berwarna-warni menanti Anda di Resep Bayi!', title_ja = 'ビタミンをたっぷり 🥦', body_ja = '「栄養管理ツール」で今日のメニューをチェックしましょう。足りないビタミンには、ベビーレシピのカラフルな一品が待っています！', title_ko = '비타민 창고 🥦', body_ko = '수유 기록 도구로 오늘 식단을 확인해 보세요. 부족한 비타민은 아기 레시피의 알록달록한 메뉴로 채울 수 있어요!', title_nl = 'Een voorraad vitaminen 🥦', body_nl = 'Controleer het menu van vandaag met de Voedingstracker. Voor ontbrekende vitaminen wachten kleurrijke porties op je in de babyrecepten!', title_pl = 'Skarbnica witamin 🥦', body_pl = 'Sprawdź dzisiejsze menu w narzędziu do śledzenia karmienia. Na brakujące witaminy czekają kolorowe porcje w Przepisach dla maluszka!', title_pt = 'Uma reserva de vitaminas 🥦', body_pt = 'Verifique a ementa de hoje com o Registo de Alimentação. Para as vitaminas em falta, esperam-na porções coloridas nas Receitas para bebés!', title_sv = 'Vitaminförråd 🥦', body_sv = 'Kolla dagens meny med Matningskoll. För vitaminer som saknas väntar färgglada portioner i Babyrecept!', title_vi = 'Kho vitamin 🥦', body_vi = 'Hãy kiểm tra thực đơn hôm nay bằng công cụ Theo dõi cữ bú. Để bổ sung vitamin còn thiếu, những phần ăn đầy màu sắc trong Công thức cho bé đang chờ mẹ!', title_zh = '维生素补给站 🥦', body_zh = '用喂养记录工具检查今天的菜单。宝宝食谱里有色彩丰富的小份餐，帮你补上缺少的维生素！' WHERE id = '23c1e329-cee4-4d43-89e7-04f3883f2a24' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Está muy terco? 🤖', body_es = '¿No para de decir «no»? Recibe de nuestro asistente Anacan AI consejos psicológicos con base científica para gestionar las rabietas de un niño de 17,5 meses.', title_fr = 'Il est très têtu ? 🤖', body_fr = 'Le mot « non » ne quitte plus ses lèvres ? Obtenez auprès de notre assistant Anacan AI des conseils psychologiques fondés sur la science pour gérer les crises de votre enfant de 17,5 mois.', title_hi = 'बहुत ज़िद्दी है? 🤖', body_hi = '''नहीं'' शब्द ज़ुबान से उतरता ही नहीं? 17.5 महीने के बच्चे के नखरे संभालने के लिए हमारे Anacan AI असिस्टेंट से वैज्ञानिक मनोवैज्ञानिक सलाह लीजिए।', title_id = 'Ia sangat keras kepala? 🤖', body_id = 'Kata "tidak" tak pernah lepas dari mulutnya? Dapatkan saran psikologis berbasis ilmiah dari asisten Anacan AI kami untuk menghadapi krisis anak usia 17,5 bulan.', title_ja = 'いやいやが強い？🤖', body_ja = '「いや」が口ぐせになっていますか？1歳5か月半の子のかんしゃくへの対応について、Anacan AIアシスタントから科学的な根拠のある心理的アドバイスをもらいましょう。', title_ko = '고집이 너무 센가요? 🤖', body_ko = '"싫어"라는 말을 입에 달고 사나요? 17.5개월 아이의 떼쓰기를 다루는 과학적 근거가 있는 심리 조언을 Anacan AI 도우미에게 받아 보세요.', title_nl = 'Is hij erg koppig? 🤖', body_nl = 'Zegt je kindje de hele dag nee? Krijg van onze assistent Anacan AI wetenschappelijk onderbouwd psychologisch advies voor de driftbuien van je kindje van 17,5 maanden.', title_pl = 'Bardzo uparty? 🤖', body_pl = 'Ciągle tylko „nie”? Otrzymaj od naszego asystenta Anacan AI oparte na nauce rady psychologiczne, jak radzić sobie z kryzysami 17,5-miesięcznego dziecka.', title_pt = 'Anda muito teimoso? 🤖', body_pt = 'A palavra "não" não lhe sai da boca? Receba do nosso assistente Anacan AI conselhos psicológicos com base científica para gerir as crises de uma criança de 17,5 meses.', title_sv = 'Är barnet väldigt envist? 🤖', body_sv = 'Är ordet nej ständigt på läpparna? Få vetenskapligt grundade psykologiska råd från vår assistent Anacan AI om hur du hanterar utbrotten hos ett barn på 17,5 månader.', title_vi = 'Bé bướng bỉnh quá? 🤖', body_vi = 'Bé nói "không" suốt ngày? Hãy nhận lời khuyên tâm lý có cơ sở khoa học từ trợ lý Anacan AI để xử lý những cơn khủng hoảng của bé 17,5 tháng.', title_zh = '特别倔？🤖', body_zh = '“不”字总挂在嘴边？向我们的Anacan AI助手获取有科学依据的心理建议，应对17.5个月宝宝的情绪崩溃。' WHERE id = '2450b85b-f956-4dd3-b9ad-11b269818238' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una noche llena de calma 🌊', body_es = 'Es hora de crear calma en la habitación. Pon el sonido de las olas del mar en Ruido blanco y ayuda a su sistema nervioso a pasar a un sueño profundo.', title_fr = 'Une soirée paisible 🌊', body_fr = 'C''est l''heure d''apaiser la chambre. Lancez les vagues de l''océan dans les Bruits blancs pour aider son système nerveux à plonger dans un sommeil profond.', title_hi = 'सुकून भरी शाम 🌊', body_hi = 'कमरे में शांति बनाने का समय है। व्हाइट नॉइज़ से समुद्र की लहरें चलाइए और उसके नर्वस सिस्टम को गहरी नींद में जाने में मदद कीजिए।', title_id = 'Malam penuh ketenangan 🌊', body_id = 'Saatnya menciptakan ketenangan di kamar. Putar suara ombak laut dari Suara Putih dan bantu sistem sarafnya beralih ke tidur nyenyak.', title_ja = '穏やかな夜 🌊', body_ja = '部屋を静かな雰囲気にする時間です。「ホワイトノイズ」から波の音を流して、神経が深い眠りへと移るのを助けてあげましょう。', title_ko = '평온한 저녁 🌊', body_ko = '방을 차분하게 만들 시간이에요. 백색소음에서 파도 소리를 틀어 신경계가 깊은 잠으로 넘어가도록 도와주세요.', title_nl = 'Een rustige avond 🌊', body_nl = 'Tijd om rust in de kamer te brengen. Zet in Witte ruis de golven van de oceaan aan en help zijn zenuwstelsel om diep in slaap te vallen.', title_pl = 'Spokojny wieczór 🌊', body_pl = 'Czas wyciszyć pokój. Włącz w Białym szumie fale oceanu i pomóż jego układowi nerwowemu przejść w głęboki sen.', title_pt = 'Uma noite tranquila 🌊', body_pt = 'É altura de criar calma no quarto. Ligue o som das ondas do mar no Ruído Branco e ajude o sistema nervoso dele a passar para um sono profundo.', title_sv = 'En kväll full av ro 🌊', body_sv = 'Det är dags att skapa lugn i rummet. Sätt på havsvågor i Vitt brus och hjälp nervsystemet att gå över i djup sömn.', title_vi = 'Buổi tối bình yên 🌊', body_vi = 'Đã đến lúc tạo sự yên tĩnh trong phòng. Hãy bật tiếng sóng biển trong Tiếng ồn trắng để giúp hệ thần kinh của bé chìm vào giấc ngủ sâu.', title_zh = '宁静的夜晚 🌊', body_zh = '是时候让房间安静下来了。在白噪音里放海浪声，帮他的神经系统进入深睡。' WHERE id = '91b9e4eb-ca6a-4a90-94bc-2abf486852f9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba en la mesa ⏱️', body_es = '¿La comida se alarga demasiado? Activa el temporizador de tomas para respetar las cantidades y analizar las causas de la falta de apetito.', title_fr = 'L''épreuve du repas ⏱️', body_fr = 'Le repas s''éternise ? Lancez le minuteur des repas pour respecter le bon rythme et analyser les causes de son manque d''appétit.', title_hi = 'खाने की मेज़ की परीक्षा ⏱️', body_hi = 'खाने का समय बहुत लंबा खिंचता है? फ़ीडिंग टाइमर चालू कीजिए, मानक का पालन भी कीजिए और भूख न लगने की वजहों का विश्लेषण भी।', title_id = 'Ujian di meja makan ⏱️', body_id = 'Waktu makannya terlalu lama? Nyalakan Timer Makan, jaga porsinya, sekaligus analisis penyebab hilangnya nafsu makan.', title_ja = '食卓のチャレンジ ⏱️', body_ja = '食事の時間が長くなりすぎる？食事タイマーをオンにして、目安を守りつつ、食欲がない原因も分析しましょう。', title_ko = '식탁 시험 ⏱️', body_ko = '식사 시간이 너무 길어지나요? 수유 타이머를 켜서 적정 시간을 지키고, 입맛이 없는 이유도 분석해 보세요.', title_nl = 'De test aan tafel ⏱️', body_nl = 'Duurt het eten te lang? Zet de voedingstimer aan, houd je aan de norm en analyseer waarom hij weinig trek heeft.', title_pl = 'Próba przy stole ⏱️', body_pl = 'Posiłki bardzo się przeciągają? Włącz timer karmienia, trzymaj się normy i przeanalizuj przyczyny braku apetytu.', title_pt = 'O desafio da mesa ⏱️', body_pt = 'A refeição está a durar demasiado? Ligue o temporizador de alimentação, cumpra a quantidade recomendada e analise as causas da falta de apetite.', title_sv = 'Prövning vid matbordet ⏱️', body_sv = 'Drar måltiden ut på tiden? Starta matningstimern, håll normen och analysera orsakerna till den dåliga aptiten.', title_vi = 'Thử thách bàn ăn ⏱️', body_vi = 'Giờ ăn kéo dài quá lâu? Hãy bật bộ hẹn giờ trong Theo dõi cữ bú để vừa giữ đúng định mức, vừa phân tích nguyên nhân biếng ăn.', title_zh = '餐桌考验 ⏱️', body_zh = '吃饭时间拖得太长？打开喂养计时器，既遵循参考量，又能分析食欲不振的原因。' WHERE id = '60f75637-7bb2-4f09-8e04-1616cc3f6b3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia diaria 📝', body_es = 'Ser madre a veces es una montaña rusa emocional. Abre el Diario de ánimo, vuelca en el papel el cansancio de hoy y quítate un peso de encima.', title_fr = 'La thérapie du jour 📝', body_fr = 'Être maman, c''est parfois des montagnes russes émotionnelles. Ouvrez le Journal d''humeur, couchez votre fatigue du jour sur le papier et sentez-vous plus légère.', title_hi = 'रोज़ की थेरेपी 📝', body_hi = 'माँ बनना कभी-कभी भावनाओं की रेलगाड़ी जैसा है। मूड डायरी खोलिए, आज की थकान शब्दों में उतारिए और हल्का महसूस कीजिए।', title_id = 'Terapi harian 📝', body_id = 'Menjadi ibu kadang seperti naik roller coaster emosi. Buka Buku Harian Suasana Hati, tuangkan rasa lelah hari ini ke dalam tulisan, dan rasakan lega.', title_ja = '毎日のセラピー 📝', body_ja = '子育てはときに感情のジェットコースターのよう。「気分日記」を開いて、今日の疲れを言葉にして、気持ちを軽くしましょう。', title_ko = '매일의 테라피 📝', body_ko = '엄마로 사는 건 가끔 감정의 롤러코스터 같아요. 기분 일기를 열고 오늘의 피로를 글로 쏟아 내며 마음을 가볍게 하세요.', title_nl = 'Dagelijkse therapie 📝', body_nl = 'Het moederschap is soms een emotionele achtbaan. Open je Stemmingsdagboek, schrijf je vermoeidheid van vandaag van je af en voel je lichter.', title_pl = 'Codzienna terapia 📝', body_pl = 'Macierzyństwo bywa czasem emocjonalnym rollercoasterem. Otwórz Dziennik nastroju, przelej dzisiejsze zmęczenie na papier i poczuj ulgę.', title_pt = 'A terapia diária 📝', body_pt = 'A maternidade às vezes parece uma montanha-russa de emoções. Abra o Diário de Humor, passe para o papel o cansaço de hoje e sinta-se mais leve.', title_sv = 'Daglig terapi 📝', body_sv = 'Moderskapet är ibland som en känslomässig berg-och-dalbana. Öppna Humördagboken, skriv ner dagens trötthet och känn dig lättare.', title_vi = 'Liệu pháp mỗi ngày 📝', body_vi = 'Làm mẹ đôi khi như chuyến tàu cảm xúc. Hãy mở Nhật ký tâm trạng, trút sự mệt mỏi hôm nay vào từng dòng chữ để nhẹ lòng hơn.', title_zh = '每日疗愈 📝', body_zh = '当妈妈有时就像坐情绪过山车。打开心情日记，把今天的疲惫倾注在字里行间，让自己轻松一些。' WHERE id = '8773c2dd-9938-4a61-a038-72940b1c0339' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Es la hora del café! ☕', body_es = '¿Agobiada entre cuatro paredes? Encuentra en Lugares para mamás una cafetería a la que ir cómodamente con tu peque y date un capricho.', title_fr = 'C''est l''heure du café ☕', body_fr = 'Les quatre murs de la maison vous pèsent ? Trouvez dans les Lieux adaptés aux mamans un café où aller facilement avec votre enfant, et faites-vous plaisir.', title_hi = 'कॉफ़ी का समय आ गया ☕', body_hi = 'घर की चार दीवारों से ऊब गई हैं? माँ के लिए अनुकूल जगहों में ऐसा कैफ़े ढूँढिए जहाँ बच्चे के साथ आराम से जा सकें, और खुद को खुश कीजिए।', title_id = 'Waktunya ngopi ☕', body_id = 'Bosan terkurung di empat dinding rumah? Temukan kafe yang nyaman dikunjungi bersama anak di Tempat Ramah Ibu dan senangkan diri Anda.', title_ja = 'コーヒータイム ☕', body_ja = '家の中にこもって息がつまりそう？「ママにやさしいスポット」で子連れで気軽に行けるカフェを見つけて、自分を喜ばせてあげましょう。', title_ko = '커피 타임이에요 ☕', body_ko = '집 안 네 벽이 답답한가요? 엄마 친화 장소에서 아이와 편하게 갈 수 있는 카페를 찾아 나에게 기쁨을 선물하세요.', title_nl = 'Tijd voor koffie ☕', body_nl = 'Word je benauwd van de vier muren thuis? Zoek in Mamavriendelijke plekken een café waar je makkelijk met je kindje naartoe kunt en verwen jezelf.', title_pl = 'Czas na kawę ☕', body_pl = 'Masz dość czterech ścian? Znajdź w Miejscach przyjaznych mamom kawiarnię, do której wygodnie pójdziesz z dzieckiem, i zrób sobie przyjemność.', title_pt = 'Chegou a hora do café ☕', body_pt = 'Está farta das quatro paredes de casa? Encontre nos Locais Amigos das Mães um café onde possa ir à vontade com a criança e dê-se um mimo.', title_sv = 'Dags för kaffe ☕', body_sv = 'Har du tröttnat på hemmets fyra väggar? Hitta ett kafé i Mammavänliga platser dit du lätt kan gå med barnet och unna dig något.', title_vi = 'Đến giờ cà phê rồi ☕', body_vi = 'Mẹ thấy ngột ngạt giữa bốn bức tường? Hãy tìm một quán cà phê tiện đưa bé đi cùng trong Địa điểm thân thiện với mẹ và tự thưởng cho mình niềm vui nhỏ.', title_zh = '咖啡时间到 ☕', body_zh = '被家里的四面墙闷坏了？在妈妈友好场所里找一家适合带娃的咖啡馆，让自己开心一下吧。' WHERE id = 'da198266-6b56-4801-ac35-87e201ed0cda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te preocupa el desarrollo del lenguaje de tu peque de 18 meses? Pregunta a Anacan AI qué palabras son normales a esta edad.', body_fr = 'Le langage de votre enfant de 18 mois vous inquiète ? Demandez à Anacan AI quels mots sont normaux à cet âge.', body_hi = '18 महीने के बच्चे की भाषा के विकास को लेकर चिंता है? Anacan AI से पूछिए और जानिए कि कितने शब्द सामान्य हैं।', body_id = 'Khawatir dengan perkembangan bahasa anak 18 bulan Anda? Tanyakan ke Anacan AI dan cari tahu kata-kata apa yang normal di usia ini.', body_ja = '1歳6か月の子の言葉の発達が気になりますか？Anacan AIに聞いて、どんな言葉が出ていれば普通なのか確かめましょう。', body_ko = '18개월 아이의 언어 발달이 걱정되나요? Anacan AI에게 물어 어떤 단어 수준이 정상인지 알아보세요.', body_nl = 'Maak je je zorgen over de taalontwikkeling van je kindje van 18 maanden? Vraag het Anacan AI en ontdek welke woorden normaal zijn.', body_pl = 'Martwisz się rozwojem mowy 18-miesięcznego dziecka? Zapytaj Anacan AI i dowiedz się, ile słów to norma.', body_pt = 'Está preocupada com o desenvolvimento da linguagem de uma criança de 18 meses? Pergunte ao Anacan AI e saiba que palavras são normais nesta idade.', body_sv = 'Är du orolig för språkutvecklingen hos ditt barn på 18 månader? Fråga Anacan AI och ta reda på vilka ord som är normala.', body_vi = 'Mẹ lo lắng về sự phát triển ngôn ngữ của bé 18 tháng? Hãy hỏi Anacan AI để biết những từ nào là bình thường ở tuổi này.', body_zh = '担心18个月宝宝的语言发展？问问Anacan AI，了解说哪些词是正常的。' WHERE id = 'cee8912e-bf87-4d52-b0d0-309e7583f3e5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis del sueño con temporizador ⏱️', body_es = '¿Sus siestas son cada vez más cortas? Activa el Temporizador de sueño, analiza el horario de esta semana y ajusta de nuevo la hora de acostarle.', title_fr = 'Analyser le sommeil avec le minuteur ⏱️', body_fr = 'Sa sieste raccourcit ? Lancez le minuteur de sommeil, analysez le planning de la semaine et réajustez l''heure du coucher.', title_hi = 'टाइमर से नींद का विश्लेषण ⏱️', body_hi = 'दिन की झपकी छोटी हो रही है? स्लीप टाइमर चालू कीजिए, इस हफ़्ते के चार्ट का विश्लेषण करके शाम की नींद का समय फिर से तय कीजिए।', title_id = 'Analisis tidur dengan timer ⏱️', body_id = 'Tidur siangnya makin pendek? Nyalakan Timer Tidur, analisis grafik minggu ini, dan atur ulang jam tidur malamnya.', title_ja = 'タイマーで睡眠を分析 ⏱️', body_ja = 'お昼寝が短くなってきた？睡眠タイマーをオンにして、今週の記録を分析し、夜の就寝時間を調整し直しましょう。', title_ko = '타이머로 수면 분석 ⏱️', body_ko = '낮잠이 짧아지고 있나요? 수면 타이머를 켜고 이번 주 그래프를 분석해 저녁 잠자리 시간을 다시 맞춰 보세요.', title_nl = 'Slaapanalyse met de timer ⏱️', body_nl = 'Wordt het middagdutje korter? Zet de Slaaptimer aan, analyseer het schema van deze week en stel de bedtijd ''s avonds opnieuw in.', title_pl = 'Analiza snu z timerem ⏱️', body_pl = 'Drzemka się skraca? Włącz timer snu, przeanalizuj wykres z tego tygodnia i na nowo ustal porę wieczornego snu.', title_pt = 'Analisar o sono com o temporizador ⏱️', body_pt = 'A sesta está a ficar mais curta? Ligue o temporizador de sono, analise o gráfico desta semana e reajuste a hora de dormir à noite.', title_sv = 'Sömnanalys med timer ⏱️', body_sv = 'Blir dagsluren kortare? Starta sömntimern, analysera veckans schema och justera tiden för kvällssömnen.', title_vi = 'Phân tích giấc ngủ bằng bộ hẹn giờ ⏱️', body_vi = 'Giấc ngủ ngày ngắn lại? Hãy bật Bộ hẹn giờ ngủ, phân tích biểu đồ tuần này và điều chỉnh lại giờ đi ngủ buổi tối.', title_zh = '用计时器分析睡眠 ⏱️', body_zh = '白天小睡变短了？打开睡眠计时器，分析这周的图表，重新调整晚上的睡觉时间吧。' WHERE id = 'c0292e27-64a9-4ecc-95f9-37e4ccbb6b7d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Apoyaos el uno al otro! 💖', title_fr = 'Soutenez-vous l''un l''autre ! 💖', title_hi = 'एक-दूसरे का सहारा बनिए! 💖', title_id = 'Saling mendukung! 💖', title_ja = '支え合いましょう！💖', title_ko = '서로에게 힘이 되어 주세요! 💖', title_nl = 'Steun elkaar! 💖', title_pl = 'Wspierajcie się nawzajem! 💖', title_pt = 'Apoiem-se um ao outro! 💖', title_sv = 'Stötta varandra! 💖', title_vi = 'Hãy hỗ trợ lẫn nhau! 💖', title_zh = '互相支持吧！💖' WHERE id = 'fda065c2-2893-4c1e-858b-19c095a29529' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Salto intelectual 🧠', body_es = '¿Qué está pasando en el cerebro de tu peque? Lee en nuestro Blog el artículo más reciente sobre el desarrollo cognitivo de los niños de 17-18 meses.', title_fr = 'Un bond intellectuel 🧠', body_fr = 'Que se passe-t-il dans le cerveau de votre enfant ? Lisez dans les Blogs notre dernier article sur le développement cognitif des enfants de 17-18 mois.', title_hi = 'दिमागी छलांग 🧠', body_hi = 'आपके बच्चे के दिमाग में क्या चल रहा है? ब्लॉग सेक्शन में 17-18 महीने के बच्चों के संज्ञानात्मक विकास पर सबसे नया लेख पढ़िए।', title_id = 'Lompatan kecerdasan 🧠', body_id = 'Apa yang terjadi di otak si kecil? Baca artikel terbaru di bagian Blog tentang perkembangan kognitif anak usia 17-18 bulan.', title_ja = '知能の飛躍 🧠', body_ja = 'お子さんの脳では何が起きているのでしょう？ブログで、1歳5-6か月の子の認知の発達についての最新記事を読んでみましょう。', title_ko = '두뇌 도약 🧠', body_ko = '아기의 뇌에서는 무슨 일이 일어나고 있을까요? 블로그 섹션에서 17-18개월 아이의 인지 발달에 관한 최신 글을 읽어 보세요.', title_nl = 'Een sprong in het verstand 🧠', body_nl = 'Wat gebeurt er in het hoofdje van je kindje? Lees in het onderdeel Blogs het nieuwste artikel over de verstandelijke ontwikkeling van kinderen van 17-18 maanden.', title_pl = 'Skok umysłowy 🧠', body_pl = 'Co dzieje się w głowie twojego dziecka? Przeczytaj w sekcji Blogi najnowszy artykuł o rozwoju poznawczym dzieci w wieku 17-18 miesięcy.', title_pt = 'Salto de inteligência 🧠', body_pt = 'O que se passa no cérebro do seu bebé? Leia na secção Blogues o artigo mais recente sobre o desenvolvimento cognitivo das crianças de 17-18 meses.', title_sv = 'Intelligenssprång 🧠', body_sv = 'Vad händer i barnets hjärna? Läs den senaste artikeln i avsnittet Bloggar om den kognitiva utvecklingen hos barn på 17-18 månader.', title_vi = 'Bước nhảy trí tuệ 🧠', body_vi = 'Điều gì đang diễn ra trong não bé? Hãy đọc bài viết mới nhất về sự phát triển nhận thức của trẻ 17-18 tháng trong mục Blog.', title_zh = '智力飞跃 🧠', body_zh = '宝宝的大脑里正在发生什么？读读博客板块里关于17-18个月宝宝认知发展的最新文章吧。' WHERE id = '815e2a58-ed5b-46c4-bdc7-5775cc6d2d5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Horario de sueño ⏱️', body_es = '¿Han cambiado sus horas de despertarse? Revisa las estadísticas del Temporizador de sueño y analiza el equilibrio entre la siesta y el sueño nocturno.', title_fr = 'Le planning de sommeil ⏱️', body_fr = 'Ses heures de réveil ont changé ? Consultez les statistiques du minuteur de sommeil pour bien analyser l''équilibre entre siestes et nuit.', title_hi = 'नींद का शेड्यूल ⏱️', body_hi = 'जागने का समय बदल गया है? स्लीप टाइमर के आँकड़े देखकर दिन और रात की नींद के बीच के संतुलन का अच्छे से विश्लेषण कीजिए।', title_id = 'Jadwal tidur ⏱️', body_id = 'Jam bangunnya berubah? Lihat statistik Timer Tidur dan analisis keseimbangan tidur siang dan malamnya dengan sempurna.', title_ja = '睡眠スケジュール ⏱️', body_ja = '起きる時間が変わってきた？睡眠タイマーの統計を見て、お昼寝と夜の睡眠のバランスをしっかり分析しましょう。', title_ko = '수면 일정 ⏱️', body_ko = '깨는 시간이 달라졌나요? 수면 타이머 통계를 보며 낮잠과 밤잠의 균형을 꼼꼼히 분석해 보세요.', title_nl = 'Slaapschema ⏱️', body_nl = 'Zijn de tijden van wakker worden veranderd? Bekijk de cijfers van de Slaaptimer en analyseer de balans tussen dag- en nachtslaap.', title_pl = 'Plan snu ⏱️', body_pl = 'Zmieniły się pory pobudek? Sprawdź statystyki timera snu i dokładnie przeanalizuj równowagę między snem w dzień i w nocy.', title_pt = 'O horário do sono ⏱️', body_pt = 'As horas de acordar mudaram? Consulte as estatísticas do temporizador de sono e analise na perfeição o equilíbrio entre a sesta e o sono noturno.', title_sv = 'Sömnschema ⏱️', body_sv = 'Har uppvakningstiderna ändrats? Titta på sömntimerns statistik och analysera balansen mellan dag- och nattsömn perfekt.', title_vi = 'Lịch ngủ ⏱️', body_vi = 'Giờ thức dậy của bé đã thay đổi? Hãy xem thống kê của Bộ hẹn giờ ngủ để phân tích sự cân bằng giữa giấc ngủ ngày và đêm.', title_zh = '睡眠时间表 ⏱️', body_zh = '醒来的时间变了？看看睡眠计时器的统计，好好分析白天小睡和夜间睡眠之间的平衡吧。' WHERE id = '87dc449d-a56d-419b-bdab-000fd5ed38fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Informe de la mañana 💩', body_es = 'El sistema digestivo es el primer indicador de salud. Al cambiar el pañal, anota en la app cómo es la caca y sigue los cambios a lo largo del día.', title_fr = 'Le bilan du matin 💩', body_fr = 'La digestion est le premier indicateur de santé. Lors du change, notez les selles dans l''application et suivez les changements au fil de la journée.', title_hi = 'सुबह की रिपोर्ट 💩', body_hi = 'सेहत का पहला संकेत पाचन तंत्र है। डायपर बदलते समय पॉटी की जानकारी ऐप में जोड़िए और दिनभर के बदलावों पर नज़र रखिए।', title_id = 'Laporan pagi 💩', body_id = 'Indikator pertama kesehatan adalah sistem pencernaan. Saat mengganti popok, tambahkan catatan BAB ke aplikasi dan pantau perubahannya sepanjang hari.', title_ja = '朝のうんちレポート 💩', body_ja = '健康のいちばんのサインは消化です。おむつ替えのときにうんちの記録をアプリに追加して、一日の変化を見守りましょう。', title_ko = '아침 리포트 💩', body_ko = '건강의 첫 번째 신호는 소화 기관이에요. 기저귀를 갈 때 배변 기록을 앱에 추가하고 하루 동안의 변화를 살펴보세요.', title_nl = 'Ochtendverslag 💩', body_nl = 'De spijsvertering is de eerste graadmeter van gezondheid. Voeg bij het verschonen notities over de ontlasting toe in de app en volg de veranderingen gedurende de dag.', title_pl = 'Poranny raport 💩', body_pl = 'Pierwszym wskaźnikiem zdrowia jest układ pokarmowy. Przy przewijaniu zapisuj w aplikacji informacje o kupce i śledź zmiany w ciągu dnia.', title_pt = 'O relatório da manhã 💩', body_pt = 'O primeiro indicador de saúde é o sistema digestivo. Ao mudar a fralda, adicione à app as notas sobre as fezes e acompanhe as mudanças ao longo do dia.', title_sv = 'Morgonrapport 💩', body_sv = 'Matsmältningen är det första tecknet på hälsa. Lägg in anteckningar om bajset i appen när du byter blöja och följ förändringarna under dagen.', title_vi = 'Báo cáo buổi sáng 💩', body_vi = 'Hệ tiêu hóa là dấu hiệu đầu tiên của sức khỏe. Khi thay tã, hãy ghi chú về phân vào ứng dụng và theo dõi những thay đổi trong ngày.', title_zh = '早晨报告 💩', body_zh = '健康的第一个指标就是消化系统。换尿布时把便便记录添加到应用里，关注一天中的变化。' WHERE id = '4c6d197d-5cde-42e9-b88b-05a62b37e397' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeña estrella 🌟', body_es = '¡No te pierdas esa sonrisa tan dulce! Inmortaliza su estado de ánimo de hoy con los temas divertidos de la Sesión de fotos del bebé.', title_fr = 'Petite étoile 🌟', body_fr = 'Ne manquez pas ce joli sourire ! Immortalisez son humeur du jour avec les thèmes amusants de la Séance photo bébé.', title_hi = 'नन्हा सितारा 🌟', body_hi = 'इस प्यारी मुस्कान को मत चूकिए! बेबी फ़ोटोशूट टूल की दिलचस्प थीम से उसके आज के मूड को हमेशा के लिए सहेज लीजिए।', title_id = 'Bintang kecil 🌟', body_id = 'Jangan lewatkan senyum manis ini! Abadikan suasana hatinya hari ini dengan tema-tema menarik di Sesi Foto Bayi.', title_ja = '小さなスター 🌟', body_ja = 'このかわいい笑顔を見逃さないで！「ベビーフォトセッション」の楽しいテーマで、今日の表情を残しましょう。', title_ko = '작은 별 🌟', body_ko = '이 사랑스러운 미소를 놓치지 마세요! 아기 사진 촬영 도구의 재미있는 테마로 오늘의 기분을 영원히 남기세요.', title_nl = 'Kleine ster 🌟', body_nl = 'Mis die lieve glimlach niet! Leg de stemming van vandaag vast met de leuke thema''s in de tool Babyfotoshoot.', title_pl = 'Mała gwiazdka 🌟', body_pl = 'Nie przegap tego słodkiego uśmiechu! Uwiecznij jego dzisiejszy nastrój z ciekawymi motywami w narzędziu Sesja zdjęciowa dziecka.', title_pt = 'Pequena estrela 🌟', body_pt = 'Não perca este sorriso doce! Eternize o humor de hoje com os temas divertidos da Sessão Fotográfica do Bebé.', title_sv = 'Lilla stjärna 🌟', body_sv = 'Missa inte det söta leendet! Förevig dagens humör med de roliga temana i verktyget Babyfotografering.', title_vi = 'Ngôi sao nhỏ 🌟', body_vi = 'Đừng bỏ lỡ nụ cười ngọt ngào này! Hãy lưu giữ tâm trạng hôm nay của bé với những chủ đề thú vị trong công cụ Chụp ảnh cho bé.', title_zh = '小星星 🌟', body_zh = '别错过这个甜甜的微笑！用宝宝写真工具里有趣的主题，把他今天的好心情永远留住吧。' WHERE id = 'e59af63b-a407-459e-a6f1-a0263d9f74f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedícate tiempo 🍵', body_es = 'Ya duerme; ahora te toca a ti recuperar fuerzas. Prepárate una infusión relajante de Recetas saludables.', title_fr = 'Prenez du temps pour vous 🍵', body_fr = 'Il dort, c''est maintenant à votre corps de récupérer. Préparez une tisane apaisante grâce aux Recettes saines.', title_hi = 'अपने लिए समय निकालिए 🍵', body_hi = 'बच्चा सो गया, अब अपने शरीर को फिर से तरोताज़ा करने की आपकी बारी है। सेहतमंद रेसिपी से सुकून देने वाली हर्बल चाय बनाइए।', title_id = 'Luangkan waktu untuk diri sendiri 🍵', body_id = 'Si kecil sudah tidur, sekarang giliran Anda memulihkan tubuh. Seduh teh herbal yang menenangkan dari Resep Sehat.', title_ja = '自分の時間をつくろう 🍵', body_ja = 'お子さんが寝ました。今度はあなたが体を回復させる番です。「ヘルシーレシピ」から、心落ち着くハーブティーをいれましょう。', title_ko = '나를 위한 시간을 내세요 🍵', body_ko = '아이가 잠들었으니 이제 엄마가 몸을 회복할 차례예요. 건강한 레시피에서 마음을 차분하게 해 주는 허브차를 우려 보세요.', title_nl = 'Neem tijd voor jezelf 🍵', body_nl = 'Je kindje slaapt, nu is het jouw beurt om je lichaam te laten herstellen. Zet een rustgevende kruidenthee uit Gezonde recepten.', title_pl = 'Znajdź czas dla siebie 🍵', body_pl = 'Maluszek śpi, teraz twoja kolej, by zregenerować ciało. Zaparz kojącą herbatkę ziołową ze zdrowych przepisów.', title_pt = 'Reserve tempo para si 🍵', body_pt = 'Ele adormeceu, agora é a sua vez de recuperar o corpo. Prepare nas Receitas Saudáveis uma infusão calmante.', title_sv = 'Ta tid för dig själv 🍵', body_sv = 'Barnet sover, nu är det din tur att återhämta kroppen. Brygg ett lugnande örtte från Hälsosamma recept.', title_vi = 'Dành thời gian cho bản thân 🍵', body_vi = 'Bé ngủ rồi, giờ đến lượt mẹ hồi phục cơ thể. Hãy pha một tách trà thảo mộc thư giãn từ Công thức lành mạnh.', title_zh = '给自己留点时间 🍵', body_zh = '宝宝睡了，现在轮到你恢复身体了。从健康食谱里泡一杯安神的花草茶吧。' WHERE id = 'f71b2bf0-976d-4844-8538-db17781ce999' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juguete adecuado 🧩', body_es = '¿Buscas un juguete que desarrolle su lógica? Descubre en Productos recomendados puzles adecuados a su edad y beneficiosos.', title_fr = 'Le bon jouet 🧩', body_fr = 'Vous cherchez un jouet qui développe sa logique ? Découvrez dans les Produits recommandés des puzzles utiles et adaptés à son âge.', title_hi = 'सही खिलौना 🧩', body_hi = 'उसकी तर्क शक्ति बढ़ाने वाला खिलौना ढूँढ रही हैं? सुझाए गए प्रोडक्ट सेक्शन में उम्र के हिसाब से उपयोगी पज़ल के विकल्प देखिए।', title_id = 'Mainan yang tepat 🧩', body_id = 'Mencari mainan yang mengembangkan logikanya? Temukan pilihan puzzle yang sesuai usia dan bermanfaat di bagian Produk Rekomendasi.', title_ja = 'ぴったりのおもちゃ 🧩', body_ja = '考える力を育てるおもちゃを探していますか？「おすすめ商品」で、年齢に合った役立つパズルを見つけましょう。', title_ko = '알맞은 장난감 🧩', body_ko = '논리력을 키워 줄 장난감을 찾고 있나요? 추천 제품 섹션에서 나이에 맞고 유익한 퍼즐을 찾아보세요.', title_nl = 'Het juiste speelgoed 🧩', body_nl = 'Zoek je speelgoed dat zijn logisch denken stimuleert? Ontdek in het onderdeel Aanbevolen producten nuttige puzzels die passen bij zijn leeftijd.', title_pl = 'Odpowiednia zabawka 🧩', body_pl = 'Szukasz zabawki, która rozwinie logiczne myślenie? Odkryj w sekcji Polecane produkty pożyteczne układanki odpowiednie do wieku.', title_pt = 'O brinquedo certo 🧩', body_pt = 'Procura um brinquedo que desenvolva o raciocínio lógico? Descubra na secção Produtos Recomendados puzzles úteis e adequados à idade.', title_sv = 'Rätt leksak 🧩', body_sv = 'Letar du efter en leksak som utvecklar logiken? Upptäck åldersanpassade och nyttiga pussel (puzzle) i avsnittet Rekommenderade produkter.', title_vi = 'Đồ chơi phù hợp 🧩', body_vi = 'Mẹ đang tìm đồ chơi phát triển tư duy? Hãy khám phá những bộ xếp hình phù hợp lứa tuổi và bổ ích trong mục Sản phẩm gợi ý.', title_zh = '合适的玩具 🧩', body_zh = '在找能锻炼逻辑思维的玩具？去推荐商品里发现适合年龄、有益的拼图选择吧。' WHERE id = '91d67474-6689-4302-b69e-a9b260aedef7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rutina de la noche 🌙', body_es = 'Acostarle cada día a la misma hora crea un hábito. Activa el Temporizador de sueño, revisa cuánto duerme y disfruta de un sueño sin esfuerzo.', title_fr = 'Le rituel du soir 🌙', body_fr = 'Le coucher à heure fixe chaque jour crée une habitude. Lancez le minuteur de sommeil, vérifiez ses besoins et profitez d''un endormissement facile.', title_hi = 'रात का रूटीन 🌙', body_hi = 'हर दिन एक ही समय पर सुलाने से आदत बनती है। स्लीप टाइमर चालू कीजिए, नींद का मानक जाँचिए और आसान नींद का आनंद लीजिए।', title_id = 'Rutinitas malam 🌙', body_id = 'Menidurkannya di jam yang sama setiap hari membentuk kebiasaan. Nyalakan Timer Tidur, periksa kebutuhan tidurnya, dan nikmati tidur yang mudah.', title_ja = '夜の習慣 🌙', body_ja = '毎日同じ時間に寝かせると、習慣になります。睡眠タイマーをオンにして睡眠量をチェックし、スムーズな寝つきを楽しみましょう。', title_ko = '밤 루틴 🌙', body_ko = '매일 같은 시간에 재우면 습관이 생겨요. 수면 타이머를 켜고 수면량을 확인하며 편안한 잠을 누려 보세요.', title_nl = 'Avondroutine 🌙', body_nl = 'Elke dag op hetzelfde tijdstip naar bed brengen schept een gewoonte. Zet de Slaaptimer aan, controleer zijn slaapbehoefte en geniet van makkelijk inslapen.', title_pl = 'Wieczorna rutyna 🌙', body_pl = 'Usypianie codziennie o tej samej porze tworzy nawyk. Włącz timer snu, sprawdź normę i ciesz się łatwym zasypianiem.', title_pt = 'A rotina da noite 🌙', body_pt = 'Deitá-lo todos os dias à mesma hora cria um hábito. Ligue o temporizador de sono, verifique as horas de sono e aproveite um adormecer fácil.', title_sv = 'Kvällsrutin 🌙', body_sv = 'Att natta barnet vid samma tid varje dag skapar en vana. Starta sömntimern, kolla normen och njut av ett lätt insomnande.', title_vi = 'Nếp ngủ buổi tối 🌙', body_vi = 'Cho bé ngủ cùng một giờ mỗi ngày sẽ tạo thành thói quen. Hãy bật Bộ hẹn giờ ngủ, kiểm tra định mức và tận hưởng những giấc ngủ dễ dàng.', title_zh = '睡前程序 🌙', body_zh = '每天同一时间哄睡能养成习惯。打开睡眠计时器，看看睡眠参考量，享受轻松入睡吧。' WHERE id = 'c5a6eac8-e59c-4b94-98cf-eb7be52db9a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crecemos sanos 📈', body_es = '¡Ya casi tiene 18 meses! Analiza su ritmo de crecimiento con el Registro de peso y comprueba si su altura y su peso están dentro de lo normal.', title_fr = 'On grandit en bonne santé 📈', body_fr = 'Bientôt 18 mois ! Analysez son rythme de croissance dans le Suivi du poids et vérifiez que sa taille et son poids sont dans la norme.', title_hi = 'सेहत के साथ बढ़ रहे हैं 📈', body_hi = '18वाँ महीना करीब है! वेट ट्रैकर टूल में विकास की रफ़्तार का विश्लेषण कीजिए और जाँचिए कि लंबाई और वज़न मानक के अनुसार हैं।', title_id = 'Tumbuh sehat 📈', body_id = 'Bulan ke-18 sudah dekat! Analisis laju pertumbuhannya dengan Pelacak Berat Badan dan periksa apakah tinggi dan beratnya sesuai standar.', title_ja = '健やかに成長中 📈', body_ja = 'もうすぐ1歳6か月！「体重トラッカー」で成長のスピードを分析し、身長と体重が目安に合っているか確認しましょう。', title_ko = '건강하게 자라요 📈', body_ko = '18개월이 얼마 남지 않았어요! 체중 기록 도구로 성장 속도를 분석하고 키와 몸무게가 정상 범위인지 확인하세요.', title_nl = 'We groeien gezond 📈', body_nl = 'Bijna 18 maanden! Analyseer zijn groeitempo in de tool Gewichtstracker en controleer of zijn lengte en gewicht binnen de norm vallen.', title_pl = 'Rośniemy zdrowo 📈', body_pl = 'Już prawie 18 miesięcy! Przeanalizuj tempo rozwoju w narzędziu Licznik wagi i sprawdź, czy wzrost i waga mieszczą się w normie.', title_pt = 'A crescer com saúde 📈', body_pt = 'Faltam poucos dias para os 18 meses! Analise o ritmo de crescimento no Registo de Peso e confirme se a altura e o peso estão dentro do normal.', title_sv = 'Vi växer friskt 📈', body_sv = 'Snart 18 månader! Analysera tillväxttakten i verktyget Viktspåraren och kolla om längd och vikt följer normen.', title_vi = 'Lớn lên khỏe mạnh 📈', body_vi = 'Sắp tròn 18 tháng rồi! Hãy phân tích tốc độ phát triển trong công cụ Theo dõi cân nặng và kiểm tra chiều cao, cân nặng có đạt chuẩn không.', title_zh = '健康成长 📈', body_zh = '快到第18个月了！在体重记录工具里分析成长速度，看看身高和体重是否符合参考范围。' WHERE id = 'e8b020dc-c4fe-4f5b-946a-28ae84382a39' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El final de un día increíble 🖼️', body_es = 'Inmortaliza este día tan especial (¡540 días!) añadiendo al Álbum del bebé vuestra foto juntos más alegre y entrañable.', title_fr = 'La fin d''une journée formidable 🖼️', body_fr = 'Immortalisez ce jour spécial (540 jours !) en ajoutant à l''Album de bébé votre photo ensemble la plus joyeuse et la plus tendre.', title_hi = 'एक शानदार दिन का अंत 🖼️', body_hi = 'साथ में खिंचवाई अपनी सबसे खुशनुमा और प्यारी फ़ोटो बेबी एल्बम में जोड़कर इस खास दिन (540 दिन!) को हमेशा के लिए सहेज लीजिए।', title_id = 'Akhir hari yang luar biasa 🖼️', body_id = 'Abadikan hari istimewa ini (hari ke-540!) dengan menambahkan foto bersama paling ceria dan hangat ke Album Bayi.', title_ja = 'すてきな一日の締めくくり 🖼️', body_ja = '一緒に撮ったいちばん楽しくて温かい写真を「ベビーアルバム」に追加して、この特別な日（540日目！）を残しましょう。', title_ko = '멋진 하루의 끝 🖼️', body_ko = '함께 찍은 가장 즐겁고 따뜻한 사진을 아기 앨범에 추가해 이 특별한 날(540일!)을 영원히 남기세요.', title_nl = 'Het einde van een geweldige dag 🖼️', body_nl = 'Leg deze bijzondere dag (540 dagen!) voor altijd vast door jullie vrolijkste en warmste foto samen in het Babyalbum te zetten.', title_pl = 'Wspaniały koniec dnia 🖼️', body_pl = 'Uwiecznij ten wyjątkowy dzień (540 dni!), dodając do Albumu dziecka wasze najweselsze i najcieplejsze wspólne zdjęcie.', title_pt = 'O fim de um dia fantástico 🖼️', body_pt = 'Adicione ao Álbum do Bebé a foto mais alegre e calorosa que tiraram juntos e eternize este dia especial (540 dias!).', title_sv = 'Slutet på en fantastisk dag 🖼️', body_sv = 'Förevig den här speciella dagen (540 dagar!) genom att lägga till er gladaste och varmaste bild tillsammans i Babyalbumet.', title_vi = 'Kết thúc một ngày tuyệt vời 🖼️', body_vi = 'Hãy lưu giữ ngày đặc biệt này (540 ngày!) bằng cách thêm bức ảnh chung vui vẻ và ấm áp nhất vào Album của bé.', title_zh = '美好一天的尾声 🖼️', body_zh = '把你们一起拍的最开心、最温暖的照片加进宝宝相册，永远纪念这个特别的日子（第540天！）。' WHERE id = 'ab02b4ce-b2c3-41bc-a1aa-f97787c0ba17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Eres una heroína! ✨', body_es = '¡Día 540 de tu viaje como madre! Cuéntale a Anacan AI tu logro de hoy y deja que te dé una motivación especial para alegrarte el día.', title_fr = 'Vous êtes une héroïne ! ✨', body_fr = 'Le 540e jour de votre aventure de maman ! Racontez votre réussite du jour à Anacan AI et laissez-le vous offrir un mot de motivation pour embellir votre journée.', title_hi = 'आप हीरो हैं! ✨', body_hi = 'माँ बनने के सफ़र का 540वाँ दिन! Anacan AI को आज की अपनी कामयाबी लिखिए, ताकि वह आपको दिन सुंदर बनाने वाला खास मोटिवेशन दे।', title_id = 'Anda pahlawan! ✨', body_id = 'Hari ke-540 perjalanan Anda sebagai ibu! Tulis keberhasilan Anda hari ini ke Anacan AI, dan biarkan ia memberi motivasi khusus yang mempercantik hari Anda.', title_ja = 'あなたはヒーローです！✨', body_ja = '子育ての旅、540日目！今日のがんばりをAnacan AIに書き込めば、一日を明るくする特別なメッセージが届きます。', title_ko = '엄마는 영웅이에요! ✨', body_ko = '엄마가 된 지 540일째! 오늘의 성공을 Anacan AI에게 적어 보세요. 하루를 더 빛나게 해 줄 특별한 응원을 받을 수 있어요.', title_nl = 'Je bent een held! ✨', body_nl = 'Dag 540 van je reis als moeder! Schrijf Anacan AI je succes van vandaag en krijg een speciale dosis motivatie die je dag mooier maakt.', title_pl = 'Jesteś bohaterką! ✨', body_pl = '540. dzień twojej drogi w macierzyństwie! Napisz Anacan AI o swoim dzisiejszym sukcesie, a dostaniesz wyjątkową motywację, która upiększy ci dzień.', title_pt = 'É uma heroína! ✨', body_pt = 'O dia 540 da sua viagem como mãe! Escreva ao Anacan AI a sua conquista de hoje e receba uma motivação especial para tornar o seu dia mais bonito.', title_sv = 'Du är en hjälte! ✨', body_sv = 'Dag 540 på din mammaresa! Skriv dagens framgång till Anacan AI och få en särskild motivation som gör din dag finare.', title_vi = 'Mẹ là người hùng! ✨', body_vi = 'Ngày thứ 540 của hành trình làm mẹ! Hãy kể với Anacan AI thành công hôm nay của mẹ để nhận một lời động viên đặc biệt giúp ngày thêm tươi đẹp.', title_zh = '你是英雄！✨', body_zh = '妈妈之旅的第540天！把今天的成就告诉Anacan AI，让它送你一句特别的鼓励，点亮你的一天。' WHERE id = 'c1dc4453-41a2-40e6-812c-73fb934ccc70' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mesa en familia 🍲', body_es = 'Ya puede comer lo mismo que vosotros. Calcula fácilmente el valor nutricional de vuestras comidas compartidas con el Seguimiento de tomas.', title_fr = 'Le repas en famille 🍲', body_fr = 'Il peut déjà manger les mêmes plats que vous. Calculez facilement la valeur nutritionnelle de vos repas partagés avec le Suivi des repas.', title_hi = 'परिवार की खाने की मेज़ 🍲', body_hi = 'अब वह आपके जैसा ही खाना खा सकता है। फ़ीडिंग ट्रैकर से आपके साझा खाने का पोषण मूल्य आसानी से निकालिए।', title_id = 'Meja makan keluarga 🍲', body_id = 'Kini ia sudah bisa makan makanan yang sama dengan Anda. Hitung nilai gizi hidangan bersama Anda dengan mudah lewat alat Pemantau Makan.', title_ja = '家族の食卓 🍲', body_ja = 'もうあなたと同じ料理を食べられます。「栄養管理ツール」で、家族の共通メニューの栄養価をかんたんに計算しましょう。', title_ko = '가족 식탁 🍲', body_ko = '이제 엄마와 같은 음식을 먹을 수 있어요. 수유 기록 도구로 함께 먹는 음식의 영양가를 쉽게 계산해 보세요.', title_nl = 'Aan de gezinstafel 🍲', body_nl = 'Je kindje kan nu hetzelfde eten als jullie. Bereken met de Voedingstracker makkelijk de voedingswaarde van jullie gezamenlijke maaltijden.', title_pl = 'Rodzinny stół 🍲', body_pl = 'Może już jeść te same dania co wy. Łatwo oblicz wartość odżywczą wspólnych posiłków w narzędziu do śledzenia karmienia.', title_pt = 'A mesa da família 🍲', body_pt = 'Já pode comer os mesmos pratos que vocês. Calcule com facilidade o valor nutricional das refeições partilhadas com o Registo de Alimentação.', title_sv = 'Familjebordet 🍲', body_sv = 'Nu kan barnet äta samma mat som ni. Räkna enkelt ut näringsvärdet i er gemensamma mat med Matningskoll.', title_vi = 'Mâm cơm gia đình 🍲', body_vi = 'Bé đã có thể ăn cùng món với cả nhà. Hãy dễ dàng tính giá trị dinh dưỡng của các món ăn chung bằng công cụ Theo dõi cữ bú.', title_zh = '家庭餐桌 🍲', body_zh = '他已经可以和你们吃一样的饭菜了。用喂养记录工具轻松算出全家共享餐的营养价值吧。' WHERE id = 'fa1d5820-5e14-435d-81d1-df116bd7de6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué te preocupa? 🤔', body_es = '¿De repente rechaza la comida? Haz cualquier pregunta sobre maternidad a Anacan AI y recibe al momento una respuesta con precisión experta.', title_fr = 'Qu''est-ce qui vous préoccupe ? 🤔', body_fr = 'Il refuse soudain de manger ? Posez toutes vos questions de maman à Anacan AI et obtenez tout de suite une réponse précise d''expert.', title_hi = 'आपको क्या सोच में डाल रहा है? 🤔', body_hi = 'अचानक खाना मना कर रहा है? माँ बनने से जुड़ा कोई भी सवाल Anacan AI से पूछिए और तुरंत विशेषज्ञ जैसी सटीकता से जवाब पाइए।', title_id = 'Apa yang Anda pikirkan? 🤔', body_id = 'Tiba-tiba ia menolak makan? Ajukan pertanyaan apa pun soal pengasuhan ke Anacan AI dan dapatkan jawaban instan seakurat ahli.', title_ja = '気になっていることは？🤔', body_ja = '急に食べなくなった？どんな子育ての質問でもAnacan AIに送れば、専門家のような正確さですぐに答えが届きます。', title_ko = '무엇이 고민인가요? 🤔', body_ko = '갑자기 밥을 거부하나요? 육아에 관한 어떤 질문이든 Anacan AI에게 물어 바로 전문가 수준의 정확한 답을 받아 보세요.', title_nl = 'Waar denk je aan? 🤔', body_nl = 'Weigert je kindje ineens te eten? Stel al je vragen over het moederschap aan Anacan AI en krijg meteen een antwoord met de precisie van een deskundige.', title_pl = 'Co cię nurtuje? 🤔', body_pl = 'Nagle odmawia jedzenia? Każde pytanie o macierzyństwo kieruj do Anacan AI i od razu otrzymaj odpowiedź z ekspercką precyzją.', title_pt = 'O que a preocupa? 🤔', body_pt = 'Recusa de repente a comida? Faça qualquer pergunta sobre maternidade ao Anacan AI e receba na hora uma resposta com precisão de especialista.', title_sv = 'Vad funderar du på? 🤔', body_sv = 'Vägrar barnet plötsligt äta? Ställ vilken mammafråga som helst till Anacan AI och få direkt ett svar med expertprecision.', title_vi = 'Điều gì khiến mẹ băn khoăn? 🤔', body_vi = 'Bé bỗng dưng không chịu ăn? Hãy hỏi Anacan AI bất kỳ câu hỏi nào về việc nuôi con và nhận ngay câu trả lời chính xác như chuyên gia.', title_zh = '什么让你挂心？🤔', body_zh = '突然不肯吃饭？把任何育儿问题发给Anacan AI，马上获得专家般准确的回答。' WHERE id = '4f770f32-235d-4481-acc9-8a3353f11910' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dormirse sin esfuerzo 🎶', body_es = '¿No consigue dormirse después de un día lleno de descubrimientos? Elige una nana en Ruido blanco y crea una calma mágica en la habitación.', title_fr = 'S''endormir facilement 🎶', body_fr = 'Il n''arrive pas à dormir après une journée pleine de découvertes ? Choisissez une berceuse dans les Bruits blancs et créez un calme magique dans la chambre.', title_hi = 'नींद में आसानी से जाना 🎶', body_hi = 'खोजबीन भरे दिन के बाद सो नहीं पा रहा? व्हाइट नॉइज़ में लोरी की आवाज़ चुनिए और कमरे में जादुई शांति बनाइए।', title_id = 'Peralihan mudah ke tidur 🎶', body_id = 'Ia tidak bisa tidur setelah hari penuh penjelajahan? Pilih nina bobo dari Suara Putih dan ciptakan keheningan ajaib di kamar.', title_ja = '眠りへの切りかえを楽に 🎶', body_ja = '活発な発見でいっぱいの一日のあと、なかなか眠れない？「ホワイトノイズ」から子守唄を選んで、部屋に魔法のような静けさをつくりましょう。', title_ko = '편안하게 잠으로 🎶', body_ko = '활발한 탐험으로 가득한 하루 뒤에 잠들지 못하나요? 백색소음에서 자장가를 골라 방에 마법 같은 고요함을 만들어 주세요.', title_nl = 'Makkelijk in slaap vallen 🎶', body_nl = 'Kan je kindje niet slapen na een dag vol ontdekkingen? Kies een slaapliedje in Witte ruis en zorg voor een magische stilte in de kamer.', title_pl = 'Łatwe zasypianie 🎶', body_pl = 'Nie może zasnąć po dniu pełnym aktywnych odkryć? Wybierz w Białym szumie kołysankę i stwórz w pokoju magiczną ciszę.', title_pt = 'Uma passagem fácil para o sono 🎶', body_pt = 'Não consegue dormir depois de um dia cheio de descobertas? Escolha uma canção de embalar no Ruído Branco e crie no quarto uma calma mágica.', title_sv = 'Lätt övergång till sömn 🎶', body_sv = 'Kan barnet inte sova efter en dag full av aktiva upptäckter? Välj vaggvisan i Vitt brus och skapa en magisk stillhet i rummet.', title_vi = 'Vào giấc dễ dàng 🎶', body_vi = 'Bé không ngủ được sau một ngày đầy khám phá sôi nổi? Hãy chọn bài hát ru trong Tiếng ồn trắng để tạo một không gian tĩnh lặng kỳ diệu trong phòng.', title_zh = '轻松入睡 🎶', body_zh = '探索了一整天，兴奋得睡不着？在白噪音里选摇篮曲，在房间里营造一种魔法般的宁静。' WHERE id = '996b9423-cc50-4ec2-bbf6-02866083bb10' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubrimientos en la naturaleza 🍂', body_es = 'El aire fresco os sentará bien a los dos. Encuentra un parque diferente en Lugares para mamás y deja que corra libre y gaste energía.', title_fr = 'Découvertes dans la nature 🍂', body_fr = 'L''air frais vous fera du bien à tous les deux. Trouvez un nouveau parc dans les Lieux adaptés aux mamans et laissez-le courir librement pour se défouler.', title_hi = 'प्रकृति की खोज 🍂', body_hi = 'ताज़ी हवा आप दोनों के लिए अच्छी रहेगी। माँ के लिए अनुकूल जगहों में कोई अलग पार्क ढूँढिए और उसे खुलकर दौड़कर ऊर्जा निकालने दीजिए।', title_id = 'Menjelajahi alam 🍂', body_id = 'Udara segar baik untuk kalian berdua. Temukan taman yang berbeda di Tempat Ramah Ibu, dan biarkan ia bebas berlari menyalurkan energinya.', title_ja = '自然の中で発見 🍂', body_ja = '新鮮な空気はおふたりにとって心地よいもの。「ママにやさしいスポット」でいつもとちがう公園を見つけて、思いきり走ってエネルギーを発散させてあげましょう。', title_ko = '자연 속 발견 🍂', body_ko = '신선한 공기는 두 사람 모두에게 좋아요. 엄마 친화 장소에서 색다른 공원을 찾아 아이가 마음껏 뛰며 에너지를 발산하게 해 주세요.', title_nl = 'Ontdekkingen in de natuur 🍂', body_nl = 'Frisse lucht doet jullie allebei goed. Zoek in Mamavriendelijke plekken een ander park en laat je kindje vrij rondrennen om zijn energie kwijt te raken.', title_pl = 'Odkrywanie natury 🍂', body_pl = 'Świeże powietrze dobrze zrobi wam obojgu. Znajdź w Miejscach przyjaznych mamom inny park, niech swobodnie biega i wyładuje energię.', title_pt = 'Descobertas na natureza 🍂', body_pt = 'O ar puro vai fazer bem aos dois. Encontre nos Locais Amigos das Mães um parque diferente e deixe-o correr à vontade e gastar energia.', title_sv = 'Upptäckter i naturen 🍂', body_sv = 'Frisk luft gör er båda gott. Hitta en ny park i Mammavänliga platser och låt barnet springa fritt och få ut sin energi.', title_vi = 'Khám phá thiên nhiên 🍂', body_vi = 'Không khí trong lành sẽ tốt cho cả hai mẹ con. Hãy tìm một công viên mới trong Địa điểm thân thiện với mẹ để bé tự do chạy nhảy, xả hết năng lượng.', title_zh = '大自然探索 🍂', body_zh = '新鲜空气对你们俩都有好处。在妈妈友好场所里找一个不一样的公园，让他自由奔跑、释放精力吧。' WHERE id = '9d8ea18e-9c4f-4f0b-9883-a708f0ed884b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu voz interior 💖', body_es = 'No tienes que ser una madre perfecta: para él eres la mejor. Escribe en el Diario de ánimo cómo te has sentido hoy y respira.', title_fr = 'Votre voix intérieure 💖', body_fr = 'Vous n''avez pas à être une maman parfaite, pour lui, vous êtes la meilleure. Écrivez vos ressentis du jour dans le Journal d''humeur et détendez-vous.', title_hi = 'आपके मन की आवाज़ 💖', body_hi = 'आपको परफ़ेक्ट माँ होने की ज़रूरत नहीं, उसके लिए आप सबसे अच्छी हैं। मूड डायरी में आज की भावनाएँ लिखिए और सुकून पाइए।', title_id = 'Suara hati Anda 💖', body_id = 'Anda tidak harus menjadi ibu yang sempurna, bagi si kecil Anda yang terbaik. Tulis perasaan Anda hari ini di Buku Harian Suasana Hati dan tenangkan diri.', title_ja = 'あなたの心の声 💖', body_ja = '完璧なママでなくていいのです。お子さんにとって、あなたが最高です。「気分日記」に今日の気持ちを書いて、ほっとしましょう。', title_ko = '내 마음의 소리 💖', body_ko = '완벽한 엄마일 필요는 없어요. 아이에게는 당신이 최고예요. 기분 일기에 오늘의 감정을 적고 마음을 편히 하세요.', title_nl = 'Je innerlijke stem 💖', body_nl = 'Je hoeft geen perfecte moeder te zijn, voor je kindje ben jij de beste. Schrijf je gevoelens van vandaag op in je Stemmingsdagboek en kom tot rust.', title_pl = 'Twój wewnętrzny głos 💖', body_pl = 'Nie musisz być idealną mamą, dla niego jesteś najlepsza. Zapisz dzisiejsze uczucia w Dzienniku nastroju i odetchnij.', title_pt = 'A sua voz interior 💖', body_pt = 'Não tem de ser uma mãe perfeita: para ele, é a melhor. Escreva no Diário de Humor o que sentiu hoje e descontraia.', title_sv = 'Din inre röst 💖', body_sv = 'Du behöver inte vara en perfekt mamma, du är den bästa för ditt barn. Skriv dagens känslor i Humördagboken och slappna av.', title_vi = 'Tiếng nói bên trong 💖', body_vi = 'Mẹ không cần phải là người mẹ hoàn hảo, với bé, mẹ là tuyệt nhất. Hãy viết cảm xúc hôm nay vào Nhật ký tâm trạng để nhẹ lòng hơn.', title_zh = '你内心的声音 💖', body_zh = '你不必做一个完美的妈妈，对他来说你就是最好的。把今天的感受写进心情日记，放松一下吧。' WHERE id = '19f1aa58-50a6-4acf-b375-1d03850cfcb6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de comer solo ⏱️', body_es = '¿Intenta comer solo? ¡Hazte la vista gorda con el desorden! Activa el temporizador de tomas y analiza cuánto tiempo le lleva esta independencia.', title_fr = 'L''épreuve du repas en solo ⏱️', body_fr = 'Il essaie de manger seul ? Fermez les yeux sur le désordre ! Lancez le minuteur des repas et analysez le temps que prend cette autonomie.', title_hi = 'खुद खाने का अभ्यास ⏱️', body_hi = 'खुद खाने की कोशिश कर रहा है? बिखराव को नज़रअंदाज़ कीजिए! फ़ीडिंग टाइमर चालू कीजिए और देखिए कि इस आत्मनिर्भरता में कितना समय लगता है।', title_id = 'Uji makan sendiri ⏱️', body_id = 'Ia mencoba makan sendiri? Biarkan saja berantakan! Nyalakan Timer Makan dan analisis berapa lama waktu yang dibutuhkan untuk kemandirian ini.', title_ja = '自分で食べるチャレンジ ⏱️', body_ja = '自分で食べようとしていますか？散らかるのは気にしないで！食事タイマーをオンにして、自分で食べるのにどれくらい時間がかかるか分析しましょう。', title_ko = '혼자 먹기 시험 ⏱️', body_ko = '혼자 먹으려고 하나요? 어질러지는 건 눈감아 주세요! 수유 타이머를 켜고 혼자 먹는 데 시간이 얼마나 걸리는지 분석해 보세요.', title_nl = 'Zelf eten met de timer ⏱️', body_nl = 'Probeert je kindje zelf te eten? Kijk niet naar de rommel! Zet de voedingstimer aan en analyseer hoe lang deze zelfstandigheid duurt.', title_pl = 'Próba samodzielnego jedzenia ⏱️', body_pl = 'Próbuje jeść sam? Przymknij oko na bałagan! Włącz timer karmienia i sprawdź, ile czasu zajmuje mu ta samodzielność.', title_pt = 'O desafio de comer sozinho ⏱️', body_pt = 'Tenta comer sozinho? Feche os olhos à desarrumação! Ligue o temporizador de alimentação e analise quanto tempo demora esta independência.', title_sv = 'Test av att äta själv ⏱️', body_sv = 'Försöker barnet äta själv? Blunda för stöket! Starta matningstimern och analysera hur lång tid självständigheten tar.', title_vi = 'Thử thách tự ăn ⏱️', body_vi = 'Bé đang cố tự ăn? Hãy bỏ qua chuyện bừa bộn! Bật bộ hẹn giờ trong Theo dõi cữ bú và phân tích xem việc tự ăn mất bao nhiêu thời gian.', title_zh = '自己吃饭大考验 ⏱️', body_zh = '他在尝试自己吃？对乱糟糟睁一只眼闭一只眼吧！打开喂养计时器，看看这份独立要花多少时间。' WHERE id = '6cc2d53f-bf34-4dcd-9edd-bf3d05a35b98' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dulces sanos 🍪', body_es = 'No hacen falta los dulces del súper. Prepara galletas fáciles, sin azúcar y deliciosas de Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Des douceurs saines 🍪', body_fr = 'Pas besoin de sucreries du commerce. Préparez des biscuits faciles, sans sucre et savoureux grâce aux Recettes pour bébés qui commencent la diversification.', title_hi = 'सेहतमंद मिठाई 🍪', body_hi = 'बाज़ार की मिठाइयों की ज़रूरत नहीं। ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी से आसान, बिना चीनी के स्वादिष्ट बिस्किट बनाइए।', title_id = 'Camilan manis yang sehat 🍪', body_id = 'Tak perlu camilan manis dari toko. Buat kue kering yang mudah, tanpa gula, dan lezat dari Resep untuk bayi yang mulai MPASI.', title_ja = 'ヘルシーなおやつ 🍪', body_ja = 'お店のお菓子は必要ありません。「離乳食を始める赤ちゃんのレシピ」から、かんたんで砂糖不使用のおいしいクッキーをつくりましょう。', title_ko = '건강한 간식 🍪', body_ko = '마트 과자는 필요 없어요. 이유식을 시작하는 아기를 위한 레시피에서 쉽고 설탕 없는 맛있는 쿠키를 만들어 보세요.', title_nl = 'Gezonde lekkernijen 🍪', body_nl = 'Snoep uit de winkel is niet nodig. Maak uit Recepten voor baby''s die met bijvoeding beginnen makkelijke, lekkere koekjes zonder suiker.', title_pl = 'Zdrowe słodkości 🍪', body_pl = 'Nie potrzebujesz słodyczy ze sklepu. Przygotuj z Przepisów dla niemowląt rozpoczynających rozszerzanie diety proste, smaczne ciasteczka bez cukru.', title_pt = 'Doces saudáveis 🍪', body_pt = 'Não precisa de doces do supermercado. Prepare com as Receitas para bebés em diversificação alimentar bolachas fáceis, sem açúcar e saborosas.', title_sv = 'Nyttigt godis 🍪', body_sv = 'Du behöver inget godis från affären. Gör enkla, sockerfria och goda kakor från Recept för bebisar som börjar med fast föda.', title_vi = 'Đồ ngọt lành mạnh 🍪', body_vi = 'Không cần đến bánh kẹo ngoài cửa hàng. Hãy làm những chiếc bánh quy đơn giản, không đường và thơm ngon từ mục Công thức cho bé bắt đầu ăn dặm.', title_zh = '健康甜点 🍪', body_zh = '不需要买超市的甜食。从食谱板块的辅食宝宝食谱里，做些简单、无糖又好吃的饼干吧。' WHERE id = 'f869363f-52a1-4240-a759-b2b999d347e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Paso al sueño profundo 🌙', body_es = 'Activa el Temporizador de sueño. Si se despierta más por la noche, relaja su sistema nervioso con el sonido de las olas en Ruido blanco.', title_fr = 'Plonger dans un sommeil profond 🌙', body_fr = 'Activez le minuteur de sommeil. Si les réveils nocturnes augmentent, apaisez son système nerveux avec les vagues de l''océan des Bruits blancs.', title_hi = 'गहरी नींद की ओर 🌙', body_hi = 'स्लीप टाइमर चालू कीजिए। अगर रात में जागना बढ़ गया है, तो व्हाइट नॉइज़ की समुद्र की लहरों से उसके नर्वस सिस्टम को सुकून दीजिए।', title_id = 'Beralih ke tidur nyenyak 🌙', body_id = 'Aktifkan Timer Tidur. Kalau ia makin sering terbangun malam, tenangkan sistem sarafnya dengan suara ombak laut dari Suara Putih.', title_ja = '深い眠りへの切りかえ 🌙', body_ja = '睡眠タイマーをオンにしましょう。夜中に起きることが増えたら、「ホワイトノイズ」の波の音で神経を落ち着かせてあげましょう。', title_ko = '깊은 잠으로 🌙', body_ko = '수면 타이머를 켜세요. 밤에 깨는 일이 늘었다면 백색소음의 파도 소리로 신경계를 편안하게 해 주세요.', title_nl = 'Overgang naar diepe slaap 🌙', body_nl = 'Zet de Slaaptimer aan. Wordt je kindje ''s nachts vaker wakker? Kalmeer zijn zenuwstelsel met de oceaangolven in Witte ruis.', title_pl = 'Przejście w głęboki sen 🌙', body_pl = 'Włącz timer snu. Jeśli nocnych pobudek przybywa, ukój jego układ nerwowy falami oceanu z Białego szumu.', title_pt = 'A passagem para o sono profundo 🌙', body_pt = 'Ative o temporizador de sono. Se os despertares noturnos aumentarem, acalme o sistema nervoso dele com o som das ondas do mar no Ruído Branco.', title_sv = 'Övergång till djup sömn 🌙', body_sv = 'Aktivera sömntimern. Om de nattliga uppvaknandena ökar, lugna nervsystemet med havsvågor i Vitt brus.', title_vi = 'Chìm vào giấc ngủ sâu 🌙', body_vi = 'Hãy bật Bộ hẹn giờ ngủ. Nếu bé thức giấc ban đêm nhiều hơn, hãy làm dịu hệ thần kinh của bé bằng tiếng sóng biển trong Tiếng ồn trắng.', title_zh = '进入深睡 🌙', body_zh = '打开睡眠计时器。如果夜醒变多，就用白噪音里的海浪声放松他的神经系统。' WHERE id = 'ae531928-8e01-4e71-961a-63a517eaee5a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa matutina 💩', body_es = '¡Anota el primer cambio de pañal del día! Es la mejor forma de seguir el sistema digestivo y la ingesta de líquidos de tu peque, que no para de crecer.', title_fr = 'La surprise du matin 💩', body_fr = 'Notez le premier change de la journée ! C''est le meilleur moyen de suivre la digestion et l''hydratation de votre enfant qui grandit.', title_hi = 'सुबह का सरप्राइज़ 💩', body_hi = 'दिन का पहला डायपर बदलते समय दर्ज कीजिए! बढ़ते बच्चे के पाचन और तरल लेने पर नज़र रखने का यह सबसे अच्छा तरीका है।', title_id = 'Kejutan pagi 💩', body_id = 'Catat saat mengganti popok pertama hari ini! Ini cara terbaik memantau sistem pencernaan dan asupan cairan si kecil yang sedang tumbuh.', title_ja = '朝のサプライズ 💩', body_ja = '今日最初のおむつ替えを記録しましょう！成長中のお子さんの消化と水分摂取を見守るいちばんの方法です。', title_ko = '아침의 깜짝 선물 💩', body_ko = '오늘 첫 기저귀를 갈 때 기록하세요! 자라는 아기의 소화 상태와 수분 섭취를 살피는 가장 좋은 방법이에요.', title_nl = 'Een verrassing in de ochtend 💩', body_nl = 'Noteer de eerste verschoning van de dag! Zo houd je het best de spijsvertering en de vochtinname van je groeiende kindje bij.', title_pl = 'Poranna niespodzianka 💩', body_pl = 'Zapisz pierwszą zmianę pieluszki dnia! To najlepszy sposób, by śledzić układ pokarmowy i nawodnienie rosnącego malucha.', title_pt = 'A surpresa da manhã 💩', body_pt = 'Registe a primeira muda de fralda do dia! É a melhor forma de acompanhar o sistema digestivo e a ingestão de líquidos de um bebé em crescimento.', title_sv = 'Morgonens överraskning 💩', body_sv = 'Anteckna dagens första blöjbyte! Det är det bästa sättet att följa matsmältningen och vätskeintaget hos ett växande barn.', title_vi = 'Bất ngờ buổi sáng 💩', body_vi = 'Hãy ghi lại khi thay chiếc tã đầu tiên trong ngày! Đây là cách tốt nhất để theo dõi hệ tiêu hóa và lượng nước của em bé đang lớn.', title_zh = '早晨的惊喜 💩', body_zh = '换今天第一片尿布时记录一下！这是关注成长中宝宝消化系统和水分摄入的最好方法。' WHERE id = 'bacdcc71-8211-4dd5-b3af-c5af34fb468a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No suelta la cuchara? 🥄', body_es = 'Activa el temporizador de tomas. Analiza cuánto tardan sus intentos de comer solo y revisa las cantidades diarias recomendadas.', title_fr = 'Il ne lâche plus sa cuillère ? 🥄', body_fr = 'Lancez le minuteur des repas. Analysez le temps que prennent ses essais pour manger seul et vérifiez ses besoins alimentaires du jour.', title_hi = 'चम्मच हाथ से छूटता ही नहीं? 🥄', body_hi = 'फ़ीडिंग टाइमर चालू कीजिए। खुद खाने की कोशिशों में कितना समय लगता है, इसका विश्लेषण कीजिए और रोज़ के पोषण का मानक देखिए।', title_id = 'Sendok tak lepas dari tangannya? 🥄', body_id = 'Nyalakan Timer Makan. Analisis berapa lama usahanya makan sendiri dan lihat kebutuhan makan hariannya.', title_ja = 'スプーンを手放さない？🥄', body_ja = '食事タイマーをオンにしましょう。自分で食べるのにどれくらいかかるか分析して、1日の食事の目安を確認しましょう。', title_ko = '숟가락을 손에서 놓지 않나요? 🥄', body_ko = '수유 타이머를 켜세요. 혼자 먹으려는 시도에 시간이 얼마나 걸리는지 분석하고 하루 섭취량도 확인해 보세요.', title_nl = 'Laat de lepel niet meer los? 🥄', body_nl = 'Zet de voedingstimer aan. Analyseer hoe lang zijn pogingen om zelf te eten duren en bekijk de dagelijkse voedingsnorm.', title_pl = 'Nie wypuszcza łyżeczki z ręki? 🥄', body_pl = 'Włącz timer karmienia. Sprawdź, ile trwają próby samodzielnego jedzenia, i zajrzyj do dziennej normy karmienia.', title_pt = 'Não larga a colher? 🥄', body_pt = 'Ligue o temporizador de alimentação. Analise quanto tempo demoram as tentativas de comer sozinho e veja a quantidade diária recomendada.', title_sv = 'Släpper inte skeden? 🥄', body_sv = 'Starta matningstimern. Analysera hur lång tid försöken att äta själv tar och titta på den dagliga matnormen.', title_vi = 'Bé không rời chiếc thìa? 🥄', body_vi = 'Hãy bật bộ hẹn giờ trong Theo dõi cữ bú. Phân tích xem những lần tự ăn mất bao lâu và xem định mức ăn hằng ngày.', title_zh = '勺子不离手？🥄', body_zh = '打开喂养计时器。分析他自己吃饭花了多长时间，再看看每日喂养参考量。' WHERE id = 'e207d666-c361-4203-8076-7ba835d4f015' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahógate 📝', body_es = 'No todos los días son perfectos, y es normal. Escribe en el Diario de ánimo cómo te has sentido hoy, libérate del estrés y descansa tranquila.', title_fr = 'Videz votre sac 📝', body_fr = 'Tous les jours ne sont pas parfaits, et c''est normal. Écrivez vos ressentis du jour dans le Journal d''humeur, libérez-vous du stress et reposez-vous au calme.', title_hi = 'मन हल्का कीजिए 📝', body_hi = 'हर दिन परफ़ेक्ट नहीं होता और यह सामान्य है। मूड डायरी में आज की अपनी भावनाएँ लिखिए, तनाव से मुक्त होकर शांति से आराम कीजिए।', title_id = 'Curahkan isi hati 📝', body_id = 'Tidak setiap hari sempurna, dan itu normal. Tulis perasaan Anda hari ini di Buku Harian Suasana Hati, lepaskan stres, dan beristirahatlah dengan tenang.', title_ja = '心の中を吐き出そう 📝', body_ja = '毎日が完璧なわけではなく、それは自然なことです。「気分日記」に今日の気持ちを書いて、ストレスから解放され、ゆっくり休みましょう。', title_ko = '마음을 비워 내세요 📝', body_ko = '매일이 완벽할 수는 없고, 그건 자연스러운 일이에요. 기분 일기에 오늘의 감정을 적고 스트레스에서 벗어나 조용히 쉬세요.', title_nl = 'Lucht je hart 📝', body_nl = 'Niet elke dag is perfect en dat is normaal. Schrijf je gevoelens van vandaag op in je Stemmingsdagboek, laat de stress los en rust rustig uit.', title_pl = 'Wyrzuć to z siebie 📝', body_pl = 'Nie każdy dzień jest idealny i to normalne. Zapisz dzisiejsze uczucia w Dzienniku nastroju, uwolnij się od stresu i spokojnie odpocznij.', title_pt = 'Desabafe 📝', body_pt = 'Nem todos os dias são perfeitos, e isso é normal. Escreva no Diário de Humor o que sentiu hoje, liberte-se do stress e descanse com calma.', title_sv = 'Töm ditt inre 📝', body_sv = 'Alla dagar blir inte perfekta, och det är normalt. Skriv dagens känslor i Humördagboken, bli fri från stressen och vila i lugn och ro.', title_vi = 'Hãy trút hết lòng mình 📝', body_vi = 'Không phải ngày nào cũng hoàn hảo và điều đó là bình thường. Hãy viết cảm xúc hôm nay vào Nhật ký tâm trạng, giải tỏa căng thẳng và nghỉ ngơi thật yên bình.', title_zh = '把心事倒出来 📝', body_zh = '不是每天都完美，这很正常。把今天的感受写进心情日记，摆脱压力，安静地休息吧。' WHERE id = '35587de2-b62b-435c-aca4-01e72314423a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Date un premio ☕', body_es = '¡Ser madre de un peque de 18 meses no es nada fácil! Encuentra una cafetería acogedora en el mapa de Lugares para mamás y pídete un café calentito.', title_fr = 'Faites-vous plaisir ☕', body_fr = 'Être maman d''un enfant de 18 mois n''est pas de tout repos ! Trouvez un café confortable sur notre carte des Lieux adaptés aux mamans et offrez-vous un café chaud.', title_hi = 'खुद को इनाम दीजिए ☕', body_hi = '18 महीने की माँ होना बिल्कुल आसान नहीं! हमारे माँ के लिए अनुकूल जगहों के नक्शे से कोई आरामदायक कैफ़े ढूँढिए और अपने लिए गरम कॉफ़ी मँगाइए।', title_id = 'Hadiahi diri Anda ☕', body_id = 'Menjadi ibu anak 18 bulan itu tidak mudah! Temukan kafe yang nyaman di peta Tempat Ramah Ibu dan pesanlah kopi hangat untuk diri sendiri.', title_ja = '自分にごほうびを ☕', body_ja = '1歳6か月の子育ては決して楽ではありません！「ママにやさしいスポット」マップで居心地のいいカフェを見つけて、温かいコーヒーを注文しましょう。', title_ko = '스스로에게 상을 주세요 ☕', body_ko = '18개월 동안의 육아는 결코 쉽지 않았어요! 엄마 친화 장소 지도에서 편한 카페를 찾아 따뜻한 커피 한 잔을 나에게 선물하세요.', title_nl = 'Beloon jezelf ☕', body_nl = '18 maanden moederschap is helemaal niet makkelijk! Zoek een gezellig café op onze kaart Mamavriendelijke plekken en bestel een warme koffie voor jezelf.', title_pl = 'Nagródź się ☕', body_pl = '18 miesięcy macierzyństwa to wcale nie jest łatwe! Znajdź na naszej mapie Miejsc przyjaznych mamom wygodną kawiarnię i zamów sobie gorącą kawę.', title_pt = 'Recompense-se ☕', body_pt = 'Ser mãe de uma criança de 18 meses não é nada fácil! Encontre no mapa dos Locais Amigos das Mães um café acolhedor e peça um café quente para si.', title_sv = 'Belöna dig själv ☕', body_sv = 'Att vara mamma i 18 månader är inte lätt! Hitta ett mysigt kafé på vår karta Mammavänliga platser och beställ ett varmt kaffe åt dig själv.', title_vi = 'Hãy tự thưởng cho mình ☕', body_vi = 'Làm mẹ của bé 18 tháng không hề dễ dàng! Hãy tìm một quán cà phê ấm cúng trên bản đồ Địa điểm thân thiện với mẹ và gọi cho mình một tách cà phê nóng.', title_zh = '奖励一下自己 ☕', body_zh = '当18个月宝宝的妈妈可一点都不容易！在我们的妈妈友好场所地图上找一家舒适的咖啡馆，给自己点一杯热咖啡吧。' WHERE id = 'da88924f-9b7a-4cc5-9b9e-429e9d903edd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Listos para correr? 👟', body_es = '¡Para sus primeras carreras con seguridad, el calzado adecuado es fundamental! Descubre en Productos recomendados los modelos ortopédicos favoritos de otras mamás.', title_fr = 'Prête pour les courses ? 👟', body_fr = 'De bonnes chaussures sont indispensables pour ses premières courses assurées ! Découvrez dans les Produits recommandés les modèles orthopédiques préférés des mamans.', title_hi = 'दौड़ के लिए तैयार हैं? 👟', body_hi = 'पहली भरोसेमंद दौड़ के लिए सही जूते ज़रूरी हैं! सुझाए गए प्रोडक्ट में माँओं के सबसे पसंदीदा ऑर्थोपेडिक मॉडल देखिए।', title_id = 'Siap berlari? 👟', body_id = 'Sepatu yang tepat itu wajib untuk lari pertamanya yang mantap! Temukan model ortopedi favorit para ibu di Produk Rekomendasi.', title_ja = 'かけっこの準備はいい？👟', body_ja = '自信をもって走り始めるには、ぴったりの靴が欠かせません！「おすすめ商品」で、ママたちにいちばん人気の足にやさしいモデルを見つけましょう。', title_ko = '달릴 준비 됐나요? 👟', body_ko = '자신 있게 뛰기 시작할 때는 알맞은 신발이 꼭 필요해요! 추천 제품에서 엄마들이 가장 좋아하는 발 건강 신발을 찾아보세요.', title_nl = 'Klaar om te rennen? 👟', body_nl = 'Voor de eerste zekere sprintjes zijn goede schoenen onmisbaar! Ontdek in Aanbevolen producten de orthopedische modellen die moeders het mooist vinden.', title_pl = 'Gotowi do biegania? 👟', body_pl = 'Do pierwszych pewnych biegów potrzebne są odpowiednie buty! Odkryj w Polecanych produktach modele ortopedyczne najbardziej lubiane przez mamy.', title_pt = 'Pronta para as corridas? 👟', body_pt = 'Para as primeiras corridas confiantes, o sapato certo é essencial! Descubra nos Produtos Recomendados os modelos ortopédicos preferidos das mães.', title_sv = 'Redo för springet? 👟', body_sv = 'Rätt skor är en förutsättning för de första säkra springturerna! Upptäck de ortopediska modeller som mammor gillar mest i Rekommenderade produkter.', title_vi = 'Sẵn sàng chạy nhảy chưa? 👟', body_vi = 'Đôi giày phù hợp là điều kiện cần cho những bước chạy tự tin đầu tiên! Hãy khám phá những mẫu giày chỉnh hình được các mẹ yêu thích nhất trong Sản phẩm gợi ý.', title_zh = '准备好奔跑了吗？👟', body_zh = '第一次自信地奔跑，一双合适的鞋必不可少！在推荐商品里发现妈妈们最喜欢的矫形款式吧。' WHERE id = '6b77a02d-8882-4aed-be91-5f8ce3841671' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Fotos tiernas 📸', body_es = '¿Se cae corriendo y se echa a reír? Añade enseguida este momento al Álbum del bebé y conviértelo en un recuerdo lleno de color para siempre.', title_fr = 'De jolies photos 📸', body_fr = 'Il tombe en courant et éclate de rire ? Ajoutez tout de suite ce moment adorable à l''Album de bébé pour en faire un souvenir coloré pour la vie.', title_hi = 'प्यारी तस्वीरें 📸', body_hi = 'दौड़ते हुए गिरकर हँस पड़ा? इस प्यारे पल को तुरंत बेबी एल्बम में जोड़कर भविष्य के लिए रंगीन और उम्रभर की याद बना लीजिए।', title_id = 'Foto-foto manis 📸', body_id = 'Ia jatuh saat berlari lalu tertawa? Segera tambahkan momen manis ini ke Album Bayi dan jadikan kenangan penuh warna seumur hidup.', title_ja = 'かわいい一枚 📸', body_ja = '走って転んで、笑っている？このかわいい瞬間をすぐに「ベビーアルバム」に追加して、カラフルな一生の思い出にしましょう。', title_ko = '귀여운 한 컷 📸', body_ko = '뛰다가 넘어지고는 깔깔 웃나요? 이 귀여운 모습을 바로 아기 앨범에 추가해 훗날 다채로운 평생의 추억으로 만드세요.', title_nl = 'Lieve foto''s 📸', body_nl = 'Valt je kindje tijdens het rennen en moet hij erom lachen? Zet dit lieve moment meteen in het Babyalbum en maak er een kleurrijke herinnering voor altijd van.', title_pl = 'Słodkie ujęcia 📸', body_pl = 'Przewraca się w biegu i się śmieje? Od razu dodaj tę słodką chwilę do Albumu dziecka i zamień ją w kolorowe wspomnienie na całe życie.', title_pt = 'Fotos doces 📸', body_pt = 'Caiu a correr e desatou a rir? Adicione já este momento ao Álbum do Bebé e transforme-o numa recordação colorida para toda a vida.', title_sv = 'Söta bilder 📸', body_sv = 'Ramlade barnet när det sprang och började skratta? Lägg direkt till det söta ögonblicket i Babyalbumet och gör det till ett färgglatt minne för livet.', title_vi = 'Những khung hình đáng yêu 📸', body_vi = 'Bé chạy, ngã rồi phá lên cười? Hãy thêm ngay khoảnh khắc đáng yêu này vào Album của bé để biến nó thành kỷ niệm đầy màu sắc trọn đời.', title_zh = '可爱的画面 📸', body_zh = '跑着跑着摔倒了还在笑？马上把这份可爱加进宝宝相册，变成一段多彩又永恒的回忆吧。' WHERE id = 'd6d681fb-3d1d-40b8-84c0-e3cd64921f6e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal el hierro? 🥩', body_es = 'Comprueba con el Seguimiento de tomas si hoy ha tomado suficiente hierro. Si le falta, echa un vistazo a Recetas para bebé.', title_fr = 'Et les réserves de fer ? 🥩', body_fr = 'Vérifiez avec le Suivi des repas s''il a eu assez de fer aujourd''hui. S''il en manque, consultez les Recettes pour bébés.', title_hi = 'आयरन कितना मिल रहा है? 🥩', body_hi = 'फ़ीडिंग ट्रैकर से जाँचिए कि आज उसे पर्याप्त आयरन मिला या नहीं। कमी हो तो बच्चों की रेसिपी देखिए।', title_id = 'Bagaimana cadangan zat besinya? 🥩', body_id = 'Periksa apakah hari ini ia cukup mendapat zat besi dengan alat Pemantau Makan. Kalau kurang, lihat Resep Bayi.', title_ja = '鉄分は足りている？🥩', body_ja = '「栄養管理ツール」で、今日鉄分を十分にとれたか確認しましょう。足りなければ、ベビーレシピをのぞいてみて。', title_ko = '철분은 충분한가요? 🥩', body_ko = '수유 기록 도구로 오늘 철분을 충분히 섭취했는지 확인하세요. 부족하다면 아기 레시피를 살펴보세요.', title_nl = 'Hoe zit het met het ijzer? 🥩', body_nl = 'Controleer met de Voedingstracker of je kindje vandaag genoeg ijzer heeft gekregen. Is er een tekort, kijk dan in de babyrecepten.', title_pl = 'Jak tam zapas żelaza? 🥩', body_pl = 'Sprawdź w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco żelaza. Jeśli są braki, zajrzyj do Przepisów dla maluszka.', title_pt = 'Como está a reserva de ferro? 🥩', body_pt = 'Confirme com o Registo de Alimentação se hoje comeu ferro suficiente. Se faltar, espreite as Receitas para bebés.', title_sv = 'Hur är järnförrådet? 🥩', body_sv = 'Kolla med Matningskoll om barnet har fått tillräckligt med järn i dag. Om något saknas, titta i Babyrecept.', title_vi = 'Lượng sắt thế nào rồi? 🥩', body_vi = 'Hãy kiểm tra xem hôm nay bé đã nạp đủ sắt chưa bằng công cụ Theo dõi cữ bú. Nếu còn thiếu, hãy xem Công thức cho bé.', title_zh = '铁摄入够吗？🥩', body_zh = '用喂养记录工具看看今天铁是否摄入足够。如果不足，就看看宝宝食谱吧。' WHERE id = 'e2aefd08-9263-41a3-87d4-c2d0378c7526' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un cuento especial 🪄', body_es = 'Crea en Cuentos inteligentes una historia especial protagonizada por tu peque: «Las aventuras del explorador de año y medio».', title_fr = 'Un conte unique 🪄', body_fr = 'Dans les Contes intelligents, créez une histoire unique dont votre enfant est le héros : « Les aventures du petit explorateur de 1 an et demi ».', title_hi = 'खास कहानी 🪄', body_hi = 'स्मार्ट कहानियों में ऐसी खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: ''1.5 साल के खोजी के कारनामे''।', title_id = 'Dongeng istimewa 🪄', body_id = 'Di Dongeng Pintar, buat kisah istimewa dengan si kecil sebagai pahlawannya: Petualangan Penjelajah Usia 1,5 Tahun.', title_ja = '特別なお話 🪄', body_ja = '「スマートおはなし」で、お子さんが主人公の特別なお話「1歳半の探検家の冒険」をつくりましょう。', title_ko = '특별한 동화 🪄', body_ko = '스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: 1살 반 꼬마 탐험가의 모험.', title_nl = 'Een speciaal sprookje 🪄', body_nl = 'Maak in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: De avonturen van een ontdekkingsreiziger van 1,5 jaar.', title_pl = 'Wyjątkowa bajka 🪄', body_pl = 'Stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Przygody 1,5-rocznego odkrywcy”.', title_pt = 'Uma história especial 🪄', body_pt = 'Crie nas Histórias Inteligentes uma história especial em que o herói é o seu filho: "As aventuras do explorador de 1 ano e meio".', title_sv = 'Egen saga 🪄', body_sv = 'Skapa en speciell berättelse i Smarta sagor där ditt barn är hjälten: Äventyren med den 1,5-åriga upptäcktsresanden.', title_vi = 'Câu chuyện riêng 🪄', body_vi = 'Trong Truyện cổ tích thông minh, hãy tạo một câu chuyện đặc biệt với nhân vật chính là chính con mình: "Cuộc phiêu lưu của nhà thám hiểm 1,5 tuổi".', title_zh = '专属故事 🪄', body_zh = '在智能故事里创作一个以你的孩子为主角的专属故事：《1岁半小探险家历险记》。' WHERE id = '48983c78-1769-4320-a7cf-ba470eef1415' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Sigue creciendo! 🌟', body_es = '¡Ya tiene más de 18 meses! Empieza una nueva etapa con un niño que anda solo, muestra sus emociones, es terco, ¡pero está lleno de amor!', title_fr = 'Il continue de grandir ! 🌟', body_fr = 'Il a déjà plus de 18 mois ! Une nouvelle période commence avec un enfant qui marche seul, montre ses émotions, têtu mais tellement plein d''amour !', title_hi = 'बढ़ना जारी है! 🌟', body_hi = 'वह अब 18 महीने से बड़ा है! खुलकर चलने वाले, अपनी भावनाएँ दिखाने वाले, ज़िद्दी पर बेहद प्यार भरे बच्चे के साथ एक नया दौर शुरू हो रहा है!', title_id = 'Terus tumbuh! 🌟', body_id = 'Kini usianya sudah lebih dari 18 bulan! Babak baru dimulai bersama anak yang berjalan sendiri, menunjukkan emosinya, keras kepala, tapi sangat penuh cinta!', title_ja = 'ぐんぐん成長中！🌟', body_ja = 'もう1歳6か月を過ぎました！ひとりで歩き、気持ちを表し、いやいやもあるけれど愛情いっぱいの子どもとの、新しい時期が始まります！', title_ko = '계속 자라요! 🌟', body_ko = '이제 18개월이 넘었어요! 자유롭게 걷고, 감정을 드러내고, 고집도 세지만 사랑이 넘치는 아이와 새로운 시기가 시작돼요!', title_nl = 'Hij blijft groeien! 🌟', body_nl = 'Je kindje is nu ouder dan 18 maanden! Er begint een nieuwe periode met een kindje dat zelf loopt, zijn gevoelens laat zien, koppig maar heel liefdevol is!', title_pl = 'Rośniemy dalej! 🌟', body_pl = 'Ma już ponad 18 miesięcy! Zaczyna się nowy etap z dzieckiem, które samo chodzi, okazuje emocje, bywa uparte, ale jest pełne miłości!', title_pt = 'Continua a crescer! 🌟', body_pt = 'Já tem mais de 18 meses! Começa uma nova fase com uma criança que anda sozinha, mostra as emoções, é teimosa mas cheia de amor!', title_sv = 'Fortsätt växa! 🌟', body_sv = 'Barnet är nu äldre än 18 månader! En ny period börjar med ett barn som går fritt, visar sina känslor, är envist men fullt av kärlek!', title_vi = 'Tiếp tục lớn khôn! 🌟', body_vi = 'Bé đã hơn 18 tháng rồi! Một giai đoạn mới bắt đầu cùng một đứa trẻ tự đi lại, biết thể hiện cảm xúc, bướng bỉnh nhưng tràn đầy yêu thương!', title_zh = '继续长大！🌟', body_zh = '他已经超过18个月了！和一个会自己走、会表达情绪、有点倔却充满爱的孩子在一起，新的阶段开始了！' WHERE id = '9815225a-8bb2-4fd7-93dd-34bcbbda8ac0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Regresión del sueño de los 18 meses? 🥱', body_es = '¿Se resiste a dormirse o se despierta por la noche? Es la famosa regresión del sueño de esta etapa. Recibe de Anacan AI información científica sobre este proceso biológico.', title_fr = 'La régression du sommeil de 18 mois ? 🥱', body_fr = 'Il résiste à l''endormissement ou se réveille la nuit ? C''est la fameuse régression du sommeil de cette période. Obtenez auprès d''Anacan AI des informations scientifiques sur ce processus biologique.', title_hi = '18 महीने की स्लीप रिग्रेशन? 🥱', body_hi = 'सोने का विरोध करता है या रात में जागता है? यह इस दौर की मशहूर स्लीप रिग्रेशन है। Anacan AI से इस जैविक प्रक्रिया के बारे में वैज्ञानिक जानकारी लीजिए।', title_id = 'Regresi tidur 18 bulan? 🥱', body_id = 'Ia menolak tidur atau terbangun di malam hari? Ini regresi tidur yang terkenal di masa ini. Dapatkan informasi ilmiah tentang proses biologis ini dari Anacan AI.', title_ja = '1歳半の睡眠退行？🥱', body_ja = '寝るのを嫌がったり、夜中に起きたりしますか？この時期によくある睡眠退行です。この体の自然な変化について、Anacan AIで科学的な情報を確認しましょう。', title_ko = '18개월 수면 퇴행? 🥱', body_ko = '잠들기를 거부하거나 밤에 깨나요? 이 시기에 잘 알려진 수면 퇴행이에요. 이 생물학적 과정에 대한 과학적 정보를 Anacan AI에게 받아 보세요.', title_nl = 'Slaapterugval na 18 maanden? 🥱', body_nl = 'Verzet je kindje zich tegen het slapengaan of wordt hij ''s nachts wakker? Dat is de bekende slaapterugval van deze periode. Krijg bij Anacan AI wetenschappelijke uitleg over dit biologische proces.', title_pl = 'Regres snu w 18. miesiącu? 🥱', body_pl = 'Broni się przed zasypianiem albo budzi się w nocy? To słynny regres snu w tym okresie. Poznaj w Anacan AI naukowe informacje o tym biologicznym procesie.', title_pt = 'A regressão do sono dos 18 meses? 🥱', body_pt = 'Resiste a adormecer ou acorda de noite? É a famosa regressão do sono desta fase. Receba do Anacan AI informação científica sobre este processo biológico.', title_sv = 'Sömnregression vid 18 månader? 🥱', body_sv = 'Kämpar barnet emot insomnandet eller vaknar på natten? Det är den här periodens kända sömnregression. Få vetenskaplig information om denna biologiska process från Anacan AI.', title_vi = 'Thoái lui giấc ngủ 18 tháng? 🥱', body_vi = 'Bé chống lại giấc ngủ hay thức giấc ban đêm? Đây là giai đoạn thoái lui giấc ngủ nổi tiếng của tuổi này. Hãy tìm hiểu thông tin khoa học về quá trình sinh học này cùng Anacan AI.', title_zh = '18个月睡眠倒退？🥱', body_zh = '抗拒入睡，或者夜里醒来？这是这个阶段出名的睡眠倒退。向Anacan AI了解这个生理过程的科学知识吧。' WHERE id = 'cdca9fee-71e1-4e46-aea7-41734d6fa68a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La terquedad del «¡Yo solo!» 🛑', body_es = 'Quiere cogerlo todo él solo, incluso cosas peligrosas. Prepárate para la tormenta cuando se lo quites. En lugar de prohibir, prueba a desviar su atención hacia algo más interesante.', title_fr = 'La période du « Tout seul ! » 🛑', body_fr = 'Il veut tout prendre lui-même, même les objets dangereux. Préparez-vous à la tempête quand vous les lui retirez. Plutôt que d''interdire, essayez de détourner son attention vers quelque chose de plus intéressant.', title_hi = '''मैं खुद!'' की ज़िद 🛑', body_hi = 'हर चीज़, यहाँ तक कि खतरनाक चीज़ें भी, खुद उठाना चाहता है। उसके हाथ से लेने पर उठने वाले तूफ़ान के लिए तैयार रहिए। मना करने के बजाय उसका ध्यान किसी और दिलचस्प चीज़ की ओर मोड़कर देखिए।', title_id = 'Ngotot "Aku sendiri!" 🛑', body_id = 'Ia ingin mengambil sendiri segala hal, bahkan benda berbahaya. Bersiaplah menghadapi badai saat Anda mengambilnya dari tangannya. Daripada melarang, coba alihkan perhatiannya ke sesuatu yang lebih menarik.', title_ja = '「自分で！」のこだわり 🛑', body_ja = 'なんでも、危ないものでさえ自分で取りたがります。取り上げると大嵐になる覚悟を。禁止するかわりに、もっと楽しいものに気をそらしてみましょう。', title_ko = '"내가 할래!" 고집 🛑', body_ko = '모든 걸, 위험한 물건까지도 직접 집으려 해요. 빼앗으면 몰아칠 폭풍에 대비하세요. 금지하는 대신 더 흥미로운 것으로 관심을 돌려 보세요.', title_nl = 'Koppig zelf willen 🛑', body_nl = 'Je kindje wil alles zelf pakken, zelfs gevaarlijke dingen. Wees voorbereid op een storm als je het afpakt. Probeer in plaats van een verbod zijn aandacht op iets leukers te richten.', title_pl = 'Upór „Sam!” 🛑', body_pl = 'Chce sam brać wszystko, nawet niebezpieczne przedmioty. Gdy mu coś zabierzesz, szykuj się na burzę. Zamiast zakazu spróbuj skierować jego uwagę na coś ciekawszego.', title_pt = 'A teimosia do "Sozinho!" 🛑', body_pt = 'Quer pegar sozinho em tudo, até em objetos perigosos. Prepare-se para a tempestade quando lhos tirar das mãos. Em vez de proibir, experimente desviar a atenção dele para algo mais interessante.', title_sv = 'Envisheten med ”Själv!” 🛑', body_sv = 'Barnet vill ta allt själv, även farliga saker. Var beredd på stormen när du tar det ifrån barnet. Prova att i stället för ett förbud leda uppmärksamheten till något mer spännande.', title_vi = 'Sự bướng bỉnh "Con tự làm!" 🛑', body_vi = 'Bé muốn tự cầm mọi thứ, kể cả đồ nguy hiểm. Hãy sẵn sàng cho cơn bão khi mẹ lấy đi. Thay vì cấm đoán, hãy thử hướng sự chú ý của bé sang một thứ thú vị hơn.', title_zh = '“我自己来！”的倔强 🛑', body_zh = '什么都要自己拿，连危险的东西也是。从他手里拿走时，准备好迎接一场风暴吧。与其直接禁止，不如试着把他的注意力转移到更有趣的东西上。' WHERE id = 'be8b4ec7-a61e-4f60-ae12-bdc8b7beda03' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Masaje y silencio 💆‍♀️', body_es = '¿Tienes la espalda destrozada de correr todo el día? Cuando se duerma, pide a tu pareja un masaje de hombros de 10 minutos. ¡Te lo mereces!', title_fr = 'Massage et silence 💆‍♀️', body_fr = 'À force de courir toute la journée, vous avez le dos en compote ? Une fois qu''il dort, demandez à votre conjoint un massage des épaules de 10 minutes. Vous le méritez !', title_hi = 'मालिश और खामोशी 💆‍♀️', body_hi = 'पूरे दिन भागते-भागते कमर टूट गई? बच्चे के सोने के बाद अपने साथी से 10 मिनट की कंधों की मालिश माँगिए। आप इसकी हकदार हैं!', title_id = 'Pijat dan ketenangan 💆‍♀️', body_id = 'Punggung serasa patah karena berlari seharian? Setelah si kecil tidur, minta pijatan bahu 10 menit dari pasangan Anda. Anda pantas mendapatkannya!', title_ja = 'マッサージと静けさ 💆‍♀️', body_ja = '一日中追いかけて、腰がくたくた？お子さんが寝たら、パートナーに10分間の肩もみをお願いしましょう。あなたにはその価値があります！', title_ko = '마사지와 고요함 💆‍♀️', body_ko = '하루 종일 뛰어다니느라 허리가 끊어질 것 같나요? 아이가 잠들면 배우자에게 10분 어깨 마사지를 부탁하세요. 그럴 자격이 충분해요!', title_nl = 'Massage en stilte 💆‍♀️', body_nl = 'Breekt je rug van het rennen de hele dag? Vraag je partner als je kindje slaapt om een schoudermassage van 10 minuten. Je verdient het!', title_pl = 'Masaż i cisza 💆‍♀️', body_pl = 'Plecy pękają ci od całodziennego biegania? Gdy maluszek zaśnie, poproś partnera o 10-minutowy masaż ramion. Zasługujesz na to!', title_pt = 'Massagem e silêncio 💆‍♀️', body_pt = 'De correr o dia todo, as costas estão a dar de si? Depois de a criança adormecer, peça ao seu companheiro uma massagem aos ombros de 10 minutos. Merece-a!', title_sv = 'Massage och tystnad 💆‍♀️', body_sv = 'Värker ryggen av att springa hela dagen? Be din partner om en 10 minuters axelmassage när barnet har somnat. Du förtjänar det!', title_vi = 'Xoa bóp và yên tĩnh 💆‍♀️', body_vi = 'Lưng mẹ rã rời vì chạy theo bé cả ngày? Khi bé ngủ, hãy nhờ bố xoa bóp vai cho mẹ 10 phút. Mẹ xứng đáng được như vậy!', title_zh = '按摩与安静 💆‍♀️', body_zh = '跑了一整天，腰都要断了？宝宝睡着后，请另一半给你按摩10分钟肩膀。这是你应得的！' WHERE id = 'd6508b29-e914-4995-93c3-58c73e271159' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Estás en plena carrera 🏃‍♂️', body_es = '¿Corre a toda velocidad de una habitación a otra y no hay quien le pare? Estos días su equilibrio de pie se consolida. Quita los pequeños peligros de casa y disfruta viendo estos momentos llenos de energía.', title_fr = 'Vous êtes sur la piste de course 🏃‍♂️', body_fr = 'Il court à toute vitesse d''une pièce à l''autre sans jamais s''arrêter ? En ce moment, son équilibre debout se met complètement en place. Écartez les petits dangers de la maison et observez de loin ces moments pleins d''énergie.', title_hi = 'आप रेस ट्रैक पर हैं 🏃‍♂️', body_hi = 'एक कमरे से दूसरे कमरे तक तेज़ी से दौड़ता है और रुकता ही नहीं? इन दिनों पैरों पर उसका संतुलन पूरी तरह बन रहा है। घर के छोटे-मोटे खतरे हटाइए और इन ऊर्जा भरे पलों को दूर से देखिए।', title_id = 'Anda di lintasan lari 🏃‍♂️', body_id = 'Ia berlari kencang dari kamar ke kamar tanpa henti? Di hari-hari ini keseimbangannya saat berdiri makin matang. Singkirkan bahaya-bahaya kecil di rumah dan saksikan momen penuh energi ini dari jauh.', title_ja = '全力疾走中 🏃‍♂️', body_ja = '部屋から部屋へ止まることなく走り回っていますか？この時期、立ったときのバランスがしっかり身につきます。家の中の小さな危険を片付けて、元気いっぱいの姿を見守りましょう。', title_ko = '달리기 트랙 위에 있어요 🏃‍♂️', body_ko = '방에서 방으로 쉬지 않고 빠르게 뛰어다니나요? 요즘 서 있는 균형이 완전히 잡혀 가고 있어요. 집 안의 작은 위험 요소를 치우고 이 활기찬 순간을 옆에서 지켜봐 주세요.', title_nl = 'Je zit op de renbaan 🏃‍♂️', body_nl = 'Rent je kindje snel van kamer naar kamer zonder te stoppen? Zijn evenwicht op twee benen is in deze dagen bijna helemaal ontwikkeld. Ruim kleine gevaren in huis op en kijk van een afstandje naar deze energieke momenten.', title_pl = 'Jesteś na bieżni 🏃‍♂️', body_pl = 'Szybko biega z pokoju do pokoju i nie umie się zatrzymać? W tych dniach w pełni kształtuje się równowaga na nóżkach. Usuń drobne zagrożenia w domu i obserwuj z boku te pełne energii chwile.', title_pt = 'Está na pista de corrida 🏃‍♂️', body_pt = 'Corre a toda a velocidade de divisão em divisão e não para? Nestes dias, o equilíbrio de pé fica completo. Tire de casa os pequenos perigos e observe à distância estes momentos cheios de energia.', title_sv = 'Du är på löparbanan 🏃‍♂️', body_sv = 'Springer barnet snabbt från rum till rum och kan inte stanna? Balansen på fötterna formas helt de här dagarna. Plocka bort små faror i hemmet och följ dessa energiska stunder på avstånd.', title_vi = 'Mẹ đang trên đường chạy 🏃‍♂️', body_vi = 'Bé chạy thật nhanh từ phòng này sang phòng khác không ngừng nghỉ? Những ngày này khả năng giữ thăng bằng khi đứng đang hoàn thiện. Hãy dọn những mối nguy nhỏ trong nhà và ngắm nhìn những khoảnh khắc sôi động này.', title_zh = '你在跑道上 🏃‍♂️', body_zh = '在房间之间飞快地跑，停都停不下来？这些天他的站立平衡正在完全形成。收拾好家里的小隐患，在一旁欣赏这些活力满满的时刻吧。' WHERE id = 'dd068a2e-5d54-49f1-be6d-02db7c690974' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Enemistad con la fruta 🍎', body_es = '¿Hoy tira al suelo la manzana que ayer le encantaba? Ser selectivo con la comida es el problema más clásico de esta edad. Sin perderte en internet, mira en Recetas saludables formas divertidas de presentar la fruta.', title_fr = 'La guerre des fruits 🍎', body_fr = 'Il jette aujourd''hui par terre la pomme qu''il adorait hier ? Être difficile à table est le grand classique de cet âge. Sans vous perdre sur Internet, découvrez des présentations de fruits amusantes dans les Recettes saines.', title_hi = 'फलों से दुश्मनी 🍎', body_hi = 'कल का पसंदीदा सेब आज ज़मीन पर फेंक देता है? खाने में नखरे इस उम्र की सबसे आम परेशानी है। इंटरनेट में खोए बिना सेहतमंद रेसिपी में फल परोसने के मज़ेदार तरीके देखिए।', title_id = 'Musuh buah 🍎', body_id = 'Apel yang kemarin ia sukai, hari ini dilempar ke lantai? Pilih-pilih makanan adalah masalah paling klasik di usia ini. Jangan tersesat di internet, lihat cara penyajian buah yang seru di Resep Sehat.', title_ja = '果物ぎらい 🍎', body_ja = '昨日大好きだったりんごを、今日は床に投げる？好き嫌いはこの年齢のいちばんよくある悩みです。ネットで迷わず、「ヘルシーレシピ」で楽しい果物の盛り付けを見てみましょう。', title_ko = '과일과의 전쟁 🍎', body_ko = '어제 좋아하던 사과를 오늘은 바닥에 던지나요? 음식을 가리는 건 이 나이의 가장 흔한 고민이에요. 인터넷에서 헤매지 말고 건강한 레시피에서 재미있는 과일 담음새를 찾아보세요.', title_nl = 'Vijandschap met fruit 🍎', body_nl = 'Gooit je kindje vandaag de appel op de grond die hij gisteren nog lekker vond? Kieskeurig eten is het klassieke probleem van deze leeftijd. Verdwaal niet op internet en bekijk leuke manieren om fruit op te dienen in Gezonde recepten.', title_pl = 'Wojna z owocami 🍎', body_pl = 'Jabłko, które wczoraj uwielbiał, dziś rzuca na podłogę? Wybiórczość w jedzeniu to klasyczny problem tego wieku. Nie gub się w internecie, zajrzyj do zdrowych przepisów po zabawne sposoby podania owoców.', title_pt = 'Guerra à fruta 🍎', body_pt = 'A maçã de que ontem gostava hoje vai parar ao chão? Ser esquisito com a comida é o problema mais clássico desta idade. Sem se perder na internet, veja nas Receitas Saudáveis formas divertidas de apresentar a fruta.', title_sv = 'Fruktfiendskap 🍎', body_sv = 'Kastar barnet i dag på golvet äpplet det älskade i går? Kräsenhet är den här ålderns mest klassiska problem. Gå inte vilse på nätet, titta på roliga sätt att servera frukt i Hälsosamma recept.', title_vi = 'Bé "ghét" trái cây 🍎', body_vi = 'Quả táo hôm qua bé thích, hôm nay lại ném xuống sàn? Kén ăn là vấn đề kinh điển nhất của tuổi này. Đừng lạc lối trên mạng, hãy xem những cách bày trái cây vui mắt trong Công thức lành mạnh.', title_zh = '跟水果过不去 🍎', body_zh = '昨天还爱吃的苹果，今天就扔到地上？挑食是这个年龄最典型的问题。别在网上迷路了，去健康食谱里看看有趣的水果摆盘吧。' WHERE id = 'e1121d1f-a680-4fb9-9a1f-6792cb16e172' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La conversación se alarga 🗣️', body_es = '¿Nada más despertarse se pone a contar cosas largas en su idioma? Su centro del lenguaje vive una explosión. Escúchale con toda seriedad y respóndele «¿De verdad?», «¿Y luego qué pasó?».', title_fr = 'La conversation s''allonge 🗣️', body_fr = 'Dès son réveil, il vous raconte de longues histoires dans sa propre langue ? Son centre du langage est en pleine explosion. Écoutez-le sérieusement et répondez : « Vraiment ? », « Et après, que s''est-il passé ? ».', title_hi = 'बातचीत लंबी चल रही है 🗣️', body_hi = 'सुबह जागते ही अपनी भाषा में लंबी-लंबी बातें करता है? उसकी बोली में ज़बरदस्त उछाल आ रहा है। उसे ध्यान से सुनिए और ''सच में?'', ''फिर क्या हुआ?'' कहकर जवाब दीजिए।', title_id = 'Obrolannya makin panjang 🗣️', body_id = 'Begitu bangun pagi, ia bercerita panjang lebar dengan bahasanya sendiri? Pusat bicaranya sedang berkembang pesat. Dengarkan dengan serius dan jawab "Oh ya?", "Lalu apa yang terjadi?".', title_ja = 'おしゃべりが長くなってきた 🗣️', body_ja = '朝起きたとたん、自分の言葉で長々とおしゃべりしますか？言葉の力が爆発的に伸びています。真剣に耳を傾けて、「ほんと？」「それからどうなったの？」と返してあげましょう。', title_ko = '대화가 길어져요 🗣️', body_ko = '아침에 눈뜨자마자 자기만의 말로 한참 이야기하나요? 언어 중추가 폭발적으로 자라고 있어요. 진지하게 들어 주고 "정말?", "그다음엔 어떻게 됐어?" 하고 대답해 주세요.', title_nl = 'Het gesprek duurt lang 🗣️', body_nl = 'Vertelt je kindje meteen na het wakker worden een heel verhaal in zijn eigen taaltje? Zijn taalcentrum maakt een explosie door. Luister serieus en antwoord: echt waar? En toen?', title_pl = 'Rozmowa się przeciąga 🗣️', body_pl = 'Zaraz po przebudzeniu długo opowiada coś po swojemu? Ośrodek mowy przeżywa eksplozję. Słuchaj go z pełną powagą i odpowiadaj: „Naprawdę?”, „I co było dalej?”.', title_pt = 'A conversa está cada vez mais longa 🗣️', body_pt = 'Mal acorda, fala muito tempo na sua própria língua? O centro da fala está a viver uma explosão. Escute-o com toda a seriedade e responda: "A sério?", "E depois, o que aconteceu?".', title_sv = 'Pratet drar ut på tiden 🗣️', body_sv = 'Pratar barnet länge om något på sitt eget språk så fort det vaknar på morgonen? Talcentrum upplever en explosion. Lyssna på allvar och svara ”Verkligen?” eller ”Vad hände sedan?”.', title_vi = 'Cuộc trò chuyện kéo dài 🗣️', body_vi = 'Vừa thức dậy là bé đã líu lo thật lâu bằng ngôn ngữ riêng? Trung tâm ngôn ngữ đang bùng nổ. Hãy nghiêm túc lắng nghe và đáp lại: "Thật sao?", "Rồi sao nữa?".', title_zh = '话越说越长 🗣️', body_zh = '早上一醒来就用自己的语言滔滔不绝？语言中枢正在经历大爆发。认真听他说，回应他“真的吗？”“然后呢？”吧。' WHERE id = 'ef76ecee-5471-407a-a72c-9593be1406af' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Oscuridad total 🌙', body_es = '¿Se resiste a dormirse? Hasta una lucecita en la habitación le distrae. Apaga las pantallas, deja la habitación totalmente a oscuras y ayuda a liberar la melatonina.', title_fr = 'L''obscurité totale 🌙', body_fr = 'Il résiste à l''endormissement ? Même une petite lumière dans la chambre peut le distraire. Éteignez les écrans et faites le noir complet pour accélérer la sécrétion de mélatonine.', title_hi = 'पूरा अँधेरा 🌙', body_hi = 'सोने का विरोध करता है? कमरे की छोटी सी रोशनी भी उसका ध्यान भटकाती है। स्क्रीन बंद कीजिए और कमरे में पूरा अँधेरा करके मेलाटोनिन बनने की रफ़्तार बढ़ाइए।', title_id = 'Gelap total 🌙', body_id = 'Ia menolak tidur? Bahkan cahaya kecil di kamar bisa mengalihkan perhatiannya. Matikan layar, buat kamar benar-benar gelap, dan percepat produksi melatonin.', title_ja = '真っ暗にしよう 🌙', body_ja = '寝るのを嫌がる？部屋の小さな明かりさえ気が散る原因になります。画面を消して部屋を真っ暗にし、メラトニンの分泌を促しましょう。', title_ko = '완전한 어둠 🌙', body_ko = '잠들기를 거부하나요? 방 안의 작은 불빛 하나도 주의를 빼앗아요. 화면을 끄고 방을 완전히 어둡게 해 멜라토닌 분비를 도와주세요.', title_nl = 'Helemaal donker 🌙', body_nl = 'Verzet je kindje zich tegen het slapen? Zelfs een klein lampje leidt hem af. Zet schermen uit en maak de kamer helemaal donker, zo wordt sneller melatonine aangemaakt.', title_pl = 'Całkowita ciemność 🌙', body_pl = 'Broni się przed zasypianiem? Nawet małe światełko w pokoju go rozprasza. Wyłącz ekrany, całkiem zaciemnij pokój i przyspiesz wydzielanie melatoniny.', title_pt = 'Escuridão total 🌙', body_pt = 'Resiste a adormecer? No quarto, até uma luz pequena o distrai. Desligue os ecrãs e deixe o quarto totalmente escuro para acelerar a libertação de melatonina.', title_sv = 'Helt mörkt 🌙', body_sv = 'Kämpar barnet emot insomnandet? Även ett litet ljus i rummet stör uppmärksamheten. Stäng av skärmarna, gör rummet helt mörkt och påskynda bildningen av melatonin.', title_vi = 'Bóng tối hoàn toàn 🌙', body_vi = 'Bé chống lại giấc ngủ? Ngay cả một chút ánh sáng nhỏ trong phòng cũng khiến bé xao nhãng. Hãy tắt màn hình và làm tối hoàn toàn căn phòng để melatonin được tiết ra nhanh hơn.', title_zh = '完全黑暗 🌙', body_zh = '抗拒入睡？房间里哪怕一点小光都会分散他的注意力。关掉屏幕，让房间完全变暗，帮助褪黑素更快分泌。' WHERE id = '1bf2c33f-3711-4208-8da6-0a931502b566' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te ha vuelto a fallar la memoria? 🛒', body_es = '¿Se han acabado los pañales o el yogur? No te agobies: apúntalo al momento en la Lista de la compra y que tu pareja lo compre al volver del trabajo.', title_fr = 'Votre mémoire vous a encore joué un tour ? 🛒', body_fr = 'Plus de couches ou de yaourts ? Ne vous fatiguez pas l''esprit, ajoutez-les tout de suite à la Liste de courses, votre conjoint les achètera en rentrant du travail.', title_hi = 'याददाश्त ने फिर धोखा दिया? 🛒', body_hi = 'डायपर खत्म हुए या दही? दिमाग मत थकाइए, तुरंत शॉपिंग लिस्ट में डालिए, ताकि आपके साथी काम से लौटते समय ले आएँ।', title_id = 'Ingatan Anda menipu lagi? 🛒', body_id = 'Popok atau yogurt habis? Jangan bebani pikiran, langsung masukkan ke Daftar Belanja, biar pasangan Anda membelinya saat pulang kerja.', title_ja = 'またうっかり忘れた？🛒', body_ja = 'おむつやヨーグルトが切れた？頭を悩ませず、すぐに「買い物リスト」に入れて、パートナーに仕事帰りに買ってきてもらいましょう。', title_ko = '기억력이 또 깜빡했나요? 🛒', body_ko = '기저귀가 떨어졌나요, 요거트가 떨어졌나요? 머리 쓰지 말고 바로 쇼핑 목록에 넣어 두세요. 배우자가 퇴근길에 사 올 거예요.', title_nl = 'Liet je geheugen je weer in de steek? 🛒', body_nl = 'Zijn de luiers of de yoghurt op? Pijnig je hoofd niet, zet het meteen op het Boodschappenlijstje, dan neemt je partner het mee op weg naar huis.', title_pl = 'Pamięć znów cię zawiodła? 🛒', body_pl = 'Skończyły się pieluszki albo jogurt? Nie męcz głowy, od razu wpisz to na Listę zakupów, a partner kupi w drodze z pracy.', title_pt = 'A memória voltou a pregar-lhe uma partida? 🛒', body_pt = 'Acabaram as fraldas ou o iogurte? Não canse a cabeça: ponha-os já na Lista de Compras e o seu companheiro compra-os no regresso do trabalho.', title_sv = 'Har minnet svikit dig igen? 🛒', body_sv = 'Har blöjorna eller yoghurten tagit slut? Trötta inte ut huvudet, lägg det direkt i Inköpslistan, så kan din partner handla på vägen hem från jobbet.', title_vi = 'Trí nhớ lại đánh lừa mẹ? 🛒', body_vi = 'Hết tã hay sữa chua rồi? Đừng làm đầu óc mệt thêm, hãy thêm ngay vào Danh sách mua sắm để bố mua trên đường đi làm về.', title_zh = '记性又跟你开玩笑了？🛒', body_zh = '尿布还是酸奶用完了？别费脑子记，马上丢进购物清单，让另一半下班路上买回来。' WHERE id = '5f000b16-6031-438b-92a6-3ea1d69ae68b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los detalles de los libros 📖', body_es = '¿Pasa las páginas y señala con el dedo el detalle más pequeño del dibujo (por ejemplo, un pajarito)? Registra esta atención cognitiva en el Seguimiento del desarrollo. ¡Su memoria visual funciona de maravilla!', title_fr = 'Les détails des livres 📖', body_fr = 'Il feuillette un livre et montre du doigt le plus petit détail d''une image (par exemple un petit oiseau) ? Notez cette attention cognitive dans le Suivi de développement. Sa mémoire visuelle fonctionne à merveille !', title_hi = 'किताबों की बारीकियाँ 📖', body_hi = 'किताब पलटते हुए तस्वीर की सबसे छोटी चीज़ (जैसे नन्ही चिड़िया) की ओर उँगली दिखाता है? ग्रोथ ट्रैकर में इस संज्ञानात्मक ध्यान को दर्ज कीजिए। देखी चीज़ें याद रखने की उसकी क्षमता शानदार है!', title_id = 'Detail di buku 📖', body_id = 'Ia membalik halaman buku dan menunjuk detail terkecil di gambar (misalnya burung kecil) dengan jarinya? Catat perhatian kognitif ini di Pelacak Perkembangan. Ingatan visualnya bekerja dengan sangat baik!', title_ja = '絵本の細かいところ 📖', body_ja = '絵本をめくって、絵のほんの小さなところ（たとえば小鳥）を指さしますか？「発達トラッカー」にこの注意力を記録しましょう。見たものを覚える力がすばらしく働いています！', title_ko = '책 속의 작은 부분 📖', body_ko = '책장을 넘기며 그림 속 아주 작은 부분(예: 작은 새)까지 손가락으로 가리키나요? 성장 기록에 이 인지적 집중력을 남기세요. 시각 기억력이 훌륭하게 발달하고 있어요!', title_nl = 'Details in boeken 📖', body_nl = 'Bladert je kindje door een boek en wijst hij het kleinste detail op een plaatje aan (bijvoorbeeld een vogeltje)? Noteer deze cognitieve aandacht in de Groeitracker. Zijn visuele geheugen werkt prima!', title_pl = 'Szczegóły w książkach 📖', body_pl = 'Przegląda książkę i pokazuje paluszkiem najmniejszy szczegół na obrazku (np. małego ptaszka)? Zapisz tę uważność poznawczą w Śledzeniu rozwoju. Pamięć wzrokowa działa świetnie!', title_pt = 'Os detalhes dos livros 📖', body_pt = 'Folheia o livro e aponta com o dedo o detalhe mais pequeno da imagem (por exemplo, um passarinho)? Registe esta atenção cognitiva no Registo de Desenvolvimento. A memória visual funciona muito bem!', title_sv = 'Detaljer i böckerna 📖', body_sv = 'Bläddrar barnet i boken och pekar ut den minsta detaljen på bilden (till exempel en liten fågel)? Anteckna denna kognitiva uppmärksamhet i Utvecklingsspåraren. Det visuella minnet fungerar utmärkt!', title_vi = 'Những chi tiết trong sách 📖', body_vi = 'Bé lật sách và chỉ tay vào chi tiết nhỏ nhất trong tranh (ví dụ, một chú chim nhỏ)? Hãy ghi lại sự chú ý nhận thức này trong Theo dõi phát triển. Trí nhớ hình ảnh của bé hoạt động thật tuyệt!', title_zh = '书里的细节 📖', body_zh = '他翻着书，用手指指出图里最小的细节（比如一只小鸟）？在发育追踪里记下这份认知上的专注吧。视觉记忆很棒！' WHERE id = '8593e3b3-5794-49a0-a5ef-d04af1bd53a7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisemos su horario de sueño ⏱️', body_es = '¿No quiere irse a la cama por la noche? Analiza la gráfica del Temporizador de sueño. Quizá haya que acortar un poco la siesta.', title_fr = 'Vérifions son rythme de sommeil ⏱️', body_fr = 'Il ne veut pas se coucher le soir ? Analysez le graphique du minuteur de sommeil. Il faut peut-être raccourcir un peu la sieste.', title_hi = 'नींद का रूटीन जाँचें ⏱️', body_hi = 'शाम को सोना नहीं चाहता? स्लीप टाइमर के चार्ट का विश्लेषण कीजिए। शायद दिन की झपकी थोड़ी छोटी करनी होगी।', title_id = 'Yuk, cek pola tidurnya ⏱️', body_id = 'Ia tidak mau tidur di malam hari? Analisis grafik Timer Tidur. Mungkin tidur siangnya perlu sedikit dipersingkat.', title_ja = '睡眠リズムをチェック ⏱️', body_ja = '夜、寝たがらない？睡眠タイマーの記録を分析しましょう。お昼寝を少し短くするといいかもしれません。', title_ko = '수면 일과를 확인해요 ⏱️', body_ko = '저녁에 자기 싫어하나요? 수면 타이머 그래프를 분석해 보세요. 낮잠을 조금 줄여야 할 수도 있어요.', title_nl = 'Laten we het slaapritme controleren ⏱️', body_nl = 'Wil je kindje ''s avonds niet slapen? Analyseer het schema van de Slaaptimer. Misschien moet het middagdutje iets korter.', title_pl = 'Sprawdźmy rytm snu ⏱️', body_pl = 'Wieczorem nie chce spać? Przeanalizuj wykres timera snu. Może trzeba trochę skrócić drzemkę w ciągu dnia.', title_pt = 'Vamos verificar o sono ⏱️', body_pt = 'Não quer ir dormir à noite? Analise o gráfico do temporizador de sono. Talvez seja preciso encurtar um pouco a sesta.', title_sv = 'Vi kollar sömnrutinen ⏱️', body_sv = 'Vill barnet inte sova på kvällen? Analysera sömntimerns schema. Kanske behöver dagsluren kortas lite.', title_vi = 'Cùng kiểm tra nếp ngủ ⏱️', body_vi = 'Buổi tối bé không chịu ngủ? Hãy phân tích biểu đồ của Bộ hẹn giờ ngủ. Có thể cần rút ngắn giấc ngủ ngày một chút.', title_zh = '看看睡眠作息 ⏱️', body_zh = '晚上不想睡？分析一下睡眠计时器的图表。也许需要把白天小睡稍微缩短一点。' WHERE id = '5df90283-8938-4f2c-bc5d-95fad0d0249f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡No te olvides de ti! Elige en las recetas un desayuno rápido, delicioso y rico en proteínas.', body_fr = 'Ne vous oubliez pas ! Choisissez dans les Recettes une portion savoureuse, riche en protéines et rapide à préparer pour le matin.', body_hi = 'खुद को मत भूलिए! रेसिपी से सुबह के लिए जल्दी बनने वाला, प्रोटीन से भरपूर स्वादिष्ट खाना चुनिए।', body_id = 'Jangan lupakan diri Anda! Pilih sarapan lezat kaya protein yang cepat dibuat dari bagian Resep.', body_ja = '自分のことも忘れないで！レシピから、朝にさっとつくれる、たんぱく質たっぷりのおいしい一品を選びましょう。', body_ko = '나 자신을 잊지 마세요! 레시피에서 아침에 빨리 만들 수 있는 단백질 가득한 맛있는 한 끼를 골라 보세요.', body_nl = 'Vergeet jezelf niet! Kies in Recepten een lekker ontbijt vol eiwit dat snel klaar is.', body_pl = 'Nie zapominaj o sobie! Wybierz z przepisów smaczne, bogate w białko danie na śniadanie, które szybko przygotujesz.', body_pt = 'Não se esqueça de si! Escolha nas Receitas um pequeno-almoço delicioso, rápido de preparar e rico em proteína.', body_sv = 'Glöm inte dig själv! Välj en god och proteinrik portion som går snabbt att laga till frukost bland recepten.', body_vi = 'Đừng quên bản thân mẹ! Hãy chọn trong mục Công thức một bữa sáng ngon miệng, giàu protein và làm nhanh.', body_zh = '别忘了自己！从食谱里选一份早上能快速做好、富含蛋白质的美味餐点吧。' WHERE id = 'eb685812-a20b-4dfa-8dcd-a8c0865f1a25' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las crisis del «¡No!» 🛑', body_es = '¿Protesta por todo? Consulta con nuestro asistente Anacan AI sobre la terquedad del año y medio y encuentra apoyo psicológico y soluciones.', title_fr = 'Les crises du « Non ! » 🛑', body_fr = 'Il s''oppose à tout ? Demandez conseil à notre assistant Anacan AI sur l''entêtement de 1 an et demi pour trouver un soutien psychologique et des solutions.', title_hi = '''नहीं!'' के नखरे 🛑', body_hi = 'हर बात का विरोध करता है? 1.5 साल की ज़िद के बारे में हमारे Anacan AI असिस्टेंट से सलाह लेकर मनोवैज्ञानिक सहारा और हल पाइए।', title_id = 'Krisis "Tidak!" 🛑', body_id = 'Ia membantah segala hal? Konsultasikan sikap keras kepala usia 1,5 tahun ini dengan asisten Anacan AI kami, dan temukan dukungan psikologis serta jalan keluarnya.', title_ja = '「いや！」のかんしゃく 🛑', body_ja = 'なんにでも反抗しますか？1歳半のいやいやについて、Anacan AIアシスタントに相談して、心のサポートと解決のヒントを見つけましょう。', title_ko = '"싫어!" 떼쓰기 🛑', body_ko = '모든 것에 반대하나요? 1살 반의 고집에 대해 Anacan AI 도우미와 상담하며 심리적 지원과 해결책을 찾아보세요.', title_nl = 'Nee-buien 🛑', body_nl = 'Protesteert je kindje tegen alles? Overleg met onze assistent Anacan AI over de koppigheid rond 1,5 jaar en vind psychologische steun en een uitweg.', title_pl = 'Kryzysy „Nie!” 🛑', body_pl = 'Sprzeciwia się wszystkiemu? Poradź się naszego asystenta Anacan AI w sprawie uporu półtoraroczniaka i znajdź wsparcie psychologiczne i wyjście z sytuacji.', title_pt = 'As crises do "Não!" 🛑', body_pt = 'Protesta contra tudo? Fale com o nosso assistente Anacan AI sobre a teimosia de 1 ano e meio e encontre apoio psicológico e soluções.', title_sv = '”Nej!”-utbrott 🛑', body_sv = 'Protesterar barnet mot allt? Rådfråga vår assistent Anacan AI om trotset vid 1,5 år och hitta psykologiskt stöd och en väg framåt.', title_vi = 'Những cơn khủng hoảng "Không!" 🛑', body_vi = 'Bé phản đối mọi thứ? Hãy hỏi ý kiến trợ lý Anacan AI về sự bướng bỉnh của tuổi 1,5 để nhận hỗ trợ tâm lý và tìm ra cách giải quyết.', title_zh = '“不！”的崩溃 🛑', body_zh = '什么都反对？关于1岁半的倔脾气，咨询我们的Anacan AI助手，获得心理支持，找到应对办法吧。' WHERE id = 'f80fa225-e7f6-4b7d-a7da-b651f5688ba0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bomba de vitaminas 🥗', body_es = '¡La energía de mamá no debe agotarse! Prepara en Recetas saludables para mujeres un batido delicioso que te dé energía al momento.', title_fr = 'Une bombe de vitamines 🥗', body_fr = 'L''énergie de maman ne doit pas s''épuiser ! Préparez un smoothie savoureux et revigorant grâce aux Recettes saines pour femmes.', title_hi = 'विटामिन बम 🥗', body_hi = 'माँ की ताकत खत्म नहीं होनी चाहिए! महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ऊर्जा देने वाली स्वादिष्ट स्मूदी बनाइए।', title_id = 'Bom vitamin 🥗', body_id = 'Tenaga ibu tidak boleh habis! Buat smoothie lezat yang langsung memberi energi dari Resep Sehat untuk wanita.', title_ja = 'ビタミンたっぷり 🥗', body_ja = 'ママの元気は切らさないで！「女性のためのヘルシーレシピ」から、すぐに元気が出るおいしいスムージーをつくりましょう。', title_ko = '비타민 폭탄 🥗', body_ko = '엄마의 힘이 바닥나면 안 돼요! 건강한 레시피에서 바로 기운을 주는 맛있는 스무디를 만들어 보세요.', title_nl = 'Een vitaminebom 🥗', body_nl = 'Een mama mag niet zonder kracht komen te zitten! Maak uit Gezonde recepten voor vrouwen een lekkere smoothie die je meteen energie geeft.', title_pl = 'Bomba witaminowa 🥗', body_pl = 'Mamie nie może zabraknąć sił! Przygotuj ze Zdrowych przepisów dla kobiet smaczne smoothie, które od razu doda ci energii.', title_pt = 'Uma bomba de vitaminas 🥗', body_pt = 'A força da mãe não se pode esgotar! Prepare nas Receitas Saudáveis para Mulheres um batido delicioso que dá energia na hora.', title_sv = 'Vitaminbomb 🥗', body_sv = 'Mammas kraft får inte ta slut! Gör en god smoothie som ger energi direkt från Hälsosamma recept för kvinnor.', title_vi = 'Quả bom vitamin 🥗', body_vi = 'Sức lực của mẹ không được cạn! Hãy làm một ly sinh tố thơm ngon, nạp năng lượng tức thì từ Công thức lành mạnh cho phụ nữ.', title_zh = '维生素炸弹 🥗', body_zh = '妈妈的力气可不能耗尽！从女性健康食谱里做一杯马上补充能量的美味果昔吧。' WHERE id = 'bd224607-0812-4b81-8b5d-af59d7d7cc10' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ritual para ir a dormir 🌙', body_es = 'Activa el Temporizador de sueño y oscurece la habitación. Analiza la gráfica y crea fácilmente el hábito de acostarle cada noche a la misma hora.', title_fr = 'Le rituel avant de dormir 🌙', body_fr = 'Lancez le minuteur de sommeil et faites le noir dans la chambre. En analysant le graphique, prenez facilement l''habitude de le coucher chaque soir à la même heure.', title_hi = 'सोने की तैयारी की रस्म 🌙', body_hi = 'स्लीप टाइमर चालू कीजिए और कमरे में अँधेरा कीजिए। चार्ट का विश्लेषण करके हर शाम एक ही समय पर सुलाने की आदत आसानी से डालिए।', title_id = 'Ritual menjelang tidur 🌙', body_id = 'Nyalakan Timer Tidur dan gelapkan kamar. Analisis grafiknya dan bentuk dengan mudah kebiasaan tidur di jam yang sama setiap malam.', title_ja = '眠りの準備の儀式 🌙', body_ja = '睡眠タイマーをオンにして、部屋を暗くしましょう。記録を分析すれば、毎晩同じ時間に寝かせる習慣がかんたんに身につきます。', title_ko = '잠자리 준비 의식 🌙', body_ko = '수면 타이머를 켜고 방을 어둡게 하세요. 그래프를 분석하며 매일 저녁 같은 시간에 재우는 습관을 쉽게 만들어 보세요.', title_nl = 'Ritueel voor het slapengaan 🌙', body_nl = 'Zet de Slaaptimer aan en maak de kamer donker. Analyseer het schema en bouw makkelijk de gewoonte op om elke avond op hetzelfde tijdstip naar bed te gaan.', title_pl = 'Rytuał przed snem 🌙', body_pl = 'Włącz timer snu i zaciemnij pokój. Analizując wykres, łatwo wyrobisz nawyk usypiania co wieczór o tej samej porze.', title_pt = 'O ritual de preparação para o sono 🌙', body_pt = 'Ligue o temporizador de sono e escureça o quarto. Analise o gráfico e crie com facilidade o hábito de o deitar todas as noites à mesma hora.', title_sv = 'Ritual inför sömnen 🌙', body_sv = 'Starta sömntimern och mörklägg rummet. Analysera schemat och skapa enkelt vanan att lägga barnet vid samma tid varje kväll.', title_vi = 'Nghi thức chuẩn bị đi ngủ 🌙', body_vi = 'Hãy bật Bộ hẹn giờ ngủ và làm tối căn phòng. Phân tích biểu đồ để dễ dàng tạo thói quen cho bé ngủ cùng một giờ mỗi tối.', title_zh = '睡前仪式 🌙', body_zh = '打开睡眠计时器，把房间调暗。分析图表，轻松养成每晚同一时间上床的习惯。' WHERE id = 'c9435c7a-e56d-449f-9eb8-fae0dc263176' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juguetes que hacen pensar 🧩', body_es = 'Los 18 meses son la edad ideal para los juegos de lógica. Descubre en Productos recomendados puzles y cubos adecuados a su edad y estimula su mente.', title_fr = 'Des jouets d''éveil 🧩', body_fr = '18 mois, c''est l''âge idéal pour les jeux de logique. Découvrez dans les Produits recommandés des puzzles et des cubes adaptés à son âge pour aiguiser son esprit.', title_hi = 'दिमागी खिलौने 🧩', body_hi = '18 महीने तर्क वाले खेलों के लिए सबसे सही समय है। सुझाए गए प्रोडक्ट में उम्र के हिसाब से पज़ल और ब्लॉक खोजिए और उसका दिमाग तेज़ कीजिए।', title_id = 'Mainan edukatif 🧩', body_id = 'Usia 18 bulan adalah waktu ideal untuk permainan logika. Temukan puzzle dan balok yang sesuai usianya di Produk Rekomendasi untuk mengasah kecerdasannya.', title_ja = '知育おもちゃ 🧩', body_ja = '1歳半は考える遊びにぴったりの時期です。「おすすめ商品」で年齢に合ったパズルや積み木を見つけて、頭をきたえましょう。', title_ko = '두뇌 발달 장난감 🧩', body_ko = '18개월은 논리 놀이에 딱 좋은 때예요. 추천 제품에서 나이에 맞는 퍼즐과 블록을 찾아 두뇌를 키워 주세요.', title_nl = 'Slim speelgoed 🧩', body_nl = '18 maanden is de ideale leeftijd voor denkspelletjes. Ontdek in Aanbevolen producten puzzels en blokken die passen bij zijn leeftijd en scherp zijn verstand.', title_pl = 'Zabawki rozwijające umysł 🧩', body_pl = '18 miesięcy to idealny czas na zabawy logiczne. Odkryj w Polecanych produktach układanki i klocki odpowiednie do wieku i rozwijaj jego bystrość.', title_pt = 'Brinquedos inteligentes 🧩', body_pt = 'Os 18 meses são a idade ideal para jogos de lógica. Descubra nos Produtos Recomendados puzzles e cubos adequados à idade e estimule a inteligência dele.', title_sv = 'Intellektuella leksaker 🧩', body_sv = '18 månader är en perfekt tid för logiklekar. Upptäck åldersanpassade pussel och klossar i Rekommenderade produkter och slipa barnets intelligens.', title_vi = 'Đồ chơi trí tuệ 🧩', body_vi = '18 tháng là thời điểm lý tưởng cho các trò chơi tư duy. Hãy khám phá những bộ xếp hình và khối gỗ phù hợp lứa tuổi trong Sản phẩm gợi ý để rèn luyện trí thông minh của bé.', title_zh = '益智玩具 🧩', body_zh = '18个月正是玩逻辑游戏的好时候。在推荐商品里发现适合年龄的拼图和积木，让他的头脑更灵活吧。' WHERE id = 'ffe1377d-426e-4c3f-a06d-3551b2ee446b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La alegría de la mesa familiar 🍲', body_es = '¡Ya puede comer contigo de todo! Elige una cena sana para compartir en Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Le bonheur du repas en famille 🍲', body_fr = 'Il peut désormais manger complètement avec vous ! Choisissez un dîner sain à partager dans les Recettes pour bébés qui commencent la diversification.', title_hi = 'परिवार की मेज़ की बरकत 🍲', body_hi = 'अब वह पूरी तरह आपके साथ खा सकता है! ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी से साझा और सेहतमंद रात का खाना चुनिए।', title_id = 'Berkahnya meja makan keluarga 🍲', body_id = 'Kini ia sudah bisa makan bersama Anda sepenuhnya! Pilih menu makan malam sehat untuk bersama dari Resep untuk bayi yang mulai MPASI.', title_ja = '家族の食卓のめぐみ 🍲', body_ja = 'もうすっかりあなたと一緒に食べられます！「離乳食を始める赤ちゃんのレシピ」から、家族で食べられるヘルシーな夕食を選びましょう。', title_ko = '풍성한 가족 식탁 🍲', body_ko = '이제 완전히 엄마와 함께 먹을 수 있어요! 이유식을 시작하는 아기를 위한 레시피에서 함께 먹을 건강한 저녁 메뉴를 골라 보세요.', title_nl = 'Samen aan de gezinstafel 🍲', body_nl = 'Je kindje kan nu helemaal met jullie mee-eten! Kies in Recepten voor baby''s die met bijvoeding beginnen een gezond avondeten voor het hele gezin.', title_pl = 'Dobrodziejstwo rodzinnego stołu 🍲', body_pl = 'Może już w pełni jeść razem z wami! Wybierz z Przepisów dla niemowląt rozpoczynających rozszerzanie diety wspólną, zdrową kolację.', title_pt = 'A abundância da mesa em família 🍲', body_pt = 'Já pode comer totalmente convosco! Escolha nas Receitas para bebés em diversificação alimentar um jantar saudável para partilharem.', title_sv = 'Välsignelsen vid familjebordet 🍲', body_sv = 'Nu kan barnet äta helt och hållet med er! Välj en gemensam och nyttig middag från Recept för bebisar som börjar med fast föda.', title_vi = 'Mâm cơm gia đình ấm no 🍲', body_vi = 'Giờ bé đã có thể ăn hoàn toàn cùng cả nhà! Hãy chọn một bữa tối chung lành mạnh từ mục Công thức cho bé bắt đầu ăn dặm.', title_zh = '全家餐桌的福气 🍲', body_zh = '他已经完全可以和你们一起吃饭了！从食谱板块的辅食宝宝食谱里选一道全家共享的健康晚餐吧。' WHERE id = '10d89b1a-052c-42d7-9604-a8aa080e3159' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión intestinal ⏱️', body_es = 'Anota en el Seguimiento de pañales los cambios del día y analiza fácilmente si toma suficiente líquido y fibra.', title_fr = 'Contrôle du transit ⏱️', body_fr = 'En notant les changements de la journée dans le Suivi des couches, analysez facilement s''il reçoit assez de liquides et de fibres.', title_hi = 'आँतों की जाँच ⏱️', body_hi = 'डायपर ट्रैकर में दिनभर के बदलाव दर्ज करके आसानी से विश्लेषण कीजिए कि उसे पर्याप्त तरल और फ़ाइबर मिल रहा है या नहीं।', title_id = 'Cek pencernaan ⏱️', body_id = 'Catat perubahan sepanjang hari di Pelacak Popok dan analisis dengan mudah apakah ia cukup mendapat cairan dan serat.', title_ja = 'おなかの調子チェック ⏱️', body_ja = '「おむつトラッカー」に一日の変化を記録すれば、水分と食物繊維が十分にとれているかかんたんに分析できます。', title_ko = '장 건강 체크 ⏱️', body_ko = '기저귀 기록에 하루 동안의 변화를 남기면 수분과 식이섬유를 충분히 섭취하는지 쉽게 분석할 수 있어요.', title_nl = 'Controle van de darmen ⏱️', body_nl = 'Noteer de verschoningen van de dag in de Luiertracker en analyseer zo makkelijk of je kindje genoeg vocht en vezels binnenkrijgt.', title_pl = 'Kontrola jelit ⏱️', body_pl = 'Zapisuj w narzędziu do śledzenia pieluszek zmiany w ciągu dnia i łatwo sprawdzaj, czy dostaje wystarczająco płynów i błonnika.', title_pt = 'Verificação do intestino ⏱️', body_pt = 'Registe no Registo de Fraldas as mudanças ao longo do dia e analise com facilidade se ele recebe líquidos e fibra suficientes.', title_sv = 'Tarmkontroll ⏱️', body_sv = 'Anteckna dagens förändringar i Blöjkollen och analysera enkelt om barnet får i sig tillräckligt med vätska och fibrer.', title_vi = 'Kiểm tra đường ruột ⏱️', body_vi = 'Hãy ghi lại những thay đổi trong ngày vào Theo dõi tã để dễ dàng phân tích bé có nạp đủ nước và chất xơ không.', title_zh = '肠道检查 ⏱️', body_zh = '在尿布记录里记下一天中的变化，轻松分析他是否摄入了足够的水分和膳食纤维。' WHERE id = '25077620-39e7-49c9-abd7-7ee3d4c9f4a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma del sonido de la lluvia 🌧️', body_es = 'Un día muy activo puede cansar su cerebro. Pon el sonido de la lluvia en Ruido blanco y crea en la habitación un fondo relajante perfecto para dormir.', title_fr = 'La sérénité du bruit de la pluie 🌧️', body_fr = 'Une journée active peut fatiguer le cerveau. Lancez le bruit de la pluie dans les Bruits blancs pour créer dans la chambre un fond apaisant parfait qui invite au sommeil.', title_hi = 'बारिश की आवाज़ का सुकून 🌧️', body_hi = 'भाग-दौड़ भरा दिन दिमाग को थका सकता है। व्हाइट नॉइज़ से बारिश की आवाज़ चलाकर कमरे में शांत, नींद लाने वाला परफ़ेक्ट बैकग्राउंड बनाइए।', title_id = 'Tenangnya suara hujan 🌧️', body_id = 'Hari yang aktif bisa membuat otaknya lelah. Putar suara hujan dari Suara Putih untuk menciptakan latar sempurna yang menenangkan dan mengundang kantuk di kamar.', title_ja = '雨の音の安らぎ 🌧️', body_ja = '活発な一日は脳を疲れさせることも。「ホワイトノイズ」から雨の音を流して、部屋に心落ち着く、眠りを誘う雰囲気をつくりましょう。', title_ko = '빗소리의 평온 🌧️', body_ko = '활발한 하루는 뇌를 지치게 할 수 있어요. 백색소음의 빗소리로 방에 잠을 부르는 차분하고 완벽한 배경을 만들어 주세요.', title_nl = 'De rust van regengeluid 🌧️', body_nl = 'Een drukke dag kan het hoofdje vermoeien. Zet in Witte ruis het geluid van regen aan en zorg voor een rustgevende achtergrond die slaap brengt.', title_pl = 'Spokój szumu deszczu 🌧️', body_pl = 'Aktywny dzień może zmęczyć umysł. Włącz w Białym szumie odgłos deszczu i stwórz w pokoju idealne, kojące tło do snu.', title_pt = 'A tranquilidade do som da chuva 🌧️', body_pt = 'Um dia ativo pode cansar o cérebro. Ligue o som da chuva no Ruído Branco e crie no quarto um fundo calmante perfeito, que traz o sono.', title_sv = 'Regnljudets ro 🌧️', body_sv = 'En aktiv dag kan trötta ut hjärnan. Sätt på regnljud i Vitt brus och skapa en perfekt lugnande bakgrund i rummet som gör barnet sömnigt.', title_vi = 'Sự bình yên của tiếng mưa 🌧️', body_vi = 'Một ngày hiếu động có thể khiến não bé mệt mỏi. Hãy bật tiếng mưa trong Tiếng ồn trắng để tạo nền âm thanh êm dịu, dễ ngủ hoàn hảo cho căn phòng.', title_zh = '雨声的宁静 🌧️', body_zh = '活跃的一天会让大脑疲惫。在白噪音里放雨声，为房间营造一个安神助眠的完美背景。' WHERE id = '94fb4891-ca2e-4e41-b663-ea23a832df89' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Tú puedes! 💖', body_es = 'Cuando te sientas cansada, abre el Diario de ánimo. Escribe simplemente «Puedo con todo» y descansa.', title_fr = 'Vous y arriverez ! 💖', body_fr = 'Quand vous vous sentez épuisée, ouvrez le Journal d''humeur. Écrivez simplement « Je m''en sors très bien » et reposez-vous.', title_hi = 'आप कर सकती हैं! 💖', body_hi = 'जब थकान महसूस हो, मूड डायरी खोलिए। उसमें बस इतना लिखिए ''मैं सब कुछ संभाल लेती हूँ'' और आराम कीजिए।', title_id = 'Anda pasti bisa! 💖', body_id = 'Saat merasa lelah, buka Buku Harian Suasana Hati. Cukup tulis "Aku bisa mengatasi semuanya" di sana, lalu beristirahatlah.', title_ja = 'あなたならできる！💖', body_ja = '疲れを感じたら「気分日記」を開きましょう。「私はなんでも乗りこえられる」とだけ書いて、ひと休みしてください。', title_ko = '당신은 할 수 있어요! 💖', body_ko = '지쳤다고 느껴지면 기분 일기를 여세요. 그저 ''나는 모든 걸 잘 해내고 있어''라고 적고 쉬세요.', title_nl = 'Je kunt het! 💖', body_nl = 'Voel je je moe? Open je Stemmingsdagboek. Schrijf er gewoon in: ik kan alles aan, en rust uit.', title_pl = 'Dasz radę! 💖', body_pl = 'Gdy czujesz zmęczenie, otwórz Dziennik nastroju. Napisz tam po prostu „Ze wszystkim sobie radzę” i odpocznij.', title_pt = 'Consegue! 💖', body_pt = 'Quando se sentir cansada, abra o Diário de Humor. Escreva lá simplesmente "Eu consigo dar conta de tudo" e descanse.', title_sv = 'Du klarar det! 💖', body_sv = 'Öppna Humördagboken när du känner dig trött. Skriv bara ”Jag klarar allt” där och vila.', title_vi = 'Mẹ làm được mà! 💖', body_vi = 'Khi cảm thấy mệt mỏi, hãy mở Nhật ký tâm trạng. Chỉ cần viết vào đó "Mình làm được mọi thứ" và nghỉ ngơi nhé.', title_zh = '你一定可以！💖', body_zh = '觉得累的时候，打开心情日记。只写一句“我能搞定一切”，然后休息吧。' WHERE id = '02d8aef9-6d63-4748-9f41-c063ee842eb2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exploración en la naturaleza 🌳', body_es = '¿Se le queda pequeña la casa? Encuentra en Lugares para mamás un parque amplio y seguro y ayúdale a gastar energía.', title_fr = 'Exploration de la nature 🌳', body_fr = 'Les murs de la maison sont trop étroits pour lui ? Trouvez dans les Lieux adaptés aux mamans un parc grand et sûr pour l''aider à se défouler.', title_hi = 'प्रकृति की खोज 🌳', body_hi = 'घर की दीवारें उसे तंग लगती हैं? माँ के लिए अनुकूल जगहों में कोई बड़ा और सुरक्षित पार्क ढूँढिए और उसकी ऊर्जा निकालने में मदद कीजिए।', title_id = 'Menjelajahi alam 🌳', body_id = 'Dinding rumah terasa terlalu sempit baginya? Temukan taman yang luas dan aman di Tempat Ramah Ibu dan bantu ia menyalurkan energinya.', title_ja = '自然を探検 🌳', body_ja = '家の壁が窮屈に感じられる？「ママにやさしいスポット」で広くて安全な公園を見つけて、エネルギーを発散させてあげましょう。', title_ko = '자연 탐험 🌳', body_ko = '집 안이 아이에게 너무 좁게 느껴지나요? 엄마 친화 장소에서 넓고 안전한 공원을 찾아 에너지를 발산하게 도와주세요.', title_nl = 'Ontdekkingstocht in de natuur 🌳', body_nl = 'Worden de muren thuis te krap voor je kindje? Zoek in Mamavriendelijke plekken een ruim en veilig park en help hem zijn energie kwijt te raken.', title_pl = 'Odkrywanie natury 🌳', body_pl = 'W domu robi mu się za ciasno? Znajdź w Miejscach przyjaznych mamom duży, bezpieczny park i pomóż mu wyładować energię.', title_pt = 'Explorar a natureza 🌳', body_pt = 'As paredes de casa ficam-lhe apertadas? Encontre nos Locais Amigos das Mães um parque amplo e seguro e ajude-o a gastar energia.', title_sv = 'Upptäcktsfärd i naturen 🌳', body_sv = 'Känns hemmets väggar trånga för barnet? Hitta en stor och säker park i Mammavänliga platser och hjälp barnet att få ut sin energi.', title_vi = 'Khám phá thiên nhiên 🌳', body_vi = 'Những bức tường trong nhà đã quá chật với bé? Hãy tìm một công viên rộng rãi, an toàn trong Địa điểm thân thiện với mẹ để giúp bé xả năng lượng.', title_zh = '大自然探险 🌳', body_zh = '家里的墙壁关不住他了？在妈妈友好场所里找一个宽敞安全的公园，帮他释放精力吧。' WHERE id = '04fca8dd-97bb-4af2-93b5-030f318cd3da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Temporizador de comidas ⏱️', body_es = '¿Juega mucho con la comida? Activa el temporizador de tomas y analiza si el tiempo que pasa en la mesa es el adecuado y cómo va su apetito.', title_fr = 'Le minuteur des repas ⏱️', body_fr = 'Il joue beaucoup avec la nourriture ? Lancez le minuteur des repas et analysez si le temps passé à table est normal ainsi que son appétit.', title_hi = 'खाने का टाइमर ⏱️', body_hi = 'खाने से बहुत खेलता है? फ़ीडिंग टाइमर चालू कीजिए और देखिए कि मेज़ पर बिताया समय मानक के अनुसार है या नहीं, और उसकी भूख कैसी है।', title_id = 'Timer makan ⏱️', body_id = 'Ia terlalu banyak bermain dengan makanannya? Nyalakan Timer Makan, analisis apakah waktu di meja makan sudah wajar, dan perhatikan nafsu makannya.', title_ja = '食事タイマー ⏱️', body_ja = '食べ物で遊んでばかり？食事タイマーをオンにして、食卓にいる時間が目安どおりか、食欲の様子を分析しましょう。', title_ko = '식사 타이머 ⏱️', body_ko = '음식으로 너무 오래 노나요? 수유 타이머를 켜고 식탁에서 보내는 시간이 적당한지, 입맛은 어떤지 분석해 보세요.', title_nl = 'Eettimer ⏱️', body_nl = 'Speelt je kindje veel met zijn eten? Zet de voedingstimer aan en analyseer of de tijd aan tafel normaal is en hoe zijn eetlust is.', title_pl = 'Timer posiłku ⏱️', body_pl = 'Bardziej bawi się jedzeniem, niż je? Włącz timer karmienia i sprawdź, czy czas przy stole i apetyt mieszczą się w normie.', title_pt = 'Temporizador das refeições ⏱️', body_pt = 'Brinca muito com a comida? Ligue o temporizador de alimentação e analise se o tempo passado à mesa está dentro do normal, bem como o apetite.', title_sv = 'Måltidstimer ⏱️', body_sv = 'Leker barnet mycket med maten? Starta matningstimern och analysera om tiden vid bordet följer normen och hur aptiten är.', title_vi = 'Hẹn giờ bữa ăn ⏱️', body_vi = 'Bé nghịch đồ ăn nhiều quá? Hãy bật bộ hẹn giờ trong Theo dõi cữ bú để phân tích thời gian ngồi ăn có hợp lý không và tình trạng ăn uống của bé.', title_zh = '吃饭计时器 ⏱️', body_zh = '总是玩食物？打开喂养计时器，分析餐桌上的时间是否合适，以及他的食欲。' WHERE id = '7306940e-101e-4de4-af72-da4ab6736ad8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de lógica 🧱', body_es = '¿Construye una torre apilando 4-5 cubos? ¡Registra este logro motor en el Seguimiento del desarrollo! No olvides aplaudir sus intentos de pequeño ingeniero.', title_fr = 'Jeux de logique 🧱', body_fr = 'Il empile 4-5 cubes pour construire une tour ? Notez cette victoire motrice dans le Suivi de développement ! N''oubliez pas d''applaudir ses petits essais d''ingénieur.', title_hi = 'तर्क वाले खेल 🧱', body_hi = '4-5 ब्लॉक एक के ऊपर एक रखकर मीनार बनाता है? ग्रोथ ट्रैकर में इस मोटर जीत को दर्ज कीजिए! उसकी छोटी इंजीनियरिंग कोशिशों पर ताली बजाना मत भूलिए।', title_id = 'Permainan logika 🧱', body_id = 'Ia menumpuk 4-5 balok untuk membangun menara? Catat kemenangan motorik ini di Pelacak Perkembangan! Jangan lupa bertepuk tangan untuk usaha kecilnya sebagai insinyur.', title_ja = '考える力を育てる遊び 🧱', body_ja = '積み木を4-5個重ねてタワーをつくっていますか？「発達トラッカー」にこの運動の成果を記録しましょう！小さなエンジニアの挑戦に拍手を忘れずに。', title_ko = '논리 놀이 🧱', body_ko = '블록 4-5개를 쌓아 탑을 만드나요? 성장 기록에 이 운동 발달의 승리를 남기세요! 꼬마 엔지니어의 도전에 박수 치는 것도 잊지 마세요.', title_nl = 'Denkspelletjes 🧱', body_nl = 'Zet je kindje 4-5 blokken op elkaar en bouwt hij een toren? Noteer deze motorische overwinning in de Groeitracker! Vergeet niet te applaudisseren voor zijn kleine bouwpogingen.', title_pl = 'Zabawy logiczne 🧱', body_pl = 'Ustawia 4-5 kostek jedna na drugiej i buduje wieżę? Zapisz ten sukces motoryczny w Śledzeniu rozwoju! Nie zapomnij nagradzać brawami jego małych inżynierskich prób.', title_pt = 'Jogos de lógica 🧱', body_pt = 'Empilha 4-5 cubos e constrói uma torre? Registe esta vitória motora no Registo de Desenvolvimento! Não se esqueça de aplaudir estas pequenas tentativas de engenharia.', title_sv = 'Logiklekar 🧱', body_sv = 'Staplar barnet 4-5 klossar och bygger ett torn? Anteckna denna motoriska seger i Utvecklingsspåraren! Glöm inte att applådera de små ingenjörsförsöken.', title_vi = 'Trò chơi tư duy 🧱', body_vi = 'Bé chồng 4-5 khối lên nhau thành tòa tháp? Hãy ghi lại chiến thắng vận động này trong Theo dõi phát triển! Đừng quên vỗ tay khen những nỗ lực "kỹ sư" nhỏ của bé.', title_zh = '逻辑游戏 🧱', body_zh = '他能把4-5块积木摞成一座塔了？在发育追踪里记下这个动作上的胜利！别忘了为这位小工程师的尝试鼓掌。' WHERE id = '07b5d33a-c674-4dcc-a023-81e3746cb054' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No cargues tú sola con los despertares nocturnos. Despierta también a tu pareja: ser un equipo es repartir la responsabilidad. Esta noche le toca a tu pareja calmarle.', body_fr = 'N''affrontez pas seule les réveils nocturnes. Réveillez aussi votre conjoint : être une équipe, c''est partager les responsabilités. Ce soir, c''est à lui de le calmer.', body_hi = 'रात में जागने का बोझ पूरी तरह अकेले मत उठाइए। अपने साथी को भी जगाइए, टीम होने का मतलब है ज़िम्मेदारी बराबर बाँटना। आज रात शांत कराने की बारी उनकी है।', body_id = 'Jangan tanggung sendiri saat ia terbangun malam. Bangunkan juga pasangan Anda, menjadi tim berarti berbagi tanggung jawab secara adil. Malam ini, gilirannya menenangkan si kecil.', body_ja = '夜中に起きるのを、ひとりで抱えこまないで。パートナーも起こしましょう。チームとは責任を平等に分けることです。今夜の寝かしつけはパートナーの番です。', body_ko = '밤에 깨는 일을 혼자 다 감당하지 마세요. 배우자도 깨우세요. 한 팀이 된다는 건 책임을 똑같이 나누는 거예요. 오늘 밤 달래기는 아빠 몫이에요.', body_nl = 'Draag het ''s nachts opstaan niet helemaal alleen. Maak ook je partner wakker: een team zijn betekent de verantwoordelijkheid eerlijk delen. Vannacht mag hij troosten.', body_pl = 'Nie bierz nocnych pobudek całkiem na siebie. Obudź też partnera, bycie zespołem to równy podział obowiązków. Tej nocy uspokajanie należy do niego.', body_pt = 'Não aguente sozinha os despertares noturnos. Acorde também o seu companheiro: ser uma equipa é dividir a responsabilidade por igual. Esta noite, acalmá-lo fica por conta dele.', body_sv = 'Ta inte de nattliga uppvaknandena helt själv. Väck din partner också, att vara ett team betyder att dela ansvaret lika. I natt är det partnerns tur att trösta.', body_vi = 'Đừng gánh hết việc thức dậy ban đêm một mình. Hãy đánh thức cả bố nữa, là một đội nghĩa là chia đều trách nhiệm. Tối nay đến lượt bố dỗ bé.', body_zh = '别一个人扛下所有夜醒。也叫醒另一半吧，团队就是平分责任。今晚轮到他来哄了。' WHERE id = 'be5acfb3-03f0-4bea-9e14-40b38bca8262' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Quieres salir, pero el tiempo está cambiante. Deja que Tiempo y ropa te diga no solo la temperatura, sino también qué ponerle para que no le pase el viento.', body_fr = 'Vous voulez sortir, mais le temps est changeant ? Laissez l''assistant Météo et tenue vous indiquer non seulement la température, mais aussi quelle tenue coupe-vent lui mettre.', body_hi = 'बाहर जाना चाहती हैं, लेकिन मौसम बदल रहा है? मौसम और कपड़े टूल सिर्फ़ तापमान ही नहीं, यह भी बताएगा कि हवा से बचाने के लिए क्या पहनाएँ।', body_id = 'Ingin keluar rumah, tapi cuacanya berubah-ubah? Biarkan asisten Cuaca dan Pakaian memberi tahu tidak hanya suhunya, tapi juga pakaian tahan angin yang perlu dipakai si kecil.', body_ja = 'お出かけしたいけれど、天気が変わりやすい？「天気と服装」アシスタントが、気温だけでなく、風を通さない服装まで教えてくれます。', body_ko = '밖에 나가고 싶은데 날씨가 변덕스러운가요? 날씨와 옷차림 도우미가 기온뿐 아니라 바람을 막아 줄 옷차림까지 알려 줄 거예요.', body_nl = 'Wil je naar buiten, maar is het weer wisselvallig? Laat de assistent Weer en kleding je niet alleen de temperatuur vertellen, maar ook welke winddichte kleding je kindje aan moet.', body_pl = 'Chcesz wyjść, ale pogoda jest zmienna? Pomocnik Pogoda i ubiór poda ci nie tylko temperaturę, ale też podpowie, w co go ubrać, by nie przewiało go wiatr.', body_pt = 'Quer sair, mas o tempo está instável? Deixe que o assistente Tempo e Roupa lhe diga não só a temperatura, mas também que roupa corta-vento lhe deve vestir.', body_sv = 'Vill du gå ut, men vädret är ombytligt? Låt assistenten Väder och kläder berätta inte bara temperaturen, utan också vilka vindtäta kläder barnet ska ha på sig.', body_vi = 'Mẹ muốn ra ngoài nhưng thời tiết thất thường. Hãy để Trợ lý thời tiết và trang phục cho mẹ biết không chỉ nhiệt độ mà cả nên mặc cho bé đồ gì để chắn gió.', body_zh = '想出门，可天气变化多端。让天气穿衣助手不只告诉你温度，还告诉你该给他穿什么才能防风。' WHERE id = 'fa9c7680-afc6-4095-9ec3-d56ad432d989' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Limpieza de la mañana 💧', body_es = '¿Has cambiado el primer pañal del día? Anota los datos de la caca en la app y sigue fácilmente si toma suficiente líquido.', title_fr = 'Le change du matin 💧', body_fr = 'Vous avez changé la première couche de la journée ? Notez les selles dans l''application et vérifiez facilement s''il boit suffisamment.', title_hi = 'सुबह की सफ़ाई 💧', body_hi = 'दिन का पहला डायपर बदल दिया? पॉटी की जानकारी ऐप में दर्ज कीजिए और आसानी से देखिए कि उसे पर्याप्त तरल मिल रहा है या नहीं।', title_id = 'Bersih-bersih pagi 💧', body_id = 'Sudah mengganti popok pertama hari ini? Catat data BAB-nya di aplikasi dan pantau dengan mudah apakah asupan cairannya cukup.', title_ja = '朝のすっきりチェック 💧', body_ja = '今日最初のおむつ替えはすみましたか？うんちの情報をアプリに記録して、水分が十分にとれているかかんたんに見守りましょう。', title_ko = '아침 정리 💧', body_ko = '오늘 첫 기저귀를 갈았나요? 배변 정보를 앱에 기록하고 수분 섭취가 충분한지 쉽게 살펴보세요.', title_nl = 'Ochtendverschoning 💧', body_nl = 'Heb je de eerste luier van de dag verschoond? Noteer de gegevens over de ontlasting in de app en volg makkelijk of hij genoeg vocht binnenkrijgt.', title_pl = 'Poranne porządki 💧', body_pl = 'Przewinęłaś pierwszą pieluszkę dnia? Zapisz informacje o wypróżnieniu w aplikacji i łatwo sprawdzaj, czy pije wystarczająco płynów.', title_pt = 'A limpeza da manhã 💧', body_pt = 'Já mudou a primeira fralda do dia? Registe na app as informações das fezes e acompanhe com facilidade se a ingestão de líquidos é suficiente.', title_sv = 'Morgonens fräschör 💧', body_sv = 'Har du bytt dagens första blöja? Anteckna informationen om bajset i appen och följ enkelt om vätskeintaget är tillräckligt.', title_vi = 'Vệ sinh buổi sáng 💧', body_vi = 'Mẹ vừa thay chiếc tã đầu tiên trong ngày? Hãy ghi thông tin về phân vào ứng dụng để dễ dàng theo dõi bé có nạp đủ nước không.', title_zh = '早晨的清洁 💧', body_zh = '换了今天的第一片尿布？把便便情况记到应用里，轻松关注他的水分摄入是否足够。' WHERE id = '22efa7bf-186e-41c7-b46c-b75ce17b0a09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis con el menú 🥣', body_es = '¿Rechaza la comida? En lugar de obligarle, pon en su plato verduras de distintos colores para despertar su interés. Busca ideas nuevas en Recetas saludables.', title_fr = 'Les crises du menu 🥣', body_fr = 'Il refuse de manger ? Au lieu de le forcer, éveillez sa curiosité en mettant des légumes de différentes couleurs dans son assiette. Trouvez de nouvelles idées dans les Recettes saines.', title_hi = 'मेन्यू के नखरे 🥣', body_hi = 'खाना मना करता है? ज़बरदस्ती खिलाने के बजाय उसकी प्लेट में अलग-अलग रंगों की सब्ज़ियाँ रखकर उसकी दिलचस्पी जगाइए। सेहतमंद रेसिपी से नए आइडिया लीजिए।', title_id = 'Krisis menu 🥣', body_id = 'Ia menolak makan? Daripada memaksa, tarik minatnya dengan menata sayuran berbagai warna di piringnya. Dapatkan ide baru dari Resep Sehat.', title_ja = '食事のかんしゃく 🥣', body_ja = '食べるのを嫌がる？無理に食べさせるかわりに、いろいろな色の野菜をお皿にのせて興味を引きましょう。「ヘルシーレシピ」で新しいアイデアを見つけて。', title_ko = '메뉴 위기 🥣', body_ko = '밥을 거부하나요? 억지로 먹이는 대신 접시에 여러 색의 채소를 담아 관심을 끌어 보세요. 건강한 레시피에서 새로운 아이디어를 얻으세요.', title_nl = 'Crisis aan tafel 🥣', body_nl = 'Weigert je kindje te eten? Dwing hem niet, maar maak hem nieuwsgierig met groenten in verschillende kleuren op zijn bord. Haal nieuwe ideeën uit Gezonde recepten.', title_pl = 'Kryzysy przy jedzeniu 🥣', body_pl = 'Odmawia jedzenia? Zamiast karmić na siłę, połóż mu na talerzu kolorowe warzywa i wzbudź jego ciekawość. Poszukaj nowych pomysłów w zdrowych przepisach.', title_pt = 'Crises à mesa 🥣', body_pt = 'Recusa-se a comer? Em vez de o obrigar, desperte-lhe o interesse com legumes de cores diferentes no prato. Encontre novas ideias nas Receitas Saudáveis.', title_sv = 'Menykriser 🥣', body_sv = 'Vägrar barnet äta? I stället för att tvinga, väck intresset genom att lägga grönsaker i olika färger på tallriken. Hämta nya idéer i Hälsosamma recept.', title_vi = 'Khủng hoảng thực đơn 🥣', body_vi = 'Bé không chịu ăn? Thay vì ép, hãy bày rau củ nhiều màu sắc lên đĩa để thu hút bé. Tìm ý tưởng mới trong Công thức lành mạnh nhé.', title_zh = '菜单危机 🥣', body_zh = '不肯吃饭？与其强迫，不如在盘子里放些不同颜色的蔬菜吸引他的兴趣。去健康食谱里找新点子吧。' WHERE id = '37e7b0b1-141f-488d-99c8-a87bde73955f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Mientras le preparas para dormir, controla el nivel de ruido de la habitación con el Medidor de sonido. Un sueño interrumpido por la noche perjudica su desarrollo y tu humor por la mañana.', body_fr = 'Pendant la préparation au coucher, surveillez le niveau sonore de la chambre avec le Sonomètre. Un sommeil interrompu la nuit nuit à son développement comme à votre humeur du matin.', body_hi = 'सोने की तैयारी के समय साउंड मीटर से कमरे की आवाज़ का स्तर नियंत्रित रखिए। रात में टूटी नींद उसके विकास और आपके सुबह के मूड, दोनों को बिगाड़ती है।', body_id = 'Saat bersiap tidur, jaga tingkat suara di kamar dengan Pengukur Suara. Tidur yang terputus di malam hari mengganggu perkembangannya dan juga suasana hati Anda di pagi hari.', body_ja = '寝る準備をするときは、「サウンドメーター」で部屋の音の大きさを見守りましょう。夜中に途切れる眠りは、お子さんの発達にも、あなたの翌朝の気分にも影響します。', body_ko = '잠들 준비를 할 때는 소음 측정기로 방의 소리 크기를 관리하세요. 밤에 깨는 잠은 아이의 발달도, 엄마의 아침 기분도 망쳐요.', body_nl = 'Bewaak bij het slapengaan het geluidsniveau in de kamer met de Geluidsmeter. Onderbroken nachtrust is slecht voor zijn ontwikkeling en voor jouw humeur de volgende ochtend.', body_pl = 'Szykując go do snu, pilnuj poziomu hałasu w pokoju Miernikiem dźwięku. Przerywany sen w nocy psuje i jego rozwój, i twój poranny nastrój.', body_pt = 'Enquanto o prepara para dormir, controle o nível de som do quarto com o Medidor de Som. Um sono interrompido à noite prejudica o desenvolvimento dele e também o seu humor de manhã.', body_sv = 'Skydda ljudnivån i rummet med Ljudmätaren när barnet ska sova. Avbruten nattsömn förstör både barnets utveckling och ditt humör på morgonen.', body_vi = 'Khi chuẩn bị cho bé ngủ, hãy giữ yên tĩnh cho căn phòng bằng Đo âm thanh. Giấc ngủ đêm bị gián đoạn ảnh hưởng cả sự phát triển của bé lẫn tâm trạng buổi sáng của mẹ.', body_zh = '准备睡觉时，用噪音测量守护房间的音量。夜里睡眠被打断，既影响他的发育，也影响你早上的心情。' WHERE id = '5ae1647c-ec81-4db7-838c-66f57619dd06' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué hace esto? 🤖', body_es = '¿Han empezado las rabietas sin motivo? Consulta ya con Anacan AI y aprende enfoques psicológicos de expertos.', title_fr = 'Pourquoi fait-il ça ? 🤖', body_fr = 'Les crises de colère sans raison ont commencé ? Demandez tout de suite conseil à Anacan AI pour découvrir les approches psychologiques des experts.', title_hi = 'ऐसा क्यों करता है? 🤖', body_hi = 'बिना वजह गुस्से के दौरे (टैंट्रम) शुरू हो गए? तुरंत Anacan AI से सलाह लीजिए और विशेषज्ञों के मनोवैज्ञानिक तरीके जानिए।', title_id = 'Kenapa ia begitu? 🤖', body_id = 'Mulai muncul ledakan amarah (tantrum) tanpa sebab? Segera konsultasikan dengan Anacan AI dan pelajari pendekatan psikologis dari para ahli.', title_ja = 'どうしてこうなるの？🤖', body_ja = '理由のわからないかんしゃくが始まりましたか？すぐにAnacan AIに相談して、専門家の心理的な接し方を学びましょう。', title_ko = '왜 이러는 걸까요? 🤖', body_ko = '이유 없는 분노 발작(떼쓰기)이 시작됐나요? 바로 Anacan AI와 상담해 전문가의 심리적 접근법을 알아보세요.', title_nl = 'Waarom doet hij zo? 🤖', body_nl = 'Zijn er driftbuien zonder reden begonnen? Overleg meteen met Anacan AI en leer de psychologische aanpak van deskundigen.', title_pl = 'Dlaczego tak robi? 🤖', body_pl = 'Zaczęły się napady złości bez powodu? Od razu poradź się Anacan AI i poznaj eksperckie podejście psychologiczne.', title_pt = 'Porque faz isto? 🤖', body_pt = 'Começaram as crises de raiva sem motivo (birras)? Fale já com o Anacan AI e conheça as abordagens psicológicas dos especialistas.', title_sv = 'Varför gör barnet så här? 🤖', body_sv = 'Har oförklarliga ilskeutbrott (tantrum) börjat? Rådfråga Anacan AI direkt och lär dig psykologiska förhållningssätt från experter.', title_vi = 'Sao bé lại như vậy? 🤖', body_vi = 'Những cơn giận dữ vô cớ đã bắt đầu? Hãy hỏi ý kiến Anacan AI ngay để biết những cách ứng xử tâm lý theo chuyên gia.', title_zh = '他为什么会这样？🤖', body_zh = '开始无缘无故地发脾气了？马上咨询Anacan AI，学习专家的心理应对方法。' WHERE id = '82b5cb21-ea7e-4957-9166-81471c0b098a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía sin azúcar 🍌', body_es = '¿Por la tarde pide dulces? Cuida su alimentación con tentempiés sanos de plátano y avena de Recetas para bebé.', title_fr = 'De l''énergie sans sucre 🍌', body_fr = 'Il réclame une douceur l''après-midi ? Gardez un bon équilibre alimentaire avec des en-cas sains à la banane et aux flocons d''avoine des Recettes pour bébés.', title_hi = 'बिना चीनी की ऊर्जा 🍌', body_hi = 'दोपहर में मीठा माँगता है? बच्चों की रेसिपी में केले और ओट्स वाले सेहतमंद स्नैक्स से पोषण का मानक बनाए रखिए।', title_id = 'Energi tanpa gula 🍌', body_id = 'Ia ingin camilan manis di siang hari? Jaga porsi makannya dengan camilan sehat dari pisang dan oat di Resep Bayi.', title_ja = '砂糖なしでエネルギー 🍌', body_ja = '午後に甘いものをほしがる？ベビーレシピのバナナとオートミールのヘルシーなおやつで、栄養バランスを守りましょう。', title_ko = '설탕 없는 에너지 🍌', body_ko = '오후에 단 걸 찾나요? 아기 레시피의 바나나와 오트밀로 만든 건강한 간식으로 식사량을 지켜 주세요.', title_nl = 'Energie zonder suiker 🍌', body_nl = 'Wil je kindje ''s middags iets zoets? Houd de voedingsnorm in de gaten met gezonde tussendoortjes met banaan en havermout uit de babyrecepten.', title_pl = 'Energia bez cukru 🍌', body_pl = 'Po południu ma ochotę na słodycze? Trzymaj się normy żywienia dzięki zdrowym przekąskom z bananem i płatkami owsianymi z Przepisów dla maluszka.', title_pt = 'Energia sem açúcar 🍌', body_pt = 'À tarde pede doces? Mantenha a alimentação equilibrada com lanches saudáveis de banana e aveia das Receitas para bebés.', title_sv = 'Sockerfri energi 🍌', body_sv = 'Vill barnet ha något sött på eftermiddagen? Håll matnormen med nyttiga mellanmål med banan och havre i Babyrecept.', title_vi = 'Năng lượng không đường 🍌', body_vi = 'Buổi chiều bé đòi đồ ngọt? Hãy giữ đúng định mức dinh dưỡng với những món ăn nhẹ lành mạnh từ chuối và yến mạch trong Công thức cho bé.', title_zh = '无糖能量 🍌', body_zh = '下午想吃甜的？用宝宝食谱里的香蕉燕麦健康小食，守住喂养参考量吧。' WHERE id = '8aa141ab-420e-4a45-9eba-7dddd2430cb1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Depósito de calcio 🧀', body_es = 'El calcio es imprescindible para los dientes y los huesos. Comprueba con el Seguimiento de tomas si hoy ha tomado la cantidad adecuada de lácteos.', title_fr = 'Une réserve de calcium 🧀', body_fr = 'Le calcium est indispensable aux dents et aux os. Vérifiez avec le Suivi des repas qu''il a eu sa ration de produits laitiers aujourd''hui.', title_hi = 'कैल्शियम का खज़ाना 🧀', body_hi = 'दाँतों और हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से जाँचिए कि आज डेयरी प्रोडक्ट का मानक पूरा हुआ या नहीं।', title_id = 'Gudang kalsium 🧀', body_id = 'Kalsium itu wajib untuk gigi dan tulang. Periksa dengan alat Pemantau Makan apakah porsi produk susu hari ini sudah terpenuhi.', title_ja = 'カルシウムをたっぷり 🧀', body_ja = '歯と骨のためにカルシウムは欠かせません。「栄養管理ツール」で、今日の乳製品の目安を守れているか確認しましょう。', title_ko = '칼슘 창고 🧀', body_ko = '치아와 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 유제품 섭취량을 잘 채웠는지 확인하세요.', title_nl = 'Een voorraad calcium 🧀', body_nl = 'Calcium is onmisbaar voor tanden en botten. Controleer met de Voedingstracker of je de norm voor zuivel van vandaag haalt.', title_pl = 'Skarbnica wapnia 🧀', body_pl = 'Wapń jest niezbędny dla zębów i kości. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza norma nabiału jest osiągnięta.', title_pt = 'Uma reserva de cálcio 🧀', body_pt = 'O cálcio é essencial para os dentes e os ossos. Confirme com o Registo de Alimentação se hoje cumpriu a quantidade recomendada de laticínios.', title_sv = 'Kalciumförråd 🧀', body_sv = 'Kalcium är en förutsättning för tänderna och skelettet. Kolla med Matningskoll att dagens norm för mejeriprodukter nås.', title_vi = 'Kho canxi 🧀', body_vi = 'Canxi là điều kiện cần cho răng và xương. Hãy kiểm tra bằng công cụ Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức sản phẩm từ sữa chưa.', title_zh = '钙质补给站 🧀', body_zh = '钙对牙齿和骨骼必不可少。用喂养记录工具看看今天的奶制品是否达到了参考量。' WHERE id = '2d802010-e9c4-4370-b595-862f19214f3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El momento más tierno del día 🖼️', body_es = '¿Recuerdas eso que hizo hoy y que más te hizo reír? Súbelo ya al Álbum del bebé y guárdalo para el futuro.', title_fr = 'Le plus doux moment du jour 🖼️', body_fr = 'Vous vous souvenez de ce qu''il a fait aujourd''hui qui vous a le plus fait rire ? Ajoutez-le tout de suite à l''Album de bébé pour le garder pour plus tard.', title_hi = 'दिन का सबसे प्यारा पल 🖼️', body_hi = 'आज की वह हरकत याद है जिसने आपको सबसे ज़्यादा हँसाया? उसे तुरंत बेबी एल्बम में अपलोड करके भविष्य के लिए सहेज लीजिए।', title_id = 'Momen termanis hari ini 🖼️', body_id = 'Ingat tingkah yang paling membuat Anda tertawa hari ini? Segera unggah ke Album Bayi dan simpan untuk masa depan.', title_ja = '今日いちばんかわいい瞬間 🖼️', body_ja = '今日いちばん笑ったしぐさを覚えていますか？すぐに「ベビーアルバム」にアップして、未来のために残しておきましょう。', title_ko = '오늘의 가장 귀여운 순간 🖼️', body_ko = '오늘 가장 많이 웃게 한 그 행동이 기억나나요? 바로 아기 앨범에 올려 훗날을 위해 간직하세요.', title_nl = 'Het liefste moment van de dag 🖼️', body_nl = 'Weet je nog waar je vandaag het hardst om moest lachen? Zet het meteen in het Babyalbum en bewaar het voor later.', title_pl = 'Najsłodsza chwila dnia 🖼️', body_pl = 'Pamiętasz to, co dziś najbardziej cię rozśmieszyło? Od razu dodaj to do Albumu dziecka i zachowaj na przyszłość.', title_pt = 'O momento mais doce do dia 🖼️', body_pt = 'Lembra-se daquele gesto que hoje mais a fez rir? Carregue-o já no Álbum do Bebé e guarde-o para o futuro.', title_sv = 'Dagens sötaste stund 🖼️', body_sv = 'Minns du det som fick dig att skratta mest i dag? Ladda direkt upp det i Babyalbumet och spara det för framtiden.', title_vi = 'Khoảnh khắc đáng yêu nhất trong ngày 🖼️', body_vi = 'Mẹ còn nhớ hành động khiến mẹ cười nhiều nhất hôm nay không? Hãy tải ngay lên Album của bé để lưu giữ cho mai sau.', title_zh = '今天最甜的瞬间 🖼️', body_zh = '还记得今天最让你发笑的那个动作吗？马上上传到宝宝相册，留给将来吧。' WHERE id = '739069ab-a4c7-4cc9-ae84-572e67836bd2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desarrollo intelectual 🧠', body_es = 'No te pierdas el nuevo artículo del Blog sobre los increíbles procesos que ocurren en el cerebro de los niños de año y medio.', title_fr = 'Le développement de l''intelligence 🧠', body_fr = 'Lisez absolument dans les Blogs notre nouvel article sur les processus incroyables qui se déroulent dans le cerveau des enfants de 1 an et demi.', title_hi = 'दिमागी विकास 🧠', body_hi = 'ब्लॉग सेक्शन में 1.5 साल के बच्चों के दिमाग में चल रही अद्भुत प्रक्रियाओं पर नया लेख ज़रूर पढ़िए।', title_id = 'Perkembangan kecerdasan 🧠', body_id = 'Pastikan membaca artikel baru di bagian Blog tentang proses luar biasa yang terjadi di otak anak usia 1,5 tahun.', title_ja = '知能の発達 🧠', body_ja = 'ブログで、1歳半の子の脳で起きている驚くべき変化についての新しい記事を、ぜひ読んでみてください。', title_ko = '두뇌 발달 🧠', body_ko = '블로그 섹션에서 1살 반 아이의 뇌에서 일어나는 놀라운 과정에 관한 새 글을 꼭 읽어 보세요.', title_nl = 'Ontwikkeling van het verstand 🧠', body_nl = 'Lees zeker het nieuwe artikel in het onderdeel Blogs over de ongelofelijke processen in het hoofdje van kinderen van 1,5 jaar.', title_pl = 'Rozwój umysłu 🧠', body_pl = 'Koniecznie przeczytaj w sekcji Blogi nowy artykuł o niesamowitych procesach zachodzących w mózgu półtorarocznych dzieci.', title_pt = 'O desenvolvimento da inteligência 🧠', body_pt = 'Não deixe de ler na secção Blogues o novo artigo sobre os processos incríveis que acontecem no cérebro das crianças de 1 ano e meio.', title_sv = 'Intelligensens utveckling 🧠', body_sv = 'Läs den nya artikeln i avsnittet Bloggar om de otroliga processerna i hjärnan hos barn på 1,5 år.', title_vi = 'Phát triển trí tuệ 🧠', body_vi = 'Mẹ nhớ đọc bài viết mới trong mục Blog về những quá trình kỳ diệu diễn ra trong não của trẻ 1,5 tuổi nhé.', title_zh = '智力发展 🧠', body_zh = '一定要读读博客板块里的新文章，了解1岁半孩子大脑里正在发生的神奇过程。' WHERE id = 'faac9718-e68e-455d-90e4-e34b7b38a24e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El equilibrio de la mañana 🧻', body_es = '¿Has anotado en la app el primer pañal del día? El color y la consistencia de la caca muestran con precisión si toma suficiente líquido.', title_fr = 'L''équilibre du matin 🧻', body_fr = 'Avez-vous noté la première couche de la journée dans l''application ? La couleur et la consistance des selles montrent précisément s''il boit suffisamment.', title_hi = 'सुबह का संतुलन 🧻', body_hi = 'क्या आपने दिन का पहला डायपर ऐप में दर्ज किया? पॉटी का रंग और गाढ़ापन ठीक-ठीक बताते हैं कि बच्चे को पर्याप्त तरल मिल रहा है या नहीं।', title_id = 'Keseimbangan pagi 🧻', body_id = 'Sudah mencatat popok pertama hari ini di aplikasi? Warna dan kepadatan BAB menunjukkan dengan tepat apakah ia cukup mendapat cairan.', title_ja = '朝のバランス 🧻', body_ja = '今日最初のおむつをアプリに記録しましたか？うんちの色やかたさで、水分が十分にとれているかがはっきりわかります。', title_ko = '아침 균형 🧻', body_ko = '오늘 첫 기저귀를 앱에 기록했나요? 변의 색과 굳기는 아이가 수분을 충분히 섭취하는지 정확히 알려 줘요.', title_nl = 'Balans in de ochtend 🧻', body_nl = 'Heb je de eerste luier van de dag in de app genoteerd? De kleur en dikte van de ontlasting laten precies zien of je kindje genoeg vocht krijgt.', title_pl = 'Poranny bilans 🧻', body_pl = 'Zapisałaś w aplikacji pierwszą pieluszkę dnia? Kolor i konsystencja kupki dokładnie pokazują, czy dziecko dostaje wystarczająco płynów.', title_pt = 'O balanço da manhã 🧻', body_pt = 'Já registou na app a primeira fralda do dia? A cor e a consistência das fezes mostram com precisão se a criança bebe líquidos suficientes.', title_sv = 'Morgonbalans 🧻', body_sv = 'Har du antecknat dagens första blöja i appen? Bajsets färg och konsistens visar exakt om barnet får i sig tillräckligt med vätska.', title_vi = 'Cân bằng buổi sáng 🧻', body_vi = 'Mẹ đã ghi chiếc tã đầu tiên trong ngày vào ứng dụng chưa? Màu sắc và độ đặc của phân cho biết chính xác bé có nạp đủ nước không.', title_zh = '早晨的平衡 🧻', body_zh = '今天的第一片尿布记到应用里了吗？便便的颜色和稠度能准确反映孩子是否摄入了足够的水分。' WHERE id = '2155f722-dd8c-49ec-a515-ecee85476474' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba en la mesa ⏱️', body_es = '¿Se pasa mucho rato en la mesa jugando con la comida? Activa el temporizador de tomas y empieza a analizar las causas de su falta de apetito.', title_fr = 'L''épreuve du repas ⏱️', body_fr = 'Il reste longtemps à table et joue avec la nourriture ? Lancez le minuteur des repas et commencez à analyser les causes de son manque d''appétit.', title_hi = 'खाने की मेज़ की परीक्षा ⏱️', body_hi = 'मेज़ पर बहुत देर बैठता है और खाने से खेलता है? फ़ीडिंग टाइमर चालू कीजिए और भूख न लगने की वजहों का विश्लेषण शुरू कीजिए।', title_id = 'Ujian di meja makan ⏱️', body_id = 'Ia terlalu lama duduk di meja dan bermain dengan makanannya? Nyalakan Timer Makan dan mulailah menganalisis penyebab hilangnya nafsu makan.', title_ja = '食卓のチャレンジ ⏱️', body_ja = '食卓に長く座って、食べ物で遊んでいますか？食事タイマーをオンにして、食欲がない原因の分析を始めましょう。', title_ko = '식탁 시험 ⏱️', body_ko = '식탁에 오래 앉아 음식으로 장난치나요? 수유 타이머를 켜고 입맛이 없는 이유를 분석해 보세요.', title_nl = 'De test aan tafel ⏱️', body_nl = 'Zit je kindje lang aan tafel en speelt hij met zijn eten? Zet de voedingstimer aan en begin te analyseren waarom hij weinig trek heeft.', title_pl = 'Próba przy stole ⏱️', body_pl = 'Długo siedzi przy stole i bawi się jedzeniem? Włącz timer karmienia i zacznij analizować przyczyny braku apetytu.', title_pt = 'O desafio da mesa ⏱️', body_pt = 'Fica muito tempo à mesa e brinca com a comida? Ligue o temporizador de alimentação e comece a analisar as causas da falta de apetite.', title_sv = 'Prövning vid matbordet ⏱️', body_sv = 'Sitter barnet länge vid bordet och leker med maten? Starta matningstimern och börja analysera orsakerna till den dåliga aptiten.', title_vi = 'Thử thách bàn ăn ⏱️', body_vi = 'Bé ngồi bàn ăn lâu và nghịch đồ ăn? Hãy bật bộ hẹn giờ trong Theo dõi cữ bú và bắt đầu phân tích nguyên nhân biếng ăn.', title_zh = '餐桌考验 ⏱️', body_zh = '在餐桌前坐太久，还玩食物？打开喂养计时器，开始分析食欲不振的原因吧。' WHERE id = '67ef78f2-7b35-47be-a6f4-6368c3a37a84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Regresión del sueño? 🤖', body_es = '¿Se despierta a menudo por la noche? Escribe a Anacan AI y descubre al momento si se trata de un salto de crecimiento.', title_fr = 'Une régression du sommeil ? 🤖', body_fr = 'Il se réveille souvent la nuit ? Écrivez à l''expert Anacan AI pour savoir tout de suite s''il s''agit d''une poussée de croissance.', title_hi = 'स्लीप रिग्रेशन? 🤖', body_hi = 'रातों में बार-बार जागता है? Anacan AI विशेषज्ञ को लिखकर तुरंत जानिए कि यह विकास की छलांग है या नहीं।', title_id = 'Regresi tidur? 🤖', body_id = 'Ia sering terbangun di malam hari? Cari tahu segera apakah ini lonjakan pertumbuhan dengan menulis ke ahli Anacan AI.', title_ja = '睡眠退行？🤖', body_ja = '夜中によく起きますか？成長の節目によるものかどうか、Anacan AIの専門アシスタントに書き込んで、すぐに確かめましょう。', title_ko = '수면 퇴행일까요? 🤖', body_ko = '밤에 자주 깨나요? 성장 급등기인지 Anacan AI 전문가에게 물어 바로 알아보세요.', title_nl = 'Slaapterugval? 🤖', body_nl = 'Wordt je kindje ''s nachts vaak wakker? Schrijf de deskundige van Anacan AI en ontdek meteen of het een groeisprong is.', title_pl = 'Regres snu? 🤖', body_pl = 'W nocy często się budzi? Napisz do eksperta Anacan AI i od razu sprawdź, czy to skok rozwojowy.', title_pt = 'Regressão do sono? 🤖', body_pt = 'Acorda muitas vezes de noite? Escreva ao especialista Anacan AI e descubra já se é um pico de crescimento.', title_sv = 'Sömnregression? 🤖', body_sv = 'Vaknar barnet ofta på nätterna? Skriv till experten Anacan AI och ta direkt reda på om det är ett tillväxtsprång.', title_vi = 'Thoái lui giấc ngủ? 🤖', body_vi = 'Ban đêm bé hay thức giấc? Hãy nhắn cho chuyên gia Anacan AI để biết ngay đó có phải bước nhảy tăng trưởng không.', title_zh = '睡眠倒退？🤖', body_zh = '夜里经常醒？给Anacan AI专家留言，马上弄清楚是不是生长飞跃期。' WHERE id = 'd9b69a33-09da-4d7d-98e9-ac3acd553715' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Eres una heroína 💖', body_es = 'No tienes que ser perfecta. Escribe simplemente «Puedo con todo» en el Diario de ánimo y descansa.', title_fr = 'Vous êtes une héroïne 💖', body_fr = 'Vous n''avez pas à être parfaite. Écrivez simplement « Je m''en sors très bien » dans le Journal d''humeur et reposez-vous.', title_hi = 'आप हीरो हैं 💖', body_hi = 'आपको परफ़ेक्ट होने की ज़रूरत नहीं। मूड डायरी में बस इतना लिखिए ''मैं सब कुछ संभाल लेती हूँ'' और आराम कीजिए।', title_id = 'Anda pahlawan 💖', body_id = 'Anda tidak harus sempurna. Cukup tulis "Aku bisa mengatasi semuanya" di Buku Harian Suasana Hati, lalu beristirahatlah.', title_ja = 'あなたはヒーローです 💖', body_ja = '完璧でなくていいのです。「気分日記」に「私はなんでも乗りこえられる」とだけ書いて、ひと休みしましょう。', title_ko = '엄마는 영웅이에요 💖', body_ko = '완벽할 필요는 없어요. 기분 일기에 그저 ''나는 모든 걸 잘 해내고 있어''라고 적고 쉬세요.', title_nl = 'Je bent een held 💖', body_nl = 'Je hoeft niet perfect te zijn. Schrijf gewoon in je Stemmingsdagboek: ik kan alles aan, en rust uit.', title_pl = 'Jesteś bohaterką 💖', body_pl = 'Nie musisz być idealna. Napisz po prostu w Dzienniku nastroju „Ze wszystkim sobie radzę” i odpocznij.', title_pt = 'É uma heroína 💖', body_pt = 'Não tem de ser perfeita. Escreva simplesmente no Diário de Humor "Eu consigo dar conta de tudo" e descanse.', title_sv = 'Du är en hjälte 💖', body_sv = 'Du behöver inte vara perfekt. Skriv bara ”Jag klarar allt” i Humördagboken och vila.', title_vi = 'Mẹ là người hùng 💖', body_vi = 'Mẹ không cần phải hoàn hảo. Chỉ cần viết vào Nhật ký tâm trạng "Mình làm được mọi thứ" và nghỉ ngơi nhé.', title_zh = '你是英雄 💖', body_zh = '你不必完美。只要在心情日记里写一句“我能搞定一切”，然后休息吧。' WHERE id = '283507fe-ca12-4764-a828-61d9a9f30424' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando al aire libre 🌳', body_es = 'Se le queda pequeña la casa. Encuentra en Lugares para mamás un parque amplio y seguro y ayúdale a gastar energía.', title_fr = 'Exploration au grand air 🌳', body_fr = 'Les murs de la maison sont trop étroits pour lui. Trouvez dans les Lieux adaptés aux mamans un parc grand et sûr pour l''aider à se défouler.', title_hi = 'ताज़ी हवा में खोज 🌳', body_hi = 'घर की दीवारें उसे तंग लगती हैं। माँ के लिए अनुकूल जगहों में कोई बड़ा और सुरक्षित पार्क ढूँढिए और उसकी ऊर्जा निकालने में मदद कीजिए।', title_id = 'Menjelajah di udara segar 🌳', body_id = 'Dinding rumah terasa terlalu sempit baginya. Temukan taman yang luas dan aman di Tempat Ramah Ibu dan bantu ia menyalurkan energinya.', title_ja = '外の空気で探検 🌳', body_ja = '家の壁が窮屈に感じられるようです。「ママにやさしいスポット」で広くて安全な公園を見つけて、エネルギーを発散させてあげましょう。', title_ko = '신선한 공기 탐험 🌳', body_ko = '집 안이 아이에게 너무 좁게 느껴져요. 엄마 친화 장소에서 넓고 안전한 공원을 찾아 에너지를 발산하게 도와주세요.', title_nl = 'Ontdekkingen in de frisse lucht 🌳', body_nl = 'De muren thuis worden je kindje te krap. Zoek in Mamavriendelijke plekken een ruim en veilig park en help hem zijn energie kwijt te raken.', title_pl = 'Odkrycia na świeżym powietrzu 🌳', body_pl = 'W domu robi mu się za ciasno. Znajdź w Miejscach przyjaznych mamom duży, bezpieczny park i pomóż mu wyładować energię.', title_pt = 'Explorar ao ar livre 🌳', body_pt = 'As paredes de casa ficam-lhe apertadas. Encontre nos Locais Amigos das Mães um parque amplo e seguro e ajude-o a gastar energia.', title_sv = 'Upptäcktsfärd i friska luften 🌳', body_sv = 'Hemmets väggar känns trånga för barnet. Hitta en stor och säker park i Mammavänliga platser och hjälp barnet att få ut sin energi.', title_vi = 'Khám phá không khí trong lành 🌳', body_vi = 'Những bức tường trong nhà đã quá chật với bé. Hãy tìm một công viên rộng rãi, an toàn trong Địa điểm thân thiện với mẹ để giúp bé xả năng lượng.', title_zh = '新鲜空气探险 🌳', body_zh = '家里的墙壁关不住他了。在妈妈友好场所里找一个宽敞安全的公园，帮他释放精力吧。' WHERE id = '290e0f59-3a24-4f74-9a01-c478f55efce5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que no se te acabe la energía 🔋', body_es = '¿Sin fuerzas de tanto correr? Elige en Recetas saludables para mujeres un desayuno delicioso que te dé energía al momento.', title_fr = 'Gardez votre énergie 🔋', body_fr = 'Vous êtes épuisée à force de courir ? Choisissez un petit-déjeuner savoureux et revigorant dans les Recettes saines pour femmes.', title_hi = 'आपकी ऊर्जा खत्म न हो 🔋', body_hi = 'भागते-भागते थककर चूर हो गईं? महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ताकत देने वाला स्वादिष्ट नाश्ता चुनिए।', title_id = 'Jangan sampai energi Anda habis 🔋', body_id = 'Kehabisan tenaga karena berlari ke sana kemari? Pilih sarapan lezat yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = 'エネルギーを切らさないで 🔋', body_ja = '追いかけてくたくたですか？「女性のためのヘルシーレシピ」から、すぐに元気が出るおいしい朝食を選びましょう。', title_ko = '에너지가 바닥나지 않게 🔋', body_ko = '뛰어다니느라 기진맥진했나요? 건강한 레시피에서 바로 힘이 나는 맛있는 아침 식사를 골라 보세요.', title_nl = 'Laat je energie niet opraken 🔋', body_nl = 'Ben je uitgeput van het rennen? Kies uit Gezonde recepten voor vrouwen een lekker ontbijt dat je meteen kracht geeft.', title_pl = 'Niech energii nie zabraknie 🔋', body_pl = 'Bieganie odebrało ci siły? Wybierz ze Zdrowych przepisów dla kobiet smaczne śniadanie, które od razu doda ci energii.', title_pt = 'Que a energia não acabe 🔋', body_pt = 'De tanto correr, ficou sem forças? Escolha nas Receitas Saudáveis para Mulheres um pequeno-almoço delicioso que dá força na hora.', title_sv = 'Låt inte energin ta slut 🔋', body_sv = 'Har du blivit helt slut av allt springande? Välj en god frukost som ger kraft direkt från Hälsosamma recept för kvinnor.', title_vi = 'Đừng để cạn năng lượng 🔋', body_vi = 'Mẹ kiệt sức vì chạy theo bé? Hãy chọn một bữa sáng ngon miệng, nạp năng lượng tức thì từ Công thức lành mạnh cho phụ nữ.', title_zh = '别让能量耗尽 🔋', body_zh = '跑得筋疲力尽？从女性健康食谱里选一份马上补充体力的美味早餐吧。' WHERE id = 'd9528425-30f7-4a4a-ac0d-053206658d00' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La siesta ⏱️', body_es = 'Activa el Temporizador de sueño. Precisa las horas de la siesta y ajusta fácilmente el paso al sueño nocturno.', title_fr = 'La sieste ⏱️', body_fr = 'Activez le minuteur de sommeil. En notant précisément l''heure des siestes, réglez facilement le passage au sommeil du soir.', title_hi = 'दिन की झपकी ⏱️', body_hi = 'स्लीप टाइमर चालू कीजिए। दिन की झपकी का समय तय करके शाम की नींद की ओर बढ़ना आसानी से संभालिए।', title_id = 'Tidur siang ⏱️', body_id = 'Aktifkan Timer Tidur. Dengan mencatat jam tidur siangnya secara tepat, atur peralihan ke tidur malam dengan mudah.', title_ja = 'お昼寝 ⏱️', body_ja = '睡眠タイマーをオンにしましょう。お昼寝の時間を正確に把握すれば、夜の眠りへの切りかえもかんたんに整えられます。', title_ko = '낮잠 ⏱️', body_ko = '수면 타이머를 켜세요. 낮잠 시간을 정확히 파악해 밤잠으로 넘어가는 시간을 쉽게 맞춰 보세요.', title_nl = 'Middagdutje ⏱️', body_nl = 'Zet de Slaaptimer aan. Leg de tijden van het middagdutje precies vast en stem zo makkelijk de overgang naar de nachtslaap af.', title_pl = 'Drzemka w ciągu dnia ⏱️', body_pl = 'Włącz timer snu. Dokładnie ustalając godziny drzemek, łatwo dopasujesz przejście do wieczornego snu.', title_pt = 'A sesta ⏱️', body_pt = 'Ative o temporizador de sono. Registe com precisão as horas da sesta e ajuste com facilidade a passagem para o sono da noite.', title_sv = 'Dagslur ⏱️', body_sv = 'Aktivera sömntimern. Bestäm tiderna för dagsluren exakt och justera enkelt övergången till kvällssömnen.', title_vi = 'Giấc ngủ ngày ⏱️', body_vi = 'Hãy bật Bộ hẹn giờ ngủ. Ghi lại chính xác giờ ngủ ngày để dễ dàng điều chỉnh việc chuyển sang giấc ngủ buổi tối.', title_zh = '白天小睡 ⏱️', body_zh = '打开睡眠计时器。弄清楚白天小睡的时间，轻松调整晚上的入睡安排。' WHERE id = '0867f1c5-1a97-47ac-ba01-ac80c4c73f6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mesa en familia 🍲', body_es = 'Ya puede comer lo mismo que vosotros. Calcula fácilmente el valor nutricional de vuestras comidas compartidas con el Seguimiento de tomas.', title_fr = 'Le repas en famille 🍲', body_fr = 'Il peut déjà manger les mêmes aliments que vous. Calculez facilement la valeur nutritionnelle de vos repas partagés avec le Suivi des repas.', title_hi = 'परिवार की खाने की मेज़ 🍲', body_hi = 'अब वह आपके जैसा ही खाना खा सकता है। फ़ीडिंग ट्रैकर से आपके साझा खाने का पोषण मूल्य आसानी से निकालिए।', title_id = 'Meja makan keluarga 🍲', body_id = 'Kini ia sudah bisa makan makanan yang sama dengan Anda. Hitung nilai gizi hidangan bersama Anda dengan mudah lewat alat Pemantau Makan.', title_ja = '家族の食卓 🍲', body_ja = 'もうあなたと同じものを食べられます。「栄養管理ツール」で、家族の共通メニューの栄養価をかんたんに計算しましょう。', title_ko = '가족 식탁 🍲', body_ko = '이제 엄마와 같은 음식을 먹을 수 있어요. 수유 기록 도구로 함께 먹는 음식의 영양가를 쉽게 계산해 보세요.', title_nl = 'Aan de gezinstafel 🍲', body_nl = 'Je kindje kan nu hetzelfde eten als jullie. Bereken met de Voedingstracker makkelijk de voedingswaarde van jullie gezamenlijke maaltijden.', title_pl = 'Rodzinny stół 🍲', body_pl = 'Może już jeść te same potrawy co wy. Łatwo oblicz wartość odżywczą wspólnych posiłków w narzędziu do śledzenia karmienia.', title_pt = 'A mesa da família 🍲', body_pt = 'Já pode comer os mesmos alimentos que vocês. Calcule com facilidade o valor nutricional das refeições partilhadas com o Registo de Alimentação.', title_sv = 'Familjebordet 🍲', body_sv = 'Nu kan barnet äta samma mat som ni. Räkna enkelt ut näringsvärdet i er gemensamma mat med Matningskoll.', title_vi = 'Mâm cơm gia đình 🍲', body_vi = 'Bé đã có thể ăn cùng món với cả nhà. Hãy dễ dàng tính giá trị dinh dưỡng của các món ăn chung bằng công cụ Theo dõi cữ bú.', title_zh = '家庭餐桌 🍲', body_zh = '他已经可以和你们吃一样的食物了。用喂养记录工具轻松算出全家共享餐的营养价值吧。' WHERE id = '1b9ea296-6f6b-4447-9f45-4c6548d5e543' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ecos de risas 📸', body_es = 'Recuerda ese momento tan tierno que más te ha hecho reír hoy y añádelo al Álbum del bebé en un vídeo corto o una foto.', title_fr = 'Des éclats de rire 📸', body_fr = 'Repensez au moment adorable qui vous a le plus fait rire aujourd''hui et ajoutez-le absolument à l''Album de bébé en petite vidéo ou en photo.', title_hi = 'हँसी की गूँज 📸', body_hi = 'आज जिस प्यारे पल ने आपको सबसे ज़्यादा हँसाया, उसे याद कीजिए और छोटे वीडियो या फ़ोटो के रूप में बेबी एल्बम में ज़रूर जोड़िए।', title_id = 'Gema tawa 📸', body_id = 'Ingat kembali momen manis yang paling membuat Anda tertawa hari ini dan pastikan menambahkannya ke Album Bayi sebagai video pendek atau foto.', title_ja = '笑い声 📸', body_ja = '今日いちばん笑ったかわいい瞬間を思い出して、ぜひ短い動画か写真で「ベビーアルバム」に追加しましょう。', title_ko = '웃음소리 📸', body_ko = '오늘 가장 많이 웃게 한 사랑스러운 순간을 떠올려 보세요. 그리고 짧은 영상이나 사진으로 아기 앨범에 꼭 추가하세요.', title_nl = 'Het geluid van gelach 📸', body_nl = 'Denk terug aan het lieve moment waar je vandaag het hardst om moest lachen en zet het zeker als korte video of foto in het Babyalbum.', title_pl = 'Odgłosy śmiechu 📸', body_pl = 'Przypomnij sobie tę słodką chwilę, która najbardziej cię dziś rozśmieszyła, i koniecznie dodaj ją do Albumu dziecka jako krótki filmik lub zdjęcie.', title_pt = 'O som das gargalhadas 📸', body_pt = 'Recorde aquele momento doce que hoje mais a fez rir e não deixe de o adicionar ao Álbum do Bebé como um pequeno vídeo ou fotografia.', title_sv = 'Ljudet av skratt 📸', body_sv = 'Tänk på den söta stunden som fick dig att skratta mest i dag och lägg till den som en kort video eller bild i Babyalbumet.', title_vi = 'Tiếng cười giòn tan 📸', body_vi = 'Hãy nhớ lại khoảnh khắc đáng yêu khiến mẹ cười nhiều nhất hôm nay và nhất định thêm nó vào Album của bé dưới dạng một video ngắn hoặc bức ảnh.', title_zh = '笑声不断 📸', body_zh = '回想一下今天最让你发笑的那个可爱瞬间，一定要把它作为小视频或照片加进宝宝相册。' WHERE id = 'b62665c0-5b12-4c5d-adfa-7b34000204cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te alarmes 🤖', body_es = '¿Has visto que hace algo raro? Sin esperar a la noche, escribe ya a Anacan AI y quítate la preocupación.', title_fr = 'Pas de panique 🤖', body_fr = 'Vous avez remarqué un comportement étrange chez votre enfant ? N''attendez pas la nuit, écrivez tout de suite à Anacan AI pour dissiper votre inquiétude.', title_hi = 'घबराइए मत 🤖', body_hi = 'बच्चे का कोई अजीब व्यवहार देखा? रात का इंतज़ार किए बिना तुरंत Anacan AI को लिखिए और अपनी चिंता दूर कीजिए।', title_id = 'Jangan panik 🤖', body_id = 'Melihat perilaku aneh pada si kecil? Jangan tunggu sampai malam, segera tulis ke Anacan AI dan hilangkan kecemasan Anda.', title_ja = '慌てないで 🤖', body_ja = 'お子さんの気になる行動に気づきましたか？夜まで待たずに、すぐにAnacan AIに書き込んで、不安を解消しましょう。', title_ko = '당황하지 마세요 🤖', body_ko = '아이의 이상한 행동을 봤나요? 밤까지 기다리지 말고 바로 Anacan AI에게 물어 걱정을 덜어 내세요.', title_nl = 'Raak niet in paniek 🤖', body_nl = 'Zag je vreemd gedrag bij je kindje? Wacht niet tot de nacht, schrijf meteen Anacan AI en neem je zorgen weg.', title_pl = 'Nie panikuj 🤖', body_pl = 'Zauważyłaś u dziecka dziwne zachowanie? Nie czekaj do nocy, od razu napisz do Anacan AI i rozwiej swoje obawy.', title_pt = 'Não entre em pânico 🤖', body_pt = 'Reparou num comportamento estranho do seu filho? Não espere pela noite: escreva já ao Anacan AI e livre-se da preocupação.', title_sv = 'Få inte panik 🤖', body_sv = 'Har du märkt ett konstigt beteende hos barnet? Vänta inte till natten, skriv direkt till Anacan AI och bli av med oron.', title_vi = 'Đừng hoảng hốt 🤖', body_vi = 'Mẹ thấy bé có hành vi lạ? Đừng đợi qua đêm, hãy nhắn ngay cho Anacan AI để trút bỏ nỗi lo.', title_zh = '别慌 🤖', body_zh = '发现孩子有奇怪的举动？别等到晚上，马上给Anacan AI留言，消除你的担心。' WHERE id = 'e16b58bb-af8f-43a3-bf1f-c1d132a221a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de calcio 🦷', body_es = 'Calcula con el Seguimiento de tomas cuánto calcio ha tomado hoy. Presta atención a la cantidad de lácteos para sus huesos y dientes.', title_fr = 'Les besoins en calcium 🦷', body_fr = 'Calculez avec le Suivi des repas combien de calcium il a pris aujourd''hui. Pour ses os et ses dents, veillez à sa ration de produits laitiers.', title_hi = 'कैल्शियम की ज़रूरत 🦷', body_hi = 'फ़ीडिंग ट्रैकर से हिसाब लगाइए कि आज उसे कितना कैल्शियम मिला। हड्डियों और दाँतों के लिए डेयरी प्रोडक्ट के मानक पर ध्यान दीजिए।', title_id = 'Kebutuhan kalsium 🦷', body_id = 'Hitung berapa banyak kalsium yang ia dapat hari ini dengan alat Pemantau Makan. Perhatikan porsi produk susu untuk tulang dan giginya.', title_ja = 'カルシウムは足りている？🦷', body_ja = '「栄養管理ツール」で、今日どれくらいカルシウムをとれたか計算しましょう。骨と歯のために、乳製品の目安に気をつけて。', title_ko = '칼슘이 필요해요 🦷', body_ko = '수유 기록 도구로 오늘 칼슘을 얼마나 섭취했는지 계산해 보세요. 뼈와 치아를 위해 유제품 섭취량을 챙겨 주세요.', title_nl = 'Behoefte aan calcium 🦷', body_nl = 'Bereken met de Voedingstracker hoeveel calcium je kindje vandaag heeft gekregen. Let op de norm voor zuivel voor zijn botten en tanden.', title_pl = 'Zapotrzebowanie na wapń 🦷', body_pl = 'Oblicz w narzędziu do śledzenia karmienia, ile wapnia dostał dziś. Zwróć uwagę na normę nabiału dla kości i zębów.', title_pt = 'A necessidade de cálcio 🦷', body_pt = 'Calcule com o Registo de Alimentação quanto cálcio comeu hoje. Para os ossos e os dentes, preste atenção à quantidade recomendada de laticínios.', title_sv = 'Kalciumbehov 🦷', body_sv = 'Räkna ut med Matningskoll hur mycket kalcium barnet har fått i dag. Var uppmärksam på normen för mejeriprodukter för skelettet och tänderna.', title_vi = 'Nhu cầu canxi 🦷', body_vi = 'Hãy tính lượng canxi bé nạp hôm nay bằng công cụ Theo dõi cữ bú. Hãy chú ý định mức các sản phẩm từ sữa cho xương và răng.', title_zh = '钙的需求 🦷', body_zh = '用喂养记录工具算算他今天摄入了多少钙。为了骨骼和牙齿，注意奶制品的参考量。' WHERE id = 'ec3f1a4d-28dd-4a4a-9b91-b595f96327d4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha acabado el champú, los pañales o la avena? No lo guardes en la cabeza: apúntalo en la Lista de la compra y sincronízala con tu pareja.', body_fr = 'Plus de shampoing, de couches ou de flocons d''avoine ? Ne gardez pas tout en tête, notez-le dans la Liste de courses et synchronisez-la avec votre conjoint.', body_hi = 'शैम्पू, डायपर या ओट्स खत्म हो गए? दिमाग में मत रखिए, शॉपिंग लिस्ट में लिखिए और अपने साथी के साथ सिंक कीजिए।', body_id = 'Sampo, popok, atau oat habis? Jangan disimpan di kepala, tulis di Daftar Belanja dan sinkronkan dengan pasangan Anda.', body_ja = 'シャンプー、おむつ、オートミールが切れた？頭で覚えておかず、「買い物リスト」に書いてパートナーと共有しましょう。', body_ko = '샴푸, 기저귀, 오트밀이 떨어졌나요? 머릿속에 담아 두지 말고 쇼핑 목록에 적어 배우자와 공유하세요.', body_nl = 'Is de shampoo, zijn de luiers of is de havermout op? Onthoud het niet, zet het op het Boodschappenlijstje en synchroniseer met je partner.', body_pl = 'Skończył się szampon, pieluszki albo płatki owsiane? Nie trzymaj tego w głowie, wpisz na Listę zakupów i zsynchronizuj z partnerem.', body_pt = 'Acabou o champô, as fraldas ou a aveia? Não guarde isso na cabeça: escreva na Lista de Compras e sincronize com o seu companheiro.', body_sv = 'Har schampot, blöjorna eller havregrynen tagit slut? Håll det inte i huvudet, skriv det i Inköpslistan och synka med din partner.', body_vi = 'Hết dầu gội, tã hay yến mạch? Đừng cố nhớ trong đầu, hãy ghi vào Danh sách mua sắm và đồng bộ với bố.', body_zh = '洗发水、尿布还是燕麦用完了？别记在脑子里，写进购物清单，和另一半同步吧。' WHERE id = '284e490f-ef18-407e-b320-432395edf56f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ahora te toca a ti 🥗', body_es = 'Si ya duerme, ¡a la cocina! Descubre en Recetas saludables para mujeres una ensalada rica en proteínas que te dé fuerzas al momento.', title_fr = 'Maintenant, c''est votre tour 🥗', body_fr = 'Il dort ? Direction la cuisine ! Découvrez une salade protéinée et revigorante dans les Recettes saines pour femmes.', title_hi = 'अब आपकी बारी है 🥗', body_hi = 'बच्चा सो गया, तो रसोई में चलिए! महिलाओं के लिए सेहतमंद रेसिपी में तुरंत ताकत देने वाला प्रोटीन भरा सलाद खोजिए।', title_id = 'Sekarang giliran Anda 🥗', body_id = 'Si kecil sudah tidur? Pergilah ke dapur! Temukan salad kaya protein yang langsung memberi tenaga di Resep Sehat untuk wanita.', title_ja = '今度はあなたの番 🥗', body_ja = 'お子さんが寝たら、キッチンへ！「女性のためのヘルシーレシピ」で、すぐに元気が出るたんぱく質たっぷりのサラダを見つけましょう。', title_ko = '이제 엄마 차례예요 🥗', body_ko = '아이가 잠들었다면 부엌으로! 건강한 레시피에서 바로 힘이 나는 단백질 샐러드를 찾아보세요.', title_nl = 'Nu ben jij aan de beurt 🥗', body_nl = 'Slaapt je kindje? Ga naar de keuken! Ontdek in Gezonde recepten voor vrouwen een salade vol eiwit die je meteen kracht geeft.', title_pl = 'Teraz twoja kolej 🥗', body_pl = 'Maluszek zasnął? Idź do kuchni! Odkryj w Zdrowych przepisach dla kobiet sałatkę pełną białka, która od razu doda ci sił.', title_pt = 'Agora é a sua vez 🥗', body_pt = 'Se ele adormeceu, vá até à cozinha! Descubra nas Receitas Saudáveis para Mulheres uma salada rica em proteína que dá força na hora.', title_sv = 'Nu är det din tur 🥗', body_sv = 'Har barnet somnat? Gå till köket! Upptäck en proteinrik sallad som ger kraft direkt i Hälsosamma recept för kvinnor.', title_vi = 'Giờ đến lượt mẹ 🥗', body_vi = 'Bé ngủ rồi thì mẹ vào bếp thôi! Hãy khám phá một món salad giàu protein, nạp năng lượng tức thì trong Công thức lành mạnh cho phụ nữ.', title_zh = '现在轮到你了 🥗', body_zh = '宝宝睡了，就去厨房吧！在女性健康食谱里发现一款马上补充体力、富含蛋白质的沙拉。' WHERE id = '72bb2391-6fc4-4ef8-9352-3ae963d61f5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de salir de casa ☕', body_es = '¿Agobiada de la rutina? Encuentra en Lugares para mamás una cafetería con rincón infantil y disfruta de un café calentito.', title_fr = 'L''heure de sortir ☕', body_fr = 'La routine vous pèse ? Trouvez dans les Lieux adaptés aux mamans un café avec un coin enfants et savourez un café chaud.', title_hi = 'घर से निकलने का समय ☕', body_hi = 'रूटीन से ऊब गईं? माँ के लिए अनुकूल जगहों में बच्चों के कोने वाला कोई कैफ़े ढूँढिए और गरम कॉफ़ी का मज़ा लीजिए।', title_id = 'Waktunya keluar rumah ☕', body_id = 'Bosan dengan rutinitas? Temukan kafe dengan area bermain anak di Tempat Ramah Ibu dan nikmati kopi hangat.', title_ja = 'お出かけの時間 ☕', body_ja = '毎日の繰り返しに疲れた？「ママにやさしいスポット」でキッズスペースのあるカフェを見つけて、温かいコーヒーを味わいましょう。', title_ko = '집을 나설 시간 ☕', body_ko = '일상이 답답한가요? 엄마 친화 장소에서 키즈 공간이 있는 카페를 찾아 따뜻한 커피 한 잔을 즐기세요.', title_nl = 'Tijd om de deur uit te gaan ☕', body_nl = 'Ben je de routine zat? Zoek in Mamavriendelijke plekken een café met een kinderhoek en geniet van een warme kop koffie.', title_pl = 'Czas wyjść z domu ☕', body_pl = 'Masz dość rutyny? Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem dla dzieci i delektuj się gorącą kawą.', title_pt = 'Hora de sair de casa ☕', body_pt = 'Está cansada da rotina? Encontre nos Locais Amigos das Mães um café com espaço infantil e saboreie um café quente.', title_sv = 'Dags att komma ut ☕', body_sv = 'Trött på rutinen? Hitta ett kafé med lekhörna i Mammavänliga platser och njut av ett varmt kaffe.', title_vi = 'Đến lúc ra khỏi nhà rồi ☕', body_vi = 'Mẹ thấy ngột ngạt với nếp sinh hoạt? Hãy tìm một quán cà phê có góc vui chơi cho trẻ trong Địa điểm thân thiện với mẹ và thưởng thức một tách cà phê nóng.', title_zh = '出门时间到 ☕', body_zh = '厌倦了日常重复？在妈妈友好场所里找一家有儿童角的咖啡馆，享受一杯热咖啡吧。' WHERE id = '91cfb4b2-1e2c-4e02-8b77-867d550b9fcd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Desahógate 📝', body_es = '¿Ha sido un día muy ruidoso? Escribir lo que sientes en el Diario de ánimo te quitará peso de la cabeza.', title_fr = 'Videz votre sac 📝', body_fr = 'La journée a été très bruyante ? Écrire vos ressentis dans le Journal d''humeur allégera votre charge mentale.', title_hi = 'मन हल्का कीजिए 📝', body_hi = 'बहुत शोर-शराबे वाला दिन था? मूड डायरी में अपनी भावनाएँ लिखने से दिमाग का बोझ हल्का होगा।', title_id = 'Curahkan isi hati 📝', body_id = 'Harinya sangat bising? Menuliskan perasaan Anda di Buku Harian Suasana Hati akan meringankan beban pikiran.', title_ja = '心の中を吐き出そう 📝', body_ja = 'とてもにぎやかな一日でしたか？「気分日記」に気持ちを書けば、頭の中の重荷が軽くなります。', title_ko = '마음을 비워 내세요 📝', body_ko = '정말 시끌벅적한 하루였나요? 기분 일기에 감정을 적으면 머릿속의 짐이 한결 가벼워질 거예요.', title_nl = 'Lucht je hart 📝', body_nl = 'Was het een erg drukke, lawaaierige dag? Je gevoelens opschrijven in je Stemmingsdagboek maakt je hoofd lichter.', title_pl = 'Wyrzuć to z siebie 📝', body_pl = 'To był bardzo hałaśliwy dzień? Zapisanie uczuć w Dzienniku nastroju zdejmie ci ciężar z głowy.', title_pt = 'Desabafe 📝', body_pt = 'Foi um dia muito barulhento? Escrever no Diário de Humor o que sente vai aliviar o peso na sua cabeça.', title_sv = 'Töm ditt inre 📝', body_sv = 'Har det varit en väldigt bullrig dag? Att skriva dina känslor i Humördagboken lättar bördan i huvudet.', title_vi = 'Hãy trút hết lòng mình 📝', body_vi = 'Hôm nay thật ồn ào? Viết cảm xúc vào Nhật ký tâm trạng sẽ giúp đầu óc mẹ nhẹ nhõm hơn.', title_zh = '把心事倒出来 📝', body_zh = '今天特别吵闹？把感受写进心情日记，能减轻你脑中的负担。' WHERE id = '7c893844-8335-47b4-baf7-b21329be4554' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Crea un cuento especial en Cuentos inteligentes. Léeselo a tu peque.', body_fr = 'Créez un conte unique dans les Contes intelligents.  Lisez-le à votre enfant.', body_hi = 'स्मार्ट कहानियों में एक खास कहानी बनाइए।  अपने बच्चे को पढ़कर सुनाइए।', body_id = 'Buat dongeng istimewa di Dongeng Pintar.  Bacakan untuk si kecil.', body_ja = '「スマートおはなし」で特別なお話をつくって、お子さんに読んであげましょう。', body_ko = '스마트 동화에서 특별한 동화를 만들어 아이에게 읽어 주세요.', body_nl = 'Maak in Slimme sprookjes een speciaal sprookje. Lees het voor aan je kindje.', body_pl = 'Stwórz w Mądrych bajkach wyjątkową bajkę.  Przeczytaj ją dziecku.', body_pt = 'Crie uma história especial nas Histórias Inteligentes.  Leia-a ao seu filho.', body_sv = 'Skapa en speciell saga i Smarta sagor.  Läs den för ditt barn.', body_vi = 'Hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh.  Và đọc cho bé nghe nhé.', body_zh = '在智能故事里创作一个专属故事，读给宝宝听吧。' WHERE id = 'ee049a04-c690-49d6-a1c7-d2c603be49d5' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Otra vez se le queda pequeña la ropa? 📏', body_es = 'Después de los 18 meses se espera un estirón. Anota las nuevas cifras en el Registro de peso y mira con orgullo su curva de crecimiento.', title_fr = 'Les vêtements ont encore rapetissé ? 📏', body_fr = 'Une poussée de croissance est attendue après 18 mois. Notez les nouveaux chiffres dans le Suivi du poids et regardez fièrement sa courbe de croissance.', title_hi = 'कपड़े फिर छोटे हो गए? 📏', body_hi = '18 महीने के बाद लंबाई में तेज़ बढ़त की उम्मीद होती है। वेट ट्रैकर में नए आँकड़े लिखिए और विकास की रेखा को गर्व से देखिए।', title_id = 'Bajunya kekecilan lagi? 📏', body_id = 'Setelah 18 bulan, lonjakan pertambahan tinggi badan biasa terjadi. Tulis angka terbarunya di Pelacak Berat Badan dan lihat kurva pertumbuhannya dengan bangga.', title_ja = 'お洋服がまた小さくなった？📏', body_ja = '1歳半を過ぎると、ぐんと背が伸びる時期がやってきます。「体重トラッカー」に新しい数値を入れて、成長曲線を誇らしく眺めましょう。', title_ko = '옷이 또 작아졌나요? 📏', body_ko = '18개월 이후에는 키가 쑥 크는 시기가 와요. 체중 기록에 새 수치를 적고 성장 곡선을 뿌듯하게 살펴보세요.', title_nl = 'Zijn de kleertjes alweer te klein? 📏', body_nl = 'Na 18 maanden wordt een groeisprong verwacht. Noteer de nieuwe cijfers in de Gewichtstracker en kijk trots naar zijn groeicurve.', title_pl = 'Ubranka znów za małe? 📏', body_pl = 'Po 18 miesiącach spodziewany jest skok wzrostu. Wpisz nowe liczby w Liczniku wagi i z dumą spójrz na krzywą rozwoju.', title_pt = 'A roupa voltou a ficar pequena? 📏', body_pt = 'Depois dos 18 meses, espera-se um pico de crescimento. Escreva os novos números no Registo de Peso e veja com orgulho a curva de crescimento.', title_sv = 'Har kläderna blivit för små igen? 📏', body_sv = 'Efter 18 månader väntar ett tillväxtsprång. Skriv in de nya siffrorna i Viktspåraren och titta med stolthet på tillväxtkurvan.', title_vi = 'Quần áo lại chật rồi? 📏', body_vi = 'Sau 18 tháng, bé sẽ có bước nhảy chiều cao. Hãy ghi số đo mới vào Theo dõi cân nặng và tự hào ngắm đường cong phát triển.', title_zh = '衣服又变小了？📏', body_zh = '18个月后会迎来一波长个子的飞跃。在体重记录里写下新数字，自豪地看看成长曲线吧。' WHERE id = 'fa6aaf54-9d2b-4b0c-a7b0-543d93bdc90a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Come solo! 🥣', body_es = '¿No suelta la cuchara? Activa el temporizador de tomas, sigue cuánto dura la comida y comprueba la cantidad.', title_fr = 'Il mange tout seul ! 🥣', body_fr = 'Il ne lâche plus sa cuillère ? Lancez le minuteur des repas pour suivre la durée du repas et vérifier ce qu''il mange.', title_hi = 'खुद खाता है! 🥣', body_hi = 'चम्मच हाथ से नहीं छोड़ता? फ़ीडिंग टाइमर चालू कीजिए, प्रक्रिया की अवधि पर भी नज़र रखिए और मानक भी जाँचिए।', title_id = 'Makan sendiri! 🥣', body_id = 'Sendok tak mau lepas dari tangannya? Nyalakan Timer Makan, pantau durasi makannya, sekaligus periksa porsinya.', title_ja = '自分で食べる！🥣', body_ja = 'スプーンを手から離さない？食事タイマーをオンにして、食事にかかる時間を見守り、量の目安もチェックしましょう。', title_ko = '혼자 먹어요! 🥣', body_ko = '숟가락을 손에서 놓지 않나요? 수유 타이머를 켜고 먹는 시간과 식사량을 함께 확인하세요.', title_nl = 'Eet zelf! 🥣', body_nl = 'Laat je kindje de lepel niet los? Zet de voedingstimer aan, volg hoe lang het duurt en controleer de norm.', title_pl = 'Je sam! 🥣', body_pl = 'Nie wypuszcza łyżeczki z ręki? Włącz timer karmienia, śledź czas trwania posiłku i sprawdzaj normę.', title_pt = 'Come sozinho! 🥣', body_pt = 'Não larga a colher? Ligue o temporizador de alimentação, acompanhe a duração da refeição e verifique a quantidade recomendada.', title_sv = 'Äter själv! 🥣', body_sv = 'Släpper barnet inte skeden? Starta matningstimern, följ hur lång tid det tar och kolla normen.', title_vi = 'Bé tự ăn! 🥣', body_vi = 'Bé không chịu rời chiếc thìa? Hãy bật bộ hẹn giờ trong Theo dõi cữ bú để vừa theo dõi thời gian, vừa kiểm tra định mức.', title_zh = '自己吃饭！🥣', body_zh = '勺子不离手？打开喂养计时器，既能记录用时，也能看看参考量。' WHERE id = '46fbf80f-0604-494d-b68e-60f85488090d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primeros dibujos 🖍️', body_es = '¿Han empezado los garabatos? Echa un vistazo en Productos recomendados a las mejores pinturas inofensivas y lavables.', title_fr = 'Premiers dessins 🖍️', body_fr = 'Les gribouillis ont commencé ? Jetez un œil aux meilleures peintures sans danger et lavables dans les Produits recommandés.', title_hi = 'पहली ड्रॉइंग 🖍️', body_hi = 'आड़ी-तिरछी लकीरें शुरू हो गईं? सुरक्षित और धुलने वाले रंगों के लिए सुझाए गए प्रोडक्ट सेक्शन के सबसे अच्छे विकल्प देखिए।', title_id = 'Gambar pertama 🖍️', body_id = 'Masa coret-coret sudah dimulai? Lihat pilihan terbaik untuk krayon yang aman dan bisa dicuci di bagian Produk Rekomendasi.', title_ja = 'はじめての作品 🖍️', body_ja = 'なぐり描きが始まりましたか？安全で洗って落とせる絵の具は、「おすすめ商品」でベストな選択肢をのぞいてみましょう。', title_ko = '첫 그림 🖍️', body_ko = '끄적이기가 시작됐나요? 안전하고 물로 지워지는 크레용은 추천 제품 섹션에서 가장 좋은 제품을 살펴보세요.', title_nl = 'De eerste tekeningen 🖍️', body_nl = 'Is het krassen begonnen? Bekijk in het onderdeel Aanbevolen producten de beste keuzes voor onschadelijke, afwasbare verf.', title_pl = 'Pierwsze rysunki 🖍️', body_pl = 'Zaczęło się bazgranie? Przejrzyj w sekcji Polecane produkty najlepsze bezpieczne i zmywalne farby.', title_pt = 'Os primeiros desenhos 🖍️', body_pt = 'Começaram os rabiscos? Espreite na secção Produtos Recomendados as melhores opções de tintas inofensivas e laváveis.', title_sv = 'De första teckningarna 🖍️', body_sv = 'Har klottret börjat? Titta på de bästa alternativen för ofarliga och tvättbara färger i avsnittet Rekommenderade produkter.', title_vi = 'Những bức vẽ đầu tiên 🖍️', body_vi = 'Giai đoạn vẽ nguệch ngoạc đã bắt đầu? Hãy xem những lựa chọn màu vẽ an toàn, có thể giặt sạch tốt nhất trong mục Sản phẩm gợi ý.', title_zh = '第一批画作 🖍️', body_zh = '开始涂鸦了？看看推荐商品里安全、可水洗颜料的最佳选择吧。' WHERE id = '5174db8a-22d1-41db-af86-5a575522337a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño artista 📸', body_es = '¿Está lleno de pintura de arriba abajo? En lugar de enfadarte, inmortaliza este momento tan gracioso con los marcos divertidos de la Sesión de fotos del bebé.', title_fr = 'Petit artiste 📸', body_fr = 'Il est couvert de peinture ? Au lieu de vous énerver, immortalisez ce moment comique avec les cadres joyeux de la Séance photo bébé.', title_hi = 'नन्हा कलाकार 📸', body_hi = 'पूरा रंगों में सना है? चिढ़ने के बजाय इस मज़ेदार पल को बेबी फ़ोटोशूट के खुशनुमा फ़्रेम से हमेशा के लिए सहेज लीजिए।', title_id = 'Pelukis kecil 📸', body_id = 'Baju dan tubuhnya penuh cat? Daripada kesal, abadikan momen lucu ini dengan bingkai ceria di Sesi Foto Bayi.', title_ja = '小さな画家 📸', body_ja = '全身絵の具まみれ？イライラするかわりに、このおもしろい瞬間を「ベビーフォトセッション」の楽しいフレームで残しましょう。', title_ko = '꼬마 화가 📸', body_ko = '온몸이 물감 범벅인가요? 화내는 대신 이 웃긴 순간을 아기 사진 촬영의 즐거운 프레임으로 영원히 남기세요.', title_nl = 'Kleine kunstenaar 📸', body_nl = 'Zit je kindje helemaal onder de verf? Word niet boos, maar leg dit grappige moment voor altijd vast met de vrolijke kaders in Babyfotoshoot.', title_pl = 'Mały artysta 📸', body_pl = 'Cały jest w farbie? Zamiast się denerwować, uwiecznij tę zabawną chwilę z wesołymi ramkami w Sesji zdjęciowej dziecka.', title_pt = 'O pequeno artista 📸', body_pt = 'Está todo coberto de tinta? Em vez de se irritar, eternize este momento cómico com as molduras divertidas da Sessão Fotográfica do Bebé.', title_sv = 'Liten konstnär 📸', body_sv = 'Är barnet täckt av färg? I stället för att bli irriterad, förevig det roliga ögonblicket med glada ramar i Babyfotografering.', title_vi = 'Họa sĩ nhí 📸', body_vi = 'Bé dính màu khắp người? Thay vì bực mình, hãy lưu giữ khoảnh khắc hài hước này với những khung ảnh vui nhộn trong Chụp ảnh cho bé.', title_zh = '小画家 📸', body_zh = '身上沾满了颜料？与其生气，不如用宝宝写真里欢乐的相框把这个好笑的瞬间永远留下来。' WHERE id = '5e9337e9-36e0-44d6-9ecf-c3265d3eca6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Horario de sueño ⏱️', body_es = '¡A la cama! Activa el Temporizador de sueño y analiza su rutina para asegurarte de que duerme lo que necesita cada día.', title_fr = 'Le planning de sommeil ⏱️', body_fr = 'Au lit ! Lancez le minuteur de sommeil et analysez son rythme pour vous assurer qu''il dort suffisamment chaque jour.', title_hi = 'नींद का शेड्यूल ⏱️', body_hi = 'सोने चलें! स्लीप टाइमर चालू कीजिए, यह पक्का करने के लिए कि वह रोज़ की नींद का मानक पूरा कर रहा है, उसके रूटीन का विश्लेषण कीजिए।', title_id = 'Jadwal tidur ⏱️', body_id = 'Waktunya tidur! Nyalakan Timer Tidur dan analisis rutinitasnya untuk memastikan kebutuhan tidur hariannya terpenuhi.', title_ja = '睡眠スケジュール ⏱️', body_ja = 'さあ、ねんねの時間！睡眠タイマーをオンにして、1日の睡眠量の目安を守れているか、リズムを分析しましょう。', title_ko = '수면 일정 ⏱️', body_ko = '잘 시간이에요! 수면 타이머를 켜고 하루 수면량을 잘 지키고 있는지 일과를 분석해 보세요.', title_nl = 'Slaapschema ⏱️', body_nl = 'Tijd voor bed! Zet de Slaaptimer aan en analyseer zijn ritme om zeker te zijn dat hij zijn dagelijkse slaap haalt.', title_pl = 'Plan snu ⏱️', body_pl = 'Idziemy spać! Włącz timer snu i przeanalizuj jego rytm, by mieć pewność, że trzyma się dziennej normy snu.', title_pt = 'O horário do sono ⏱️', body_pt = 'Vamos para a cama! Ligue o temporizador de sono e analise a rotina para confirmar que cumpre as horas de sono diárias recomendadas.', title_sv = 'Sömnschema ⏱️', body_sv = 'Vi går och lägger oss! Starta sömntimern och analysera rutinen för att försäkra dig om att barnet når sin dagliga sömnnorm.', title_vi = 'Lịch ngủ ⏱️', body_vi = 'Đi ngủ thôi! Hãy bật Bộ hẹn giờ ngủ và phân tích nếp sinh hoạt để chắc chắn bé ngủ đủ định mức hằng ngày.', title_zh = '睡眠时间表 ⏱️', body_zh = '准备上床啦！打开睡眠计时器，分析他的作息，确认达到了每日睡眠参考量。' WHERE id = 'd414aad6-2d3e-4a62-a555-9241874e68b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sorpresa matutina 💩', body_es = '¿Has cambiado el primer pañal del día? Anota los datos de la caca en la app y sigue de cerca su sistema digestivo y la ingesta de líquidos.', title_fr = 'La surprise du matin 💩', body_fr = 'Vous avez changé la première couche de la journée ? Notez les selles dans l''application pour suivre de près sa digestion et son hydratation.', title_hi = 'सुबह का सरप्राइज़ 💩', body_hi = 'दिन का पहला डायपर बदल दिया? पॉटी की जानकारी ऐप में दर्ज करके पाचन तंत्र और तरल लेने पर करीब से नज़र रखिए।', title_id = 'Kejutan pagi 💩', body_id = 'Sudah mengganti popok pertama hari ini? Catat data BAB-nya di aplikasi dan pantau dengan cermat sistem pencernaan serta asupan cairannya.', title_ja = '朝のサプライズ 💩', body_ja = '今日最初のおむつ替えはすみましたか？うんちの情報をアプリに記録して、おなかの調子と水分摂取をしっかり見守りましょう。', title_ko = '아침의 깜짝 선물 💩', body_ko = '오늘 첫 기저귀를 갈았나요? 배변 정보를 앱에 기록하고 소화 상태와 수분 섭취를 꼼꼼히 살펴보세요.', title_nl = 'Een verrassing in de ochtend 💩', body_nl = 'Heb je de eerste luier van de dag verschoond? Noteer de gegevens over de ontlasting in de app en volg zijn spijsvertering en vochtinname van dichtbij.', title_pl = 'Poranna niespodzianka 💩', body_pl = 'Przewinęłaś pierwszą pieluszkę dnia? Zapisz informacje o kupce w aplikacji i uważnie śledź pracę układu pokarmowego i ilość wypijanych płynów.', title_pt = 'A surpresa da manhã 💩', body_pt = 'Já mudou a primeira fralda do dia? Registe na app as informações das fezes e acompanhe de perto o sistema digestivo e a ingestão de líquidos.', title_sv = 'Morgonens överraskning 💩', body_sv = 'Har du bytt dagens första blöja? Anteckna informationen om bajset i appen och följ noga matsmältningen och vätskeintaget.', title_vi = 'Bất ngờ buổi sáng 💩', body_vi = 'Mẹ vừa thay chiếc tã đầu tiên trong ngày? Hãy ghi thông tin về phân vào ứng dụng để theo dõi sát hệ tiêu hóa và lượng nước bé nạp.', title_zh = '早晨的惊喜 💩', body_zh = '换了今天的第一片尿布？把便便情况记到应用里，密切关注他的肠胃和水分摄入。' WHERE id = '7616cbf9-cf9d-45e8-86a1-eb74cb13ae1e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Temporizador de sueño en marcha! ⏱️', body_es = 'Empieza la rutina de la noche. Activa el temporizador y analiza fácilmente cómo cambia el tiempo que tarda en dormirse después de un día activo.', title_fr = 'Le minuteur de sommeil est lancé ! ⏱️', body_fr = 'Le rituel du soir commence. Lancez le minuteur et analysez facilement comment une journée active change le temps d''endormissement.', title_hi = 'स्लीप टाइमर चालू हो गया! ⏱️', body_hi = 'शाम का रूटीन शुरू हो रहा है। टाइमर चालू कीजिए और आसानी से देखिए कि भाग-दौड़ भरे दिन ने नींद में जाने का समय कैसे बदला।', title_id = 'Timer Tidur sudah menyala! ⏱️', body_id = 'Rutinitas malam dimulai. Nyalakan timer dan analisis dengan mudah bagaimana hari yang aktif mengubah lamanya ia beralih ke tidur.', title_ja = '睡眠タイマーがスタート！⏱️', body_ja = '夜の習慣が始まります。タイマーをオンにして、活発な一日が寝つくまでの時間にどう影響するか、かんたんに分析しましょう。', title_ko = '수면 타이머 시작! ⏱️', body_ko = '저녁 루틴이 시작돼요. 타이머를 켜고 활발한 하루가 잠드는 시간을 어떻게 바꾸는지 쉽게 분석해 보세요.', title_nl = 'De Slaaptimer is gestart! ⏱️', body_nl = 'De avondroutine begint. Zet de timer aan en analyseer makkelijk hoe een drukke dag de tijd tot het inslapen verandert.', title_pl = 'Timer snu włączony! ⏱️', body_pl = 'Zaczyna się wieczorna rutyna. Włącz timer i łatwo sprawdź, jak aktywny dzień zmienia czas zasypiania.', title_pt = 'O temporizador de sono está ligado! ⏱️', body_pt = 'Começa a rotina da noite. Ligue o temporizador e analise com facilidade como um dia ativo altera o tempo que demora a adormecer.', title_sv = 'Sömntimern är igång! ⏱️', body_sv = 'Kvällsrutinen börjar. Starta timern och analysera enkelt hur en aktiv dag påverkar tiden det tar att somna.', title_vi = 'Bộ hẹn giờ ngủ đã bật! ⏱️', body_vi = 'Nếp sinh hoạt buổi tối bắt đầu. Hãy bật bộ hẹn giờ và dễ dàng phân tích một ngày hiếu động ảnh hưởng thế nào đến thời gian vào giấc.', title_zh = '睡眠计时器启动啦！⏱️', body_zh = '晚间作息开始了。打开计时器，轻松分析活跃的一天如何改变了入睡所需的时间。' WHERE id = 'b32e8863-be99-483a-aff4-94fc82f554bc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te han dejado sin fuerzas tantas carreras? ¡No te olvides de ti! Prepara en Recetas saludables un batido con proteínas que te dé energía al momento.', body_fr = 'Courir partout vous a vidée ? Ne vous oubliez pas ! Préparez un smoothie protéiné et revigorant grâce aux Recettes saines.', body_hi = 'भागदौड़ ने ताकत छीन ली? खुद को मत भूलिए! सेहतमंद रेसिपी से तुरंत ताकत देने वाली प्रोटीन भरी स्मूदी बनाइए।', body_id = 'Kejar-kejaran menguras tenaga Anda? Jangan lupakan diri sendiri! Buat smoothie kaya protein yang langsung memberi tenaga dari Resep Sehat.', body_ja = '追いかけっこでへとへと？自分のことも忘れないで！「ヘルシーレシピ」から、すぐに元気が出るたんぱく質たっぷりのスムージーをつくりましょう。', body_ko = '뛰어다니느라 기운이 다 빠졌나요? 나 자신을 잊지 마세요! 건강한 레시피에서 바로 힘이 나는 단백질 스무디를 만들어 보세요.', body_nl = 'Heeft al het rennen je uitgeput? Vergeet jezelf niet! Maak uit Gezonde recepten een smoothie vol eiwit die je meteen kracht geeft.', body_pl = 'Bieganina odebrała ci siły? Nie zapominaj o sobie! Przygotuj ze zdrowych przepisów smoothie z białkiem, które od razu doda ci energii.', body_pt = 'A correria tirou-lhe as forças? Não se esqueça de si! Prepare nas Receitas Saudáveis um batido rico em proteína que dá força na hora.', body_sv = 'Har allt springande tagit all din kraft? Glöm inte dig själv! Gör en proteinrik smoothie som ger kraft direkt från Hälsosamma recept.', body_vi = 'Chạy theo bé làm mẹ kiệt sức? Đừng quên bản thân mẹ! Hãy làm một ly sinh tố giàu protein, nạp năng lượng tức thì từ Công thức lành mạnh.', body_zh = '追追跑跑让你筋疲力尽？别忘了自己！从健康食谱里做一杯马上补充体力、富含蛋白质的果昔吧。' WHERE id = '4673b81e-675b-4232-a5ca-c06aa26d504d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Una mañana difícil? 🌪️', body_es = 'Las rabietas agotan. Respira hondo y pregunta ya a Anacan AI cómo actuar en esta situación.', title_fr = 'Matinée difficile ? 🌪️', body_fr = 'Les crises d''entêtement sont épuisantes. Respirez profondément et demandez tout de suite à Anacan AI comment réagir dans cette situation.', title_hi = 'मुश्किल सुबह? 🌪️', body_hi = 'ज़िद के दौरे थका देते हैं। गहरी साँस लीजिए और तुरंत Anacan AI से पूछिए कि ऐसी स्थिति में कैसे पेश आएँ।', title_id = 'Pagi yang berat? 🌪️', body_id = 'Krisis keras kepala itu melelahkan. Tarik napas dalam-dalam dan segera tanyakan ke Anacan AI bagaimana bersikap dalam situasi ini.', title_ja = '大変な朝？🌪️', body_ja = 'いやいやのかんしゃくは疲れます。深呼吸して、こんなときどう対応すればいいか、すぐにAnacan AIに聞いてみましょう。', title_ko = '힘든 아침인가요? 🌪️', body_ko = '고집 부리는 떼쓰기는 정말 지쳐요. 깊게 숨을 쉬고 이런 상황에서 어떻게 해야 할지 바로 Anacan AI에게 물어보세요.', title_nl = 'Een zware ochtend? 🌪️', body_nl = 'Koppige driftbuien zijn vermoeiend. Haal diep adem en vraag Anacan AI meteen hoe je in deze situatie het best reageert.', title_pl = 'Trudny poranek? 🌪️', body_pl = 'Kryzysy uporu są męczące. Weź głęboki oddech i od razu zapytaj Anacan AI, jak zachować się w tej sytuacji.', title_pt = 'Uma manhã difícil? 🌪️', body_pt = 'As crises de teimosia cansam. Respire fundo e pergunte já ao Anacan AI como agir nesta situação.', title_sv = 'Tuff morgon? 🌪️', body_sv = 'Trotsutbrotten är tröttsamma. Ta ett djupt andetag och fråga direkt Anacan AI hur du ska agera i den här situationen.', title_vi = 'Một buổi sáng khó khăn? 🌪️', body_vi = 'Những cơn bướng bỉnh thật mệt mỏi. Hãy hít thở thật sâu và hỏi ngay Anacan AI nên ứng xử thế nào trong tình huống này.', title_zh = '艰难的早晨？🌪️', body_zh = '倔脾气的崩溃很累人。深呼吸，马上问问Anacan AI这种情况该怎么做吧。' WHERE id = '7a2ab463-526e-46c6-a246-3494b6c46fa9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escucha tu voz interior 📝', body_es = 'Ya duerme. Abre ahora el Diario de ánimo y vuelca lo que has sentido hoy en esas líneas que nadie más leerá; te sentirás más ligera.', title_fr = 'Écoutez votre voix intérieure 📝', body_fr = 'Il dort. Ouvrez maintenant le Journal d''humeur et allégez-vous en confiant vos ressentis du jour à ces lignes que personne ne lira.', title_hi = 'अपने मन की आवाज़ सुनिए 📝', body_hi = 'बच्चा सो गया। अब मूड डायरी खोलिए और उन पंक्तियों में आज की भावनाएँ उतारकर हल्का महसूस कीजिए, जिन्हें कोई और नहीं पढ़ेगा।', title_id = 'Dengarkan suara hati Anda 📝', body_id = 'Si kecil sudah tidur. Sekarang buka Buku Harian Suasana Hati dan ringankan hati dengan menuangkan perasaan hari ini ke dalam tulisan yang tak akan dibaca siapa pun.', title_ja = '心の声に耳を傾けて 📝', body_ja = 'お子さんが寝ました。「気分日記」を開いて、誰も読まないページに今日の気持ちを書き出し、心を軽くしましょう。', title_ko = '내 마음의 소리에 귀 기울이세요 📝', body_ko = '아이가 잠들었어요. 이제 기분 일기를 열고 아무도 읽지 않을 그 줄들에 오늘의 감정을 쏟아 내며 마음을 가볍게 하세요.', title_nl = 'Luister naar je innerlijke stem 📝', body_nl = 'Je kindje slaapt. Open nu je Stemmingsdagboek en lucht je hart door je gevoelens van vandaag op te schrijven op die bladzijden die niemand anders leest.', title_pl = 'Wsłuchaj się w swój wewnętrzny głos 📝', body_pl = 'Maluszek zasnął. Teraz otwórz Dziennik nastroju, przelej dzisiejsze uczucia na strony, których nikt nie przeczyta, i poczuj ulgę.', title_pt = 'Escute a sua voz interior 📝', body_pt = 'Ele adormeceu. Agora abra o Diário de Humor e alivie-se, passando o que sentiu hoje para aquelas linhas que mais ninguém vai ler.', title_sv = 'Lyssna på din inre röst 📝', body_sv = 'Barnet sover. Öppna nu Humördagboken och lätta ditt hjärta genom att skriva dagens känslor på raderna som ingen annan kommer att läsa.', title_vi = 'Lắng nghe tiếng nói bên trong 📝', body_vi = 'Bé ngủ rồi. Giờ hãy mở Nhật ký tâm trạng và trút cảm xúc hôm nay vào những dòng chữ không ai đọc để nhẹ lòng hơn.', title_zh = '倾听内心的声音 📝', body_zh = '宝宝睡了。现在打开心情日记，把今天的感受倾注在那些没人会读到的字里行间，让自己轻松一些。' WHERE id = 'c995af30-30f9-4eaf-a66c-3d0d65fc825b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un sonido que calma 🌧️', body_es = '¿No consigue dormirse después de un día lleno de descubrimientos? Pon el sonido de la lluvia en Ruido blanco y calma su sistema nervioso de forma natural.', title_fr = 'Un son apaisant 🌧️', body_fr = 'Il n''arrive pas à dormir après une journée pleine de nouvelles découvertes ? Lancez le bruit de la pluie dans les Bruits blancs pour apaiser naturellement son système nerveux.', title_hi = 'शांत करने वाली आवाज़ 🌧️', body_hi = 'नई खोजों से भरे दिन के बाद सो नहीं पा रहा? व्हाइट नॉइज़ से बारिश की आवाज़ चलाकर उसके नर्वस सिस्टम को स्वाभाविक रूप से शांत कीजिए।', title_id = 'Suara yang menenangkan 🌧️', body_id = 'Ia tidak bisa tidur setelah hari penuh penemuan baru? Tenangkan sistem sarafnya secara alami dengan memutar suara hujan dari Suara Putih.', title_ja = '心落ち着く音 🌧️', body_ja = '新しい発見でいっぱいの一日のあと、なかなか眠れない？「ホワイトノイズ」から雨の音を流して、神経を自然に落ち着かせましょう。', title_ko = '마음을 달래 주는 소리 🌧️', body_ko = '새로운 발견으로 가득한 하루 뒤에 잠들지 못하나요? 백색소음의 빗소리로 신경계를 자연스럽게 진정시켜 주세요.', title_nl = 'Rustgevend geluid 🌧️', body_nl = 'Kan je kindje niet slapen na een dag vol nieuwe ontdekkingen? Zet in Witte ruis het geluid van regen aan en kalmeer zijn zenuwstelsel op een natuurlijke manier.', title_pl = 'Kojący dźwięk 🌧️', body_pl = 'Nie może zasnąć po dniu pełnym nowych odkryć? Włącz w Białym szumie odgłos deszczu i w naturalny sposób wycisz jego układ nerwowy.', title_pt = 'Um som calmante 🌧️', body_pt = 'Não consegue dormir depois de um dia cheio de novas descobertas? Ligue o som da chuva no Ruído Branco e acalme de forma natural o sistema nervoso dele.', title_sv = 'Lugnande ljud 🌧️', body_sv = 'Kan barnet inte sova efter en dag full av nya upptäckter? Sätt på regnljud i Vitt brus och lugna nervsystemet på ett naturligt sätt.', title_vi = 'Âm thanh êm dịu 🌧️', body_vi = 'Bé không ngủ được sau một ngày đầy khám phá mới? Hãy bật tiếng mưa trong Tiếng ồn trắng để làm dịu hệ thần kinh của bé một cách tự nhiên.', title_zh = '舒缓的声音 🌧️', body_zh = '探索了一整天，兴奋得睡不着？在白噪音里放雨声，让他的神经系统自然地平静下来。' WHERE id = '0aa2cefc-f18c-4c10-98d6-e4dfda22198e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aire fresco y mucha energía 🌳', body_es = '¿Se le queda pequeña la casa? Encuentra en Lugares para mamás un parque nuevo con columpios diferentes y ayúdale a gastar energía.', title_fr = 'Air frais et plein d''énergie 🌳', body_fr = 'Les murs de la maison sont trop étroits ? Trouvez dans les Lieux adaptés aux mamans un nouveau parc avec des jeux différents pour l''aider à se défouler.', title_hi = 'ताज़ी हवा, भरपूर ऊर्जा 🌳', body_hi = 'घर की दीवारें तंग लगती हैं? माँ के लिए अनुकूल जगहों में अलग-अलग झूलों वाला कोई नया पार्क ढूँढिए और उसकी ऊर्जा निकालने में मदद कीजिए।', title_id = 'Udara segar, energi melimpah 🌳', body_id = 'Dinding rumah terasa sempit? Temukan taman baru dengan wahana bermain yang berbeda di Tempat Ramah Ibu dan bantu ia menyalurkan energinya.', title_ja = '新鮮な空気で元気いっぱい 🌳', body_ja = '家の中が窮屈？「ママにやさしいスポット」で、いろいろな遊具のある新しい公園を見つけて、エネルギーを発散させてあげましょう。', title_ko = '신선한 공기, 넘치는 에너지 🌳', body_ko = '집 안이 너무 좁게 느껴지나요? 엄마 친화 장소에서 색다른 놀이기구가 있는 새 공원을 찾아 에너지를 발산하게 도와주세요.', title_nl = 'Frisse lucht, veel energie 🌳', body_nl = 'Worden de muren thuis te krap? Zoek in Mamavriendelijke plekken een nieuw park met andere speeltoestellen en help je kindje zijn energie kwijt te raken.', title_pl = 'Świeże powietrze, mnóstwo energii 🌳', body_pl = 'W domu robi się ciasno? Znajdź w Miejscach przyjaznych mamom nowy park z ciekawymi urządzeniami do zabawy i pomóż mu wyładować energię.', title_pt = 'Ar puro, muita energia 🌳', body_pt = 'As paredes de casa ficam-lhe apertadas? Encontre nos Locais Amigos das Mães um parque novo com diversões diferentes e ajude-o a gastar energia.', title_sv = 'Frisk luft, massor av energi 🌳', body_sv = 'Känns hemmets väggar trånga? Hitta en ny park med olika lekredskap i Mammavänliga platser och hjälp barnet att få ut sin energi.', title_vi = 'Không khí trong lành, tràn đầy năng lượng 🌳', body_vi = 'Những bức tường trong nhà đã quá chật? Hãy tìm một công viên mới có nhiều trò chơi khác nhau trong Địa điểm thân thiện với mẹ để giúp bé xả năng lượng.', title_zh = '新鲜空气，满满能量 🌳', body_zh = '家里的墙壁关不住他了？在妈妈友好场所里找一个有不同游乐设施的新公园，帮他释放精力吧。' WHERE id = 'a57c041d-751b-4413-a98e-ee1564a86127' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Salto intelectual 🧠', body_es = '¿Qué está pasando en el cerebro de tu peque de 18,5 meses? Lee el artículo más reciente del Blog y descubre su proceso de desarrollo.', title_fr = 'Un bond intellectuel 🧠', body_fr = 'Que se passe-t-il dans le cerveau d''un enfant de 18,5 mois ? Découvrez les étapes de son développement en lisant le dernier article de nos Blogs.', title_hi = 'दिमागी छलांग 🧠', body_hi = '18.5 महीने के बच्चे के दिमाग में क्या चल रहा है? ब्लॉग सेक्शन का सबसे नया लेख पढ़कर विकास की प्रक्रियाएँ जानिए।', title_id = 'Lompatan kecerdasan 🧠', body_id = 'Apa yang terjadi di otak anak usia 18,5 bulan? Baca artikel terbaru di bagian Blog dan kenali proses perkembangannya.', title_ja = '知能の飛躍 🧠', body_ja = '1歳6か月半の子の脳では何が起きているのでしょう？ブログの最新記事を読んで、発達の仕組みを知りましょう。', title_ko = '두뇌 도약 🧠', body_ko = '18.5개월 아기의 뇌에서는 무슨 일이 일어나고 있을까요? 블로그 섹션의 최신 글을 읽으며 발달 과정을 알아보세요.', title_nl = 'Een sprong in het verstand 🧠', body_nl = 'Wat gebeurt er in het hoofdje van een kindje van 18,5 maanden? Lees het nieuwste artikel in het onderdeel Blogs en ontdek zijn ontwikkeling.', title_pl = 'Skok umysłowy 🧠', body_pl = 'Co dzieje się w mózgu 18,5-miesięcznego dziecka? Przeczytaj najnowszy artykuł w sekcji Blogi i poznaj procesy rozwoju.', title_pt = 'Salto de inteligência 🧠', body_pt = 'O que se passa no cérebro de uma criança de 18,5 meses? Leia o artigo mais recente da secção Blogues e descubra os processos de desenvolvimento.', title_sv = 'Intelligenssprång 🧠', body_sv = 'Vad händer i hjärnan hos ett barn på 18,5 månader? Läs den senaste artikeln i avsnittet Bloggar och upptäck utvecklingsprocesserna.', title_vi = 'Bước nhảy trí tuệ 🧠', body_vi = 'Điều gì đang diễn ra trong não bé 18,5 tháng? Hãy đọc bài viết mới nhất trong mục Blog để khám phá những quá trình phát triển của bé.', title_zh = '智力飞跃 🧠', body_zh = '18.5个月宝宝的大脑里正在发生什么？读读博客板块里的最新文章，探索发育过程吧。' WHERE id = 'f3737052-fe7e-4f0c-9b36-7d082f7dbdfc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se pasa mucho rato en la mesa? ⏱️', body_es = 'Ha empezado la etapa de jugar con la comida. Activa el temporizador de tomas y analiza cuánto dura cada comida para evitar la falta de apetito.', title_fr = 'Il reste longtemps à table ? ⏱️', body_fr = 'La période où l''on joue avec la nourriture a commencé. Lancez le minuteur des repas et analysez la durée des repas pour éviter le manque d''appétit.', title_hi = 'मेज़ पर बहुत देर बैठता है? ⏱️', body_hi = 'खाने से खेलने का दौर शुरू हो गया है। फ़ीडिंग टाइमर चालू कीजिए और भूख न लगने से बचाने के लिए खाने की अवधि का विश्लेषण कीजिए।', title_id = 'Terlalu lama duduk di meja makan? ⏱️', body_id = 'Masa bermain dengan makanan sudah dimulai. Nyalakan Timer Makan dan analisis durasi makannya untuk mencegah hilangnya nafsu makan.', title_ja = '食卓に長く座りすぎ？⏱️', body_ja = '食べ物で遊ぶ時期が始まりました。食事タイマーをオンにして、食欲不振を防ぐために食事時間を分析しましょう。', title_ko = '식탁에 너무 오래 앉아 있나요? ⏱️', body_ko = '음식으로 노는 시기가 시작됐어요. 수유 타이머를 켜고 입맛 없는 식사를 예방할 수 있도록 식사 시간을 분석해 보세요.', title_nl = 'Zit hij lang aan tafel? ⏱️', body_nl = 'De fase van spelen met eten is begonnen. Zet de voedingstimer aan en analyseer hoe lang het eten duurt om gebrek aan eetlust te voorkomen.', title_pl = 'Długo siedzi przy stole? ⏱️', body_pl = 'Zaczął się etap zabawy jedzeniem. Włącz timer karmienia i przeanalizuj czas posiłków, by zapobiec brakowi apetytu.', title_pt = 'Fica muito tempo à mesa? ⏱️', body_pt = 'Começou a fase de brincar com a comida. Ligue o temporizador de alimentação e analise a duração das refeições para prevenir a falta de apetite.', title_sv = 'Sitter barnet länge vid bordet? ⏱️', body_sv = 'Perioden då barnet leker med maten har börjat. Starta matningstimern och analysera måltidens längd för att förebygga dålig aptit.', title_vi = 'Bé ngồi bàn ăn quá lâu? ⏱️', body_vi = 'Giai đoạn nghịch đồ ăn đã bắt đầu. Hãy bật bộ hẹn giờ trong Theo dõi cữ bú và phân tích thời gian ăn để phòng tránh biếng ăn.', title_zh = '在餐桌前坐太久？⏱️', body_zh = '玩食物的阶段开始了。打开喂养计时器，分析进餐时长，预防食欲不振。' WHERE id = '108adc32-ab84-4dcd-be8c-e7597e84aa99' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Otra vez se le queda pequeña la ropa? 📏', body_es = '¿Notas que ha pegado un estirón de repente? Introduce las nuevas cifras en el Seguimiento del desarrollo y mira con orgullo cómo sube su gráfica.', title_fr = 'Les vêtements ont encore rapetissé ? 📏', body_fr = 'Vous sentez qu''il a grandi d''un coup ? Saisissez les nouveaux chiffres dans le Suivi de croissance et regardez fièrement sa courbe monter.', title_hi = 'कपड़े फिर छोटे हो गए? 📏', body_hi = 'महसूस हो रहा है कि अचानक लंबाई बढ़ गई? ग्रोथ ट्रैकर में नए आँकड़े डालिए और विकास के चार्ट की बढ़त को गर्व से देखिए।', title_id = 'Bajunya kekecilan lagi? 📏', body_id = 'Merasa ia tiba-tiba bertambah tinggi? Masukkan angka terbarunya di Pelacak Pertumbuhan dan lihat dengan bangga grafik pertumbuhannya yang terus naik.', title_ja = 'お洋服がまた小さくなった？📏', body_ja = '急に背が伸びたと感じますか？「発達トラッカー」に新しい数値を入れて、成長グラフの伸びを誇らしく眺めましょう。', title_ko = '옷이 또 작아졌나요? 📏', body_ko = '키가 갑자기 쑥 자란 것 같나요? 성장 기록에 새 수치를 입력하고 성장 그래프가 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Zijn de kleertjes alweer te klein? 📏', body_nl = 'Merk je dat je kindje ineens gegroeid is? Voer de nieuwe cijfers in de Groeitracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Ubranka znów za małe? 📏', body_pl = 'Czujesz, że nagle urósł? Wpisz nowe liczby w Śledzeniu rozwoju i z dumą patrz, jak pnie się wykres rozwoju.', title_pt = 'A roupa voltou a ficar pequena? 📏', body_pt = 'Sente que cresceu de repente? Introduza os novos números no Registo de Desenvolvimento e veja com orgulho a subida do gráfico de crescimento.', title_sv = 'Har kläderna blivit för små igen? 📏', body_sv = 'Känner du att barnet plötsligt har vuxit? Skriv in de nya siffrorna i Tillväxtspåraren och titta med stolthet på hur tillväxtkurvan stiger.', title_vi = 'Quần áo lại chật rồi? 📏', body_vi = 'Mẹ thấy bé bỗng dưng cao vọt? Hãy nhập số đo mới vào Theo dõi phát triển và tự hào ngắm biểu đồ phát triển đi lên.', title_zh = '衣服又变小了？📏', body_zh = '感觉他突然长高了？在发育追踪里输入新数字，自豪地看看成长曲线的上升吧。' WHERE id = '36ae8436-7cda-46ec-b16d-44295bf2f7bc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Fotos tiernas 📸', body_es = '¿Intenta saltar o bailar? Decora este momento con los marcos divertidos de la Sesión de fotos del bebé y crea un recuerdo para toda la vida.', title_fr = 'De jolies photos 📸', body_fr = 'Il essaie de sauter ou de danser ? Décorez ce moment avec les cadres joyeux de la Séance photo bébé et créez un souvenir pour la vie.', title_hi = 'प्यारी तस्वीरें 📸', body_hi = 'कूदने या नाचने की कोशिश करता है? इस पल को बेबी फ़ोटोशूट के खुशनुमा फ़्रेम से सजाकर उम्रभर की याद बना लीजिए।', title_id = 'Foto-foto manis 📸', body_id = 'Ia mencoba melompat atau berjoget? Hiasi momen ini dengan bingkai ceria di Sesi Foto Bayi dan jadikan kenangan seumur hidup.', title_ja = 'かわいい一枚 📸', body_ja = 'ジャンプしたり、踊ったりしようとしていますか？この瞬間を「ベビーフォトセッション」の楽しいフレームで飾って、一生の思い出にしましょう。', title_ko = '귀여운 한 컷 📸', body_ko = '점프하거나 춤추려고 하나요? 이 순간을 아기 사진 촬영의 즐거운 프레임으로 꾸며 평생의 추억을 만드세요.', title_nl = 'Lieve foto''s 📸', body_nl = 'Probeert je kindje te springen of te dansen? Versier dit moment met de vrolijke kaders in Babyfotoshoot en maak er een herinnering voor altijd van.', title_pl = 'Słodkie ujęcia 📸', body_pl = 'Próbuje skakać albo tańczyć? Ozdób tę chwilę wesołymi ramkami w Sesji zdjęciowej dziecka i stwórz wspomnienie na całe życie.', title_pt = 'Fotos doces 📸', body_pt = 'Tenta saltar ou dançar? Decore este momento com as molduras divertidas da Sessão Fotográfica do Bebé e crie uma recordação para toda a vida.', title_sv = 'Söta bilder 📸', body_sv = 'Försöker barnet hoppa eller dansa? Pynta ögonblicket med glada ramar i Babyfotografering och skapa ett minne för livet.', title_vi = 'Những khung hình đáng yêu 📸', body_vi = 'Bé thử nhảy lên hay nhún nhảy? Hãy trang trí khoảnh khắc này bằng những khung ảnh vui nhộn trong Chụp ảnh cho bé để tạo kỷ niệm trọn đời.', title_zh = '可爱的画面 📸', body_zh = '他在尝试蹦跳或跳舞？用宝宝写真里欢乐的相框装点这一刻，留下一辈子的回忆吧。' WHERE id = '909b1a9f-36d9-4ba3-a481-ae0e711ea145' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Podrían ser los dientes? 🤖', body_es = '¿Pierde el apetito o llora sin motivo? Pide a Anacan AI una opinión experta sobre las señales de que le están saliendo las muelas.', title_fr = 'Et si c''étaient les dents ? 🤖', body_fr = 'Il manque d''appétit ou pleure sans raison ? Demandez à Anacan AI l''avis d''un expert sur les signes de la poussée des molaires.', title_hi = 'क्या दाँत का दर्द हो सकता है? 🤖', body_hi = 'बिना वजह भूख नहीं लग रही या रो रहा है? दाढ़ें निकलने के लक्षणों के बारे में Anacan AI से विशेषज्ञ की राय पूछिए।', title_id = 'Mungkinkah sakit gigi? 🤖', body_id = 'Nafsu makannya turun atau ia menangis tanpa sebab? Minta pendapat ahli dari Anacan AI tentang tanda-tanda tumbuhnya geraham.', title_ja = '歯が痛いのかも？🤖', body_ja = '理由のわからない食欲不振や泣きがありますか？奥歯が生えるサインについて、Anacan AIに専門的な意見を聞いてみましょう。', title_ko = '이가 아픈 걸까요? 🤖', body_ko = '이유 없이 입맛이 없거나 우나요? 어금니가 나는 신호에 대해 Anacan AI에게 전문가 의견을 물어보세요.', title_nl = 'Kan het tandpijn zijn? 🤖', body_nl = 'Heeft je kindje zonder reden geen trek of huilt hij? Vraag Anacan AI om deskundig advies over de tekenen van doorkomende kiezen.', title_pl = 'Może to ból zęba? 🤖', body_pl = 'Bez powodu traci apetyt lub płacze? Zapytaj Anacan AI o opinię eksperta na temat objawów wyrzynania się trzonowców.', title_pt = 'Podem ser dores de dentes? 🤖', body_pt = 'Há falta de apetite ou choro sem razão aparente? Peça ao Anacan AI uma opinião de especialista sobre os sinais do nascimento dos molares.', title_sv = 'Kan det vara tandvärk? 🤖', body_sv = 'Har barnet dålig aptit eller gråter utan orsak? Fråga Anacan AI om ett expertutlåtande om tecknen på att kindtänderna kommer.', title_vi = 'Có thể là đau răng? 🤖', body_vi = 'Bé biếng ăn hay khóc vô cớ? Hãy hỏi ý kiến chuyên gia từ Anacan AI về các dấu hiệu mọc răng hàm.', title_zh = '会不会是牙疼？🤖', body_zh = '无缘无故没胃口，或者哭闹？向Anacan AI问问磨牙萌出的迹象，听听专家的意见。' WHERE id = '049ab226-ff27-4f2f-a64f-85d2b588c035' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasos seguros 👟', body_es = '¡Cada vez corre más rápido! Para sus primeros pasos con seguridad, echa un vistazo a los mejores modelos de calzado ortopédico en Productos recomendados.', title_fr = 'Des pas en sécurité 👟', body_fr = 'Ses courses s''accélèrent ! Pour ses premiers pas assurés, jetez un œil aux meilleurs modèles de chaussures orthopédiques dans les Produits recommandés.', title_hi = 'सुरक्षित कदम 👟', body_hi = 'उसकी दौड़ तेज़ हो रही है! पहले भरोसेमंद कदमों के लिए सुझाए गए प्रोडक्ट सेक्शन में सबसे अच्छे ऑर्थोपेडिक जूतों के मॉडल देखिए।', title_id = 'Langkah yang aman 👟', body_id = 'Larinya makin kencang! Untuk langkah mantap pertamanya, lihat model sepatu ortopedi terbaik di bagian Produk Rekomendasi.', title_ja = '安全な足取り 👟', body_ja = '走るのがどんどん速くなっています！自信をもって走り回るために、「おすすめ商品」でいちばん人気の足にやさしい靴を見てみましょう。', title_ko = '안전한 걸음 👟', body_ko = '뛰는 속도가 빨라지고 있어요! 자신 있게 걷고 뛸 수 있도록 추천 제품 섹션에서 가장 좋은 발 건강 신발을 둘러보세요.', title_nl = 'Veilige stapjes 👟', body_nl = 'Je kindje rent steeds sneller! Bekijk voor de eerste zekere stappen de beste orthopedische schoenen in het onderdeel Aanbevolen producten.', title_pl = 'Bezpieczne kroki 👟', body_pl = 'Biega coraz szybciej! Na pierwsze pewne kroki przejrzyj najlepsze modele butów ortopedycznych w sekcji Polecane produkty.', title_pt = 'Passos seguros 👟', body_pt = 'As corridas estão mais rápidas! Para os primeiros passos confiantes, espreite os melhores modelos de sapatos ortopédicos na secção Produtos Recomendados.', title_sv = 'Säkra steg 👟', body_sv = 'Springturerna blir snabbare! Titta på de bästa ortopediska skomodellerna för de första säkra stegen i avsnittet Rekommenderade produkter.', title_vi = 'Những bước đi an toàn 👟', body_vi = 'Bé chạy ngày càng nhanh! Để có những bước đi tự tin đầu tiên, hãy xem những mẫu giày chỉnh hình tốt nhất trong mục Sản phẩm gợi ý.', title_zh = '安全的每一步 👟', body_zh = '他跑得越来越快！为了自信地迈出步伐，看看推荐商品里最好的矫形鞋款吧。' WHERE id = '0e73fb38-1702-4d44-8a47-bf821e795ce5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un legado para el futuro 🖼️', body_es = '¿Has añadido al Álbum del bebé eso que hizo hoy y que más te hizo reír? Aunque se llene la memoria del móvil, los recuerdos estarán siempre a salvo.', title_fr = 'Un héritage pour l''avenir 🖼️', body_fr = 'Avez-vous ajouté à l''Album de bébé ce qui vous a le plus fait rire aujourd''hui ? Même si la mémoire du téléphone est pleine, vos souvenirs restent toujours en sécurité.', title_hi = 'भविष्य के लिए विरासत 🖼️', body_hi = 'आज की वह हरकत, जिसने आपको सबसे ज़्यादा हँसाया, बेबी एल्बम में जोड़ी? फ़ोन की मेमोरी भर जाए, तब भी यादें हमेशा सुरक्षित रहें।', title_id = 'Warisan untuk masa depan 🖼️', body_id = 'Sudah menambahkan tingkah yang paling membuat Anda tertawa hari ini ke Album Bayi? Meski memori ponsel penuh, kenangan Anda tetap aman.', title_ja = '未来へのおくりもの 🖼️', body_ja = '今日いちばん笑った瞬間を「ベビーアルバム」に追加しましたか？スマホの容量がいっぱいになっても、思い出はいつも安全に残せます。', title_ko = '미래를 위한 선물 🖼️', body_ko = '오늘 가장 많이 웃게 한 그 행동을 아기 앨범에 추가했나요? 휴대폰 저장 공간이 가득 차도 추억은 언제나 안전하게 남아 있도록요.', title_nl = 'Een erfenis voor later 🖼️', body_nl = 'Heb je het moment waar je vandaag het hardst om moest lachen al in het Babyalbum gezet? Ook als je telefoon vol raakt, blijven je herinneringen altijd veilig.', title_pl = 'Pamiątka na przyszłość 🖼️', body_pl = 'Dodałaś do Albumu dziecka to, co najbardziej cię dziś rozśmieszyło? Nawet gdy pamięć telefonu się zapełni, wspomnienia zawsze będą bezpieczne.', title_pt = 'Uma herança para o futuro 🖼️', body_pt = 'Já adicionou ao Álbum do Bebé aquele gesto que hoje mais a fez rir? Mesmo que a memória do telemóvel fique cheia, as recordações ficam sempre seguras.', title_sv = 'Ett arv till framtiden 🖼️', body_sv = 'Har du lagt till det som fick dig att skratta mest i dag i Babyalbumet? Även om telefonens minne blir fullt ska minnena alltid vara i säkerhet.', title_vi = 'Di sản cho tương lai 🖼️', body_vi = 'Mẹ đã thêm hành động khiến mẹ cười nhiều nhất hôm nay vào Album của bé chưa? Dù bộ nhớ điện thoại có đầy, kỷ niệm vẫn luôn được an toàn.', title_zh = '留给未来的财富 🖼️', body_zh = '今天最让你发笑的那个动作加进宝宝相册了吗？就算手机内存满了，回忆也能一直安全保存。' WHERE id = '2606521b-da76-4e40-8b9b-74eaed8f4900' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juguetes de lógica 🧩', body_es = 'Cerca de los 18,5 meses es el momento ideal para los juegos de lógica. Descubre en Productos recomendados puzles y cubos adecuados a su edad.', title_fr = 'Jouets de logique 🧩', body_fr = 'À l''approche des 18,5 mois, c''est le moment idéal pour les jeux de logique. Découvrez dans les Produits recommandés des puzzles et des cubes adaptés à son âge.', title_hi = 'तर्क वाले खिलौने 🧩', body_hi = '18.5 महीने के आसपास का समय तर्क वाले खेलों के लिए सबसे सही है। सुझाए गए प्रोडक्ट में उम्र के हिसाब से पज़ल और ब्लॉक खोजिए।', title_id = 'Mainan logika 🧩', body_id = 'Menjelang 18,5 bulan adalah waktu ideal untuk permainan logika. Temukan puzzle dan balok yang sesuai usianya di Produk Rekomendasi.', title_ja = '考える力を育てるおもちゃ 🧩', body_ja = '1歳6か月半ごろは、考える遊びにぴったりの時期です。「おすすめ商品」で年齢に合ったパズルや積み木を見つけましょう。', title_ko = '논리 장난감 🧩', body_ko = '18.5개월을 앞둔 지금이 논리 놀이에 딱 좋은 때예요. 추천 제품에서 나이에 맞는 퍼즐과 블록을 찾아보세요.', title_nl = 'Denkspeelgoed 🧩', body_nl = 'Rond 18,5 maanden is de ideale tijd voor denkspelletjes. Ontdek in Aanbevolen producten puzzels en blokken die passen bij zijn leeftijd.', title_pl = 'Zabawki logiczne 🧩', body_pl = 'Okolice 18,5 miesiąca to idealny czas na zabawy logiczne. Odkryj w Polecanych produktach układanki i klocki odpowiednie do wieku.', title_pt = 'Brinquedos de lógica 🧩', body_pt = 'Perto dos 18,5 meses é a altura ideal para jogos de lógica. Descubra nos Produtos Recomendados puzzles e cubos adequados à idade.', title_sv = 'Logikleksaker 🧩', body_sv = 'Runt 18,5 månader är en perfekt tid för logiklekar. Upptäck åldersanpassade pussel och klossar i Rekommenderade produkter.', title_vi = 'Đồ chơi tư duy 🧩', body_vi = 'Gần 18,5 tháng là thời điểm lý tưởng cho các trò chơi tư duy. Hãy khám phá những bộ xếp hình và khối gỗ phù hợp lứa tuổi trong Sản phẩm gợi ý.', title_zh = '逻辑玩具 🧩', body_zh = '快到18.5个月了，正是玩逻辑游戏的好时候。在推荐商品里发现适合年龄的拼图和积木吧。' WHERE id = '1e433a5c-ee68-4089-bf86-5ce74fde7136' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ritmo de crecimiento 📈', body_es = 'Analiza su ritmo de crecimiento con el Seguimiento del desarrollo. Comprueba en la gráfica si su altura y su peso están dentro de lo normal.', title_fr = 'Le rythme de croissance 📈', body_fr = 'Analysez son rythme de croissance dans le Suivi de croissance. Vérifiez sur la courbe que sa taille et son poids sont dans la norme.', title_hi = 'बढ़ने की रफ़्तार 📈', body_hi = 'ग्रोथ ट्रैकर टूल में विकास की रफ़्तार का विश्लेषण कीजिए। चार्ट में देखिए कि लंबाई और वज़न मानक के अनुसार हैं।', title_id = 'Laju pertumbuhan 📈', body_id = 'Analisis laju pertumbuhannya dengan Pelacak Pertumbuhan. Pantau di grafik apakah tinggi dan beratnya sesuai standar.', title_ja = '成長のスピード 📈', body_ja = '「発達トラッカー」で成長のスピードを分析しましょう。身長と体重が目安に合っているか、グラフで見守りましょう。', title_ko = '성장 속도 📈', body_ko = '성장 기록 도구로 발달 속도를 분석하세요. 키와 몸무게가 정상 범위인지 그래프로 확인할 수 있어요.', title_nl = 'Groeitempo 📈', body_nl = 'Analyseer zijn groeitempo in de tool Groeitracker. Volg in de grafiek of zijn lengte en gewicht binnen de norm vallen.', title_pl = 'Tempo wzrostu 📈', body_pl = 'Przeanalizuj tempo rozwoju w narzędziu Śledzenie rozwoju. Sprawdzaj na wykresie, czy wzrost i waga mieszczą się w normie.', title_pt = 'O ritmo de crescimento 📈', body_pt = 'Analise o ritmo de crescimento no Registo de Desenvolvimento. Acompanhe no gráfico se a altura e o peso estão dentro do normal.', title_sv = 'Tillväxttakt 📈', body_sv = 'Analysera tillväxttakten i verktyget Tillväxtspåraren. Följ i diagrammet om längd och vikt följer normen.', title_vi = 'Tốc độ phát triển 📈', body_vi = 'Hãy phân tích tốc độ phát triển bằng công cụ Theo dõi phát triển. Theo dõi trên biểu đồ xem chiều cao và cân nặng có đạt chuẩn không.', title_zh = '成长速度 📈', body_zh = '在发育追踪工具里分析成长速度。从图表上看看身高和体重是否符合参考范围。' WHERE id = '9d69d283-cfae-47a2-a874-8fabcc20a7f1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Olas que calman 🌊', body_es = 'Un cerebro sobreestimulado necesita bajar el ritmo. Calma a tu peque poniendo el sonido de las olas del mar en Ruido blanco.', title_fr = 'Des vagues apaisantes 🌊', body_fr = 'Un cerveau trop stimulé a besoin de ralentir. Apaisez-le en lançant le bruit des vagues de l''océan dans les Bruits blancs.', title_hi = 'शांत करने वाली लहरें 🌊', body_hi = 'ज़रूरत से ज़्यादा उत्तेजित दिमाग को धीमा करना ज़रूरी है। कमरे में व्हाइट नॉइज़ से समुद्र की लहरों की आवाज़ चलाकर उसे शांत कीजिए।', title_id = 'Ombak yang menenangkan 🌊', body_id = 'Otak yang terlalu banyak terstimulasi perlu diperlambat. Tenangkan ia dengan memutar suara ombak laut dari Suara Putih di kamar.', title_ja = '心落ち着く波の音 🌊', body_ja = '刺激を受けすぎた脳は、ペースを落とす必要があります。部屋で「ホワイトノイズ」から波の音を流して、落ち着かせてあげましょう。', title_ko = '마음을 달래 주는 파도 🌊', body_ko = '자극을 너무 많이 받은 뇌는 속도를 늦춰 줘야 해요. 방에 백색소음의 파도 소리를 틀어 아이를 진정시켜 주세요.', title_nl = 'Rustgevende golven 🌊', body_nl = 'Een overprikkeld hoofdje moet tot rust komen. Zet in Witte ruis het geluid van de oceaangolven aan in de kamer en kalmeer hem.', title_pl = 'Kojące fale 🌊', body_pl = 'Przestymulowany mózg trzeba wyciszyć. Włącz w pokoju fale oceanu z Białego szumu i go uspokój.', title_pt = 'Ondas calmantes 🌊', body_pt = 'Um cérebro com estímulos a mais precisa de abrandar. Ligue no quarto o som das ondas do mar no Ruído Branco e acalme-o.', title_sv = 'Lugnande vågor 🌊', body_sv = 'En överstimulerad hjärna behöver sakta ner. Lugna barnet genom att sätta på havsvågor i Vitt brus i rummet.', title_vi = 'Những con sóng êm dịu 🌊', body_vi = 'Bộ não bị kích thích quá mức cần được chậm lại. Hãy bật tiếng sóng biển trong Tiếng ồn trắng để giúp bé dịu lại.', title_zh = '舒缓的海浪 🌊', body_zh = '受到过度刺激的大脑需要慢下来。在房间里用白噪音放海浪声，让他平静下来。' WHERE id = '58a79bee-96dd-429b-a570-14dc6d97d91a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¿Qué es esto?» 🤖', body_es = '¿Te sorprenden sus preguntas sin fin y sus ganas de descubrirlo todo? Infórmate sobre este salto cognitivo con nuestro asistente Anacan AI.', title_fr = 'La période du « C''est quoi ? » 🤖', body_fr = 'Ses questions sans fin et sa soif de découvertes vous surprennent ? Renseignez-vous sur ce bond cognitif auprès de notre assistant Anacan AI.', title_hi = '''यह क्या है?'' का दौर 🤖', body_hi = 'बच्चे के कभी न खत्म होने वाले सवाल और खोजने की ललक आपको हैरान करती है? इस संज्ञानात्मक छलांग के बारे में हमारे Anacan AI असिस्टेंट से जानकारी लीजिए।', title_id = 'Fase "Ini apa?" 🤖', body_id = 'Takjub dengan pertanyaannya yang tak ada habisnya dan rasa ingin tahunya? Dapatkan informasi tentang lompatan kognitif ini dari asisten Anacan AI kami.', title_ja = '「これなあに？」の時期 🤖', body_ja = '終わらない質問と探究心に驚いていますか？この知能の飛躍について、Anacan AIアシスタントに聞いてみましょう。', title_ko = '"이게 뭐야?" 단계 🤖', body_ko = '끝없는 질문과 탐구심에 놀라고 있나요? 이 인지 도약에 대해 Anacan AI 도우미에게 알아보세요.', title_nl = 'De wat-is-dat-fase 🤖', body_nl = 'Sta je versteld van de eindeloze vragen en de ontdekkingsdrang van je kindje? Lees bij onze assistent Anacan AI meer over deze sprong in zijn verstand.', title_pl = 'Etap „Co to jest?” 🤖', body_pl = 'Zaskakują cię jego niekończące się pytania i ciekawość świata? Dowiedz się więcej o tym skoku poznawczym od naszego asystenta Anacan AI.', title_pt = 'A fase do "O que é isto?" 🤖', body_pt = 'As perguntas sem fim e a vontade de descobrir da criança surpreendem-na? Receba informação sobre este salto cognitivo do nosso assistente Anacan AI.', title_sv = 'Fasen ”Vad är det?” 🤖', body_sv = 'Förvånas du av barnets oändliga frågor och upptäckarlust? Få information om detta kognitiva språng från vår assistent Anacan AI.', title_vi = 'Giai đoạn "Cái gì đây?" 🤖', body_vi = 'Những câu hỏi không dứt và sự tò mò khám phá của bé khiến mẹ ngạc nhiên? Hãy tìm hiểu về bước nhảy nhận thức này cùng trợ lý Anacan AI.', title_zh = '“这是什么？”阶段 🤖', body_zh = '孩子没完没了的问题和探索欲让你惊讶？向我们的Anacan AI助手了解这次认知飞跃吧。' WHERE id = 'cf7f3cf6-5b3a-46ef-aef0-f4f77d4245e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere comer solo 🥣', body_es = '¿No suelta la cuchara? Activa el temporizador de tomas, sigue cuánto dura la comida y elige en Recetas para bebé alimentos fáciles de coger.', title_fr = 'Il veut manger seul 🥣', body_fr = 'Il ne lâche plus sa cuillère ? Lancez le minuteur des repas, suivez la durée du repas et choisissez dans les Recettes pour bébés des aliments faciles à attraper.', title_hi = 'खुद खाना चाहता है 🥣', body_hi = 'चम्मच हाथ से नहीं छोड़ता? फ़ीडिंग टाइमर चालू कीजिए, प्रक्रिया की अवधि पर नज़र रखिए और बच्चों की रेसिपी से आसानी से पकड़े जाने वाले खाने चुनिए।', title_id = 'Ingin makan sendiri 🥣', body_id = 'Sendok tak mau lepas dari tangannya? Nyalakan Timer Makan, pantau durasinya, dan pilih makanan yang mudah dipegang dari Resep Bayi.', title_ja = '自分で食べたい 🥣', body_ja = 'スプーンを手から離さない？食事タイマーをオンにして食事時間を見守り、ベビーレシピから持ちやすい料理を選びましょう。', title_ko = '혼자 먹고 싶어 해요 🥣', body_ko = '숟가락을 손에서 놓지 않나요? 수유 타이머를 켜서 먹는 시간을 살펴보고, 아기 레시피에서 집기 쉬운 음식을 골라 보세요.', title_nl = 'Wil zelf eten 🥣', body_nl = 'Laat je kindje de lepel niet los? Zet de voedingstimer aan, volg hoe lang het duurt en kies in de babyrecepten eten dat makkelijk vast te pakken is.', title_pl = 'Chce jeść sam 🥣', body_pl = 'Nie wypuszcza łyżeczki z ręki? Włącz timer karmienia, śledź czas posiłku i wybierz z Przepisów dla maluszka dania, które łatwo chwycić.', title_pt = 'Quer comer sozinho 🥣', body_pt = 'Não larga a colher? Ligue o temporizador de alimentação, acompanhe a duração da refeição e escolha nas Receitas para bebés alimentos fáceis de agarrar.', title_sv = 'Vill äta själv 🥣', body_sv = 'Släpper barnet inte skeden? Starta matningstimern, följ hur lång tid det tar och välj mat som är lätt att hålla från Babyrecept.', title_vi = 'Bé muốn tự ăn 🥣', body_vi = 'Bé không chịu rời chiếc thìa? Hãy bật bộ hẹn giờ trong Theo dõi cữ bú, theo dõi thời gian ăn và chọn những món dễ cầm trong Công thức cho bé.', title_zh = '想自己吃饭 🥣', body_zh = '勺子不离手？打开喂养计时器记录用时，再从宝宝食谱里选些容易拿的食物吧。' WHERE id = 'f8ad5a51-f4c3-4fc4-8170-0775df79fe84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reserva de proteínas 🥚', body_es = '¡Las proteínas son imprescindibles para los músculos de un peque tan movido! Mide el equilibrio de su alimentación diaria con el Seguimiento de tomas y completa lo que falte.', title_fr = 'Le plein de protéines 🥚', body_fr = 'Les protéines sont indispensables aux muscles de votre petit qui bouge beaucoup ! Mesurez l''équilibre de son alimentation du jour avec le Suivi des repas et comblez les manques.', title_hi = 'प्रोटीन का भंडार 🥚', body_hi = 'चुलबुले नन्हे की मांसपेशियों के लिए प्रोटीन ज़रूरी है! फ़ीडिंग ट्रैकर से उसके रोज़ के खाने का संतुलन देखिए और कमियाँ पूरी कीजिए।', title_id = 'Cadangan protein 🥚', body_id = 'Protein itu wajib untuk otot si kecil yang aktif! Ukur keseimbangan makanan hariannya dengan alat Pemantau Makan dan lengkapi kekurangannya.', title_ja = 'たんぱく質をしっかり 🥚', body_ja = '活発なお子さんの筋肉には、たんぱく質が欠かせません！「栄養管理ツール」で毎日の栄養バランスを確認して、足りないものを補いましょう。', title_ko = '단백질 창고 🥚', body_ko = '활발한 아이의 근육에는 단백질이 꼭 필요해요! 수유 기록 도구로 하루 영양 균형을 확인하고 부족한 부분을 채워 주세요.', title_nl = 'Een voorraad eiwit 🥚', body_nl = 'Eiwit is onmisbaar voor de spiertjes van je beweeglijke kleintje! Meet zijn dagelijkse voedingsbalans met de Voedingstracker en vul aan wat ontbreekt.', title_pl = 'Zapas białka 🥚', body_pl = 'Białko jest niezbędne dla mięśni ruchliwego malucha! Sprawdź w narzędziu do śledzenia karmienia jego dzienny bilans żywieniowy i uzupełnij braki.', title_pt = 'A reserva de proteína 🥚', body_pt = 'A proteína é essencial para os músculos do seu pequeno irrequieto! Meça o equilíbrio alimentar diário dele com o Registo de Alimentação e complete o que faltar.', title_sv = 'Proteinförråd 🥚', body_sv = 'Protein är en förutsättning för den lilla aktiva kroppens muskler! Mät den dagliga näringsbalansen med Matningskoll och fyll i det som saknas.', title_vi = 'Lượng protein 🥚', body_vi = 'Protein là điều kiện cần cho cơ bắp của em bé hiếu động! Hãy đo sự cân bằng dinh dưỡng hằng ngày bằng công cụ Theo dõi cữ bú và bổ sung những gì còn thiếu.', title_zh = '蛋白质储备 🥚', body_zh = '好动的小家伙肌肉生长离不开蛋白质！用喂养记录工具衡量他每天的饮食均衡，补上不足的部分吧。' WHERE id = '995604f6-97b2-4fe5-91ea-98f2248c1b28' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Atención y memoria 🧠', body_es = '¿Cómo aprende tu peque? Lee en el Blog de nuestra app el artículo sobre el desarrollo de la atención y la memoria a partir del año y medio.', title_fr = 'Attention et mémoire 🧠', body_fr = 'Comment votre enfant apprend-il ? Lisez dans les Blogs de l''application notre article sur le développement de l''attention et de la mémoire après 1 an et demi.', title_hi = 'ध्यान और याददाश्त 🧠', body_hi = 'आपका बच्चा कैसे सीखता है? हमारे ऐप के ब्लॉग सेक्शन में 1.5 साल के बाद ध्यान और याददाश्त के विकास पर लेख पढ़िए।', title_id = 'Perhatian dan ingatan 🧠', body_id = 'Bagaimana si kecil belajar? Baca artikel di bagian Blog aplikasi kami tentang perkembangan perhatian dan ingatan setelah usia 1,5 tahun.', title_ja = '集中力と記憶力 🧠', body_ja = 'お子さんはどうやって学んでいるのでしょう？アプリのブログで、1歳半以降の集中力と記憶力の発達についての記事を読んでみましょう。', title_ko = '집중력과 기억력 🧠', body_ko = '아기는 어떻게 배울까요? 앱의 블로그 섹션에서 1살 반 이후 집중력과 기억력 발달에 관한 글을 읽어 보세요.', title_nl = 'Aandacht en geheugen 🧠', body_nl = 'Hoe leert je kindje? Lees in het onderdeel Blogs van onze app het artikel over de ontwikkeling van aandacht en geheugen na 1,5 jaar.', title_pl = 'Uwaga i pamięć 🧠', body_pl = 'Jak uczy się twoje dziecko? Przeczytaj w sekcji Blogi w naszej aplikacji artykuł o rozwoju uwagi i pamięci po 1,5 roku.', title_pt = 'Atenção e memória 🧠', body_pt = 'Como aprende o seu bebé? Leia na secção Blogues da nossa app o artigo sobre o desenvolvimento da atenção e da memória depois de 1 ano e meio.', title_sv = 'Uppmärksamhet och minne 🧠', body_sv = 'Hur lär sig barnet? Läs artikeln i appens avsnitt Bloggar om hur uppmärksamhet och minne utvecklas efter 1,5 år.', title_vi = 'Chú ý và trí nhớ 🧠', body_vi = 'Bé học hỏi như thế nào? Hãy đọc bài viết về sự phát triển khả năng chú ý và trí nhớ sau 1,5 tuổi trong mục Blog của ứng dụng.', title_zh = '专注力与记忆力 🧠', body_zh = '宝宝是怎么学习的？读读我们应用博客板块里关于1岁半后专注力和记忆力发展的文章吧。' WHERE id = 'ec6ff433-9523-4a66-a427-b2548807345b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El final del día 🌙', body_es = '¡A la cama! Activa el Temporizador de sueño, anota su rutina para asegurarte de que duerme lo que necesita y descansa.', title_fr = 'La fin de la journée 🌙', body_fr = 'Au lit ! Lancez le minuteur de sommeil, notez son rythme pour vous assurer qu''il dort suffisamment chaque jour, et reposez-vous.', title_hi = 'दिन का अंत 🌙', body_hi = 'सोने चलें! स्लीप टाइमर चालू कीजिए, यह पक्का करने के लिए कि वह रोज़ की नींद का मानक पूरा कर रहा है, रूटीन दर्ज कीजिए और आराम कीजिए।', title_id = 'Akhir hari 🌙', body_id = 'Waktunya tidur! Nyalakan Timer Tidur, catat rutinitasnya untuk memastikan kebutuhan tidur hariannya terpenuhi, lalu beristirahatlah.', title_ja = '一日の終わり 🌙', body_ja = 'さあ、ねんねの時間！睡眠タイマーをオンにして、1日の睡眠量の目安を守れているかリズムを記録し、ゆっくり休みましょう。', title_ko = '하루의 끝 🌙', body_ko = '잘 시간이에요! 수면 타이머를 켜고 하루 수면량을 잘 지키는지 일과를 기록한 뒤 쉬세요.', title_nl = 'Het einde van de dag 🌙', body_nl = 'Tijd voor bed! Zet de Slaaptimer aan, noteer zijn ritme om zeker te zijn dat hij zijn dagelijkse slaap haalt, en rust uit.', title_pl = 'Koniec dnia 🌙', body_pl = 'Idziemy spać! Włącz timer snu, zapisuj jego rytm, by mieć pewność, że trzyma się dziennej normy snu, i odpocznij.', title_pt = 'O fim do dia 🌙', body_pt = 'Vamos para a cama! Ligue o temporizador de sono, registe a rotina para confirmar que cumpre as horas de sono diárias recomendadas e descanse.', title_sv = 'Dagens slut 🌙', body_sv = 'Vi går och lägger oss! Starta sömntimern, anteckna rutinen för att försäkra dig om att barnet når sin dagliga sömnnorm och vila.', title_vi = 'Cuối ngày 🌙', body_vi = 'Đi ngủ thôi! Hãy bật Bộ hẹn giờ ngủ, ghi lại nếp sinh hoạt để chắc chắn bé ngủ đủ định mức hằng ngày, rồi nghỉ ngơi nhé.', title_zh = '一天的尾声 🌙', body_zh = '准备上床啦！打开睡眠计时器，记录他的作息，确认达到了每日睡眠参考量，然后好好休息吧。' WHERE id = 'ef4e2662-a0c2-4758-a2d7-d0ebe8f23855' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Regresión del sueño? ⏱️', body_es = '¿Se despierta a menudo por la noche? Mira la gráfica del Temporizador de sueño. Si la siesta es demasiado larga, quizá sea el momento de acortarla un poco.', title_fr = 'Une régression du sommeil ? ⏱️', body_fr = 'Il se réveille souvent la nuit ? Consultez le graphique du minuteur de sommeil. Si la sieste est trop longue, il est peut-être temps de la raccourcir un peu.', title_hi = 'स्लीप रिग्रेशन? ⏱️', body_hi = 'रातों में बार-बार जागता है? स्लीप टाइमर का चार्ट देखिए। अगर दिन की झपकी बहुत लंबी है, तो उसे थोड़ा कम करने का समय आ गया होगा।', title_id = 'Regresi tidur? ⏱️', body_id = 'Ia sering terbangun di malam hari? Lihat grafik Timer Tidur. Kalau tidur siangnya terlalu lama, mungkin sudah waktunya sedikit dikurangi.', title_ja = '睡眠退行？⏱️', body_ja = '夜中によく起きますか？睡眠タイマーのグラフを見てみましょう。お昼寝が長すぎるなら、少し短くするタイミングかもしれません。', title_ko = '수면 퇴행일까요? ⏱️', body_ko = '밤에 자주 깨나요? 수면 타이머 그래프를 확인해 보세요. 낮잠이 너무 길다면 조금 줄일 때가 됐을 수도 있어요.', title_nl = 'Slaapterugval? ⏱️', body_nl = 'Wordt je kindje ''s nachts vaak wakker? Bekijk het schema van de Slaaptimer. Is het middagdutje te lang, dan is het misschien tijd om het iets in te korten.', title_pl = 'Regres snu? ⏱️', body_pl = 'W nocy często się budzi? Zajrzyj do wykresu timera snu. Jeśli drzemka w dzień jest za długa, może czas ją trochę skrócić.', title_pt = 'Regressão do sono? ⏱️', body_pt = 'Acorda muitas vezes de noite? Veja o gráfico do temporizador de sono. Se a sesta for demasiado longa, pode ser altura de a encurtar um pouco.', title_sv = 'Sömnregression? ⏱️', body_sv = 'Vaknar barnet ofta på nätterna? Titta på sömntimerns schema. Om dagsluren är för lång kan det vara dags att korta den lite.', title_vi = 'Thoái lui giấc ngủ? ⏱️', body_vi = 'Ban đêm bé hay thức giấc? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Nếu giấc ngủ ngày quá dài, có thể đã đến lúc rút ngắn một chút.', title_zh = '睡眠倒退？⏱️', body_zh = '夜里经常醒？看看睡眠计时器的图表。如果白天小睡太长，也许是时候稍微减少一点了。' WHERE id = '309ac2aa-7e4c-4fba-a6ae-8ce53ca7a9f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Depósito de calcio 🧀', body_es = 'El calcio es imprescindible para los dientes y los huesos. Comprueba con el Seguimiento de tomas si hoy ha tomado la cantidad adecuada de lácteos.', title_fr = 'Une réserve de calcium 🧀', body_fr = 'Le calcium est indispensable aux dents et aux os. Vérifiez précisément avec le Suivi des repas qu''il a eu sa ration de produits laitiers aujourd''hui.', title_hi = 'कैल्शियम का खज़ाना 🧀', body_hi = 'दाँतों और हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज डेयरी प्रोडक्ट का मानक पूरा हुआ।', title_id = 'Gudang kalsium 🧀', body_id = 'Kalsium itu wajib untuk gigi dan tulang. Pastikan dengan alat Pemantau Makan bahwa porsi produk susu hari ini sudah terpenuhi.', title_ja = 'カルシウムをたっぷり 🧀', body_ja = '歯と骨のためにカルシウムは欠かせません。「栄養管理ツール」で、今日の乳製品の目安を守れているか確認しましょう。', title_ko = '칼슘 창고 🧀', body_ko = '치아와 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 유제품 섭취량을 잘 지켰는지 확인하세요.', title_nl = 'Een voorraad calcium 🧀', body_nl = 'Calcium is onmisbaar voor tanden en botten. Controleer met de Voedingstracker of je de norm voor zuivel van vandaag haalt.', title_pl = 'Skarbnica wapnia 🧀', body_pl = 'Wapń jest niezbędny dla zębów i kości. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza norma nabiału jest osiągnięta.', title_pt = 'Uma reserva de cálcio 🧀', body_pt = 'O cálcio é essencial para os dentes e os ossos. Confirme com o Registo de Alimentação se hoje cumpriu a quantidade recomendada de laticínios.', title_sv = 'Kalciumförråd 🧀', body_sv = 'Kalcium är en förutsättning för tänderna och skelettet. Kontrollera med Matningskoll att dagens norm för mejeriprodukter nås.', title_vi = 'Kho canxi 🧀', body_vi = 'Canxi là điều kiện cần cho răng và xương. Hãy kiểm tra chính xác bằng công cụ Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức sản phẩm từ sữa chưa.', title_zh = '钙质补给站 🧀', body_zh = '钙对牙齿和骨骼必不可少。用喂养记录工具确认今天的奶制品是否达到了参考量。' WHERE id = '6cc3ddd9-74b8-4e89-bf39-abc72a3548c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Equilibrio diario 💧', body_es = '¡No olvides anotarlo al cambiar el pañal del mediodía! La frecuencia de las cacas muestra cuánto líquido necesita según lo que se mueve y cómo va su digestión.', title_fr = 'L''équilibre du jour 💧', body_fr = 'N''oubliez pas de noter le change de midi ! La fréquence des selles renseigne sur ses besoins en liquides liés à son activité et sur sa digestion.', title_hi = 'रोज़ का संतुलन 💧', body_hi = 'दोपहर का डायपर बदलते समय दर्ज करना मत भूलिए! पॉटी कितनी बार होती है, यह उसकी भाग-दौड़ से जुड़ी तरल की ज़रूरत और पाचन को दिखाता है।', title_id = 'Keseimbangan harian 💧', body_id = 'Jangan lupa mencatat saat mengganti popok siang! Frekuensi BAB menunjukkan kebutuhan cairan dan kondisi pencernaannya sesuai aktivitasnya.', title_ja = '毎日のバランス 💧', body_ja = 'お昼のおむつ替えも記録するのを忘れずに！うんちの回数で、活発に動くお子さんに必要な水分量や消化の様子がわかります。', title_ko = '하루 균형 💧', body_ko = '점심 기저귀를 갈 때 기록하는 걸 잊지 마세요! 배변 횟수는 활동량에 따른 수분 필요량과 소화 상태를 보여 줘요.', title_nl = 'Dagelijkse balans 💧', body_nl = 'Vergeet niet de middagluier te noteren! Hoe vaak je kindje plast en poept, laat zien hoeveel vocht hij door al dat bewegen nodig heeft en hoe zijn spijsvertering werkt.', title_pl = 'Codzienny bilans 💧', body_pl = 'Nie zapomnij zapisać popołudniowej zmiany pieluszki! Częstotliwość wypróżnień pokazuje, ile płynów potrzebuje ruchliwy maluch i jak działa jego trawienie.', title_pt = 'O equilíbrio diário 💧', body_pt = 'Não se esqueça de registar a fralda ao mudá-la à hora de almoço! A frequência das dejeções mostra a digestão e a necessidade de líquidos ligada à atividade da criança.', title_sv = 'Daglig balans 💧', body_sv = 'Glöm inte att anteckna eftermiddagens blöjbyte! Hur ofta barnet bajsar visar vätskebehovet i förhållande till aktiviteten och matsmältningen.', title_vi = 'Cân bằng mỗi ngày 💧', body_vi = 'Đừng quên ghi lại khi thay tã buổi trưa! Tần suất đi vệ sinh cho biết nhu cầu nước theo mức độ vận động và tình trạng tiêu hóa của bé.', title_zh = '每日平衡 💧', body_zh = '换中午的尿布时别忘了记录！便便的频率能反映孩子活动量带来的水分需求和消化情况。' WHERE id = 'ec0d2d5d-31ad-48a9-8c47-f6c4eeeace11' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ahora te toca a ti 🥗', body_es = '¿Se ha dormido la siesta? ¡A la cocina! Prepárate algo rico de Recetas saludables para mujeres.', title_fr = 'Maintenant, c''est votre tour 🥗', body_fr = 'Il fait la sieste ? Direction la cuisine ! Préparez-vous une portion savoureuse grâce aux Recettes saines pour femmes.', title_hi = 'अब आपकी बारी है 🥗', body_hi = 'बच्चा दिन की झपकी लेने गया? रसोई में चलिए! महिलाओं के लिए सेहतमंद रेसिपी से अपने लिए कुछ स्वादिष्ट बनाइए।', title_id = 'Sekarang giliran Anda 🥗', body_id = 'Si kecil sudah tidur siang? Pergilah ke dapur! Siapkan hidangan lezat untuk diri sendiri dari Resep Sehat untuk wanita.', title_ja = '今度はあなたの番 🥗', body_ja = 'お昼寝が始まりましたか？キッチンへ行きましょう！「女性のためのヘルシーレシピ」から、自分のためにおいしい一品をつくりましょう。', title_ko = '이제 엄마 차례예요 🥗', body_ko = '아이가 낮잠을 자나요? 부엌으로 가세요! 건강한 레시피에서 나를 위한 맛있는 한 끼를 만들어 보세요.', title_nl = 'Nu ben jij aan de beurt 🥗', body_nl = 'Doet je kindje zijn middagdutje? Ga naar de keuken! Maak uit Gezonde recepten voor vrouwen een lekkere portie voor jezelf.', title_pl = 'Teraz twoja kolej 🥗', body_pl = 'Maluszek poszedł na drzemkę? Idź do kuchni! Przygotuj sobie smaczne danie ze Zdrowych przepisów dla kobiet.', title_pt = 'Agora é a sua vez 🥗', body_pt = 'Ele foi fazer a sesta? Vá até à cozinha! Prepare para si uma refeição deliciosa das Receitas Saudáveis para Mulheres.', title_sv = 'Nu är det din tur 🥗', body_sv = 'Har barnet somnat för dagsluren? Gå till köket! Gör en god portion åt dig själv från Hälsosamma recept för kvinnor.', title_vi = 'Giờ đến lượt mẹ 🥗', body_vi = 'Bé đã ngủ trưa? Mẹ vào bếp thôi! Hãy làm cho mình một phần ăn ngon miệng từ Công thức lành mạnh cho phụ nữ.', title_zh = '现在轮到你了 🥗', body_zh = '宝宝去睡午觉了？快去厨房！从女性健康食谱里给自己做一份美味的餐点吧。' WHERE id = '44008632-a96c-4f5e-a936-9b65273a2264' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa para el café ☕', body_es = '¿Te han agotado las tareas de casa y la rutina? Encuentra en Lugares para mamás una cafetería con rincón infantil. Tomarte un café calentito es tu derecho más natural.', title_fr = 'Pause café ☕', body_fr = 'Les tâches ménagères et la routine vous ont épuisée ? Trouvez dans les Lieux adaptés aux mamans un café avec un coin enfants. Boire un café chaud, c''est votre droit le plus naturel.', title_hi = 'कॉफ़ी ब्रेक ☕', body_hi = 'घर के काम और रूटीन ने थका दिया? माँ के लिए अनुकूल जगहों में बच्चों के कोने वाला कोई कैफ़े ढूँढिए। गरम कॉफ़ी पीना आपका सबसे स्वाभाविक हक है।', title_id = 'Rehat kopi ☕', body_id = 'Lelah dengan pekerjaan rumah dan rutinitas? Temukan kafe dengan area bermain anak di Tempat Ramah Ibu. Menikmati kopi hangat adalah hak Anda yang paling wajar.', title_ja = 'コーヒーブレイク ☕', body_ja = '家事や毎日の繰り返しに疲れましたか？「ママにやさしいスポット」でキッズスペースのあるカフェを見つけましょう。温かいコーヒーを飲むのは、あなたの当然の権利です。', title_ko = '커피 타임 ☕', body_ko = '집안일과 반복되는 일상에 지쳤나요? 엄마 친화 장소에서 키즈 공간이 있는 카페를 찾아보세요. 따뜻한 커피 한 잔은 엄마의 당연한 권리예요.', title_nl = 'Koffiepauze ☕', body_nl = 'Ben je moe van het huishouden en de routine? Zoek in Mamavriendelijke plekken een café met een kinderhoek. Een warme kop koffie heb je dubbel en dwars verdiend.', title_pl = 'Przerwa na kawę ☕', body_pl = 'Prace domowe i rutyna cię zmęczyły? Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem dla dzieci. Gorąca kawa to twoje najbardziej naturalne prawo.', title_pt = 'Pausa para o café ☕', body_pt = 'As tarefas de casa e a rotina cansaram-na? Encontre nos Locais Amigos das Mães um café com espaço infantil. Beber um café quente é um direito seu, mais do que natural.', title_sv = 'Kaffepaus ☕', body_sv = 'Har hushållet och rutinen tröttat ut dig? Hitta ett kafé med lekhörna i Mammavänliga platser. Att dricka ett varmt kaffe är din självklara rätt.', title_vi = 'Giờ nghỉ cà phê ☕', body_vi = 'Việc nhà và nếp sinh hoạt khiến mẹ mệt mỏi? Hãy tìm một quán cà phê có góc vui chơi cho trẻ trong Địa điểm thân thiện với mẹ. Thưởng thức một tách cà phê nóng là quyền đương nhiên của mẹ.', title_zh = '咖啡时间 ☕', body_zh = '家务和日常让你累了？在妈妈友好场所里找一家有儿童角的咖啡馆。喝一杯热咖啡，是你最天经地义的权利。' WHERE id = '868f8ace-292a-4cf1-9abe-4b2da08aca3f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No existe la madre perfecta 💖', body_es = 'Si hoy no ha salido todo como lo planeabas, no te culpes. Escribe tus agobios en el Diario de ánimo y respira tranquila.', title_fr = 'La maman parfaite n''existe pas 💖', body_fr = 'Si tout ne s''est pas passé comme prévu aujourd''hui, ne vous blâmez pas. Écrivez ce qui vous pèse dans le Journal d''humeur et respirez librement.', title_hi = 'परफ़ेक्ट माँ कोई नहीं होती 💖', body_hi = 'अगर आज सब कुछ योजना के मुताबिक नहीं हुआ, तो खुद को दोष मत दीजिए। मूड डायरी में अपनी अंदर की परेशानियाँ लिखिए और चैन की साँस लीजिए।', title_id = 'Tidak ada ibu yang sempurna 💖', body_id = 'Kalau hari ini tidak semuanya berjalan sesuai rencana, jangan menyalahkan diri sendiri. Tulis beban hati Anda di Buku Harian Suasana Hati dan bernapaslah dengan lega.', title_ja = '完璧なママなんていません 💖', body_ja = '今日すべてが計画どおりにいかなくても、自分を責めないで。「気分日記」に心のもやもやを書いて、ほっと息をつきましょう。', title_ko = '완벽한 엄마는 없어요 💖', body_ko = '오늘 모든 게 계획대로 되지 않았다면 자책하지 마세요. 기분 일기에 마음속 답답함을 적고 편히 숨 쉬세요.', title_nl = 'De perfecte moeder bestaat niet 💖', body_nl = 'Ging vandaag niet alles volgens plan? Wees niet streng voor jezelf. Schrijf wat je dwarszit op in je Stemmingsdagboek en haal opgelucht adem.', title_pl = 'Nie ma idealnych mam 💖', body_pl = 'Jeśli dziś nie wszystko poszło zgodnie z planem, nie obwiniaj się. Zapisz w Dzienniku nastroju, co cię gnębi, i odetchnij spokojnie.', title_pt = 'Não há mães perfeitas 💖', body_pt = 'Se hoje nem tudo correu como planeado, não se culpe. Escreva no Diário de Humor as suas angústias e respire tranquila.', title_sv = 'Det finns ingen perfekt mamma 💖', body_sv = 'Om inte allt gick enligt planen i dag, skuldbelägg inte dig själv. Skriv det som tynger dig i Humördagboken och andas ut.', title_vi = 'Không có người mẹ hoàn hảo 💖', body_vi = 'Nếu hôm nay mọi thứ không theo kế hoạch, đừng tự trách mình. Hãy viết những nỗi niềm trong lòng vào Nhật ký tâm trạng và thở phào nhẹ nhõm.', title_zh = '没有完美的妈妈 💖', body_zh = '如果今天一切都没按计划进行，别责怪自己。把内心的烦闷写进心情日记，轻松地呼吸吧。' WHERE id = 'f7b08a7d-5067-40df-81d3-421be952c00e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ecos de risas 📸', body_es = 'Añade al Álbum del bebé la foto más alegre que le hayas hecho trepando o jugando a pillar y convierte el cansancio del día en una sonrisa.', title_fr = 'Des éclats de rire 📸', body_fr = 'Ajoutez à l''Album de bébé la photo la plus joyeuse prise pendant qu''il grimpait ou courait partout, et transformez la fatigue de la journée en sourire.', title_hi = 'हँसी की गूँज 📸', body_hi = 'चढ़ते हुए या दौड़-भाग वाले खेल में खींची अपनी सबसे खुशनुमा फ़ोटो बेबी एल्बम में जोड़कर दिन की थकान को मुस्कान में बदल दीजिए।', title_id = 'Gema tawa 📸', body_id = 'Ubah lelah hari ini menjadi senyuman dengan menambahkan foto paling ceria saat ia memanjat atau bermain kejar-kejaran ke Album Bayi.', title_ja = '笑い声 📸', body_ja = 'よじ登ったり走り回ったりしているときに撮った、いちばん楽しい写真を「ベビーアルバム」に追加して、一日の疲れを笑顔に変えましょう。', title_ko = '웃음소리 📸', body_ko = '기어오르거나 뛰어놀 때 찍은 가장 즐거운 사진을 아기 앨범에 추가해 하루의 피로를 미소로 바꿔 보세요.', title_nl = 'Het geluid van gelach 📸', body_nl = 'Zet de vrolijkste foto die je maakte terwijl hij klom of rondrende in het Babyalbum en maak van de vermoeidheid van vandaag een glimlach.', title_pl = 'Odgłosy śmiechu 📸', body_pl = 'Dodaj do Albumu dziecka najweselsze zdjęcie zrobione, gdy się wspinał lub biegał, i zamień zmęczenie dnia w uśmiech.', title_pt = 'O som das gargalhadas 📸', body_pt = 'Adicione ao Álbum do Bebé a foto mais alegre que tirou enquanto ele trepava ou corria a brincar e transforme o cansaço do dia num sorriso.', title_sv = 'Ljudet av skratt 📸', body_sv = 'Lägg till den gladaste bilden du tog när barnet klättrade eller lekte jagalek i Babyalbumet och förvandla dagens trötthet till ett leende.', title_vi = 'Tiếng cười giòn tan 📸', body_vi = 'Hãy thêm bức ảnh vui nhất mẹ chụp khi bé leo trèo hay chạy nhảy vào Album của bé để biến mệt mỏi trong ngày thành nụ cười.', title_zh = '笑声不断 📸', body_zh = '把他爬上爬下、跑来跑去时拍下的最开心的照片加进宝宝相册，把一天的疲惫变成微笑吧。' WHERE id = '913b583d-e8e0-426f-a7cd-75ab8b1bc0b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigamos su crecimiento 📈', body_es = 'Se mueve mucho más. ¿Pero su aumento de peso es normal? Analiza su ritmo de crecimiento con el Registro de peso y olvídate de las preocupaciones.', title_fr = 'Suivons sa croissance 📈', body_fr = 'Il bouge davantage. Mais sa prise de poids est-elle dans la norme ? Analysez son rythme de croissance dans le Suivi du poids et dissipez vos inquiétudes.', title_hi = 'बढ़त पर नज़र रखें 📈', body_hi = 'उसकी शारीरिक सक्रियता बढ़ गई है। पर क्या वज़न सामान्य रूप से बढ़ रहा है? वेट ट्रैकर टूल में विकास की रफ़्तार का विश्लेषण करके चिंता दूर कीजिए।', title_id = 'Yuk, pantau pertumbuhannya 📈', body_id = 'Aktivitas fisiknya bertambah. Tapi apakah pertambahan beratnya normal? Analisis laju pertumbuhannya dengan Pelacak Berat Badan dan hilangkan kekhawatiran Anda.', title_ja = '成長を見守ろう 📈', body_ja = '体を動かすことが増えました。体重の増え方は目安どおり？「体重トラッカー」で成長のスピードを分析して、不安を解消しましょう。', title_ko = '성장을 지켜봐요 📈', body_ko = '활동량이 늘었어요. 그럼 몸무게는 잘 늘고 있을까요? 체중 기록 도구로 성장 속도를 분석하고 걱정을 덜어 내세요.', title_nl = 'Laten we de groei volgen 📈', body_nl = 'Hij beweegt meer. Maar groeit zijn gewicht nog volgens de norm? Analyseer zijn groeitempo in de tool Gewichtstracker en neem je zorgen weg.', title_pl = 'Śledźmy wzrost 📈', body_pl = 'Jest coraz bardziej aktywny fizycznie. A czy przyrost wagi jest w normie? Przeanalizuj tempo rozwoju w narzędziu Licznik wagi i rozwiej obawy.', title_pt = 'Vamos acompanhar o crescimento 📈', body_pt = 'A atividade física aumentou. Mas o aumento de peso está dentro do normal? Analise o ritmo de crescimento no Registo de Peso e afaste as preocupações.', title_sv = 'Vi följer tillväxten 📈', body_sv = 'Den fysiska aktiviteten har ökat. Men är viktökningen normal? Analysera tillväxttakten i verktyget Viktspåraren och bli av med oron.', title_vi = 'Cùng theo dõi bé lớn lên 📈', body_vi = 'Bé vận động nhiều hơn. Vậy cân nặng tăng có đạt chuẩn không? Hãy phân tích tốc độ phát triển bằng công cụ Theo dõi cân nặng để xua tan lo lắng.', title_zh = '关注成长 📈', body_zh = '他的活动量变大了。那体重增长在参考范围内吗？在体重记录工具里分析成长速度，打消顾虑吧。' WHERE id = 'ccbbf1c0-789d-4a84-96bd-cdb04c618d13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Pega y muerde? 🛑', body_es = 'Las emociones que no sabe expresar a veces se convierten en agresividad. Pregunta a Anacan AI cómo actuar cuando muerde o pega a esta edad.', title_fr = 'Il tape et il mord ? 🛑', body_fr = 'Les émotions qu''il n''arrive pas à exprimer se transforment parfois en agressivité. Demandez à Anacan AI comment réagir face aux morsures et aux coups à cet âge.', title_hi = 'मारना और काटना? 🛑', body_hi = 'जो भावनाएँ वह व्यक्त नहीं कर पाता, वे कभी-कभी आक्रामकता बन जाती हैं। इस उम्र में काटने और मारने पर कैसे पेश आएँ, Anacan AI से पूछिए।', title_id = 'Memukul dan menggigit? 🛑', body_id = 'Perasaan yang belum bisa ia ungkapkan kadang berubah menjadi agresi. Tanyakan ke Anacan AI bagaimana menghadapi perilaku menggigit dan memukul di usia ini.', title_ja = 'たたく、かみつく？🛑', body_ja = '言葉にできない気持ちが、ときに攻撃的な行動になることがあります。この時期のかみつきやたたきにどう対応すればいいか、Anacan AIに聞いてみましょう。', title_ko = '때리고 깨물어요? 🛑', body_ko = '표현하지 못한 감정이 가끔 공격적인 행동으로 나타나요. 이 시기에 깨물거나 때릴 때 어떻게 대처해야 할지 Anacan AI에게 물어보세요.', title_nl = 'Slaan en bijten? 🛑', body_nl = 'Gevoelens die je kindje niet kan uiten, worden soms agressie. Vraag Anacan AI hoe je op deze leeftijd reageert op bijten en slaan.', title_pl = 'Bicie i gryzienie? 🛑', body_pl = 'Emocje, których nie umie wyrazić, czasem zamieniają się w agresję. Zapytaj Anacan AI, jak reagować na gryzienie i bicie w tym wieku.', title_pt = 'Bater e morder? 🛑', body_pt = 'As emoções que não consegue expressar às vezes transformam-se em agressividade. Pergunte ao Anacan AI como agir perante mordidelas e pancadas nesta idade.', title_sv = 'Slå och bitas? 🛑', body_sv = 'Känslor som barnet inte kan uttrycka blir ibland till aggression. Fråga Anacan AI hur du ska agera när barnet bits och slår i den här åldern.', title_vi = 'Đánh và cắn? 🛑', body_vi = 'Những cảm xúc chưa diễn đạt được đôi khi biến thành hành vi hung hăng. Hãy hỏi Anacan AI nên ứng xử thế nào khi bé cắn và đánh ở độ tuổi này.', title_zh = '打人和咬人？🛑', body_zh = '表达不出来的情绪有时会变成攻击行为。问问Anacan AI，这个年龄段遇到咬人和打人时该怎么做。' WHERE id = '44418a3d-932e-44e2-832c-c9fdeea34df1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo nace el amor por los libros? 📖', body_es = '¿Leéis antes de dormir? Lee en nuestro Blog las reglas de oro para que los niños amen los libros y mantengan la atención en las páginas.', title_fr = 'Comment naît l''amour des livres ? 📖', body_fr = 'Vous lisez avant de dormir ? Découvrez dans nos Blogs les règles d''or pour faire aimer les livres aux enfants et garder leur attention sur les pages.', title_hi = 'किताबों से प्यार कैसे होता है? 📖', body_hi = 'सोने से पहले पढ़ती हैं? हमारे ब्लॉग सेक्शन में बच्चों को किताबों से प्यार कराने और उनका ध्यान पन्नों पर बनाए रखने के सुनहरे नियम पढ़िए।', title_id = 'Bagaimana menumbuhkan cinta buku? 📖', body_id = 'Membaca sebelum tidur? Di bagian Blog kami, baca aturan emas agar anak mencintai buku dan perhatiannya tetap tertuju pada halaman.', title_ja = '本好きはどうやって育つ？📖', body_ja = '寝る前に読み聞かせをしていますか？ブログで、子どもを本好きにして、ページに集中させるための黄金ルールを読んでみましょう。', title_ko = '책을 좋아하게 되려면? 📖', body_ko = '잠들기 전에 책을 읽어 주나요? 블로그 섹션에서 아이가 책을 좋아하게 하고 책장에 집중하게 하는 황금 규칙을 읽어 보세요.', title_nl = 'Hoe ontstaat liefde voor boeken? 📖', body_nl = 'Lees je voor het slapengaan voor? Lees in ons onderdeel Blogs de gouden regels om kinderen van boeken te laten houden en hun aandacht bij de bladzijden te houden.', title_pl = 'Jak rodzi się miłość do książek? 📖', body_pl = 'Czytacie przed snem? Przeczytaj w sekcji Blogi złote zasady, jak sprawić, by dziecko pokochało książki i skupiało uwagę na stronach.', title_pt = 'Como nasce o amor pelos livros? 📖', body_pt = 'Leem antes de dormir? Leia na nossa secção Blogues as regras de ouro para fazer as crianças gostarem de livros e manter a atenção delas nas páginas.', title_sv = 'Hur skapas kärleken till böcker? 📖', body_sv = 'Läser ni före sömnen? Läs i vårt avsnitt Bloggar de gyllene reglerna för att få barn att älska böcker och hålla uppmärksamheten på sidorna.', title_vi = 'Tình yêu sách được hình thành thế nào? 📖', body_vi = 'Mẹ có đọc sách cho bé trước giờ ngủ? Hãy đọc trong mục Blog những quy tắc vàng giúp bé yêu sách và giữ sự chú ý vào từng trang.', title_zh = '怎样培养对书的热爱？📖', body_zh = '睡前一起读书吗？读读我们博客板块里让孩子爱上书、把注意力留在书页上的黄金法则吧。' WHERE id = '4a287257-0f36-49cd-93f7-28a1154386a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Nuevos descubrimientos, nuevos peligros ⚠️', body_es = '¡Ya trepa por todas partes! Para aumentar la seguridad de casa, echa un vistazo en Productos recomendados a los protectores blandos para los bordes de los muebles.', title_fr = 'Nouvelles découvertes, nouveaux dangers ⚠️', body_fr = 'Il grimpe déjà partout ! Pour renforcer la sécurité de la maison, jetez absolument un œil aux protège-coins souples pour meubles dans les Produits recommandés.', title_hi = 'नई खोजें, नए खतरे ⚠️', body_hi = 'अब वह हर जगह चढ़ता है! घर की सुरक्षा बढ़ाने के लिए सुझाए गए प्रोडक्ट सेक्शन में फ़र्नीचर के किनारों के लिए नरम गार्ड ज़रूर देखिए।', title_id = 'Penemuan baru, bahaya baru ⚠️', body_id = 'Kini ia memanjat ke mana-mana! Untuk meningkatkan keamanan rumah, pastikan melihat pelindung sudut perabot yang empuk di bagian Produk Rekomendasi.', title_ja = '新しい発見と、新しい危険 ⚠️', body_ja = 'もうどこにでもよじ登ります！家の安全を高めるために、「おすすめ商品」で家具の角用のやわらかいガードをぜひチェックしましょう。', title_ko = '새로운 발견, 새로운 위험 ⚠️', body_ko = '이제 어디든 기어올라요! 집 안 안전을 높이려면 추천 제품 섹션에서 가구 모서리용 부드러운 보호대를 꼭 살펴보세요.', title_nl = 'Nieuwe ontdekkingen, nieuwe gevaren ⚠️', body_nl = 'Je kindje klimt nu overal op! Bekijk voor meer veiligheid in huis zeker de zachte hoekbeschermers voor meubels in het onderdeel Aanbevolen producten.', title_pl = 'Nowe odkrycia, nowe zagrożenia ⚠️', body_pl = 'Wspina się już wszędzie! Aby zwiększyć bezpieczeństwo w domu, koniecznie zajrzyj do sekcji Polecane produkty po miękkie osłonki na krawędzie mebli.', title_pt = 'Novas descobertas, novos perigos ⚠️', body_pt = 'Já trepa a todo o lado! Para reforçar a segurança da casa, não deixe de espreitar na secção Produtos Recomendados os protetores macios para as arestas dos móveis.', title_sv = 'Nya upptäckter, nya faror ⚠️', body_sv = 'Barnet klättrar redan överallt! Titta i avsnittet Rekommenderade produkter efter mjuka kantskydd till möblerna för att öka säkerheten i hemmet.', title_vi = 'Khám phá mới, nguy hiểm mới ⚠️', body_vi = 'Bé đã leo trèo khắp nơi! Để tăng an toàn trong nhà, mẹ nhớ xem miếng bọc mềm cho cạnh đồ đạc trong mục Sản phẩm gợi ý nhé.', title_zh = '新发现，新危险 ⚠️', body_zh = '他已经到处爬了！为了提升家里的安全，一定要看看推荐商品里的家具软防撞条。' WHERE id = 'f9f77164-bd35-4d6c-83ca-1991fcf7701a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal el hierro? 🥩', body_es = 'Para que tu peque tan movido no tenga anemia y siga lleno de energía, revisa el hierro de hoy en el Seguimiento de tomas y completa lo que falte.', title_fr = 'Et les réserves de fer ? 🥩', body_fr = 'Pour que votre petit qui bouge tant ne manque pas de fer et reste plein d''énergie, vérifiez ses apports en fer du jour dans le Suivi des repas et comblez les manques.', title_hi = 'आयरन कितना मिल रहा है? 🥩', body_hi = 'चुलबुले नन्हे को खून की कमी न हो और वह ऊर्जा से भरा रहे, इसके लिए फ़ीडिंग ट्रैकर में आज का आयरन जाँचिए और कमियाँ पूरी कीजिए।', title_id = 'Bagaimana cadangan zat besinya? 🥩', body_id = 'Agar si kecil yang aktif tidak mengalami anemia dan tetap berenergi, periksa asupan zat besi hari ini di alat Pemantau Makan dan lengkapi kekurangannya.', title_ja = '鉄分は足りている？🥩', body_ja = '活発なお子さんが貧血にならず元気でいられるよう、「栄養管理ツール」で今日の鉄分摂取量を確認して、足りない分を補いましょう。', title_ko = '철분은 충분한가요? 🥩', body_ko = '활발한 아이가 빈혈 없이 기운차게 지낼 수 있도록 수유 기록 도구에서 오늘 철분 섭취량을 확인하고 부족한 부분을 채워 주세요.', title_nl = 'Hoe zit het met het ijzer? 🥩', body_nl = 'Controleer in de Voedingstracker de ijzerinname van vandaag en vul aan wat ontbreekt, zodat je beweeglijke kleintje geen bloedarmoede krijgt en vol energie blijft.', title_pl = 'Jak tam zapas żelaza? 🥩', body_pl = 'Aby ruchliwy maluch nie miał anemii i był pełen energii, sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza i uzupełnij braki.', title_pt = 'Como está a reserva de ferro? 🥩', body_pt = 'Para que o seu pequeno irrequieto não tenha anemia e se mantenha cheio de energia, verifique no Registo de Alimentação o ferro que comeu hoje e complete o que faltar.', title_sv = 'Hur är järnförrådet? 🥩', body_sv = 'Kolla dagens järnintag i Matningskoll och fyll i det som saknas, så att den lilla aktiva inte får blodbrist och behåller energin.', title_vi = 'Lượng sắt thế nào rồi? 🥩', body_vi = 'Để em bé hiếu động không bị thiếu máu và luôn tràn đầy năng lượng, hãy kiểm tra lượng sắt hôm nay trong công cụ Theo dõi cữ bú và bổ sung những gì còn thiếu.', title_zh = '铁摄入够吗？🥩', body_zh = '为了让好动的小家伙不贫血、保持活力，在喂养记录工具里查看今天的铁摄入量，补上不足的部分吧。' WHERE id = '66297752-072e-4e90-afa0-bfdfc587176c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de arena y hojas 🍂', body_es = '¡Sal de entre cuatro paredes! Encuentra en Lugares para mamás un parque con arenero o una gran zona verde y apoya su desarrollo sensorial.', title_fr = 'La thérapie du sable et des feuilles 🍂', body_fr = 'Sortez de vos quatre murs ! Trouvez dans les Lieux adaptés aux mamans un parc avec un bac à sable ou de grands espaces verts pour soutenir son développement sensoriel.', title_hi = 'रेत और पत्तियों की थेरेपी 🍂', body_hi = 'घर की चार दीवारों से बाहर निकलिए! माँ के लिए अनुकूल जगहों में सैंडपिट या बड़े हरे-भरे मैदान वाला पार्क ढूँढिए और उसके सेंसरी विकास में मदद कीजिए।', title_id = 'Terapi pasir dan daun 🍂', body_id = 'Keluar dari empat dinding rumah! Temukan taman dengan bak pasir atau area hijau yang luas di Tempat Ramah Ibu dan dukung perkembangan sensoriknya.', title_ja = '砂と葉っぱのセラピー 🍂', body_ja = '家の中から外へ出かけましょう！「ママにやさしいスポット」で砂場や広い芝生のある公園を見つけて、感覚の発達を応援しましょう。', title_ko = '모래와 나뭇잎 테라피 🍂', body_ko = '집 안 네 벽을 벗어나세요! 엄마 친화 장소에서 모래 놀이터나 넓은 잔디밭이 있는 공원을 찾아 감각 발달을 도와주세요.', title_nl = 'Zand- en bladertherapie 🍂', body_nl = 'Ga weg uit de vier muren! Zoek in Mamavriendelijke plekken een park met een zandbak of veel groen en ondersteun zijn zintuiglijke ontwikkeling.', title_pl = 'Terapia piaskiem i liśćmi 🍂', body_pl = 'Wyjdźcie z czterech ścian! Znajdź w Miejscach przyjaznych mamom park z piaskownicą lub dużym terenem zielonym i wspieraj rozwój jego zmysłów.', title_pt = 'Terapia de areia e folhas 🍂', body_pt = 'Saia das quatro paredes de casa! Encontre nos Locais Amigos das Mães um parque com caixa de areia ou muito espaço verde e apoie o desenvolvimento sensorial dele.', title_sv = 'Sand- och lövterapi 🍂', body_sv = 'Ut ur hemmets fyra väggar! Hitta en park med sandlåda eller stora gröna ytor i Mammavänliga platser och stötta den sensoriska utvecklingen.', title_vi = 'Liệu pháp cát và lá cây 🍂', body_vi = 'Hãy ra khỏi bốn bức tường! Tìm một công viên có hố cát hoặc bãi cỏ rộng trong Địa điểm thân thiện với mẹ để hỗ trợ sự phát triển giác quan của bé.', title_zh = '沙子和树叶疗法 🍂', body_zh = '走出家里的四面墙吧！在妈妈友好场所里找一个有沙池或大片绿地的公园，支持他的感官发育。' WHERE id = '802d0f46-e525-43d0-8f5c-440b82228035' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja de buscar la perfección ✨', body_es = '¿Hoy le has levantado la voz? No te tortures. Escribe tu agobio en el Diario de ánimo, perdónate y prepárate para un nuevo día mañana.', title_fr = 'Lâchez la quête de perfection ✨', body_fr = 'Vous avez haussé le ton avec votre enfant aujourd''hui ? Ne culpabilisez pas. Écrivez ce qui vous pèse dans le Journal d''humeur, pardonnez-vous et préparez-vous pour une nouvelle journée demain.', title_hi = 'परफ़ेक्ट होने की चाह छोड़िए ✨', body_hi = 'आज बच्चे पर आवाज़ ऊँची हो गई? अपराध-बोध मत पालिए। मूड डायरी में अपनी अंदर की परेशानी लिखिए, खुद को माफ़ कीजिए और कल के नए दिन की तैयारी कीजिए।', title_id = 'Lepaskan keinginan untuk sempurna ✨', body_id = 'Hari ini Anda meninggikan suara pada si kecil? Jangan dihantui rasa bersalah. Tulis beban hati Anda di Buku Harian Suasana Hati, maafkan diri sendiri, dan bersiaplah untuk hari baru besok.', title_ja = '完璧を求めるのはやめよう ✨', body_ja = '今日お子さんに声を荒げてしまいましたか？罪悪感を抱かないで。「気分日記」に心のもやもやを書いて、自分を許し、明日の新しい一日に備えましょう。', title_ko = '완벽함은 내려놓으세요 ✨', body_ko = '오늘 아이에게 목소리를 높였나요? 죄책감에 시달리지 마세요. 기분 일기에 마음속 답답함을 적고, 나를 용서하고, 새로운 내일을 준비하세요.', title_nl = 'Laat het streven naar perfectie los ✨', body_nl = 'Heb je vandaag je stem verheven tegen je kindje? Voel je niet schuldig. Schrijf wat je dwarszit op in je Stemmingsdagboek, vergeef jezelf en maak je klaar voor een nieuwe dag morgen.', title_pl = 'Porzuć pogoń za perfekcją ✨', body_pl = 'Podniosłaś dziś głos na dziecko? Nie zadręczaj się wyrzutami sumienia. Zapisz w Dzienniku nastroju, co cię gnębi, wybacz sobie i przygotuj się na nowy dzień.', title_pt = 'Deixe de procurar a perfeição ✨', body_pt = 'Hoje levantou a voz à criança? Não se martirize com a culpa. Escreva no Diário de Humor a sua angústia, perdoe-se e prepare-se para o novo dia de amanhã.', title_sv = 'Släpp jakten på perfektion ✨', body_sv = 'Höjde du rösten mot barnet i dag? Plåga dig inte med dåligt samvete. Skriv det som tynger dig i Humördagboken, förlåt dig själv och förbered dig för morgondagen.', title_vi = 'Buông bỏ sự cầu toàn ✨', body_vi = 'Hôm nay mẹ lỡ to tiếng với bé? Đừng dằn vặt. Hãy viết nỗi niềm trong lòng vào Nhật ký tâm trạng, tha thứ cho bản thân và chuẩn bị cho ngày mới.', title_zh = '放下对完美的追求 ✨', body_zh = '今天对孩子提高了嗓门？别受良心折磨。把内心的烦闷写进心情日记，原谅自己，准备迎接明天新的一天。' WHERE id = 'ee6e42f5-c128-4ecd-8cea-dcd4ee6be618' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Operación brócoli! 🥦', body_es = '¿Rechaza la verdura? No te preocupes. Descubre en Recetas para bebé cómo esconder el brócoli dentro de unas tortitas deliciosas.', title_fr = 'Opération brocoli ! 🥦', body_fr = 'Il refuse les légumes ? Pas d''inquiétude. Découvrez dans les Recettes pour bébés comment cacher du brocoli dans de délicieuses petites crêpes.', title_hi = 'ऑपरेशन ब्रोकली! 🥦', body_hi = 'सब्ज़ियाँ नहीं खाता? चिंता मत कीजिए। बच्चों की रेसिपी में जानिए कि ब्रोकली को स्वादिष्ट पैनकेक के अंदर कैसे छिपाएँ।', title_id = 'Operasi brokoli! 🥦', body_id = 'Ia menolak sayuran? Jangan khawatir. Temukan cara menyembunyikan brokoli di dalam panekuk lezat di Resep Bayi.', title_ja = 'ブロッコリー大作戦！🥦', body_ja = '野菜を嫌がる？心配いりません。ベビーレシピで、ブロッコリーをおいしいパンケーキに隠す方法を見つけましょう。', title_ko = '브로콜리 작전! 🥦', body_ko = '채소를 거부하나요? 걱정하지 마세요. 아기 레시피에서 맛있는 팬케이크 속에 브로콜리를 숨기는 방법을 알아보세요.', title_nl = 'Operatie broccoli! 🥦', body_nl = 'Weigert je kindje groenten? Geen zorgen. Ontdek in de babyrecepten hoe je broccoli verstopt in lekkere pannenkoekjes.', title_pl = 'Operacja Brokuł! 🥦', body_pl = 'Odrzuca warzywa? Nie martw się. Odkryj w Przepisach dla maluszka, jak ukryć brokuła w pysznych naleśnikach.', title_pt = 'Operação brócolos! 🥦', body_pt = 'Rejeita os legumes? Não se preocupe. Descubra nas Receitas para bebés como esconder os brócolos dentro de panquecas deliciosas.', title_sv = 'Operation broccoli! 🥦', body_sv = 'Vägrar barnet grönsaker? Oroa dig inte. Upptäck i Babyrecept hur du gömmer broccoli i goda små pannkakor.', title_vi = 'Chiến dịch bông cải xanh! 🥦', body_vi = 'Bé từ chối rau? Mẹ đừng lo. Hãy khám phá cách giấu bông cải xanh trong những chiếc bánh kếp thơm ngon với Công thức cho bé.', title_zh = '西兰花行动！🥦', body_zh = '不肯吃蔬菜？别担心。在宝宝食谱里看看怎么把西兰花藏进美味的小煎饼里吧。' WHERE id = '0bcc42e9-f88e-427d-8d6d-562c3e7e7138' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sé sincera contigo misma 🛋️', body_es = '¿Hoy estás agotada y has querido tirar la toalla? ¡Es normal! Abre el Diario de ánimo, escribe «Necesito descansar» y dedica esta noche solo a ti.', title_fr = 'Soyez honnête avec vous-même 🛋️', body_fr = 'Vous êtes très fatiguée aujourd''hui et vous aviez envie de tout lâcher ? C''est normal ! Ouvrez le Journal d''humeur, écrivez « J''ai besoin de repos » et consacrez cette soirée à vous seule.', title_hi = 'खुद से मान लीजिए 🛋️', body_hi = 'आज बहुत थक गईं और सब कुछ छोड़ देने का मन हुआ? यह सामान्य है! मूड डायरी खोलिए, ''मुझे आराम चाहिए'' लिखिए और यह शाम सिर्फ़ अपने लिए रखिए।', title_id = 'Jujurlah pada diri sendiri 🛋️', body_id = 'Hari ini Anda sangat lelah dan ingin melepaskan semuanya? Itu normal! Buka Buku Harian Suasana Hati, tulis "Aku butuh istirahat", dan khususkan malam ini hanya untuk diri sendiri.', title_ja = '自分に正直になろう 🛋️', body_ja = '今日はとても疲れて、すべてを投げ出したくなりましたか？それは自然なことです！「気分日記」を開いて「休みが必要」と書き、今夜は自分のためだけに使いましょう。', title_ko = '스스로에게 솔직해지세요 🛋️', body_ko = '오늘 너무 지쳐서 다 내려놓고 싶었나요? 자연스러운 일이에요! 기분 일기를 열고 ''나에게는 휴식이 필요해''라고 적은 뒤, 오늘 저녁은 오롯이 나를 위해 쓰세요.', title_nl = 'Wees eerlijk tegen jezelf 🛋️', body_nl = 'Was je vandaag heel moe en wilde je alles laten vallen? Dat is normaal! Open je Stemmingsdagboek, schrijf: ik heb rust nodig, en geef deze avond helemaal aan jezelf.', title_pl = 'Przyznaj się przed sobą 🛋️', body_pl = 'Jesteś dziś bardzo zmęczona i chciałaś wszystko rzucić? To normalne! Otwórz Dziennik nastroju, napisz „Potrzebuję odpoczynku” i poświęć ten wieczór tylko sobie.', title_pt = 'Seja sincera consigo 🛋️', body_pt = 'Hoje ficou muito cansada e apeteceu-lhe largar tudo? É normal! Abra o Diário de Humor, escreva "Preciso de descansar" e dedique esta noite só a si.', title_sv = 'Var ärlig mot dig själv 🛋️', body_sv = 'Har du varit väldigt trött i dag och velat släppa allt? Det är normalt! Öppna Humördagboken, skriv ”Jag behöver vila” och ägna kvällen bara åt dig själv.', title_vi = 'Hãy thành thật với chính mình 🛋️', body_vi = 'Hôm nay mẹ quá mệt và chỉ muốn buông bỏ tất cả? Điều đó là bình thường! Hãy mở Nhật ký tâm trạng, viết "Mình cần được nghỉ ngơi" và dành buổi tối nay cho riêng mình.', title_zh = '对自己坦白 🛋️', body_zh = '今天累坏了，什么都想撒手不管？这很正常！打开心情日记，写下“我需要休息”，把今晚只留给自己吧。' WHERE id = '2e502c2f-240e-4506-a102-a80013f7742b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Más pañales secos? 🧻', body_es = 'Revisa el pañal de la mañana. Si se mantiene seco más de 2 horas, ¡puede ser la primera señal para empezar a dejar el pañal! Anota tus observaciones en el Seguimiento de pañales y revisa las estadísticas.', title_fr = 'Plus de couches sèches ? 🧻', body_fr = 'Vérifiez la couche du matin. Si elle reste sèche plus de 2 heures, c''est peut-être un premier signal pour l''apprentissage de la propreté ! Saisissez vos observations dans le Suivi des couches et consultez les statistiques.', title_hi = 'सूखे डायपर बढ़ रहे हैं? 🧻', body_hi = 'सुबह का डायपर जाँचिए। अगर वह 2 घंटे से ज़्यादा सूखा रहता है, तो यह टॉयलेट ट्रेनिंग का पहला संकेत हो सकता है! डायपर ट्रैकर में अपने नोट्स डालिए और आँकड़े देखिए।', title_id = 'Popoknya makin sering kering? 🧻', body_id = 'Periksa popok paginya. Kalau tetap kering lebih dari 2 jam, ini bisa jadi sinyal pertama untuk latihan toilet! Masukkan catatan Anda ke Pelacak Popok dan lihat statistiknya.', title_ja = '乾いたおむつが増えてきた？🧻', body_ja = '朝のおむつをチェックしましょう。2時間以上乾いたままなら、トイレトレーニングの最初のサインかもしれません！「おむつトラッカー」に記録して、統計を確認しましょう。', title_ko = '마른 기저귀가 늘었나요? 🧻', body_ko = '아침 기저귀를 확인해 보세요. 2시간 넘게 마른 상태라면 배변 훈련을 시작할 첫 신호일 수 있어요! 기저귀 기록에 입력하고 통계를 확인하세요.', title_nl = 'Vaker droge luiers? 🧻', body_nl = 'Controleer de ochtendluier. Blijft hij langer dan 2 uur droog? Dat kan het eerste signaal zijn voor zindelijkheidstraining! Voer je notities in de Luiertracker in en bekijk de cijfers.', title_pl = 'Coraz więcej suchych pieluszek? 🧻', body_pl = 'Sprawdź poranną pieluszkę. Jeśli przez ponad 2 godziny pozostaje sucha, to może być pierwszy sygnał gotowości do nauki korzystania z nocnika! Wpisz obserwacje do narzędzia do śledzenia pieluszek i sprawdź statystyki.', title_pt = 'Há mais fraldas secas? 🧻', body_pt = 'Verifique a fralda da manhã. Se ficar seca mais de 2 horas, pode ser o primeiro sinal para o desfralde! Introduza as suas notas no Registo de Fraldas e veja as estatísticas.', title_sv = 'Blir det fler torra blöjor? 🧻', body_sv = 'Kolla morgonblöjan. Om den håller sig torr i mer än 2 timmar kan det vara den första signalen för pottträning! Lägg in dina anteckningar i Blöjkollen och kolla statistiken.', title_vi = 'Tã khô nhiều hơn? 🧻', body_vi = 'Hãy kiểm tra tã buổi sáng. Nếu tã khô hơn 2 tiếng, đó có thể là tín hiệu đầu tiên để tập cho bé đi bô! Hãy ghi lại vào Theo dõi tã và xem thống kê.', title_zh = '干爽的尿布变多了？🧻', body_zh = '检查一下早上的尿布。如果超过2小时都是干的，这可能是如厕训练的第一个信号！把记录录入尿布记录，看看统计数据吧。' WHERE id = '530196ff-adb2-4ae9-a06d-67bb4bfd998f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hidratación de mamá 💧', body_es = '¿Te has quedado sin beber de tanto correr detrás de tu peque? Puede ser la causa de tu dolor de cabeza. Prepara aguas detox de Recetas saludables y recupera energía.', title_fr = 'L''hydratation de maman 💧', body_fr = 'À force de courir après lui, vous avez oublié de boire ? Votre mal de tête vient peut-être de là. Retrouvez votre énergie en préparant des eaux détox grâce aux Recettes saines.', title_hi = 'माँ के पानी का संतुलन 💧', body_hi = 'बच्चे के पीछे भागते हुए पानी पीना भूल गईं? सिरदर्द की वजह यही हो सकती है। सेहतमंद रेसिपी से डिटॉक्स वॉटर बनाकर अपनी ऊर्जा लौटाइए।', title_id = 'Keseimbangan cairan Bunda 💧', body_id = 'Lupa minum karena sibuk mengejar si kecil? Mungkin itu penyebab sakit kepala Anda. Pulihkan energi dengan membuat air detoks dari Resep Sehat.', title_ja = 'ママの水分バランス 💧', body_ja = 'お子さんを追いかけて、水分不足になっていませんか？頭痛の原因はそれかもしれません。「ヘルシーレシピ」のデトックスウォーターで、エネルギーを取り戻しましょう。', title_ko = '엄마의 수분 균형 💧', body_ko = '아이를 쫓아다니느라 물 마시는 걸 잊었나요? 두통의 원인이 그것일 수 있어요. 건강한 레시피에서 디톡스 워터를 만들어 기운을 되찾으세요.', title_nl = 'Mama''s vochtbalans 💧', body_nl = 'Vergeet je te drinken terwijl je achter je kindje aanrent? Dat kan de oorzaak zijn van hoofdpijn. Maak detoxwater uit Gezonde recepten en krijg je energie terug.', title_pl = 'Nawodnienie mamy 💧', body_pl = 'Biegając za dzieckiem, zapominasz pić? To może być przyczyna bólu głowy. Przygotuj wodę detoks ze zdrowych przepisów i odzyskaj energię.', title_pt = 'A hidratação da mãe 💧', body_pt = 'Ficou desidratada a correr atrás da criança? Pode ser essa a causa da dor de cabeça. Recupere a energia preparando águas detox das Receitas Saudáveis.', title_sv = 'Mammas vätskebalans 💧', body_sv = 'Har du blivit uttorkad av att springa efter barnet? Det kan vara orsaken till huvudvärken. Gör detoxvatten från Hälsosamma recept och fyll på energin.', title_vi = 'Cân bằng nước cho mẹ 💧', body_vi = 'Chạy theo bé mà quên uống nước? Đó có thể là nguyên nhân gây đau đầu. Hãy làm nước detox từ Công thức lành mạnh để lấy lại năng lượng.', title_zh = '妈妈的水分平衡 💧', body_zh = '追着孩子跑，忘了喝水？头痛可能就是因为这个。从健康食谱里做点排毒水，恢复能量吧。' WHERE id = '057998e1-6566-4f75-aa40-70a38d334aee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '10 minutos para dormir... ⏱️', body_es = 'Activa el Temporizador de sueño y oscurece la habitación. Pon el susurro del bosque en Ruido blanco y haz que el paso al sueño sea mágico para los dos.', title_fr = '10 minutes avant de dormir... ⏱️', body_fr = 'Lancez le minuteur de sommeil et faites le noir dans la chambre. Mettez le murmure de la forêt dans les Bruits blancs pour rendre l''endormissement magique, pour lui comme pour vous.', title_hi = 'सोने में 10 मिनट... ⏱️', body_hi = 'स्लीप टाइमर चालू कीजिए और कमरे में अँधेरा कीजिए। व्हाइट नॉइज़ से जंगल की सरसराहट चलाकर उसके और अपने लिए नींद में जाने को जादुई बना दीजिए।', title_id = '10 menit menuju tidur... ⏱️', body_id = 'Nyalakan Timer Tidur dan gelapkan kamar. Putar suara desir hutan dari Suara Putih dan jadikan peralihan ke tidur terasa ajaib untuknya dan untuk Anda.', title_ja = 'ねんねまであと10分… ⏱️', body_ja = '睡眠タイマーをオンにして、部屋を暗くしましょう。「ホワイトノイズ」から森のざわめきを流せば、眠りへの切りかえがお子さんにもあなたにも魔法のような時間になります。', title_ko = '잠들기 10분 전... ⏱️', body_ko = '수면 타이머를 켜고 방을 어둡게 하세요. 백색소음에서 숲속 바람 소리를 틀어 아이와 엄마 모두에게 잠드는 시간을 마법처럼 만들어 보세요.', title_nl = 'Nog 10 minuten tot het slapen... ⏱️', body_nl = 'Zet de Slaaptimer aan en maak de kamer donker. Zet in Witte ruis het ruisen van het bos aan en maak het in slaap vallen magisch, voor hem en voor jezelf.', title_pl = '10 minut do snu... ⏱️', body_pl = 'Włącz timer snu i zaciemnij pokój. Włącz w Białym szumie szum lasu i zamień zasypianie w magiczną chwilę dla niego i dla siebie.', title_pt = '10 minutos para dormir... ⏱️', body_pt = 'Ligue o temporizador de sono e escureça o quarto. Ligue o som da floresta no Ruído Branco e torne mágica a passagem para o sono, para ele e para si.', title_sv = '10 minuter till sömn... ⏱️', body_sv = 'Starta sömntimern och mörklägg rummet. Sätt på skogens sus i Vitt brus och gör insomnandet magiskt både för barnet och dig själv.', title_vi = 'Còn 10 phút nữa là đến giờ ngủ... ⏱️', body_vi = 'Hãy bật Bộ hẹn giờ ngủ và làm tối căn phòng. Bật tiếng rừng xào xạc trong Tiếng ồn trắng để giờ đi ngủ trở nên kỳ diệu cho cả bé và mẹ.', title_zh = '离入睡还有10分钟…… ⏱️', body_zh = '打开睡眠计时器，把房间调暗。在白噪音里放森林的沙沙声，让入睡过程对他和你都变得像魔法一样。' WHERE id = '29452fba-ed37-4bde-8e72-45e1f9c46d4d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El monstruo de los macarrones! 🍝', body_es = '¿Al comer solo se ha puesto perdido, hasta el pelo? ¡No te pierdas este momento tan gracioso! Decóralo con los marcos divertidos de la Sesión de fotos del bebé y añádelo al álbum.', title_fr = 'Le monstre des pâtes ! 🍝', body_fr = 'En mangeant seul, il s''est sali de la tête aux pieds, cheveux compris ? Ne manquez pas ce moment comique ! Décorez-le avec les cadres amusants de la Séance photo bébé et ajoutez-le à l''album.', title_hi = 'पास्ता मॉन्स्टर! 🍝', body_hi = 'खुद खाते हुए कपड़े, यहाँ तक कि बाल भी सन गए? इस मज़ेदार पल को मत चूकिए! बेबी फ़ोटोशूट के मज़ेदार फ़्रेम से सजाकर एल्बम में जोड़िए।', title_id = 'Monster makaroni! 🍝', body_id = 'Saat makan sendiri, baju bahkan rambutnya ikut kotor? Jangan lewatkan momen lucu ini! Hiasi dengan bingkai seru di Sesi Foto Bayi dan tambahkan ke album.', title_ja = 'パスタモンスター！🍝', body_ja = '自分で食べて、服も髪までもべとべと？このおもしろい瞬間を見逃さないで！「ベビーフォトセッション」の楽しいフレームで飾って、アルバムに追加しましょう。', title_ko = '파스타 괴물! 🍝', body_ko = '혼자 먹다가 옷은 물론 머리카락까지 엉망이 됐나요? 이 웃긴 순간을 놓치지 마세요! 아기 사진 촬영의 재미있는 프레임으로 꾸며 앨범에 추가하세요.', title_nl = 'Het pastamonster! 🍝', body_nl = 'Zit je kindje na het zelf eten helemaal onder, zelfs zijn haar? Mis dit grappige moment niet! Versier het met de leuke kaders in Babyfotoshoot en zet het in het album.', title_pl = 'Makaronowy potwór! 🍝', body_pl = 'Jedząc sam, ubrudził się cały, nawet włosy? Nie przegap tej zabawnej chwili! Ozdób ją zabawnymi ramkami w Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'O monstro da massa! 🍝', body_pt = 'A comer sozinho, sujou a roupa e até o cabelo? Não perca este momento cómico! Decore-o com as molduras divertidas da Sessão Fotográfica do Bebé e adicione-o ao álbum.', title_sv = 'Pastamonstret! 🍝', body_sv = 'Har barnet fått mat över hela sig, till och med i håret, när det ätit själv? Missa inte det roliga ögonblicket! Pynta det med roliga ramar i Babyfotografering och lägg till det i albumet.', title_vi = 'Quái vật mì ống! 🍝', body_vi = 'Tự ăn mà dính đầy người, cả tóc nữa? Đừng bỏ lỡ khoảnh khắc hài hước này! Hãy trang trí bằng những khung ảnh vui nhộn trong Chụp ảnh cho bé và thêm vào album.', title_zh = '意面小怪兽！🍝', body_zh = '自己吃饭时弄得满身满脸，连头发都沾上了？别错过这个好笑的瞬间！用宝宝写真里有趣的相框装点一下，加进相册吧。' WHERE id = 'fa637a9e-0a58-4301-a5dd-89fb27cdb46b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le aprietan los zapatos? 👟', body_es = '¿Últimamente tropieza a menudo al correr? ¡Quizá le ha crecido el pie! Introduce su nueva talla de zapato y su altura en el Registro de peso y analiza su ritmo de crecimiento.', title_fr = 'Ses chaussures le serrent ? 👟', body_fr = 'Il trébuche souvent en courant ces derniers temps ? Son pied a peut-être grandi ! Saisissez sa nouvelle pointure et sa taille dans le Suivi du poids et analysez son rythme de croissance.', title_hi = 'जूते तंग हो रहे हैं? 👟', body_hi = 'आजकल दौड़ते हुए बार-बार लड़खड़ाता है? शायद उसका पैर बड़ा हो गया है! वेट ट्रैकर में जूते और लंबाई के नए माप डालिए और बढ़त की रफ़्तार का विश्लेषण कीजिए।', title_id = 'Sepatunya kekecilan? 👟', body_id = 'Akhir-akhir ini ia sering tersandung saat berlari? Mungkin kakinya sudah bertambah besar! Masukkan ukuran sepatu dan tinggi terbarunya di Pelacak Berat Badan dan analisis laju pertumbuhannya.', title_ja = '靴がきつい？👟', body_ja = '最近、走っているときによくつまずきますか？足が大きくなったのかもしれません！「体重トラッカー」に新しい靴のサイズと身長を入れて、成長のスピードを分析しましょう。', title_ko = '신발이 작아졌나요? 👟', body_ko = '요즘 뛰다가 자주 넘어지나요? 발이 컸을 수도 있어요! 체중 기록에 새 신발 사이즈와 키를 입력하고 성장 속도를 분석해 보세요.', title_nl = 'Knellen zijn schoenen? 👟', body_nl = 'Struikelt je kindje de laatste tijd vaak tijdens het rennen? Misschien zijn zijn voetjes gegroeid! Voer de nieuwe schoenmaat en lengte in de Gewichtstracker in en analyseer zijn groeitempo.', title_pl = 'Buty za ciasne? 👟', body_pl = 'Ostatnio często potyka się w biegu? Może urosła mu stopa! Wpisz nowy rozmiar butów i wzrost w Liczniku wagi i przeanalizuj tempo wzrostu.', title_pt = 'Os sapatos estão apertados? 👟', body_pt = 'Ultimamente tropeça muito a correr? Talvez o pé tenha crescido! Introduza no Registo de Peso as novas medidas do sapato e da altura e analise o ritmo de crescimento.', title_sv = 'Klämmer skorna? 👟', body_sv = 'Snubblar barnet ofta när det springer på sistone? Kanske har foten vuxit! Skriv in nya sko- och längdmått i Viktspåraren och analysera tillväxttakten.', title_vi = 'Giày chật rồi? 👟', body_vi = 'Dạo này bé hay vấp khi chạy? Có thể chân bé đã lớn! Hãy nhập cỡ giày và chiều cao mới vào Theo dõi cân nặng để phân tích tốc độ phát triển.', title_zh = '鞋子挤脚了？👟', body_zh = '最近跑的时候经常绊倒？也许是脚长大了！在体重记录里输入新的鞋码和身高，分析一下成长速度吧。' WHERE id = '031932e3-d91b-494c-9f35-dc03d53026b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Alimento para el cerebro: omega-3 🐟', body_es = 'El pescado es importante para su desarrollo intelectual. Prepara unas deliciosas hamburguesitas de pescado al horno y sin espinas de Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Nourrir le cerveau : les oméga-3 🐟', body_fr = 'Le poisson est important pour son développement intellectuel. Préparez de délicieuses galettes de poisson sans arêtes cuites au four grâce aux Recettes pour bébés qui commencent la diversification.', title_hi = 'दिमाग का भोजन: ओमेगा-3 🐟', body_hi = 'बढ़ते दिमागी विकास के लिए मछली ज़रूरी है। ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी से बिना काँटे वाली, ओवन में बनी स्वादिष्ट फ़िश कटलेट बनाइए।', title_id = 'Makanan otak: Omega-3 🐟', body_id = 'Ikan penting untuk perkembangan kecerdasannya. Buat perkedel ikan panggang tanpa tulang yang lezat dari Resep untuk bayi yang mulai MPASI.', title_ja = '脳のための栄養：オメガ3 🐟', body_ja = '知能の発達のために、お魚は大切です。「離乳食を始める赤ちゃんのレシピ」から、骨なしでオーブン焼きのおいしいお魚ハンバーグをつくりましょう。', title_ko = '두뇌 영양: 오메가-3 🐟', body_ko = '쑥쑥 자라는 두뇌 발달에는 생선이 중요해요. 이유식을 시작하는 아기를 위한 레시피에서 가시 없는 오븐 생선 동그랑땡을 만들어 보세요.', title_nl = 'Voeding voor de hersenen: omega-3 🐟', body_nl = 'Vis is belangrijk voor de groeiende verstandelijke ontwikkeling. Maak uit Recepten voor baby''s die met bijvoeding beginnen een lekker visburgertje zonder graten uit de oven.', title_pl = 'Pokarm dla mózgu: omega-3 🐟', body_pl = 'Ryby są ważne dla rozwoju umysłu. Przygotuj z Przepisów dla niemowląt rozpoczynających rozszerzanie diety smaczne kotleciki rybne bez ości pieczone w piekarniku.', title_pt = 'Alimento para o cérebro: ómega-3 🐟', body_pt = 'O peixe é importante para o desenvolvimento cognitivo. Prepare com as Receitas para bebés em diversificação alimentar deliciosos hambúrgueres de peixe sem espinhas, feitos no forno.', title_sv = 'Hjärnmat: Omega-3 🐟', body_sv = 'Fisk är viktigt för den växande intelligensen. Gör goda benfria, ugnsbakade fiskbiffar från Recept för bebisar som börjar med fast föda.', title_vi = 'Thức ăn cho não: Omega-3 🐟', body_vi = 'Cá rất quan trọng cho sự phát triển trí tuệ. Hãy làm món chả cá nướng lò không xương thơm ngon từ mục Công thức cho bé bắt đầu ăn dặm.', title_zh = '大脑食物：Omega-3 🐟', body_zh = '鱼对不断发展的智力很重要。从食谱板块的辅食宝宝食谱里，做些无刺、烤箱烤制的美味鱼饼吧。' WHERE id = 'db0a30ff-e18a-4830-abdc-881dc8827a75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de frenar! 🌙', body_es = 'Fin de un día activo. Activa el Temporizador de sueño, deja las carreras y pasa a actividades tranquilas (por ejemplo, hacer un puzle).', title_fr = 'L''heure de ralentir ! 🌙', body_fr = 'Fin d''une journée active. Activez le minuteur de sommeil, arrêtez les courses-poursuites et passez à des activités apaisantes (par exemple un puzzle).', title_hi = 'ब्रेक लगाने का समय! 🌙', body_hi = 'भाग-दौड़ भरे दिन का अंत। स्लीप टाइमर चालू कीजिए और पकड़म-पकड़ाई रोककर शांत गतिविधियों (जैसे पज़ल जोड़ना) पर आ जाइए।', title_id = 'Waktunya mengerem! 🌙', body_id = 'Akhir hari yang aktif. Aktifkan Timer Tidur, hentikan kejar-kejaran, dan beralihlah ke kegiatan yang menenangkan (misalnya menyusun puzzle).', title_ja = 'ブレーキの時間！🌙', body_ja = '活発な一日の終わり。睡眠タイマーをオンにして、追いかけっこをやめ、落ち着いた遊び（たとえばパズル）に切りかえましょう。', title_ko = '브레이크를 걸 시간! 🌙', body_ko = '활발한 하루가 끝났어요. 수면 타이머를 켜고 술래잡기를 멈춘 뒤 차분한 활동(예: 퍼즐 맞추기)으로 바꿔 주세요.', title_nl = 'Tijd om af te remmen! 🌙', body_nl = 'Het einde van een drukke dag. Zet de Slaaptimer aan, stop met rennen en ga over op rustgevende bezigheden (bijvoorbeeld een puzzel maken).', title_pl = 'Czas zwolnić! 🌙', body_pl = 'Koniec aktywnego dnia. Włącz timer snu, przerwij gonitwy i przejdźcie do uspokajających zajęć (np. układania puzzli).', title_pt = 'Hora de travar! 🌙', body_pt = 'O fim de um dia ativo. Ative o temporizador de sono, pare as correrias e passe a atividades calmantes (por exemplo, fazer um puzzle).', title_sv = 'Dags att bromsa in! 🌙', body_sv = 'Slutet på en aktiv dag. Aktivera sömntimern, avbryt jagalekarna och gå över till lugnande aktiviteter (till exempel att lägga pussel).', title_vi = 'Giờ "phanh" lại rồi! 🌙', body_vi = 'Kết thúc một ngày hiếu động. Hãy bật Bộ hẹn giờ ngủ, dừng các trò đuổi bắt và chuyển sang những hoạt động nhẹ nhàng (ví dụ, xếp hình).', title_zh = '该踩刹车啦！🌙', body_zh = '活跃一天的尾声。打开睡眠计时器，停下追追跑跑，换成安静的活动（比如拼拼图）。' WHERE id = 'eb71840a-d8fc-43f9-897d-715c008b72b7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Un capricho de 5 minutos! 🥗', body_es = '¿Comes cualquier cosa de pie al mediodía? Prepara en Recetas saludables para mujeres una tostada de aguacate y huevo que te saciará y te dará energía.', title_fr = 'Un délice en 5 minutes ! 🥗', body_fr = 'Vous grignotez debout à midi ? Préparez une tartine avocat-œuf des Recettes saines pour femmes, qui vous rassasiera et vous donnera de l''énergie.', title_hi = '5 मिनट का स्वाद! 🥗', body_hi = 'दोपहर में खड़े-खड़े कुछ खा लेती हैं? महिलाओं के लिए सेहतमंद रेसिपी से पेट भरने और ऊर्जा देने वाला एवोकाडो-अंडा टोस्ट बनाइए।', title_id = 'Nikmat dalam 5 menit! 🥗', body_id = 'Siang hari makan seadanya sambil berdiri? Buat roti panggang alpukat dan telur yang mengenyangkan dan memberi energi dari Resep Sehat untuk wanita.', title_ja = '5分でできるごちそう！🥗', body_ja = 'お昼を立ったまますませていませんか？「女性のためのヘルシーレシピ」から、お腹も満たされて元気が出る、アボカドと卵のトーストをつくりましょう。', title_ko = '5분이면 완성! 🥗', body_ko = '점심을 서서 대충 때우나요? 건강한 레시피에서 든든하고 힘이 나는 아보카도 달걀 토스트를 만들어 보세요.', title_nl = 'Genieten in 5 minuten! 🥗', body_nl = 'Eet je ''s middags staand snel iets tussendoor? Maak uit Gezonde recepten voor vrouwen een toast met avocado en ei die je verzadigt en energie geeft.', title_pl = 'Przysmak w 5 minut! 🥗', body_pl = 'W południe jesz coś na stojąco? Przygotuj ze Zdrowych przepisów dla kobiet tost z awokado i jajkiem, który cię nasyci i doda energii.', title_pt = 'Uma delícia em 5 minutos! 🥗', body_pt = 'À tarde, come qualquer coisa à pressa e de pé? Prepare das Receitas Saudáveis para Mulheres uma tosta de abacate e ovo que a deixa satisfeita e lhe dá energia.', title_sv = 'Njutning på 5 minuter! 🥗', body_sv = 'Äter du något stående på eftermiddagen? Gör en toast med avokado och ägg från Hälsosamma recept för kvinnor som håller dig mätt och ger energi.', title_vi = 'Món ngon 5 phút! 🥗', body_vi = 'Buổi trưa mẹ ăn vội vài miếng? Hãy làm món bánh mì nướng bơ và trứng từ Công thức lành mạnh cho phụ nữ để no lâu và đầy năng lượng.', title_zh = '5分钟的美味！🥗', body_zh = '中午站着随便吃两口？从女性健康食谱里做一份牛油果鸡蛋吐司，既顶饱又补充能量。' WHERE id = '36d9b82f-d63f-40d9-bafa-df3b3dc844b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Física en la bañera 🛁', body_es = 'Añade al Álbum del bebé esa cara tan seria y concentrada que pone al pasar el agua de un vaso de plástico a otro: ¡estos pequeños descubrimientos son inolvidables!', title_fr = 'Découvertes de physique dans le bain 🛁', body_fr = 'Ajoutez à l''Album de bébé son air sérieux et concentré quand il verse l''eau d''un gobelet en plastique à l''autre : ces petits moments de découverte sont inoubliables !', title_hi = 'नहाते समय भौतिकी की खोज 🛁', body_hi = 'एक प्लास्टिक के गिलास से दूसरे में पानी डालते समय उसका वह गंभीर और ध्यान भरा चेहरा बेबी एल्बम में जोड़िए, खोज के ये छोटे पल यादगार हैं!', title_id = 'Penemuan fisika di bak mandi 🛁', body_id = 'Tambahkan ke Album Bayi ekspresi serius dan fokusnya saat menuang air dari satu gelas plastik ke gelas lain, momen penemuan kecil ini tak terlupakan!', title_ja = 'お風呂で物理の発見 🛁', body_ja = 'プラスチックのコップから別のコップへ水を移すときの、真剣で集中した表情を「ベビーアルバム」に追加しましょう。こんな小さな発見の瞬間は忘れられません！', title_ko = '욕조 속 물리학 발견 🛁', body_ko = '플라스틱 컵에서 다른 컵으로 물을 옮겨 부을 때의 그 진지하고 집중한 표정을 아기 앨범에 남기세요. 이런 작은 발견의 순간은 잊을 수 없어요!', title_nl = 'Natuurkundige ontdekkingen in bad 🛁', body_nl = 'Zet die serieuze, geconcentreerde blik terwijl hij water van het ene plastic bekertje in het andere giet in het Babyalbum. Deze kleine ontdekkingsmomenten zijn onvergetelijk!', title_pl = 'Odkrycia fizyczne w wannie 🛁', body_pl = 'Dodaj do Albumu dziecka tę poważną, skupioną minę, z którą przelewa wodę z jednego plastikowego kubeczka do drugiego. Te małe chwile odkryć są niezapomniane!', title_pt = 'Descobertas de física na banheira 🛁', body_pt = 'Adicione ao Álbum do Bebé aquela expressão séria e concentrada que faz ao passar água de um copo de plástico para outro: estes pequenos momentos de descoberta são inesquecíveis!', title_sv = 'Fysikupptäckter i badkaret 🛁', body_sv = 'Lägg till barnets allvarliga och koncentrerade min när det häller vatten från en plastmugg till en annan i Babyalbumet. Dessa små upptäcktsstunder är oförglömliga!', title_vi = 'Khám phá vật lý trong bồn tắm 🛁', body_vi = 'Hãy thêm vào Album của bé vẻ mặt nghiêm túc, tập trung khi bé rót nước từ cốc nhựa này sang cốc khác, những khoảnh khắc khám phá nhỏ này thật khó quên!', title_zh = '浴缸里的物理发现 🛁', body_zh = '把水从一个塑料杯倒进另一个时，他那副认真专注的表情，加进宝宝相册吧，这些小小的发现时刻令人难忘！' WHERE id = '5db92d40-f36e-4671-8f65-a3cb3f1c91ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Pasa mucho tiempo delante de la pantalla? 📱', body_es = '¿Quitarle el móvil provoca una gran rabieta? Aprende con Anacan AI a limitar el tiempo de pantalla sin estrés y a poner límites sanos.', title_fr = 'Trop de temps devant les écrans ? 📱', body_fr = 'Lui reprendre le téléphone déclenche une grosse crise ? Découvrez avec Anacan AI comment limiter le temps d''écran sans stress et poser des limites saines.', title_hi = 'स्क्रीन के सामने बहुत देर रहता है? 📱', body_hi = 'हाथ से फ़ोन लेने पर बड़ा हंगामा हो जाता है? Anacan AI से सीखिए कि बिना तनाव के स्क्रीन टाइम कैसे सीमित करें और सेहतमंद सीमाएँ कैसे तय करें।', title_id = 'Terlalu lama di depan layar? 📱', body_id = 'Mengambil ponsel dari tangannya memicu krisis besar? Pelajari dari Anacan AI cara membatasi waktu layar tanpa stres dan menetapkan batasan yang sehat.', title_ja = '画面を見る時間が長すぎる？📱', body_ja = 'スマホを取り上げると大きなかんしゃくに？ストレスなく画面時間を減らす方法と、健全なルールの決め方をAnacan AIで学びましょう。', title_ko = '화면을 너무 오래 보나요? 📱', body_ko = '휴대폰을 뺏으면 큰 떼쓰기가 시작되나요? 스트레스 없이 화면 시간을 줄이고 건강한 한계를 정하는 법을 Anacan AI에게 알아보세요.', title_nl = 'Zit hij te lang voor een scherm? 📱', body_nl = 'Leidt de telefoon afpakken tot een grote driftbui? Ontdek bij Anacan AI hoe je schermtijd zonder stress beperkt en gezonde grenzen stelt.', title_pl = 'Za dużo czasu przed ekranem? 📱', body_pl = 'Zabranie mu telefonu wywołuje wielki kryzys? Dowiedz się w Anacan AI, jak bez stresu ograniczyć czas przed ekranem i postawić zdrowe granice.', title_pt = 'Passa muito tempo em frente ao ecrã? 📱', body_pt = 'Tirar-lhe o telemóvel das mãos provoca uma grande crise? Aprenda com o Anacan AI a limitar o tempo de ecrã sem stress e a definir limites saudáveis.', title_sv = 'Sitter barnet för mycket framför skärmen? 📱', body_sv = 'Blir det ett stort utbrott när du tar telefonen? Lär dig av Anacan AI hur du begränsar skärmtiden utan stress och sätter sunda gränser.', title_vi = 'Bé xem màn hình quá nhiều? 📱', body_vi = 'Lấy điện thoại khỏi tay là bé khủng hoảng? Hãy tìm hiểu cùng Anacan AI cách giới hạn thời gian dùng màn hình không căng thẳng và đặt ra ranh giới lành mạnh.', title_zh = '盯着屏幕太久？📱', body_zh = '从他手里拿走手机就引发大崩溃？向Anacan AI学习如何不带压力地限制屏幕时间、设立健康的边界。' WHERE id = 'e18f3a19-4a7e-44e4-9703-5c88f6dda037' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hora de socializar! 👶', body_es = 'Ya tiene ganas de estar con otros niños. Descubre en Lugares para mamás un sitio con zona de juegos infantil y hazle feliz.', title_fr = 'L''heure de se sociabiliser ! 👶', body_fr = 'Il a déjà envie d''être avec d''autres enfants. Faites-lui plaisir en trouvant dans les Lieux adaptés aux mamans un endroit avec un espace de jeux pour enfants.', title_hi = 'मेलजोल का समय! 👶', body_hi = 'अब वह दूसरे बच्चों के साथ रहने को उत्सुक है। माँ के लिए अनुकूल जगहों में बच्चों के प्ले सेंटर वाली कोई जगह खोजिए और उसे खुश कीजिए।', title_id = 'Waktunya bersosialisasi! 👶', body_id = 'Kini ia ingin berada di tempat yang sama dengan anak-anak lain. Temukan tempat dengan pusat bermain anak di Tempat Ramah Ibu dan buat ia senang.', title_ja = 'ほかの子とふれあう時間！👶', body_ja = 'ほかの子どもたちと同じ場所で過ごしたがっています。「ママにやさしいスポット」でキッズプレイセンターのある場所を見つけて、喜ばせてあげましょう。', title_ko = '사회성을 키울 시간! 👶', body_ko = '이제 다른 아이들과 함께 있고 싶어 해요. 엄마 친화 장소에서 키즈 플레이 센터가 있는 곳을 찾아 아이를 기쁘게 해 주세요.', title_nl = 'Tijd om te socialiseren! 👶', body_nl = 'Je kindje wil nu graag tussen andere kinderen zijn. Ontdek in Mamavriendelijke plekken een plek met een speelhoek voor kinderen en maak hem blij.', title_pl = 'Czas na kontakty z innymi! 👶', body_pl = 'Coraz bardziej chce przebywać z innymi dziećmi. Odkryj w Miejscach przyjaznych mamom miejsce z bawialnią dla dzieci i spraw mu radość.', title_pt = 'Hora de socializar! 👶', body_pt = 'Já anseia por estar no mesmo espaço que outras crianças. Descubra nos Locais Amigos das Mães um sítio com espaço de brincar para crianças e deixe-o feliz.', title_sv = 'Dags att umgås! 👶', body_sv = 'Barnet längtar nu efter att vara bland andra barn. Upptäck ett ställe med lekland i Mammavänliga platser och gör barnet glatt.', title_vi = 'Giờ giao lưu! 👶', body_vi = 'Bé đã háo hức được ở cùng các bạn nhỏ khác. Hãy khám phá một địa điểm có khu vui chơi cho trẻ trong Địa điểm thân thiện với mẹ để bé thêm vui.', title_zh = '社交时间！👶', body_zh = '他已经渴望和其他孩子待在一起了。在妈妈友好场所里发现一个有儿童游乐中心的地方，让他开心一下吧。' WHERE id = '2c1e9be8-ccf0-412a-a942-30cea5075e5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le da miedo la oscuridad? 🌌', body_es = '¿Llora o se inquieta cuando apagas la luz? Pon el sonido del vientre materno (latido del corazón) en Ruido blanco y devuélvele esa sensación de seguridad tan cálida y conocida.', title_fr = 'Il a peur du noir ? 🌌', body_fr = 'Il pleure ou s''inquiète quand vous éteignez la lumière ? Lancez le son du ventre maternel (battements de cœur) dans les Bruits blancs pour lui redonner ce sentiment de sécurité chaleureux et familier.', title_hi = 'अँधेरे से डरता है? 🌌', body_hi = 'कमरे की बत्ती बुझाने पर रोता है या बेचैन होता है? व्हाइट नॉइज़ से गर्भ की आवाज़ (दिल की धड़कन) चलाकर उसे वही पुराना, गर्म भरोसे का एहसास दीजिए।', title_id = 'Takut gelap? 🌌', body_id = 'Ia menangis atau gelisah saat lampu kamar dimatikan? Putar suara rahim ibu (detak jantung) dari Suara Putih untuk memberinya rasa aman yang hangat dan akrab.', title_ja = '暗いのがこわい？🌌', body_ja = '部屋の電気を消すと泣いたり、不安そうにしたりしますか？「ホワイトノイズ」から胎内音（心臓の音）を流して、なじみのある温かい安心感をあげましょう。', title_ko = '어둠을 무서워하나요? 🌌', body_ko = '방 불을 끄면 울거나 불안해하나요? 백색소음에서 엄마 배 속 소리(심장 박동)를 틀어 익숙하고 따뜻한 안정감을 선물하세요.', title_nl = 'Bang in het donker? 🌌', body_nl = 'Huilt je kindje of wordt hij onrustig als je het licht uitdoet? Zet in Witte ruis het geluid van de baarmoeder (hartslag) aan en geef hem dat oude, warme gevoel van veiligheid.', title_pl = 'Boi się ciemności? 🌌', body_pl = 'Płacze lub się niepokoi, gdy gasisz światło? Włącz w Białym szumie dźwięk z brzucha mamy (bicie serca) i daj mu dawne, ciepłe poczucie bezpieczeństwa.', title_pt = 'Tem medo do escuro? 🌌', body_pt = 'Chora ou fica inquieto quando apaga a luz do quarto? Ligue no Ruído Branco o som do útero materno (batimentos cardíacos) e devolva-lhe aquela antiga sensação de segurança calorosa.', title_sv = 'Mörkrädd? 🌌', body_sv = 'Gråter barnet eller blir oroligt när du släcker i rummet? Sätt på ljudet från livmodern (hjärtslag) i Vitt brus och ge barnet den gamla, varma känslan av trygghet.', title_vi = 'Bé sợ bóng tối? 🌌', body_vi = 'Tắt đèn là bé khóc hay bất an? Hãy bật âm thanh trong bụng mẹ (tiếng tim đập) trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn, ấm áp quen thuộc.', title_zh = '怕黑？🌌', body_zh = '关灯时会哭或不安？在白噪音里放子宫的声音（心跳声），带给他熟悉而温暖的安全感。' WHERE id = 'fec1f9db-8b95-410a-b753-aded5a7dc606' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lavarse los dientes es divertido! 🪥', body_es = '¿No deja que le acerques el cepillo a la boca? Mira en Productos recomendados los cepillos de dedo o los modelos con luz y música y convierte la higiene en un juego.', title_fr = 'Se brosser les dents, c''est amusant ! 🪥', body_fr = 'Il refuse qu''on approche la brosse de sa bouche ? Regardez dans les Produits recommandés les brosses à doigt ou les modèles lumineux et musicaux pour transformer ce moment d''hygiène en jeu.', title_hi = 'दाँत साफ़ करना मज़ेदार है! 🪥', body_hi = 'ब्रश मुँह के पास भी नहीं आने देता? सुझाए गए प्रोडक्ट में फ़िंगर ब्रश या लाइट और संगीत वाले मॉडल देखकर सफ़ाई को खेल बना दीजिए।', title_id = 'Menyikat gigi itu seru! 🪥', body_id = 'Ia tidak mau sikat gigi didekatkan ke mulutnya? Lihat sikat gigi jari atau model bercahaya dan bermusik di Produk Rekomendasi, dan jadikan kebiasaan bersih ini sebuah permainan.', title_ja = '歯みがきは楽しい！🪥', body_ja = '歯ブラシを口に近づけさせてくれない？「おすすめ商品」で指歯ブラシや、光る・音楽が鳴るタイプを見て、歯みがきを遊びに変えましょう。', title_ko = '양치는 즐거워요! 🪥', body_ko = '칫솔을 입 근처에도 못 오게 하나요? 추천 제품에서 손가락 칫솔이나 불빛과 음악이 나오는 칫솔을 살펴보고 양치를 놀이로 만들어 보세요.', title_nl = 'Tandenpoetsen is leuk! 🪥', body_nl = 'Laat je kindje de tandenborstel niet in de buurt van zijn mond komen? Bekijk vingertandenborstels of modellen met lichtjes en muziek in Aanbevolen producten en maak van poetsen een spelletje.', title_pl = 'Mycie zębów to zabawa! 🪥', body_pl = 'Nie pozwala zbliżyć szczoteczki do buzi? Zajrzyj w Polecanych produktach do szczoteczek na palec albo modeli ze światełkiem i muzyką i zamień higienę w zabawę.', title_pt = 'Lavar os dentes é divertido! 🪥', body_pt = 'Não deixa a escova aproximar-se da boca? Veja nos Produtos Recomendados escovas de dedo ou modelos com luz e música e transforme a higiene num jogo.', title_sv = 'Tandborstning är roligt! 🪥', body_sv = 'Släpper barnet inte tandborsten nära munnen? Gör hygienen till lek genom att titta på fingertandborstar eller modeller med ljus och musik i Rekommenderade produkter.', title_vi = 'Đánh răng thật vui! 🪥', body_vi = 'Bé không cho đưa bàn chải lại gần miệng? Hãy xem bàn chải xỏ ngón hay những mẫu có đèn, có nhạc trong Sản phẩm gợi ý để biến việc vệ sinh này thành trò chơi.', title_zh = '刷牙真好玩！🪥', body_zh = '牙刷一靠近嘴巴就不让？看看推荐商品里的指套牙刷，或者会发光、有音乐的款式，把刷牙变成游戏吧。' WHERE id = '5c635a69-e5ff-42eb-9277-29e39d9986fa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la noche 🍵', body_es = 'Se ha dormido y el temporizador se ha parado. Ahora no toca correr, sino descansar. Prepárate una manzanilla de Recetas saludables y disfruta de verdad de la calma.', title_fr = 'Le calme de la nuit 🍵', body_fr = 'Il dort, le minuteur est arrêté. Ce n''est plus l''heure de courir, mais de vous reposer. Préparez une infusion de camomille grâce aux Recettes saines et savourez pleinement le calme.', title_hi = 'रात की शांति 🍵', body_hi = 'बच्चा सो गया, टाइमर रुक गया। अब भागने का नहीं, आराम का समय है। सेहतमंद रेसिपी से कैमोमाइल चाय बनाइए और शांति का पूरा आनंद लीजिए।', title_id = 'Ketenangan malam 🍵', body_id = 'Si kecil sudah tidur, timer sudah berhenti. Sekarang bukan waktunya berlari, tapi beristirahat. Seduh teh chamomile dari Resep Sehat dan nikmati ketenangannya.', title_ja = '夜の静けさ 🍵', body_ja = 'お子さんが眠り、タイマーも止まりました。今は走るときではなく、休むときです。「ヘルシーレシピ」からカモミールティーをいれて、静けさをしっかり味わいましょう。', title_ko = '고요한 밤 🍵', body_ko = '아이가 잠들고 타이머도 멈췄어요. 이제 뛰어다닐 때가 아니라 쉴 때예요. 건강한 레시피에서 캐모마일차를 우려 고요함을 꼭 즐기세요.', title_nl = 'De stilte van de avond 🍵', body_nl = 'Je kindje slaapt, de timer staat stil. Nu is het tijd om uit te rusten, niet om te rennen. Zet kamillethee uit Gezonde recepten en geniet echt van de stilte.', title_pl = 'Nocna cisza 🍵', body_pl = 'Maluszek śpi, timer zatrzymany. Teraz czas nie na bieganie, tylko na odpoczynek. Zaparz rumianek ze zdrowych przepisów i koniecznie delektuj się ciszą.', title_pt = 'A tranquilidade da noite 🍵', body_pt = 'Ele adormeceu e o temporizador parou. Agora não é hora de correr, é hora de descansar. Prepare um chá de camomila das Receitas Saudáveis e aproveite a calma.', title_sv = 'Nattens stillhet 🍵', body_sv = 'Barnet sover, timern har stannat. Nu är det inte dags att springa, utan att vila. Brygg kamomillte från Hälsosamma recept och njut av lugnet.', title_vi = 'Sự tĩnh lặng của màn đêm 🍵', body_vi = 'Bé ngủ rồi, bộ hẹn giờ đã dừng. Giờ không phải lúc chạy đôn chạy đáo mà là lúc nghỉ ngơi. Hãy pha trà hoa cúc từ Công thức lành mạnh và tận hưởng sự yên tĩnh.', title_zh = '夜晚的宁静 🍵', body_zh = '宝宝睡了，计时器也停了。现在不是奔忙的时候，而是休息的时候。从健康食谱里泡一杯洋甘菊茶，好好享受这份安静吧。' WHERE id = 'f2a19104-ece3-4a8f-9966-8cad392a68af' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Me visto yo solo! 👕', body_es = '¿Por las mañanas vestirle es una batalla? Lee en el Blog formas prácticas de resolver estas crisis dándole opciones para elegir.', title_fr = 'Je m''habille tout seul ! 👕', body_fr = 'L''habillage du matin tourne à la bataille ? Lisez dans les Blogs des astuces pratiques pour désamorcer ces crises en lui proposant des choix.', title_hi = 'मैं खुद पहनूँगा! 👕', body_hi = 'सुबह कपड़े पहनाते समय बड़ा झगड़ा होता है? ब्लॉग सेक्शन में बच्चे को विकल्प देकर कपड़े पहनने के झगड़े सुलझाने के व्यावहारिक तरीके पढ़िए।', title_id = 'Aku pakai baju sendiri! 👕', body_id = 'Setiap pagi terjadi pertengkaran besar saat berpakaian? Baca cara praktis mengatasi krisis berpakaian dengan memberi anak pilihan di bagian Blog.', title_ja = '自分で着る！👕', body_ja = '朝の着替えが大げんかになっていませんか？ブログで、選択肢をあげて着替えのかんしゃくを解決する実践的な方法を読んでみましょう。', title_ko = '내가 입을래! 👕', body_ko = '아침마다 옷 입히다가 큰 싸움이 나나요? 블로그 섹션에서 선택지를 주며 옷 입기 떼쓰기를 해결하는 실용적인 방법을 읽어 보세요.', title_nl = 'Ik kleed me zelf aan! 👕', body_nl = 'Is aankleden ''s ochtends een grote strijd? Lees in het onderdeel Blogs praktische manieren om aankleedcrisissen op te lossen door je kindje keuzes te geven.', title_pl = 'Sam się ubiorę! 👕', body_pl = 'Poranne ubieranie kończy się wielką kłótnią? Przeczytaj w sekcji Blogi praktyczne sposoby na rozwiązywanie kryzysów przy ubieraniu dzięki dawaniu dziecku wyboru.', title_pt = 'Eu visto-me sozinho! 👕', body_pt = 'De manhã, vestir a roupa dá uma grande guerra? Leia na secção Blogues formas práticas de resolver as crises da hora de vestir, dando escolhas à criança.', title_sv = 'Jag klär på mig själv! 👕', body_sv = 'Blir det stora bråk när barnet ska klä på sig på morgonen? Läs i avsnittet Bloggar om praktiska sätt att lösa påklädningskriser genom att ge barnet valmöjligheter.', title_vi = 'Con tự mặc! 👕', body_vi = 'Sáng nào mặc đồ cũng thành cuộc chiến? Hãy đọc trong mục Blog những cách thực tế để giải quyết khủng hoảng mặc đồ bằng cách cho bé lựa chọn.', title_zh = '我要自己穿！👕', body_zh = '早上穿衣服总是大闹一场？读读博客板块里通过给孩子选择来化解穿衣危机的实用方法吧。' WHERE id = 'f524b282-4173-4386-b8dd-255261b77d1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Un gran berrinche en el súper? 🛒', body_es = '¿Se tira al suelo en un lugar público porque no le compras lo que quiere? No hagas caso de las miradas: para mantener la calma en ese momento, desahógate con Anacan AI y recibe apoyo.', title_fr = 'Grosse crise au supermarché ? 🛒', body_fr = 'Il se jette par terre en public parce qu''il n''a pas eu ce qu''il voulait ? Ignorez les regards autour de vous et, pour rester calme à ce moment-là, confiez-vous à Anacan AI et trouvez du soutien.', title_hi = 'मार्केट में ज़ोरदार चीख? 🛒', body_hi = 'सबके सामने मन की चीज़ न मिलने पर खुद को ज़मीन पर पटक देता है? आसपास की नज़रों पर ध्यान मत दीजिए, उस पल शांत रहने के लिए Anacan AI से बात करके सहारा लीजिए।', title_id = 'Teriakan besar di supermarket? 🛒', body_id = 'Ia menjatuhkan diri ke lantai di tempat umum karena keinginannya tidak dituruti? Abaikan tatapan orang sekitar, dan untuk tetap tenang saat itu juga, curhat dan dapatkan dukungan dari Anacan AI.', title_ja = 'スーパーで大泣き？🛒', body_ja = '人前で欲しいものを買ってもらえず、床にひっくり返りますか？まわりの視線は気にしないで。その場で落ち着いていられるよう、Anacan AIに話してサポートを受けましょう。', title_ko = '마트에서 대성통곡? 🛒', body_ko = '사람 많은 곳에서 원하는 걸 안 사 준다고 바닥에 드러눕나요? 주변 시선은 신경 쓰지 마세요. 그 순간 침착함을 지킬 수 있게 Anacan AI와 이야기하며 도움을 받으세요.', title_nl = 'Groot gekrijs in de supermarkt? 🛒', body_nl = 'Gooit je kindje zich in het openbaar op de grond omdat hij niet krijgt wat hij wil? Let niet op de blikken van anderen. Praat met Anacan AI en krijg steun om op dat moment rustig te blijven.', title_pl = 'Wielki krzyk w sklepie? 🛒', body_pl = 'Rzuca się na podłogę w miejscu publicznym, bo nie dostał tego, czego chciał? Nie przejmuj się spojrzeniami innych, porozmawiaj z Anacan AI, by w tej chwili zachować spokój, i otrzymaj wsparcie.', title_pt = 'Uma grande gritaria no supermercado? 🛒', body_pt = 'Atira-se para o chão em público porque não lhe compraram o que queria? Não ligue aos olhares à volta: para manter a calma nesse momento, desabafe com o Anacan AI e receba apoio.', title_sv = 'Stort skrik i affären? 🛒', body_sv = 'Kastar sig barnet på golvet på en offentlig plats för att det inte fick som det ville? Bry dig inte om blickarna, prata med Anacan AI och få stöd för att hålla dig lugn i stunden.', title_vi = 'La hét trong siêu thị? 🛒', body_vi = 'Ở nơi công cộng không được mua thứ mình muốn là bé ném mình xuống sàn? Đừng bận tâm ánh mắt xung quanh, hãy tâm sự với Anacan AI để được hỗ trợ giữ bình tĩnh lúc ấy.', title_zh = '超市里的大哭大闹？🛒', body_zh = '在公共场合因为没买到想要的东西就往地上一躺？别在意周围的目光，那一刻向Anacan AI倾诉，获得保持冷静的支持吧。' WHERE id = '46919051-4727-4a43-8ba3-d5a1f5451c16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Frases de dos palabras! 🗣️', body_es = '¿Hoy ha formado una combinación nueva como «Mamá, ven» o «Tira pelota»? Guarda enseguida este gran avance del lenguaje en un vídeo con sonido en el Álbum del bebé.', title_fr = 'Des phrases de deux mots ! 🗣️', body_fr = 'Aujourd''hui, il a formé une nouvelle association comme « Maman viens » ou « Lance ballon » ? Enregistrez tout de suite ce magnifique progrès du langage en vidéo avec le son dans l''Album de bébé.', title_hi = 'दो शब्दों वाले वाक्य! 🗣️', body_hi = 'आज उसने ''माँ आओ'' या ''गेंद फेंको'' जैसा नया जोड़ बनाया? भाषा के इस शानदार विकास को तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में सहेज लीजिए।', title_id = 'Kalimat dua kata! 🗣️', body_id = 'Hari ini ia merangkai gabungan kata baru seperti "Mama sini" atau "Lempar bola"? Segera simpan perkembangan bahasa yang luar biasa ini sebagai video bersuara di Album Bayi.', title_ja = '2語文！🗣️', body_ja = '今日「ママ、きて」「ボール、なげて」のような新しい言葉の組み合わせができましたか？このすばらしい言葉の成長を、音声つきの動画ですぐに「ベビーアルバム」に保存しましょう。', title_ko = '두 단어 문장! 🗣️', body_ko = '오늘 "엄마 와"나 "공 던져" 같은 새 조합을 말했나요? 이 놀라운 언어 발달을 소리가 담긴 영상으로 바로 아기 앨범에 남기세요.', title_nl = 'Zinnetjes van twee woorden! 🗣️', body_nl = 'Maakte je kindje vandaag een nieuwe combinatie zoals mama kom of bal gooien? Leg deze geweldige taalontwikkeling meteen vast als video met geluid in het Babyalbum.', title_pl = 'Zdania z dwóch słów! 🗣️', body_pl = 'Złożył dziś nowe połączenie słów, np. „mama chodź” albo „rzuć piłkę”? Od razu zapisz ten wspaniały postęp w mowie jako filmik z dźwiękiem w Albumie dziecka.', title_pt = 'Frases de duas palavras! 🗣️', body_pt = 'Hoje juntou palavras de uma forma nova, como "Mamã, vem" ou "Atira bola"? Guarde já no Álbum do Bebé este fantástico avanço na linguagem num vídeo com som.', title_sv = 'Meningar med två ord! 🗣️', body_sv = 'Satte barnet i dag ihop en ny kombination som ”Mamma kom” eller ”Kasta boll”? Spara direkt denna fantastiska språkutveckling som video med ljud i Babyalbumet.', title_vi = 'Câu hai từ! 🗣️', body_vi = 'Hôm nay bé ghép được câu mới như "Mẹ lại đây" hay "Ném bóng"? Hãy lưu ngay bước phát triển ngôn ngữ tuyệt vời này vào Album của bé dưới dạng video có tiếng.', title_zh = '两个词的句子！🗣️', body_zh = '今天他说出了“妈妈来”或“扔球”这样的新组合？马上把这个了不起的语言进步录成有声视频，存进宝宝相册吧。' WHERE id = '874df706-e26e-4b72-a02c-7f8309fc95d5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Motricidad de los dedos en acción! 🧩', body_es = 'Deja que coma solo guisantes, maíz o fruta troceada. Así desarrolla la motricidad fina. Controla la ración con el Seguimiento de tomas.', title_fr = 'La motricité des doigts en action ! 🧩', body_fr = 'Laissez-le manger seul des petits pois, du maïs ou des fruits coupés. Cela développe sa motricité fine. Surveillez les portions avec le Suivi des repas.', title_hi = 'उँगलियों की मोटर स्किल्स काम पर! 🧩', body_hi = 'मटर, मक्का या कटे फल उसे खुद खाने दीजिए। इससे बारीक मोटर स्किल्स विकसित होती हैं। फ़ीडिंग ट्रैकर से हिस्से पर नज़र रखिए।', title_id = 'Motorik jari sedang beraksi! 🧩', body_id = 'Biarkan ia makan sendiri kacang polong, jagung, atau potongan buah. Ini mengembangkan motorik halusnya. Pantau porsinya dengan alat Pemantau Makan.', title_ja = '指先の力が活躍中！🧩', body_ja = 'ひよこ豆やコーン、小さく切った果物を自分で食べさせてあげましょう。指先の発達につながります。「栄養管理ツール」で量も見守りましょう。', title_ko = '손가락 근육 작업 중! 🧩', body_ko = '완두콩, 옥수수, 잘게 썬 과일을 혼자 집어 먹게 해 주세요. 소근육이 발달해요. 수유 기록으로 먹는 양을 살펴보세요.', title_nl = 'De vingermotoriek aan het werk! 🧩', body_nl = 'Laat je kindje zelf erwtjes, maïs of stukjes fruit eten. Dat ontwikkelt de fijne motoriek. Volg de portie met de Voedingstracker.', title_pl = 'Motoryka palców w akcji! 🧩', body_pl = 'Pozwól mu samodzielnie jeść groszek, kukurydzę lub pokrojone owoce. To rozwija motorykę małą. Śledź porcje w narzędziu do śledzenia karmienia.', title_pt = 'A motricidade dos dedos em ação! 🧩', body_pt = 'Deixe-o comer sozinho grão-de-bico, milho ou fruta às pedaços. Isso desenvolve a motricidade fina. Acompanhe a porção com o Registo de Alimentação.', title_sv = 'Fingermotoriken i arbete! 🧩', body_sv = 'Låt barnet äta ärtor, majs eller skuren frukt själv. Det utvecklar finmotoriken. Följ portionen med Matningskoll.', title_vi = 'Vận động tinh của ngón tay đang làm việc! 🧩', body_vi = 'Hãy để bé tự ăn đậu Hà Lan, ngô hay trái cây cắt nhỏ. Điều này giúp phát triển vận động tinh. Theo dõi khẩu phần bằng công cụ Theo dõi cữ bú.', title_zh = '手指精细动作在发展！🧩', body_zh = '让他自己吃豌豆、玉米或切好的水果吧。这能锻炼精细动作。用喂养记录关注一下分量。' WHERE id = 'af368cd3-f751-4611-9e47-9c8fda037ebd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Refuerza sus defensas! 🍊', body_es = '¿Cambia el tiempo? Calcula con el Seguimiento de tomas la vitamina C de hoy y añade al menú cítricos, kiwi o pimientos de colores.', title_fr = 'Un coup de pouce pour l''immunité ! 🍊', body_fr = 'Le temps change ? Calculez ses apports en vitamine C du jour avec le Suivi des repas et ajoutez au menu des agrumes, du kiwi ou des poivrons colorés.', title_hi = 'इम्यूनिटी को सहारा! 🍊', body_hi = 'मौसम बदल रहा है? फ़ीडिंग ट्रैकर से आज के विटामिन C का हिसाब लगाइए और मेन्यू में खट्टे फल, कीवी या रंगीन शिमला मिर्च जोड़िए।', title_id = 'Dukungan untuk kekebalan tubuh! 🍊', body_id = 'Cuaca sedang berubah? Hitung asupan Vitamin C hari ini dengan alat Pemantau Makan dan tambahkan jeruk, kiwi, atau paprika berwarna ke menu.', title_ja = '免疫をサポート！🍊', body_ja = '季節の変わり目ですか？「栄養管理ツール」で今日のビタミンCの摂取量を計算して、メニューに柑橘類やキウイ、カラフルなパプリカを加えましょう。', title_ko = '면역력을 지켜요! 🍊', body_ko = '환절기인가요? 수유 기록 도구로 오늘 비타민 C 섭취량을 계산하고 식단에 감귤류, 키위, 알록달록한 파프리카를 더해 보세요.', title_nl = 'Steun voor de weerstand! 🍊', body_nl = 'Verandert het weer? Bereken met de Voedingstracker de inname van vitamine C van vandaag en voeg citrusfruit, kiwi of kleurrijke paprika toe aan het menu.', title_pl = 'Wsparcie odporności! 🍊', body_pl = 'Pogoda się zmienia? Oblicz w narzędziu do śledzenia karmienia dzisiejsze spożycie witaminy C i dodaj do menu cytrusy, kiwi lub kolorową paprykę.', title_pt = 'Apoio à imunidade! 🍊', body_pt = 'O tempo está a mudar? Calcule com o Registo de Alimentação a vitamina C de hoje e junte à ementa citrinos, kiwi ou pimentos coloridos.', title_sv = 'Stöd för immunförsvaret! 🍊', body_sv = 'Växlar vädret? Räkna ut dagens intag av C-vitamin med Matningskoll och lägg till citrusfrukter, kiwi eller färgglad paprika i menyn.', title_vi = 'Hỗ trợ miễn dịch! 🍊', body_vi = 'Thời tiết đang thay đổi? Hãy tính lượng vitamin C hôm nay bằng công cụ Theo dõi cữ bú và thêm cam quýt, kiwi hay ớt chuông nhiều màu vào thực đơn.', title_zh = '支持免疫力！🍊', body_zh = '换季了？用喂养记录工具算算今天的维生素C摄入量，在菜单里加些柑橘、猕猴桃或彩椒吧。' WHERE id = '1f770df3-c7ef-4bf3-8564-f5ddd0b6a323' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Eres una madre entregada y maravillosa! Abre el Diario de ánimo, anota hasta el gesto más pequeño que hayas tenido hoy con tu peque y siéntete orgullosa de ti.', body_fr = 'Vous êtes une maman si dévouée et si formidable ! Ouvrez le Journal d''humeur, notez même la plus petite attention que vous avez eue pour votre enfant aujourd''hui, et soyez fière de vous.', body_hi = 'आप कितनी समर्पित और प्यारी माँ हैं! मूड डायरी खोलिए और आज अपने बच्चे के लिए की गई छोटी से छोटी भलाई भी लिखकर खुद पर गर्व कीजिए।', body_id = 'Anda ibu yang begitu penuh pengorbanan dan luar biasa! Buka Buku Harian Suasana Hati, catat bahkan kebaikan terkecil yang Anda lakukan untuk si kecil hari ini, dan banggalah pada diri sendiri.', body_ja = 'あなたはなんて献身的ですてきなママでしょう！「気分日記」を開いて、今日お子さんのためにしたほんの小さなことも書きとめ、自分を誇りに思いましょう。', body_ko = '정말 헌신적이고 멋진 엄마예요! 기분 일기를 열고 오늘 아이를 위해 한 아주 작은 일까지 적으며 스스로를 자랑스러워하세요.', body_nl = 'Wat ben je een toegewijde, lieve moeder! Open je Stemmingsdagboek, schrijf zelfs het kleinste wat je vandaag voor je kindje hebt gedaan op en wees trots op jezelf.', body_pl = 'Jesteś taką oddaną i wspaniałą mamą! Otwórz Dziennik nastroju, zapisz nawet najmniejszą dobrą rzecz, którą dziś zrobiłaś dla dziecka, i bądź z siebie dumna.', body_pt = 'É uma mãe tão dedicada e maravilhosa! Abra o Diário de Humor, registe até o mais pequeno gesto de carinho que fez hoje pelo seu filho e orgulhe-se de si.', body_sv = 'Du är en så uppoffrande och fin mamma! Öppna Humördagboken, anteckna även det minsta goda du gjort för ditt barn i dag och var stolt över dig själv.', body_vi = 'Mẹ là người mẹ thật tận tụy và tuyệt vời! Hãy mở Nhật ký tâm trạng, ghi lại dù chỉ là việc tốt nhỏ nhất mẹ làm cho bé hôm nay và tự hào về bản thân.', body_zh = '你是多么无私又美好的妈妈！打开心情日记，哪怕是今天为孩子做的最小的一件好事也记下来，为自己骄傲吧。' WHERE id = '28cf8172-0a76-4afd-b2de-765879c7939a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primer contacto con el orinal 🚽', body_es = 'Aunque aún es pronto, tener el orinal en el baño le prepara visualmente. Mira en Productos recomendados modelos cómodos y llamativos que capten su atención.', title_fr = 'Première rencontre avec le pot 🚽', body_fr = 'Même s''il est encore tôt, garder un pot dans la salle de bain l''y prépare visuellement. Découvrez dans les Produits recommandés des modèles confortables et attrayants qui attireront son attention.', title_hi = 'पॉटी से पहली पहचान 🚽', body_hi = 'भले अभी जल्दी हो, पॉटी को बाथरूम में रखने से उसे देखकर तैयारी होती है। सुझाए गए प्रोडक्ट में उसका ध्यान खींचने वाले आरामदायक और दिलचस्प मॉडल देखिए।', title_id = 'Perkenalan pertama dengan pispot 🚽', body_id = 'Meski masih terlalu dini, menaruh pispot di kamar mandi memberi persiapan visual. Lihat model yang nyaman dan menarik perhatiannya di Produk Rekomendasi.', title_ja = 'おまるとのはじめての出会い 🚽', body_ja = 'まだ早くても、おまるをバスルームに置いておくと、目で見て慣れる準備になります。「おすすめ商品」で、お子さんの興味を引く使いやすいモデルを見てみましょう。', title_ko = '아기 변기와의 첫 만남 🚽', body_ko = '아직 이르지만 아기 변기를 욕실에 두면 눈으로 먼저 익숙해질 수 있어요. 추천 제품에서 관심을 끌 만한 편하고 재미있는 모델을 살펴보세요.', title_nl = 'Eerste kennismaking met het potje 🚽', body_nl = 'Ook al is het nog vroeg, het potje in de badkamer laten staan maakt je kindje er alvast vertrouwd mee. Bekijk in Aanbevolen producten handige, leuke modellen die zijn aandacht trekken.', title_pl = 'Pierwsze spotkanie z nocnikiem 🚽', body_pl = 'Choć to jeszcze wcześnie, nocnik stojący w łazience oswaja go wzrokowo. Zajrzyj do Polecanych produktów po wygodne i ciekawe modele, które przyciągną jego uwagę.', title_pt = 'O primeiro contacto com o bacio 🚽', body_pt = 'Mesmo que ainda seja cedo, ter o bacio na casa de banho cria uma preparação visual. Veja nos Produtos Recomendados modelos confortáveis e interessantes que lhe chamem a atenção.', title_sv = 'Första mötet med pottan 🚽', body_sv = 'Även om det är tidigt skapar det en visuell förberedelse att ha pottan i badrummet. Titta på bekväma och spännande modeller som fångar barnets intresse i Rekommenderade produkter.', title_vi = 'Làm quen với bô 🚽', body_vi = 'Dù vẫn còn sớm, để bô trong phòng tắm giúp bé làm quen bằng mắt. Hãy xem những mẫu bô thoải mái, thú vị thu hút bé trong Sản phẩm gợi ý.', title_zh = '初识小马桶 🚽', body_zh = '虽然还早，但把小马桶放在浴室里能带来视觉上的准备。看看推荐商品里能吸引他注意的舒适又有趣的款式吧。' WHERE id = 'f00a5e44-ed12-4c77-9249-e4246b2b108d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exceso de estímulos 🎇', body_es = 'Un cerebro muy activo durante el día no consigue frenar por la noche. Pon el sonido del secador o del ventilador en Ruido blanco y comprueba cómo le calma la monotonía.', title_fr = 'Trop d''excitation 🎇', body_fr = 'Un cerveau très actif le jour a du mal à ralentir la nuit. Lancez le bruit du sèche-cheveux ou du ventilateur dans les Bruits blancs et voyez comme la monotonie l''apaise.', title_hi = 'ज़रूरत से ज़्यादा जागरूकता 🎇', body_hi = 'दिन में बहुत सक्रिय दिमाग रात को ब्रेक नहीं लगा पाता। व्हाइट नॉइज़ से हेयर ड्रायर या पंखे की आवाज़ चलाइए और देखिए कि एक जैसी आवाज़ उसे कैसे शांत करती है।', title_id = 'Terlalu bersemangat 🎇', body_id = 'Otak yang terlalu aktif di siang hari sulit mengerem di malam hari. Putar suara pengering rambut atau kipas angin dari Suara Putih dan lihat bagaimana suara monoton menenangkannya.', title_ja = '刺激を受けすぎ 🎇', body_ja = '日中とても活発だった脳は、夜にブレーキがかかりにくいもの。「ホワイトノイズ」からドライヤーや扇風機の音を流して、単調な音がどう落ち着かせるか見てみましょう。', title_ko = '과도한 흥분 🎇', body_ko = '낮에 너무 활발했던 뇌는 밤에 브레이크를 걸지 못할 수 있어요. 백색소음에서 헤어드라이어나 선풍기 소리를 틀어 단조로운 소리가 아이를 어떻게 진정시키는지 보세요.', title_nl = 'Overprikkeld 🎇', body_nl = 'Een hoofdje dat overdag erg actief was, kan ''s nachts niet afremmen. Zet in Witte ruis het geluid van een föhn of ventilator aan en zie hoe het eentonige geluid hem kalmeert.', title_pl = 'Nadmierne pobudzenie 🎇', body_pl = 'Mózg bardzo aktywny w dzień nie potrafi w nocy zwolnić. Włącz w Białym szumie dźwięk suszarki lub wentylatora i zobacz, jak monotonia go uspokaja.', title_pt = 'Excesso de estímulos 🎇', body_pt = 'Um cérebro muito ativo durante o dia não consegue travar à noite. Ligue no Ruído Branco o som do secador ou da ventoinha e veja como a monotonia o acalma.', title_sv = 'Överstimulering 🎇', body_sv = 'En hjärna som är väldigt aktiv på dagen kan inte bromsa in på natten. Sätt på ljudet av hårtork eller fläkt i Vitt brus och se hur monotonin lugnar barnet.', title_vi = 'Bị kích thích quá mức 🎇', body_vi = 'Bộ não quá hoạt động ban ngày khó "phanh" lại vào ban đêm. Hãy bật tiếng máy sấy tóc hoặc quạt trong Tiếng ồn trắng và xem âm thanh đều đều giúp bé dịu lại thế nào.', title_zh = '过度兴奋 🎇', body_zh = '白天太活跃的大脑，晚上可能刹不住车。在白噪音里放吹风机或电风扇的声音，看看单调的声音如何让他平静下来。' WHERE id = 'f830cd97-a8bb-4789-bdc5-7806bcd89cfe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te sigue cayendo el pelo? 💇‍♀️', body_es = 'Tu cuerpo sigue recuperándose. Cuídate hoy eligiendo en Recetas saludables para mujeres un desayuno rico en zinc y biotina.', title_fr = 'La chute de cheveux continue ? 💇‍♀️', body_fr = 'Votre corps est encore en train de récupérer. Prenez soin de vous aujourd''hui en choisissant dans les Recettes saines pour femmes un petit-déjeuner riche en zinc et en biotine.', title_hi = 'बाल झड़ना जारी है? 💇‍♀️', body_hi = 'आपका शरीर अब भी रिकवरी में है। महिलाओं के लिए सेहतमंद रेसिपी से ज़िंक और बायोटिन से भरपूर नाश्ता चुनकर आज अपना ख्याल रखिए।', title_id = 'Rambut masih rontok? 💇‍♀️', body_id = 'Tubuh Anda masih dalam proses pemulihan. Rawat diri Anda hari ini dengan memilih menu sarapan kaya zinc dan biotin dari Resep Sehat untuk wanita.', title_ja = '抜け毛が続いている？💇‍♀️', body_ja = '体はまだ回復の途中です。「女性のためのヘルシーレシピ」から亜鉛とビオチンたっぷりの朝食メニューを選んで、今日は自分をいたわりましょう。', title_ko = '머리카락이 계속 빠지나요? 💇‍♀️', body_ko = '몸은 아직 회복 중이에요. 건강한 레시피에서 아연과 비오틴이 풍부한 아침 메뉴를 골라 오늘은 나를 돌봐 주세요.', title_nl = 'Valt je haar nog steeds uit? 💇‍♀️', body_nl = 'Je lichaam is nog aan het herstellen. Zorg vandaag goed voor jezelf en kies in Gezonde recepten voor vrouwen een ontbijt vol zink en biotine.', title_pl = 'Włosy wciąż wypadają? 💇‍♀️', body_pl = 'Twoje ciało wciąż się regeneruje. Zadbaj dziś o siebie, wybierając ze Zdrowych przepisów dla kobiet śniadanie bogate w cynk i biotynę.', title_pt = 'A queda de cabelo continua? 💇‍♀️', body_pt = 'O seu corpo ainda está em recuperação. Cuide de si hoje escolhendo nas Receitas Saudáveis para Mulheres um pequeno-almoço rico em zinco e biotina.', title_sv = 'Fortsätter håravfallet? 💇‍♀️', body_sv = 'Din kropp återhämtar sig fortfarande. Ta hand om dig själv i dag genom att välja en frukostmeny rik på zink och biotin från Hälsosamma recept för kvinnor.', title_vi = 'Tóc vẫn rụng? 💇‍♀️', body_vi = 'Cơ thể mẹ vẫn đang trong quá trình hồi phục. Hôm nay hãy chăm sóc bản thân bằng một thực đơn sáng giàu kẽm và biotin từ Công thức lành mạnh cho phụ nữ.', title_zh = '还在掉头发？💇‍♀️', body_zh = '你的身体还在恢复中。从女性健康食谱里选一份富含锌和生物素的早餐，今天好好照顾自己吧。' WHERE id = '1915583e-53f5-46af-8212-835dfd587e22' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa de los instrumentos musicales 🥁', body_es = '¿Le encanta aporrear las ollas con cucharas de madera? Mira en Productos recomendados xilófonos y tambores con un volumen seguro para sus oídos.', title_fr = 'La période des instruments de musique 🥁', body_fr = 'Il adore taper sur les casseroles avec des cuillères en bois ? Découvrez dans les Produits recommandés des xylophones et des tambours dont le volume est sans danger pour ses oreilles.', title_hi = 'म्यूज़िकल इंस्ट्रूमेंट का दौर 🥁', body_hi = 'लकड़ी के चम्मच से पतीले बजाना पसंद है? सुझाए गए प्रोडक्ट में ऐसे ज़ाइलोफ़ोन और ड्रम देखिए जिनकी आवाज़ बच्चे के कानों के लिए सुरक्षित हो।', title_id = 'Masa alat musik 🥁', body_id = 'Ia senang memukul-mukul panci dengan sendok kayu? Lihat xilofon dan drum dengan tingkat suara yang aman untuk telinga anak di Produk Rekomendasi.', title_ja = '楽器の時期 🥁', body_ja = '木のスプーンでお鍋をたたくのが大好き？「おすすめ商品」で、子どもの耳に安全な音量の木琴や太鼓を見てみましょう。', title_ko = '악기 시기 🥁', body_ko = '나무 숟가락으로 냄비 두드리기를 좋아하나요? 추천 제품에서 아이 귀에 안전한 소리 크기의 실로폰과 북을 살펴보세요.', title_nl = 'De fase van muziekinstrumenten 🥁', body_nl = 'Trommelt je kindje graag met houten lepels op pannen? Bekijk in Aanbevolen producten xylofoons en trommels met een geluidsniveau dat veilig is voor kinderoortjes.', title_pl = 'Czas instrumentów muzycznych 🥁', body_pl = 'Uwielbia walić drewnianymi łyżkami w garnki? Zajrzyj do Polecanych produktów po cymbałki i bębenki o głośności bezpiecznej dla uszu dziecka.', title_pt = 'A fase dos instrumentos musicais 🥁', body_pt = 'Adora bater nos tachos com colheres de pau? Veja nos Produtos Recomendados xilofones e tambores com volume seguro para os ouvidos das crianças.', title_sv = 'Musikinstrumentens tid 🥁', body_sv = 'Älskar barnet att trumma på kastruller med träslevar? Titta efter xylofoner och trummor med en ljudnivå som är säker för barnöron i Rekommenderade produkter.', title_vi = 'Giai đoạn nhạc cụ 🥁', body_vi = 'Bé thích lấy thìa gỗ gõ vào nồi? Hãy xem đàn xylophone và trống có âm lượng an toàn cho tai trẻ trong Sản phẩm gợi ý.', title_zh = '乐器时期 🥁', body_zh = '喜欢用木勺敲锅？在推荐商品里看看音量对孩子耳朵安全的木琴和小鼓吧。' WHERE id = 'cfbeabf3-def0-4cbe-a106-fd34987dd776' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Come menos, ¿y el peso? 📉', body_es = 'En estos meses aumenta la selectividad con la comida. Introduce las cifras actuales en el Registro de peso, comprueba que en realidad su desarrollo va perfectamente y quédate tranquila.', title_fr = 'Moins d''appétit, et le poids ? 📉', body_fr = 'À ces âges, il devient souvent plus difficile à table. Saisissez ses mesures actuelles dans le Suivi du poids : vous verrez que sa croissance est tout à fait normale et vous serez vite rassurée.', title_hi = 'भूख कम हुई, पर वज़न? 📉', body_hi = 'इन महीनों में खाने के नखरे बढ़ जाते हैं। वेट ट्रैकर में ताज़ा आँकड़े डालिए, देखिए कि विकास असल में बिल्कुल सामान्य है, और तुरंत निश्चिंत हो जाइए।', title_id = 'Nafsu makan turun, bagaimana beratnya? 📉', body_id = 'Di bulan-bulan ini anak makin pilih-pilih makanan. Masukkan angka terbarunya di Pelacak Berat Badan, lihat bahwa pertumbuhannya sebenarnya normal, dan langsung tenang.', title_ja = '食欲が落ちたけど、体重は？📉', body_ja = 'この時期は好き嫌いが増えます。「体重トラッカー」に今の数値を入れて、成長が実はしっかり目安どおりだと確かめ、ほっとしましょう。', title_ko = '입맛이 줄었는데, 몸무게는? 📉', body_ko = '요즘은 음식을 가리는 일이 늘어요. 체중 기록에 현재 수치를 입력해 성장이 사실 정상 범위라는 걸 확인하고 마음을 놓으세요.', title_nl = 'Minder eetlust, maar het gewicht? 📉', body_nl = 'In deze maanden wordt kieskeurig eten vaak erger. Voer de huidige cijfers in de Gewichtstracker in, zie dat de groei eigenlijk helemaal normaal verloopt en stel jezelf meteen gerust.', title_pl = 'Apetyt spadł, a waga? 📉', body_pl = 'W tych miesiącach wybiórczość w jedzeniu rośnie. Wpisz aktualne liczby w Liczniku wagi, zobacz, że rozwój tak naprawdę jest w normie, i od razu odetchnij.', title_pt = 'O apetite diminuiu, e o peso? 📉', body_pt = 'Nestes meses, a esquisitice à mesa aumenta. Introduza os números atuais no Registo de Peso, veja que o crescimento está perfeitamente dentro do normal e descanse.', title_sv = 'Aptiten har minskat, men vikten? 📉', body_sv = 'Kräsenheten ökar de här månaderna. Lägg in aktuella siffror i Viktspåraren, se att utvecklingen faktiskt följer normen och slappna av direkt.', title_vi = 'Bé ăn ít đi, còn cân nặng thì sao? 📉', body_vi = 'Những tháng này bé thường kén ăn hơn. Hãy nhập số đo hiện tại vào Theo dõi cân nặng để thấy sự phát triển thực ra vẫn hoàn toàn bình thường và yên tâm ngay.', title_zh = '胃口变小了，那体重呢？📉', body_zh = '这几个月挑食会加重。在体重记录里输入当前的数字，看到发育其实完全在正常范围内，马上就能安心了。' WHERE id = '2ed7fd17-90ba-451d-9c88-a1f94a180fe0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rituales para ir a dormir 🧸', body_es = '¡Cada noche, el mismo orden! Activa el Temporizador de sueño, haz que dé las buenas noches a su osito favorito y observa cómo esta constancia le ayuda a dormirse.', title_fr = 'Les rituels avant de dormir 🧸', body_fr = 'Le même ordre chaque soir ! Lancez le minuteur de sommeil, faites-lui dire bonne nuit à son nounours préféré et notez comme cette régularité facilite l''endormissement.', title_hi = 'सोने की तैयारी की रस्में 🧸', body_hi = 'हर शाम एक ही क्रम! स्लीप टाइमर चालू कीजिए, उससे अपने पसंदीदा टेडी को ''गुड नाइट'' कहलवाइए और दर्ज कीजिए कि यह नियमितता नींद में जाना कैसे आसान बनाती है।', title_id = 'Ritual menjelang tidur 🧸', body_id = 'Urutan yang sama setiap malam! Nyalakan Timer Tidur, ajak ia mengucapkan "Selamat malam" pada boneka beruang kesayangannya, dan catat bagaimana konsistensi ini memudahkan peralihan ke tidur.', title_ja = '眠りの準備の儀式 🧸', body_ja = '毎晩同じ順番で！睡眠タイマーをオンにして、お気に入りのくまさんに「おやすみ」を言わせ、この習慣で寝つきがどれだけ楽になるか記録しましょう。', title_ko = '잠자리 준비 의식 🧸', body_ko = '매일 저녁 같은 순서로! 수면 타이머를 켜고, 좋아하는 곰 인형에게 ''잘 자''라고 인사하게 한 뒤, 이 꾸준함이 잠들기를 얼마나 쉽게 하는지 기록하세요.', title_nl = 'Rituelen voor het slapengaan 🧸', body_nl = 'Elke avond dezelfde volgorde! Zet de Slaaptimer aan, laat je kindje welterusten zeggen tegen zijn lievelingsbeer en noteer hoe deze vastigheid het inslapen makkelijker maakt.', title_pl = 'Rytuały przed snem 🧸', body_pl = 'Co wieczór ta sama kolejność! Włącz timer snu, niech powie „dobranoc” ulubionemu misiowi, i zapisz, jak ta stałość ułatwia zasypianie.', title_pt = 'Rituais de preparação para o sono 🧸', body_pt = 'Todas as noites, a mesma sequência! Ligue o temporizador de sono, peça-lhe que dê as boas-noites ao ursinho preferido e registe como esta estabilidade facilita a passagem para o sono.', title_sv = 'Ritualer inför sömnen 🧸', body_sv = 'Samma ordning varje kväll! Starta sömntimern, låt barnet säga godnatt till sin favoritnalle och anteckna hur denna stabilitet gör insomnandet lättare.', title_vi = 'Nghi thức chuẩn bị đi ngủ 🧸', body_vi = 'Mỗi tối cùng một trình tự! Hãy bật Bộ hẹn giờ ngủ, cho bé chúc gấu bông yêu thích "ngủ ngon" và ghi nhận sự ổn định này giúp bé vào giấc dễ dàng thế nào.', title_zh = '睡前仪式 🧸', body_zh = '每晚同样的顺序！打开睡眠计时器，让他对心爱的小熊说“晚安”，记录这份规律如何让入睡变得更容易。' WHERE id = '50209dd4-d2d7-4719-bf4e-21df8c72686a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Un escudo de colores para sus defensas 🛡️', body_es = 'Comprueba con el Seguimiento de tomas si hoy ha tomado suficiente vitamina C. Para verduras naranjas y rojas, consulta Recetas para bebé.', title_fr = 'Un bouclier coloré pour l''immunité 🛡️', body_fr = 'Vérifiez avec le Suivi des repas s''il a eu assez de vitamine C aujourd''hui. Pour les légumes orange et rouges, consultez les Recettes pour bébés.', title_hi = 'रंग-बिरंगी इम्यूनिटी ढाल 🛡️', body_hi = 'फ़ीडिंग ट्रैकर से जाँचिए कि आज उसे पर्याप्त विटामिन C मिला या नहीं। नारंगी और लाल सब्ज़ियों के लिए बच्चों की रेसिपी देखिए।', title_id = 'Perisai kekebalan berwarna-warni 🛡️', body_id = 'Periksa apakah hari ini ia cukup mendapat vitamin C dengan alat Pemantau Makan. Untuk sayuran oranye dan merah, lihat Resep Bayi.', title_ja = 'カラフルな免疫のシールド 🛡️', body_ja = '「栄養管理ツール」で、今日ビタミンCを十分にとれたか確認しましょう。オレンジや赤の野菜を使ったメニューはベビーレシピでどうぞ。', title_ko = '알록달록 면역 방패 🛡️', body_ko = '수유 기록 도구로 오늘 비타민 C를 충분히 섭취했는지 확인하세요. 주황색과 빨간색 채소는 아기 레시피를 참고하세요.', title_nl = 'Een kleurrijk schild voor de weerstand 🛡️', body_nl = 'Controleer met de Voedingstracker of je kindje vandaag genoeg vitamine C heeft gekregen. Kijk in de babyrecepten voor oranje en rode groenten.', title_pl = 'Kolorowa tarcza odporności 🛡️', body_pl = 'Sprawdź w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco witaminy C. Po pomysły z pomarańczowymi i czerwonymi warzywami zajrzyj do Przepisów dla maluszka.', title_pt = 'Um escudo colorido para a imunidade 🛡️', body_pt = 'Confirme com o Registo de Alimentação se hoje comeu vitamina C suficiente. Para legumes cor de laranja e vermelhos, consulte as Receitas para bebés.', title_sv = 'Färgglad sköld för immunförsvaret 🛡️', body_sv = 'Kolla med Matningskoll om barnet har fått tillräckligt med C-vitamin i dag. Titta i Babyrecept efter orange och röda grönsaker.', title_vi = 'Lá chắn miễn dịch đầy màu sắc 🛡️', body_vi = 'Hãy kiểm tra xem hôm nay bé đã nạp đủ vitamin C chưa bằng công cụ Theo dõi cữ bú. Tìm món với rau củ màu cam và đỏ trong Công thức cho bé.', title_zh = '多彩的免疫盾牌 🛡️', body_zh = '用喂养记录工具看看他今天的维生素C是否摄入足够。橙色和红色蔬菜的做法，去宝宝食谱里找吧。' WHERE id = '3abde512-ebd4-4cf1-986e-fb1953695f78' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libérate de la carga mental 🧘‍♀️', body_es = '«Tengo que hacer esto, tengo que cocinar aquello»: ¿tu mente no para? Escribe todos tus planes y miedos en el Diario de ánimo. Hacer una lista reduce el estrés al momento.', title_fr = 'Libérez-vous de la charge mentale 🧘‍♀️', body_fr = 'Je dois faire ceci, je dois cuisiner cela : votre tête ne s''arrête jamais ? Écrivez tous vos projets et vos peurs dans le Journal d''humeur. Faire une liste réduit tout de suite le stress.', title_hi = 'दिमाग के बोझ से छुटकारा 🧘‍♀️', body_hi = '''यह भी करना है, वह भी बनाना है'' - दिमाग चुप ही नहीं होता? मूड डायरी में अपनी सारी योजनाएँ और डर लिख डालिए। लिस्ट बनाने से तनाव तुरंत कम होता है।', title_id = 'Bebaskan diri dari beban pikiran 🧘‍♀️', body_id = '"Aku harus melakukan ini, memasak itu", pikiran Anda tidak bisa diam? Tulis semua rencana dan ketakutan Anda di Buku Harian Suasana Hati. Membuat daftar langsung mengurangi stres.', title_ja = '頭の中の重荷をおろそう 🧘‍♀️', body_ja = 'あれもしなきゃ、これもつくらなきゃ、と頭が休まらない？「気分日記」に予定も不安もすべて書き出しましょう。リストにするだけで、ストレスはすぐに軽くなります。', title_ko = '머릿속 짐을 내려놓으세요 🧘‍♀️', body_ko = '''이것도 해야 하고, 저것도 만들어야 하고'' 머릿속이 쉬지 않나요? 기분 일기에 모든 계획과 걱정을 적어 보세요. 목록으로 정리하면 스트레스가 바로 줄어요.', title_nl = 'Bevrijd je van de mentale last 🧘‍♀️', body_nl = 'Dit moet ik nog doen, dat moet ik nog koken: staat je hoofd nooit stil? Schrijf al je plannen en angsten op in je Stemmingsdagboek. Alles op een lijstje zetten vermindert meteen de stress.', title_pl = 'Uwolnij się od obciążenia psychicznego 🧘‍♀️', body_pl = '„Muszę zrobić to, muszę ugotować tamto” i głowa nie milknie? Zapisz w Dzienniku nastroju wszystkie plany i obawy. Spisanie ich od razu zmniejsza stres.', title_pt = 'Liberte-se da carga mental 🧘‍♀️', body_pt = '"Tenho de fazer isto, tenho de cozinhar aquilo": a cabeça não se cala? Escreva no Diário de Humor todos os seus planos e receios. Fazer uma lista reduz logo o stress.', title_sv = 'Bli fri från den mentala bördan 🧘‍♀️', body_sv = 'Jag måste göra det här, laga det där, tystnar aldrig huvudet? Skriv alla dina planer och rädslor i Humördagboken. Att skriva en lista minskar stressen direkt.', title_vi = 'Giải thoát khỏi gánh nặng tinh thần 🧘‍♀️', body_vi = '"Phải làm việc này, phải nấu món kia", đầu óc mẹ chẳng lúc nào yên? Hãy viết mọi kế hoạch và nỗi sợ vào Nhật ký tâm trạng. Liệt kê ra giúp giảm căng thẳng ngay.', title_zh = '卸下心理负担 🧘‍♀️', body_zh = '“这个要做，那个要煮”，脑子停不下来？把所有计划和担忧都写进心情日记。列成清单，压力马上就会减轻。' WHERE id = '56129e04-2f90-42b1-b51e-b835940e284e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mucho líquido, mejor digestión 💧', body_es = 'El paso total a los alimentos sólidos a veces complica la digestión. Anota en el Seguimiento de pañales y averigua fácilmente si necesita beber más agua.', title_fr = 'Beaucoup de liquides, une digestion facile 💧', body_fr = 'Le passage complet aux aliments solides complique parfois la digestion. En prenant des notes dans le Suivi des couches, voyez facilement s''il faut augmenter ses apports en eau.', title_hi = 'भरपूर तरल, आसान पाचन 💧', body_hi = 'पूरी तरह ठोस खाने पर आने से कभी-कभी पाचन मुश्किल हो जाता है। डायपर ट्रैकर में नोट्स रखकर आसानी से तय कीजिए कि पानी बढ़ाने की ज़रूरत है या नहीं।', title_id = 'Banyak cairan, pencernaan lancar 💧', body_id = 'Peralihan penuh ke makanan padat kadang membuat pencernaan lebih sulit. Dengan mencatat di Pelacak Popok, Anda bisa dengan mudah menentukan apakah asupan airnya perlu ditambah.', title_ja = 'たっぷりの水分で、すっきり消化 💧', body_ja = '固形の食事に完全に移ると、消化が難しくなることもあります。「おむつトラッカー」に記録しておけば、お水をもっと飲ませるべきかかんたんにわかります。', title_ko = '충분한 수분, 편한 소화 💧', body_ko = '고형식으로 완전히 넘어가면 소화가 힘들어질 때가 있어요. 기저귀 기록을 남기며 물을 더 마셔야 하는지 쉽게 판단해 보세요.', title_nl = 'Veel vocht, makkelijke spijsvertering 💧', body_nl = 'De volledige overstap op vaste voeding kan de spijsvertering soms lastiger maken. Houd notities bij in de Luiertracker, dan zie je makkelijk of hij meer water moet drinken.', title_pl = 'Dużo płynów, łatwe trawienie 💧', body_pl = 'Pełne przejście na stałe pokarmy czasem utrudnia trawienie. Prowadząc zapisy w narzędziu do śledzenia pieluszek, łatwo ustalisz, czy trzeba zwiększyć ilość wody.', title_pt = 'Muitos líquidos, digestão fácil 💧', body_pt = 'A passagem total para alimentos sólidos às vezes dificulta a digestão. Tome notas no Registo de Fraldas e perceba com facilidade se é preciso aumentar a ingestão de água.', title_sv = 'Mycket vätska, lätt matsmältning 💧', body_sv = 'Den fullständiga övergången till fast föda gör ibland matsmältningen svårare. Anteckna i Blöjkollen och avgör enkelt om vattenintaget behöver öka.', title_vi = 'Đủ nước, dễ tiêu hóa 💧', body_vi = 'Chuyển hẳn sang đồ ăn đặc đôi khi khiến bé khó tiêu. Hãy ghi chép trong Theo dõi tã để dễ dàng biết bé có cần uống thêm nước không.', title_zh = '多喝水，好消化 💧', body_zh = '完全转为固体食物有时会让消化变难。在尿布记录里做好记录，轻松判断是否需要多喝水。' WHERE id = '1576f605-27d8-4159-b3bd-3dd9e63c91dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Empieza el teatro de sombras! 🐰', body_es = 'Apaga la luz y haz sombras con una linterna en la pared. Graba esa carita de asombro tan tierna mientras mira esta magia para el Álbum del bebé.', title_fr = 'Le théâtre d''ombres commence ! 🐰', body_fr = 'Éteignez la lumière et créez des ombres sur le mur avec une lampe de poche. Filmez absolument son adorable air émerveillé devant cette magie pour l''Album de bébé.', title_hi = 'परछाइयों का थिएटर शुरू! 🐰', body_hi = 'कमरे की बत्ती बुझाकर टॉर्च से दीवार पर परछाइयों के आकार बनाइए। इस जादू को देखकर हैरान होने वाला उसका प्यारा चेहरा बेबी एल्बम के लिए ज़रूर रिकॉर्ड कीजिए।', title_id = 'Teater bayangan dimulai! 🐰', body_id = 'Matikan lampu kamar dan buat bayangan berbagai bentuk di dinding dengan senter. Pastikan merekam ekspresi takjubnya yang manis saat melihat keajaiban ini untuk Album Bayi.', title_ja = '影絵あそびの始まり！🐰', body_ja = '部屋の電気を消して、懐中電灯で壁に影絵をつくってみましょう。その魔法を見て驚くかわいい表情を、ぜひ「ベビーアルバム」用に撮影してください。', title_ko = '그림자 극장 시작! 🐰', body_ko = '방 불을 끄고 손전등으로 벽에 그림자 모양을 만들어 보세요. 이 마법을 보며 놀라는 사랑스러운 표정을 아기 앨범용으로 꼭 영상에 담으세요.', title_nl = 'Het schaduwtheater begint! 🐰', body_nl = 'Doe het licht uit en maak met een zaklamp schaduwfiguren op de muur. Film zeker die lieve, verbaasde blik waarmee hij naar deze magie kijkt voor het Babyalbum.', title_pl = 'Zaczyna się teatr cieni! 🐰', body_pl = 'Zgaś światło w pokoju i latarką stwórz na ścianie cieniowe postacie. Koniecznie nagraj dla Albumu dziecka tę słodką, zdumioną minę, z którą patrzy na tę magię.', title_pt = 'Começa o teatro de sombras! 🐰', body_pt = 'Apague a luz do quarto e faça figuras de sombras na parede com uma lanterna. Não deixe de filmar para o Álbum do Bebé aquela expressão doce de espanto perante esta magia.', title_sv = 'Skuggteatern börjar! 🐰', body_sv = 'Släck i rummet och gör skuggfigurer på väggen med en ficklampa. Filma barnets söta, förvånade min när det tittar på magin till Babyalbumet.', title_vi = 'Màn kịch bóng bắt đầu! 🐰', body_vi = 'Hãy tắt đèn và dùng đèn pin tạo hình bóng trên tường. Nhất định phải quay lại vẻ mặt ngạc nhiên đáng yêu của bé trước phép màu này cho Album của bé nhé.', title_zh = '影子剧场开演啦！🐰', body_zh = '关掉房间的灯，用手电筒在墙上做出影子造型。他看着这份魔法惊奇的可爱表情，一定要录下来放进宝宝相册。' WHERE id = '93141c59-a17f-414d-9f6c-c865a0650eeb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le encanta romper páginas? 📖', body_es = '¿En lugar de leer los libros quiere romperlos? Lee en el Blog los nuevos consejos sobre la importancia de los libros de cartón y de texturas a esta edad.', title_fr = 'Il a envie de déchirer les pages ? 📖', body_fr = 'Il veut déchirer les livres au lieu de les lire ? Lisez dans les Blogs nos nouvelles astuces sur l''importance des livres cartonnés et des livres à toucher à cet âge.', title_hi = 'पन्ने फाड़ने का शौक? 📖', body_hi = 'किताबें पढ़ने के बजाय फाड़ना चाहता है? इस उम्र में कार्डबोर्ड और छूकर महसूस करने वाली किताबों की अहमियत पर ब्लॉग सेक्शन के नए टिप्स पढ़िए।', title_id = 'Senang merobek halaman? 📖', body_id = 'Ia lebih ingin merobek buku daripada membacanya? Baca tips baru di bagian Blog tentang pentingnya buku karton dan buku sentuh di usia ini.', title_ja = 'ページをやぶりたい？📖', body_ja = '絵本を読むより、やぶりたがりますか？この年齢に厚紙の絵本やさわって楽しむ絵本が大切な理由について、ブログの新しいヒントを読んでみましょう。', title_ko = '책장을 찢고 싶어 하나요? 📖', body_ko = '책을 읽기보다 찢으려 하나요? 이 나이에 보드북과 촉감책이 왜 중요한지 블로그 섹션의 새 팁을 읽어 보세요.', title_nl = 'Zin om bladzijden te scheuren? 📖', body_nl = 'Wil je kindje boeken liever verscheuren dan lezen? Lees in het onderdeel Blogs de nieuwe tips over het belang van karton- en voelboekjes op deze leeftijd.', title_pl = 'Ochota na darcie kartek? 📖', body_pl = 'Zamiast czytać książki, chce je drzeć? Przeczytaj w sekcji Blogi nowe wskazówki o tym, jak ważne są w tym wieku książeczki kartonowe i sensoryczne.', title_pt = 'Vontade de rasgar as páginas? 📖', body_pt = 'Em vez de ler os livros, quer rasgá-los? Leia na secção Blogues as novas dicas sobre a importância dos livros cartonados e táteis nesta idade.', title_sv = 'Lust att riva sidor? 📖', body_sv = 'Vill barnet riva sönder böckerna i stället för att läsa dem? Läs de nya tipsen i avsnittet Bloggar om varför kartongböcker och känselböcker är viktiga i den här åldern.', title_vi = 'Bé thích xé sách? 📖', body_vi = 'Bé muốn xé sách thay vì đọc? Hãy đọc những mẹo mới trong mục Blog về tầm quan trọng của sách bìa cứng và sách sờ chạm ở tuổi này.', title_zh = '爱撕书页？📖', body_zh = '他不想读书，只想把书撕开？读读博客板块里关于这个年龄纸板书和触摸书重要性的新小贴士吧。' WHERE id = 'a14c30d1-ff1f-46da-8b1e-98116e38ee0d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Del ruido al silencio 🎶', body_es = 'Pasar de golpe del ruido de la tele o los juguetes al silencio total puede asustar a los niños. Pon el sonido del tren en Ruido blanco y crea una transición suave al ambiente de sueño.', title_fr = 'Du bruit au silence 🎶', body_fr = 'Passer d''un coup du bruit de la télé ou des jouets au silence peut effrayer les enfants. Lancez le bruit du train dans les Bruits blancs pour créer une transition douce vers le sommeil.', title_hi = 'आवाज़ से खामोशी तक 🎶', body_hi = 'टीवी या खिलौनों की आवाज़ से अचानक खामोशी बच्चों को डरा सकती है। कमरे में व्हाइट नॉइज़ से ट्रेन की आवाज़ चलाकर नींद के माहौल में नरमी से ले जाइए।', title_id = 'Dari suara ke keheningan 🎶', body_id = 'Peralihan mendadak dari suara TV atau mainan ke keheningan bisa membuat anak takut. Putar suara kereta dari Suara Putih di kamar untuk menciptakan peralihan yang lembut ke suasana tidur.', title_ja = '音から静けさへ 🎶', body_ja = 'テレビやおもちゃの音から急に静かになると、こわがる子もいます。部屋で「ホワイトノイズ」から電車の音を流して、眠りの環境へやさしく切りかえましょう。', title_ko = '소리에서 고요함으로 🎶', body_ko = 'TV나 장난감 소리에서 갑자기 조용해지면 아이가 놀랄 수 있어요. 방에 백색소음의 기차 소리를 틀어 잠자는 환경으로 부드럽게 넘어가 주세요.', title_nl = 'Van geluid naar stilte 🎶', body_nl = 'Een plotselinge overgang van tv- of speelgoedgeluiden naar stilte kan kinderen laten schrikken. Zet in Witte ruis het geluid van een trein aan en zorg voor een zachte overgang naar de slaap.', title_pl = 'Od dźwięku do ciszy 🎶', body_pl = 'Nagłe przejście od telewizora lub dźwięków zabawek do ciszy może przestraszyć dziecko. Włącz w pokoju odgłos pociągu z Białego szumu i łagodnie przejdźcie do snu.', title_pt = 'Do som ao silêncio 🎶', body_pt = 'Passar de repente do som da televisão ou dos brinquedos para o silêncio pode assustar as crianças. Ligue no quarto o som do comboio no Ruído Branco e crie uma passagem suave para o ambiente de sono.', title_sv = 'Från ljud till tystnad 🎶', body_sv = 'En plötslig övergång från TV- eller leksaksljud till tystnad kan skrämma barn. Sätt på tågljud i Vitt brus i rummet och skapa en mjuk övergång till sovmiljön.', title_vi = 'Từ âm thanh đến yên lặng 🎶', body_vi = 'Chuyển đột ngột từ tiếng TV hay đồ chơi sang im lặng có thể khiến bé sợ. Hãy bật tiếng tàu hỏa trong Tiếng ồn trắng để chuyển sang không gian ngủ nhẹ nhàng.', title_zh = '从有声到安静 🎶', body_zh = '从电视或玩具的声音突然变得一片安静，可能会吓到孩子。在房间里用白噪音放火车声，为睡眠环境做一个柔和的过渡。' WHERE id = '8e7d531f-d445-43eb-a4d5-05ffff377c4f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Problemas para compartir 🧸', body_es = '¿En el parque corre hacia los juguetes de otros niños, pero no deja los suyos? Aprende con Anacan AI a enseñar a un niño de año y medio a jugar por turnos.', title_fr = 'Le problème du partage 🧸', body_fr = 'Au parc, il court vers les jouets des autres enfants mais refuse de prêter les siens ? Découvrez avec Anacan AI comment apprendre à un enfant de 1 an et demi à jouer chacun son tour.', title_hi = 'बाँटने की परेशानी 🧸', body_hi = 'पार्क में दूसरे बच्चों के खिलौनों की ओर दौड़ता है, पर अपना नहीं देता? Anacan AI से सीखिए कि 1.5 साल के बच्चों को बारी-बारी से खेलना कैसे सिखाएँ।', title_id = 'Masalah berbagi 🧸', body_id = 'Di taman ia berlari ke mainan anak lain, tapi tidak mau memberikan mainannya sendiri? Pelajari dari Anacan AI cara mengajarkan konsep bermain bergiliran kepada anak usia 1,5 tahun.', title_ja = '貸し借りの悩み 🧸', body_ja = '公園でほかの子のおもちゃには駆け寄るのに、自分のものは貸さない？1歳半の子に順番で遊ぶことをどう教えるか、Anacan AIで学びましょう。', title_ko = '나누기 문제 🧸', body_ko = '공원에서 다른 아이 장난감에는 달려가면서 자기 것은 안 주나요? 1살 반 아이에게 차례대로 노는 개념을 알려 주는 방법을 Anacan AI에게 알아보세요.', title_nl = 'Moeite met delen 🧸', body_nl = 'Rent je kindje in het park naar het speelgoed van andere kinderen, maar geeft hij het zijne niet? Ontdek bij Anacan AI hoe je kinderen van 1,5 jaar leert om om de beurt te spelen.', title_pl = 'Kłopot z dzieleniem się 🧸', body_pl = 'W parku biegnie do zabawek innych dzieci, ale swoich nie oddaje? Dowiedz się w Anacan AI, jak nauczyć półtoraroczniaka bawić się po kolei.', title_pt = 'O problema de partilhar 🧸', body_pt = 'No parque, corre para os brinquedos das outras crianças, mas não empresta os seus? Aprenda com o Anacan AI a ensinar a uma criança de 1 ano e meio a noção de brincar à vez.', title_sv = 'Problem med att dela 🧸', body_sv = 'Springer barnet fram till andra barns leksaker i parken men ger inte bort sina egna? Lär dig av Anacan AI hur du lär barn på 1,5 år att turas om.', title_vi = 'Chuyện chia sẻ 🧸', body_vi = 'Ở công viên bé chạy đến lấy đồ chơi của bạn nhưng không chịu đưa đồ của mình? Hãy tìm hiểu cùng Anacan AI cách dạy trẻ 1,5 tuổi khái niệm chơi lần lượt.', title_zh = '分享难题 🧸', body_zh = '在公园里冲向别的孩子的玩具，自己的却不给？向Anacan AI学习如何让1岁半的孩子理解“轮流玩”的概念。' WHERE id = 'c6f920b8-00cf-46b0-a823-bf8cf1fd5ecf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una pausa del tamaño de una taza ☕', body_es = '¿Cómo va tu batería? Deja las tareas de casa. Prepara un bizcocho energético con crema de cacahuete de Recetas saludables para mujeres y simplemente escucha el sonido de tu café.', title_fr = 'Une pause le temps d''une tasse ☕', body_fr = 'Où en est votre batterie ? Arrêtez les tâches ménagères. Préparez un cake énergisant au beurre de cacahuète grâce aux Recettes saines pour femmes et écoutez simplement le bruit de votre café.', title_hi = 'एक कप का ब्रेक ☕', body_hi = 'आपकी बैटरी कैसी है? घर के काम रोकिए। महिलाओं के लिए सेहतमंद रेसिपी से ऊर्जा भरा पीनट बटर मफ़िन बनाइए और बस अपनी कॉफ़ी की आवाज़ सुनिए।', title_id = 'Jeda secangkir kopi ☕', body_id = 'Bagaimana kondisi baterai Anda? Hentikan pekerjaan rumah. Buat kue mangkuk selai kacang yang berenergi dari Resep Sehat untuk wanita dan nikmati saja suara kopi Anda.', title_ja = 'カップ1杯分の休憩 ☕', body_ja = 'あなたのバッテリー残量はどうですか？家事の手を止めましょう。「女性のためのヘルシーレシピ」から元気が出るピーナッツバターのマフィンをつくって、コーヒーの音にただ耳を傾けて。', title_ko = '커피 한 잔의 휴식 ☕', body_ko = '엄마의 배터리는 몇 퍼센트인가요? 집안일은 멈추세요. 건강한 레시피에서 든든한 땅콩버터 머핀을 만들고, 그저 커피 내리는 소리에 귀 기울여 보세요.', title_nl = 'Een kopje pauze ☕', body_nl = 'Hoe vol is jouw batterij? Stop met het huishouden. Bak een energierijke cake met pindakaas uit Gezonde recepten voor vrouwen en luister gewoon naar het geluid van je koffie.', title_pl = 'Przerwa na filiżankę ☕', body_pl = 'Jak tam twoja bateria? Przerwij prace domowe. Upiecz energetyczną babeczkę z masłem orzechowym ze Zdrowych przepisów dla kobiet i po prostu wsłuchaj się w szum kawy.', title_pt = 'Uma pausa do tamanho de uma chávena ☕', body_pt = 'Como está a sua bateria? Pare as tarefas de casa. Prepare um queque energético de manteiga de amendoim das Receitas Saudáveis para Mulheres e escute simplesmente o som do seu café.', title_sv = 'En paus på en kopp ☕', body_sv = 'Hur är det med ditt batteri? Avbryt hushållssysslorna. Gör en energigivande muffins med jordnötssmör från Hälsosamma recept för kvinnor och lyssna bara på ljudet av ditt kaffe.', title_vi = 'Nghỉ ngơi bên tách cà phê ☕', body_vi = '"Pin" của mẹ còn bao nhiêu? Hãy tạm dừng việc nhà. Làm một chiếc bánh nướng bơ đậu phộng giàu năng lượng từ Công thức lành mạnh cho phụ nữ và chỉ lắng nghe tiếng cà phê.', title_zh = '一杯咖啡的休息 ☕', body_zh = '你的电量还剩多少？停下家务吧。从女性健康食谱里做一个提神的花生酱蛋糕，静静地听着咖啡的声音。' WHERE id = 'ca671510-91c4-4377-9f69-b4bd47b292a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de la arena cinética 🏖️', body_es = '¿Creamos una pequeña playa en casa? Echa un vistazo en Productos recomendados a los kits de arena cinética, que fortalecen los músculos de los dedos y se limpian fácilmente.', title_fr = 'La magie du sable cinétique 🏖️', body_fr = 'Et si on créait une petite plage à la maison ? Jetez un œil aux kits de sable cinétique dans les Produits recommandés : ils renforcent les muscles des doigts et se nettoient facilement.', title_hi = 'काइनेटिक रेत का जादू 🏖️', body_hi = 'घर में एक छोटा सा बीच बनाएँ? उँगलियों की मांसपेशियाँ मज़बूत करने वाले और आसानी से साफ़ होने वाले काइनेटिक सैंड सेट के लिए सुझाए गए प्रोडक्ट देखिए।', title_id = 'Keajaiban pasir kinetik 🏖️', body_id = 'Bagaimana kalau membuat pantai kecil di rumah? Lihat set pasir kinetik yang menguatkan otot jari dan mudah dibersihkan di Produk Rekomendasi.', title_ja = 'キネティックサンドの魔法 🏖️', body_ja = 'おうちに小さなビーチをつくってみませんか？指の筋肉をきたえられて、お片付けもかんたんなキネティックサンドのセットを、「おすすめ商品」でチェックしましょう。', title_ko = '키네틱 샌드 마법 🏖️', body_ko = '집 안에 작은 해변을 만들어 볼까요? 손가락 근육을 키워 주고 치우기도 쉬운 키네틱 샌드 세트는 추천 제품에서 살펴보세요.', title_nl = 'Toveren met kinetisch zand 🏖️', body_nl = 'Zullen we thuis een klein strandje maken? Bekijk in Aanbevolen producten sets met kinetisch zand die de vingerspiertjes sterker maken en makkelijk op te ruimen zijn.', title_pl = 'Magia piasku kinetycznego 🏖️', body_pl = 'Zrobimy w domu małą plażę? Zajrzyj do Polecanych produktów po zestawy piasku kinetycznego, które wzmacniają mięśnie palców i łatwo się sprzątają.', title_pt = 'A magia da areia cinética 🏖️', body_pt = 'E se criássemos uma pequena praia em casa? Espreite nos Produtos Recomendados os conjuntos de areia cinética, que fortalecem os músculos dos dedos e são fáceis de limpar.', title_sv = 'Trolleri med kinetisk sand 🏖️', body_sv = 'Ska vi skapa en liten strand hemma? Titta i Rekommenderade produkter efter set med kinetisk sand som stärker fingermusklerna och är lätta att städa upp.', title_vi = 'Phép màu cát động lực 🏖️', body_vi = 'Cùng tạo một bãi biển nhỏ trong nhà nhé? Hãy xem các bộ cát động lực giúp tăng cường cơ ngón tay và dễ dọn dẹp trong Sản phẩm gợi ý.', title_zh = '动力沙魔法 🏖️', body_zh = '在家里打造一个小沙滩？看看推荐商品里能锻炼手指肌肉、又容易清理的动力沙套装吧。' WHERE id = '38141003-a43c-4589-a477-21da541a08db' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Conoce su cuerpo! 👃', body_es = '¿Cuando le preguntas «¿Dónde está tu nariz?» la señala con orgullo? Organiza una pequeña sesión en su habitación con la Sesión de fotos del bebé y guarda enseguida esa pose tan tierna en el álbum.', title_fr = 'Il découvre son corps ! 👃', body_fr = 'Quand vous demandez « Où est ton nez ? », il le montre fièrement ? Organisez une petite séance dans sa chambre avec la Séance photo bébé et ajoutez tout de suite cette pose adorable à l''album.', title_hi = 'अपने शरीर को पहचानता है! 👃', body_hi = '''नाक कहाँ है?'' पूछने पर गर्व से दिखाता है? बेबी फ़ोटोशूट से कमरे में छोटा सा शूट कीजिए और वह प्यारा पोज़ तुरंत एल्बम में सहेज लीजिए।', title_id = 'Ia mengenali tubuhnya sendiri! 👃', body_id = 'Saat ditanya "Hidungnya mana?", ia menunjuk dengan bangga? Adakan pemotretan kecil di kamar dengan Sesi Foto Bayi dan segera simpan pose menggemaskan itu ke album.', title_ja = '自分の体がわかる！👃', body_ja = '「お鼻はどこ？」と聞くと、得意げに指さしますか？「ベビーフォトセッション」で部屋でミニ撮影会をして、そのかわいいポーズをすぐにアルバムに残しましょう。', title_ko = '자기 몸을 알아요! 👃', body_ko = '"코 어디 있어?" 하면 뿌듯하게 가리키나요? 아기 사진 촬영으로 방 안에서 작은 촬영을 하고 그 사랑스러운 포즈를 바로 앨범에 남기세요.', title_nl = 'Leert zijn eigen lichaam kennen! 👃', body_nl = 'Wijst je kindje trots zijn neus aan als je vraagt: waar is je neus? Houd met Babyfotoshoot een kleine fotoshoot in de kamer en zet die lieve pose meteen in het album.', title_pl = 'Poznaje swoje ciało! 👃', body_pl = 'Na pytanie „Gdzie masz nos?” z dumą go pokazuje? Zorganizuj w pokoju małą sesję w Sesji zdjęciowej dziecka i od razu dodaj tę uroczą pozę do albumu.', title_pt = 'Conhece o próprio corpo! 👃', body_pt = 'Quando lhe pergunta "Onde está o nariz?", aponta com orgulho? Organize uma pequena sessão no quarto com a Sessão Fotográfica do Bebé e guarde já no álbum aquela pose adorável.', title_sv = 'Lär känna sin kropp! 👃', body_sv = 'Pekar barnet stolt när du frågar ”Var är näsan?”? Ordna en liten fotostund i rummet med Babyfotografering och spara den söta posen i albumet direkt.', title_vi = 'Bé nhận biết cơ thể mình! 👃', body_vi = 'Mẹ hỏi "Mũi con đâu?" là bé tự hào chỉ vào? Hãy tổ chức một buổi chụp ảnh nhỏ trong phòng với Chụp ảnh cho bé và lưu ngay tư thế đáng yêu ấy vào album.', title_zh = '认识自己的身体！👃', body_zh = '问“鼻子在哪里？”他会骄傲地指给你看？用宝宝写真在房间里来个小拍摄，马上把这个可爱的姿势存进相册。' WHERE id = '75f9f2e1-a04a-4711-9125-3d8c610326d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo saber si ya está lleno? ⏱️', body_es = 'Si empieza a tirar o escupir la comida, te está diciendo que ya está lleno. Para el temporizador de tomas, anota que ha comido lo necesario y analiza su apetito.', title_fr = 'Comment savoir s''il n''a plus faim ? ⏱️', body_fr = 'S''il commence à jeter ou à recracher sa nourriture, c''est qu''il n''a plus faim. Arrêtez le minuteur des repas, notez que ses besoins sont couverts et analysez son appétit.', title_hi = 'कैसे जानें कि पेट भर गया? ⏱️', body_hi = 'अगर वह खाना फेंकने या थूकने लगा है, तो इसका मतलब है कि पेट भर गया। फ़ीडिंग टाइमर रोकिए, मानक पूरा होना दर्ज कीजिए और भूख का विश्लेषण कीजिए।', title_id = 'Bagaimana tahu ia sudah kenyang? ⏱️', body_id = 'Kalau ia mulai melempar atau menyemburkan makanan, artinya "aku sudah kenyang". Hentikan Timer Makan, catat bahwa porsinya terpenuhi, dan analisis nafsu makannya.', title_ja = 'お腹いっぱいのサインは？⏱️', body_ja = '食べ物を投げたり吐き出したりし始めたら、「もうお腹いっぱい」の合図です。食事タイマーを止めて、十分食べたことを記録し、食欲を分析しましょう。', title_ko = '배부른 걸 어떻게 알까요? ⏱️', body_ko = '음식을 던지거나 뱉기 시작했다면 "이제 배불러"라는 뜻이에요. 수유 타이머를 멈추고 충분히 먹었다고 기록한 뒤 입맛을 분석해 보세요.', title_nl = 'Hoe weet je dat hij vol zit? ⏱️', body_nl = 'Begint je kindje eten te gooien of uit te spugen? Dan zegt hij: ik zit vol. Stop de voedingstimer, noteer dat de norm gehaald is en analyseer zijn eetlust.', title_pl = 'Jak poznać, że jest najedzony? ⏱️', body_pl = 'Jeśli zaczyna rzucać jedzeniem lub je wypluwać, to znaczy „już jestem najedzony”. Zatrzymaj timer karmienia, zapisz, że norma jest osiągnięta, i przeanalizuj apetyt.', title_pt = 'Como saber se está satisfeito? ⏱️', body_pt = 'Se começa a atirar ou a cuspir a comida, quer dizer "já estou cheio". Pare o temporizador de alimentação, registe que a quantidade foi atingida e analise o apetite.', title_sv = 'Hur vet vi att barnet är mätt? ⏱️', body_sv = 'Om barnet börjar kasta eller spotta ut maten betyder det ”nu är jag mätt”. Stoppa matningstimern, anteckna att normen är nådd och analysera aptiten.', title_vi = 'Làm sao biết bé đã no? ⏱️', body_vi = 'Nếu bé bắt đầu ném hay nhè thức ăn, nghĩa là bé đã no. Hãy dừng bộ hẹn giờ trong Theo dõi cữ bú, ghi lại rằng bé đã ăn đủ và phân tích tình trạng ăn uống.', title_zh = '怎么知道他吃饱了？⏱️', body_zh = '开始扔食物或吐出来，就说明“我吃饱了”。停下喂养计时器，记录已达到参考量，分析一下他的胃口吧。' WHERE id = 'ae036003-f237-47e6-8031-7feeb47126cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas compañía 💬', body_es = '¡Relacionarte con otras mamás también te sentará bien! Elige en Lugares para mamás un centro con grupos de juego y regalaos a los dos un rato de socializar.', title_fr = 'Vous aussi avez besoin de compagnie 💬', body_fr = 'Échanger avec d''autres mamans vous fera du bien à vous aussi ! Choisissez dans les Lieux adaptés aux mamans un centre avec des groupes de jeux et offrez-vous à tous les deux un moment de sociabilité.', title_hi = 'आपको भी साथ की ज़रूरत है 💬', body_hi = 'दूसरी माँओं से मिलना-जुलना आपके लिए भी अच्छा रहेगा! माँ के लिए अनुकूल जगहों में प्ले ग्रुप वाला कोई सेंटर चुनिए और आप दोनों को मेलजोल का तोहफ़ा दीजिए।', title_id = 'Anda juga butuh pergaulan 💬', body_id = 'Bergaul dengan ibu-ibu lain juga baik untuk Anda! Pilih pusat dengan kelompok bermain di Tempat Ramah Ibu dan hadiahkan kesempatan bersosialisasi untuk kalian berdua.', title_ja = 'あなたにも仲間が必要です 💬', body_ja = 'ほかのママたちとの交流は、あなたにとってもいいものです！「ママにやさしいスポット」でプレイグループのある施設を選んで、おふたりにふれあいの時間をプレゼントしましょう。', title_ko = '엄마에게도 사람들이 필요해요 💬', body_ko = '다른 엄마들과 어울리면 엄마에게도 좋아요! 엄마 친화 장소에서 놀이 모임이 있는 센터를 골라 두 사람 모두에게 사회적 교류를 선물하세요.', title_nl = 'Ook jij hebt gezelschap nodig 💬', body_nl = 'Contact met andere moeders doet jou ook goed! Kies in Mamavriendelijke plekken een centrum met speelgroepjes en geef jullie allebei wat sociaal contact cadeau.', title_pl = 'Ty też potrzebujesz towarzystwa 💬', body_pl = 'Kontakt z innymi mamami dobrze ci zrobi! Wybierz w Miejscach przyjaznych mamom miejsce z grupami zabaw i podaruj wam obojgu trochę towarzystwa.', title_pt = 'Também precisa de companhia 💬', body_pt = 'Conviver com outras mães também lhe vai fazer bem! Escolha nos Locais Amigos das Mães um centro com grupos de brincadeira e ofereça aos dois o presente da socialização.', title_sv = 'Du behöver också gemenskap 💬', body_sv = 'Att umgås med andra mammor gör dig också gott! Välj ett ställe med lekgrupper i Mammavänliga platser och ge er båda gemenskap i present.', title_vi = 'Mẹ cũng cần cộng đồng 💬', body_vi = 'Giao lưu với các mẹ khác cũng tốt cho mẹ! Hãy chọn một trung tâm có nhóm vui chơi trong Địa điểm thân thiện với mẹ để cả hai mẹ con cùng được giao lưu.', title_zh = '你也需要圈子 💬', body_zh = '和其他妈妈交流对你也有好处！在妈妈友好场所里选一个有游戏小组的中心，送你们俩一份社交的礼物吧。' WHERE id = '05bc3cfd-c566-4963-b6b2-87889d369e27' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cuál ha sido tu victoria de hoy? 🏆', body_es = '¿Dormirle sin llantos? ¿Que se acabe todo el plato? Escribe en el Diario de ánimo hasta tu logro más pequeño y date una ovación de pie.', title_fr = 'Quelle est votre victoire du jour ? 🏆', body_fr = 'Le coucher sans pleurs ? Ou un bol entier avalé ? Notez même votre plus petite réussite dans le Journal d''humeur et applaudissez-vous debout.', title_hi = 'आज आपकी जीत क्या है? 🏆', body_hi = 'बिना रोए सुला दिया? या पूरी कटोरी खिला दी? अपनी छोटी से छोटी कामयाबी भी मूड डायरी में लिखिए और खड़े होकर खुद के लिए ताली बजाइए।', title_id = 'Apa kemenangan Anda hari ini? 🏆', body_id = 'Menidurkannya tanpa tangisan? Atau berhasil menyuapkan satu mangkuk penuh? Tulis bahkan keberhasilan terkecil Anda di Buku Harian Suasana Hati dan beri diri Anda tepuk tangan meriah.', title_ja = '今日のあなたの勝利は？🏆', body_ja = '泣かずに寝かしつけられた？それとも、お茶わん1杯を全部食べさせられた？ほんの小さな成功でも「気分日記」に書いて、自分に盛大な拍手を送りましょう。', title_ko = '오늘의 승리는 무엇인가요? 🏆', body_ko = '울리지 않고 재웠나요? 아니면 한 그릇을 다 먹였나요? 아주 작은 성공이라도 기분 일기에 적고 스스로에게 기립 박수를 보내세요.', title_nl = 'Wat is je overwinning van vandaag? 🏆', body_nl = 'Je kindje zonder huilen in slaap gekregen? Of een hele kom leeg laten eten? Schrijf zelfs je kleinste succes op in je Stemmingsdagboek en geef jezelf een staande ovatie.', title_pl = 'Jakie jest twoje dzisiejsze zwycięstwo? 🏆', body_pl = 'Uśpiłaś go bez płaczu? A może zjadł całą miseczkę? Zapisz w Dzienniku nastroju nawet najmniejszy sukces i nagródź się owacją na stojąco.', title_pt = 'Qual foi a sua vitória de hoje? 🏆', body_pt = 'Adormecê-lo sem choro? Ou fazê-lo comer uma taça inteira? Escreva no Diário de Humor até a mais pequena conquista e aplauda-se de pé.', title_sv = 'Vad är din seger i dag? 🏆', body_sv = 'Fick du barnet att somna utan gråt? Eller att äta upp en hel skål? Skriv även din minsta framgång i Humördagboken och ge dig själv stående ovationer.', title_vi = 'Chiến thắng hôm nay của mẹ là gì? 🏆', body_vi = 'Cho bé ngủ mà không khóc? Hay cho bé ăn hết cả một bát? Hãy viết cả thành công nhỏ nhất vào Nhật ký tâm trạng và đứng lên vỗ tay cho chính mình.', title_zh = '今天你赢了什么？🏆', body_zh = '没哭就哄睡了？还是喂完了一整碗？哪怕是最小的成就也写进心情日记，起立为自己鼓掌吧。' WHERE id = '5b6366a9-6eb4-4593-8335-c41fd3447da1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El crecimiento empieza por los zapatos 📏', body_es = 'Si no quiere ponerse los zapatos, quizá es que le aprietan. Revisa la tabla de tallas en el Registro de peso y sigue su desarrollo físico.', title_fr = 'La croissance commence par les chaussures 📏', body_fr = 'S''il refuse de mettre ses chaussures, c''est peut-être qu''elles sont devenues trop petites ! Consultez le tableau des tailles dans le Suivi du poids et suivez son développement physique.', title_hi = 'बढ़त जूतों से शुरू होती है 📏', body_hi = 'जूते न पहनना चाहना शायद उनके तंग होने की वजह से हो! वेट ट्रैकर टूल में साइज़ चार्ट देखिए और शारीरिक विकास पर नज़र रखिए।', title_id = 'Pertumbuhan dimulai dari sepatu 📏', body_id = 'Ia tidak mau memakai sepatunya? Mungkin sepatunya sudah kekecilan! Periksa tabel ukuran di Pelacak Berat Badan dan pantau perkembangan fisiknya.', title_ja = '成長は靴からわかる 📏', body_ja = '靴を履きたがらないのは、きつくなったからかもしれません！「体重トラッカー」でサイズ表を確認して、体の成長を見守りましょう。', title_ko = '성장은 신발에서 시작돼요 📏', body_ko = '신발을 신기 싫어하는 건 신발이 작아져서일지도 몰라요! 체중 기록 도구에서 사이즈를 확인하고 신체 발달을 살펴보세요.', title_nl = 'Groeien begint bij de schoenen 📏', body_nl = 'Wil je kindje zijn schoenen niet aan? Misschien zijn ze te krap geworden! Controleer de maattabel in de tool Gewichtstracker en volg zijn lichamelijke ontwikkeling.', title_pl = 'Wzrost zaczyna się od butów 📏', body_pl = 'Może nie chce zakładać butów, bo zrobiły się za ciasne! Sprawdź tabelę rozmiarów w narzędziu Licznik wagi i śledź jego rozwój fizyczny.', title_pt = 'O crescimento começa pelos sapatos 📏', body_pt = 'Se não quer calçar os sapatos, talvez já estejam apertados! Verifique a tabela de medidas no Registo de Peso e acompanhe o desenvolvimento físico.', title_sv = 'Tillväxten börjar med skorna 📏', body_sv = 'Kanske vill barnet inte ta på sig skorna för att de har blivit för små! Kolla storlekstabellen i verktyget Viktspåraren och följ den fysiska utvecklingen.', title_vi = 'Bé lớn lên bắt đầu từ đôi giày 📏', body_vi = 'Bé không chịu đi giày có thể vì giày đã chật! Hãy kiểm tra bảng kích cỡ trong công cụ Theo dõi cân nặng và theo dõi sự phát triển thể chất của bé.', title_zh = '成长从鞋子开始 📏', body_zh = '不肯穿鞋，也许是因为鞋变紧了！在体重记录工具里看看尺码表，追踪身体的发育吧。' WHERE id = '98a39354-24f3-4f3c-9cfb-1e084764a56b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Un gran berrinche en el súper? 🛒', title_fr = 'Grosse crise au supermarché ? 🛒', title_hi = 'मार्केट में ज़ोरदार चीख? 🛒', title_id = 'Teriakan besar di supermarket? 🛒', title_ja = 'スーパーで大泣き？🛒', title_ko = '마트에서 대성통곡? 🛒', title_nl = 'Groot gekrijs in de supermarkt? 🛒', title_pl = 'Wielki krzyk w sklepie? 🛒', title_pt = 'Uma grande gritaria no supermercado? 🛒', title_sv = 'Stort skrik i affären? 🛒', title_vi = 'La hét trong siêu thị? 🛒', title_zh = '超市里的大哭大闹？🛒' WHERE id = '907f2a4d-a45c-43e1-8024-d6c91a18d072' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La energía de la mañana es otra cosa! ⚡', body_es = '¿Rechaza las gachas de avena? Descubre en Recetas para bebé un batido de fruta con crema de cacahuete y alcanza fácilmente el objetivo de calorías del Seguimiento de tomas.', title_fr = 'L''énergie du matin, c''est autre chose ! ⚡', body_fr = 'Il refuse la bouillie d''avoine ? Découvrez dans les Recettes pour bébés un smoothie aux fruits et au beurre de cacahuète, et atteignez facilement l''objectif calorique du Suivi des repas.', title_hi = 'सुबह की ऊर्जा अलग है! ⚡', body_hi = 'ओट्स का दलिया मना करता है? बच्चों की रेसिपी में फल और पीनट बटर वाली स्मूदी खोजिए और फ़ीडिंग ट्रैकर का कैलोरी लक्ष्य आसानी से पूरा कीजिए।', title_id = 'Energi pagi itu berbeda! ⚡', body_id = 'Ia menolak bubur oat? Temukan smoothie buah dan selai kacang di Resep Bayi dan capai target kalori di alat Pemantau Makan dengan mudah.', title_ja = '朝のエネルギーは特別！⚡', body_ja = 'オートミールのおかゆを嫌がる？ベビーレシピで果物とピーナッツバターのスムージーを見つけて、「栄養管理ツール」のカロリー目標をかんたんに達成しましょう。', title_ko = '아침 에너지는 달라요! ⚡', body_ko = '오트밀 죽을 거부하나요? 아기 레시피에서 과일과 땅콩버터 스무디를 찾아 수유 기록 도구의 칼로리 목표를 쉽게 채워 보세요.', title_nl = 'Ochtendenergie is anders! ⚡', body_nl = 'Weigert je kindje havermoutpap? Ontdek in de babyrecepten een smoothie met fruit en pindakaas en haal makkelijk het caloriedoel in de Voedingstracker.', title_pl = 'Poranna energia jest inna! ⚡', body_pl = 'Odmawia owsianki? Odkryj w Przepisach dla maluszka smoothie z owocami i masłem orzechowym i łatwo osiągnij cel kaloryczny w narzędziu do śledzenia karmienia.', title_pt = 'A energia da manhã é diferente! ⚡', body_pt = 'Recusa as papas de aveia? Descubra nas Receitas para bebés um batido de fruta com manteiga de amendoim e atinja com facilidade a meta de calorias no Registo de Alimentação.', title_sv = 'Morgonenergin är annorlunda! ⚡', body_sv = 'Vägrar barnet havregrynsgröt? Upptäck en smoothie med frukt och jordnötssmör i Babyrecept och nå enkelt kalorimålet i Matningskoll.', title_vi = 'Năng lượng buổi sáng thật khác! ⚡', body_vi = 'Bé không chịu ăn cháo yến mạch? Hãy khám phá món sinh tố trái cây và bơ đậu phộng trong Công thức cho bé để dễ dàng đạt mục tiêu calo trong công cụ Theo dõi cữ bú.', title_zh = '早晨的能量不一样！⚡', body_zh = '不肯吃燕麦粥？在宝宝食谱里发现水果花生酱果昔，轻松达到喂养记录工具里的热量目标。' WHERE id = '6d72635f-ba12-4c8b-b7ef-f626dd634dce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te cierran los ojos? 😴', body_es = 'Cuando se duerma, túmbate tú también. Si no consigues dormir, prepárate un té verde lleno de antioxidantes de Recetas saludables para mujeres y recupérate.', title_fr = 'Vos yeux se ferment ? 😴', body_fr = 'Quand il dort, allongez-vous aussi. Si vous n''arrivez pas à dormir, ressourcez-vous avec un thé vert riche en antioxydants des Recettes saines pour femmes.', title_hi = 'आँखें बंद हो रही हैं? 😴', body_hi = 'बच्चा सोए तो आप भी लेट जाइए। अगर नींद न आए, तो महिलाओं के लिए सेहतमंद रेसिपी से एंटीऑक्सीडेंट से भरपूर ग्रीन टी बनाकर खुद को तरोताज़ा कीजिए।', title_id = 'Mata Anda mulai berat? 😴', body_id = 'Saat si kecil tidur, berbaringlah juga. Kalau tidak bisa tidur, segarkan diri dengan teh hijau kaya antioksidan dari Resep Sehat untuk wanita.', title_ja = 'まぶたが重い？😴', body_ja = 'お子さんが寝たら、あなたも横になりましょう。眠れなければ、「女性のためのヘルシーレシピ」から抗酸化物質たっぷりの緑茶をいれて、リフレッシュしましょう。', title_ko = '눈이 감기나요? 😴', body_ko = '아이가 잘 때 엄마도 누우세요. 잠이 오지 않는다면 건강한 레시피에서 항산화 성분이 가득한 녹차를 우려 기운을 되찾으세요.', title_nl = 'Vallen je ogen dicht? 😴', body_nl = 'Ga ook liggen als je kindje slaapt. Kun je niet slapen? Zet dan groene thee vol antioxidanten uit Gezonde recepten voor vrouwen en kom weer op krachten.', title_pl = 'Oczy ci się kleją? 😴', body_pl = 'Gdy maluszek śpi, ty też się połóż. Jeśli nie możesz zasnąć, przygotuj ze Zdrowych przepisów dla kobiet zieloną herbatę pełną przeciwutleniaczy i odśwież się.', title_pt = 'Os olhos estão a fechar-se? 😴', body_pt = 'Quando ele dormir, deite-se também. Se não conseguir dormir, prepare um chá verde cheio de antioxidantes das Receitas Saudáveis para Mulheres e renove-se.', title_sv = 'Faller ögonlocken ihop? 😴', body_sv = 'Lägg dig du också när barnet sover. Om du inte kan sova, gör ett grönt te fullt av antioxidanter från Hälsosamma recept för kvinnor och fräscha upp dig.', title_vi = 'Mắt mẹ díp lại rồi? 😴', body_vi = 'Khi bé ngủ, mẹ cũng nằm nghỉ nhé. Nếu không ngủ được, hãy pha trà xanh giàu chất chống oxy hóa từ Công thức lành mạnh cho phụ nữ để tươi tỉnh lại.', title_zh = '眼睛快睁不开了？😴', body_zh = '宝宝睡觉时你也躺一会儿。如果睡不着，就从女性健康食谱里泡一杯富含抗氧化物的绿茶，让自己焕然一新。' WHERE id = '9867089b-80a4-4895-985d-1e1d5fa3df95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se resiste a ir a la cama? 🛌', body_es = 'El mes 19 es famoso por los cambios en el sueño. Activa el Temporizador de sueño y revisa la gráfica: ¡quizá sea el momento de acortar la siesta!', title_fr = 'Il résiste au coucher ? 🛌', body_fr = 'Le 19e mois est connu pour ses bouleversements du sommeil. Lancez le minuteur de sommeil et vérifiez le graphique : c''est peut-être le bon moment pour raccourcir la sieste !', title_hi = 'बिस्तर से विरोध? 🛌', body_hi = '19वाँ महीना नींद में बदलावों के लिए मशहूर है। स्लीप टाइमर चालू कीजिए और शेड्यूल देखिए, शायद दिन की झपकी छोटी करने का सही समय आ गया है!', title_id = 'Menolak tidur? 🛌', body_id = 'Bulan ke-19 terkenal dengan lompatan tidurnya. Nyalakan Timer Tidur dan periksa grafiknya, mungkin inilah saatnya mempersingkat tidur siang!', title_ja = 'ベッドに行きたがらない？🛌', body_ja = '1歳7か月は睡眠の変化が起きやすい時期です。睡眠タイマーをオンにして記録を確認しましょう。お昼寝を短くするちょうどいいタイミングかもしれません！', title_ko = '잠자리를 거부하나요? 🛌', body_ko = '19개월은 수면 변화로 잘 알려진 시기예요. 수면 타이머를 켜고 그래프를 확인해 보세요. 낮잠을 줄일 때가 됐을지도 몰라요!', title_nl = 'Verzet tegen het slapengaan? 🛌', body_nl = 'De 19e maand staat bekend om slaapsprongen. Zet de Slaaptimer aan en bekijk het schema, misschien is het precies het moment om het middagdutje in te korten!', title_pl = 'Opór przed łóżkiem? 🛌', body_pl = '19. miesiąc słynie ze skoków w śnie. Włącz timer snu i sprawdź wykres, może to idealny moment, by skrócić drzemkę w ciągu dnia!', title_pt = 'Resiste a ir para a cama? 🛌', body_pt = 'O 19.º mês é conhecido pelos saltos no sono. Ligue o temporizador de sono e veja o gráfico: talvez seja a altura certa para encurtar a sesta!', title_sv = 'Motstånd mot sängen? 🛌', body_sv = 'Den 19:e månaden är känd för sömnsprång. Starta sömntimern och kolla schemat, kanske är det precis rätt tid att korta dagsluren!', title_vi = 'Bé không chịu lên giường? 🛌', body_vi = 'Tháng thứ 19 nổi tiếng với những bước nhảy giấc ngủ. Hãy bật Bộ hẹn giờ ngủ và xem biểu đồ, có lẽ đã đến lúc rút ngắn giấc ngủ ngày!', title_zh = '抗拒上床？🛌', body_zh = '第19个月以睡眠飞跃出名。打开睡眠计时器看看图表，也许正是缩短白天小睡的时候！' WHERE id = 'a5fedf21-2dca-46ed-9476-0b415ced68a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sospechas de dolor de barriga? 💩', body_es = 'Al cambiar el pañal de la mañana, anota cómo es la caca. Si hay riesgo de estreñimiento, pregunta enseguida a Anacan AI por soluciones naturales y técnicas de masaje y ponlas en práctica.', title_fr = 'Un mal de ventre ? 💩', body_fr = 'Lors du change du matin, notez les selles. En cas de risque de constipation, demandez tout de suite à Anacan AI des solutions naturelles et des techniques de massage, et appliquez-les.', title_hi = 'पेट दर्द का शक? 💩', body_hi = 'सुबह का डायपर बदलते समय पॉटी की जानकारी दर्ज कीजिए। अगर कब्ज़ का खतरा है, तो Anacan AI से तुरंत प्राकृतिक उपाय और मालिश के तरीके पूछकर अपनाइए।', title_id = 'Curiga sakit perut? 💩', body_id = 'Masukkan catatan BAB saat mengganti popok pagi. Kalau ada risiko sembelit, tanyakan ke Anacan AI solusi alami dan teknik pijat yang bisa segera diterapkan.', title_ja = 'おなかが痛いのかも？💩', body_ja = '朝のおむつ替えのときに、うんちの記録を入力しましょう。便秘が心配なら、Anacan AIにすぐに自然な対処法やマッサージの方法を聞いて、試してみましょう。', title_ko = '배가 아픈 걸까요? 💩', body_ko = '아침 기저귀를 갈 때 배변 기록을 입력하세요. 변비가 걱정된다면 Anacan AI에게 바로 자연스러운 해결법과 마사지 방법을 물어 실천해 보세요.', title_nl = 'Vermoeden van buikpijn? 💩', body_nl = 'Noteer bij het verschonen van de ochtendluier de gegevens over de ontlasting. Is er kans op verstopping? Vraag Anacan AI meteen naar natuurlijke oplossingen en massagetechnieken en pas ze toe.', title_pl = 'Podejrzewasz ból brzuszka? 💩', body_pl = 'Przy porannym przewijaniu zapisz informacje o kupce. Jeśli grozi zaparcie, od razu zapytaj Anacan AI o naturalne sposoby i techniki masażu i je zastosuj.', title_pt = 'Suspeita de dor de barriga? 💩', body_pt = 'Ao mudar a fralda da manhã, introduza as notas sobre as fezes. Se houver risco de obstipação, peça já ao Anacan AI soluções naturais e técnicas de massagem e aplique-as.', title_sv = 'Misstänkt magont? 💩', body_sv = 'Lägg in anteckningar om bajset när du byter morgonblöjan. Om det finns risk för förstoppning, fråga Anacan AI om naturliga lösningar och massagetekniker och använd dem.', title_vi = 'Nghi ngờ đau bụng? 💩', body_vi = 'Khi thay tã buổi sáng, hãy ghi chú về phân. Nếu có nguy cơ táo bón, hãy hỏi ngay Anacan AI về các cách giải quyết tự nhiên và kỹ thuật xoa bóp để áp dụng.', title_zh = '怀疑肚子疼？💩', body_zh = '换早上的尿布时录入便便记录。如果有便秘的风险，马上向Anacan AI问问天然的解决办法和按摩手法，试着用起来。' WHERE id = '39db43fc-07a0-417e-90da-c0bbbd5f14a4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cuántos «no» has oído hoy? 🙉', body_es = 'Lidiar con un peque tan terco exige paciencia. Escribe tu tensión en el Diario de ánimo y suelta lo que sientes sin juzgarte.', title_fr = 'Combien de « Non » avez-vous entendus ? 🙉', body_fr = 'Gérer un petit têtu demande de la patience. Écrivez vos tensions dans le Journal d''humeur et libérez vos émotions sans vous juger.', title_hi = 'आज कितनी बार ''नहीं'' सुना? 🙉', body_hi = 'ज़िद्दी नन्हे को संभालने में धैर्य चाहिए। मूड डायरी में अपना अंदर का तनाव लिखिए और खुद को परखे बिना अपनी भावनाएँ बाहर निकालिए।', title_id = 'Berapa kali Anda mendengar "Tidak"? 🙉', body_id = 'Menghadapi si kecil yang keras kepala butuh kesabaran. Tulis ketegangan batin Anda di Buku Harian Suasana Hati dan lepaskan perasaan tanpa menghakimi diri sendiri.', title_ja = '今日は何回「いや」を聞きましたか？🙉', body_ja = 'いやいやの強いお子さんと向き合うには、根気が必要です。「気分日記」に心の緊張を書き出して、自分を責めずに気持ちを解放しましょう。', title_ko = '"싫어"를 몇 번이나 들었나요? 🙉', body_ko = '고집 센 꼬마를 감당하려면 인내심이 필요해요. 기분 일기에 마음속 긴장을 적고, 나를 판단하지 말고 감정을 풀어 내세요.', title_nl = 'Hoe vaak hoorde je nee? 🙉', body_nl = 'Omgaan met een koppig kleintje vraagt geduld. Schrijf je innerlijke spanning op in je Stemmingsdagboek en laat je gevoelens los zonder jezelf te veroordelen.', title_pl = 'Ile razy dziś usłyszałaś „nie”? 🙉', body_pl = 'Radzenie sobie z upartym maluchem wymaga cierpliwości. Zapisz swoje napięcie w Dzienniku nastroju i bez oceniania siebie daj upust uczuciom.', title_pt = 'Quantos "não" já ouviu? 🙉', body_pt = 'Lidar com um pequeno teimoso exige paciência. Escreva no Diário de Humor a sua tensão interior e liberte o que sente, sem se julgar.', title_sv = 'Hur många ”Nej” har du hört? 🙉', body_sv = 'Att hantera en envis liten kräver tålamod. Skriv din inre spänning i Humördagboken och släpp ut känslorna utan att döma dig själv.', title_vi = 'Hôm nay mẹ nghe bao nhiêu lần "Không"? 🙉', body_vi = 'Đối phó với một em bé bướng bỉnh đòi hỏi sự kiên nhẫn. Hãy viết những căng thẳng trong lòng vào Nhật ký tâm trạng và trút bỏ cảm xúc mà không phán xét bản thân.', title_zh = '今天听了多少个“不”？🙉', body_zh = '应付一个倔强的小家伙需要耐心。把内心的紧张写进心情日记，不评判自己，把情绪释放出来。' WHERE id = '613cd9e2-958a-41bd-b191-0de3ff8ec07f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Campeón de escalada! 🧗', body_es = '¿Se le quedan cortos los muebles de casa? Encuentra en Lugares para mamás un centro de ocio cubierto con circuitos blandos y deja que trepe con seguridad.', title_fr = 'Champion d''escalade ! 🧗', body_fr = 'Les meubles de la maison ne lui suffisent plus ? Trouvez dans les Lieux adaptés aux mamans un espace de jeux couvert avec des parcours en mousse pour satisfaire cette envie en toute sécurité.', title_hi = 'चढ़ने का चैंपियन! 🧗', body_hi = 'घर का फ़र्नीचर कम पड़ रहा है? माँ के लिए अनुकूल जगहों में नरम बाधाओं वाला इनडोर प्ले सेंटर ढूँढिए और उसकी इस चाह को सुरक्षित ढंग से पूरा कीजिए।', title_id = 'Juara memanjat! 🧗', body_id = 'Perabot di rumah tak lagi cukup? Temukan pusat hiburan dalam ruangan dengan lintasan rintangan empuk di Tempat Ramah Ibu dan penuhi keinginannya dengan aman.', title_ja = 'よじ登りチャンピオン！🧗', body_ja = '家の家具では物足りない？「ママにやさしいスポット」で、やわらかい障害物コースのある屋内の遊び場を見つけて、その気持ちを安全に満たしてあげましょう。', title_ko = '기어오르기 챔피언! 🧗', body_ko = '집 안 가구로는 부족한가요? 엄마 친화 장소에서 푹신한 장애물 코스가 있는 실내 놀이 센터를 찾아 이 욕구를 안전하게 채워 주세요.', title_nl = 'Kampioen klimmen! 🧗', body_nl = 'Zijn de meubels thuis niet meer genoeg? Zoek in Mamavriendelijke plekken een overdekte speelhal met zachte obstakels en geef hem veilig de ruimte om te klimmen.', title_pl = 'Mistrz wspinaczki! 🧗', body_pl = 'Domowe meble już mu nie wystarczają? Znajdź w Miejscach przyjaznych mamom salę zabaw z miękkimi torami przeszkód i bezpiecznie zaspokój tę potrzebę.', title_pt = 'Campeão de escalada! 🧗', body_pt = 'Os móveis de casa já não chegam? Encontre nos Locais Amigos das Mães um centro de diversões interior com circuitos de obstáculos macios e satisfaça esta vontade dele em segurança.', title_sv = 'Klättermästare! 🧗', body_sv = 'Räcker möblerna hemma inte till? Hitta ett lekland inomhus med mjuka hinderbanor i Mammavänliga platser och möt barnets lust på ett säkert sätt.', title_vi = 'Nhà vô địch leo trèo! 🧗', body_vi = 'Đồ đạc trong nhà không đủ để bé leo trèo? Hãy tìm một khu vui chơi trong nhà có chướng ngại vật mềm trong Địa điểm thân thiện với mẹ để đáp ứng nhu cầu của bé một cách an toàn.', title_zh = '攀爬冠军！🧗', body_zh = '家里的家具已经不够他爬了？在妈妈友好场所里找一个有软体障碍道的室内游乐中心，安全地满足他的愿望吧。' WHERE id = 'e893b0aa-e3fc-4f78-a970-b681a0ed0450' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
