UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal las proteínas? 🍗', body_es = '¡Las proteínas son imprescindibles para su crecimiento! Mide el equilibrio de su alimentación diaria con el Seguimiento de tomas y completa lo que falte.', title_fr = 'Et les protéines ? 🍗', body_fr = 'Les protéines sont indispensables à sa croissance ! Mesurez l''équilibre de son alimentation du jour avec le Suivi des repas et comblez les manques.', title_hi = 'प्रोटीन कितना मिल रहा है? 🍗', body_hi = 'बच्चे की बढ़त के लिए प्रोटीन ज़रूरी है! फ़ीडिंग ट्रैकर से उसके रोज़ के खाने का संतुलन देखिए और कमियाँ पूरी कीजिए।', title_id = 'Bagaimana asupan proteinnya? 🍗', body_id = 'Protein itu wajib untuk pertumbuhan anak! Ukur keseimbangan makanan hariannya dengan alat Pemantau Makan dan lengkapi kekurangannya.', title_ja = 'たんぱく質は足りている？🍗', body_ja = '子どもの成長にたんぱく質は欠かせません！「栄養管理ツール」で毎日の栄養バランスを確認して、足りないものを補いましょう。', title_ko = '단백질은 충분한가요? 🍗', body_ko = '아이의 성장에는 단백질이 꼭 필요해요! 수유 기록 도구로 하루 영양 균형을 확인하고 부족한 부분을 채워 주세요.', title_nl = 'Hoe zit het met de eiwitten? 🍗', body_nl = 'Eiwit is onmisbaar voor de groei van je kindje! Meet zijn dagelijkse voedingsbalans met de Voedingstracker en vul aan wat ontbreekt.', title_pl = 'Jak tam zapas białka? 🍗', body_pl = 'Białko jest niezbędne do wzrostu dziecka! Sprawdź w narzędziu do śledzenia karmienia jego dzienny bilans żywieniowy i uzupełnij braki.', title_pt = 'Como está a reserva de proteína? 🍗', body_pt = 'A proteína é essencial para o crescimento da criança! Meça o equilíbrio alimentar diário dele com o Registo de Alimentação e complete o que faltar.', title_sv = 'Hur går det med proteinet? 🍗', body_sv = 'Protein är en förutsättning för barnets tillväxt! Mät det dagliga näringsintaget med Matningskoll och fyll i det som saknas.', title_vi = 'Lượng protein thế nào rồi? 🍗', body_vi = 'Protein là điều kiện cần cho sự phát triển của bé! Hãy đo sự cân bằng dinh dưỡng hằng ngày bằng công cụ Theo dõi cữ bú và bổ sung những gì còn thiếu.', title_zh = '蛋白质够吗？🍗', body_zh = '蛋白质是孩子成长的必需！用喂养记录工具衡量他每天的饮食均衡，补上不足的部分吧。' WHERE id = 'e29e6044-f61d-47fa-b1d7-8e16d2c4b2ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
