UPDATE public.mommy_day_notifications SET title_es = 'Un fondo mágico para la noche 🪄', title_fr = 'Une ambiance de nuit magique 🪄', title_hi = 'जादुई रात का बैकग्राउंड 🪄', title_id = 'Latar malam yang ajaib 🪄', title_ja = '魔法の夜のBGM 🪄', title_ko = '마법 같은 밤의 배경음 🪄', title_nl = 'Een magische achtergrond voor de nacht 🪄', title_pl = 'Magiczne tło na noc 🪄', title_pt = 'Um fundo mágico para a noite 🪄', title_sv = 'Magisk nattbakgrund 🪄', title_vi = 'Không gian đêm kỳ diệu 🪄', title_zh = '魔法夜晚背景 🪄' WHERE id = 'eec0d21f-e4e1-482b-ae4c-9c9f182e42a1' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se te ha acabado la paciencia? Cierra la puerta de la habitación y deja a tu peque a solas con papá. Que esta noche sea él quien mande en el parque de juegos de casa.', body_fr = 'Vous êtes à bout de patience ? Fermez la porte de la pièce et laissez l''enfant seul avec son papa. Ce soir, c''est lui le chef de l''aire de jeux de la maison.', body_hi = 'धैर्य खत्म हो गया? कमरे का दरवाज़ा बंद कीजिए और बच्चे को उसके पापा के साथ अकेला छोड़ दीजिए। आज शाम घर के प्ले पार्क के बॉस वही हों।', body_id = 'Kesabaran habis? Tutup pintu kamar dan biarkan si kecil berdua saja dengan ayahnya. Malam ini, biar ia yang jadi pemimpin taman bermain di rumah.', body_ja = 'がまんの限界？部屋のドアを閉めて、お子さんをパパに任せましょう。今夜は家の遊び場のリーダーはパパです。', body_ko = '인내심이 바닥났나요? 방문을 닫고 아이를 아빠와 단둘이 두세요. 오늘 저녁 집 안 놀이터의 대장은 아빠예요.', body_nl = 'Is je geduld op? Doe de deur dicht en laat je kindje alleen met papa. Laat hem vanavond de baas zijn van de speeltuin thuis.', body_pl = 'Skończyła ci się cierpliwość? Zamknij drzwi pokoju i zostaw malucha samego z tatą. Niech dziś wieczorem to on rządzi domowym placem zabaw.', body_pt = 'A paciência acabou? Feche a porta do quarto e deixe a criança sozinha com o pai. Esta noite, ele que seja o chefe do parque infantil lá de casa.', body_sv = 'Har tålamodet tagit slut? Stäng dörren och lämna barnet ensamt med pappa. Låt honom vara chef över hemmets lekpark i kväll.', body_vi = 'Mẹ hết kiên nhẫn rồi? Hãy đóng cửa phòng và để bé chơi riêng với bố. Tối nay hãy để bố làm "trưởng khu vui chơi" trong nhà.', body_zh = '耐心用完了？关上房门，让宝宝和爸爸单独待一会儿。今晚就让爸爸当家里游乐园的负责人吧。' WHERE id = '51155148-f9ec-40a7-99a1-3f09cffe59c1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
