UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal las proteínas? 🍗', title_fr = 'Et les protéines ? 🍗', title_hi = 'प्रोटीन कितना मिल रहा है? 🍗', title_id = 'Bagaimana asupan proteinnya? 🍗', title_ja = 'たんぱく質は足りている？🍗', title_ko = '단백질은 충분한가요? 🍗', title_nl = 'Hoe zit het met de eiwitten? 🍗', title_pl = 'Jak tam zapas białka? 🍗', title_pt = 'Como está a reserva de proteína? 🍗', title_sv = 'Hur går det med proteinet? 🍗', title_vi = 'Lượng protein thế nào rồi? 🍗', title_zh = '蛋白质够吗？🍗' WHERE id = '25439bfb-873c-4735-bc03-f5aa2d6b8ff2' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo saber si ya está lleno? ⏱️', title_fr = 'Comment savoir s''il n''a plus faim ? ⏱️', title_hi = 'कैसे जानें कि पेट भर गया? ⏱️', title_id = 'Bagaimana tahu ia sudah kenyang? ⏱️', title_ja = 'お腹いっぱいのサインは？⏱️', title_ko = '배부른 걸 어떻게 알까요? ⏱️', title_nl = 'Hoe weet je dat hij vol zit? ⏱️', title_pl = 'Jak poznać, że jest najedzony? ⏱️', title_pt = 'Como saber se está satisfeito? ⏱️', title_sv = 'Hur vet vi att barnet är mätt? ⏱️', title_vi = 'Làm sao biết bé đã no? ⏱️', title_zh = '怎么知道他吃饱了？⏱️' WHERE id = 'a40e092a-696e-4da1-98b1-5b56a4f49122' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando se duerma, daos un masaje de hombros el uno al otro con tu pareja para soltar el estrés del día. ¡Sois un equipo!', body_fr = 'Une fois qu''il dort, massez-vous les épaules à tour de rôle avec votre conjoint pour évacuer le stress de la journée. Vous êtes une équipe !', body_hi = 'बच्चे के सोने के बाद दिन का तनाव निकालने के लिए अपने पार्टनर के साथ एक-दूसरे के कंधों की मालिश कीजिए। आप एक टीम हैं!', body_id = 'Setelah si kecil tidur, lepaskan stres hari ini dengan saling memijat bahu bersama pasangan. Kalian satu tim!', body_ja = 'お子さんが寝たら、一日のストレスを解消するために、パートナーと肩をもみ合いましょう。おふたりはチームです！', body_ko = '아이가 잠들면 하루의 스트레스를 풀 수 있게 배우자와 서로 어깨를 주물러 주세요. 두 사람은 한 팀이에요!', body_nl = 'Geef elkaar als je kindje slaapt een schoudermassage om de stress van de dag kwijt te raken. Jullie zijn een team!', body_pl = 'Gdy maluszek zaśnie, zróbcie sobie z partnerem nawzajem masaż ramion, by zrzucić stres dnia. Jesteście zespołem!', body_pt = 'Depois de a criança adormecer, façam uma massagem aos ombros um ao outro para libertar o stress do dia. Vocês são uma equipa!', body_sv = 'När barnet har somnat, ge varandra en axelmassage med din partner för att släppa dagens stress. Ni är ett team!', body_vi = 'Khi bé ngủ, hãy cùng bố xoa bóp vai cho nhau để xua tan căng thẳng trong ngày. Hai người là một đội!', body_zh = '宝宝睡着后，和伴侣互相按按肩膀，卸下一天的压力吧。你们是一个团队！' WHERE id = '25c00809-7707-4080-969f-0093aea099c2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
