UPDATE public.mommy_day_notifications SET title_es = 'Explorando al aire libre 🌳', title_fr = 'Exploration au grand air 🌳', title_hi = 'ताज़ी हवा में खोज 🌳', title_id = 'Menjelajah di udara segar 🌳', title_ja = '外の空気で探検 🌳', title_ko = '신선한 공기 탐험 🌳', title_nl = 'Ontdekkingen in de frisse lucht 🌳', title_pl = 'Odkrycia na świeżym powietrzu 🌳', title_pt = 'Explorar ao ar livre 🌳', title_sv = 'Upptäcktsfärd i friska luften 🌳', title_vi = 'Khám phá không khí trong lành 🌳', title_zh = '新鲜空气探险 🌳' WHERE id = '2f36e03e-8050-4c96-a7d2-3231c5e8bf3f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa para el café ☕', title_fr = 'Pause café ☕', title_hi = 'कॉफ़ी ब्रेक ☕', title_id = 'Rehat kopi ☕', title_ja = 'コーヒーブレイク ☕', title_ko = '커피 타임 ☕', title_nl = 'Koffiepauze ☕', title_pl = 'Przerwa na kawę ☕', title_pt = 'Pausa para o café ☕', title_sv = 'Kaffepaus ☕', title_vi = 'Giờ nghỉ cà phê ☕', title_zh = '咖啡时间 ☕' WHERE id = '1a858fa5-276f-440e-972b-2b83e93db467' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Sin fregar el suelo? Que se quede así. Una casa sucia se arregla, pero una mamá agotada tarda mucho en recuperarse. Túmbate en el sofá y escucha la calma.', body_fr = 'Le sol n''a pas été lavé ? Tant pis. Une maison sale se range, mais une maman épuisée met longtemps à récupérer. Allongez-vous sur le canapé et écoutez simplement le calme.', body_hi = 'फ़र्श पर पोंछा नहीं लगा? रहने दीजिए। गंदा घर ठीक हो जाता है, लेकिन थकी हुई माँ को सँभलने में लंबा समय लगता है। सोफ़े पर लेटिए और बस शांति को सुनिए।', body_id = 'Lantai belum dipel? Biarkan saja. Rumah yang kotor bisa dibereskan, tapi ibu yang kehabisan tenaga butuh waktu lama untuk pulih. Berbaringlah di sofa dan dengarkan saja ketenangannya.', body_ja = '床が拭けていない？そのままで大丈夫。散らかった家は片付きますが、疲れきったママの回復には時間がかかります。ソファに横になって、静けさに耳を傾けましょう。', body_ko = '바닥을 못 닦았나요? 그냥 두세요. 지저분한 집은 금방 정리되지만, 지친 엄마가 회복하는 데는 오래 걸려요. 소파에 누워 고요함에 귀 기울여 보세요.', body_nl = 'Is de vloer niet gedweild? Laat maar zo. Een vies huis is zo opgeruimd, maar een uitgeputte moeder heeft lang nodig om te herstellen. Ga op de bank liggen en luister gewoon naar de rust.', body_pl = 'Podłoga nieumyta? Niech tak zostanie. Brudny dom da się ogarnąć, ale wyczerpana mama długo wraca do sił. Połóż się na kanapie i po prostu wsłuchaj się w ciszę.', body_pt = 'O chão não foi limpo? Deixe ficar. Uma casa suja arruma-se, mas uma mãe esgotada demora muito a recuperar. Deite-se no sofá e escute simplesmente a tranquilidade.', body_sv = 'Är golvet inte torkat? Låt det vara. Ett smutsigt hem går att fixa, men det tar lång tid för en utmattad mamma att återhämta sig. Lägg dig på soffan och lyssna bara på lugnet.', body_vi = 'Sàn nhà chưa lau? Cứ để đó. Nhà bẩn thì dọn được, nhưng một người mẹ kiệt sức cần rất lâu để hồi phục. Hãy nằm xuống sofa và lắng nghe sự yên bình.', body_zh = '地还没拖？那就先放着。乱糟糟的家很快能收拾好，但累垮的妈妈要恢复却需要很久。在沙发上躺一躺，静静聆听这份安宁吧。' WHERE id = 'e490e4c7-7ef7-4eec-a03a-11da14534526' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
