UPDATE public.mommy_day_notifications SET title_es = 'Exploración en la naturaleza 🌳', title_fr = 'Exploration de la nature 🌳', title_hi = 'प्रकृति की खोज 🌳', title_id = 'Menjelajahi alam 🌳', title_ja = '自然を探検 🌳', title_ko = '자연 탐험 🌳', title_nl = 'Ontdekkingstocht in de natuur 🌳', title_pl = 'Odkrywanie natury 🌳', title_pt = 'Explorar a natureza 🌳', title_sv = 'Upptäcktsfärd i naturen 🌳', title_vi = 'Khám phá thiên nhiên 🌳', title_zh = '大自然探险 🌳' WHERE id = 'f9854a88-373e-4d4d-91e8-4e24a9ea9cba' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cansada de ver siempre las mismas paredes? Descubre en Lugares para mamás una cafetería con zona de juegos infantil. Que juegue mientras tú disfrutas del café.', body_fr = 'Regarder toujours les mêmes murs vous a épuisée. Trouvez dans les Lieux adaptés aux mamans un café avec un coin jeux. Il joue, vous savourez votre café.', body_hi = 'घर की वही दीवारें देखकर आप थक गई हैं। माँ के लिए अनुकूल जगहों में बच्चों के खेलने के कोने वाला कोई कैफ़े खोजिए। वह खेले, और आप कॉफ़ी का मज़ा लीजिए।', body_id = 'Bosan menatap dinding rumah yang sama? Temukan kafe dengan area bermain anak di Tempat Ramah Ibu. Biar ia bermain, dan Anda menikmati kopi.', body_ja = '家の同じ壁ばかり見て疲れていませんか？「ママにやさしいスポット」でキッズスペースのあるカフェを見つけましょう。お子さんは遊び、あなたはコーヒーを楽しんで。', body_ko = '집 안의 똑같은 벽만 보느라 지쳤나요? 엄마 친화 장소에서 키즈 놀이 공간이 있는 카페를 찾아보세요. 아이는 놀고, 엄마는 커피를 즐기세요.', body_nl = 'Ben je het zat om naar dezelfde muren te kijken? Ontdek in Mamavriendelijke plekken een café met speelhoek. Laat je kindje spelen en geniet jij van je koffie.', body_pl = 'Masz dość patrzenia na te same ściany w domu? Odkryj w Miejscach przyjaznych mamom kawiarnię z kącikiem zabaw dla dzieci. Niech on się bawi, a ty delektuj się kawą.', body_pt = 'Olhar para as mesmas paredes de casa esgotou-a. Descubra nos Locais Amigos das Mães um café com espaço de brincar para crianças. Ele brinca, e a mãe saboreia o café.', body_sv = 'Har du tröttnat på att titta på samma väggar hemma? Hitta ett kafé med lekhörna i Mammavänliga platser. Låt barnet leka medan du njuter av kaffet.', body_vi = 'Nhìn mãi những bức tường quen thuộc khiến mẹ kiệt sức. Hãy khám phá một quán cà phê có góc vui chơi cho trẻ trong Địa điểm thân thiện với mẹ. Bé chơi, còn mẹ thưởng thức cà phê.', body_zh = '天天对着家里同样的墙壁，你已经累坏了。从妈妈友好场所里找一家有儿童游乐区的咖啡馆。宝宝玩，你好好享受咖啡。' WHERE id = '69a15994-f6a2-4e74-92d0-633dfea33b45' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sonidos de animales 🐶', title_fr = 'Les cris des animaux 🐶', title_hi = 'जानवरों की आवाज़ें 🐶', title_id = 'Suara hewan 🐶', title_ja = '動物の鳴き声 🐶', title_ko = '동물 소리 🐶', title_nl = 'Dierengeluiden 🐶', title_pl = 'Odgłosy zwierząt 🐶', title_pt = 'Sons de animais 🐶', title_sv = 'Djurläten 🐶', title_vi = 'Tiếng kêu của con vật 🐶', title_zh = '动物叫声 🐶' WHERE id = '71af31e1-67cd-4bc6-a54d-505d0d3ed0af' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Celebra esta noche con tu pareja, a la luz de las velas, el cansancio y el orgullo de todo un año. ¡Sois un equipo perfecto!', body_fr = 'Ce soir, fêtez avec votre conjoint, à la lueur des bougies, une année de fatigue et de fierté. Vous formez une équipe parfaite !', body_hi = '1 साल की थकान और गर्व को आज शाम अपने साथी के साथ मोमबत्ती की रोशनी में मनाइए। आप एक परफ़ेक्ट टीम हैं!', body_id = 'Malam ini, rayakan lelah dan bangganya 1 tahun bersama pasangan di bawah cahaya lilin. Kalian tim yang sempurna!', body_ja = '1年分の疲れと誇りを、今夜はパートナーとろうそくの灯りの下でお祝いしましょう。おふたりは最高のチームです！', body_ko = '1년의 피로와 뿌듯함을 오늘 저녁 배우자와 함께 촛불 아래에서 축하해요. 두 사람은 완벽한 팀이에요!', body_nl = 'Vier vanavond bij kaarslicht samen met je partner een jaar vol vermoeidheid en trots. Jullie zijn een perfect team!', body_pl = 'Uczcij dziś wieczorem z partnerem przy świecach zmęczenie i dumę całego roku. Jesteście idealnym zespołem!', body_pt = 'Celebre esta noite, à luz das velas, com o seu companheiro o cansaço e o orgulho de um ano inteiro. Vocês são uma equipa perfeita!', body_sv = 'Fira ett års trötthet och stolthet i kväll med din partner i levande ljus. Ni är ett perfekt team!', body_vi = 'Tối nay hãy cùng bố ăn mừng một năm mệt nhọc nhưng đầy tự hào bên ánh nến. Hai người là một đội hoàn hảo!', body_zh = '今晚和另一半一起在烛光下，庆祝这一年的疲惫与骄傲。你们是完美的团队！' WHERE id = '0eb89ca2-1605-4f92-8c61-0198a966afb1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mañana cumple 16 meses! 🎉', body_es = '¿Lista? ¡Mañana hace 16 meses justos! Libera memoria en el móvil: mañana necesitarás espacio para captar sus caritas más tiernas en la Sesión de fotos del bebé.', title_fr = 'Demain, 16 mois ! 🎉', body_fr = 'Prête ? Demain, 16 mois pile ! Libérez de la mémoire sur votre téléphone, il vous faudra de la place pour capturer ses plus jolies mimiques dans la Séance photo bébé.', title_hi = 'कल 16 महीने! 🎉', body_hi = 'तैयार हैं? कल पूरे 16 महीने! फ़ोन की मेमोरी खाली कीजिए, कल बेबी फ़ोटोशूट में उसके सबसे प्यारे हाव-भाव कैद करने के लिए जगह चाहिए होगी।', title_id = 'Besok genap 16 bulan! 🎉', body_id = 'Siap? Besok tepat 16 bulan! Kosongkan memori ponsel, besok Anda butuh ruang untuk memotret ekspresi termanisnya di Sesi Foto Bayi.', title_ja = '明日で1歳4か月！🎉', body_ja = '準備はいいですか？明日でちょうど1歳4か月！スマホの容量を空けておきましょう。明日の「ベビーフォトセッション」で、かわいい表情をたくさん撮るのに必要です。', title_ko = '내일이면 16개월! 🎉', body_ko = '준비됐나요? 내일이면 꼬박 16개월이에요! 휴대폰 저장 공간을 비워 두세요. 내일 아기 사진 촬영으로 가장 귀여운 표정을 담으려면 공간이 필요할 거예요.', title_nl = 'Morgen 16 maanden! 🎉', body_nl = 'Ben je er klaar voor? Morgen precies 16 maanden! Maak ruimte vrij op je telefoon, morgen heb je in Babyfotoshoot plek nodig voor de liefste gezichtjes.', title_pl = 'Jutro 16 miesięcy! 🎉', body_pl = 'Gotowa? Jutro równo 16 miesięcy! Zwolnij pamięć w telefonie, jutro w Sesji zdjęciowej dziecka przyda się miejsce na najsłodsze minki.', title_pt = 'Amanhã faz 16 meses! 🎉', body_pt = 'Está pronta? Amanhã faz exatamente 16 meses! Liberte memória no telemóvel: amanhã vai precisar de espaço para fotografar as caretas mais doces na Sessão Fotográfica do Bebé.', title_sv = '16 månader i morgon! 🎉', body_sv = 'Är du redo? I morgon är det exakt 16 månader! Rensa telefonens minne, i morgon behöver du plats för att fånga de sötaste minerna i Babyfotografering.', title_vi = 'Ngày mai bé tròn 16 tháng! 🎉', body_vi = 'Mẹ sẵn sàng chưa? Ngày mai bé tròn 16 tháng! Hãy dọn dẹp bộ nhớ điện thoại, mai mẹ sẽ cần chỗ để chụp những biểu cảm đáng yêu nhất trong Chụp ảnh cho bé.', title_zh = '明天就16个月啦！🎉', body_zh = '准备好了吗？明天就整整16个月了！清理一下手机内存，明天用宝宝写真拍那些最可爱的小表情需要空间。' WHERE id = '2980029e-45df-4043-851c-f7839d81a721' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡UN AÑO! ¡PRIMER CUMPLEAÑOS! 🎂🎉', body_es = '¡ERES INCREÍBLE! {milestone_days} días exactos de noches sin dormir, primeras carcajadas y primeros pasos. ¡Ya tiene 1 año! Abre la Sesión de fotos del bebé e inmortaliza este día histórico con las fotos más bonitas.', title_fr = 'UN AN ! PREMIER ANNIVERSAIRE ! 🎂🎉', body_fr = 'VOUS ÊTES FORMIDABLE ! {milestone_days} jours pile, des nuits blanches, les premiers éclats de rire, les premiers pas ! Il a déjà 1 an ! Ouvrez la Séance photo bébé et immortalisez ce jour historique avec les plus belles photos !', title_hi = 'एक साल! पहला जन्मदिन! 🎂🎉', body_hi = 'आप कमाल की हैं! पूरे {milestone_days} दिन, बिना नींद की रातें, पहली खिलखिलाहट, पहले कदम! अब वह 1 साल का हो गया है! बेबी फ़ोटोशूट खोलिए और इस ऐतिहासिक दिन को सबसे खूबसूरत तस्वीरों में हमेशा के लिए सहेज लीजिए!', title_id = 'SATU TAHUN! ULANG TAHUN PERTAMA! 🎂🎉', body_id = 'ANDA LUAR BIASA! Tepat {milestone_days} hari: malam tanpa tidur, tawa pertama, langkah pertama! Kini ia sudah berusia 1 tahun! Buka Sesi Foto Bayi dan abadikan hari bersejarah ini dengan foto-foto terindah!', title_ja = '1歳！はじめてのお誕生日！🎂🎉', body_ja = '本当にすごい！ちょうど{milestone_days}日間、眠れない夜、はじめての笑い声、はじめての一歩！お子さんはもう1歳です！「ベビーフォトセッション」を開いて、この記念すべき日を最高の写真で残しましょう！', title_ko = '1살! 첫 생일! 🎂🎉', body_ko = '정말 대단해요! 꼬박 {milestone_days}일, 잠 못 든 밤들, 첫 웃음소리, 첫걸음! 아이가 벌써 1살이에요! 아기 사진 촬영을 열어 이 역사적인 날을 가장 아름다운 사진으로 영원히 남기세요!', title_nl = 'EEN JAAR! DE EERSTE VERJAARDAG! 🎂🎉', body_nl = 'JULLIE ZIJN GEWELDIG! Precies {milestone_days} dagen, slapeloze nachten, eerste schaterlachjes, eerste stapjes! Je kindje is nu 1 jaar! Open Babyfotoshoot en leg deze historische dag vast met de mooiste foto''s!', title_pl = 'ROCZEK! PIERWSZE URODZINY! 🎂🎉', body_pl = 'JESTEŚ WSPANIAŁA! Równo {milestone_days} dni, nieprzespane noce, pierwsze wybuchy śmiechu, pierwsze kroki! Maluszek ma już roczek! Otwórz Sesję zdjęciową dziecka i uwiecznij ten historyczny dzień na najpiękniejszych zdjęciach!', title_pt = 'UM ANO! O PRIMEIRO ANIVERSÁRIO! 🎂🎉', body_pt = 'É FANTÁSTICA! Exatamente {milestone_days} dias, noites sem dormir, as primeiras gargalhadas, os primeiros passos! Já tem 1 ano! Abra a Sessão Fotográfica do Bebé e eternize este dia histórico com as fotos mais bonitas!', title_sv = 'ETT ÅR! FÖRSTA FÖDELSEDAGEN! 🎂🎉', body_sv = 'NI ÄR FANTASTISKA! Exakt {milestone_days} dagar, sömnlösa nätter, de första skratten, de första stegen! Nu är barnet 1 år! Öppna Babyfotografering och förevig denna historiska dag med de finaste bilderna!', title_vi = 'TRÒN MỘT TUỔI! SINH NHẬT ĐẦU TIÊN! 🎂🎉', body_vi = 'MẸ THẬT TUYỆT VỜI! Tròn {milestone_days} ngày, những đêm mất ngủ, những tràng cười đầu tiên, những bước đi đầu tiên! Bé đã tròn 1 tuổi rồi! Hãy mở Chụp ảnh cho bé và lưu giữ ngày lịch sử này bằng những khung hình đẹp nhất!', title_zh = '一岁啦！第一个生日！🎂🎉', body_zh = '你们太棒了！整整{milestone_days}天，无数个不眠之夜、第一次大笑、第一次迈步！宝宝已经1岁啦！打开宝宝写真，用最美的照片定格这个历史性的日子！' WHERE id = '2e46d431-01ee-479e-a146-2b349cd7f234' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Camino de los 14 meses! ¡Faltan 10 días! 🎂', body_es = '¡Es increíble! Dentro de 10 días exactos tu peque cumple 14 meses. Cada día se vuelve más independiente.', title_fr = 'Bientôt 14 mois ! Plus que 10 jours ! 🎂', body_fr = 'Incroyable ! Dans 10 jours pile, votre petit aura 14 mois. Chaque jour, il devient un peu plus autonome.', title_hi = '14 महीने करीब! 10 दिन बाकी! 🎂', body_hi = 'यकीन नहीं होता! ठीक 10 दिन बाद आपका नन्हा 14 महीने का हो जाएगा। हर गुज़रते दिन के साथ वह और आत्मनिर्भर इंसान बनता जा रहा है।', title_id = 'Menuju 14 bulan! 10 hari lagi! 🎂', body_id = 'Luar biasa! Tepat 10 hari lagi si kecil genap 14 bulan. Setiap hari ia makin menjadi pribadi yang mandiri.', title_ja = 'もうすぐ1歳2か月！あと10日！🎂', body_ja = '信じられない！ちょうど10日後に、1歳2か月になります。日ごとに、ますます自立したひとりの人へと成長しています。', title_ko = '14개월까지 10일! 🎂', body_ko = '믿기지 않아요! 딱 10일 뒤면 우리 아이가 14개월이 돼요. 하루하루 더 독립적인 한 사람이 되어 가요.', title_nl = 'Bijna 14 maanden! Nog 10 dagen! 🎂', body_nl = 'Ongelofelijk! Over precies 10 dagen wordt je kleintje 14 maanden. Elke dag wordt hij een zelfstandiger persoontje.', title_pl = 'Coraz bliżej 14 miesięcy! Zostało 10 dni! 🎂', body_pl = 'Niesamowite! Dokładnie za 10 dni maluszek skończy 14 miesięcy. Z każdym dniem staje się coraz bardziej samodzielną osóbką.', title_pt = 'A caminho dos 14 meses! Faltam 10 dias! 🎂', body_pt = 'É incrível! Daqui a exatamente 10 dias, o seu pequenino faz 14 meses. A cada dia que passa torna-se uma pessoa mais independente.', title_sv = 'Snart 14 månader! 10 dagar kvar! 🎂', body_sv = 'Otroligt! Om exakt 10 dagar fyller den lilla 14 månader. För varje dag blir barnet en allt mer självständig person.', title_vi = 'Sắp tròn 14 tháng! Còn 10 ngày! 🎂', body_vi = 'Thật khó tin! Đúng 10 ngày nữa bé sẽ tròn 14 tháng. Mỗi ngày trôi qua, bé lại tự lập hơn một chút.', title_zh = '快14个月啦！还有10天！🎂', body_zh = '真不敢相信！再过整整10天，小家伙就满14个月了。他每天都在变得更加独立。' WHERE id = '319cae50-0492-468a-98e4-1b38563ab7ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡14 MESES JUSTOS! 🎉', body_es = '¡Enhorabuena! ¡Han pasado exactamente 14 meses desde el parto! Crea ya una foto temática especial en la Sesión de fotos del bebé y comparte esta alegría en la Comunidad Anacan.', title_fr = '14 MOIS PILE ! 🎉', body_fr = 'Félicitations ! Cela fait 14 mois pile depuis la naissance ! Créez vite une photo à thème dans la Séance photo bébé et partagez cette joie dans la Communauté Anacan !', title_hi = 'पूरे 14 महीने! 🎉', body_hi = 'बधाई हो! जन्म से अब तक पूरे 14 महीने बीत गए! तुरंत बेबी फ़ोटोशूट से खास थीम वाली तस्वीर बनाइए और यह खुशी Anacan कम्युनिटी में शेयर कीजिए!', title_id = 'GENAP 14 BULAN! 🎉', body_id = 'Selamat! Sudah tepat 14 bulan sejak ia lahir! Segera buat foto bertema khusus di Sesi Foto Bayi dan bagikan kebahagiaan ini di Komunitas Anacan!', title_ja = 'ちょうど1歳2か月！🎉', body_ja = 'おめでとうございます！生まれてからちょうど14か月！さっそく「ベビーフォトセッション」で特別なテーマの写真をつくって、この喜びをAnacanコミュニティでシェアしましょう！', title_ko = '꼬박 14개월! 🎉', body_ko = '축하해요! 태어난 지 꼬박 14개월이 됐어요! 지금 바로 아기 사진 촬영에서 특별한 테마 사진을 만들어 이 기쁨을 Anacan 커뮤니티에 공유하세요!', title_nl = 'PRECIES 14 MAANDEN! 🎉', body_nl = 'Gefeliciteerd! Sinds de geboorte zijn precies 14 maanden voorbij! Maak meteen een speciale themafoto in Babyfotoshoot en deel deze vreugde in de Anacan Community!', title_pl = 'RÓWNO 14 MIESIĘCY! 🎉', body_pl = 'Gratulacje! Od porodu minęło równo 14 miesięcy! Od razu stwórz w Sesji zdjęciowej dziecka wyjątkowe tematyczne zdjęcie i podziel się tą radością w Społeczności Anacan!', title_pt = '14 MESES CERTINHOS! 🎉', body_pt = 'Parabéns! Passaram exatamente 14 meses desde o nascimento! Crie já uma foto temática especial na Sessão Fotográfica do Bebé e partilhe esta alegria na Comunidade Anacan!', title_sv = 'EXAKT 14 MÅNADER! 🎉', body_sv = 'Grattis! Exakt 14 månader har gått sedan förlossningen! Skapa direkt en temabild i Babyfotografering och dela glädjen i Anacans Community!', title_vi = 'TRÒN 14 THÁNG! 🎉', body_vi = 'Chúc mừng! Đã tròn 14 tháng kể từ ngày bé chào đời! Hãy tạo ngay một bức ảnh theo chủ đề đặc biệt trong Chụp ảnh cho bé và chia sẻ niềm vui này trong Cộng đồng Anacan!', title_zh = '整整14个月！🎉', body_zh = '恭喜！从出生到现在已经整整14个月了！马上用宝宝写真做一张特别主题照片，在Anacan社区分享这份喜悦吧！' WHERE id = '3d197dae-8e31-468d-8d92-41ba68985a62' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Creció 9 meses en tu vientre y 1 año en tus brazos! Hoy no solo es su cumpleaños, también es tu cumpleaños como madre. ¡Siéntete orgullosa!', body_fr = 'Il a grandi 9 mois dans votre ventre et 1 an dans vos bras ! Aujourd''hui, ce n''est pas seulement son anniversaire, c''est aussi celui de votre maternité. Soyez fière de vous !', body_hi = 'वह 9 महीने आपकी कोख में और 1 साल आपकी बाँहों में बड़ा हुआ! आज सिर्फ़ उसका नहीं, आपका भी ''माँ बनने का जन्मदिन'' है। खुद पर गर्व कीजिए!', body_id = 'Ia tumbuh 9 bulan di rahim Anda dan 1 tahun di pelukan Anda! Hari ini bukan hanya ulang tahunnya, tapi juga Ulang Tahun Keibuan Anda. Banggalah pada diri sendiri!', body_ja = 'お腹の中で9か月、腕の中で1年、大きくなりました！今日はお子さんだけでなく、あなたの「ママとしての誕生日」でもあります。自分を誇りに思ってくださいね。', body_ko = '배 속에서 9개월, 품 안에서 1년을 자랐어요! 오늘은 아이만이 아니라 엄마가 된 지 1년이 되는 날이기도 해요. 스스로를 자랑스러워하세요!', body_nl = 'Je kindje groeide 9 maanden in je buik en 1 jaar in je armen! Vandaag is niet alleen zijn verjaardag, maar ook jouw moederschapsverjaardag. Wees trots op jezelf!', body_pl = 'Rósł 9 miesięcy pod twoim sercem i 1 rok w twoich ramionach! Dziś to nie tylko jego urodziny, ale też twoje urodziny jako mamy. Bądź z siebie dumna!', body_pt = 'Cresceu 9 meses na sua barriga e 1 ano nos seus braços! Hoje não é só o aniversário dele, é também o seu Aniversário de Mãe. Orgulhe-se de si!', body_sv = 'Barnet växte 9 månader i din mage och 1 år i din famn! I dag är det inte bara barnets födelsedag, utan också din födelsedag som mamma. Var stolt över dig själv!', body_vi = 'Bé đã lớn lên 9 tháng trong bụng mẹ và 1 năm trong vòng tay mẹ! Hôm nay không chỉ là sinh nhật của bé mà còn là "Sinh nhật làm mẹ" của mẹ. Hãy tự hào về bản thân nhé!', body_zh = '宝宝在你肚子里长了9个月，在你怀里长了1年！今天不只是宝宝的生日，也是你成为妈妈的生日。为自己骄傲吧！' WHERE id = '3c2fa886-d095-424c-ad68-b439a1ffc0b9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡19 MESES JUSTOS! 🎂', body_es = '¡Enhorabuena! ¡Han pasado exactamente 19 meses desde el parto! Elige ya una pegatina especial en la Sesión de fotos del bebé y comparte esta alegría en la Comunidad Anacan.', title_fr = '19 MOIS PILE ! 🎂', body_fr = 'Félicitations ! Cela fait 19 mois pile depuis la naissance ! Choisissez vite un sticker spécial dans la Séance photo bébé et partagez cette joie dans la Communauté Anacan !', title_hi = 'पूरे 19 महीने! 🎂', body_hi = 'बधाई हो! जन्म से अब तक पूरे 19 महीने बीत गए! तुरंत बेबी फ़ोटोशूट से खास स्टिकर चुनिए और यह खुशी Anacan कम्युनिटी में शेयर कीजिए!', title_id = 'GENAP 19 BULAN! 🎂', body_id = 'Selamat! Sudah tepat 19 bulan sejak ia lahir! Segera pilih stiker khusus di Sesi Foto Bayi dan bagikan kebahagiaan ini di Komunitas Anacan!', title_ja = 'ちょうど1歳7か月！🎂', body_ja = 'おめでとうございます！生まれてからちょうど19か月！さっそく「ベビーフォトセッション」で特別なステッカーを選んで、この喜びをAnacanコミュニティでシェアしましょう！', title_ko = '꼬박 19개월! 🎂', body_ko = '축하해요! 태어난 지 꼬박 19개월이 됐어요! 지금 바로 아기 사진 촬영에서 특별한 스티커를 골라 이 기쁨을 Anacan 커뮤니티에 공유하세요!', title_nl = 'PRECIES 19 MAANDEN! 🎂', body_nl = 'Gefeliciteerd! Sinds de geboorte zijn precies 19 maanden voorbij! Kies meteen een speciale sticker in Babyfotoshoot en deel deze vreugde in de Anacan Community!', title_pl = 'RÓWNO 19 MIESIĘCY! 🎂', body_pl = 'Gratulacje! Od porodu minęło równo 19 miesięcy! Od razu wybierz w Sesji zdjęciowej dziecka specjalną naklejkę i podziel się tą radością w Społeczności Anacan!', title_pt = '19 MESES CERTINHOS! 🎂', body_pt = 'Parabéns! Passaram exatamente 19 meses desde o nascimento! Escolha já um autocolante especial na Sessão Fotográfica do Bebé e partilhe esta alegria na Comunidade Anacan!', title_sv = 'EXAKT 19 MÅNADER! 🎂', body_sv = 'Grattis! Exakt 19 månader har gått sedan förlossningen! Välj direkt ett speciellt klistermärke i Babyfotografering och dela glädjen i Anacans Community!', title_vi = 'TRÒN 19 THÁNG! 🎂', body_vi = 'Chúc mừng! Đã tròn 19 tháng kể từ ngày bé chào đời! Hãy chọn ngay một sticker đặc biệt trong Chụp ảnh cho bé và chia sẻ niềm vui này trong Cộng đồng Anacan!', title_zh = '整整19个月！🎂', body_zh = '恭喜！从出生到现在已经整整19个月了！马上在宝宝写真里选一个特别的贴纸，在Anacan社区分享这份喜悦吧！' WHERE id = '465d0258-9df5-4a0a-9902-79a09218dcc5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡15 meses justos! 🎉', body_es = '¡Cómo pasa el tiempo! Han pasado exactamente 1 año y 3 meses desde que tu peque llegó al mundo. Enhorabuena.', title_fr = '15 mois pile ! 🎉', body_fr = 'Comme le temps passe vite ! Cela fait 1 an et 3 mois pile que votre petit est arrivé au monde. Félicitations.', title_hi = 'पूरे 15 महीने! 🎉', body_hi = 'वक्त कितनी तेज़ी से उड़ता है! नन्हे के जन्म को पूरे 1 साल 3 महीने हो गए। बधाई हो।', title_id = 'Genap 15 bulan! 🎉', body_id = 'Waktu begitu cepat berlalu! Sudah tepat 1 tahun 3 bulan sejak si kecil lahir ke dunia. Selamat.', title_ja = 'ちょうど1歳3か月！🎉', body_ja = '時間がたつのは本当に早い！生まれてからちょうど1年3か月。おめでとうございます。', title_ko = '꼬박 15개월! 🎉', body_ko = '시간이 정말 빨리 가요! 아이가 태어난 지 꼬박 1년 3개월이 됐어요. 축하해요.', title_nl = 'Precies 15 maanden! 🎉', body_nl = 'Wat vliegt de tijd! Precies 1 jaar en 3 maanden geleden kwam je kleintje ter wereld. Gefeliciteerd.', title_pl = 'Równo 15 miesięcy! 🎉', body_pl = 'Jak ten czas leci! Od narodzin maluszka minął równo 1 rok i 3 miesiące. Gratulacje.', title_pt = '15 meses certinhos! 🎉', body_pt = 'Como o tempo voa! Passou exatamente 1 ano e 3 meses desde que o seu pequenino nasceu. Parabéns.', title_sv = 'Exakt 15 månader! 🎉', body_sv = 'Vad tiden flyger! Exakt 1 år och 3 månader har gått sedan den lilla kom till världen. Grattis.', title_vi = 'Tròn 15 tháng! 🎉', body_vi = 'Thời gian trôi nhanh quá! Đã tròn 1 năm 3 tháng kể từ ngày bé chào đời. Chúc mừng mẹ nhé.', title_zh = '整整15个月！🎉', body_zh = '时间过得真快！从小家伙出生到现在，已经整整1年3个月了。恭喜。' WHERE id = '4df5ec18-5365-45c2-a49d-90ce26310b0b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo faltan 10 días para los 16 meses! 🎂', body_es = '¡Es increíble! Dentro de 10 días exactos tu peque cumple 16 meses. Empieza a planear una pequeña tarta o una sesión de fotos para celebrarlo.', title_fr = 'Plus que 10 jours avant ses 16 mois ! 🎂', body_fr = 'Incroyable ! Dans 10 jours pile, votre petit aura 16 mois. Commencez à prévoir un petit gâteau ou une séance photo pour fêter ça.', title_hi = '16 महीने में बस 10 दिन बाकी! 🎂', body_hi = 'यकीन नहीं होता! ठीक 10 दिन बाद आपका नन्हा 16 महीने का हो जाएगा। इस मौके के लिए छोटा सा केक या फ़ोटोशूट प्लान करना शुरू कीजिए।', title_id = 'Tinggal 10 hari lagi menuju 16 bulan! 🎂', body_id = 'Luar biasa! Tepat 10 hari lagi si kecil genap 16 bulan. Mulailah merencanakan kue kecil atau sesi foto untuk merayakannya.', title_ja = '1歳4か月まであと10日！🎂', body_ja = '信じられない！ちょうど10日後に1歳4か月になります。記念日のために、小さなケーキやフォトセッションの計画を始めましょう。', title_ko = '16개월까지 딱 10일! 🎂', body_ko = '믿기지 않아요! 딱 10일 뒤면 아이가 16개월이 돼요. 기념일을 위한 작은 케이크나 사진 촬영을 계획해 보세요.', title_nl = 'Nog maar 10 dagen tot 16 maanden! 🎂', body_nl = 'Ongelofelijk! Over precies 10 dagen wordt je kleintje 16 maanden. Begin alvast met het plannen van een taartje of een fotoshoot voor dit jubileum.', title_pl = 'Tylko 10 dni do 16 miesięcy! 🎂', body_pl = 'Niesamowite! Dokładnie za 10 dni maluszek skończy 16 miesięcy. Zacznij planować mały tort lub sesję zdjęciową na tę okazję.', title_pt = 'Faltam só 10 dias para os 16 meses! 🎂', body_pt = 'É incrível! Daqui a exatamente 10 dias, o seu pequenino faz 16 meses. Comece a planear um pequeno bolo ou uma sessão de fotos para a ocasião.', title_sv = 'Bara 10 dagar kvar till 16 månader! 🎂', body_sv = 'Otroligt! Om exakt 10 dagar fyller den lilla 16 månader. Börja planera en liten tårta eller en fotostund för jubileet.', title_vi = 'Chỉ còn 10 ngày nữa là tròn 16 tháng! 🎂', body_vi = 'Thật khó tin! Đúng 10 ngày nữa bé sẽ tròn 16 tháng. Hãy bắt đầu lên kế hoạch cho một chiếc bánh nhỏ hay buổi chụp ảnh để mừng dịp này.', title_zh = '离16个月只剩10天！🎂', body_zh = '真不敢相信！再过整整10天，小家伙就满16个月了。开始计划一个小蛋糕或一次拍照，庆祝这个纪念日吧。' WHERE id = '569d0003-c871-435a-ae9b-f4e977441a16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Faltan 2 días para el gran día! 🗣', body_es = '️ Que te llame «mamá» o «papá» es el regalo más bonito. Lee los consejos del Blog para apoyar el desarrollo de sus primeras palabras.', title_fr = 'Plus que 2 jours avant le grand jour ! 🗣', body_fr = '️ L''entendre vous appeler « Maman » ou « Papa » est le plus beau des cadeaux. Lisez les conseils des Blogs pour accompagner ses premiers mots.', title_hi = 'बड़े दिन में 2 दिन बाकी! 🗣', body_hi = '️ उसका आपको माँ या पापा कहकर पुकारना सबसे खूबसूरत तोहफ़ा है। पहले शब्दों के विकास में मदद के लिए ब्लॉग में दी गई सलाह पढ़िए।', title_id = '2 hari lagi menuju hari besar! 🗣', body_id = '️ Dipanggil "Mama" atau "Papa" adalah hadiah terindah. Baca tips di Blog untuk mendukung perkembangan kata-kata pertamanya.', title_ja = '大切な日まであと2日！🗣', body_ja = '️「ママ」「パパ」と呼んでもらえるのは、何よりのプレゼントです。はじめての言葉の発達を応援するコツをブログで読んでみましょう。', title_ko = '큰 날까지 2일! 🗣', body_ko = '️엄마, 아빠 하고 불러 주는 건 가장 멋진 선물이에요. 첫 말의 발달을 돕는 팁을 블로그에서 읽어 보세요.', title_nl = 'Nog 2 dagen tot de grote dag! 🗣', body_nl = '️ Dat je kindje je mama of papa noemt, is het mooiste cadeau. Lees de tips in Blogs om de eerste woordjes te stimuleren.', title_pl = 'Jeszcze 2 dni do wielkiego dnia! 🗣', body_pl = '️ Usłyszeć od niego „mama” albo „tata” to najpiękniejszy prezent. Przeczytaj wskazówki na Blogach, aby wspierać rozwój pierwszych słów.', title_pt = 'Faltam 2 dias para o grande dia! 🗣', body_pt = '️ Ouvi-lo chamar "Mamã" ou "Papá" é o presente mais bonito. Leia as sugestões dos Blogues para apoiar o desenvolvimento das primeiras palavras.', title_sv = '2 dagar kvar till den stora dagen! 🗣', body_sv = '️ Att barnet kallar dig mamma eller pappa är den finaste gåvan. Läs tipsen i Bloggar för att stötta utvecklingen av de första orden.', title_vi = 'Còn 2 ngày nữa là đến ngày trọng đại! 🗣', body_vi = '️ Được bé gọi "Mẹ" hay "Bố" là món quà đẹp nhất. Hãy đọc những gợi ý trong mục Blog để hỗ trợ bé nói những từ đầu tiên.', title_zh = '离大日子还有2天！🗣', body_zh = '️ 宝宝叫你“妈妈”或“爸爸”，就是最美的礼物。去博客读读支持宝宝说出第一批词语的建议吧。' WHERE id = '5c11361a-fa0a-4cbc-ab7e-82f7bcc5e4bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Año y medio oficialmente! 🎈', body_es = 'Estos meses tu peque crece muy rápido. Introduce sus últimas medidas en el Seguimiento del desarrollo y mira con orgullo su gráfica de crecimiento.', title_fr = 'Officiellement 1 an et demi ! 🎈', body_fr = 'Votre enfant grandit très vite ces derniers mois. Saisissez ses dernières mesures dans le Suivi de croissance et regardez fièrement sa courbe.', title_hi = 'आधिकारिक तौर पर 1.5 साल! 🎈', body_hi = 'इन महीनों में आपका बच्चा तेज़ी से बढ़ रहा है। ग्रोथ ट्रैकर में ताज़ा आँकड़े डालिए और विकास के चार्ट को गर्व से देखिए।', title_id = 'Resmi 1,5 tahun! 🎈', body_id = 'Di bulan-bulan ini si kecil tumbuh dengan cepat. Masukkan ukuran terbarunya di Pelacak Pertumbuhan dan lihat grafik pertumbuhannya dengan bangga.', title_ja = 'ついに1歳半！🎈', body_ja = 'この数か月で、ぐんぐん大きくなっています。「発達トラッカー」に最新の数値を入れて、成長グラフを誇らしく眺めましょう。', title_ko = '공식적으로 1살 반! 🎈', body_ko = '요즘 아이가 쑥쑥 자라고 있어요. 성장 기록에 최근 수치를 입력하고 성장 그래프를 뿌듯하게 살펴보세요.', title_nl = 'Officieel 1,5 jaar! 🎈', body_nl = 'Je kindje groeit deze maanden snel. Voer de nieuwste gegevens in de Groeitracker in en bekijk trots zijn groeicurve.', title_pl = 'Oficjalnie 1,5 roku! 🎈', body_pl = 'W tych miesiącach dziecko szybko rośnie. Wpisz najnowsze pomiary w Śledzeniu rozwoju i z dumą spójrz na wykres rozwoju.', title_pt = 'Oficialmente 1 ano e meio! 🎈', body_pt = 'Nestes meses, o seu filho cresce depressa. Introduza as últimas medidas no Registo de Desenvolvimento e espreite com orgulho o gráfico de crescimento.', title_sv = 'Officiellt 1,5 år! 🎈', body_sv = 'Barnet växer snabbt de här månaderna. Lägg in de senaste måtten i Tillväxtspåraren och titta med stolthet på tillväxtkurvan.', title_vi = 'Chính thức 1,5 tuổi! 🎈', body_vi = 'Những tháng này bé lớn rất nhanh. Hãy nhập số đo mới nhất vào Theo dõi phát triển và tự hào ngắm biểu đồ phát triển của bé.', title_zh = '正式1岁半啦！🎈', body_zh = '这几个月宝宝长得飞快。在发育追踪里输入最新数据，自豪地看看成长曲线吧。' WHERE id = '6dca6700-52a0-4818-812b-80dcc5c42de9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡16 MESES JUSTOS! 🎂', body_es = 'Es increíble, ¿verdad? ¡Han pasado exactamente 16 meses desde aquel día tan emocionante en que le cogiste en brazos por primera vez! Es el momento perfecto para celebrar cuánto ha crecido. Elige un tema en la Sesión de fotos del bebé, inmortaliza la foto más tierna y comparte este orgullo con las demás mamás de la Comunidad Anacan.', title_fr = '16 MOIS PILE ! 🎂', body_fr = 'Incroyable, non ? Cela fait 16 mois pile depuis ce jour plein d''émotion où vous l''avez pris dans vos bras pour la première fois ! C''est le moment idéal pour fêter cette belle croissance. Choisissez un thème dans la Séance photo bébé pour immortaliser la plus jolie photo, et partagez cette fierté avec les autres mamans de la Communauté Anacan !', title_hi = 'पूरे 16 महीने! 🎂', body_hi = 'यकीन नहीं होता, है ना? जिस रोमांचक दिन आपने उसे पहली बार गोद में लिया था, तब से पूरे 16 महीने बीत गए! इस शानदार बढ़त को मनाने का यही सही समय है। बेबी फ़ोटोशूट से थीम चुनकर सबसे प्यारी तस्वीर सहेज लीजिए और यह गर्व Anacan कम्युनिटी की दूसरी माँओं के साथ ज़रूर बाँटिए!', title_id = 'GENAP 16 BULAN! 🎂', body_id = 'Luar biasa, bukan? Sudah tepat 16 bulan sejak hari mendebarkan saat Anda pertama kali menggendongnya! Inilah saat yang tepat untuk merayakan pertumbuhan yang luar biasa ini. Pilih tema di Sesi Foto Bayi, abadikan foto termanis, dan jangan lupa bagikan kebanggaan ini dengan ibu-ibu lain di Komunitas Anacan!', title_ja = 'ちょうど1歳4か月！🎂', body_ja = '信じられないですよね？はじめて腕に抱いたあのドキドキの日から、ちょうど16か月！このすばらしい成長をお祝いするのにぴったりのタイミングです。「ベビーフォトセッション」でテーマを選んでいちばんかわいい一枚を残し、その誇らしさをAnacanコミュニティのママたちとぜひシェアしましょう！', title_ko = '꼬박 16개월! 🎂', body_ko = '믿기지 않죠? 처음 품에 안았던 그 설레던 날부터 꼬박 16개월이 지났어요! 이 멋진 성장을 축하하기에 딱 좋은 때예요. 아기 사진 촬영에서 테마를 골라 가장 귀여운 한 컷을 영원히 남기고, 이 뿌듯함을 Anacan 커뮤니티의 다른 엄마들과 꼭 나눠 보세요!', title_nl = 'PRECIES 16 MAANDEN! 🎂', body_nl = 'Ongelofelijk, toch? Precies 16 maanden geleden hield je je kindje voor het eerst in je armen! Het is het perfecte moment om deze geweldige groei te vieren. Kies een thema in Babyfotoshoot, leg de liefste foto vast en deel deze trots zeker met de andere moeders in de Anacan Community!', title_pl = 'RÓWNO 16 MIESIĘCY! 🎂', body_pl = 'Niesamowite, prawda? Od tego pełnego emocji dnia, gdy pierwszy raz wzięłaś go na ręce, minęło równo 16 miesięcy! To idealny moment, by uczcić ten wspaniały rozwój. Wybierz motyw w Sesji zdjęciowej dziecka, uwiecznij najsłodsze ujęcie i koniecznie podziel się tą dumą z innymi mamami w Społeczności Anacan!', title_pt = '16 MESES CERTINHOS! 🎂', body_pt = 'É incrível, não é? Passaram exatamente 16 meses desde aquele dia emocionante em que o pegou ao colo pela primeira vez! É a altura certa para celebrar este crescimento fantástico. Escolha um tema na Sessão Fotográfica do Bebé, eternize a foto mais doce e não deixe de partilhar este orgulho com as outras mães da Comunidade Anacan!', title_sv = 'EXAKT 16 MÅNADER! 🎂', body_sv = 'Otroligt, eller hur? Exakt 16 månader har gått sedan den spännande dagen då du först höll barnet i famnen! Det är precis rätt tid att fira denna fantastiska tillväxt. Välj ett tema i Babyfotografering, förevig den sötaste bilden och dela stoltheten med de andra mammorna i Anacans Community!', title_vi = 'TRÒN 16 THÁNG! 🎂', body_vi = 'Thật khó tin phải không? Đã tròn 16 tháng kể từ ngày đầy xúc động mẹ lần đầu ôm bé vào lòng! Đây là lúc hoàn hảo để ăn mừng sự trưởng thành tuyệt vời này. Hãy chọn một chủ đề trong Chụp ảnh cho bé để lưu giữ khung hình đáng yêu nhất và chia sẻ niềm tự hào này với các mẹ trong Cộng đồng Anacan nhé!', title_zh = '整整16个月！🎂', body_zh = '真不可思议，对吧？从第一次把他抱在怀里的那个激动日子到现在，已经整整16个月了！现在正是庆祝这份了不起的成长的时候。在宝宝写真里选个主题，把最可爱的画面定格下来，一定要和Anacan社区的其他妈妈分享这份骄傲！' WHERE id = '86b4bb0f-0f98-485c-9149-10540747f598' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Felicidad en la mesa familiar 🍲', body_es = 'Ya puede comer lo mismo que vosotros. Descubre platos para toda la familia en las recetas de nuestra app y celebra este pequeño aniversario.', title_fr = 'Le bonheur des repas en famille. 🍲', body_fr = 'Il peut déjà manger les mêmes plats que vous. Découvrez des recettes familiales dans l''application et fêtez ce petit anniversaire.', title_hi = 'परिवार के खाने की मेज़ पर खुशी। 🍲', body_hi = 'अब वह आपके जैसा ही खाना खा सकता है। हमारे ऐप की रेसिपी से परिवार के लिए स्वादिष्ट व्यंजन खोजिए और इस छोटी सालगिरह को मनाइए।', title_id = 'Bahagia di meja makan keluarga. 🍲', body_id = 'Kini ia sudah bisa makan makanan yang sama dengan Anda. Temukan hidangan keluarga dari resep di aplikasi kami dan rayakan momen kecil ini.', title_ja = '家族の食卓の幸せ 🍲', body_ja = 'もう家族と同じ料理を食べられます。アプリのレシピで家族みんなで楽しめる味を見つけて、この小さな記念日をお祝いしましょう。', title_ko = '가족 식탁의 행복. 🍲', body_ko = '이제 엄마와 같은 음식을 먹을 수 있어요. 앱의 레시피에서 온 가족이 즐길 맛을 찾아 이 작은 기념일을 축하하세요.', title_nl = 'Geluk aan de gezinstafel. 🍲', body_nl = 'Je kindje kan nu hetzelfde eten als jullie. Ontdek gerechten voor het hele gezin in de recepten van onze app en vier dit kleine jubileum.', title_pl = 'Szczęście przy rodzinnym stole. 🍲', body_pl = 'Może już jeść te same dania co wy. Odkryj rodzinne smaki w przepisach z naszej aplikacji i uczcijcie ten mały jubileusz.', title_pt = 'Felicidade à mesa em família. 🍲', body_pt = 'Já pode comer os mesmos pratos que vocês. Descubra sabores para toda a família nas receitas da nossa app e celebre este pequeno marco.', title_sv = 'Lycka vid familjebordet. 🍲', body_sv = 'Nu kan barnet äta samma mat som ni. Upptäck familjerätter bland recepten i appen och fira det här lilla jubileet.', title_vi = 'Hạnh phúc bên mâm cơm gia đình. 🍲', body_vi = 'Giờ bé đã có thể ăn cùng món với cả nhà. Hãy khám phá những món ngon gia đình trong các công thức trên ứng dụng và ăn mừng cột mốc nhỏ này.', title_zh = '餐桌上的幸福 🍲', body_zh = '宝宝已经可以和你们吃一样的饭菜了。在我们应用的食谱里发现适合全家的美味，庆祝这个小小的纪念日吧。' WHERE id = 'a50254b7-b2f0-44b3-8ee9-5246bba08038' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Últimos preparativos 📸', body_es = '¿Velas, tarta y ropita listas? Libera memoria en el móvil: ¡mañana vas a necesitar mucho espacio para la Sesión de fotos del bebé!', title_fr = 'Derniers préparatifs 📸', body_fr = 'Bougies, gâteau, tenues : tout est prêt ? Libérez de la mémoire sur votre téléphone, demain la Séance photo bébé va demander beaucoup de place !', title_hi = 'आखिरी तैयारियाँ 📸', body_hi = 'मोमबत्तियाँ, केक, कपड़े तैयार हैं? फ़ोन की मेमोरी खाली कीजिए, कल बेबी फ़ोटोशूट में ढेर सारी जगह चाहिए होगी!', title_id = 'Persiapan terakhir 📸', body_id = 'Lilin, kue, dan baju sudah siap? Kosongkan memori ponsel, besok di Sesi Foto Bayi Anda butuh banyak ruang!', title_ja = '最後の準備 📸', body_ja = 'ろうそく、ケーキ、衣装の準備はできましたか？スマホの容量を空けておきましょう。明日の「ベビーフォトセッション」でたっぷり必要になりますよ！', title_ko = '마지막 준비 📸', body_ko = '초, 케이크, 옷은 다 준비됐나요? 휴대폰 저장 공간을 비워 두세요. 내일 아기 사진 촬영에 공간이 많이 필요할 거예요!', title_nl = 'Laatste voorbereidingen 📸', body_nl = 'Zijn de kaarsjes, de taart en de kleertjes klaar? Maak ruimte vrij op je telefoon, morgen heb je in Babyfotoshoot veel plek nodig!', title_pl = 'Ostatnie przygotowania 📸', body_pl = 'Świeczki, tort i ubranka gotowe? Zwolnij pamięć w telefonie, jutro w Sesji zdjęciowej dziecka przyda się mnóstwo miejsca!', title_pt = 'Últimos preparativos 📸', body_pt = 'Velas, bolo e roupa estão prontos? Liberte memória no telemóvel: amanhã vai precisar de muito espaço na Sessão Fotográfica do Bebé!', title_sv = 'Sista förberedelserna 📸', body_sv = 'Är ljusen, tårtan och kläderna klara? Rensa telefonens minne, i morgon behöver du massor av plats för Babyfotografering!', title_vi = 'Chuẩn bị những bước cuối cùng 📸', body_vi = 'Nến, bánh kem, quần áo đã sẵn sàng chưa? Hãy dọn dẹp bộ nhớ điện thoại, ngày mai mẹ sẽ cần thật nhiều chỗ cho Chụp ảnh cho bé!', title_zh = '最后的准备 📸', body_zh = '蜡烛、蛋糕、衣服都准备好了吗？清理一下手机内存，明天宝宝写真要用很多空间！' WHERE id = 'a6e2ed87-38de-413e-9884-cda9afcbb191' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Solo 5 días para los 16 meses! 🎈', body_es = '¡La cuenta atrás está a punto de terminar! ¿Tienes encargada la tarta y lista la ropa? Echa ya un vistazo a los temas alegres de la Sesión de fotos del bebé.', title_fr = '16 mois dans 5 jours ! 🎈', body_fr = 'Le compte à rebours touche à sa fin ! Le gâteau est commandé et les tenues sont prêtes ? Jetez dès maintenant un œil aux thèmes joyeux de la Séance photo bébé.', title_hi = '16 महीने में बस 5 दिन! 🎈', body_hi = 'उलटी गिनती खत्म होने को है! केक का ऑर्डर और कपड़े तैयार हैं? बेबी फ़ोटोशूट में मज़ेदार थीम अभी से देखिए।', title_id = 'Tinggal 5 hari lagi menuju 16 bulan! 🎈', body_id = 'Hitung mundur hampir selesai! Pesanan kue dan bajunya sudah siap? Lihat konsep-konsep ceria di Sesi Foto Bayi dari sekarang.', title_ja = '1歳4か月まであと5日！🎈', body_ja = 'カウントダウンももうすぐ終わり！ケーキの注文や衣装の準備はできましたか？「ベビーフォトセッション」の楽しいテーマを今からのぞいてみましょう。', title_ko = '16개월까지 딱 5일! 🎈', body_ko = '카운트다운이 거의 끝나 가요! 케이크 주문과 옷은 준비됐나요? 아기 사진 촬영에서 즐거운 콘셉트를 미리 둘러보세요.', title_nl = 'Nog maar 5 dagen tot 16 maanden! 🎈', body_nl = 'Het aftellen is bijna voorbij! Zijn de taart en de kleertjes klaar? Bekijk alvast de vrolijke thema''s in Babyfotoshoot.', title_pl = 'Tylko 5 dni do 16 miesięcy! 🎈', body_pl = 'Odliczanie dobiega końca! Tort zamówiony, ubranka gotowe? Już teraz przejrzyj wesołe motywy w Sesji zdjęciowej dziecka.', title_pt = 'Faltam só 5 dias para os 16 meses! 🎈', body_pt = 'A contagem decrescente está quase a terminar! A encomenda do bolo e a roupa estão prontas? Espreite desde já os temas divertidos da Sessão Fotográfica do Bebé.', title_sv = 'Bara 5 dagar till 16 månader! 🎈', body_sv = 'Nedräkningen är snart slut! Är tårtan beställd och kläderna klara? Titta redan nu på glada teman i Babyfotografering.', title_vi = 'Chỉ còn 5 ngày nữa là tròn 16 tháng! 🎈', body_vi = 'Đếm ngược sắp kết thúc! Bánh kem đã đặt và quần áo đã sẵn sàng chưa? Hãy xem trước những ý tưởng vui nhộn trong Chụp ảnh cho bé ngay từ bây giờ.', title_zh = '离16个月只剩5天！🎈', body_zh = '倒计时快结束了！蛋糕订好了吗？衣服准备好了吗？现在就去宝宝写真里看看欢乐的拍摄主题吧。' WHERE id = 'c016a9a1-5e0d-434a-ba4b-907c1125a45a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mañana cumple 1 año! 🎉', body_es = '¡Qué nostalgia! ¿Recuerdas el primer día que salisteis del hospital? Abre el Diario de ánimo y escríbele esta noche una carta emotiva que podrá leer en el futuro.', title_fr = 'Demain, il a 1 an ! 🎉', body_fr = 'Un vent de nostalgie ! Vous souvenez-vous du tout premier jour où vous avez quitté la maternité ? Ouvrez le Journal d''humeur et écrivez-lui ce soir une lettre émouvante qu''il lira plus tard.', title_hi = 'कल 1 साल का! 🎉', body_hi = 'पुरानी यादों की हवा! अस्पताल से घर लौटने का वह पहला दिन याद है? मूड डायरी खोलिए और आज रात उसके लिए एक भावुक चिट्ठी लिखिए, जिसे वह बड़ा होकर पढ़ेगा।', title_id = 'Besok ulang tahun pertama! 🎉', body_id = 'Rindu masa lalu? Ingat hari pertama Anda keluar dari rumah sakit bersalin? Buka Buku Harian Suasana Hati dan malam ini tulislah surat penuh perasaan yang kelak akan ia baca.', title_ja = '明日で1歳！🎉', body_ja = '懐かしい気持ちになりますね！退院したあの最初の日を覚えていますか？「気分日記」を開いて、今夜、いつかお子さんが読む心のこもった手紙を書いてみましょう。', title_ko = '내일이면 1살! 🎉', body_ko = '추억이 밀려와요! 산부인과에서 퇴원하던 그 첫날이 기억나나요? 기분 일기를 열고 오늘 밤 아이가 훗날 읽을 감동적인 편지를 써 보세요.', title_nl = 'Morgen wordt je kindje 1! 🎉', body_nl = 'Een vleugje nostalgie! Weet je nog die eerste dag dat je uit het ziekenhuis kwam? Open je Stemmingsdagboek en schrijf vanavond een ontroerende brief die je kindje later kan lezen.', title_pl = 'Jutro pierwsze urodziny! 🎉', body_pl = 'Chwila nostalgii! Pamiętasz ten pierwszy dzień, gdy wyszłaś ze szpitala? Otwórz Dziennik nastroju i napisz dziś wzruszający list, który maluszek kiedyś przeczyta.', title_pt = 'Amanhã faz 1 ano! 🎉', body_pt = 'Ventos de nostalgia! Lembra-se daquele primeiro dia em que saiu da maternidade? Abra o Diário de Humor e escreva-lhe esta noite uma carta emotiva para ele ler no futuro.', title_sv = 'I morgon fyller barnet 1 år! 🎉', body_sv = 'Nostalgiska vindar! Minns du den första dagen ni lämnade BB? Öppna Humördagboken och skriv i kväll ett känslosamt brev som barnet kan läsa i framtiden.', title_vi = 'Ngày mai bé tròn 1 tuổi! 🎉', body_vi = 'Bồi hồi nhớ lại! Mẹ còn nhớ ngày đầu tiên rời nhà hộ sinh không? Hãy mở Nhật ký tâm trạng và tối nay viết cho bé một lá thư xúc động để sau này bé đọc nhé.', title_zh = '明天就1岁啦！🎉', body_zh = '怀旧时刻！还记得从产院回家的第一天吗？打开心情日记，今晚给宝宝写一封将来会读到的走心信件吧。' WHERE id = 'c639a352-3f59-4488-9ce0-2ba361a4790c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Faltan 5 días para los 15 meses! 🎈', body_es = '¡La cuenta atrás está a punto de terminar! Ya compartes casa con una personita que camina y lo entiende todo. ¡Sonríe!', title_fr = '15 mois dans 5 jours ! 🎈', body_fr = 'Le compte à rebours touche à sa fin ! Vous partagez désormais la maison avec un petit être qui marche partout et comprend tout. Souriez !', title_hi = '15 महीने में 5 दिन! 🎈', body_hi = 'उलटी गिनती खत्म होने को है! अब आप घर में दौड़ने वाले, सब कुछ समझने वाले एक नन्हे इंसान के साथ रहती हैं। मुस्कुराइए!', title_id = '5 hari lagi menuju 15 bulan! 🎈', body_id = 'Hitung mundur hampir selesai! Kini Anda berbagi rumah dengan pribadi kecil yang berjalan ke sana kemari dan memahami segalanya. Tersenyumlah!', title_ja = '1歳3か月まであと5日！🎈', body_ja = 'カウントダウンももうすぐ終わり！今では、歩き回ってなんでもわかる小さなひとりの人と一緒に暮らしています。ほほえんで！', title_ko = '15개월까지 5일! 🎈', body_ko = '카운트다운이 거의 끝나 가요! 이제 집 안을 걸어 다니고 모든 걸 알아듣는 작은 한 사람과 함께 살고 있어요. 웃어 보세요!', title_nl = 'Nog 5 dagen tot 15 maanden! 🎈', body_nl = 'Het aftellen is bijna voorbij! Je deelt je huis nu met een klein persoontje dat rondloopt en alles begrijpt. Glimlach!', title_pl = 'Jeszcze 5 dni do 15 miesięcy! 🎈', body_pl = 'Odliczanie dobiega końca! Dzielisz dom z małą osóbką, która chodzi wszędzie i wszystko rozumie. Uśmiechnij się!', title_pt = 'Faltam 5 dias para os 15 meses! 🎈', body_pt = 'A contagem decrescente está quase a terminar! Já partilha a casa com uma pessoinha que anda por todo o lado e percebe tudo. Sorria!', title_sv = '5 dagar kvar till 15 månader! 🎈', body_sv = 'Nedräkningen är snart slut! Nu delar du hem med en liten person som går omkring och förstår allt. Le!', title_vi = 'Còn 5 ngày nữa tròn 15 tháng! 🎈', body_vi = 'Đếm ngược sắp kết thúc! Giờ mẹ đang sống chung nhà với một con người nhỏ bé biết đi khắp nơi và hiểu mọi thứ. Hãy mỉm cười nhé!', title_zh = '离15个月还有5天！🎈', body_zh = '倒计时快结束了！你正和一个满屋子跑、什么都懂的小家伙住在同一屋檐下。笑一笑吧！' WHERE id = 'd08fdb3f-542d-478d-95e6-72b2d85a8a9a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
COMMIT;
